comms.text:
@1 וְאִלֵין שְׁמָהַת בְּנֵי יִשְׂרָאֵל דְעַלוּ לְמִצְרָיִם עִם יַעֲקֹב גְבַר וֶאֱנַשׁ בֵּיתֵהּ עַלוּ:
@2 רְאוּבֵן שִׁמְעוֹן לֵוִי וִיהוּדָה:
@3 יִשָׂשׂכָר זְבוּלֻן וּבִנְיָמִין:
@4 דָן וְנַפְתָּלִי גָד וְאָשֵׁר:
@5 וַהֲוָה כָּל נַפְשָׁתָא נַפְקֵי יַרְכָּא דְיַעֲקֹב שַׁבְעִין נַפְשָׁן וְיוֹסֵף דַהֲוָה בְּמִצְרָיִם:
@6 וּמִית יוֹסֵף וְכָל אַחוֹהִי וְכֹל דָרָא הַהוּא:
@7 וּבְנֵי יִשְׂרָאֵל נְפִישׁוּ וְאִתְיַלָדוּ וּסְגִיאוּ וּתְקִיפוּ לַחֲדָא לַחֲדָא וְאִתְמְלִיאַת אַרְעָא מִנְהוֹן:
@8 וְקָם מַלְכָּא חַדְתָּא עַל מִצְרָיִם דְלָא מְקַיֵם גְזֵרַת יוֹסֵף:
@9 וַאֲמַר לְעַמֵהּ הָא עַמָא בְּנֵי יִשְׂרָאֵל סָגָן וְתַקִיפִין מִנָנָא:
@10 הָבוּ נִתְחַכַּם לְהוֹן דִלְמָא יִסְגוּן וִיהֵי אֲרֵי יְעַרְעִנָנָא קְרָב וְיִתּוֹסְפוּן אַף אִנוּן עַל סַנְאָנָא וִיגִיחוּן בָּנָא קְרָב וְיִסְקוּן מִן אַרְעָא:
@11 וּמַנִיאוּ עֲלֵיהוֹן שִׁלְטוֹנִין מַבְּאִישִׁין בְּדִיל לְעַנוֹאֵהוֹן בְּפָלְחָנְהוֹן וּבְנוֹ קִרְוֵי בֵית אוֹצָרָא לְפַרְעֹה יָת פִּיתוֹם וְיָת רַעַמְסֵס:
@12 וּכְמָא דִמְעַנַן לְהוֹן כֵּן סָגָן וְכֵן תַּקְפִין וַעֲקַת לְמִצְרָאֵי מִן קֳדָם בְּנֵי יִשְׂרָאֵל:
@13 וְאַפְלָחוּ מִצְרָאֵי יָת בְּנֵי יִשְׂרָאֵל בְּקַשְׁיוּ:
@14 וְאַמְרָרוּ יָת חַיֵיהוֹן בְּפָלְחָנָא קָשְׁיָא בְּטִּינָא וּבְלִבְנִין וּבְכָל פָלְחָנָא בְּחַקְלָא יָת כָּל פָּלְחָנְהוֹן דְאַפְלָחוּ בְהוֹן בְּקַשְׁיוּ:
@15 וַאֲמַר מַלְכָּא דְמִצְרַיִם לְחַיָתָא יְהוּדַיָתָא דְשׁוּם חָדָא שִׁפְרָה וְשּׁוּם תִּנְיֵתָא פּוּעָה:
@16 וַאֲמַר כַּד תֶּהֶוְיָן מוֹלְדָן יָת יְהוּדַיָתָא וְתֶחְזְיָן עַל מַתְבְּרָא אִם בַּר הוּא תִּקְטְלַן יָתֵהּ וְאִם בְּרַתָּא הִיא ותְקַיְמִנַהּ:
@17 וּדְחִילָא חַיָתָא מִן קֳדָם יְיָ וְלָא עֲבָדָא כְּמָא דְמַלִיל עִמְהֶן מַלְכָּא דְמִצְרָיִם וְקַיָמָא יָת בְּנַיָא:
@18 וּקְרָא מַלְכָּא דְמִצְרַיִם לְחַיָתָא וַאֲמַר לְהֶן מָה דֵין עֲבַדְתּוּן יָת פִּתְגָמָא הָדֵין וְקַיֵמְתּוּן יָת בְּנַיָא:
@19 וַאֲמָרָא חַיָתָא לְפַרְעֹה אֲרֵי לָא כִנְשַׁיָא מִצְרְיָתָא יְהוּדַיָתָא אֲרֵי חֲכִּימָן אִנוּן עַד לָא עַלַת לְוָתְהֶּן חַיָתָא וִילִידָן:
@20 וְאוֹטֵּיב יְיָ לְחַיָתָא וּסְגִי עַמָא וּתְקִיפוּ לַחֲדָא:
@21 וַהֲוָה כַּד דְחִילָא חַיָתָא מִן קֳדָם יְיָ וַעֲבַד לְהוֹן בָּתִּין:
@22 וּפַקִיד פַּרְעֹה לְכָל עַמֵהּ לְמֵימָר כָּל בְּרָא דְיִתְיְלִּיד לִיהוּדָאֵי בְּנַהֲרָא תִּרְמֻנֵהּ וְכָל בְּרַתָּא תְּקַיְמוּן:
@23 וַאֲזַל גַבְרָא מִדְבֵית לֵוִי וּנְסִיב יָת בַּת לֵוִי:
@24 וְעַדִיאַת אִתְּתָא וִילִידַת בָּר וַחֲזַת יָתֵהּ אֲרֵי טַּב הוּא וְאַטְמַרְתֵּהּ תְּלָתָא יַרְחִין:
@25 וְלָא יְכֵילַת עוֹד לְאַטְמָרוּתֵהּ וּנְסֵיבַת לֵהּ תֵּבוּתָא דְגוֹמֶא וְחַפָּתַהּ בְּחֵמָרָא וּבְזִפְתָּא וְשַׁוִיאַת בַּהּ יָת רַבְיָא וְשַׁוִיתַהּ בְּיַעֲרָא עַל כֵּיף נַהֲרָא:
@26 וְאִתְעַתָּדַת אֲחָתֵהּ מֵרָחִיק לְמִידַע מָה יִתְעֲבֵד לֵהּ:
@27 וּנְחָתַת בַּת פַּרְעֹה לְמִסְחֵי עַל נַהֲרָא וְעוּלֵימָתָהָא מְהַלְכָן עַל כֵּיף נַהֲרָא וַחֲזַת יָת תֵּבוּתָא בְּגוֹ יַעֲרָא וְאוֹשֵׁטַת יָת אַמְתַהּ וּנְסֵבְתַהּ:
@28 וּפְתָחַת וַחֲזַת יָת רַבְיָא וְהָא עוּלֵימָא בָּכֵי וְחָסַת עֲלוֹהִי וַאֲמֶרֶת מִבְּנֵי יְהוּדָאֵי הוּא דֵין:
@29 וַאֲמֶרֶת אֲחָתֵהּ לְבַת פַרְעֹה הַאֵיזִיל וְאִקְרֵי לִיךְ אִתְּתָא מֵינִקְתָּא מִן יְהוּדַיָתָא וְתוֹנִיק לִיךְ יָת רַבְיָא:
@30 וַאֲמֶרֶת לַהּ בַּת פַּרְעֹה אֵיזִילִי וַאֲזָלַת עוּלֶמְתָּא וּקְרַת יָת אִמֵהּ דְרַבְיָא:
@31 וַאֲמֶרֶת לַהּ בַּת פַּרְעֹה אוֹבִילִי יָת רַבְיָא הָדֵין וְאוֹנְקִיהִי לִי וַאֲנָא אֶתֵּן יָת אַגְרָךְ וּנְסֵיבַת אִתְּתָא יָת רַבְיָא וְאוֹנִקְתֵּהּ:
@32 וּרְבָא רַבְיָא וְאַיְתִיתֵהּ לְבַת פַּרְעֹה וַהֲוָה לָהּ לְבָר וּקְרַת שְׁמֵהּ משֶׁה וַאֲמֶרֶת אֲרֵי מִן מַיָא שְׁחַלְתֵּהּ:
@33 וַהֲוָה בְּיוֹמַיָא הָאִנוּן וּרְבָא משֶׁה וּנְפַק לְוָת אַחוֹהִי וַחֲזָא בְּפָלְחַנְהוֹן וַחֲזָא גְבַר מִצְרִי מָחֵי לִגְבַר יְהוּדִי מֵאַחוֹהִי:
@34 וְאִתְפְּנֵי לְכָא וּלְכָא וַחֲזָא אֲרֵי לֵית גַבְרָא וּמְחָא יָת מִצְרָאָה וְטַמְרֵהּ בְּחָלָא:
@35 וּנְפַק בְּיוֹמָא תִנְיָנָא וְהָא תְּרֵין גֻבְרִין יְהוּדָאִין נָצָן וַאֲמַר לְחַיָבָא לְמָא אַתְּ מָחֵי לְחַבְרָךְ:
@36 וַאֲמַר מָן שַׁוְיָךְ לִגְבַר רַב וְדַיָן עֲלָנָא הַלְמִקְטְלִי אַתְּ אָמַר כְּמָא דִקְטַלְתָּ יָת מִצְרָאָה וּדְחִיל משֶׁה וַאֲמַר בְּקוּשְׁטָא אִתְיְדַע פִּתְגָמָא:
@37 וּשְׁמַע פַּרְעֹה יָת פִּתְגָמָא הָדֵין וּבְעָא לְמִקְטַל יָת משֶׁה וַעֲרַק משֶׁה מִן קֳדָם פַּרְעֹה וִיתֵיב בְּאַרְעָא דְמִדְיָן וִיתֵיב עַל בֵּירָא:
@38 וּלְרַבָא דְמִדְיָן שְׁבַע בְּנָן וְאָתָאָה וּדְלָאָה וּמְלָאָה יָת רְהָטַיָא לְאַשְׁקָאָה עֲנָא דַאֲבוּהֵן:
@39 וַאֲתוֹ רָעַיָא וּטְרָדוּנוּן וְקָם משֶׁה וּפְרָקִנוּן וְאַשְׁקֵי יָת עַנְהֵן:
@40 וַאֲתָאָה לְוַת רְעוּאֵל אֲבוּהֵן וַאֲמַר מָה דֵין אוֹחִיתוּן לְמֵיתֵי יוֹמָא דֵין:
@41 וַאֲמָרָא גַבְרָא מִצְרָאָה שֵׁזְבָנָא מִיַד רָעַיָא וְאַף מִדְלָא דְלָא לָנָא וְאַשְׁקֵי יָת עָנָא:
@42 וַאֲמַר לִבְנָתֵיהּ וְאָן הוּא לְמָא דְנַן שְׁבַקְתִּין יָת גַבְרָא קְרַן לֵהּ וְיֵכוּל לַחְמָא:
@43 וּצְבִי משֶׁה לְמִיתַב עִם גַבְרָא וִיהַב יָת צִפּוֹרָה בְרַתֵּהּ לְמשֶׁה:
@44 וִילֵדַת בַּר וּקְרָא יָת שְׁמֵהּ גֵרְשֹׁם אֲרֵי אֲמַר דַיָר הֲוֵיתִי בְּאַרַע נוּכְרָאָה:
@45 וַהֲוָה בְּיוֹמַיָא סַגִיאַיָא הָאִנוּן וּמִית מַלְכָּא דְמִצְרַיִם וְאִתְנָחוּ בְנֵי יִשְׂרָאֵל מִן פָּלְחָנָא דַהֲוָה קְשֵׁי עֲלֵיהוֹן וּזְעִיקוּ וּסְלֵיקָת קְבֶלְתְּהוֹן לָקֳדָם יְיָ מִן פָּלְחָנָא:
@46 וּשְׁמִיעַ קֳדָם יְיָ יָת קְבֶלְתְּהוֹן וּדְכִיר יְיָ יָת קַיָמֵהּ דְעִם אַבְרָהָם דְעִם יִצְחָק וּדְעִם יַעֲקֹב:
@47 וּגְלִי קְדָם יְיָ שִׁעְבּוּדָא דִבְנֵי יִשְׂרָאֵל וַאֲמַר בְּמֵימְרֵהּ לְמִפְרַקְהוֹן יְיָ:
@48 וּמשֶׁה הֲּוָה רָעֵי יָת עָנָא דְיִתְרוֹ חֲמוֹהִי רַבָּא דְמִדְיָן וּדְבַר יָת עָנָא לְבָתַר שְׁפַר רַעֲיָא לְמַדְבְּרָא וְאָתָא לְטוּרָא דְאִתְגְלִי עֲלוֹהִי יְקָרָא דַיְיָ לְחוֹרֵב:
@49 וְאִתְגְלִי מַלְאָכָא דַיְיָ לֵהּ בְּשַׁלְהוֹבִית אֶשָׁתָא מִגוֹ אַסָנָא וַחֲזָא וְהָא אַסָנָא בָּעֵר בְּאֶשָׁתָא וַאֲסָנָא לֵיתוֹהִי מִתְאָכִיל:
@50 וַאֲמַר משֶׁה אִתְפְּנֵי כְעַן וְאֶחֱזֵי יָת חָזְוָנָא רַבָּא הָדֵין מָא דֵין לָא מִתּוֹקַד אַסָנָא:
@51 וַחֲזָא יְיָ אֲרֵי אִתְפְּנֵי לְמֶחֱזֵי וּקְרָא לֵהּ יְיָ מִגוֹ אַסָנָא וַאֲמַר משֶׁה משֶׁה וַאֲמַר הָא אֲנָא:
@52 וַאֲמַר לָא תִקְרַב הַלְכָא שְׁרִי סֵינָךְ מֵעַל רִגְלָךְ אֲרֵי אַתְרָא דְאַתְּ קָאִים עֲלוֹהִי אֲתַר קַדִישׁ הוּא:
@53 וַאֲמַר אֲנָא אֱלָהָא דְאָבוּךְ אֱלָהָא דְאַבְרָהָם אֱלָהָא דְיִצְחָק וֵאלָהָא דְיַעֲקֹב וּכְבֵשִׁנּוּן משֶׁה לְאַפּוֹהִי אֲרֵי דָחִיל מִלְאִסְתַּכָּלָא בְּצֵית יְקָרָא דַיְיָ:
@54 וַאֲמַר יְיָ מִגְלָא גְלִי קֳדָמַי יָת שִׁעְבּוּד עַמִי דִי בְמִצְרָיִם וְיָת קְבֶלְתְּהוֹן שְׁמִיעַ קֳדָמַי מִן קֳדָם מַפְלְחֵיהוֹן אֲרֵי גְלֵי קָדָמַי יָת כֵּיבֵיהוֹן:
@55 וְאִתְגְלֵיתִי לְשֵׁזָבוּתְהוֹן מִידָא דְמִצְרָאֵי וּלְאַסָקוּתְהוֹן מִן אַרְעָא הַהִיא לְאַרְעָא טָבָא וּפַתְיָא לְאַרְעָא עָבְדָא חֲלָב וּדְבָשׁ לַאֲתַר כְּנַעֲנָאֵי וְחִתָּאֵי וֶאֱמוֹרָאֵי וּפְרִזָאֵי וְחִוָאֵי וִיבוּסָאֵי:
@56 וּכְעַן הָא קְבֵילַת בְּנֵי יִשְׂרָאֵל עָלַת קֳדָמָי וְאַף גְלֵי קֳדָמַי יָת דוֹחֲקָא דִי מִצְרָאֵי דָחֲקִין לְהוֹן:
@57 וּכְעַן אִיתָא וְאֶשְׁלְחִנָּךְ לְוַת פַּרְעֹה וְאַפֵּיק יָת עַמִי בְנֵי יִשְׂרָאֵל מִמִצְרָיִם:
@58 וַאֲמַר משֶׁה קֳדָם יְיָ מָן אֲנָא אֲרֵי אֵזִיל לְוָת פַּרְעֹה וַאֲרֵי אַפֵּיק יָת בְּנֵי יִשְׂרָאֵל מִמִצְרָיִם:
@59 וַאֲמַר אֲרֵי יְהֵי מֵימְרִי בְסַעְדָךְ וְדֵין לָךְ אָתָא אֲרֵי אֲנָא שְׁלַחְתָּךְ בְּאַפָּקוּתָךְ יָת עַמָא מִמִצְרַיִם תִּפְלְחוּן קֳדָם יְיָ עַל טוּרָא הָדֵין:
@60 וַאֲמַר משֶׁה קֳדָם יְיָ הָא אֲנָא אָתֵי לְוָת בְּנֵי יִשְׂרָאֵל וְאֵימַר לְהוֹן אֱלָהָא דְאַבְהַתְכוֹן שַׁלְחַנִי לְוָתְכוֹן וְיֵימְרוּן לִי מָא שְׁמֵהּ מָא אֵימַר לְהוֹן:
@61 וַאֲמַר יְיָ לְמשֶׁה אֶהְיֶה אֲשֶׁר אֶהְיֶה וַאֲמַר כִּדְנַן תֵּימַר לִבְנֵי יִשְׂרָאֵל אֶהְיֶה שַׁלְחַנִי לְוָתְכוֹן:
@62 וַאֲמַר עוֹד יְיָ לְמשֶׁה כִּדְנַן תֵּימַר לִבְנֵי יִשְׂרָאֵל יְיָ אֱלָהָא דְאַבְהַתְכוֹן אֱלָהֵהּ דְאַבְרָהָם אֱלָהֵהּ דְיִצְחָק וֵאלָהֵהּ דְיַעֲקֹב שַׁלְחַנִי לְוָתְכוֹן דֵין שְׁמִי לְעָלַם וְדֵין דָכְרָנִי לְכָל דָר וְדָר:
@63 אִזֵיל וְתִכְנוֹשׁ יָת סָבֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן יְיָ אֱלָהָא דְאַבְהַתְכוֹן אִתְגְלֵי לִי אֱלָהֵהּ דְאַבְרָהָם יִצְחָק וְיַעֲקֹב לְמֵימָר מִדְכַּר דְכִירְנָא יַתְכוֹן וְיָת דְאִתְעֲבַד לְכוֹן בְּמִצְרַיִם:
@64 וַאֲמָרִית אַסֵיק יָתְכוֹן מִשִׁעְבּוּד מִצְרָאֵי לַאֲרַע כְּנַעֲנָאֵי וְחִתָּאֵי וֶאֱמוֹרָאֵי וּפְרִזָאֵי וְחִוָאֵי וִיבוּסָאֵי לְאַרְעָא עַבְדָא חֲלָב וּדְבָשׁ:
@65 וִיקַבְּלוּן לְמֵימְרָךְ וְתֵיתֵי אַתְּ וְסָבֵי יִשְׂרָאֵל לְוָת מַלְכָּא דְמִצְרַיִם וְתֵימְרוּן לֵהּ יְיָ אֱלָהָא דִיהוּדָאֵי אִתְקְרֵי עֲלָנָא וּכְעַן נֵזֵיל כְּעַן מַהֲלַךְ תְּלָתָא יוֹמִין בְּמַדְבְּרָא וּנְדַבַּח קֳדָם יְיָ אֱלָהָנָא:
@66 וּקְדָמַי גְלֵי אֲרֵי לָא יִשְׁבּוֹק יָתְכוֹן מַלְכָּא דְמִצְרַיִם לְמֵיזָל וְלָא מִן קֳדָם דְחֵילֵהּ תַּקִיף:
@67 וָאֲשַׁלַח פּוֹן יָת מְחַת גְבֻרְתִּי וְאֶמְחֵי יָת מִצְרָאֵי בְּכֹל פְּרִשְׁוָתִי דִי אַעְבֵּד בֵּינֵיהוֹן וּבָתַר כֵּן יְשַׁלַח יָתְכוֹן:
@68 וְאֶתֵּן יָת עַמָא הָדֵין לְרַחֲמִין בְּעֵינֵי מִצְרָאֵי וִיהֵי אֲרֵי תְהָכוּן לָא תְהָכוּן רֵיקָנִין:
@69 וְתִשְׁאַל אִתְּתָא מִשְׁבַבְתַּהּ וּמִקְרִיבַת בֵּיתַהּ מָנִין דִכְסַף וּמָנִין דִדְהַב וּלְבוּשִׁין וּתְשַׁווּן עַל בְּנֵיכוֹן וְעַל בְּנָתֵיכוֹן וּתְרוֹקִנוּן יָת מִצְרָיִם:
@70 וַאֲתֵיב משֶׁה וַאֲמַר וְהָא לָא יְהֵמְנוּן לִי וְלָא יְקַבְּלוּן מִנִי אֲרֵי יֵימְרוּן לָא אִתְגְלֵי לָךְ יְיָ:
@71 וַאֲמַר לֵהּ יְיָ מָא דֵין בִּידָךְ וַאֲמַר חוּטְרָא:
@72 וַאֲמַר רְמִיהִי לְאַרְעָא וּרְמָהִי לְאַרְעָא וַהֲוָה לְחִוֵי וַעֲרַק משֶׁה מִן קֳדָמוֹהִי:
@73 וַאֲמַר יְיָ לְמשֶׁה אוֹשִׁט יְדָךְ וְאֵחוֹד בְּזַנְבֵהּ וְאוֹשֵׁיט יְדֵהּ וְאַתְקֵף בֵּהּ וַהֲוָה לְחוּטְּרָא בִּידֵהּ:
@74 בְּדִיל דִיהֵמְנוּן אֲרֵי אִתְגְלִי לָךְ יְיָ אֱלָהָא דְאַבְהַתְהוֹן אֱלָהֵהּ דְאַבְרָהָם אֱלָהֵהּ דְיִצְחָק וֵאֵלָהֵהּ דְיַעֲקֹב:
@75 וַאֲמַר יְיָ לֵהּ עוֹד אָעֵיל כְּעַן יְדָךְ בְּעִטְּפָךְ וְאָעֵיל יְדֵהּ בְּעִטְפֵהּ וְאַפְקַהּ וְהָא יְדֵהּ חַוְרָא כְתַלְגָא:
@76 וַאֲמַר אָתֵיב יְדָךְ לְעִטְפָךְ וַאֲתֵיב יְדֵהּ לְעִטְּפֵהּ וְאַפְקַהּ מֵעִטְפֵהּ וְהָא תָבַת הֲוַת כְּבִשְׂרֵהּ:
@77 וִיהֵי אִם לָא יְהֵמְנוּן לָךְ וְלָא יְקַבְּלוּן לְקַל אָתָא קַדְמָאָה וִיהֵמְנוּן לְקַל אָתָא בַתְרָאָה:
@78 וִיהֵי אִם לָא יְהֵמְנוּן אַף לִתְרֵין אָתַיָא הָאִלֵּין וְלָא יְקַבְּלוּן מִנָךְ וְתִסַב מִמַיָא דִבְנַהֲרָא וְתֵשׁוֹד לְּיַבֶּשְׁתָּא וִיהוֹן מַיָא דִי תִסַב מִן נַהֲרָא וִיהוֹן לִדְמָא בְּיַבֶּשְׁתָּא:
@79 וַאֲמַר משֶׁה קֳדָם יְיָ בְּבָעוּ יְיָ לָא גְבַר דְמִלוּל אֲנָא אַף מִתְּמַלִי אַף מִדְקָמוֹהִי אַף מֵעִדַן דְמַלֶלְתָּא עִם עַבְדָךְ אֲרֵי יַקִיר מַמְלָל וְעַמִיק לִישָׁן אֲנָא:
@80 וַאֲמַר יְיָ לֵהּ מָן שַׁוִי פּוּמָא לַאֲנָשָׁא אוֹ מָן שַׁוִי אִלְמָא אוֹ חֵרְשָּׁא אוֹ פִקְחָא אוֹ עַוִירָא הֲלָא אֲנָא יְיָ:
@81 וּכְעַן אֱזֵיל וּמֵימְרִי יְהֵא עִם פּוּמָךְ וְאַלֵפִנָךְ דִי תְמַלֵל:
@82 וַאֲמַר בְּבָעוּ יְיָ שְׁלַח כְּעַן בְּיַד מָן דְכָשַׁר דְתִשְׁלַח:
@83 וּתְקֵיף רוּגְזָא דַיְיָ בְּמשֶׁה וַאֲמַר הֲלָא אַהֲרֹן אָחוּךְ לֵוָאֵי גְלֵי קֳדָמַי אֲרֵי מַלָלָא יְמַלֵל הוּא וְאַף הָא הוּא נָפֵק לְקַדָמוּתָךְ וְיֶחֱזִנָךְ וְיֶחְדֵי בְלִבֵּהּ:
@84 וּתְמַלֵל עִמֵהּ וּתְשַׁוִי יָת פִּתְגָמַיָא בְּפוּמֵהּ וּמֵימְרִי יְהֵי עִם פּוּמָךְ וְעִם פּוּמֵהּ וְאַלֵיף יָתְכוֹן יָת דִי תַעְבְּדוּן:
@85 וִימַלֵל הוּא לָךְ לְעַמָא וִיהֵי הוּא יְהֵי לָךְ לִמְתֻרְגְמָן וְאַתְּ תְּהֵי לֵהּ לְרָב:
@86 וְיָת חֻטְרָא הָדֵין תִּסַב בִּידָךְ דְתַעְבֵּד בֵּהּ יָת אָתַיָא:
@87 וַאֲזַל משֶׁה וְתָב לְוָת יֶתֶר חֲמוֹהִי וַאֲמַר לֵהּ אֵיזִיל כְּעַן וְאֵיתוּב לְוָת אַחַי דִי בְמִצְרַיִם וְאֶחֱזֵי הַעַד כְּעַן קַיָמִין וַאֲמַר יִתְרוֹ לְמשֶׁה אֱזֵיל לִשְׁלָם:
@88 וַאֲמַר יְיָ לְמשֶׁה בְּמִדְיָן אֱזֵיל תּוּב לְמִצְרָיִם אֲרֵי מִיתוּ כָּל גֻבְרַיָא דִבְעוֹ לְמִקְטְלָךְ:
@89 וּדְבַר משֶׁה יָת אִתְּתֵהּ וְיָת בְּנוֹהִי וְאַרְכְּבִנוּן עַל חֲמָרָא וְתָב לְאַרְעָא דְמִצְרָיִם וּנְסִיב משֶׁה יָת חוּטְרָא דְאִתְעֲבִידוּ בֵּהּ נִסִין מִן קֳדָם יְיָ בִּידֵהּ:
@90 וַאֲמַר יְיָ לְמשֶׁה בִּמְהָכָךְ לְמִתּוּב לְמִצְרַיִם חֲזֵי כָּל מוֹפְתַיָא דִי שַׁוֵיתִי בִידָךְ וְתַעְבְּדִנוּן קֳדָם פַּרְעֹה וַאֲנָא אַתְקֵיף יָת לִבֵּהּ וְלָא יְשַּׁלַח יָת עַמָא:
@91 וְתֵימַר לְוָת פַּרְעֹה כִּדְנַן אֲמַר יְיָ בְּרִי בוּכְרִי יִשְׂרָאֵל:
@92 וַאֲמָרִית לָךְ שַׁלַח יָת בְּרִי וְיִפְלַח קֳדָמַי וְאִם סָרִיב אַתְּ לְשַׁלָחוּתֵהּ הָא אֲנָא קָטִיל יָת בְּרָךְ בּוּכְרָךְ:
@93 וַהֲוָה בְאָרְחָא בְּבֵית מְבָתָא וַעֲרַע בֵּהּ מַלְאֲכָא דַיְיָ וּבְעָא לְמִקְטְלֵהּ:
@94 וּנְסֵיבַת צִפּוֹרָה טִנָרָא וּגְזָרַת יָת עָרְלַת בְּרַהּ וּקְרִיבַת לָקֳדָמוֹהִי וַאֲמֶ רֶת אֲרֵי בִדְמָא דִמְהֻלְתָּא הָדֵין אִתְיְהֵב חַתְנָא לָנָא:
@95 וְנָח מִנֵהּ בְּכֵן אֲמֶרֶת אִלוּלֵי דְמָא דִמְהֻלְתָּא הָדֵין אִתְחַיַב חַתְנָא קְטוֹל:
@96 וַאֲמַר יְיָ לְאַהֲרֹן אֱזֵיל לְקַדָמוּת משֶׁה לְמַדְבְּרָא וַאֲזַל וְעַרְעֵהּ בְּטוּרָא דְאִתְגְלֵי עֲלוֹהִי יְקָרָא דַיְיָ וּנְשַׁק לֵהּ:
@97 וְחַוִי משֶׁה לְאַהֲרֹן יָת כָּל פִּתְגָמַיָא דַיְיָ דִי שַׁלְחֵהּ וְיָת כָּל אָתַיָא דִי פַקְדֵהּ:
@98 וַאֲזַל משֶׁה וְאַהֲרֹן וּכְנָשׁוּ יָת כָּל סָבֵי בְּנֵי יִשְׂרָאֵל:
@99 וּמַלִיל אַהֲרֹן יָת כָּל פִּתְגָמַיָא דִי מַלִיל יְיָ עִם משֶׁה וַעֲבַד אָתַיָא לְעֵינֵי עַמָא:
@100 וְהֵימִן עַמָא וּשְׁמָעוּ אֲרֵי דְכִיר יְיָ יָת בְּנֵי יִשְׂרָאֵל וַאֲרֵי גְלֵי קֳדָמוֹהִי יָת שִׁעְבּוּדְהוֹן וּכְרָעוּ וּסְגִידוּ:
@101 וּבָתַר כֵּן עַלוּ משֶׁה וְאַהֲרֹן וַאֲמָרוּ לְפַרְעֹה כִּדְנַן אֲמַר יְיָ אֱלָהָא דְיִשְׂרָאֵל שַׁלַח יָת עַמִי וִיחַגוּן קֳדָמַי בְּמַדְבְּרָא:
@102 וַאֲמַר פַּרְעֹה שְׁמָא דַיְיָ לָא אִתְגְלִי לִי דִי אֲקַבֵּל לְמֵמְרֵהּ לְשַׁלָחָא יָת יִשְׂרָאֵל לָא אִתְגְלִי לִי שְׁמָא דַיְיָ וְאַף יָת יִשְׂרָאֵל לָא אֲשַׁלַח:
@103 וַאֲמָרוּ אֱלָהָא דִיהוּדָאֵי אִתְגְלִי עֲלָנָא נֵיזֵיל כְּעַן מַהֲלַךְ תְּלָתָא יוֹמִין בְּמַדְבְּרָא וּנְדַבַּח קֳדָם יְיָ אֱלָהָנָא דִלְמָא יְעַרְעִנָנָא בְּמוֹתָא אוֹ בִקְטוֹל:
@104 וַאֲמַר לְהוֹן מַלְכָּא דְמִצְרַיִם לְמָא משֶׁה וְאַהֲרֹן תְּבַטְלוּן יָת עַמָא מֵעוֹבָדֵהוֹן אֱזִילוּ לְפָלְחָנְכוֹן:
@105 וַאֲמַר פַּרְעֹה הָא סַגִיאִין כְּעַן עַמָא דְאַרְעָא וּתְבַטְלוּן יָתְהוֹן מִפָּלְחָנְהוֹן:
@106 וּפַקִיד פַּרְעֹה בְּיוֹמָא הַהוּא יָת שִׁלְטוֹנִין דְעַמָא וְיָת סָרְכוֹהִי לְמֵימָר:
@107 לָא תוֹסְפוּן לְמִיתַּן תִּבְנָא לְעַמָא לְמִרְמֵי לִבְנִין כְּמִתְּמַלֵי וּמִדְקָמוֹהִי אִנוּן יְהָכוּן וִיגַבְּבוּן לְהוֹן תִּבְנָא:
@108 וְיָת סְכוֹם לְבֵנַיָא דִי אִנוּן עָבְדִין מִתְּמַלֵי וּמִדְקָמוֹהִי תְּמַנוּן עֲלֵיהוֹן לָא תִמְנְעוּן מִנֵהּ אֲרֵי בַטְלָנִין אִנוּן עַל כֵּן אִנוּן צָוְחִין לְמֵימַר נֵיזֵיל נְדַבַּח קֳדָם אֱלָהָנָא:
@109 תִּתָּקַף פָּלְחָנָא עַל גֻבְרַיָא וְיִתְעַסְקוּן בַּהּ וְלָא יִתְעַסְקוּן בְּפִתְגָמִ ין בְּטֵלִין:
@110 וּנְפָקוּ שִׁלְטוֹנֵי עַמָא וְסָרְכוֹהִי וַאֲמָרוּ לְעַמָא לְמֵימָר כִּדְנַן אֲמַר פַּרְעֹה לֵית אֲנָא יָהֵב לְכוֹן תִּבְנָא:
@111 אַתּוּן אֱזִילוּ סִיבוּ לְכוֹן תִּבְנָא מֵאֲתַר דְתַשְׁכְּחוּן אֲרֵי לָא יִתִּמְנַע מִפָּלְחָנְכוֹן מִדָעַם:
@112 וְאִתְבַּדַר עַמָא בְּכָל אַרְעָא דְמִצְרָיִם לְגַבָּבָא גִילֵי לְתִבְנָא:
@113 וְשִׁלְטוֹנַיָא דָחֲקִין לְמֵימָר אַשְׁלִימוּ עוֹבָדֵיכוֹן פִּתְגַם יוֹם בְּיוֹמֵהּ כְּמָא דַהֲוֵיתוּן עָבְדִין כַּד אִתְיְהֵב לְכוֹן תִּבְנָא:
@114 וּלְקוֹ סָרְכֵי בְּנֵי יִשְׂרָאֵל דִי מַנִיאוּ עֲלֵיהוֹן שִׁלְטוֹנֵי פַרְעֹה לְמֵימָר מָא דֵין לָא אַשְׁלֶמְתּוּן גְזֵרָתְכוֹן לְמִרְמֵי (לִבְנִין) כְּמֵאִתְמַלֵי וּמִדְקָמוֹהִי אַף תְּמַלֵי אַף יוֹמָא דֵין:
@115 וַאֲתוֹ סָרְכֵי בְּנֵי יִשְׂרָאֵל וּצְוָחוּ (קֳדָם) לְפַרְעֹה לְמֵימָר לְמָא תַעְבֵּד כְּדֵין לְעַבְדָיךְ:
@116 תִּבְנָא לָא מִתְיְהֵב לְעַבְדָיךְ וּלְבֵנַיָא אָמְרִין לָנָא עִבִידוּ וְהָא עַבְדָיךְ לָקָן וְחָטָן עֲלֵיהוֹן עַמָךְ:
@117 וַאֲמַר בַּטְלָנִין אַתּוּן בַּטְלָנִין עַל כֵּן אַתּוּן אָמְרִין נֵזֵיל נְדַבַּח קֳדָם יְיָ:
@118 וּכְעַן אֱזִילוּ פְלָחוּ וְתִבְנָא לָא יִתְיְהֵב לְכוֹן וּסְכוֹם לְבֵינַיָא תִּתְּנוּן:
@119 וַחֲזוֹ סָרְכֵי בְנֵי יִשְׂרָאֵל יָתְהוֹן בְּבִישׁ לְמֵימָר לָא תִמְנְעוּן מִלִבְנֵיכוֹן פִּתְגַם יוֹם בְּיוֹמֵהּ:
@120 וַעֲרָעוּ יָת משֶׁה וְיָת אַהֲּרֹן קָיְמִין לְקַדָמוּתְהוֹן בְּמִפַּקְהוֹן מִקֳדָם פַּרְעֹה:
@121 וַאֲמָרוּ לְהוֹן יִתְגְלֵי יְיָ עֲלֵיכוֹן וְיִתְפְּרַע דִי אַבְאֶשְׁתּוּן יָת רֵיחָנָא בְּעֵינֵי פַרְעֹה וּבְעֵינֵי עַבְדוֹהִי לְמִתַּן חַרְבָּא בִּידֵיהוֹן לְקַטָלוּתָנָא:
@122 וְתָב משֶׁה קֳדָם יְיָ וַאֲמַר יְיָ לְמָא אַבְאֵשְׁתָּא לְעַמָא הָדֵין וּלְמָא דְנַן שְׁלַחְתָּנִי:
@123 וּמֵעִדַן עַלִית לְוָת פַּרְעֹה לְמַלָלָא בִשְׁמָךְ אַבְאֵשׁ לְעַמָּא הָדֵין וְשֵׁזָבָא לָא שֵׁזַבְתָּא יָת עַמָךְ:
@124 וַאֲמַר יְיָ לְמשֶׁה כְּעַן תֶּחֱזֵי דְאֶעְבֵּד לְפַרְעֹה אֲרֵי בִידָא תַקִיפָא יְשַׁלְחִנוּן וּבִידָא תַקִיפָא יְתָרֵכִנוּן מֵאַרְעֵהּ: ססס:
@125 וּמַלִיל יְיָ עִם משֶׁה וַאֲמַר לֵהּ אֲנָא יְיָ:
@126 וְאִתְגְלֵיתִי לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב בְּאֵל שַׁדָי וּשְׁמִי יְיָ לָא הוֹדָעִית לְהוֹן:
@127 וְאַף אֲקֵימִית יָת קְיָמִי עִמְהוֹן לְמִתַּן לְהוֹן יָת אַרְעָא דִכְנָעַן יָת אַרְעָא תּוֹתָבוּתְהוֹן דְאִתּוֹתָבוּ בָהּ:
@128 וְאַף קֳדָמַי שְׁמִיעַ יָת קְבֵילַת בְּנֵי יִשְׂרָאֵל דִי מִצְרָאֵי מַפְלְחִין בְּהוֹן וְדָכִירְנָא יָת קְיָמִי:
@129 בְּכֵן אֱמַר לִבְנֵי יִשְׂרָאֵל אֲנָא יְיָ וְאַפֵּיק יָתְכוֹן מִגוֹ דְחוֹק פָּלְחַן מִצְרָאֵי וֶאֱשֵׁיזֵב יָתְכוֹן מִפָּלְחָנְהוֹן וְאֶפְרוֹק יָתְכוֹן בִּדְרָעָה מְרָמָא וּבְדִינִין רַבְרְבִין:
@130 וֶאֱקָרֵיב יָתְכוֹן קדָמַי לְעַמָא וְאֶהֱוֵי לְכוֹן לֶאֱלָהּ וְתִדְעוּן אֲרֵי אֲנָא יְיָ אֱלָהָכוֹן דְאַפֵּיק יָתְכוֹן מִגוֹ דְחוֹק פָּלְחַן מִצְרָיִם:
@131 וְאָעֵיל יָתְכוֹן לְאַרְעָא דִי קַיֵמִית בְּמֵימְרִי לְמִתַּן יָתַהּ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב וְאֶתֵּן יָתַהּ לְכוֹן יְרֻתָּא אֲנָא יְיָ:
@132 וּמַלֵיל משֶׁה כֵּן לִבְנֵי יִשְׂרָאֵל וְלָא קַבִּילוּ מִן משֶׁה מִמַעְיַק רוּחָא וּמִפָּלְחָנָא דַהֲוָה קָשְׁיָא עֲלֵיהוֹן:
@133 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@134 עוּל מַלֵיל לְוָת פַּרְעֹה מַלְכָּא דְמִצְרָיִם וִישַׁלַח יָת בְּנֵי יִשְׂרָאֵל מֵאַרְעֵהּ:
@135 וּמַלִיל משֶׁה קֳדָם יְיָ לְמֵימָר הָא בְנֵי יִשְׂרָאֵל לָא קַבִּילוּ מִנִי וְאֵכְדֵין יְקַבֵּל מִנִי פַרְעֹה וַאֲנָא יַקִיר מַמְלָל:
@136 וּמַלִיל יְיָ עִם משֶׁה וְעִם אַהֲרֹן וּפַקֵדִנוּן לְוָת בְּנֵי יִשְׂרָאֵל וּלְוָת פַּרְעֹה מַלְכָּא דְמִצְרָיִם לְאַפָּקָא יָת בְּנֵי יִשְׂרָאֵל מֵאַרְעָא דְמִצְרָיִם:
@137 אִלֵין רֵישֵׁי בֵית אֲבָהָתְהוֹן בְּנֵי רְאוּבֵן בּוּכְרָא דְיִשְׂרָאֵל חֲנוֹךְ וּפַלוּא חֶצְרוֹן וְכַרְמִי אִלֵין זַרְעֲיַת רְאוּבֵן:
@138 וּבְנֵי שִׁמְעוֹן יְמוּאֵל וְיָמִין וְאֹהַד וְיָכִין וְצֹחַר וְשָׁאוּל בַּר כְּנַעֲנֵיתָא אִלֵין זַרְעֲיַת שִׁמְעוֹן:
@139 וְאִלֵין שְׁמָהַת בְּנֵי לֵוִי לְתוּלְדָתְהוֹן גֵרְשׁוֹן וּקְהָת וּמְרָרִי וּשְׁנֵי חַיֵי לֵוִי מְאָה וּתְלָתִין וּשְׁבַע שְׁנִין:
@140 בְּנֵי גֵרְשׁוֹן לִבְנִי וְשִׁמְעִי לְזַרְעֲיָתְהוֹן:
@141 וּבְנֵי קְהָת עַמְרָם וְיִצְהָר וְחֶבְרוֹן וְעֻזִיאֵל וּשְׁנֵי חַיֵי קְהָת מְאָה וּתְלָתִין וּתְלַת שְׁנִין:
@142 וּבְנֵי מְרָרִי מַחְלִי וּמוּשִׁי אִלֵין זַרְעֲיַת לֵוִי לְתוּלְדָתְהוֹן:
@143 וּנְסִיב עַמְרָם יָת יוֹכֶבֶד אֲחַת אֲבוּהִי לֵהּ לְאִנְתּוּ וִילִידַת לֵהּ יָת אַהֲרֹן וְיָת משֶׁה וּשְׁנֵי חַיֵי עַמְרָם מְאָה וּתְלָתִין וּשְׁבַע שְׁנִין:
@144 וּבְנֵי יִצְהָר קֹרַח וָנֶפֶג וְזִכְרִי:
@145 וּבְנֵי עֻזִיאֵל מִישָׁאֵל וְאֶלְצָפָן וְסִתְרִי:
@146 וּנְסִיב אַהֲרֹן יָת אֱלִישֶׁבַע בַּת עַמִינָדָב אַחָתֵהּ דְנַחְשׁוֹן לֵהּ לְאִנְתּוּ וִילִידַת לֵהּ יָת נָדָב וְיָת אֲבִיהוּא יָת אֶלְעָזָר וְיָת אִיתָמָר:
@147 וּבְנֵי קֹרַח אַסִיר וְאֶלְקָנָה וַאֲבִיאָסָף אִלֵין זַרְעֲיַת קֹרַח:
@148 וְאֶלְעָזָר בַּר אַהֲרֹן נְסִיב לֵהּ מִבְּנַת פּוּטִיאֵל לֵהּ לְאִנְתּוּ וִילִידַת לֵהּ יָת פִּינְחָס אִלֵין רֵישֵׁי אֲבָהַת לֵיוָאֵי לְזַרְעֲיָתְהוֹן:
@149 הוּא אַהֲרֹן וּמשֶׁה דִי אֲמַר יְיָ לְהוֹן אַפִּיקוּ יָת בְּנֵי יִשְׂרָאֵל מֵאַרְעָא דְמִצְרַיִם עַל חֵילֵיהוֹן:
@150 אִנוּן דְמַלְלִין עִם פַּרְעֹה מַלְכָּא דְמִצְרַיִם לְאַפָּקָא יָת בְּנֵי יִשְׂרָאֵל מִמִצְרָיִם הוּא משֶׁה וְאַהֲרֹן:
@151 וַהֲוָה בְּיוֹמָא דְמַלִיל יְיָ עִם משֶׁה בְּאַרְעָא דְמִצְרָיִם:
@152 וּמַלִיל יְיָ עִם משֶׁה לְמֵימַר אֲנָא יְיָ מַלֵל עִם פַּרְעֹה מַלְכָּא דְמִצְרַיִם יָת כָּל דִי אֲנָא מְמַלֵל עִמָךְ:
@153 וַאֲמַר משֶׁה קֳדָם יְיָ הָא אֲנָא יַקִיר מַמְלָל וְאֶכְדֵין יְקַבֵּל מִנִי פַּרְעֹה:
@154 וַאֲמַר יְיָ לְמשֶׁה חֲזֵי מַנֵיתָךְ רַב לְפַרְעֹה וְאַהֲרֹן אָחוּךְ יְהֵי מְתֻרְגְמָנָךְ:
@155 אַתְּ תְּמַלֵל יָת כָּל דִי אֲפַקְדִנָךְ וְאַהֲרֹן אָחוּךְ יְמַלֵל עִם פַּרְעֹה וִישַׁלַח יָת בְּנֵי יִשְׂרָאֵל מֵאַרְעֵהּ:
@156 וַאֲנָא אַקְשֵׁי יָת לִבָּא דְפַרְעֹה וְאַסְגֵיתִי יָת אַתְוָתַי וְיָת מוֹפְתַי בְּאַרְעָא דְמִצְרָיִם:
@157 וְלָא יְקַבֵּל מִנְכוֹן פַּרְעֹה וְאֶתֵּן יָת מָחַת גְבֻרְתִּי בְּמִצְרָיִם וְאַפֵּיק יָת חֵילִי יָת עַמִי בְנֵי יִשְׂרָאֵל מֵאַרְעָא דְמִצְרַיִם בְּדִינִין רַבְרְבִין:
@158 וְיִדְעוּן מִצְרַיִם אֲרֵי אֲנָא יְיָ כַּד אָרֵים יָת מָחַת גְבֻרְתִּי עַל מִצְרָיִם וְאַפֵּיק יָת בְּנֵי יִשְׂרָאֵל מִבֵּינֵיהוֹן:
@159 וַעֲבַד משֶׁה וְאַהֲרֹן כְּמָא דְפַקִיד יְיָ יָתְהוֹן כֵּן עֲבָדוּ:
@160 וּמשֶׁה בַּר תְּמָנָן שְׁנִין וְאַהֲרֹן בַּר תְּמָנָן וּתְלָת שְׁנִין בְּמַלָלוּתְהוֹן עִם פַּרְעֹה:
@161 וַאֲמַר יְיָ לְמשֶׁה וּלְאַהֲרֹן לְמֵימָר:
@162 אֲרֵי יְמַלֵל לְוָתְכוֹן פַּרְעֹה לְמֵימַר הָבוּ לְכוֹן אָתָא וְתֵימַר לְאַהֲרֹן סַב יָת חוּטְרָךְ וּרְמֵי קֳדָם פַּרְעֹה יְהִי לְתַנִינָא:
@163 וְעַל משֶׁה וְאַהֲרֹן לְוָת פַּרְעֹה וַעֲבָדוּ כֵן כְּמָא דְפַקֵיד יְיָ וּרְמָא אַהֲרֹן יָת חוּטְרֵהּ קֳדָם פַּרְעֹה וְקָדָם עַבְדוֹהִי וַהֲוָה לְתַנִינָא:
@164 וּקְרָא אַף פַּרְעֹה לְחַכִּימַיָא וּלְחָרָשַׁיָא וַעֲבָדוּ אַף אִנּוּן חָרָשֵׁי מִצְרַיִם בְּלַחֲשֵׁיהוֹן כֵּן:
@165 וּרְמוֹ גְבַר חוּטְרֵהּ וַהֲווֹ לְתַנִינַיָא וּבְלַע חֻטְרָא דְאַהֲרֹן יָת חֻטְרֵיהוֹן:
@166 וְאִתַּקַף לִבָּא דְפַרְעֹה וְלָא קַבִּיל מִנְהוֹן כְּמָא דְמַלִיל יְיָ:
@167 וַאֲמַר יְיָ לְמשׁה אִתְיַקַר (לפרש''י יַקִיר) לִבָּא דְפַרְעֹה סָרִיב לְשַׁלָחָא עַמָא:
@168 אִזֵיל לְוָת פַּרְעֹה בְּצַפְרָא הָא נָפֵיק לְמַיָא וְתִתְעַתַּד לְקַדָמוּתֵהּ עַל כֵּיף נַהֲרָא וְחֻטְרָא דְאִתְהֲפִיךְ לְחִוְיָא תִּסַב בִּידָךְ:
@169 וְתֵימַר לֵהּ יְיָ אֱלָהָא דִיהוּדָאֵי שַׁלְחַנִי לְוָתָךְ לְמֵימַר שַׁלַח יָת עַמִי וְיִפְלְחוּן קֳדָמַי בְּמַדְבְּרָא וְהָא לָא קַבִּלְתָּא עַד כְּעָן:
@170 כִּדְנַן אֲמַר יְיָ בְּדָא תִדַע אֲרֵי אֲנָא יְיָ הָא אֲנָא מָחֵי בְּחֻטְרָא דִי בִידִי עַל מַיָא דִי בְנַהֲרָא וְיִתְהַפְּכוּן לִדְמָא:
@171 וְנוּנֵי דִי בְנַהֲרָא תְּמוּת וּסְרִי נַהֲרָא וְיִלְאוּן מִצְרָאֵי לְמִשְׁתֵּי מַיָא מִן נַהֲרָא:
@172 וַאֲמַר יְיָ לְמשֶׁה אֱמַר לְאַהֲרֹן טּוֹל חֻטְרָךְ וַאֲרֵים יְדָךְ עַל מַיָא דְמִצְרַיִם עַל נַהֲרֵיהוֹן עַל אֲרִתֵּיהוֹן וְעַל אַגְמֵיהוֹן וְעַל כָּל בֵּית כְּנִישׁוּת מֵימֵיהוֹן וִיהוֹן דְמָא וִיהֵי דְמָא בְּכָל אַרְעָא דְמִצְרַיִם וּבְמָנֵי אָעָא וּבְמָנֵי אַבְנָא:
@173 וַעֲבָדוּ כֵן משֶׁה וְאַהֲרֹן כְּמָא דְפַקֵיד יְיָ וַאֲרֵים בְּחֻטְרָא וּמְחָא יָת מַיָא דִי בְנַהֲרָא לְעֵינֵי פַּרְעֹה וּלְעֵינֵי עַבְדוֹהִי וְאִתְהַפִיכוּ כָּל מַיָא דִי בְנַהֲרָא לִדְמָא:
@174 וְנוּנֵי דִי בְנַהֲרָא מִיתוּ וּסְרִי נַהֲרָא וְלָא יְכִילוּ מִצְרָאֵי לְמִשְׁתֵּי מַיָא מִן נַהֲרָא וַהֲוָה דְמָא בְּכָל אַרְעָא דְמִצְרָיִם:
@175 וַעֲבָדוּ כֵן חָרָשֵׁי מִצְרַיִם בְּלַחֲשֵׁיהוֹן וְאִתַּקַף לִבָּא דְפַרְעֹה וְלָא קַבֵּיל מִנְהוֹן כְּמָא דְמַלִיל יְיָ:
@176 וְאִתְפְּנִי פַרְעֹה וְעַל לְבֵיתֵהּ וְלָא שַׁוִי לִבֵּהּ אַף לְדָא:
@177 וַחֲפָרוּ כָל מִצְרָאֵי סַחֲרָנוּת נַהֲרָא מַיָא לְמִשְׁתֵּי אֲרֵי לָא יְכִילוּ לְמִשְׁתֵּי מִמַיָא דְנַהֲרָא:
@178 וְאַשְׁלֵם שִׁבְעַת יוֹמִין בָּתַר דִמְחָא יְיָ יָת נַהֲרָא:
@179 וַאֲמַר יְיָ לְמשֶׁה עוּל לְוָת פַּרְעֹה וְתֵימַר לֵהּ כִּדְנַן אֲמַר יְיָ שַׁלַח יָת עַמִי וְיִפְלְחוּן קֳדָמָי:
@180 וְאִם סָרִיב אַתְּ לְשַׁלָחָא הָא אֲנָא מָחֵי יָת כָּל תְּחוּמָךְ בְּעֻרְדְעָנַיָא:
@181 וִירַבֵּי נַהֲרָא עֻרְדְעָנַיָא וְיִסְקוּן וְיֶעֱלוּן בְּבֵיתָךְ וּבְאִדְרוֹן בֵּית מִשְׁכְּבָךְ וְעַל עַרְסָךְ וּבְבֵית עַבְדָיךְ וּבְעַמָךְ וּבְתַנוּרָךְ וּבְאַצְוָתָךְ:
@182 וּבָךְ וּבְעַמָךְ וּבְכָל עַבְדָיךְ יִסְקוּן עֻרְדְעָנַיָא:
@183 וַאֲמַר יְיָ לְמשֶׁה אֱמַר לְאַהֲרֹן אֲרֵים יָת יְדָךְ בְּחֻטְּרָךְ עַל נַהֲרַיָא עַל אֲרִיתַּיָא וְעַל אַגְמַיָא וְאַסֵיק יָת עֻרְדְעָנַיָא עַל אַרְעָא דְמִצְרָיִם:
@184 וַאֲרֵים אַהֲרֹן יָת יְדֵהּ עַל מַיָא דְמִצְרָאֵי וּסְלֵיקַת עֻרְדְעָנַיָא וַחֲפַת יָת אַרְעָא דְמִצְרָיִם:
@185 וַעֲבָדוּ כֵן חָרָשַׁיָא בְּלַחֲשֵׁיהוֹן וְאַסִ יקוּ יָת עֻרְדְעָנַיָא עַל אַרְעָא דְמִצְרָיִם:
@186 וּקְרָא פַרְעֹה לְמשֶׁה וּלְאַהֲרֹן וַאֲמַר צַלוֹ קֳדָם יְיָ וְיַעְדֵי עֻרְדְעָנַיָא מִנִי וּמֵעַמִי וְאֶשְׁלַח יָת עַמָא וְיִדְבְּחוּן קֳדָם יְיָ:
@187 וַאֲמַר משֶׁה לְפַרְעֹה שְׁאַל לָךְ גְבוּרָא הַב לִי זְמַן לְאִמָתַי אֱצַלֵי עֲלָךְ וְעַל עַבְדָיךְ וְעַל עַמָךְ לְשֵׁיצָאָה עֻרְדְעָנַיָא מִנָךְ וּמִבָּתָּיךְ לְחוֹד בְּנַהֲרָא תִּשְׁתָּאָרָן:
@188 וַאֲמַר לִמְחָר וַאֲמַר כְּפִתְגָמָךְ בְּדִיל דְתִדַע אֲרֵי לֵית כַּיְיָ אֱלָהָנָא:
@189 וְיֶעְדוּן עֻרְדְעָנַיָא מִנָךְ וּמִבָּתָּיךְ וּמֵעַבְדָיךְ וּמֵעַמָךְ לְחוֹד בְּנַהֲרָא יִשְׁתָּאָרָן:
@190 וּנְפַק משֶׁה וְאַהֲרֹן מִלְוָת פַרְעֹה וְצַלִי משֶׁה קֳדָם יְיָ עַל עֵסַק עֻרְדְעָנַיָא דִי שַׁוִי לְפַרְעֹה:
@191 וַעֲבַד יְיָ כְּפִתְגָמָא דְמשֶׁה וּמִיתוּ עוּרְדְעָנַיָא מִן בָּתַּיָא מִן דָרָתָא וּמִן חַקְלָתָא:
@192 וּכְנָשׁוּ יָתְהוֹן דְגוֹרִין דְגוֹרִין וּסְרִיאוּ עַל אַרְעָא:
@193 וַחֲזָא פַרְעֹה אֲרֵי הֲוַת רְוַחְתָּא וְיִתְיַקַר יָת לִבֵּהּ וְלָא קַבִּיל מִנְהוֹן כְּמָא דְמַלִיל יְיָ:
@194 וַאֲמַר יְיָ לְמשֶׁה אֱמַר לְאַהֲרֹן אֲרֵים יָת חֻטְרָךְ וּמְחָא יָת עַפְרָא דְאַרְעָא וִיהֵא לְקַלְמְתָא בְּכָל אַרְעָא דְמִצְרָיִם:
@195 וַעֲבָדוּ כֵן וַאֲרֵים אַהֲרֹן יָת יְדֵהּ בְחֻטְרֵהּ וּמְחָא יָת עַפְרָא דְאַרְעָא וַהֲוַת קַלְמְתָא בַּאֲנָשָׁא וּבִבְעִירָא כָּל עַפְרָא דְאַרְעָא הֲוַת קַלְמְתָא בְּכָל אַרְעָא דְמִצְרָיִם:
@196 וַעֲבָדוּ כֵן חָרָשַׁיָא בְּלַחֲשֵׁיהוֹן לְאַפָּקָא יָת קַלְמְתָא וְלָא יָכִילוּ וַהֲוַת קַלְמְתָא בַּאֲנָשָׁא וּבִבְעִירָא:
@197 וַאֲמָרוּ חָרָשַּׁיָא לְפַרְעֹה הָא מָחָא מִן קֳדָם יְיָ הִיא וְאִתַּקַף לִבָּא דְפַרְעֹה וְלָא קַבִּיל מִנְהוֹן כְּמָא דִמַלִיל יְיָ:
@198 וַאֲמַר יְיָ לְמשֶׁה אַקְדֵם בְּצַפְרָא וְאִתְעַתַּד קֳדָם פַּרְעֹה הָא נָפֵק לְמַיָא וְתֵימַר לֵהּ כִּדְנַן אֲמַר יְיָ שַׁלַח עַמִי וְיִפְלְחוּן קֳדָמָי:
@199 אֲרֵי אִם לֵיתָךְ מְשַׁלַח יָת עַמִי הָא אֲנָא מַשְׁלַח בָּךְ וּבְעַבְדָיךְ וּבְעַמָךְ וּבְבָתָּיךְ יָת עָרוֹבָא וְיִמְלוּן בָּתֵּי מִצְרַיִם יָת עָרוֹבָא וְאַף אַרְעָא דְאִנוּן עֲלַהּ:
@200 וְאַפְרֵישׁ בְּיוֹמָא הַהוּא יָת אַרְעָא דְגשֶׁן דְעַמִי קָאִים עֲלַהּ בְּדִיל דְלָא לְמֶהֱוֵי תַמָן עָרוֹבָא בְּדִיל דְתִדַע אֲרֵי אֲנָא יְיָ שַׁלִיטּ בְּגוֹ אַרְעָא:
@201 וֶאֱשַׁוֵי פוּרְקַן לְעַמִי וְעַל עַמָךְ אַיְתִי מָחָא לִמְחָר יְהֵא אָתָא הָדֵין:
@202 וַעֲבַד יְיָ כֵּן וַאֲתָא עָרוֹבָא תַקִיף לְבֵית פַּרְעֹה וּלְבֵית עַבְּדוֹהִי וּבְכָל אַרְעָא דְמִצְרַיִם אִתְחַבָּלַת אַרְעָא מִן קֳדָם עָרוֹבָא:
@203 וּקְרָא פַרְעֹה לְמשֶׁה וּלְאַהֲרֹן וַאֲמַר אֱזִילוּ דַבָּחוּ קֳדָם אֱלָהָכוֹן בְּאַרְעָא:
@204 וַאֲמַר משֶׁה לָא תַקֵן לְמֶעְבַּד כֵּן אֲרֵי בְעִירָא דְמִצְרָאֵי דָחֲלִין לֵהּ מִנֵהּ אֲנַחְנָא נָסְבִין לְדַבָּחָא קֳדָם יְיָ אֱלָהָנָא הָא נְדַבַּח יָת בְּעִירָא דְמִצְרָאֵי דָחֲלִין לֵהּ וְאִנוּן יְהוֹן חָזָן הֲלָא יֵימְרוּן לְמִרְגְמָנָא:
@205 מַהֲלַךְ תְּלָתָא יוֹמִין נֵיזִיל בְּמַדְבְּרָא וּנְדַבַּח קֳדָם יְיָ אֱלָהָנָא כְּמָא דְיֵימַר לָנָא:
@206 וַאֲמַר פַּרְעֹה אֲנָא אֲשַׁלַח יָתְכוֹן וְתִדְבְּחוּן קֳדָם יְיָ אֱלָהָכוֹן בְּמַדְבְּרָא לְחוֹד אַרְחָקָא לָא תְרַחֲקוּן לְמֵיזַל צַלוֹ אַף עָלָי:
@207 וַאֲמַר משֶׁה הָא אֲנָא נָפֵק מֵעִמָךְ וֶאֱצַלֵי קֳדָם יְיָ וְיַעְדֵי עָרוֹבָא מִפַּרְעֹה מֵעַבְדוֹהִי וּמֵעַמֵהּ מְחָר לְחוֹד לָא יוֹסֵף פַּרְעֹה לְשַׁקָרָא בְּדִיל דְלָא לְשַׁלָחָא יָת עַמָא לְדַבָּחָא קֳדָם יְיָ:
@208 וּנְפַק משֶׁה מִן קֳדָם פַּרְעֹה וְצַלִי קֳדָם יְיָ:
@209 וַעֲבַד יְיָ כְּפִתְגָמָא דְמשֶׁה וְאַעְדִי עָרוֹבָא מִפַּרְעֹה מֵעַבְדוֹהִי וּמֵעַמֵהּ לָא אִשְׁתָּאַר חָד:
@210 וְיַקַר פַּרְעֹה יָת לִבֵּהּ אַף בְּזִמְנָא הָדָא וְלָא שַׁלַח יָת עַמָא:
@211 וַאֲמַר יְיָ לְמשֶׁה עוּל לְוָת פַּרְעֹה וּתְמַלֵל עִמֵהּ כִּדְנַן אֲמַר יְיָ אֱלָהָא דִיהוּדָאֵי שַׁלַח יָת עַמִי וְיִפְלְחוּן קֳדָמָי:
@212 אֲרֵי אִם סָרִיב אַתְּ לְשַׁלָחָא וְעַד כְּעַן אַתְּ מַתְקֵף בְּהוֹן:
@213 הָא מָחָא מִן קֳדָם יְיָ הַוְיָא בִּבְעִירָךְ דִי בְחַקְלָא בְּסוּסְוָתָא בַּחֲמָרֵי בְּגַמְלֵי בְּתוֹרֵי וּבְעָנָא מוֹתָא תַּקִיף לַחֲדָא:
@214 וְאַפְרֵישׁ יְיָ בֵּין בְּעִירָא דְיִשְׂרָאֵל וּבֵין בְּעִירָא דְמִצְרָיִם וְלָא יְמוּת מִכָּל לִבְנֵי יִשְׂרָאֵל מִדָעַם:
@215 וְשַׁוִי יְיָ זִמְנָא לְמֵימָר מְחַר יַעְבֵּד יְיָ פִּתְגָמָא הָדֵין בְּאַרְעָא:
@216 וַעֲבַד יְיָ יָת פִּתְגָמָא הָדֵין בְּיוֹמָא דְבַתְרוֹהִי וּמִית כֹּל בְּעִירָא דְמִצְרָיִם וּמִבְּעִירָא דִבְנֵי יִשְׂרָאֵל לָא מִית חָד:
@217 וּשְׁלַח פַּרְעֹה וְהָא לָא מִית מִבְּעִירָא דְיִשְׂרָאֵל עַד חָד וְאִתְיַקַר לִבָּא דְפַרְעֹה וְלָא שַׁלַח יָת עַמָא:
@218 וַאֲמַר יְיָ לְמשֶׁה וּלְאַהֲרֹן סִיבוּ לְכוֹן מְלֵי חָפְנֵיכוֹן פִּיחָא דְאַתּוּנָא וְיִזְרְקִנֵהּ משֶׁה לְצֵית שְׁמַיָא לְעֵינֵי פַרְעֹה:
@219 וִיהֵי לְאַבְקָא עַל כָּל אַרְעָא דְמִצְרָיִם וִיהֵי עַל אֲנָשָׁא וְעַל בְּעִירָא לְשִׁיחֲנָא סַגִי אֲבַעְבֻּעִין בְּכָל אַרְעָא דְמִצְרָיִם:
@220 וּנְסִיבוּ יָת פִּיחָא דְאַתּוּנָא וְקָמוּ קֳדָם פַּרְעֹה וּזְרַק יָתֵהּ משֶׁה לְצֵית שְׁמַיָא וַהֲוָה שִׁיחֲנָא אֲבַעְבֻּעִין סָגֵי בַּאֲנָשָׁא וּבִבְעִירָא:
@221 וְלָא יָכִילוּ חָרָשַׁיָא לְמֵיקַם קֳדָם משֶׁה מִן קֳדָם שִׁיחֲנָא אֲרֵי הֲוָה שִׁיחֲנָא בְּחָרָשַׁיָא וּבְכָל מִצְרָאֵי:
@222 וְתַקִיף יְיָ יָת לִבָּא דְפַרְעֹה וְלָא קַבִּיל מִנְהוֹן כְּמָא דְמַלֵיל יְיָ עִם משֶׁה:
@223 וַאֲמַר יְיָ לְמשֶׁה אַקְדֵם בְּצַפְרָא וְאִתְעַתַּד קֳדָם פַּרְעֹה וְתֵימַר לֵהּ כִּדְנַן אֲמַר יְיָ אֱלָהָא דִיהוּדָאֵי שַׁלַח יָת עַמִי וְיִפְלְחוּן קֳדָמָי:
@224 אֲרֵי בְּזִמְנָא הָדָא אֲנָא שָׁלַח יָת כָּל מְחָתַי לְלִבָּךְ וּבְעַבְדָיךְ וּבְעַמָךְ בְּדִיל דְתִדַע אֲרֵי לֵית דִכְוָתִי שַׁלִיט בְּכָל אַרְעָא:
@225 אֲרֵי כְעַן קְרֵיב קֳדָמַי דְאֶשְׁלַח פּוֹן יָת מַחַת גְבֻרְתִּי וְאֶמְחֵי יָתָךְ וְיָת עַמָךְ בְּמוֹתָא וְשֵׁיצִיאַת מִן אַרְעָא:
@226 וּבְרַם בְּדִיל דָא קַיֵמְתָּךְ בְּדִיל לְאַחֲזָיוּתָךְ יָת חֵילִי וּבְדִיל דִיהוֹן מִשְׁתָּעַן גְבוּרַת שְׁמִי בְּכָל אַרְעָא:
@227 עַד כְּעַן אַתְּ כְּבֵישַׁת בֵּהּ בְּעַמִי בְּדִיל דְלָא לְשַׁלָחוּתְהוֹן:
@228 הָא אֲנָא מָחֵית מִטְרָא בְּעִדָנָא הָדֵין מְחַר בַּרְדָא תַּקִיף לַחֲדָא דִי לָא הֲוָה דִכְוָתֵהּ בְּמִצְרַיִם לְמִן יוֹמָא דְאִשְׁתַּכְלָלַת וְעַד כְּעָן:
@229 וּכְעַן שְׁלַח כְּנוֹשׁ יָת בְּעִירָךְ וְיָת כָּל דִי לָךְ בְּחַקְלָא כָּל אֲנָשָׁא וּבְעִירָא דְאִשְׁתְּכַח בְּחַקְלָא וְלָא יִתְכְּנֵשׁ לְבֵיתָא וְיֵחוֹת עֲלֵיהוֹן בַּרְדָא וִימוּתוּן:
@230 דְדָחִיל מִפִּתְגָמָא דַיְיָ מֵעַבְדֵי פַּרְעֹה כְּנַשׁ יָת עַבְדוֹהִי וְיָת גֵיתוֹהִי לְבָתַּיָא:
@231 וְדִי לָא שַׁוִי לִבֵּהּ לְפִתְגָמָא דַיְיָ שְׁבַק יָת עַבְדוֹהִי וְיָת גֵיתוֹהִי בְּחַקְלָא:
@232 וַאֲמַר יְיָ לְמשֶׁה אֲרֵים יָת יְדָךְ עַל צֵית שְׁמַיָא וִיהֵי בַרְדָא בְּכָל אַרְעָא דְמִצְרָאֵי עַל אֲנָשָׁא וְעַל בְּעִירָא וְעַל כָּל עֶסְבָּא דְחַקְלָא בְּאַרְעָא דְמִצְרָיִם:
@233 וַאֲרֵים משֶׁה יָת חֻטְרֵהּ עַל צֵית שְׁמַיָא וַיְיָ יְהַב קָלִין וּבַרְדָא וּמְהַלְכָא אֶשָׁתָא עַל אַרְעָא וְאַמְטַר יְיָ בַּרְדָא עַל אַרְעָא דְמִצְרָיִם:
@234 וַהֲוָה בַרְדָא וְאֶשָׁתָא מִשְׁתַּלְהָבַת בְּגוֹ בַרְדָא תַּקִיף לַחֲדָא דִי לָא הֲוָה דִכְוָתֵהּ בְּכָל אַרְעָא דְמִצְרַיִם מֵעִדַן דַהֲוַת לְעָם:
@235 וּמְחָא בַרְדָא בְּכָל אַרְעָא דְמִצְרַיִם יָת כָּל דִי בְחַקְלָא מֵאֲנָשָׁא וְעַד בְּעִירָא וְיָת כָּל עֶסְבָּא דְחַקְלָא מְחָא בַרְדָא וְיָת כָּל אִילַן דִבְחַקְלָא תְּבַר:
@236 לְחוֹד בְּאַרְעָא דְגשֶׁן דִי תַמָן בְּנֵי יִשְׂרָאֵל לָא הֲוָה בַּרְדָא:
@237 וּשְׁלַח פַּרְעֹה וּקְרָא לְמשֶׁה וּלְאַהֲרֹן וַאֲמַר לְהוֹן חָבִית זִמְנָא הָדָא יְיָ זַכָּאָה וַאֲנָא וְעַמִי חַיָבִין:
@238 צַלוֹ קֳדָם יְיָ וְסַגִי קֳדָמוֹהִי רְוַח דְלָא יְהוֹן עֲלָנָא קָלִין דִלְוַט כְּאִלֵין מִן קֳדָם יְיָ וּבַרְדָא וְאֶשְׁלַח יָתְכוֹן וְלָא תוֹסְפוּן לְאִתְעַכָּבָא:
@239 וַאֲמַר לֵהּ משֶׁה כְּמִפְּקִי מִן קַרְתָּא אֶפְרוֹשׂ יְדַי בִּצְלוֹ קֳדָם יְיָ קָלַיָא יִתְמַנְעוּן וּבַרְדָא לָא יְהֵי עוֹד בְּדִיל דְתִדַע אֲרֵי דַיְיָ אַרְעָא:
@240 וְאַתְּ וְעַבְדָיךְ יְדַעְנָא אֲרֵי עַד כְּעַן לָא אִתְכְּנַעְתּוּן מִן קֳדָם יְיָ אֱלֹהִים:
@241 וְכִתָּנָא וְסַעֲרֵי לְקוֹ אֲרֵי סַעְרַנְיָא אַבִּיבִין וְכִתָּנָא גַבְעוֹלִין:
@242 וְחִטָאָה וְכֻנְתַּיָא לָא לְקוֹ אֲרֵי אֲפֵילָתָא אִנוּן:
@243 וּנְפַק משֶׁה מִלְוַת פַּרְעֹה יָת קַרְתָּא וּפְרַשׂ יְדוֹהִי בִּצְלוֹ קֳדָם יְיָ וַיִתְמַנְעוּן קָלַיָא וּבַרְדָא וּמִטְרָא דַהֲוָה נָחִית לָא מְטָא עַל אַרְעָא:
@244 וַחֲזָא פַרְעֹה אֲרֵי אִתְמְנַע מִטְרָא וּבַרְדָא וְקָלַיָא וְאוֹסֵף לְמֶחֱטֵי וְיַקְרֵהּ לְלִבֵּהּ הוּא וְעַבְדוֹהִי:
@245 וְאִתַּקַף לִבָּא דְפַרְעֹה וְלָא שַׁלַח יָת בְּנֵי יִשְׂרָאֵל כְּמָא דִי מַלֵיל יְיָ בִּידָא דְמשֶׁה: פפפ:
@246 וַאֲמַר יְיָ לְמשֶׁה עוּל לְוָת פַּרְעֹה אֲרֵי אֲנָא יַקָרִית יָת לִבֵּהּ וְיָת לִבָּא דְעַבְדוֹהִי בְּדִיל לְשַׁוָאָה אָתַי אִלֵין בֵּינֵיהוֹן:
@247 וּבְדִיל דְתִשְׁתָּעֵי קֳדָם בְּרָךְ וּבַר בְּרָךְ יָת נִסִין דִי עֲבָדִית בְּמִצְרַיִם וְיָת אַתְוָתַי דִי שַׁוֵיתִי בְהוֹן וְתִדְעוּן אֲרֵי אֲנָא יְיָ:
@248 וַאֲתָא משֶׁה וְאַהֲרֹן לְוָת פַּרְעֹה וַאֲמָרוּ לֵהּ כִּדְנַן אֲמַר יְיָ אֱלָהָא דִיהוּדָאֵי עַד אִמָתַי מְסָרֵב אַתְּ לְאִתְכְּנָעָא מִן קֳדָמָי שַׁלַח עַמִי וְיִפְלְחוּן קֳדָמָי:
@249 אֲרֵי אִם סָרֵיב אַתְּ לְשַׁלָחָא יָת עַמִי הָא אֲנָא מַיְיתִי מְחָר גוֹבָא בִּתְחוּמָךְ:
@250 וַחֲפָא יָת עֵין שִׁמְשָׁא דְאַרְעָא וְלָא יִכּוּל לְמֶחֱזֵי יָת אַרְעָא וְיֵכוּל יָת שְׁאָר שֵׁזַבְתָּא דְאִשְׁתָּאַר לְכוֹן מִן בַּרְדָא וְיֵכוּל יָת כָּל אִילָנָא דְאַצְמַח לְכוֹן מִן חַקְלָא:
@251 וְיִמְלוּן בָּתָּיךְ וּבָתֵּי כָל עַבְדָיךְ וּבָתֵּי כָל מִצְרַיִם דִי לָא חֲזוֹ אֲבָהָתָךְ וַאֲבָהַת אֲבָהָתָךְ מִיוֹמָא דְמֶהֱוֵיהוֹן עַל אַרְעָא עַד יוֹמָא הָדֵין וְאִתְפְּנִי וּנְפַק מִן קֳדָם פַּרְעֹה:
@252 וַאֲמָרוּ עַבְדֵי פַרְעֹה לֵהּ עַד אִמָתַי יְהֵי דֵין לָנָא לְתַקְלָא שַׁלַח יָת גֻבְרַיָא וְיִפְלְחוּן קֳדָם יְיָ אֱלָהֲהוֹן הַעַד כְּעַן לָא יְדַעְתָּ אֲרֵי אֲבֵדַת מִצְרָיִם:
@253 וְאִתּוֹתַב יָת משֶׁה וְיָת אַהֲרֹן לְוָת פַּרְעֹה וַאֲמַר לְהוֹן אֱזִילוּ פְלָחוּ קֳדָם יְיָ אֱלָהֲכוֹן מָן וּמָן דְאָזְלִין:
@254 וַאֲמַר משֶׁה בְּעוּלֵמָנָּא וּבְסָבָנָּא נֵזֵיל בְּבָנָנָא וּבִבְנָתָנָא בְּעָנָנָא וּבְתוֹרָנָא נֵזֵיל אֲרֵי חַגָא קֳדָם יְיָ לָנָא:
@255 וַאֲמַר לְהוֹן יְהֵי כֵן מֵימְרָא דַיְיָ בְּסַעְדְכוֹן כַּד אֲשַּׁלַח יָתְכוֹן וְיָת טַפְלְכוֹן חֲזוֹ אֲרֵי בִישָׁא דְאַתּוּן סְבִירִין לְמֶעְבַּד לָקֳבֵל אַפֵּיכוֹן לְאִסְתַּחָרָא:
@256 לָא כֵן אֱזִילוּ כְעַן גֻבְרַיָא וּפְלָחוּ קֳדָם יְיָ אֲרֵי יָתַהּ אַתּוּן בָּעָן וְתָרִיךְ יָתְהוֹן מִן קֳדָם פַּרְעֹה:
@257 וַאֲמַר יְיָ לְמשֶׁה אֲרֵים יְדָךְ עַל אַרְעָא דְמִצְרָיִם וְיֵתֵי גוֹבָא וְיִסַק עַל אַרְעָא דְמִצְרָיִם וְיֵכוּל יָת כָּל עִסְבָּא דְאַרְעָא יָת כָּל דִי אַשְׁאַר בַּרְדָא:
@258 וַאֲרֵים משֶׁה יָת חֻטְרֵהּ עַל אַרְעָא דְמִצְרַיִם וַיְיָ דַבַּר רוּחַ קִדוּמָא בְּאַרְעָא כָּל יוֹמָא הַהוּא וְכָל לֵילְיָא צַפְרָא הֲוָה וְרוּחַ קִדוּמָא נְטַּל יָת גוֹבָא:
@259 וּסְלֵיק גוֹבָא עַל כָּל אַרְעָא דְמִצְרַיִם וּשְׁרָא בְּכָל תְּחוּם מִצְרָיִם תַּקִיף לַחֲדָא קֳדָמוֹהִי לָא הֲוָה כֵן גוֹבָא דִכְוָתֵהּ וּבַתְרוֹהִי לָא יְהֵי כֵן:
@260 וַחֲפָא יָת עֵין שִׁמְשָׁא דְכָל אַרְעָא וַחֲשׁוֹכַת אַרְעָא וַאֲכַל יָת כָּל עֶסְבָּא דְאַרְעָא וְיָת כָּל פֵּירֵי אִילָנָא דִי אַשְׁאַר בַּרְדָא וְלָא אִשְׁתָּאַר כָּל יָרוֹקָא בְּאִילָנָא וּבְעֶסְבָּא דְחַקְלָא בְּכָל אַרְעָא דְמִצְרָיִם:
@261 וְאוֹחִי פַרְעֹה לְמִקְרֵי לְמשֶׁה וּלְאַהֲרֹן וַאֲמַר חָבִית קֳדָם יְיָ אֱלָהֲכוֹן וּלְכוֹן:
@262 וּכְעַן שְׁבוֹק כְּעַן לְחוֹבִי בְּרַם זִמְנָא הָדָא וְצַלוֹ קָדָם יְיָ אֱלָהֲכוֹן וְיַעְדֵי מִנִי לְחוֹד יָת מוֹתָא הָדֵין:
@263 וּנְפַק מִלְוָת פַּרְעֹה וְצַלִי קֳדָם יְיָ:
@264 וַהֲפַךְ יְיָ רוּחָא מַעַרְבָא תַּקִיף לַחֲדָא וּנְטַל יָת גוֹבָא וּרְמָהִי לְיַמָא דְסוּף לָא אִשְׁתָּאַר גוֹבָא חַד בְּכֹל תְּחוּם מִצְרָיִם:
@265 וְאַתְקֵף יְיָ יָת לִבָּא דְפַרְעֹה וְלָא שַׁלַח יָת בְּנֵי יִשְׂרָאֵל:
@266 וַאֲמַר יְיָ לְמשֶׁה אֲרֵים יְדָךְ עַל צֵית שְׁמַיָא וִיהֵי חֲשׁוֹכָא עַל אַרְעָא דְמִצְרָיִם בָּתַר דְיַעְדֵי קְבֵל לֵילְיָא:
@267 וַאֲרֵים משֶׁה יָת יְדֵהּ עַל צֵית שְׁמַיָא וַהֲוָה חֲשׁוֹךְ קְבֵל בְּכָל אַרְעָא דְמִצְרַיִם תְּלָתָא יוֹמִין:
@268 לָא חֲזוֹ אֱנָשׁ יָת אֲחוֹהִי וְלָא קָמוּ אֱנָשׁ מִתְּחוֹתוֹהִי תְּלָתָא יוֹמִין וּלְכָל בְּנֵי יִשְׂרָאֵל הֲוָה נְהוֹרָא בְּמוֹתְבָנְהוֹן:
@269 וּקְרָא פַרְעֹה לְמשֶׁה וַאֲמַר אֱזִילוּ פְּלָחוּ קֳדָם יְיָ לְחוֹד עָנְכוֹן וְתוֹרְכוֹן שְׁבוּקוּ אַף טַפְלְכוֹן יֵזֵיל עִמְכוֹן:
@270 וַאֲמַר משֶׁה אַף אַתְּ תִּמְסַר בִּידָנָא נִכְסַת קֻדְשִׁין וַעֲלָוָן וְנַעְבֵּד קֳדָם יְיָ אֱלָהָנָא:
@271 וְאַף בְּעִירָנָא יֵזֵיל עִמָנָא לָא תִשְׁתָּאַר מִדַעַם אֲרֵי מִנֵהּ אֲנַחְנָא נָסְבִין לְמִפְלַח קֳדָם יְיָ אֱלָהָנָא וַאֲנַחְנָא לֵית אֲנַחְנָא יָדְעִין מָה נִפְלַח קֳדָם יְיָ עַד מֵיתָנָא תַּמָן:
@272 וְאַתְקֵיף יְיָ יָת לִבָּא דְפַרְעֹה וְלָא אָבָה לְשַׁלָחוּתְהוֹן:
@273 וַאֲמַר לֵּהּ פַּרְעֹה אִזֵיל מֵעִלָוָי אִסְתַּמַר לָךְ לָא תוֹסִיף לְמֶחֱזֵי אַפַּי אֲרֵי בְּיוֹמָא דְתֶחֱזֵי אַפַּי תְּמוּת:
@274 וַאֲמַר משֶׁה יָאוּת מַלֵילְתָּא לָא אוֹסִיף עוֹד לְמֶחֱזֵי אַפָּיךְ:
@275 וַאֲמַר יְיָ לְמשֶׁה עוֹד מַכְתַּשׁ חַד אַיְתִי עַל פַּרְעֹה וְעַל מִצְרַיִם בָּתַר כֵּן יְשַׁלַח יָתְכוֹן מִכָּא כְּשַׁלָחוּתֵהּ גְמֵירָא תָּרָכָא יְתָרֵךְ יָתְכוֹן מִכָּא:
@276 מַלֵיל כְּעַן קֳדָם עַמָא וּשְׁאִילוּ גְבַר מִן חַבְרֵהּ וְאִתְּתָא מִן חַבְרָתַהּ מָנִין דִכְסַף וּמָנִין דִדְהָב:
@277 וִיהַב יְיָ יָת עַמָא לְרַחֲמִין בְּעֵינֵי מִצְרָיִם אַף גַבְרָא משֶׁה רַב לַחֲדָא בְּאַרְעָא דְמִצְרַיִם בְּעֵינֵי עַבְדֵי פַרְעֹה וּבְעֵינֵי עַמָא:
@278 וַאֲמַר משֶׁה כִּדְנַן אֲמַר יְיָ כְּפַלְגוּת לֵילְיָא אֲנָא מִתְגְלִי בְּגוֹ מִצְרָיִם:
@279 וִימוּת כָּל בּוּכְרָא בְּאַרְעָא דְמִצְרַיִם מִבּוּכְרָא דְפַרְעֹה דְעָתִיד לְמִתַּב עַל כָּרְסֵי מַלְכוּתֵהּ עַד בּוּכְרָא דְאַמְתָא דִי בָּתַר רֵיחְיָא וְכֹל בּוּכְרָא דִבְעִירָא:
@280 וּתְהֵי צְוַחְתָּא רַבָּא בְּכָל אַרְעָא דְמִצְרָיִם דִכְוָתֵהּ לָא הֲוַת וְדִכְוָתֵהּ לָא תוֹסֵף:
@281 וּלְכֹל בְּנֵי יִשְׂרָאֵל לָא יַנְזֵק כַּלְבָּא בְּלִישְׁנֵהּ לְמִנְבַּח לְמֵאֲנָשָׁא וְעַד בְּעִירָא בְּדִיל דְתִדְעוּן דְיַפְרֵישׁ יְיָ בֵּין מִצְרַיִם וּבֵין יִשְׂרָאֵל:
@282 וְיֶחֱתוּן כָּל עַבְדָיךְ אִלֵין לְוָתִי וְיִבְעוֹן מִנִי לְמֵימָר פּוּק אַתְּ וְכָל עַמָא דִי עִמָךְ וּבָתַר כֵּן אֶפּוֹק וּנְפַק מִלְוָת פַּרְעֹה בִּתְקוֹף רְגָז:
@283 וַאֲמַר יְיָ לְמשֶׁה לָא יְקַבֵּל מִנְכוֹן פַּרְעֹה בְּדִיל לְאַסְגָאָה מוֹפְתַי בְּאַרְעָא דְמִצְרָיִם:
@284 וּמשֶׁה וְאַהֲרֹן עֲבָדוּ יָת כָּל מוֹפְתַיָא הָאִלֵין קֳדָם פַּרְעֹה וְתַקַף יְיָ יָת לִבָּא דְפַרְעֹה וְלָא שַׁלַח יָת בְּנֵי יִשְׂרָאֵל מֵאַרְעֵהּ:
@285 וַאֲמַר יְיָ לְמשֶׁה וּלְאַהֲרֹן בְּאַרְעָא דְמִצְרַיִם לְמֵימָר:
@286 יַרְחָא הָדֵין לְכוֹן רֵישׁ יַרְחִין קַדְמַאי הוּא לְכוֹן לְיַרְחֵי שַׁתָּא:
@287 מַלִילוּ עִם כָּל כְּנִשְׁתָּא דְיִשְׂרָאֵל לְמֵימַר בְּעַסְרָא לְיַרְחָא הָדֵין וְיִסְבוּן לְהוֹן גְבַר אִמָר לְבֵית אַבָּא אִמָר לְבֵיתָא:
@288 וְאִם יִזְעֵיר בֵּיתָא מִלְאִתְמְנָאָה עַל אִמְרָא וְיִסַב הוּא וְשֵׁיבָבֵהּ דְקָרִיב לְבֵיתֵהּ בְּמִנְיַן נַפְשָׁתָא גְבַר לְפוּם מֵיכְלֵהּ תִּתְמְנוּן עַל אִמְרָא:
@289 אִמַר שְׁלִים דְכַר בַּר שַׁתֵּהּ יְהֵי לְכוֹן מִן אִמְרַיָא וּמִן עִזַיָא תִּסְבוּן:
@290 וִיהֵי לְכוֹן לְמַטְרָא עַד אַרְבְּעָא עַסְרָא יוֹמָא לְיַרְחָא הָדֵין וְיִכְּסוּן יָתֵהּ כֹּל קְהָלָא כְנִשְׁתָּא דְיִשְׂרָאֵל בֵּין שִׁמְשַּׁיָא:
@291 וְיִסְבוּן מִן דְמָא וְיִתְּנוּן עַל תְּרֵין סִפַּיָא וְעַל שַׁקְפָא עַל בָּתַּיָא דְיֵכְלוּן יָתֵהּ בְּהוֹן:
@292 וְיֵכְלוּן יָת בִּסְרָא בְּלֵילָא הַהוּא טְּוֵי נוּר וּפַטִיר עַל מְרָרִין יֵכְלֻנֵהּ:
@293 לָא תֵיכְלוּן מִנֵהּ כַּד חַי וְאַף לָא בַשָׁלָא מְבֻשָׁל בְּמַיָא אֱלָהֵן טְוֵי נוּר רֵישֵׁיה עַל כְּרָעוֹהִי וְעַל גַוֵהּ:
@294 וְלָא תַשְׁאֲרוּן מִנֵהּ עַד צַפְרָא וּדְיִשְׁתָּאַר מִנֵהּ עַד צַפְרָא בְּנוּרָא תוֹקְדוּן:
@295 וּכְדֵין תֵּיכְלוּן יָתֵהּ חַרְצֵיכוֹן יְהוֹן אֲסִירִין מְסָנֵיכוֹן בְּרִגְלֵיכוֹן וְחוּטְרֵיכוֹן בִּידֵיכוֹן וְתֵיכְלוּן יָתֵהּ בִּבְהִילוּ פִּסְחָא הוּא קֳדָם יְיָ:
@296 וְאִתְגְלֵיתִי בְאַרְעָא דְמִצְרַיִם בְּלֵילְיָא הָדֵין וְאֶקְטוֹל כָּל בּוּכְרָא בְּאַרְעָא דְמִצְרַיִם מֵאֲנָשָׁא וְעַד בְּעִירָא וּבְכָל טַעֲוַת מִצְרַיִם אַעְבֵּד דִינִין אֲנָא יְיָ:
@297 וִיהֵי דְמָא לְכוֹן לְאָת עַל בָּתַּיָא דִי אַתּוּן תַּמָן וְאֶחֱזֵי יָת דְמָא וְאֵיחוֹס עֲלֵיכוֹן וְלָא יְהֵי בְכוֹן מוֹתָא לְחַבָּלָא בְּמִקְטְלִי בְּאַרְעָא דְמִצְרָיִם:
@298 וִיהֵי יוֹמָא הָדֵין לְכוֹן לְדוּכְרָנָא וּתְחַגוּן יָתֵהּ חַגָא קָדָם יְיָ לְדָרֵיכוֹן קְיָם עָלָם תְּחַגֻנֵהּ:
@299 שִׁבְעַת יוֹמִין פַּטִיר תֵּיכְלוּן בְּרַם בְּיוֹמָא קַדְמָאָה תְּבַטְלוּן חֲמִיעַ מִבָּתֵּיכוֹן אֲרֵי כָּל דְיֵכוּל חֲמִיעַ וְיִשְׁתֵּצֵי אֱנָשָׁא הַהוּא מִיִשְׂרָאֵל מִיוֹמָא קַדְמָאָה עַד יוֹמָא שְׁבִיעָאָה:
@300 וּבְיוֹמָא קַדְמָאָה מְעָרַע קַדִישׁ וּבְיוֹמָא שְׁבִיעָאָה מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִיבִידָא לָא יִתְעֲבֵד בְּהוֹן בְּרַם דִי מִתְאֲכֵל לְכָל נְפַשׁ הוּא בִלְחוֹדוֹהִי יִתְעֲבֵד לְכוֹן:
@301 וְתִטְרוּן יָת פַּטִירָא אֲרֵי בִּכְרַן יוֹמָא הָדֵין אַפֵּיקִית יָת חֵילֵיכוֹן מֵאַרְעָא דְמִצְרָיִם וְתִטְּרוּן יָת יוֹמָא הָדֵין לְדָרֵיכוֹן קְיָם עָלָם:
@302 בְּנִיסָן בְּאַרְבְּעָא עַסְרָא יוֹמָא לְיַרְחָא בְּרַמְשָׁא תֵּיכְלוּן פַּטִירָא עַד יוֹמָא עֶסְרִין וְחַד לְיַרְחָא בְּרַמְשָׁא:
@303 שִׁבְעַת יוֹמִין חֲמִיר לָא יִשְׁתְּכַח בְּבָתֵּיכוֹן אֲרֵי כָּל דְיֵכוּל מַחְמְעָא וְיִשְׁתֵּצֵי אֱנָשָׁא הַהוּא מִכְּנִשְׁתָּא דְיִשְׂרָאֵל בְּגִיוֹרָא וּבְיַצִיבָא דְאַרְעָא:
@304 כָּל מַחְמְעָא לָא תֵיכְלוּן בְּכֹל מוֹתְבָנֵיכוֹן תֵּיכְלוּן פַּטִירָא:
@305 וּקְרָא משֶׁה לְכָל סָבֵי יִשְׂרָאֵל וַאֲמַר לְהוֹן אִתְנְגִידוּ וְסִיבוּ לְכוֹן (מִן בְּנֵי) עָנָא לְזַרְעֲיָתְכוֹן וְכוּסוּ פִסְחָא:
@306 וְתִסְבּוּן אֱסָרַת אֵזוֹבָא וְתִטְבְּלוּן בִּדְמָא דִבְמָנָא וְתַדוּן לְשַׁקְפָא וְלִתְרֵין סִפַּיָא מִן דְמָא דִבְמָנָא וְאַתּוּן לָא תִפְּקוּן אֱנַשׁ מִתְּרַע בֵּיתֵהּ עַד צַפְרָא:
@307 וְיִתְגְלֵי יְיָ לְמִמְחֵי יָת מִצְרַיִם וְיֶחֱזֵי יָת דְמָא עַל שַׁקְפָא וְעַל תְּרֵין סִפַּיָא וְיֵחוֹס יְיָ עַל תַּרְעָא וְלָא יִשְׁבּוֹק לְחַבָּלָא לְמֵיעַל לְבָתֵּיכוֹן לְמִמְחֵי:
@308 וְתִטְרוּן יָת פִּתְגָמָא הָדֵין לִקְיָם לָךְ וְלִבְנָיךְ עַד עָלָם:
@309 וִיהֵי אֲרֵי תֵעֲלוּן לְאַרְעָא דְיִתֵּן יְיָ לְכוֹן כְּמָא דִי מַלִיל וְתִטְּרוּן יָת פָּלְחָנָא הָדֵין:
@310 וִיהֵי אֲרֵי יֵימְרוּן לְכוֹן בְּנֵיכוֹן מָא פָּלְחָנָא הָדֵין לְכוֹן:
@311 וְתֵימְרוּן דַבַּח חֲיָס הוּא קֳדָם יְיָ דִי חָס עַל בָּתֵּי בְנֵי יִשְׂרָאֵל בְּמִצְרַיִם כַּד הֲוָה מָחֵי יָת מִצְרָאֵי וְיָת בָּתָּנָא שֵׁזִיב וּכְרַע עַמָא וּסְגִידוּ:
@312 וַאֲזָלוּ וַעֲבָדוּ בְּנֵי יִשְׂרָאֵל כְּמָא דְפַקִיד יְיָ יָת משֶׁה וְאַהֲרֹן כֵּן עֲבָדוּ:
@313 וַהֲוָה בְּפַלְגוּת לֵילְיָא וַיְיָ קְטַל כָּל בּוּכְרָא בְּאַרְעָא דְמִצְרַיִם מִבּוּכְרָא דְפַרְעֹה דְעָתִיד לְמִתַּב עַל כָּרְסֵי מַלְכוּתֵהּ עַד בּוּכְרָא דְשִׁבְיָא דִי בְּבֵית אֲסִירֵי וְכֹל בּוּכְרָא דִבְעִירָא:
@314 וְקָם פַּרְעֹה לֵילְיָא הוּא וְכָל עַבְדוֹהִי וְכָל מִצְרַיִם וַהֲוַת צְוַחְתָּא רַבְּתָא בְּמִצְרָיִם אֲרֵי לֵית בֵּיתָא דִי לֵית הֲוָה בֵהּ תַּמָן מֵתָא:
@315 וּקְרָא לְמשֶׁה וּלְאַהֲרֹן לֵילְיָא וַאֲמַר קוּמוּ פּוּקוּ מִגוֹ עַמִי אַף אַתּוּן אַף בְּנֵי יִשְׂרָאֵל וֶאֱזִילוּ פְלָחוּ קֳדָם יְיָ כְּמָא דִהֲוֵתוּן אָמְרִין:
@316 אַף עַנְכוֹן אַף תּוֹרְכוֹן דְבָרוּ כְּמָא דִי מַלֵלְתֻּן וֶאֱזִילוּ וְצַלוֹ אַף עָלָי:
@317 וּתְקֵיפַת מִצְרַיִם עַל עַמָא לְאוֹחָאָה לְשַׁלָחוּתְהוֹן מִן אַרְעָא אֲרֵי אֲמָרוּ כֻּלָנָא מָיְתִין:
@318 וּנְטַל עַמָא יָת לַיְשֵׁיהוֹן עַד לָא חֲמָע מוֹתַר אַצְוָתְהוֹן צְרִיר בִּלְבָשֵׁהוֹן עַל כַּתְפֵּיהוֹן:
@319 וּבְנֵי יִשְׂרָאֵל עֲבָדוּ כְּפִתְגָמָא דְמשֶׁה וּשְׁאִילוּ מִמִצְרַיִם מָנִין דִכְסַף וּמָנִין דִדְהַב וּלְבוּשִׁין:
@320 וַייָ יְהַב יָת עַמָא לְרַחֲמִין בְּעֵינֵי מִצְרַיִם וּשְׁאֵילִנוּן וְרוֹקִינוּ יָת מִצְרַיִם:
@321 וּנְטָלוּ בְנֵי יִשְׂרָאֵל מֵרַעְמְסֵס לְסֻכּוֹת כְּשִׁתְּ מֵאָה אַלְפִין רִגְלָאִין גֻבְרַיָא בַּר מִטַפְלָא:
@322 וְאַף נוּכְרָאִין סַגִיאִין סְלִיקוּ עִמְהוֹן וְעָנָא וְתוֹרִין בְּעִירָא סַגִי לַחֲדָא:
@323 וַאֲפוֹ יָת לַיְשָׁא דִי אַפִּיקוּ מִמִצְרַיִם גְרִיצָן פַּטִירָן אֲרֵי לָא חֲמָע אֲרֵי אִתָּרָכוּ מִמִצְרַיִם וְלָא יָכִילוּ לְאִתְעַכָּבָא וְאַף זְוָדִין לָא עֲבָדוּ לְהוֹן:
@324 וּמוֹתַב בְּנֵי יִשְׂרָאֵל דִי יְתִיבוּ בְּמִצְרָיִם אַרְבַּע מְאָה וּתְלָתִין שְׁנִין:
@325 וַהֲוָה מִסוֹף אַרְבַּע מְאָה וּתְלָתִין שְׁנִין וַהֲוָה בִּכְרַן יוֹמָא הָדֵין נְפָקוּ כָּל חֵילַיָא דַיְיָ מֵאַרְעָא דְמִצְרָיִם:
@326 לֵילֵי נְטִּיר הוּא קֳדָם יְיָ לְאַפָּקוּתְהוֹן מֵאַרְעָא דְמִצְרַיִם הוּא לֵילְיָא הָדֵין קֳדָם יְיָ נְטִירִין לְכָל בְּנֵי יִשְׂרָאֵל לְדָרֵיהוֹן:
@327 וַאֲמַר יְיָ לְמשֶׁה וּלְאַהֲרֹן דָא גְזֵירַת פִּסְחָא כָּל בַּר יִשְׂרָאֵל דְיִשְׁתַּמַד לָא יֵכוּל בֵּהּ:
@328 וְכָל עָבֵד גְבַר זְבִינֵי כַסְפָּא וְתִגְזַר יָתֵהּ בְּכֵן יֵכוּל בֵּהּ:
@329 תּוֹתָבָא וַאֲגִירָא לָא יֵכוּל בֵּהּ:
@330 בַּחֲבוּרָא חֲדָא יִתְאָכֵל לָא תַפֵּיק מִן בֵּיתָא מִן בִּסְרָא לְבָרָא וְגַרְמָא לָא תִתְבְּרוּן בֵּהּ:
@331 כָּל כְּנִשְׁתָּא דְיִשְׂרָאֵל יַעְבְדוּן יָתֵהּ:
@332 וַאֲרֵי יִתְגַיַר עִמָךְ גִיוֹרָא וְיַעְבֵּד פִּסְחָא קֳדָם יְיָ מִגְזַר לֵהּ כָּל דְכוּרָא וּבְכֵן יִקְרַב לְמֶעְבְּדֵהּ וִיהֵי כְּיַצִיבָא דְאַרְעָא וְכָל עַרְלָא לָא יֵכוּל בֵּהּ:
@333 אוֹרַיְתָא חֲדָא יְהֵא לְיַצִיבָא וּלְגִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן:
@334 וַעֲבָדוּ כָּל בְּנֵי יִשְׂרָאֵל כְּמָא דִי פַקִיד יְיָ יָת משֶׁה וְיָת אַהֲרֹן כֵּן עֲבָדוּ:
@335 וַהֲוָה בִּכְרַן יוֹמָא הָדֵין אַפֵּיק יְיָ יָת בְּנֵי יִשְׂרָאֵל מֵאַרְעָא דְמִצְרַיִם עַל חֵילֵיהוֹן:
@336 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@337 אַקְדֵשׁ קֳדָמַי כָּל בּוּכְרָא פָּתַח כָּל וַלְדָא בִּבְנֵי יִשְׂרָאֵל בֶּאֱנָשָׁא וּבִבְעִירָא דִילִי הוּא:
@338 וַאֲמַר משֶׁה לְעַמָא הֲווֹ דְכִירִין יָת יוֹמָא הָדֵין דִי נְפַקְתּוּן מִמִצְרַיִם מִבֵּית עַבְדוּתָא אֲרֵי בִּתְקוֹף יְדָא אַפֵּיק יְיָ יָתְכוֹן מִכָּא וְלָא יִתְאֲכֵל חֲמִיעַ:
@339 יוֹמָא דֵין אַתּוּן נָפְקִין בְּיַרְחָא דְאַבִּיבָא:
@340 וִיהֵי אֲרֵי יָעֵלִנָךְ יְיָ לְאַרְעָא דִכְנַעֲנָאֵי וְחִתָּאֵי וֶאֱמוֹרָאֵי וְחִוָאֵי וִיבוּסָאֵי דִי קַיִים לַאֲבָהָתָךְ לְמִתַּן לָךְ אַרְעָא עַבְדָא חֲלָב וּדְבָשׁ וְתִפְלַח יָת פָּלְחָנָא הָדָא בְּיַרְחָא הָדֵין:
@341 שִׁבְעָה יוֹמִין תֵּיכוּל פַּטִירָא וּבְיוֹמָא שְׁבִיעָאָה חַגָא קֳדָם יְיָ:
@342 פַּטִיר יִתְאֲכֵל יָת שִׁבְעַת יוֹמִין וְלָא יִתְחֲזֵי לָךְ חֲמִיעַ וְלָא יִתְחֲזֵי לָךְ חֲמִיר בְּכָל תְּחוּמָךְ:
@343 וּתְחַוֵי לִבְנָךְ בְּיוֹמָא הַהוּא לְמֵימָר בְּדִיל דֵין עֲבַד יְיָ לִי בְּמִפְּקִי מִמִצְרָיִם:
@344 וִיהֵי לָךְ לְאָת עַל יְדָךְ וּלְדָכְרָנָא בֵּין עֵינָיךְ בְּדִיל תְּהֵי אוֹרַיְתָא דַיְיָ בְּפוּמָךְ אֲרֵי בִּידָא תַקִיפָא אַפְּקָךְ יְיָ מִמִצְרָיִם:
@345 וְתִטַּר יָת קְיָמָא הָדָא לְזִמְנַהּ מִזְמַן לִזְמָן:
@346 וִיהֵי אֲרֵי יָעֵלִנָךְ יְיָ לְאַרְעָא דִכְנַעֲנָאֵי כְּמָא דִי קַיִים לָךְ וְלַאֲבָהָתָךְ וְיִתְּנִנַהּ לָךְ:
@347 וְתַעְבַּר כָּל פָּתַח וַלְדָא קֳדָם יְיָ וְכָל פָּתַח וְלַד בְּעִירָא דִי יְהֵי לָךְ דִכְרִין תַּקְדֵשׁ קֳדָם יְיָ:
@348 וְכָל פָּתַח (בּוּכְרָא) דַחֲמָרָא תִּפְרוֹק בְּאִמְרָא וְאִם לָא תִפְרוֹק וְתִנְקְפֵהּ וְכָל בּוּכְרָא דַאֲנָשָׁא בִּבְנָיךְ תִּפְרוֹק:
@349 וִיהֵי אֲרֵי יִשְׁאֲלִנָךְ בְּנָךְ מְחָר לְמֵימַר מָא דָא וְתֵימַר לֵהּ בִּתְקוֹף יְדָא אַפְּקָנָא יְיָ מִמִצְרַיִם מִבֵּית עַבְדוּתָא:
@350 וַהֲוָה אֲרֵי אַקְשֵׁי פַרְעֹה לְשַׁלָחוּתָנָא וּקְטַל יְיָ כָּל בּוּכְרָא בְּאַרְעָא דְמִצְרַיִם מִבּוּכְרָא דַאֲנָשָׁא וְעַד בּוּכְרָא דִבְעִירָא עַל כֵּן אֲנָא דָבַח קֳדָם יְיָ כָּל פָּתַח וַלְדָא דִכְרִין וְכָל בּוּכְרָא דִבְנַי אֶפְרוֹק:
@351 וִיהֵי לְאָת עַל יְדָךְ וְלִתְפִלִין בֵּין עֵינָיךְ אֲרֵי בִּתְקוֹף יְדָא אַפְּקָנָא יְיָ מִמִצְרָיִם: ססס:
@352 וַהֲוָה כַּד שַׁלַח פַּרְעֹה יָת עַמָא וְלָא דַבָּרִינוּן יְיָ אֹרַח אַרְעָא פְלִשְׁתָּאֵי אֲרֵי קָרִיבָא הוּא אֲרֵי אֲמַר יְיָ דִילְמָא יְזוּעוּן עַמָא בְּמֶחֱזֵיהוֹן קְרָבָא וִיתוּבוּן לְמִצְרָיִם:
@353 וְאַסְחַר יְיָ יָת עַמָא אֹרַח מַדְבְּרָא יַמָא דְסוּף וּמְזָרְזִין סְלִיקוּ בְּנֵי יִשְׂרָאֵל מֵאַרְעָא דְמִצְרָיִם:
@354 וְאַסִיק משֶׁה יָת גַרְמֵי יוֹסֵף עִמֵהּ אֲרֵי אוֹמָאָה אוֹמִי יָת בְּנֵי יִשְׂרָאֵל לְמֵימָר מִדְכַּר דְכִיר יְיָ יָתְכוֹן וְתַסְקוּן יָת גַרְמַי מִכָּא עִמְכוֹן:
@355 וּנְטָלוּ מִסֻכּוֹת וּשְׁרוֹ בְאֵתָם בִּסְטַר מַדְבְּרָא:
@356 וַיְיָ מְדַבַּר קָדָמֵיהוֹן בִּימָמָא בְּעַמוּדָא דַעֲנָנָא לְדַבָּרוּתְהוֹן בְּאוֹרְחָא וְלֵילְיָא בְּעַמוּדָא דְאֶשָׁתָא לְאַנְהָרָא לְהוֹן לְמֵיזַל בִּימָמָא וּבְלֵילְיָא:
@357 לָא יַעֲדֵי עַמוּדָא דַעֲנָנָא בִּימָמָא וְאַף לָא עַמוּדָא דְאֶשָׁתָא בְּלֵילְיָא קֳדָם עַמָא:
@358 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@359 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וִיתוּבּוּן וְיִשְׁרוּן קֳדָם פּוּם חִירָתָא בֵּין מִגְדוֹל וּבֵין יַמָא קֳדָם בְּעֵיל צְפוֹן לְקִבְלֵהּ תִּשְׁרוּן עַל יַמָא:
@360 וְיֵימַר פַּרְעֹה עַל בְּנֵי יִשְׂרָאֵל מְעַרְבְּלִין אִנוּן בְּאַרְעָא אֲחַד עֲלֵיהוֹן מַדְבְּרָא:
@361 וְאַתְקֵף יָת לִבָּא דְפַרְעֹה וְיִרְדַף בַּתְרֵיהוֹן וְאֶתְיַקַר בְּפַרְעֹה וּבְכָל מַשִׁרְיָתֵהּ וְיִדְעוּן מִצְרָאֵי אֲרֵי אֲנָא יְיָ וַעֲבָדוּ כֵן:
@362 וְאִתְחַוָא לְמַלְכָּא דְמִצְרַיִם אֲרֵי אֲזַל עַמָא וְאִתְהֲפִיךְ לִבָּא דְפַרְעֹה וְעַבְדוֹהִי לְעַמָא וַאֲמָרוּ מָא דָא עֲבַדְנָא אֲרֵי שַׁלַחְנָא יָת יִשְׂרָאֵל מִפָּלְחָנָנָא:
@363 וְטַקִיס יָת רְתִכֵּהּ וְיָת עַמֵהּ דַבַּר עִמֵהּ:
@364 וּדְבַר שִׁתְּ מְאָה רְתִכִּין בְּחִירָן וְכֹל רְתִכֵּי מִצְרָאֵי וְגִבָּרִין מְמַנָן עַל כֻּלְהוֹן:
@365 וְתַקִיף יְיָ יָת לִבָּא דְפַרְעֹה מַלְכָּא דְמִצְרַיִם וּרְדַף בָּתַר בְּנֵי יִשְׂרָאֵל וּבְנֵי יִשְׂרָאֵל נְפָקוּ בְּרֵישׁ גְלִי:
@366 וּרְדָפוּ מִצְרָאֵי בַּתְרֵיהוֹן וְאַדְבִּיקוּ יָתְהוֹן כַּד שָׁרָן עַל יַמָא כָּל סוּסָוַת רְתִכֵּי פַרְעֹה וּפָרָשׁוֹהִי וּמַשִׁרְיָתֵהּ עַל פּוּם חִירָתָא קֳדָם בְּעֵיל צְפוֹן:
@367 וּפַרְעֹה קְרֵיב וּזְקָפוּ בְנֵי יִשְׂרָאֵל יָת עֵינֵיהוֹן וְהָא מִצְרָאֵי נַטְלִין בַּתְרֵיהוֹן וּדְחִילוּ לַחֲדָא וּזְעִיקוּ בְּנֵי יִשְׂרָאֵל קֳדָם יְיָ:
@368 וַאֲמָרוּ לְמשֶׁה הֲמִדְלֵית קְבָרִין בְּמִצְרַיִם דְבַרְתָּנָא לִמְמַת בְּמַדְבְּרָא מָא דָא עֲבַדְתָּא לָנָא לְאַפָּקוּתָנָא מִמִצְרָיִם:
@369 הֲלָא דֵין פִּתְגָמָא דִי מַלֵלְנָא עִמָךְ בְמִצְרַיִם לְמֵימַר שְׁבוֹק מִנָנָא וְנִפְלַח יָת מִצְרָאֵי אֲרֵי טַב לָנָא דְנִפְלַח יָת מִצְרָאֵי מִדִנְמוּת בְּמַדְבְּרָא:
@370 וַאֲמַר משֶׁה לְעַמָא לָא תִדְחֲלוּן אִתְעַתָּדוּ וַחֲזוֹ יָת פּוּרְקָנָא דַיְיָ דְיַעְבֵּד לְכוֹן יוֹמָא דֵין אֲרֵי כְּמָא דִחֲזֵיתוּן יַת מִצְרָאֵי יוֹמָא דֵין לָא תוֹסְפוּן לְמֶחֱזֵיהוֹן עוֹד עַד עָלְמָא:
@371 יְיָ יְגִיחַ לְכוֹן קְרָב וְאַתּוּן תִּשְׁתְּקוּן:
@372 וַאֲמַר יְיָ לְמשֶׁה קַבֵּלִית צְלוֹתָךְ מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְיִטְלוּן:
@373 וְאַתְּ טוֹל יָת חֻטְרָךְ וַאֲרֵים יָת יְדָךְ עַל יַמָא וּבְזָעוֹהִי וְיֵעֲלוּן בְּנֵי יִשְׂרָאֵל בְּגוֹ יַמָא בְּיַבֶּשְׁתָּא:
@374 וַאֲנָא הָא אֲנָא מְתַקֵף יָת לִבָּא דְמִצְרָאֵי וְיֵעֲלוּן בַּתְרֵיהוֹן וְאֶתְיַקַר בְּפַרְעֹה וּבְכָל מַשִׁרְיָתֵהּ בִּרְתִכּוֹהִי וּבְפָרָשׁוֹהִי:
@375 וְיִדְּעוּן מִצְרָאֵי אֲרֵי אֲנָא יְיָ בְּאִתְיַקָרוּתִי בְּפַרְעֹה בִּרְתִכּוֹהִי וּבְפָרָשׁוֹהִי:
@376 וּנְטַל מַלְאֲכָא דַיְיָ דִמְדַבַּר קֳדָם מַשְׁרִיתָא דְיִשְׂרָאֵל וַאֲתָא מִבַּתְרֵיהוֹן וּנְטַל עַמּוּדָא דַעֲנָנָא מִן קֳדָמֵיהוֹן וּשְׁרָא מִבַּתְרֵיהוֹן:
@377 וְעַל בֵּין מַשְׁרִיתָא דְמִצְרָאֵי וּבֵין מַשְׁרִיתָא דְיִשְׂרָאֵל וַהֲוָה עֲנָנָא וְקַבְלָא לְמִצְרָאֵי וּלְיִשְׂרָאֵל נְהַר כָּל לֵילְיָא וְלָא אִתְקְרִיבוּ דֵין לְוָת דֵין כָּל לֵילְיָא:
@378 וַאֲרֵים משֶׁה יָת יְדֵהּ עַל יַמָּא וְדַבַּר יְיָ יָת יַמָּא בְּרוּחַ קִדוּמָא תַקִיף כָּל לֵילְיָא וְשַׁוִי יָת יַמָּא לְיַבֶּשְׁתָּא וְאִתְבְּזָעוּ מַיָּא:
@379 וְעַלוּ בְנֵי יִשְׂרָאֵל בְּגוֹ יַמָא בְּיַבֶּשְׁתָּא וּמַיָּא לְהוֹן שׁוּרִין מִיַּמִינֵהוֹן וּמִסְמָאלֵהוֹן:
@380 וּרְדָפוּ מִצְרָאֵי וְעַלוּ בַתְרֵיהוֹן כֹּל סוּסָוַת פַּרְעֹה רְתִכּוֹהִי וּפָרָשׁוֹהִי לְגוֹ יַמָא:
@381 וַהֲוָה בְּמַטְרַת צַפְרָא וְאִסְתְּכֵי יְיָ לְמַשְׁרִיתָא דְמִצְרָאֵי בְּעַמוּדָא דְאֶשָׁתָא וַעֲנָנָא וְשַׁגִישׁ יָת מַשְׁרִיתָא דְמִצְרָאֵי:
@382 וְאַעְדִי יָת גַלְגַלֵי רְתִכּוֹהִי וּמְדַבְּרִין לְהוֹן בִּתְקוֹף וַאֲמַר מִצְרָאֵי נֵעִירוֹק מִן קֳדָם יִשְׂרָאֵל אֲרֵי דָא הִיא גְבֻרְתָּא דַיְיָ דַעֲבֵד לְהוֹן קְרָבִין בְּמִצְרָיִם:
@383 וַאֲמַר יְיָ לְמשֶׁה אֲרֵים יָת יְדָךְ עַל יַמָא וִיתוּבוּן מַיָא עַל מִצְרָאֵי עַל רְתִכֵּיהוֹן וְעַל פָּרָשֵׁיהוֹן:
@384 וַאֲרֵים משֶׁה יָת יְדֵהּ עַל יַמָא וְתָב יַמָא לְעִדַן צַפְרָא לְתָקְפֵּהּ וּמִצְרָאֵי עָרְקִין לְקַדָמוּתֵהּ וְשַׁנִיק יְיָ יָת מִצְרָאֵי בְּגוֹ יַמָא:
@385 וְתָבוּ מַיָא וַחֲפוֹ יָת רְתִכַּיָא וְיָת פָּרָשַׁיָא לְכֹל מַשִׁרְיַת פַּרְעֹה דְעַלוּ בַתְרֵיהוֹן בְּיַמָא לָא אִשְׁתָּאַר בְּהוֹן עַד חָד:
@386 וּבְנֵי יִשְׂרָאֵל הַלִיכוּ בְיַבֶּשְׁתָּא בְּגוֹ יַמָא וּמַיָא לְהוֹן שׁוּרִין מִיַמִינֵהוֹן וּמִסְמָאלֵהוֹן:
@387 וּפְרַק יְיָ בְּיוֹמָא הַהוּא יָת יִשְׂרָאֵל מִידָא דְמִצְרָאֵי וַחֲזוֹ יִשְׂרָאֵל יָת מִצְרָאֵי מַיְתִין עַל כֵּיף יַמָא:
@388 וַחֲזָא יִשְׂרָאֵל יָת גְבוּרְתָּא יְדָא רַבְּתָא דִי עֲבַד יְיָ בְּמִצְרַיִם וּדְחִילוּ עַמָא מִן קֳדָם יְיָ וְהֵמִינוּ בְּמֵימְרָא דַיְיָ וּבִנְבִיאוּת משֶׁה עַבְדֵהּ:
@389 בְּכֵן שַׁבַּח משֶׁה וּבְנֵי יִשְׂרָאֵל יָת תִּשְׁבַּחְתָּא הָדָא קֳדָם יְיָ וַאֲמָרוּ לְמֵימָר נְשַׁבַּח וְנוֹדֶה קָדָם יְיָ אֲרֵי אִתְגָאֵי עַל גֵוְתָנַיָא וְגֵאוּתָא דִילֵהּ הִיא סוּסְיָא וְרָכְבֵהּ רְמָא בְיַמָא:
@390 תָּקְפִּי וְתִשְׁבַּחְתִּי דְחִילָא יְיָ וַאֲמַר בְּמֵימְרֵהּ וַהֲוָה לִי לְפָרָק דֵין אֱלָהַי וְאֶבְנֵי לֵהּ מַקְדְשָׁא אֱלָהָא דַאֲבָהָתַי וְאֶפְלַח קֳדָמוֹהִי:
@391 יְיָ מָרֵי נִצְחָן קְרָבַיָא יְיָ שְׁמֵהּ:
@392 רְתִכֵּי פַּרְעֹה וּמַשִׁרְיָתֵהּ שְׁדִי בְיַמָא וּשְׁפַר גִבָּרוֹהִי אִטְבָּעוּ בְּיַמָא דְסוּף:
@393 תְּהוֹמַיָא חֲפוֹ עֲלֵיהוֹן נְחָתוּ לְעוּמְקַיָא כְּאַבְנָא:
@394 יַמִינָךְ יְיָ אַדִיר בְּחֵילָא יַמִינָךְ יְיָ תְּבָּרַת סָנְאָה:
@395 וּבִסְגֵי תָקְפָּךְ תְּבַרְתָּנוּן לִדְקָמוּ עַל עַמָךְ שַׁלַחְתָּ רוּגְזָךְ שֵׁיצִנוּן כְּנוּרָא לְקַשָׁא:
@396 וּבְמֵימַר פּוּמָךְ חַכִּימוּ מַיָא קָמוּ כְשׁוּר אֲזָלַיָא קָפוּ תְהוֹמִין בְּלִבָּא דְיַמָא:
@397 דַהֲוָה אֲמַר סָנְאָה אֶרְדוֹף אַדְבֵּק אֲפַלֵג בִּזְתָא תִּשְׂבַּע מִנְהוֹן נַפְשִׁי אֶשְׁלוֹף חַרְבִּי תְּשֵׁיצִינוּן יְדִי:
@398 אֲמַרְתָּ בְּמֵימְרָךְ חֲפָא עֲלֵיהוֹן יַמָא אִשְׁתְּקָעוּ כַּאֲבָרָא בְּמַיִן תַּקִיפִין:
@399 לֵית בַּר מִנָךְ דְאַתְּ הוּא אֱלָהָא יְיָ לֵית בַּר מִנָךְ אֱלָהָא אַתְּ אַדִיר בְּקוּדְשָׁא דָחֵל תֻּשְׁבְּחָן עָבֵד פָּרִישָׁן:
@400 אֲרֵמְתָּ יַמִינָךְ בְּלַעְתְּנוּן אַרְעָא:
@401 דַבַּרְהִי בְטַבְוָתָךְ עַמָא דְנַן דִפְרָקְתָּ סוֹבַרְהִי בְתָקְפָּךְ לְדִירָא דְקֻדְשָׁךְ:
@402 שְׁמָעוּ עַמְמַיָא וְזָעוּ דַחֲלָא אַחֲדָתְנוּן דַהֲווֹ יָתְבִין בִּפְלָשֶׁת:
@403 בְּכֵן אִתְבְּהִילוּ רַבְרְבֵי אֱדוֹם תַּקִיפֵי מוֹאָב אֲחַדָתְנוּן רְתֵיתָא אִתְבָּרוּ כֹּל דַהֲווֹ יָתְבִין בִּכְנָעַן:
@404 תַּפִּיל עֲלֵיהוֹן אֵימְתָא וְדַחַלְתָּא בִּסְגֵי תָקְפָּךְ יִשְׁתְּקוּן כְּאַבְנָא עַד דְיֵעִבַּר עַמָךְ יְיָ יָת אַרְנוֹנָא עַד דְיֵעִבַּר עַמָא דְנַן דִי פְרַקְתָּא יָת יַרְדְנָא:
@405 תָּעֵלִנוּן וְתַשְׁרִינוּן בְּטוּרָא דְאַחְסַנְתָּךְ אֲתַר מְתַקֵן לְבֵית שְׁכִנְתָּךְ אַתְקֵנְתָּא יְיָ מַקְדְשָׁא יְיָ אַתְקְנוֹהִי יְדָיךְ:
@406 יְיָ מַלְכוּתֵהּ קָאֵם לְעָלַם וּלְעָלְמֵי עָלְמַיָא:
@407 אֲרֵי עַלוּ סוּסָוַת פַּרְעֹה בִּרְתִכּוֹהִי וּבְפָרָשׁוֹהִי בְּיַמָא וַאֲתֵיב יְיָ עֲלֵיהוֹן יָת מֵי יַמָא וּבְנֵי יִשְׂרָאֵל הַלִיכוּ בְיַבֶּשְׁתָּא בְּגוֹ יַמָא:
@408 וּנְסֵיבַת מִרְיָם נְבִיאֲתָא אֲחָתֵהּ דְאַהֲרֹן יָת תֻּפָּא בִּידַהּ וּנְפָקוּ כָל נְשַׁיָא בַּתְרָהָא בְּתֻפִּין וּבְחִנְגִין:
@409 וּמְעַנְיָא לְהוֹן מִרְיָם שַׁבָּחוּ וְאוֹדוּ קֳדָם יְיָ אֲרֵי אִתְגָאֵי עַל גֵוְתָנַיָא וְגֵאוּתָא דִילֵהּ הִיא סוּסְיָא וְרָכְבֵהּ רְמָא בְיַמָא:
@410 וְאַטֵּל משֶׁה יָת יִשְׂרָאֵל מִיַמָא דְסוּף וּנְפָקוּ לְמַדְבְּרָא דְחַגְרָא וַאֲזָלוּ תְלָתָא יוֹמִין בְּמַדְבְּרָא וְלָא אַשְׁכָּחוּ מַיָא:
@411 וַאֲתוֹ לְמָרָה וְלָא יְכִילוּ לְמִשְׁתֵּי מַיָא מִמָרָה אֲרֵי מְרִירִין אִנוּן עַל כֵּן קְרָא שְׁמַהּ מָרָה:
@412 וְאִתְרָעָמוּ עַמָא עַל משֶׁה לְמֵימַר מָה נִשְׁתֵּי:
@413 וְצַלִי קֳדָם יְיָ וְאַלְפֵהּ יְיָ אָעָא וּרְמָא לְמַיָא וּבַסִימוּ מַיָא תַּמָן גְזַר לֵהּ קְיָם וְדִין וְתַמָן נַסְיֵהּ:
@414 וַאֲמַר אִם קַבָּלָא תְקַבֵּל לְמֵימְרָא דַיְיָ אֱלָהָךְ וּדְכָשַׁר קֳדָמוֹהִי תַעְבֵּד וְתַצֵית לִפִקוּדוֹהִי וְתִטַר כָּל קְיָמוֹהִי כָּל מַרְעִין דִי שַׁוֵיתִי בְמִצְרַיִם לָא אֲשַׁוִנוּן עֲלָךְ אֲרֵי אֲנָא יְיָ אַסָךְ:
@415 וַאֲתוֹ לְאֵילִם וְתַמָן תְּרֵי עֲסַר מַבּוּעִין דְמַיִן וְשִׁבְעִין דִקְלִין וּשְׁרוֹ תַמָן עַל מַיָא:
@416 וּנְטָלוּ מֵאֵילִם וַאֲתוֹ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל לְּמַדְבְּרָא דְסִין דִי בֵין אֵילִם וּבֵין סִינָי בְּחַמְשַׁת עַסְרָא יוֹמָא לְיַרְחָא תִנְיָנָא לְמִפָּקְהוֹן מֵאַרְעָא דְמִצְרַיִם:
@417 וְאִתְרָעָמוּ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל עַל משֶׁה וְעַל אַהֲרֹן בְּמַדְבְּרָא:
@418 וַאֲמָרוּ לְהוֹן בְּנֵי יִשְׂרָאֵל לְוַי דְמִיתְנָא קֳדָם יְיָ בְּאַרְעָא דְמִצְרַיִם כַּד הֲוֵינָא יָתְבִין עַל דוּדֵי בִסְרָא כַּד הֲוֵינָא אָכְלִין לַחְמָא וְשָׂבְעִין אֲרֵי אַפֶּקְתּוּן יָתָנָא לְמַדְבְּרָא הָדֵין לְקַטָּלָא יָת כָּל קְהָלָא הָדֵין בְּכַפְנָא:
@419 וַאֲמַר יְיָ לְמשֶׁה הָא אֲנָא מָחֵית לְכוֹן לַחְמָא מִן שְׁמַיָא וְיִפְקוּן עַמָא וְיִלְקְטוּן פִּתְגַם יוֹם בְּיוֹמֵהּ בְּדִיל דַאֲנַסִנוּן הַיְהָכוּן בְּאוֹרַיְתִי אִם לָא:
@420 וִיהֵי בְּיוֹמָא שְׁתִיתָאָה וִיתַקְנוּן יָת דְיַיְתוּן וִיהֵי עַל חַד תְּרֵין עַל דְיִלְקְטוּן יוֹם יוֹם:
@421 וַאֲמַר משֶׁה וְאַהֲרֹן לְכָל בְּנֵי יִשְׂרָאֵל בְּרַמְשָׁא וְתִדְעוּן אֲרֵי יְיָ אַפֵּיק יָתְכוֹן מֵאַרְעָא דְמִצְרָיִם:
@422 וּבְצַפְרָא וְתֶחֱזוּן יָת יְקָרָא דַיְיָ כַּד שְׁמִיעַ (קֳדָמוֹהִי) יָת תֻּרְעֲמוּתְכוֹן עַל מֵימְרָא דַיְיָ וְנַחְנָא מָא אֲרֵי אַתְרַעַמְתּוּן עֲלָנָא:
@423 וַאֲמַר משֶׁה בִּדְיִתֵּן יְיָ לְכוֹן בְּרַמְשָׁא בִּסְרָא לְמֵיכַל וְלַחְמָא בְּצַפְרָא לְמִסְבַּע בְּדִשְׁמִיעַן קֳדָם יְיָ יָת תֻּרְעֲמוּתְכוֹן דִי אַתּוּן מִתְרַעֲמִין עֲלוֹהִי וְנַחְנָא מָא לָא עֲלָנָא תֻּרְעֲמוּתְכוֹן אֶלָהֵן עַל מֵימְרָא דַיְיָ:
@424 וַאֲמַר משֶׁה לְאַהֲרֹן אֱמַר לְכָל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל קְרִיבוּ קֳדָם יְיָ אֲרֵי שְׁמִיעַן קֳדָמוֹהִי יָת תֻּרְעֲמוּתְכוֹן:
@425 וַהֲוָה כַּד מַלִיל אַהֲרֹן עִם כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵלּ וְאִתְפְּנִיוּ לְמַדְבְּרָא וְהָא יְקָרָא דַיְיָ אִתְגְלִי בַּעֲנָנָא:
@426 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@427 שְׁמִיעַ קֳדָמַי יָת תֻּרְעֲמַת בְּנֵי יִשְּׂרָאֵל מַלֵיל עִמְהוֹן לְמֵימַר בֵּין שִׁמְשַׁיָא תֵּיכְלּוּן בִּסְרָא וּבְצַפְרָא תִּשְׂבְּעוּן לַחְמָא וְתִדְעוּן אֲרֵי אֲנָא יְיָ אֱלָהָכוֹן:
@428 וַהֲוָה בְרַמְשָׁא וּסְלֵיקַת סְלָיו וַחֲפַת יָת מַשְׁרִיתָא וּבְצַפְרָא הֲוַת נְחָתַת טַלָא סְחוֹר סְחוֹר לְמַשְׁרִיתָא:
@429 וּסְלֵיקַת נְחָתַת טַלָא וְהָא עַל אַפֵּי מַדְבְּרָא דַעְדַק מְקַלַף דַעְדַק כְּגִיר כִּגְלִידָא עַל אַרְעָא:
@430 וַחֲזוֹ בְנֵי יִשְׂרָאֵל וַאֲמָרוּ גְבַר לַאֲחוּהִי מַנָא הוּא אֲרֵי לָא יְדָעוּ מָא הוּא וַאֲמַר משֶׁה לְהוֹן הוּא לַחְמָא דִי יְהַב יְיָ לְכוֹן לְמֵיכַל:
@431 דֵין פִּתְגָמָא דִי פַקֵיד יְיָ לְקוּטוּ מִנֵהּ גְבַר לְפוּם מֵיכְלֵהּ עֻמְרָא לְגֻלְגַלְתָּא מִנְיַן נַפְשָׁתֵיכוֹן גְבַר לְדִי בְמַשְׁכְּנֵהּ תִּסְבוּן:
@432 וַעַבָדוּ כֵן בְּנֵי יִשְׂרָאֵל וּלְקָטוּ דְאַסְגֵי וּדְאַזְעֵר:
@433 וּכְלוֹ בְעוּמְרָא וְלָא אוֹתַר דְאַסְגֵי וּדְאַזְעֵר לָא חַסִיר גְבַר לְפוּם מֵיכְלֵהּ לְקָטוּ:
@434 וַאֲמַר משֶׁה לְהוֹן אֱנַשׁ לָא יַשְׁאַר מִנֵהּ עַד צַפְרָא:
@435 וְלָא קַבִּילוּ מִן משֶׁה וְאַשְׁאָרוּ גֻבְרַיָא מִנֵה עַד צַפְרָא וּרְחֵשׁ רִיחֲשָׁא וּסְרִי וּרְגַז עֲלֵיהוֹן משֶׁה:
@436 וּלְקָטוּ יָתֵהּ בִּצְפַר בִּצְפָר גְבַר לְפוּם מֵיכְלֵהּ וּמָא דְמִשְׁתָּאַר מִנֵהּ עַל אַפֵּי חַקְלָא כַּד חֲמָא עֲלוֹהִי שִׁמְשָׁא פָּשָׁר:
@437 וַהֲוָה בְּיוֹמָא שְׁתִיתָאָה לְקָטוּ לַחְמָא עַל חַד תְּרֵין תְּרֵין עֻמְרִין לְחָד וַאֲתוֹ כָּל רַבְרְבֵי כְנִשְׁתָּא וְחַוִיאוּ לְמשֶׁה:
@438 וַאֲמַר לְהוֹן הוּא דִי מַלִיל יְיָ שְׁבָתָא שְׁבַת קוּדְשָׁא קֳדָם יְיָ מְחָר יָת דִי אַתּוּן עֲתִידִין לְמֵפָא אֲפוֹ וְיָת דִי אַתּוּן עֲתִידִין לְבַשָׁלָא בַּשִׁילוּ וְיָת כָּל מוֹתָרָא אַצְנָעוּ לְכוֹן לְמַטְּרַת עַד צַפְרָא:
@439 וְאַצְנָעוּ יָתֵהּ עַד צַפְרָא כְּמָא דְפַקִיד משֶׁה וְלָא סְרִי וְרִיחֲשָׁא לָא הֲוָה בֵהּ:
@440 וַאֲמַר משֶׁה אִכְלוּהִי יוֹמָא דֵין אֲרֵי שַׁבְּתָא יוֹמָא דֵין קֳדָם יְיָ יוֹמָא דֵין לָא תַשְׁכְּחֻנֵהּ בְּחַקְלָא:
@441 שִׁתָּא יוֹמִין תִּלְקְטֻנֵהּ וּבְיוֹמָא שְׁבִיעָאָה שַׁבְּתָא לָא יְהֵי בֵהּ:
@442 וַהֲוָה בְּיוֹמָא שְׁבִיעָאָה נְפָקוּ מִן עַמָא לְמִלְקָטּ וְלָא אַשְׁכָּחוּ:
@443 וַאֲמַר יְיָ לְמשֶׁה עַד אֵימָתַי אַתּוּן מְסָרְבִין לְמִטַר פִּקוּדַי וְאוֹרָיָתַי:
@444 חֲזוֹ אֲרֵי יְיָ יְהַב לְכוֹן שַׁבְּתָא עַל כֵּן הוּא יָהֵב לְכוֹן בְּיוֹמָא שְׁתִיתָאָה לְחֵם תְּרֵין יוֹמִין תִּיבוּ אֲנַשׁ תְּחוֹתוֹהִי לָא יִפּוֹק אֲנַשׁ מֵאַתְרֵהּ בְּיוֹמָא שְׁבִיעָאָה:
@445 וְנָחוּ עַמָא בְּיוֹמָא שְׁבִיעָאָה:
@446 וּקְרוֹ בֵית יִשְׂרָאֵל יָת שְׁמֵהּ מָן וְהוּא כְּבַר זְרַע גִדָא חִוָר וְטַעְמֵה כְּאִסְקְרֵיטָוָן בִּדְבָשׁ:
@447 וַאֲמַר משֶׁה דֵין פִּתְגָמָא דִי פַקִיד יְיָ מִלֵי עֻמְרָא מִנֵהּ לְמַטְרָא לְדָרֵיכוֹן בְּדִיל דְיֶחְזוּן יָת לַחְמָא דִי אוֹכָלִית יָתְכוֹן בְּמַדְבְּרָא בְּאַפָּקוּתִי יָתְכוֹן מֵאַרְעָא דְמִצְרָיִם:
@448 וַאֲמַר משֶׁה לְאַהֲרֹן סַב צְלוֹחִית חֲדָא וְהַב תַמָן מְלֵי עֻמְרָא מָן וְאַצְנַע יָתֵהּ קֳדָם יְיָ לְמַטְרָא לְדָרֵיכוֹן:
@449 כְּמָא דִי פַקִיד יְיָ לְמשֶׁה וְאַצְנְעֵהּ אַהֲרֹן קֳדָם סַהֲדוּתָא לְמַטְרָא:
@450 וּבְנֵי יִשְׂרָאֵל אֲכָלוּ יָת מַנָא אַרְבְּעִין שְׁנִין עַד דְמֵיתֵיהוֹן לְאַרְעָא יָתְבָתָא יָת מַנָא אֲכָלוּ עַד דְאָתוֹ לִסְיָפֵי אַרְעָא דִכְנָעַן:
@451 וְעֻמְרָא חַד מִן עַסְרָא בִּתְלָת סְאִין הוּא:
@452 וּנְטָלוּ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל מִמַדְבְּרָא דְסִין לְמַטְלָנֵיהוֹן עַל מֵימְרָא דַיְיָ וּשְׁרוֹ בִּרְפִידִים וְלֵית מַיָא לְמִשְׁתֵּי עַמָא:
@453 וּנְצָא עַמָא עִם משֶׁה וַאֲמָרוּ הָבוּ לָנָא מַיָא וְנִשְׁתֵּי וַאֲמַר לְהוֹן משֶׁה מָא אַתּוּן נָצָן עִמִי מָא מְנַסוּן אַתּוּן קֳדָם יְיָ:
@454 וּצְחִי תַמָן עַמָא לְמַיָא וְאִתְרַעַם עַמָא עַל משֶׁה וַאֲמַר לְמָא דְנַן אַסֶקְתָּנָא מִמִצְרַיִם לְקַטָלָא יָתִי וְיָת בָּנַי וְיָת בְּעִירַי בְּצָחוּתָא:
@455 וְצַלִי משֶׁה קֳדָם יְיָ לְמֵימַר מָא אֶעְבֵּד לְעַמָא הָדֵין עוֹד זְעֵיר פּוֹן וְיִרְגְמֻנִי:
@456 וַאֲמַר יְיָ לְמשֶׁה עִבַּר קֳדָם עַמָא וּדְבַר עִמָךְ מִסָבֵי יִשְׂרָאֵל וְחֻטְרָךְ דִי מָחֵיתָא בֵהּ יָת נַהֲרָא סַב בִּידָךְ וְתֵיזִל:
@457 הָא אֲנָא קָאֵם קֳדָמָךְ תַּמָן עַל טִנָרָא בְּחוֹרֵב וְתִמְחֵי בְטִנָרָא וְיִפְּקוּן מִנֵהּ מַיָא וְיִשְׁתֵּי עַמָא וַעֲבַד כֵּן משֶׁה לְעֵינֵי סָבֵי יִשְׂרָאֵל:
@458 וּקְרָא שְׁמָא דְאַתְרָא נִסֵיתָא וּמַצוּתָא עַל דִנְצוֹ בְּנֵי יִשְׂרָאֵל וְעַל דְנַסִיאוּ קֳדָם יְיָ לְמֵימַר הֲאִית שְׁכִינְתָּא דַיְיָ בֵּינָנָא אִם לָא:
@459 וַאֲתָא עֲמָלֵק וַאֲגַח קְרָבָא עִם יִשְׂרָאֵל בִּרְפִידִם:
@460 וַאֲמַר משֶׁה לִיהוֹשֻׁעַ בְּחַר לָנָא גֻבְרַיָא וּפוּק אֲגַח קְרָבָא בַּעֲמָלֵק מְחָר אֲנָא קָאֵם עַל רֵישׁ רָמָתָא וְחוּטְרָא דְאִתְעֲבִידוּ בֵהּ נִסִין מִן קֳדָם יְיָ בִּידִי:
@461 וַעֲבַד יְהוֹשֻׁעַ כְּמָא דְאֲמַר לֵהּ משֶׁה לְאַגָחָא קְרָבָא בַּעֲמָלֵק וּמשֶׁה אַהֲרֹן וְחוּר סְלִיקוּ לְרֵישׁ רָמָתָא:
@462 וַהֲוִי כַּד יְרִים משֶׁה יְדוֹהִי וּמִתְגַבְּרִין דְבֵית יִשְׂרָאֵל וְכַד מַנַח יְדוֹהִי וּמִתְגַבְּרִין דְבֵית עֲמָלֵק:
@463 וִידֵי משֶׁה יְקָרָן וּנְסִיבוּ אַבְנָא וְשַׁוִיאוּ תְחוֹתוֹהִי וִיתֵב עֲלַהּ וְאַהֲרֹן וְחוּר סַעְדָן בִּידוֹהִי מִכָּא חַד וּמִכָּא חַד וַהֲוָה יְדוֹהִי פְּרִיסָן בִּצְלוֹ עַד דְעַל שִׁמְשָׁא:
@464 וְתַבַּר יְהוֹשֻׁעַ יָת עֲמָלֵק וְיָת עַמֵהּ לְפִתְגָם דְחָרֶב:
@465 וַאֲמַר יְיָ לְמשֶׁה כְּתָב דָא דוּכְרָנָא בְּסִפְרָא וְשַׁוִי קֳדָם יְהוֹשֻׁעַ אֲרֵי מִמְחָא אֶמְחֵי יָת דוּכְרָנָא דַעֲמָלֵק מִתְּחוֹת שְׁמַיָא:
@466 וּבְנָא משֶׁה מַדְבְּחָא וּפְלַח עֲלוֹהִי קֳדָם יְיָ דַעֲבַד לֵהּ נִסִין:
@467 וַאֲמַר בִּשְׁבוּעָה אֲמִירָא דָא מִן קֳדָם דְחֵילָא דִשְׁכִנְתֵּהּ עַל כָּרְסֵהּ יְקָרֵהּ דְעָתִיד דְאִתָּגַח קְרָבָא קֳדָם יְיָ בִּדְבֵית עֲמָּלֵק לְשֵׁצָיוּתְהוֹן מִדָרֵי עָלְמָא: פפפ:
@468 וּשְׁמַע יִתְרוֹ רַבָּא דְמִדְיָן חֲמוּהִי דְמשֶׁה יַת כָּל דִי עֲבַד יְיָ לְמשֶׁה וּלְיִשְׂרָאֵל עַמֵהּ אֲרֵי אַפִּיק יְיָ יָת יִשְׂרָאֵל מִמִצְרָיִם:
@469 וּדְבַר יִתְרוֹ חֲמוּהִי דְמשֶׁה יָת צִפֹּרָה אִתַּת משֶׁה בָּתַר דְפַטְרַהּ:
@470 וְיָת תְּרֵין בְּנָהָא דִי שׁוּם חַד גֵרְשֹׁם אֲרֵי אֲמַר דַיָר הֲוֵיתִי בְּאַרְעָא נוּכְרָאָה:
@471 וְשׁוּם חַד אֱלִיעֶזֶר אֲרֵי אֱלָהָא דְאַבָּא הֲוָה בְסַעְדִי וְשֵׁזְבַנִי מֵחַרְבָּא דְפַרְעֹה:
@472 וַאֲתָא יִתְרוֹ חֲמוּהִי דְמשֶׁה וּבְנוֹהִי וְאִתְּתֵהּ לְוָת משֶׁה לְמַדְבְּרָא דִי הוּא שָׁרֵי תַמָן לְטוּרָא דְאִתְגְלֵי עֲלוֹהִי יְקָרָא דַיְיָ:
@473 וַאֲמַר לְמשֶׁה אֲנָא חֲמוּךְ יִתְרוֹ אָתֵי לְוָתָךְ וְאִתְּתָךְ וּתְרֵין בְּנָהָא עִמַהּ:
@474 וּנְפַק משֶׁה לְקַדָמוּת חֲמוּהִי וּסְגִיד וּנְשִׁיק לֵהּ וּשְׁאִילוּ גְבַר לְחַבְרֵהּ לִשְׁלָם וְעַלוּ לְמַשְׁכְּנָא:
@475 וְאִשְׁתָּעִי משֶׁה לַחֲמוּהִי יָת כָּל דִי עֲבַד יְיָ לְפַרְעֹה וּלְמִצְרָאֵי עַל עֵסַק יִשְׂרָאֵל יָת כָּל עַקְתָא דִי אַשְׁכַּחְתִּנוּן בְּאָרְחָא וְשֵׁזְבָנוּן יְיָ:
@476 וַחֲדִי יִתְרוֹ עַל כָּל טַבְתָא דִי עֲבַד יְיָ לְיִשְׂרָאֵל דִי שֵׁזְבָנוּן מִידָא דְמִצְרָאֵי:
@477 וַאֲמַר יִתְרוֹ בְּרִיךְ יְיָ דִי שֵׁזִיב יָתְכוֹן מִידָא דְמִצְרָאֵי וּמִידָא דְפַרְעֹה דִי שֵׁזִיב יָת עַמָא מִתְּחוֹת מַרְוַת מִצְרָאֵי:
@478 כְּעַן יְדַעְנָא אֲרֵי רַב יְיָ וְלֵית אֱלָּהּ בַּר מִנֵהּ אֲרֵי בְּפִתְגָמָא דִי חַשִׁיבוּ מִצְרָאֵי לְמִדַן יָת יִשְׂרָאֵל בֵּהּ דָנִנוּן:
@479 וְקָרִיב יִתְרוֹ חֲמוּהִי דְמשֶׁה עֲלָוָן וְנִכְסַת קוּדְשִׁין קֳדָם יְיָ וַאֲתָא אַהֲרֹן וְכֹל סָבֵי יִשְׂרָאֵל לְמֵיכַל לַחְמָא עִם חֲמוּהִי דְמשֶׁה קֳדָם יְיָ:
@480 וַהֲוָה מִיוֹמָא דְבַתְרוֹהִי וִיתֵיב משֶׁה לְמִדַן יָת עַמָא וְקָם עַמָא עִלָוֹהִי דְמשֶׁה מִן צַפְרָא עַד רַמְשָׁא:
@481 וַחֲזָא חֲמוּהִי דְמשֶׁה יָת כָּל דִי הוּא עָבֵד לְעַמָא וַאֲמַר מָא פִתְגָמָא הָדֵין דִי אַתְּ עָבֵד לְּעַמָא מָה דֵין אַתְּ יָתֵב בִּלְחוֹדָךְ וְכָל עַמָא קָיְמִין עִלָוָךְ מִן צַפְרָא עַד רַמְשָׁא:
@482 וַאֲמַר משֶׁה לַחֲמוּהִי אֲרֵי אָתָן לְוָתִי עַמָא לְמִתְבַּע אוּלְפַן מִן קֳדָם יְיָ:
@483 כַּד הֲוֵי לְהוֹן דִינָא אָתָן לְוָתִי וְדָאִינְנָא בֵּין גַבְרָא וּבֵין חַבְרֵהּ וּמְהוֹדַעְנָא לְהוֹן יָת קְיָמַיָא דַיְיָ וְיָת אוֹרָיָתֵהּ:
@484 וַאֲמַר חֲמוּהִי דְמשֶׁה לֵהּ לָא תַקִין פִּתְגָמָא דְאַתְּ עָבֵד:
@485 מִלְאָה תִלְאֶה אַף אַתְּ אַף עַמָא הָדֵין דִעִמָךְ אֲרֵי יַקִיר מִנָךְ פִּתְגָמָא לָא תִכּוֹל לְמֶעְבְּדֵהּ בִּלְחוֹדָךְ:
@486 כְּעַן קַבֵּל מִנִי אֲמַלְכִנָךְ וִיהֵי מֵימְרָא דַיְיָ בְּסַעְדָךְ הֱוֵי אַתְּ לְעַמָא (תְּבַע) אוּלְפַן מִן קֳדָם יְיָ וּתְהֵי מַיְתִי אַתְּ יָת פִּתְגָמַיָא לִקֳדָם יְיָ:
@487 וְתַזְהַר יָתְהוֹן יָת קְיָמַיָא וְיָת אוֹרַיְתָא וּתְהוֹדַע לְהוֹן יָת אוֹרְחָא דִיְהָכוּן בַּהּ וְיָת עוֹבָדָא דִיַעְבְּדוּן:
@488 וְאַתְּ תֶּחֶזֵי מִכָּל עַמָא גֻבְרִין דְחֵילָא דַחֲלַיָא דַיְיָ גֻבְרִין דִקְשׁוֹט דְסָנָן לְקַבָּלָא מָמוֹן וּתְמַנֵי עֲלֵיהוֹן רַבָּנֵי אַלְפִין רַבָּנֵי מָאוָתָא רַבָּנֵי חַמְשִׁין וְרַבָּנֵי עִשׂוֹרְיָתָא:
@489 וִידוּנוּן יָת עַמָא בְּכָל עִדַן וִיהֵי כָּל פִּתְגַם רַב יַיְתוּן לְוָתָךְ וְכָל פִּתְגַם זְעֵיר יְדוּנוּן אִנוּן וְיִקְלוּן מִנָךְ וִיסוֹבְרוּן עִמָךְ:
@490 אִם יָת פִּתְגָמָא הָדֵין תַּעְבֵּד וִיפַקְדִנָךְ יְיָ וְתִכּוֹל לְמֵיקָם וְאַף כָּל עַמָא הָדֵין עַל אַתְרֵהּ יְהַךְ בִּשְׁלָם:
@491 וְקַבִּיל משֶׁה לְמֵימְרָא דַחֲמוּהִי וַעֲבַד כֹּל דִי אֲמָר:
@492 וּבְחַר משֶׁה גֻבְרִין דְחֵילָא מִכָּל יִשְׂרָאֵל וּמַנִי יָתְהוֹן רֵישִׁין עַל עַמָא רַבָּנֵי אַלְפִין רַבָּנֵי מָאוָתָא רַבָּנֵי חַמְשִׁין וְרַבָּנֵי עִשׂוֹרְיָתָא:
@493 וְדַיְנִין יָת עַמָא בְּכָל עִדָן יָת פִתְגַם קָשֵׁי מַיְתִין לְוָת משֶׁה וְכָל פִּתְגַם זְעֵיר דָיְנִין אִנוּן:
@494 וְשַׁלַח משֶׁה יָת חֲמוּהִי וַאֲזַל לֵהּ לְאַרְעֵהּ:
@495 בְּיַרְחָא תְּלִיתָאָה לְמִפַּק בְּנֵי יִשְׂרָאֵל מֵאַרְעָא דְמִצְרָיִם בְּיוֹמָא הָדֵין אֲתוֹ לְמַדְבְּרָא דְסִינָי:
@496 וּנְטָלוּ מֵרְפִידִים וַאֲתוֹ לְמַדְבְּרָא דְסִינָי וּשְׁרוֹ בְּמַדְבְּרָא וּשְׁרָא תַמָן יִשְׂרָאֵל לָקֳבֵל טוּרָא:
@497 וּמשֶׁה סְלֵק לִקֳדָם יְיָ וּקְרָא לֵהּ יְיָ מִן טוּרָא לְמֵימַר כִּדְנַן תֵּימַר לְבֵית יַעֲקֹב וּתְחַוִי לִבְנֵי יִשְׂרָאֵל:
@498 אַתּוּן חֲזִתּוּן דִי עֲבָדִית לְמִצְרָיִם וּנְטָלִית (נ''א וְאַטְּלִית) יָתְכוֹן כִּדְעַל גַדְפֵי נִשְׁרִין וְקָרֵבִית יָתְכוֹן לְפָלְחָנִי:
@499 וּכְעַן אִם קַבָּלָא תְקַבְּלוּן לְמֵימְרִי וְתִטְרוּן יָת קְיָמִי וּתְהוֹן קֳדָמַי חַבִּיבִין מִכָּל עַמְמַיָא אֲרֵי דִי לִי כָּל אַרְעָא:
@500 וְאַתּוּן תְּהוֹן קֳדָמַי מַלְכִין כָּהֲנִין וְעַם קַדִישׁ אִלֵין פִּתְגָמַיָא דִי תְמַלֵל עִם בְּנֵי יִשְׂרָאֵל:
@501 וַאֲתָא משֶׁה וּקְרָא לְסָבֵי עַמָא וְסַדַר קֳדָמֵיהוֹן יָת כָּל פִּתְגָמַיָא הָאִלֵין דִפַקְדֵיהּ יְיָ:
@502 וַאֲתִיבוּ כָל עַמָא כַּחֲדָא וַאֲמָרוּ כֹּל דִי מַלִיל יְיָ נַעְבֵּד וַאֲתֵיב משֶׁה יָת פִּתְגָמֵי עַמָא קֳדָם יְיָ:
@503 וַאֲמַר יְיָ לְמשֶׁה הָא אֲנָא מִתְגְלִי לָךְ בְּעֵיבָא דַעֲנָנָא בְּדִיל דְיִשְׁמַע עַמָא בְּמַלָלוּתִי עִמָךְ וְאַף בָּךְ יְהֵימְנוּן לְעָלָם וְחַוִי משֶׁה יָת פִּתְגָמֵי עַמָא קֳדָם יְיָ:
@504 וַאֲמַר יְיָ לְמשֶׁה אִזֵיל לְוָת עַמָא וּתְזַמִנוּן יוֹמָא דֵין וּמְחָר וִיחַוְרוּן לְבוּשֵׁיהוֹן:
@505 וִיהוֹן זְמִינִין לְיוֹמָא תְלִיתָאָה אֲרֵי בְּיוֹמָא תְלִיתָאָה יִתְגְלִי יְיָ לְעֵינֵי כָל עַמָא עַל טוּרָא דְסִינָי:
@506 וּתְתַחֵם יָת עַמָא סְחוֹר סְחוֹר לְמֵימַר אִסְתַּמָרוּ לְכוֹן מִלְמִסַק בְּטוּרָא וּלְמִקְרַב בְּסוֹפֵהּ כָּל דְיִקְרַב בְּטוּרָא אִתְקְטָלָא יִתְקְטֵל:
@507 לָא תִקְרַב בֵּהּ יְדָא אֲרֵי אִתְרְגָמָא יִתְרְגֵם אוֹ אִשְׁתְּדָאָה יִשְׁתְּדִי אִם בְּעִירָא אִם אֱנָשָׁא לָא יִתְקַיָם בְּמֵיגַד שׁוֹפָרָא אִנוּן מְרָשָׁן לְמִסַק בְּטוּרָא:
@508 וּנְחַת משֶׁה מִן טוּרָא לְוָת עַמָא וְזַמִין יָת עַמָא וְחַוָרוּ לְבוּשֵׁיהוֹן:
@509 וַאֲמַר לְעַמָא הֱווֹ זְמִינִין לִתְלָתָא יוֹמִין לָא תִקְרְבוּן לְצַד אִתְּתָא:
@510 וַהֲוָה בְיוֹמָא תְלִיתָאָה בְּמֶהֱוֵי צַפְרָא וַהֲוָה קָלִין וּבַרְקִין וַעֲנָנָא תַקִיף עַל טוּרָא וְקַל שׁוֹפָרָא תַּקִיף לַחֲדָא וְזָע כָּל עַמָא דִי בְמַשְׁרִיתָא:
@511 וְאַפֵיק משֶׁה יָת עַמָא לְקַדָמוּת מֵימְרָא דַיְיָ מִן מַשְׁרִיתָא וְאִתְעַתָּדוּ בְּשִׁפּוֹלֵי טוּרָא:
@512 וְטוּרָא דְסִינַי תָּנַן כֻּלֵהּ מִן קֳדָם דְאִתְגְלִי עֲלוֹהִי יְיָ בְּאֶשָׁתָא וּסְלִיק תְּנָנֵהּ כִּתְנָנָא דְאַתּוּנָא וְזָע כָּל טוּרָא לַחֲדָא:
@513 וַהֲוָה קַל שׁוֹפָרָא אָזֵל וְתָקֵף לַחֲדָא משֶׁה מְמַלֵל וּמִן קֳדָם יְיָ מִתְעֲנֵי לֵהּ בְקָל:
@514 וְאִתְגְלִי יְיָ עַל טוּרָא דְסִינַי לְרֵישׁ טוּרָא וּקְרָא יְיָ לְמשֶׁה לְרֵישׁ טוּרָא וּסְלִיק משֶׁה:
@515 וַאֲמַר יְיָ לְמשֶׁה חוּת אַסְהֵיד בְּעַמָא דִילְמָא יְפַגְרוּן קֳדָם יְיָ לְמֶחֱזֵי וְיִפֵּל מִנְהוֹן סַגִי:
@516 וְאַף כָּהֲנַיָא דִקְרִיבִין לְשַׁמָשָׁא קֳדָם יְיָ יִתְקַדְשׁוּן דִילְמָא יִקְטוֹל בְּהוֹן יְיָ:
@517 וַאֲמַר משֶׁה קֳדָם יְיָ לָא יִכּוֹל עַמָא לְמִסַק לְטוּרָא דְסִינַי אֲרֵי אַתְּ אַסְהֵדְתָּ בָּנָא לְמֵימַר תַּחִים יָת טוּרָא וְקַדְשֵׁהּ:
@518 וַאֲמַר לֵהּ יְיָ אִזֵיל חוּת וְתִסַק אַתְּ וְאַהֲרֹן עִמָךְ וְכָהֲנַיָא וְעַמָא לָא יְפַגְרוּן לְמִסַק לִקֳדָם יְיָ דִילְמָא יִקְטוֹל בְּהוֹן:
@519 וּנְחַת משֶׁה לְעַמָא וַאֲמַר לְהוֹן:
@520 וּמַלִיל יְיָ יָת כָּל פִּתְגָמַיָא הָאִלֵין לְמֵימָר:
@521 אֲנָא יְיָ אֱלָהָךְ דִי אַפֵּיקְתָּךְ מֵאַרְעָא דְמִ צְרַיִם מִבֵּית עַבְדוּתָא:
@522 לָא יְהֵי לָךְ אֱלָהּ אָחֳרָן בַּר מִנִי:
@523 לָא תַעְבֵּד לָךְ צֶלֶם וְכָל דְמוּת דִי בִשְׁמַיָא מִלְעֵלָא וְדִי בְאַרְעָא מִלְרָע וְדִי בְמַיָא מִלְרַע לְאַרְעָא:
@524 לָא תִסְגֻד לְהוֹן וְלָא תִפְלְחִנוּן אֲרֵי אֲנָא יְיָ אֱלָהָךְ אֵל קַנָא מַסְעַר חוֹבֵי אֲבָהָן עַל בְּנִין מָרָדִין עַל דַר תְּלִיתַי וְעַל דַר רְבִיעַי לְשָׂנְאָי כַּד מְשַׁלְמִין בְּנַיָא לְמֶחֱטֵי בָּתַר אֲבָהָתְהוֹן:
@525 וְעָבֵד טִּיבוּ לְאַלְפֵי דָרִין לְרַחֲמַי וּלְנָטְרֵי פִקוֹדָי:
@526 לָא תֵימֵי יָת שְׁמָא דַיְיָ אֱלָהָךְ לְמַגָנָא אֲרֵי לָא יִזַכֵּי יְיָ יָת דִיֵימֵי בִשְׁמֵהּ לְשִׁקְרָא:
@527 הֲוֵי דְכִיר יָת יוֹמָא דְשַׁבְּתָא לְקַדָשׁוּתֵהּ:
@528 שִׁתָּא יוֹמִין תִּפְלָח וְתַעְבֵּד כָּל עִבִדְתָּךְ:
@529 וְיוֹמָא שְׁבִיעָאָה שַׁבְּתָא קֳדָם יְיָ אֱלָהָךְ לָא תַעְבֵּד כָּל עִבִדְתָּא אַתְּ וּבְרָךְ וּבְרַתָּךְ עַבְדָךְ וְאַמְתָךְ וּבְעִירָךְ וְגִיוֹרָךְ דִי בְקִרְוָךְ:
@530 אֲרֵי שִׁתָּא יוֹמִין עֲבַד יְיָ יָת שְׁמַיָא וְיָת אַרְעָא יָת יַמָא וְיָת כָּל דִי בְהוֹן וְנָח בְּיוֹמָא שְׁבִיעָאָה עַל כֵּן בָּרִיךְ יְיָ יָת יוֹמָא דְשַׁבְּתָא וְקַדְשֵׁהּ:
@531 יַקַר יָת אָבוּךְ וְיָת אִמָךְ בְּדִיל דְיוֹרְכוּן יוֹמָיךְ עַל אַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@532 לָא תִקְטוֹל נְפָשׁ לָא תְגוּף לָא תִגְנוּב לָא תַסְהֵד בְּחַבְרָךְ סַהֲדוּתָא דְשִׁקְרָא:
@533 לָא תַחְמֵד בֵּית חַבְרָךְ לָא תַחְמֵד אִתַּת חַבְרָךְ וְעַבְדֵהּ וְאַמְתֵהּ וְתוֹרֵהּ וַחֲמָרֵהּ וְכֹל דִי לְחַבְרָךְ:
@534 וְכָל עַמָא חָזָן יָת קָלַיָא וְיָת בָּעוֹרַיָא וְיָת קַל שׁוֹפָרָא וְיָת טוּרָא תָּנֵן וַחֲזָא עַמָא וְזָעוּ וְקָמוּ מֵרָחִיק:
@535 וַאֲמָרוּ לְמשֶׁה מַלֵל אַתְּ עִמָנָא וּנְקַבֵּל וְלָא יִתְמַלֵל עִמָנָא מִן קֳדָם יְיָ דִילְּמָא נְמוּת:
@536 וַאֲמַר משֶׁה לְעַמָא לָא תִדְחֲלוּן אֲרֵי בְּדִיל לְנַסָאָה יָתְכוֹן אִתְגְלִי לְכוֹן יְקָרָא דַיְיָ וּבְדִיל דִתְהֵי דַחַלְתֵּהּ עַל אַפֵּיכוֹן בְּדִיל דְלָא תְחוּבוּן:
@537 וְקָם עַמָא מֵרָחִיק וּמשֶׁה קָרֵב לְצַד אַמִיטְּתָא דִתַמָן יְקָרָא דַיְיָ:
@538 וַאֲמַר יְיָ לְמשֶׁה כִּדְנַן תֵּימַר לִבְנֵי יִשְׂרָאֵל אַתּוּן חֲזִיתּוּן אֲרֵי מִן שְׁמַיָא מַלֵילִית עִמְכוֹן:
@539 לָא תַעְבְּדוּן קֳדָמָי דַחֲלָן דִכְסַף וְדַחֲלָן דִדְהַב לָא תַעְבְּדוּן לְכוֹן:
@540 מַדְבַּח אַדְמְתָא תַּעְבֵּד קֳדָמַי וּתְהֵי דַבָּח עֲלוֹהִי יָת עֲלָוָתָךְ וְיָת נְכַס קוּדְשָׁךְ מִן עָנָךְ וּמִן תּוֹרָךְ בְּכָל אַתְרָא דִי אַשְׁרֵי יָת שְׁכִנְתִּי לְתַמָן אֶשְׁלַח בִּרְכְּתִי לָךְ וֶאֱבָרֵכִנָךְ:
@541 וְאִם מַדְבַּח אַבְנִין תַּעְבֵּד קֳדָמַי לָא תִבְנֵי יָתְהוֹן פְּסִילָן לָא תְרִים חַרְבָּךְ עֲלַהּ וּתְחַלְלִנַהּ:
@542 וְלָא תִסַק בְּדַרְגִין עַל מַדְבְּחִי דְלָא תִתְגְלֵי עֶרְיְתָךְ עֲלוֹהִי: פפפ:
@543 וְאִלֵין דִינַיָא דִי תַסְדַר קֳדָמֵיהוֹן:
@544 אֲרֵי תִזְבַּן עַבְדָא בַר יִשְׂרָאֵל שִׁתְּ שְׁנִין יִפְלָח וּבַשְׁבִיעֵתָא יִפּוֹק לְבַר חוֹרִין מַגָן:
@545 אִם בִּלְחוֹדוֹהִי יֵיעוֹל בִּלְחוֹדוֹהִי יִפּוֹק אִם בְּעֵל אִתְּתָא הוּא וְתִפּוֹק אִתְּתֵהּ עִמֵהּ:
@546 אִם רִבּוֹנֵהּ יִתֶּן לֵהּ אִתְּתָא וּתְלִיד לֵהּ בְּנִין אוֹ בְנָן אִתְּתָא וּבְנָהָא תְּהֵי לְרִבּוֹנָהָא וְהוּא יִפּוֹק בִּלְחוֹדוֹהִי:
@547 וְאִם מֵימַר יֵימַר עַבְדָא רָחֵימְנָא יָת רִבּוֹנִי יָת אִתְּתִי וְיָת בְּנָי לָא אֶפּוֹק לְבַר חוֹרִין:
@548 וִיקָרְבִנֵהּ רִבּוֹנֵהּ לִקֳדָם דַיָנַיָא וִיקָרְבִנֵהּ לְוָת דָשָׁא אוֹ לְוָת (נ''א דִילְוָת) מְזְזֶתָּא וְיַרְצַע רִבּוֹנֵהּ יָת אוּדְנֵהּ בְּמַרְצְעָא וִיהֵי לֵהּ עֲבַד פָּלַח לְעָלָם:
@549 וַאֲרֵי יְזַבֵּן גְבַר יָת בְּרַתֵּהּ לְאַמְהוּ לָא תִפּוֹק כְּמַפְקָנוּת עַבְדַיָא:
@550 אִם בִּישָׁא בְּעֵינֵי רִבּוֹנַהּ דִיקַיְמַהּ לֵהּ וְיִפְרְקִנַהּ לִגְבַר אָחֳרָן לֵית לֵהּ רְשׁוּ לְזַבּוֹנַהּ בְּמִשְׁלְטֵהּ בַהּ:
@551 וְאִם לִבְרֵהּ יְקַיְמִנַהּ כְּהִלְכַת בְּנַת יִשְׂרָאֵל יַעְבֵּד לַהּ:
@552 אִם אָחֳרַנְתָּא יִסַב לֵהּ זִיוּנַהּ כְּסוּתַהּ וְעוֹנָתַהּ לָא יִתְמְנָע:
@553 וְאִם תְּלָת אִלֵין לָא יַעְבֵּד לַהּ וְתִפּוֹק מַגָן בְּלָא כְסַף:
@554 דְיִמְחֵי לֶאֱנַשׁ וְיִקְטְלִנֵהּ אִתְקְטָלָא יִתְקְטֵל:
@555 וּדְלָא כְמַן לֵהּ וּמִן קֳדָם יְיָ אִתִּמְסַר לִידֵהּ וֶאֱשַׁוִי לָךְ אֲתַר דִי יֵעִרוֹק לְתַמָן:
@556 וַאֲרֵי יַרְשַׁע גְבַר עַל חַבְרֵהּ לְמִקְטְלֵהּ בִנְכִילוּ מִן מַדְבְּחִי תִּדְבְּרִנֵהּ לִמְמָת:
@557 וּדְיִמְחֵי אֲבוּהִי וְאִמֵהּ אִתְקְטָלָא יִתְקְטֵל:
@558 וְדִיִגְנוּב נַפְשָׁא מִן בְּנֵי יִשְׂרָאֵל וִיזַבְּנִנֵהּ וְיִשְׁתְּכַח בִּידֵהּ אִתְקְטָלָא יִתְקְטֵל:
@559 וְדִיְלוּט אֲבוּהִי וְאִמֵהּ אִתְקְטָלָא יִתְקְטֵל:
@560 וַאֲרֵי יִנְצוּן גֻבְרִין וְיִמְחֵי גְבַר יָת חַבְרֵהּ בְּאַבְנָא אוֹ בְכוּרְמֵיזָא וְלָא יְמוּת וְיִפּוֹל לְבוּטְלָן:
@561 אִם יְקוּם וִיהַלִיךְ בְּבָרָא עַל בּוּרְיֵהּ וִיהֵי זַכָּאָה מָחַיָא לְחוֹד בּוּטְּלָנֵהּ יִתֵּן וַאֲגַר אַסְיָא יְשַׁלֵם:
@562 וַאֲרֵי יִמְחֵי גְבַר יָת עַבְדֵהּ אוֹ יָת אַמְתֵהּ בְּשָׁלְטָּן וִימוּת תְּחוֹת יְדֵהּ אִתְדָנָא יִתְּדָן:
@563 בְּרַם אִם יוֹמָא אוֹ תְרֵין יוֹמִין יִתְקַיָם לָא יִתְּדָן אֲרֵי כַסְפֵּהּ הוּא:
@564 וַאֲרֵי יִנְצוּן גֻבְרִין וְיִמְחוּן אִתְּתָא מַעַדְיָא וְיִפְּקוּן וַלְדָהָא וְלָא יְהֵי מוֹתָא אִתְגְבָאָה יִתְגְבֵי כְּמָא דִי יְשַׁוִי עֲלוֹהִי בַּעֲלַהּ דְאִתְּתָא וְיִתֵּן עַל מֵימַר דַיָנַיָא:
@565 וְאִם מוֹתָא יְהֵא וְתִתֵּן נַפְשָׁא חֳלָף נַפְשָׁא:
@566 עֵינָא חֳלָף עֵינָא שִׁנָא חֳלָף שִׁנָא יְדָא חֳלָף יְדָא רַגְלָא חֳלָף רַגְלָא:
@567 כְּוָאָה חֳלָף כְּוָאָה פִּדְעָא חֳלָף פִּדְעָא מַשְׁקוֹפֵי חֳלָף מַשְׁקוֹפֵי:
@568 וַאֲרֵי יִמְחֵי גְבַר יָת עֵינָא דְעַבְדֵהּ אוֹ יָת עֵינָא דְאַמְתֵהּ וִיחַבְּלִנַהּ לְבַר חוֹרִין יִפְטְּרִנֵהּ חֳלָף עֵינֵהּ:
@569 וְאִם שִׁנָא דְעַבְדֵהּ אוֹ שִּׁנָא דְאַמְתֵהּ יַפֵּל לְבַר חוֹרִין יִפְטְרִנֵהּ חֳלָף שִׁנֵהּ:
@570 וַאֲרֵי יַגַח תּוֹרָא יָת גַבְרָא אוֹ יָת אִתְּתָא וִימוּת אִתְרְגְמָא יִתְרְגֵם תּוֹרָא וְלָא יִתְאָכֵל יָת בִּסְרֵהּ וּמָרֵהּ דְתוֹרָא יְהֵי זַכָּאָה:
@571 וְאִם תּוֹר נַגַח הוּא מֵאִתְּמַלֵי וּמִדְקַמוֹהִי וְיִתַּסְהֵד בְּמָרֵהּ וְלָא נַטְרֵהּ וְיִקְטוֹל גַבְרָא אוֹ אִתְּתָא תּוֹרָא יִתְרְגֵם וְאַף מָרֵהּ יִתְקְטֵל:
@572 אִם מָמוֹן יְשַׁווּן עֲלוֹהִי וְיִתֵּן פּוּרְקַן נַפְשֵׁהּ כְּכֹל דִי יְשַׁווּן עֲלוֹהִי:
@573 אוֹ לְבַר יִשְׂרָאֵל יַגַח תּוֹרָא אוֹ לְבַת יִשְׂרָאֵל יַגָח כְּדִינָא הָדֵין יִתְעֲבֵד לֵהּ:
@574 אִם לְעַבְדָא יַגַח תּוֹרָא אוֹ לְאַמְתָא כְּסַף תְּלָתִין סִלְעִין יִתֵּן לְרִבּוֹנֵהּ וְתוֹרָא יִתְרְגֵם:
@575 וַאֲרֵי יִפְתַּח גְבַר גוֹב אוֹ אֲרֵי יִכְרֶה גְבַר גוֹב וְלָא יְכַסִנֵהּ וְיִפֵּל תַּמָן תּוֹרָא אוֹ חֲמָרָא:
@576 מָרֵי דְגֻבָּא יְשַׁלֵם כַּסְפָּא יָתִיב לְמָרוֹהִי וּמֵיתָא יְהֵי דִילֵהּ:
@577 וַאֲרֵי יִגוֹף תּוֹר דִגְבַר יָת תּוֹרָא דְחַבְרֵהּ וִימוּת וִזַבְּנוּן יָת תּוֹרָא חַיָא וִיפַלְגוּן יָת כַּסְפֵּהּ וְאַף יָת דְמֵי מֵיתָא יְפַלְגוּן:
@578 אוֹ אִתְיְדַע אֲרֵי תוֹר נַגַח הוּא מֵאִתְּמַלֵי וּמִדְקַמוֹהִי וְלָא נָטְרֵהּ מָרֵהּ שַׁלָמָא יְשַׁלֵם תּוֹרָא חֲלַף תּוֹרָא וּמֵיתָא יְהֵא דִילֵהּ:
@579 אֲרֵי יִגְנוּב גְבַר תּוֹר אוֹ אִמָר וְיִכְּסִנֵהּ אוֹ זַבְּנִנֵהּ חַמְשָׁא תוֹרִין יְשַׁלֵם חָלָף תּוֹרָא וְאַרְבַּע עָנָא חֳלָף אִמְרָא:
@580 אִם בְּמַחְתַּרְתָּא יִשְׁתְּכַח גַנָבָא וְיִתְמְחֵי וִימוּת לֵית לֵהּ דָם:
@581 אִם עֵינָא דְסַהֲדַיָא נְפָלַת עֲלוֹהִי דְמָא לֵהּ שַׁלָמָא יְשַׁלֵם אִם לֵית לֵהּ וְיִזְדַבַּן בִּגְנֻבְתֵּהּ:
@582 אִם אִשְׁתְּכָחָא יִשְׁתְּכַח בִּידֵהּ גְנֻבְתָּא מִתּוֹר עַד חֲמַר עַד אִמַר דְאִנוּן חַיִין עַל חַד תְּרֵין יְשַׁלֵם:
@583 אֲרֵי יאכִיל גְבַר חֲקַל אוֹ כְרָם וִישַׁלַח יָת בְּעִירֵהּ וְיֵיכוּל בַּחֲקַל אָחֳרָן שְׁפַר חַקְלֵהּ וּשְׁפַר כַּרְמֵהּ יְשַׁלֵם:
@584 אֲרֵי תִתַּפַּק נוּר וְיַשְׁכַּח כּוּבִין וְיֵיכוּל גְדִישִׁין אוֹ קֳמָא אוֹ חַקְלָא שַׁלָמָא יְשַׁלֵם דְאַדְלֵק יָת דְלֶקְתָּא:
@585 אֲרֵי יִתֵּן גְבַר לְחַבְרֵהּ כְּסַף אוֹ מָנִין לְמִטַר וְיִתְגַנְבוּן מִבֵּית גַבְרָא אִם יִשְׁתְּכַח גַנָבָא יְשַׁלֵם עַל חַד תְּרֵין:
@586 אִם לָא יִשְׁתְּכַח גַנָבָא וְיִתְקָרֵב מָרֵי דְבֵיתָא לִקֳדָם דַיָנַיָא אִם לָא אוֹשִׁיט יְדֵהּ בְּמָא דִמְסַר לֵהּ חַבְרֵהּ:
@587 עַל כָּל פִּתְגַם דְחוֹב עַל תּוֹר עַל חֲמַר עַל אִמָר עַל כְּסוּ עַל כָּל אֲבֶדְתָּא דִי יֵימַר אֲרֵי הוּא דֵין לִקֳדָם דַיָנַיָא יֵיעוֹל דִין תַּרְוֵיהוֹן דִי יְחַיְבוּן דַיָנַיָא יְשַׁלֵם עַל חַד תְּרֵין לְחַבְרֵהּ:
@588 אֲרֵי יִתֵּן גְבַר לְחַבְרֵהּ חֲמַר אוֹ תוֹר אוֹ אִמָר וְכָל בְּעִירָא לְמִטָּר וּמִית אוֹ אִתְּבַר אוֹ אִשְׁתְּבִי לֵית דְחָזֵי:
@589 מוֹמָתָא דַיְיָ תְּהֵי בֵּין תַּרְוֵיהוֹן אִם לָא אוֹשִׁיט יְדֵהּ בְּמָא דִמְסַר לֵהּ חַבְרֵהּ וִיקַבֵּל מָרֵהּ מִנֵהּ מוֹמָתָא וְלָא יְשַׁלֵם:
@590 וְאִם אִתְגְנָבָא יִתְגְנֵב מֵעִמֵהּ יְשַׁלֵם לְמָרוֹהִי:
@591 אִם אִתְּבָרָא יִתְּבַר יַיְתִי סַהֲדִין דִתְבִירָא לָא יְשַׁלֵם:
@592 וַאֲרֵי יִשְׁאַל גְבַר מִן חַבְרֵהּ וְיִתְּבַר אוֹ מִית מָרֵהּ לֵית עִמֵהּ שַׁלָמָא יְשַׁלֵם:
@593 אִם מָרֵהּ עִמֵהּ לָא יְשַׁלֵם אִם אֲגִירָא הוּא עַל בְּאַגְרֵהּ:
@594 וַאֲרֵי יְשַׁדֵל גְבַר בְּתֻלְתָּא דִּי לָא מְאַרְסָא וְיִשְׁכּוּב עִמַהּ קַיָמָא יְקַיְמִנַהּ לֵהּ לְאִנְתּוּ:
@595 אִם מִצְבָּא לָא יִצְבֵּי אֲבוּהָא לְמִתְּנַהּ לֵהּ כַּסְפָּא יִתְקוֹל כְּמוֹהֲרֵי בְּתֻלְתָּא:
@596 חָרָשָׁא לָא תָחֵי:
@597 כָּל דְיִשְׁכּוּב עִם בְּעִירָא אִתְקְטָלָא יִתְקְטֵל:
@598 דְדַבַּח לְטַעְוַת עַמְמַיָא יִתְקְטֵל אֶלָהֵן לִשְׁמָא דַיְיָ בִּלְחוֹדוֹהִי:
@599 וְגִיוֹרָא לָא תוֹנוּן וְלָא תְעִיקוּן לֵהּ אֲרֵי דַיָרִין הֱוֵיתוּן בְּאַרְעָא דְמִצְרָיִם:
@600 כָּל אַרְמְלָא וְיִתָּם לָא תְעַנוּן:
@601 אִם עַנָאָה תְעַנֵי יָתֵהּ אֲרֵי אִם מִקְבַל יִקְבֵל קֳדָמַי קַבָּלָא אֱקַבֵּל קְבִלְתֵּהּ:
@602 וְיִתְקֵף רוּגְזִי וְאֶקְטוֹל יָתְכוֹן בְּחַרְבָּא וִיהֶוְיָן נְשֵׁיכוֹן אַרְמְלִין וּבְנֵיכוֹן יַתְמִין:
@603 אִם כַּסְפָּא תּוֹזֵף בְּעַמִי לְּעַנְיָא דִי עִמָךְ לָא תְהֵי לֵהּ כְּרַשְׁיָא לָא תְשַׁוּוֹן עֲלוֹהִי חִבּוּלְיָא:
@604 אִם מַשְׁכּוֹנָא תִסַב כְּסוּתָא דְחַבְרָךְ עַד מֵעַל שִׁמְשָׁא תְּתִיבִנֵהּ לֵהּ:
@605 אֲרֵי הִיא כְסוּתֵהּ בִּלְחוֹדַהּ הִיא תוֹתְבֵהּ לְמַשְׁכֵּיהּ בְּמָא יִשְׁכּוּב וִיהֵי אֲרֵי יִקְבֵל קֳדָמַי וֶאֱקַבֵּל קְבִלְתֵּהּ אֲרֵי חַנָנָא אֲנָא:
@606 דַיָנָא לָא תְקִיל וְרַבָּא בְעַמָךְ לָא תְלוּט:
@607 בִּכּוּרָךְ וְדִמְעָךְ לָא תְאַחֵר בּוּכְרָא דִבְנָיךְ תַּפְרֵשׁ קֳדָמָי:
@608 כֵּן תַּעְבֵּד לְתוֹרָךְ לְעָנָךְ שִׁבְעָא יוֹמִין יְהֵי עִם אִמֵהּ בְּיוֹמָא תְמִינָאָה תִּפְרְשִׁנֵהּ קֳדָמָי:
@609 וֶאֱנָשִׁין קַדִישִׁין תְּהוֹן קֳדָמָי וּבְשַׂר תְּלִישׁ מִן חֵיוָא חַיְתָא לָא תֵיכְלוּן לְכַלְבָּא תִּרְמוּן יָתֵהּ:
@610 לָא תְקַבֵּל שְׁמַע דִשְׁקָר לָא תְשַׁוִי יְדָךְ עִם חַיָבָא לְמֶהֱוֵי לֵהּ סָהִיד שְׁקָר:
@611 לָא תְהֵי בָּתַר סַגִיאִין לְאַבְאָשָׁא וְלָא תִתִּמְנַע מִלְאַלָפָא מָא דִבְעֵינָךְ עַל דִינָא בָּתַר סַגִיאֵי שְׁלַם דִינָא:
@612 וְעַל מִסְכֵּינָא לָא תְרַחֵם בְּדִינֵהּ:
@613 אֲרֵי תִפְגַע תּוֹרָא דְסָנְאָךְ אוֹ חֲמָרֵהּ דְטָּעֵי אָתָבָא תְּתִיבִנֵהּ לֵהּ:
@614 אֲרֵי תֶחֱזֵי חֲמָרָא דְסָנְאָךְ רְבִיעַ תְּחוֹת טוֹעֲנֵיהּ וְתִתִּמְנַע מִלְמִשְׁבַּק לֵהּ מִשְׁבַּק תִּשְׁבּוֹק מָא דִבְלִבָּךְ עֲלוֹהִי וּתְפָרֵק עִמֵהּ:
@615 לָא תַצְלֵי דִין מִסְכֵּינָךְ בְּדִינֵהּ:
@616 מִפִּתְגָמָא דְשִׁקְרָא הֱוֵי רָחִיק וְדִזְכֵי וְדִי נְפַק (דְכֵי) מִן דִינָא לָא תִקְטוֹל אֲרֵי לָא אֱזַכֵּי חַיָבָא:
@617 וְשׁוֹחֲדָא לָא תְקַבֵּל אֲרֵי שׁוֹחֲדָא מְעַוֵר עֵינֵי חַכִּימִין וּמְקַלְקֵל פִּתְגָמִין תְּרִיצִין:
@618 וְגִיוֹרָא לָא תְעִיקוּן וְאַתּוּן יְדַעְתּוּן יָת נַפְשָׁא דְגִיוֹרָא אֲרֵי דַיָרִין הֲוֵיתוּן בְּאַרְעָא דְמִצְרָיִם:
@619 וְשִׁית שְׁנִין תִּזְרַע יָת אַרְעָךְ וְתִכְנוֹשׁ יָת עֲלַלְתַּהּ:
@620 וּשְׁבִעֵתָא תַּשְׁמְטִּנַהּ וְתַרְטְשִׁנַהּ וְיֵיכְלוּן מִסְכְּנֵי עַמָךְ וּשְׁאָרְהוֹן תֵּיכוּל חֵיוַת בָּרָא כֵּן תַּעְבֵּד לְכַרְמָךְ לְזֵיתָךְ:
@621 שִׁתָּא יוֹמִין תַּעְבֵּד עוֹבָדָיךְ וּבְיוֹמָא שְׁבִיעָאָה תָּנוּחַ בְּדִיל דִינוּחַ תּוֹרָךְ וְחַמָרָךְ וְיִשְּׁקוֹט בַּר אַמְתָךְ וְגִיוֹרָא:
@622 וּבְכֹל דִי אֲמָרִית לְכוֹן תִּסְתַּמְרוּן וְשׁוּם טַעֲוַת עַמְמַיָא לָא תִדְכְּרוּן לָא יִשְׁתְּמַע עַל פּוּמְכוֹן:
@623 תְּלַת זִמְנִין תֵּחוֹג קֳדָמַי בְּשַׁתָּא:
@624 יָת חַגָא דְפַטִירַיָא תִּטַר שִׁבְעָא יוֹמִין תֵּיכוּל פַּטִירָא כְּמָא דִפַקֵידִתָּךְ לִזְמַן יַרְחָא דַאֲבִיבָא אֲרֵי בֵהּ נְפַקְתָּ מִמִצְרָיִם וְלָא יִתְחֲזוּן קֳדָמַי רֵיקָנוּן:
@625 וְחַגָא דַחֲצָדָא בִּכּוּרֵי עוֹבָדָיךְ דִי תִזְרַע בְּחַקְלָא וְחַגָא דִכְנָשָׁא בְּמִפְּקָא דְשַׁתָּא בְּמִכְנְשָׁךְ יָת עוֹבָדָיךְ מִן חַקְלָא:
@626 תְּלַת זִמְנִין בְּשַׁתָּא יִתְחֲזוּן כָּל דְכוּרָךְ קֳדָם רִבּוֹן עָלְמָא יְיָ:
@627 לָא תִכּוֹס עַל חֲמִיעַ דַם פִּסְחִי וְלָא יְבִיתוּן בַּר מִן מַדְבְּחָא תַּרְבֵּי נִכְסַת חַגָא עַד צַפְרָא:
@628 רֵישׁ בִּכּוּרֵי אַרְעָךְ תַּיְתִי לְבֵית מִקְדְשָׁא דַיְיָ אֱלָהָךְ לָא תֵיכְלוּן בְּשַׂר בַּחֲלָב:
@629 הָא אֲנָא שָׁלַח מַלְאָכָא קֳדָמָךְ לְמִטְרָךְ בְּאָרְחָא וּלְאָעֳלוּתָךְ לְאַתְרָא דִאַתְקֵנִית:
@630 אִסְתַּמַּר מִן קֳדָמוֹהִי וְקַבֵּל לְמֵימְרֵהּ לָא תְסָרֵב לְקִבְלֵהּ אֲרֵי לָא יִשְׁבּוֹק לְחוֹבֵיכוֹן אֲרֵי בִשְׁמִי מֵימְרֵהּ:
@631 אֲרֵי אִם קַבָּלָא תְקַבֵּל לְמֵימְרֵהּ וְתַעְבֵּד כֹּל דִאֱמַלֵל וְאֶסְנֵי יָת סָנְאָךְ וְאָעִיק לְדִמְעִיקִין לָךְ:
@632 אֲרֵי יְהַךְ מַלְאָכִי קֳדָמָךְ וְיָעֵלִנָךְ לְוָת אֱמוֹרָאֵי וְחִתָּאֵי וּפְרִיזָאֵי וּכְנַעֲנָאֵי חִוָאֵי וִיבוּסָאֵי וֶאֱשֵׁצִנוּן:
@633 לָא תִסְגוּד לְטַעֲוָתְהוֹן וְלָא תִפְלְחִנוּן וְלָא תַעְבֵּד כְּעוֹבָדֵיהוֹן אֲרֵי פַגָרָא תְּפַגְרִנוּן וְתַבָּרָא תְתַבַּר קָמָתְהוֹן:
@634 וְתִפְלְחוּן קֳדָם יְיָ אֱלָהֲכוֹן וִיבָרֵךְ יָת מֵיכְלָךְ וְיָת מִשְׁתְּיָךְ וְאַעְדִי מַרְעִין בִּישִׁין מִבֵּינָךְ:
@635 לָא תְהֵי מְתַכְּלָא וְעַקְרָא בְּאַרְעָךְ יָת מִנְיַן יוֹמָיךְ אַשְׁלִים:
@636 יָת אֵימְתִי אֲשַׁלַח קֳדָמָךְ ואֶתְּפַר (נ''א וֶאֱשַׁגֵשׁ) יָת כָּל עַמָא דְאַתְּ אָתֵי לַאֲגָחָא בְּהוֹן וְאֶמְסַר יָת כָּל בַּעֲלֵי דְבָבָךְ קֳדָמָךְ מְחַזְרֵי קְדָל:
@637 וְאֶשְׁלַח יָת עֲרָעִיתָא קֳדָמָךְ וּתְתָרֵךְ יָת חִוָאֵי יָת כְּנַעֲנָאֵי וְיָת חִתָּאֵי מִן קֳדָמָךְ:
@638 לָא אֱתָרֵכִנוּן מִן קֳדָמָךְ בְּשַׁתָּא חֲדָא דִילְמָא תְהֵי אַרְעָא צַדְיָא וְתִסְגֵי עֲלָךְ חֵיוַת בָּרָא:
@639 זְעֵיר זְעֵיר אֱתָרֵכִנוּן מִן קֳדָמָךְ עַד דְתִסְגֵי וְתַחְסֵן יָת אַרְעָא:
@640 וֶאֱשַׁוֵי יָת תְּחוּמָךְ מִיַמָא דְסוּף וְעַד יַמָא דִפְלִשְׁתָּאֵי וּמִמַדְבְּרָא עַד פְּרָת אֲרֵי אֶמְסַר בִּידֵיכוֹן יָת יָתְבֵי אַרְעָא וּתְתָרֵכִנוּן מִן קֳדָמָךְ:
@641 לָא תִגְזַר לְהוֹן וּלְּטַעֲוָתְהוֹן קְיָם:
@642 לָא יֵתְבוּן בְּאַרְעָךְ דִילְמָא יְחַיְבוּן יָתָךְ קֳדָמָי אֲרֵי תִפְלַח יָת טַעֲוָתְהוֹן אֲרֵי יְהוֹן לָךְ לְתַקְלָא:
@643 וּלְמשֶׁה אֲמַר סַק לִקֳדָם יְיָ אַתְּ וְאַהֲרֹן נָדָב וַאֲבִיהוּא וְשִׁבְעִין מִסָבֵי יִשְׂרָאֵל וְתִסְגְדוּן מֵרָחִיק:
@644 וְיִתְקְרֵב משֶׁה בִלְחוֹדוֹהִי לִקֳדָם יְיָ וְאִנוּן לָא יִתְקָרְבוּן וְעַמָא לָא יִסְקוּן עִמֵהּ:
@645 וַאֲתָא משֶׁה וְאִשְׁתָּעִי לְעַמָא יָת כָּל פִּתְגָמַיָא דַיְיָ וְיָת כָּל דִינַיָא וַאֲתֵיב כָּל עַמָא קָלָא חַד וַאֲמָרוּ כָּל פִּתְגָמַיָא דִי מַלִיל יְיָ נַעְבֵּד:
@646 וּכְתַב משֶׁה יָת כָּל פִּתְגָמַיָא דַיְיָ וְאַקְדֵם בְּצַפְרָא וּבְנָא מַדְבְּחָא בְּשִׁפּוֹלֵי טוּרָא וְתַרְתָּא עֶשְׂרֵי קָמָן לִתְרֵי עֲסַר שִׁבְטַיָא דְיִשְׂרָאֵל:
@647 וּשְׁלַח יָת בּוּכְרֵי בְּנֵי יִשְׂרָאֵל וְאַסִיקוּ עֲלָוָן וְקָרִיבוּ נִכְסַת קוּדְשִׁין קֳדָם יְיָ תּוֹרִין:
@648 וּנְסִיב משֶׁה פַּלְגוּת דְמָא וְשַׁוִי בְּמִזְרְקַיָא וּפַלְגוּת דְמָא זְרַק עַל מַדְבְּחָא:
@649 וּנְסִיב סִפְרָא דִקְיָמָא וּקְרָא קֳדָם עַמָא וַאֲמָרוּ כֹּל דִי מַלִיל יְיָ נַעְבֵּד וּנְקַבֵּל:
@650 וּנְסִיב משֶׁה יָת דְמָא וּזְרַק עַל מַדְבְּחָא לְכַפָּרָא עַל עַמָא וַאֲמַר הָא דֵין דָם קְיָמָא דִגְזַר יְיָ עִמְכוֹן עַל כָּל פִּתְגָמַיָא הָאִלֵין:
@651 וּסְלֵיק משֶׁה וְאַהֲרֹן נָדָב וַאֲבִיהוּא וְשִׁבְעִין מִסָבֵי יִשְׂרָאֵל:
@652 וַחֲזוֹ יָת יְקַר אֱלָהָא דְיִשְׂרָאֵל וּתְחוֹת כָּרְסָא יְקָרֵהּ כְּעוֹבַד אֶבֶן טָבָא וּכְמֶחֱזֵי שְׁמַיָא לְבָרִירוּ:
@653 וּלְרַבְרְבֵי בְּנֵי יִשְׂרָאֵל לָא הֲוָה נִזְקָא וַחֲזוֹ יָת יְקָרָא דַיְיָ וַהֲווֹ חָדָן בְּקָרְבָּנֵיהוֹן דְאִתְקַבָּלוּ בְּרַעֲוָא כְּאִלוּ אָכְלִין וְשָׁתָן:
@654 וַאֲמַר יְיָ לְמשֶׁה סַק לִקֳדָמַי לְטוּרָא וֶהֱוֵי תַמָן וְאֶתֵּן לָךְ יָת לוּחֵי אַבְנָא וְאוֹרַיְתָא וְתַפְקֶדְתָּא דִכְתָבִית לְאַלוּפֵיהוֹן:
@655 וְקָם משֶׁה וִיהוֹשֻׁעַ מְשֻׁמְשָׁנֵהּ וּסְלֵיק משֶׁה לְטוּרָא דְאִתְגְלִי עֲלוֹהִי יְקָרָא דַיְיָ:
@656 וּלְםָבַיָא אֲמַר אוֹרִיכוּ לָנָא הָכָא עַד דִנְתוּב לְוָתְכוֹן וְהָא אַהֲרֹן וְחוּר עִמְכוֹן מָן דְאִית לֵהּ דִינָא יִתְקְרֵב לִקֳדָמֵיהוֹן:
@657 וּסְלֵק משֶׁה לְטוּרָא וַחֲפָא עֲנָנָא יָת טוּרָא:
@658 וּשְׁרָא יְקָרָא דַיְיָ עַל טוּרָא דְסִינַי וַחֲפָהִי עֲנָנָא שִׁתָּא יוֹמִין וּקְרָא לְמשֶׁה בְּיוֹמָא שְׁבִיעָאָה מִגוֹ עֲנָנָא:
@659 וְחֵיזוּ יְקָרָא דַיְיָ כְּחֵיזוּ אֶשָׁא אָכְלָא בְּרֵישׁ טוּרָא לְעֵינֵי בְּנֵי יִשְׂרָאֵל:
@660 וְעַל משֶׁה בְּגוֹ עֲנָנָא וּסְלֵיק לְטוּרָא וַהֲוָה משֶׁה בְּטּוּרָא אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן: פפפ:
@661 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@662 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְיַפְרְשׁוּן קֳדָמַי אַפְרָשׁוּתָא מִן כָּל גְבַר דִי יִתִּרְעֵי לִבֵּהּ תִּסְבוּן יָת אַפְרָשׁוּתִי:
@663 וְדָא אַפְרָשׁוּתָא דִתִסְבוּן מִנְהוֹן דַהֲבָא וְכַסְפָּא וּנְחָשָׁ א:
@664 וְתִכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ וּמֵעַזֵי:
@665 וּמַשְׁכֵי דְדִכְרֵי מְסַמְקֵי וּמַשְׁכֵי סַסְגוֹנָא וְאָעֵי שִׁטִין:
@666 מִשְׁחָא לְאַנְהָרוּתָא בּוּסְ מַיָא לְמִשְׁחָא דִרְבוּתָא וְלִקְטוֹרֶת בּוּסְמַיָא:
@667 אַבְנֵי בוּרְלָא וְאַבְנֵי אַשְׁלָמוּתָא לְשַׁקָעָא בְאֵפוֹדָא וּבְחוּשְׁנָא:
@668 וְיַעְבְּדוּן קֳדָמַי מִקְדְשָׁא וְאַשְׁרֵי שְׁכִנְתִּי בֵּינֵיהוֹן:
@669 כְּכֹל דִי אֲנָא מַחֲזֵי יָתָךְ יָת דְמוּת מַשְׁכְּנָא וְיָת דְמוּת כָּל מָנוֹהִי וְכֵן תַּעְבְּדוּן:
@670 וְיַעְבְּדוּן אֲרוֹנָא דְאָעֵי שִׁטִּין תַּרְתֵּין אַמִין וּפַלְגָא אֻרְכֵּהּ וְאַמְתָא וּפַלְגָא פְּתָיֵהּ וְאַמְתָא וּפַלְגָא רוּמֵה:
@671 וְתֶחֱפֵי יָתֵהּ דְהַב דְכֵי מִגָו וּמִבָּרָא תַּחֲפִנֵהּ וְתַעְבֵּד עֲלוֹהִי זֵיר דִדְהַב סְחוֹר סְחוֹר:
@672 וְתַתִּיךְ לֵהּ אַרְבַּע עִזְקָן דִדְהַב וְתִתֵּן עַל אַרְבַּע זִוְיָתֵהּ וְתַרְתֵּין עִזְקָן עַל סִטְרֵהּ חַד וְתַרְתֵּן עִזְקָן עַל סִטְרֵהּ תִּנְיֵתָא:
@673 וְתַעְבֵּד אֲרִיחֵי דְאָעֵי שִׁטִּין וְתַחֲפֵי יָתְהוֹן דַהֲבָא:
@674 וְתָעֵל יָת אֲרִיחֲיָא בְּעִזְקָתָא עַל סִטְרֵי אֲרוֹנָא לְמִטַל יָת אֲרוֹנָא בְּהוֹן:
@675 בְּעִזְקְתָא דַאֲרוֹנָא יְהוֹן אֲרִיחַיָא לָא יְעִדוּן מִנֵהּ:
@676 וְתִתֵּן בַּאֲרוֹנָא יָת סַהֲדוּתָא דִי אֶתֵּן לָךְ:
@677 וְתַעְבֵּד כַּפֻּרְתָּא דִדְהַב דְכֵי תַּרְתֵּין אַמִין וּפַלְגָא אֻרְכַּהּ וְאַמְתָא וּפַלְגָא פְּתָיַהּ:
@678 וְתַעְבֵּד תְּרֵין כְּרוּבִין דִדְהָב נְגִיד תַּעְבֵּד יָתְהוֹן מִתְּרֵין סִטְרֵי כַפֻּרְתָּא:
@679 וְעִבֵּד כְּרוּבָא חַד מִסִטְרָא מִכָּא וּכְרוּבָא חַד מִסִטְרָא מִכָּא מִן כַּפֻּרְתָּא תַּעְבְּדוּן יָת כְּרוּבַיָא עַל תְּרֵין סִטְרוֹהִי:
@680 וִיהוֹן כְּרוּבַיָא פְּרִיסָן גַדְפֵיהוֹן לְעֵלָא מְטַלִין בְּגַדְפֵהוֹן עַל כַּפֻּרְתָּא וְאַפֵּיהוֹן חַד לָקֳבֵל חַד לָקֳבֵל כַּפֻּרְתָּא יְהוֹן אַפֵי כְרוּבַיָא:
@681 וְתִתֵּן יָת כַּפֻּרְתָּא עַל אֲרוֹנָא מִלְעֵלָא וּבַאֲרוֹנָא תִּתֵּן יָת סַהֲדוּתָא דִי אֶתֵּן לָךְ:
@682 וֶאֱזַמֵן מֵימְרִי לָךְ תַּמָן וֶאֱמַלֵל עִמָךְ מֵעִלָוֵי כַפֻּרְתָּא מִבֵּין תְּרֵין כְּרוּבַיָא דִי עַל אֲרוֹנָא דְסַהֲדוּתָא יָת כָּל דִי אֲפַקֵד יָתָךְ לְוָת בְּנֵי יִשְׂרָאֵל:
@683 וְתַעְבֵּד פָּתוֹרָא דְאָעֵי שִׁטִּין תַּרְתֵּין אַמִין אֻרְכֵּהּ וְאַמְתָא פְתָיֵהּ וְאַמְתָא וּפַלְגָא רוּמֵהּ:
@684 וְתַחֲפֵי יָתֵהּ דְהַב דְכֵי וְתַעְבֵּד לֵהּ זֵיר דִדְהַב סְחוֹר סְחוֹר:
@685 וְתַעְבֵּד לֵהּ גְדַנְפָא רוּמֵהּ פֻּשְׁכָּא סְחוֹר סְחוֹר וְתַעְבֵּד זֵיר דִדְהַב לִגְדַנְפֵהּ סְחוֹר סְחוֹר:
@686 וְתַעְבֵּד לֵהּ אַרְבַּע עִזְקָן דִדְהָב וְתִתֵּן יָת עִזְקָתָא עַל אַרְבַּע זִיוְיָתָא דִי לְאַרְבַּע רַגְלוֹהִי:
@687 לָקֳבֵל גְדַנְפָא יְהֶוְיָן עִזְקָתָא לְאַתְרָא לַאֲרִיחַיָא לְמִטַל יָת פָּתוֹרָא:
@688 וְתַעְבֵּד יָת אֲרִיחַיָא דְאָעֵי שִׁיטִין וְתַחֲפֵי יָתְהוֹן דַהֲבָא וִיהוֹן נָטְלִין בְּהוֹן יָת פָּתוֹרָא:
@689 וְתַעְבֵּד מָגִיסוֹהִי וּבָזִכּוֹהִי וְקַסְוָתֵהּ וּמְכִילָתֵהּ דְיִתְנַסַךְ בְּהֵן דְהַב דְכֵי תַּעְבֵּד יָתְהוֹן:
@690 וְתִתֵּן עַל פָּתוֹרָא לְחֵם אַפַּיָא קֳדָמַי תְּדִירָא:
@691 וְתַעְבֵּד מְנַרְתָּא דִדְהַב דְכֵי נְגִיד תִּתְעֲבֵד מְנַרְתָּא שִׁדַהּ וּקְנַהּ כַּלִידָהָא חֵזוּרָהָא וְשׁוֹשַׁנָהָא מִנַהּ יְהוֹן:
@692 וְשִׁתָּא קְנִין נָפְקִין מִסִטְרָהָא תְּלָתָא קְנֵי מְנַרְתָּא מִסִטְרַהּ חַד וּתְלָתָא קְנֵי מְנַרְתָּא מִסִטְרַהּ תִּנְיָנָא:
@693 תְּלָתָא כַלִידִין מְצַיְרִין בְּקַנְיָא חַד חֵזוּר וְשׁוֹשַׁן וּתְלָתָא כַלִידִין מְצַיְרִין בְּקַנְיָא חַד חֵזוּר וְשׁוֹשָׁן כֵּן לְשִׁתָּא קְנִין דְנָפְקִין מִן מְנַרְתָּא:
@694 וּבִמְנַרְתָּא אַרְבְּעָא כַלִידִין מְצַיְרִין חֵזוּרָהָא וְשׁוֹשַׁנָהָא:
@695 וְחֵזוּר תְּחוֹת תְּרֵין קְנִין מִנַהּ וְחֵזוּר תְּחוֹת תְּרֵין קְנִין מִנַהּ וְחֵזוּר תְּחוֹת תְּרֵין קְנִין מִנַהּ לְשִׁתָּא קְנִין דְנָפְקִין מִן מְנַרְתָּא:
@696 חֵזוּרֵיהוֹן וּקְנֵיהוֹן מִנַהּ יְהוֹן כֻּלַהּ נְגִידָא חֲדָא דִדְהַב דְכֵי:
@697 וְתַעְבֵּד יָת בּוֹצִינָהָא שִׁבְעָא וְתַדְלֵק יָת בּוֹצִינָהָא וִיהוֹן מְנַהֲרִין עַל קֳבֵל אַפָּהָא:
@698 וְצִבְיְתָהָא וּמַחְתְּיָתָהָא דִדְהַב דְכֵי:
@699 כִּכְּרָא דִדְהַב דְכֵי יַעְבֵּד יָתַהּ יָת כָּל מָנַיָא הָאִלֵין:
@700 וַחֲזֵי וַעֲבֵיד כִּדְמוּתְהוֹן דִאַתְּ מִתְחֲזִי בְּטוּרָא:
@701 וְיָת מַשְׁכְּנָא תַּעְבֵּד עֲשַׂר יְרִיעָן דְבוּץ שְׁזִיר וְתִכְלָא וְאַרְגְּוָנָא וּצְבַע זְהוֹרִי צוּרַת כְּרוּבִין עוֹבַד אֳמָן תַּעְבֵּד יָתְהוֹן:
@702 אֻרְכָּא דִירִיעֲתָא חֲדָא עַשְׂרִין וְתַמְנֵי אַמִין וּפוּתְיָא אַרְבַּע אַמִין דִירִיעֲתָא חֲדָא מְשַׁחְתָּא חֲדָא לְכָל יְרִיעֲתָא:
@703 חֲמֵשׁ יְרִיעָן יְהֶוְיָן מְלַפְּפָן חֲדָא עִם חֲדָא וַחֲמֵשׁ יְרִיעָן מְלַפְּפָן חֲדָא עִם חֲדָא:
@704 וְתַעְבֵּד עֲנוּבִין דְתִכְלָא עַל שִׂפְתָא דִירִיעֲתָא חֲדָא מִסִטְרָא בֵּית לוֹפֵי וְכֵן תַּעְבֵּד בְּשִׂפְתָא דִירִיעֲתָא בְּסִטְרָא דְבֵית לוֹפֵי תִּנְיֵתָא:
@705 חַמְשִׁין עֲנוּבִין תַּעְבֵּד בִּירִיעֲתָא חֲדָא וְחַמְשִׁין עֲנוּבִין תַּעְבֵּד בְּסִטְרָא דִירִיעֲתָא דְבֵית לוֹפֵי תִּנְיָנָא מְכַוְנָן עֲנוּבַיָא חֲדָא לָקֳבֵל חֲדָא:
@706 וְתַעְבֵּד חַמְשִׁין פּוּרְפִין דִדְהָב וּתְלָפֵף יָת יְרִיעֲתָא חֲדָא עִם חֲדָא בְּפּוּרְפַיָא וִיהֵי מַשְׁכְּנָא חָד:
@707 וְתַעְבֵּד יְרִיעָן מְעַזֵי לִפְרָסָא עַל מַשְׁכְּנָא חֲדָא עֶסְרֵי יְרִיעָן תַּעְבֵּד יָתְהוֹן:
@708 אֻרְכָּא דִירִיעֲתָא חֲדָא תְּלָתִין אַמִין וּפוּתְיָא אַרְבַּע אַמִין דִירִיעֲתָא חֲדָא מְשַׁחְתָּא חֲדָא לַחֲדָא עֶסְרֵי יְרִיעָן:
@709 וּתְלָפֵף יָת חֲמֵשׁ יְרִיעָן לְחוֹד וְיָת שִׁית יְרִיעָן לְחוֹד וְתֵיעוּף יָת יְרִיעֲתָא שְׁתִיתֵיתָא לָקֳבֵל אַפֵּי מַשְׁכְּנָא:
@710 וְתַעְבֵּד חַמְשִׁין עֲנוּבִין עַל שִׂפְתָא דִירִיעֲתָא חֲדָא בְּסִטְּרָא בֵּית לוֹפֵי וְחַמְשִׁין עֲנוּבִין עַל שִׂפְתָא דִירִיעֲתָא דְבֵית לוֹפֵי תִּנְיֵתָא:
@711 וְתַעְבֵּד פּוּרְפִין דִנְחָשָׁא חַמְשִׁין וְתָעֵיל יָת פּוּרְפַיָא בַּעֲנוּבַיָא וּתְלָפֵף יָת מַשְׁכְּנָא וִיהֵי חָד:
@712 וְסִרְחָא דְיַתִּירָא בִּירִיעַת מַשְׁכְּנָא פַּלְגוּת יְרִיעֲתָא דְיַתִּירָא תִּסְרַח עַל אֲחוֹרֵי מַשְׁכְּנָא:
@713 וְאַמְתָא מִכָּא וְאַמְתָא מִכָּא בִּדְיַתִּירָא בְּאֻרְכָּא יְרִיעֲתָא דְמַשְׁכְּנָא יְהֵי סְרִיחַ עַל סִטְרֵי מַשְׁכְּנָא מִכָּא וּמִכָּא לְכַסָיוּתֵהּ:
@714 וְתַעְבֵּד חוֹפָאָה לִפְרָסָא מַשְׁכֵי דְדִכְרֵי מְסַמְקֵי וְחוֹפָאָה מַשְׁכֵי דְסַסְגוֹנָא מִלְעֵלָא:
@715 וְתַעְבֵּד יָת דַפַּיָא לְמַשְׁכְּנָא דְאָעֵי שִטִין קָיְמִין:
@716 עֲשַׂר אַמִין אֻרְכָּא דְדַפָּא וְאַמְתָא וּפַלְגוּת אַמְתָא פּוּתְיָא דְדַפָּא חָד:
@717 תַּרְתֵּין צִירִין לְדַפָּא חַד מְשַׁלְבִין חֲדָא לָקֳבֵל חֲדָא כֵּן תַּעְבֵּד לְכֹל דַפֵּי מַשְׁכְּנָא:
@718 וְתַעְבֵּד יָת דַפַּיָא לְמַשְׁכְּנָא עַסְרִין דַפִּין לְרוּחַ עֵבַר דְרוֹמָא:
@719 וְאַרְבְּעִין סַמְכִין דִכְסַף תַּעְבֵּד תְּחוֹת עַסְרִין דַפִּין תְּרֵין סַמְכִין תְּחוֹת דַפָּא חַד לִתְרֵין צִירוֹהִי וּתְרֵין סַמְכִין תְּחוֹת דַפָּא חַד לִתְרֵין צִירוֹהִי:
@720 וְלִסְטַר מַשְׁכְּנָא תִּנְיֵתָא לְרוּחַ צִפּוּנָא עֶסְרִין דַפִּין:
@721 וְאַרְבְּעִין סַמְכֵיהוֹן דִכְסַף תְּרֵין סַמְכִין תְּחוֹת דַפָּא חַד וּתְרֵין סַמְכִין תְּחוֹת דַפָּא חָד:
@722 וְלִסְיָפֵי מַשְׁכְּנָא מַעַרְבָא תַּעְבֵּד שִׁתָּא דַפִּין:
@723 וּתְרֵין דַפִּין תַּעְבֵּד לְזָוְיַת מַשְׁכְּנָא בְּסוֹפֵיהוֹן:
@724 וִיהוֹן מְכַוְנִין מִלְרַע וְכַחֲדָא יְהוֹן מְכַוְנִין עַל רֵישֵׁהּ לְעִזְקְתָא חֲדָא כֵּן יְהֵי לְתַרְוֵיהוֹן לִתְרֵין זָוְיָן יְהוֹן:
@725 וִיהוֹן תְּמַנְיָא דַפִּין וְסַמְכֵיהוֹן דִכְסַף שִׁתָּא עֲשַׂר סַמְכִין תְּרֵין סַמְכִין תְּחוֹת דַפָּא חַד וּתְרֵין סַמְכִין תְּחוֹת דַפָּא חָד:
@726 וְתַעְבֵּד עַבְּרֵי דְאָעֵי שִׁטִין חַמְשָׁא לְדַפֵּי סְטַּר מַשְׁכְּנָא חָד:
@727 וְחַמְשָׁא עַבְּרִין לְדַפֵּי סְטַר מַשְׁכְּנָא תִּנְיֵתָא וְחַמְשָׁא עַבְּרִין לְדַפֵּי סְטַּר מַשְׁכְּנָא לְסוֹפֵיהוֹן מַעַרְבָא:
@728 וְעַבְּרָא מְצִיעָאָה בְּגוֹ דַפַּיָא מַעְבַר מִן סְיָפֵי לִסְיָפֵי:
@729 וְיָת דַפַּיָא תַּחְפֵּי דַהֲבָא וְיָת עִזְקָתְהוֹן תַּעְבֵּד דַהֲבָא אַתְרָא לְעַבְרַיָא וְתַחְפֵּי יָת עַבְּרַיָא דַהֲבָא:
@730 וּתְקִים יָת מַשְׁכְּנָא כְּהִלְכְתֵהּ דִי אִתְחֲזֵיתָא בְּטוּרָא:
@731 וְתַעְבֵּד פָּרֻכְתָּא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר עוֹבַד אֳמָן יַעְבֵּד יָתַהּ צוּרַת כְּרוּבִין:
@732 וְתִתֵּן יָתַהּ עַל אַרְבְּעָא עַמוּדֵי שִׁטִין מְחַפְּיָן דַהֲבָא וָוֵיהוֹן דַהֲבָא עַל אַרְבְּעָא סַמְכֵי דִכְסָף:
@733 וְתִתֵּן יָת פָּרֻכְתָּא תְּחוֹת פּוּרְפַיָא וְתָעֵיל תַּמָן מִגָּו לְפָרֻכְתָּא יָת אֲרוֹנָא דְסַהֲדוּתָא וְתַפְרֵשׁ פָּרֻכְתָּא לְכוֹן בֵּין קוּדְשָׁא וּבֵין קֹדֶשׁ קוּדְשַׁיָא:
@734 וְתִתֵּן יָת כַּפֻּרְתָּא עַל אֲרוֹנָא דְסַהֲדוּתָא בְּקֹדֶשׁ קוּדְשַׁיָא:
@735 וּתְשַׁוִי יָת פָּתוֹרָא מִבָּרָא לְפָרֻכְתָּא וְיָת מְנַרְתָּא לָקֳבֵל פָּתוֹרָא עַל צִדָּא דְמַשְּׁכְּנָא דָרוֹמָא וּפָתוֹרָא תִתֵּן עַל סְטַר צִפּוּנָא:
@736 וְתַעְבֵּד פְּרָסָא לִתְרַע מַשְׁכְּנָא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר עוֹבַד צַיָר:
@737 וְתַעְבֵּד לִפְרָסָא חַמְשָׁא עַמוּדֵי שִׁטִין וְתַחֲפֵי יָתְהוֹן דַהֲבָא וָוֵיהוֹן דַהֲבָא וְתַתִּיךְ לְהוֹן חַמְשָׁא סַמְכֵי נְחָשָׁא:
@738 וְתַעְבֵּד יָת מַדְבְּחָא דְאָעֵי שִׁטִין חֲמֵשׁ אַמִין אֻרְכָּא וַחֲמֵשׁ אַמִין פּוּתְיָא מְרַבַּע יְהֵי מַדְבְּחָא וּתְלַת אַמִין רוּמֵהּ:
@739 וְתַעְבֵּד קַרְנוֹהִי עַל אַרְבַּע זִוְיָתֵהּ מִנֵהּ תְּהֶוְיָן קַרְנוֹהִי וְתַחֲפֵי יָתֵהּ נְחָשָׁא:
@740 וְתַעְבֵּד פְּסַכְתְּרָוָתֵהּ לְמִסְפֵי קִטְּמֵיהּ וּמַגְרוֹפְיָתֵהּ וּמִזְרְקָתֵהּ וְצִנוּרְיָתֵהּ וּמַחְתְּיָתֵהּ לְכָל מָנוֹהִי תַּעְבֵּד נְחָשָׁא:
@741 וְתַעְבֵּד לֵהּ סְרָדָא עוֹבַד מְצַדְתָּא דִנְחָשָׁא וְתַעְבֵּד עַל מְצַדְתָּא אַרְבַּע עִזְקָן דִנְחָשָׁא עַל אַרְבַּע סִטְּרוֹהִי:
@742 וְתִתֵּן יָתַהּ תְּחוֹת סוֹבָבֵי מַדְבְּחָא מִלְרָע וּתְהֵי מְצַדְתָּא עַד פַּלְגוּת מַדְבְּחָא:
@743 וְתַעְבֵּד אֲרִיחַיָא לְמַדְבְּחָא אֲרִיחֵי דְאָעֵי שִׁטִין וְתַחֲפֵי יָתְהוֹן נְחָשָׁא:
@744 וְיָעֵל יָת אֲרִיחוֹהִי בְּעִזְקָתָא וִיהוֹן אֲרִיחַיָא עַל תְּרֵין סִטְרֵי מַדְבְּחָא בְּמִטַל יָתֵהּ:
@745 חֲלִיל לוּחֵי תַּעְבֵּד יָתֵהּ כְּמָא דִי אַחֲזִי יָתָךְ בְּטוּרָא כֵּן יַעְבְּדוּן:
@746 וְתַעְבֵּד יָת דָרַת מַשְׁכְּנָא לְרוּחַ עֵבַר דָרוֹמָא סְרָדִין לְדָרְתָּא דְבוּץ שְׁזִיר מְאָה בְאַמִין אֻרְכָּא לְעֵבֶר חָד:
@747 וְעַמוּדוֹהִי עֶשְׂרִין וְסַמְכֵיהוֹן עֶשְׂרִין נְחָשָׁא וָוֵי עַמוּדַיָא וְכִבּוּשֵׁיהוֹן כְּסָף:
@748 וְכֵן לְרוּחַ צִפּוּנָא בְּאֻרְכָּא סְרָדִין מְאָה אֻרְכָּא וְעַמוּדוֹהִי עֶשְׂרִין וְסַמְכֵיהוֹן עֶשְׂרִין נְחָשָׁא וָוֵי עַמוּדַיָא וְכִבּוּשֵׁהוֹן דִכְסָף:
@749 וּפוּתְיָא דְדַרְתָּא לְרוּחַ מַעַרְבָא סְרָדִין חַמְשִׁין אַמִין עַמוּדֵיהוֹן עַשְׂרָא וְסַמְכֵיהוֹן עַשְׂרָא:
@750 וּפוּתְיָא דְדַרְתָּא לְרוּחַ קִדוּמָא מַדִינְחָא חַמְשִׁין אַמִין:
@751 וַחֲמֵשׁ עֶשְׂרֵי אַמִין סְרָדִין לְעִבְרָא עַמוּדֵיהוֹן תְּלָתָא וְסַמְכֵיהוֹן תְּלָתָא:
@752 וּלְעִבְרָא תִּנְיָנָא חֲמֵשׁ עֶשְׂרֵי סְרָדִין עֲמוּדֵיהוֹן תְּלָתָא וְסַמְכֵיהוֹן תְּלָתָא:
@753 וְלִתְרַע דַרְתָּא פְּרָסָא עֶשְׂרִין אַמִין תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר עוֹבַד צַיָר עַמוּדֵיהוֹן אַרְבְּעָא וְסַמְכֵיהוֹן אַרְבְּעָא:
@754 כָּל עַמוּדֵי דַרְתָּא סְחוֹר סְחוֹר מְכַבְּשִׁין כְּסַף וָוֵיהוֹן כְּסַף וְסַמְכֵיהוֹן נְחָשָׁא:
@755 אֻרְכָּא דְדַרְתָּא מְאָהּ בְאַמִין וּפוּתְיָא חַמְשִׁין בְּחַמְשִׁין וְרוּמָא חֲמֵשׁ אַמִין דְבוּץ שְׁזִיר וְסַמְכֵיהוֹן נְחָשָׁא:
@756 לְכֹל מָאנֵי מַשְׁכְּנָא בְּכֹל פָּלְחָנֵהּ וְכָל סִכּוֹהִי וְכָל סִכֵּי דְדַרְתָּא נְחָשָׁא:ססס:
@757 וְאַתְּ תְּפַקֵד יָת בְּנֵי יִשְׂרָאֵל וְיִסְבוּן לָךְ מִשְׁחָא זֵיתָא דַכְיָא כָּתִישָׁא לְאַנְהָרָא לְאַדְלָקָא בוֹצִינַיָא תְּדִירָא:
@758 בְּמַשְׁכַּן זִמְנָא מִבָּרָא לְפָרֻכְתָּא דְעַל סַהֲדוּתָא יְסַדַר יָתֵהּ אַהֲרֹן וּבְנוֹהִי מֵרַמְשָׁא עַד צַפְרָא קָדָם יְיָ קְיָם עֲלָם לְדָרֵיהוֹן מִן בְּנֵי יִשְׂרָאֵל:וְ
@759 אַתְּ קָרֵב לְוָתָךְ יָת אַהֲרֹן אָחוּךְ וְיָת בְּנוֹהִי עִמֵהּ מִגוֹ בְּנֵי יִשְׂרָאֵל לְשַׁמָשָׁא קֳדָמַי אַהֲרֹן נָדָב וַאֲבִיהוּא אֶלְעָזָר וְאִיתָמָר בְּנֵי אַהֲרֹן:
@760 וְתַעְבֵּד לְבוּשֵׁי קוּדְשָׁא לְאַהֲרֹן אָחוּךְ לִיקָר וּלְתֻשְׁבְּחָן:
@761 וְאַתְּ תְּמַלֵל עִם כָּל חַכִּימֵי לִבָּא דְאַשְׁלֵמִית עִמֵהּ רוּחַ חָכְמְתָא וְיַעְבְּדוּן יָת לְבוּשֵׁי אַהֲרֹן לְקַדָשׁוּתֵהּ לְשַׁמָשָׁא קֳדָמַי:
@762 וְאִלֵין לְבוּשַׁיָא דִי יַעְבְּדוּן חוּשְׁנָא וְאֵפוֹדָא וּמְעִילָא וְכִתּוּנָא מְרַמְצָא מִצְנֶפְתָּא וְהֶמְיָנָא וְיַעְבְּדוּן לְבוּשֵׁי קוּדְשָׁא לְאַהֲרֹן אָחוּךְ וְלִבְנוֹהִי לְשַׁמָשָׁא קֳדָמַי:
@763 וְאִנוּן יִסְבוּן יָת דַהֲבָא וְיָת תִּכְלָא וְיָת אַרְגְוָנָא וְיָת צְבַע זְהוֹרִי וְיָת בּוּצָא:
@764 וְיַעְבְּדוּן יָת אֵפוֹדָא דַהֲבָא תִּכְלָא וְאַרְגְוָנָא צְבַע זְהוֹרִי וּבוּץ שְׁזִיר עוֹבַד אֳמָן:
@765 תַּרְתֵּין כַּתְפִּין מְלַפְּפָן יְהוֹן לֵהּ עַל תְּרֵין סִטְרוֹהִי וְיִתְלָפַף:
@766 וְהֶמְיַן תִּקוּנֵי דִי עֲלוֹהִי כְּעוֹבָדוֹהִי מִנֵהּ יְהֵי דַהֲבָא תִּכְלָא וְאַרְגְּוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר:
@767 וְתִסַב יָת תַּרְתֵּין אַבְנֵי בוּרְלָא וְתִגְלוֹף עֲלֵיהֶן שְׁמָהַת בְּנֵי יִשְׂרָאֵל:
@768 שִׁתָּא מִשְׁמָהָתְהוֹן עַל אַבְנָא חֲדָא וְיָת שְׁמָהַת שִׁתָּא דְאִשְׁתָּאָרוּ עַל אַבְנָא תִנְיֵתָא כְּתוּלְדָתְהוֹן:
@769 עוֹבַד אֳמָן אֶבֶן טָבָא כְּתַב מְפָרַשׁ כִּגְלֹף דְעִזְקָא תִגְלוֹף יָת תַּרְתֵּין אַבְנַיָא עַל שְׁמָהַת בְּנֵי יִשְׂרָאֵל מְשַׁקְעָן מְרַמְצָן דִדְהַב תַּעְבֵּד יָתְהוֹן:
@770 וּתְשַׁוִּי יָת תַּרְתֵּין אַבְנַיָא עַל כִּתְפֵּי אֵפוֹדָא אַבְנֵי דָכְרָנָא לִבְנֵי יִשְׂרָאֵל וְיִטּוֹל אַהֲרֹן יָת שְׁמָהָתְהוֹן קֳדָם יְיָ עַל תְּרֵין כִּתְפּוֹהִי לְדָכְרָנָא:
@771 וְתַעְבֵּד מְרַמְצָן דִדְהַב:
@772 וְתַרְתֵּין תִּכִּין דְהַב דְכֵי מְתַחְמָן תַּעְבֵד יָתְהוֹן עוֹבַד גְדִילוּ וְתִתֵּן יָת תִּכַּיָא גְדִילָתָא עַל מְרַמְצָתָא:
@773 וְתַעְבֵּד חשֶׁן דִינָא עוֹבַד אֳמָן כְּעוֹבַד אֵפוֹדָא תַּעְבְּדִנֵהּ דַהֲבָא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר תַּעְבֵּד יָתֵהּ:
@774 מְרַבַּע יְהֵי עֵיף זֶרְתָּא אֻרְכֵּה וְזֶרְתָּא פְתָיֵהּ:
@775 וְתַשְׁלֵם בֵּה אַשְׁלָמוּת אַבְנָא אַרְבְּעָא סִדְרִין אֶבֶן טָּבָא סִדְרָא קַדְמָאָה םַמְקָן יַרְקָן וּבַרְקָן סִדְרָא חָד:
@776 וְסִדְרָא תִּנְיָנָא אִזְמָרַגְדִין וְשַׁבְזִיז וְסִבְהֲלוֹם:
@777 וְסִדְרָא תְּלִיתָאָה קַנְכִּירֵי טַרְקְיָא וְעֵין עֶגְלָא:
@778 וְסִדְרֵא רְבִיעָאָה כְּרוּם יַמָא וּבוּרְלָא וּפַנְטֵרֵי מְרַמְצָן דִדְהַב יְהוֹן בְּאַשְׁלָמוּתְהוֹן:
@779 וְאַבְנַיָא יְהֶוְיַן עַל שְׁמָהַת בְּנֵי יִשְׂרָאֵל תַּרְתֵּי עֶסְרֵי עַל שְׁמָהַתְהוֹן כְּתַב מְפָרַשׁ כִּגְלוֹף דְעִזְקָא גְבַר עַל שְׁמֵהּ תְּהֶוְיָן לִתְרֵין עֲסַר שִׁבְטִין:
@780 וְתַעְבֵּד עַל חוּשְׁנָא תִּכִּין מְתַחְמָן עוֹבַד גְדִילוּ דְהַב דְכֵי:
@781 וְתַעְבֵּד עַל חוּשְׁנָא תַּרְתֵּין עִזְקָן דִדְהַב וְתִתֵּן יָת תַּרְתֵּין עִזְקָתָא עַל תְּרֵין סִטְרֵי חוּשְׁנָא:
@782 וְתִתֵּן יָת תַּרְתֵּין גְדִילָן דִדְהַב עַל תַּרְתֵּין עִזְקָתָא לְסִטְרֵי חוּשְׁנָא:
@783 וְיָת תַּרְתֵּין גְדִילָן דְעַל תַּרְתֵּין סִטְרוֹהִי תִּתֵּן עַל תַּרְתֵּין מְרַמְצָתָא וְתִתֵּן עַל כִּתְפֵּי אֵפוֹדָא לָקֳבֵל אַפּוֹהִי:
@784 וְתַעְבֵּד תַּרְתֵּין עִזְקָן דִדְהַב וּתְשַׁוִּי יָתְהוֹן עַל תְּרֵין סִטְרֵי חוּשְׁנָא עַל סִפְתֵהּ דִי לְעִבְרָא דְאֵפוֹדָא מִלְגָו:
@785 וְתַעְבֵּד תַּרְתֵּין עִזְקָן דִדְהַב וְתִתֵּן יָתְהוֹן עַל תַּרְתֵּין כִּתְפֵּי אֵפוֹדָא מִלְרַע מִלְקֳבֵל אַפּוֹהִי לָקֳבֵל בֵּית לוֹפֵי מֵעִלָוֵי לְהֶמְיַן אֵפוֹדָא:
@786 וְיֶחְדוּן יָת חוּשְׁנָא מֵעִזְקְתֵהּ לְעִזְקְתָא דְאֵפוֹדָא בְּחוּטָא דִתְכֶלְתָּא לְמֶהֱוֵי עַל הֶמְיַן אֵפוֹדָא וְלָא יִתְפָּרֵק חוּשְׁנָא מֵעִלָוֵי אֵפוֹדָא:
@787 וְיִטוֹל אַהֲרֹן יָת שְׁמָהַת בְּנֵי יִשְׂרָאֵל בְּחשֶׁן דִינָא עַל לִבֵּהּ בְּמֵעֲלֵהּ לְקוּדְשָׁא לְדוּכְרָנָא קֳדָם יְיָ תְּדִירָא:
@788 וְתִתֵּן בְּחשֶׁן דִינָא יָת אוּרַיָא וְיָת תֻּמַיָא וִיהוֹן עַל לִבָּא דְאַהֲרֹן בְּמֵעֲלֵהּ קֳדָם יְיָ וְיִטוֹל אַהֲרֹן יָת דִינָא דִבְנֵי יִשְׂרָאֵל עַל לִבֵּהּ קֳדָם יְיָ תְּדִירָא:
@789 וְתַעְבֵּד יָת מְעִילָא דְאֵפוֹדָא גְמִיר תִּכְלָא:
@790 וִיהֵי פוּם רֵישֵׁהּ כָּפִיל לְגַוֵּהּ תּוֹרָא יְהֵא מַקַף לְפוּמֵהּ סְחוֹר סְחוֹר עוֹבַד מָחֵי כְּפוּם שִׂרְיָן יְהֵי לֵהּ לָא יִתְבְּזָע:
@791 וְתַעְבֵּד עַל שִׁיפוֹלוֹהִי רִמוֹנֵי תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי עַל שִׁיפוֹלוֹהִי סְחוֹר סְחוֹר וְזַגִין דְדַהֲבָא בֵּינֵיהוֹן סְחוֹר סְחוֹר:
@792 זַגָא דְדַהֲבָא וְרִמוֹנָא זַגָא דְדַהֲבָא וְרִמוֹנָא עַל שִׁיפוֹלֵי מְעִילָא סְחוֹר סְחוֹר:
@793 וִיהֵי עַל אַהֲרֹן לְשַׁמָשָׁא וְיִשְׁתְּמַע קָלֵהּ בְּמֵעֲלֵהּ לְקוּדְשָׁא קֳדָם יְיָ וּבְמִפְקֵהּ וְלָא יְמוּת:
@794 וְתַעְבֵּד צִיצָא דִדְהַב דְכֵי וְתִגְלוֹף עֲלוֹהִי כְּתַב מִפָרַשׁ קֹדֶשׁ לַיָי:
@795 וּתְשַׁוִי יָתֵהּ עַל חוּטָא דִתְכֶלְתָּא וִיהֵי עַל מִצְנֶפְתָּא לָקֳבֵל אַפֵּי מִצְנֶפְתָּא יְהֵי:
@796 וִיהֵי עַל בֵּית עֵינוֹהִי דְאַהֲרֹן וְיִטּוֹל אַהֲרֹן יָת עֲוָיַת קוּדְשַׁיָא דִי יְקַדְשׁוּן בְּנֵי יִשְׂרָאֵל לְכָל מַתְּנַּת קוּדְשֵׁיהוֹן וִיהֵי עַל בֵּית עֵינוֹהִי תְּדִירָא לְרַעֲוָא לְהוֹן קֳדָם יְיָ:
@797 וּתְרַמֵץ כִּתּוּנָא בוּצָא וְתַעְבֵּד מִצְנֶפְתָּא דְבוּצָא וְהֶמְיָנָא תַּעְבֵּד עוֹבַד צַיָר:
@798 וְלִבְנֵי אַהֲרֹן תַּעְבֵּד כִּתּוּנִין וְתַעְבֵּד לְהוֹן הֶמְיָנִין וְכוֹבָעִין תַּעְבֵּד לְהוֹן לִיקָר וּלְתֻשְׁבְּחָן:
@799 וְתַלְבֵּש יָתְהוֹן יָת אַהֲרֹן אָחוּךְ וְיָת בְּנוֹהִי עִמֵהּ וּתְרַבֵּי יָתְהוֹן וּתְקָרֵב יָת קֻרְבָּנְהוֹן וּתְקַדֵשׁ יָתְהוֹן וִישַׁמְשׁוּן קֳדָמַי:
@800 וְעִבֵד לְהוֹן מִכְנְסִין דְבוּץ לְכַסָאָה בְשַׂר עֶרְיְתָא מֵחַרְצָן וְעַד יַרְכָּן יְהוֹן:
@801 וִיהוֹן עַל אַהֲרֹן וְעַל בְּנוֹהִי בְּמֵעַלְהוֹן לְּמַשְׁכַּן זִמְנָא אוֹ בְמִקְרָבְהוֹן לְמַדְבְּחָא לְשַׁמָשָׁא בְקוּדְשָׁא וְלָא יְקַבְּלוּן חוֹבָא וִימוּתוּן קְיָם עָלָם לֵהּ וְלִבְנוֹהִי בַתְרוֹהִי:
@802 וְדֵין פִּתְגָמָא דִי תַעְבֵּד לְהוֹן לְקַדָשָׁא יָתְהוֹן לְשַׁמָשָׁא קֳדָמַי סַב תּוֹר חָד בַּר תּוֹרֵי וְדִכְרִין תְּרֵין שַׁלְמִין:
@803 וּלְחֵם פַּטִיר וּגְרִיצִין פַּטִּירִין דְפִילָן בִּמְשַׁח וְאֶסְפּוֹגִין פַּטִּירִין דִמְשִׁיחִין בִּמְשָׁח סֻלְתָּא חִטִין תַּעְבֵּד יָתְהוֹן:
@804 וְתִתֵּן יָתְהוֹן עַל סַלָא חַד וּתְקָרֵב יָתְהוֹן בְּסַלָא וְיָת תּוֹרָא וְיָת תְּרֵין דִכְרִין:
@805 וְיָת אַהֲרֹן וְיָת בְּנוֹהִי תְּקָרֵב לִתְרַע מַשְׁכַּן זִמְנָא וְתַסְחֵי יָתְהוֹן בְּמַיָא:
@806 וְתִסַב יָת לְבוּשַׁיָא וְתַלְבֵּשׁ יָת אַהֲרֹן יָת כִּתּוּנָא וְיָת מְעִיל אֵפוֹדָא וְיָת אֵפוֹדָא וְיָת חוּשְׁנָא וְתַתְקֵן לֵהּ בְּהֶמְיַן אֵפוֹדָא:
@807 וּתְשַׁוִי מִצְנֶפְתָּא עַל רֵישֵׁהּ וְתִתֵּן יָת כְּלִילָא דְקוּדְשָׁא עַל מִצְנֶפְתָּא:
@808 וְתִסַב יָת מִשְׁחָא דִרְבוּתָא וּתְרִיק עַל רֵישֵׁהּ וּתְרַבֵּהּ יָתֵהּ:
@809 וְיָת בְּנוֹהִי תְּקָרֵב וְתַלְבֵּשִׁנוּן כִּתּוּנִין:
@810 וּתְזָרֵז יָתְהוֹן הֶמְיָנִין אַהֲרֹן וּבְנוֹהִי וְתַתְקֵן לְהוֹן כּוֹבָעִין וּתְהֵי לְהוֹן כְּהֻנְתָּא לִקְיַם עָלָם וּתְקָרֵב קֻרְבָּנָא דְאַהֲרֹן וְקֻרְבָּנָא דִבְנוֹהִי:
@811 וּתְקָרֵב יָת תּוֹרָא לִקֳדָם מַשְׁכַּן זִמְנָא וְיִסְמוֹךְ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ תּוֹרָא:
@812 וְתִכּוֹס יָת תּוֹרָא קֳדָם יְיָ בִּתְרַע מַשְׁכַּן זִמְנָא:
@813 וְתִסַב מִדְמָא דְתוֹרָא וְתִתֵּן עַל קַרְנַת מַדְבְּחָא בְּאֶצְבְּעָךְ וְיָת כָּל דְמָא תֵישׁוֹד לִיסוֹדָא דְמַדְבְּחָא:
@814 וְתִסַב יָת כָּל תַּרְבָּא דְחָפֵי יָת גַוָא וְיָת חִצְרָא דִעַל כַּבְדָא וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִי עֲלֵיהֶן וְתַסֵיק לְמַדְבְּחָא:
@815 וְיָת בִּסְרָא דְתוֹרָא וְיָת מַשְׁכֵהּ וְיָת אוּכְלֵהּ תּוֹקִיד בְּנוּרָא מִבָּרָא לְמַשְׁרִיתָא חַטָאתָא הוּא:
@816 וְיָת דִכְרָא חַד תִּסַב וְיִסְמְכוּן אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ דִכְרָא:
@817 וְתִכּוֹס יָת דִכְרָא וְתִסַב יָת דְמֵהּ וְתִזְרוֹק עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@818 וְיָת דִכְרָא תְּפַלֵג לְאֵבָרוֹהִי וּתְחַלִיל גַּוֵהּ וּכְרָעוֹהִי וְתִתֵּן עַל אֵבָרוֹהִי וְעַל רֵישֵׁהּ:
@819 וְתַסֵיק יָת כָּל דִכְרָא לְמַדְבְּחָא עֲלָתָא הוּא קֳדָם יְיָ לְאִתְקַבָּלָא בְרַעֲוָא קֻרְבָּנָא קֳדָם יְיָ הוּא:
@820 וְתִסַב יָת דִכְרָא תִנְיָנָא וְיִסְמוֹךְ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ דִכְרָא:
@821 וְתִכּוֹס יָת דִכְרָא וְתִסַב מִדְמֵהּ וְתִתֵּן עַל רוּם אוּדְנָא דְאַהֲרֹן וְעַל רוּם אוּדְנָא דִבְנוֹהִי דְיַמִינָא וְעַל אִלְיוֹן יְדֵיהוֹן דְיַמִינָא וְעַל אִלְיוֹן רַגְלֵיהוֹן דְיַמִינָא וְתִזְרוֹק יָת דְמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@822 וְתִסַב מִן דְמָא דִי עַל מַדְבְּחָא וּמִמִשְׁחָא דִרְבוּתָא וְתַדֵי עַל אַהֲרֹן וְעַל לְבוּשׁוֹהִי וְעַל בְּנוֹהִי וְעַל לְבוּשֵׁי בְנוֹהִי עִמֵהּ וְיִתְקַדַשׁ הוּא וּלְבוּשׁוֹהִי וּבְנוֹהִי וּלְבוּשֵׁי בְנוֹהִי עִמֵהּ:
@823 וְתִסַב מִן דִכְרָא תַּרְבָּא וְאַלִיתָא וְיָת תַּרְבָּא דְחָפֵי יָת גַוָא וְיָת חֲצַר כַּבְדָא וְיָת תַּרְתֵּן כָּלְיָן וְיָת תַּרְבָּא דִי עֲלֵיהֶן וְיָת שׁוֹקָא דְיַמִינָא אֲרֵי דְכַר קֻרְבָּנָא הוּא:
@824 וּפִתָּא דִלְחֵם חַד וּגְרִצְתָּא דִלְחֵם מְשַׁח חֲדָא וְאֶסְפּוֹג חָד מִסַלָא דְפַטִירַיָא דִי קֳדָם יְיָ:
@825 וּתְשַׁוֵי כֹלָא עַל יְדָא דְאַהֲרֹן וְעַל יְדָא דִבְנוֹהִי וּתְרִים יָתְהוֹן אֲרָמוּתָא קֳדָם יְיָ:
@826 וְתִסַב יָתְהוֹן מִידֵיהוֹן וְתַסֵיק לְמַדְבְּחָא עַל עֲלָתָא לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ קֻרְבָּנָא הוּא קֳדָם יְיָ:
@827 וְתִסַב יָת חֶדְיָא מִדְכַר קֻרְבָּנַיָא דִי לְאַהֲרֹן וּתְרִים יָתֵהּ אֲרָמוּתָא קֳדָם יְיָ וִיהֵי לָךְ לָחֳלָק:
@828 וּתְקַדֵשׁ יָת חֶדְיָא דַאֲרָמוּתָא וְיָת שׁוֹקָא דְאַפְרָשׁוּתָא דִי אִתָּרַם וְדִי אִתַּפְרָשׁ מִדְכַר קֻרְבָּנַיָא מִדִי לְאַהֲרֹן וּמִדִי לִבְנוֹהִי:
@829 וִיהֵי לְאַהֲרֹן וְלִבְנוֹהִי לִקְיַם עָלָם מִן בְּנֵי יִשְׂרָאֵל אֲרֵי אַפְרָשׁוּתָא הוּא וְאַפְרָשׁוּתָא יְהֵי מִן בְּנֵי יִשְׂרָאֵל מִנִכְסַת קוּדְשֵׁיהוֹן אַפְרָשׁוּתְהוֹן קֳדָם יְיָ:
@830 וּלְבוּשֵׁי קוּדְשָׁא דִי לְאַהֲרֹן יְהוֹן לִבְנוֹהִי בַּתְרוֹהִי לְדַכָּאָה בְהוֹן וּלְקָרָבָא בְהוֹן יָת קֻרְבָּנְהוֹן:
@831 שִׁבְעַת יוֹמִין יַלְבֵּשִׁנוּן כַּהֲנָא תְּחוֹתוֹהִי מִבְּנוֹהִי דִי יֵעוֹל לְמַשְׁכַּן זִמְנָא לְשַׁמָשָׁא בְקוּדְשָׁא:
@832 וְיָת דְכַר קֻרְבָּנַיָא תִּסָב וּתְבַשֵׁל יָת בִּסְרֵהּ בַּאֲתַר קַדִישׁ:
@833 וְיֵכוּל אַהֲרֹן וּבְנוֹהִי יָת בְּסַר דִכְרָא וְיָת לַחְמָא דִי בְסַלָא לִתְרַע מַשְׁכַּן זִמְנָא:
@834 וְיֵכְלוּן יָתְהוֹן דִי יִתְכַּפַּר בְּהוֹן לְקָרָבָא יָת קֻרְבָּנְהוֹן לְקַדָשָׁא יָתְהוֹן וְחִלוֹנַי לָא יֵיכוּל אֲרֵי קוּדְשָׁא אִנוּן:
@835 וְאִם יִשְׁתָּאַר מִבְּסַר קֻרְבָּנַיָא וּמִן לַחְמָא עַד צַפְרָא וְתוֹקִיד יָת דְאִשְׁתָּאַר בְּנוּרָא לָא יִתְאֲכֵל אֲרֵי קוּדְשָׁא הוּא:
@836 וְתַעְבֵּד לְאַהֲרֹן וְלִבְנוֹהִי כְּדֵין כְּכֹל דִי פַקֵּדִית יָתָךְ שִׁבְעַת יוֹמִין תְּקָרֵב קֻרְבָּנְהוֹן:
@837 וְתוֹרָא דְחַטָאתָא תַּעְבֵּד לְיוֹמָא עַל כִּפּוּרַיָא וּתְדַכֵּי עַל מַדְבְּחָא בְּכַפָּרוּתָךְ עֲלוֹהִי וּתְרַבֵּי יָתֵהּ לְקַדָשׁוּתֵהּ:
@838 שִׁבְעַת יוֹמִין תְּכַפֵּר עַל מַדְבְּחָא וּתְקַדֵשׁ יָתֵהּ וִיהֵי מַדְבְּחָא קֹדֶשׁ קוּדְשַׁיָא כָּל דְיִקְרַב בְּמַדְבְּחָא יִתְקַדָשׁ:
@839 וְדֵין דִי תַעְבֵּד עַל מַדְבְּחָא אִמְרִין בְּנֵי שְׁנָא תְּרֵין לְיוֹמָא תְּדִירָא:
@840 יָת אִמְרָא חַד תַּעְבֵּד בְּצַפְרָא וְיָת אִמְרָא תִנְיָנָא תַּעְבֵּד בֵּין שִׁמְשַׁיָא:
@841 וְעִסְרוֹנָא סֻלְתָּא דְפִילָא בִמְשַׁח כָּתִישָׁא רַבְעוּת הִינָא וְנִסְכָּא רַבְעוּת הִינָא חַמְרָא לְאִמְרָא חָד:
@842 וְיָת אִמְרָא תִנְיָנָא תַּעְבֵּד בֵּין שִׁמְשַׁיָא כְּמִנְחַת צַפְרָא וּכְנִסְכַּהּ תַּעְבֵּד לַהּ לְאִתְקַּבָּלָא בְרַעֲוָא קֻרְבָּנָא קֳדָם יְיָ:
@843 עֲלָתָא תְדִירָא לְדָרֵיכוֹן בִּתְרַע מַשְׁכַּן זִמְנָא קֳדָם יְיָ דִאֱזַמֵן מֵימְרִי לְכוֹן תַּמָן לְמַלָלָא עִמָךְ תַּמָן:
@844 וֶאֱזַמֵן מֵימְרִי תַמָן לִבְנֵי יִשְׂרָאֵל וְיִתְקַדַשׁ בִּיקָרִי:
@845 וֶאֱקַדֵשׁ יָת מַשְׁכַּן זִמְנָא וְיָת מַדְבְּחָא וְיָת אַהֲרֹן וְיָת בְּנוֹהִי אֱקַדֵשׁ לְשַׁמָשָׁא קֳדָמַי:
@846 וְאַשְׁרֵי שְׁכִנְתִּי בְּגוֹ בְּנֵי יִשְׂרָאֵל וְאֶהֱוֵי לְהוֹן לֶאֱלָהּ:
@847 וְיִדְעוּן אֲרֵי אֲנָא יְיָ אֱלָהֲהוֹן דִי אַפֵּקִית יָתְהוֹן מֵאַרְעָא דְמִצְרַיִם לְאַשְׁרָאָה שְׁכִנְתִּי בֵּינֵיהוֹן אֲנָא יְיָ אֱלָהֲהוֹן:
@848 וְתַעְבֵד מַדְבְּחָא לְאַקְטָרָא עֲלוֹהִי קְטוֹרֶת בּוּסְמַיָא דְאָעֵי שִׁטִין תַּעְבֵּד יָתֵהּ:
@849 אַמְתָא אֻרְכֵּהּ וְאַמְתָא פְתָיֵהּ מְרַבַּע יְהֵי וְתַרְתֵּין אַמִין רוּמֵהּ מִנֵהּ קַרְנוֹהִי:
@850 וְתַחֲפֵי יָתֵהּ דְהַב דְכֵי יָת אִגָרֵהּ וְיָת כָּתְלוֹהִי סְחוֹר סְחוֹר וְיָת קַרְנוֹהִי וְתַעְבֵּד לֵהּ דֵיר דִדְהב סְחוֹר סְחוֹר:
@851 וְתַרְתֵּין עִזְקַן דִדְהַב תַּעְבֶּד לֵהּ מִלְרַע לְדֵירֵהּ עַל תַּרְתֵּין זִוְיָתֵהּ תַּעְבֵּד עַל תְּרֵין סִטְרוֹהִי וִיהֵי לְאַתְרָא לַאֲרִיחַיָא לְמִטַל יָתֵהּ בְּהוֹן:
@852 וְתַעְבֵּד יָת אֲרִיחַיָא דְאָעֵי שִׁטִין וְתַחֲפֵי יָתְהוֹן דַהֲבָא:
@853 וְתִתֵּן יָתֵה קֳדָם פָּרֻכְתָּא דִי עַל אֲרוֹנָא דְסַהֲדוּתָא לִקֳדָם כַּפֻּרְתָּא דִי עַל סַהֲדוּתָא דִי אֲזַמֵן מֵימְרִי לָךְ תַּמָן:
@854 וְיַקְטַר עֲלוֹהִי אַהֲרֹן קְטוֹרֶת בּוּסְמִין בִּצְפַר בִּצְפַר בְּאַתְקָנוּתֵהּ יָת בּוֹצִינַיָא יַסֵקִנַהּ:
@855 וּבְאַדְלָקוּת אַהֲרֹן יָת בּוֹצִינַיָא בֵּין שִׁמְשַׁיָא יַסֵקִנַהּ קְטוֹרֶת בּוּסְמַיָא תְדִירָא קֳדָם יְיָ לְדָרֵיכוֹן:
@856 לָא תַסְקוּן עֲלוֹהִי קְטוֹרֶת בּוּסְמִין נוּכְרָאִין וַעֲלָתָא וּמִנְחָתָא וְנִסְכָּא לָא תְנַסְכוּן עֲלוֹהִי:
@857 וִיכַפֵר אַהֲרֹן עַל קַרְנוֹהִי חֲדָא בְּשַׁתָּא מִדְמָא חַטַאת כִּפּוּרַיָא חֲדָא בְשַׁתָּא יְכַפֵּר עֲלוֹהִי לְדָרֵיכוֹן קֹדֶשׁ קוּדְשִׁין הוּא קֳדָם יְיָ: פפפ:
@858 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@859 אֲרֵי תְקַבֵּל יָת חֻשְׁבַּן בְּנֵי יִשְׂרָאֵל לְמִנְיָנֵיהוֹן וְיִתְּנוּן גְבַר פֻּרְקַן נַפְשֵׁהּ קֳדָם יְיָ כַּד תִּמְנֵי יָתְהוֹן וְלָא יְהֵי בְהוֹן מוֹתָא כַּד תִּמְנֵי יָתְהוֹן:
@860 דֵין יִתְּנוּן כָּל דְעָבַר עַל מִנְיָנַיָּא פַּלְגוּת סִלְעָא בְּסִלְעֵי קוּדְשָׁא עֶסְרִין מָעִין סִלְעָא פַּלְגוּת סִלְעָא אַפְרָשׁוּתָא קֳדָם יְיָ:
@861 כֹּל דְעָבַר עַל מִנְיָנַיָא מִבַּר עֶסְרִין שְׁנִין וּלְעֵלָא יִתֵּן אַפְרָשׁוּתָא קֳדָם יְיָ:
@862 דְעַתִּיר לָא יַסְגֵי וּדְמִסְכֵּן לָא יַזְעֵר מִפַּלְגוּת סִלְעָא לְמִתַּן יָת אַפְרָשׁוּתָא קֳדָם יְיָ לְכַפָּרָא עַל נַפְשָׁתֵיכוֹן:
@863 וְתִסַב יָת כְּסַף כִּפּוּרַיָא מִן בְּנֵי יִשְׂרָאֵל וְתִתֵּן יָתֵהּ עַל פָּלְחַן מַשְׁכַּן זִמְנָא וִיהֵי לִבְנֵי יִשְׂרָאֵל לְדָכְרָנָא קֳדָם יְיָ לְכַפָּרָא עַל נַפְשָׁתֵיכוֹן:
@864 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@865 וְתַעְבֵּד כִּיוֹרָא דִנְחָשָׁא וּבְסִיסֵהּ נְחָשָׁא לְקִדוּשׁ וְתִתֵּן יָתֵהּ בֵּין מַשְׁכַּן זִמְנָא וּבֵין מַדְבְּחָא וְתִתֵּן תַּמָן מַיָא:
@866 וִיקַדְשׁוּן אַהֲרֹן וּבְנוֹהִי מִנֵהּ יָת יְדֵיהוֹן וְיָת רַגְלֵיהוֹן:
@867 בְּמֵיעַלְהוֹן לְמַשְׁכַּן זִמְנָא יְקַדְשׁוּן מַיָא וְלָא יְמוּתוּן אוֹ בְמִקְרָבְהוֹן לְמַדְבְּחָא לְשַׁמָשָׁא לְאַסָקָא קֻרְבָּנָא קֳדָם יְיָ:
@868 וִיקַדְשׁוּן יְדֵיהוֹן וְרַגְלֵיהוֹן וְלָא יְמוּתוּן וּתְהֵי לְהוֹן קְיָם עָלָם לֵהּ וְלִבְנוֹהִי לְדָרֵיהוֹן:
@869 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@870 וְאַתְּ סַב לָךְ בּוּסְמִין רֵישָׁא מֵירָא דַכְיָא מַתְקַל חֲמֵשׁ מְאָה וְקִנְמָן בֶּשֶׂם פַּלְגוּתֵהּ מַתְקַל מָאתָן וְחַמְשִׁין וּקְנֵה בוּסְמָא מַתְקַל מָאתָן וְחַמְשִׁין:
@871 וּקְצִיעֵתָא מַתְקַל חֲמֵשׁ מְאָה בְּסִלְעֵי קוּדְשָׁא וּמְשַׁח זֵיתָא מְלֵא הִינָא:
@872 וְתַעְבֵּד יָתֵהּ מְשַׁח רְבוּת קוּדְשָׁא בּוֹסֶם מְבַסָם עוֹבַד בּוּסְמָנוּ מְשַׁח רְבוּת קוּדְשָׁא יְהֵא:
@873 וּתְרַבִּי בֵהּ יָת מַשְׁכַּן זִמְנָא וְיָת אֲרוֹנָא דְסַהֲדוּתָא:
@874 וְיָת פָּתוֹרָא וְיָת כָּל מָנוֹהִי וְיָת מְנַרְתָּא וְיָת מָנָהָא וְיָת מַדְבְּחָא דִקְטֹרֶת בּוּסְמַיָא:
@875 וְיָת מַדְבַּח דַעֲלָתָא וְיָת כָּל מָנוֹהִי וְיָת כִּיוֹרָא וְיָת בְּסִיסֵהּ:
@876 וּתְקַדֵשׁ יָתְהוֹן וִיהוֹן קֹדֶשׁ קוּדְשַׁיָא כָּל דְיִקְרַב בְּהוֹן יִתְקַדָשׁ:
@877 וְיָת אַהֲרֹן וְיָת בְּנוֹהִי תְּרַבִּי וּתְקַדֵשׁ יָתְהוֹן לְשַׁמָשָׁא קֳדָמַי:
@878 וְעִם בְּנֵי יִשְׂרָאֵל תְּמַלֵל לְמֵימָר מְשַׁח רְבוּת קוּדְשָׁא יְהֵי דֵין קֳדָמַי לְדָרֵיכוֹן:
@879 עַל בִּסְרָא דַאֲנָשָׁא לָא יִתְנַסַךְ וּבִדְמוּתֵהּ לָא תַעְבְּדוּן כְּוָתֵהּ קוּדְשָׁא הוּא קוּדְשָׁא יְהֵי לְכוֹן:
@880 גְבַר דִי יְבַסֵם דִכְוָתֵהּ וְדִי יִתֵּן מִנֵהּ עַל חִלוֹנָי וְיִשְׁתֵּצֵי מֵעַמֵהּ:
@881 וַאֲמַר יְיָ לְמשֶׁה סַב לָךְ בּוּסְמִין נְטוֹפָא וְטוּפְרָא וְחֶלְבְּנֵתָא בּוּסְמִין וּלְבוּנְתָא דָכִיתָא מַתְקַל בְּמַתְקַל יְהֵי:
@882 וְתַעְבֵּד יָתַהּ קְטוֹרֶת בּוּסְמִין בּוֹסֶם עוֹבַד בּוּסְמָנוּ מְעָרַב דְכֵי קוּדְשָׁא:
@883 וְתִשְׁחוֹק מִנַהּ וְתַדִיק וְתִתֵּן מִנַהּ קֳדָם סַהֲדוּתָא בְּמַשְׁכַּן זִמְנָא דִי אֱזַמֵן מֵימְרִי לָךְ תַּמָן קֹדֶשׁ קוּדְשִׁין תְּהֵי לְכוֹן:
@884 וּקְטֹרֶת בּוּסְמִין דִי תַעְבֵּד בִּדְמוּתַהּ לָא תַעְבְּדוּן לְכוֹן קוּדְשָׁא תְּהֵי לָךְ קֳדָם יְיָ:
@885 גְבַר דִיַעְבֵּד דִכְוָתַהּ לַאֲרָחָא בַהּ וְיִשְׁתֵּצֵי מֵעַמֵּהּ:
@886 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@887 חֲזֵי דְרַבֵּיתִי בְשׁוּם בְּצַלְאֵל בַּר אוּרִי בַּר חוּר לְשִׁבְטָא דִיהוּדָה:
@888 וְאַשְׁלֵמִית עִמֵהּ רוּחַ מִן קֳדָם יְיָ בְּחָכְמְתָא וּבְסוּכְלְתָנוּ וּבְמַדַע וּבְכָל עִבִידָא:
@889 לְאַלָפָא אוּמַנְוָן לְמֶעְבַּד בְּדַהֲבָא וּבְכַסְפָּא וּבִנְחָשָׁא:
@890 וּבְאָמָנוּת אֶבֶן טָבָא לְאַשְׁלָמָא וּבְנַגָרוּת אָעָא לְמֶעְבַּד בְּכָל עִבִידָא:
@891 וַאֲנָא הָא יְהָבִית עִמֵהּ יָת אָהֳלִיאָב בַּר אֲחִיסָמָךְ לְשִׁבְטָא דְדָן וּבְלִבָּא כָל חַכִּימֵי לִבָּא יְהָבִית חָכִמְתָא וְיַעְבִּדוּן יָת כָּל דִי פַקֵדִתָּךְ:
@892 יָת מַשְׁכַּן זִמְנָא וְיָת אֲרוֹנָא לְסַהֲדוּתָא וְיָת כַּפֻּרְתָּא דִי עֲלוֹהִי וְיָת כָּל מָנֵי מַשְׁכְּנָא:
@893 וְיָת פָּתוֹרָא וְיָת מָנוֹהִי וְיָת מְנַרְתָּא דָכִיתָא וְיָת כָּל מָנָהָא וְיָת מַדְבְּחָא דִקְטּוֹרֶת בּוּסְמַיָא:
@894 וְיָת מַדְבְּחָא דַעֲלָתָא וְיָת כָּל מָנוֹהִי וְיָת כִּיוֹרָא וְיָת בְּסִיסֵהּ:
@895 וְיָת לְבוּשֵׁי שִׁמוּשָׁא וְיָת לְבוּשֵׁי קוּדְשָׁא לְאַהֲרֹן כַּהֲנָא וְיָת לְבוּשֵׁי בְנוֹהִי לְשַׁמָשָׁא:
@896 וְיָת מִשְׁחָא דִרְבוּתָא וְיָת קְטוֹרֶת בּוּסְמַיָא לְקוּדְשָׁא כְּכֹל דִי פַקֵדִתָּךְ יַעְבְּדוּן:
@897 וַאֲמַר יְיָ לְמשֶׁה לְמֵימָר:
@898 וְאַתְּ מַלֵל עִם בְּנֵי יִשְׂרָאֵל לְמֵימַר בְּרַם יָת יוֹמֵי שַׁבַּיָא דִי לִי תִּטְּרוּן אֲרֵי אָת הִיא בֵּין מֵימְרִי וּבֵינֵיכוֹן לְדָרֵיכוֹן לְמִדַע אֲרֵי אֲנָא יְיָ מְקַדִשְׁכוֹן:
@899 וְתִטְּרוּן יָת שַׁבְּתָא אֲרֵי קוּדְשָׁא הִיא לְכוֹן מְחַלְלִנַהּ אִתְקְטָלָא יִתְקְטֵל אֲרֵי כָּל דְיַעְבֶּד בַּהּ עִבִידָא וְיִשְׁתֵּצֵי אֲנָשָׁא הַהוּא מִגוֹ עַמֵּהּ:
@900 שִׁתָּא יוֹמִין יִתְעֲבֵד עִבִידָא וּבְיוֹמָא שְׁבִיעָאָה שְׁבַת שַׁבְּתָא קוּדְשָׁא קֳדָם יְיָ כָּל דְיַעְבֵּד עִבִדְתָּא בְּיוֹמָא דְשַׁבְּתָא אִתְקְטָלָא יִתְקְטֵל:
@901 וְיִטְרוּן בְּנֵי יִשְׂרָאֵל יָת שַׁבְּתָא לְמֶעְבַּד יָת שַׁבְּתָא לְדָרֵיהוֹן קְיַם עָלָם:
@902 בֵּין מֵימְרִי וּבֵין בְּנֵי יִשְׂרָאֵל אָת הִיא לְעָלָם אֲרֵי שִׁתָּא יוֹמִין עֲבַד יְיָ יָת שְׁמַיָא וְיָת אַרְעָא וּבְיוֹמָא שְׁבִיעָאָה שְׁבַת וְנַח:
@903 וִיהַב לְמשֶׁה כַּד שֵׁיצֵי לְמַלָלָא עִמֵהּ בְּטוּרָא דְסִינָי תְּרֵין לוּחֵי סַהֲדוּתָא לוּחֵי אַבְנָא כְּתִיבִין בְּאֶצְבְּעָא דַיְיָ:
@904 וַחֲזָא עַמָא אֲרֵי אוֹחַר משֶׁה לְמֵחַת מִן טוּרָא וְאִתְכְּנֵשׁ עַמָא עַל אַהֲרֹן וַאֲמָרוּ לֵהּ קוּם עֲבֵד לָנָא דַחֲלָן דִיְהָכוּן קֳדָמָנָא אֲרֵי דֵין משֶׁה גַבְרָא דִי אַסְקָנָא מֵאַרְעָא דְמִצְרַיִם לָא יְדַעְנָא מָא הֲוָה לֵהּ:
@905 וַאֲמַר לְהוֹן אַהֲרֹן פְּרִיקוּ קָדָשֵׁי דְדַהֲבָא דִי בְאוּדְנֵי נְשֵׁיכוֹן בְּנֵיכוֹן וּבְנָתֵיכוֹן וְאַיְתִיוּ לְוָתִי:
@906 וְאִתְפְּרִיקוּ כָּל עַמָא יָת קָדָשֵׁי דְדַהֲבָא דִי בְאוּדְנֵיהוֹן וְאַיְתִיוּ לְאַהֲרֹן:
@907 וּנְסִיב מִידֵיהוֹן וְצַר יָתֵהּ בְּזִיפָא וְעָבְדֵהּ עֵגֶל מַתְּכָא וַאֲמָרוּ אִלֵין דַחַלְתָּךְ יִשְׂרָאֵל דִי אַסְקוּךְ מֵאַרְעָא דְמִצְרָיִם:
@908 וַחֲזָא אַהֲרֹן וּבְנָא מַדְבְּחָא קֳדָמוֹהִי וּקְרָא אַהֲרֹן וַאֲמַר חַגָא קֳדָם יְיָ מְחָר:
@909 וְאַקְדִימוּ בְּיוֹמָא דְבַתְרוֹהִי וְאַסִיקוּ עֲלָוָן וְקָרִיבוּ נִכְסִין וְאַסְחַר עַמָא לְמֵיכַל וּלְמִשְׁתֵּי וְקָמוּ לְחַיָכָא:
@910 וּמַלִיל יְיָ עִם משֶׁה אִזֵל חוּת אֲרֵי חַבִּיל עַמָּךְ דִי אַסֶקְתָּא מֵאַרְעָא דְמִצְרָיִם:
@911 סָטוּ בִּפְרִיעַ מִן אוֹרְחָא דִי פַקֶדְתִּנוּן עֲבָדוּ לְהוֹן עֵגֶל מַתְּכָא וּסְגִידוּ לֵהּ וְדַבָּחוּ לֵהּ וַאֲמָרוּ אִלֵין דַחַלְתָּךְ יִשְׂרָאֵל דִי אַסְקוּךְ מֵאַרְעָא דְמִצְרָיִם:
@912 וַאֲמַר יְיָ לְמשֶׁה גְלִי קֳדָמַי עַמָא הָדֵין וְהָא עַמָא קְשֵׁי קְדַל הוּא:
@913 וּכְעַן הַנַּח בָּעוּתָךְ מִן קֳדָמַי וְיִתְקֵף רוּגְזִי בְהוֹן וְאֵישֵׁיצִנוּן וְאֶעְבֵּד יָתָךְ לְעַם סַגִי:
@914 וְצַלִי משֶׁה קֳדָם יְיָ אֱלָהֵהּ וַאֲמַר לְמָא יְיָ יִתְקֵף רוּגְזָךְ בְּעַמָךְ דִי אַפֶּקְתָּא מֵאַרְעָא דְמִצְרַיִם בְּחֵיל רַב וּבִידָא תַקִ יפָא:
@915 לְמָא יֵימְרוּן מִצְרָאֵי לְמֵימַר בְּבִישְׁתָּא אַפֶּקְתִּנוּן לְקַטָלָא יָתְהוֹן בֵינֵי טוּרַיָא וּלְשֵׁיצָיוּתְהוֹן מֵעַל אַפֵּי אַרְעָא תּוּב מִתְּקוֹף רוּגְזָךְ וְאָתֵיב מִן בִּשָׁתָא דְמַלֶלְתָּא לְמֶעְבַּד לְעַמָךְ:
@916 אִדְכַּר לְאַבְרָהָם לְיִצְחָק וּלְיִשְׂרָאֵל עַבְדָיךְ דִי קַיֶמְתָּא לְהוֹן בְּמֵימְרָךְ וּמַלֶלְתָּא עִמְהוֹן אַסְגֵי יָת בְּנֵיכוֹן כְּכוֹכְבֵי שְׁמַיָא וְכָל אַרְעָא הָדָא דִי אֲמָרִית אֶתֵּן לִבְנֵיכוֹן וְיַחְסְנוּן לַעֲלָם:
@917 וְתַב יְיָ מִן בִּישְׁתָא דִי מַלִיל לְמֶעְבַּד לְעַמֵהּ:
@918 וְאִתְפְּנֵי וּנְחַת משֶׁה מִן טוּרָא וּתְרֵין לוּחֵי סַהֲדוּתָא בִּידֵהּ לוּחֵי כְּתִיבִין מִתְּרֵין עִבְרֵיהוֹן מִכָּא וּמִכָּא אִנוּן כְּתִיבִין:
@919 וְלוּחַיָא עוֹבָדָא דַיְיָ אִנוּן וּכְתָבָא כְּתָבָא דַיְיָ הוּא מְפָרַשׁ עַל לוּחַיָא:
@920 וּשְׁמַע יְהוֹשֻׁעַ יָת קַל עַמָא כַּד מְיַבְּבִן וַאֲמַר לְמשֶׁה קַל קְרָבָא בְּמַשְׁרִיתָא:
@921 וַאֲמַר לָא קַל גִבָּרִין דְנַצְחִין בִּקְרָבָא וְאַף לָא קַל חַלָשִׁין דְמִתַּבְּרִין קַל דִמְחַיְכִין אֲנָא שְׁמָע:
@922 וַהֲוָה כַּד קָרִיב לְמַשְׁרִיתָא וַחֲזָא יָת עֶגְלָא וְחִנְגִין וּתְקֵיף רוּגְזָא דְמשֶׁה וּרְמָא מִידוֹהִי יָת לוּחַיָא וְתַבַּר יָתְהוֹן בְּשִׁפּוֹלֵי טּוּרָא:
@923 וּנְסֵיב יָת עֶגְלָא דִי עֲבָדוּ וְאוֹקֵד בְּנוּרָא וְשַׁף עַד דַהֲוָה דַקִיק וּזְרָא עַל אַפֵּי מַיָא וְאַשְׁקֵי יָת בְּנֵי יִשְׂרָאֵל:
@924 וַאֲמַר משֶׁה לְאַהֲרֹן מָא עֲבַד לָךְ עַמָא הָדֵין אֲרֵי אַיְתֵיתָא עֲלוֹהִי חוֹבָא רַבָּא:
@925 וַאֲמַר אַהֲרֹן לָא יִתְקֵף רוּגְזָא דְרִבּוֹנִי אַתְּ יְדַעְתְּ יָת עַמָא אֲרֵי בְּבִישׁ הוּא:
@926 וַאֲמָרוּ לִי עִבֵיד לָנָא דַחֲלָן דִי יְהָכָן קֳדָמָנָא אֲרֵי דֵין משֶׁה גַבְרָא דִי אַסְקָנָא מֵאַרְעָא דְמִצְרַיִם לָא יְדַעְנָא מָא הֲוָה לֵהּ:
@927 וַאֲמָרִית לְהוֹן לְמָן דַהֲבָא פְּרִיקוּ וִיהָבוּ לִי וּרְמִיתֵהּ בְּנוּרָא וּנְפַק עֶגְלָא הָדֵין:
@928 וַחֲזָא משֶׁה יָת עַמָא אֲרֵי בְטִיל הוּא אֲרֵי בָטֵילִנוּן אַהֲרֹן לַאֲסָבוּתְהוֹן שׁוּם בִּישׁ לְדָרֵיהוֹן:
@929 וְקָם משֶׁה בִּתְרַע מַשְׁרִיתָא וַאֲמַר מָן דַחֲלַיָא דַיְיָ יֵיתוּן לְוָתִי וְאִתְכַּנָשׁוּ לְוָתֵהּ כָּל בְּנֵי לֵוִי:
@930 וַאֲמַר לְהוֹן כִּדְנַן אֲמַר יְיָ אֱלָהָא דְיִשְׂרָאֵל שַׁווּ גְבַר חַרְבֵּהּ עַל יַרְכֵּהּ עִבַרוּ וְתוּבוּ מִתְּרַע לִתְרַע בְּמַשְׁרִיתָא וּקְטוּלוּ גְבַר יָת אָחוּהִי וּגְבַר יָת חַבְרֵהּ וֶאֱנַשׁ יָת קָרִיבֵהּ:
@931 וַעֲבָדוּ בְנֵי לֵוִי כְּפִתְגָמָא דְמשֶׁה וּנְפַל מִן עַמָא בְּיוֹמָא הַהוּא כִּתְלָתָא אַלְפִין גַבְרָא:
@932 וַאֲמַר משֶׁה קָרִיבוּ יֶדְכוֹן קֻרְבָּנָא יוֹמָא דֵין קֳדָם יְיָ אֲרֵי גְבַר בִּבְרֵהּ וּבְאָחוּהִי וּלְאַיְתָאָה עֲלֵיכוֹן יוֹמָא דֵין בִּרְכָן:
@933 וַהֲוָה בְּיוֹמָא דְבַתְרוֹהִי וַאֲמַר משֶׁה לְעַמָא אַתּוּן חַבְתּוּן חוֹבָא רַבָּא וּכְעַן אֶסַק קֳדָם יְיָ מָאִים אֵכַפֵּר עַל חוֹבֵיכוֹן:
@934 וְתַב משֶׁה לִקֳדָם יְיָ וַאֲמָר בְּבָעוּ חַב עַמָא הָדֵין חוֹבָא רַבָּא וַעֲבָדוּ לְהוֹן דַחֲלָן דִדְהָב:
@935 וּכְעַן אִם שַׁבְקַת לְחוֹבֵיהוֹן וְאִם לָא מְחֵנִי כְעַן מִסִפְרָךְ דִי כְתַבְתָּא:
@936 וַאֲמַר יְיָ לְמשֶׁה מָן דִי חַב קֳדָמַי אֶמְחִנֵהּ מִסִפְרִי:
@937 וּכְעַן אִיזֵל דַבַּר יָת עַמָא לַאֲתַר דִי מַלֵלִית לָךְ הָא מַלְאָכִי יְהַךְ קֳדָמָךְ וּבְיוֹם אַסַעֲרוּתִי וְאַסְעַר עֲלֵיהוֹן חוֹבֵיהוֹן:
@938 וּמְחָא יְיָ יָת עַמָא עַל דִי אִשְׁתַּעְבָּדוּ לְעֶגְלָא דִי עֲבַד אַהֲרֹן:
@939 וּמַלִיל יְיָ עִם משֶׁה אִיזֵל סַק מִכָּא אַתְּ וְעַמָא דְאַסֶקְתָּא מֵאַרְעָא דְמִצְרַיִם לְאַרְעָא דִי קַיֵמִית לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב לְמֵימַר לִבְנָיךְ אֶתְּנִנַהּ:
@940 וְאֶשְׁלַח קֳדָמָךְ מַלְאָכָא וְאֵתָרֵךְ יָת כְּנַעֲנָאֵי אֱמוֹרָאֵי וְחִתָּאֵי וּפְרִזָאֵי חִוָאֵי וִיבוּסָאֵי:
@941 לְאַרְעָא עַבְדָא חֲלָב וּדְבָשׁ אֲרֵי לָא אֲסַלֵק שְׁכִנְתִּי מִבֵּינָךְ אֲרֵי עַם קְשֵׁי קְדַל אַתְּ דִילְמָא אֲשֵׁצִינָךְ בְּאָרְחָא:בְּאָרְחָא:
@942 וּשְׁמַע עַמָא יָת פִּתְגָמָא בִישָׁא הָדֵין וְאִתְאַבָּלוּ וְלָא שַׁוִיוּ גְבַר תִּקוּן זֵינֵהּ עֲלוֹהִי:
@943 וַאֲמַר יְיָ לְמשֶׁה אֵימַר לִבְנֵי יִשְׂרָאֵל אַתּוּן עַם קְשֵׁי קְדַל שָׁעָה חֲדָא אֲסַלֵק שְׁכִנְתִּי מִבֵּינָךְ וְאֵשֵׁיצִינָךְ וּכְעַן אַעְדִי תִּקוּן זֵינָךְ מִנָךְ וּגְלֵי קֳדָמַי מָה אַעְבֵּד לָךְ:
@944 וְאַעְדִיאוּ בְנֵי יִשְׂרָאֵל יָת תִּקוּן זֵינֵיהוֹן מִטוּרָא דְחוֹרֵב:
@945 וּמשֶׁה נְסִיב יָת מַשְׁכְּנָא וּפַרְסֵהּ לֵהּ מִבָּרָא לְמַשְׁרִיתָא אַרְחֵיק מִן מַשְׁרִיתָא וְקָרֵי לֵהּ מַשְׁכַּן בֵּית אוּלְפָנָא וִיהֵי כָּל דְתָבַע אוּלְפַן מִן קֳדָם יְיָ נְפַק לְמַשְׁכַּן בֵּית אוּלְפָנָא דִי מִבָּרָא לְמַשְׁרִיתָא:
@946 וַהֲוָה כַּד נְפַק משֶׁה לְמַשְׁכְּנָא קַיְמִין כָּל עַמָא וּמִתְעַתְּדִין גְבַר בִּתְרַע מַשְׁכְּנֵהּ וּמִסְתַּכְּלִין אֲחוֹרֵי משֶׁה עַד דְעָלֵל לְמַשְׁכְּנָא:
@947 וַהֲוָה כַּד עָלֵל משֶׁה לְמַשְׁכְּנָא נָחִית עַמוּדָא דַעֲנָנָא וְקָאִים בִּתְרַע מַשְׁכְּנָא וּמִתְמַלֵל עִם משֶׁה:
@948 וַחֲזָן כָּל עַמָא יָת עַמוּדָא דַעֲנָנָא קָאֵם בִּתְרַע מַשְׁכְּנָא וְקַיְמִין כָּל עַמָא וְסָגְדִין גְבַר בִּתְרַע מַשְׁכְּנֵהּ:
@949 וּמִתְמַלֵל יְיָ עִם משֶׁה מַמְלַל עִם מַמְלַל כְּמָא דִמְמַלֵל גְבַר עִם חַבְרֵהּ וְתָב לְמַשְׁרִיתָא וּמְשׁוּמְשָׁנֵהּ יְהוֹשֻׁעַ בַּר נוּן עוּלֵימָא לָא עֲדֵי מִגוֹ מַשְׁכְּנָא:
@950 וַאֲמַר משֶׁה קֳדָם יְיָ חֲזֵי דְאַתְּ אָמַר לִי אַסֵיק יָת עַמָא הָדֵין וְאַתְּ לֹא הוֹדַעְתַּנִי יָת דִי תִשְׁלַח עִמִי וְאַתְּ אָמַרְתְּ רַבִּיתָךְ בְּשׁוּם וְאַף אַשְׁכַּחְתָּא רַחֲמִין קֳדָמָי:
@951 וּכְעַן אִם כְּעַן אַשְׁכָּחִית רַחֲמִין קֳדָמָךְ הוֹדַעְנִי כְעַן יָת אוֹרַח טּוּבָךְ וְאִדַע רַחֲמָךְ בְּדִיל דְאַשְׁכַּח רַחֲמִין קֳדָמָךְ וּגְלֵי קֳדָמָךְ אֲרֵי עַמָךְ עַמָא הָדֵין:
@952 וַאֲמַר שְׁכִנְתִּי תְהַךְ וְאָנִיחַ לָךְ:
@953 וַאֲמַר קֳדָמוֹהִי אִם לֵית שְׁכִנְתָּךְ מֵהַלְכָא בֵינָנָא לָא תַסְקִינָנָא מִכָּא:
@954 וּבַמֶה יִתְיַדַע הָכָא אֲרֵי אַשְׁכָּחִית רַחֲמִין קֳדָמָךְ אֲנָא וְעַמָךְ הֲלָא בְּמֵהַךְ שְׁכִנְתָּךְ עִמָנָא וְיִתְעַבְּדַן לָנָא פְרִישָׁן לִי וּלְעַמָךְ מְשַׁנֵי מִכָּל עַמָא דִי עַל אַפֵּי אַרְעָא:
@955 וַאֲמַר יְיָ לְמשֶׁה אַף יָת פִּתְגָמָא הָדֵין דִי מַלֶלְתָּא אֶעְבֵּד אֲרֵי אַשְׁכַּחְתָּ רַחֲמִין קֳדָמַי וְרַבִּיתָךְ בְּשׁוּם:
@956 וַאֲמַר אַחֲזֵינִי כְעַן יָת יְקָרָךְ:
@957 וַאֲמַר אֲנָא אַעְבַּר כָּל טוּבִי עַל אַפָּיךְ וְאֶקְרֵי בִשְׁמָא דַיְיָ קֳדָמָךְ וְאֵחוֹן לְמָן דְאֵחוֹן וְאֵרַחֵם עַל מָן דְאֵרַחֵם:
@958 וַאֲמַר לָא תִיכוּל לְמֶחֱזֵי יָת אַפֵּי שְׁכִנְתִּי אֲרֵי לָא יֶחֱזִינַנִי:אֶנָשָׁא וְיִתְקַיָם:
@959 וַאֲמַר יְיָ הָא אָתַר מַתְקַן קֳדָמָי וְתִתְעַתַּד עַל טִנָרָא:
@960 וִיהֵי בְּמֵעֲבַר יְקָרִי וְאֵשַׁוִינָךְ בִּמְעָרַת טִנָרָא וְאָגֵין בְּמֵימְרִי עֲלָךְ עַד דְאֶעֱבַר:
@961 וְאַעְדֵי יָת דִבְרַת יְקָרִי וְתֶחֱזֵי יָת דְבַתְרָי וְדִקֳדָמַי לָא יִתְחֲזוּן:
@962 וַאֲמַר יְיָ לְמשֶׁה פְּסָל לָךְ תְּרֵין לוּחֵי אַבְנַיָא כְּקַדְמָאֵי וְאֶכְתּוֹב עַל לוּחַיָא יָת פִּתְגָמַיָא דִי הֲווֹ עַל לוּחַיָא קַדְמָאֵי דִי תְבַרְתָּא:
@963 וֶהֱוֵי זַמִין לְצַפְרָא וְתִסַק בְּצַפְרָא לְטוּרָא דְסִינַי וְתִתְעַתַּד קֳדָמַי תַּמָן עַל רֵישׁ טוּרָא:
@964 וֶאֱנַשׁ לָא יִסַק עִמָךְ וְאַף אֱנַשׁ לָא יִתְחֲזֵי בְּכָל טוּרָא אַף עֲנָא וְתוֹרֵי לָא יִרְעוּן לָקֳבֵל טוּרָא הַהוּא:
@965 וּפְסַל תְּרֵין לוּחֵי אַבְנַיָא כְּקַדְמָאֵי וְאַקְדֵם משֶׁה בְּצַפְרָא וּסְלֵיק לְטוּרָא דְסִינַי כְּמָא דְפַקֵד יְיָ יָתֵהּ וּנְסֵב בִּידֵהּ תְּרֵין לוּחֵי אַבְנַיָא:
@966 וְאִתְגְלִי יְיָ בַּעֲנָנָא וְאִתְעַתַּד עִמֵהּ תַּמָן וּקְרָא בִשְׁמָא דַיְיָ:
@967 וְאַעְבַּר יְיָ שְׁכִנְתֵּהּ עַל אַפּוֹהִי וּקְרָא יְיָ יְיָ אֱלָהָא רַחֲמָנָא וְחַנָנָא מַרְחִיק רְגַז וּמַסְגֵי לְמֶעְבַּד טַבְוָן וּקְשׁוֹט:
@968 נָטַר טִיבוּ לְאַלְפֵי דָרִין שָׁבֵק לַעֲוָיָן וְלִמְרוֹד וּלְחוֹבִין סָלַח לִדְתַיְבִין לְאוֹרַיְתֵהּ וְלִדְלָא תַיְבִין לָא מְזַכֵּי מַסְעַר חוֹבֵי אֲבָהָן עַל בְּנִין וְעַל בְּנֵי בְנִין מְרָדִין עַל דַר תְּלִיתָי וְעַל דַר רְבִיעָי:
@969 וְאוֹחִי משֶׁה וּכְרַע עַל אַרְעָא וּסְגִיד:
@970 וַאֲמַר אִם כְּעַן אַשְׁכָּחִית רַחֲמִין קֳדָמָךְ יְיָ תְּהַךְ כְּעַן שְׁכִנְתָּא דַיְיָ בֵּינָנָא אֲרֵי עַם קְשֵׁי קְדַל הוּא וְתִשְׁבּוֹק לְחוֹבָנָא וְלַחֲטָאָנָא וְתַחְסְנָנָא:
@971 וַאֲמַר הָא אֲנָא גְזַר קְיַם קֳדָם כָּל עַמָךְ אֶעְבֵּד פְּרִישָׁן דִי לָא אִתְבְּרִיאוּ בְּכָל אַרְעָא וּבְכָל עַמְמַיָא וְיֶחֱזֵי כָל עַמָא דִי אַתְּ בֵּינֵיהוֹן יָת עוֹבָדָא דַיְיָ אֲרֵי דָחֵל הוּא דִי אֲנָא עָבֵד עִמָךְ:
@972 טָר לָךְ יָת דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין הָא אֲנָא מְתָרֵךְ מִן קֳדָמָךְ יָת אֱמוֹרָאֵי וּכְנַעֲנָאֵי וְחִתָּאֵי וּפְרִזָאֵי וְחִוָאֵי וִיבוּסָאֵי:
@973 אִסְתַּמַר לָךְ דִילְמָא תִגְזַר קְיַם לְיָתֵב אַרְעָא דִי אַתְּ עָלֵל עֲלַהּ דִילְמָא יְהֵי לְתַקְלָא בֵּינָךְ:
@974 אֲרֵי יָת אֲגוֹרֵיהוֹן תְּתַרְעוּן וְיָת קָמַתְהוֹן תְּתַבְּרוּן וְיָת אַשְׁרֵיהוֹן תְּקַצְצוּן:
@975 אֲרֵי לָא תִסְגוֹד לְטַעֲוַת עַמְמַיָא אֲרֵי יְיָ קַנָא שְׁמֵהּ אֵל קַנָא הוּא:
@976 דִילְמָא תִגְזַר קְיַם לְיָתֵב אַרְעָא וְיִטְּעוּן בָּתַר טַּעֲוַתְהוֹן וְיִדְבְּחוּן לְטַּעֲוַתְהוֹן וְיִקְרוּן לָךְ וְתֵיכוּל מִדִבְחֵיהוֹן:
@977 וְתִסַב מִבְּנַתְהוֹן לִבְנָיךְ וְיִטְעַיָן בְּנַתְהוֹן בָּתַר טַעֲוַתְהוֹן וְיִטְעַיַן יָת בְּנָיךְ בָּתַר טַעֲוַתְהוֹן:
@978 דַחֲלַן דְמַתְּכָא לָא תַעְבֵּד לָךְ:
@979 יָת חַגָא דְפַטִּירַיָא תִּטַר שַׁבְעָא יוֹמִין תֵּיכוֹל פַּטִירָא כְּמָא דִי פַקֵדִתָּךְ לִזְמַן יַרְחָא דְאַבִּיבָא אֲרֵי בְּיַרְחָא דְאַבִּיבָא נְפַקְתָּא מִמִצְרָיִם:
@980 כָּל פָּתַח וַלְדָא דִילִי וְכָל בְּעִירָךְ דִכְרִין תַּקְדֵשׁ בְּכוֹר תּוֹר וְאִימָר:
@981 וּבוּכְרָא דַחֲמָרָא תִּפְרוֹק בְּאִימְרָא וְאִם לָא תִפְרוֹק וְתַנְקְפֵהּ כָּל בּוּכְרָא דִבְנָיךְ תִּפְרוֹק וְלָא יִתְחֲזוּן קֳדָמַי רֵיקָנִין:
@982 שִׁתָּא יוֹמִין תִּפְלָח וּבְיוֹמָא שְׁבִיעָאָה תְּנוּחַ בִּזְרוֹעָא וּבַחֲצָדָא תְּנוּחַ:
@983 וְחַגָא דְשָׁבוּעַיָא תַּעְבֵּד לָךְ בִּכּוּרֵי חֲצַד חִטִין וְחַגָא דִכְנָשָׁא בְּמִפְקָא דְשַׁתָּא:
@984 תְּלַת זִמְנִין בְּשַׁתָּא יִתְחֲזוּן כָּל דְכוּרָךְ קֳדָם רִבּוֹן עָלְמָא יְיָ אֱלָהָא דְיִשְׂרָאֵל:
@985 אֲרֵי אֲתָרֵךְ עַמְמִין מִן קֳדָמָךְ וְאַפְתֵּי יָת תְּחוּמָךְ וְלָא יַחְמֵד אֱנַשׁ יָת אַרְעָךְ בְּמִסְקָךְ לְאִתְחַזָאָה קֳדָם יְיָ אֱלָהָךְ תְּלַת זִמְנִין בְּשַׁתָּא:
@986 לָא תִכּוֹס עַל חֲמִיעַ דַם פִּסְחִי וְלָא יְבִיתוּן לְצַפְרָא בַּר מִמַדְבְּחָא תַּרְבֵּי נִכְסַת חַגָא דְפִסְחָא:
@987 רֵישׁ בִּכּוּרֵי אַרְעָךְ תַּיְתֵי לְבֵית מַקְדְשָׁא דַיְיָ אֱלָהָךְ לָא תֵיכְלוּן בְּשַׂר בַּחֲלָב:
@988 וַאֲמַר יְיָ לְמשֶׁה כְּתַב לָךְ יָת פִּתְגָמַיָא הָאִלֵין אֲרֵי עַל מֵימַר פִּתְגָמַיָא הָאִלֵין גְזָרִית עִמָךְ קְיַם וְעִם יִשְׂרָאֵל:
@989 וַהֲוָה תַמָן קֳדָם יְיָ אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן לַחְמָא לָא אֲכַל וּמַיָא לָא שְׁתֵי וּכְתַב עַל לוּחַיָא יָת פִּתְגָמֵי קְיָמָא עַשְׂרָא פִּתְגָמִין:
@990 וַהֲוָה כַּד נְחַת משֶׁה מִטוּרָא דְסִינַי וּתְרֵין לוּחֵי סַהֲדוּתָא בִּידָא דְמשֶׁה בְּמֵחֲתֵהּ מִן טוּרָא וּמשֶׁה לָא יְדַע אֲרֵי סְגֵי זִיו יְקָרָא דְאַפּוֹהִי בְּמַלָלוּתֵהּ עִמֵהּ:
@991 וַחֲזָא אַהֲרֹן וְכָל בְּנֵי יִשְׂרָאֵל יָת משֶׁה וְהָא סְגֵי זִיו יְקָרָא דְאַפּוֹהִי וּדְחִילוּ מִלְאִתְקְרְבָא לְוָתֵהּ:
@992 וּקְרָא לְהוֹן משֶׁה וְתָבוּ לְוָתֵהּ אַהֲרֹן וְכָל רַבְרְבַיָא בִּכְנִשְׁתָּא וּמַלֵל משֶׁה עִמְהוֹן:
@993 וּבָתַר כֵּן אִתְקְרִיבוּ כָּל בְּנֵי יִשְׂרָאֵל וּפַקֵדִנוּן יָת כָּל דִי מַלֵל יְיָ עִמֵהּ בְּטוּרָא דְסִינָי:
@994 וְשֵׁיצֵי משֶׁה מִלְמַלָלָא עִמְהוֹן וִיהַב עַל אַפּוֹהִי בֵּית אַפֵּי:
@995 וְכַד עָלֵל משֶׁה לִקֳדָם יְיָ לְמַלָלָא עִמֵה אַעְדִי יָת בֵּית אַפּוֹהִי עַד מִפְקֵהּ וְנָפֵק וּמְמַלֵל עִם בְּנֵי יִשְׂרָאֵל יָת דִי מִתְפַּקָד:
@996 וַחֲזָן בְּנֵי יִשְׂרָאֵל יָת אַפֵּי משֶׁה אֲרֵי סְגֵי זִיו יְקָרָא דְאַפֵי משֶׁה וַאֲתֵב משֶׁה יָת בֵּית אַפֵּי עַל אַפּוֹהִי עַד דְעָלֵל לְמַלָלָא עִמֵהּ: ססס:
@997 וְאַכְנֵשׁ משֶׁה יָת כָּל כְּנִשְׁתָּא דִבְנֵי יִשְרָאֵל וַאֲמַר לְהוֹן אִלֵין פִּתְגָמַיָא דִי פַקֵד יְיָ לְמֶעְבַּד יָתְהוֹן:
@998 שִׁתָּא יוֹמִין תִּתְעֲבֵד עִבִדְתָּא וּבְיוֹמָא שְׁבִיעָאָה יְהֵי לְכוֹן קוּדְשָׁא שַׁבָּא שַׁבְּתָא קֳדָם יְיָ כָּל דְיַעֲבֵד בֵּה עִבִדְתָּא יִתְקְטֵל:
@999 לָא תְבַעֲרוּן אֶשָׁתָא בְּכֹל מוֹתְבָנֵיכוֹן בְּיוֹמָא דְשַׁבְּתָא:
@1000 וַאֲמַר משֶׁה לְכָל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל לְמֵימָר דֵין פִּתְגָּמָא דִי פַקֵד יְיָ לְמֵימָר:
@1001 סָבוּ מִנְכוֹן אַפְרָשׁוּתָא קֳדָם יְיָ כֹּל דְיִתְרְעֵי לִבֵּהּ יַיְתֵי יָת אַפְרָשׁוּתָא קֳדָם יְיָ דַהֲבָא וְכַסְפָא וּנְחָשָׁא:
@1002 וְתִכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ וּמֵעַזֵי:
@1003 וּמַשְׁכֵי דְדִכְרֵי מְסַמְקֵי וּמַשְׁכֵי דְסַסְגוֹנָא וְאָעֵי שִׁטִין:
@1004 וּמִשְׁחָא לְאַנְהָרוּתָא וּבוּסְמַיָא לִמְשַׁח רְבוּתָא וְלִקְטֹרֶת בּוּסְמַיָא:
@1005 וְאַבְנֵי בוּרְלָא וְאַבְנֵי אַשְׁלָמוּתָא לְשַׁקָעָא בְּאֵפוֹדָא וּבְחוּשְׁנָא:
@1006 וְכָל חַכִּימֵי לִבָּא בְּכוֹן יֵיתוּן וְיַעְבְדוּן יָת כָּל דִי פַקֵד יְיָ:
@1007 יָת מַשְׁכְּנָא יָת פְּרָסֵהּ וְיָת חוֹפָאֵהּ יָת פּוּרְפוֹהִי וְיָת דַפּוֹהִי יָת עַבְרוֹהִי יָת עַמוּדוֹהִי וְיָת סַמְכוֹהִי:
@1008 יָת אֲרוֹנָא וְיָת אֲרִיחוֹהִי יָת כַּפֻּרְתָּא וְיָת פָּרֻכְתָּא דִפְרָסָא:
@1009 יָת פָּתוֹרָא וְיָת אֲרִיחוֹהִי וְיָת כָּל מָנוֹהִי וְיָת לְחֵם אַפַּיָא:
@1010 וְיָת מְנַרְתָּא דְאַנְהוֹרֵי וְיָת מָנָהָא וְיָת בּוֹצִינָהָא וְיָת מִשְׁחָא דְאַנְהָרוּתָא:
@1011 וְיָת מַדְבְּחָא דִקְטוֹרֶת בּוּסְמַיָא וְיָת אֲרִיחוֹהִי וְיָת מִשְׁחָא דִרְבוּתָא וְיָת קְטֹרֶת בּוּסְמַיָא וְיָת פְּרָסָא דְתַרְעָא לִתְרַע מַשְׁכְּנָא:
@1012 יָת מַדְבְּחָא דַעֲלָתָא וְיָת סְרָדָא דִנְחָשָׁא דִילֵהּ יָת אָרִיחוֹהִי וְיָת כָּל מָנוֹהִי יָת כִּיוֹרָא וְיָת בְּסִיסֵהּ:
@1013 יָת סְרָדֵי דַרְתָּא יָת עַמוּדוֹהִי וְיָת סַמְכָהָא וְיָת פְּרָסָא דִתְרַע דַרְתָּא:
@1014 יָת סִכֵּי מַשְׁכְּנָא וְיָת סִכֵּי דְדַרְתָּא וְיָת אַטוּנֵיהוֹן:
@1015 יָת לְבוּשֵׁי שִׁמוּשָׁא לְשַׁמָשָׁא בְקוּדְשָׁא יָת לְבוּשֵׁי קוּדְשָׁא לְאַהֲרֹן כַּהֲנָא וְיָת לְבוּשֵׁי בְנוֹהִי לְשַׁמָשָׁא:
@1016 וּנְפָקוּ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל מִן קֳדָם משֶׁה:
@1017 וַאֲתוֹ כָּל גְבַר דְאִתְרְעֵי לִבֵּהּ וְכֹל דִי אַשְׁלֵמַת רוּחֵהּ יָתֵהּ אַיְתִיאוּ יָת אַפְרָשׁוּתָא קֳדָם יְיָ לַעֲבִידַת מַשְׁכַּן זִמְנָא וּלְכָל פֻּלְחָנֵהּ וְלִלְבוּשֵׁי קוּדְשָׁא:
@1018 וּמַיְתַן גֻבְרַיָא עַל נְשַׁיָא כֹּל דְאִתְרְעֵי לִבֵּהּ אַיְתִיאוּ שֵׁירִין וְשִׁבְכִין וְעִזְקַן וּמָחוּךְ כָּל מָן דִדְהַב וְכָל גְּבַר דִי אֲרֵים אֲרָמוּת דַהֲבָא קֳדָם יְיָ:
@1019 וְכָל גְבַר דְאִשְׁתְּכַח עִמֵהּ תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ וּמֵעַזֵי וּמַשְׁכֵי דְדִכְרֵי מְסַמְקֵי וּמַשְׁכֵי סַסְגוֹנָא אַיְתִיאוּ:
@1020 כָּל דַאֲרֵים אֲרָמוּת כְּסַף וּנְחַשׁ אַיְתִיאוּ יָת אַפְרָשׁוּתָא קֳדָם יְיָ וְכֹל דִי אִשְׁתְּכַח עִמֵהּ אָעֵי שִׁטִין לְכָל עִבִידַת פֻּלְחָנָא אַיְתִיאוּ:
@1021 וְכָל אִתְּתָא חַכִּימַת לִבָּא בִּידָהָא מְעַזְלָא וּמַיְתַן כַּד עָזֵל יָת תִּכְלָא וְיָת אַרְגְוָנָא יָת צְבַע זְהוֹרִי וְיָת בּוּצָא:
@1022 וְכָל נְשַׁיָא דְאִתְרְעֵי לִבְּהֶן עִמְהֶן בְּחָכְמָא עַזְלַן יָת מֵעַזְיָא:
@1023 וְרַבְרְבַיָא אַיְתִיאוּ יָת אַבְנֵי בוּרְלָא וְיָת אַבְנֵי אַשְׁלָמוּתָא לְשַׁקָעָא בְאֵפוֹדָא וּבְחוּשְׁנָא:
@1024 וְיָת בּוּסְמָא וְיָת מִשְׁחָא לְאַנְהָרוּתָא וּלְמִשְׁחָא דִרְבוּתָא וְלִקְטוֹרֶת בּוּסְמַיָא:
@1025 כָּל גְבַר וְאִתְּתָא דְאִתְרְעֵי לִבְּהוֹן עִמְהוֹן לְאַיְתָאָה לְכָל עִבִדְתָּא דִי פַקֵד יְיָ לְמֶעְבַּד בִּידָא דְמשֶׁה אַיְתִיאוּ בְנֵי יִשְׂרָאֵל נְדַבְתָּא קֳדָם יְיָ:
@1026 וַאֲמַר משֶׁה לִבְנֵי יִשְׂרָאֵל חֲזוֹ דְרַבִּי יְיָ בְּשׁוּם בְּצַלְאֵל בַּר אוּרִי בַר חוּר לְשִׁבְטָא דִיהוּדָה:
@1027 וְאַשְׁלֵם עִמֵהּ רוּחַ נְבוּאָה מִן קֳדָם יְיָ בְּחָכְמְתָא בְּסוּכְלְתָנוּ וּבְמַדַע וּבְכָל עִבִידָא:
@1028 וּלְאַלָפָא אוּמַנְוָן לְמֶעְבַּד בְּדַהֲבָא וּבְכַסְפָא וּבִנְחָשָׁא:
@1029 וּבְאוּמָנוּת אֶבֶן טָבָא לְאַשְׁלָמָא וּבְנַגָרוּת אָעָא לְמֶעְבַּד בְּכָל עִבִידַת אוּמַנְוָן:
@1030 וּלְאַלָפָא יְהַב בְּלִבֵּהּ הוּא וְאָהֳלִיאָב בַּר אֲחִיסָמָךְ לְשִׁבְטָא דְדָן:
@1031 אַשְׁלֵם עִמְהוֹן חַכִּימוּת לִבָּא לְמֶעְבַּד כָּל עִבִידַת נַגָר וְאָמָן וְצַיָר בְּתִכְלָא וּבְאַרְגְוָנָא בִּצְבַע זְהוֹרִי וּבְבוּצָא וּמַחֵי עָבְדֵי כָּל עֲבִידָא וּמַלְפֵי אוּמַנְוָן:
@1032 וַעֲבַד בְּצַלְאֵל וְאָהֳלִיאָב וְכָל גְבַר חַכִּים לִבָּא דִיהַב יְיָ חָכְמָא וְסוּכְלְתָנוּתָא בְּהוֹן לְמִדַע לְמֶעְבַּד יָת כָּל עִבִידַת פָלְחַן קוּדְשָׁא לְכֹל דִי פַקֵד יְיָ:
@1033 וּקְרָא משֶׁה לִבְצַלְאֵל וּלְאָהֳלִיאָב וּלְכָל גְּבַר חַכִּים לִבָּא דִיהַב יְיָ חָכְמְתָא בְּלִבֵּה כָּל דְאִתְרְעֵי לִבֵּהּ לְמִקְרַב לְעִבִדְתָּא לְמֶעְבַּד יָתַהּ:
@1034 וּנְסִיבוּ מִן קֳדָם משֶׁה יָת כָּל אַפְרָשׁוּתָא דִי אַיְתִיאוּ בְּנֵי יִשְׂרָאֵל לְעִבִידַת פָּלְחַן קוּדְשָׁא לְמֶעְבַּד יָתַהּ וְאִנוּן מַיְתַן לֵהּ עוֹד נְדַבְתָּא בִּצְפַר בִּצְפָר:
@1035 וַאֲתוֹ כָּל חַכִּימַיָא דְעָבְדִין יָת כָּל עִבִידַת קוּדְשָׁא גְבַר גְבַר מֵעִבִדְתֵּהּ דְאִנוּן עָבְדִין:
@1036 וַאֲמָרוּ לְמשֶׁה לְמֵימַר מַסְגַן עַמָא לְאַיְתָאָה מִסַת פָּלְחָנָא לְעִבִדְתָּא דְפַקֵד יְיָ לְמֶעְבַּד יָתַהּ:
@1037 וּפַקֵד משֶׁה וַאַעֲבַרוּ כְרוֹזָא בְּמַשְׁרִיתָא לְמֵימַר גְבַר וְאִתְּתָא לָא יַעַבְדוּן עוֹד עִבִדְתָּא לְאַפְרָשׁוּת קוּדְשָׁא וּפְסַק עַמָא מִלְאַיְתָאָה:
@1038 וְעִבִדְתָּא הֲוַת מִסַת לְכָל עִבִדְתָּא לְמֶעְבַּד יָתַהּ וִיתָרָת:
@1039 וַעֲבָדוּ כָל חַכִּימֵי לִבָּא בְּעָבְדֵי עִבִדְתָּא יָת מַשְׁכְּנָא עֲשַׂר יְרִיעָן דְבוּץ שְׁזִיר וְתִכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי צוּרַת כְּרוּבִין עוֹבַד אֳמָן עֲבַד יָתְהוֹן:
@1040 אֻרְכָּא דִירִעֲתָא חֲדָא עַסְרִין וּתְמַנְיָא אַמִין וּפוּתְיָא אַרְבַּע אַמִין דִירִיעֲתָא חֲדָא מְשַׁחְתָּא חֲדָא לְכָל יְרִיעָתָא:
@1041 וְלָפֵף יָת חָמֵשׁ יְרִיעָן חֲדָא עִם חֲדָא וְחָמֵשׁ יְרִיעָן לָפֵף חֲדָא עִם חֲדָא:
@1042 וַעֲבַד עֲנוּבִין דְתִכְלָא עַל סִפְתָא דִירִעֲתָא חֲדָא מִסִטְרָא בֵּית לוֹפֵי כֵּן עֲבַד בְּסִפְתָא דִירִיעֲתָא בְּסִטְרָא בֵּית לוֹפֵי תִּנְיֵתָא:
@1043 חַמְשִׁין עֲנוּבִין עֲבַד בִּירִיעֲתָא חֲדָא וְחַמְשִׁין עֲנוּבִין עֲבַד בְּסִטְרָא דִירִיעֲתָא דְבֵית לוֹפֵי תִּנְיֵתָא מְכַוְנָן עֲנוּבַיָא חֲדָא לָקֳבֵל חֲדָא:
@1044 וַעֲבַד חַמְשִׁין פּוּרְפִין דִדְהַב וְלָפֵף יָת יְרִיעֲתָא חֲדָא עִם חֲדָא בְּפוּרְפַיָא וַהֲוָה מַשְׁכְּנָא חָד:
@1045 וַעֲבַד יְרִיעָן דִמְעַזֵי לִפְרָסָא עַל מַשְׁכְּנָא חַד עֲשַׂר יְרִיעָן עֲבַד יָתְהֶן:
@1046 אֻרְכָּא דִירִיעֲתָא חֲדָא תְּלָתִין בְּאַמִין וְאַרְבַּע אַמִין פּוּתְיָא דִירִיעֲתָא חֲדָא מְשַׁחְתָּא חֲדָא לְחַד עֲשַׂר יְרִיעָן:
@1047 וְלָפֵף יָת חָמֵשׁ יְרִיעָן לְחוֹד וְיָת שִׁית יְרִיעָן לְחוֹד:
@1048 וַעֲבַד עֲנוּבִין חַמְשִׁין עַל סִפְתָא דִירִיעֲתָא בְּסִטְרָא בֵּית לוֹפֵי וְחַמְשִׁין עֲנוּבִין עֲבַד עַל סִפְתָא דִירִיעֲתָא דְבֵית לוֹפֵי תִּנְיֵתָא:
@1049 וַעֲבַד פּוּרְפִין דִנְחָשָׁא חַמְשִׁין לְלַפָּפָא יָת מַשְׁכְּנָא לְמֶהֱוֵי חָד:
@1050 וַעֲבַד חוֹפָאָה לְמַשְׁכְּנָא מַשְׁכֵי דְדִכְרֵי מְסַמְקֵי וְחוֹפָאָה מַשְׁכֵי דְסַסְגוֹנָא מִלְעֵלָא:
@1051 וַעֲבַד יָת דַפַּיָא לְמַשְׁכְּנָא דְאָעֵי שִׁטִין קָיְמִין:
@1052 עֲשַׂר אַמִין אֻרְכָּא דְדַפָּא וְאַמְתָא וּפַלְגוּת אַמְתָא פּוּתְיָא דְדַפָּא חָד:
@1053 תַּרְתֵּין צִירִין לְדַפָּא חַד מְשַׁלְבִין חֲדָא לָקֳבֵל חֲדָא כֵּן עֲבַד לְכֹל דַפֵּי מַשְׁכְּנָא:
@1054 וַעֲבַד יָת דַפַּיָא לְמַשְׁכְּנָא עֶסְרִין דַפִּין לְרוּחַ עֵבַר דָרוֹמָא:
@1055 וְאַרְבְּעִין סַמְכִין דִכְסַף עֲבַד תְּחוֹת עֶסְרִין דַפִּין תְּרֵין סַמְכִין תְּחוֹת דַפָּא חַד לִתְרֵין צִירוֹהִי וּתְרֵין סַמְכִין תְּחוֹת דַפָּא חַד לִתְרֵין צִירוֹהִי:
@1056 וְלִסְטַר מַשְׁכְּנָא תִּנְיֵתָא לְרוּחַ צִפּוּנָא עֲבַד עֶסְרִין דַפִּין:
@1057 וְאַרְבְּעִין סַמְכֵיהוֹן דִכְסָף תְּרֵין סַמְכִין תְּחוֹת דַפָּא חַד וּתְרֵין סַמְכִין תְּחוֹת דַפָּא חָד:
@1058 וְלִסְיָפֵי מַשְׁכְּנָא מַעַרְבָא עֲבַד שִׁתָּא דַפִין:
@1059 וּתְרֵין דַפִין עֲבַד לְזָוְיַת מַשְׁכְּנָא בְּסוֹפֵיהוֹן:
@1060 וַהֲווֹ מְכַוְנִין מִלְרַע וְכַחֲדָא הֲווֹ מְכַוְנִין עַל רֵישֵׁהּ לְעִזְקָתָא חֲדָא כֵּן עֲבַד לְתַרְוֵיהוֹן לִתְרֵין זָוְיָן:
@1061 וַהֲווֹ תְּמַנְיָא דַפִּין וְסַמְכֵיהוֹן דִכְסַף שִׁתָּא עֲשַׂר סַמְכִין תְּרֵין סַמְכִין תְּרֵין סַמְכִין תְּחוֹת דַפָּא חָד:
@1062 וַעֲבַד עַבְּרֵי דְאָעֵי שִׁטִין חַמְשָׁא לְדַפֵּי סְטַר מַשְׁכְּנָא חָד:
@1063 וְחַמְשָׁא עַבְּרִין לְדַפֵּי סְטַר מַשְׁכְּנָא תִּנְיֵתָא וְחַמְשָׁא עַבְּרִין לְדַפֵּי מַשְׁכְּנָא לְסוֹפֵיהוֹן מַעַרְבָא:
@1064 וַעֲבַד יָת עַבְּרָא מְצִיעָאָה לְאַעְבָּרָא בְּגוֹ דַפַּיָא מִן סְיָפֵי לִסְיָפֵי:
@1065 וְיָת דַפַּיָא חֲפָא דַהֲבָא וְיָת עִזְקָתְהוֹן עֲבַד דַהֲבָא אַתְרָא לְעַבְּרַיָא וַחֲפָא יָת עַבְּרַיָא דַהֲבָא:
@1066 וַעֲבַד יָת פָּרֻכְתָּא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר עוֹבַד אֳמָן עֲבַד יָתַהּ צוּרַת כְּרוּבִין:
@1067 וַעֲבַד לַהּ אַרְבְּעָא עַמוּדֵי שִׁטִין וַחֲפָנוּן דַהֲבָא וָוֵיהוֹן דַהֲבָא וְאַתִּיךְ לְהוֹן אַרְבְּעָא סַמְכִין דִכְסָף:
@1068 וַעֲבַד פְּרָסָא לִתְרַע מַשְׁכְּנָא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר עוֹבַד צַיָר:
@1069 וְיָת עַמוּדוֹהִי חַמְשָׁא וְיָת וָוֵיהוֹן וַחֲפָא רֵישֵׁיהוֹן וְכִבּוּשֵׁיהוֹן דַהֲבָא וְסַמְכֵיהוֹן חַמְשָׁא נְחָשָׁא:
@1070 וַעֲבַד בְּצַלְאֵל יָת אֲרוֹנָא דְאָעֵי שִׁטִין תַּרְתֵּין אַמִין וּפַלְגָא אֻרְכֵּהּ וְאַמְתָא וּפַלְגָא פְתָיֵהּ וְאַמְתָא וּפַלְגָא רוּמֵהּ:
@1071 וַחֲפָהִי דְהַב דְכֵי מִגָּו וּמִבָּרָא וַעֲבַד לֵהּ דֵיר דִדְהַב סְחוֹר סְחוֹר:
@1072 וְאַתִּיךְ לֵהּ אַרְבַּע עִזְקַן דִדְהַב עַל אַרְבַּע זִוְיָתֵהּ וְתַרְתֵּין עִזְקַן עַל סִטְרֵהּ חַד וְתַרְתֵּין עִזְקַן עַל סִטְרֵהּ תִּנְיֵתָא:
@1073 וַעֲבַד אֲרִיחֵי דְאָעֵי שִׁטִין וַחֲפָא יָתְהוֹן דַהֲבָא:
@1074 וְאָעֵיל יָת אֲרִיחַיָא בְּעִזְקָתָא עַל סִטְרֵי אֲרוֹנָא לְמִטָל יָת אֲרוֹנָא:
@1075 וַעֲבַד כַּפֻּרְתָּא דְהַב דְכֵי תַּרְתֵּין אַמִין וּפַלְגָא אֻרְכַּהּ וְאַמְתָא וּפַלְגָא פְתָיַהּ:
@1076 וַעֲבַד תְּרֵין כְּרוּבִין דִדְהָב נְגִיד עֲבַד יָתְהוֹן מִתְּרֵין סִטְרֵי כַפֻּרְתָּא:
@1077 כְּרוּבָא חַד מִסִטְרָא מִכָּא וּכְרוּבָא חַד מִסִטְרָא מִכָּא מִן כַּפֻּרְתָּא עֲבַד יָת כְּרוּבַיָא מִתְּרֵין סִטְרוֹהִי:
@1078 וַהֲווֹ כְרוּבַיָא פְּרִיסָן גַדְפֵיהוֹן לְעֵלָא נָטְלִין בְּגַדְפֵיהוֹן עַל כַּפֻּרְתָּא וְאַפֵּיהוֹן חַד לָקֳבֵל חַד לָקֳבֵל כַּפֻּרְתָּא הֲווֹ אַפֵּי כְרוּבַיָא:
@1079 וַעֲבַד יָת פָּתוֹרָא דְאָעֵי שִׁטִין תַּרְתֵּין אַמִין אֻרְכֵּהּ וְאַמְתָא פְתָיֵהּ וְאַמְתָא וּפַלְגָא רוּמֵהּ:
@1080 וַחֲפָא יָתֵהּ דְהַב דְכֵי וַעֲבַד לֵהּ דֵיר דִדְהַב סְחוֹר סְחוֹר:
@1081 וַעֲבַד לֵהּ גְדַנְפָא רוּמֵהּ פּוּשְׁכָא סְחוֹר סְחוֹר וַעֲבַד דֵיר דִדְהַב לִגְדַנְפֵהּ סְחוֹר סְחוֹר:
@1082 וְאַתִּיךְ לֵהּ אַרְבַּע עִזְקַן דִדְהָב וִיהַב יָת עִזְקֳתָא עַל אַרְבַּע זִוְיָתָא דִי לְאַרְבַּע רַגְלוֹהִי:
@1083 לָקֳבֵל גְדַנְפָא הֲווֹ עִזְקָתָא אַתְרָא לַאֲרִיחַיָא לְמִטַל יָת פָּתוֹרָא:
@1084 וַעֲבַד יָת אֲרִיחַיָא דְאָעֵי שִׁטִּין וַחֲפָא יָתְהוֹן דַהֲבָא לְמִטַל יָת פָּתוֹרָא:
@1085 וַעֲבַד יָת מָנַיָא דִי עַל פָּתוֹרָא יָת מָגִיסוֹהִי וְיָת בָּזִיכּוֹהִי וְיָת מְכִילָתֵהּ וְיָת קַשְׂוָתָא דִי יִתְנַסַךְ בְּהוֹן דְהַב דְכֵי:
@1086 וַעֲבַד יָת מְנַרְתָּא דְהַב דְכֵי נְגִיד עֲבַד יָת מְנַרְתָּא שִׁידַהּ וּקְנַהּ כַּלִידָהָא חֵזוּרָהָא וְשׁוֹשַׁנָהָא מִנַהּ הֲווֹ:
@1087 וְשִׁתָּא קְנִין נָפְקִין מִסִטְרָהָא תְּלָתָא קְנֵי מְנַרְתָּא מִסִטְרַהּ חַד וּתְלָתָא קְנֵי מְנַרְתָּא מִסִטְרַהּ תִּנְיָנָא:
@1088 תְּלָתָא כַלִידִין מְצַיְרִין בְּקַנְיָא חַד חֵזוּר וְשׁוֹשָׁן וּתְלָתָא כַלִידִין מְצַיְרִין בְּקַנְיָא חַד חֵזוּר וְשׁוֹשָׁן כֵּן לְשִׁתָּא קְנִין דְנָפְקִין מִן מְנַרְתָּא:
@1089 וּבִמְנַרְתָּא אַרְבְּעָא כַלִידִין מְצַיְרִין חֵזוּרָהָא וְשׁוֹשַׁנָהָא:
@1090 וְחֵזוּר תְּחוֹת תְּרֵין קְנִין מִנַהּ וְחֵזוּר תְּחוֹת תְּרֵין קְנִין מִנַהּ וְחֵזוּר תְּחוֹת תְּרֵין קְנִין מִנַהּ לְשִׁתָּא קְנִין דְנַפְקִין מִנַהּ:
@1091 חֵזוּרֵיהוֹן וּקְנֵיהוֹן מִנַהּ הֲווֹ כֻּלַהּ נְגִידָא חֲדָא דְהַב דְכֵי:
@1092 וַעֲבַד יָת בּוֹצִינָהָא שִׁבְעָא וְצִבְיְתָהָא וּמַחְתְּיָתָהָא דְהַב דְכֵי:
@1093 כִּכְּרָא דְהַב דְכֵי עֲבַד יָתַהּ וְיָת כָּל מָנָהָא:
@1094 וַעֲבַד יָת מַדְבְּחָא דִקְטֹּרֶת בּוּסְמַיָא דְאָעֵי שִׁטִין אַמְתָא אֻרְכֵּהּ וְאַמְתָא פְתָיֵהּ מְרַבַּע וְתַרְתֵּין אַמִין רוּמֵהּ מִנֵהּ הֲווֹ קַרְנוֹהִי:
@1095 וַחֲפָא יָתֵהּ דְהַב דְכֵי יָת אִגָרֵה וְיָת כָּתְלוֹהִי סְחוֹר סְחוֹר וְיָת קַרְנוֹהִי וַעֲבַד לֵהּ דֵיר דִדְהַב סְחוֹר סְחוֹר:
@1096 וְתַרְתֵּין עִזְקַן דִדְהַב עֲבַד לֵהּ מִלְרַע לְדֵירֵהּ עַל תַּרְתֵּין זִוְיָתֵהּ עַל תְּרֵין סִטְרוֹהִי לְאַתְרָא לַאֲרִיחַיָא לְמִטַל יָתֵהּ בְּהוֹן:
@1097 וַעֲבַד יָת אֲרִיחַיָא דְאָעֵי שִׁטִין וַחֲפָא יָתְהוֹן דַהֲבָא:
@1098 וַעֲבַד יָת מִשְׁחָא דִרְבוּתָא קוּדְשָׁא וְיָת קְטֹרֶת בּוּסְמַיָא דְכֵי עוֹבַד בּוּסְמָנוּ:
@1099 וַעֲבַד יָת מַדְבְּחָא דַעֲלָתָא דְאָעֵי שִׁטִין חֲמֵשׁ אַמִין אֻרְכֵּהּ וַחֲמֵשׁ אַמִין פְּתָיֵהּ מְרַבַּע וּתְלָתָא אַמִין רוּמֵהּ:
@1100 וַעֲבַד קַרְנוֹהִי עַל אַרְבַּע זִוְיָתֵהּ מִנֵהּ הֲווֹ קַרְנוֹהִי וַחֲפָא יָתֵהּ נְחָשָׁא:
@1101 וַעֲבַד יָת כָּל מָנֵי מַדְבְּחָא יָת פְּסַכְתְּרָוָתָא וְיָת מַגְרוֹפְיָתָא וְיָת מִזְרְקָתָא יָת צִנוֹרְיָתָא וְיָת מַחְתְּיָתָא כָּל מָנוֹהִי עֲבַד נְחָשָׁא:
@1102 וַעֲבַד לְּמַדְבְּחָא סְרָדָא עוֹבַד מְצַדְתָּא דִנְחָשָׁא תְּחוֹת סוֹבָבֵהּ מִלְרַע עַד פַּלְגֵהּ:
@1103 וְאַתִּיךְ אַרְבַּע עִזְקָתָא בְּאַרְבַּע סִטְרָתָא לִסְרָדָא דִנְחָשָׁא אַתְרָא לַאֲרִיחַיָא:
@1104 וַעֲבַד יָת אֲרִיחַיָא דְאָעֵי שִׁטִין וַחֲפָא יָתְהוֹן נְחָשָׁא:
@1105 וְאָעֵיל יָת אֲרִיחַיָא בְּעִזְקָתָא עַל סִטְרֵי מַדְבְּחָא לְמִטַל יָתֵהּ בְּהוֹן חֲלִיל לוּחִין עֲבַד יָתֵהּ:
@1106 וַעֲבַד יָת כִּיוֹרָא נְחָשָׁא וְיָת בְּסִיסֵהּ נְחָשָׁא בְּמֶחְזְיַן נְשַׁיָא דְאָתְיָן לְצַלָאָה בִּתְרַע מַשְׁכַּן זִמְנָא:
@1107 וַעֲבַד יָת דַרְתָּא לְרוּחַ עֵבַר דָרוֹמָא סְרָדֵי דַרְתָּא דְבוּץ שְׁזִיר מְאָה בְאַמִין:
@1108 עַמוּדֵיהוֹן עֶסְרִין וְסַמְכֵיהוֹן עֶסְרִין נְחָשָׁא וָוֵי עַמוּדַיָא וְכִבּוּשֵׁיהוֹן דִכְסָף:
@1109 וּלְרוּחַ צִפּוּנָא מְאָה אַמִין עַמוּדֵיהוֹן עֶסְרִין וְסַמְכֵיהוֹן עֶסְרִין נְחָשָׁא וָוֵי עַמוּדַיָא וְכִבּוּשֵׁיהוֹן דִכְסָף:
@1110 וּלְרוּחַ מַעַרְבָא סְרָדִין חַמְשִׁין בְּאַמִין עֲמוּדֵיהוֹן עַסְרָא וְסַמְכֵיהוֹן עַסְרָא וָוֵי עַמוּדַיָא וְכִבּוּשֵׁיהוֹן דִכְסָף:
@1111 וּלְרוּחַ קִדוּמָא מָדִינְחָא חַמְשִׁין אַמִין:
@1112 סְרָדִין חֲמֵשׁ עֶסְרֵי אַמִין לְעִבְרָא עַמוּדֵיהוֹן תְּלָתָא וְסַמְכֵיהוֹן תְּלָתָא:
@1113 וּלְעִבְרָא תִנְיֵתָא מִכָּא וּמִכָּא לִתְרַע דַרְתָּא סְרָדִין חֲמֵשׁ עֶסְרֵי אַמִין עַמוּדֵיהוֹן תְּלָתָא וְסַמְכֵיהוֹן תְּלָתָא:
@1114 כָּל סְרָדֵי דְדַרְתָּא סְחוֹר סְחוֹר דְבוּץ שְׁזִיר:
@1115 וְסַמְכַיָא לְעַמוּדַיָא נְחָשָׁא וָוֵי עַמוּדַיָא וְכִבּוּשֵׁיהוֹן דִכְסַף וְחִפּוּי רֵישֵׁיהוֹן דִכְסָף וְאִנוּן מְכַבְּשִׁין דִכְסָף כָּל עַמוּדֵי דַרְתָּא:
@1116 וּפְרָסָא דִתְרַע דַרְתָּא עוֹבַד צַיָר תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר וְעֶסְרִין אַמִין אֻרְכָּא וְרוּמָא בְּפוּתְיָא חֲמֵשׁ אַמִין לָקֳבֵל סְרָדֵי דַרְתָּא:
@1117 וְעַמוּדֵיהוֹן אַרְבְּעָא וְסַמְכֵיהוֹן אַרְבְּעָא נְחָשָׁא וָוֵיהוֹן דִכְסַף וְחִפּוּי רֵישֵׁיהוֹן וְכִבּוּשֵׁיהוֹן דִכְסָף:
@1118 וְכָל סִכַּיָא לְמַשְׁכְּנָא וּלְדַרְתָּא סְחוֹר סְחוֹר דִנְחָשָׁא: ססס:
@1119 אִלֵין מִנְיָנֵי מַשְׁכְּנָא מַשְׁכְּנָא דְסַהֲדוּתָא דִי אִתְמְנֵי עַל מֵימְרָא דְמשֶׁה פָּלְחַן לֵיוָאֵי בִּידָא דְאִיתָמָר בַּר אַהֲרֹן כַּהֲנָא:
@1120 וּבְצַלְאֵל בַּר אוּרִי בַר חוּר לְשִׁבְטָא דִיהוּדָה עֲבַד יָת כָּל דִי פַקֵיד יְיָ יָת משֶׁה:
@1121 וְעִמֵהּ אָהֳלִיאָב בַּר אֲחִיסָמָךְ לְשִׁבְטָא דְדָן נַגָר וָאֳמָן וְצַיָר בְּתִכְלָא וּבְאַרְגְוָנָא וּבִצְבַע זְהוֹרִי וּבְבוּצָא:
@1122 כָּל דַהֲבָא דְאִתְעֲבֵד לְעִבִידָא בְּכֹל עִבִידַת קוּדְשָׁא וַהֲוָה דְהַב אֲרָמוּתָא עֶסְרִין וּתְשַׁע כִּכְּרִין וּשְׁבַע מְאָה וּתְלָתִין סִלְעִין בְּסִלְעֵי קוּדְשָׁא:
@1123 וּכְסַף מִנְיָנֵי כְנִשְׁתָּא מְאָה כִכְּרִין וְאֶלֶף וּשְׁבַע מְאָה וְשִׁבְעִין וְחַמְשָׁא סִלְעִין בְּסִלְעֵי קוּדְשָׁא:
@1124 תִּקְלָּא לְגֻלְגַלְתָּא פַלְגוּת סִלְעָא בְּסִלְעֵי קוּדְשָׁא לְכֹל דְעָבַר עַל מִנְיָנַיָא מִבַּר עֶסְרִין שְׁנִין וּלְעֵלָא לְשִׁית מְאָה וּתְלָתָא אַלְפִין וַחֲמֵשׁ מְאָה וְחַמְשִׁין:
@1125 וַהֲוָה מְאָה כִכְּרִין דִכְסַף לְאַתָּכָא יָת סַמְכֵי קוּדְשָׁא וְיָת סַמְכֵי דְפָרֻכְתָּא מְאָה סַמְכִין לִמְאָה כִכְּרִין כִּכְּרָא לְסַמְכָא:
@1126 וְיָת אַלְפָא וּשְׁבַע מְאָה וְשִׁבְעִין וְחַמְשָׁא עֲבַד וָוִין לְעַמוּדַיָא וְחִפָּא רֵישֵׁיהוֹן וְכַבֵּשׁ יָתְהוֹן:
@1127 וּנְחָשָׁא דַאֲרָמוּתָא שִׁבְעִין כִּכְּרִין וּתְרֵין אַלְפִין וְאַרְבַּע מְאָה סִלְעִין:
@1128 וַעֲבַד בַּהּ יָת סַמְכֵי תְּרַע מַשְׁכַּן זִמְנָא וְיָת מַדְבְּחָא דִנְחָשָׁא וְיָת סְרָדָא דִנְחָשָׁא דִי לֵהּ וְיָת כָּל מָנֵי מַדְבְּחָא:
@1129 וְיָת סַמְכֵי דְדַרְתָּא סְחוֹר סְחוֹר וְיָת סַמְכֵי תְּרַע דַרְתָּא וְיָת כָּל סִכֵּי מַשְׁכְּנָא וְיָת כָּל סִכֵּי דַרְתָּא סְחוֹר סְחוֹר:
@1130 וּמִן תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי עֲבָדוּ לְבוּשֵׁי שִׁמוּשָׁא לְשַׁמָשָׁא בְּקוּדְשָׁא וַעֲבָדוּ יָת לְבוּשֵׁי קוּדְשָׁא דִי לְאַהֲרֹן כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@1131 וַעֲבַד יַת אֵפוֹדָא דַהֲבָא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר:
@1132 וְרַדִידוּ יָת טַסֵי דַהֲבָא וְקַצִיצוּ חוּטִין לְמֶעְבַּד בְּגוֹ תִּכְלָא וּבְגוֹ אַרְגְוָנָא וּבְגוֹ צְבַע זְהוֹרִי וּבְגוֹ בוּצָא עוֹבַד אֳמָן:
@1133 כַּתְפָּן עֲבָדוּ לֵהּ מְלַפְּפָן עַל תְּרֵין סִטְרוֹהִי יִתְלָפֵף:
@1134 וְהֶמְיַן תִּקוּנֵהּ דִי עֲלוֹהִי מִנֵהּ הוּא כְּעוֹבָדוֹהִי דַהֲבָא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@1135 וַעֲבָדוּ יָת אַבְנֵי בוּרְלָא מְשַׁקְעָן מְרַמְצָן דִדְהָב גְלִיפָן כְּתַב מְפָרַשׁ עַל שְׁמָהַת בְּנֵי יִשְׂרָאֵל:
@1136 וְשַׁוִי יָתְהוֹן עַל כִּתְפָא דְאֵפוֹדָא אַבְנֵי דוּכְרָנָא לִבְנֵי יִשְׂרָאֵל כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@1137 וַעֲבַד יָת חוּשְׁנָא עוֹבַד אֳמָן כְּעוֹבְדֵי אֵפוֹדָא דַהֲבָּא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר:
@1138 מְרַבַּע הֲוָה עֵיף עֲבָדוּ יָת חוּשְׁנָא זֶרְתָּא אֻרְכֵּהּ וְזֶרְתָּא פְתָיֵהּ עֵיף:
@1139 וְאַשְׁלִימוּ בֵהּ אַרְבְּעָא סִדְרֵי אֶבֶן טָבָא סִדְרָא קַדְמָאָה סַמְקָן יַרְקָן וּבַרְקָן סִדְרָא חָד:
@1140 וְסִדְרָא תִּנְיָנָא אִזְמָרַגְדִין שַׁבְזִיז וְסַבְהֲלוֹם:
@1141 וְסִדְרָא תְּלִיתָאָה קַנְכֵּרֵי טַרְקְיָא וְעֵין עֶגְלָא:
@1142 וְסִדְרָא רְבִיעָאָה כְּרוּם יַמָּא וּבוּרְלָא וּפַנְטֵּרֵי מְשַׁקְעָן מְרַמְצָן דִדְהַב בְּאַשְׁלָמוּתְהוֹן:
@1143 וְאַבְנַיָא עַל שְׁמָהַת בְּנֵי יִשְׂרָאֵל אִנוּן תַּרְתֵּי עֶסְרֵי עַל שְׁמָהַתְהוֹן כְּתַב מְפָרַשׁ כִּגְלוֹף דְעִזְקָא גְבַר עַל שְׁמֵהּ לִתְרֵין עֲסַר שִׁבְטִין:
@1144 וַעֲבָדוּ עַל חוּשְׁנָא תִּכִּין מְתַחְמָן עוֹבַד גְדִילוּ דְהַב דְכֵי:
@1145 וַעֲבָדוּ תַּרְתֵּין מְרַמְצָן דִדְהַב וְתַרְתֵּין עִזְקָן דִדְהָב וִיהָבוּ יָת תַּרְתֵּין עִזְקָתָא עַל תְּרֵין סִטְרֵי חוּשְׁנָא:
@1146 וִיהָבוּ תַּרְתֵּין גְדִילָתָא דִדְהַב עַל תַּרְתֵּין עִזְקָתָא עַל סִטְרֵי חוּשְׁנָא:
@1147 וְיָת תַּרְתֵּין גְדִילָן דְעַל תַּרְתֵּין סִטְרוֹהִי יְהָבוּ עַל תַּרְתֵּין מְרַמְצָתָא וִיהָבֻנוּן עַל כַּתְפֵּי אֵפוֹדָא לָקֳבֵל אַפּוֹהִי:
@1148 וַעֲבָדוּ תַּרְתֵּין עִזְקַן דִדְהַב וְשַׁוִיאוּ עַל תְּרֵין סִטְרֵי חוּשְׁנָא עַל סִפְתֵהּ דִי לְעִבְרָא דְאֵפוֹדָא מִלְגָיו:
@1149 וַעֲבָדוּ תַּרְתֵּין עִזְקַן דִדְהַב וִיהָבֻנוּן עַל תַּרְתֵּין כִּתְפֵי אֵפוֹדָא מִלְרַע מִלָקֳבֵל אַפּוֹהִי לָקֳבֵל בֵּית לוֹפֵי מֵעִלָוֵי לְהֶמְיַן אֵפוֹדָא:
@1150 וְיַחֲדוּן יָת חוּשְׁנָא מֵעִזְקְתֵהּ לְעִזְקָתָא דְאֵפוֹדָא בְּחוּטָּא דִתְכֶלְתָּא לְמֶהֱוֵי עַל הֶמְיַן אֵפוֹדָא וְלָא יִתְפָּרֵק חוּשְׁנָא מֵעִלָוֵי אֵפוֹדָא כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@1151 וַעֲבַד יָת מְעִילָא דְאֵפוֹדָא עוֹבַד מָחֵי גְמִיר תִּכְלָא:
@1152 וּפוּם מְעִילָא כָּפִיל לְגַוֵהּ כְּפוּם שִׁרְיָן תּוֹרָא מַקַף לְפוּמֵהּ סְחוֹר סְחוֹר לָא יִתְבְּזָע:
@1153 וַעֲבָדוּ עַל שִׁפּוֹלֵי מְעִילָא רִמוֹנֵי תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי שְׁזִיר:
@1154 וַעֲבָדוּ זַגַיָא דְהַב דְכֵי וִיהָבוּ יָת זַגַיָא בְּגוֹ רִמוֹנַיָא עַל שִׁפּוֹלֵי מְעִילָא סְחוֹר סְחוֹר בְּגוֹ רִמוֹנַיָא:
@1155 זַגָא וְרִמוֹנָא זַגָא וְרִמוֹנָא עַל שִׁפּוֹלֵי מְעִילָא סְחוֹר סְחוֹר לְשַׁמָשָׁא כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@1156 וַעֲבָדוּ יָת כִּתּוּנִין דְבוּצָא עוֹבַד מָחֵי לְאַהֲרֹן וִלִבְנוֹהִי:
@1157 וְיָת מִצְנֶפְתָּא דְבוּצָא וְיָת שְׁבַח כּוֹבָעַיָא דְבוּצָא וְיָת מִכְנְסֵי בוּצָא דְבוּץ שְׁזִיר:
@1158 וְיָת הֶמְיָנָא דְבוּץ שְּׁזִיר וְתִכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי עוֹבַד צַיָר כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@1159 וַעֲבָדוּ יָת צִיצָא כְלִילָא דְקוּדְשָׁא דְהַב דְכֵי וּכְתָבוּ עֲלוֹהִי גְלִיפָן כְּתַב מְפָרַשׁ קֹדֶשׁ לַיְיָ:
@1160 וִיהָבוּ עֲלוֹהִי חוּטָא תְכֶלְתָּא לְמִתַּן עַל מִצְנֶפְתָּא מִלְעֵלָא כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@1161 וּשְׁלִים כָּל פָּלְחַן מַשְׁכְּנָא מַשְׁכַּן זִמְנָא וַעֲבָדוּ בְּנֵי יִשְׂרָאֵל כְּכֹל דִי פַקִיד יְיָ יָת משֶׁה כֵּן עֲבָדוּ:
@1162 וְאַיְתִיוּ יָת מַשְׁכְּנָא לְמשֶׁה יָת מַשְׁכְּנָא וְיָת כָּל מָנוֹהִי פוּרְפוֹהִי דַפּוֹהִי עַבְּרוֹהִי וְעַמוּדוֹהִי וְסַמְכוֹהִי:
@1163 וְיָת חוֹפָאָה מַשְׁכֵי דְדִכְרֵי מְסַמְקֵי וְיָת חוֹפָאָה מַשְׁכֵי דְסַסְגוֹנָא וְיָת פָּרֻכְתָּא דִפְרָסָא:
@1164 יָת אֲרוֹנָא דְסַהֲדוּתָא וְיָת אֲרִיחוֹהִי וְיָת כַּפֻּרְתָּא:
@1165 יָת פָּתוֹרָא יָת כָּל מָנוֹהִי וְיָת לְחֵם אַפַּיָא:
@1166 יָת מְנַרְתָּא דָכִיתָא יָת בּוֹצִינָהָא בּוֹצִנֵי סִדְרָא וְיָת כָּל מָנָהָא וְיָת מִשְׁחָא דְאַנְהָרוּתָא:
@1167 וְיָת מַדְבְּחָא דְדַהֲבָא וְיָת מִשְׁחָא דִרְבוּתָא וְיָת קְטֹרֶת בּוּסְמַיָא וְיָת פְּרָסָא דִתְרַע מַשְׁכְּנָא:
@1168 יָת מַדְבְּחָא דִנְחָשָׁא וְיָת סְרָדָא דִנְחָשָׁא דִילֵהּ יָת אֲרִיחוֹהִי וְיָת כָּל מָנוֹהִי יָת כִּיוֹרָא וְיָת בְּסִיסֵהּ:
@1169 יָת סְרָדֵי דְדַרְתָּא יָת עַמוּדָהָא וְיָת סַמְכָהָא וְיָת פְּרָסָא לִתְרַע דַרְתָּא יָת אֲטוּנוֹהִי וְסִכָּהָא וְיָת כָּל מָנֵי פָּלְחַן מַשְׁכְּנָא לְמַשְׁכַּן זִמְנָא:
@1170 יָת לְבוּשֵׁי שִׁמוּשָׁא לְשַׁמָשָׁא בְקוּדְשָׁא יָת לְבוּשֵׁי קוּדְשָׁא לְאַהֲרֹן כַּהֲנָא וְיָת לְבוּשֵׁי בְנוֹהִי לְשַׁמָשָׁא:
@1171 כְּכֹל דִי פַקִיד יְיָ יָת משֶׁה כֵּן עֲבָדוּ בְּנֵי יִשְׂרָאֵל יָת כָּל פָּלְחָנָא:
@1172 וַחֲזָא משֶׁה יָת כָּל עִבִדְתָּא וְהָא עֲבָדוּ יָתַהּ כְּמָא דִי פַקִיד יְיָ כֵּן עֲבָדוּ וּבָרִיךְ יָתְהוֹן משֶׁה:
@1173 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@1174 בְּיוֹמָא יַרְחָא קַדְמָאָה בְּחַד לְיַרְחָא תְּקִים יָת מַשְׁכְּנָא מַשְּׁכַּן זִמְנָא:
@1175 וּתְשַׁוֵי תַמָן יַת אֲרוֹנָא דְסַהֲדוּתָא וְתַטֵּל עַל אֲרוֹנָא יָת פָּרֻכְתָּא:
@1176 וְתָעֵל יָת פָּתוֹרָא וְתַסְדַר יָת סִדְרֵהּ וְתָעֵל יָת מְנַרְתָּא וְתַדְלֵק יָת בּוֹצִינָהָא:
@1177 וְתִתֵּן יָת מַדְבְּחָא דְדַהֲבָא לִקְטֹּרֶת בּוּסְמַיָא קֳדָם אֲרוֹנָא דְסַהֲדוּתָא וּתְשַׁוֵי יָת פְּרָסָא דְתַרְעָא לְמַשְׁכְּנָא:
@1178 וְתִתֵּן יָת מַדְבְּחָא דַעֲלָתָא קֳדָם תְּרַע מַשְׁכְּנָא מַשְׁכַּן זִמְנָא:
@1179 וְתִתֵּן יָת כִּיוֹרָא בֵּין מַשְׁכַּן זִמְנָא וּבֵין מַדְבְּחָא וְתִתֵּן תַּמָן מַיָא:
@1180 וּתְשַׁוֵי יָת דַרְתָּא סְחוֹר סְחוֹר וְתִתֵּן יָת פְּרָסָא דִתְרַע דַרְתָּא:
@1181 וְתִסַב יָת מִשְׁהָא דִרְבוּתָא וּתְרַבֵּי יָת מַשְׁכְּנָא וְיָת כָּל דִי בֵהּ וּתְקַדֵשׁ יָתֵהּ וְיָת כָּל מָנוֹהִי וִיהֵי קוּדְשָׁא:
@1182 וּתְרַבֵי יָת מַדְבְּחָא דַעֲלָתָא וְיָת כָּל מָנוֹהִי וּתְקַדֵשׁ יָת מַדְבְּחָא וִיהֵי מַדְבְּחָא קֹדֶשׁ קוּדְשִׁין:
@1183 וּתְרַבֵּי יָת כִּיוֹרָא וְיָת בְּסִיסֵהּ וּתְקַדֵשׁ יָתֵהּ:
@1184 וּתְקָרֵב יָת אַהֲרֹן וְיָת בְּנוֹהִי לִתְרַע מַשְׁכַּן זִמְנָא וְתַסְחֵי יָתְהוֹן בְּמַיָא:
@1185 וְתַלְבֵּשׁ יָת אַהֲרֹן יָת לְבוּשֵׁי קוּדְשָׁא וּתְרַבֵּי יָתֵהּ וּתְקַדֵשׁ יָתֵהּ וִישַׁמֵשׁ קֳדָמָי:
@1186 וְיָת בְּנוֹהִי תְּקָרֵב וְתַלְבֵּשּׁ יָתְהוֹן כִּתּוּנִין:
@1187 וּתְרַבִּי יָתְהוֹן כְּמָא דִי רַבִּיתָא יָת אֲבוּהוֹן וִישַׁמְשׁוּן קֳדָמָי וּתְהֵי לְמֶהֱוֵי לְּהוֹן רְבוּתְהוֹן לְכַהֲנוּת עֲלָם לְדָרֵיהוֹן:
@1188 וַעֲבַד משֶׁה כְּכֹל דִי פַקִיד יְיָ יָתֵהּ כֵּן עֲבָד:
@1189 וַהֲוָה בְּיַרְחָא קַדְמָאָה בְּשַׁתָּא תִנְיֵתָא בְּחַד לְיַרְחָא אִתָּקַם מַשְׁכְּנָא:
@1190 וַאֲקֵם משֶׁה יָת מַשְׁכְּנָא וִיהַב יָת סַמְכוֹהִי וְשַׁוִי יָת דַפּוֹהִי וִיהַב יָת עַבְרוֹהִי וַאֲקֵם יָת עַמוּדוֹהִי:
@1191 וּפְרַס יָת פְרָסָא עַל מַשְׁכְּנָא וְשַׁוִי יָת חוֹפָאָה דְמַשְׁכְּנָא עֲלוֹהִי מִלְעֵלָא כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@1192 וּנְסִיב וִיהַב יָת סַהֲדוּתָא לַאֲרוֹנָא וְשַׁוִי יָת אֲרִיחַיָא עַל אֲרוֹנָא וִיהַב יָת כַּפֻּרְתָּא עַל אֲרוֹנָא מִלְעֵלָא:
@1193 וְאָעֵלּ יָת אֲרוֹנָא לְמַשְׁכְּנָא וְשַׁוִי יָת פָּרֻכְתָּא דִפְרָסָא וְאַטֵל עַל אֲרוֹנָא דְסַהֲדוּתָא כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@1194 וִיהַב יָת פָּתוֹרָא בְּמַשְׁכַּן זִמְנָא עַל צִדָא דְמַשְׁכְּנָא צִפוּנָא מִבָּרָא לְפָרֻכְתָּא:
@1195 וְסַדַר עֲלוֹהִי סִדוּר דִלְחֵם קֳדָם יְיָ כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@1196 וְשַׁוִי יָת מְנַרְתָּא בְּמַשְׁכַּן זִמְנָא לָקֳבֵל פָּתוֹרָא עַל צִדָא דְמַשְׁכְּנָא לְדָרוֹמָא:
@1197 וְאַדְלֵק בּוֹצִינָהָא קֳדָם יְיָ כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@1198 וְשַׁוִי יָת מַדְבְּחָא דְדַהֲבָא בְּמַשְׁכַּן זִמְנָא קֳדָם פָּרֻכְתָּא:
@1199 וְאַקְטַּר עֲלוֹהִי קְטֹרֶת בּוּסְמִין כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@1200 וְשַׁוִי יָת פְּרָסָא דְתַרְעָא לְמַשְׁכְּנָא:
@1201 וְיָת מַדְבְּחָא דַעֲלָתָא שַׁוִי בִּתְרַע מַשְׁכְּנָא מַשְׁכַּן זִמְנָא וְאַסֵק עֲלוֹהִי יָת עֲלָתָא וְיָת מִנְחָתָּא כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@1202 וְשַׁוִי יָת כִּיוֹרָא בֵּין מַשְׁכַּן זִמְנָא וּבֵין מַדְבְּחָא וִיהַב תַּמָן מַיָא לְקִדוּשׁ:
@1203 וּמְקַדְשִׁין מִנֵהּ משֶׁה וְאַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן וְיָת רַגְלֵיהוֹן:
@1204 בְּמֵעַלְהוֹן לְמַשְׁכַּן זִמְנָא וּבְמִקְרָבְהוֹן לְמַדְבְּחָא יְקַדְשׁוּן כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@1205 וַאֲקֵם יָת דַרְתָּא סְחוֹר סְחוֹר לְמַשְׁכְּנָא וּלְמַדְבְּחָא וִיהַב יָת פְּרָסָא דִתְרַע דַרְתָּא וְשֵׁיצֵי משֶׁה יָת עִבִידָא:
@1206 וַחֲפָא עֲנָנָא יָת מַשְׁכַּן זִמְנָא וִיקָרָא דַיְיָ אִתְמְלֵי יָת מַשְׁכְּנָא:
@1207 וְלָא יָכִיל משֶׁה לְמֵיעַל לְמַשְׁכַּן זִמְנָא אֲרֵי שְׁרָא עֲלוֹהִי עֲנָנָא וִיקָרָא דַיְיָ אִתְמְלִי יָת מַשְׁכְּנָא:
@1208 וּבְאִסְתַּלָקוּת עֲנָנָא מֵעִלָוֵי מַשְׁכְּנָא נָטְלִין בְּנֵי יִשְׂרָאֵל בְּכֹל מַטְלָנֵיהוֹן:
@1209 וְאִם לָא יִסְתַּלַק עֲנָנָא וְלָא נָטְלִין עַד יוֹמָא דְאִסְתַּלָקוּתֵהּ:
@1210 אֲרֵי עֲנָנָא יְקָרָא דַיְיָ עַל מַשְׁכְּנָא בִּימָמָא וְחֵיזוּ אֶשָׁתָא הֲוֵי בְלֵילְיָא בֵּהּ לְעֵינֵי כָל בֵּית יִשְׂרָאֵל בְּכָל מַטְלָנֵיהוֹן: חזק:

@1 **ואלה שמות בני ישראל.** אף על פי שמנאן בחייהן בשמותן, חזר ומנאן במיתתן [אחר מיתתן] , להודיע חבתן שנמשלו לכוכבים, שמוציאן ומכניסן במספר ובשמותם, שנאמר המוציא במספר צבאם לכלם בשם יקרא ה **ויוסף היה במצרים.** והלא הוא ובניו היו בכלל שבעים, ומה בא ללמדנו, וכי לא היינו יודעים שהוא היה במצרים, אלא להודיעך צדקתו של יוסף, הוא יוסף הרועה את צאן אביו, הוא יוסף שהיה במצרים ונעשה מלך ועומד בצדקו:
@7 [ **פרו.** שלא הפילו נשותיהם ולא מתו כשהם קטנים] : **וישרצו.** שהיו יולדות ששה בכרס אחד:
@8 **ויקם מלך חדש.** רב ושמואל חד אמר חדש ממש. וחד אמר, שנתחדשו גזרותיו: **אשר לא ידע.** עשה עצמו כאלו לא ידע:
@10 **הבה נתחכמה לו.** כל הבה לשון הכנה והזמנה לדבר הוא, כלומר הזמינו עצמכם לכך: **נתחכמה לו.** לעם. נתחכמה מה לעשות לו. ורבותינו דרשו נתחכם למושיען של ישראל לדונם במים, שכבר נשבע שלא יביא מבול לעולם (והם לא הבינו שעל כל העולם אינו מביא, אבל הוא מביא על אמה אחת) : **ועלה מן הארץ.** על כרחנו. ורבותינו דרשו כאדם שמקלל עצמו ותולה קללתו באחרים, והרי הוא כאלו כתב ועלינו מן הארץ והם יירשוה:
@11 **עליו.** על העם: **מסים.** לשון מס, שרים שגובין מהם המס. ומהו המס, שיבנו ערי מסכנות לפרעה: **למען ענתו בסבלתם.** של מצרים: **ערי מסכנות.** כתרגומו. וכן לך בא אל הסכן הזה, גזבר הממנה על האוצרות: **את פתם ואת רעמסס.** שלא היו ראויות מתחלה לכך ועשאום חזקות ובצורות לאוצר:
@12 **וכאשר יענו אתו.** בכל מה שהם נותנין לב לענות, כן לב הקדוש ברוך הוא להרבות ולהפריץ: **כן ירבה.** כן רבה וכן פרץ. ומדרשו רוח הקדש אומרת כן אתם אומרים פן ירבה, ואני אומר כן ירבה: **ויקצו.** קצו בחייהם. ורבותינו דרשו כקוצים היו בעיניהם:
@13 **בפרך.** בעבודה קשה המפרכת את הגוף ומשברתו:
@15 **למילדת.** הוא לשון מולידות, אלא שיש לשון קל ויש לשון כבד, כמו שובר ומשבר, דובר ומדבר, כך מוליד ומילד: **שפרה.** זו יוכבד על שם שמשפרת את הולד: **פועה.** זו מרים שפועה ומדברת והוגה לולד כדרך הנשים המפיסות תינוק הבוכה. פועה לשון צעקה, כמו כיולדה אפעה:
@16 **בילדכן.** כמו בהולידכן: **על האבנים.** מושב האשה היולדת, ובמקום אחר קוראו משבר, וכמוהו עשה מלאכה על האבנים, מושב כלי אמנות יוצר חרס: **אם בן הוא** וגו' **.** לא היה מקפיד אלא על הזכרים, שאמרו לו אצטגניניו שעתיד להולד בן המושיע אותם: **וחיה.** ותחיה:
@17 **ותחיין את הילדים.** מספקות להם מים ומזון. תרגום הראשון וקיימא והשני וקיימתין, לפי שלשון עברית לנקבות רבות, תיבה זו וכיוצא בה, משמשת לשון פעלו ולשון פעלתן, כגון ותאמרנה איש מצרי, לשון עבר, כמו ויאמרו לזכרים, ותדברנה בפיכם לשון דברתן, כמו ותדברו לזכרים. וכן ותחללנה אתי אל עמי, לשון עבר חללתן, כמו ותחללו לזכרים:
@19 **כי חיות הנה.** בקיאות כמילדות. תרגום מילדות חיתא. ורבותינו דרשו הרי הן משולות לחיות השדה שאינן צריכות מילדות. והיכן משולות לחיות, גור אריה (בראשית מט ט) , זאב יטרף (שם כז) , בכור שורו (דברים לג יז) , אילה שלוחה (בראשית מט כא) , ומי שלא נכתב בו הרי הכתוב כללן (בראשית מט כח) ויברך אותם, ועוד כתיב (יחזקאל יט ב) מה אמך לביא:
@20 **וייטב.** הטיב להם. וזה חלוק בתיבה שיסודה שתי אותיות ונתן לה וי''ו יו''ד בראשה, כשהיא באה לדבר בלשון ויפעיל הוא נקוד היו''ד בציר''י שהוא קמ''ץ קטן, כגון וייטב אלהים למילדת, וירב בבת יהודה (איכה ב ה) , הרבה תאניה, וכן ויגל השארית (דברי הימים ב' לו כ) , דנבוזראדן הגלה את השארית, ויפן זנב אל זנב (שופטים טו ד) , הפנה הזנבות זו לזו, כל אלו לשון הפעיל את אחרים. וכשהוא מדבר בלשון ויפעל, הוא נקוד היו''ד בחיר''ק, כגון (ויקרא י כ) וייטב בעיניו, לשון הוטב, וכן וירב העם (פסוק כ) , נתרבה העם, ויגל יהודה (מלכים ב' כה כא) גלה יהודה, ויפן כה וכה (ב יב) , פנה לכאן ולכאן. ואל תשיבני וילך, וישב, וירד, ויצא, לפי שאינן מגזרתן של אלו, שהרי היו''ד יסוד בהן, ירד, יצא, ישב, ילך, היו''ד אות שלישית בו: **וייטב אלהים למילדת.** מהו הטובה, כא **ויעש להם בתים.** בתי כהנה ולויה ומלכות שקרויין בתים. ויבן את בית ה' ואת בית המלך (מלכים א' ט א) . כהנה ולויה מיוכבד, ומלכות ממרים, כדאיתא במסכת סוטה (סוטה יא ב) :
@22 **לכל עמו.** אף עליהם גזר. יום שנלד משה אמרו לו אצטגניניו היום נולד מושיען, ואין אנו יודעין אם ממצרים אם מישראל, ורואין אנו שסופו ללקות במים, לפיכך גזר אותו היום אף על המצרים, שנאמר כל הבן הילוד, ולא נאמר הילוד לעברים, והם לא היו יודעים שסופו ללקות על מי מריבה:
@23 **ויקח את בת לוי.** פרוש היה ממנה מפני גזרת פרעה (וחזר ולקחה. וזהו וילך, שהלך בעצת בתו שאמרה לו גזרתך קשה משל פרעה, אם פרעה גזר על הזכרים, ואתה גם כן על הנקבות) . והחזירה ועשה בה לקוחין שניים. ואף היא נהפכה להיות נערה. ובת מאה שלשים שנה היתה, שנלדה בבואה למצרים בין החומות, ומאתים ועשר שנה נשתהו שם, וכשיצאו היה משה בן שמונים שנה. אם כן כשנתעברה ממנו היתה בת מאה שלשים וקורא אותה בת לוי:
@24 **כי טוב הוא.** כשנלד נתמלא הבית כלו אורה:
@25 **ולא יכלה עוד הצפינו.** שמנו לה המצריים מיום שהחזירה, והיא ילדתו לששה חדשים ויום אחד, שהיולדת לשבעה יולדת למקטעין, והם בדקו אחריה לסוף תשעה: **גמא.** גמי בלשון משנה ובלעז יונ''ק [גומא] . ודבר רך הוא, ועומד בפני רך ובפני קשה: **בחמר ובזפת.** זפת מבחוץ וטיט מבפנים, כדי שלא יריח אותו צדיק ריח רע של זפת: **ותשם בסוף.** הוא לשון אגם רושי''ל בלעז , ודומה לו (ישעיה יט ו) קנה וסוף קמלו:
@27 **לרחץ על היאר.** סרס המקרא ופרשהו ותרד בת פרעה על היאור לרחץ בו: **על יד היאר.** אצל היאור, כמו (שמואל ב יד ל) ראו חלקת יואב אל ידי, והוא לשון יד ממש, שיד האדם סמוכה לו. ורבותינו דרשו הולכות לשון מיתה, כמו (בראשית כה לב) הנה אנכי הולך למות, הולכות למות לפי שמחו בה. והכתוב מסייען, כי למה לנו לכתוב ונערתיה הולכות: **את אמתה.** את שפחתה. ורבותינו דרשו לשון יד. אבל לפי דקדוק לשון הקודש היה לו להנקד אמתה מ''ם דגושה. והם דרשו את אמתה את ידה, שנשתרבבה אמתה אמות הרבה:
@28 **ותפתח ותראהו.** את מי ראתה, את הילד, זהו פשוטו. ומדרשו שראתה עמו שכינה: **והנה נער בכה.** קולו כנער:
@29 **מן העברית.** מלמד שהחזירתו על מצריות הרבה לינק ולא ינק, לפי שהיה עתיד לדבר עם השכינה:
@30 **ותלך העלמה.** הלכה בזריזות ועלמות כעלם:
@31 **היליכי.** נתנבאה ולא ידעה מה נתנבאה הי שליכי:
@32 **משיתהו.** שחלתיה והוא לשון הוצאה בלשון ארמי, כמשחל ביניתא מחלבא. ובלשון עברי משיתהו לשון הסירותיו, כמו (יהושע א ח) לא ימוש, לא משו (במדבר יד מד) , כך חברו מנחם. ואני אומר שאינו ממחברת מש, וימוש, אלא מגזרת משה ולשון הוצאה הוא, וכן (שמואל ב כב יז) ימשני ממים רבים, שאלו היה ממחברת מש, לא יתכן לומר משיתהו, אלא המישותיהו, כאשר יאמר מן קם הקימותי, ומן שב השיבותי, ומן בא הביאותי, או משתיהו, כמו (זכריה ג ט) ומשתי את עון הארץ, אבל משיתי אינו אלא מגזרת תיבה שפעל שלה מיסד בה''א בסוף התבה. כגון משה, בנה, עשה, צוה, פנה, כשיבא לומר בהם פעלתי, תבא היו''ד במקום ה''א, כמו עשיתי, בניתי, פניתי, צויתי:
@33 **ויגדל משה.** והלא כבר כתיב ויגדל הילד (פסוק י) אמר רבי יהודה ברבי אלעאי הראשון לקומה והשני לגדלה, שמנהו פרעה על ביתו: **וירא בסבלתם.** נתן עיניו ולבו להיות מצר עליהם: **איש מצרי.** נוגש היה, ממנה על שוטרי ישראל והיה מעמידם מקרות הגבר למלאכתם: **מכה איש עברי.** מלקהו ורודהו. ובעלה של שלומית בת דברי היה, ונתן בה עיניו, ובלילה העמידו והוציאו מביתו, והוא חזר ונכנס לבית ובא על אשתו, כסבורה שהוא בעלה, וחזר האיש לביתו והרגיש בדבר, וכשראה אותו מצרי שהרגיש בדבר, היה מכהו ורודהו כל היום:
@34 **ויפן כה וכה.** ראה מה עשה לו בבית ומה עשה לו בשדה. ולפי פשוטו כמשמעו: **וירא כי אין איש.** עתיד לצאת ממנו שיתגייר:
@35 **שני אנשים עברים.** דתן ואבירם הם שהותירו מן המן: **נצים.** מריבים: **למה תכה.** אף על פי שלא הכהו, נקרא רשע בהרמת יד: **רעך.** רשע כמותך:
@36 **מי שמך לאיש.** והרי עודך נער: **הלהרגני אתה אמר.** מכאן אנו למדים שהרגו בשם המפורש: **ויירא משה.** כפשוטו. ומדרשו דאג לו על שראה בישראל רשעים דלטורין, אמר מעתה שמא אינם ראויין להגאל: **אכן נודע הדבר.** כמשמעו. ומדרשו נודע לי הדבר שהייתי תמה עליו, מה חטאו ישראל מכל שבעים אמות להיות נרדים בעבודת פרך, אבל רואה אני שהם ראויים לכך:
@37 **וישמע פרעה.** הם הלשינו עליו: **ויבקש להרג את משה.** מסרו לקוסטינר להרגו, ולא שלטה בו החרב, הוא שאמר משה (יח ד) ויצילני מחרב פרעה: **וישב בארץ מדין.** נתעכב שם, כמו (בראשית לז א) וישב יעקב: **וישב על הבאר.** לשון ישיבה, למד מיעקב שנזדוג לו זווגו על הבאר:
@38 **ולכהן מדין.** רב שבהן ופירש לו מעבודה זרה ונידוהו מאצלם: **את הרהטים.** את ברכות מרוצת המים העשויות בארץ:
@39 **ויגרשום.** מפני הנדוי:
@42 **למה זה עזבתן.** הכיר בו שהוא מזרעו של יעקב, שהמים עולים לקראתו: **ויאכל לחם.** שמא ישא אחת מכם, כמה דאת אמר (בראשית לט ו) כי אם הלחם אשר הוא אוכל:
@43 **ויואל.** כתרגומו. ודומה לו (שופטים יט ו) הואל נא ולין, (יהושע ז ז) ולו הואלנו, (בראשית יח כז) הואלתי לדבר, ומדרשו לשון אלה, נשבע לו שלא יזוז ממדין כי אם ברשותו:
@45 **ויהי בימים הרבים ההם.** שהיה משה גר במדין, וימת מלך מצרים והצרכו ישראל לתשועה. ומשה היה רעה וגו' (ג א) ובאת תשועה על ידו, ולכך נסמכו פרשיות הללו: **וימת מלך מצרים.** נצטרע והיה שוחט תינוקות ישראל ורוחץ בדמם:
@46 **נאקתם.** צעקתם, וכן (איוב כד יב) מעיר מתים ינאקו: **את בריתו את אברהם.** עם אברהם:
@47 **וידע אלהים.** נתן עליהם לב ולא העלים עיניו:
@48 **אחר המדבר.** להתרחק מן הגזל שלא ירעו בשדות אחרים: **אל הר האלהים.** על שם העתיד:
@49 **בלבת אש.** בשלהבת אש לבו של אש, כמו (דברים ד יא) לב השמים, (שמואל ב יח יד) בלב האלה, ואל תתמה על התי''ו, שיש לנו כיוצא בו (יחזקאל טז ל) מה אמלה לבתך: **מתוך הסנה.** ולא אילן אחר, משום עמו אנכי בצרה (תהלים צא טו) : **אכל.** נאכל, כמו (דברים כא ג) לא עבד בה, אשר לקח משם (בראשית ג כג) :
@50 **אסרה נא.** אסורה מכאן להתקרב שם:
@52 **של.** שלוף והוצא, כמו (דברים יט ה) ונשל הברזל, (דברים כח מ) כי ישל זיתך: **אדמת קדש הוא.** המקום:
@54 **כי ידעתי את מכאביו.** כמו (לעיל ב כה) וידע אלהים, כלומר כי שמתי לב להתבונן ולדעת את מכאוביו ולא העלמתי עיני ולא אאטום את אזני מצעקתם:
@57 **ועתה לכה ואשלחך אל פרעה.** ואם תאמר מה תועיל, והוצא את עמי, יועילו דבריך ותוציאם משם:
@58 **מי אנכי.** מה אני חשוב לדבר עם המלכים: **וכי אוציא את בני ישראל.** ואף אם חשוב אני, מה זכו ישראל שתעשה להם נס ואוציאם ממצרים:
@59 **ויאמר כי אהיה עמך.** השיבו על ראשון ראשון ועל אחרון אחרון, שאמרת מי אנכי כי אלך אל פרעה, לא שלך היא, כי אם משלי, כי אהיה עמך, וזה המראה אשר ראית בסנה לך האות כי אנכי שלחתיך, וכדאי אני להציל כאשר ראית הסנה עושה שליחותי ואיננו אכל, כך תלך בשליחותי ואינך נזוק. וששאלת מה זכות יש לישראל שיצאו ממצרים, דבר גדול יש לי על הוצאה זו, שהרי עתידים לקבל התורה על ההר הזה לסוף שלושה חדשים שיצאו ממצרים. דבר אחר כי אהיה עמך וזה שתצליח בשליחותך לך האות על הבטחה אחרת שאני מבטיחך, שכשתוציאם ממצרים תעבדון אותי על ההר הזה, שתקבלו התורה עליו והיא הזכות העומדת לישראל. ודוגמת לשון זה מצינו (ישעיה לז ל) וזה לך האות אכול השנה ספיח וגו' , מפלת סנחריב תהיה לך אות על הבטחה אחרת שארצכם חרבה מפירות ואני אברך הספיחים:
@61 **אהיה אשר אהיה.** אהיה עמם בצרה זו אשר אהיה עמם בשעבוד שאר מלכיות. אמר לפניו רבונו של עולם, מה אני מזכיר להם צרה אחרת דים בצרה זו. אמר לו יפה אמרת, כה תאמר וגו' :
@62 **זה שמי לעלם.** חסר וי''ו, לומר העלימהו, שלא יקרא ככתבו: **וזה זכרי.** למדו היאך נקרא, וכן דוד הוא אומר (תהלים קלה יג) ה' שמך לעולם ה' זכרך לדר ודר:
@63 **את זקני ישראל.** מיחדים לישיבה. ואם תאמר זקנים סתם, היאך אפשר לו לאסוף זקנים של ששים רבוא:
@65 **ושמעו לקלך.** מאליהם, מכיון שתאמר להם לשון זה ישמעו לקולך, שכבר סימן זה מסור בידם מיעקב ומיוסף שבלשון זה הם נגאלים. יעקב אמר (בראשית נ כב) ואלהים פקד יפקד אתכם, יוסף אמר להם (בראשית נ כה) פקד יפקד אלהים אתכם: [ **אלהי העבריים.** יו''ד יתירה רמז לעשר מכות] : **נקרה עלינו.** לשון מקרה וכן (במדבר כג ד) ויקר אלהים, (שם טו) ואנכי אקרה כה, אהא נקרה מאתו הלום:
@66 **לא יתן אתכם מלך מצרים להלך.** אם אין אני מראה לו ידי החזקה, כלומר כל עוד שאין אני מודיעו ידי החזקה לא יתן אתכם להלך: **לא יתן.** לא ישבוק, כמו (בראשית כ ו) על כן לא נתתיך, ולא נתנו אלהים להרע עמדי, וכלן לשון נתינה הם. ויש מפרשים ולא ביד חזקה ולא בשביל שידו חזקה, כי מאז אשלח את ידי והכיתי את מצרים וגו' , ומתרגמין אותו ולא מן קדם דחיליה תקיף, משמו של רבי יעקב ברבי מנחם נאמר לי:
@69 **ומגרת ביתה.** מאותה שהיא גרה אתה בבית: **ונצלתם.** כתרגומו ותרוקנון. וכן (שמות יב לו) וינצלו את מצרים, (שמות לג ו) ויתנצלו בני ישראל את עדים, והנו''ן בו יסוד. ומנחם חברו במחברת צד''י עם (בראשית לא ט) ויצל אלהים את מקנה אביכם, (שם טז) אשר הציל אלהים מאבינו. ולא יאמנו דבריו, כי אם לא היתה הנו''ן יסוד והיא נקודה בחיר''ק, לא תהא משמשת בלשון ופעלתם אלא בלשון ונפעלתם, כמו (דברים כח סג) ונסחתם מן האדמה, (ויקרא כו כה) ונתתם ביד אויב, (שם יז) ונגפתם לפני אויביכם, (יחזקאל כב כא) ונתכתם בתוכה, (ירמיה ז י) ואמרתם נצלנו, לשון נפעלנו. וכל נו''ן שהיא באה בתיבה לפרקים ונופלת ממנה, כנו''ן של נוגף, נושא, נותן, נושך, כשהיא מדברת לשון ופעלתם תנקד בשו''א בחטף, כגון (בראשית מה יט) ונשאתם את אביכם, (במדבר לב כט) ונתתם להם את ארץ הגלעד, (בראשית י''ז יא) ונמלתם את בשר ערלתכם. לכן אני אומר שזאת הנקודה בחיר''ק מן היסוד היא, ויסוד שם דבר נצול, והוא מן הלשונות הכבדים, כמו דבור, כפור, למוד, כשידבר בלשון ופעלתם ינקד בחיר''ק, כמו (במדבר כ ח) ודברתם אל הסלע, (יחזקאל מה כ) וכפרתם את הבית, (דברים יא יט) ולמדתם אתם את בניכם:
@71 **מזה בידך.** לכך נכתב תיבה אחת, לדרוש מזה שבידך אתה חיב ללקות, שחשדת בכשרים. ופשוטו כאדם שאומר לחברו מודה אתה שזו שלפניך אבן היא. אומר לו הן. אמר לו הריני עושה אותה עץ:
@72 **ויהי לנחש.** רמז לו שספר לשון הרע על ישראל ותפש אמנותו של נחש:
@73 **ויחזק בו.** לשון אחיזה הוא, והרבה יש במקרא (בראשית יט טז) ויחזיקו האנשים בידו, (דברים כה יא) והחזיקה במבשיו, (שמואל א יז לה) והחזקתי בזקנו. כל לשון חזוק הדבוק לבי''ת, לשון אחיזה הוא:
@75 **מצרעת כשלג.** דרך צרעת להיות לבנה (ויקרא יג ד) ואם בהרת לבנה היא. אף באות זה רמז שלשון הרע ספר באמרו (פסוק א) לא יאמינו לי, לפיכך הלקהו בצרעת, כמו שלקתה מרים על לשון הרע:
@76 **ויוצאה מחיקו והנה שבה כבשרו.** מכאן שמדה טובה ממהרת לבא ממדת פרענות, שהרי בראשונה לא נאמר מחיקו:
@77 **והאמינו לקל האת האחרון.** משתאמר להם בשבילכם לקיתי על שספרתי עליכם לשון הרע יאמינו לך, שכבר למדו בכך שהמזדוגין להרע להם לוקים בנגעים, כגון פרעה ואבימלך בשביל שרה:
@78 **ולקחת ממימי היאור.** רמז להם שבמכה ראשונה נפרע מאלהותם: **והיו המים** וגו' **.** והיו והיו שתי פעמים. נראה בעיני, אלו נאמר והיו המים אשר תקח מן היאור לדם ביבשת, שומע אני שבידו הם נהפכים לדם ואף כשירדו לארץ יהיו בהויתן, אבל עכשיו מלמדנו שלא יהיו דם עד שיהיו ביבשת:
@79 **גם מתמול** וגו' **.** למדנו שכל שבעה ימים היה הקדוש ברוך הוא מפתה את משה בסנה לילך בשליחותו מתמול שלשום מאז דברך הרי שלשה, ושלשה גמין רבויין הם, הרי ששה, והוא היה עומד ביום השביעי כשאמר לו זאת עוד (להלן פסוק יג) שלח נא ביד תשלח, עד שחרה בו וקבל עליו. וכל זה, שלא היה רוצה לטל גדלה על אהרן אחיו שהיה גדול המנו ונביא היה, שנאמר (שמואל א ב כז) הנגלה נגליתי אל בית אביך בהיותם במצרים, הוא אהרן. וכן ביחזקאל (כ ה) ואודע להם בארץ מצרים וגו' , (שם ז) ואמר אליהם איש שקוצי עיניו השליכו, ואותה נבואה לאהרן נאמרה: **כבד פה.** בכבדות אני מדבר. ובלשון לעז בלב''א :
@80 **מי שם פה** וגו' **.** מי למדך לדבר כשהיית נדון לפני פרעה על המצרי: **או מי ישום אלם.** מי עשה פרעה אלם שלא נתאמץ במצות הריגתך, ואת משרתיו חרשים, שלא שמעו בצוותו עליך, ולאספקלטורין ההורגים מי עשאם עורים, שלא ראו כשברחת מן הבימה ונמלטת: **הלא אנכי.** ששמי ה' עשיתי כל זאת:
@82 **ביד תשלח.** ביד מי שאתה רגיל לשלוח, והוא אהרן. דבר אחר ביד אחר שתרצה לשלוח, שאין סופי להכניסם לארץ ולהיות גואלם לעתיד, יש לך שלוחים הרבה:
@83 **ויחר אף.** ר' יהושע בן קרחה אומר כל חרון אף שבתורה נאמר בו רושם, וזה לא נאמר בו רושם, ולא מצינו שבא עונש על ידי אותו חרון. אמר לו רבי יוסי אף בזו נאמר בו רושם, הלא אהרן אחיך הלוי, שהיה עתיד להיות לוי ולא כהן, והכהנה הייתי אומר לצאת ממך, מעתה לא יהיה כן, אלא הוא יהיה כהן ואתה הלוי, שנאמר (דברי הימים א' כג כד) ומשה איש האלהים בניו יקראו על שבט הלוי: **הנה הוא יצא לקראתך.** כשתלך למצרים: **וראך ושמח בלבו.** לא כשאתה סבור שיהא מקפיד עליך שאתה עולה לגדלה. ומשם זכה אהרן לעדי החשן הנתון על הלב:
@85 **ודבר הוא לך.** בשבילך ידבר אל העם וזה יוכיח על כל לך ולי ולו ולכם ולהם הסמוכים לדבור, שכלם לשון על הם: **יהיה לך לפה.** למליץ, לפי שאתה כבד פה: **לאלהים.** לרב ולשר:
@87 **וישב אל יתר חתנו.** לטול רשות, שהרי נשבע לו. ושבעה שמות היו לו רעואל, יתר, יתרו, קיני, חובב, חבר, פוטיאל:
@88 **כי מתו כל האנשים.** מי הם, דתן ואבירם. חיים היו, אלא שירדו מנכסיהם, והעני חשוב כמת:
@89 **על החמר.** חמור המיוחד, הוא החמור שחבש אברהם לעקידת יצחק והוא שעתיד מלך המשיח להגלות עליו, שנאמר (זכריה ט ט) עני ורוכב על חמור: **וישב ארצה מצרים ויקח משה את מטה** וגו' **.** אין מקדם ומאחר מדוקדקים במקרא:
@90 **בלכתך לשוב מצרימה** וגו' **.** דע שעל מנת כן תלך, שתהא גבור בשליחותי לעשות כל מופתי לפני פרעה ולא תירא ממנו: **אשר שמתי בידך.** לא על שלש האותות האמורות למעלה, שהרי לא לפני פרעה צוה לעשותם אלא לפני ישראל, שיאמינו לו, ולא מצינו שעשאם לפניו, אלא מופתים שאני עתיד לשום בידך במצרים, כמו (שמות ז ט) כי ידבר אליכם פרעה וגו' . ואל תתמה על אשר כתיב אשר שמתי, שכן משמעו כשתדבר עמו, כבר שמתים בידך:
@91 **ואמרת אל פרעה.** כשתשמע שלבו חזק וימאן לשלוח אמור לו כן: **בני בכרי.** לשון גדלה, כמו (תהלים פט כח) אף אני בכור אתנהו, זהו פשוטו. ומדרשו כאן חתם הקדוש ברוך הוא על מכירת הבכורה שלקח יעקב מעשו:
@92 **ואמר אליך.** בשליחותו של מקום: **שלח את בני** וגו' **הנה אנכי הרג** וגו' **.** היא מכה אחרונה ובה התרהו תחלה מפני שהיא קשה, וזה הוא שאמר (איוב לו כב) הן אל ישגיב בכחו, לפיכך מי כמהו מורה (איוב לו כב) . בשר ודם המבקש להנקם מחברו מעלים את דבריו שלא יבקש הצלה, אבל הקדוש ברוך הוא ישגיב בכחו ואין יכולת להמלט מידו, כי אם בשובו אליו, לפיכך הוא מורהו ומתרה בו לשוב:
@93 **ויהי.** משה **בדרך במלון: ויבקש המיתו.** המלאך למשה, לפי שלא מל את אליעזר בנו, ועל שנתרשל נענש מיתה. תניא אמר רבי יוסי חס ושלום לא נתרשל, אלא אמר אמול ואצא לדרך, סכנה היא לתינוק עד שלשה ימים, אמול ואשהה שלשה ימים, הקדוש ברוך הוא צוני (פסוק י''ט) לך שוב מצרים. ומפני מה נענש, לפי שנתעסק במלון תחלה. במסכת נדרים (דף לא ב) . והיה המלאך נעשה כמין נחש ובולעו מראשו ועד ירכיו, וחוזר ובולעו מרגליו ועד אותו מקום, הבינה צפורה שבשביל המילה הוא:
@94 **ותגע לרגליו.** השליכתו לפני רגליו של משה: **ותאמר.** על בנה: **כי חתן דמים אתה לי.** אתה היית גורם להיות החתן שלי נרצח עליך, הורג אישי אתה לי:
@95 **וירף.** המלאך **ממנו. אז הבינה שעל המילה בא להרגו: אמרה חתן דמים למולת.** חתני היה נרצח על דבר המילה: **למולת.** על דבר המולות. שם דבר הוא, והלמ''ד משמשת בלשון על, כמו (שמות יד ג) ואמר פרעה לבני ישראל. ואונקלוס תרגם דמים, על דם המילה:
@101 **ואחר באו משה ואהרן** וגו' **.** אבל הזקנים נשמטו אחד אחד מאחרי משה ואהרן, עד שנשמטו כלם קודם שהגיעו לפלטין, לפי שיראו ללכת, ובסיני נפרע להם (כד ב) ונגש משה לבדו והם לא יגשו, החזירם לאחוריהם:
@103 **פן יפגענו.** פן יפגעך היו צריכים לומר, אלא שחלקו כבוד למלכות. פגיעה זו לשון מקרה מות היא:
@104 **תפריעו את העם ממעשיו.** תבדילו ותרחיקו אותם ממלאכתם, ששומעין לכם וסבורים לנוח מן המלאכה. וכן (משלי ד טו) פרעהו אל תעבר בו, רחקהו. וכן (שם א כה) ותפרעו כל עצתי, (שמות לב כה) כי פרוע הוא, נרחק ונתעב: **לכו לסבלתיכם.** לכו למלאכתכם שיש לכם לעשות בבתיכם. אבל מלאכת שעבוד מצרים לא היתה על שבטו של לוי, ותדע לך שהרי משה ואהרן יוצאים ובאים שלא ברשות:
@105 **הן רבים עתה עם הארץ.** שהעבודה מטלת עליהם ואתם משביתים אותם מסבלותם, הפסד גדול הוא זה:
@106 **הנגשים.** מצריים היו, והשוטרים היו ישראלים, הנוגש ממנה על כמה שוטרים, והשוטר ממנה לרדות בעושי המלאכה:
@107 **תבן.** אשטובל''א [קש] היו גובלין אותו עם הטיט: **לבנים.** טיולי''ש בלעז שעושים מטיט ומיבשין אותן בחמה, ויש ששורפין אותן בכבשן: **כתמול שלשם.** כאשר הייתם עושים עד הנה: **וקששו.** ולקטו:
@108 **ואת מתכנת הלבנים.** סכום חשבון הלבנים שהיה כל אחד עושה ליום כשהיה התבן נתן להם, אותו סכום תשימו עליהם גם עתה, למען תכבד העבודה עליהם: **כי נרפים.** מן העבודה הם, לכך לבם פונה אל הבטלה וצועקים לאמר נלכה וגו' : **מתכנת.** ותוכן לבנים (פסוק יט) , ולו נתכנו עלילות (שמואל א' ב ג) , את הכסף המתכן (מלכים ב' יב יב) , כלם לשון חשבון הם: **נרפים.** המלאכה רפויה בידם ועזובה מהם והם נרפים ממנה, רטריי''ש בלע''ז :
@109 **ואל ישעו בדברי שקר.** ואל יהגו וידברו תמיד בדברי רוח לאמר נלכה נזבחה. ודומה לו (תהלים קיט קיז) ואשעה בחקיך תמיד, (דברים כח לז) למשל ולשנינה, מתרגמינן ולשועי, (בראשית כד סו) ויספר ואשתעי. ואי אפשר לומר ישעו לשון (בראשית ד ד) וישע ה' אל הבל וגו' , (שם ה) ואל קין ואל מנחתו לא שעה, ולפרש אל ישעו אל יפנו, שאם כן היה לו לכתוב ואל ישעו אל דברי שקר או לדברי שקר, כי כן גזרת כלם (ישעי' יז ז) ישעה האדם על עשהו, (שם לא א) ולא שעו על קדוש ישראל, (שם יז ח) ולא ישעה אל המזבחות, ולא מצאתי שמוש שלבי''ת סמוכה לאחריהם, אבל אחר לשון דבור, כמתעסק לדבר בדבר נופל לשון שמוש בי''ת, כגון (יחזקאל לג ל) הנדברים בך, (במדבר יב א) ותדבר מרים ואהרן במשה, (זכריה ד א) המלאך הדבר בי, (דברים יא יט) לדבר בם, (תהלים קיט מו) ואדברה בעדתיך, אף כאן אל ישעו בדברי שקר אל יהיו נדברים בדברי שוא והבאי:
@111 **אתם לכו קחו לכם תבן.** וצריכים אתם לילך בזריזות: **כי אין נגרע מעבדתכם דבר.** מכל סכום לבנים שהייתם עושים ליום בהיות התבן נתן לכם מזמן מבית המלך:
@112 **לקשש קש לתבן.** לאסוף אסיפה, ללקוט לקט לצורך תבן הטיט. קש לשון לקוט. על שם שדבר המתפזר הוא וצריך לקוששו, קרוי קש בשאר מקומות:
@113 **אצים.** דוחקים: **דבר יום ביומו.** חשבון שלכל יום כלו ביומו, כאשר עשיתם בהיות התבן מוכן:
@114 **ויכו שטרי בני ישראל.** השוטרים ישראלים היו וחסים על חבריהם מלדחקם, וכשהיו משלימים הלבנים לנוגשים שהם מצריים, והיה חסר מן הסכום, היו מלקין אותם על שלא דחקו את עושי המלאכה, לפיכך זכו אותם שוטרים להיות סנהדרין, ונאצל מן הרוח אשר על משה, והושם עליהם, שנאמר (במדבר יא טז) אספה לי שבעים איש מזקני ישראל אשר ידעת, מאותן שידעת הטובה שעשו במצרים, כי הם זקני העם ושוטריו: **ויכו שטרי בני ישראל.** אשר שמו נוגשי פרעה אותם לשוטרים עליהם לאמר מדוע וגו' . למה ויכו, שהיו אומרים להם מדוע לא כליתם גם תמול גם היום חק הקצוב עליכם ללבון כתמול השלישי שהוא יום שלפני אתמול, והוא היה בהיות התבן נתן להם: **ויכו.** לשון ויפעלו, הכו מיד אחרים, הנוגשים הכום:
@116 **ולבנים אמרים לנו עשו.** כמנין הראשון: **וחטאת עמך.** אלו היה נקוד פת''ח הייתי אומר שהוא דבוק, ודבר זה חטאת עמך הוא, עכשיו שהוא קמ''ץ, שם דבר הוא. וכך פרושו ודבר זה מביא חטאת על עמך, כאלו כתוב וחטאת לעמך, כמו (רות א יט) כבאנה בית לחם, שהוא כמו לבית לחם וכן הרבה:
@118 **ותכן לבנים.** חשבון הלבנים, וכן (מלכים ב יב יב) את הכסף המתכן, המנוי, כמו שאמר בענין (שם יא) ויצרו וימנו את הכסף:
@119 **ויראו שטרי בני ישראל.** את חבריהם הנרדים על ידם: **ברע.** ראו אותם ברעה וצרה המוצאת אותם בהכבידם העבודה עליהם לאמר לא תגרעו וגו' :
@120 **ויפגעו.** אנשים מישראל את משה ואת אהרן וגו' . ורבותינו דרשו כל נצים ונצבים דתן ואבירם היו, שנאמר בהם יצאו נצבים:
@122 **למה הרעתה לעם הזה.** ואם תאמר מה אכפת לך, קובל אני על ששלחתני:
@123 **הרע.** לשון הפעיל הוא, הרבה רעה עליהם. ותרגומו אבאש:
@124 **עתה תראה** וגו' **.** הרהרת על מדותי, לא כאברהם שאמרתי לו (בראשית כא יב) כי ביצחק יקרא לך זרע, ואחר כך אמרתי לו (שם כב ב) העלהו לעולה, ולא הרהר אחרי, לפיכך עתה תראה. העשוי לפרעה תראה, ולא העשוי למלכי שבעה אמות, כשאביאם לארץ: **כי ביד חזקה ישלחם.** מפני ידי החזקה שתחזק עליו ישלחם: **וביד חזקה יגרשם מארצו.** על כרחם של ישראל יגרשם, ולא יספיקו לעשות להם צידה. וכן הוא אומר (שמות יב לג) ותחזק מצרים על העם למהר לשלחם וגו' :
@125 **וידבר אלהים אל משה.** דבר אתו משפט על שהקשה לדבר ולומר (לעיל ה כב) למה הרעותה לעם הזה: ויאמר אליו אני ה'. נאמן לשלם שכר טוב למתהלכים לפני. ולא לחנם שלחתיך כי אם לקים דברי שדברתי לאבות הראשונים. ובלשון הזה מצינו שהוא נדרש בכמה מקומות אני ה' נאמן לפרע, כשהוא אמור אצל עונש, כגון (ויקרא יט יב) וחללת את שם אלהיך אני ה', וכשהוא אמור אצל קיום מצות, כגון (ויקרא כב לא) ושמרתם מצותי ועשיתם אותם אני ה', נאמן לתן שכר:
@126 **וארא.** אל האבות: **באל שדי.** הבטחתים הבטחות ובכלן אמרתי להם אני אל שדי: **ושמי ה' לא נודעתי להם.** לא הודעתי אין כתיב כאן אלא לא נודעתי לא נכרתי להם במדת אמתות שלי שעליה נקרא שמי ה' נאמן לאמת דברי, שהרי הבטחתים ולא קימתי:
@127 **וגם הקמתי את בריתי** וגו' **.** וגם כשנראיתי להם באל שדי הצבתי והעמדתי בריתי ביני וביניהם: **לתת להם את ארץ כנען.** לאברהם בפרשת מילה נאמר (בראשית יז א) אני אל שדי וגו' , (בראשית יז ח) ונתתי לך ולזרעך אחריך את ארץ מגוריך, ליצחק (בראשית כו ג) כי לך ולזרעך אתן את כל הארצות האל והקימותי את השבועה אשר נשבעתי לאברהם, ואותה שבועה שנשבעתי לאברהם באל שדי, אמרתי ליעקב (בראשית לה יא. יב) אני אל שדי פרה ורבה וגו' ואת הארץ אשר וגו' , הרי שנדרתי להם ולא קימתי:
@128 **וגם אני.** כמו שהצבתי והעמדתי הברית יש עלי לקים, לפיכך שמעתי את נאקת בני ישראל הנואקים: **אשר מצרים מעבדים אתם ואזכר.** אותו הברית. כי בברית בין הבתרים אמרתי לו (בראשית טו יד) וגם את הגוי אשר יעבדו דן אנכי:
@129 **לכן.** על פי אותה השבועה: **אמר לבני ישראל אני ה'.** הנאמן בהבטחתי: **והוצאתי אתכם.** כי כן הבטחתיו (שם שם) ואחרי כן יצאו ברכוש גדול: **סבלת מצרים.** טורח משא מצרים:
@131 **נשאתי את ידי.** הרימותיה להשבע בכסאי:
@132 **ולא שמעו אל משה.** לא קבלו תנחומין: **מקצר רוח.** כל מי שהוא מצר, רוחו ונשימתו קצרה ואינו יכול להאריך בנשימתו. קרוב לענין זה שמעתי פרשה זו מרבי ברוך ברבי אליעזר, והביא לי ראיה ממקרא זה (ישעיה טז כא) בפעם הזאת אודיעם את ידי ואת גבורתי וידעו כי שמי ה', למדנו כשהקדוש ברוך הוא מאמן את דבריו אפילו לפרענות מודיע ששמו ה', וכל שכן האמנה לטובה. ורבותינו דרשוהו לענין שלמעלה, שאמר משה (לעיל ה כב) למה הרעתה, אמר לו הקדוש ברוך הוא חבל על דאבדין ולא משתכחין. יש לי להתאונן על מיתת האבות, הרבה פעמים נגליתי אליהם באל שדי ולא אמרו לי מה שמך, ואתה אמרת (לעיל ג יג) מה שמו מה אומר אליהם: **וגם הקמתי** וגו' **.** וכשבקש אברהם לקבור את שרה לא מצא קבר עד שקנה בדמים מרבים, וכן ביצחק ערערו עליו על הבארות אשר חפר, וכן ביעקב (בראשית לג יט) ויקן את חלקת השדה, לנטות אהלו, ולא הרהרו אחר מדותי, ואתה אמרת (ה כב) למה הרעתה. ואין המדרש מתישב אחר המקרא מפני כמה דברים אחת, שלא נאמר, ושמי ה' לא שאלו לי. ואם תאמר לא הודיעם שכך שמו, הרי תחלה כשנגלה לאברהם בין הבתרים נאמר (בראשית טו ז) אני ה' אשר הוצאתיך מאור כשדים. ועוד, היאך הסמיכה נמשכת בדברים שהוא סומך לכאן (פסוק ה) וגם אני שמעתי וגו' (פסוק ו) לכן אמר לבני ישראל. לכך אני אומר יתישב המקרא על פשוטו דבר דבור על אפניו, והדרשה תדרש, שנאמר (ירמיה כג כט) הלוא כה דברי כאש נאם ה' וכפטיש יפוצץ סלע, מתחלק לכמה ניצוצות:
@135 **ואיך ישמעני פרעה.** זה אחד מעשרה קל וחמר שבתורה: **ערל שפתים.** אטום שפתים. וכן כל לשון ערלה אני אומר שהוא אטום (ירמיה ו י) ערלה אזנם, אטומה משמוע, (ירמיה ט כה) ערלי לב, אטומים מהבין, (חבקוק ב טז) שתה גם אתה והערל, והאטם משכרות כוס הקללה. ערלת בשר, שהגיד אטום ומכסה בה. (ויקרא יט כג) וערלתם ערלתו, עשו לו אטם וכסוי אסור שיבדיל בפני אכילתו, (שם) שלש שנים יהיה לכם ערלים, אטום ומכסה ומבדל מלאכלו:
@136 **וידבר ה' אל משה ואל אהרן.** לפי שאמר משה (פסוק יב) ואני ערל שפתים, צירף לו הקדוש ברוך הוא את אהרן להיות לו לפה ולמליץ: **ויצום אל בני ישראל.** צום עליהם להנהיגם בנחת ולסבול אותם: **ואל פרעה מלך מצרים.** צום עליו לחלק לו כבוד בדבריהם, זהו מדרשו. ופשוטו צום על דבר ישראל ועל שליחותו אל פרעה. ודבר הצווי מהו, מפורש בפרשה שניה לאחר סדר היחס, אלא מתוך שהזכיר משה ואהרן הפסיק הענין באלה ראשי בית אבותם (פסוק יד) ללמדנו היאך נלדו משה ואהרן ובמי נתיחסו:
@137 **אלה ראשי בית אבתם.** מתוך שהזקק ליחס שבטו של לוי עד משה ואהרן, בשביל משה ואהרן התחיל ליחסם דרך תולדותם מראובן. [ובפסיקתא רבתי ראיתי לפי שקנטרם יעקב אביהם לשלשה שבטים הללו בשעת מותו, חזר הכתוב ויחסם כאן לבדם לומר שחשובים הם] :
@139 **ושני חיי לוי** וגו' **.** למה נמנו שנותיו של לוי, להודיע כמה ימי השעבוד, שכל זמן שאחד מן השבטים קים לא היה שעבוד, שנאמר (שמות א ו) וימת יוסף וכל אחיו, ואחר כך (שם ח) ויקם מלך חדש, ולוי האריך ימים על כלם:
@141 **ושני חיי קהת ושני חיי עמרם** וגו' **.** מחשבון זה אנו למדים על מושב בני ישראל ארבע מאות שנה שאמר הכתוב, שלא בארץ מצרים לבדה היו, אלא מיום שנלד יצחק, שהרי קהת מיורדי מצרים היה, חשוב כל שנותיו ושנות עמרם ושמונים של משה לא תמצאם ארבע מאות שנה, והרבה שנים נבלעים לבנים בשני האבות:
@143 **יוכבד דדתו.** אחת אבוהי בת לוי אחות קהת:
@146 **אחות נחשון.** מכאן למדנו הנושא אשה צריך לבדוק באחיה:
@148 **מבנות פוטיאל.** מזרע יתרו שפטם עגלים לעבודה זרה. ומזרע יוסף שפטפט ביצרו:
@149 **הוא אהרן ומשה.** אלו שהזכרו למעלה, שילדה יוכבד לעמרם, הוא אהרן ומשה. יש מקומות שמקדים אהרן למשה ויש מקומות שמקדים משה לאהרן, לומר לך ששקולין כאחד: **על צבאתם.** בצבאותם, כל צבאם לשבטיהם. יש על שאינו אלא במקום אות אחת (בראשית כז מ) ועל חרבך תחיה, כמו בחרבך, (יחזקאל לג כו) עמדתם על חרבכם, כמו בחרבכם:
@150 **הם המדברים** וגו' **.** הם שנצטוו הם שקימו: **הוא משה ואהרן.** הם בשליחותם ובצדקתם מתחלה ועד סוף:
@151 **ויהי ביום דבר** וגו' **.** מחבר למקרא שלאחריו:
@152 **וידבר ה'.** הוא הדבור עצמו האמור למעלה (פסוק יא) בא דבר אל פרעה מלך מצרים, אלא מתוך שהפסיק הענין כדי ליחסם, חזר הענין עליו להתחיל בו: **אני ה'.** כדאי אני לשלחך ולקים דברי שליחותי:
@153 **ויאמר משה לפני ה'.** היא האמירה שאמר למעלה (פסוק יב) הן בני ישראל לא שמעו אלי, ושנה הכתוב כאן כיון שהפסיק הענין, וכך היא השטה כאדם האומר נחזור על הראשונות:
@154 **נתתיך אלהים לפרעה.** שופט ורודה לרדותו במכות ויסורין: **יהיה נביאך.** כתרגומו מתורגמנך, וכן כל לשון נבואה אדם המכריז ומשמיע לעם דברי תוכחות, והוא מגזרת (ישעיה נז יט) ניב שפתים, (משלי י לא) ינוב חכמה, ויכל מהתנבות דשמואל (א' י יג) . ובלעז קוראין לו פרקייר''א :
@155 **אתה תדבר.** פעם אחת כל שליחות ושליחות כפי ששמעתו מפי, ואהרן אחיך ימליצנו ויטעימנו באזני פרעה:
@156 **ואני אקשה.** מאחר שהרשיע והתריס כנגדי, וגלוי לפני שאין נחת רוח באמות עובדי עבודה זרה לתת לב שלם לשוב, טוב לי שיתקשה לבו למען הרבות בו אותותי ותכירו אתם את גבורותי. וכן מדתו של הקדוש ברוך הוא מביא פרענות על האמות עובדי עבודה זרה כדי שישמעו ישראל וייראו, שנאמר (צפניה ג ו) הכרתי גוים נשמו פנותם וגו' , (שם ז) אמרתי אך תיראי אותי תקחי מוסר, ואף על פי כן בחמש מכות הראשונות לא נאמר ויחזק ה' את לב פרעה, אלא ויחזק לב פרעה:
@158 **את ידי.** יד ממש להכות בהם:
@162 **מופת.** אות, להודיע שיש צורך (צרוך) במי ששולח אתכם: **לתנין.** נחש:
@164 **בלהטיהם.** בלחשיהון ואין לו דמיון במקרא, ויש לדמות לו (בראשית ג כב) להט החרב המתהפכת, דומה שהיא מתהפכת על ידי לחש:
@165 **ויבלע מטה אהרן.** מאחר שחזר ונעשה מטה בלע את כלן:
@167 **כבד.** תרגומו יקיר, ולא אתיקר, מפני שהוא שם דבר, כמו (שמות יח יח) כי כבד ממך הדבר:
@168 **הנה יצא המימה.** לנקביו, שהיה עושה עצמו אלוה ואומר שאינו צריך לנקביו ומשכים ויוצא לנילוס ועושה שם צרכיו:
@169 **עד כה.** עד הנה ומדרשו עד שתשמע ממני מכת בכורות, שאפתח בה בכה (יא ד) כה אמר ה' כחצות הלילה:
@170 **ונהפכו לדם.** לפי שאין גשמים יורדים במצרים, ונילוס עולה ומשקה את הארץ, ומצרים עובדים לנילוס, לפיכך הלקה את יראתם ואחר כך הלקה אותם:
@171 **ונלאו מצרים.** לבקש רפואה למי היאור שיהיו ראוין לשתות:
@172 **אמר אל אהרן.** לפי שהגין היאור על משה כשנשלך לתוכו, לפיכך לא לקה על ידו לא בדם ולא בצפרדעים, ולקה על ידי אהרן: **נהרתם.** הם נהרות המושכים כעין נהרות שלנו: **יאריהם.** הם ברכות נגרים העשויות בידי אדם משפת הנהר לשדות, ונילוס מימיו מתברכים ועולה דרך היאורים ומשקה השדות: **אגמיהם.** קבוצת מים שאינן נובעין ואינן מושכין, אלא עומדין במקום אחד, וקורין לו אישטנ''ק : **בכל ארץ מצרים.** אף במרחצאות ובאמבטאות שבבתים: **ובעצים ובאבנים.** מים שבכלי עץ ובכלי אבן:
@175 **בלטיהם.** לחש שאומרין אותו בלט ובחשאי. ורבותינו אמרו בלטיהם מעשה שדים, בלהטיהם מעשה כשפים: **ויחזק לב פרעה.** לומר על ידי מכשפות אתם עושים כן, תבן אתם מכניסין לעפריים, עיר שכלה תבן, אף אתם מביאין מכשפות למצרים שכלה כשפים:
@176 **גם לזאת.** למופת המטה, שנהפך לתנין ולא לזה של דם:
@178 **וימלא.** מנין שבעת ימים, שלא שב היאור לקדמותו, שהיתה המכה משמשת רביע חדש ושלשה חלקים היה מעיד ומתרה בהם:
@180 **ואם מאן אתה.** ואם סרבן אתה. מאן כמו ממאן, מסרב, אלא כנה האדם על שם המפעל, כמו (איוב טז יב) שלו, (ירמיה מח יא) ושקט, (מלכים א' כ מג) סר וזעף: **נגף את כל גבולך.** מכה, וכן כל לשון מגפה אינו לשון מיתה אלא לשון מכה, וכן (שמות כא כב) ונגפו אשה הרה, אינו לשון מיתה. וכן (ירמיה יג טז) ובטרם יתנגפו רגליכם, (תהלים צא יב) פן תגוף באבן רגלך, (ישעיה ח יד) ולאבן נגף:
@181 **ועלו.** מן היאור: **בביתך.** ואחר כך בבתי עבדיך. הוא התחיל בעצה תחלה (שמות א ט) ויאמר אל עמו, וממנו התחילה הפרענות:
@182 **ובכה ובעמך.** בתוך מעיהם נכנסין ומקרקרין:
@184 **ותעל הצפרדע.** צפרדע אחת היתה והיו מכין אותה והיא מתזת נחילים נחילים זהו מדרשו. ופשוטו יש לומר שרוץ הצפרדעים קורא לשון יחידות. וכן (להלן יד) ותהי הכנם, הרחישה דוילייר''א בלעז , ואף ותעל הצפרדע גרינוילייר''א בלעז [רחישת צפרדעים] :
@187 **התפאר עלי.** כמו (ישעיה י טו) היתפאר הגרזן על החצב בו, משתבח לומר אני גדול ממך ונט''ר בלעז [להתפאר] . וכן התפאר עלי, השתבח להתחכם ולשאול דבר גדול ולומר שלא אוכל לעשותו: **למתי אעתיר לך.** את אשר אעתיר לך היום על הכרתת הצפרדעים, למתי תרצה שיכרתו, ותראה אם אשלים דברי למועד שתקבע לי. אלו נאמר מתי אעתיר, היה משמע מתי אתפלל, עכשיו שנאמר למתי משמע אני היום אתפלל עליך שיכרתו הצפרדעים לזמן שתקבע עלי, אמור לאיזה יום תרצה שיכרתו. אעתיר, העתירו, והעתרתי, ולא נאמר אעתר עתרו ועתרתי, מפני שכל לשון עתר הרבות פלל הוא, וכאשר יאמר הרבו, ארבה, והרביתי לשון מפעיל, כך יאמר, אעתיר, העתירו, והעתרתי דברים, ואב לכלם והעתרתם עלי דבריכם (יחזקאל לה יג) , הרביתם:
@188 **ויאמר למחר.** התפלל היום שיכרתו למחר:
@190 **ויצא ויצעק.** מיד שיכרתו למחר:
@192 **חמרם חמרם.** צבורים צבורים כתרגומו דגורין גלים:
@193 **והכבד את לבו.** לשון פעול הוא, כמו (בראשית יב ט) הלוך ונסוע' וכן (מלכים ב' ג כד) והכות את מואב, (שמו''א כב יג) ושאול לו באלהים, (מלכים א' כ לז) הכה ופצע: **כאשר דבר ה'.** והיכן דבר (שמות ז ד) ולא ישמע אליכם פרעה:
@194 **אמר אל אהרן.** לא היה העפר כדאי ללקות על ידי משה לפי שהגין עליו כשהרג את המצרי ויטמנהו בחול ולקה על ידי אהרן:
@195 **ותהי הכנם.** הרחישה דולייר''א בלעז [רחישת כנים] :
@196 **להוציא את הכנים.** לבראתם ממקום אחר: **ולא יכלו.** שאין השד שולט על בריה פחותה מכשעורה:
@197 **אצבע אלהים הוא.** מכה זו אינה על ידי כשפים, מאת המקום היא: **כאשר דבר ה'.** (ז ד) ולא ישמע אליכם פרעה:
@199 **משליח בך.** מגרה בך, וכן (דברים לב כד) ושן בהמות אשלח בם, לשון שסוי אינציטי''ר בלעז : **את הערב.** כל מיני חיות רעות ונחשים ועקרבים בערבוביא והיו משחיתים בהם. ויש טעם בדבר באגדה בכל מכה ומכה למה זו ולמה זו. בטכסיסי מלחמות מלכים בא עליהם, כסדר מלכות כשצרה על עיר, בתחלה מקלקל מעינותיה, ואחר כך תוקעין עליהם ומריעין בשופרות ליראם ולבהלם, וכן הצפרדעים מקרקרים והומים וכו. כדאיתא במדרש רבי תנחומא:
@200 **והפליתי.** והפרשתי, וכן (שמות ט ד) והפלה ה', וכן (דברים ל יא) לא נפלאת היא ממך. לא מבדלת ומפרשת היא ממך: **למען תדע כי אני ה' בקרב הארץ.** אף על פי ששכינתי בשמים גזרתי מתקימת בתחתונים:
@201 **ושמתי פדת.** שיבדיל בין עמי ובין עמך:
@202 **תשחת הארץ.** נשחתה הארץ. אתחבלת ארעא:
@203 **זבחו לאלהיכם בארץ.** במקומכם, ולא תלכו במדבר:
@204 **תועבת מצרים.** יראת מצרים, כמו (מלכים ב' כג יג) ולמלכם תועבת בני עמון, ואצל ישראל קורא אותה תועבה. ועוד יש לומר בלשון אחר תועבת מצרים, דבר שנאוי הוא למצרים זביחה שאנו זובחים, שהרי יראתם אנו זובחים: **ולא יסקלנו.** בתמיהה:
@207 **התל.** כמו להתל:
@208 **ויעתר אל ה'.** נתאמץ בתפלה, וכן אם בא לומר, ויעתיר היה יכול לומר ומשמע וירבה בתפלה, וכשהוא אומר בלשון ויפעל משמע וירבה להתפלל:
@209 **ויסר הערב.** ולא מתו כמו שמתו הצפרדעים, שאם מתו היה להם הנאה בעורות:
@210 **גם בפעם הזאת.** אף על פי שאמר (פסוק כד) אנכי אשלח אתכם, לא קים הבטחתו:
@212 **מחזיק בם.** אוחז בם, כמו (דברים כה יא) והחזיקה במבשיו:
@213 **הנה יד ה' הויה.** לשון הוה, כי כן יאמר בלשון נקבה על שעבר היתה ועל העתיד תהיה ועל העומד הויה, כמו עושה, רוצה, רועה:
@214 **והפלה.** והבדיל:
@218 **מלא חפניכם.** ילויני''ש בלעז : **פיח כבשן.** דבר הנפח מן הגחלים עמומים הנשרפים בכבשן, ובלעז אולבי''ש . פיח לשון הפחה, שהרוח מפיחן ומפריחן: **וזרקו משה.** כל דבר הנזרק בכח אינו נזרק אלא ביד אחת. הרי נסים הרבה, אחד שהחזיק קמצו של משה מלא חפנים שלו ושל אהרן. ואחד שהלך האבק על כל ארץ מצרים:
@219 **לשחין פרח אבעבעת.** כתרגומו לשחין סגי אבעבועין, שעל ידו צומחין בהן בועות: **שחין.** לשון חמימות. והרבה יש בלשון משנה (יומא נג ב) שנה שחונה:
@220 **באדם ובבהמה.** ואם תאמר מאין היו להם הבהמות והלא כבר נאמר (פסוק ו) וימת כל מקנה מצרים, אלא לא נגזרה גזרה אלא על אותן שבשדות בלבד, שנאמר (פסוק ג) במקנך אשר בשדה והירא את דבר ה' הניס את מקנהו אל הבתים. וכן שנויה במכילתא אצל (יד ז) ויקח שש מאות רכב בחור:
@224 **את כל מגפתי.** למדנו מכאן שמכת בכורות (י''ג: בכורות) שקולה כנגד כל המכות:
@225 **כי עתה שלחתי את ידי** וגו' **.** כי אלו רציתי כשהיתה ידי במקנך שהכיתים בדבר שלחתיה והכיתי אותך ואת עמך עם הבהמות ותכחד מן הארץ, אבל בעבור זאת העמדתיך וגו' :
@227 **עודך מסתולל בעמי.** כתרגומו כבישת ליה לעמי, והוא מגזרת (ישעיה יא טז) מסלה, דמתרגמינן אורח כבישא, ובלעז קלקיי''ר . וכבר פרשתי בסוף ויהי מקץ כל תבה שתחלת יסודה סמ''ך והיא באה לדבר בלשון מתפעל, נותן התי''ו של שמוש באמצע אותיות של עיקר, כגון זו וכגון (קהלת יב ה) ויסתבל החגב, מגזרת סבל, (במדבר טז יג) כי תשתרר עלינו, מגזרת שר ונגיד, (דניאל ז ח) משתכל הוית:
@228 **כעת מחר.** כעת הזאת למחר, שרט לו שריטה בכותל למחר כשתגיע חמה לכאן ירד הברד: **הוסדה.** שנתיסדה וכל תבה שתחלת יסודה יו''ד כגון יסד, ילד, ידע, יסר, כשהיא מתפעלת תבא הוי''ו במקום היו''ד, כמו הוסדה (הושע ב ה) הולדה (אסתר ב כה) ויודע (בראשית מו כ) ויולד ליוסף, בדברים לא יוסר עבד (משלי כט יט) :
@229 **שלח העז.** כתרגומו שלח כנוש. וכן (ישעיה י לא) ישבי הגבים העיזו, (ירמיה ו א) העזו בני בנימן: **ולא יאסף הביתה.** לשון הכנסה הוא:
@230 **הניס.** הבריח לשון (שמות ד ג) וינס משה:
@232 **על השמים.** לצד השמים, ומדרש אגדה הגביהו הקדוש ברוך הוא למשה למעלה מן השמים:
@234 **מתלקחת בתוך הברד.** נס בתוך נס, האש והברד מעורבין, והברד מים הוא, ולעשות רצון קונם עשו שלום ביניהם:
@238 **ורב.** די לו במה שהוריד כבר:
@239 **כצאתי את העיר.** מן העיר, אבל בתוך העיר לא התפלל, לפי שהיתה מלאה גלולים:
@240 **טרם תיראון.** עדין לא תיראון. וכן כל טרם שבמקרא עדין לא הוא, ואינו לשון קודם, כמו (בראשית יט ד) טרם ישכבו, עד לא שכיבו (שם ב ה) טרם יצמח, עד לא צמח, אף זה כן הוא ידעתי כי עדין אינכם יראים ומשתהיה הרוחה תעמדו בקלקולכם:
@241 **והפשתה והשערה נכתה.** נשברה לשון (מלכים ב כג כט) פרעה נכה, (ישעיה טז ז) נכאים, וכן (פסוק לב) לא נכו. ולא יתכן לפרשו לשון הכאה, שאין נו''ן במקום ה''א לפרש נכתה כמו הכתה, נכו כמו הכו, אלא הנו''ן שרש בתבה והרי הוא מגזרת (איוב לג כא) ושפו עצמותיו: **כי השערה אביב.** כבר בכרה ועומדת בקשיה ונשתברו ונפלו. וכן הפשתה גדלה כבר והקשה לעמוד בגבעוליה: **השערה אביב.** עמדה באביה, לשון (שיר השירים ו יא) באבי הנחל:
@242 **כי אפילת הנה.** מאחרות, ועדין היו רכות ויכולות לעמוד בפני קשה. ואף על פי שנאמר (פסוק כה) ואת כל עשב השדה הכה הברד יש לפרש פשוטו של מקרא בעשבים העומדים בקלחם הראויים ללקות בברד. ובמדרש רבי תנחומא יש מרבותינו שנחלקו על זאת ודרשו כי אפילות פלאי פלאות נעשו להם, שלא לקו:
@243 **לא נתך.** לא הגיע, ואף אותן שהיו באויר לא הגיעו לארץ, ודומה לו (דניאל ט יא) ותתך עלינו האלה והשבועה, דעזרא, ותגיע עלינו. ומנחם בן סרוק חברו בחלק (יחזקאל כב כב) כהתוך כסף, לשון יציקת מתכת, ורואה אני את דבריו, כתרגומו ויצק (שמות לח ה) ואתיך, (שם כז) לצקת לאתכא, אף זה לא נתך לארץ לא לארץ: הוצק
@246 **ויאמר ה' אל משה בא אל פרעה.** והתרה בו: **שתי.** שימי, שאשית אני:
@247 **ולמען תספר.** בתורה להודיע לדורות: **התעללתי.** שחקתי, כמו (במדבר כב כט) כי התעללת בי, (שמואל א' ו ו) הלוא כאשר התעולל בהם, האמור במצרים. ואינו לשון פועל ומעללים, שאם כן היה לו לכתוב עוללתי, כמו (איכה א כב) ועולל למו כאשר עוללת לי, (שם כב) אשר עולל לי:
@248 **לענת.** כתרגומו לאתכנעא, והוא מגזרת עני, מאנת להיות עני ושפל מפני:
@250 **את עין הארץ.** את מראה הארץ: **ולא יוכל** וגו' **.** הרואה לראות את הארץ, ולשון קצרה דבר:
@252 **הטרם תדע.** העוד לא ידעת כי אבדה מצרים:
@253 **ויושב.** הושבו על ידי שליח ששלחו אחריהם והשיבום אל פרעה:
@255 **כאשר אשלח אתכם ואת טפכם.** אף כי אשלח גם את הצאן ואת הבקר כאשר אמרתם: **ראו כי רעה נגד פניכם.** כתרגומו. ומדרש אגדה שמעתי כוכב אחד יש ששמו רעה. אמר להם פרעה רואה אני באיצטגנינות שלי אותו כוכב עולה לקראתכם במדבר, והוא סימן דם והריגה וכשחטאו ישראל בעגל ובקש הקדוש ברוך הוא להרגם אמר משה בתפלתו (שמות לב יב) למה יאמרו מצרים לאמר ברעה הוציאם, זו היא שאמר להם ראו כי רעה נגד פניכם, מיד (שם יד) וינחם ה' על הרעה והפך את הדם לדם מילה, שמל יהושע אותם, וזהו שנאמר (יהושע ה ט) היום גלותי את חרפת מצרים מעליכם שהיו אומרים לכם דם אנו רואין עליכם במדבר:
@256 **לא כן.** כאשר אמרתם להוליך הטף עמכם אלא לכו נא הגברים ועבדו את ה': **כי אתה אתם מבקשים.** כי אותה בקשתם עד הנה (שמות ה ח) נזבחה לאלהינו, ואין דרך הטף לזבוח: **ויגרש אתם.** הרי זה לשון קצר ולא פרש מי המגרש:
@257 **בארבה.** בשביל מכת הארבה:
@258 **ורוח הקדים.** רוח מזרחית נשא את הארבה, לפי שבא כנגדו שמצרים בדרומית מערבית היתה, כמו שמפורש במקום אחר:
@259 **ואחריו לא יהיה כן.** ואותו שהיה בימי יואל, שנאמר (יואל ב ב) כמוהו לא נהיה מן העולם, למדנו שהיה כבד משל משה כי אותו של יואל היה על ידי מינין הרבה, שהיו יחד ארבה ילק חסיל גזם, אבל של משה לא היה אלא של מין אחד, וכמוהו לא היה ולא יהיה:
@260 **כל ירק.** עלה ירוק וירדור''א בלעז :
@264 **רוח ים.** רוח מערבי: **ימה סוף.** אומר אני שים סוף היה מקצתו במערב כנגד כל רוח דרומית וגם במזרח של ארץ ישראל, לפיכך רוח ים תקעו לארבה בימה סוף כנגדו. וכן מצינו לענין תחומין שהוא פונה לצד מזרח, שנאמר (שמות כג לא) מים סוף ועד ים פלשתים, ממזרח למערב, שים פלשתים במערב היה, שנאמר בפלשתים (צפניה ב ה) יושבי חבל הים גוי כרתים: **לא נשאר ארבה אחד.** אף המלוחים שמלחו מהם:
@266 **וימש חשך.** ויחשיך עליהם חשך יותר מחשכו של לילה, וחשך של לילה יאמיש ויחשיך עוד: **וימש.** כמו ויאמש יש לנו תיבות הרבה חסרות אל''ף לפי שאין הברת האל''ף נכרת כל כך אין הכתוב מקפיד על חסרונה, כגון (ישע' יג כ) ולא יהל שם ערבי, כמו לא יאהל, לא יטה אהלו. וכן (שמואל ב כב מ) ותזרני חיל, כמו ותאזרני. ואונקלוס תרגם לשון הסרה, כמו (שמות יג כב) לא ימיש בתר דיעדי קבל ליליא, כשיגיע סמוך לאור היום. אבל אין הדבר מישב על הוי''ו של וימש, לפי שהוא כתוב אחר ויהי חשך. ומדרש אגדה פותרו לשון (דברים כח כט) ממשש בצהרים, שהיה כפול ומכפל ועב עד שהיה בו ממש:
@267 **ויהי חשך אפלה** וכו' **שלשת ימים** וגו' **.** חשך של אופל שלא ראו איש את אחיו אותן שלשת ימים. ועוד שלשת ימים אחרים חשך מכפל על זה, שלא קמו איש מתחתיו. יושב אין יכול לעמוד, ועומד אין יכול לישב. ולמה הביא עליהם חשך, שהיו בישראל באותו הדור רשעים, ולא היו רוצים לצאת, ומתו בשלשת ימי אפלה כדי שלא יראו מצרים במפלתם ויאמרו אף הן לוקין כמונו. ועוד שחפשו ישראל וראו את כליהם, וכשיצאו והיו שואלין מהן והיו אומרים אין בידינו כלום אמר לו אני ראיתיו בביתך ובמקום פלוני הוא: **שלשת ימים.** שלוש של ימים טירציינ''א בלעז וכן שבעת ימים בכל מקום שטיינ''א של ימים. כד **יצג.** יהא מצג במקומו:
@270 **גם אתה תתן.** לא דיך שמקננו ילך עמנו, אלא גם משלך תתן:
@271 **פרסה.** פרסת רגל פלנט''א בלעז : **לא נדע מה נעבד.** כמה תכבד העבודה שמא ישאל ממנו יותר ממה שיש בידינו:
@274 **כן דברת.** יפה דברת ובזמנו דברת, אמת שלא אוסיף עוד ראות פניך:
@275 **כלה.** גמירא, (כלה) כליל, כלכם ישלח:
@276 **דבר נא.** אין נא אלא לשון בקשה, בבקשה ממך הזהירם על כך שלא יאמר אותו צדיק אברהם (בראשית טו יג) ועבדום וענו אותם קים בהם, (שם יד) ואחרי כן יצאו ברכוש גדול לא קים בהם:
@278 **ויאמר משה כה אמר ה'.** בעמדו לפני פרעה נאמרה לו נבואה זו שהרי משיצא מלפניו לא הוסיף ראות פניו: **כחצת הלילה.** כהחלק הלילה, כחצות, כמו (מלכים א' יט כה) כעלות, (תהלים קכד ג) בחרות אפם בנו, זהו פשוטו לישבו על אפניו, שאין חצות שם דבר של חצי. ורבותינו דרשוהו כמו בחצי הלילה (שמות יב כט) ואמרו, שאמר משה כחצות, דמשמע סמוך לו או לפניו או לאחריו, ולא אמר בחצות, שמא יטעו אצטגניני פרעה, ויאמרו משה בדאי הוא:
@279 **עד בכור השבי.** (שמות יב כט) למה לקו השבויים, כדי שלא יאמרו, יראתם תבעה עלבונם והביאה פרענות על מצרים: **מבכור פרעה עד בכור השפחה.** כל הפחותים מבכור פרעה וחשובים מבכור השפחה היו בכלל. ולמה לקו בני השפחות, שאף הם היו משעבדים בהם ושמחים בצרתם: **וכל בכור בהמה.** לפי שהיו עובדין לה, וכשהקדוש ברוך הוא נפרע מן האמה נפרע מאלהיה:
@281 **לא יחרץ כלב לשנו.** אומר אני שהוא לשון שנון, לא ישנן, וכן (יהושע י כא) לא חרץ לבני ישראל לאיש את לשנו, לא שנן, (שמו''ב ה כד) אז תחרץ תשתנן, (ישעיה מא טו) למורג חרוץ שנון, (משלי כא ה) מחשבות חרוץ, אדם חריף ושנון, (משלי י ד) ויד חרוצים תעשיר, חריפים, סוחרים שנונים: **אשר יפלה.** יבדיל:
@282 **וירדו כל עבדיך.** חלק כבוד למלכות שהרי בסוף ירד פרעה בעצמו אליו בלילה (שמות יב לא) ויאמר קומו צאו מתוך עמי ולא אמר לו משה מתחלה וירדת אלי והשתחוית לי: **אשר ברגליך.** ההולכים אחר עצתך והלוכך: **ואחרי כן אצא.** עם כל העם מארצך: **ויצא מעם פרעה.** כשגמר דבריו יצא מלפניו: **בחרי אף.** על שאמר לו (שמות י כח) אל תוסף ראות פני:
@283 **למען רבות מופתי.** מופתי שנים, רבות שלושה מכת בכורות וקריעת ים סוף ולנער את מצרים:
@284 **ומשה ואהרן עשו** וגו' **.** כבר כתב לנו זאת בכל המופתים, ולא שנאה כאן אלא בשביל לסמכה לפרשה של אחריה:
@285 **ויאמר ה' אל משה ואל אהרן.** בשביל שאהרן עשה וטרח במופתים כמשה, חלק לו כבוד זה במצוה ראשונה שכללו עם משה בדבור: **בארץ מצרים.** חוץ לכרך, או אינו אלא בתוך הכרך תלמוד לומר (לעיל ט כט) כצאתי את העיר וגו' , ומה תפלה קלה לא התפלל בתוך הכרך דבור חמור לא כל שכן, ומפני מה לא נדבר עמו בתוך הכרך, לפי שהיתה מלאה גלולים:
@286 **החדש הזה.** הראהו לבנה בחדושה ואמר לו כשהירח מתחדש יהיה לך ראש חדש. ואין מקרא יוצא מידי פשוטו, על חדש ניסן אמר לו, זה יהיה ראש לסדר מנין החדשים, שיהא אייר קרוי שני, סיון שלישי: **הזה.** נתקשה משה על מולד הלבנה באיזו שעור תראה ותהיה ראויה לקדש, והראה לו באצבע את הלבנה ברקיע, ואמר לו כזה ראה וקדש. וכיצד הראהו, והלא לא היה מדבר עמו אלא ביום, שנאמר (שמ' ו כח) ויהי ביום דבר ה', (ויק' ז לח) ביום צוותו, (במדבר טו כג) מן היום אשר צוה ה' והלאה, אלא סמוך לשקיעת החמה נאמרה לו פרשה זו, והראהו עם חשכה:
@287 **דברו אל כל עדת.** וכי אהרן מדבר והלא כבר נאמר (שמות ז ב) אתה תדבר, אלא חולקין כבוד זה לזה ואומרים זה לזה למדני, והדבור יוצא מבין שניהם, כאלו שניהם מדברים: **אל כל עדת ישראל** וגו' **בעשר לחדש.** דברו היום בראש חדש שיקחוהו בעשור לחדש: **הזה.** פסח מצרים מקחו בעשור, ולא פסח דורות: **שה לבית אבת.** למשפחה אחת, הרי שהיו מרבין יכול שה אחד לכלן, תלמוד לומר שה לבית:
@288 **ואם ימעט הבית מהיות משה.** ואם יהיו מועטין מהיות משה אחד שאין יכולין לאכלו ויבא לידי נותר, **ולקח הוא ושכנו** וגו' **זהו משמעו לפי פשוטו.** ועוד יש בו מדרש ללמד שאחר שנמנו עליו יכולין להתמעט ולמשוך ידיהם המנו ולהמנות על שה אחר, אך אם באו למשוך ידיהם ולהתמעט מהיות משה, יתמעטו בעוד השה קים בהיותו בחיים, ולא משנשחט: **במכסת.** חשבון וכן (ויקרא כז כג) מכסת הערכך: **לפי אכלו.** הראוי לאכילה פרט לחולה וזקן שאינן יכולין לאכול כזית: **תכסו.** תתמנון:
@289 **תמים.** בלא מום: **בן שנה.** כל שנתו קרוי בן שנה כלומר שנלד בשנה זו: **מן הכבשים ומן העזים.** או מזה או מזה שאף עז קרויה שה, שנאמר (דברים יד ד) ושה עזים:
@290 **והיה לכם למשמרת.** זה לשון בקור שטעון בקור ממום ארבעה ימים קדם שחיטה, ומפני מה הקדים לקיחתו לשחיטתו ארבעה ימים מה שלא צוה כן בפסח דורות, היה ר' מתיא בן חרש אומר הרי הוא אומר (יחזקאל טז ח) ואעבור עליך ואראך והנה עתך עת דדים, הגיעה שבועה שנשבעתי לאברהם שאגאל את בניו ולא היו בידם מצוות להתעסק בהם כדי שיגאלו, שנאמר (שם ז) ואת ערום ועריה, ונתן להם שתי מצוות דם פסח ודם מילה, שמלו באותו הלילה, שנאמר (שם ו) מתבוססת בדמיך, בשני דמים, ואומר (זכריה ט יא) . גם את בדם בריתך שלחתי אסיריך מבור אין מים בו, ולפי שהיו שטופים בעבודה זרה אמר להם (פסוק כא) משכו וקחו לכם, משכו ידיכם מעבודה זרה וקחו לכם צאן של מצוה: **ושחטו אתו** וגו' **.** וכי כלן שוחטין אלא מכאן ששלוחו של אדם כמותו: **קהל עדת ישראל.** קהל ועדה וישראל. מכאן אמרו, פסחי צבור נשחטין בשלש כתות זו אחר זו, נכנסה כת ראשונה ננעלו דלתות העזרה וכו' , כדאיתא בפסחים (דף סד א) : **בין הערבים.** משש שעות ולמעלה קרוי בין הערבים, שהשמש נוטה לבית מבואו לערוב. ולשון בין הערבים נראה בעיני אותן שעות שבין עריבת היום לעריבת הלילה, עריבת היום בתחלת שבע שעות מכי ינטו צללי ערב (ירמיה ו ד) , ועריבת הלילה בתחלת הלילה. ערב לשון נשף וחשך, כמו (ישעיה כד יא) ערבה כל שמחה:
@291 **ולקחו מן הדם.** זו קבלת הדם. יכול ביד, תלמוד לומר (פסוק כב) אשר בסף: **המזוזת.** הם הזקופות אחת מכאן לפתח ואחת מכאן: **המשקוף.** הוא העליון שהדלת שוקף עליו כשסוגרין אותו לינט''ר בלעז ולשון שקיפה. חבטה, כמו (ויקרא כו לו) קול עלה נדף, טרפא דשקיף, (שמות כא כה) חבורה. משקופי: **על הבתים אשר יאכלו אתו בהם.** ולא על משקוף ומזוזות שבבית התבן ובבית הבקר, שאין דרין בתוכו:
@292 **את הבשר.** ולא גידים ועצמות: **על מררים.** כל עשב מר נקרא מרור. וצום לאכול מרור זכר לוימררו את חייהם (שמות א יד) :
@293 **אל תאכלו ממנו נא.** שאינו צלוי כל צרכו קראו נא בלשון ערבי: **ובשל מבשל.** כל זה באזהרת אל תאכלו: **במים.** מנין לשאר משקין, תלמוד לומר ובשל מבשל מכל מקום: **כי אם צלי אש.** למעלה גזר עליו במצות עשה וכאן הוסיף עליו לא תעשה אל תאכלו ממנו כי אם צלי אש: **ראשו על כרעיו.** צולהו כלו כאחד עם ראשו ועם כרעיו ועם קרבו, ובני מעיו נותן לתוכו אחר הדחתן. ולשון על כרעיו ועל קרבו כלשון (שמות ו כו) על צבאותם, כמו בצבאותם, כמות שהן, אף זה כמות שהוא, כל בשרו משלם:
@294 **והנתר ממנו עד בקר.** מה תלמוד לומר עד בקר פעם שניה, לתן בקר על בקר, שהבקר משמעו משעת הנץ החמה, ובא הכתוב להקדים שאסור באכילה מעלות השחר, זהו לפי משמעו. ועוד מדרש אחר למד שאינו נשרף ביום טוב אלא ממחרת. וכך תדרשנו והנותר ממנו בבקר ראשון עד בקר שני תעמוד ותשרפנו:
@295 **מתניכם חגרים.** מזמנים לדרך: **בחפזון.** לשון בהלה ומהירות, כמו (שמואל א' כג כו) ויהי דוד נחפז ללכת, (מלכים ב' ז טו) אשר השליכו ארם בחפזם: **פסח הוא לה'.** הקרבן קרוי פסח על שם הדלוג והפסיחה שהקדוש ברוך הוא היה מדלג בתי ישראל מבין בתי מצרים וקופץ ממצרי למצרי, וישראל אמצעי נמלט, ואתם עשו כל עבודותיו לשם שמים. דבר אחר דרך דלוג וקפיצה, זכר לשמו שקרוי פסח וגם פשק''א [פסח] לשון פסיעה:
@296 **ועברתי.** כמלך העובר ממקום למקום, ובהעברה אחת וברגע אחד כלן לוקין: **כל בכור בארץ מצרים.** אף בכורות אחרים והם במצרים, ומנין אף בכורי מצרים שבמקומות אחרים, תלמוד לומר (תהלים קלו י) למכה מצרים בבכוריהם: **מאדם ועד בהמה.** מי שהתחיל בעברה ממנו מתחלת הפרענות: **ובכל אלהי מצרים.** של עץ נרקבת, ושל מתכת נמסת ונתכת לארץ: **אעשה שפטים אני ה'.** אני בעצמי ולא על ידי שליח:
@297 **והיה הדם לכם לאת.** לכם לאות ולא לאחרים לאות מכאן שלא נתנו הדם אלא מבפנים: **וראיתי את הדם.** הכל גלוי לפניו, אלא אמר הקדוש ברוך הוא נותן אני את עיני לראות שאתם עסוקים במצוותי ופוסח אני עליכם: **ופסחתי.** וחמלתי, ודומה לו (ישעיה לא ה) פסח והמליט. ואני אומר כל פסיחה לשון דלוג וקפיצה. ופסחתי מדלג היה מבתי ישראל לבתי מצרים, שהיו שרוים זה בתוך זה, וכן (מלכים א' יח כא) פסחים על שתי הסעפים, וכן כל הפסחים הולכים כקופצים, וכן (ישעיה לא ה) פסח והמליט, מדלגו וממלטו מבין המומתים: **ולא יהיה בכם נגף.** אבל הוה הוא במצרים הרי שהיה מצרי בביתו של ישראל, יכול ימלט, תלמוד לומר ולא יהיה בכם נגף, אבל הוה במצרי שבבתיכם, הרי שהיה ישראל בביתו של מצרי, שומע אני ילקה כמותו, תלמוד לומר ולא יהיה בכם נגף:
@298 **לזכרון.** לדורות: **וחגתם אתו.** יום שהוא לך לזכרון אתה חוגגו. ועדין לא שמענו אי זהו יום הזכרון, תלמוד לומר (שמות יג ג) זכור את היום הזה אשר יצאתם, למדנו שיום היציאה הוא יום של זכרון. ואיזה יום יצאו, תלמוד לומר (במדבר לג ג) ממחרת הפסח יצאו, הוי אומר יום חמשה עשר בניסן הוא של יום טוב, שהרי ליל חמשה עשר אכלו את הפסח ולבקר יצאו: **לדרתיכם.** שומע אני מעוט דורות שנים, תלמוד לומר חקת עולם תחגהו:
@299 **שבעת ימים.** שטיינ''א של ימים: **שבעת ימים מצות תאכלו.** ובמקום אחר הוא אומר (דברים טז ח) ששת ימים תאכל מצות, למד על שביעי של פסח שאינו חובה לאכול מצה, ובלבד שלא יאכל חמץ. מנין אף ששה רשות תלמוד לומר ששת ימים. זו מדה בתורה, דבר שהיה בכלל ויצא מן הכלל ללמד, לא ללמד על עצמו בלבד יצא, אלא ללמד על הכלל כלו יצא, מה שביעי רשות אף ששה רשות, יכול אף לילה הראשון רשות, תלמוד לומר (להלן פסוק יח) בערב תאכלו מצות, הכתוב קבעו חובה: **אך ביום הראשון תשביתו שאר.** מערב יום טוב, וקרוי ראשון לפי שהוא לפני השבעה, ומצינו מקדם קרוי ראשון, כמו (איוב טו ז) הראישון אדם תולד, הלפני אדם נלדת, או אינו אלא ראשון של שבעה, תלמוד לומר (שמות לד כה) לא תשחט על חמץ, לא תשחט הפסח ועדין חמץ קים: **הנפש ההוא.** כשהיא בנפשה ובדעתה, פרט לאנוס: **מישראל.** שומע אני תכרת מישראל ותלך לה לעם אחר, תלמוד לומר במקום אחר (ויקרא כב ג) מלפני, בכל מקום שהוא רשותי:
@300 **מקרא קדש.** מקרא שם דבר, קרא אותו קדש לאכילה ושתיה וכסות: **לא יעשה בהם.** אפלו על ידי אחרים: **הוא לבדו.** הוא ולא מכשיריו שאפשר לעשותן מערב יום טוב: **לכל נפש.** אפלו לבהמה יכול אף לנכרים, תלמוד לומר לכם:
@301 **ושמרתם את המצות.** שלא יבאו לידי חמוץ מכאן אמרו תפח, תלטוש בצונן. רבי יאשיה אומר אל תהי קורא את המצות אלא את המצוות, כדרך שאין מחמיצין את המצה כך אין מחמיצין את המצוה אלא אם באה לידך עשה אותה מיד: **ושמרתם את היום הזה.** ממלאכה: **לדרתיכם חקת עולם.** לפי שלא נאמר דורות וחקת עולם על המלאכה אלא על החגיגה, לכך חזר ושנאו כאן, שלא תאמר אזהרת (לעיל טז) כל מלאכה לא יעשה, לא לדורות נאמרה, אלא לאותו הדור:
@302 **עד יום האחד ועשרים.** למה נאמר, והלא כבר נאמר (לעיל טו) שבעת ימים, לפי שנאמר ימים, לילות מנין, תלמוד לומר עד יום האחד ועשרים וגו' :
@303 **לא ימצא בבתיכם.** מנין לגבולין, תלמוד לומר (להלן יג ז) בכל גבלך. מה תלמוד לומר בבתיכם, מה ביתך ברשותך אף גבולך שב א רשותך, יצא חמצו של נכרי שהוא אצל ישראל ולא קבל עליו אחריות: **כי כל אכל מחמצת.** לענוש כרת על השאור, והלא כבר ענש על החמץ, אלא שלא תאמר חמץ שראוי לאכילה ענש עליו, שאור שאינו ראוי לאכילה לא יענש עליו. ואם ענש על השאור ולא ענש על החמץ, הייתי אומר שאור שהוא מחמץ אחרים ענש עליו, חמץ שאינו מחמץ אחרים לא יענש עליו, לכך נאמרו שניהם: **בגר ובאזרח הארץ.** לפי שהנס נעשה לישראל, הצרך לרבות את הגרים:
@304 **מחמצת לא תאכלו.** אזהרה על אכילת שאור: **כל מחמצת.** להביא את תערבתו: **בכל מושבתיכם תאכלו מצות.** זה בא ללמד שתהא ראויה לאכל בכל מושבותיכם, פרט למעשר שני וחלות תודה:
@305 **משכו.** מי שיש לו צאן ימשוך משלו: **וקחו.** מי שאין לו יקח מן השוק: **למשפחתיכם.** שה לבית אבות:
@306 **אזוב.** מין ירק שיש לו גבעולין: **אגדת אזוב.** שלשה קלחין קרויין אגדה: **אשר בסף.** בכלי, כמו (מלכים ב' יב יד) ספות כסף: **מן הדם אשר בסף.** למה חזר ושנאו, שלא תאמר טבילה אחת לשלש המתנות, לכך נאמר עוד אשר בסף, ושתהא כל נתינה ונתינה מן הדם אשר בסף, על כל הגעה טבילה: **ואתם לא תצאו** וגו' **.** מגיד שמאחר שנתנה רשות למשחית לחבל אינו מבחין בין צדיק לרשע, ולילה רשות למחבלים הוא, שנאמר (תהלים קד כ) בו תרמוש כל חיתו יער:
@307 **ופסח.** וחמל, ויש לומר ודלג: **ולא יתן המשחית.** ולא יתן לו יכלת לבא, כמו (בראשית לא ז) ולא נתנו אלהים להרע עמדי:
@309 **והיה כי תבאו אל הארץ.** תלה הכתוב מצוה זו בביאתם לארץ, ולא נתחיבו במדבר אלא בפסח אחד שעשו בשנה השנית ועל פי הדבור: **כאשר דבר.** והיכן דבר, (שמות ו ח) והבאתי אתכם אל הארץ וגו' :
@311 **ויקד העם.** על בשורת הגאלה וביאת הארץ ובשורת הבנים שיהיו להם:
@312 **וילכו ויעשו בני ישראל.** וכי כבר עשו, והלא מראש חדש נאמר להם, אלא מכיון שקבלו עליהם, מעלה עליהם כאלו עשו: **וילכו ויעשו.** אף ההליכה מנה הכתוב, לתן שכר להליכה ושכר לעשיה: **כאשר צוה ה' את משה ואהרן.** להגיד שבחן של ישראל, שלא הפילו דבר מכל מצות משה ואהרן. ומהו כן עשו, אף משה ואהרן כן עשו:
@313 **וה'.** כל מקום שנאמר וה' הוא ובית דינו, שהוי''ו לשון תוספת הוא כמו פלוני ופלוני: **הכה כל בכור.** אף של אמה אחרת והוא במצרים: **מבכר פרעה.** אף פרעה בכור היה ונשתיר מן הבכורות, ועליו הוא אומר (שמות ט טז) בעבור הראותך את כחי, בים סוף: **עד בכור השבי.** שהיו שמחין לאידם של ישראל. ועוד, שלא יאמרו יראתנו הביאה הפרענות, ובכור השפחה בכלל היה, שהרי מנה מן החשוב שבכלן עד הפחות, ובכור השפחה חשוב מבכור השבי:
@314 **ויקם פרעה.** ממטתו: **לילה.** ולא כדרך המלכים בשלש שעות ביום: **הוא.** תחלה ואחר כך עבדיו, מלמד שהיה הוא מחזר על בתי עבדיו ומעמידן: **כי אין בית אשר אין שם מת.** יש שם בכור מת. אין שם בכור, גדול שבבית קרוי בכור, שנאמר (תהלים פט כח) אף אני בכור אתנהו. דבר אחר מצריות מזנות תחת בעליהן ויולדות מרוקים פנויים, והיו להם בכורות הרבה, פעמים הם חמשה לאשה אחת, כל אחד בכור לאביו:
@315 **ויקרא למשה ולאהרן לילה.** מגיד שהיה מחזר על פתחי העיר וצועק היכן משה שרוי היכן אהרן שרוי: **גם אתם.** הגברים: **גם בני ישראל.** הטף: **ולכו עבדו את ה' כדברכם.** הכל כמו שאמרתם, ולא כמו שאמרתי אני, בטל (שמות ה ב) לא אשלח בטל (שם י ח) מי ומי ההולכים בטל (שם כד) רק צאנכם ובקרכם יצג:
@316 **גם צאנכם גם בקרכם קחו.** ומהו כאשר דברתם, גם אתה תתן בידנו זבחים ועולות (שמות י כה) : **קחו כאשר דברתם וברכתם גם אתי.** התפללו עלי שלא אמות, שאני בכור:
@317 **כלנו מתים.** אמרו לא כגזרת משה הוא, שהרי אמר (לעיל יא ה) ומת כל בכור, וכאן אף הפשוטים מתים חמשה או עשרה בבית אחד:
@318 **טרם יחמץ.** המצריים לא הניחום לשהות כדי חמוץ: **משארתם.** שירי מצה ומרור: **על שכמם.** אף על פי שבהמות הרבה הוליכו עמהם מחבבים היו את המצוה:
@319 **כדבר משה.** שאמר להם במצרים (לעיל יא ב) וישאלו איש מאת רעהו: **ושמלת.** אף הן היו חשובות להם מן הכסף ומן הזהב, והמאוחר בפסוק חשוב:
@320 **וישאלום.** אף מה שלא היו שואלים מהם היו נותנים להם. אתה אומר אחד, טול שנים ולך: **וינצלו.** ורוקינו:
@321 **מרעמסס סכתה.** מאה ועשרים מיל היו ובאו שם לפי שעה, שנאמר (שמות יט ד) ואשא אתכם על כנפי נשרים: **הגברים.** מבן עשרים שנה ומעלה:
@322 **ערב רב.** תערובות אמות של גרים:
@323 **עגת מצות.** חררה של מצה בצק שלא החמיץ קרוי מצה: **וגם צדה לא עשו להם.** לדרך. מגיד שבחן של ישראל, שלא אמרו היאך נצא למדבר בלא צדה, אלא האמינו והלכו, הוא שמפורש בקבלה (ירמיה ב ב) זכרתי לך חסד נעוריך אהבת כלולתיך לכתך אחרי במדבר בארץ לא זרועה, ומה שכר מפורש אחריו (שם ג) קדש ישראל לה' וגו' :
@324 **אשר ישבו במצרים.** אחר שאר הישיבות שישבו גרים בארץ לא להם: **שלשים שנה וארבע מאות שנה.** בין הכל משנלד יצחק עד עכשיו היו ארבע מאות שנה. משהיה לו זרע לאברהם נתקים (בראשית טו יג) כי גר יהיה זרעך, ושלשים שנה היו משנגזרה גזרת בין הבתרים עד שנלד יצחק. ואי אפשר לומר בארץ מצרים לבדה, שהרי קהת מן הבאים עם יעקב היה צא וחשוב כל שנותיו וכל שנות עמרם בנו ושמונים של משה, לא תמצאם כל כך, ועל כרחך הרבה שנים היו לקהת עד שלא ירד למצרים, והרבה משנות עמרם נבלעים בשנות קהת והרבה משמונים של משה נבלעים בשנות עמרם, הרי שלא תמצא ארבע מאות לביאת מצרים, והזקקת לומר על כרחך, שאף שאר הישיבות נקראו גרות, אפלו בחברון, שנאמר (בראשית לה כז) אשר גר שם אברהם ויצחק, ואומר (שמות ו ד) את ארץ מגוריהם אשר גרו בה, לפיכך אתה צריך לומר כי גר יהיה זרעך משהיה לו זרע. וכשתמנה ארבע מאות שנה משנלד יצחק, תמצא מביאתן למצרים עד יציאתן מאתים ועשר שנה, וזה אחד מן הדברים ששנו לתלמי המלך:
@325 **ויהי מקץ שלשים שנה** וגו' **ויהי בעצם היום הזה.** מגיד שכיון שהגיע הקץ לא עכבן המקום כהרף עין, בחמשה עשר בניסן באו מלאכי השרת אצל אברהם לבשרו, בחמשה עשר בניסן נלד יצחק, ובחמשה עשר בניסן נגזרה גזרת בין הבתרים:
@326 **ליל שמרים.** שהיה הקב''ה שומר ומצפה לו לקים הבטחתו להוציאם מארץ מצרים: **הוא הלילה הזה לה'.** הוא הלילה שאמר לאברהם בלילה הזה אני גואל את בניך: **שמרים לכל בני ישראל לדרתם.** משמר ובא מן המזיקין, כענין שנאמר (פסוק כג) ולא יתן המשחית וגו' :
@327 **זאת חקת הפסח.** בארבעה עשר בניסן נאמרה להם פרשה זו: **כל בן נכר.** שנתנכרו מעשיו לאביו שבשמים. ואחד נכרי ואחד ישראל משמד במשמע:
@328 **ומלתה אתו אז יאכל בו.** רבו, מגיד שמילת עבדיו מעכבתו מלאכול בפסח, דברי רבי יהושע. רבי אלעזר אומר אין מילת עבדיו מעכבתו מלאכול בפסח, אם כן מה תלמוד לומר אז יאכל בו, העבד:
@329 **תושב.** זה גר תושב: **ושכיר.** זה הנכרי. ומה תלמוד לומר, והלא ערלים הם, ונאמר (פסוק מח) וכל ערל לא יאכל בו, אלא כגון ערבי מהול וגבעוני מהול והוא תושב או שכיר:
@330 **בבית אחד יאכל.** בחבורה אחת, שלא יעשו הנמנין עליו שתי חבורות ויחלקוהו. אתה אומר בחבורה אחת, או אינו אלא בבית אחד כמשמעו, וללמד שאם התחילו והיו אוכלים בחצר וירדו גשמים שלא יכנסו לבית, תלמוד לומר (פסוק ז) על הבתים אשר יאכלו אותו בהם, מכאן שהאוכל אוכל בשני מקומות: **לא תוציא מן הבית.** מן החבורה: **ועצם לא תשברו בו.** הראוי לאכילה, כגון שיש עליו כזית בשר יש בו משום שבירת עצם, אין עליו כזית בשר אין בו משום שבירת עצם:
@331 **כל עדת ישראל יעשו אתו.** למה נאמר, לפי שהוא אומר בפסח מצרים (פסוק ג) שה לבית אבות, שנמנו עליו למשפחות, יכול אף פסח דורות כן, תלמוד לומר כל עדת ישראל יעשו אותו:
@332 **ועשה פסח.** יכול כל המתגיר יעשה פסח מיד, תלמוד לומר והיה כאזרח הארץ, מה אזרח בארבעה עשר אף גר בארבעה עשר: **וכל ערל לא יאכל בו.** להביא את שמתו אחיו מחמת מילה שאינו משמד לערלות ואינו נלמד מבן נכר לא יאכל בו (פסוק מג) :
@333 **תורה אחת** וגו' **.** להשוות גר לאזרח אף לשאר מצות שבתורה:
@337 **פטר כל רחם.** שפתח את הרחם תחלה, כמו (משלי יז יד) פוטר מים ראשית מדון, וכן (תהלים כב ח) יפטירו בשפה, יפתחו שפתים: **לי הוא.** לעצמי קניתים על ידי שהכיתי בכורי מצרים:
@338 **זכור את היום הזה.** למד שמזכירין יציאת מצרים בכל יום:
@339 **בחדש האביב.** וכי לא היו יודעין באיזה חדש, אלא כך אמר להם, ראו חסד שגמלכם שהוציא אתכם בחדש שהוא כשר לצאת, לא חמה ולא צנה ולא גשמים. וכן הוא אומר (תהלים סח ז) מוציא אסירים בכושרות, חדש שהוא כשר לצאת:
@340 **אל ארץ הכנעני** וגו' **.** אף על פי שלא מנה אלא חמשה עממין, כל שבעה גוים במשמע, שכלן בכלל כנעני הם, ואחת ממשפחות כנען היתה שלא נקרא לה שם אלא כנעני: **נשבע לאבתיך** וגו' **.** באברהם הוא אומר (בראשית טו יח) ביום ההוא כרת ה' את אברם וגו' , וביצחק הוא אומר (שם כו ג) גור בארץ הזאת וגו' , וביעקב הוא אומר (שם כח יג) הארץ אשר אתה שוכב עליה וגו' : **זבת חלב ודבש.** החלב זב מן העזים והדבש זב מן התמרים ומן התאנים: **את העבדה הזאת.** של פסח. והלא כבר נאמר למעלה (יב כה) והיה כי תבאו אל הארץ וגו' , ולמה חזר ושנאה, בשביל דבר שנתחדש בה. בפרשה ראשונה נאמר (שם כו) והיה כי יאמרו אליכם בניכם מה העבודה הזאת לכם, בבן רשע הכתוב מדבר שהוציא את עצמו מן הכלל, וכאן (פסוק ח) והגדת לבנך, בבן שאינו יודע לשאל, והכתוב מלמדך שתפתח לו אתה בדברי אגדה המושכין את הלב:
@343 **בעבור זה.** בעבור שאקים מצותיו, כגון פסח מצה ומרור הללו: **עשה ה' לי.** רמז תשובה לבן רשע לומר, עשה ה' לי ולא לך, שאלו היית שם לא היית כדאי לגאל:
@344 **והיה לך לאות.** יציאת מצרים תהיה לך לאות: **על ידך ולזכרון בין עיניך.** שתכתוב פרשיות הללו ותקשרם בראש ובזרוע: **על ידך.** יד שמאל, לפיכך ידכה מלא בפרשה שניה (פסוק טז) לדרוש בה, יד שהיא כהה:
@345 **מימים ימימה.** משנה לשנה:
@346 **והיה כי יבאך.** יש מרבותינו שלמדו מכאן שלא קדשו בכורות הנלדים במדבר, והאומר שקדשו מפרש ביאה זו לומר אם תקימוהו במדבר תזכו לכנס לארץ ותקימוהו שם: **נשבע לך.** והיכן נשבע לך, (שמות ו ח) והבאתי אתכם אל הארץ אשר נשאתי וגו' : **ונתנה לך.** תהא בעיניך כאלו נתנה לך בו ביום, ואל תהי בעיניך כירשת אבות:
@347 **והעברת.** אין והעברת אלא לשון הפרשה, וכן הוא אומר (במדבר כז ח) והעברתם את נחלתו לבתו: **שגר בהמה.** נפל ששגרתו אמו ושלחתו בלא עתו, ולמדך הכתוב שהוא קדוש בבכורה לפטור את הבא אחריו. ואף שאינו נפל קרוי שגר, כמו (דברים ז יג) שגר אלפיך. אבל זה לא בא אלא ללמד על הנפל שהרי כבר כתיב כל פטר רחם. ואם תאמר אף בכור בהמה טמאה במשמע בא ופרש במקום אחר (דברים טו יט) בבקרך ובצאנך. לשון אחר יש לפרש והעברת כל פטר רחם, בבכור אדם הכתוב מדבר:
@348 **פטר חמר.** ולא פטר שאר בהמה טמאה, וגזרת הכתוב היא לפי שנמשלו בכורי מצרים לחמורים. ועוד, שסיעו את ישראל ביציאתן ממצרים, שאין לך אחד מישראל שלא נטל הרבה חמורים טעונים מכספם ומזהבם של מצרים: **תפדה בשה.** נותן שה לכהן ופטר חמור מתר בהנאה והשה חלין ביד כהן: **וערפתו.** עורפו בקופיץ מאחוריו והורגו. הוא הפסיד ממונו של כהן, לפיכך יפסיד ממונו: **וכל בכור אדם בבניך תפדה.** חמש סלעים פדיונו קצוב במקום אחר:
@349 **כי ישאלך בנך מחר.** יש מחר שהוא עכשיו, ויש מחר שהוא לאחר זמן, כגון זה וכגון (יהושע כב כד) מחר יאמרו בניכם לבנינו, דבני גד ובני ראובן: **מה זאת.** זה תינוק טפש שאינו יודע להעמיק שאלתו וסותם ושואל מה זאת, ובמקום אחר הוא אומר (דברים ו כ) מה העדות והחקים והמשפטים וגו' , הרי זאת שאלת בן חכם. דברה תורה כנגד ארבעה בנים, רשע ושאינו יודע לשאל והשואל דרך סתומה והשואל דרך חכמה:
@351 **ולטוטפת.** תפלין, ועל שם שהם ארבעה בתים קרויין טטפת, טט בכתפי שתים, פת באפריקי שתים. ומנחם חברו עם (יחזקאל כא ב) והטף אל דרום, (מיכה ב ו) אל תטיפו, לשון דבור, כמו (לעיל פסוק ט) ולזכרון, שהרואה אותם קשורים בין העינים יזכור הנס וידבר בו:
@352 **ויהי בשלח פרעה** וגו' **ולא נחם.** ולא נהגם, כמו (שמות לב לד) לך נחה את העם, (משלי ו כב) בהתהלכך תנחה אותך: **כי קרוב הוא.** ונוח לשוב באותו הדרך למצרים. ומדרשי אגדה יש הרבה: **בראתם מלחמה.** כגון מלחמת (במדבר יד מה) וירד העמלקי והכנעני וגו' . אם הלכו דרך ישר היו חוזרים, ומה אם כשהקיפם דרך מעקם אמרו (במדבר יד ד) נתנה ראש ונשובה מצרימה, אם הוליכם בפשוטה על אחת כמה וכמה: **פן ינחם.** יחשבו מחשבה על שיצאו ויתנו לב לשוב:
@353 **ויסב.** הסבם מן הדרך הפשוטה לדרך העקומה: **ים סוף.** כמו לים סוף. וסוף הוא לשון אגם שגדלים בו קנים, כמו (שמות ב ג) ותשם בסוף, (ישעיה יט ו) קנה וסוף קמלו: **וחמשים.** אין חמושים אלא מזינים. לפי שהסבן במדבר גרם להם שעלו חמושים, שאלו הסיבן דרך ישוב לא היו מחמשים להם כל מה שצריכין, אלא כאדם שעובר ממקום למקום ובדעתו לקנות שם מה שיצטרך, אבל כשהוא פורש למדבר צריך לזמן לו כל הצרך, ומקרא זה לא נכתב כי אם לשבר את האזן, שלא תתמה במלחמת עמלק ובמלחמות סיחון ועוג ומדין, מהיכן היו להם כלי זין שהכום ישראל בחרב. וכן הוא אומר (יהושע א יד) ואתם תעברו חמשים. וכן תרגם אנקלוס מזרזין, כמו וירק את חניכיו (בראשית יד יד) וזריז. דבר אחר חמושים אחד מחמשה יצאו, וארבעה חלקים מתו בשלשת ימי אפלה:
@354 **השבע השביע.** השביעם שישביעו לבניהם. ולמה לא השביע את בניו שישאוהו לארץ כנען מיד, כמו שהשביעו יעקב, אמר יוסף אני שליט הייתי במצרים והיה ספק בידי לעשות, אבל בני לא יניחום מצרים לעשות, לכך השביעם לכשיגאלו ויצאו משם שישאוהו: **והעליתם את עצמתי מזה אתכם.** לאחיו השביע כן, למדנו שאף עצמות כל השבטים העלו עמהם, שנאמר אתכם:
@355 **ויסעו מסכת.** ביום השני, שהרי בראשון באו מרעמסס לסכות:
@356 **לנחתם הדרך.** נקוד פת''ח, שהוא כמו להנחותם, כמו (דברים א לג) לראותכם בדרך אשר תלכו בה, שהוא כמו להראותכם, אף כאן להנחותם על ידי שליח. ומי הוא השליח עמוד הענן, והקדוש ברוך הוא בכבודו מוליכו לפניהם. ומכל מקום את עמוד הענן הכין להנחותם על ידו, שהרי על ידי עמוד הענן הם הולכים, ועמוד הענן אינו לאורה אלא להורותם הדרך:
@357 **לא ימיש.** הקדוש ברוך הוא את עמוד הענן יומם ועמוד האש לילה. מגיד שעמוד הענן משלים לעמוד האש ועמוד האש משלים לעמוד הענן, שעד שלא ישקע זה עולה זה:
@359 **וישבו.** לאחוריהם לצד מצרים היו מקרבין כל יום השלישי כדי להטעות את פרעה שיאמר תועים הם בדרך, כמו שנאמר (פסוק ג) ואמר פרעה לבני ישראל וגו' : **ויחנו לפני פי החירת.** הוא פיתום, ועכשיו נקרא פי החירות על שם שנעשו בני חורין, והם שני סלעים גבוהים וזקופים, והגיא שביניהם קרוי פי הסלעים: **לפני בעל צפן.** הוא נשאר מכל אלהי מצרים, כדי להטעותן, שיאמרו קשה יראתן. ועליו פרש איוב (איוב יב כג) משגיא לגוים ויאבדם:
@360 **ואמר פרעה.** כשישמע שהם שבים לאחוריהם: **לבני ישראל.** על בני ישראל. וכן (פסוק יד) ה' ילחם לכם. עליכם, (בראשית כ יג) אמרי לי אחי הוא. אמרי עלי: **נבכים הם.** כלואים ומשקעים ובלעז שירי''ץ , כמו (תהלים פד ז) בעמק הבכא, (איוב כח יא) מבכי נהרות, (שם לח טז) נבכי ים. נבכים הם כלואים הם במדבר, שאינן יודעין לצאת ממנו ולהיכן ילכו:
@361 **ואכבדה בפרעה.** כשהקדוש ברוך הוא מתנקם ברשעים שמו מתגדל ומתכבד. וכן הוא אומר (יחזקאל לח כב) ונשפטתי אתו וגו' , ואחר כך (שם כג) והתגדלתי והתקדשתי ונודעתי וגו' , ואומר (תהלים עו ד) שמה שבר רשפי קשת, ואחר כך (שם פסוק ב) נודע ביהודה אלהים, ואומר (שם ט יז) נודע ה' משפט עשה: **בפרעה ובכל חילו.** הוא התחיל בעברה וממנו התחילה הפרענות: **ויעשו כן.** להגיד שבחן ששמעו לקול משה, ולא אמרו היאך נתקרב אל רודפינו, אנו צריכים לברוח, אלא אמרו אין לנו אלא דברי בן עמרם:
@362 **ויגד למלך מצרים.** איקטורין שלח עמהם, וכיון שהגיעו לשלשת ימים שקבעו לילך ולשוב וראו שאינן חוזרין למצרים, באו והגידו לפרעה ביום הרביעי. בחמישי ובששי רדפו אחריהם, וליל שביעי ירדו לים, בשחרית אמרו שירה, והוא יום שביעי של פסח, לכן אנו קורין השירה ביום השביעי: **ויהפך.** נהפך ממה שהיה, שהרי אמר להם (שמות יב לא) קומו צאו מתוך עמי, ונהפך לבב עבדיו, שהרי לשעבר היו אומרים לו (שם י ז) עד מתי יהיה זה לנו למוקש, ועכשיו נהפכו לרדוף אחריהם בשביל ממונם שהשאילום: **מעבדנו.** מעבוד אותנו:
@363 **ויאסר את רכבו.** הוא בעצמו: **ואת עמו לקח עמו.** משכם בדברים לקינו ונטלו ממוננו ושלחנום, בואו עמי ואני לא אתנהג עמכם כשאר מלכים, דרך שאר מלכים עבדיו קודמין לו במלחמה, ואני אקדים לפניכם, שנאמר (פסוק י) ופרעה הקריב, הקריב עצמו ומהר לפני חילותיו. דרך שאר מלכים לטול בזה בראש כמו שיבחר, אני אשוה עמכם בחלק, שנאמר (שמות טו ט) אחלק שלל:
@364 **בחור.** נבחרים, בחור לשון יחיד כל רכב ורכב שבמנין זה היה בחור: **וכל רכב מצרים.** ועמהם כל שאר הרכב ומהיכן היו הבהמות הללו, אם תאמר משל מצרים, הרי נאמר (שמות ט ו) וימת כל מקנה מצרים, ואם תאמר משל ישראל, והלא נאמר (שם י כו) וגם מקננו ילך עמנו. משל מי היו, מן הירא את דבר ה' (שם ט כ) . מכאן היה רבי שמעון אומר כשר שבמצרים הרוג, טוב שבנחשים רצוץ את מוחו: **ושלשם על כלו.** שרי צבאות כתרגומו:
@365 **ויחזק ה' את לב פרעה.** שהיה תולה אם לרדוף אם לאו. וחזק את לבו לרדוף: **ביד רמה.** גבורה גבוהה ומפרסמת:
@367 **ופרעה הקריב.** היה לו לכתוב ופרעה קרב, מהו הקריב, הקריב עצמו ונתאמץ לקדם לפניהם, כמו שהתנה עמהם: **נסע אחריהם.** בלב אחד כאיש אחד. דבר אחר והנה מצרים נוסע אחריהם, ראו שר של מצרים נוסע מן השמים לעזור למצרים. תנחומא: **ויצעקו.** תפשו אמנות אבותם. באברהם הוא אומר (בראשית יט כז) אל המקום אשר עמד שם, ביצחק (שם כד סג) לשוח בשדה, ביעקב (שם כח יא) ויפגע במקום:
@368 **המבלי אין קברים.** וכי מחמת חסרון קברים שאין קברים במצרים לקבר שם לקחתנו משם. ש''י פו''ר פיילנצ''א ד''י נו''ן פושי''ש בלעז :
@369 **אשר דברנו אליך במצרים.** והיכן דברו, (שמות ה כא) ירא ה' עליכם וישפוט: **ממתנו.** מאשר נמות, ואם היה נקוד מלאפו''ם היה נבאר ממיתתנו, עכשיו שנקוד בשור''ק נבאר מאשר נמות, וכן (להלן טז ג) מי יתן מותנו. שנמות, וכן (שמואל ב' יט א) מי יתן מותי, דאבשלום. שאמות, כמו (צפניה ג ח) ליום קומי לעד, (דברי הימים ב' יח כו) עד שובי בשלום, שאקום שאשוב:
@370 **כי אשר ראיתם את מצרים** וגו' **.** מה שראיתם אותם אינו אלא היום, היום הוא שראיתם אותם ולא תוסיפו עוד:
@371 **ה' ילחם לכם.** בשבילכם. וכן (פסוק כה) כי ה' נלחם להם, וכן (איוב יג ח) אם לאל תריבון, וכן (בראשית כד ז) ואשר דבר לי וכן (שופטים ו לא) האתם תריבון לבעל:
@372 **מה תצעק אלי.** למדנו שהיה משה עומד ומתפלל, אמר לו הקדוש ברוך הוא לא עת עתה להאריך בתפלה שישראל נתונין בצרה. דבר אחר מה תצעק אלי עלי הדבר תלוי ולא עליך, כמו שנאמר להלן (ישעיה מה יא) על בני ועל פעל ידי תצוני: **דבר אל בני ישראל ויסעו.** אין להם אלא לסע שאין הים עומד בפניהם, כדאי זכות אבותיהם והם והאמונה שהאמינו בי ויצאו, לקרוע להם הים:
@376 **וילך מאחריהם.** להבדיל בין מחנה מצרים ובין מחנה ישראל, ולקבל חצים ובליסטראות של מצרים. בכל מקום הוא אומר מלאך ה', וכאן מלאך האלהים, אין אלהים בכל מקום אלא דין, מלמד שהיו ישראל נתונין בדין באותה שעה אם להנצל אם להאבד עם מצרים: **ויסע עמוד הענן.** כשחשכה והשלים עמוד הענן את המחנה לעמוד האש, לא נסתלק הענן כמו שהיה רגיל להסתלק ערבית לגמרי, אלא נסע והלך לו מאחריהם להחשיך למצרים:
@377 **ויבא בין מחנה מצרים.** משל למהלך בדרך ובנו מהלך לפניו. באו לסטים לשבותו, נטלו מלפניו ונתנו לאחריו, באו זאבים מאחריו, נתנו לפניו, באו לסטים לפניו וזאבים מאחריו, נתנו על זרועו ונלחם בהם, כך (הושע יא ג) ואנכי תרגלתי לאפרים קחם על זרועותיו: **ויהי הענן והחשך.** למצרים: **ויאר.** עמוד האש את הלילה לישראל, והולך לפניהם כדרכו ללכת כל הלילה, והחשך של ערפל לצד מצרים: **ולא קרב זה אל זה.** מחנה אל מחנה:
@378 **ברוח קדים עזה.** ברוח קדים שהיא עזה שברוחות, היא הרוח שהקדוש ברוך הוא נפרע בה מן הרשעים, שנאמר (ירמיה יח יז) ברוח קדים אפיצם, (הושע יג טו) יבא קדים רוח ה', (יחזקאל כז כו) רוח הקדים שברך בלב ימים, (ישעיה כז ח) הגה ברוחו הקשה ביום קדים: **ויבקעו המים.** כל מים שבעולם:
@380 **כל סוס פרעה.** וכי סוס אחד היה אלא מגיד שאין כלם חשובין לפני המקום אלא כסוס אחד:
@381 **באשמרת הבקר.** שלשת חלקי הלילה קרויין אשמורות, ואותה שלפני הבקר קורא אשמורת הבקר. ואומר אני לפי שהלילה חלוק למשמרות שיר של מלאכי השרת, כת אחר כת לשלשה חלקים, לכך קרוי אשמורת, וזהו שתרגם אנקלוס במטרת: **וישקף.** ויבט, כלומר פנה אליהם להשחיתם, ותרגומו ואסתכי, אף הוא לשון הבטה, כמו (במדבר כג יד) שדה צופים. חקל סכותא: **בעמוד אש וענן.** עמוד ענן יורד ועושה אותו כטיט ועמוד אש מרתיחו, וטלפי סוסיהם משתמטות: **ויהם.** לשון מהומה, אישטורדישו''ן בלעז ערבבם, נטל סגניות שלהם. ושנינו בפרקי רבי אליעזר בנו של רבי יוסי הגלילי כל מקום שנאמר בו מהומה, הרעמת קול הוא, וזה אב לכלן (שמואל א' ז י) וירעם ה' בקול גדול וגו' על פלשתים ויהמם:
@382 **ויסר את אפן מרכבתיו.** מכח האש נשרפו הגלגלים והמרכבות נגררות, והיושבים בהם נעים ואיבריהן מתפרקין: **וינהגהו בכבדת.** בהנהגה שהיא כבדה וקשה להם, במדה שמדדו (שמות ט לד) ויכבד לבו הוא ועבדיו, אף כאן וינהגהו בכבדות: **נלחם להם במצרים.** במצרים. דבר אחר במצרים, בארץ מצרים, שכשם שאלו לוקים על הים, כך לוקים אותם שנשארו במצרים:
@383 **וישבו המים.** שזקופים ועומדים כחומה, ישובו למקומם ויכסו על מצרים:
@384 **לפנות בקר.** לעת שהבקר פונה לבא: **לאיתנו.** לתקפו הראשון: **נסים לקראתו.** שהיו מהממים ומטרפים ורצין לקראת המים: **וינער ה'.** כאדם שמנער את הקדרה והופך העליון למטה והתחתון למעלה, כך היו עולין ויורדין ומשתברין בים, ונתן הקדוש ברוך הוא בהם חיות לקבל היסורין: **וינער.** ושניק, והוא לשון טרוף בלשון ארמי והרבה יש במדרשי אגדה:
@385 **ויכסו את הרכב** וגו' **לכל חיל פרעה.** כך דרך המקראות לכתוב למ''ד יתרה, כמו (להלן כג) לכל כליו תעשה נחשת, וכן (שם יט) לכל כלי המשכן בכל עבודתו, (במדבר ד לב) ויתדותם ומיתריהם לכל כליהם, ואינה אלא תקון לשון:
@387 **וירא ישראל את מצרים מת.** שפלטן הים על שפתו, כדי שלא יאמרו ישראל כשם שאנו עולים מצד זה כך הם עולין מצד אחר רחוק ממנו וירדפו אחרינו:
@388 **את היד הגדלה.** את הגבורה הגדולה שעשתה ידו של הקדוש ברוך הוא. והרבה לשונות נופלין על לשון יד, וכלן לשון יד ממש הן, והמפרשו יתקן הלשון אחר ענין הדבור:
@389 **אז ישיר משה.** אז כשראה הנס עלה בלבו שישיר שירה, וכן (יהושע י יב) אז ידבר יהושע, וכן (מלכים א' ז ח) ובית יעשה לבת פרעה, חשב בלבו שיעשה לה, אף כאן ישיר, אמר לו לבו שישיר, וכן עשה, ויאמרו לאמר אשירה לה'. וכן ביהושע, כשראה הנס אמר לו לבו שידבר וכן עשה (יהושע י יב) ויאמר לעיני ישראל, וכן שירת הבאר שפתח בה (במדבר כא יז) אז ישיר ישראל, פרש אחריו עלי באר ענו לה. (מלכים יא ז) אז יבנה שלמה במה, פרשו בו חכמי ישראל שבקש לבנות ולא בנה. למדנו שהיו''ד על שם המחשבה נאמרה, זהו לישב פשוטו. אבל מדרשו אמרו רבותינו זכרונם לברכה, מכאן רמז לתחית המתים מן התורה, וכן בכלן חוץ משל שלמה, שפרשוהו, בקש לבנות ולא בנה. ואין לומר ולישב הלשון הזה כשאר דברים הנכתבים בלשון עתיד והן מיד, כגון (איוב א ה) ככה יעשה איוב, (במדבר ט כג) על פי ה' יחנו, (שם כ) ויש אשר יהיה הענן, לפי שהן דבר ההוה תמיד, ונופל בו בין לשון עתיד בין לשון עבר, אבל זה שלא היה אלא לשעה אינו יכול לישבו בלשון הזה: **כי גאה גאה.** שנתגאה על כל גאה כתרגומו. דבר אחר בא הכפל לומר שעשה דבר שאי אפשר לבשר ודם לעשות, כשהוא נלחם בחבירו ומתגבר עליו מפילו מן הסוס וכאן סוס ורוכבו רמה בים וכל שאי אפשר לעשות על ידי זולתו נופל בו לשון גאות, כמו (ישעיה יב ה) כי גאות עשה, וכן כל השירה תמצא כפולה (פסוק ב) עזי וזמרת יה ויהי לי לישועה (פסוק ג) ה' איש מלחמה ה' שמו, וכן כלם. דבר אחר כי גאה גאה על כל השירות, וכל מה שאקלס בו עוד יש בו תוספת, ולא כמדת מלך בשר ודם שמקלסין אותו ואין בו: **סוס ורכבו.** שניהם קשורין זה בזה והמים מעלין אותם לרום ומורידין אותם לעמק ואינן נפרדין: **רמה.** השליך וכן (דניאל ג ו) יתרמא לגוא אתון נורא. ומדרש אגדה כתוב אחד אומר רמה, וכתוב אחד אומר (פסוק ד) ירה, מלמד שהיו עולין לרום ויורדין לתהום, כמו (איוב לח ו) מי ירה אבן פנתה, מלמעלה למטה:
@390 **עזי וזמרת יה.** אונקלוס תרגם תוקפי ותושבחתי. עזי כמו עזי בשור''ק, וזמרת כמו וזמרתי. ואני תמה על לשון המקרא שאין לך כמוהו בנקדתו במקרא אלא בשלשה מקומות שהוא סמוך אצל וזמרת, וכל שאר מקומות נקוד שור''ק, (ירמיה טז יט) ה' עזי ומעזי, (תהלים נט י) עזו אליך אשמרה. וכן כל תבה בת שתי אותיות הנקודה מלאפו''ם כשהיא מארכת באות שלישית ואין השניה בשו''א בחטף, הראשונה נקודה בשור''ק כגון עז עזי, רק רקי, חק חקי, על עלו, יסור עלו (ישעיה י כז) , כל כלו ושלישים על כלו (לעיל יד ז) . ואלו שלושה עזי וזמרת של כאן, ושל ישעיה (ישעיה יב ב) ושל תהלים (תהלים קיח יד) נקודים בחטף קמ''ץ, ועוד אין באחד מהם כתוב וזמרתי אלא וזמרת, וכלם סמוך להם ויהי לי לישועה, לכך אני אומר לישב לשון המקרא, שאין עזי כמו עזי, ולא וזמרת כמו וזמרתי, אלא עזי שם דבר הוא, כמו (שם קכג א) היושבי בשמים, (עובדיה א ג) שוכני בחגוי סלע, (דברים לג טז) שוכני סנה. וזהו השבח עזי וזמרת יה הוא היה לי לישועה, וזמרת דבוק הוא לתיבת ה', כמו (שופטים ה כג) לעזרת ה', (ישעיה ט יח) בעברת ה', (קהלת ג יח) על דברת בני האדם. ולשון וזמרת לשון (ויקרא כה ד) לא תזמר, (ישעיה כה ה) זמיר עריצים, לשון כסוח וכריתה. עזו ונקמתו של אלהינו היה לנו לישועה. ואל תתמה על לשון ויהי שלא נאמר היה, שיש לנו כמה מקראות מדברים בלשון זה, וזה דגמתו (מלכים א ו ה) את קירות הבית סביב להיכל ולדביר ויעש צלעות סביב, היה לו לומר עשה צלעות סביב, וכן בדברי הימים (דברי הימים ב' י יז) ובני ישראל היושבים בערי יהודה וימלך עליהם רחבעם, היה לו לומר מלך עליהם רחבעם, (במד' יד טז) מבלתי יכולת ה' וגו' וישחטם, היה לו לומר שחטם, (שם לו. לז) והאנשים אשר שלח משה וגו' וימתו, מתו היה לו לומר, (שמות ט כא) ואשר לא שם לבו אל דבר ה' ויעזב, היה לו לומר עזב: **זה אלי.** בכבודו נגלה עליהם והיו מראין אותו באצבע, ראתה שפחה על הים מה שלא ראו נביאים: **ואנוהו.** אנקלוס תרגם לשון נוה, (ישעיה לג כ) נוה שאנן, (שם סה י) לנוה צאן. דבר אחר ואנוהו לשון נוי, אספר נויו ושבחו לבאי עולם, כגון (שיר השירים ה ט. י) מה דודך מדוד דודי צח ואדום, וכל הענין: **אלהי אבי.** הוא זה **וארוממנהו.** אלהי אבי, לא אני תחלת הקדשה, אלא מחזקת ועומדת לי הקדשה ואלהותו עלי מימי אבותי:
@391 **ה' איש מלחמה.** בעל מלחמות, כמו (רות א ג) איש נעמי, וכל איש ואישך מתרגמין בעל, וכן (מלכים א' ב ב) וחזקת והיית לאיש. לגבור: **ה' שמו.** מלחמותיו לא בכלי זין, אלא בשמו הוא נלחם, כמו שאמר דוד (שמואל א' יז מה) ואנכי בא אליך בשם ה' צבאות. דבר אחר ה' שמו אף בשעה שהוא נלחם ונוקם מאויביו, אוחז הוא במדתו לרחם על ברואיו ולזון את כל באי עולם, ולא כמדת מלכי אדמה כשהוא עוסק במלחמה פונה עצמו מכל עסקיו, ואין בו כח לעשות זו וזו:
@392 **ירה בים.** שדי בימא. שדי לשון יריה, וכן הוא אומר (שמות יט יג) או ירה יירה או אשתדאה ישתדי, והתי''ו משמשת באלו במקום יתפעל: **ומבחר.** שם דבר, כמו (ויקרא טו ט) מרכב, (שם ד) משכב, (שמות יב טז) מקרא קדש: **טבעו.** אין טביעה אלא במקום טיט, כמו (תהלים סט ג) טבעתי ביון מצולה, (ירמיה לח ו) ויטבע ירמיהו בטיט, מלמד שנעשה הים טיט לגמול להם כמדתם, ששעבדו את ישראל בחומר ובלבנים:
@393 **יכסימו.** כמו יכסום, והיו''ד האמצעית יתרה בו, ודרך המקראות בכך, כמו (דברים ח יג) ובקרך וצאנך ירבין, (תהלים לו ט) ירוין מדשן ביתך, והיו''ד ראשונה שמשמעה לשון עתיד כך פרשהו, טבעו בים סוף כדי שיחזרו המים ויכסו אותן. יכסימו אין דומה לו במקרא בנקדתו, ודרכו להיות נקוד יכסימו במלאפו''ם: **כמו אבן.** ובמקום אחר (פסוק י) צללו כעופרת, ובמקום אחר (פסוק ז) יאכלמו כקש, הרשעים כקש הולכים ומטרפין עולין ויורדין, בינונים כאבן, והכשרים כעופרת, שנחו מיד:
@394 **ימינך ימינך.** שתי פעמים, כשישראל עושין את רצונו של מקום השמאל נעשית ימין: **ימינך ה' נאדרי בכח.** להציל את ישראל וימינך השנית תרעץ אויב. ולי נראה אותה ימין עצמה תרעץ אויב, מה שאי אפשר לאדם לעשות שתי מלאכות ביד אחת. ופשוטו של מקרא ימינך הנאדרת בכח מה מלאכתה, ימינך היא תרעץ אויב, וכמה מקראות דגמתו (תהלים צב י) כי הנה אויביך ה' כי הנה אויביך יאבדו, (תהלים צד ג) עד מתי רשעים ה' עד מתי רשעים יעלזו, (תהלים צג ג) נשאו נהרות ה' נשאו נהרות קולם, (תהלים קטו א) לא לנו ה' לא לנו, (הושע ב כג) אענה נאם ה' אענה את השמים, (שופטים ה ג) אנכי לה' אנכי אשירה, (תהלים קכד א. ב) לולי ה' וכו' לולי ה' שהיה לנו בקום עלינו אדם, (שופטים ה יב) עורי עורי דבורה עורי עורי דברי שיר, (ישעי' כו ו) תרמסנה רגל רגלי עני, (תהלים קלו כא, כב) ונתן ארצם לנחלה וכו' נחלה לישראל: **נאדרי.** היו''ד יתרה, כמו (איכה א א) רבתי עם שרתי במדינות, (בראשית לא לט) גנבתי יום: **תרעץ אויב.** תמיד היא רועצת ומשברת האויב, ודומה לו (שופטים י ח) וירעצו וירוצצו את בני ישראל, בשופטים. דבר אחר ימינך הנאדרת בכח היא משברת ומלקה אויב:
@395 **וברב גאונך.** אם היד בלבד רועצת האויב, כשהוא מרומם ברוב גאונו, אז יהרס קמיו, ואם ברוב גאונו לבד אויביו נהרסים, קל וחומר כששלח בם חרון אף יאכלמו: **תהרס.** תמיד אתה הורס קמיך הקמים נגדך, ומי הם הקמים כנגדו, אלו הקמים על ישראל, וכן הוא אומר (תהל' פג ג) כי הנה אויביך יהמיון, ומה היא ההמיה, (שם ב) על עמך יערימו סוד, ועל זה קורא אותם אויביו של מקום:
@396 **וברוח אפיך.** היוצא משני נחירים של אף. דבר הכתוב כביכול בשכינה דגמת מלך בשר ודם, כדי להשמיע אזן הבריות כפי ההוה שיוכלו להבין דבר. כשאדם כועס יוצא רוח מנחיריו, וכן (תהלים יח ט) עלה עשן באפו, וכן (איוב ד ט) ומרוח אפו יכלו, וזהו שאמר (ישעיה מח ט) למען שמי אאריך אפי, כשזעפו נח נשמתו ארכה, וכשהוא כועס, נשמתו קצרה, (שם) ותהלתי אחטם לך, ולמען תהלתי אשים חטם באפי לסתום נחירי בפני האף והרוח שלא יצאו, לך בשבילך. אחטם כמו נאקה בחטם במסכת שבת (דף נא ב) כך נראה בעיני. וכל אף וחרון שבמקרא אני אומר כן, (דברים ז ד) חרה אף, כמו (איוב ל ל) ועצמי חרה מני חרב, לשון שרפה ומוקד, שהנחירים מתחממים ונחרים בעת הקצף, וחרון מגזרת חרה, כמו רצון מגזרת רצה, וכן חמה לשון חמימות, על כן הוא אומר (אסתר א יב) וחמתו בערה בו, ובנוח החמה אומר נתקררה דעתו: **נערמו מים.** אנקלוס תרגם לשון ערמימות ולשון צחות המקרא, כמו (שיר השירים ז ג) ערמת חטים, ונצבו כמו נד יוכיח. נערמו מים. ממוקד רוח שיצא מאפיך יבשו המים והם נעשו כמין גלים וכריות של ערמה שהם גבוהים: **כמו נד.** כתרגומו כשור, כחומה: **נד.** לשון צבור וכנוס, כמו (ישעיה יז יא) נד קציר ביום נחלה, (תהלים לג ז) כונס כנד, לא כתיב כנאד אלא כנד, ואלו היה כנד כמו כנאד. וכונס לשון הכנסה, היה לו לכתוב מכנס כבנאד מי הים, אלא כונס לשון אוסף וצובר הוא, וכן (יהושע ג טז) קמו נד אחד, (שם יג) ויעמדו נד אחד, ואין לשון קימה ועמידה בנאדות אלא בחומות וצבורים, ולא מצינו נאד נקוד אלא במלאפו''ם, כמו (תהלים נו ט) שימה דמעתי בנאדך, (שופטים ד יט) את נאד החלב: **קפאו.** כמו (איוב י י) וכגבנה תקפיאני, שהקשו ונעשו כאבנים והמים זורקים את המצרים על האבן בכח ונלחמים בם בכל מיני קושי: **בלב ים.** בחזק הים, ודרך המקראות לדבר כן (דברים ד יא) עד לב השמים, (שמואל ב' יח יד) בלב האלה, לשון עיקרו ותקפו של דבר:
@397 **אמר אויב.** לעמו כשפיתם בדברים, ארדוף ואשיגם ואחלק שלל עם שרי ועבדי: **תמלאמו.** תתמלא מהם: **נפשי.** רוחי ורצוני. ואל תתמה על תבה המדברת בשתים. תמלאמו תמלא מהם, יש הרבה כלשון הזה (שופטים א טו) כי ארץ הנגב נתתני, כמו נתת לי. (בראשית לז ד) ולא יכלו דברו לשלום, כמו דבר עמו. (ירמיה י כ) בני יצאוני, כמו יצאו ממני. (איוב לא לז) מספר צעדי אגידנו, כמו אגיד לו, אף כאן תמלאמו. תמלא נפשי מהם: **אריק חרבי.** אשלוף, ועל שם שהוא מריק את התער בשליפתו ונשאר ריק נופל בו לשון הרקה, כמו (בראשית מב לה) מריקים שקיהם, (ירמיה מח יב) וכליו יריקו. ואם תאמר אין לשון ריקות נופל על היוצא, אלא על התיק ועל השק ועל הכלי שיצא ממנה, אבל לא על החרב ועל היין, ולדחוק ולפרש אריק חרבי, כלשון (בראשית יד יד) וירק את חניכיו. אזדיין בחרבי, מצינו הלשון מוסב אף על היוצא (שיר השירים א ג) שמן תורק, (ירמיה מח יא) ולא הורק מכלי אל כלי, לא הורק הכלי אין כתיב כאן אלא לא הורק היין מכלי אל כלי, מצינו הלשון מוסב על היין. וכן (יחזקאל כח ז) והריקו חרבותם על יפי חכמתך, דחירם: **תורישמו.** לשון רישות ודלות, כמו (שמואל א' ב ז) מוריש ומעשיר:
@398 **נשפת.** לשון הפחה, וכן (ישעיה מ כד) וגם נשף בהם: **צללו.** שקעו, עמקו, לשון (תהלים סט ג) מצולה: **כעופרת.** אבר פלו''ם בלעז :
@399 **באלם.** בחזקים, כמו (יחזקאל יז יג) ואת אילי הארץ לקח, (תהלים כב כ) אילותי לעזרתי חושה: **נורא תהלת.** יראוי מלהגיד תהלותיו פן ימעטו, כמו שכתוב (שם סה ב) לך דמיה תהלה:
@400 **נטית ימינך.** כשהקדוש ברוך הוא נוטה ידו הרשעים כלים ונופלים, לפי שהכל נתון בידו נופלים בהטיתה וכן הוא אומר (ישעיה לא ג) וה' יטה ידו וכשל עוזר ונפל עזר. משל לכלי זכוכית הנתונים בידי אדם, מטה ידו מעט והן נופלין ומשתברין: **תבלעמו ארץ.** מכאן שזכו לקבורה בשכר שאמרו (לעיל ט כז) ה' הצדיק:
@401 **נהלת.** לשון מנהל, ואונקלוס תרגם לשון נושא וסובל, ולא דקדק לפרש אחר לשון העברית:
@402 **ירגזון.** מתרגזין: **ישבי פלשת.** מפני שהרגו את בני אפרים שמהרו את הקץ ויצאו בחזקה, כמפורש בדברי הימים (דברי הימים א' ז כא) והרגום אנשי גת:
@403 **אלופי אדום אילי מואב.** והלא לא היה להם לירא כלום, שהרי לא עליהם הולכים, אלא מפני אנינות שהיו מתאוננים ומצטערים על כבודם של ישראל: **נמגו.** נמסו, כמו (תהלים סה יא) ברביבים תמגגנה. אמרו עלינו הם באים לכלותינו ולירש את ארצנו:
@404 **תפל עליהם אימתה.** על הרחוקים: **ופחד.** על הקרובים, כענין שנאמר (יהושע ב י) כי שמענו את אשר הוביש וגו' : **עד יעבר עד יעבר.** כתרגומו: **קנית.** חבבת משאר אמות, כחפץ הקנוי בדמים יקרים, שחביב על האדם:
@405 **תבאמו.** נתנבא משה שלא יכנס לארץ לכך לא נאמר תביאנו: **מכון לשבתך.** מקדש של מטה מכון כנגד כסא של מעלה אשר פעלת: **מקדש.** הטעם עליו זקף גדול להפרידו מתבת השם של אחריו המקדש אשר כוננו ידיך ה'. חביב בית המקדש שהעולם נברא ביד אחת, שנאמר (ישע' מח יג) אף ידי יסדה ארץ, ומקדש בשתי ידים. ואימתי יבנה בשתי ידים, בזמן שה' ימלך לעלם ועד, לעתיד לבא שכל המלוכה שלו:
@406 **לעלם ועד.** לשון עולמות הוא והוי''ו בו יסוד לפיכך היא פתוחה, אבל (ירמיה כט כג) ואנכי היודע ועד, שהוי''ו בו שמוש, קמוצה היא:
@407 **כי בא סוס פרעה.** כאשר בא:
@408 **ותקח מרים הנביאה.** היכן נתנבאה כשהיתה אחות אהרן, קדם שנלד משה, אמרה עתידה אמי שתלד בן וכו' , כדאיתא בסוטה (דף יג א) . דבר אחר אחות אהרן לפי שמסר נפשו עליה כשנצטרעה, נקראת על שמו: **את התף.** כלי של מיני זמר: **בתפים ובמחלת.** מבטחות היו צדקניות שבדור שהקדוש ברוך הוא עושה להם נסים והוציאו תפים ממצרים:
@409 **ותען להם מרים.** משה אמר שירה לאנשים, הוא אומר והם עונין אחריו, ומרים אמרה שירה לנשים:
@410 **ויסע משה.** הסיען בעל כרחם שעטרו מצרים סוסיהם בתכשיטי זהב וכסף ואבנים טובות, והיו ישראל מוצאין אותם בים, וגדולה היתה בזת הים מבזת מצרים, שנאמר (שיר השירים א יא) תורי זהב נעשה לך עם נקדות הכסף, לפיכך הצרך להסיען בעל כרחם:
@411 **ויבאו מרתה.** כמו למרה, ה''א בסוף תבה במקום למ''ד בתחלתה, והתי''ו היא במקום ה''א הנשרשת בתיבת מרה, ובסמיכתה כשהיא נדבקת לה''א, שהוא מוסיף במקום הלמ''ד, תהפך הה''א של שרש לתי''ו, וכן כל ה''א שהיא שרש בתבה, תתהפך לתי''ו בסמיכתה, כמו (ישעיה כז ד) חמה אין לי, (אסתר א יב) וחמתו בערה בו, הרי ה''א של שרש נהפכת לתי''ו, מפני שנסמכת אל הו''ו הנוספת, וכן (ויקרא כה מד) עבד ואמה, (בראשית ל ג) הנה אמתי בלהה, (שם ב ז) לנפש חיה, (איוב לג כ) וזהמתו חיתו לחם, (שופטים ד ה) בין הרמה, (שמואל א' ז יז) ותשובתו הרמתה:
@412 **וילנו.** לשון נפעל הוא וכן התרגום לשון נפעל הוא ואתרעמו. כן דרך לשון תלנה להסב הדבור אל האדם מתלונן מתרועם, ולא אמר, לונן, רועם, וכן יאמר הלועז דיקומפליינש''ט שי''י , מוסב הדבור אליו באמרו שי''י [עצמו] :
@413 **שם שם לו.** במרה נתן להם מקצת פרשיות של תורה שיתעסקו בהם, שבת ופרה אדמה ודינין: **ושם נסהו.** לעם, וראה קשי ערפן שלא נמלכו במשה בלשון יפה, בקש עלינו רחמים שיהיה לנו מים לשתות, אלא נתלוננו:
@414 **אם שמוע תשמע.** זו קבלה שיקבלו עליהם: **תעשה.** היא עשיה: **והאזנת.** תטה אזנים לדקדק בהם: **כל חקיו.** דברים שאינן אלא גזרת מלך בלא שום טעם, ויצר הרע מקנטר עליהם מה אסור באלו, למה נאסרו, כגון לבישת כלאים ואכילת חזיר ופרה אדמה וכיוצא בהם: **לא אשים עליך.** ואם אשים הרי היא כלא הושמה, כי אני ה' רופאך, זהו מדרשו. ולפי פשוטו כי אני ה' רופאך ומלמדך תורה ומצות למען תנצל מהם, כרופא הזה האומר לאדם אל תאכל דבר זה פן יביאך לידי חולי זה וכן הוא אומר (משלי ג ח) רפאות תהי לשרך:
@415 **שתים עשרה עינת מים.** כנגד שנים עשר שבטים נזדמנו להם: **ושבעים תמרים.** כנגד שבעים זקנים:
@416 **בחמשה עשר יום.** נתפרש היום של חניה זו, לפי שבו ביום כלתה החררה שהוציאו ממצרים והצרכו למן, למדנו שאכלו משירי הבצק [משירי המצה] ששים ואחת סעודות, וירד להם מן בששה עשר באיר ויום ראשון בשבת היה, כדאיתא במסכת שבת (דף פז ב) :
@417 **וילונו.** לפי שכלה הלחם:
@418 **מי יתן מותנו.** שנמות, ואינו שם דבר כמו מותנו אלא כמו עשותנו, חנותנו, שובנו, לעשות אנחנו, לחנות אנחנו, למות אנחנו. ותרגומו לוי דמיתנא, כמו (במדבר יד ב) לו מתנו, הלואי והיינו מתים:
@419 **דבר יום ביומו.** צורך אכילת יום ילקטו ביומו, ולא ילקטו היום לצורך מחר: **למען אנסנו הילך בתורתי.** אם ישמרו מצות התלויות בו, שלא יותירו ממנו ולא יצאו בשבת ללקוט:
@420 **והיה משנה.** ליום ולמחרת: **משנה.** על שהיו רגילים ללקוט יום יום של שאר ימות השבוע. ואומר אני אשר יביאו והיה משנה, לאחר שיביאו ימצאו משנה במדידה על אשר ילקטו וימדו יום יום וזהו (להלן פסוק כב) לקטו לחם משנה, בלקיטתו היה נמצא לחם משנה. וזהו (להלן פסוק כט) על כן הוא נותן לכם ביום הששי לחם יומים, נותן לכם ברכה פוישו''ן [שפע] בבית למלאות העמר פעמים ללחם יומים:
@421 **ערב.** כמו לערב: **וידעתם כי ה' הוציא אתכם מארץ מצרים.** לפי שאמרתם לנו כי הוצאתם אותנו, תדעו כי לא אנחנו המוציאים אלא ה' הוציא אתכם, שיגיז לכם את השליו:
@422 **ובקר וראיתם.** לא על הכבוד שנאמר (להלן פסוק י) והנה כבוד ה' נראה בענן, נאמר, אלא כך אמר להם ערב וידעתם כי היכולת בידו לתן תאותכם ובשר יתן, אך לא בפנים מאירות יתננה לכם, כי שלא כהוגן שאלתם אותו ומכרס מלאה, והלחם ששאלתם לצורך, בירידתו לבקר תראו את כבוד אור פניו שיורידהו לכם דרך חבה בבקר, שיש שהות להכינו וטל מלמעלה וטל מלמטה כמנח בקפסא: **את תלנתיכם על ה'.** כמו אשר על ה': **ונחנו מה.** מה אנחנו חשובין: **כי תלינו עלינו.** שתרעימו עלינו את הכל, את בניכם ונשיכם ובנותיכם וערב רב, ועל כרחי אני זקוק לפרש תלינו בלשון תפעילו מפני דגשותו וקריתו, שאלו היה רפה הייתי מפרשו בלשון תפעלו, כמו (שמות יז ג) וילן העם על משה, או אם היה דגוש ואין בו יו''ד ונקרא תלונו, הייתי מפרשו לשון תתלוננו, עכשיו הוא משמע תלינו את אחרים, כמו במרגלים (במדבר יד לו) וילינו עליו את כל העדה:
@423 **בשר לאכל.** ולא לשבע, למדה תורה דרך ארץ שאין אוכלין בשר לשבע. ומה ראה להוריד לחם בבקר ובשר בערב, לפי שהלחם שאלו כהוגן, שאי אפשר לו לאדם בלא לחם, אבל בשר שאלו שלא כהוגן, שהרבה בהמות היו להם. ועוד, שהיה אפשר להם בלא בשר, לפיכך נתן להם בשעת טרח, שלא כהוגן: **אשר אתם מלינם עליו.** את האחרים השומעים אתכם מתלוננים:
@424 **קרבו.** למקום שהענן ירד:
@428 **השלו.** מין עוף ושמן מאד: **היתה שכבת הטל.** הטל שוכב על המן ובמקום אחר הוא אומר (במדבר יא ט) וברדת הטל וגו' הטל יורד על הארץ והמן יורד עליו, וחוזר ויורד טל עליו והרי הוא כמנח בקפסא:
@429 **ותעל שכבת הטל** וגו' **.** כשהחמה זורחת עולה הטל שעל המן לקראת החמה, כדרך טל עולה לקראת החמה, אף אם תמלא שפופרת של ביצה טל, ותסתום את פיה ותניחה בחמה, היא עולה מאליה באויר. ורבותינו דרשו שהטל עולה מן הארץ באויר, וכעלות שכבת הטל נתגלה המן וראו והנה על פני המדבר וגו' : **דק.** דבר דק: **מחספס.** מגלה, ואין דומה לו במקרא. ויש לפרש מחספס לשון חפיסא ודלוסקמא שבלשון משנה. כשנתגלה משכבת הטל ראו שהיה דבר דק מחספס בתוכו בין שתי שכבות הטל. ואונקלוס תרגם מקלף, לשון (בראשית ל לז) מחשוף הלבן: **ככפר.** כפור ייליד''ה בלע''ז דעדק כגיר (ישעיה כז ט) כאבני גיר והוא מין צבע שחור, כדאמרינן גבי כסוי הדם (חולין פח ב) הגיר והזרניך. דעדק כגיר כגלידא על ארעא, דק היה כגיר ושוכב מגלד כקרח על הארץ. וכן פרוש דק ככפור, שטוח קלוש ומחבר כגליד. דק טינבי''ש בלעז , שהיה מגליד גלד דק מלמעלה. וכגיר שתרגם אנקלוס, תוספת הוא על לשון העברית, ואין לו תבה בפסוק:
@430 **מן הוא.** הכנת מזון הוא, כמו (דניאל א ה) וימן להם המלך: **כי לא ידעו מה הוא.** שיקראוהו בשמו:
@431 **עמר.** שם מדה: **מספר נפשתיכם.** כפי מנין נפשות שיש לאיש באהלו תקחו עמר לכל גלגלת:
@432 **המרבה והממעיט.** יש שלקטו הרבה ויש שלקטו מעט וכשבאו לביתם ומדדו בעומר, איש איש מה שלקטו, ומצאו שהמרבה ללקוט לא העדיף על עמר לגלגלת אשר באהלו, והממעיט ללקוט לא מצא חסר מעומר לגלגלת, וזהו נס גדול שנעשה בו:
@435 **ויותרו אנשים.** דתן ואבירם: **וירם תולעים.** לשון רמה: **ויבאש.** הרי זה מקרא הפוך, שתחלה הבאיש ולבסוף התליע, כענין שנאמר (פסוק כד) ולא הבאיש ורמה לא היתה בו, וכן דרך כל המתליעים:
@436 **וחם השמש ונמס.** הנשאר בשדה נמוח (י''ג: נמוח) ונעשה נחלים, ושותין ממנו אילים וצבאים, ואמות העולם צדין מהם וטועמין בהם טעם מן, ויודעין מה שבחן של ישראל. ותרגומו של נמס פשר, לשון פושרין, על ידי השמש מתחמם ומפשיר דישטיפרי''ר ודגמתו בסנהדרין [ סז ] בסוף ארבע מיתות:
@437 **לקטו לחם משנה.** כשמדדו את לקיטתם באהליהם מצאו כפלים שני העמר לאחד. ומדרש אגדה לחם משנה משנה. אותו היום נשתנה לשבח בריחו וטעמו: **ויגידו למשה.** שאלוהו מה היום מיומים, ומכאן יש ללמוד שעדין לא הגיד להם משה פרשת שבת שנצטוה לומר להם (פסוק ה) והיה ביום הששי והכינו וגו' , עד ששאלו את זאת, אמר להם (פסוק כג) הוא אשר דבר ה', שנצטויתי לומר לכם, ולכך ענשו הכתוב, שאמר לו (פסוק כח) עד אנה מאנתם, ולא הוציאו מן הכלל:
@438 **את אשר תאפו אפו.** מה שאתם רוצים לאפות בתנור, אפו היום, הכל לשני ימים, ומה שאתם צריכים לבשל ממנו במים, בשלו היום. לשון אפיה נופל בלחם, ולשון בשול בתבשיל: **למשמרת.** לגניזה:
@440 **ויאמר משה אכלהו היום כי שבת היום.** שחרית שהיו רגילים לצאת וללקוט, באו לשאול אם נצא אם לאו, אמר להם את שבידכם אכלו. לערב חזרו לפניו ושאלוהו מהו לצאת, אמר להם שבת היום. ראה אותם דואגים שמא פסק המן ולא ירד עוד, אמר להם היום לא תמצאהו. מה תלמוד לומר היום, היום לא תמצאהו אבל מחר תמצאהו:
@441 **וביום השביעי שבת.** שבת הוא, המן לא יהיה בו, ולא בא הכתוב אלא לרבות יום הכפורים וימים טובים:
@443 **עד אנה מאנתם.** משל הדיוט הוא, בהדי הוצא לקי כרבא, על ידי הרשעים מתגנין הכשרין:
@444 **ראו.** בעיניכם כי ה' בכבודו מזהיר אתכם על השבת, שהרי נס נעשה בכל ערב שבת לתת לכם לחם יומים: **שבו איש תחתיו.** מכאן סמכו חכמים ארבע אמות ליוצא חוץ לתחום: **אל יצא איש ממקמו.** אלו אלפים אמה של תחום שבת, ולא במפורש, שאין תחומין אלא מדברי סופרים, ועיקרו של מקרא על לוקטי המן נאמר:
@446 **והוא כזרע גד לבן.** עשב ששמו אליינדר''א [כוסבר] וזרע שלו עגול ואינו לבן, והמן היה לבן, ואינו נמשל לזרע גד אלא לענין העגול כזרע גד היה, והוא לבן: **כצפיחת.** בצק שמטגנין אותו בדבש וקורין לו אסקריטון בלשון משנה והוא תרגום של אנקלוס:
@447 **למשמרת.** לגניזה: **לדרתיכם.** בימי ירמיהו כשהיה ירמיהו מוכיחם, למה אין אתם עוסקים בתורה והם אומרים נניח מלאכתנו ונעסוק בתורה, מהיכן נתפרנס, הוציא להם צנצנת המן ואמר להם (ירמיה ב לא) הדור אתם ראו דבר ה', שמעו לא נאמר אלא ראו, בזה נתפרנסו אבותיכם, הרבה שלוחין יש לו למקום להכין מזון ליראיו:
@448 **צנצנת.** צלוחית של חרס, כתרגומו: **והנח אתו לפני ה'.** לפני הארון, ולא נאמר מקרא זה עד שנבנה אהל מועד, אלא שנכתב כאן בפרשת המן:
@450 **ארבעים שנה.** והלא חסר שלשים יום, שהרי בחמשה עשר באיר ירד להם המן תחלה, ובחמשה עשר בניסן פסק, שנאמר (יהושע ה יב) וישבת המן ממחרת, אלא מגיד שהעוגות שהוציאו ישראל ממצרים טעמו בהם טעם מן: **אל ארץ נושבת.** לאחר שעברו את הירדן שאותה שבעבר הירדן מישבת וטובה, שנאמר (דברים ג כה) אעברה נא ואראה את הארץ הטובה אשר בעבר הירדן, ותרגום של נושבת יתבתא, רצה לומר מישבת: **אל קצה ארץ כנען.** בתחלת הגבול, קדם שעברו את הירדן, והוא ערבות מואב. נמצאו מכחישין זה את זה, אלא בערבות מואב כשמת משה בשבעה באדר פסק המן מלירד, ונסתפקו ממן שלקטו בו ביום עד שהקריבו העמר בששה עשר בניסן, שנאמר (יהושע ה יא) ויאכלו מעבור הארץ ממחרת הפסח:
@451 **עשרית האיפה.** האיפה שלש סאין, והסאה ששה קבין והקב ארבעה לוגין והלוג שש ביצים נמצא עשירית האיפה ארבעים ושלש ביצים וחמש ביצה והוא שעור לחלה ולמנחות:
@453 **מה תנסון.** לומר היוכל לתת מים בארץ ציה:
@455 **עוד מעט.** אם אמתין עוד מעט וסקלני:
@456 **עבר לפני העם.** וראה אם יסקלוך, למה הוצאת לעז על בני: **וקח אתך מזקני ישראל.** לעדות שיראו שעל ידך המים יוצאים מן הצור, ולא יאמרו מעינות היו שם מימי קדם: **ומטך אשר הכית בו את היאר.** מה תלמוד לומר אשר הכית בו את היאור, אלא שהיו ישראל אומרים על המטה שאינו מוכן אלא לפרענות, בו לקה פרעה ומצרים כמה מכות במצרים ועל הים, לכן נאמר אשר הכית בו את היאר, יראו עתה שאף לטובה הוא מוכן:
@457 **והכית בצור.** על הצור לא נאמר אלא בצור, מכאן שהמטה היה של מין דבר חזק ושמו סנפרינון והצור נבקע מפניו:
@459 **ויבא עמלק** וגו' **.** סמך פרשה זו למקרא זה, לומר תמיד אני ביניכם ומזמן לכל צרכיכם, ואתם אומרים (פסוק ז) היש ה' בקרבנו אם אין, חייכם שהכלב בא ונושך אתכם ואתם צועקים אלי ותדעון היכן אני. משל לאדם שהרכיב בנו על כתפו ויצא לדרך, היה אותו הבן רואה חפץ ואומר, אבא טול חפץ זה ותן לי, והוא נותן לו, וכן שניה וכן שלישית, פגעו באדם אחד, אמר לו אותו הבן ראית את אבא. אמר לו אביו אינך יודע היכן אני, השליכו מעליו ובא הכלב ונשכו:
@460 **בחר לנו.** לי ולך, השוהו לו, מכאן אמרו יהי כבוד תלמידך חביב עליך כשלך וכבוד חברך כמורא רבך, מנין שנאמר (במדבר יב יא) ויאמר אהרן אל משה בי אדני והלא אהרן גדול מאחיו היה ועושה את חברו כרבו. ומורא רבך כמורא שמים מנין, שנאמר (שם יא כח) אדני משה כלאם, כלם מן העולם, חייבין הם כליה, המורדים בך, כאלו מרדו בהקדוש ברוך הוא: **וצא הלחם.** צא מן הענן והלחם בו: **מחר.** בעת המלחמה אנכי נצב: **בחר לנו אנשים.** גבורים ויראי חטא שתהא זכותן מסיעתן. דבר אחר בחר לנו אנשים שיודעין לבטל כשפים לפי שבני עמלק מכשפין היו:
@461 **ומשה אהרן וחור.** מכאן לתענית שצריכים שלשה לעבור לפני התבה, שבתענית היו שרוים: **חור.** בנה של מרים היה וכלב בעלה:
@462 **כאשר ירים משה ידו.** וכי ידיו של משה נוצחות היו המלחמה וכו' כדאיתא בראש השנה (כט א) :
@463 **וידי משה כבדים.** בשביל שנתעצל במצוה ומנה אחר תחתיו, נתיקרו ידיו: **ויקחו.** אהרן וחור: **אבן וישימו תחתיו.** ולא ישב לו על כר וכסת. אמר ישראל שרויין בצער, אף אני אהיה עמהם בצער: **ויהי ידיו אמונה.** ויהי משה ידיו באמונה פרושות השמים בתפלה נאמנה ונכונה: **עד בא השמש.** שהיו עמלקים מחשבין את השעות באצטרולוגיאה באיזו שעה הם נוצחים, והעמיד להם משה חמה וערבב את השעות:
@464 **ויחלש יהושע.** חתך ראשי גבוריו ולא השאיר אלא חלשים שבהם ולא הרגם כלם, מכאן אנו למדין שעשה על פי הדבור של שכינה:
@465 **כתב זאת זכרון.** שבא עמלק להזדוג לישראל קדם לכל האמות: **ושים באזני יהושע.** המכניס את ישראל לארץ, שיצוה את ישראל לשלם לו את גמולו, כאן נרמז לו למשה שיהושע מכניס את ישראל לארץ: **כי מחה אמחה.** לכך אני מזהירך כן, כי חפץ אני למחותו:
@466 **ויקרא שמו.** של מזבח: **ה' נסי.** הקדוש ברוך הוא עשה לנו כאן נס גדול, לא שהמזבח קרוי ה', אלא המזכיר שמו של מזבח זוכר את הנס שעשה המקום, ה' הוא נס שלנו:
@467 **ויאמר.** משה: **כי יד על כס יה.** ידו של הקדוש ברוך הוא הרמה לשבע בכסאו להיות לו מלחמה ואיבה בעמלק עולמית, ומהו כס, ולא נאמר כסא, ואף השם נחלק לחציו, נשבע הקדוש ברוך הוא שאין שמו שלם ואין כסאו שלם עד שימחה שמו של עמלק כלו, וכשימחה שמו יהיה השם שלם והכסא שלם, שנאמר (תהלים ט ז) האויב תמו חרבות לנצח, זהו עמלק שכתוב בו (עמוס א יא) ועברתו שמרה נצח, (תהלים שם) וערים נתשת אבד זכרם המה, מהו אומר אחריו (תהלים ט ח) וה' לעולם ישב, הרי השם שלם, (תהלים שם) כונן למשפט כסאו, הרי כסאו שלם:
@468 **וישמע יתרו.** מה שמועה שמע ובא, קריעת ים סוף ומלחמת עמלק: **יתרו.** שבע שמות נקראו לו רעואל, יתר, יתרו, חובב, חבר, קני, פוטיאל. יתר, על שם שיתר פרשה אחת בתורה (להלן פסוק כא) ואתה תחזה. יתרו לכשנתגיר וקים המצות הוסיפו לו אות אחת על שמו. חובב שחבב את התורה. וחובב הוא יתרו, שנאמר (שופטים ד יא) מבני חובב חותן משה. ויש אומרים רעואל אביו של יתרו היה, ומה הוא אומר (שמות ב יח) ותבאנה אל רעואל אביהן, שהתינוקות קורין לאבי אביהן אבא. בספרי: **חתן משה.** כאן היה יתרו מתכבד במשה, אני חותן המלך ולשעבר היה משה תולה הגדלה בחמיו, שנאמר (שמות ד יח) וישב אל יתר חותנו: **למשה ולישראל.** שקול משה כנגד כל ישראל: **את כל אשר עשה.** להם בירידת המן ובבאר ובעמלק: **כי הוציא ה'** וגו' **.** זו גדולה על כלם:
@469 **אחר שלוחיה.** כשאמר לו הקדוש ברוך הוא במדין (שמות ד יט) לך שוב מצרים, (שם כ) ויקח משה את אשתו ואת בניו גו' ויצא אהרן לקראתו, (שם כז) ויפגשהו בהר האלהים. אמר לו מי הם הללו. אמר לו זו היא אשתי שנשאתי במדין ואלו בני. אמר לו והיכן אתה מוליכן. אמר לו למצרים. אמר לו על הראשונים אנו מצטערים ואתה בא להוסיף עליהם. אמר לה לכי אל בית אביך, נטלה שני בניה והלכה לה:
@471 **ויצלני מחרב פרעה.** כשגלו דתן ואבירם על דבר המצרי ובקש להרג את משה, נעשה צוארו כעמוד של שיש:
@472 **אל המדבר.** אף אנו יודעין שבמדבר היו, אלא בשבחו של יתרו דבר הכתוב, שהיה יושב בכבודו של עולם ונדבו לבו לצאת אל המדבר, מקום תהו, לשמוע דברי תורה:
@473 **ויאמר אל משה.** על ידי שליח: **אני חתנך יתרו** וגו' **.** אם אין אתה יוצא בגיני צא בגין אשתך, ואם אין אתה יוצא בגין אשתך צא בגין שני בניה:
@474 **ויצא משה.** כבוד גדול נתכבד יתרו באותה שעה, כיון שיצא משה יצא אהרן נדב ואביהוא, ומי הוא שראה את אלו יוצאין ולא יצא: **וישתחו וישק לו.** איני יודע מי השתחוה למי, כשהוא אומר איש לרעהו, מי הקרוי איש, זה משה, שנאמר (במדבר יב ג) והאיש משה:
@475 **ויספר משה לחתנו.** למשוך את לבו לקרבו לתורה: **את כל התלאה.** שעל הים ושל עמלק: **התלאה.** למ''ד אל''ף מן היסוד של התבה והתי''ו הוא תקון ויסוד הנופל ממנו לפרקים, וכן תרומה, תנופה, תקומה, תנואה:
@476 **ויחד יתרו.** וישמח יתרו, זהו פשוטו ומדרשו נעשה בשרו חדודין חדודין, מצר על אבוד מצרים, הינו דאמרי אינשי גיורא עד עשרה דרי לא תבזי ארמאה באפיה: **על כל הטובה.** טובת המן והבאר והתורה. ועל כלן אשר הצילו מיד מצרים, עד עכשיו לא היה עבד יכול לברוח ממצרים, שהיתה הארץ מסגרת, ואלו יצאו ששים רבוא:
@477 **אשר הציל אתכם מיד מצרים.** אמה קשה: **ומיד פרעה.** מלך קשה: **מתחת יד מצרים.** כתרגומו לשון רדוי ומרות היד שהיו מכבידים עליהם, היא העבודה:
@478 **עתה ידעתי.** מכירו הייתי לשעבר ועכשיו ביותר: **מכל האלהים.** מלמד שהיה מכיר בכל עבודה זרה שבעולם שלא הניח עבודה זרה שלא עבדה: **כי בדבר אשר זדו עליהם.** כתרגומו במים דמו לאבדם והם נאבדו במים: **אשר זדו.** אשר הרשיעו. ורבותינו דרשוהו לשון (בראשית כה כט) ויזד יעקב נזיד, בקדרה אשר בשלו בה, נתבשלו:
@479 **עלה.** כמשמעה שהיא עולה כליל: **וזבחים.** שלמים: **ויבא אהרן** וגו' **.** ומשה היכן הלך, והלא הוא שיצא לקראתו וגרם לו את כל הכבוד, אלא שהיה עומד ומשמש לפניהם: **לפני האלהים.** מכאן שהנהנה מסעודה שתלמידי חכמים מסבין בה כאלו נהנה מזיו השכינה:
@480 **ויהי ממחרת.** מוצאי יום הכפורים היה, כך שנינו בספרי, ומהו ממחרת, למחרת רדתו מן ההר. ועל כרחך אי אפשר לומר אלא ממחרת יום הכפורים, שהרי קודם מתן תורה אי אפשר לומר (פסוק טז) והודעתי את חקי וגו' , ומשנתנה תורה עד יום הכפורים לא ישב משה לשפוט את העם, שהרי בשבעה עשר בתמוז ירד ושבר את הלוחות, ולמחר עלה בהשכמה ושהה שמונים יום וירד ביום הכפורים. ואין פרשה זו כתובה כסדר, שלא נאמר ויהי ממחרת עד שנה שניה, אף לדברי האומר יתרו קדם מתן תורה בא, שלוחו אל ארצו לא היה אלא עד שנה שניה, שהרי נאמר כאן (פסוק כז) וישלח משה את חתנו ומצינו במסע הדגלים שאמר לו משה (במדבר י כט) נוסעים אנחנו אל המקום וגו' , (שם לא) אל נא תעזוב אותנו, ואם זו קדם מתן תורה, מששלחו והלך היכן מצינו שחזר ואם תאמר שם לא נאמר יתרו אלא חובב, ובנו של יתרו היה, הוא חובב הוא יתרו, שהרי כתיב (שופטים ד יא) מבני חובב חותן משה: **וישב משה** וגו' **ויעמד העם.** יושב כמלך וכלן עומדים, והקשה הדבר ליתרו שהיה מזלזל בכבודן של ישראל והוכיחו על כך, שנאמר (פסוק יד) מדוע אתה יושב לבדך וכלם נצבים: **מן הבקר עד הערב.** אפשר לומר כן, אלא כל דין שדן דין אמת לאמתו אפלו שעה אחת, מעלה עליו הכתוב כאלו עוסק בתורה כל היום, וכאלו נעשה שותף להקדוש ברוך הוא במעשה בראשית, שנאמר בו (בראשית א ה) ויהי ערב ויהי בקר יום אחד:
@482 **כי יבא.** כמו כי בא, לשון הוה: **לדרש אלהים.** כתרגומו למתבע אלפן, לשאול תלמוד מפי הגבורה:
@483 **כי יהיה להם דבר בא.** מי שיהיה לו דבר בא אלי:
@484 **ויאמר חתן משה.** דרך כבוד קוראו הכתוב חותנו של מלך:
@485 **נבל תבל.** כתרגומו. ולשונו לשון כמישה פליישטרי''ר בלעז . כמו (ירמיה ח יג) והעלה נבל, (ישעיה לד ד) כנבול עלה מגפן וגו' , שהוא כמוש על ידי חמה ועל ידי קרח, וכחו תש ונלאה: **גם אתה.** לרבות אהרן וחור ושבעים זקנים: **כי כבד ממך.** כבדו רב יותר מכחך:
@486 **איעצך ויהי אלהים עמך.** בעצה, אמר לו צא המלך בגבורה: **היה אתה לעם מול האלהים.** שליח ומליץ בינותם למקום, ושואל משפטים מאתו: **את הדברים.** דברי ריבותם:
@488 **ואתה תחזה.** ברוח הקדש שעליך: **אנשי חיל.** עשירים, שאין צריכין להחניף ולהכיר פנים: **אנשי אמת.** אלו בעלי הבטחה, שהם כדאי לסמוך על דבריהם, שעל ידי כן יהיו דבריהם נשמעין: **שנאי בצע.** ששונאין את ממונם בדין כההיא דאמרינן כל דינא דמפקין ממונא מניה בדינא לאו דינא הוא: **שרי אלפים.** הם היו שש מאות שרים לשש מאות אלף: **שרי מאות.** ששת אלפים היו: **שרי חמשים.** שנים עשר אלף: **ושרי עשרת.** ששים אלף:
@489 **ושפטו.** וידונון, לשון צווי: **והקל מעליך.** דבר זה להקל מעליך. והקל, כמו (שמות ח יא) והכבד את לבו, (מלכים ב ג כד) והכות את מואב, לשון הוה:
@490 **וצוך אלהים ויכלת עמד.** המלך בגבורה אם יצוה אותך לעשות כך תוכל עמוד, ואם יעכב על ידך לא תוכל לעמוד: **וגם כל העם הזה.** אהרן נדב ואביהוא ושבעים זקנים הנלוים עתה עמך:
@493 **ושפטו.** ודינין ית עמא: **יביאון.** מיתן: **ישפוטו הם.** כמו ישפוטו וכן (רות ב ח) לא תעבורי, כמו לא תעברי ותרגומו דינין אנון. מקראות העליונים הם לשון צווי, לכך מתרגמין וידונון ייתון, ידונון, ומקראות הללו לשון עשיה:
@494 **וילך לו אל ארצו.** לגיר בני משפחתו:
@495 **ביום הזה.** בראש חדש. לא היה צריך לכתוב אלא ביום ההוא, מהו ביום הזה, שיהיו דברי תורה חדשים עליך כאלו היום נתנו:
@496 **ויסעו מרפידים.** למה הצרך לחזור ולפרש מהיכן נסעו, והלא כבר כתב שברפידים היו חונים, בידוע שמשם נסעו, אלא להקיש נסיעתן מרפידים לביאתן למדבר סיני, מה ביאתן למדבר סיני בתשובה, אף נסיעתן מרפידים בתשובה: **ויחן שם ישראל.** כאיש אחד בלב אחד, אבל שאר כל החניות בתרעומת ובמחלוקת: **נגד ההר.** למזרחו, וכל מקום שאתה מוצא נגד, פנים למזרח:
@497 **ומשה עלה.** ביום השני. וכל עליותיו בהשכמה היו, שנאמר (שמות לד ד) וישכם משה בבקר: **כה תאמר.** בלשון הזה וכסדר הזה: **לבית יעקב.** אלו הנשים, תאמר להן בלשון רכה: **ותגיד לבני ישראל.** ענשין ודקדוקין פרש לזכרים. דברים הקשין כגידין:
@498 **אתם ראיתם.** לא מסרת היא בידכם, ולא בדברים אני משגר לכם, לא בעדים אני מעיד עליכם, אלא אתם ראיתם אשר עשיתי למצרים, על כמה עברות היו חיבין לי קדם שנזדוגו לכם, ולא נפרעתי מהם אלא על ידכם: **ואשא אתכם.** זה יום שבאו ישראל לרעמסס, שהיו ישראל מפזרין בכל ארץ גושן, ולשעה קלה כשבאו לסע ולצאת נקבצו כלם לרעמסס. ואונקלוס תרגם ואשא, ונטלית יתכון, כמו ואסיע אתכם, תקן את הדבר דרך כבוד למעלה: **על כנפי נשרים.** כנשר הנושא גוזליו על כנפיו, שכל שאר העופות נותנים את בניהם בין רגליהם, לפי שמתיראין מעוף אחר שפורח על גביהם, אבל הנשר הזה אינו מתירא אלא מן האדם, שמא יזרוק בו חץ, לפי שאין עוף אחר פורח על גביו, לכך נותנן על כנפיו, אומר מוטב יכנס החץ בי, ולא בבני. אף אני עשיתי כן, (שמות יד יט) ויסע מלאך האלהים וגו' (שם כ) ויבא בין מחנה מצרים וגו' , והיו מצרים זורקים חצים ואבני בליסטראות והענן מקבלם: **ואבא אתכם אלי.** כתרגומו:
@499 **ועתה.** אם עתה תקבלו עליכם יערב לכם מכאן ואלך, שכל התחלות קשות: **ושמרתם את בריתי.** שאכרות עמכם על שמירת התורה: **סגלה.** אוצר חביב, כמו (קהלת ב ח) וסגלת מלכים, כלי יקר ואבנים טובות שהמלכים גונזים אותם. כך אתם תהיו לי סגלה משאר אמות, ולא תאמרו אתם לבדכם שלי ואין לי אחרים עמכם, ומה יש לי עוד שתהא חבתכם נכרת: **כי לי כל הארץ.** והם בעיני ולפני לכלום:
@500 **ואתם תהיו לי ממלכת כהנים.** שרים כמה דאת אמר (שמואל ב' ח יח) ובני דוד כהנים היו: **אלה הדברים.** לא פחות ולא יותר:
@502 **וישב משה את דברי העם** וגו' **.** ביום המחרת, שהוא יום שלישי, שהרי בהשכמה עלה. וכי צריך היה משה להשיב, אלא בא הכתוב ללמדך דרך ארץ ממשה שלא אמר, הואיל ויודע מי ששלחני, איני צריך להשיב:
@503 **בעב הענן.** במעבה הענן וזהו ערפל: **וגם בך.** גם בנביאים הבאים אחריך: **ויגד משה.** ביום המחרת שהוא רביעי לחדש: **את דברי העם** וגו' **.** תשובה על דבר זה שמעתי מהם שרצונם לשמוע ממך אינו דומה השומע מפי השליח לשומע מפי המלך, רצוננו לראות את מלכנו:
@504 **ויאמר ה' אל משה.** אם כן, שמזקיקין לדבר עמם, לך אל העם: **וקדשתם.** וזמנתם, שיכינו עצמם היום ומחר:
@505 **והיו נכנים.** מבדלים מאשה: **ליום השלישי.** שהוא ששה בחדש. ובחמישי בנה משה את המזבח תחת ההר ושתים עשרה מצבה, כל הענין האמור בפרשת ואלה המשפטים, (שמות כד ד) ואין מקדם ומאחר בתורה: **לעיני כל העם.** מלמד שלא היה בהם סומא, שנתרפאו כלם:
@506 **והגבלת.** קבע להם תחומין לסימן, שלא יקרבו מן הגבול והלאה: **לאמר.** הגבול אומר להם, השמרו מעלות מכאן והלאה, ואתה תזהירם על כך: **ונגע בקצהו.** אפלו בקצהו:
@507 **ירה יירה.** מכאן לנסקלין שהם נדחין למטה מבית הסקילה, שהיה גבוה שתי קומות: **יירה.** ישלך למטה לארץ, כמו (שמות טו ד) ירה בים: **במשך היבל.** כשימשוך היובל קול ארוך הוא סימן סלוק שכינה והפסקת הקול, וכיון שנסתלק הם רשאין לעלות: **היבל.** הוא שופר של איל, שכן בערביא קורין לדכרא יובלא, ושופר של אילו של יצחק היה:
@508 **מן ההר אל העם.** מלמד שלא היה משה פונה לעסקיו אלא מן ההר אל העם:
@509 **היו נכנים לשלשת ימים.** לסוף שלשה ימים, הוא יום רביעי שהוסיף משה יום אחד מדעתו, כדברי רבי יוסי, ולדברי האומר בששה בחדש נתנו עשרת הדברות לא הוסיף משה כלום. לשלשת ימים, כמו (פסוק יא) ליום השלישי: **אל תגשו אל אשה.** כל שלשת ימים הללו כדי שיהו הנשים טובלות ליום השלישי ותהיינה טהורות לקבל תורה שאם ישמשו תוך שלשת ימים, שמא תפלוט האשה שכבת זרע לאחר טבילתה ותחזור ותטמא, אבל מששהתה שלושה ימים כבר הזרע מסריח ואינו ראוי להזריע וטהור מלטמא את הפולטת:
@510 **בהית הבקר.** מלמד שהקדים על ידם מה שאין דרך בשר ודם לעשות כן, שיהא הרב ממתין לתלמיד, וכן מצינו ביחזקאל (יחזקאל ג כב) קום צא אל הבקעה וגו' , (שם כג) ואקום ואצא אל הבקעה והנה שם כבוד ה' עומד:
@511 **לקראת האלהים.** מגיד שהשכינה יצאה לקראתם, כחתן היוצא לקראת כלה, וזהו שנאמר (דברים לג ב) ה' מסיני בא, ולא נאמר לסיני בא: **בתחתית ההר.** לפי פשוטו ברגלי ההר. ומדרשו שנתלש ההר ממקומו ונכפה עליהם כגיגית:
@512 **עשן כלו.** אין עשן זה שם דבר, שהרי נקוד השי''ן פת''ח, אלא לשון פעל, כמו אמר, שמר, שמע, לכך תרגומו תנן כליה, ולא תרגם תננא, וכל עשן שבמקרא נקודים קמ''ץ מפני שהם שם דבר: **הכבשן.** של סיד, יכול ככבשן זה ולא יותר, תלמוד לומר (דברים ד יא) בער באש עד לב השמים. ומה תלמוד לומר כבשן, לשבר את האזן, מה שהיא יכולה לשמוע, נותן לבריות סימן הנכר להם. כיוצא בו (הושע יא י) כאריה ישאג, וכי מי נתן כח בארי, אלא הוא, והכתוב מושלו כאריה, אלא אנו מכנין ומדמין אותו לבריותיו, כדי לשבר את האזן מה שיכולה לשמוע. וכיוצא בו (יחזקאל מג ב) וקולו כקול מים רבים, וכי מי נתן קול למים, אלא הוא, ואתה מכנה אותו לדמותו לבריותיו, כדי לשבר את האזן:
@513 **הולך וחזק מאד.** מנהג הדיוט, כל זמן שהוא מאריך לתקע קולו מחליש וכוהה, אבל כאן הולך וחזק מאד. ולמה כך, מתחלה לשבר אזניהם מה שיכולין לשמוע: **משה ידבר.** כשהיה משה מדבר ומשמיע הדברות לישראל שהרי לא שמעו מפי הגבורה אלא (שמות כ ב) אנכי ולא יהיה לך והקדוש ברוך הוא מסיעו לתת בו כח להיות קולו מגביר ונשמע: **יעננו בקול.** יעננו על דבר הקול, כמו (מלכים א' יח כד) אשר יענה באש, על דבר האש להורידו:
@514 **וירד ה' על הר סיני.** יכול ירד עליו ממש, תלמוד לומר (שמות כ יט) כי מן השמים דברתי עמכם. מלמד שהרכין שמים העליונים והתחתונים והציען על גבי ההר, כמצע על המטה, וירד כסא הכבוד עליהם:
@515 **העד בעם.** התרה בהם שלא לעלות בהר: **פן יהרסו** וגו' **.** שלא יהרסו את מצבם על ידי שתאותם אל ה' לראות ויקרבו לצד ההר: **ונפל ממנו רב.** כל מה שיפול מהם ואפלו הוא יחידי חשוב לפני רב: **יהרסו.** כל הריסה מפרדת אסיפת הבנין, אף הנפרדין ממצב אנשים הורסים את המצב:
@516 **וגם הכהנים.** אף הבכורות שהעבודה בהם: **הנגשים אל ה'.** להקריב קרבנות, אף הם אל יסמכו על חשיבותם לעלות: **יתקדשו.** יהיו מזמנים להתיצב על עמדם: **פן יפרץ.** לשון פרצה, יהרוג בהם ויעשה בהם פרצה:
@517 **לא יוכל העם.** איני צריך להעיד בהם שהרי מתרין ועומדין הם היום שלשת ימים, ולא יוכלו לעלות שאין להם רשות:
@518 **לך רד.** והעד בהם שנית, שמזרזין את האדם קדם מעשה, וחוזרין ומזרזין אותו בשעת מעשה: **ועלית אתה ואהרן עמך והכהנים.** יכול אף הם עמך, תלמוד לומר ועלית אתה. אמור מעתה, אתה מחצה לעצמך ואהרן מחצה לעצמו והם מחצה לעצמם. משה נגש יותר מאהרן, ואהרן יותר מן הכהנים, והעם כל עיקר אל יהרסו את מצבם לעלות אל ה': **פן יפרץ בם.** אף על פי שהוא נקוד חטף קמ''ץ אינו זז מגזרתו, כך דרך כל תבה שנקדתה מלאפו''ם כשהיא סמוכה במקף משתנה הנקוד לחטף קמ''ץ:
@519 **ויאמר אליהם.** התראה זו:
@520 **וידבר אלהים.** אין אלהים אלא דין. לפי שיש פרשיות בתורה שאם עשאן אדם מקבל שכר, ואם לאו אינו מקבל עליהם פרענות, יכול אף עשרת הדברות כן, תלמוד לומר וידבר אלהים, דיין לפרע: **את כל הדברים האלה.** מלמד שאמר הקדוש ברוך הוא עשרת הדברות בדבור אחד, מה שאי אפשר לאדם לומר כן. אם כן מה תלמוד לומר עוד אנכי ולא יהיה לך, שחזר ופרש על כל דבור ודבור בפני עצמו: **לאמר.** מלמד שהיו עונין על הן הן ועל לאו לאו:
@521 **אשר הוצאתיך מארץ מצרים.** כדאי היא ההוצאה שתהיו משעבדים לי. דבר אחר לפי שנגלה בים כגבור מלחמה, ונגלה כאן כזקן מלא רחמים, שנאמר (שמות כד י) ויראו את אלהי ישראל ותחת רגליו כמעשה לבנת הספיר, זו היתה לפניו בשעת השעבוד, (שם) וכעצם השמים, משנגאלו, הואיל ואני משתנה במראות אל תאמרו שתי רשויות הן, אנכי הוא אשר הוצאתיך ממצרים ועל הים. דבר אחר לפי שהיו שומעין קולות הרבה, שנאמר, (להלן פסוק טו) את הקולות, קולות באין מארבע רוחות ומן השמים ומן הארץ, אל תאמרו רשויות הרבה הן. ולמה אמר לשון יחיד, אלהיך, לתן פתחון פה למשה ללמד סנגוריא במעשה העגל, וזהו שאמר (שמות לב יא) למה ה' יחרה אפך בעמך, לא להם צוית, לא יהיה לכם אלהים אחרים, אלא לי לבדי: **מבית עבדים.** מבית פרעה שהייתם עבדים לו. או אינו אומר אלא מבית עבדים, שהיו עבדים לעבדים, תלמוד לומר (דברים ז ח) ויפדך מבית עבדים מיד פרעה מלך מצרים, אמור מעתה עבדים למלך היו, ולא עבדים לעבדים:
@522 **לא יהיה לך.** למה נאמר, לפי שנאמר (פסוק ד) לא תעשה לך, אין לי אלא שלא יעשה, העשוי כבר מנין שלא יקים, תלמוד לומר לא יהיה לך: **אלהים אחרים.** שאינן אלהות אלא אחרים עשאום אלהים עליהם, ולא יתכן לפרש אלהים אחרים זולתי, שגנאי הוא כלפי מעלה לקרותם אלהות אצלו. דבר אחר אלהים אחרים, שהם אחרים לעובדיהם, צועקים אליהם ואינן עונין אותם, ודומה כאלו הוא אחר שאינו מכירו מעולם: **על פני.** כל זמן שאני קים, שלא תאמר לא נצטוו על עבודה זרה אלא אותו הדור:
@523 **פסל.** על שם שנפסל: **וכל תמונה.** תמונת כל דבר אשר בשמים:
@524 **אל קנא.** מקנא לפרע ואינו עובר על מדתו למחול על עוון עבודה זרה, כל לשון קנא אינפרינמינ''ט בלעז , נותן לב לפרע: **לשנאי.** כתרגומו, כשאוחזין מעשה אבותיהם בידיהם:
@525 **ועשה חסד.** נוצר חסד שאדם עושה, לשלם שכר עד לאלפים דור, נמצאת מדה טובה יתרה על מדת פרענות אחת על חמש מאות, שזו לארבעה דורות וזו לאלפים:
@526 **לשוא.** (השני לשון שקר כתרגומו) כמא דתימר (שבועות כט א) אי זהו שבועת שוא, נשבע לשנות את הידוע, על עמוד של אבן שהוא של זהב. (הראשון לשון מגן, כתרגומו) זה הנשבע לחנם ולהבל, על של עץ עץ ועל אבן אבן:
@527 **זכור.** זכור ושמור בדבור אחד נאמרו. וכן (שמות לא יד) מחלליה מות יומת, (במדבר כח ט) וביום השבת שני כבשים, וכן (דברים כב יא) לא תלבש שעטנז, (שם יב) גדילים תעשה לך, וכן (ויקרא יח טז) ערות אשת אחיך, (דברים כה ה) יבמה יבא עליה, הוא שנאמר (תהלים סב יב) אחת דבר אלהים שתים זו שמעתי. זכור לשון פעול הוא, כמו (ישעיה כב יג) אכול ושתו, (שמואל ב ג טז) הלוך ובכה, וכן פתרונו תנו לב לזכור תמיד את יום השבת, שאם נזדמן לך חפץ יפה תהא מזמינו לשבת:
@528 **ועשית כל מלאכתך.** כשתבא שבת, יהא בעיניך כאלו מלאכתך עשויה, שלא תהרהר אחר מלאכה:
@529 **אתה ובנך ובתך.** אלו קטנים. או אינו אלא גדולים, אמרת הרי כבר מזהרים הם, אלא לא בא אלא להזהיר גדולים על שביתת הקטנים, וזו ששנינו (שבת קכא א) קטן שבא לכבות אין שומעין לו, מפני ששביתתו עליך:
@530 **וינח ביום השביעי.** כביכול הכתיב בעצמו מנוחה ללמד המנו קל וחמר לאדם, שמלאכתו בעמל וביגיעה, שיהא נח בשבת: **ברך ויקדשהו.** ברכו במן לכפלו בששי לחם משנה, וקדשו במן שלא היה יורד בו:
@531 **למען יאריכון ימיך.** אם תכבד יאריכון, ואם לאו יקצרון, שדברי תורה נוטריקון הם נדרשין מכלל הן לאו ומכלל לאו הן:
@532 **לא תנאף.** אין ניאוף אלא באשת איש, שנאמר (ויקרא כ י) מות יומת הנואף והנואפת, ואומר (יחזקאל טז לב) האשה המנאפת תחת אישה תקח את זרים: **לא תגנב.** בגונב נפשות הכתוב מדבר. לא תגנבו (ויקרא יט יא) בגונב ממון. או אינו אלא זה בגונב ממון, ולהלן בגונב נפשות, אמרת דבר הלמד מענינו, מה לא תרצח, לא תנאף, מדבר בדבר שחייבין עליהם מיתת בית דין, אף לא תגנוב דבר שחיב עליו מיתת בית דין:
@534 **וכל העם ראים.** מלמד שלא היה בהם אחד סומא. ומנין שלא היה בהם אלם, תלמוד לומר (שמות יט ח) ויענו כל העם. ומנין שלא היה בהם חרש, תלמוד לומר (שמות כד ז) נעשה ונשמע: **ראים את הקולות.** רואין את הנשמע, שאי אפשר לראות במקום אחר: **את הקולת.** (מכילתא בחדש פ''ט) היוצאין מפי הגבורה: **וינעו.** (שם) אין נוע אלא זיע: **ויעמדו מרחק.** היו נרתעין לאחוריהם שנים עשר מיל כאורך מחניהם ומלאכי השרת באין ומסיעין אותן להחזירם, שנאמר (תהלים סח יג) מלכי צבאות ידדון ידדון:
@536 **לבעבור נסות אתכם.** לגדל אתכם בעולם שיצא לכם שם באמות שהוא בכבודו נגלה עליכם: **נסות.** לשון הרמה וגדלה, כמו (ישעיה סב י) הרימו נס, ארים נסי (ישעיה מט כב) , וכנס על הגבעה (ישעיה ל, יז) , שהוא זקוף: **ובעבור תהיה יראתו.** על ידי שראיתם אותו יראוי ומאים, תדעו כי אין זולתו ותיראו מפניו:
@537 **נגש אל הערפל.** לפנים משלש מחיצות, חשך ענן וערפל שנאמר (דברים ד יא) וההר בוער באש עד לב השמים חשך ענן וערפל, ערפל הוא עב הענן, שנאמר לו (שמות יט ט) הנה אנכי בא אליך בעב הענן:
@538 **כה תאמר.** בלשון הזה: **אתם ראיתם.** יש הפרש בין מה שאדם רואה למה שאחרים משיחין לו, שמה שאחרים משיחין לו פעמים שלבו חלוק מלהאמין: **כי מן השמים דברתי.** וכתוב אחד אומר וירד ה' על הר סיני, בא הכתוב השלישי והכריע ביניהם (דברים ד לו) מן השמים השמיעך את קולו ליסרך ועל הארץ הראך את אשו הגדולה, כבודו בשמים ואשו וגבורתו על הארץ. דבר אחר הרכין שמים ושמי השמים והציען על ההר, וכן הוא אומר (תהלים יח י) ויט שמים וירד:
@539 **לא תעשון אתי.** לא תעשון דמות שמשי המשמשים לפני במרום: **אלהי כסף.** בא להזהיר על הכרובים, שאתה עושה לעמוד אתי, שלא יהיו של כסף, שאם שניתם לעשותם של כסף הרי הן לפני כאלהות: **ואלהי זהב.** בא להזהיר שלא יוסיף על שנים, שאם עשית ארבעה, הרי הן לפני כאלהי זהב: **לא תעשו לכם.** לא תאמר הריני עושה כרובים בבתי כנסיות ובבתי מדרשות כדרך שאני עושה בבית עולמים, לכך נאמר לא תעשו לכם:
@540 **מזבח אדמה.** מחבר באדמה, שלא יבננו על גבי עמודים או על גבי כפים. דבר אחר שהיה ממלא את חלל מזבח הנחשת אדמה בשעת חניתן: **תעשה לי.** שתהא תחלת עשייתו לשמי: **וזבחת עליו.** אצלו, כמו (במדבר ב כ) ועליו מטה מנשה. או אינו אלא עליו ממש, תלמוד לומר (דברים יב כז) הבשר והדם על מזבח ה' אלהיך, ואין שחיטה בראש המזבח: **את עלתיך ואת שלמיך.** אשר מצאנך ומבקרך. את צאנך ואת בקרך, פרוש לאת עולתיך ואת שלמיך: **בכל המקום אשר אזכיר את שמי.** אשר אתן לך רשות להזכיר שם המפרש שלי, שם אבא אליך וברכתיך אשרה שכינתי עליך מכאן אתה למד שלא נתן רשות להזכיר שם המפרש אלא במקום שהשכינה באה שם, וזהו בית הבחירה. שם נתן רשות לכהנים להזכיר שם המפרש בנשיאת כפים לברך את העם:
@541 **ואם מזבח אבנים.** רבי ישמעאל אומר כל אם ואם שבתורה רשות, חוץ משלשה ואם מזבח אבנים תעשה לי, הרי אם זה משמש בלשון כאשר, כאשר תעשה לי מזבח אבנים לא תבנה אתהן גזית שהרי חובה עליך לבנות מזבח אבנים, שנאמר (דברים כז ו) אבנים שלמות תבנה, וכן (שמות כב כד) אם כסף תלוה, חובה הוא, שנאמר (דברים טו ח) והעבט תעביטנו. ואף זה משמש בלשון כאשר וכן (ויקרא ב יד) ואם תקריב מנחת בכורים זו מנחת העמר, שהיא חובה, ועל כרחך אין אם הללו תלוין, אלא ודאין, ובלשון כאשר הם משמשים: **גזית.** לשון גזיזה שפוסלן ומסתתן בברזל: **כי חרבך הנפת עליה.** הרי כי זה משמש בלשון פן, שהוא דילמא, פן תניף חרבך עליה: **ותחללה.** הא למדת, שאם הנפת עליה ברזל חללת, שהמזבח נברא להאריך ימיו של אדם, והברזל נברא לקצר ימיו של אדם, אין זה בדין, שיונף המקצר על המאריך. ועוד, שהמזבח מטיל שלום בין ישראל לאביהם שבשמים, לפיכך לא יבא עליו כורת ומחבל. והרי דברים קל וחמר ומה אבנים שאינם רואות ולא שומעות ולא מדברות על ידי שמטילות שלום אמרה תורה לא תניף עליהם ברזל, המטיל שלום בין איש לאשתו, בין משפחה למשפחה, בין אדם לחברו, על אחת כמה וכמה שלא תבואהו פרענות:
@542 **ולא תעלה במעלות.** כשאתה בונה כבש למזבח, לא תעשהו מעלות מעלות אישיקלונ''ש בלעז [מדרגות] אלא חלק יהא ומשופע: **אשר לא תגלה ערותך.** שעל ידי המעלות אתה צריך להרחיב פסיעותיך, ואף על פי שאינו גלוי ערוה ממש, שהרי כתיב (שמות כח מב) ועשה להם מכנסי בד, מכל מקום הרחבת הפסיעות קרוב לגלוי ערוה הוא, ואתה נוהג בהם מנהג בזיון. והרי דברים קל וחומר ומה אבנים הללו שאין בהם דעת להקפיד על בזיונן אמרה תורה הואיל ויש בהם צורך, לא תנהג בהם מנהג בזיון, חברך שהוא בדמות יוצרך, ומקפיד על בזיונו, על אחת כמה וכמה:
@543 **ואלה המשפטים.** כל מקום שנאמר אלה פסל את הראשונים, ואלה מוסיף על הראשונים, מה הראשונים מסיני, אף אלו מסיני. ולמה נסמכה פרשת דינין לפרשת מזבח, לומר לך שתשים סנהדרין אצל המקדש [המזבח] : **אשר תשים לפניהם.** אמר לו הקדוש ברוך הוא למשה לא תעלה על דעתך לומר אשנה להם הפרק וההלכה ב' או ג' פעמים עד שתהא סדורה בפיהם כמשנתה, ואיני מטריח עצמי להבינם טעמי הדבר ופירושו, לכך נאמר אשר תשים לפניהם, כשלחן הערוך ומוכן לאכול לפני האדם: **לפניהם.** ולא לפני גוים, ואפילו ידעת בדין אחד שהם דנין אותו כדיני ישראל, אל תביאהו בערכאות שלהם, שהמביא דיני ישראל לפני גוים מחלל את השם ומיקר שם עבודה זרה להחשיבה, שנאמר (דברים לב לא) כי לא כצורנו צורם ואויבינו פלילים, כשאויבינו פלילים זהו עדות לעלוי יראתם:
@544 **כי תקנה עבד עברי.** עבד שהוא עברי, או אינו אלא עבדו של עברי, עבד כנעני שלקחתו מישראל, ועליו הוא אומר שש שנים יעבד, ומה אני מקים (ויקרא כה מו) והתנחלתם אתם, בלקוח מן הגוי, אבל בלקוח מישראל יצא בשש, תלמוד לומר (דברים טו יב) כי ימכר לך אחיך העברי, לא אמרתי אלא באחיך: **כי תקנה.** מיד בית דין שמכרוהו בגנבתו כמו שנאמר (שמות כב ב) אם אין לו ונמכר בגנבתו. או אינו אלא במוכר עצמו מפני דחקו, אבל מכרוהו בית דין לא יצא בשש, כשהוא אומר (ויקרא כה לט) וכי ימוך אחיך עמך ונמכר לך, הרי מוכר עצמו מפני דחקו אמור, ומה אני מקים כי תקנה, בנמכר בבית דין: **לחפשי.** לחרות:
@545 **אם בגפו יבא.** שלא היה נשוי אשה כתרגומו אם בלחודוהי. ולשון בגפו בכנפו, שלא בא אלא כמות שהוא, יחידי, בתוך לבושו בכנף בגדו: **בגפו יצא.** מגיד שאם לא היה נשוי מתחלה, אין רבו מוסר לו שפחה כנענית להוליד ממנה עבדים: **אם בעל אשה הוא.** ישראלית: **ויצאה אשתו עמו.** וכי מי הכניסה שתצא, אלא מגיד הכתוב, שהקונה עבד עברי חיב במזונות אשתו ובניו:
@546 **אם אדניו יתן לו אשה.** מכאן שהרשות ביד רבו למסור לו שפחה כנענית להוליד ממנה עבדים. או אינו אלא בישראלית, תלמוד לומר האשה וילדיה תהיה לאדוניה, הא אינו מדבר אלא בכנענית, שהרי העבריה אף היא יוצאה בשש, ואפילו לפני שש אם הביאה סימנין יוצאה, שנאמר (דברים טו יב) אחיך העברי או העבריה, מלמד, שאף העבריה יוצאה בשש:
@547 **את אשתי.** השפחה:
@548 **אל האלהים.** לבית דין, צריך שימלך במוכריו שמכרוהו לו: **אל הדלת או אל המזוזה.** יכול שתהא המזוזה כשרה לרצוע עליה, תלמוד לומר (דברים טו יז) ונתתה באזנו ובדלת, בדלת ולא במזוזה, הא מה תלמוד לומר או אל המזוזה, הקיש דלת למזוזה מה מזוזה מעומד אף דלת מעומד: **ורצע אדניו את אזנו במרצע.** הימנית. או אינו אלא של שמאל, תלמוד לומר אזן, אזן לגזרה שוה נאמר כאן ורצע אדניו את אזנו, ונאמר במצורע (ויקרא יד יד) תנוך אזן המטהר הימנית, מה להלן הימנית, אף כאן הימנית. ומה ראה אזן להרצע מכל שאר אברים שבגוף, אמר רבי יוחנן בן זכאי (קידושין כב ע''ב) אזן זאת ששמעה על הר סיני לא תגנוב, והלך וגנב, תרצע. ואם מוכר עצמו, אזן ששמעה על הר סיני (ויקרא כה נה) כי לי בני ישראל עבדים, והלך וקנה אדון לעצמו, תרצע. ר' שמעון היה דורש מקרא זה כמין חמר מה נשתנו דלת ומזוזה מכל כלים שבבית, אמר הקדוש ברוך הוא דלת ומזוזה שהיו עדים במצרים כשפסחתי על המשקוף ועל שתי המזוזות ואמרתי כי לי בני ישראל עבדים, עבדי הם ולא עבדים לעבדים, והלך זה וקנה אדון לעצמו, ירצע בפניהם: **ועבדו לעלם.** עד היובל. או אינו אלא לעולם כמשמעו, תלמוד לומר (ויקרא כה י) ואיש אל משפחתו תשובו, מגיד שחמשים שנה קרויים עולם, ולא שיהא עובדו כל חמשים שנה, אלא עובדו עד היובל בין סמוך בין מפלג:
@549 **וכי ימכר איש את בתו לאמה.** בקטנה הכתוב מדבר. יכול אפלו הביאה סימנים. אמרת קל וחמר ומה מכורה קדם לכן יוצאה בסימנין, כמו שנאמר (פסוק יא) ויצאה חנם אין כסף, שאנו דורשים אותן לסימני נערות, שאינה מכורה אינו דין שלא תמכר: **לא תצא כצאת העבדים.** כיציאת עבדים כנענים שיוצאים בשן ועין, אבל זו לא תצא בשן ועין, אלא עובדת שש או עד היובל, או עד שתביא סימנין, וכל הקודם קדם לחירותה ונותן לה דמי עינה או דמי שנה, או אינו אלא לא תצא כצאת העבדים בשש וביובל, תלמוד לומר (דברים טו יב) כי ימכר לך אחיך העברי או העבריה. מקיש עבריה לעברי לכל יציאותיו מה עברי יוצא בשש וביובל, אף עבריה יוצאה בשש וביובל, ומהו לא תצא כצאת העבדים, לא תצא בראשי אברים כעבדים כנענים. יכול העברי יוצא בראשי אברים, תלמוד לומר העברי או העבריה, מקיש עברי לעבריה מה העבריה אינה יוצאה בראשי אברים, אף הוא אינו יוצא בראשי אברים:
@550 **אם רעה בעיני אדניה.** שלא נשאה חן בעיניו לכנסה: **אשר לא יעדה.** שהיה לו ליעדה ולהכניסה לו לאשה, וכסף קניתה הוא כסף קדושיה. כאן רמז לך הכתוב שמצוה ביעוד ורמז לך שאינה צריכה קדושין אחרים: **והפדה.** יתן לה מקום להפדות ולצאת, שאף הוא מסיע בפדיונה ומה הוא מקום שנותן לה, שמגרע מפדיונה כמספר השנים שעשתה אצלו, כאלו היא שכורה אצלו. כיצד, הרי שקנאה במנה ועשתה אצלו שתי שנים אומרים לו יודע היית שעתידה לצאת לסוף שש, נמצא שקנית עבודת כל שנה ושנה בששית המנה, ועשתה אצלך שתי שנים, הרי שלישית המנה, טול שתי שלישיות המנה ותצא מאצלך: **לעם נכרי לא ימשל למכרה.** אינו רשאי למכרה לאחר, לא האדון ולא האב: **בבגדו בה.** אם בא לבגד בה, שלא לקים בה מצות ייעוד, וכן אביה, מאחר שבגד בה ומכרה לזה:
@551 **ואם לבנו ייעדנה.** האדון. מלמד, שאף בנו קם תחתיו ליעדה, אם ירצה אביו, ואינו צריך לקדשה קדושין אחרים. אלא אומר לה הרי את מיועדת לי בכסף שקבל אביך בדמיך: **כמשפט הבנות.** שאר, כסות ועונה:
@552 **אם אחרת יקח לו.** עליה: **שארה כסותה וענתה לא יגרע.** מן האמה שיעד לו כבר: **שארה.** מזונות: **כסותה.** כמשמעו: **ענתה.** תשמיש:
@553 **ואם שלש אלה לא יעשה לה.** אם אחת משלש אלה לא יעשה לה, ומה הן השלש, ייעדנה לו, או לבנו, או יגרע מפדיונה ותצא, וזה לא יעדה לא לו ולא לבנו, והיא לא היה בידה לפדות את עצמה: **ויצאה חנם.** רבה לה יציאה לזו יותר ממה שרבה לעבדים, ומה היא היציאה, ללמדך שתצא בסימנין ותשהה עמו עד שתביא סימנין. ואם הגיעו שש שנים קודם סימנין, כבר למדנו שתצא, שנאמר (דברים טו יב) העברי או העבריה ועבדך שש שנים, ומהו האמור כאן ויצאה חנם, שאם קדמו סימנים לשש שנים תצא בהן, או אינו אומר שתצא אלא בבגרות תלמוד לומר אין כסף לרבות יציאת בגרות ואם לא נאמרו שניהם הייתי אומר ויצאה חנם זו בגרות, לכך נאמרו שניהם, שלא לתן פתחון פה לבעל הדין לחלוק:
@554 **מכה איש ומת.** כמה כתובים נאמרו בפרשת רוצחין, ומה שבידי לפרש למה באו כלם, אפרש: **מכה איש ומת.** למה נאמר, לפי שנאמר (ויקרא כד יז) ואיש כי יכה כל נפש אדם מות יומת, שומע אני בהכאה בלא מיתה, תלמוד לומר מכה איש ומת, אינו חיב אלא בהכאה של מיתה. ואם נאמר מכה איש, ולא נאמר ואיש כי יכה, הייתי אומר אינו חיב עד שיכה איש, הכה את האשה ואת הקטן מנין, תלמוד לומר כי יכה כל נפש אדם, אפלו קטן ואפילו אשה. ועוד אלו נאמר מכה איש, שומע אני, אפלו קטן שהכה והרג יהא חיב, תלמוד לומר ואיש כי יכה, ולא קטן שהכה. ועוד, כי יכה כל נפש אדם, אפלו נפלים במשמע, תלמוד לומר מכה איש, אינו חיב עד שיכה בן קימא ראוי להיות איש:
@555 **ואשר לא צדה.** לא ארב לו ולא נתכון: **צדה.** לשון ארב, וכן הוא אומר (שמואל א כד יא) ואתה צודה את נפשי לקחתה, ולא יתכן לומר צדה לשון הצד ציד (בראשית כז לג) , שצידת חיות אין נופל ה''א בפועל שלה, ושם דבר בה ציד, וזה שם דבר בו צדיה ופועל שלו צודה, וזה פועל שלו צד. ואומר אני פתרונו כתרגומו ודלא כמן ליה. ומנחם חברו בחלק צד ציד, ואין אני מודה לו. ואם יש לחברו באחת ממחלוקת של צד, נחברנו בחלק (ישעיה סו יב) על צד תנשאו, (שמואל א' כ כ) צדה אורה, (דניאל ז כה) ומלין לצד עלאה ימלל. אף כאן אשר לא צדה לא צדד למצוא לו שום צד מיתה, ואף זה יש להרהר עליו, סוף דבר לשון אורב הוא: **והאלהים אנה לידו.** זמן לידו, לשון (תהלים צא י) לא תאנה אליך רעה, (משלי יב כא) לא יאנה לצדיק כל און, (מלכים ב' ה ז) מתאנה הוא לי, מזדמן למצא לי עלה: **והאלהים אנה לידו.** ולמה תצא זאת מלפניו, הוא שאמר דוד (שמואל א' כד יג) כאשר יאמר משל הקדמוני מרשעים יצא רשע, ומשל הקדמוני היא התורה, שהיא משל הקדוש ברוך הוא שהוא קדמונו של עולם. והיכן אמרה תורה מרשעים יצא רשע, והאלהים אנה לידו. במה הכתוב מדבר, בשני בני אדם, אחד הרג שוגג ואחד הרג מזיד, ולא היו עדים בדבר שיעידו, זה לא נהרג וזה לא גלה, והקדוש ברוך הוא מזמנן לפנדק אחד, זה שהרג במזיד יושב תחת הסלם, וזה שהרג שוגג עולה בסלם ונופל על זה שהרג במזיד והורגו, ועדים מעידים עליו ומחייבים אותו לגלות, נמצא זה שהרג בשוגג גולה, וזה שהרג במזיד נהרג: **ושמתי לך מקום.** אף במדבר, שינוס שמה, ואיזה מקום קולטו, זה מחנה לויה:
@556 **וכי יזיד.** למה נאמר, לפי שנאמר מכה איש וגו' שומע אני אפילו גוי, והרופא שהרג ושליח בית דין שהמית במלקות ארבעים, והאב המכה את בנו, והרב הרודה את תלמידו, והשוגג, תלמוד לומר וכי יזיד ולא שוגג על רעהו ולא על גוי. להרגו בערמה. ולא שליח בית דין והרופא והרודה את בנו ותלמידו, שאף על פי שהם מזידין אין מערימין: **מעם מזבחי.** אם היה כהן ורוצה לעבוד עבודה, תקחנו למות:
@557 **ומכה אביו ואמו.** לפי שלמדנו על החובל בחברו שהוא בתשלומין ולא במיתה, הצרך לומר על החובל באביו שהוא במיתה, ואינו חיב אלא בהכאה שיש בה חבורה: **אביו ואמו.** או זה או זה: **מות יומת.** בחנק:
@558 **וגנב איש ומכרו.** למה נאמר, לפי שנאמר (דברים כד ז) כי ימצא איש גונב נפש מאחיו, אין לי אלא איש שגנב נפש, אשה או טומטום או אנדרוגינוס שגנבו מנין, תלמוד לומר וגונב איש ומכרו. ולפי שנאמר כאן וגונב איש, אין לי אלא גונב איש, גונב אשה מנין, תלמוד לומר (שם) גונב נפש, לכך הצרכו שניהם, מה שחסר זה גלה זה: **ונמצא בידו.** שראוהו עדים שגנבו ומכרו ונמצא בידו כבר קדם מכירה: **מות יומת.** בחנק, כל מיתה האמורה בתורה סתם חנק היא. והפסיק הענין וכתב וגונב איש, בין מכה אביו ואמו למקלל אביו ואמו, ונראה לי הינו פלוגתא, דמר סבר מקשנן הכאה לקללה, ומר סבר לא מקשנן:
@559 **ומקלל אביו ואמו.** למה נאמר, לפי שהוא אומר (ויקרא כ ט) איש איש אשר יקלל את אביו, אין לי אלא איש שקלל את אביו, אשה שקללה את אביה מנין, תלמוד לומר ומקלל אביו ואמו סתם בין איש ובין אשה. אם כן למה נאמר איש אשר יקלל, להוציא את הקטן: **מות יומת.** בסקילה, וכל מקום שנאמר דמיו בו, בסקילה ובנין אב לכלם (ויקרא כ כז) באבן ירגמו אותם דמיהם בם, ובמקלל אביו ואמו נאמר (ויקרא כ ט) דמיו בו:
@560 **וכי יריבן אנשים.** למה נאמר, לפי שנאמר (פסוק כד) עין תחת עין, לא למדנו אלא דמי אבריו, אבל שבת ורפוי לא למדנו, לכך נאמרה פרשה זו: **ונפל למשכב.** כתרגומו ויפל לבוטלן, לחולי שמבטלו ממלאכתו:
@561 **על משענתו.** על בוריו וכחו: **ונקה המכה.** וכי תעלה על דעתך שיהרג זה שלא הרג, אלא למדך כאן שחובשים אותו, עד שנראה אם יתרפא זה, וכן משמעו כשקם זה והולך על משענתו אז נקה המכה, אבל עד שלא יקום זה לא נקה המכה: **רק שבתו.** בטול מלאכתו מחמת החולי, אם קטע ידו או רגלו, רואין בטול מלאכתו מחמת החולי כאלו הוא שומר קשואין, שהרי אף לאחר החולי אינו ראוי למלאכת יד ורגל, והוא כבר נתן לו מחמת נזקו דמי ידו ורגלו, שנאמר (פסוק כד) יד תחת יד רגל תחת רגל: **ורפא ירפא.** כתרגומו, ישלם שכר הרופא:
@562 **וכי יכה איש את עבדו או את אמתו.** בעבד כנעני הכתוב מדבר. או אינו אלא בעברי, תלמוד לומר כי כספו הוא, מה כספו קנוי לו עולמית, אף עבד הקנוי לו עולמית. והרי היה בכלל (פסוק יב) מכה איש ומת, אלא בא הכתוב והוציאו מן הכלל, להיות נדון בדין יום או יומים, שאם לא מת תחת ידו ושהה מעת לעת פטור: **בשבט.** כשיש בו כדי להמית הכתוב מדבר. או אינו אלא אפלו אין בו כדי להמית, תלמוד לומר בישראל (במדבר לה יז) ואם באבן יד אשר ימות בה הכהו, והלא דברים קל וחמר מה ישראל חמור אין חיב עליו, אלא אם כן הכהו בדבר שיש בו כדי להמית, ועל אבר שהוא כדי למות בהכאה זו, עבד הקל לא כל שכן: **נקם ינקם.** מיתת סייף, וכן הוא אומר (ויקרא כו כה) חרב נוקמת נקם ברית:
@563 **אך אם יום או יומים יעמד לא יקם.** אם על יום אחד הוא פטור, על יומים לא כל שכן, אלא יום שהוא כיומים, ואיזה, זה מעת לעת: **לא יקם כי כספו הוא.** הא אחר שהכהו, אף על פי ששהה מעת לעת קדם שמת, חיב:
@564 **וכי ינצו אנשים.** זה עם זה, ונתכון להכות את חברו והכה את האשה: **ונגפו.** אין נגיפה אלא לשון דחיפה והכאה, כמו (תהלים צא יב) פן תגוף באבן רגלך, (ירמיה יג טז) ובטרם יתנגפו רגליכם, (ישעיה ח יד) ולאבן נגף: **ולא יהיה אסון.** באשה: **ענוש יענש.** לשלם דמי ולדות לבעל שמין אותה, כמה היתה ראויה למכר בשוק להעלות בדמיה בשביל הריונה: **ענוש יענש.** יגבו ממון ממנו, כמו (דברים כב יט) וענשו אותו מאה כסף: **כאשר ישית עליו** וגו' **.** כשיתבענו הבעל בבית דין להשית עליו עונש על כך: **ונתן.** המכה דמי ולדות: **בפללים.** על פי הדינים:
@565 **ואם אסון יהיה.** באשה: **ונתתה נפש תחת נפש.** רבותינו חולקין בדבר. יש אומרים נפש ממש, ויש אומרים ממון, אבל לא נפש ממש, שהמתכון להרג את זה והרג את זה פטור ממיתה ומשלם ליורשיו דמיו, כמו שהיה נמכר בשוק:
@566 **עין תחת עין.** סמא עין חברו נותן לו דמי עינו, כמה שפחתו דמיו למכר בשוק, וכן כלם, ולא נטילת אבר ממש, כמו שדרשו רבותינו בפרק החובל (בבא קמא פד א) :
@567 **כויה תחת כויה.** מכות אש, ועד עכשיו דבר בחבלה שיש בה פחת דמים, ועכשיו בשאין בה פחת דמים, אלא צער, כגון כואו בשפוד על צפרנו אומדים כמה אדם כיוצא בזה רוצה לטל להיות מצטער כך: **פצע.** היא מכה המוציאה דם, שפצע את בשרו, נברדור''א בלעז , הכל לפי מה שהוא אם יש בו פחת דמים נותן נזק, ואם נפל למשכב נותן שבת ורפוי ובשת וצער. ומקרא זה יתר הוא, ובהחובל דרשוהו רבותינו לחייב על הצער אפלו במקום נזק, שאף על פי שנותן לו דמי ידו, אין פוטרין אותו מן הצער לומר הואיל וקנה ידו יש עליו לחתכה בכל מה שירצה, אלא אומרים יש לו לחתכה בסם, שאינו מצטער כל כך, וזה חתכה בברזל וצערו: **חבורה.** היא מכה שהדם נצרר בה ואינו יוצא, אלא שמאדים הבשר כנגדו ולשון חבורה [ טי''א ] בלעז [כתם] , כמו (ירמיה יג כג) ונמר חברברתיו ותרגומו משקופי, לשון חבטה בטדור''א בלעז , וכן ושדופת קדים (בראשית מא ו) שקיפן קדום, חבוטות ברוח, וכן על המשקוף (לעיל יב כג) על שם שהדלת נושק עליו:
@568 **את עין עבדו.** כנעני, אבל עברי אינו יוצא בשן ועין, כמו שאמרנו אצל לא תצא כצאת העבדים (פסוק ז) : **תחת עינו.** וכן בעשרים וארבעה ראשי אברים אצבעות הידים והרגלים. ושתי אזנים והחוטם וראש הגויה, שהוא גיד האמה. ולמה נאמר שן ועין, שאם נאמר עין ולא נאמר שן, הייתי אומר מה עין שנברא עמו אף כל שנברא עמו, והרי שן לא נברא עמו, ואם נאמר שן ולא נאמר עין, הייתי אומר אפלו שן תינוק שיש לה חליפין, לכך נאמר עין:
@570 **וכי יגח שור.** אחד שור ואחד כל בהמה וחיה ועוף אלא שדבר הכתוב בהוה: **ולא יאכל את בשרו.** ממשמע שנאמר סקול יסקל השור, איני יודע שהוא נבלה, ונבלה אסורה באכילה, אלא מה תלמוד לומר ולא יאכל את בשרו, שאפלו שחטו לאחר שנגמר דינו, אסור באכילה. בהנאה מנין, תלמוד לומר: **ובעל השור נקי.** כאדם האומר לחברו יצא פלוני נקי מנכסיו ואין לו בהם הנאה של כלום, זהו מדרשו. ופשוטו כמשמעו לפי שנאמר במועד וגם בעליו יומת, הצרך לומר בתם ובעל השור נקי:
@571 **מתמל שלשם.** הרי שלש נגיחות: **והועד בבעליו.** לשון התראה בעדים, כמו (בראשית מג ג) העד העיד בנו האיש: **והמית איש** וגו' **.** לפי שנאמר וכי יגח, אין לי אלא שהמיתו בנגיחה, המיתו בנשיכה, דחיפה, רביצה, בעיטה מנין, תלמוד לומר והמית [מכל מקום] : **וגם בעליו יומת.** בידי שמים. יכול בידי אדם, תלמוד לומר (במדבר לה כא) מות יומת המכה רוצח הוא, על רציחתו אתה הורגו, ואי אתה הורגו על רציחת שורו:
@572 **אם כפר יושת עליו.** ''אם'' זה אינו תלוי, והרי הוא כמו (לקמן כב כד) אם כסף תלוה, לשון אשר זה משפטו, שישיתו עליו בית דין כופר: **ונתן פדיון נפשו.** דמי נזק, דברי רבי ישמעאל, רבי עקיבא אומר דמי מזיק:
@573 **או בן יגח.** בן שהוא קטן: **או בת.** שהיא קטנה. לפי שנאמר והמית איש או אשה, יכול אינו חיב אלא על הגדולים, תלמוד לומר או בן יגח וגו' , לחייב על הקטנים כגדולים:
@574 **אם עבד' או אמה.** כנעניים: **שלשים שקלים יתן.** גזרת הכתוב הוא, בין שהוא שוה אלף זוז, בין שאינו שוה אלא דינר. והשקל משקלו ארבעה זהובים שהם חצי אונקיא למשקל הישר של קולוניי''א :
@575 **וכי יפתח איש בור.** שהיה מכסה וגלהו: **או כי יכרה.** למה נאמר, אם על הפתיחה חיב, על הכריה לא כל שכן, אלא להביא כורה אחר כורה שהוא חיב: **ולא יכסנו.** הא אם כסהו, פטור, ובחופר ברשות הרבים דבר הכתוב: **שור או חמור.** הוא הדין לכל בהמה וחיה, שבכל מקום שנאמר שור וחמור, אנו למדין אותו שור שור משבת, שנאמר למען ינוח שורך וחמורך (שמות כג יב) , מה להלן כל בהמה וחיה כשור. שהרי נאמר במקום אחר וכל בהמתך (דברים ה יג) אף כאן, כל בהמה וחיה כשור, ולא נאמר שור וחמור אלא שור, ולא אדם, חמור, ולא כלים:
@576 **בעל הבור.** בעל התקלה, אף על פי שאין הבור שלו, שעשאו ברשות הרבים, עשאו הכתוב בעליו להתחיב עליו בנזקיו: **כסף ישיב לבעליו.** ישיב, לרבות שוה כסף, ואפלו סבין: **והמת יהיה לו.** לנזק, שמין את הנבלה ונוטלה בדמים ומשלם לו המזיק עליה תשלומי נזקו:
@577 **וכי יגף.** ידחוף, בין בקרניו, בין בגופו, בין ברגליו, בין שנשכו בשניו, כלן בכלל נגיפה הם, שאין נגיפה אלא לשון מכה: **שור איש.** שור של איש: **ומכרו את השור** וגו' **.** בשוים הכתוב מדבר, שור שוה מאתים שהמית שור שוה מאתים, בין שהנבלה שוה הרבה, בין שהיא שוה מעט, כשנוטל זה חצי החי וחצי המת, וזה חצי החי וחצי המת, נמצא כל אחד מפסיד חצי נזק שהזיקה המיתה, למדנו שהתם משלם חצי נזק, שמן השוין אתה למד לשאינן שוין, כי דין התם לשלם חצי נזק לא פחות ולא יותר. או יכול אף בשאינן שוין בדמיהן כשהן חיים, אמר הכתוב וחצו את שניהם, אם אמרת כן, פעמים שמזיק משתכר הרבה, כשהנבלה שוה למכר לנכרים הרבה יותר מדמי שור המזיק, ואי אפשר שיאמר הכתוב, שיהא המזיק נשכר. או פעמים שהנזק נוטל הרבה יותר מדמי נזק שלם, שחצי דמי שור המזיק שוין יותר מכל דמי שור הנזק, ואם אמרת כן, הרי תם חמור ממועד, על כרחך לא דבר הכתוב אלא בשוין. ולמדך שהתם משלם חצי נזק, ומן השוין תלמד לשאינן שוין, שהמשתלם חצי נזקו שמין לו את הנבלה, ומה שפחתו דמיו בשביל המיתה, נוטל חצי הפחת והולך, ולמה אמר הכתוב בלשון הזה ולא אמר ישלם חציו, ללמד שאין התם משלם אלא מגופו, ואם נגח ומת, אין הנזק נוטל אלא הנבלה, ואם אינה מגעת לחצי נזקו, יפסיד. או שור שוה מנה שנגח שור שוה חמש מאות זוז, אינו נוטל אלא את השור, שלא נתחיב התם לחיב את בעליו לשלם מן העליה:
@578 **או נודע.** או לא היה תם, אלא נודע כי שור נגח הוא היום, ומתמול שלשום, הרי שלש נגיחות: **שלם ישלם שור.** נזק שלם: **והמת יהיה לו.** לנזק, ועליו ישלים המזיק עד שישתלם נזק כל נזקו:
@579 **חמשה בקר** וגו' **.** אמר רבן יוחנן בן זכאי חס המקום על כבודן של בריות, שור שהולך ברגליו ולא נתבזה בו הגנב לנשאו על כתפו, משלם חמשה, שה שנשאו על כתפו, משלם ארבעה הואיל ונתבזה בו. אמר רבי מאיר בא וראה כמה גדולה כחה של מלאכה, שור שבטלו ממלאכתו משלם חמשה, שה שלא בטלו ממלאכתו ארבעה: **תחת השור' תחת השה.** שנאן הכתוב לומר, שאין מדת תשלומי ארבעה וחמשה נוהגת אלא בשור ושה בלבד:
@580 **אם במחתרת.** כשהיה חותר את הבית: **אין לו דמים.** אין זו רציחה, הרי הוא כמת מעיקרו. כאן למדתך תורה אם בא להרגך, השכם להרגו, וזה להרגך בא שהרי יודע הוא, שאין אדם מעמיד עצמו ורואה שנוטלין ממונו בפניו ושותק, לפיכך על מנת כן בא, שאם יעמוד בעל הממון כנגדו יהרגנו:
@581 **אם זרחה השמש עליו.** אין זה אלא כמן משל אם ברור לך הדבר שיש לו שלום עמך, כשמש הזה שהוא שלום בעולם, כך פשוט לך שאינו בא להרוג, אפילו יעמוד בעל הממון כנגדו, כגון אב החותר לגנוב ממון הבן, בידוע שרחמי האב על הבן, ואינו בא על עסקי נפשות: **דמים לו.** כחי הוא חשוב ורציחה היא, אם יהרגהו בעל הבית: **שלם ישלם.** הגנב ממון שגנב, ואינו חיב מיתה. ואונקלוס שתרגם אם עינא דסהדיא נפלת עלוהי, לקח לו שטה אחרת, לומר שאם מצאוהו עדים קדם שבא בעל הבית, וכשבא בעל הבית נגדו, התרו בו, שלא יהרגהו, דמים לו, חיב עליו אם הרגו, שאחר שיש רואים לו, אין הגנב הזה בא על עסקי נפשות, ולא יהרוג את בעל הממון:
@582 **אם המצא תמצא בידו.** ברשותו, שלא טבח ולא מכר: **משור עד חמור.** כל דבר בכלל תשלומי כפל בין שיש בו רוח חיים בין שאין בו רוח חיים, שהרי נאמר במקום אחר (פסוק ח) על שה על שלמה על כל אבדה וגו' ישלם שנים לרעהו: **חיים שנים ישלם.** ולא ישלם לו מתים, אלא חיים או דמי חיים:
@583 **כי יבער. את בעירה ובער.** כלם לשון בהמה, כמו (במדבר כ ד) אנחנו ובעירנו: **כי יבער.** יוליך בהמותיו בשדה וכרם של חברו ויזיק אתו באחת משתי אלה או בשלוח בעירה, או בבעור. ופירשו רבותינו שלוח הוא נזקי מדרך כף רגל, ובער הוא נזקי השן האוכלת ומבערת: **בשדה אחר.** בשדה של איש אחר: **מיטב שדהו ישלם.** שמין את הנזק, ואם בא לשלם לו קרקע דמי נזקו, ישלם לו ממיטב שדותיו אם היה נזקו סלע יתן לו שוה סלע מעדית שיש לו. למדך הכתוב, שהנזקין שמין להם בעדית:
@584 **כי תצא אש.** אפילו מעצמה: **ומצאה קוצים.** קרדונ''ש בלעז : **ונאכל גדיש.** שליחכה בקוצים עד שהגיעה לגדיש או לקמה המחברת לקרקע: **או השדה.** שליחכה את נירו וצריך לניר אותה פעם שניה: **שלם ישלם המבעיר.** אף על פי שהדליק בתוך שלו והיא יצאה מעצמה על ידי קוצים שמצאה, חיב לשלם, לפי שלא שמר את גחלתו שלא תצא ותזיק:
@585 **וגנב מבית האיש.** לפי דבריו: **אם ימצא הגנב.** ישלם הגנב שנים לבעלים:
@586 **אם לא ימצא הגנב.** ובא השומר הזה שהוא בעל הבית: **ונקרב.** אל הדינין לדון עם זה ולשבע לו שלא שלח ידו בשלו:
@587 **על כל דבר פשע.** שימצא שקרן בשבועתו, שיעידו עדים שהוא עצמו גנבו, וירשיעוהו אלהים על פי העדים: **ישלם שנים לרעהו.** למדך הכתוב, שהטוען בפקדון לומר נגנב המנו, ונמצא שהוא עצמו גנבו, משלם תשלומי כפל. ואימתי בזמן שנשבע ואחר כך באו עדים, שכך דרשו רבותינו זכרונם לברכה ונקרב בעל הבית אל האלהים, קריבה זו שבועה היא. אתה אומר לשבועה, או אינו אלא לדין, שכיון שבא לדין וכפר לומר נגנבה, מיד יתחיב כפל, אם באו עדים שהוא בידו. נאמר כאן שליחות יד, ונאמר למטה שליחות יד (פסוק י) שבועת ה' תהיה בין שניהם אם לא שלח ידו, מה להלן שבועה אף כאן שבועה: **אשר יאמר כי הוא זה.** לפי פשוטו אשר יאמר העד כי הוא זה שנשבעת עליו הרי הוא אצלך. עד הדינין יבא דבר שניהם ויחקרו את העדים, ואם כשרים הם וירשיעוהו לשומר זה, ישלם שנים, ואם ירשיעו את העדים, שנמצאו זוממין, ישלמו הם שנים לשומר. ורבותינו זכרונם לברכה דרשו כי הוא זה, ללמד שאין מחייבין אותו שבועה אלא אם כן הודה במקצת לומר כך וכך אני חיב לך, והמותר נגנב ממני:
@588 **כי יתן איש אל רעהו חמור או שור.** פרשה ראשונה נאמרה בשומר חנם, לפיכך פטר בו את הגנבה, כמו שנאמר (פסוק ו) וגנב מבית האיש, אם לא ימצא הגנב ונקרב בעל הבית לשבועה, למדת שפוטר עצמו בשבועה זו. ופרשה זו אמורה בשומר שכר, לפיכך אינו פטור אם נגנבה, כמו שכתוב (פסוק יא) אם גנב יגנב מעמו ישלם, אבל על האונס, כגון מת מעצמו, או נשבר או נשבה בחזקה על ידי לסטים, ואין רואה שיעיד בדבר:
@589 **שבועת ה' תהיה.** ישבע שכן הא כדבריו, והוא לא שלח בה יד להשתמש בה לעצמו, שאם שלח בה יד, ואחר כך נאנסה, חיב באנסים: **ולקח בעליו.** השבועה: **ולא ישלם.** לו השומר כלום:
@591 **אם טרף יטרף.** על ידי חיה רעה: **יבאהו עד.** יביא עדים שנטרפה באונס, ופטור: **הטרפה לא ישלם.** אינו אומר טרפה לא ישלם, אלא הטרפה, יש טרפה שהוא משלם ויש טרפה שאינו משלם. טרפת חתול ושועל ונמיה משלם. טרפת זאב, ארי ודב ונחש אינו משלם. ומי לחשך לדון כן, שהרי כתיב ומת או נשבר או נשבה, מה מיתה שאין יכול להציל, אף שבר ושביה שאין יכול להציל:
@592 **וכי ישאל.** בא ללמדך על השואל שחיב באונסין: **בעליו אין עמו.** אם בעליו שלשור אינו עם השואל במלאכתו:
@593 **אם בעליו עמו.** בין שהוא באותה מלאכה, בין שהוא במלאכה אחרת, היה עמו בשעת שאלה, אינו צריך להיות עמו בשעת שבירה ומיתה: **אם שכיר הוא.** אם השור אינו שאול אלא שכור, **בא בשכרו.** ליד השוכר הזה ולא בשאלה, ואין כל הנאה שלו, שהרי על ידי שכרו נשתמש, ואין לו משפט שואל להתחיב באנסין. ולא פרש מה דינו, אם כשומר חנם או כשומר שכר, לפיכך נחלקו בו חכמי ישראל, שוכר כיצד משלם, רבי מאיר אומר כשומר חנם. רבי יוחנן אומר כשומר שכר:
@594 **וכי יפתה.** מדבר על לבה עד ששומעת לו, וכן תרגומו וארי ישדל. שדול בלשון ארמי כפתוי בלשון עברי: **מהר ימהרנה.** יפסוק לה מהר כמשפט איש לאשתו, שכותב לה כתבה וישאנה:
@595 **כמהר הבתולות.** שהוא קצוב חמשים כסף אצל התופס את הבתולה ושוכב עמה באונס שנאמר (דברים כב כט) ונתן האיש השוכב עמה לאבי הנער חמשים כסף:
@596 **מכשפה לא תחיה.** אלא תומת בבית דין, ואחד זכרים ואחד נקבות, אלא שדבר הכתוב בהוה שהנשים מצויות מכשפות:
@597 **כל שוכב עם בהמה מות יומת.** בסקילה, רובע כנרבעת, שכתוב בהן (ויקרא כ טז) דמיהם בם:
@598 **לאלהים.** לעבודה זרה. אלו היה נקוד לאלהים היה צריך לפרש ולכתב אחרים, עכשיו שאמר לאלהים, אין צריך לפרש אחרים, שכל למד ובית המשמשות בראש התבה אם נקודה בחטף, כגון למלך, למדבר, לעיר, צריך לפרש לאיזה מלך, לאיזה מדבר, לאיזה עיר, וכן למלכים, לרגלים צריך לפרש לאיזה, ואם אינו מפרש, כל מלכים במשמע, וכן לאלהים כל אלהים משמע, אפלו קדש, אבל כשהיא נקודה פת''ח, כמו למלך, למדבר, לעיר נודע באיזה מלך, באיזו מדבר ובאיזה עיר מדבר, וכן לאלהים, לאותן שהזהרתם עליהם במקום אחר, כיוצא בו (תהלים פו ח) אין כמוך באלהים, לפי שלא פרש הצרך לנקד פתח: **יחרם.** יומת. ולמה נאמר יחרם, והלא כבר נאמר בו מיתה במקום אחר (דברים יז ה) והוצאת את האיש ההוא או את האשה ההיא וגו' , אלא לפי שלא פרש על איזו עבודה חיב מיתה, שלא תאמר כל עבודות במיתה, בא ופרש לך כאן זובח לאלהים יחרם, לומר לך, מה זביחה עבודה הנעשית בפנים לשמים, אף אני מרבה המקטיר והמנסך והמשתחוה, שהן עבודת בפנים וחיבים עליהם לכל עבודה זרה בין שדרכה לעבדה בכך, בין שאין דרכה לעבדה בכך, אבל שאר עבודות, כגון המכבד והמרבץ והמגפף והמנשק, אינו במיתה, אלא באזהרה:
@599 **וגר לא תונה.** אונאת דברים, קונטרליי''ר בלעז [לקנטר] , כמו (ישעיה מט כו) והאכלתי את מוניך את בשרם: **ולא תלחצנו.** בגזלת ממון: **כי גרים הייתם.** אם הוניתו, אף הוא יכול להונותך ולומר לך אף אתה מגרים באת, מום שבך אל תאמר לחברך. כל לשון גר, אדם שלא נולד באותה מדינה, אלא בא ממדינה אחרת לגור שם:
@600 **כל אלמנה ויתום לא תענון.** הוא הדין לכל אדם, אלא שדבר הכתוב בהווה, לפי שהם תשושי כח ודבר מצוי לענותם:
@601 **אם ענה תענה אתו.** הרי זה מקרא קצר, גזם ולא פרש ענשו, כמו (בראשית ד טו) לכן כל הרג קין גזם ולא פרש ענשו אף כאן אם ענה תענה אתו, לשון גזום, כלומר סופך לטול את שלך, למה, כי אם צעק יצעק אלי וגו' :
@602 **והיו נשיכם אלמנות.** ממשמע שנאמר והרגתי אתכם, איני יודע שנשיכם אלמנות ובניכם יתומים, אלא הרי זו קללה אחרת, שיהיו הנשים צרורות כאלמנות חיות, שלא יהיו עדים למיתת בעליהן ותהיינה אסורות להנשא והבנים יהיו יתומים, שלא יניחום בית דין לירד לנכסי אביהם לפי שאין יודעים אם מתו אם נשבו:
@603 **אם כסף תלוה את עמי.** רבי ישמעאל אומר כל אם ואם שבתורה רשות, חוץ משלשה וזה אחד מהן: **את עמי.** עמי וגוי, עמי קדם. עני ועשיר, עני קדם. עניי עירך ועניי עיר אחרת, עניי עירך קודמין. וזה משמעו אם כסף תלוה, את עמי תלוהו, ולא לגוי ולאיזה מעמי, את העני, ולאיזה עני לאותו שעמך. דבר אחר את העני, שלא תנהג בו מנהג בזיון בהלואה, שהוא עמי: **את העני עמך.** הוי מסתכל בעצמך כאלו אתה העני: **לא תהיה לו כנשה.** לא תתבענו בחזקה, אם אתה יודע שאין לו, אל תהי דומה עליו כאלו הלויתו, אלא כאלו לא הלויתו, כלומר לא תכלימהו: **נשך.** רבית שהוא כנשיכת נחש, שנושך חבורה קטנה ברגלו ואינו מרגיש, ופתאום הוא מבצבץ ונופח עד קדקדו, כך רבית, אינו מרגיש ואינו נכר עד שהרבית עולה ומחסרו ממון הרבה:
@604 **אם חבל תחבל.** כל לשון חבלה אינו משכון בשעת הלואה, אלא שממשכנין את הלוה, כשמגיע הזמן ואינו פורע. חבל תחבול כפל לך בחבלה, עד כמה פעמים, אמר הקדוש ברוך הוא כמה אתה חיב לי, והרי נפשך עולה אצלי כל אמש ואמש ונותנת דין וחשבון ומתחיבת לפני, ואני מחזירה לך, אף אתה טול והשב טול והשב: **עד בא השמש תשיבנו לו.** כל היום תשיבנו לו עד בא השמש, וכבוא השמש תחזור ותטלנו, עד שיבא בקר של מחר, ובכסות יום הכתוב מדבר, שאין צריך לה בלילה:
@605 **כי הוא כסותה.** זו טלית: **שמלתו.** זו חלוק: **במה ישכב.** לרבות את המצע:
@606 **אלהים לא תקלל.** הרי זו אזהרה לברכת השם, ואזהרה לקללת דין:
@607 **מלאתך.** חובה המטלת עליך כשתתמלא תבואתך להתבשל, והם בכורים: **ודמעך.** התרומה, ואיני יודע מהו לשון דמע: **לא תאחר.** לא תשנה סדר הפרשתן, לאחר את המקדם ולהקדים את המאחר, שלא יקדים תרומה לבכורים ומעשר לתרומה: **בכור בניך תתן לי.** לפדותו בחמש סלעים מן הכהן. והלא כבר צוה עליו במקום אחר, אלא כדי לסמוך לו כט **כן תעשה לשורך.** מה בכור אדם לאחר שלשים יום פודהו שנאמר (במדבר יח טז) ופדויו מבן חדש תפדה, אף בכור בהמה דקה [גסה] מטפל בו שלשים יום ואחר כך נותנו לכהן: **שבעת ימים יהיה עם אמו.** זו אזהרה לכהן, שאם בא למהר את הקרבתו, לא ימהר קדם שמונה, לפי שהוא מחסר זמן: **ביום השמיני תתנו לי.** יכול יהא חובה לבו ביום, נאמר כאן שמיני, ונאמר להלן (ויקרא כב כז) ומיום השמיני והלאה ירצה, מה שמיני האמור להלן להכשיר משמיני ולהלן, אף שמיני האמור כאן להכשיר משמיני ולהלן, וכן משמעו וביום השמיני אתה רשאי לתנו לי:
@609 **ואנשי קדש תהיון לי.** אם אתם קדושים ופרושים משקוצי נבלות וטרפות הרי אתם שלי, ואם לאו אינכם שלי: **ובשר בשדה טרפה.** אף בבית כן, אלא שדבר הכתוב בהוה, מקום שדרך בהמות לטרף, וכן (דבר' כב כז) כי בשדה מצאה, וכן (שם כג יא) אשר לא יהיה טהור מקרה לילה, הוא הדין מקרה יום, אלא שדבר הכתוב בהוה. ואונקלוס תרגם ובשר תליש מן חיוא חיא, בשר שנתלש על ידי טרפת זאב או ארי, מן חיה כשרה או מבהמה כשרה בחייה: **לכלב תשלכון אתו.** אף הגוי ככלב, או אינו אלא כלב כמשמעו, תלמוד לומר בנבלה (דב' יד כא) או מכר לנכרי, קל וחמר לטרפה שמתרת בכל הנאות. אם כן מה תלמוד לומר לכלב, למדך הכתוב שאין הקדוש ברוך הוא מקפח שכר כל בריה, שנאמר (שמות יא ז) ולכל בני ישראל לא יחרץ כלב לשונו, אמר הקדוש ברוך הוא תנו לו שכרו:
@610 **לא תשא שמע שוא.** כתרגומו לא תקבל שמע דשקר, אזהרה למקבל לשון הרע, ולדין, שלא ישמע דברי בעל דין עד שיבא בעל דין חברו: **אל תשת ידך עם רשע.** הטוען את חברו תביעת שקר, שהבטיחהו להיות לו עד חמס:
@611 **לא תהיה אחרי רבים לרעת.** יש במקרא זה מדרשי חכמי ישראל, אבל אין לשון המקרא מישב בהן על אפניו. מכאן דרשו שאין מטין לחובה בהכרעת דין אחד, וסוף המקרא דרשו אחרי רבים להטות, שאם יש שנים במחיבין יותר על המזכין, הטה הדין על פיהם לחובה ובדיני נפשות הכתוב מדבר, ואמצע המקרא דרשו ולא תענה על רב, על רב, שאין חולקין על מפלא שבבית דין, לפיכך מתחילין בדיני נפשות מן הצד, לקטנים שבהן שואלין תחלה, שיאמרו את דעתם. לפי דברי רבותינו כך פתרון המקרא לא תהיה אחרי רבים לרעות לחייב מיתה בשביל דין אחד, שירבו המחיבין על המזכין ולא תענה על הרב לנטות מדבריו, ולפי שהוא חסר יו''ד דרשו בו כן. אחרי רבים להטת ויש רבים שאתה נוטה אחריהם, ואימתי, בזמן שהן שנים המכריעין במחיבין יותר מן המזכין, וממשמע שנאמר לא תהיה אחרי רבים לרעות שומע אני אבל היה עמהם לטובה, מכאן אמרו דיני נפשות מטין על פי אחד לזכות ועל פי שנים לחובה. ואונקלוס תרגם לא תתמנע מלאלפא מה דבעינך על דינא, ולשון העברי, לפי התרגום, כך הוא נדרש לא תענה על ריב לנטת אם ישאלך דבר למשפט, לא תענה לנטות לצד אחד ולסלק עצמך מן הריב, אלא הוי דן אותו לאמתו. ואני אומר לישבו על אפניו כפשוטו, כך פתרונו: **לא תהיה אחרי רבים לרעת.** אם ראית רשעים מטין משפט, לא תאמר הואיל ורבים הם, הנני נוטה אחריהם: **ולא תענה על רב לנטת** וגו' **.** ואם ישאל הנדון על אותו המשפט אל תעננו על הריב דבר הנוטה אחרי אותן רבים להטות את המשפט מאמתו אלא אמור את המשפט כאשר הוא, וקלר יהא תלוי בצואר הרבים:
@612 **לא תהדר.** לא תחלוק לו כבוד לזכותו בדין ולומר דל הוא, אזכנו ואכבדנו:
@614 **כי תראה חמור שנאך** וגו' **.** הרי כי משמש בלשון דלמא, שהוא מארבע לשונות של שמושי כי וכה פתרונו שמא תראה חמורו רובץ תחת משאו: **וחדלת מעזב לו.** בתמיהה: **עזב תעזב עמו.** עזיבה זו לשון עזרה, וכן (דברים לב לו) עצור ועזוב, וכן (נחמיה ג ח) ויעזבו ירושל ם עד החומה, מלאוה עפר לעזוב ולסיע את חוזק החומה. כיוצא בו (דברים ז יז) כי תאמר בלבבך רבים הגוים האלה ממני וגו' , שמא תאמר כן, בתמיהה, לא תירא מהם. ומדרשו, כך דרשו רבותינו כי תראה וחדלת פעמים שאתה חדל ופעמים שאתה עוזר. הא כיצד, זקן ואינו לפי כבודו, וחדלת, או בהמת נכרי ומשאוי ישראל, וחדלת: **עזב תעזב עמו.** לפרק המשא. מלמשקל ליה, מלטול משאוי ממנו:
@615 **אבינך.** לשון אובה, שהוא מדולדל ותאב לכל טובה:
@616 **ונקי וצדיק אל תהרג.** מנין ליוצא מבית דין חיב ואמר אחד יש לי ללמד עליו זכות, שמחזירין אותו, תלמוד לומר ונקי אל תהרג וזה אף על פי שאינו צדיק, שלא נצטדק בבית דין, מכל מקום נקי הוא מדין מיתה, שהרי יש לך לזכותו. ומנין ליוצא מבית דין זכאי ואמר אחד יש לי ללמד עליו חובה, שאין מחזירין אותו לבית דין לחיבו תלמוד לומר וצדיק אל תהרוג, וזה צדיק הוא, שנצטדק בבית דין: **כי לא אצדיק רשע.** אין עליך להחזירו, כי אני לא אצדיקנו בדיני, אם יצא מידך זכאי, יש לי שלוחים הרבה להמיתו במיתה שנתחייב בה:
@617 **ושחד לא תקח.** אפלו לשפוט אמת, וכל שכן כדי להטות הדין, שהרי כדי להטות את הדין נאמר כבר לעיל לא תטה משפט: **יעור פקחים.** אפלו חכם בתורה ונוטל שחד, סוף שתטרף דעתו עליו, וישתכח תלמודו, ויכהה מאור עיניו: **ויסלף.** כתרגומו ומקלקל: **דברי צדיקים.** דברים המצדקים, משפטי אמת, וכן תרגומו פתגמין תריצין. ישרים:
@618 **וגר לא תלחץ.** בהרבה מקומות הזהירה תורה על הגר מפני שסורו רע: **את נפש הגר.** כמה קשה לו כשלוחצים אותו:
@619 **ואספת את תבואתה.** לשון הכנסה לבית, כמו (דברים כב ב) ואספתו אל תוך ביתך:
@620 **תשמטנה.** מעבודה: **ונטשתה.** מאכילה אחר זמן הבעור. דבר אחר תשמטנה מעבודה גמורה, כגון חרישה וזריעה. ונטשתה מלזבל ומלקשקש: **ויתרם תאכל חית השדה.** להקיש מאכל אביון למאכל חיה מה חיה אוכלת בלא מעשר, אף אביונים אוכלים בלא מעשר, מכאן אמרו אין מעשר בשביעית: **כן תעשה לכרמך.** ותחלת המקרא בשדה הלבן, כמו שאמר למעלה המנו תזרע את ארצך:
@621 **וביום השביעי תשבת.** אף בשנה השביעית לא תעקר שבת בראשית ממקומה, שלא תאמר הואיל וכל השנה קרויה שבת, לא תנהג בה שבת בראשית: **למען ינוח שורך וחמרך.** תן לו ניח להתיר שיהא תולש ואוכל עשבים מן הקרקע. או אינו אלא יחבשנו בתוך הבית, אמרת אין זה ניח אלא צער: **בן אמתך.** בעבד הערל הכתוב מדבר: **והגר.** גר תושב:
@622 **ובכל אשר אמרתי אליכם תשמרו.** לעשות כל מצות עשה באזהרה, שכל שמירה שבתורה אזהרה היא במקום לאו: **לא תזכירו.** שלא יאמר לו שמור לי בצד עבודה זרה פלונית או תעמוד עמי ביום עבודה זרה פלונית. דבר אחר ובכל אשר אמרתי אליכם תשמרו ושם אלהים אחרים לא תזכירו ללמדך ששקולה עבודה זרה כנגד כל המצות כלן, והנזהר בה כשומר את כלן: **לא ישמע.** מן הגוי: **על פיך.** שלא תעשה שתפות עם נכרי וישבע לך בעבודה זרה שלו נמצאת שאתה גורם שיזכר על ידך:
@623 **רגלים.** פעמים וכן (במדבר כב כח) כי הכיתני זה שלש רגלים:
@624 **חדש האביב.** שהתבואה מתמלאת בו באביה. לשון אחר אביב, לשון אב, בכור וראשון לבשל פרות: **ולא יראו פני ריקם.** כשתבאו לראות פני ברגלים, הביאו לי עולות:
@625 **וחג הקציר.** הוא חג שבועות: **בכורי מעשיך.** שהוא זמן הבאת בכורים, ששתי הלחם הבאים בעצרת היו מתירין החדש למנחות ולהביא בכורים למקדש, שנאמר (במדבר כח כו) וביום הבכורים וגו' : **וחג האסיף.** הוא חג הסכות: **באספך את מעשיך.** שכל ימות החמה התבואה מתיבשת בשדות ובחג אוספים אותה אל הבית מפני הגשמים:
@626 **שלש פעמים** וגו' **.** לפי שהענין מדבר בשביעית הצרך לומר שלא יסתרסו רגלים ממקומן: **כל זכורך.** הזכרים שבך:
@627 **לא תזבח על חמץ** וגו' **.** לא תשחט את הפסח בארבעה עשר בניסן עד שתבער החמץ: **ולא ילין חלב חגי** וגו' **.** חוץ למזבח: **עד בקר.** יכול אף על המערכה יפסל בלינה, תלמוד לומר (ויקרא ו ב) על מוקדה על המזבח כל הלילה: **ולא ילין.** אין לינה אלא בעמוד השחר שנאמר עד בקר, אבל כל הלילה יכול להעלותו מן הרצפה למזבח:
@628 **ראשית בכורי אדמתך.** אף השביעית חיבת בבכורים, לכך נאמר אף כאן בכורי אדמתך. כיצד, אדם נכנס לתוך שדהו, וראה תאנה שבכרה, כורך עליה גמי לסימן ומקדישה. ואין בכורים אלא משבעת המינין האמורין במקרא (דברים ח ח) ארץ חטה ושעורה וגו' : **לא תבשל גדי.** אף עגל וכבש בכלל גדי, שאין גדי אלא לשון ולד רך, ממה שאתה מוצא בכמה מקומות בתורה שכתוב גדי, והוצרך לפרש אחריו עזים, כגון (בראשית לח יז) אנכי אשלח גדי עזים, (שם שם כ) את גדי העזים, (שם כז ט) שני גדיי עזים, ללמדך, שכל מקום שנאמר גדי סתם, אף עגל וכבש במשמע. ובשלושה מקומות נכתב בתורה אחד לאסור אכילה, ואחד לאסור הנאה, ואחד לאסור בשול:
@629 **הנה אנכי שלח מלאך.** כאן נתבשרו שעתידין לחטוא, ושכינה אומרת להם (שמות לג ג) כי לא אעלה בקרבך: **אשר הכנתי.** אשר זמנתי לתת לכם, זהו פשוטו ומדרשו אל המקום אשר הכינותי כבר מקומי נכר כנגדו, וזה אחד מן המקראות שאומרים, שבית המקדש של מעלה מכון כנגד בית המקדש של מטה:
@630 **אל תמר בו.** לשון המראה, כמו (יהושע א יח) אשר ימרה את פיך: **כי לא ישא לפשעכם.** אינו מלמד בכך, שהוא מן הכת שאין חוטאין, ועוד שהוא שליח ואינו עושה אלא שליחותו: **כי שמי בקרבו.** מחבר לראש המקרא, השמר מפניו כי שמי משתף בו, ורבותינו אמרו זה מטטרו''ן ששמו כשם רבו. מטטרו''ן בגימטריא שדי:
@631 **וצרתי.** כתרגומו ואעיק:
@633 **הרס תהרסם.** לאותם אלהות: **מצבותיהם.** אבנים שהם מציבין להשתחוות להם:
@635 **לא תהיה משכלה.** אם תעשה רצוני: **משכלה.** מפלת נפלים או קוברת את בניה, קרויה משכלה:
@636 **והמתי.** כמו והממתי ותרגומו ואשגש. וכן כל תבה שפעל שלה בכפל האות האחרונה, כשתהפוך לדבר בלשון פעלתי, יש מקומות שנוטל אות הכפולה ומדגיש את האות ונוקדו במלאפום, כגון והמותי, מגזרת (ישעיה כח כח) והמם גלגל עגלתו, (קהלת ב כ) וסבותי, מגזרת (שמו''א ז טז) וסבב בית אל, (תהלים קטז ו) דלותי, מגזרת (ישעיה יט ו) דללו וחרבו, (שם מט טז) על כפים חקותיך, מגזרת (שופטים ה טו) חקקי לב, (שמו''א יב ג) את מי רצותי, מגזרת (איוב כ יט) רצץ עזב דלים. והמתרגם והמותי ואקטל, טועה הוא, שאלו מגזרת מיתה היה, אין ה''א שלה בפת''ח, ולא מ''ם שלו מדגשת, ולא נקודה מלאפום, אלא והמתי, כגון (במד' יד טו) והמתה את העם הזה, והתי''ו מדגשת, לפי שתבא במקום ב' תוי''ן, האחת נשרשת, לפי שאין מיתה בלא ת''ו, והאחרת משמשת, כמו אמרתי, חטאתי, עשיתי, וכן ונתתי, הת''ו מדגשת, שהיא באה במקום שתים, לפי שהיה צריך שלש תוי''ן, שתים ליסוד, כמו (יהושע י יב) ביום תת ה', (קהלת ג יג) מתת אלהים היא, והשלישית לשמוש: **ערף.** שינוסו מפניך ויהפכו לך ערפם:
@637 **הצרעה.** מן שרץ העוף, והיתה מכה אותם בעיניהם ומטילה בהם ארס והם מתים, והצרעה לא עברה את הירדן, והחתי והכנעני הם ארץ סיחון ועוג, לפיכך מכל שבע אמות לא מנה כאן אלא אלו. וחוי אף על פי שהוא מעבר הירדן והלאה, שנו רבותינו במסכת סוטה (סוטה לו א) על שפת הירדן עמדה וזרקה בהם מרה:
@638 **שממה.** ריקנית מבני אדם, לפי שאתם מעט ואין בכם כדי למלאות אותה: **ורבה עליך.** ותרבה עליך:
@639 **עד אשר תפרה.** תרבה, לשון פרי, כמו פרו ורבו:
@640 **ושתי.** לשון השתה, והת''ו מדגשת מפני שבאה תחת שתים, שאין שיתה בלא ת''ו, והאחת לשמוש: **עד הנהר.** פרת: **וגרשתמו.** ותגרשם:
@642 **כי תעבד וגו' כי יהיה לך למקש.** הרי אלו כי משמשין במקום אשר, וכן בכמה מקומות, וזהו לשון אי, שהוא אחד מארבע לשונות שהכי משמש. וגם מצינו בהרבה מקומות אם משמש בלשון אשר, כמו (ויקרא ב יד) ואם תקריב מנחת בכורים, שהיא חובה:
@643 **ואל משה אמר עלה.** פרשה זו נאמרה קדם עשרת הדברות, ובארבעה בסיון נאמר לו עלה:
@644 **ונגש משה לבדו.** אל הערפל:
@645 **ויבא משה ויספר לעם.** בו ביום: **את כל דברי ה'.** מצות פרישה והגבלה: **ואת כל המשפטים.** שבע מצות שנצטוו בני נח. ושבת וכבוד אב ואם ופרה אדמה ודינין שנתנו להם במרה:
@646 **ויכתב משה.** מבראשית ועד מתן תורה, וכתב מצות שנצטוו במרה: **וישכם בבקר.** בחמשה בסיון:
@647 **את נערי.** הבכורות:
@648 **ויקח משה חצי הדם.** מי חלקו, מלאך בא וחלקו: **באגנות.** שני אגנות אחד לחצי דם עולה ואחד לחצי דם שלמים להזות אותם על העם. ומכאן למדו רבותינו שנכנסו אבותינו לברית במילה וטבילה והרצאת דמים שאין הזאה בלא טבילה:
@649 **ספר הברית.** מבראשית ועד מתן תורה ומצות שנצטוו במרה:
@650 **ויזרק.** ענין הזאה, ותרגומו וזרק על מדבחא לכפרא על עמא:
@652 **ויראו את אלהי ישראל.** נסתכלו והציצו ונתחייבו מיתה, אלא שלא רצה הקדוש ברוך הוא לערבב שמחת התורה, והמתין לנדב ואביהוא עד יום חנכת המשכן, ולזקנים עד, (במדבר יא א) ויהי העם כמתאוננים וגו' ותבער בם אש ה' ותאכל בקצה המחנה, בקצינים שבמחנה: **כמעשה לבנת הספיר.** היא היתה לפניו בשעת השעבוד לזכור צרתן של ישראל, שהיו משעבדים במעשה לבנים: **וכעצם השמים לטהר.** משנגאלו היה אור וחדוה לפניו: **וכעצם.** כתרגומו, לשון מראה: **לטהר.** לשון ברור וצלול:
@653 **ואל אצילי.** הם נדב ואביהוא והזקנים: **לא שלח ידו.** מכלל שהיו ראוים להשתלח בהם יד: **ויחזו את האלהים.** היו מסתכלין בו בלב גס מתוך אכילה ושתיה, כך מדרש תנחומא. ואונקלוס לא תרגם כן. אצילי לשון גדולים, כמו (ישעיה מא ט) ומאציליה קראתיך, (במדבר יא כה) ויאצל מן הרוח, (יחזקאל מא ח) שש אמות אצילה:
@654 **ויאמר ה' אל משה.** לאחר מתן תורה: **עלה אלי ההרה והיה שם.** ארבעים יום: **את לחת האבן והתורה והמצוה אשר כתבתי להורתם.** כל שש מאות ושלש עשרה מצות בכלל עשרת הדברות הן, ורבנו סעדיה פרש באזהרות שיסד לכל דבור ודבור מצוות התלויות בו:
@655 **ויקם משה ויהושע משרתו.** לא ידעתי מה טיבו של יהושע כאן. ואומר אני, שהיה התלמיד מלוה לרב עד מקום הגבלת תחומי ההר, שאינו רשאי לילך משם והלאה, ומשם ויעל משה לבדו אל הר האלהים, ויהושע נטה שם אהלו ונתעכב שם כל ארבעים יום, שכן מצינו, כשירד משה (לקמן לב יז) וישמע יהושע את קול העם ברעה, למדנו שלא היה יהושע עמהם:
@656 **ואל הזקנים אמר.** בצאתו מן המחנה: **שבו לנו בזה.** והתעכבו כאן עם שאר העם במחנה להיות נכונים לשפוט לכל איש ריבו: **חור.** בנה של מרים היה, ואביו כלב בן יפנה, שנאמר ויקח לו כלב את אפרת ותלד לו את חור (דברי הימים א' ב יט) . אפרת זו מרים, כדאיתא בסוטה (יא ב) : **מי בעל דברים.** מי שיש לו דין:
@658 **ויכסהו הענן.** רבותינו חולקין בדבר. יש מהם אומרים אלו ששה ימים שמראש חדש עד עצרת יום מתן תורה: **ויכסהו הענן.** להר: **ויקרא אל משה ביום השביעי.** לומר עשרת הדברות, ומשה וכל בני ישראל עומדים, אלא שחלק הכתוב כבוד למשה, ויש אומרים ויכסהו הענן למשה ששה ימים לאחר עשרת הדברות, והם היו בתחלת ארבעים יום שעלה משה לקבל הלוחות, ולמדך, שכל הנכנס למחנה שכינה טעון פרישה ששה ימים:
@660 **בתוך הענן.** ענן זה כמין עשן הוא, ועשה לו הקדוש ברוך הוא למשה שביל [ נ''א : חפה] בתוכו:
@662 **ויקחו לי תרומה.** לי לשמי: **תרומה.** הפרשה, יפרישו לי מממונם נדבה: **ידבנו לבו.** לשון נדבה, והוא לשון רצון טוב, פרישנ''ט בלעז : **תקחו את תרומתי.** אמרו רבותינו שלש תרומות אמורות כאן, אחת תרומת בקע לגלגלת, שנעשו מהם האדנים, כמו שמפורש באלה פקודי (שמות לח כו. כז) , ואחת תרומת המזבח בקע לגלגלת לקפות לקנות מהן קרבנות צבור, ואחת תרומת המשכן נדבת כל אחד ואחד. שלשה עשר דברים האמורים בענין כלם הצרכו למלאכת המשכן או לבגדי כהנה, כשתדקדק בהם:
@663 **זהב וכסף ונחשת** וגו' **.** כלם באו בנדבה, איש איש מה שנדבו לבו, חוץ מן הכסף שבא בשוה מחצית השקל לכל אחד, ולא מצינו בכל מלאכת המשכן, שהצרך שם כסף יותר, שנאמר (שמות לח כו, כז) וכסף פקודי העדה וגו' בקע לגלגלת וגו' , ושאר הכסף הבא שם בנדבה עשאוה לכלי שרת:
@664 **ותכלת.** צמר צבוע בדם חלזון, וצבעו ירוק: **וארגמן.** צמר צבוע ממין צבע ששמו ארגמן: **ושש.** הוא פשתן: **ועזים.** נוצה של עזים, לכך תרגם אנקלוס ומעזי, הבא מן העזים, ולא עזים עצמם, שתרגום של עזים עזיא:
@665 **מאדמים.** צבועות היו אדום לאחר עבודן: **תחשים.** מין חיה, ולא היתה אלא לשעה והרבה גונים היו לה, לכך מתרגם ססגונא, ששש ומתפאר בגונין שלו: **ועצי שטים.** מאין היו להם במדבר, פרש רבי תנחומא יעקב אבינו צפה ברוח הקדש, שעתידין ישראל לבנות משכן במדבר, והביא ארזים למצרים ונטעם, וצוה לבניו לטלם עמהם, כשיצאו ממצרים:
@666 **שמן למאור.** שמן זית זך להעלות נר תמיד: **בשמים לשמן המשחה.** שנעשה למשוח כלי המשכן והמשכן לקדשו, והצרכו לו בשמים כמו שמפורש בכי תשא (שמות ל כג. כה) : **ולקטרת הסמים.** שהיו מקטירין בכל ערב ובקר, כמו שמפורש בואתה תצוה (שמות ל ז. ח) ולשון קטרת העלאת קיטור ותמרות עשן:
@667 **אבני שהם.** שתים הצרכו שם לצורך האפוד האמור בואתה תצוה (שמות כח יב) : **מלאים.** על שם שעושין להם בזהב מושב כמין גמא ונותנין האבן שם למלאות הגמא, קרויים אבני מלאים, ומקום המושב קרוי משבצות: **לאפוד ולחשן.** אבני השהם לאפוד, ואבני המלאים לחשן, וחשן ואפוד מפורשים בואתה תצוה, והם מיני תכשיט:
@668 **ועשו לי מקדש.** ועשו לשמי בית קדשה:
@669 **ככל אשר אני מראה אותך.** כאן את תבנית המשכן. המקרא הזה מחבר למקרא שלמעלה המנו ועשו לי מקדש ככל אשר אני מראה אותך: **וכן תעשו.** לדורות אם יאבד אחד מן הכלים או כשתעשו לי כלי בית עולמים, כגון שלחנות ומנורות וכיורות ומכונות שעשה שלמה, כתבנית אלו תעשו אותם. ואם לא היה המקרא מחבר למעלה המנו, לא היה לו לכתוב וכן תעשו אלא כן תעשו, והיה מדבר על עשית אהל מועד וכליו:
@670 **ועשו ארון.** כמין ארונות שעושים בלא רגלים, עשוים כמין ארגז שקורין אישקרי''ן בלעז , יושב על שוליו:
@671 **מבית ומחוץ תצפנו.** שלשה ארונות עשה בצלאל, שתים של זהב ואחד של עץ, וארבע כתלים ושולים לכל אחד ופתוחים מלמעלה, נתן של עץ בתוך של זהב ושל זהב בתוך של עץ, וחפה שפתו העליונה בזהב, נמצא מצפה מבית ומחוץ: **זר זהב.** כמין כתר מקיף לו סביב למעלה משפתו, שעשה הארון החיצון גבוה מן הפנימי עד שעלה למול עובי הכפורת ולמעלה המנו משהו, וכשהכפורת שוכב על עובי הכתלים, עולה הזר למעלה מכל עובי הכפורת כל שהוא, והוא סימן לכתר תורה:
@672 **ויצקת.** לשון התכה כתרגומו: **פעמתיו.** כתרגומו זויתיה. ובזויות העליונות סמוך לכפרת היו נתונות שתים מכאן ושתים מכאן לרחבו של ארון, והבדים נתונים בהם, וארכו של ארון מפסיק בין הבדים, אמתים וחצי בין בד לבד, שיהיו שני בני אדם, הנושאים את הארון, מהלכין ביניהם, וכן מפורש במנחות בפרק שתי הלחם (צח ב) **ושתי טבעות על צלעו האחת.** הן הן הארבע טבעות שבתחלת המקרא, ופרש לך היכן היו, והוי''ו זו יתרה היא ופתרונו כמו שתי טבעות, ויש לך לישבה כן ושתים מן הטבעות האלו על צלעו האחת: **צלעו.** צדו:
@673 **בדי.** מוטות:
@675 **לא יסרו ממנו.** לעולם:
@676 **ונתת אל הארן.** כמו בארון: **העדות.** התורה שהיא לעדות ביני וביניכם, שצויתי אתכם מצות הכתובות בה:
@677 **כפרת.** כסוי על הארון שהיה פתוח מלמעלה ומניחו עליו כמין דף: **אמתים וחצי ארכה.** כארכו של ארון, ורחבה כרחבו של ארון, ומנחת על עובי הכתלים ארבעתם, ואף על פי שלא נתן שעור לעביה, פרשו רבותינו שהיה עביה טפח:
@678 **כרבים.** דמות פרצוף תינוק להם: **מקשה תעשה אתם.** שלא תעשם בפני עצמם ותחברם בראשי הכפרת לאחר עשיתם כמעשה צורפים, שקורין שולדי''ץ [מלחמים] אלא הטל זהב הרבה בתחלת עשית הכפרת והכה בפטיש ובקרנס באמצע, וראשין בולטין למעלה וצייר הכרובים בבליטת קצותיו: **מקשה.** בטידי''ץ בלעז [עשוי בהכאה] . כמו (דניאל ה ו) דא לדא נקשן: **קצות הכפורת.** ראשי הכפרת:
@679 **ועשה כרוב אחד מקצה.** שלא תאמר שנים כרובים לכל קצה וקצה, לכך הצרך לפרש כרוב אחד מקצה מזה: **מן הכפרת.** עצמה תעשו את הכרובים. זהו פרושו של מקשה תעשה אותם, שלא תעשם בפני עצמם ותחברם לכפרת:
@680 **פרשי כנפים.** שלא תעשה כנפיהם שוכבים, אלא פרושים וגבוהים למעלה אצל ראשיהם, שיהא עשרה טפחים בחלל בין הכנפים לכפרת, כדאיתא בסכה (דף ה ב) :
@681 **ואל הארן תתן את העדות.** לא ידעתי למה נכפל, שהרי כבר נאמר (פסוק טז) ונתת אל הארון את העדות. ויש לומר שבא ללמד, שבעודו ארון לבדו בלא כפרת, יתן תחלה העדות לתוכו, ואחר כך יתן את הכפרת עליו. וכן מצינו כשהקים את המשכן נאמר (שמות מ כ) ויתן את העדות אל הארון, ואחר כך ויתן את הכפורת על הארון מלמעלה:
@682 **ונועדתי.** כשאקבע מועד לך לדבר עמך, אותו מקום אקבע למועד שאבא שם לדבר אליך: **ודברתי אתך מעל הכפורת.** ובמקום אחר הוא אומר (ויקרא א א) וידבר ה' אליו מאהל מועד לאמר, זה המשכן מחוץ לפרכת, נמצאו שני כתובים מכחישים זה את זה, בא הכתוב השלישי והכריע ביניהם (במדבר ז פט) ובבא משה אל אהל מועד וישמע את הקול מדבר אליו מעל הכפרת וגו' , משה היה נכנס למשכן וכיון שבא בתוך הפתח, קול יורד מן השמים לבין הכרובים, ומשם יוצא ונשמע למשה באהל מועד: **ואת כל אשר אצוה אותך אל בני ישראל.** הרי וי''ו זו יתרה וטפלה, וכמוהו הרבה במקרא, וכה תפתר ואת אשר אדבר עמך שם, את כל אשר אצוה אותך אל בני ישראל הוא.
@683 **קמתו.** גובה רגליו עם עובי השלחן:
@684 **זר זהב.** סימן לכתר מלכות, שהשלחן שם עושר וגדלה, כמו שאומרים שלחן מלכים:
@685 **מסגרת.** כתרגומו גדנפא, ונחלקו חכמי ישראל בדבר יש אומרים, למעלה היתה סביב לשלחן, כמו לבזבזין שבשפת שלחן שרים, ויש אומרים, למטה היתה תקועה מרגל לרגל בארבע רוחות השלחן, ודף השלחן שוכב על אותה מסגרת: **ועשית זר זהב למסגרתו.** הוא זר האמור למעלה, ופרש לך כאן שעל המסגרת היתה:
@687 **לעמת המסגרת תהיין הטבעות.** ברגלים תקועות כנגד ראשי המסגרת: **לבתים לבדים.** אותן הטבעות יהיו בתים להכניס בהן הבדים: **לבתים.** לצורך בתים: **לבדים.** כתרגומו אתרא לאריחיא:
@688 **ונשא בם.** לשון נפעל, יהיה נשא בם את השלחן:
@689 **ועשית קערתיו וכפתיו.** קערותיו זה הדפוס שהיה עשוי כדפוס הלחם, והלחם היה עשוי כמין תבה פרוצה משתי רוחותיה, שולים לו למטה וקופל מכאן ומכאן כלפי מעלה כמין כתלים, ולכך קרוי לחם הפנים, שיש לו פנים רואין לכאן ולכאן לצדי הבית מזה ומזה, ונותן ארכו לרחבו של שלחן, וכתליו זקופים כנגד שפת השלחן, והיה עשוי לו דפוס זהב ודפוס ברזל, בשל ברזל הוא נאפה וכשמוציאו מן התנור נותנו בשל זהב עד למחר בשבת שמסדרו על השלחן, ואותו הדפוס קרוי קערה: **וכפתיו.** בזכין שנותנים בהם לבונה, ושתים היו לשני קמצי לבונה שנותנין על שתי המערכות, שנאמר (ויקרא כד ז) ונתת על המערכת לבונה זכה: **וקשותיו.** הן כמין חצאי קנים חלולים הנסדקין לארכן דגמתן עשה של זהב ומסדר שלשה על ראש כל לחם, שישב לחם האחד על גבי אותן הקנים ומבדילין בין לחם ללחם כדי שתכנס הרוח ביניהם ולא יתעפשו, ובלשון ערבי כל דבר חלול קרוי קסו''ה: **ומנקיתיו.** תרגומו ומכילתיה, הן סניפים, כמין יתדות זהב עומדין בארץ וגבוהים עד למעלה מן השלחן הרבה כנגד גובה מערכת הלחם, ומפצלים ששה פצולים זה למעלה מזה, וראשי הקנים שבין לחם ללחם סמוכין על אותן פצולין, כדי שלא יכבד משא הלחם העליונים על התחתונים וישברו ולשון מכילתיה, סובלותיו, כמו (ירמיה ו יא) נלאיתי הכיל, אבל לשון מנקיות איני יודע, איך נופל על סניפין. ויש מחכמי ישראל אומרים קשותיו אלו סניפין, שמקשין אותו ומחזיקין אותו שלא ישבר, ומנקיותיו אלו הקנים שמנקין אותו שלא יתעפש, אבל אונקלוס שתרגם ומכילתיה היה שונה כדברי האומר מנקיות הן סניפין: **אשר יסך בהן.** אשר יכסה בהן, ועל קשותיו הוא אומר אשר יסך, שהיו עליו כמין סכך וכסוי, וכן במקום אחר הוא אומר (במדבר ד ז) ואת קשות הנסך וזה וזה, יסך והנסך, לשון סכך וכסוי הם:
@690 **לחם פנים.** שיש לו פנים כמו שפרשתי, ומנין הלחם וסדר מערכותיו מפורשים באמור אל הכהנים:
@691 **מקשה תעשה המנורה.** שלא יעשנה חליות, ולא יעשה קניה ונרותיה איברים איברים, ואחר כך ידביקם כדרך הצורפין, שקורין שולדי''ר בלעז אלא כלה באה מחתיכה אחת, ומקיש בקרנס וחותך בכלי האמנות ומפריד הקנים אלך ואלך: **מקשה.** תרגומו נגיד, לשון המשכה שממשיך את האיברים מן העשת לכאן ולכאן בהקשת הקרנס, ולשון מקשה מכת קרנס, בטידי''ץ בלעז [עשוי בהכאה] כמו (דניאל ה ו) דא לדא נקשן: **תעשה המנורה.** מאליה, לפי שהיה משה מתקשה בה, אמר לו הקדוש ברוך הוא השלך את הככר לאור והיא נעשית מאליה, לכך לא נכתב תעשה: **ירכה.** הוא הרגל של מטה העשוי כמין תבה, ושלשה רגלים יוצאין המנה ולמטה: **וקנה.** הקנה האמצעי שלה העולה באמצע הירך זקוף כלפי מעלה, ועליו נר האמצעי עשוי כמין בזיך לצוק השמן לתוכו ולתת הפתילה: **גביעיה.** הן כמין כוסות שעושין מזכוכית ארכים וקצרים, וקורין להם מדרינ''ש בלעז [גביעים] , ואלו עשויין מזהב ובולטין ויוצאין מכל קנה וקנה כמנין שנתן בהם הכתוב, ולא היו בה אלא לנוי: **כפתריה.** כמין תפוחים עגולין סביב, בולטין סביבות הקנה האמצעי, כדרך שעושין למנורות שלפני השרים וקורין להם פומיל''ש בלעז [כפתורים] , ומנין שלהם כתוב בפרשה, כמה כפתורים בולטין ממנה, וכמה חלק בין כפתור לכפתור: **ופרחיה.** ציורין עשויין בה כמין פרחים: **ממנה יהיו.** הכל מקשה יוצא מתוך חתכת העשת, ולא יעשם לבדם וידביקם:
@692 **יצאים מצדיה.** לכאן ולכאן באלכסון, נמשכים ועולין עד כנגד גבהה של מנורה, שהוא קנה האמצעי, ויוצאין מתוך קנה האמצעי זה למעלה מזה, התחתון ארוך, ושל מעלה קצר המנו והעליון קצר המנו, לפי שהיה גובה ראשיהן שוה לגבהו של קנה האמצעי השביעי, שממנו יוצאים ששת הקנים:
@693 **משקדים.** כתרגומו, מצוירים היו כדרך שעושין לכלי כסף וזהב שקורין ניילי''ר : **ושלשה גבעים.** בולטין מכל קנה וקנה: **כפתר ופרח.** היה לכל קנה וקנה:
@694 **ובמנרה ארבעה גבעים.** בגופה של מנורה היו ארבעה גביעים אחד בולט בה למטה מן הקנים, והשלשה למעלה מן יציאת הקנים היוצאים מצדיה: **משקדים כפתריה ופרחיה.** זה אחד מחמשה מקראות שאין להם הכרע, שאין ידוע אם גביעים משקדים או משקדים כפתוריה ופרחיה:
@695 **וכפתר תחת שני הקנים.** מתוך הכפתור היו הקנים נמשכים משני צדיה אלך ואלך. כך שנינו במלאכת המשכן (פרק י) גבהה של מנורה שמונה עשר טפחים, הרגלים והפרח שלשה טפחים, הוא הפרח האמור בירך, שנאמר (במדבר ח ד) עד ירכה עד פרחה, וטפחיים חלק, וטפח שבו גביע מהארבעה גביעים, וכפתור ופרח משני כפתורים ושני פרחים האמורים במנורה עצמה, שנאמר משקדים כפתוריה ופרחיה, למדנו שהיו בקנה שני כפתורים ושני פרחים לבד מן השלשה כפתורים, שהקנים נמשכין מתוכן, שנאמר וכפתור תחת שני הקנים, וגו' וטפחים חלק, וטפח כפתור ושני קנים יוצאים ממנו אלך ואלך נמשכים ועולים כנגד גבהה של מנורה, וטפחיים חלק, וטפח כפתור ושני קנים יוצאים ממנו, וטפחיים חלק וטפח כפתור ושני קנים יוצאים ממנו ונמשכים ועולין כנגד גבהה של מנורה וטפחיים חלק, נשתיירו שם שלשה טפחים, שבהם שלשה גביעים וכפתור ופרח. נמצאו גביעים עשרים ושנים שמונה עשר לששה קנים, שלשה לכל אחד ואחד, וארבעה בגופה של מנורה, הרי עשרים ושנים, ואחד עשר כפתורים ששה בששת הקנים, ושלשה בגופה של מנורה, שהקנים יוצאים מהם, ושנים עוד במנורה, שנאמר משקדים כפתוריה, מעוט כפתורים שנים האחד למטה אצל הירך, והאחד בשלשת טפחים העליונים עם שלשת הגביעים, ותשעה פרחים היו לה ששה לששת הקנים, שנאמר (פסוק לג) בקנה האחד כפתור ופרח, ושלשה למנורה, שנאמר משקדים כפתוריה ופרחיה, ומיעוט פרחים שנים, ואחד האמור בפרשת בהעלותך (במדבר ח ד) עד ירכה עד פרחה. ואם תדקדק במשנה זו הכתובה למעלה, תמצאם כמנינם איש איש במקומו:
@697 **את נרתיה.** כמין בזכין שנותנין בתוכם השמן והפתילות: **והאיר על עבר פניה.** עשה ששת הנרות שבראשי הקנים, היוצאים מצדיה, מסבים כלפי האמצעי, כדי שיהיו הנרות כשתדליקם מאירים אל עבר פניה, מוסב אורם אל צד פני הקנה האמצעי, שהוא גוף המנורה:
@698 **ומלקחיה.** הם הצבתים העשויין לקח בהם הפתילה מתוך השמן לישבן ולמשכן בפי הנרות, ועל שם שלוקחים בהם קרויים מלקחים. וצבתהא שתרגם אנקלוס, לשון צבת, טינליי''א בלעז : **ומחתתיה.** הם כמין בזכין קטנים, שחותה בהן את האפר שבנר בבקר בבקר, כשהוא מטיב את הנרות מאפר הפתילות, שדלקו הלילה וכבו, ולשון מחתה פוישידויר''א בלעז [יעה] , כמו (ישעיה ל יד) לחתות אש מיקוד:
@699 **ככר זהב טהור.** שלא יהיה משקלה עם כל כליה אלא ככר, לא פחות ולא יותר, והככר של חול ששים מנה ושל קדש היה כפול, מאה עשרים מנה, והמנה הוא ליטרא ששוקלין בה כסף למשקל קולוני''א והם מאה זהובים, עשרים וחמשה סלעים והסלע ארבעה זהובים:
@700 **וראה ועשה.** ראה כאן בהר תבנית שאני מראה אותך, מגיד שנתקשה משה במעשה המנורה, עד שהראה לו הקדוש ברוך הוא מנורה של אש: **אשר אתה מראה.** כתרגומו דאת מתחזי בטורא, אלו היה נקוד מראה בפת''ח, היה פתרונו אתה מראה לאחרים, עכשו שנקוד חטף קמ''ץ, פתרונו דאת מתחזי, שאחרים מראים לך, שהנקוד מפריד בין עשה לנעשה:
@701 **ואת המשכן תעשה עשר יריעת.** להיות לו לגג ולמחצות מחוץ לקרשים שהיריעות תלויות מאחוריהן לכסותן: **שש משזר ותכלת וארגמן ותולעת שני.** הרי ארבע מינין יחד בכל חוט וחוט אחד של פשתים ושלשה של צמר, וכל חוט וחוט כפול ששה הרי ארבעה מינין, כשהן שזורין יחד, עשרים וארבע כפלים לחוט: **כרבים מעשה חשב.** כרובים היו מצוירין בהם באריגתן, ולא ברקימה שהוא מעשה מחט, אלא באריגה בשני כתלים, פרצוף אחד מכאן ופרצוף אחד מכאן, ארי מצד זה ונשר מצד זה, וכמו שאורגין חגורות של משי, שקורין בלעז פיישי''ש :
@703 **תהיין חברת.** תופרן במחט זו בצד זו, חמש לבד וחמש לבד: **אשה אל אחותה.** כך דרך המקרא לדבר בדבר שהוא לשון נקבה. ובדבר שהוא לשון זכר אומר איש אל אחיו, כמו שנאמר בכרובים (שמות כה כ) ופניהם איש אל אחיו:
@704 **ללאת.** לצול''ש בלעז [שרוכים] וכן תרגם אנקלוס ענובין, לשון עניבה: **מקצה בחברת.** באותה יריעה שבסוף החבור, קבוצת חמשת היריעות קרויה חוברת: **וכן תעשה בשפת היריעה הקיצונה במחברת השנית.** באותה יריעה שהיא קיצונה, לשון קצה, כלומר לסוף החוברת:
@705 **מקבילת הללאת אשה אל אחותה.** שמור שתעשה הלולאות במדה אחת מכונת הבדלתן זו מזו, וכמדתן ביריעה זו כן יהא בחברתה, כשתפרוש חוברת אצל חוברת, יהיו הלולאות של יריעה זו מכונות כנגד לולאות של זו. וזהו לשון מקבילות זו כנגד זו. תרגומו של נגד, קביל. היריעות ארכן עשרים ושמונה ורחבן ארבע, וכשחבר חמש יריעות יחד, נמצא רחבן עשרים, וכן החוברת השנית. והמשכן ארכו שלשים מן המזרח למערב, שנאמר עשרים קרש לפאת נגבה תימנה (פסוק יח) וכן לצפון, וכל קרש אמה וחצי האמה, הרי שלשים מן המזרח למערב. רוחב המשכן מן הצפון לדרום עשר אמות. שנאמר (כו כב. כג) ולירכתי המשכן ימה וגו' , ושני קרשים למקצעות, הרי עשר. ובמקומם אפרשם למקראות הללו. נותן היריעות ארכן לרחבו של משכן, עשר אמות אמצעיות לגג חלל רוחב המשכן, ואמה מכאן ואמה מכאן לעובי ראשי הקרשים שעבין אמה, נשתירו שש עשרה אמה, שמונה לצפון ושמונה לדרום מכסות קומת הקרשים שגבהן עשר, נמצאו שתי אמות התחתונות מגלות. רחבן של יריעות ארבעים אמה, כשהן מחברות עשרים אמה לחוברת, שלשים מהן לגג חלל המשכן לארכו ואמה כנגד עובי ראשי הקרשים שבמערב, ואמה לכסות עובי העמודים שבמזרח, שלא היו קרשים במזרח אלא ארבעה עמודים, שהמסך פרוש ותלוי בווין שבהן כמין וילון. נשתירו שמונה אמות התלויין על אחורי הקרשים שבמערב ושתי אמות התחתונות מגלות. זו מצאתי בברייתא דארבעים ותשע מדות. אבל במסכת שבת (צח ב) אין היריעות מכסות את עמודי המזרח, ותשע אמות תלויות אחורי המשכן, והכתוב מסייענו ונתת את הפרוכת תחת הקרסים, ואם כדברי הברייתא הזאת, נמצאת פרוכת משוכה מן הקרסים ולמערב אמה:
@706 **קרסי זהב.** פירמייל''ץ בלעז ומכניסין ראשן אחד בלולאות שבחוברת זו וראשן אחד בלולאות שבחוברת זו ומחברן בהן:
@707 **יריעות עזים.** מנוצה של עזים: **לאהל על המשכן.** לפרוש אותן על היריעות התחתונות:
@708 **שלשים באמה.** שכשנותן ארכן לרוחב המשכן, כמו שנתן את הראשונות, נמצאו אלו עודפות אמה מכאן ואמה מכאן לכסות אחת מהשתי אמות, שנשארו מגלות מן הקרשים, והאמה התחתונה של קרש, שאין היריעה מכסה אותו היא האמה התחובה בנקב האדן, שהאדנים גבהן אמה:
@709 **וכפלת את היריעה הששית.** העודפת באלו העליונות יותר מן התחתונות: **אל מול פני האהל.** חצי רחבה היה תלוי וכפול על המסך שבמזרח כנגד הפתח, דומה לכלה צנועה המכסה בצעיף על פניה:
@712 **וסרח העדף ביריעת האהל.** על יריעות המשכן. יריעות האהל הן העליונות של עזים שקרויים אהל, כמו שכתוב בהן (פסוק ז) לאהל על המשכן, וכל אהל האמור בהן אינו אלא לשון גג, שמאהילות ומסככות על התחתונות, והן היו עודפות על התחתונות חצי היריעה למערב, שהחצי של יריעה אחת עשרה היתרה, היה נכפל אל מול פני האהל, נשארו שתי אמות רוחב חציה עודף על רוחב התחתונות: **תסרח על אחרי המשכן.** לכסות שתי אמות שהיו מגלות בקרשים:
@713 **והאמה מזה והאמה מזה.** לצפון ולדרום: **בעדף בארך יריעת האהל.** שהן עודפות על אורך יריעות המשכן שתי אמות: **יהיה סרוח על צדי המשכן.** לצפון ולדרום, כמו שפירשתי למעלה. למדה תורה דרך ארץ שיהא אדם חס על היפה: **אחרי המשכן.** הוא צד מערבי, לפי שהפתח במזרח שהם פניו, וצפון ודרום קרויין צדדין לימין ולשמאל:
@714 **מכסה לאהל.** לאותו גג של יריעות עזים עשה עוד מכסה אחד של עורות אילם מאדמים, ועוד למעלה ממנו מכסה עורות תחשים, ואותן מכסאות לא היו מכסין אלא את הגג, ארכן שלשים ורחבן עשר, אלו דברי רבי נחמיה, ולדברי רבי יהודה מכסה אחד היה, חציו של עורות אילים מאדמים, וחציו של עורות תחשים:
@715 **ועשית את הקרשים.** היה לו לומר ועשית קרשים, כמה שנאמר בכל דבר ודבר, ומהו הקרשים, מאותן העומדין ומיחדין לכך. יעקב אבינו צפה ברוח הקדש ונטע ארזים במצרים, וכשמת צוה לבניו להעלותם עמהם כשיצאו ממצרים, אמר להם, שעתיד הקדוש ברוך הוא לצוות אתכם לעשות משכן במדבר מעצי שטים, ראו שיהיו מזמנים בידכם. הוא שיסד הבבלי בפיוט שלו טס מטע מזורזים קורות בתינו ארזים, שנזדרזו להיות מוכנים בידם מקדם לכן: **עצי שטים עומדים.** אישטנטיבי''ש בלעז שיהא אורך הקרשים זקוף למעלה בקירות המשכן, ולא תעשה הכתלים בקרשים שוכבים להיות רוחב הקרשים לגובה הכתלים קרש על קרש:
@716 **עשר אמות ארך הקרש.** למדנו שגבהו של משכן עשר אמות: **ואמה וחצי האמה רחב.** למדנו ארכו של משכן לעשרים קרשים, שהיו בצפון ובדרום מן המזרח למערב, שלשים אמה:
@717 **שתי ידות לקרש האחד.** היה חורץ את הקרש מלמטה, באמצעו בגובה אמה, מניח רביע רחבו מכאן ורביע רחבו מכאן, והן הן הידות, והחריץ חצי רוחב הקרש באמצע, ואותן הידות מכניס באדנים שהיו חלולים, והאדנים גבהן אמה ויושבים רצופים ארבעים זה אצל זה, וידות הקרש, הנכנסים בחלל האדנים, חרוצות משלשת צדיהן, רוחב החריץ כעובי שפת האדן, שיכסה הקרש את כל ראש האדן, שאם לא כן נמצא רוח בין קרש לקרש כעובי שפת שני האדנים שיפסיקו ביניהם, וזהו שנאמר (לקמן כד) והיו תאמים מלמטה, שיחרוץ את צדי הידות, כדי שיתחברו הקרשים זה אצל זה: **משלבת.** עשויות כמין שליבות סלם, מבדלות זו מזו ומשפין ראשיהם לכנס בתוך חלל האדן כשליבה, הנכנסת בנקב עמודי הסלם: **אשה אל אחתה.** מכונות זו כנגד זו, שיהיו חריציהם שוים, זו כמדת זו, כדי שלא יהיו שתי ידות זו משוכה לצד פנים וזו משוכה לצד חוץ בעובי הקרש שהוא אמה. ותרגום של ידות צירין, לפי שדומות לצירי הדלת הנכנסים בחורי המפתן:
@718 **לפאת נגבה תימנה.** אין פאה זו לשון מקצוע, אלא כל הרוח קרויה פאה, כתרגומו לרוח עבר דרומא:
@722 **ולירכתי.** לשון סוף, כתרגומו ולסיפי, ולפי שהפתח במזרח, קרוי המזרח פנים, והמערב אחורים, וזהו סוף, שהפנים הוא הראש: **תעשה ששה קרשים.** הרי תשע אמות רוחב:
@723 **ושני קרשים תעשה למקצעת.** אחד למקצוע צפונית מערבית ואחד למערבית דרומית, כל שמונה קרשים בסדר אחד הן, אלא שאלו השנים אינן בחלל המשכן, אלא חצי אמה מזו וחצי אמה מזו נראות בחלל להשלים רחבו לעשר, והאמה מזה והאמה מזה באות כנגד אמת עובי קרשי המשכן, הצפון והדרום, כדי שיהא המקצוע מבחוץ שוה:
@724 **ויהיו.** כל הקרשים תואמים זה לזה מלמטה שלא יפסיק עובי שפת שני האדנים ביניהם להרחיקם זו מזו. זהו שפרשתי (לעיל יז) שיהיו צירי הידות חרוצים מצדיהן, שיהא רוחב הקרש בולט לצדיו חוץ ליד הקרש לכסות את שפת האדן, וכן הקרש שאצלו, ונמצאו תואמים זה לזה. וקרש המקצוע שבסדר המערב חרוץ לרחבו בעביו כנגד חריץ של צד קרש הצפוני והדרומי, כדי שלא יפרידו האדנים ביניהם: **ויחדו יהיו תמים.** כמו תואמים: **על ראשו.** של קרש: **אל הטבעת האחת.** כל קרש וקרש היה חרוץ למעלה ברחבו שני חריצין בשני צדיו כדי עובי טבעת, ומכניסו בטבעת אחת, נמצא מתאים לקרש שאצלו. אבל אותן טבעות לא ידעתי אם קבועות הן אם מטולטלות. ובקרש שבמקצוע היה טבעת בעובי הקרש הדרומי והצפוני, וראש קרש המקצוע שבסדר מערב נכנס לתוכו, נמצאו שני הכתלים מחברים: **כן יהיה לשניהם.** לשני הקרשים שבמקצוע, לקרש שבסוף צפון ולקרש המערבי וכן לשני המקצועות:
@725 **והיו שמנה קרשים.** הם האמורים למעלה (פסוקים כב. כג) תעשה ששה קרשים ושני קרשים תעשה למקצעות, נמצאו שמנה קרשים בסדר מערבי. כך שנויה במשנת מעשה סדר הקרשים במלאכת המשכן (פרק א) היה עושה את האדנים חלולים, וחורץ את הקרש מלמטה רביע מכאן ורביע מכאן, והחריץ חציו באמצע, ועשה לו שתי ידות כמין שני חמוקין ולי נראה שהגרסא כמין שני חוקין, כמין שתי שליבות סלם המובדלות זו מזו ומשפות להכנס בחלל האדן כשליבה, הנכנסת בנקב עמוד הסלם, והוא לשון משלבות, עשויות כמין שליבה, ומכניסן לתוך שני אדנים, שנאמר (פסוק יט) שני אדנים ושני אדנים, וחורץ את הקרש מלמעלה אצבע מכאן ואצבע מכאן ונותן לתוך טבעת אחת של זהב כדי שלא יהיו נפרדים זה מזה, שנאמר (פסוק כד) והיו תואמים מלמטה וגו' . כך היא המשנה, והפרוש שלה הצעתי למעלה בסדר המקראות:
@726 **בריחם.** כתרגומו עברין ובלעז אישבר''ש : **חמשה לקרשי צלע המשכן.** אלו חמשה שלשה הן, אלא שהבריח העליון והתחתון עשוי משתי חתכות, זה מבריח עד חצי הכתל וזה מבריח עד חצי הכתל, זה נכנס בטבעת מצד זה וזה נכנס בטבעת מצד זה, עד שמגיעין זה לזה, נמצאו שעליון ותחתון שנים שהן ארבע, אבל האמצעי ארכו כנגד כל הכתל ומבריח מקצה הכתל ועד קצהו, שנאמר (פסוק כח) והבריח התיכון וגו' מבריח מן הקצה אל הקצה, שהעליונים והתחתונים היו להן טבעות בקרשים להכנס לתוכן שתי טבעות לכל קרש, משלשים בתוך עשר אמות של גובה הקרש, חלק אחד מן הטבעת העליונה ולמעלה וחלק אחד מן התחתונה ולמטה, וכל חלק הוא רביע אורך הקרש, ושני חלקים בין טבעת לטבעת, כדי שיהיו כל הטבעות מכונות זו כנגד זו. אבל לבריח התיכון אין טבעות, אלא הקרשים נקובין בעביין והוא נכנס בהם דרך הנקבים שהם מכונין זה מול זה, וזהו שנאמר בתוך הקרשים. הבריחים העליונים והתחתונים שבצפון ושבדרום אורך כל אחת חמשה עשר אמה, והתיכון ארכו שלשים אמה, וזהו מן הקצה אל הקצה, מן המזרח ועד המערב, וחמשה בריחים שבמערב אורך העליונים והתחתונים שש אמות והתיכון ארכו שתים עשרה כנגד רוחב שמונה קרשים, כך היא מפרשת במלאכת המשכן (פרק א) :
@729 **בתים לבריחם.** הטבעות, שתעשה בהן, יהיו בתים להכניס בהן הבריחים: **וצפית את הבריחם זהב.** לא שהיה הזהב מדבק על הבריחים, שאין עליהם שום צפוי, אלא בקרש היה קובע כמין שני פיפיות של זהב כמין שני סדקי קנה חלול, וקובען אצל הטבעות לכאן ולכאן ארכן ממלא את רוחב הקרש מן הטבעת לכאן וממנה לכאן והבריח נכנס לתוכו וממנו לטבעת ומן הטבעת לפה השני, נמצאו הבריחים מצפין זהב, כשהן תחובין בקרשים, והבריחים הללו מבחוץ היו בולטות והטבעות והפיפיות לא היו נראות בתוך המשכן אלא כל הכתל חלק מבפנים:
@730 **והקמת את המשכן.** לאחר שיגמר הקימהו: **הראית בהר.** קדם לכן, שאני עתיד ללמדך ולהראותך סדר הקמתו:
@731 **פרכת.** לשון מחצה הוא, ובלשון חכמים פרגוד, דבר המבדיל בין המלך ובין העם: **תכלת וארגמן.** כל מין ומין היה כפול, בכל חוט וחוט ששה חוטין: **מעשה חשב.** כבר פרשתי שזו היא אריגה שלשני קירות, והציורין שמשני עבריה אינן דומין זה לזה: **כרובים.** ציורין של בריות יעשה בה:
@732 **ארבעה עמודי שטים.** תקועים בתוך ארבעה אדנים ואונקליות קבועין בהן עקומים למעלה להושיב עליהן כלונס שראש הפרוכת כרוך בה, והאונקליות הן הווין, שהרי כמין ווין הן עשוים, והפרכת ארכה עשר אמות לרחבו של משכן, ורחבה עשר אמות כגבהן של קרשים, פרוסה בשלישית של משכן, שיהא המנה ולפנים עשר אמות, והמנה ולחוץ עשרים אמה, נמצא בית קדשי הקדשים עשר על עשר, שנאמר ונתת את הפרכת תחת הקרסים, המחברים את שתי חוברות של יריעות המשכן, ורוחב החוברת עשרים אמה, וכשפרשה על גג המשכן מן הפתח למערב, כלתה בשני שלישי המשכן, והחוברת השניה כסתה שלישו של משכן, והמותר תלוי לאחוריו לכסות את הקרשים:
@735 **ושמת את השלחן.** שלחן בצפון, משוך מן הכתל הצפוני שתי אמות ומחצה. ומנורה בדרום משוכה מן הכתל הדרומי שתי אמות ומחצה. ומזבח הזהב נתון כנגד אויר שבין שלחן למנורה, משוך קמעא כלפי המזרח, וכלם נתונים מן חצי המשכן ולפנים. כיצד, אורך המשכן מן הפתח לפרכת עשרים אמה, המזבח והשלחן והמנורה משוכים מן הפתח לצד מערב עשר אמות:
@736 **ועשית מסך.** וילון שהוא מסך כנגד הפתח, כמו (איוב א י) שכת בעדו, לשון מגן: **מעשה רקם.** הצורות עשויות בו מעשה מחט, כפרצוף של עבר זה כך פרצוף של עבר זה: **רקם.** שם האמן, ולא שם האמנות, ותרגומו עובד ציר. מדת המסך כמדת הפרוכת, עשר אמות על עשר אמות:
@738 **ועשית את המזבח** וגו' **ושלש אמות קומתו.** דברים ככתבן, דברי רבי יהודה. רבי יוסי אומר נאמר כאן רבוע, ונאמר בפנימי רבוע, מה להלן גבהו פי שנים כארכו, אף כאן גבהו פי שנים כארכו. ומה אני מקים ושלש אמות קומתו, משפת סובב ולמעלה:
@739 **ממנו תהיין קרנתיו.** שלא יעשם לבדם ויחברם בו: **וצפית אותו נחשת.** לכפר על עזות מצח, שנאמר (ישעיה מח ד) ומצחך נחושה:
@740 **סירתיו.** כמין יורות: **לדשנו.** להסיר דשנו לתוכם, והוא שתרגם אנקלוס למספי קטמיה, לספות הדשן לתוכם, כי יש מלות בלשון עברית מלה אחת מתחלפת בפתרון לשמש בנין וסתירה, כמו (תהלים פ י) ותשרש שרשיה, (איוב ה ג) אויל משריש. וחלופו (שם לא יב) ובכל תבואתי תשרש. וכמוהו (ישע' יז ו) בסעיפיה פריה, וחלופו (שם י לג) מסעף פארה, מפשח סעיפיה, וכמוהו (ירמיה נ יז) וזה האחרון עצמו, שבר עצמיו, וכמוהו (מל''א כא יג) ויסקלהו באבנים, וחלופו (ישע' סב י) סקלו מאבן, הסירו אבניה, וכן (שם ה ב) . ויעזקהו ויסקלהו, אף כאן לדשנו להסיר דשנו ובלעז אישצינדרי''ר : **ויעיו.** כתרגומו, מגרפות שנוטל בהם הדשן, והן כמין כסוי הקדרה של מתכת דק ולו בית יד, ובלעז וידי''ל : **ומזרקתיו.** לקבל בהם דם הזבחים: **ומזלגתיו.** כמין אנקליות כפופים, ומכה בהם בבשר ונתחבים בו ומהפך בהן על גחלי המערכה שיהא ממהר שרפתן ובלעז קרוצינ''ש [אנקולים] ובלשון חכמים צנוריות: **ומחתתיו.** בית קבול יש להם לטול בהן גחלים מן המזבח לשאתם על מזבח הפנימי לקטרת, ועל שם חתייתן קרויים מחתות, כמו (ישעיה ל יד) לחתת אש מיקוד, לשון שאיבת אש ממקומה, וכן (משלי ו כז) היחתה איש אש בחיקו: **לכל כליו.** כמו כל כליו:
@741 **מכבר.** לשון כברה, שקורין קריבל''א כמין לבוש עשוי לו למזבח, עשוי חורין חורין כמין רשת. ומקרא זה מסורס וכה פתרונו ועשית לו מכבר נחשת מעשה רשת:
@742 **כרכב המזבח.** סובב, כל דבר המקיף סביב בעגול קרוי כרכוב, כמו ששנינו בהכל שוחטין (חולין כה א) אלו הן גלמי כלי עץ, כל שעתיד לשוף ולכרכב, והוא כמו שעושין חריצין עגולין בקרשי דפני התבות וספסלי העץ, אף למזבח עשה חריץ סביבו והיה רחבו אמה בדפנו לנוי והוא לסוף שש אמות של גבהו, כדברי האומר גבהו פי שנים כארכו, הא מה אני מקים ושלש אמות קומתו, משפת סובב ולמעלה. אבל סובב להלוך הכהנים לא היה למזבח הנחשת אלא על ראשו לפנים מקרנותיו, וכן שנינו בזבחים (סב ב) איזהו כרכוב, בין קרן לקרן ולפנים מהן אמה של הלוך רגלי הכהנים, ושתי אמות הללו קרויים כרכוב. ודקדקנו שם והכתיב תחת כרכוב המזבח מלמטה, למדנו שהכרכוב בדפנו הוא ולבוש המכבר תחתיו. ותירץ המתרץ תרי הוו, חד לנוי וחד לכהנים דלא ישתרגו. זה שבדופן לנוי היה ומתחתיו הלבישו המכבר והגיע רחבו עד חצי המזבח. נמצא שהמכבר רחב אמה, והוא היה סימן לחצי גבהו להבדיל בין דמים העליונים לדמים התחתונים. וכנגדו עשו למזבח בית עולמים חגורת חוט הסקרא באמצעו. וכבש שהיו עולין בו אף על פי שלא פרשו בענין זה, כבר שמענו בפרשת (לעיל כ כ) מזבח אדמה תעשה לי (לעיל כ כב) ולא תעלה במעלות, לא תעשה לי מעלות בכבש שלו אלא כבש חלק למדנו שהיה לו כבש, כך שנינו במכילתא. ומזבח אדמה הוא מזבח הנחשת שהיו ממלאין חללו אדמה במקום חניתן. והכבש היה בדרום המזבח מבדל מן המזבח מלא חוט השערה, ורגליו מגיעין עד אמה סמוך לקלעי החצר שבדרום, כדברי האומר עשר אמות קומתו. ולדברי האומר דברים ככתבן שלש אמות קומתו לא היה אורך הכבש אלא עשר אמות, כך מצאתי במשנת מ''ט מדות, וזה שהיה מבדל מן המזבח מלא החוט, במסכת זבחים (סב ב) למדוה מן המקרא:
@744 **בטבעת.** בארבע טבעות שנעשו למכבר:
@745 **נבוב לחת.** כתרגומו חליל לוחין. לוחות עצי שטים מכל צד והחלל באמצע, ולא יהא כלו עץ אחד שיהא עביו חמש אמות על חמש אמות כמין סדן:
@746 **קלעים.** עשויין כמין קלעי ספינה נקבים נקבים מעשה קליעה ולא מעשה אורג ותרגומו סרדין כתרגומו של מכבר המתורגם סרדא לפי שהן מנקבין ככברה: **לפאה האחת.** כל הרוח קרוי פאה:
@747 **ועמדיו עשרים.** חמש אמות בין עמוד לעמוד: **ואדניהם.** של עמודים נחשת, האדנים יושבים על הארץ והעמודים תקועים לתוכן היה עושה כמין קונדסין שקורין פל''ש בלעז ארכן ששה טפחים ורחבן שלשה וטבעת נחשת קבועה בו באמצעו, וכורך שפת הקלע סביבו במיתרים כנגד כל עמוד ועמוד, ותולה הקונדס דרך טבעתו באונקליות שבעמוד העשוי כמין ו''ו, ראשו זקוף למעלה וראשו אחד תקוע בעמוד, כאותן שעושין להציב דלתות שקורין גונזי''ש בלעז ורחב הקלע תלוי מלמטה, והיא קומת מחיצות החצר: **ווי העמודים.** הם האונקליות: **וחשקיהם.** מקפין היו העמודים בחוטי כסף סביב. ואיני יודע אם על פני כלן, אם בראשם, אם באמצעם. אך יודע אני שחשוק לשון חגורה, שכן מצינו בפילגש בגבעה (שופטים יט יז) ועמו צמד חמורים חבושים, תרגומו חשוקים:
@750 **לפאת קדמה מזרחה.** פני המזרח קרוי קדם, לשון פנים. אחור לשון אחורים, לפיכך המזרח קרוי קדם שהוא פנים, ומערב קרוי אחור, כמו דתרגם אנקלוס (דברים יא כד) הים האחרון ימא מערבאה: **חמשים אמה.** אותן חמשים אמה לא היו סתומים כלם בקלעים, לפי ששם הפתח, אלא חמש עשרה אמה קלעים לכתף הפתח מכאן, וכן לכתף השנית, נשאר רחב חלל הפתח בינתים עשרים אמה וזה שנאמר (פסוק טז) ולשער החצר מסך עשרים אמה, וילון למסך כנגד הפתח עשרים אמה ארך כרחב הפתח:
@751 **עמדיהם שלשה.** חמש אמות בין עמוד לעמוד, בין עמוד שבראש הדרום העומד במקצוע דרומית מזרחית עד עמוד שהוא מן השלשה שבמזרח חמש אמות וממנו לשני חמש אמות, ומן השני לשלישי חמש אמות, וכן לכתף השנית, וארבעה עמודים למסך, הרי עשרה עמודים למזרח כנגד עשרה למערב:
@754 **כל עמודי החצר סביב** וגו' **.** לפי שלא פרש ווין וחשוקים ואדני נחשת אלא לצפון ולדרום, אבל למזרח ולמערב לא נאמר ווין וחשוקים ואדני נחשת, לכך בא ולמד כאן:
@755 **ארך החצר.** הצפון והדרום שמן המזרח למערב מאה באמה: **ורחב חמשים בחמשים.** חצר שבמזרח היתה מרבעת חמשים על חמשים, שהמשכן ארכו שלשים ורחבו עשר, העמיד מזרח פתחו בשפת חמשים החיצונים של אורך החצר נמצא כלו בחמשים הפנימיים, וכלה ארכו לסוף שלשים נמצאו עשרים אמה רוח לאחוריו בין הקלעים שבמערב ליריעות של אחורי המשכן, ורוחב המשכן עשר אמות באמצע רחב החצר, נמצאו לו עשרים אמה רוח לצפון ולדרום מן קלעי החצר ליריעות המשכן, וכן למערב, וחמשים על חמשים חצר לפניו: **וקמה חמש אמות.** גובה מחצות החצר, והוא רוחב הקלעים: **ואדניהם נחשת.** להביא אדני המסך, שלא תאמר לא נאמרו אדני נחשת אלא לעמודי הקלעים, אבל אדני המסך של מין אחר היו. כך נראה בעיני, שלכך חזר ושנאן:
@756 **לכל כלי המשכן.** שהיו צריכין להקמתו ולהורדתו, כגון מקבות לתקוע יתדות ועמודים: **יתדות.** כמין נגרי נחשת עשויין ליריעות האהל ולקלעי החצר, קשורים במיתרים סביב סביב בשפוליהן, כדי שלא תהא הרוח מגביהתן. ואיני יודע, אם תחובין בארץ או קשורין ותלויין וכבדן מכביד שפולי היריעות, שלא ינועו ברוח. ואומר אני ששמן מוכיח עליהם שהם תקועין בארץ, לכך נקראו יתדות, ומקרא זה מסיעני (ישעיה לג כ) אהל בל יצען בל יסע יתדותיו לנצח:
@757 **ואתה תצוה' זך.** בלי שמרים, כמו ששנינו במנחות (פו א) מגרגרו בראש הזית וכו' : **כתית.** הזיתים היה כותש במכתשת, ואינו טוחנן בריחים, כדי שלא יהו בו שמרים, ואחר שהוציא טפה ראשונה מכניסן לריחים וטוחנן, והשמן השני פסול למנורה וכשר למנחות, שנאמר כתית למאור, ולא כתית למנחות: **להעלות נר תמיד.** מדליק עד שתהא שלהבת עולה מאליה: **תמיד.** כל לילה ולילה קרוי תמיד, כמו שאתה אומר (במדבר כח ו) עולת תמיד, ואינה אלא מיום ליום. וכן במנחת חבתין נאמר (ויקרא ו יג) תמיד, ואינה אלא מחציתה בבקר ומחציתה בערב. אבל תמיד האמור בלחם הפנים משבת לשבת הוא:
@758 **מערב עד בקר.** תן לה מדתה שתהא דולקת מערב עד בקר, ושערו חכמים חצי לוג ללילי טבת הארכין, וכן לכל הלילות, ואם יותר אין בכך כלום:
@759 **ואתה הקרב אליך.** לאחר שתגמר מלאכת המשכן:
@761 **לקדשו לכהנו לי.** לקדשו להכניסו בכהנה על ידי הבגדים שיהא כהן לי, ולשון כהנה שרות הוא, שוריינטריא''ה בלעז :
@762 **חשן.** תכשיט כנגד הלב: **ואפוד.** לא שמעתי ולא מצאתי בברייתא פרוש תבניתו, ולבי אומר לי שהוא חגור לו מאחוריו, רחבו כרוחב גב איש, כמין סינר שקורין פורציינ''ט בלעז שחוגרות השרות כשרוכבות על הסוסים, כך מעשהו מלמטה, שנאמר (שמואל ב ו יד) ודוד חגור אפוד בד, למדנו שהאפוד חגורה היא. ואי אפשר לומר שאין בו אלא חגורה לבדה, שהרי נאמר (ויקרא ח ז) ויתן עליו את האפוד, ואחר כך ויחגור אותו בחשב האפוד, ותרגם אנקלוס בהמין אפודא, למדנו שהחשב הוא החגור, והאפוד שם תכשיט לבדו. ואי אפשר לומר שעל שם שתי הכתפות שבו הוא קרוי אפוד, שהרי נאמר (פסוק כז) שתי כתפות האפוד, למדנו שהאפוד שם לבד, והכתפות שם לבד, והחשב שם לבד. לכך אני אומר שעל שם הסינר של מטה קרוי אפוד, על שם שאופדו ומקשטו בו, כמו שנאמר (ויקרא ח ז) ויאפוד לו בו, והחשב הוא החגור של מעלה המנו, והכתפות קבועות בו. ועוד אומר לי לבי, שיש ראיה שהוא מין לבוש, שתרגם יונתן (שמואל ב' ו יד) ודוד חגור אפוד בד, כרדוט דבוץ. ותרגם כמו כן מעילים, כרדוטין, במעשה תמר אחות אבשלום (שמואל ב יג יח) כי כן תלבשנה בנות המלך הבתולות מעילים: **ומעיל.** הוא כמין חלוק, וכן הכתנת, אלא שהכתונת סמוך לבשרו ומעיל קרוי חלוק עליון: **תשבץ.** עשויין משבצות לנוי, והמשבצות הן כמין גמות העשויות בתכשיטי זהב למושב קביעות אבנים טובות ומרגליות, כמו שנאמר באבני האפוד (פסוק יא) מסבות משבצות זהב, ובלעז קוראין אותו קשטונ''ש : **מצנפת.** כמין כפת כובע שקורין קויפ''א בלעז , שהרי במקום אחר קורא להם (לט כח) מגבעות, ומתרגמנן קובעיא: **ואבנט.** היא חגורה על הכתנת, והאפוד חגורה על המעיל, כמו שמצינו בסדר לבישתן (ויקרא ח ז) ויתן עליו את הכתנת ויחגור אותו באבנט וילבש אותו את המעיל ויתן עליו את האפוד: **בגדי קדש.** מתרומה המקדשת לשמי יעשו אותם:
@763 **והם יקחו.** אותם חכמי לב שיעשו הבגדים, יקבלו מן המתנדבים את הזהב ואת התכלת לעשות מהן את הבגדים:
@764 **ועשו את האפוד.** אם באתי לפרש מעשה האפוד והחשן על סדר המקראות, הרי פרושן פרקים פרקים, וישגה הקורא בצרופן, לכך אני כותב מעשיהם כמות שהוא, למען ירוץ הקורא בו, ואחר כך אפרש על סדר המקראות. האפוד עשוי כמין סינר של נשים רוכבות סוסים, וחוגר אותו מאחוריו כנגד לבו למטה מאציליו, רחבו כמדת רוחב גבו של אדם ויותר ומגיע עד עקביו, והחשב מחבר בראשו על פני רחבו מעשה אורג, ומאריך לכאן ולכאן כדי להקיף ולחגור בו, והכתפות מחברות בחשב אחד לימין ואחד לשמאל, מרוחקות זו מזו שעור הבדלת כתפים, מאחורי הכהן לשני קצות רחבו של סינר, וכשזוקפן עומדות לו על שני כתפיו, והן כמין שתי רצועות עשויות ממין האפוד, ארכות כדי שעור לזקפן אצל צוארו מכאן ומכאן, ונקפלות לפניו למטה מכתפיו מעט, ואבני השהם קבועות בהם, אחת על כתף ימין ואחת על כתף שמאל, והמשבצות נתונות בראשיהם לפני כתפיו, ושתי עבותות הזהב תחובות בשתי טבעות שבחשן בשני קצות רחבו העליון, אחת לימין ואחת לשמאל, ושני ראשי השרשרת [הימנית] תקועין במשבצות לימין, וכן שני ראשי השרשרת השמאלית תקועין במשבצות שבכתף שמאל, נמצא החושן תלוי במשבצות האפוד על לבו מלפניו. ועוד שתי טבעות בשני קצות החשן בתחתיתו וכנגדם שתי טבעות בשתי כתפות האפוד מלמטה בראשו התחתון המחבר בחשב, טבעות החשן אל מול טבעות האפוד שוכבים זה על זה ומרכסן בפתיל תכלת תחוב בטבעות האפוד והחשן, שיהא תחתית החשן דבוק לחשב האפוד ולא יהא נד ונבדל, הולך וחוזר: **זהב תכלת וארגמן תולעת שני ושש משזר.** חמשת מינים הללו שזורין בכל חוט וחוט היו מרדדין את הזהב כמין טסין דקין וקוצצין פתילים מהם, וטווין אותן חוט של זהב עם ששה חוטים של תכלת, וחוט של זהב עם ששה חוטין של ארגמן, וכן בתולעת שני, וכן בשש, שכל המינין חוטן כפול ששה, וחוט של זהב עם כל אחד ואחד, ואחר כך שוזר את כלם כאחד, נמצא חוטן כפול עשרים ושמונה. וכן מפורש במסכת יומא (עב א) , ולמד מן המקרא הזה (שמות לט ג) וירקעו את פחי הזהב וקצץ פתילים לעשות, את פתילי הזהב, בתוך התכלת ובתוך הארגמן וגו' , למדנו שחוט של זהב שזור עם כל מין ומין: **מעשה חשב.** כבר פרשתי (שמות כו א) שהוא אריגת שתי קירות שאין צורות שני עבריה דומות זו לזו:
@765 **שתי כתפות** וגו' **.** הסינר מלמטה, וחשב האפוד היא החגורה וצמודה לו מלמעלה דגמת סינר הנשים, ומגבו של כהן היו מחברות בחשב. שתי חתכות כמין שתי רצועות רחבות, אחת כנגד כל כתף וכתף, וזוקפן על שתי כתפותיו עד שנקפלות לפניו כנגד החזה, ועל ידי חבורן לטבעות החשן נאחזין מלפניו כנגד לבו שאין נופלות, כמו שמפורש בענין, והיו זקופות והולכות כנגד כתפיו, ושתי אבני השהם קבועות בהן, אחת בכל אחת: **אל שני קצותיו.** אל רחבו של אפוד, שלא היה רחבו אלא כנגד גבו של כהן, וגבהו עד כנגד האצילים שקורין קודי''ש בלעז [מרפקים] שנאמר (יחזקאל מד יח) לא יחגרו ביזע, אין חוגרין במקום זיעה, לא למעלה מאציליהם ולא למטה ממתניהם, אלא כנגד אציליהם: **וחבר.** האפוד עם אותן שתי כתפות האפוד, יחבר אותם במחט למטה בחשב, ולא יארגם עמו, אלא אורגם לבדם ואחר כך מחברם:
@766 **וחשב אפדתו.** וחגור שעל ידו הוא מאפדו ומתקנהו לכהן ומקשטו: **אשר עליו.** למעלה בשפת הסינר, היא החגורה: **כמעשהו.** כאריגת הסינר מעשה חושב ומחמשת מינים, כך אריגת החשב מעשה חושב ומחמשת מינין: **ממנו יהיה.** עמו יהיה ארוג, ולא יארגנו לבד ויחברנו:
@768 **כתולדתם.** כסדר שנלדו ראובן שמעון לוי יהודה דן נפתלי, על האחת, ועל השניה גד אשר יששכר זבולן יוסף בנימין מלא, שכן הוא כתוב במקום תולדתו, עשרים וחמש אותיות בכל אחת ואחת:
@769 **מעשה חרש אבן.** מעשה אמן של אבנים. חרש זה דבוק הוא לתבה שלאחריו, ולפיכך הוא נקוד פתח בסופו, וכן (ישעיה מד יג) חרש עצים נטה קו, חרש של עצים. וכן (ישעיה מד יב) חרש ברזל מעצד, כל אלה דבוקים ופתוחים: **פתוחי חתם.** כתרגומו כתב מפרש כגלף דעזקא, חרוצות האותיות בתוכן, כמו שחורצין חותמי טבעות שהם לחתום אגרות, כתב נכר ומפרש: **על שמות.** כמו בשמות: **מסבת משבצות.** מוקפות האבנים במשבצות זהב, שעושה מושב האבן בזהב כמין גומא למדת האבן ומשקיעה במשבצות, נמצאת המשבצת סובבת את האבן סביב, ומחבר המשבצות בכתפות האפוד:
@770 **לזכרון.** שיראה הקדוש ברוך הוא השבטים כתובים לפניו ויזכור צדקתם:
@771 **ועשית משבצות.** מעוט משבצות שתים, ולא פרש לך עתה בפרשה זו אלא מקצת צרכן, ובפרשת החושן גומר לך פרושן:
@772 **שרשרת זהב.** שלשלאות: **מגבלות.** לסוף גבול החשן תעשה אותם: **מעשה עבות.** מעשה קליעת חוטין, ולא מעשה נקבים וכפלים, כאותן שעושין לבורות, אלא כאותן שעושין לערדסקאות, שקורין אינצינשייר''ש בלעז [כלי קטורת] : **ונתת את שרשרת.** של עבותות העשויות מעשה עבות על המשבצות הללו. ולא זה הוא מקום צואת עשיתן של שרשרות, ולא צואת קביעתן, ואין תעשה האמור כאן לשון צווי, ואין ונתתה האמור כאן לשון צווי, אלא לשון עתיד, כי בפרשת החשן חוזר ומצוה על עשיתן ועל קביעתן, ולא נכתב כאן אלא להודיע מקצת צורך המשבצות שצוה לעשות עם האפוד, וכתב לך זאת לומר לך המשבצות הללו יזקקו לך לכשתעשה שרשרות מגבלות על החשן, תתנם על המשבצות הללו:
@773 **חשן משפט.** שמכפר על קלקול הדין. דבר אחר משפט, שמברר דבריו והבטחתו אמת, דיריישנימינ''ט בלעז . שהמשפט משמש שלש לשונות דברי טענות הבעלי דינים, וגמר הדין, ועונש הדין, אם עונש מיתה, אם עונש מכות, אם עונש ממון, וזה משמש לשון ברור דברים, שמפרש ומברר דבריו: **כמעשה אפוד.** מעשה חושב ומחמשת מינין:
@774 **זרת ארכו וזרת רחבו.** כפול ומוטל לו לפניו כנגד לבו, שנאמר (פסוק ל) והיו על לב אהרן, תלוי בכתפות האפוד, הבאות מאחוריו על כתפיו ונקפלות ויורדות לפניו מעט, והחשן תלוי בהן בשרשרות וטבעות, כמו שמפורש בענין:
@775 **ומלאת בו.** על שם שהאבנים ממלאות גמות המשבצות המתקנות להן, קורא אותן בלשון מלאים:
@778 **משבצים זהב.** יהיו הטורים במלואתם, מקפים משבצות זהב בעומק שעור שיתמלא בעובי האבן, זהו לשון במלואתם, כשיעור מלוי עביין של אבנים יהיה עומק המשבצות לא פחות ולא יותר:
@779 **איש על שמו.** כסדר תולדותם סדר האבנים, אודם לראובן, פטדה לשמעון, וכן כלם:
@780 **על החשן.** בשביל החשן, לקבעם בטבעותיו, כמו שמפורש למטה בענין: **שרשת.** לשון שרשי אילן המאחיזין לאילן להאחז ולהתקע בארץ, אף אלו יהיו מאחיזין לחשן, שבהם יהיה תלוי באפוד, והן שתי שרשרות האמורות למעלה (פסוק יד) בענין המשבצות. ואף שרשרות פתר מנחם בן סרוק לשון שרשים, ואמר שהרי''ש יתרה, כמו מ''ם שבשלשום, ומ''ם שבריקם. ואיני רואה את דבריו, אלא שרשרת בלשון עברית, כשלשלת בלשון משנה: **גבלת.** הוא מגבלות האמור למעלה (פסוק יד) שתתקעם בטבעות, שיהיו בגבול החשן, וכל גבול לשון קצה, אשומיי''ל בלעז : **מעשה עבות.** מעשה קליעה:
@781 **על החשן.** לצורך החושן, כדי לקבעם בו. ולא יתכן לומר שתהא תחלת עשיתן עליו, שאם כן מה הוא שחוזר ואומר ונתת את שתי הטבעות, והלא כבר נתונים בו, היה לו לכתוב בתחלת המקרא ועשית על קצות החשן שתי טבעות זהב, ואף בשרשרות צריך אתה לפתור כן: **על שני קצות החשן.** לשתי פאות שכנגד הצואר, לימנית ולשמאלית הבאים מול כתפות האפוד:
@782 **ונתתה את שתי עבתת הזהב.** הן הן שרשרות גבלות הכתובות למעלה (פסוק כב) ולא פרש מקום קבוען בחשן, עכשיו מפרש לך שיהא תוחב אותן בטבעות, ותדע לך שהן הן הראשונות, שהרי בפרשת אלה פקודי לא הכפלו:
@783 **ואת שתי קצות.** של שתי העבותות שני ראשיהם שלכל אחת: **תתן על שתי המשבצות.** הן הכתובות למעלה (פסוק יד) בין פרשת החשן ופרשת האפוד, ולא פרש את צרכן ואת מקומן, עכשיו מפרש שיתקע בהן ראשי העבותות התחובות בטבעות [בראשי] החשן לימין ולשמאל אצל הצואר, שני ראשי השרשרת הימנית תוקע במשבצות של ימין, וכן בשל שמאל שני ראשי שרשרות השמאלית: **ונתתה.** המשבצות: **על כתפות האפוד.** אחת בזו ואחת בזו, נמצאו כתפות האפוד מחזיקין את החשן שלא יפל, ובהן הוא תלוי, ועדין שפת החשן התחתונה הולכת ובאה ונוקשת על כרסו, ואינה דבוקה לו יפה, לכך הצרך עוד שתי טבעות לתחתיתו, כמו שמפרש והולך: **אל מול פניו.** של אפוד, שלא יתן המשבצות בעבר הכתפות שכלפי המעיל, אלא בעבר העליון שכלפי החוץ, והוא קרוי מול פניו של אפוד, כי אותו עבר שאינו נראה אינו קרוי פנים:
@784 **על שני קצות החשן.** הן שתי פאותיו התחתונות לימין ולשמאל: **על שפתו אשר אל עבר האפד ביתה.** הרי לך שני סימנין האחד שיתנם בשני קצות של תחתיתו שהוא כנגד האפוד, שעליונו אינו כנגד האפוד, שהרי סמוך לצואר הוא, והאפוד נתון על מתניו, ועוד נתן סימן שלא יקבעם בעבר החשן שכלפי החוץ, אלא בעבר שכלפי פנים שנאמר ביתה, ואותו העבר הוא לצד האפוד, שחשב האפוד חוגרו הכהן ונקפל הסינר לפני הכהן על מתניו, וקצת כרסו מכאן ומכאן עד כנגד קצות החשן, וקצותיו שוכבין עליו:
@785 **על שתי כתפות האפוד מלמטה.** שהמשבצות נתונות בראשי כתפות האפוד העליונים הבאים על כתפיו כנגד גרונו, ונקפלות ויורדות לפניו, והטבעות צוה לתן בראשן השני, שהוא מחבר לאפוד, והוא שנאמר לעמת מחברתו, סמוך למקום חבורן באפוד למעלה מן החגורה מעט, שהמחברת לעמת החגורה, ואלו נתונים מעט בגובה זקיפת הכתפות, הוא שנאמר ממעל לחשב האפוד, והן כנגד סוף החשן, ונותן פתיל תכלת באותן הטבעות ובטבעות החשן, ורוכסן באותן פתילין לימין ולשמאל, שלא יהא תחתית החושן הולך לפנים וחוזר לאחור ונוקש על כרסו, ונמצא מישב על המעיל יפה: **ממול פניו.** בעבר החיצון:
@786 **וירכסו.** לשון חבור, וכן (תהלים לא כא) מרכסי איש, חבורי חבלי רשעים, וכן (ישעיה מ ד) והרכסים לבקעה, הרים הסמוכים זה לזה שאי אפשר לירד לגיא שביניהם אלא בקושי גדול, שמתוך סמיכתן הגיא זקופה ועמוקה, יהיו לבקעת מישור ונוחה לילך: **להיות על חשב האפוד.** להיות החשן דבוק אל חשב האפוד: **ולא יזח.** לשון נתוק, ולשון ערבי הוא, כדברי דונש בן לברט:
@788 **את האורים ואת התמים.** הוא כתב שם המפורש, שהיה נותנו בתוך כפלי החשן, שעל ידו הוא מאיר דבריו ומתמם את דבריו. ובמקדש שני היה החשן, שאי אפשר לכהן גדול להיות מחסר בגדים, אבל אותו השם לא היה בתוכו, ועל שם אותו הכתב הוא קרוי משפט, שנאמר (במדבר כז כא) ושאל לו במשפט האורים: **את משפט בני ישראל.** דבר שהם נשפטים ונוכחים על ידו אם לעשות דבר או לא לעשות. ולפי מדרש אגדה שהחשן מכפר על מעותי הדין, נקרא משפט על שם סליחת המשפט:
@789 **את מעיל האפוד.** שהאפוד נתון עליו לחגורה: **כליל תכלת.** כלו תכלת, שאין מין אחר מעורב בו:
@790 **והיה פי ראשו.** פי המעיל שבגבהו הוא פתיחת בית הצואר: **בתוכו.** כתרגומו כפיל לגויה, כפול לתוכו להיות לו לשפה כפילתו, והיה מעשה אורג ולא במחט: **כפי תחרא.** למדנו שהשריונים שלהם פיהם כפול לתוכן: **לא יקרע.** כדי שלא יקרע, והקורעו עובר בלאו, שזה ממנין לאוין שבתורה, וכן (פסוק כח) ולא יזח החשן, וכן (שמות כה טו) לא יסורו ממנו. הנאמר בבדי הארון:
@791 **רמוני.** עגולים וחלולים היו כמין רמונים העשויים כביצת תרנגולת: **ופעמוני זהב.** זגין עם ענבלין שבתוכם: **בתוכם סביב.** ביניהם סביב, בין שני רמונים פעמון אחד דבוק ותלוי בשולי המעיל:
@792 **פעמון זהב ורמון פעמון זהב ורמון.** אצלו:
@793 **ולא ימות.** מכלל לאו אתה שומע הן, אם יהיו לו לא יתחיב מיתה, הא אם יכנס מחסר אחד מן הבגדים הללו חיב מיתה בידי שמים:
@794 **ציץ.** כמין טס של זהב היה, רוחב שתי אצבעות, מקיף על המצח מאוזן לאוזן:
@795 **על פתיל תכלת.** ובמקום אחר הוא אומר (שמות לט לא) ויתנו עליו פתיל תכלת, ועוד כתיב כאן והיה על המצנפת, ולמטה הוא אומר (פסוק לח) והיה על מצח אהרן, ובשחיטת קדשים שנינו (זבחים יט א) שערו היה נראה בין ציץ למצנפת, ששם מניח תפלין, למדנו שהמצנפת למעלה בגובה הראש ואינה עמוקה לכנס בה כל הראש עד המצח, והציץ מלמטה, והפתילים היו בנקבים ותלויין בו בשני ראשים ובאמצעיתו ששה בשלושה מקומות הללו, פתיל מלמעלה, אחד מבחוץ, ואחד מבפנים כנגדו, וקושר ראשי הפתילים מאחורי העורף שלשתן, ונמצאו בין אורך הטס ופתילי ראשו מקיפין את הקדקד, ופתיל האמצעי שבראשו קשור עם ראשי השנים, הולך על פני רוחב הראש מלמעלה, ונמצא עשוי כמין כובע, ועל פתיל האמצעי הוא אומר והיה על המצנפת, והיה נותן הציץ על ראשו כמין כובע על המצנפת, והפתיל האמצעי מחזיקו שאינו נופל, והטס תלוי כנגד מצחו, ונתקימו כל המקראות פתיל על הציץ, וציץ על הפתיל, והפתיל על המצנפת מלמעלה:
@796 **ונשא אהרן.** לשון סליחה, ואף על פי כן אינו זז ממשמעו, אהרן נושא את המשא שלעון, נמצא מסלק העון מן הקדשים: **את עון הקדשים.** לרצות על הדם ועל החלב שקרבו בטומאה, כמו ששנינו (פסחים טז א) אי זה עון הוא נושא, אם עון פגול, הרי כבר נאמר (ויקרא יט ז) לא ירצה, ואם עון נותר, הרי נאמר (ויקרא ז יח) לא יחשב, ואין לומר שיכפר על עון הכהן שהקריב טמא, שהרי עון הקדשים נאמר, ולא עון המקריבים, הא אינו מרצה אלא להכשיר הקרבן: **והיה על מצחו תמיד.** אי אפשר לומר שיהא על מצחו תמיד, שהרי אינו עליו אלא בשעת העבודה, אלא תמיד לרצות להם, אפלו אינו על מצחו, שלא היה כהן גדול עובד באותה שעה. ולדברי האומר (יומא ז ב) עודהו על מצחו מכפר ומרצה, ואם לאו אינו מרצה, נדרש על מצחו תמיד, מלמד שמשמש בו בעודו על מצחו, שלא יסיח דעתו ממנו:
@797 **ושבצת.** עשה אותה משבצות משבצות, וכלה של שש:
@798 **ולבני אהרן תעשה כתנת.** ארבעה בגדים הללו ולא יותר כתנת, ואבנט, ומגבעות היא מצנפת, ומכנסים הכתובים למטה בפרשה (פסוק מב) :
@799 **והלבשת אתם את אהרן.** אותם האמורים באהרן חשן ואפוד ומעיל וכתונת תשבץ, מצנפת ואבנט וציץ ומכנסים, הכתובים למטה בכלם: **ואת בניו אתו.** אותם הכתובים בהם: **ומשחת אותם.** את אהרן ואת בניו בשמן המשחה: **ומלאת את ידם.** כל מלוי ידים לשון חנוך, כשהוא נכנס לדבר להיות מחזק בו מאותו יום והלאה הוא מלוי, ובלשון לעז כשממנין אדם על פקידת דבר, נותן השליט בידו בית יד של עור שקורין גנ''ט בלעז [כפפה] , ועל ידו הוא מחזיקו בדבר, וקורין לאותו מסירה ריוישטי''ר בלעז [להסמיך] והוא מלוי ידים:
@800 **ועשה להם.** לאהרן ולבניו: **מכנסי בד.** הרי שמונה בגדים לכהן גדול, וארבעה לכהן הדיוט:
@801 **והיו על אהרן.** כל הבגדים האלה על אהרן הראויין לו: **ועל בניו.** האמורים בהם: **בבאם אל אהל מועד.** להיכל, וכן למשכן: **ומתו.** הא למדת, שהמשמש מחסר בגדים במיתה: **חקת עולם לו.** כל מקום שנאמר חקת עולם, הוא גזרה מיד ולדורות, לעכב בו:
@802 **לקח.** כמו קח, ושתי גזרות הן, אחת של קיחה, ואחת של לקיחה, ולהן פתרון אחד: **פר אחד.** לכפר על מעשה העגל שהוא פר:
@803 **ולחם מצות וחלת מצת ורקיקי מצות.** הרי אלו שלשה מינין רבוכה, וחלות ורקיקים לחם מצות, היא הקרויה למטה בענין (פסוק כג) חלת לחם שמן, על שם שנותן שמן ברבוכה כנגד החלות והרקיקין, וכל המינין באים עשר עשר חלות: **בלולת בשמן.** כשהן קמח יוצק בהן שמן ובוללן: **משחים בשמן.** אחר אפייתן מושחן כמין כי יונית, שהיא עשויה כנו''ן שלנו:
@804 **והקרבת אתם.** אל חצר המשכן ביום הקמתו:
@805 **ורחצת.** זו טבילת כל הגוף:
@806 **ואפדת.** קשט ותקן החגורה והסינר סביבותיו:
@807 **נזר הקדש.** זה הציץ: **על המצנפת.** כמו שפרשתי למעלה (שמות כח לז) על ידי הפתיל האמצעי ושני פתילין שבראשו הקשורין שלשתן מאחורי העורף, הוא נותנו על המצנפת כמין כובע:
@808 **ומשחת אותו.** אף משיחה זו כמין כי יונית, נותן שמן על ראשו ובין ריסי עיניו ומחברן באצבעו:
@810 **והיתה להם.** מלוי ידים זה לכהנת עולם: **ומלאת.** על ידי הדברים האלה: **יד אהרן ויד בניו.** במלוי ופקדת הכהונה:
@812 **פתח אהל מועד.** בחצר המשכן שלפני הפתח:
@813 **על קרנות.** למעלה בקרנות ממש: **ואת כל הדם.** שירי הדם: **אל יסוד המזבח.** כמין בליטת בית קבול עשוי לו סביב סביב לאחר שעלה אמה מן הארץ:
@814 **החלב המכסה את הקרב.** הוא הקרום שעל הכרס שקורין טייל''א : **ואת היתרת.** הוא טרפשא דכבדא שקורין איבדי''ש [סרעפת] : **על הכבד.** אף מן הכבד יטול עמה:
@815 **תשרף באש.** לא מצינו חטאת חיצונה נשרפת אלא זו:
@817 **וזרקת.** בכלי, אוחז במזרק וזורק כנגד הקרן כדי שיראה לכאן ולכאן, ואין קרבן טעון מתנה באצבע אלא חטאת בלבד, אבל שאר זבחים אינן טעונין קרן ולא אצבע, שמתן דמם מחצי המזבח ולמטה, ואינו עולה בכבש אלא עומד בארץ וזורק: **סביב.** כך מפורש בשחיטת קדשים (זבחים נב ב) שאין סביב אלא שתי מתנות שהן ארבע, האחת בקרן זוית זו, והאחת בקרן שכנגדה באלכסון, וכל מתנה נראית בשני צדי הקרן אלך ואלך, נמצא הדם נתן בארבע רוחות סביב, לכך קרוי סביב:
@818 **על נתחיו.** עם נתחיו, מוסף על שאר הנתחים:
@819 **ריח ניחוח.** נחת רוח לפני, שאמרתי ונעשה רצוני: **אשה.** לשון אש, והיא הקטרת איברים שעל האש:
@821 **תנוך.** הוא הסחוס האמצעי שבתוך האזן שקורין טנדרו''ם : **בהן ידם.** הגדל ובפרק האמצעי:
@823 **החלב.** זה חלב הדקים או הקיבה: **והאליה.** מן הכליות ולמטה, כמו שמפורש בויקרא (ג ט) שנאמר לעמת העצה יסירנה, מקום שהכליות יועצות, ובאמורי הפר לא נאמר אליה, שאין אליה קריבה אלא בכבש וכבשה ואיל, אבל שור ועז אין טעונים אליה: **ואת שוק הימין.** לא מצינו הקטרה בשוק הימין עם האמורים אלא זו בלבד: **כי איל מלאים הוא.** שלמים, לשון שלמות שמשלם בכל. מגיד הכתוב שהמלואים שלמים, שמשימים שלום למזבח ולעובד העבודה ולבעלים, לכך אני מצריכו החזה להיות לו לעובד העבודה למנה, וזהו משה ששמש במלואים, והשאר אכלו אהרן ובניו שהם בעלים, כמפורש בענין:
@824 **וככר לחם.** מן החלות: **וחלת לחם שמן.** ממין הרבוכה: **ורקיק.** מן הרקיקין, אחד מעשרה שבכל מין ומין ולא מצינו תרומת לחם הבא עם זבח נקטרת אלא זו בלבד, שתרומת לחמי תודה ואיל נזיר נתונה לכהנים עם חזה ושוק, ומזה לא היה למשה למנה אלא חזה בלבד:
@825 **על כפי אהרן** וגו' **והנפת.** שניהם עסוקים בתנופה, הבעלים והכהן. הא כיצד, כהן מניח ידו תחת יד הבעלים ומניף, ובזה היו אהרן ובניו בעלים, ומשה כהן: **תנופה.** מוליך ומביא למי שארבע רוחות העולם שלו, ותנופה מעכבת רוחות רעות. תרומה מעלה ומוריד למי שהשמים וארץ שלו, ומעכבת טללים רעים:
@826 **על העולה.** על האיל הראשון שהעלית עולה: **לריח ניחוח.** לנחת רוח למי שאמר ונעשה רצונו: **אשה.** לאש נתן: **לה'.** לשמו של מקום:
@828 **וקדשת את חזה התנופה ואת שוק התרומה** וגו' **.** קדשם לדורות, להיות נוהגת תרומתם והנפתם כחזה ושוק של שלמים, אבל לא להקטרה, אלא והיה לאהרן ולבניו לאכול: **תנופה.** לשון הולכה והבאה, וינטילי''ר בלעז : **הורם.** לשון מעלה ומוריד:
@829 **לחק עולם מאת בני ישראל.** שהשלמים לבעלים, ואת החזה ואת השוק יתנו לכהן: **כי תרומה הוא.** החזה ושוק הזה:
@830 **לבניו אחריו.** למי שבא בגדלה אחריו: **למשחה.** להתגדל בהם, שיש משיחה שהיא לשון שררה, כמו (במדבר יח ח) לך נתתים למשחה, (תהלים קה טו) אל תגעו במשיחי: **ולמלא בם את ידם.** על ידי הבגדים הוא מתלבש בכהנה גדולה:
@831 **שבעת ימים.** רצופין: **ילבשם הכהן.** אשר יקום מבניו תחתיו לכהנה גדולה, כשימנוהו להיות כהן גדול: **אשר יבא אל אהל מועד.** אותו כהן המוכן לכנס לפני ולפנים ביום הכפורים, וזהו כהן גדול, שאין עבודת יום הכפורים כשרה אלא בו: **תחתיו מבניו.** מלמד שאם יש לו לכהן גדול בן ממלא את מקומו, ימנוהו כהן גדול תחתיו: **הכהן תחתיו מבניו.** מכאן ראיה כל לשון כהן לשון פועל עובד ממש, לפיכך נגון תביר נמשך לפניו:
@832 **במקום קדוש.** בחצר אהל מועד, שהשלמים הללו קדשי קדשים היו:
@833 **פתח אהל מועד.** כל החצר קרוי כן:
@834 **ואכלו אתם.** אהרן ובניו, לפי שהם בעליהם: **אשר כפר בהם.** כל זרות ותיעוב: **למלא את ידם.** באיל ולחם הללו: **לקדש אתם.** שעל ידי המלאים הללו נתמלאו ידיהם ונתקדשו לכהנה: **כי קדש הם.** קדשי קדשים, ומכאן למדנו אזהרה לזר האוכל קדש קדשים, שנתן המקרא טעם לדבר משום דקדש הם:
@836 **ועשית לאהרן ולבניו ככה.** שנה הכתוב וכפל לעכב, שאם חסר דבר אחד מכל האמור בענין, לא נתמלאו ידיהם להיות כהנים ועבודתם פסולה: **אתכה.** כמו אותך: **שבעת ימים תמלא** וגו' **.** בענין הזה ובקרבנות הללו בכל יום:
@837 **על הכפרים.** בשביל הכפורים, לכפר על המזבח מכל זרות ותיעוב. ולפי שנאמר (פסוק לה) שבעת ימים תמלא ידם, אין לי אלא דבר הבא בשבילם, כגון האילים והלחם, אבל הבא בשביל המזבח, כגון פר שהוא לחטוי המזבח, לא שמענו, לכך הצרך מקרא זה. ומדרש תורת כהנים אומר כפרת המזבח הצרך, שמא התנדב איש דבר גזל במלאכת המשכן והמזבח: **וחטאת.** ותדכי, לשון מתנת דמים הנתונים באצבע קרוי חטוי: **ומשחת אתו.** בשמן המשחה וכל המשיחות כמין כי יונית:
@838 **והיה המזבח קדש.** ומה היא קדשתו, כל הנגע במזבח יקדש, אפלו קרבן פסול שעלה עליו, קדשו המזבח להכשירו שלא ירד. מתוך שנאמר כל הנגע במזבח יקדש, שומע אני בין ראוי בין שאינו ראוי, כגון דבר שלא היה פסולו בקדש, כגון הרובע והנרבע ומקצה ונעבד והטרפה וכיוצא בהן, תלמוד לומר וזה אשר תעשה, הסמוך אחריו, מה עולה ראויה אף כל ראוי, שנראה לו כבר ונפסל משבא לעזרה, כגון הלן והיוצא והטמא ושנשחט במחשבת חוץ לזמנו וחוץ למקומו וכיוצא בהן:
@841 **ועשרון סולת.** עשירית האיפה, ארבעים ושלש ביצים וחמש ביצה: **בשמן כתית.** לא לחובה נאמר כתית אלא להכשיר, לפי שנאמר (לעיל כז כ) כתית למאור, ומשמע למאור ולא למנחות, יכול לפסלו למנחות, תלמוד לומר כאן כתית, ולא נאמר (שמות כז כ) כתית למאור אלא למעט מנחות שאין צריך כתית, שאף הטחון בריחים כשר בהן: **רבע ההין.** שלשה לוגין: **ונסך.** לספלים, כמו ששנינו במסכת סכה (מח א) שני ספלים של כסף היו בראש המזבח, ומנקבים כמין שני חטמין דקים, נותן היין לתוכו והוא מקלח ויוצא דרך החוטם ונופל על גג המזבח, ומשם יורד לשיתין במזבח בית עולמים, ובמזבח הנחשת יורד מן המזבח לארץ:
@842 **לריח ניחח.** על המנחה נאמר, שמנחת נסכים כלה כליל, וסדר הקרבתן האיברים בתחלה ואחר כך המנחה, שנאמר (ויקרא כג לז) עולה ומנחה:
@843 **תמיד.** מיום אל יום, ולא יפסיק יום בנתים: **אשר אועד לכם.** כשאקבע מועד לדבר אליך שם אקבענו לבא. ויש מרבותינו למדים מכאן, שמעל מזבח הנחשת היה הקדוש ברוך הוא מדבר עם משה משהוקם המשכן, ויש אומרים מעל הכפרת, כמו שנאמר (שמות כה כב) ודברתי אתך מעל הכפורת, ואשר אועד לכם האמור כאן אינו אמור על המזבח, אלא על אהל מועד הנזכר במקרא:
@844 **ונועדתי שמה.** אתועד עמם בדבור, כמלך הקובע מקום מועד לדבר עם עבדיו שם: **ונקדש.** המשכן: **בכבודי.** שתשרה שכינתי בו. ומדרש אגדה אל תקרי בכבודי, אלא [במכבדי] , במכבדים שלי, כאן רמז לו מיתת בני אהרן ביום הקמתו, וזהו שאמר משה (ויקרא י ג) הוא אשר דבר ה' לאמר בקרובי אקדש, והיכן דבר, ונקדש בכבודי:
@847 **לשכני בתוכם.** על מנת לשכון אני בתוכם:
@848 **מקטר קטרת.** להעלות עליו קיטור עשן סמים:
@850 **את גגו.** זה היה לו גג, אבל מזבח העולה לא היה לו גג, אלא ממלאים חללו אדמה בכל חניתן: **זר זהב.** סימן הוא לכתר כהנה:
@851 **צלעותיו.** כאן הוא לשון זויות, כתרגומו, לפי שנאמר על שני צדיו, על שתי זויותיו שבשני צדיו: **והיה.** מעשה הטבעות האלה: **לבתים לבדים.** לכל בית תהיה הטבעת לבד:
@853 **לפני הפרכת.** שמא תאמר משוך מכנגד הארון לצפון או לדרום, תלמוד לומר לפני הכפרת, מכון כנגד הארון מבחוץ:
@854 **בהיטיבו.** לשון נקוי הבזכין של מנורה מדשן הפתילות שנשרפו בלילה, והיה מטיבן בכל בקר ובקר: **הנרות.** לוצי''ש בלעז [מנורות] וכן כל נרות האמורות במנורה, חוץ ממקום שנאמר שם העלאה, שהוא לשון הדלקה:
@855 **ובהעלות.** כשידליקם להעלות להבתן: **יקטירנה.** בכל יום פרס מקטיר שחרית ופרס מקטיר בין הערבים:
@856 **לא תעלו עליו.** על מזבח זה: **קטרת זרה.** שום קטורת של נדבה. כלן זרות לו חוץ מזו: **ועולה ומנחה.** ולא עולה ומנחה, עולה של בהמה ועוף, ומנחה היא של מין לחם:
@857 **וכפר אהרן.** מתן דמים: **אחת בשנה.** ביום הכפורים, הוא שנאמר באחרי מות (ויקרא טז יח) ויצא אל המזבח אשר לפני ה' וכפר עליו: **חטאת הכפורים.** הם פר ושעיר של יום הכפורים המכפרים על טומאת מקדש וקדשיו: **קדש קדשים.** המזבח מקדש לדברים הללו בלבד ולא לעבודה אחרת:
@859 **כי תשא.** לשון קבלה, כתרגומו, כשתחפוץ לקבל סכום מנינם לדעת כמה הם, אל תמנם לגלגולת, אלא יתנו כל אחד מחצית השקל ותמנה את השקלים ותדע מנינם: **ולא יהיה בהם נגף.** שהמנין שולט בו עין הרע והדבר בא עליהם, כמו שמצינו בימי דוד:
@860 **זה יתנו.** הראה לו כמין מטבע של אש, ומשקלה מחצית השקל, ואמר לו כזה יתנו: **העבר על הפקודים.** דרך המונין מעבירין את הנמנין זה אחר זה, וכן לשון (ויקרא כז לב) כל אשר יעבור תחת השבט, וכן (ירמיה לג יג) תעבורנה הצאן על ידי מונה: **מחצית השקל בשקל הקדש.** במשקל השקל שקצבתי לך לשקול בו שקלי הקדש, כגון שקלים האמורין בפרשת ערכין ושדה אחזה: **עשרים גרה השקל.** עכשיו פרש לך כמה הוא: **גרה.** לשון מעה, וכן בשמואל (שמואל א' ב לו) יבוא להשתחות לו לאגורת כסף וככר לחם: **עשרים גרה השקל.** השקל השלם, שהשקל ארבעה זוזים, והזוז מתחלתו חמש מעות, אלא באו והוסיפו עליו שתות והעלוהו לשש מעה כסף, ומחצית השקל הזה, שאמרתי לך, יתנו תרומה לה':
@861 **מבן עשרים שנה ומעלה.** למדך כאן, שאין פחות מבן עשרים יוצא לצבא ונמנה בכלל אנשים:
@862 **לכפר על נפשתיכם.** שלא תנגפו על ידי המנין. דבר אחר לכפר על נפשותיכם, לפי שרמז להם כאן שלש תרומות, שנכתב כאן תרומת ה' שלש פעמים אחת תרומת אדנים, שמנאן כשהתחילו בנדבת המשכן ונתנו כל אחד ואחד מחצית השקל, ועלה למאת ככר, שנאמר (שמות לח כה) וכסף פקודי העדה מאת ככר, ומהם נעשו האדנים, שנאמר (שמות לח כז) ויהי מאת ככר הכסף וגו' . והשנית אף היא על ידי מנין שמנאן, משהוקם המשכן, הוא המנין האמור בתחלת חמש הפקודים (במדבר א א) באחד לחדש השני בשנה השנית, ונתנו כל אחד מחצית השקל, והן לקנות מהן קרבנות צבור של כל שנה ושנה, והשוו בהם עניים ועשירים, ועל אותה תרומה נאמר לכפר על נפשותיכם, שהקרבנות לכפרה הם באים. והשלישית היא תרומת המשכן, כמו שנאמר (שמות לה כד) כל מרים תרומת כסף ונחשת, ולא היתה יד כלם שוה בה, אלא איש איש מה שנדבו לבו:
@863 **ונתת אתו על עבודת אהל מועד.** למדת שנצטוה למנותם בתחלת נדבת המשכן אחר מעשה העגל, מפני שנכנס בהם מגפה, כמו שנאמר (שמות לב לה) ויגוף ה' את העם. משל לצאן החביבה על בעליה, שנפל בה דבר, ומשפסק אמר לו לרועה בבקשה ממך, מנה את צאני ודע כמה נותרו בהם, להודיע שהיא חביבה עליו. ואי אפשר לומר, שהמנין הזה הוא האמור בחומש הפקודים, שהרי נאמר בו (במדבר א א) באחד לחדש השני, והמשכן הוקם באחד לחדש הראשון, שנאמר (שמות מ ב) ביום החדש הראשון באחד לחדש תקים וגו' , ומהמנין הזה נעשו האדנים משקלים שלו, שנאמר (שמות לח כז) ויהי מאת ככר הכסף לצקת וגו' , הא למדת שתים היו אחת בתחלת נדבתן אחר יום הכפורים בשנה ראשונה, ואחת בשנה שניה באיר משהוקם המשכן. ואם תאמר, וכי אפשר שבשניהם היו ישראל שווים שש מאות אלף ושלשת אלפים וחמש מאות וחמשים, שהרי בכסף פקודי העדה נאמר כן, ובחומש הפקודים אף בו נאמר כן (במדבר א מו) ויהיו כל הפקודים שש מאות אלף ושלשת אלפים וחמש מאות וחמשים, והלא בשתי שנים היו, ואי אפשר שלא היו בשעת מנין הראשון בני תשע עשרה שנה שלא נמנו ובשנייה נעשו בני עשרים. תשובה לדבר, אצל שנות האנשים בשנה אחת נמנו, אבל למנין יציאת מצרים היו שתי שנים, לפי של יציאת מצרים מונין מניסן, כמו ששנינו במסכת ראש השנה (ב:) , ונבנה המשכן בראשונה והוקם בשנייה שנתחדשה שנה באחד בניסן, אבל שנות האנשים מנויין למנין שנות עולם המתחילין מתשרי, נמצאו שני המנינים בשנה אחת המנין הראשון היה בתשרי לאחר יום הכפורים, שנתרצה המקום לישראל לסלוח להם, ונצטוו על המשכן, והשני באחד באיר: **על עבודת אהל מועד.** הן האדנים שנעשו בו:
@865 **כיור.** כמין דוד גדולה ולה דדים המריקים בפיהם מים: **וכנו.** כתרגומו ובסיסיה, מושב מתקן לכיור: **לרחצה.** מוסב על הכיור: **ובין המזבח.** מזבח העולה שכתוב בו, שהוא לפני פתח משכן אהל מועד, והיה הכיור משוך קמעא ועומד כנגד אויר שבין המזבח והמשכן, ואינו מפסיק כלל בנתים, משום שנאמר (שמות מ כט) ואת מזבח העולה שם פתח משכן אהל מועד, כלומר מזבח לפני אהל מועד ואין כיור לפני אהל מועד, הא כיצד, משוך קמעא כלפי הדרום, כך שנויה בזבחים (נט א) :
@866 **את ידיהם ואת רגליהם.** בבת אחת היה מקדש ידיו ורגליו, וכך שנינו בזבחים (יט ב) כיצד קדוש ידים ורגלים, מניח ידו הימנית על גבי רגלו הימנית, וידו השמאלית על גבי רגלו השמאלית, ומקדש:
@867 **בבאם אל אהל מועד.** להקטיר קטרת שחרית ובין הערבים, או להזות מדם פר כהן המשיח ושעירי עבודה זרה: **ולא ימותו.** הא אם לא ירחצו ימותו, שבתורה נאמרו כללות, ומכלל לאו אתה שומע הן: **אל המזבח.** החיצון, שאין כאן ביאת אהל מועד אלא בחצר:
@868 **ולא ימותו.** לחייב מיתה על המשמש במזבח ואינו רחוץ ידים ורגלים, שממיתה הראשונה לא שמענו אלא על הנכנס להיכל:
@870 **בשמים ראש.** חשובים: **וקנמן בשם.** לפי שהקנמון קליפת עץ הוא, יש שהוא טוב ויש בו ריח טוב וטעם, ויש שאינו אלא כעץ, לכך הצרך לומר קנמן בשם, מן הטוב: **מחציתו חמשים ומאתים.** מחצית הבאתו תהא חמשים ומאתים, נמצא כלו חמש מאות, כמו שיעור מר דרור, אם כן, למה נאמר בו חצאין, גזרת הכתוב היא להביאו לחצאין, להרבות בו שתי הכרעות, שאין שוקלין עין בעין, וכך שנויה בכרתות (דף ה א) : **וקנה בשם.** קנה של בשם לפי שיש קנים שאינן של בשם, הצרך לומר בשם: **חמשים ומאתים.** סך משקל כלו:
@871 **וקדה.** שם שרש עשב, ובלשון חכמים קציעה: **הין.** שנים עשר לוגין, ונחלקו בו חכמי ישראל רבי מאיר אומר בו שלקו את העקרין. אמר לו רבי יהודה והלא לסוך את העקרין אינו ספק, אלא שראום במים, שלא יבלעו את השמן, ואחר כך הציף עליהם השמן עד שקלט הריח וקפחו לשמן מעל העקרין:
@872 **רקח מרקחת.** רקח שם דבר הוא, והטעם מוכיח שהוא למעלה, והרי הוא כמו רקח, רגע, ואינו כמו (ישעיה נא טו) רגע הים, וכמו (ישעיה ו מב ה) רקע הארץ, שהטעם למטה, וכל דבר המעורב בחברו, עד שזה קופח מזה או ריח או טעם קרוי מרקחת: **רקח מרקחת.** רקח העשוי על ידי אמנות ותערובות: **מעשה רוקח.** שם האמן בדבר:
@873 **ומשחת בו.** כל המשיחות כמין כי יונית, חוץ משל מלכים שהן כמין נזר:
@876 **וקדשת אתם.** משיחה זו מקדשתם להיות קדש קדשים, ומה היא קדשתם, כל הנגע וגו' , כל הראוי לכלי שרת משנכנס לתוכו קדוש קדשת הגוף לפסל ביוצא ובלינה ובטבול יום, ואינו נפדה לצאת לחלין, אבל דבר שאינו ראוי להם אין מקדשין. ושנויה היא משנה שלמה אצל מזבח, מתוך שנאמר (שמות כט לז) כל הנגע במזבח יקדש, שומע אני בין ראוי בין שאינו ראוי, תלמוד לומר כבשים, מה כבשים ראוים אף כל ראוי. כל משיחת משכן וכהנים ומלכים מתורגם לשון רבוי, לפי שאין צורך משיחתן אלא לגדלה, כי כן יסד המלך, שזה חנוך גדלתן, ושאר משיחות כגון (שמות כט ב) רקיקין משוחין, (עמוס ו ו) וראשית שמנים ימשחו, לשון ארמית בהן כלשון עברית:
@878 **לדרתיכם.** מכאן למדו רבותינו לומר שכלו קים לעתיד לבא: **זה.** בגימטריה תריסר לוגין הוו:
@879 **לא ייסך.** בשני יודי''ן, לשון לא יפעל, כמו (דברים ה טו) למען ייטב לך: **על בשר אדם לא ייסך.** מן השמן הזה עצמו: **ובמתכנתו לא תעשו כמהו.** בסכום סמניו לא תעשו אחר כמוהו במשקל סמנין הללו לפי מדת הין שמן, אבל אם פחת או רבה סממנין לפי מדת הין שמן מתר, ואף העשוי במתכנתו של זה, אין הסך ממנו חיב אלא הרוקחו: **ובמתכנתו.** לשון חשבון, כמו (שמות ה ח) מתכנת הלבנים, וכן במתכנתה של קטורת:
@880 **ואשר יתן ממנו.** מאותו של משה: **על זר.** שאינו צורך כהנה ומלכות:
@881 **נטף.** הוא צרי, ועל שאינו אלא שרף הנוטף מעצי הקטף קרוי נטף ובלעז גומ''א , והצרי קורין לו תירייק''א : **ושחלת.** שרש בשם חלק ומצהיר כצפורן, ובלשון המשנה קרוי צפורן, וזהו שתרגם אנקלוס וטופרא: **וחלבנה.** בשם שריחו רע וקורין לו גלבנא, ומנאה הכתוב בין סמני הקטורת, ללמדנו, שלא יקל בעינינו לצרף עמנו באגדת תעניותינו ותפלותינו את פושעי ישראל שיהיו נמנין עמנו: **סמים.** אחרים: **ולבנה זכה.** מכאן למדו רבותינו אחד עשר סמנין נאמרו לו למשה בסיני מעוט סמים שנים, נטף ושחלת וחלבנה שלשה, הרי חמשה, סמים, לרבות עוד כמו אלו, הרי עשרה, ולבונה הרי אחד עשר ואלו הן הצרי והצפורן, החלבנה והלבונה, מור וקציעה, שבולת נרד וכרכם, הרי שמונה, שהשבולת ונרד אחד, שהנרד דומה לשבולת, הקושט והקלופה והקנמון הרי אחד עשר. בורית כרשינה אינו נקטר אלא בו שפין את הצפורן ללבנה שתהא נאה: **בד בבד יהיה.** אלו הארבעה הנזכרים כאן יהיו שווין משקל במשקל, כמשקלו של זה כך משקלו של זה, וכן שנינו (כריתות ו א) הצרי והצפורן, החלבנה והלבונה משקל שבעים שבעים מנה. ולשון בד נראה בעיני שהוא לשון יחיד, אחד באחד, יהיה זה כמו זה:
@882 **ממלח.** כתרגומו מעורב, שיערב שחיקתן יפה יפה זה עם זה. ואומר אני שדומה לו (יונה א ה) ויראו המלחים, (יחזקאל כז כז) מלחיך וחבליך, על שם שמהפכין את המים במשוטות, כשמנהיגים את הספינה, כאדם המהפך בכף ביצים טרפות לערבן עם המים, וכל דבר שהאדם רוצה לערב יפה יפה, מהפכו באצבע או בבזך: **ממלח טהור קדש.** ממלח יהיה וטהור יהיה וקדש יהיה:
@883 **ונתתה ממנה** וגו' **.** היא קטרת שבכל יום ויום שעל מזבח הפנימי, שהוא באהל מועד: **אשר אועד לך שמה.** כל מועדי דבור שאקבע לך, אני קובעם לאותו מקום:
@884 **במתכנתה.** במנין סממניה: **קדש תהיה לך לה'.** שלא תעשנה אלא לשמי:
@885 **להריח בה.** אבל עושה אתה במתכנתה משלך כדי למסרה לצבור:
@887 **קראתי בשם.** לעשות מלאכתי, את בצלאל:
@888 **בחכמה.** מה שאדם שומע מאחרים ולמד: **ובתבונה.** מבין דבר מלבו, מתוך דברים שלמד: **ובדעת.** רוח הקדש:
@889 **לחשב מחשבת.** אריגת מעשה חשב:
@890 **ובחרשת.** לשון אמנות, כמו (ישעיה מ כ) חרש חכם, ואונקלוס פרש ושנה בפירושן, שחרש אבנים קרוי אמן, וחרש עץ קרוי נגר: **למלאת.** להושיבה במשבצת שלה במלואה, לעשות המשבצת למדת מושב האבן ועביה:
@891 **ובלב כל חכם לב** וגו' **.** ועוד שאר חכמי לב יש בכם, וכל אשר נתתי בו חכמה ועשו את כל אשר צויתיך:
@892 **ואת הארן לעדת.** לצורך לוחות העדות:
@893 **הטהרה.** על שם זהב טהור:
@895 **ואת בגדי השרד.** אומר אני לפי פשוטו של מקרא אי אפשר לומר שבבגדי כהנה מדבר, לפי שנאמר אצלם ואת בגדי הקדש לאהרן הכהן ואת בגדי בניו לכהן, אלא אלו בגדי השרד, הם בגדי התכלת והארגמן ותולעת שני, האמורין בפרשת מסעות (במדבר ד יב) ונתנו עליו בגד תכלת, (שם יג) ופרשו עליו בגד ארגמן, (שם ח) ופרשו עליהם בגד תולעת שני. ונראין דברי, שנאמר (שמות לט א) ומן התכלת והארגמן ותולעת השני עשו בגדי שרד לשרת בקדש, ולא הזכר שש עמהם, ואם בבגדי כהנה מדבר, לא מצינו באחד מהם ארגמן או תולעת שני בלא שש: **בגדי השרד.** יש מפרשים לשון עבודה ושרות, כתרגומו לבושי שמושא, ואין לו דמיון במקרא. ואני אומר, שהוא לשון ארמי, כתרגום של קלעים, ותרגום של מכבר, שהיו ארוגים במחט עשוים נקבים נקבים לצידי''ץ בלעז [רשת] :
@896 **ואת קטרת הסמים לקדש.** לצרך הקטרת ההיכל שהוא קדש:
@898 **ואתה דבר אל בני ישראל.** ואתה, אף על פי שהפקדתיך לצוותם על מלאכת המשכן, אל יקל בעיניך לדחות את השבת מפני אותה מלאכה: **אך את שבתתי תשמרו.** אף על פי שתהיו רדופין וזריזין בזריזות מלאכה שבת אל תדחה מפניה. כל אכין ורקין מיעוטין, למעט שבת ממלאכת המשכן: **כי אות הוא ביני וביניכם.** אות גדולה היא בינינו שבחרתי בכם, בהנחילי לכם את יום מנוחתי למנוחה: **לדעת.** האמות [בה] כי אני ה' מקדשכם:
@899 **מות יומת.** אם יש עדים והתראה: **ונכרתה.** בלא התראה: **מחלליה.** הנוהג בה חול בקדשתה:
@900 **שבת שבתון.** מנוחת מרגוע ולא מנוחת עראי: **שבת שבתון.** לכך כפלו הכתוב לומר שאסור בכל מלאכה, אפלו אוכל נפש, וכן יום הכפורים שנאמר בו (ויקרא כג לב) שבת שבתון הוא לכם, אסור בכל מלאכה, אבל יום טוב לא נאמר בו כי אם ביום הראשון שבתון וביום השמיני שבתון (שם) אסורים בכל מלאכת עבודה, ומתרים במלאכת אוכל נפש: **קדש לה'.** שמירת קדשתה לשמי ובמצותי:
@902 **וינפש.** כתרגומו ונח, וכל לשון נופש והוא לשון נפש, שמשיב נפשו ונשימתו בהרגיעו מטורח המלאכה. ומי שכתוב בו (ישעיה מ כח) לא ייעף ולא ייגע, וכל פעלו במאמר, הכתיב מנוחה לעצמו, לשבר האזן מה שהיא יכולה לשמוע:
@903 **ויתן אל משה** וגו' **.** אין מקדם ומאחר בתורה. מעשה העגל קודם לצווי מלאכת המשכן ימים רבים היה, שהרי בשבעה עשר בתמוז נשתברו הלוחות, וביום הכפורים נתרצה הקדוש ברוך הוא לישראל, ולמחרת התחילו בנדבת המשכן והוקם באחד בניסן: **ככלתו.** ככלתו כתיב חסר, שנמסרה לו תורה במתנה ככלה לחתן, שלא היה יכול ללמוד כלה בזמן מועט כזה. דבר אחר מה כלה מתקשטת בעשרים וארבעה קשוטין, הן האמורים בספר ישעיה (ישעיה ג יח. כד) אף תלמיד חכם צריך להיות בקי בעשרים וארבעה ספרים: **לדבר אתו.** החקים והמשפטים שבואלה המשפטים: **לדבר אתו.** מלמד שהיה משה שומע מפי הגבורה וחוזרין ושונין את ההלכה שניהם יחד: **לחת.** לחת כתיב שהיו שתיהם שוות:
@904 **כי בשש משה.** כתרגומו, לשון אחור, וכן בשש רכבו, (שופטים ה כח) , ויחילו עד בוש (שם ג כה) כי כשעלה משה להר אמר להם לסוף ארבעים יום אני בא בתוך שש שעות. כסבורים הם, שאותו יום שעלה מן המנין הוא, והוא אמר להם שלמים, ארבעים יום ולילו עמו, ויום עליתו אין לילו עמו, שהרי בשבעה בסיון עלה, נמצא יום ארבעים בשבעה עשר בתמוז. בששה עשר בא השטן וערבב את העולם והראה דמות חשך ואפלה וערבוביא לומר ודאי מת משה, לכך בא ערבוביא לעולם. אמר להם מת משה, שכבר באו שש שעות ולא בא וכו' , כדאיתא במסכת שבת (דף פט) . ואי אפשר לומר שלא טעו אלא ביום המענן בין קודם חצות בין לאחר חצות, שהרי לא ירד משה עד יום המחרת, שנאמר וישכימו ממחרת ויעלו עולות: **אשר ילכו לפנינו.** אלהות הרבה אוו להם: **כי זה משה האיש.** כמין דמות משה הראה להם השטן, שנושאים אותו באויר רקיע השמים: **אשר העלנו מארץ מצרים.** והיה מורה לנו דרך, אשר נעלה בה, עתה צריכין אנו לאלהות, אשר ילכו לפנינו:
@905 **באזני נשיכם.** אמר אהרן בלבו הנשים והילדים חסים על תכשיטיהן, שמא יתעכב הדבר, ובתוך כך יבא משה, והם לא המתינו ופרקו מעל עצמן: **פרקו.** לשון צווי, מגזרת פרק ליחיד, כמו ברכו, מגזרת ברך:
@906 **ויתפרקו.** לשון פריקת משא, כשנטלום מאזניהם נמצאו הם מפורקים מנזמיהם, דישקריי''ר בלעז : **את נזמי.** כמו מנזמי, כמו (שמות ט כט) כצאתי את העיר, מן העיר:
@907 **ויצר אותו בחרט.** יש לתרגמו בשני פנים האחד, ויצר לשון קשירה, בחרט לשון סודר, כמו (ישעיה ג כא) והמטפחות והחריטים, (מלכים ב ה כג) ויצר ככרים כסף בשני חריטים. והשני, ויצר לשון צורה, בחרט כלי אמנות הצורפין, שחורצין וחורטין בו צורות בזהב כעט סופר החורט אותיות בלוחות ופנקסין, כמו (ישעיה ח א) וכתב עליו בחרט אנוש. וזהו שתרגם אנקלוס וצר יתיה בזיפא, לשון זיוף הוא כלי אמנות שחורצין בו בזהב אותיות ושקדים, שקורין בלעז ניאי''ל ומזיפין על ידו חותמת: **עגל מסכה.** כיון שהשליכו לכור, באו מכשפי ערב רב שעלו עמהם ממצרים ועשאוהו בכשפים ויש אומרים מיכה היה שם שיצא מתוך דמוסי בנין שנתמעך בו במצרים, והיה בידו שם, וטס שכתב בו משה עלה שור, עלה שור, להעלות ארונו של יוסף מתוך נילוס, והשליכו לתוך הכור ויצא העגל: **מסכה.** לשון מתכת. דבר אחר מאה עשרים וחמשה קנטרין זהב היה בו, כגימטריא של מסכה: **אלה אלהיך.** ולא נאמר אלה אלהינו, מכאן שערב רב שעלו ממצרים, הם שנקהלו על אהרן, והם שעשאוהו, ואחר כך הטעו את ישראל אחריו:
@908 **וירא אהרן.** שהיה בו רוח חיים, שנאמר (תהלים קו כ) בתבנית שור אוכל עשב, וראה שהצליח מעשה שטן, ולא היה לו פה לדחותם לגמרי: **ויבן מזבח.** לדחותם: **ויאמר חג לה' מחר.** ולא היום, שמא יבא משה קודם שיעבדוהו, זהו פשוטו. ומדרשו בויקרא רבה (י, ג) דברים הרבה ראה אהרן, ראה חור בן אחותו, שהיה מוכיחם והרגוהו, וזהו ויבן מזבח לפניו. ויבן מזבוח לפניו. ועוד ראה ואמר מוטב שיתלה בי הסרחון ולא בהם, ועוד ראה ואמר אם הם בונים אותו המזבח, זה מביא צרור וזה מביא אבן, ונמצאת מלאכתן נעשית בבת אחת, מתוך שאני בונה אותו ומתעצל במלאכתי, בין כך ובין כך משה בא: **חג לה'.** בלבו היה לשמים, בטוח היה שיבא משה, ויעבדו את המקום:
@909 **וישכימו.** השטן זרזם כדי שיחטאו: **לצחק.** יש במשמע הזה גלוי עריות, כמו שנאמר (בראשית לט יז) לצחק בי, ושפיכות דמים, כמו שנאמר (שמואל ב' ב יד) יקומו נא הנערים וישחקו לפנינו, אף כאן נהרג חור:
@910 **וידבר.** לשון קושי הוא, כמו (בראשית מב ז) וידבר אתם קשות: **לך רד.** מגדלתך, לא נתתי לך גדלה אלא בשבילם. באותה שעה נתנדה משה מפי בית דין שלמעלה: **שחת עמך.** שחת העם לא נאמר אלא עמך, ערב רב שקבלת מעצמך וגירתם ולא נמלכת בי, ואמרת טוב שידבקו גרים בשכינה, הם שחתו והשחיתו:
@912 **קשה ערף.** מחזרין קשי ערפם לנגד מוכיחיהם, וממאנים לשמוע:
@913 **הניחה לי.** עדין לא שמענו, שהתפלל משה עליהם, והוא אומר הניחה לי, אלא כאן פתח לו פתח והודיעו, שהדבר תלוי בו, שאם יתפלל עליהם לא יכלם:
@914 **למה ה' יחרה אפך.** כלום מתקנא אלא חכם בחכם, גבור בגבור:
@915 **והנחם.** התעשת מחשבה אחרת להטיב להם: **על הרעה.** אשר חשבת להם:
@916 **זכר לאברהם.** אם עברו על עשרת הדברות, אברהם אביהם נתנסה בעשרה נסיונות ועדין לא קבל שכרו, תנהו לו, ויצאו עשרה בעשרה: **לאברהם ליצחק ולישראל.** אם לשרפה הם, זכור לאברהם שמסר עצמו לשרף עליך באור כשדים. אם להריגה, זכור ליצחק שפשט צוארו לעקידה. אם לגלות, זכור ליעקב שגלה לחרן, ואם אינן נצולין בזכותן, מה אתה אומר לי (פסוק י) ואעשה אותך לגוי גדול, ואם כסא של שלש רגלים אינו עומד לפניך בשעת כעסך, קל וחמר לכסא של רגל אחת: **אשר נשבעת להם בך.** לא נשבעת להם בדבר שהוא כלה, לא בשמים ולא בארץ לא בהרים ולא בגבעות, אלא בך, שאתה קים ושבועתך קימת לעולם, שנאמר (ברא' כב טז) בי נשבעתי נאם ה', וליצחק נאמר (שם כו ג) והקימותי את השבועה אשר נשבעתי לאברהם אביך, וליעקב נאמר (שם לה יא) אני אל שדי פרה ורבה, נשבע לו באל שדי:
@918 **משני עבריהם.** היו האותיות נקראות, ומעשה נסים היה:
@919 **מעשה אלהים המה.** כמשמעו הוא בכבודו עשאן. דבר אחר כאדם האומר לחברו כל עסקיו של פלוני במלאכת פלונית, כך כל שעשועיו של הקדוש ברוך הוא בתורה: **חרות.** לשון חרת וחרט אחד הוא, שניהם לשון חקוק אנטייליי''ר בלעז :
@920 **ברעה.** בהריעו, שהיו מריעים ושמחים וצוחקים:
@921 **אין קול ענות גבורה.** אין הקול הזה נראה קול ענית גבורים הצועקים נצחון ולא קול חלשים שצועקים וי או ניסה: **קול ענות.** קול חרופין וגדופין המענין את נפש שומען כשנאמרין לו:
@922 **וישלך מידיו** וגו' **.** אמר מה פסח שהיא אחת מן המצות, אמרה תורה (שמות יב מג) כל בן נכר לא יאכל בו, התורה כלה כאן, וכל ישראל משמדים ואתננה להם: **תחת ההר.** לרגלי ההר:
@923 **ויזר.** לשון נפוץ, וכן (איוב יח טו) יזרה על נוהו גפרית, וכן (משלי א יז) כי חנם מזורה הרשת, שזורין בה דגן וקטניות: **וישק את בני ישראל.** נתכון לבדקן כסוטות. שלש מיתות נדונו שם אם יש עדים והתראה בסייף, כמשפט אנשי עיר הנדחת שהן מרבים, עדים בלא התראה במגפה, שנאמר (פסוק לה) ויגף ה' את העם, לא עדים ולא התראה בהדרוקן, שבדקום המים וצבו בטניהם:
@924 **מה עשה לך העם הזה.** כמה יסורים (סבלת) שיסרוך [סבלת] , עד שלא תביא עליהם חטא זה:
@925 **כי ברע הוא.** בדרך רע הם הולכין תמיד ובנסיונות לפני המקום:
@927 **ואמר להם.** אמרתי להם דבר אחד למי זהב לבד, והם מהרו והתפרקו ויתנו לי: **ואשלכהו באש.** ולא ידעתי שיצא העגל הזה ויצא:
@928 **פרוע.** מגלה. נתגלה שמצו וקלונו, כמו (במדבר ה יח) ופרע את ראש האשה: **לשמצה בקמיהם.** להיות להם הדבר הזה לגנות בפי כל הקמים עליהם:
@929 **מי לה' אלי.** יבא אלי: **כל בני לוי.** מכאן שכל השבט כשר:
@930 **כה אמר** וגו' **.** והיכן אמר, (שמות כב יט) זובח לאלהים יחרם, כך שנויה במכילתא: **אחיו.** מאמו והוא מישראל:
@932 **מלאו ידכם.** אתם ההורגים אותם, בדבר זה תתחנכו להיות כהנים למקום: **כי איש.** מכם ימלא ידו בבנו ובאחיו:
@933 **אכפרה בעד חטאתכם.** אשים כפר וקנוח וסתימה לנגד חטאתכם, להבדיל ביניכם ובין החטא:
@934 **אלהי זהב.** אתה הוא שגרמת להם, שהשפעת להם זהב וכל חפצם, מה יעשו שלא יחטאו. משל למלך שהיה מאכיל ומשקה את בנו ומקשטו ותולה לו כיס בצוארו ומעמידו בפתח בית זונות, מה יעשה הבן שלא יחטא:
@935 **ועתה אם תשא חטאתם.** הרי טוב, איני אומר לך מחני. ואם אין, מחני, וזה מקרא קצר, וכן הרבה: **מספרך.** מכל התורה כלה, שלא יאמרו עלי, שלא הייתי כדאי לבקש עליהם רחמים:
@937 **אל אשר דברתי לך.** יש כאן לך אצל דבור במקום אליך, וכן (מל''א ב יט) לדבר לו על אדוניהו: **הנה מלאכי.** ולא אני: **וביום פקדי** וגו' **.** עתה שמעתי אליך מלכלותם יחד, ותמיד תמיד כשאפקוד עליהם עונותיהם ופקדתי עליהם מעט מן העון הזה עם שאר העונות, ואין פרענות באה על ישראל שאין בה קצת מפרעון עון העגל:
@938 **ויגף ה' את העם.** מיתה בידי שמים, לעדים בלא התראה:
@939 **לך עלה מזה.** ארץ ישראל גבוהה מכל הארצות, לכך נאמר עלה, דבר אחר כלפי שאמר לו בשעת הכעס (שמות לב ז) לך רד, אמר לו בשעת רצון לך עלה: **אתה והעם.** כאן לא נאמר ועמך:
@940 **וגרשתי את הכנעני** וגו' **.** שש אמות הן, והגרגשי עמד ופנה מפניהם מאליו:
@941 **אל ארץ זבת חלב ודבש.** אני אומר לך להעלותם: **כי לא אעלה בקרבך.** לכך אני אומר לך ושלחתי לפניך מלאך: **כי עם קשה ערף אתה.** וכששכינתי בקרבכם ואתם ממרים בי מרבה אני עליכם זעם: **אכלך.** לשון כליון:
@942 **הדבר הרע.** שאין השכינה שורה ומהלכת עמם: **איש עדיו.** כתרים שנתנו להם בחורב, כשאמרו נעשה ונשמע:
@943 **רגע אחד אעלה בקרבך וכליתיך.** אם אעלה בקרבך, ואתם ממרים בי בקשיות ערפכם, אזעום עליכם רגע אחד, שהוא שיעור זעמו, שנאמר (ישעיה כו כ) חבי כמעט רגע עד יעבר זעם, ואכלה אתכם, לפיכך טוב לכם שאשלח מלאך: **ועתה.** פרענות זו תלקו מיד, שתורידו עדיכם מעליכם: **ואדעה מה אעשה לך.** בפקדת שאר העון. אני יודע מה שבלבי לעשות לך:
@944 **את עדים מהר חורב.** את העדי שהיה בידם מהר חורב:
@945 **ומשה.** מאותו עון והלאה: **יקח את האהל.** לשון הוה הוא, לוקח אהלו ונוטהו מחוץ למחנה, אמר מנדה לרב, מנדה לתלמיד: **הרחק.** אלפים אמה, כענין שנאמר (יהושע ג ד) אך רחוק יהיה ביניכם וביניו כאלפים אמה במדה: **וקרא לו.** והיה קורא לו אהל מועד, הוא בית ועד למבקשי תורה: **כל מבקש ה'.** מכאן למבקש פני זקן כמקבל פני השכינה: **יצא אל אהל מועד.** כמו יוצא. דבר אחר והיה כל מבקש ה' אפלו מלאכי השרת כשהיו שואלים מקום שכינה, חבריהם אומרים להם הרי היא באהלו של משה:
@946 **והיה.** לשון הוה: **כצאת משה מן המחנה ללכת אל האהל: יקומו כל העם.** עומדים מפניו ואין יושבין עד שנתכסה מהם: **והביטו אחרי משה.** לשבח, אשרי ילוד אשה שכך מבטח, שהשכינה תכנס אחריו לפתח אהלו:
@947 **ודבר עם משה.** כמו ומדבר עם משה. תרגומו ומתמלל עם משה שהוא כבוד שכינה, כמו (במדבר ז פט) וישמע את הקול מדבר אליו. ואינו קורא מדבר אליו. כשהוא קורא מדבר פתרונו הקול מדבר בינו לבין עצמו, וההדיוט שומע מאליו, וכשהוא קורא מדבר משמע שהמלך מדבר עם ההדיוט:
@948 **והשתחוו.** לשכינה:
@949 **ודבר ה' אל משה פנים אל פנים.** ומתמלל עם משה: **ושב אל המחנה.** לאחר שנדבר עמו, היה משה שב אל המחנה ומלמד לזקנים מה שלמד. והדבר הזה נהג משה מיום הכפורים עד שהוקם המשכן ולא יותר, שהרי בשבעה עשר בתמוז נשתברו הלוחות, ובשמונה עשר שרף את העגל ודן את החוטאים, ובתשעה עשר עלה, שנאמר (שמות לב ל) ויהי ממחרת ויאמר משה אל העם וגו' , עשה שם ארבעים יום ובקש רחמים, שנאמר (דב' ט יח) ואתנפל לפני ה' וגו' , ובראש חדש אלול נאמר לו (שמות לד ב) ועלית בבקר אל הר סיני, לקבל לוחות האחרונות, ועשה שם ארבעים יום, שנאמר בהם (דברים י י) ואנכי עמדתי בהר כימים הראשונים וגו' , מה הראשונים ברצון אף האחרונים ברצון, אמור מעתה אמצעיים היו בכעס. בעשרה בתשרי נתרצה הקדוש ברוך הוא לישראל בשמחה ובלב שלם, ואמר לו למשה סלחתי כדברך, ומסר לו לוחות אחרונות. וירד והתחיל לצוותם על מלאכת המשכן ועשאוהו עד אחד בניסן, ומשהוקם לא נדבר עמו עוד אלא מאהל מועד: **ושב אל המחנה.** תרגומו ותב למשריתא, לפי שהוא לשון הוה, וכן כל הענין. וראה כל העם, וחזן. ונצבו, וקיימין. והביטו, ומסתכלין. והשתחוו, וסגדין. ומדרשו ודבר ה' אל משה שישוב אל המחנה, אמר לו אני בכעס ואתה בכעס, אם כן מי יקרבם:
@950 **ראה אתה אומר אלי.** ראה, תן עיניך ולבך על דבריך. אתה אומר אלי וגו' ואתה לא הודעתני וגו' , ואשר אמרת לי (שמות כג כ) הנה אנכי שולח מלאך, אין זו הודעה, שאין אני חפץ בה: **ואתה אמרת ידעתיך בשם.** הכרתיך משאר בני אדם בשם חשיבות, שהרי אמרת לי (שמות יט ט) הנה אנכי בא אליך בעב הענן וגו' וגם בך יאמינו לעולם:
@951 **ועתה.** אם אמת שמצאתי חן בעיניך הודיעני נא את דרכך, מה שכר אתה נותן למוצאי חן בעיניך: **ואדעך למען אמצא חן בעיניך.** ואדע בזו מדת תגמולך מה היא מציאת חן שמצאתי בעיניך, ופתרון למען אמצא חן, למען אכיר כמה שכר מציאת החן: **וראה כי עמך הגוי הזה.** שלא תאמר ואעשה אותך לגוי גדול, ואת אלה תעזוב, ראה כי עמך הם מקדם, ואם בהם תמאס, איני סומך על היוצאים מחלצי שיתקימו, ואת תשלום השכר שלי בעם הזה תודיעני, ורבותינו דרשוהו במסכת ברכות (דף ז א) ואני לישב המקראות על אפניהם ועל סדרם באתי:
@952 **ויאמר פני ילכו.** כתרגומו, לא אשלח עוד מלאך, אני בעצמי אלך, כמו (שמו''ב יז יא) ופניך הולכים בקרב:
@953 **ויאמר אליו.** בזו אני חפץ, כי על ידי מלאך אל תעלנו מזה:
@954 **ובמה יודע אפוא.** יודע מציאות החן, הלא בלכתך עמנו. ועוד דבר אחר אני שואל ממך שלא תשרה שכינתך [עוד] על אמות העולם: **ונפלינו אני ועמך.** ונהיה מבדלים בדבר הזה מכל העם, כמו (שמות ט ד) והפלה ה' בין מקנה ישראל וגו' :
@955 **גם את הדבר הזה.** שלא תשרה שכינתי עוד על אמות העולם, אעשה, ואין דבריו של בלעם על ידי שרית שכינה, אלא נופל וגלוי עינים, כגון (איוב ד יב) ואלי דבר יגנב, שומעין על ידי שליח:
@956 **ויאמר הראני נא את כבודך.** ראה משה שהיה עת רצון ודבריו מקבלים, והוסיף לשאול להראותו מראית כבודו:
@957 **ויאמר אני אעביר** וגו' **.** הגיעה שעה, שתראה בכבודי מה שארשה אותך לראות, לפי שאני רוצה וצריך ללמדך סדר תפלה, שכשנצרכת לבקש רחמים על ישראל, הזכרת לי זכות אבות, כסבור אתה, שאם תמה זכות אבות אין עוד תקוה, אני אעביר כל מדת טובי לפניך על הצור, ואתה צפון במערה: **וקראתי בשם ה' לפניך.** ללמדך סדר בקשת רחמים אף אם תכלה זכות אבות, וכסדר זה שאתה רואה אותי מעטף וקורא שלש עשרה מדות הוי מלמד את ישראל לעשות כן, ועל ידי שיזכירו לפני רחום וחנון יהיו נענין כי רחמי לא כלים: **וחנתי את אשר אחן.** אותן פעמים שארצה לחון: **ורחמתי.** עת שאחפוץ לרחם. עד כאן לא הבטיחו אלא עתים אענה עתים לא אענה, אבל בשעת מעשה אמר לו (שמות לד י) הנה אנכי כורת ברית, הבטיחו שאינן חוזרות ריקם:
@958 **ויאמר לא תוכל** וגו' **.** אף כשאעביר כל טובי על פניך איני נותן לך רשות לראות את פני:
@959 **הנה מקום אתי.** בהר אשר אני מדבר עמך תמיד, יש מקום מוכן לי לצרכך שאטמינך שם שלא תזוק, ומשם תראה מה שתראה, זהו פשוטו. ומדרשו על מקום שהשכינה שם מדבר ואומר המקום אתי, ואינו אומר אני במקום, שהקדוש ברוך הוא מקומו של עולם ואין עולמו מקומו:
@960 **בעבר כבדי.** כשאעבור לפניך: **בנקרת הצור.** כמו (במדבר טז יד) העיני האנשים ההם תנקר, (משלי ל יז) יקרוה עורבי נחל, (מלכים ב' יט כד) אני קרתי ושתיתי מים, גזרה אחת להם, נקרת הצור כרית הצור: **ושכתי כפי.** מכאן שנתנה רשות למחבלים לחבל, ותרגומו ואגין במימרי, כנוי הוא לדרך כבוד של מעלה, שאינו צריך לסוכך עליו בכף ממש:
@961 **והסרותי את כפי.** ואעדי ית דברת יקרי, כשאסלק הנהגת כבודי מנגד פניך ללכת משם ולהלן: **וראית את אחרי.** הראהו קשר של תפלין:
@962 **פסל לך.** הראהו מחצב סנפירינון מתוך אהלו, ואמר לו הפסולת יהיה שלך, ומשם נתעשר משה הרבה: פסל לך. אתה שברת הראשונות, אתה פסל לך אחרות. משל למלך שהלך למדינת הים והניח ארוסתו עם השפחות, מתוך קלקול השפחות יצא עליה שם רע, עמד שושבינה וקרע כתבתה, אמר אם יאמר המלך להרגה אומר לו עדיין אינה אשתך. בדק המלך ומצא, שלא היה הקלקול אלא מן השפחות, נתרצה לה. אמר לו שושבינה כתוב לה כתבה אחרת, שנקרעה הראשונה. אמר לו המלך אתה קרעת אותה, אתה קנה לך ניר אחר, ואני אכתוב לה בכתב ידי, כן המלך זה הקדוש ברוך הוא, השפחות אלו ערב רב, והשושבין זה משה, ארוסתו של הקדוש ברוך הוא אלו ישראל, לכך נאמר פסל לך:
@963 **נכון.** מזמן:
@964 **ואיש לא יעלה עמך.** הראשונות על ידי שהיו בתשואות וקולות וקהלה, שלטה בהן עין רעה, אין לך מדה יפה מן הצניעות:
@966 **ויקרא בשם ה'.** מתרגמינן וקרא בשמא דה':
@967 **ה' ה'.** מדת הרחמים היא, אחת קדם שיחטא, ואחת אחר שיחטא וישוב: **אל.** אף זו מדת רחמים, וכן הוא אומר (תהלים כב ב) אלי אלי למה עזבתני, ואין לומר למדת הדין למה עזבתני כך מצאתי במכילתא: **ארך אפים.** מאריך אפו ואינו ממהר לפרע, שמא יעשה תשובה: **ורב חסד.** לצריכים חסד, שאין להם זכיות כל כך: **ואמת.** לשלם שכר טוב לעושי רצונו:
@968 **נצר חסד.** שהאדם עושה לפניו: **לאלפים.** לשני אלפים דורות: **עון ופשע.** עונות אלו הזדונות. פשעים אלו המרדים, שאדם עושה להכעיס: **ונקה לא ינקה.** לפי פשוטו משמע, שאינו מותר על העון לגמרי, אלא נפרע ממנו מעט מעט. ורבותינו דרשו מנקה הוא לשבים ולא ינקה לשאינן שבים: **פקד עון אבות על בנים.** כשאוחזים מעשה אבותיהם בידיהם, שכבר פרש במקרא אחר (שמות כ ד) לשונאי: **ועל רבעים.** דור רביעי, נמצאת מדה טובה מרבה על מדת פרענות אחת לחמש מאות, שבמדה טובה הוא אומר נוצר חסד לאלפים:
@969 **וימהר משה.** כשראה משה שכינה עוברת ושמע קול הקריאה, מיד וישתחו:
@970 **ילך נא ה' בקרבנו.** כמו שהבטחת, מאחר שאתה נושא עון, ואם עם קשה ערף הוא וימרו בך, ואמרת על זאת פן אכלך בדרך, אתה תסלח לעונינו. ויש כי במקום אם: **ונחלתנו.** ותתננו לך לנחלה מיחדת, זו היא בקשת ונפלינו אני ועמך, שלא תשרה שכינתך על האמות:
@971 **כרת ברית.** על זאת: **אעשה נפלאות.** לשון ונפלינו שתהיו מבדלים בזו מכל האמות, שלא תשרה שכינתי עליהם:
@972 **את האמרי** וגו' **.** שש אמות יש כאן, כי הגרגשי עמד ופנה מפניהם:
@974 **אשריו.** הוא אילן שעובדים אותו:
@975 **קנא שמו.** מקנא להפרע ואינו מותר, וזהו כל לשון קנאה, אוחז בנצחונו ופורע מעוזביו:
@976 **ואכלת מזבחו.** כסבור אתה שאין עונש באכילתו, ואני מעלה עליך כמודה בעבודתם, שמתוך כך אתה בא ולוקח מבנותיו לבניך:
@979 **חדש האביב.** חדש הבכור, שהתבואה מבכרת בבשולה:
@980 **כל פטר רחם לי.** באדם: **וכל מקנך תזכר** וגו' **.** וכל מקנך אשר תזכר בפטר שור ושה, אשר יפטור זכר את רחמה: **פטר.** לשון פתיחה, וכן (משלי יז יד) פוטר מים ראשית מדון. תי''ו של תזכר לשון נקבה היא, מוסב על היולדת:
@981 **ופטר חמור.** ולא שאר בהמה טמאה: **תפדה בשה.** נותן שה לכהן, והוא חלין ביד כהן, ופטר חמור מתר בעבודה לבעלים: **וערפתו.** עורפו בקופיץ, הוא הפסיד ממון כהן, לפיכך יפסד ממונו: **כל בכור בניך תפדה.** חמשה סלעים פדיונו קצוב, שנאמר (במדבר יח טז) ופדויו מבן חדש תפדה: **ולא יראו פני ריקם.** לפי פשוטו של מקרא דבר בפני עצמו הוא, ואינו מוסב על הבכור, שאין במצות בכור ראית פנים, אלא אזהרה אחרת היא וכשתעלו לרגל לראות לא יראו פני ריקם, מצוה עליכם להביא עולת ראית פנים, ולפי מדרש ברייתא מקרא יתר הוא, ומפנה לגזרה שוה, ללמד על הענקתו של עבד עברי שהיא חמשה סלעים מכל מין ומין, כפדיון בכור, במסכת קדושין (דף יז א) :
@982 **בחריש ובקציר תשבת.** למה נזכר חריש וקציר, יש מרבותינו אומרים על חריש של ערב שביעית הנכנס לשביעית, וקציר של שביעית היוצא למוצאי שביעית, ללמדך שמוסיפין מחול על הקדש. וכך משמעו, ששת ימים תעבד וביום השביעי תשבת ועבודת ששת הימים שהתרתי לך יש שנה שהחריש והקציר אסור, ואין צריך לומר חריש וקציר של שביעית, שהרי כבר נאמר (ויקרא כה ד) שדך לא תזרע וגו' ויש מהם אומרים, שאינו מדבר אלא בשבת, וחריש וקציר שהזכר בו, לומר לך מה חריש רשות אף קציר רשות, יצא קציר העמר, שהוא מצוה ודוחה את השבת:
@983 **בכורי קציר חטים.** שאתה מביא בו שתי הלחם מן החטים: **בכורי.** שהיא מנחה ראשונה הבאה מן החדש של חטים למקדש, כי מנחת העמר הבאה בפסח מן השעורים היא: **וחג האסיף.** בזמן שאתה אוסף תבואתך מן השדה לבית. אסיפה זו לשון הכנסה לבית, כמו (דברים כב ב) ואספתו אל תוך ביתך: **תקופת השנה.** שהיא בחזרת השנה, בתחלת השנה הבאה: **תקופת.** לשון מסבה והקפה:
@984 **כל זכורך.** כל הזכרים שבך. הרבה מצות בתורה נאמרו ונכפלו, ויש מהם שלש פעמים וארבע, לחייב ולענוש על מנין לאוין שבהם ועל מנין עשה שבהם:
@985 **אוריש.** כתרגומו אתרך, וכן (דברים ב לא) החל רש, וכן (במדבר כא לב) ויורש את האמורי, לשון גרושין: **והרחבתי את גבלך.** ואתה רחוק מבית הבחירה ואינך יכול לראות לפני תמיד, לכך אני קובע לך שלש רגלים הללו:
@986 **לא תשחט** וגו' **.** לא תשחט את הפסח ועדין חמץ קים, אזהרה לשוחט או לזורק או לאחד מבני החבורה: **ולא ילין.** כתרגומו. אין לינה מועלת בראש המזבח, ואין לינה אלא בעמוד השחר: **זבח חג הפסח.** אימוריו, ומכאן אתה למד לכל הקטר חלבים ואברים:
@987 **ראשית בכורי אדמתך.** משבעת המינין האמורים בשבח ארצך (דברים ח ח) ארץ חטה ושעורה וגפן ותאנה ורמון, ארץ זית שמן ודבש, הוא דבש תמרים: **לא תבשל גדי.** אזהרה לבשר בחלב, ושלש פעמים כתוב בתורה אחד לאכילה, ואחד להנאה, ואחד לאסור בשול: **גדי.** כל ולד רך במשמע ואף עגל וכבש. ממה שהצרך לפרש בכמה מקומות (בראשית לח יז) גדי עזים, למדת שגדי סתם כל יונקים במשמע: **בחלב אמו.** פרט לעוף שאין לו חלב אם, שאין אסורו מן התורה אלא מדברי סופרים:
@988 **את הדברים האלה.** ולא אתה רשאי לכתוב תורה שבעל פה:
@990 **ויהי ברדת משה.** כשהביא לוחות אחרונות ביום הכפורים: **כי קרן.** לשון קרנים, שהאור מבהיק ובולט כמין קרן. ומהיכן זכה משה לקרני ההוד, רבותינו אמרו מן המערה, שנתן הקדוש ברוך הוא ידו על פניו, שנאמר (שמות לג כב) ושכתי כפי:
@991 **וייראו מגשת אליו.** בא וראה, כמה גדולה כחה של עברה, שעד שלא פשטו ידיהם בעברה, מהו אומר (שמות כד יז) ומראה כבוד ה' כאש אוכלת בראש ההר לעיני בני ישראל, ולא יראים ולא מזדעזעים, ומשעשו את העגל, אף מקרני הודו של משה היו מרתיעים ומזדעזעים:
@992 **הנשאים בעדה.** כמו נשיאי העדה: **וידבר משה אליהם.** שליחותו של מקום, ולשון הוה הוא כל הענין הזה:
@993 **ואחרי כן נגשו.** אחר שלמד לזקנים, חזר ומלמד הפרשה או ההלכה לישראל. תנו רבנן כיצד סדר המשנה, משה היה לומד מפי הגבורה, נכנס אהרן, שנה לו משה פרקו, נסתלק אהרן וישב לו לשמאל משה, נכנסו בניו, שנה להם משה פרקם, נסתלקו הם, ישב אלעזר לימין משה ואיתמר לשמאל אהרן, נכנסו זקנים, שנה להם משה פרקם, נסתלקו זקנים ישבו לצדדין, נכנסו כל העם שנה להם משה פרקם, נמצא ביד כל העם אחד, ביד הזקנים שנים, ביד בני אהרן שלשה, ביד אהרן ארבעה וכו' כדאיתא בעירובין (נד ב) :
@994 **ויתן על פניו מסוה.** כתרגומו בית אפי, לשון ארמי הוא בתלמוד סוי לבא ועוד בכתבות (ס א) הוה קא מסוה לאפה, לשון הבטה, היה מסתכל בה, אף כאן מסוה בגד הנתן כנגד הפרצוף ובית העינים, ולכבוד קרני ההוד שלא יזונו הכל מהם היה נותן המסוה כנגדן ונוטלו בשעה שהיה מדבר עם ישראל, ובשעה שהמקום נדבר עמו עד צאתו, ובצאתו יצא בלא מסוה:
@995 **ודבר אל בני ישראל.** וראו קרני ההוד בפניו. וכשהוא מסתלק מהם:
@996 **והשיב משה את המסוה על פניו עד באו לדבר אתו.** וכשבא לדבר אתו נוטלו מעל פניו:
@997 **ויקהל משה.** למחרת יום הכפורים כשירד מן ההר, והוא לשון הפעיל, שאינו אוסף אנשים בידים, אלא הן נאספים על פי דבורו, ותרגומו ואכנש:
@998 **ששת ימים.** הקדים להם אזהרת שבת לצווי מלאכת המשכן, לומר שאינה דוחה את השבת:
@999 **לא תבערו אש.** יש מרבותינו אומרים הבערה ללאו יצאת, ויש אומרים לחלק יצאת:
@1000 **זה הדבר אשר צוה ה'.** לי לאמר לכם:
@1001 **נדיב לבו.** על שם שלבו נדבו קרוי נדיב לב. כבר פרשתי נדבת המשכן ומלאכתו במקום צואתן:
@1007 **את המשכן.** יריעות התחתונות הנראות בתוכו קרויים משכן: **את אהלו.** הוא אהל יריעות עזים העשוי לגג: **ואת מכסהו.** מכסה עורות האילים והתחשים:
@1008 **ואת פרכת המסך.** פרוכת המחצה. כל דבר המגין, בין מלמעלה בין מכנגד, קרוי מסך וסכך, וכן (איוב א י) שכת בעדו, (הושע ב ח) הנני שך את דרכך:
@1009 **לחם הפנים.** כבר פרשתי (שמות כה כח) על שם שהיו לו פנים לכאן ולכאן, שהוא עשוי כמין תבה פרוצה:
@1010 **ואת כליה.** מלקחים ומחתות: **נרתיה.** לוציי''ש בלעז בזכים שהשמן והפתילות נתונין בהן: **ואת שמן המאור.** אף הוא צריך חכמי לב, שהוא משנה משאר שמנים, כמו שמפורש במנחות (דף פו א) מגרגרו בראש הזית, והוא כתית וזך:
@1011 **מסך הפתח.** וילון שלפני המזרח שלא היו שם לא קרשים ולא יריעות:
@1013 **את עמודיו ואת אדניה.** הרי חצר קרוי כאן לשון זכר ולשון נקבה, וכן דברים הרבה: **ואת מסך שער החצר.** וילון פרוש לצד המזרח עשרים אמה אמצעיות של רוחב החצר, שהיה חמשים רחב, וסתומין המנו לצד צפון חמש עשרה אמה וכן לדרום, שנאמר (שמות כז יד) וחמש עשרה אמה קלעים לכתף:
@1014 **יתדת.** לתקוע ולקשור בהם סופי היריעות בארץ שלא ינועו ברוח: **מיתריהם.** חבלים לקשור:
@1015 **בגדי השרד.** לכסות הארון והשלחן, והמנורה והמזבחות בשעת סלוק מסעות:
@1018 **על הנשים.** עם הנשים וסמוכין אליהם: **חח.** הוא תכשיט של זהב עגול נתון על הזרוע, והוא הצמיד: **וכומז.** כלי זהב הוא נתון כנגד אותו מקום לאשה. ורבותינו פרשו שם כומז כאן מקום זמה:
@1019 **וכל איש אשר נמצא אתו.** תכלת או ארגמן או תולעת שני או עורות אילים או תחשים כלם הביאו:
@1022 **טוו את העזים.** היא היתה אמנות יתרה, שמעל גבי העזים טווין אותן:
@1023 **והנשאם הביאו.** אמר ר' נתן מה ראו נשיאים להתנדב בחנכת המזבח בתחלה, ובמלאכת המשכן לא התנדבו בתחלה, אלא כך אמרו נשיאים יתנדבו צבור מה שמתנדבין, ומה שמחסירים אנו משלימין אותו. כיון שהשלימו צבור את הכל, שנאמר (שמות לו ז) והמלאכה היתה דים, אמרו נשיאים מה עלינו לעשות, הביאו את אבני השהם וגו' , לכך התנדבו בחנכת המזבח תחלה. ולפי שנתעצלו מתחלה נחסרה אות משמם והנשאם כתיב:
@1026 **חור.** בנה של מרים היה:
@1030 **ואהליאב.** משבט דן, מן הירודין שבשבטים מבני השפחות, והשוהו המקום לבצלאל למלאכת המשכן, והוא מגדולי השבטים, לקים מה שנאמר (איוב לד יט) ולא נכר שוע לפני דל:
@1036 **מדי העבדה.** יותר מכדי צורך העבודה:
@1037 **ויכלא.** לשון מניעה:
@1038 **והמלאכה היתה דים לכל המלאכה.** ומלאכת ההבאה היתה דים של עושי המשכן. **לכל המלאכה.** של משכן **לעשות אותה.** ולהותיר: **והותר.** כמו (שמות ח יא) והכבד את לבו, (מלכים ב' ג כד) והכות את מואב:
@1070 **ויעש בצלאל.** לפי שנתן נפשו על המלאכה יותר משאר חכמים, נקראת על שמו:
@1105 **נבוב לחת.** נבוב הוא חלול, וכן (ירמיה נב, כא) ועביו ארבע אצבעות נבוב: **נבוב לחת.** הלוחות של עצי שטים לכל רוח והחלל באמצע:
@1106 **במראת הצובאת.** בנות ישראל היו בידן מראות, שרואות בהן כשהן מתקשטות, ואף אותן לא עכבו מלהביא לנדבת המשכן, והיה מואס משה בהן, מפני שעשויים ליצר הרע, אמר לו הקדוש ברוך הוא קבל, כי אלו חביבין עלי מן הכל, שעל ידיהם העמידו הנשים צבאות רבות במצרים. כשהיו בעליהם יגעים בעבודת פרך, היו הולכות ומוליכות להם מאכל ומשתה ומאכילות אותם ונוטלות המראות, וכל אחת רואה עצמה עם בעלה במראה ומשדלתו בדברים, לומר אני נאה ממך, ומתוך כך מביאות לבעליהן לידי תאוה ונזקקות להם, ומתעברות ויולדות שם, שנאמר (שיר השירים ח ה) תחת התפוח עוררתיך, וזהו שנאמר במראות הצובאות. ונעשה הכיור מהם, שהוא לשום שלום בין איש לאשתו, להשקות ממים שבתוכו את שקנא לה בעלה ונסתרה, ותדע לך, שהן מראות ממש, שהרי נאמר (שמות לח כט ל) , ונחשת התנופה שבעים ככר וגו' , ויעש בה וגו' , וכיור וכנו לא הזכרו שם, למדת שלא היה נחשת של כיור מנחשת התנופה, כך דרש רבי תנחומא, וכן תרגם אנקלוס במחזית נשיא, והוא תרגום של מראות מירידויר''ש בלעז . וכן מצינו בישעיה (ישעיה ג כג) והגליונים, מתרגמנן ומחזיתא: **אשר צבאו.** להביא נדבתן:
@1116 **לעמת קלעי החצר.** כמדת קלעי החצר:
@1119 **אלה פקודי.** בפרשה זו נמנו כל משקלי נדבת המשכן, לכסף ולזהב ולנחשת, ונמנו כל כליו לכל עבודתו: **המשכן משכן.** שני פעמים, רמז למקדש שנתמשכן בשני חורבנין על עונותיהן של ישראל: **משכן העדת.** עדות לישראל שותר להם הקדוש ברוך הוא על מעשה העגל, שהרי השרה שכינתו ביניהם: **עבדת הלוים.** פקודי המשכן וכליו היא עבודה המסורה ללוים במדבר, לשאת ולהוריד להקים איש איש למשאו המפקד עליו, כמו שאמרו בפרשת נשא (במדבר ד) : **ביד איתמר.** הוא היה פקיד עליהם למסור לכל בית אב עבודה שעליו:
@1120 **ובצלאל בן אורי** וגו' **עשה את כל אשר צוה ה' את משה.** אשר צוה משה אין כתיב כאן, אלא כל אשר צוה ה' את משה, אפלו דברים שלא אמר לו רבו, הסכימה דעתו למה שנאמר למשה בסיני, כי משה צוה לבצלאל לעשות תחלה כלים ואחר כך משכן, אמר לו בצלאל מנהג עולם לעשות תחלה בית ואחר כך משים כלים בתוכו. אמר לו כך שמעתי מפי הקדוש ברוך הוא. אמר לו משה בצל אל היית, כי בודאי כך צוה לי הקדוש ברוך הוא, וכן עשה המשכן תחלה ואחר כך עשה הכלים:
@1122 **ככר.** ששים מנה, ומנה של קדש כפול היה, הרי הככר מאה ועשרים מנה, והמנה עשרים וחמשה סלעים, הרי ככר של קדש שלשת אלפים שקלים, לפיכך מנה בפרוטרוט כל השקלים שפחותין במנינם משלשת אלפים שאין מגיעין לככר:
@1124 **בקע.** הוא שם משקל של מחצית השקל: **לשש מאות אלף** וגו' **.** כך היו ישראל, וכך עלה מנינם אחר שהוקם המשכן בספר במדבר. ואף עתה בנדבת המשכן כך היו. ומנין חצאי השקלים של שש מאות אלף עולה מאת ככר, כל אחד של שלשת אלפים שקלים, כיצד, שש מאות אלף חצאין הרי הן שלש מאות אלף שלמים, הרי מאת ככר, והשלשת אלפים וחמש מאות וחמשים חצאין עולין אלף ושבע מאות וחמשה ושבעים שקלים:
@1125 **לצקת.** כתרגומו לאתכא: **את אדני הקדש.** של קרשי המשכן, שהם ארבעים ושמנה קרשים ולהם תשעים וששה אדנים, ואדני פרכת ארבעה, הרי מאה וכל שאר האדנים נחשת כתיב בהם:
@1126 **וצפה ראשיהם.** של עמודים, מהן, שבכלן כתיב וצפה ראשיהם וחשוקיהם כסף.
@1130 **ומן התכלת והארגמן** וגו' **.** שש לא נאמר כאן, ומכאן אני אומר, שאין בגדי שרד הללו בגדי כהנה, שבבגדי כהנה היה שש, אלא הם בגדים שמכסים בהם כלי הקדש בשעת סלוק מסעות, שלא היה בהם שש:
@1132 **וירקעו.** כמו (תהלים קלו ו) לרוקע הארץ, כתרגומו ורדידו טסין היו מרדדין מן הזהב, אישטינדר''א בלעז , טסין דקין. כאן הוא מלמדך, היאך היו טווין את הזהב עם החוטין מרדדין הטסין דקין וקוצצין מהן פתילים לאורך הטס, לעשות אותן פתילים מעורבין עם כל מין ומין בחשן ואפוד שנאמר בהן זהב, חוט אחד של זהב עם ששה חוטין של תכלת, וכן עם כל מין ומין. שכל המינים חוטן כפול ששה, והזהב חוט שביעי עם כל אחד ואחד:
@1157 **ואת פארי המגבעות.** תפארת המגבעות, המגבעות המפוארות:
@1160 **לתת על המצנפת מלמעלה.** ועל ידי הפתילים היה מושיבו על המצנפת כמין כתר, ואי אפשר לומר הציץ על מצנפת שהרי בשחיטת קדשים שנינו (זבחים יט א) שערו היה נראה בין ציץ למצנפת, ששם מניח תפלין, והציץ היה נתון על המצח, הרי המצנפת למעלה והציץ למטה, ומהו על המצנפת מלמעלה, ועוד הקשיתי בה, כאן הוא אומר ויתנו עליו פתיל תכלת, ובענין הצואה הוא אומר (שמות כח לז) ושמת אותו על פתיל תכלת. ואומר אני פתיל תכלת זה חוטין הן לקשרו בהן במצנפת, לפי שהציץ אינו אלא מאוזן לאוזן, ובמה יקשרנו במצחו, והיו קבועין בו חוטי תכלת לשני ראשיו ובאמצעיתו, שבהן קושרו ותולהו במצנפת כשהוא בראשו, ושני חוטין היו בכל קצה וקצה אחד ממעל ואחד מתחת לצד מצחו, וכן באמצעו, שכך הוא נוח לקשור, ואין דרך קשירה בפחות משני חוטין, לכך נאמר (שמות כח לז) על פתיל תכלת, ועליו פתיל תכלת, וקשר ראשיהם השנים כלם יחד מאחוריו למול ערפו, ומושיבו על המצנפת. ואל תתמה שלא נאמר פתילי תכלת, הואיל ומרבין הן, שהרי מצינו בחשן ואפוד וירכסו את החשן וגו' בפתיל תכלת. ועל כרחך פחות משנים לא היו, שהרי בשתי קצות החשן היו שתי טבעות החשן, ובשתי כתפות האפוד היו שתי טבעות האפוד שכנגדן, ולפי דרך קשירה ארבע חוטין היו, ומכל מקום פחות משנים אי אפשר:
@1161 **ויעשו בני ישראל.** את המלאכה ככל אשר צוה ה' וגו' :
@1162 **ויביאו את המשכן** וגו' **.** שלא היו יכולין להקימו, ולפי שלא עשה משה שום מלאכה במשכן, הניח לו הקדוש ברוך הוא הקמתו, שלא היה יכול להקימו שום אדם מחמת כובד הקרשים, שאין כח באדם לזקפן, ומשה העמידו. אמר משה לפני הקדוש ברוך הוא איך אפשר הקמתו על ידי אדם, אמר לו עסוק אתה בידך נראה כמקימו, והוא נזקף וקם מאליו, וזהו שנאמר (שמות מ יז) הוקם המשכן, הוקם מאליו. מדרש רבי תנחומא:
@1172 **ויברך אתם משה.** אמר להם יהי רצון שתשרה שכינה במעשה ידיכם, (תהלים צ יז) ויהי נעם ה' אלהינו עלינו ומעשה ידינו וגו' , והוא אחד מאחד עשר מזמורים שבתפלה למשה:
@1175 **וסכת על הארן.** לשון הגנה, שהרי מחצה היתה:
@1176 **וערכת את ערכו.** שתי מערכות של לחם הפנים:
@1191 **ויפרש את האהל.** הן יריעות העזים:
@1192 **את העדות.** הלוחות:
@1194 **על ירך המשכן צפונה.** בחצי הצפוני של רוחב הבית: **ירך.** כתרגומו צדא, כירך הזה שהוא בצדו של אדם:
@1199 **ויקטר עליו.** אהרן: **קטרת.** שחרית וערבית, כמו שנאמר (שמות ל ז) בבקר בבקר בהיטיבו את הנרות וגו' :
@1201 **ויעל עליו** וגו' **.** אף ביום השמיני למלואים, שהוא יום הקמת המשכן, שמש משה והקריב קרבנות צבור, חוץ מאותן שנצטוו בו ביום, שנאמר (ויקרא ט ז) קרב אל המזבח וגו' : **את העלה.** עולת התמיד: **ואת המנחה.** מנחת נסכים של תמיד, כמו שנאמר (שמות כט מ) ועשרן סלת בלול בשמן וגו' :
@1203 **ורחצו ממנו משה ואהרן ובניו.** יום שמיני למלואים הושוו כלם לכהנה, ותרגומו ומקדשין מניה, בו ביום קדש משה עמהם:
@1204 **ובקרבתם.** כמו ובקרבם כשיקרבו:
@1207 **ולא יכל משה לבוא אל אהל מועד.** וכתוב אחד אומר (במדבר ז פט) ובבא משה אל אהל מועד, בא הכתוב השלישי והכריע ביניהם, כי שכן עליו הענן, אמור מעתה כל זמן שהיה עליו הענן לא היה יכול לבא, נסתלק הענן נכנס ומדבר עמו:
@1210 **לעיני כל בית ישראל בכל מסעיהם.** בכל מסע שהיו נוסעים היה הענן שוכן במקום אשר יחנו שם. מקום חניתן אף הוא קרוי מסע, וכן (בראשית יג ג) וילך למסעיו, וכן (במדבר לג א) אלה מסעי לפי שממקום החניה חזרו ונסעו, לכך נקראו כלן מסעות:

@1 **ואלה שמות בני ישראל**. טעם אומרו ואלה בתוספת וא''ו ללמוד עליהם כי כולם צדיקים כאבותיהם ואלה מוסיף על הראשונים מה ראשונים להם אברהם יצחק יעקב צדיקים עליונים כמעשה אבות עשו הבנים.
@1 **עוד** ירצה על דרך אומרם ז''ל (תנחומא שמות ד') כי זמן הגלות התחיל מימי אברהם משנולד יצחק, והוא אומרו ואלה וגו' הבאים מצרימה מוסיף על הראשונים לומר לך שגם הראשונים בגלות היו ואלה עמהם.
@1 **עוד** ירצה מה הראשונים ידעו והכירו בגלות וקבלו עליהם ועל זרעם כמו כן אלה. והוא אומרו ואלה מוסיף על הראשונים ולדרך זה הרוחנו טעם נכון לדעת לאיזה ענין חזר הכתוב ומנאם אחר שכבר מנאם בפרשת ויגש בירידתם למצרים, ורש''י ז''ל פירש כי להודיע חבתם חזר ומנאם במותם, ואין דבר זה מספיק אלא לדרשה ולא לפשטן של דברים, ועוד לדבריו היה לו לקבוע המנין אחר אומרו וימת יוסף וגו' ואלה שמות וגו', ולדרכנו הכתוב יודיע טעם מניינם שמונה הוא והולך בספר התורה מי ומי הבא לקבל גזירת מלך לסבול עול הגלות ולא פנה עורף כמעשה עשו הרשע (בראשית לו) שהלך לו אל ארץ מפני יעקב, ודרשו ז''ל (ב''ר פ' פ''ב) מפני שטר חוב של הגלות, ואמר ואלה שמות וגו' הבאים מצרימה פי' הבאים לסבול עול הגלות במצרים את יעקב אתו בדומין לו בהסכמה אחת לפרוע שטר חוב הגלות. לזה דקדק לומר **הבאים**, פירוש הגם שלא באו חפצים היו לבוא, וזה לך האות **איש וביתו באו** כאדם שמכין עצמו על הדבר, ואלו ירדו מצרים לסיבה ידועה לא היו עוקרים דירתם ובאים והיו באים ביאת עראי ורגליהם רגל ישרה לשוב ארצה כנען. וטעם שחזר לומר **באו** ולא הספיק במה שהקדים לומר הבאים, נתכוון לעשות הפרש בין המנויים בפרשה לאנשי ביתם כי אנשי ביתם אין כולם בגדר זה. ועי' מה שכתבתי בפרשת ויגש בפסוק בניו ובני בניו וגו' כי הם דוקא היו חפצים בדבר. והגם שלא מנה כאן אלא י''ב שבטים, אולי שהם היו בגדר בפני עצמם בדומה ליעקב.
@1 **או** יתבאר הכתוב על זה הדרך **ואלה שמות** בנ''י הבאים מרצונם וחפצם מצרימה הרשומים ראובן שמעון וגו', אבל כל שאר יוצאי ירך יעקב לצד שבא יעקב באו עמו, והוא אומרו **את יעקב איש וביתו באו**, וזולת ביאת יעקב לא היו באים כולם, ולזה הוצרך לומר באו פעם שנית:
@1 **עוד** ירצה אומרו **הבאים** וגו' שבא לומר מופת חותך כי ברצונם באו והראיה שאחר מות אביהם ועלו ארצה כנען חזרו פעם ב' כאמור בפרשת ויחי, והוא אומרו הבאים מצרימה את יעקב מחדש איש וביתו. באו אחר שעלו משם חזרו למצרים איש וביתו ומנה הכתוב מי הם בעלי צדקות זה ראובן וגו' הא למדת כי ענפי האילן כאילן עצמו שוים לחפוץ בגזירת מלך ויכתב בספר זכרון לפניו ליראי ה' וגו':
@5 **ויהי כל נפש וגו'** ויוסף וגו'. צריך לדעת למה אמר, ויהי לשון צער, ואם על הגלות אין זה מקום הדבר. גם צריך לדעת אומרו **כל**.
@5 **עוד** למה הוצרך לחזור להודיע מנין יוצאי ירך יעקב וכבר השמיענו וידענום. עוד מה הודעה זו כדבר חדש ויוסף היה במצרים.
@5 **ואולי** שיכון הכתוב לומר על דרך אומרם ז''ל (סוטה ל''ו) שעתיד היה יוסף להעמיד י''כ שבטים ומי סבב שלא העמיד אלא ב' הוא פגע רע שפגעתו אשת פוטיפר ויפוזו זרועי ידיו ע''כ, הא למדת שזולת זה הי' יוסף מעמיד י''ב שבטים, והוא אומרו **ויהי** לשון צער שמצטערת התורה על שלא היו בין הכל אלא שבעים נפש, והוא אומרו **כל נפש** וגו', ונתן הטעם לדבר שלא היו אלא ע' ואמר **ויוסף היה** וגו' ודין גרמא שלא היו, יוצאי ירך יעקב אלא ע' נפש שזולת זה אם לא ירד יוסף למצרים היה יוסף מעמיד י''ב שבטים והיו בני יעקב שמונים ענפים, ובזה נתיישבו כל הדקדוקים יחד.
@5 **עוד** יכוין הכתוב באומרו **כל נפש** וגו' **ויוסף** וגו' לומר כי כללות ענפים אלו כולם שוים לטובה באין הבדל. ביניהם כולם צדיקים כולם חכמים כולם בלב שלם זה על זה וכאלו כולם נפש אחת, והודיע חידוש ורבותא גדולה היא לצד יוסף שהיה במצרים ומן הטבע יהיה משתנה מהשואת האחים בין לצד האחוה כי לא יתכן שיהיה שוה ברצון כהשואת כולם לצד מה שעשו לו שמכרוהו ונתאכזרו עליו ואיך לא יהיה קצת שינוי בינו לבין כולם, בין לצד הצדקות כי היה נתון בכור הטומאה והאחים היו בארץ כנען ומסוככים באילן הוא יעקב אביהם, ועל כל פנים ישתנה קצת, ואף על פי כן מודיעך הכתוב כי שוה הוא להם ונכנס במספר הע' וכהשואת כולם יחד ליקרא נפש אחת בין לפרט האהבה והאחוה הנכונה בין לענין הצדקות וטהרת הנפש, שלא נדבק בו מתחלואי הנפש הגם היותו במצרים. ועיין מה שכתבתי בפסוק (ויגש מו ל) אמותה הפעם וגו':
@6 (ו~ח) **וימת יוסף וגו' ובני ישראל וגו'**. צריך לדעת לאיזה ענין חזר פ''ב להודיע מיתת יוסף וכבר השמיענו (סוף ו. הי) וימת יוסף בן וגו', עוד צריך לדעת כונת הודעת הכתוב שמתו האחים וכל הדור. עוד מה קשר יש בין מיתת האחים והדור לאומרו ובני ישראל. והנה המגיד של מהרי''ק הגיד לו טעם סמיכות זה והוא דרך סוד. עוד צריך לדעת טעם אומרו כסדר זה ובני ישראל וגו' שאם בא להודיענו פריית ורביית בני ישראל היה לו לומר כסדר זה ויפרו וישרצו וגו' בני ישראל:
@6 **אכן** ב' כתובים הבאים כאחת להודיע השתלשלות התחלת השעבוד וסיבותיו, והם במספר ד'. הא' מיתת יוסף שאם היה יוסף קיים יספיק שלא ימשלו בהם המצריים הא למדת שכל זמן שיוסף קיים היו ישראל בארץ מצרים שקטים ומעונגים. ב' מיתת האחים שכל זמן שאחד מן האחים קיים היו המצריים מכבדים אותן וכמו שפי' ז''ל (סוטה י''ג.) בפסוק (בראשית נ יד) וישב יוסף וגו' ואחיו וגו' אחר קברו את אביו יעוין שם דבריהם. ג' מיתת כל הדור פי' כל הע' נפש שכולן היו חשובין בעיניהם ובאמצעותם לא היה להם פנים להשתעבד בהם, או לצד שהיו בני דעה ואין מציאות למצריים להתחכם חכמתם שמתחיל בפה רך כי היו בני הדור ההוא חכמים ויכירו החכמה ולא יקבלו עשות להם דבר בשום אופן, ד' ובני ישראל וגו' כי אם לא היתה ההרגשה הגדולה שפרו וישרצו וגו' במאוד וגו' ותמלא הארץ וגו' לא היו נותנים לב לבקש תחבולות אלא ההרגש הגדול הוא הסובב באמצעות העדר המונע שהוא יוסף ואחיו וכל הדור, ובזה נתיישב אומרו **ובני ישראל** ולא אמר ויפרו וגו' כי לא בא להודיע ענין הרבוי אלא להודיע כי הוא זה סובב הגלות:
@6 **ועוד ויקם מלך חדש וגו'**, וזולת אחת מכל דברים הסדורים לא היה השעבוד ולמ''ד (סוטה י''א.) חדש שנתחדשו גזרותיו הסיבות הקודמות הם סבוהו לחדש דעתו משונה מקדם והבן. והנה לפי פשטן של דברים יגיד כי כל עוד שהיה אחד מהדור ההוא קיים היה מונע השעבוד, וקשה א''כ לא היה לו לומר הכתוב אלא וימת כל הדור ההוא שאפי' כל ימי א' מהדור לא היה שעבוד ולא היה צריך לומר לא מיתת יוסף ולא מיתת אחיו דק''ו שלא יהיה השיעבוד בימיהם, ואפי' לדבריהם ז''ל (סדר עולם רבה פ''ג) שאמרו כל זמן שאחד מהשבטים קיים לא היה השעבוד קשה למה הוצרך להזכיר מיתת יוסף ק''ו הוא מהאחים. ואולי כי יכוין הכתוב לומר כי היו הדרגות בדבר כי במיתת יוסף ירדו מגדולתם שהיו מעולים יותר ממצריים ונעשו שוים להם, ובמיתת האחים ירדו למטה ממדרגתם שהיו בעיניהם נבזים אבל לא היו משתעבדים בהם, ובמיתת כל הדור התחילו להשתעבד באמצעות קנאתם אשר ראו הפלגת ריבוים של ישראל שנתמלאת ארץ מצרים בהם.
@6 **ואם** תאמר והלא רז''ל לא אמרו אלא כל זמן שאחד מן השבטים כו'. ולדברינו אפי' מן השבעים. דע כי דבר זה לא הוחלט לרבותינו ז''ל, וז''ל רבותינו ז''ל בסדר עולם (שם) משמת לוי עד שיצאו ישראל מצרים קי''ו שנה אין שעבוד יתר עליו ולא פחות מפ''ו כשנותיה של מרים שנקראת על שם המרור ע''כ, הרי כי אין הכרעת דבר שמשמת לוי שהוא אחרון שבשבטים התחיל השעבוד. ופשט הכתוב אני רואה שלא אמרו הבה נתחכמה לו אלא אחר מיתת כל הדור ההוא והשוהו הכתוב לכל אחיו:
@9 **ויאמר אל עמו הנה וגו'**, אומרו הנה וגו'. יתבאר על דרך אומרם ז''ל (ב''ר פ') בפסוק (בראשית לד) עכרתם אותי שצלולה היתה החבית וכו' כי מסורת היתה ביד וכו' שעתידין ליפול ביד ישראל ע''כ. ולזה אמר מלך מצרים הנה עם בני ישראל הידוע בתוקף ועוז הנה הוא רב ועצום, ואמר **הבה נתחכמה לו פן ירבה** וגו' **ועלה מן הארץ** ויעשה מה שהוא מסורת בידם שהוא יאבד כל נפש לכנעני אחיו, לזה יתחכמו עליו לאוסרו לבל צאת. ולזה נקראת מצרים בית הכלא כי היו המצרים שומרים את ישראל בלתי צאת משם לחשש כלות אחיו הכנעני וכו'.
@9 **עוד** ירצה באומרו **הנה עם** וגו' על זה הדרך כי עם זה משונה מכל העמים כי שאר העמים יתערבו ביניהם ואין לך עם שאין בו תערובות גדול מכמה עמים אשר לא כן עם ישראל, והוא אומרו **הנה עם** כולו בני ישראל ואין זר אתם, ואומרי **רב ועצום** פירוש כי באמצעות היותם עם אחד ומיוחד הגם שיהיו מעטים בערך שאר האומות יחשבו לרבים ועצומים מהם לצד שהם כל אחד נותן נפשו על אחיו, וזה ידוע ליודעי ערך מלחמה.
@9 **עוד** ירצה באומרו **רב ועצום**, רב שמתרבה שלא כדרך העולם, והנה מטבע העולם כאשר יולדו רבים יהיו תשי כח בין בבחינת הנולדים בין בבחינת המוליד, וצא ולמד מהתאומים כידוע לטבעיים, ומעתה אין מיחוש לריבוים כי סופם להתמעט, וכי יהיו רבים אין בהם כח לחוש לרייבויים, לזה אמר ועצום פי' הגם שהם מתרבים ביותר מהרגיל אף על פי כן ועצום ממנו הגם שאין בהם הריבוי, ומן הראוי הם היו ראוים להיות חזקים יותר מהם, ומעתה בהכרח להתחכם עליו, וכפי זה תיבת ממנו חוזרת אל עצום ולא לאומרו רב כי בסמוך הוא אומר פן ירבה.
@9 **עוד** ירצה באומרו **רב ועצום ממנו** פי' שגדולתם וריבוים מהם היה, והכונה בזה כי בא להודיע אותם כי יש להם חוב בישראל, ונתכוון להקדים טענה לבל יאמרו אליו עמו או כל רואה מעשיו נכריים כי באיזה כח יעמוד ויקח עם אחד השוכן בקרבו ויעבוד בו עבודת עבד, לזה אמר **הנה עם בני ישראל** זה עצמו ובשרו משלנו הוא כי אנו החיינו אותו בשני רעב וכל מה שנתרבה ממנו הוא ג''כ כי בע' נפש בא לגור בארץ, ומעתה יחזיק בישראל בחזקה שעמה טענה ויתחכמו לו לעשות לו כטוב בעיניהם.
@9 **עוד** ירצה כי הלא תמצא כי כל המלכים וגדולי העמים יתחכמו לפאר מלכותם בעם מכובד ומה גם בעם ישראל כי שם ומעלה מיוחדת לו, ואין לך אומה ששלטה בישראל שלא היתה מעולה על כל האומות בסוד (איכה א) היו צריה לראש, לזה אמר מלך חדש הנה בני ישראל המכובדים הם הם העיקר במלכות יותר מהמצרים ובהם הם מתכבדים וכי יצאו מהעיר תהיה העיר פחותה ובזויה לזה **הבה נתחכמה לו** וגו' פן יצא מהעיר באמצעות סיבה כי תקראנה מלחמה ויקוץ מהמלחמה וילך לו, ואז אין אנו יכולין למונעו כי ילחם בנו בהצטרפות מלחמה הלוחמת עמנו:
@11 **וישימו עליו וגו'**. כאן הבן שואל מה חכמה נתחכמו בזה אין זו חכמה אלא רעות וחציפות. עוד איך מלאם לבם בתחילת השעבוד לשום עליהם שרי מסים. ועוד איך בני ישראל נטו ערפם לעבודת עבודה נכריה בחומר ובלבנים. והנה רז''ל שאמרו (סוטה י''א.) כי היה הדבר בהדרגה בתחלה בפה רך ולבסוף בפרך, ומן סדר הכתובים משמע כי בתחלה שמו עליהם שרי מסים, ולדבריהם ז''ל צריך לומר כי קדמו דברים לשימת שרי מסים. והנה לפי מה שפירשתי בפסוק רב ועצום ממנו כי סוברים שיכולין להשתעבד בהם בעד הטוב שעשו להם בשני רעב אפשר שבאו עליהם בכח ואל תיכף ומיד, ושעבדום וישימו עליהם שרים ואז היו מועטים בערך המצריים ונטו ערפם, ומה שאמר הכתוב הבה נתחכמה אינו על פרט השעבוד אלא על פרט אחר, וכמו כן אמרו ז''ל (שם) שהיה על שקוע הבנים בים כאמור בדבריהם.
@11 **עוד** נראה בדקדוק עוד אומרו **למען ענותו** וגו' שלא היה צריך והדבר מובן שהוא למען ענותו מתכוונים. עוד אומרו **בסבלותם** מה בא למעט. אכן נראה שנתחכמו עליו להשתעבד בדרך זה, כי פרעה מן הסתם יהיו לו בונים ערים לשבת והרבה עובדים עבודות הצריכין למלכות מהמצריים עצמם ומהזולת, והאנשים ההמה יקראו מס כמו שאמר הכתוב (מ''א ה') ויעל המלך שלמה מס מכל ישראל, ויעץ עצה לשום על ישראל שיהיו הם שרי מסים יובן שיהיו הם הממונים על כל עושי מלאכת המלך, ודבר זה אינו פחיתות ולא דלות לישראל ואינם יכולין למאן וכוונתם בזה הוא לערמה למען ענותו לעם ישראל בסבלותן של המסים שהם עובדי עבדות כשלא יוכלו לעבוד עבודתם אשר שמו עליהם בתוספת מרובה ממה שיוכלו שאת יצטרכו השרים להצטרף עמהם לעבוד עבודתם להשלים חקם, שלא היו מכירים בחוק העבודה אלא לשרים שהם ישראל שהם הם הממונים, וזו היא חכמתם שבאמצעות ערמה זו הכניסום בסבלות, והוא אומרם ז''ל בתחילה בפה רך היו לשרים ואח''כ לעבדים ויבן ערי וגומר:
@12 **וכאשר יענו אותו כן ירבה וגו** '. מה יערב נעימות הכתוב על פי מה שכתב בזוהר (ח''ב צ''ה:) בפסוק (קהלת ח') עת אשר שלט האדם באדם לרע לו, כי באמצעות העינוי והצרות תתברר בחינת הטוב מהרע ותסמך אל חלק הטוב ותתברר בחינת הרע מחלק הטוב ותסמך אל בחינת הרע, וב' פרטים אלו רמוזים באומרו לרע לו והוא עצמו שאמר הכתוב וכאשר יענו אותו כן כשיעור העינוי היו מוציאים ומבררים חלק הטוב ומתרבה חלק הטוב וכן יפרוץ. או ירמוז **וכן יפרוץ** שהיה נפרץ ממנו חלק הרע שהיה דבוק בו, והוא הצירוף אשר צרף ה' אותם בכור הברזל במצרים. וכפי פשט הכתוב ירצה כי כשהיו המצרים מרבים לענות היה ה' מרבה את ישראל כדי שיהיו נעזרים על העבודה והיה נותן בהם כח, והוא אומרו **כן ירבה** לשיעור אשר יספיקו העובדים בעבודה וגם ה' נותן בהם כח לשיעור אשר יתמעט מכחם מהעינוי. וכשראו המצרים כן היו מעבידים אותם בפרך כתרגומו בקשיו:
@14 **וימררו את וגו'**. אומרו **בעבודה קשה** פירוש בעבודה שהיא קשה מצד עצמה אפי' במועט, ממנה והוא עבודת חומר ולבנים ועבודת שדה. ואומרו **את**.
@14 **כל עבודתם** וגו' כי לא תאמר שהרפו ידם מהם משיעור הבנין שקצבו להם מקודם אלא שקצבת עבודה ראשונה במקומה עומדת והוסיפו להם כמו שתאמר שאחר ששמו עליהם כך וכך שיבנו בכל יום אחר שיהיה החומר והלבנים מוכנים לפניהם הוסיפו עליהם לעשות הכנת החומר והלבנים וכל עבודת הכנת הבנין ולא הקילו מצד זה שיעור עבודה ראשונה אשר עבדו בהם בפרך אלא אתה עמה, וזה מהתחכמות פן ירבה, ואף על פי כן לא הועילו להמעיטם כי נתרבו בני ישראל והספיקו לדבר זה, ואשר על כן ויאמר מלך מצרים וגו' להמית הזכרים:
@15 **ויאמר מלך וגו'**. הגם שכל המעשה האמור בענין אמר לשון רבים דכתיב וישימו וכאשר יענו וגו' ויעבידו וימררו כי לא המלך לבדו עושה אלא הוא ועמו, דבר זה עשאו המלך לבדו כדי שיהיה הדבר בסוד שלא ירגישו העבריות להסתיר הריונם ושלא ירחיקו המילדות מילד אותם כאשר אבאר בסמוך:
@15 **למילדות העבריות וגו'**. צריך לדעת מה אמר להם באמירה זו. ואולי כי האמירה היא שקרא ואמר **העבריות אשר שם האחת** וגו' כי להיות שבאו לפניו הרבה ולא היה מכיר אלו המילדות לזה קרא בשמותם ליחד להם הדיבור לצד שהיו גדולות של כל המילדות ורצה להטיל הדבר עליהן כי כן דרך השררה. עוד ירצה שהוא עשה אותן גדולות ושרות בקריאה זו על כל המילדות ואשר על כן פרט את שמותן, ולזה חזר לומר פעם אחרת **ויאמר בילדכן** וגו' פי' שהציווי לא לשתיהן לבד אלא לכל המילדות אלא שאלו יהיו עליהם שרות. עוד ירמוז הכתוב לשון גדולה ורוממות על דרך (דברים כ''ו) את ה' האמרת וה' האמירך והכונה בזה להגיד שבאמצעות ענין זה גרם להם פרעה מעלה והתרוממות לב' המילדות ועלו במעלה כאמור בסמוך (פסיק כ') וייטב אלהים וגו' ויעש להם בתים בתי כהונה בתי לויה בתי מלכות בתי נביאות (סוטה י''א:):
@16 **ויאמר וגו' וראיתן על וגו'**. צריך לדעת לאיזה ענין ראיה זו ולא היה לו לומר אלא אם בן וגו', ומה גם לדברי רבותינו ז''ל (סוטה יא:) שאמרו סימן מסר להם בן פניו למטה בת פניה למעלה לא ידעתי למה הוצרך לסימנים אלו. עוד צריך לדעת טעמו למה לא גזר על הכל, ואין להאמין עליו כי במדת רחמים נהג לשום להם שארית בארץ כי שורשו שורש אכזרי הוא. עוד קשה אומרו **והמיתן אותו** בתוס' וא''ו מבלי מעשה קודם לדבר. עוד למה הוצרך לומר **ואם בת היא וחיה** כיון שפרעה לא גזר אלא על הזכרים פשיטא שלא יבקשו המילדות לעקור את הכל.
@16 **אכן** רשע זה נתחכם כדי שתעלה בידו העצה, כי מי זאת האשה אשר תזמין עצמה למילדת להרוג בניה, לזה נתחכם ואמר להן שיתנהגו בסדר זה ויעשו בהעלם דבר ולא ירגישו היולדות על זה הדרך, כי קודם שיוודע הנולד מה הוא אם בן אם בת יראו המילדות על האבנים אם בן הוא ימיתוהו ויאמרו נולד מת ולא יניחו עד שיצא ועוי' (צועק סוטה י''ב) אלא שיראו על האבנים קודם שיצא לעולם אם בן הוא, ומנין ידעו לזה אמרו ז''ל סימן מסר להם, ולזה אמר והמיתן בתוס' וא''ו כי מצוה ראשונה צוה אותן להבחין לדעת אם בן הוא קודם שיצא לעולם ויתן קולו, והב' והמיתן אותו בצאתו מבטן אמו. ואומרו **ואם בת היא** וגו' נתכוון גם כן בזה כדי שבאמצעות ענין זה לא ירגישו בדבר הנשים היולדות כשיראו שלפעמים ולדותיהן מתקיימין לא יחשדו במילדות והם לא יבחינו כי הורגות הזכרים ולא הנקבות. ואולי שצוה עליהם לבל יודיעו הזכר אלא יאמרו שהנולד נולד מת שבאמצעות כן יסתר החשד, ובזה נתיישבו כל הדקדוקים.
@16 **והנה** עצה חכמה יעץ פרעה בדבר זה לבל יוכלו עלות מהארץ, והוא כי באמצעות שיהרגו כל זכר ויתרבו הנשים והן האשה טב למיתב טן דו ויתחברו נשי ישראל עם המצריים ויתחתנו בהם ומעתה אין מציאות לעלות מן הארץ כשיהיו לעם אחד. גם יפגימו הנפשות הקדושות בערבוב הנפשות הטמאות ויהיו שם עד עולם ב''מ. ותמצא שאמרו רז''ל (ויק''ר פ. ל''ב) שלא נגאלו ישראל עד שהיו בהם ד' דברים וא' מהם ששמרו עצמם מן העריות, ועל זה מפורש בקבלה (שה''ש ד') גן נעול וגו', ואם היו מתחתנים עם המצריים לא היתה בר מינן תקומה לשונאיהם:
@17 **ותיראן המילדות וגו'**. צריך לדעת למה כפל לומר **ולא עשו ותחיין**. ורז''ל (סוטה י''א) אמרו שהיו מספקות מים ומזון. וצריך לדעת למה לא היו עושים להם כן מקודם. ואולי שיודיע הכתוב שלא פסקו מההטבה, והוא סיבת היראה שיראו את האלהים אפי' על מניעת ההטבה שהיו רגילין להטיב בסיפוק מזון ולא מלבד שלא עשו וגו' אלא **ותחיין**.
@17 **או** לעולם כי מקודם לא נתנו דעתם על מצוה זו לספק מים ומזון, ואחר שצוה להם פרעה חששו שיהיו נחשדים אם ימות א' מהנולדים שהם הרגוהו, לזה להוציא עצמן מהחשד השתדלו להחיות אפי' מי שימות מיתת עצמו מחסרון הסיפוק. ואולי כי זה רמז בתיבת **את האלהים** לרבות יציאת ידי חובת חשד בני אדם להיות נקיים מה' ומישראל. וטעם אומרו **כאשד דבר** כ''ף הדימוי לומר לא הוא ולא דומה לו. או ירצה לומר להיות כי מן הדרך הוא כשיגזור מלך דבר על כל פנים בתחלת הגזרה דבר מלך חזק ואימת מלך רועשת לבל עבור עליה ובאורך הימים אחר הגזירה היא רופפת, ולזה הודיע הכתוב כי הצדקניות הללו בטלו גזירת מלך סמוך לגזירה, והוא אומרו **ולא עשו** ואימתי **כאשר דבר** כמו שתאמר כי בעת שיצאו משם והיו מילדות לעבריות לא עשו וגו' ואדרבה ספקו מזון לאין נכון ובטלו דבריו סמוך לגזירה, ושיעור **כאשר דיבר** כשיעור (בראשית כז ל) כאשר כלה יצחק לברך:
@18 **מדוע וגו' ותחיין וגו'**. צריך לדעת מה הוא המעשה שעשו שעליו הוא אומר **מדוע עשיתן**, ואם שלא המיתו את הילדים זה יקרא שלילת המעשה והיה צריך לומר מדוע לא עשיתן. עוד צריך לדעת אומרו **ותחיין**, ואם על סיפוק המזון לילדים הוא אומר כמו שפירשנו באומרו ותיראן המילדות וגו' ותחיין וגו' אם לזה נתכוון מה מענה בלשון המילדות על זה והרי הן מורדות במלך. ואולי כי לא ידע פרעה בפירוש שהיו מספקות מזון לילדים כי מן הסתם לא יעשו כן בפני המצריים ולבני ישראל אין לחשוד בהם דלטורין כאומרם ז''ל (ויק''ר פל''ב) בפסוק ושאלה אשה וגו' כי י''ב חדשים היה ביניהם דבר זה ולא גילה אדם מעולם, אלא שהמצריים הגידו לו שהיו המילדות מספקות מים ומזון לבית הנשים חיות, ודבר זה יכולין הגוים השכנים להכיר בדבר כשתכנים המילדת עמה דברי סיפוק וידעו גם כן כי הנשים החיות היו בניהם זכרים, לזה אמר פרעה **מדוע עשיתן את הדבר הזה** פי' סיפוק מים ומזון שהוא מעשה הנגלה, והן אמת אם לא היו מחיים הילדים הייתי תולה כי לבנות אתם מספקים אלא כיון שהסיפוק הוא למקום הילדים והילדים הנם בחיים זה לך האות כי להם אתם מספקים, והוא אומרו **ותחיין את הילדים**, ואין זה אלא מעיון שכלי כנזכר, כי הידוע לו בבירור אינו אלא מעשה הסיפוק לבית היולדות:
@19 **כי לא כנשים וגו'**. צריך לדעת למה האריך כל כך לשון, ולא הספיק לומר לא כמצריות העבריות או העבריות לא כמצריות. עוד צריך לדעת מה מענה בפיהם על סיפוק המזון, ורואני כי קבל פרעה תשובתם. עוד קשה אומרו **וילדו** שהיה צריך לומר יולדות.
@19 **אכן** כוונת הכתוב הוא שהשיבוהו שלא יקח שיעור לעבריות מהמיוחדות שבמצריות כי כולן חכמות מכל המצריות, והוא אומרו **כי חיות הנה** ומילדות זו לזו או אינם צריכין מילדת. ואולי שרמזו כי הנשים של בני ישראל היו בהם ב' לימודיות בההשכלה הא' היותם מעיקרם עבריות, והב' שהן עתה מצריות ובאמצעות זה נתחכמו ב' מיני השכלה, וזה הוא שיעור הכתוב כי לא כנשים הרגילות בנמצא הם אלו שהם מצריות עבריות, ובזה לא תהיה הוכחת הסתירה לא מעבריות ולא ממצריות כי אלו יש בהם ב' הדרגות והבן. ואומרו **בטרם** וגו' נתכוונו להשיב אם יאמר ולמה לא יהיו הם מילדות אותם בעל כרחן לצד שהם הממונות מהמלך ואמרו בטרם וגו' פי' כי אנו מתחכמין לבוא אצלם קודם שיגיע זמן הלידה כפי חשבונם ליליד אותם ואף על פי כן אנו מוצאים אותם שכבר ילדו כי היולדות היו מתחכמות להרחיק להם זמן לידתם כי הרגישו כדבר, וכל זה נכלל בתיבת חיות. ומעתה כפי הנחה זו פרחה לה מעצמה החשדה הגם שיביאו בידם מים ומזון היה לחושבם שעדיין לא ילדו והם באים ליליד אותם וכל מה שיעשו מהוראת חיבה להם אדרבה כשורה וכהוגן עושין כדי שיתקרבו הלבבות של היולדות ולא יהיו נחשדים בעיניהם כרצחניות וימצאו מקום לקיים גזירת המלך להמית הבנים, ואחר שהיו מביאין לחושבן שעדיין לא ילדו כנזכר והיו מוצאים כי כבר ילדו אינו מהמוסר להשיב המובא, ובזה ספה תמה תלונת וחשד פרעה הגם שצדקו דברי הולכי רכיל שאמרו שהמילדות ספקו מזון:
@20 **וייטב וגו' וירב וגו'**. צריך לדעת מה הוא ההטבה, ואולי שהוא הרשום בסמוך ויעש להם בתים. וקשה אם כן לא היה מפסיק כאומרו וירב העם. ונראה שמורינו הכתוב דבר שבאמצעותו רבו בני ישראל, לפי מה שקדם לנו שהיו מספקות להן מים ומזון לזה אמר **וייטב אלהים למילדות** פי' נתן להם רב טוב ובאמצעותו היה להן יכולת לספק מזון ובזה **וירב העם** וזולת זה לא יהיה להם לספק לרבים בהפלגה, ואחר כך הזכיר ה' שכרם הטוב שעשה להם בתים.
@20 **עוד** ירמוז כי בראות ה' יראתם מהאלהים הזמין לידם עשות מצות לאין קץ להרבות שכרם, והוא אומרו **וייטב** וגו' ומה הוא הטובה **וירב העם** שבזה יגדל זכותם כי כולם יחשבו להם כשלא הרגום, ואולי כי לטעם זה זכו משה ואהרן בישראל כי בשלם זוכים לצד כי יוכבד ומרים נתנו נפשם עלינו ועברו פי מלך ועוד להם שזנו ופרנסו משלהם לזה יחשבו עליו הוא אבינו הוא מלכנו הוא מושיענו. וכלך גם כן לדרך זה כי לצד שאנו ענפי נשמתו של משה דכתיב (ישעי' ס''ג) משה עמו לזה סבלה יוכבד עולינו להגן בעדינו ולספק מים ומזון כמשפט היולדים לבניהם, ולדברי המפרשים (רש''י) שההטבה היא עשיית הבתים יש לומר כי טעם שהפסיק באומרו **וירב העם** שזולת זה אין מקום לבתי כהונה ובתי מלכות כי אם אין עם אין מלך וכהן, לזה הקדים ה' העם ואחר כך עשה להם בתים וגו':
@22 **ויצו וגו' לכל עמו וגו'**. לפי מה שכתבנו כי מתחלה דבר למילדות שיהיה הדבר בסוד ולא ידעו בנות ישראל, כשלא עלתה בידו עשה הדבר בפרסום וצוה לכל עמו על הדבר כי חשב כי אין נמלט מהם לצד היותם רבים ונכרים שלא ירחמו עליהם, עוד אולי לצד שראה באצטגנינות כי מושיען של ישראל נולד ועתיד ללקות במים (סנהדר. ן קא.) לזה גזר גזירה חזקה ומינה כל איש מצרי על הדבר ובזה אין נמלט מידם, ואומרו ל.
@22 **אמר** פי' לא שהמצריים הם עצמם ישליכוהו אלא שיאמרו לבני ישראל שכל אחד ישליך בניו, והטעם למה שאמרנו שהגזירה היתה לצד מה שראו איצטגניניו וכו' מן הסתם יראו הדרך שלקה בו שהוא ע''י ישראל, לזה גזר שבני ישראל הם ישליכו אותו היאורה, וכמו שכן היה שיוכבד היא השליכה את משה ביאור.
@22 **או** ירצה **לאמר** שהם יצוו לכל שכן על שכונתו על הדבר ולא יצטרכו כל העם. ויש מרבותינו שאמרו (סוטה י''ב.) שגם על המצריים גזר, וזה דרך דרש שביום אחד אשר אמרו לפרעה כי בו ביום וגו' אותו יום גזר על כל עמו. אבל פשט הכתוב אין הדברים אמורים אלא בישראל כי גזירה זו בתמידות היתה והראיה כי יוכבד נתנה משה ביאור אחר ג' ירחים והאצטגנינים ראו יום הלידה, ואלו לא היתה הגזרה אלא יום לידת משה והוכר היום ההוא מה מקום לגזור עוד, אלא ודאי שגזירה זו על כל הבן הילוד היתה בתמידות ובהכרח אומרו **לכל עמו** הוא לצוום על בני ישראל והדרשה תדרש:
@24 **כי טוב הוא ותצפנהו וגו'**. צריך לדעת מה היא הטוביות שראתה בו. ורז''ל (סוטה יב.) אמרו נולד מהול ותמלא הבית אורה. וזה דרך דרש. עוד צריך לדעת קשר ותצפנהו עם ותרא אותו כי טוב וגו' וכי אם לא היה טוב לא תחמול על פרי בטנה לצפון אותו מאנשי דמים.
@24 **אכן** כוונת הכתוב הוא כי ממה שאמר הכתוב ותצפנהו וגו' ולא יכלה עוד וגו' אמרו ז''ל (שם) כי מנו לה המצריים מעת הריונה והיא ילדתו בן ששה חדשים ויום אחד, והנה היולדת לששה פשיטא שאינו מתקיים והיולדת לז' מתקיים, והנה אין האשה מדקדקת במספר יום אחד וכשילדתו בחזקת נפל ילדתו והודיע הכתוב כי ראתהו טוכ פי' בריא וחזק שאין בו סימנים של נפל ולזה טרחה בשבילו וסכנה עצמה מהמצריים שהיו בודקים הבתים בקטנים כמאמרם ז''ל (שם) והוא אומרו **ותרא** וגו' **ותצפנהו**. ודרשת רז''ל תדרש ממה שלקח לשון זה **כי טוב** ולא אמר לשון אחר. וכוונת רז''ל שדרשו טוב הוא מהול, כבר גילו דעתם במקום אחר (סנהדרין לח:) כי אדם הראשון קודם שחטא היה טוב מוחלט ובמעשה הרע שעשה משך הערלה מבחינת הרע, ולזה כשאמר הכתוב כי טוב הרי זה מראה באצבע כי מושלל מהכר רע שהיא הערלה:
@27 **ונערותיה הולכות וגו'**. צריך לדעת כונת סיפור זה **ונערותיה הולכות**, ואולי שיכוין לומר מעשה בתיה, להיות כי מעשה מצוה גדולה עשתה דקדק הכתוב להודיע דקדוק אופן המעשה. והנה דבר ידוע הוא כי בת מלך לא תלך ליאור בלא נערות כמשפט בנות מלכים, גם ממוסר הגדולים ובפרט המלכים להיות להם אחד מיוחד מכובד הרבה להתגלות לפניו ולשמשו ולרחוץ בבית המרחץ או ביאור וכדומה, וכאן הודיע הכתוב באומרו ונערותיה הולכות שהיה בזמן שהיתה רוחצת שהוצרכו נערותיה ממוסר המלכות שלא לעמוד לפניה ולא נשארה עמה אלא אחת המיוחדת ותשלח אותה, והוא אומרו **ותשלח את אמתה** פי' המיוחדת לה לרחוץ וגו'. ואומרו **ותקחה** שקולה, או ששלחה אותה לבל תיעצה הפך רצונה כי רצונה של בת פרעה היתה להציל הילד ההוא ותקחה בת פרעה לתיבה. או **ותשלח** וגו' **ותקחה אמתה**, ולב' הדברים שבח בת פרעה יגיד כי נפשה נפש טהורה מי יתן טהור מטמא וגו' (איוב יד) לדרך הא' יכוין לומר שהגם שלא היתה עמה אלא אמה אחת וכל נערותיה היו הולכות וגו' אף על פי כן חששה למניעה ממנה ושלחתה ונשארת בת מלך לבדה ולקחה התיבה בידה ולדרך ב' גם כן שבח יגיד שהגם שלא היתה עמה אלא אמה אחת ואין מדרך המוסר שתשאר בת מלך יחידה ואין צריך לומר על שפת היאור אף על פי כן שלחה אותה למרחוק, ולזה הקדים להודיע **ונערותיה** וגו' לדעת כוונת הודעת **ותשלח את אמתה** על אופן שכתבנו, ואילו לא אמר ונערותיה לא היתה הכונה ידועה שנתכוין למה שפירשנו והבן:
@28 **ותראהו את הילד וגו'**. צריך לדעת אומרו **ותראהו** וגו' שהיה לו לומר ותרא וגו'. ונראה שנתכוין לומר שידעה שהתיבה היא מהילדים המושלכים היאורה ונתכוונה להצילו וכמו שפירשנו בפסוק ותשלח את אמתה, והוא אומרו **ותפתח ותראהו** להילד שנתכונה להציל, ואם היה אומר הכתוב ותראה ילד יהיה המשמעות כי ראתה מה שלא חשבה כן והבן. ורז''ל דרשו (סוטה יב:) ותראהו ראתה שכינה עמו, והוא דרך דרש. וצריך לומר שלא הכירה השכינה היא, כי מנין ידעה השכינה מבית אביה ואבי אביה, אלא שראתה עמו אור גדול, וה' עשה כן כדי שתגדל מעלת הילד בעיניה. גם לטעם שדרשו ז''ל (זהר ח''ב י''ב:) בכתוב והנה נער בוכה שרמז על ישראל שהיו בוכים בגלות, לזה ויגל ה' את עיניה להראותה האור הסומך למשה.
@28 **עוד** אפשר שהרגשתה בשכינה היתה לצד שכשנגעה בו פרחה ממנה צרעת (ש''ר פ''א) אמרה אין זה אלא בן אלהי. ואולי שרמז פריחת הצרעת באומרו **ותראהו את הילד** פי' ותראהו להאמור בסמוך בכח דכתיב לרחוץ וזכרון בשרה בכח וכשפתחה התיבה ותראהו לבשרה את הילד פי' כשנגעה בילד **והנה נער** פי' חזר להיות כבשר נער קטן על דרך מה שאמר הכתוב בנעמן (מ''ב ה') וישב בשרו כבשר נער קטן:
@28 **ותחמול עליו**. לפי מה שפירשנו כי נתכונה מתחילה ובראשונה להציל הילד טעם החמלה חדשה לא להצילו מהיאור אלא יגיד הכתוב שבקשה להניקו, והעד מה שאמר בסמוך ותאמר אחותו וגו' האלך וקראתי וגו' ואמרו ז''ל (סוטה יב:) שהחזירתו על מניקות גויות וכו':
@28 **ותאמר מילדי העברים וגו'**. קשה מה חידוש אומרת **מילדי העברים זה** פשיטא שכן הוא כי הן הנה המשליכות ילדיהן ביאור בגזירת פרעה, ואם לפי מה שדרשו ז''ל (שם י''כ.) כי באותו יום גזר גם על המצריים. אם כן מנין ידעה והכירה כי אינו מילדי מצריים. והנה לפי מה שאמרו ז''ל כי החזירתו על כמה מניקות גויות ולא רצה לינק זה לך האות כי לא מילדי המצריות, ועל כל פנים מה חידוש אומרת בדבריה. ולעמוד על הדבר נשכיל על דבר אם הצלת הילד היה לצד שנסתפקה היותו מצרי או אפי' יהיה עברי, והנה אם נאמר שחשבה להציל לספק. מצרי תכוין באומרה **מילדי העברים זה** כי נתברר לה הפך מה שחשבה ובזה גלתה דעתה כי לא להציל מילדי העברים נתכונה, ודבר זה השכל יבחרהו כי סתם גויה לא תרחם אלא על בני אומתה, והגם שאנו רואים שאחרי שידעה כי מילדי העברים הוא החזיקה בו ושכרה לו מינקת, אין מזה ראיה כי אחר שידעה מעלתו גם שריפא אותה מצרעתה רחמה עליו, גם ראוי הוא מכח זה להטות לבה לאמונת ישראל כי היא ראתה מה נורא מעשיו:
@28 **ואם** נאמר שמתחילה רחמה על הילד הגם שידעה כי. מבני ישראל הוא תכוין באומרה **מילדי העברים** נתינת טעם שלא ינק מהנכריות לא שהוחלה מהיאור ומסוכן הוא ואינו יכול לינק אלא לצד שהוא מילדי העברים, ולזה תכף אמרה לה אחותו **האלך וקראתי לך** וגו' מהעבריות להבחין דבריה, ואמר הכתוב **ותקח האשה** וגו' **ותניקהו**:
@32 **ותקרא שמו וגו' ותאמר וגו'**. הנה תמצא שינוי בקריאת שם יצחק ויעקב והשבטים כי לכולם יקדים טעם השם ואחר כך השם, ביצחק (בראשית כא ו') כל השומע יצחק וגו' ותקרא שמו יצחק, יעקב (שם כ''ה כ''ו) וידו אוחזת בעקב ויקרא שמו יעקב. בשבטים כי ראה ה' ותקרא שמו ראובן (שם כ''ט ל''ב) כי שמע וגו' ותקרא שמו שמעון (שם לג) וכן על זה הדרך. מה שאין כן בקריאת שמו של משה הקדים הזכרת שמו ואחר כך טעם השם ואולי כי האמהות היו בעלי רוח הקודש והיו משיגות בחינת השם וקריאת השם היתה למה שהיו מכוונים בו מה שאין כן קריאת שם משה מגיד הכתוב כי לא השיגה לידע בחינת השם כי שמו נפלאות יגיד. וצא ולמד מה שכתוב בספר הזוהר (ח''ג דע''ו תיקונים תיקון ס''ט) מה ירמוז שם זה. וה' השם שמות בארץ שם בפיה שם משה ומה שאמרה היא בטעם השם הוא **כי מן המים משיתהו** ולא ידעה טעם זולת זה:
@32 **או** ירצה הכתוב לומר כי זאת האשה העלימה טעם השם שלא יתגלה לכל לצד כי המעשה היה הפך רצון כל עמה להציל אותם שהם גזרו עליהם להשליכם ליאור והיא תבטל עצתם לרע להם לזה לא פרסמה טעם השם אלא קראתו סתם בלא טעם והכתוב מודיע טעמה שקראתו כך הוא לצד שאמרה כי מן המים:
@33 **איש עברי מאחיו**. דקדק לומר **מאחיו**, ירמוז כי הביט בו שהיה מהצדיקים שבישראל כי היו אז בישראל רשעים וצא ולמד מה שאמרו ז''ל (מכילתא י''ב כ''ט) בפסוק וחמשים עלו וגו' (לקמן י''ג י''ח) (שה') [שד'] חלקים ולמ''ד יותר מתו בימי החושך והשאר עלו לצד היותם רשעים, ותמצא שכאשר אמר בסמוך ב' אנשים עברים נצים לא אמר מאחיו לטעם שהיו רשעים כי הם דתן ואבירם (ש''ר):
@35 **ויאמר לרשע וגו'**. פי' לרשע שהיה בהם, ואומרו **רעך** לו יהיה שיהיה רשע כמותך למה יהיה בולע צדיק ממנו. או ירצה כי הכיר שאחד רשע ואחד תם שלא הריעו, לזה אמר **לרשע למה תכה** אדם שלא נתחייב לך ולא בקש רעתך, והוא אומרו **רעך**. והגם שאמר בתחלה ב' אנשים נצים ימצא שאחד יריב חנם לצד רשעו ואידך (טו) **את הדבר הזה**. אמר תיבת **הזה** לומר ששמע דברים הבאים בסמוך שהם דברי הרשע שאמר הלהרגני וגו' לא שידע בבירור כי הוא ההורג למצרי:
@35 **ויבקש להרוג וגו'**. פירוש ביקש להוכיח הדבר אם כן עשה כדי להרוג אותו, ולזה ברח משה מפני פרעה שמא יתברר הדבר ויהרגנו. או ירצה באומרו **מפני פרעה** כי הכיר בפניו כי זעומים הם והרגיש מזה וברח הגם שלא ידע כי הגיעו הדברים לפרעה:
@42 **למה זה וגו'**. כאלו אמר למה עזבתן את זה האיש אשר גמלכם טובות. או ירצה שמקפיד על זמן שעזבוהו מאז עד שיחזרו לקרא לו, וטעמו כי אינו מהמוסר שיעשה עמהם איש נכרי חסד ויבאו ויניחוהו יעמוד בחוץ. או ירצה שהגם שיקפיד יתרו על התקרבותם עם אנשים אמר כי ישתנה זה מכלם, והוא אומרו **למה זה** וגו' כי מעשיו מוכיחות כי איש חסד הוא, ומה גם לדבריהם (ש''ד א') שאמרו לו שעלו המים לקראתו הרי זה משונה לשבח שבחים:
@43 **את צפרה בתו למשה**. טעם שכפל הזכרת שמו ולא הספיק לומר ויתן לו את וגו', יכוין הכתוב להודיע כי. היא בת זוגו, ותיבת **למשה** הוא דברי הכתוב שאומר כי צפורה למשה היא למנה בת זוגו:
@44 **גר הייתי**. לשון עבר. כי בזמן שנכתבה התורה ידבר הכתוב. או ירצה על זה הדרך **גר הייתי** על דרך אומרו (תהלים קי''ט) גר אנכי בארץ, כי הצדיקים אינם בעולם הזה אלא כגרים בלא שום ישוב, והוא אומרו **גר הייתי** מעודי ונוסף לי **בארץ נכריה** לצד שהיה חוץ מאחיו ובית אביו:
@45 **מן העבודה**. פי' לא שצעקו לאל שיושיעם אלא צעקו מן הצער כאדם הצועק מכאבו. ומודיע הכתוב כי אותה צעקה עלתה לפני ה', והוא אומרו **שועתם** וגו' **מן העבודה** פי' מצער העבודה **וישמע ה' את נאקתם** פירוש הרמת קול כאבם.
@45 **עוד** ירצה על דרך אומרו (תהלים קי''ח) מן המצר קראתי יה ענני במרחב יה כי אחת מהתפלות המתקבלות היא תפלה שמתוך צרה, וכן הוא אומר (יונה ב') קראתי. מצרה, והוא אומרו **ותעל שועתם** וגו' **מן העבודה** פי' לצד שהיתה מצרת העבודה, וכפי זה שועה זו היא תפלה וצעקת כאב הצרה הנה היא רמוזה באומרו מן העבודה ויזעקו, ובזה ידויק על נכון טעם ששינה הכתוב לשונו שהתחיל לומר ויזעקו ותעל שועתם וגו', שהיה לו לומר ותעל זעקתם וגו', אלא נתכוין לומר שהם זעקו מהצרה וגם שועו לה' כאומרו ותעל שועתם. וכפי זה שיעור הכתוב הוא על זה הדרך ותעל שועתם ששועו לאלהים מן העבודה. עוד אולי אומרו **מן העבודה** ירצה שלא הגיעה השועה לפני ה' על ידי אמצעי אלא ביושר עלתה מן העבודה אל האלהים שלא על ידי בעל כנפים יגיד דבר (קהלת י' כ'):
@47 **וירא וגו' וידע וגו'**. פי' אחר שצעקו ועלתה צעקתם זכר ה' ברית האבות וזה היה סיבה לפנות להם ולראות אותם, כי ראית ה' במצטער תועיל להסרת הצער כי הוא רחמן מלא רחמים ורחמיו על כל מעשיו, והוא אומרו וידע וגו' בלע''ז אפיאד''ו. ותמצא כי בעת כעסו יסתיר פניו, והוא אומרו (דברים ל''א) ואנכי הסתר אסתיר וגו'. עוד ירצה באומרו **וידע** דברים נסתרים שהרעו:
@48 **ומשה וגו' וינהג וגו'**. פירוש כי ה' סבבו לעשות כן. או שהוא נהג כמנהגו והצאן הלכו שמה אל הר וגו' כי שם ידבר אליו האלהים:
@51 **ויאמר הנני**. לא כשמואל שלא הכיר הקורא (ש''א ג'), כי משה נביא היה בטרם יצא מבטן אמו והכיר הקורא. ואולי כי זה רמז באומרו **המראה הגדול** רמז אל גדול המיוחד:
@52 **אל תקרב וגו' של וגו'**. הנה ב' דברים יצו אותו ה', אחד שלא יקרב, ואחד שישלוף נעל רגלו שלא יעמוד בו אפי' במקום שהוא עומד בו כאומרו **המקום אשר אתה עומד עליו** כבר **אדמת קודש הוא**, וצריך לדעת למה לא הקדים לומר לו הסרת מכשול שכבר הוא נתון בו שהוא עומד במנעלו על אדמת קודש ואחר כך יצו עליו לבל יקרב הלום. דע כי בכל התורה כולה גילה ה' דעתו ורצונו כי עיקר הקפדתו ומוסרו הוא על מצות לא תעשה כי זה יחבול בנפש, והוא טעם אומרו (קהלת י''ב) והרוח תשוב וגו' אשר נתנה ואמרו ז''ל (שבת קנ''ב:) תנה לו כמו שנתנה לך, אבל מצות עשה הם השגת הטוב כשיהיו ובהעדרם אין עונש זולת על פרטים ידועים כגון פסח ומילה. והנה כאן צוה לו ה' מצות לא תעשה ומצות עשה, לא תעשה היא **אל תקרב הלום** ואמרו ז''ל (עירובין צ''ו. שבועות ל''ו:) כל מקום שנאמר פן ואל אינו אלא לא תעשה, ומצות עשה היא **של נעלך**, ואם משה יקרב הלום הרי עבר על לא תעשה, ואם לא יסיר נעלו הגם שאינו דרך כבוד למקום לא עבר אלא אעשה ממה שאמר לו ה' בלשון עשה, ותמיד יקדים ה' השמירה לעשיה דכתיב (דברים ד ו) ושמרתם ועשיתם, לשמור לעשות (שם טו ה) משמרתי מצותי (בראשית כו ה). לזה ג''כ הקדים החמור **אל**. תקרב לא תעשה ואחר כך עשה **של** וגו' שינהוג כבוד במקום המקודש. אלא שיש לנו לדעת דעת עליון למה לא קרא אליו קודם שיעמוד במקום קדוש לכל יקרב בנעלו אשר ברגלו על אדמת קודש. ואולי כי אינו ראוי הדבר להתיחד הדיבור עליו כי אם בצירוף אזהרת **אל תקרב הלום**. עוד אפשר לומר שלא נתקדש המקום שבו עמד עד אחר כך, והטעם שכשרצה ה' לדבר עמו שם במקום עמידתו רצה לקדשו והזהירו קודם. ואולי כי לזה דקדק לומר תיבת הוא כי לא היה צריך לומר אלא המקום וגו' אדמת קודש, אלא נתכוון הכתוב באומרו **הוא** לומר ולא היה קודם:
@54 **ויאמר ה' ראה ראיתי וגו'**. צריך לדעת למה כפל לומר ב' ראיות. ב' למה הוצרך לפרש ולומר אשר במצרים ואם לא יכיר משה עמו של האלהים אינו מסויים אצלו בסימן זה אשר במצרים הלא כמה אומות היו במצרים. ואולי כי לא היתה אומה מעונה ומרודה במצרים כישראל. אלא שאין הדעת מקבלת כי לא ידע משה כי ישראל הם עם ה' ונחלתו. אכן יכוון ה' להודיע כי ראה ב' ראיות, הא' שעדיין לא הגיע הקץ ואף על פי כן **ראיתי את עני עמי** והעוני הוא **אשר במצרים** פי' על דרך אומרם שם במס' שבת (י:) שבשביל ב' סלעים מילת וכו' נתגלגל הדבר וירדו אבותינו למצרים והקשו התום' והלא כבר נגזר הגלות בבין הבתרים ואמרו שהיה יכול להיות במקום אחר שלא היו משתעבדים בו ישראל בכל כך צער ועינוי, והוא אומרו **אשר במצרים** פי' ולבחינה זו של כובד השעבוד אני רואה כי הגם שלא הגיע עדיין קץ הגאולה הגיע קץ פרט בחינת העוני אשר מענים ומשעבדים אותם.
@54 **עוד** ירצה לומר ראה הצער שישנם בו ועוד **ראיתי עוני עמי** שהם חלק ה' עמו והעוני הוא אשר הם במצרים כי אם ישראל מתעכבים עוד הם נאבדים ב''מ על דרך אומרם ז''ל (הגדה) ואלו לא הוציא הקב''ה את אבותינו ממצרים עדיין וגו' כי אם היו מתעכבים שם עוד היו נכנסים בנ' שערי טומאה ולא היתה תקומה לזה גאלם מיד ולא שהו אפי' שיעור שיספיק בצקם להחמיץ הגם שכבר בטלה עבודה מהם והיו שרי צוען המקום הוא גורם עינוי, והוא טעם אומרו (לקמן יג לט) ולא יכלו להתמהמה, והוא שרמז פי חכם ברוך הוא **אשר במצרים**.
@54 **עוד** ירצה באומרו **ראה ראיתי** ב' ראיות אחת שנשלמו בירורי ניצוצי הקדושה ואין להם עוד הנאה בגלות וכאומרם ז''ל (ברכות ט': פסחים קי''ט:) בפסוק וינצלו את מצרים עשאוה כמצודה שאין בה דגן וכמצולה שאין בה דגים, ועוד ראיתי שעכבתם שם תריע להם להטמינם בקליפה בטומאה כמו שכתבתי:
@54 **ואת צעקתם שמעתי**. פי' ועוד בא לפני צעקתם מצרה להם כי הוסיפו להרע עד שצעקו צעקה מכאב לב וכמו שפירשתי בפסוק ותעל שועתם וגו' מן העבודה. וזה הקדמת טעם לשליחותו קודם הזמן שהוא להצילו מצרה מעכשיו שלא ישתעבדו בו באותה שנה שהיו המצרים מוכים מכות גדולות כי מיום שהתחילו המכות במצרים נסתלק השעבוד מישראל כאשר אבאר בסמוך בפסוק וארד להצילו. גם למה שפירשתי באומרו **ראה ראיתי** שנתכוין על צרת מצרים כי הגיע העת להסתלק, אף על פי כן צריך התעוררות מהניצולים לזה אומר **ואת צעקתם שמעתי**:
@54 **ואומרו מפני נוגשיו** אחר שהזכיר שמיעת הצעקה ולא כן היה לו לומר אלא ואת צעקתם מפני נוגשיו שמעתי. עוד אמר צעקתם לשון רבים ונוגשיו לשון יחיד ולא השוה מדת הלשון, נתכוין לומר כי בני ישראל צעק לבם אל ה' בתפלה, וזה יצדיק מה שפי' בפסוק ותעל שועתם וגו', ואם היה אומר ואת צעקתם מפני נוגשיו שמעתי היה נשמע שהצעקה היתה מהעבודה ולא כן הוא שצעקתם היתה בתפלה לפני ה'. וטעם שאמר **צעקתם** בלשון רבים **ונוגשיו** בלשון יחיד, להיות כי אין רבים הצועקים שוים בצעקם אל ה' לזה כינה אותם בשם רבים, אבל בערך הנוגש היה נוגש לכולם יחד בשוה לזה אמר מפני **נוגשיו** לשון יחיד. וטעם אומרו **מפני נוגשיו** הוא לרמוז כי טעם שקבל צעקת לבם אל ה' הוא לצד שצעקו מצרה וכמו שפירשתי בפסוק מן העבודה. עוד ירצה באומרו **מפני נוגשיו** כאן רמז כי המצריים נתמלאת סאתם ליפרע מהם אשר הרעו הגם שישראל עדיין לא נשלם זמן הגאולה, וזה טעם אחר לשליחות משה קודם זמן הגאולה.
@54 **עוד** ירמוז **מפני נוגשיו** על דרך אומרו (ישעי' ס''ה) טרם יקראו ואני אענה, וכאן הודיע כי קודם נגישתם האדון מרגיש בצעקת בניו ידידיו, ולדרך זה טעם אומרו לשון יחיד לומר אפי' נגישת ראשון שבהם, ואמר הטעם **כי ידעתי את מכאוביו** לומר הגם שעדיין לא צעקו אני יודע ונותן לב על מכאוביו של עמי ונחלתי, גם בזה גילה עוצם אהבתו עם ישראל כרחם אב רחמן וגו'. ולדרכים הראשונים שפירשתי כונת אומרו **כי ידעתי** וגו' להגדיל רוב צרותם כי לא יוכלו שאת כי רבו מכאוביהם בנגלה ובנסתר. עוד ירצה להודיעו **כי ידעתי מכאוביו** פי' לא שקבלם מהצועקים אלא הכיר וידע שיעור המכאובים, ודבר זה יחייב לצד מדותיו להציל, וכמו שפירשתי בפסוק וירא אלהים כי לצד דאיתו בצרת הנבראים יתרבו רחמיו לפנים משורת הדין, וכמו כן הדברים שבאמצעות ידיעת המכאוב של ידידיו יתרבו רחמיו, ומכל קיבוץ הטעמים אמר **וארד להצילו**:
@55 **וארד להצילו ולהעלותו וגו'**. טעם אומרו **וארד**, כי לפי ערך גדולת אל עליון אינו מכבודו לעשות כל הנעשה שיבואו דבריו לאדם נבל כפרעה ולומר אליו דברים משמו, ומה גם כשיגיע למדרגת מיאון עד הגיעו לומר (לקמן ה ב) מי ה' ח''ו, וצא ולמד מה שדרשו ברבות בפתיחת איכה (פתיחתא י''ד) בפסוק (משלי כט) איש חכם נשפט את איש אויל שפט לא אמר אלא נשפט וכו' יעוין שם דבריהם, לזה אמר ה' **וארד** הסכים על מיעוט כבודו כביכול לצד הצלת ישראל כאומרו להצילו. וכוונת הצלה זו היא שיצילו מעכשיו מהעינוי ומהשעבוד, והוא אומרו **מיד מצרים** המשעבדים בהם. ואומרו **ולהעלותו מן הארץ** פי' כשיגיע זמן הגאולה מכאן עד י''ב חודש אעלה אותו מן הארץ וגו' לבל יתעכב שם עוד אפילו בלא עינוי. וטעם שלא העלה אותם תכף ומיד, הוא לצד שעדיין לא הגיע זמן הגאולה אשר קצב ה'. ובזה נחה דעתי בחקירה אחת למה האריך ה' י''ב חודש במכות המצרים, ורז''ל (שמו''ר פ''ט) מהם אמרו שהמכה היתה משמשת ג' שבועות וההתראה שבוע אחת ומהם אמרו להפך, ולמה יאחר ה' הגאולה והיה לו להביא המכות זו אחר זו ויגאלם מיד ותספיק ההתראה ביום אחד או בשעה אחת כדין התראת ישראל שאין צריך בה זמן ומכל שכן אומות העולם שאינן צריכין התראה. גם למה לא הספיק התראה אחת על כל המכות, אלא לצד שעדיין לא הגיע הזמן היה ה' מלביש הזמן ההוא להשביעם מרורות ביני ביני עד שהגיע הזמן. וגאלם מיד בלא שום עיכוב. וא''ת ומה בכך אם היה ה' גואל אותם קודם זמן זה. עוד למה ה' הוציאם בזבולא בתרייתא בזמן שאם היו מתעכבים קצת היו נלכדים עד שהוצרך למהר ולא יכלו להתמהמה והיה לו להוציאם בזמן מורווח.
@55 **הנה** למה שקדם לנו כי עיקר הגלות הוא לברר הניצוצות שנטמעו בנ' שערי טומאה וכמו שציינתי דבר זה כמה פעמים בזה ינוח דעת בב' השאלות כי אם היה מוציאם קודם זה היו מפסידים בירור החלק ההוא, ותדע שעם ה' השיגו בבחינת כללותם הכלול במשה שנתיחס בשם עמו השגת מ''ט שערי בינה, וטעם שלא השיג שער החמישים הוא לצד שאין המושג אלא בהשתדלות המשיג ולצד שישראל לא נכנסו בנ' שערי טומאה לברר אותו לא השיגו בחינת הקודש שכנגדו, והובטחנו כי לעתיד לבוא ישפיע בנו אל עליון תורת חיים שבשער החמשים והשגתו הוא באמצעות הגליות ובפרט גלות האחרון אנו משיגים הדבר. וטעם שנסתכנו ישראל במצרים בבירור שער הנ', לצד שלא היו בני תורה מה שאין כן דורות האחרונים באמצעות תורתם ישיגו ליכנס לשער הנ' ולהוציא בולעו מפיו, ואז ספו תמו בחינת הטומאה. ומעתה כל שהיה ה' מוציא ישראל קודם זמן כל שהוא היו ממעטים הבירור והיו מתמעטים במושג ולזה הוציאם בנקודה האחרונה של מ''ט וקודם שיכנסו לשער הנ', והוא אומרם ז''ל וגאלם מיד. (פסחים פ''י מ''ה לגי' הרמב''ם):
@56 **ועתה הנה צעקת וגו'**. צריך לדעת למה כפל האמור שכבר אמר ואת צעקתם וגו'. עוד דקדוק או **מרו ועתה**. עוד אומרו **הנה**. עוד אומרו **באה אלי** כי לא היה צריך לומר אלי. עוד אומרו **וגם ראיתי** שכבר אמר זה למעלה. ונראה כי מודיעו ה' למשה כי אז בעודו מדבר עמו באה צעקת בני ישראל מחדש, ולזה דקדק לומר **ועתה** וגם אמר **הנה** כמראה לומר הנה הוא לפני. ואמר **באה אלי** לצד שיש הדרגות בתפלות המוגשות לפני הנעתר יש מהם שמביאין אותם משרתי עליון ומגישים אותם לפניו יתברך, ויש מהם שהם מעולים שיש בהם כח שאין צריכין אמצעי להגיעם לפני הבורא אלא הם מעצמם ניגשים לפניו, לזה אמר **באה אלי** פי' בלא אמצעי. ואומרו **וגם ראיתי את הלחץ** לפי דברי התנא (בהגדה) שאמר זה הדחק הוא פרט שלא נרשם בדברי ה' הקודמים לזה הוצרך ה' לאומרו. ונתכוון באומרו **ראיתי** להגדיל מדורת חפץ הפדיום, וכמו שפי' בפסוק (ב כה) וידע אלהים. והכוונה בהודעת כל זה לומר **ועתה לכה** וגו' פי' תיכף ומיד בלא שום עיכוב לצד הדחק אשר הם נדחקים אין להמתין שום זמן:
@57 **לכה ואשלחך וגו'**. טעם שהוצרך לומר **ואשלחך** ללא צודך כי מן הסתם כשיאמר לו לכה ודאי כי הוא המשלחו, גם הקדים ההליכה קודם הזכרת השליחות, לומר כי לא הליכה זו לבד היא השליחות אלא אחר ההליכה תהיה התמדת השליחות, כמו שכן היה שאחר שהלך הוא שהיה שולחו פעם אחר פעם להוציא וגו'. עוד רמז לו כי לא בהליכה זו לחוד יוציא בני ישראל אלא שיחזור שליחות אחר שליחות, והכוונה בזה כי עתידות ישמיעהו שלא יתרצה פרעה לשלחם תכף ומיד. עוד ירצה על דרך אומרם (מכות י:) בדרך שאדם רוצה לילך בה מוליכין אותו, לזה אמר אליו.
@57 **לכה** פי' אם אתה חפץ במצוה זו ללכת אז אני אשלים חפצך ואשלחך, ומזה אתה למד שאם הוא ימאם מהלוך לא ישלחנו:
@57 **ואולי** כי לזה היה משה משיב בטענות כיון שלא ראה דבר מלך שלטון אלא אם ירצה היה מגלה דעתו כי יש לו טענות מונעות והיה ה' משיבו על כל טענה, וטענה כדי שילך מדעתו ורצונו כאשר אבאר בסמוך. עוד ירצה על דרך מה שפירשתי בפרשת וישב בשליחות יעקב ליוסף פי' לכה ואם תחוש למקרה רע ואשלחך ושלוחי מצוה אינן ניזוקין, והיא שעמדה לו בדרך במלון (לקמן ד' כד) שלא המיתו המלאך:
@58 **מי אנכי כי אלך וגו'**. פי' אפי' בשליחות שאינה הפך רצונו כי איני חשוב לדבר לפני מלך ומאמצעות כן לא יאמן בשליחותו ויסתכן שהאדם בעל בחירה ורצון. וצא ולמד ממאמר שמואל (ש''א ט''ז) איך אלך ושמע שאול והרגני, ותמצא שלא יאמן אדם בנבואה לצד בחינת השפלות כאמור בנבואת עמום (קה''ר פ''א) שהיו מזלזלין בו בני דורו וכו'. ועוד **כי אוציא** וגו' כי לזה צריך אדם גדול במעשים שיזכה לזכות גדול כזה, וחש שמא יארע תקלה לישראל באמצעות מניעת זכותו, וזה מהענוה והשפלות:
@59 **ויאמר כי אהיה עמך** וגו'. צריך לדעת מה תשובה משיבו אל עליון כי אהיה עמך הלא ודאי כי ידע משה כי מכחו הוא בא אלא שטען כי לצד מיעוט. ערכו לא יצטדק. עוד קשה אומרו **וזה לך האות** וגו' אין ידוע האות, ואם על אות שלא אוכל הסנה כמו שפירש''י אין הדעת מתישבת בזה וכי משה היה ספק אצלו ח''ו היכול יוכל הציל. ועוד קשה מה שגמר אומר **כי אנכי** וגו' שמשמע כי היה מסתפק אם ה' שולחו וזה אינו אמת כי לא אמר משה דבר שיגיד ספקו בזה.
@59 **אכן** כוונת הכתוב הוא על זה הדרך שבא ה' להשיבו על ראשון ראשון, כנגד מה שאמרת מי אנכי כי אלך אל פרעה דע כי שם אהיה עמך ומעתה גדולתך גדולה מגדולתו וכתרך גדול מכתרו ואימתך מוטלת עליו ממה שמוטלת אימתו עליך וראוי להיות בעיניך הדיוט. גם בזה סתר לו מה שאמר שאינו ראוי להוציא כי הן הראהו ה' שהשגתו גדולה, ואומרו **וזה לך האות** פי' וזה לך האות שאתה ראוי לעשות דבר גדול כזה, ומה הוא האות כי אנכי שלחתיך ואלו לא היית ראוי לא הייתי שולחך, ומה מקום לחששת שאינך ראוי. ואומרו **בהוציאך** וגו' יכוין לומר לו כי תעלה בידו המצוה עד תכליתה ויוציא העם הוא ויעבדון את האלהים וגו', ומעתה תמה טענת וכי אוציא כי הרי מודיעו ה' תכלית הדבר ואין ספק כאשר יגיד ה' מהעתידות.
@59 **עוד** ירצה באומרו **וזה לך** וגו' על זה הדרך דבר זה שאתה מקטין עצמך ואומר מי אנכי זה לך לאות כי באמצעות קנייתך מדה זו אנכי שלחתיך. ואומרו **בהוציאך** וגו' כמו שפירשנוה בסמוך. עוד ירצה על זה הדרך **וזה**.
@59 **לך האות** כי אנכי גמרתי הדבר שיהיה שליחות זה על ידך, **בהוציאך** וגו' **על ההר הזה** סיני בקודש פירוש ההר הנמוך שבהרים ואין אני בוחר בהרים הרמים כתבור וחרמון, הא למדת כי אין אני חפץ אלא בנמוכים כמוך העניו והשפל בעיניך ובהר הנמוך הזה, וכל זה תשובה לטענת וכי אוציא וגו':
@60 **הנה אנכי בא וגו'**. פי' הריני מסכים לבוא בשליחות זה ואין מקום לטענות שטענתי אלא שצריך קודם להאמן לנביא לישראל וצריך אני לבא להם מקודם **ואמרו לי מה שמו** פי' בפשיטות הוא אצלי שיאמרו לי מה שמו, והטעם כי תמצא שבכל נבואת הבטחות האבות יזכיר להם ה' שמו, באברהם אמר בפרשת לך לך (בראשית טו ז) אני ה' אשר הוצאתיך וגו', ובנבואת הבטחת הזרע והארץ עוד אמר לו (שם יז א) אני אל שדי, וכן ביעקב אמר בפרשת ויצא (שם כח יג) ויאמר אני ה', עוד בפרשת וישלח אמר אליו (שם לה יא) אני אל שדי וגו', הא למדת כי בכל ההבטחות יזכיר שמו יתברך המבטיח ומכל שכן כשישלח נביא לזולת שצריך שיאמר שם המשלח. ואולי כי בכל נבואה אשר ינבא ה' לעבדיו יזכור שמו וילמד סתום מהמפורש, ולהיות שכשדיבר ה' אל משה בנבואה זו לא הזכיר לו שמו אלא כן אמר לו אנכי אלהי אביך וגו' לזה אמר אליו **הנה אנכי בא אל בני ישראל ואמרתי להם אלהי אבותיכם** כמאמד ה' אל משה **אנכי אלהי אביך אלהי אברהם** בלא הזכרת השם **ואמרו לי מה שמו** פי' לצד שאין אני מזכיר השם בזכרונו הם ישאלו. ובזה תנוח הדעת בחקירה אחת והוא מה אות והמופת בידיעת השם או בהזכרתו, ממה נפשך אם שם זה ידוע לבני ישראל אין בזה אות לטובה כי כשם שידעוהו ישראל ידענו גם כן משה ואין הוכחה, ואם אין השם ידוע כי זה שמו יתברך ועד עתה ומי יאמין אליו כי זה שם נורא. וראיתי מהמפרשים שפירשו פירושים ודרכים רחוקים, וכל מי שיש לו חיך טועם יטעם דברינו ויהיו לפיו צפיחית כי לא לאות ולמופת הוא חפץ בהזכרת השם, ותמצא שאמר לו ה' שם אהיה הגם שלא מצינו שהוזכר בכל הנבואות לאבות ומן הסתם לא יהיה ידוע לבנים אלא שמות שהוכרו להאבות, אלא ודאי שאין אות ולא מופת בהזכרת השם אלא טעמו כמו שכתבנו. וזה תחילת הכרת משה כי נאמן פשוט הוא בכל שלוחותיו ונבואותיו שדקדק דברי ה' שלא הזכיר השם, ולא סמך על דעתו לומר כי יפרש מדעתו ויזכיר שמו אחר שהושג אצלו אמונת הנבואה ומן הסתם ודאי שידוע היה למשה שם א' משמותיו של המנבא. ועוד אפשר שנתכוון משה להרויח דעת מה היא המדה שמדבר עמו ה' בה:
@61 **ויאמר אהי' וגו'**. פי' הודיעו מדה שבה מדבר עמו, ושם זה יתייחם למדת הרחמים ואשר היא בחינת המוציא מעבדות לחרות, וצא ולמד מה שאמרו בספר התיקונים (תיקון ו') סוד נ' פעמים שנזכרה יציאת מצרים בתורה, וגם הוא טעם שלקו המצריים חמשים מכות כאומרם ז''ל (ש''ר פ''ה). ושם זה כבר רמזו אל עליון בנועם דבריו באמור לו כי אהיה עמך. ואולי כי לזה סמך ואמר **וזה לך האות כי אנכי שלחתיך** פי' בחינת אנכי והוא שהזכיר ה' בהר סיני פתח דבריו אנכי וגו' אשר הוצאתיך וגו' אלא שמשה לא הבין עמקן של דברים כי ה' ידע כי יבא משה לשאול על הדבר ונתן אומר המבשר צבא רב בחינה המדברת וסודה. ואולי כי משה השכיל והבין אלא ששואל אם יזכיר שם זה לישראל, ואומרו **אשר אהיה** הוא טעם השם שנקרא כן לצד שיהיה עם ישראל בצרתם, כמו שאמרו ז''ל (חגיגה י''ב.) טעם שם שדי שאמר לעולמו די, טעם צבאות שהוא אות בצבאו (שם ט''ז.), טעם שם הויה לצד שהיה והווה ויהיה, (זהר ח''ג רצ''ז.), כמו כן אהיה לצד שיהיה, והוא אומרו **אשר אהיה** וכאן הודיעו למשה סוד השם הגדול. ורז''ל (ברכות ט) דרשו אהיה עמם בצרה זו אשר אהיה עמם בצרה אחרת. גם יש בזה סוד ג' כתרים והמשכיל יבין:
@61 **ויאמר כה תאמר וגו'**. פי' הגם שגילה אל משה עבדו סוד השם כמו שאמר אשר אהיה חזר לומר שאינו באמור אלא הזכרת השם, והוא גם כן אומרו **אהיה שלחני אליכם** אבל מה שהוספתי לגלות לך אשר אהיה הוא בבל תאמר. ורז''ל אמרו (שם) שהחזיר משה לקונו בטענת דיה לצרה בשעתה והצצתי וראיתי כי דבר חכמה וצדק דברו מכח הכתוב עצמו, כי אם סוף דיבור כתחלת דיבור ולא היתה חזרה מדיבור ראשון אלא שגומר דבריו לנביאו נאמן בית לא היה לו לומר ויאמר באמצע דיבור א', לזה אמרו כי השם ברוך הוא באומרו אהיה אשר אהיה גמר אומר הענין ולצד סיבה חזר לומר אמירה אחרת. והמשכיל יבין ההפרש שבין דיבור ראשון לדיבור ב' והמדבר אליו וידע המניעה והמונע. ואם תאמר איך מתחלה לא חש ה' על הדבר עד שהוצרך משה לומר לפניו וכו'. הנה במה שנדקדק דבריו יתברך תדע כי יודע תעלומות חכמה השכיל על דבר, והוא שהיה צריך לומר בתחלת דבריו **כה תאמר לבני ישראל** לצד שתשובה זו בא על טענת משה ואמרו לי מה שמו היה צריך להשיבו **כה תאמר** אלא לצד שידע כי לא יעמוד הדבר הזה כן במה שיטעון משה כמו שטען אחר כך דיה לצרה לזה כדי שלא יצאו דבריו לבטלה לא אמר כה תאמר ואמר דבריו שקולים שיש במשמעותם שהכל הוא תשובת מה אומר אליהם וכשבא משה וטען אמר כי לא יאמר אלא אהיה ומה שאמר אשר אהיה הוא הודעה למשה גם הודעה לדורות כדי שיתמכו לבם בראות כי שוכן סנה יהיה עם ישראל בכל צרתם, ואם היה מפרש דבריו מתחלה ואומר כה תאמר וגו' אהיה שלחני אליכם היתה נעדרה ידיעה זו מישראל באופן כי תחלת המחשבה היתה סוף הדבור, אלא משה חסר מעט מאלהים. ואולי שידע והבחין אלא שלא סמך על עיונו ורצה שיגלה לו ה' דעתו בפירוש:
@62 **ויאמר עוד וגו' כה תאמר וגו'**. טעם שחזר לומר פעם ב' שם הויה ברוך הוא ולא הספיק לו הודעת שם אהיה, לצד כי שם הויה הוא כולל כל הבחינות הקדושות יחיד ומיוחד ברוך הוא, ומתחלה לא הזכיר לו אלא שם בחינה אחת מבחינות הקדושות אשר יתכנה בה ה' בזמן שיהיה עם ישראל בצרה, ובזמנו דיבר שהיו בצרה לזה הזכיר שם אהיה לצד דבר בעתו והזכיר שם המיוחד. עוד טעם שחזר לומר כה תאמר וגו' ה' וגו' לצד שחש אל עליון שיבין משה ששלל ה' מדעתו לומר לישראל שם הוי''ה, גם שלל מלומר מה שאמר בסמוך אלהי וגו' שלחני וגו' ולא יאמר אלא אהיה שלחני וגו', לזה חזר לומר כי יאמר גם כן ה' **אלהי אבותיכם** וגו'. ואראה כי באמירה זו רמז גם כן שם אהיה בתחלת שמות האבות א' דאברהם וב' יודין א' ביצחק וא' ביעקב:
@62 **עוד** יכוין ה' שידעו ישראל כי הוא זה המבטיח להאבות הבטחת הגאולה, כי שם אהיה לא הובא בכתובים הראשונים הבאים בהבטחות. גם לצד שעדיין ישמיעם דברות קדשו ופתח דברו יאמר אנכי ה' אלהיך לזה הקדים להודיעם שם אהיה ושם הוי''ה. שם אהיה הרמוז באנכי, ושם הוי''ה כפשוטו כדי שיצדיקו דברי משה כשידבר ה' ויאמר אנכי ה' והבן. נמצינו אומרים כי צריך משה לומר לישראל בסדר זה אהיה שלחני אליכם ולצד שהוא שם חדש לידיעתם ונקרא על שם המאורע פי' שהיה עמם בצרתם יחזור ויאמר להם ה' **אלהי אבותיכם**. ואולי שגם רמז ג' אותיות הרשומים בשמות אבותם שהוא שם אהיה נטוי על ראשיהם מלמעלה:
@63 **לך ואספת וגו'**. טעם כפל הדברים פעם ב'. נראה שיכוין ה' לומר כי בעת ביאתו למצרים בתחלה ובראשונה יאמר לכל איש ישראל כי הוא בא שליח מה' לישראל ואחר כך יקבץ כל זקני ישראל יחד ויאמר להם שליחותו יתברך כי פקד את עמו וגו'. וטעם קדימת הודעת לכל כי איש שלוח הוא להם מה' כדי שבאמצעות כן יתקבצו אליו כי זולת זה מי יטה אליו אוזן להתקבץ. גם נתחכם ה' להודיעו דברים שיאמר לכל איש ואיש מישראל ודברים אשר יאמר באסיפת זקנים, וטעם הזקנים לבד לצד הכבוד כאומרם ז''ל (ויק''ר פי''א) לא מקום אחד וכו':
@63 **פקד פקדתי**. אמר ב' פקידות כנגד פקידת קץ הגאולה וכנגד פקידתם מצרתם, והוא אומרו **אתכם** כנגד קץ הגאולה, **ואת העשו** י **לכם** כנגד צרתם במצרים כדי לגאול אותם מהצרה ולהעלותם אל הארץ אשר נשכע. ורמז להם כי זולת העשוי להם במצרים שהוא הלחץ וגו' עודנו זמן הקץ. גם רמז באומרו **העשוי** כי בא ליפרע מהמצריים את אשר כבר עשו להם:
@65 **ושמעו לקולך**. טעם אומרו **לקולך** יכוין להודיעו כי יאמינו ויקבלו ממנו הגם שלא יאמר להם מה שמו, ולזה אם היה אומר ושמעו לדבריך או אליך עדיין יש בנשמע כי טעם הקבלה לצד דברים הנאמרים ממנו, ומאומרו **לקולך** הנה הקול הוא מוגבל היותו מאדם המוציאו לא מזולתו מה שאין כן הדברים שיתכנו להאומר אותם והם דברי הזולת, לזה אמר **לקולך** פי' כי כשיוציא קולו קול מבשר יקבלו ממנו, ובזה שלל שאין שום דבר מעכב להם האמונה לא שאלת השם ואין צריך לומר אותות ומופתים:
@65 **ה' אלהי העבריים**. הנה האדון ה' צבאות נתחכם לומר אליו כי אינו מתרצה שיקרא שמו אלא על העברים ולא הודיע שם הגדול הזה אלא להעברים, והכוונה כדי שלא יהיה לו מקום לפרעה לומר לא ידעתי וגו' והלא גם ה' אמר אלהי העברים אבל אתה אינך מכיר כי בזוי אתה מאוד ומה יכיר איש שדה במרגליות:
@65 **נקרה עלינו**. פי' לבל יחשוב כי יהיו רגילים בכך ויהיה כזה יום מחר וכן על זה הדרך, גם אפשר שיאמר להם אחרי כן שיתמידו בענין, לזה אמרו כי דבר זה אינו בתמידות גם אינו דבר הרגיל אלא דרך מקרה והוא אומרו **נקרה עלינו**:
@65 **ועתה נלכה נא**. אומרו **ועתה** פי' כי דבר זה הם צריכין לעשותו תיכף ומיד בלא שום שאלת זמן כי אלהיהם לא קבע זמן. או ירצה כי אינו דבר זה אלא לפי שעה וכמו שפירשנו בנקרה עלינו, והכונה בזה מהטעם עצמו שאמר **נלכה נא דרך שלשת ימים**:
@65 **שלשת ימים**. וטעמן של דברים שאמר כן לצד שאמר בסמוך ושאלה אשה משכנתה וגו' ואם לא יאמרו כן אין מציאות לשאול מהם ולהלותם כלי כסף וגו' ולצאת ברכוש גדול. ובזה תנוח הדעת למה צוה ה' שאלת כסף וגו' מהשכנות בזמן מוקדם ולא המתין עד עת בא דכרו הטוב לצאתם מארץ מצרים ושם יאמר להם, ומה גם שהדברים שם במקומן ובזמנם נאמרו ביום שלמחר יצאו ואם כן מה צורך לאומרם קודם י''ב חודש. והיה נראה לומר כי זה היה לחזק לבבם באמיתות הגאולה ואין זה עיקר. ולדרכנו כפתור ופרח כי הוצרך ה' לומר להם הטעם שהוא הסובב שיאמרו נלכה דרך שלשת ימים וגו' שבזה ושאלה אשה וגו' לצד שדעתם לחזור. ובסמוך יתבאר עוד תיבת ועתה:
@65 **ועדיין** צריך לתת לב סוף כל סוף למה יצו ה' דברים שאינם מהמוסר לגנוב דעתם בין בהליכה בין בהשאלת חפציהם, והאמת כי כל המעשה הוא משפט צדק כי לצד ששעבדו בישראל צריכין. להעלות שכר שכיר, וצא ולמד מתשובת איש ישראל למצרים (סנהדרין צ''א.) כשתבעו מהם כליהם אשר שאלום, אלא למה יעשה ה' הדבר דרך ערמה כי ח''ו לא קצור קצרה ידו מפדות ישראל בעל כרחם ולהוציא ממונם ועיניהם רואות וכלות:
@65 **ונראה** לומר כי נתכוין ה' בזה להטעותם כדי שירדפו אחריהם להכבד בפרעה וגו', וזולת ההשאלה גם זולת ה. ליכתם בדרך זה על דעת לחזור לא היו המצריים רודפים אחריהם. ועיין מה שכתבנו בפרשת בשלח בפסוק ויהפך לבב פרעה וגו':
@65 **ותמצא** אות לדברינו כי אמרו ז''ל (שמו''ר פי''ד) שבימי האפילה גילו ישראל מצפוני המצריים וידעו אוצרותיהם וסגולותיהם וחפציהם וביום שאלתם לא היו המצרים יכולים להכחיד, מארי דאברהם ולמה לא נטלום אז ואין מבין דבר, אלא ודאי שנתכוין ה' שיעשו כסדר זה לרדוף אחריהם כנזכר ויכבד בהם. ובענין המעשה מצד עצמו שנטלו ממונם אין איסור בזה להציל אדם את שלו מהאנס, וצא ולמד מיעקב שהיה מערים להציל את שלו מיד לבן הארמי, וצא ולמד ממעשה ג' תנאים (יומא פ''ג) אשר הצילו פקדונם מאשת כידור בדרך ערמה ואין בזה איסור, והוא אומרו הנביא (תהלים י''ח) ועם עקש וגו'. ומה שלפנינו הענין הוא יותר נקי ובר כי דקדקתי בכל הדברים הנאמרים בענין ואין בהם דבר שקר כי לא הזכירו בלשונם החזרה כלל, וגם לשון זה לצד מעלת קדושו אלהי ישראל לא רצה לכנות הדברים אליו אלא הם בני ישראל ידברו כזה, ולזה אמר תיבת **ועתה** פי' לומר כי הם דברי עצמם לא דברי עליון. שאם לא אמר ועתה היה הכונה על זה הדרך נקרה עלינו ואמר נלכה וגו', וכמו כן תמצא בדבר משה עם פרעה אמר לו (ה' א') שלח את עמי ויחוגו לי במדבר לא הזכיר זמן אלא ישראל אמרו לו (ה' ג') נלכה נא דרך וגו', והגם שבדבריהם שם לא אמרו ועתה סמך על פסוק ראשון. והבינותי באמרי נועם באומרו שלח את עמי ויחוגו לי במדבר כי כל דבריו צדק ואמת, שהרי דור שיצאו ממצרים לא חגגו אלא במדבר כי שם נפלו פגריהם ואת בניהם הכנים ה' לארץ, והגם שאותם גם כן יצאו ממצרים אף על פי כן לא יחשבו הם אלא הגדולים העובדים והזובחים והם מבן עשרים שנה, ובזה כל דברי ה' אמת וצדק. גם השאלת הכסף וגו' אין בו דבר שקר בתורת שאלה בא לידם אלא שעכבוהו בעד תביעתם שיש להם כנגד שכר שכיר שעבדו אותם ובנו כמה בנינים וכשיבואו לחשבון ידייקו החשבון וישלימו להם המצריים מה שנוגע להם:
@65 **ואחת** שאלתי עמדה לי ומה הכריח הדבר להיות כן לרדוף המצרים אחרי בני ישראל ולמה לא יכבד ה' בפרעה ובכל עמו ויעלה עליהם היאור בדבר עצמו אשר זדו ושם יצף ה' לפרעה ולכל עמו וגם הנשים והטף ולא היה צריך לכל האמור ויוציא ישראל בכסף וזהב בעל כרחם או שיטלו הכל בשבעת ימי אפלה (שמו''ר פי''ד) כי להם היה אור וחפשום כמו שכתבנו בסמוך. ואולי כי עשה ה' ככה לב' טעמים, הא' כי קריעת ים סוף ופלאיו פרסמו גדולתו ית' וכבודו מלא עולם כידוע מה שלא היה נעשה כן באופן אחר, וטעם ב' כי ה' מודד מדה כנגד מדה ואמרו ז''ל (סוטה י''א:) כי המצריים נתחכמו על ישראל לשעבדם בתחלה בפה רך ואחר כך בפרך והשופט בצדק מדד במדה עצמה כי מתחלה בפה רך נלכה ג' ימים השאילונו כספיכם שמלותיכם וגו' ואחר כך בפרך, ועל כל פנים נתחכם האדון שלא יצא גם מפי ישראל דבר שקר כנזכר (מיכה ז') תתן אמת ליעקב:
@68 **לא תלכו ריקם** כאן רמז ה' משפט עבד עברי דכתיב בו (דברים טו) לא תשלחנו ריקם הענק תעניק לו:
@69 **ונצלתם וגו'**. כאן רמז היתר הצלת אדם ממונו מאנס. או ירמוז שבזה יסובבו למצרים לרדת במצולות ים כי באמצעות ב' המצאות שידברו ללכת דרך שלשת ימים גם כשישאלו מהם כליהם זה יסובב אותם לרדוף אחריהם וירדו במצולות:
@70 **ויען משה וגו'**. צריך לדעת מה מקום לטענת לא יאמינו אחר שהבטיחו ה' ואמר ושמעו לקולך. עוד למה כפל לומר לא יאמינו ולא ישמעו בקולי. והיה אפשר לומר כי לצד שאדם בעל בחירה ורצון לא סמך לבו עליהם שיצדיקו באמונה. ואומרו **ולא ישמעו** וגו' פי' אפי' שמיעת קולו לא ירצו לשמוע. ואין דרך זה מספיק בכוונת הכתוב כי לא היה לו להרהר אחר מדותיו יתברך ולחשוד כל כך בישראל. עוד יש לדקדק אומרו **הן** ולא אמר אם לא וגו'. ויתבאר על נכון על דרך מה שכתב רמב''ם בפ''ז מהלכות יסודי התורה וז''ל אין נבואה שורה אלא על חכם גדול בחכמה וכו' שלם בגופו וכו' ע''כ, וכתב הכסף משנה וזה לשונו וצ''ע למה לא כתב שצריך שיהיה עשיר גבור ועניו ותירץ שאותם תנאים צריכין למתנבא בקביעות ורמב''ם לא נחת לפרש אלא על המתנבא שלא בקביעות. והנה אפי' אם נאמר שתחשב נבואה זו של משה אקראי מה שאינו כן אף על פי כן טוען טענה הנשמעת לצד ענותנותו כי הוא חסר תנאים שבהם יאמן נביא לישראל, והוא אומרו **והן** פי' וכן הוא הדין שלא יאמינו לי כי אין אני חכם גדול בחכמה ומלא מכל התנאים המאושרים ואין צריך לומר אם תחשב נביאת קביעות כמו שכן הוא כפי האמת כי הוא הולך ובא מהשם לישראל ולפרעה ולמצרים אם כן צריך שיהיה עשיר מה שלא כן היה, וזה לך האות שהיה רועה לחותנו צאנו ולא נתעשר אלא במדבר מהלוחות (נדרים ל''ח.) ואם כן אם יבואו ישראל לשאול לזקניהם המשפט הן לא יאמינו לי כפי הדין. ומה שאמר **ולא ישמעו בקולי** כאן רמז עוד טענה הנשמעת כי הוא כבד פה וכמו שגילה אחר כך בפירוש כי כבד פה. ודבר זה הוא אחד מתנאי המתנבא אפי' באקראי שיהיה שלם בגופו, וזה אחד מחסרוני הגוף, ולזה אמר ולא ישמעו לסיבת קול כי כבד פה וכבד לשון הוא, ואמר הטעם **כי יאמרו לא**.
@70 **נראה אליך** וגו' פי' אינך ראוי שיראה לך כל עיקר ואפי' באקראי. ומה שלא טען טענה זו משה עד עתה ולא שאל אלא ואמרו לי מה שמו מה אומר שזה יגיד שאינו חושש להם שלא יאמינו שאם היה חושש לזה לא היה מחזר אחר ידיעת השם שהוא דבר שתכף יאמר אליו זה שמי:
@70 **ואולי** כי נתכוון בשאלה ראשונה ואמרו וגו' שיגלה ה' שמו וסודו אשר יעשה בו נפלאות, כי שם המפורש יפליא עשות ובאמצעותו יקנה כל הקניינים בין מעלות המורגשות בין מעלות האושר והחכמה וישלים עצמו להיות ראוי לנבואה בסוד (תהלים צא) אשגבהו כי ידע שמי, גם יפליא בעיניהם נפלאות מדרכי השם. ובתשובת ה' אליו אפשר שלא הודיעו סודי השם וסגולותיו ונפלאות אשר יפליא בהם, לזה חזר וטען והן וגו' כמו שפירשתי:
@70 **או** אפשר שלא נתרגש משה לטעון טענה זו הן לא יאמינו אלא לצד שאמר ה' לו דבר חדש מה שלא שמע מקודם, והוא אומרו ואני ידעתי כי לא יתן אתכם מלך מצרים להלוך ולא ביד חזקה, אמר מעתה משכחת לה שלא יחשיב פרעה שליחותו ולא ישלחם אם כן הן לא יאמינו לי, וכשיתרבה השליחות ולא ישלח יוסיפו שלא לשמוע בקולי, והטעם כי יאמרו **לא נראה אליך** וגו' שאם היו הדברים מאל עליון מי הוא זה שימאן לעשות דבריו ולא ישחית לו משתין בקיר (מלכים א' יד) אלא ודאי כי לא ה' שלחך ואפי' נבואה לא השגת:
@71 **ויאמר וגו' מזה בידך**. אין שאלה זו דומה לשאלת ה' לבלעם (במדבר כב ט) מי האנשים וגו' ואמרו ז''ל (ב''ר פי''ט) שמצאו עביט של מי רגלים שהיה לו לומר אתה ידעת, כי שם משמעות השאלה הוא שהענין נעלם ושואל עליו, וממה שמשיב מגלה דעתו מה שהוא עביט של מי רגלים, מה שאין כן שאלה זו לא שאל על הנעלם כי גלוי היה כי בידו מטה אלא כמי שרוצה שיודה בפיו על הדבר, ועשה משה מצות רבו **ויאמר מטה**, ושיעור משמעות הוא ויאמר אתה מבחין מה שאתה לוקח בידך מה הוא ואמר לו הן אדוני אני מכיר במה שבידי שהוא מטה:
@72 **ויהי לנחש וגו'**. כוונת אות זה הוא לרמוז כי בחינת הקליפה תתייחס לנחש, וצא ולמד מנחש הקדמוני כי הוא בחינת ס''מ, ורמז לו כי באמצעות ידי משה בכוחו העצום מאבד כח הנחש ויהיה לעץ יבש וכשירף ידו ממנו ומשליכו יהיה לנחש עד שנם משה מפניו. ואולי כי לזה נתכוון באומרו **מזה בידך** פי' שישכיל השכלה דקה בו אם התחיל להתנועע כעכברא דדברא שיתחיל לחיות מעט מעט, ולפעמים ימצא מיעוט מיעוטו עכבר ולפעמים מיעוטו ולפעמים חציו, והשיב משה **מטה** פי' כולו עץ יבש; **וישליכהו ארצה ויהי** לנחש פי' הויה בפעם אחת היה נחש, ואומרו **ארצה** רמז כי בערך הנחש תגדל מעלת הארץ כי הוא לחמו ונחשבת לו, והראהו בזה דברים רבים למשה, גם שיעשה האות עצמו לישראל, ואומרו **שלח ידך** וגו' פי' הראהו שהגם שיצא מרשותו יש כח במשה להתחזק עליו ולהסיר ממנו כחו. ואומרו **ואחוז בזנבו** ולא אמר בו, נתכוון ה' לומר אליו להיות שחששת הנחש היא אם יקחהו מזנבו כי אם יתחכם לקחת ראשו וידחוק הנושך אין מיחוש מכל הזנב לזה אמר אליו ה' אחוז אפי' בזנבו באין פחד. וכן הוא אומר **ויחזק בו** פירוש במקום שנזדמן לו באין פחד, והיה למטה בלקיחתו **בכפו** פירוש בנגיעתו בכף משה יבש כחו כאחת ולא נותר בו שום חיות והוא אומרו ויהי למטה בכפו:
@74 **למען יאמינו וגו' אלהי אבותם**. טעם אומרו אלהי אבותם וגו' פעם אחר פעם. אולי שרמז כי מהנמנע שתהיה שליטת האדם בבחינת הנחש כחזיון האות אלא למי שנגלה אליו אלהי אבות העולם, ולזה יהיה הדבר לאות כי נראה אליו אלהי אבותם וגו':
@78 **והיה אם לא יאמינו**. וכי יש ספק לפני הקב''ה, ועוד והלא כבר אמר ושמעו לקולך. ואולי ששיעור הדברים כך הוא והי' אם עדיין תחוש עוד ולא יספיק לך טעם זה לומר שבו ודאי יאמינו. עוד נראה כי נתכוון לומר לו להסיר גם ספק שאינו נראה, והוא דלמא לא יחליטו ישראל האמונה בלבם הגם שבפניהם לא יוכר העדר האמונה, לזה אמר אם לא יאמינו וגו' וספק זה אינו יוכל להתברר למשה לומר עליו מי איכא ספיקא קמי שמיא לומר אם לא, שהם דברים שבלב, ובא האדון להסיר ממנו ספק הכחשת האמונה בלב ישראל באמצעות שלש האותות:
@78 **והיו המים וגו'**. מאור עיני ישראל רש''י ז''ל נראה בעיניו כי טעם אומרו והיו והיו הוא לומר שלא יהיו לדם עד שיהיו ביבשת. ודברי קדוש חן. ואני מוסיף בו טעם לשבח כי הוא מטעם עצמו שציוה ה' כי אהרן הוא יכה במטהו ביאור, ואמרו ז''ל (שמו''ר פ''ט) כי משה אינו יכול להכות היאור לצד שהגין בעדו, וכאן ציוה ה' שיקח ממימי היאור ויהיו לדם ונתחכם שלא תהיה המכה על ידי משה לזה אמר **והיו בהוייתן** כל זמן שיהיו בידו אלא אחר שיהיו ביבשת יהיו דם ובזה אין לקותם בא ע''י משה:
@79 **ויאמר משה וגו' בי אדני**. אחר שנסתמו ממנו הטענות חזר לבקש מה' ממדת הרחמים, ולזה דייק לומר אל ה' שם הרחמים מה שלא אמר כן מקודם אלא כל אמרותיו הם אל האלהים, והתחיל להתחנן לפניו ואמר **בי** לשון תחינה וריצוי:
@79 **או** ירצה באומרו **בי** פירוש טעם שלא יאמינו הוא לצד החסרון התלוי בי כשיראוני עלג ואפי' דיבור אין אני יודע דבר, ואומרו **גם מתמו**. ל וגו' נתכוון לומר אליו כי חשב שבאמצעות שידבר ה' עמו פעמים ושלש יוסר פגמו וידבר צחות וכיון שראה שדבר פעם א' גם ב' גם ג' ועודנו לא איש דברים צעק לבו אל ה' שהרי מומו קבוע ומעתה ודאי שלא יאמינו לו כי יאמרו אם נראה אליו ה' היה מסיר פגמו:
@80 **ויאמר ה' אליו מי שם וגו'**. ירצה לומר אליו שהיה לו לבטוח בו שהוא השם פה שישים גם אליו, וכיון שכן מנע ממנו הרפואה זולת לעת הצורך, והוא אומרו **ועתה** וגו' **והוריתיך** אבל לא לעקר ממנו העלגות. או ירצה לרמוז שיעשה תשובה על מיעוט הבטחתו. עוד ראיתי לדקדק דברי ה' שלא רמז לו פרט הפעולה שמשה צריך לה שהיא שישים לו פה אחר היותו אלם או עין אחר היותו עור ולא אמר אלא תחילת הבריאה ומאורע שאחרי כן והוא אומרו מי שם פה וגו' והמאורע הוא או מי ישום אלם או חרש, וכן חלוקה ב' או פקח בתחלתו או עור אחר כך אבל לא הזכיר כי יעשה אחר כך לאלם פתוח פה וחרש שומע ועור פקח. ומעתה אין כונת התשובה ידועה. ויש להעיר עוד למה ה' לא מנע ממנו טענה זו בתחלה ובראשונה, ומה גם שראוי להיות כן:
@80 **אכן** נתכוין לומר אליו כי הוא האדון הוא הבורא והשכיל לעשות פה לאדם לשכלול הבריאה, והוא אומרו **מי שם פה** וגו', ואמר **או מי** וגו' פירוש שהגם שיארע לאדם דבר שיהיה אלם וגו' גם זה לא במקרה יהיה הדבר ההוא אלא ממני אנכי ה' הוא העושה הדבר ואני מסבב סיבובין לעשותו כן לתכלית דבר. ובזה רמז לו כי כבדות פיו ולשונו הוא לתכלית דבר טוב ולזה לא הסיר ממנו עלגותו. או ירצה לומר כיון שהשם אלם וגו' הוא ה' ברוך הוא אם כן היה לו להשכיל בדעתו כי מה' יצא דבר מלכות שיעשה עלג וזולת גזרת מלך לא היה כן, ואפי' לדברי חכמים (שמו''ר פ''א) שהיה סבה לדבר זה גחלת שנתן לפיו בהבחנת פרעה אם לא היה ה' חפץ בדבר לא היה כן אחר שה' הכין ועשה פעולתו בהכנת הפה כאומרו מי שם פה וגו' דבר פשוט הוא שכשיעשה אלם יהיה הדבר לצד איזה תכלית הגון או למה שנתחייב כפי מעשיו, וכמאמר רבי אמי (שבת נ''ה.) אין יסורין בלא עון, וכבד פה ולשון נקראים גם כן יסורין ואם כן היה ראוי לו למשה לדעת סיבת דבר ולתקן ויתפלל לה' על הדבר אשר לא כן הוא עושה אלא אדרבה מראה כי הדבר הוא טבעיי ואינו תלוי מצידו, ולזה אמר אליו **ועתה** ואין ועתה אלא תשובה שיחזור בו מדעת זו:
@80 **וכנגד** חשש שלא יאמינו ישראל לצד עלגותו אמר אליו אנכי אהיה עם פיך והוריתיך וגו'. עוד נראה שיכוין באומרו **לך ואנכי אהיה עם פיך** שהשיבו תשובה נצחת כי כל עוד שלא התחיל במצוה אין מקום להסיר עלגותו, ולזה אמר לך פי' לך בשליחות זה וכשתדבר תראה שיוסר כבדות פיך ולשונך, והוא אומרו **והוריתיך אשר תדבר**, לא אמר את אשר תדבר אלא אשר תדבר פי' אראך שתדבר בלשון צח והבן ונכון. וטעם אומרו והוריתיך ולא אמר ואראך נתכוין לרמוז לו שיהיה לו צחות הדיבור כדרך הרגיל באדם בהורתו לא לפי שעה יהיה הדבר כמעשה ניסים אלא בדרך טבעיות גמור כאילו הורה גבר בלשון צח ורגיל ולא כמו שכתבתי בפי' ראשון שלא ידבר צחות אלא בעת הצורך:
@82 **בי אדני שלח וגו'**. פירוש איני ח''ו תולה הדבר לצד הבורא כי כל יכול עשות אלא מניעת הסרת הפגם היא. מצידי כי איני ראוי לנס והוא אומרו בי אדני תלוי כל החסרון והמניעה, ואומרו **שלח נא** וגו' פי' ביד מי שהוא ראוי לעשות שליחותך לא בשפל כמוני שקבוע בי מומי וזה יגיד על היותי בלתי מוכשר לשליחות נעלה:
@83 **ויחר אף וגו' במשה**. אומר אני שהרושם שעשה חרון אפו הוא שנשאר משה קבוע בו מום כבידות פה ולשון, והוא אומרו **במשה** פי' בו בגופו ונכון. ודרשת חכמים (זבחים ק''ב) שאמרו שהוא אומרו הלא אהרן וגו', אין דברינו מכחיש אותה. ואולי כי שניהם רמז הכתוב ורמזם באומרו **ויחר אף** שהיה לו לומר ויחר ה' ומאומרו ויחר אף רמז לב' דברים:
@83 **כי דבר ידבר**. טעם הכפל לומר אליו דבר עתה ידבר פי' הגם שיהיה כבד פה ולשון כמותו ידבר. או ירמוז דברינו עצמם שפירשנו בפסוק ויחר אף והוא אומרו דבר ידבד פירוש אומרו דבר לגופו ואו' ידבר להסמיך לה תיבת הוא לומר הוא יהיה דיבורו צח ולא אתה כי תשאר כמות שאתה:
@83 **וגם הנה הוא וגו'**. לפי מה שפי' באומרו דבר ידבר כי יגיד שבחו של אהרן שהיה עושה שליחותו הגם שהיה כבד פה יוצדק לומר וגם הנה וגו' כי הוא תוספת שבח. ולפי מה שפירשתי כי החליט ממשה תקות הסרת הכבידות פה, ירצה על דרך אומרם ז''ל במס' שבת קל''ט וז''ל בשכר וראך ושמח בלבו זכה לחושן המשפט על לבו ע''כ, כפי זה נתכוין באומרו **וגם** כי מלבד שהחליט ממשה רפואת הדיבור כמו שכתבנו גם הסיר ממנו הכהונה ונתנה לאהרן והוא אומרו וגם וגו' ושמח בלבו כאן רמז הסרת הכהונה והם דברי רז''ל.
@83 **עוד** נתכוון להגיד שבחו וענותנותו כי מן הראוי היה לו להקפיד על היותו הוא לפה ואחיו הקטון יגדל ממנו ואמר כי מלבד שלא יקפיד על הדבר אלא וגם וגו' ושמח. ובאמצעות דברים אלו יגיד כי הגם שהוא עניו דבר ידבר והגם שהיה כבד פה וכמו שפי' שהענוה לא תגרום הרחקת עשות רצון המלך. ואמר **ושמח בלבו** לומר הגם שלא יראך שמחה לפנים הוא ברוך הוא העד שישמח בלבו. או ירצה שלא לפנים בלבד אלא לפנים ובלב:
@86 **ואת המטה הזה**. אמר **הזה**, לפי מה שאמרו בזוהר (זוהר ח''ב כ''ח) כי היו ב' מטות אמר הזה לשלול אחר. ואומרו **תקח בידך** פי' בתמידות, והטעם לסימן כי יש בידו מטה עוז תפארה וכן חוק לשררה הממונים על דבר מלכות, וזה לך האות דכתיב (פסוק כ') וישב ארצה מצרים ויקח וגו' מטה האלהים בידו הרי שתכף לבש כלי זיין שנתן לו ה', שאם היתה כוונת הלקיחה הוא שלקחו להוליכו עמו לא היה לו לומר בידו. ואומרו **אשר תעשה בו את האותות**, אולי שרמז למטה ב' של אהרן שבו עשה האותות שנהפך לנחש, וכאומרם שם בזוהר שזה יקרא מטה אהרן שצוה גם עליו שיהיה מוכן ביד אהרן. עוד ירמוז על דרך אומרם ז''ל (תרגום יונתן שמות ב' כ''א) שהמטה היה סנפרינון. ולא היה אדם יכול להסיטו אלא משה, וכפי זה לקיחתו יגיד כי הוא בו יעשה את האותות, וזה לך האות כי לא יקרב אל המטה איש זר זולת משה:
@87 **אלכה נא**. לדבריהם ז''ל (שמו''ר פ''א) שאמרו שמושבע היה ליתרו הוצרך לחלות פניו למחול לו על השבועה:
@87 **ואראה העודם חיים**. ולא גילה לו דבר השליחות כי לא אמר לו ה' לאמר ואמרו בת''כ (יומא ד':) שכל שלא אמר לו לאמר הרי הוא בבל תאמר:
@87 **לך לשלום**. פי' מחל לו השבועה וכל כיוצא בזה אינו צריך התרה אלא כל שמוחל המשביע אין כאן שבועה:
@88 **אל משה במדין**. כוונת הכתוב בהודעה כי הדיבור היה במדין, להגיד שבחו של משה שלא חש על שונאיו שהיו במצרים בעת שטען טענותיו הרבים כי לא היה חושש בכל טענותיו אלא לצד הורעת כח השליחות לא לצרת עצמו והראיה שלא טען כי ירא ממבקשי נפשו, ואם לא היה אומר הכתוב במדין תבא הסברא כי לא החליט בדעתו של משה ללכת בשליחות עד שהובטח מפי אל כי מתו מבקשי נפשו, לזה אמר **במדין** לומר שאחר שגמר בדעתו והסכים עם ה' ללכת הוא שנתבשר ולא היה דבר זה מעכבו:
@91 **כה אמר ה' בני בכורי**. צריך לדעת כונת נבואה זו שלא בזמנה. גם במה שמר לבל יטעה משה ויאמר נבואה זו לפרעה בפעם ראשונה בעמדו לפני פרעה.
@91 **ונראה** שנתחכם אל עליון להרים מכשול מלב משה לבל יקוץ בשליחות וח''ו תולד בדעתו תולדה רעה בראותו עוצם המכות ופרעה לא קם ולא זע ויארך זמן חודש נכנם חודש יוצא, לזה שם דבר בפיו ויהיה לו למבטח לבל יחשוב מחשבות און ח''ו ואמר אליו **ואמרת אל פרעה כה אמר ה' בני בכורי**, ומעתה יהיה מצפה משה לדבר זה וכל עוד שלא יראה מכת בכורות יסעוד לבו ולא יהיה מתירא כל עוד שלא הביא עליו מכה זו. ושיעור הנבואה הוא על זה הדרך בלכתך לשוב מצרים ראה וגו' והנני מודיעך שאני אחזק את לבו ולא ישלח אפי' אחר כמה מכות ולבסוף ואמרת אליו וגו' הנני הורג וגו'.
@91 **עוד** נתחכם בזה להודיעו למשה כי מכה זו תהיה באחרונה כי בה ישלח פרעה את העם כי לא אמר ה' שיחזק לב פרעה אחר מכת בכורות, ואשר לזה כשאמר פרעה למשה (לקמן י כח) אל תוסף ראות פני הכיר כי הגיע עת מצוה שאמר לו ה' בדרך בבואו ממדין למצרים ואמרת בני בכורי. והגם שהוסיף דברים שלא נאמרו כאן, מן הסתם נאמרו וילמד סתום מהמפורש, ובזה אין להקשות אימתי נאמרה למשה אותה נבואה והוצרכו מרבותינו לומר מדרשים, והרי שלך לפניך, ולא חש ה' שיטעה משה ויאמר נבואה זו לפרעה, כי באמצעות שישוב משה לפני ה' דברי פרעה תיכף ומיד ישלחהו בשליחות מכה אחרת וממילא ידע משה כי עדיין לא הגיע זמן מכות בכורות עד עת בא דבר פרעה ואמר לו אל תוסף וראה כי אינו יכול לצאת מלפני פרעה להתנבאות חוץ לעיר לדעת מה ידבר ה' אמר הגיע הזמן לאמר מכת בכורות. או דייק דברי ה' שאמר ואני אחזק את לב פרעה ומעתה אינו יודע שיעור שיחזק ה' לבו שיאמר לו אחרי כן מכות בכורות וכשאמר לו אל תוסף ראות פני הכיר כי זה הוא תכלית חוזק הלב ובצירוף טעם ראשון שכתבנו אמר לו שליחות מכת בכורות.
@91 **עוד** אפשר שאם היה פרעה מחזיק לבו לשלח ישראל ולא היה מדבר דברים נגד כבודו יתברך כאומרו (לקמן ה' כ') מי ה' היה ה' מביא עליו מכת בכורות תיכף ומיד ולא היה משביעו כוסות התרעלה, וזה הוא שרמז ה' למשה באומרו ואני אחזק את לבו ולא ישלח את העם פירוש שהחוזק הוא שלא ישלח שאם ישלח אפי' מכת בכורות לא תבא עליו, וכשלא יהיה אלא מניעת שלוח העם יהיה לו לצרה מכת בכורות, אבל אחר שנגע בכבודו יתברך יבואו עליו מכות גדולות ונאמנות, וכן תמצא שאמר ה' (לקמן ט טז) בעבור הראותך את כחי ולמען ספר שמי וגו':
@93 **ויבקש המיתו**. אמר **ויבקש**. אולי כי לצד שהיה שליח מצוה היה לו מונע על דרך אומרם ז''ל (פסחים ח':) שלוחי מצוה אינן ניזוקין, והמצוה שהיה עסוק בה קנה לו בה פרקליט אחד והוא המלוהו והשומר אותו ומנעו למשחית בל קרוב אליו. ואולי כי לזה נתכוין באומרו **בדרך במלון** לומר שלא היה עוסק בהליכת המצוה אלא במלון ולזה הוא שבקש המיתו. ואף על פי כן היה לו מונע כי סוף כל סוף חשוב כשלוחי מצוה גם בזמן ההוא, וביני ביני כי המלאכים נועדו יחדיו נתחכמה צפורה והרימה מכשול, אכל בעודו עסוק במצוה פשיטא כי לא יקרב אליו משחית:
@96 **לך לקראת משה וגו'**. והגם שאמר אליו ה' מקודם (לעיל ד יד) הנה הוא יוצא וגו', לפי מה שנודע לנו כי ידבר ה' דברים רבים בדיבור אחד בשעה שאמר למשה הנה הוא וגו' יצא דיבור אחר לאהרן במצרים, ונבואה זו אין ספק שנאמרה לאהרן הגם שאמרו ז''ל (תו''כ א') שכל מקום שנאמר וידבר ה' אל משה ואל אהרן לא נאמר הדיבור אלא למשה שיאמר לאהרן, ואפי' לר' יוסי הגלילי שסובר (שם) שנתמעט אהרן אפי' בדיבורים שנאמרו במצרים דוקא בדברים השייכים בשליחות להזולת אבל פרט זה שיעשה אהרן מצוה הרי שלך לפניך שדבר אליו ה', ומזה אתה למד שהיה נביא לעצמו:
@101 **ואחר באו וגו'**. פי' אחר שהאמין העם. וכן הם דברי ה' דכתיב (לעיל ג, יח) ושמעו לקולך ואחר כך ובאת וגו', ולזה הפסיק הפסקה קודם ושמעו לקולך הגם שהוא סיום ענין הנוגע לישראל וסמכה עם ובאת וגו' והבן:
@102 **אשר אשמע וגו' לשלח וגו'**. יכוין לומר מה כחו הגדול לשמוע בקולו בדבר גדול כזה לשלח וכו', וחזר לומר שדבריו לרבותא נאמרו הגם שיהיה גדול עד מאוד לא יועיל זה לשלח ישראל, ואין כוונתו בזה שהוא יודעו אלא שאינו גדול בעיניו לשלח ישראל אלא שאינו יודעו כל עיקר והוא אומרו **לא ידעתי** וגו'. ואומרו **וגם** פי' והגם שיודיעהו וישכיל כי גדול הוא אף על פי כן את ישראל לא וגו' והם תחלת דבריו והבן:
@103 **ויאמרו וגו' פן יפגענו**. דברים אלו הם של ישראל. והגם שאמרו ז''ל (שמו''ר פ''ה) שהזקנים נשמטו אחד אחד אף על פי כן אחר כך דברו דברים אלו. ועל שלא באו יחד עם משה ואהרן נענשו. או אולי שכל העם נכנסו יחדיו אל פרעה ואמרו לו דברי טעם כי יותר טוב לו שישלחם ויש תקוה שישובו אחר כך משבת שם ויכלו בדבר וגו', גם דבר זה יפחד ממנו פרעה כי יגע עד לבו דבר וחרב הבא לשכונתו. ואולי נתחכמו להפחידו פן יפגעהו לפרעה וגו' והלבישו הקללה בהם לצד כבודו של מלך:
@104 **ויאמר וגו' למה משה וגו'**. פירוש להיות שהיו לפניו משה ואהרן והזקנים שאמרו אלהי העברים וגו' והחזיר פניו אל משה ואמר אין תלונתי על זקני ישראל כי הם נפל עליהם פחת ופחד מהחרב והדבר, והתלונה הוא עליכם שעשיתם ב' דברים האחד שבאתם בשליחות אלי מאלהיכם אם כן הדבר תלוי בי אם כן מה מקום להפחיד העם פן יפגעם בדבר והלא אינם ברשות עצמם ואנוסים הם, מה תאמר כי הם יכולין לצאת ברשות עצמם אם כן למה באת אלי בשליחות לשלחם. ואולי כי לזה נתכוונו רז''ל (שם) שאמרו וז''ל אתם למה דבריכם למה פי' אתם למה באתם אלי, דבריכם שאמרתם לעם הזה מפי אלהיהם פן וגו' למה, שהם ב' דברים סותרים, והשיב פניו לישראל ואמר **לכו לסבלותיכם**, כי משה ואהרן ברשות עצמן היו:
@105 **ויאמר פרעה וגו'**. פי' לצד שהם רבים אינם בת יכיל (מ''א ז) להסיר מהם מורך לבב זה של פגיעת חרב מכולם ודבר זה יהיה גורם שתשביתו אותם מסבלותם כי יתחמץ וירך לבבם, ותרעומת זה הוא על משה ואהרן. או יטעון כנגד הנוגשים אשר הניחו אותם לבא לפרעה ובטלו עבודתם, ואמר כי הן רבים הם וזמן מועט של ביטול עבודתם יעשה הרבה רושם:
@106 **ויצו פרעה ביום ההוא**. פי' דוקא ביום ההוא צוה לעשות כן, והטעם כדי שבאמצעות תוקף הצרה שלא יוכלו שאת תשכח מהם המחשבה ההוא של המורא ויפנו לעבוד עבודתם, והמשכיל יבין כי צרה המזומנת תשכיח מיחוש צרה העתידה ושכבר עברה, וזה מהמורגש למשכיל על דבר. ושיער כי יספיק לזה יום אחד.
@106 **או** יכוין הכתוב לרמוז שלא נשאר עוד להם בעבודה אלא יום ההוא כי למחר בא משה והכה יאור מצרים ונשברה מקל השעבוד כמאמרם ז''ל מעת שהתחילו המכות נסתלק השעבוד מעליהם ואדרבה התחילו להוזיל כספם בעד משקה מים כאמור בדבריהם ז''ל (שמו''ד פ''ט) ואין להקשות מאומרו גם תמול גם היום, כי יום שלפניו לא כילו חקם לצד שהיה יום בשורה והיו מקובצים לפני משה שעשה לעיניהם האותות:
@108 **כי נרפים הם וגו'**. צריך לדעת מי תלה צעקת עבודה לאלהים לצד שהעבודה רפויה עליהם. ואולי שיכוין לומר שלא רצו ללכת לזבוח אלא לצד שראו שהטיב ה' עמהם שהקל מעליהם השעבוד והם בטלים **על כן** וגו' פי' על זה הם צועקים לאמר נזבחה וגו' פי' להביא קרבן תודה על הטוב שהוציאם מצרת השעבוד, שזולת זה מה טובת ה' עליהם להתחייב לזבוח לו, לזה אמר **תכבד העבודה** עליהם ומעתה לא ידברו עוד בדברים אלו של שקר כי אפי' כפי דעתם אין להם לזבוח כי פסקה טובת רפיון הצרה מעליהם.
@108 **עוד** ירצה כי מאומרם **נלכה ונזבחה** וגו' זה יגיד כי טעמם הוא כי מה שיבטלו מעבודתם ישנו בהשבון כשיחזרו ידחקו עצמם לעבוד בכל יום חלק יותר מהרגיל עד תשלום מלאכתם אשר בטלה, לזה אמר **לא תאספון לתת תבן** וגו' ואת מתכונת וגו' והטעם כי נרפים וגו' **על כן הם צועקים לאמר** פי' צעקה שאחריה אמירה אחרת שהיא התשלום העבודה שיעשו בחזרתם אם כן **תכבד** וגו' והבן:
@108 **עוד** ירצה באומרו **ואל ישעו** לשון רפיון. ואמר סיבת הרפיון הוא בדבר הנאמר להם ממשה שבעיני פרעה הוא שקר, והכוונה הוא על דרך מה שפירשתי בפסוק והשבתם וגו' כי באמצעות המורא פן יפגעם יכנס מורך בלבבם ולא יהיה בהם כח לעבודה הכבדה שעליהם לזה תכבד וגו' כנזכר:
@111 **כי אין נגרע וגו'**. טעם אומרו כי אין וגו' ולא אמר ואין נגרע, הכי פירושו כה אמר פרעה וגו' **אתם לכו** וגו' ודברים אלו אין בהם בשורה רעה ואדרבה הם חפצים בדבר להקל מעליהם מלאכת הבנין ולעשות מלאכה זו לקשש קש לתבן, לזה אמר טעם הגזירה היא **כי אין נגרע** ואין זה אלא המעטת הזמן בדבר זה כדי שתעשו עבודתכם בזמן מועט:
@122 **וישב משה וגו' למה וגו'**. כוונת הכתוב הוא על זה הדרך **למה הרעות** פי' כי לא אמרת לי אלא שיחזק לבו ולא ישלח את העם אבל לא שיכבד עליהם הרע. ואם תאמר שעדיין לא הגיע הקץ להקל מעליהם השעבוד וזה הוא סיבת הרע אם כן **למה זה שלחתני** פי' בזמן זה והיה לך להמתין עד קץ השעבוד:
@122 **עוד** ירצה על פי מה שכתבנו למעלה כי גילה ה' אליו שהגם שעדיין לא קרב קץ גאולה אף על פי כן הוא מקדים להציל אותם מהעוני וכשיגיע קץ הגאולה לאחר י''ב חודש יעלה אותם. והוא אומרו **למה הרעתה לעם הזה** ואם תאמר מוטב שיסבלו צרה זו לתכלית הגאולה אם כן למה זה שלחתני שהרי כל עיקר השליחות מקודם זמן הגאולה הוא לצד הסרת השעבוד ואם אין תכלית טוב לדבר אלא היציאה ולא הצלתו מצרה אם כן **למה זה שלחתני**, ורמז באומרו **זה** לי''ב חודש שנתעכבו ישראל במצרים מזמן זה עד הגאולה, וחשש משה כי צרה זו שהכביד פרעה על ישראל תהיה כן עד זמן יציאתם ממצרים.
@122 **עוד** ירצה להיות שהיו בישראל כת המשתעבדים וכת שאינם משתעבדים והוא שבט לוי, לזה אמר כנגד כת המשתעבדים **למה הרעתה לעם הזה**, אמר הזה. לשלול שאינם משתעבדים, וכנגד כת שלא גרם להם רעה אמר **למה זה שלחתני** פי' שלא הועלתי בשליחותי כלום.
@122 **עוד** ירצה על זה הדרך **למה הרעתה** לעמך ובהכרח להשיב באמצעות השליחות יצתה הרעה אם כן **למה זה שלחתני**, ורמז בתיבת זה לומר כי על זה היה ממאן מלילך בעת השליחות:
@123 **לדבר בשמך וגו' והצל וגו'**. פי' מלבד טענות הראשונים עוד הוא קובל לפני מלך איך יהיה הדבר הזה כי מאז דברתי לרשע זה בשמך לא די שלא עשה אלא הוסיף להרע, ודקדק לומר **מאז** פי' משעה עצמה שהזכיר לו שמו יתברך נתמלא חמה, כי בזה יוכר הדבר כי מה שעשה הוא משנאתו את ה' וממיעוט ערכו בעיניו נתכוון לזלזל ח''ו ואין לך מרים יד במלך ונוגע בכבודו כזה. ונתכוין משה בזה לומר כי איך לא נתקנא אל עליון לכבוד שמו להציל לישראל מידו למנעו מהרע לעמו תיכף ומיד הגם שלא יהיו ראויים ישראל לנס מצד עצמן יהיו ראויים למען שמו יתברך אשר חילל רשע בגובה לבו, והוא אומרו **והצל לא הצלת** בתמיה איך לא הצלת אותם למען מנאץ שמך. וכפל לומר ב' הצלות לרמוז כי בלא טעם זה הם עומדים להצלה ולזה שלחו:
@124 **עתה תראה וגו'**. טעם אומרו **עתה**. הוא תשובה למה שאמר ומאז באתי וגו' הרע לישראל יותר מהקודם, אמר לו **עתה תראה** כי רעה זו תיכף תסתלק תוספת ועיקר, כמו שכן היה שבמכה ראשונה של דם נסתלק השעבוד כמאמרם ז''ל (ש''ר ט') וזה הפך מחשבתו שחשב שיתמיד רעת ישראל מאמצעות שליחות זה עד עת הגאולה כמו שפירשתי בדבריו.
@124 **עוד** ירצה להשיבו על מה שאמר כי אויב חרף ה' ולא קינא לכבוד שמו, **עתה תראה אשר אעשה לפרעה** על זה. ואומרו **כי ביד** וגו' יתבאר לפי מה שפירשנו באחד מהטעמים שנאמר למשה מכת בכורות בשליחות ראשונה הוא שאם לא היה פרעה מעיז פניו לדבר דברים נגד כבודו יתברך תכף היה משלחם במכת בכורות ועל ידי כי דבר ה' בזה הפלא ה' מכותיו, והוא אומרו **כי ביד חזקה ישלחם** פי' אחזק לבו עד שאטעימהו מטעמים רבים מרים וקשים ואחר כך ישלחם וזה לטעם נגע בכבוד עליון:
@124 **וביד חזקה וגו'**. כאן הודיע אשר ירעיש ה' בהבאת מכת בכורות כאומרם ז''ל (ילקוט קפ''ו) בפסוק אין בית אשר אין שם מת כי היו מתים גדולי הבתים אם אין בכור והיו מתים בכורי אב גם בכורי אם ובאמצעות כן לא הספיק לשלחם לבד אלא לגרשם במהירות גדול דכתיב (לקמן יב לג) ותחזק מצרים וגו' למהר וגו'. וכנגד מה שאמר בתחלה למה הרעותה וגו', באה התשובה בפרשה הסמוכה וידבר אלהים וגו:
@124 **חסלת פרשת שמות**
@125 **וידבר אלהים וגו'**. צריך לדעת מה דיבר אלהים. גם הודעת אני ה' אחר שכבר אמר לו למעלה זכרון השם ואמר לו (ג טו) זה שמי לעלם.
@125 **אכן** להיות שדיבר משה לפני אל נורא ואיום דברים שאינם מהמוסר ובפרט לפנ. מלך גדול, ודבר זה נמשך לצד שהראה לו פנים צוחקות פנים שמחות הרשומים בשם הוי''ה, לזה הראהו ה' פנים של מורא שהם בחינת הדין הרשומים בשם אלהים, והוא אומרו וידבר אלהים אל משה. ושיעור. אומרו ו **ידבר אלהים** הוא כי הכתוב יגיד שהיה ה' מדבר כל הדברים האמורים בפרשה בבחינת שם אלהים שהם פנים המפחידים ומרעידים את הנדבר אליו, ואומרו **ויאמר אליו אני ה'** פירוש על דרך אומרם (ברכות ל':) במקום גילה שם תהא רעדה, נתכוון לומר לו כי הגם כי הראהו מדת הרחמים בדברו עמו לא מפני זה יסיר מסוה הפחד וידבר בלא מורא מלכות שמים, וזה לך האות כי ה' הוא האלהים שהרי הוא מדבר עמו בפנים הנוראים והבן:
@125 **עוד** ירצה על זה הדרך **וידבר אלהים** פי' דבר אתו משפט ומה הוא המשפט כי טענו טענה הנשמעת ואמר אני ה' פי' איך אתה מייחס לי מדה רעה ב''מ ותאמר אלי למה הרעתה והלא אני ה' ומדתי מדת החסד והרחמים וטוב אני לכל, וכמו שכן אמר הנביא (איכה ג') מפי עליון לא תצא הרעות כי אם הטובות, ומה שאמר שם והטוב הוא על בחינת פרט טוב אחד שהוא להיות אדם צדיק לא יגזור ה' דבר כן אלא ביד כל אדם לבחור בטוב. ותמצא שבכל פעם שיזכיר ה' זכרון תשלום הרע לעושי רשעה ידקדק לומר (ש''א כד) כי מרשעים יצא רשע וכן הוא אומר (ידמי' ב') תיסרך רעתך, (ישעי' ס''ד) ותמוגנו ביד עונינו, (איוב ח') וישלחם ביד פשעם, מה שאין כן הטוב (תהלים פ''ה) ה' יתן הטוב, (שם קמ''ה) טוב ה' לכל, ומעתה לו יהיה שעברה צרה על ישראל מי יודע אם היו חייבין כן ועונם גרם או לצד הקודם לתשלום גזירת העינוי, או לצד קצת מהם שלא האמינו כראוי וכדומה, והנך רואה כי הזקנים חזרו לאחוריהם ולא הלכו עם משה לפני פדעה כאומרם ז''ל (שמו''ר פ''ה) והקפיד ה' עליהם באופן כי מהם יצא להם דבר זה, ואיך הוציא מפיו דברים נכרים לומר למה הרעתה.
@125 **עוד** ירצה על זה הדרך להיות שאמר משה למה הרעתה למה שלחתני באה התשובה, כנגד למה הרעתה דבר אתו קשות שדיבר לפני אלהיו בלא דרך כבוד והעלים הכתוב הדברים לצד כבודו של משה, או אפשר שאמר לו שיעמידנו במשפט על זה בעת משפט, וכנגד למה שלחתני השיב ואמר אליו אני ה' פי' רחמן אני לזה לא יכולתי לסבול ראות ישראל בצער עד עת קץ והקדמתי לשולחך קודם הגעת הקץ להקל מעל ישראל הצרה של הגלות. ותשובה זו אינה צודקת אלא אחר שהקדים לומר לו עתה תראה כי תיכף ומיד יפליא פלא בפרעה מכות נפלאות ותיכף נסתלק השעבוד.
@125 **עוד** ירצה על דרך אומרם ז''ל (במד''ר פ''ג) בפסוק מוציא אסירים בכושרות בכי למצרים ושירות לישראל והם ב' מדות מדת הדין ומדת רחמים, ולזה אמר הכתוב כנגד מה שהכין לדון את המצריים אמר **וידבר אלהים** שהוא בחי' הדין, וכנגד מה שרצה להטיב לישראל אמר **ויאמר אליו אני ה'**. ובכלל זה רמז לו כי המכות הגדולות המוכנות לבא על המצריים הגם שיבואו דרך כלל על כל מצרים וישראל נתונים נתונים המה בתוכם ודבר ידוע כי אין המשחית מבחין ומחבל הכל ובפרט בבא החשך הדעת נותנת כי בודאי כי יחשיך דרך כלל לכל יושבי ארץ, לזה אמר כי ערך הדינים הרמוזים בשם אלהים אשר הכין ה' להשקות את המצריים תשמש מדת הרחמים לערך ישראל, והוא אומרו אני ה'. וכן הוא אומר (לקמן כג) ולכל בני ישראל היה אור, (ט ו) וממקנה ישראל לא מת וגו'.
@125 **עוד** ירצה על דרך אומרם ז''ל (ב''ר פל''ג) כי הרשעים מהפכים מדת הרחמים למדת הדין, והוא עצמו שאמר הכתוב כאן כי גם מדת הרחמים הסכימה לעשות דין במצרים, וזה הוא שיעור הכתוב **וידבר אלהים** שהוא כינוי לדין **ויאמר אליו** וגו' אני מודיעך כי מדת הדין זו היא משם הוי''ה שגם הרחמים נתהפכו עליהם לדין:
@125 **עוד** ירמוז גם כן כנגד ישראל על דרך אומרם ז''ל (שם) אשריהם הצדיקים שמהפכים מדת הדין למדת רחמים, והוא אומרו **וידבר אלהים ויאמר** וגו' פי' מדת הדין זו שאתה רואה נעשית רחמים המתכנת בשם הויה, ומזה יחליט משה בדעתו כי נחתם גזר דין רעת פרעה אפי' בהסכמת הרחמים ונחתם גזר דין טובת ישראל אפי' במדת הדין ובזה תחזקנה ידיו בשליחות:
@125 **עוד** ירצה להשיב על מה שטען משה למה לא קינא ה', ואמר אלהים אני, והוא אומרו **וידבר אלהים** פי' שדבר אליו כי הוא אלהים ומביא במשפט על הכל ואת פרעה ישפוט משפט שלם, וטעם שלא מיהר, ויאמר אליו אני ה' ושם זה יש בו מדות הרשומים י''ג מדות הרחמים ואחת מהם הוא ארך אפים שאינו ממהר לפרוע לרשעים בפועל כפיהם.
@125 **עוד** ירצה על זה הדרך **וידבר אלהים** ומדת דין זה באה כנגד השליח שהוא משה שדיבר לפני ה' שלא כדרך המוסר, אבל כנגד המשתלח אליהם שהם ישראל ויאמר אליו אני ה':
@125 **עוד** ירצה עז''ה **וידבר אלהים אל משה** ישב עליו בדין ויאמר אליו אני ה' פי' הגם שצריך לדון אותך אליך אני נוהג מדת הרחמים, והוא שדייק לומר אליו אני ה', והטעם על דרך אומרם ז''ל (ר''ה י''ז.) למי נושא עון למי שעובר על פשע, וידוע הוא כי משה עניו מאוד ומעביר על מדותיו יותר מכל הנבראים לזה נהג ה' עמו במדה זו ונשא עונו שהיה ראוי לבא עמו במשפט עליו, והוא אומרו אני ה' ורמז למדת נושא עון ואין כאן משפט אליו.
@125 **עוד** רמז ה' סוד אומרו ה' הוא האלהי' (מ''א יח), והוא אומרו וידבר אלהים ויאמר וגו' אני ה', וזה הוא גילוי יחוד ה' אשר גילה ה' סודו אל עבדו נביאו נאמן ביתו:
@126 **וארא אל אברהם וגו'**. טעם שהזכירם בפרטות, לצד שכל אחד יש בו בחינה מעולה, אל אברהם שנתעלה לצד שהוא אשר הכיר את בוראו תחלה מבלי שיקדים אליו דבר ממנו יתברך, כי הלא תמצא כל מי שקדם לו ידיעה מהבורא ממעשיו והנהגתו עם ברואיו אין לשבח אותו כשילך בדרך בחר לו יה כי כל משכיל יבחר בטוב ובפרט בטוב השלם והערב והמופלא הוא דרך ה', מה שאין כן אברהם כי דבק בה' קודם שיוכר אצלו מדותיו יתברך והנהגתו, וכבר כתבתי כי לאברהם למנה שיקראו לו (ישעי' מ''א) אוהבו של מקום פי' אהבת האמת אהבת הטוב כי הגם שעדיין לא הכיר ממנו אלא הנסיונות הגדולות. אף על פי כן דבק בה' ואהבו וכמו שכתבנו במקומו.
@126 **אל יצחק** שהיתה בו בחינה אחרת שפשט צוארו על גבי המזבח.
@126 **ואל יעקב** שהיה שלם שלא יצתה ממנו טיפה מאוסה כישמעאל ועשו, והכוונה בזה שלכל ג' הדרגות הצדיקים בחירי עולם לא נגליתי עליהם אלא באל שדי שהוא גילוי הדרגה למטה מהדרגת גלוי שנתגלה למשה שהוא בשם ה' כאומרו אני ה', והכוונה בזה להודיעו כי הוא כפוי בטובתו של מקום שכל כך החשיבו מהאבות והוא מדבר לפניו במיעוט דרך ארץ. והגם שמצינו שאמר בנבואת האבות גם כן (בראשית יח א) וירא אליו ה', מדבר ה' כאן אתה למד כי הכתוב שם יגיד שנגלה להם ה' אבל לא השיגו לדעת ולהכיר בחינה זו הנפלאה, והוא אומרו **ושמי ה' לא נודעתי להם** פי' שלא נתודעה להם בחינה זו העליונה **עוד** ירצה באומרו **ושמי ה' לא נודעתי** וגו' פי' הודעת יחוד ב' שמות יחד שהם שמי ה' שנודעתי לך כאומרו וידבר אלהים אני ה', והוא סוד אומרו (מ''א יח) ה' הוא האלהים, והוא סוד אומרו (זכרי' יד) ה' אחד ושמו אחד, לא נודעתי להם להאבות פי' סוד ב' שמות יחד, שמי, ה', שהם אלהים הוי''ה שהדין יעשה רחמים ורחמים יעשו משפט לא נודעתי והבן. ואמר לא נודעתי כי ה' ברוך הוא הוא שמו ושמו הוא, ואינו כשאר הנבראים שחלוקים משמם ושמם חלוק מהם אשר על כן לא יצדק לומר לא הודעתי כי השם הוא המדבר ואם כן צריך לומר **לא נודעתי**.
@126 **עוד** יתבאר אומרו **באל שדי ושמי** וגו' על דרך מה שפירשו בספר הזוה''ק (ח''ב כ''ג) בפסוק ואמרתם כה לחי כי מדת כה היא בחינת ההיכל שהוא שכינתו יתברך ויחודה הוא חי העולם וזה בחינת יחוד קטן, ואחר כך חזר לייחד יחוד עליון ואמר ואתה שלום רמז למקום גבוה שהוא תפארת ישראל הרמוז בוא''ו. ואולי כי הן הן הדברים הנאמרים כאן באומרו **באל שדי** שזה הוא בחינת חי אבל **ושמי ה'** שהוא יחוד העליון הרמוז בתיבת ואתה שגילה למשה באומרו **וידבר אלהים** וגו' **אני ה' לא נודעתי להם** וגו' והבן:
@126 **עוד** ירצה כי בא האדון ברוך הוא להשיב למשה על ששלחו קודם הקץ, ואמר כי הגם ששם קץ לחושך לצאת בני ישראל מארץ מצרים והקץ עדיין לא נשלם, יש לך לדעת כי הקץ שעשיתי להאבות הוא בחינת אל שדי ובו שמתי לגלות גבול ואמרתי לו די אבל בחינה אחרת לא נודעתי פי' לא אמרתי להם הקץ שיהיה באמצעות הרחמים אם יבקשו ויעוררו רחמים כמו שעשו ישראל שבקשו ממני רחמים וידפקו על דלתי הרחמים קודם הקץ לא נודעתי להם, ולכן הגם שלא שלמו ימי העינוי והצרה אף על פי כן רחמתי עליהם במדת הוי''ה, והוא אומרו בתחלה **אני ה'** והבן.
@126 **עוד** ירצה על זה הדרך **וארא אל אברהם** פי' איך אעלים רחמים מעם זה אשר הם בני בחוני שנגליתי על אבותם ולא לאחד בלבד אלא לשלשת האבות לכל אחד בזמנו, ולזה הפסיק ביניהם אל אברהם אל יצחק ואל יעקב ולא אמר אל אברהם ויצחק ויעקב וזה יגיד שבח כל אחד בפני עצמו באל שדי הוא חיבת גילוי שכינה. ואומרו **ושמי ה' לא נודעתי להם** פי' עדיין לא הודעתי מדת רחמי להם, שכל ההבטחות שהבטחתים עדיין לא הבאתי עליהם, ואני חפץ להודיע להם מדת רחמי כי להם יאותו. ונתכוין ה' בזה להודיע גודל חיבתם בעיניו:
@127 **וגם הקימותי וגו'**. לפי מה שפירשנו כי יודיענו אלהים אשר יפליא בינו ובין האבות, ירצה באומרו **וגם הקימותי** כאלו אמר והגם שהקימותי וגו', או וגם שהקימותי וגו', אף על פי כן לא השיגו להודיע להם שמי ה' כמו שהשגת אתה.
@127 **עוד** ירצה לומר כי דבר זה הוא דבר שה' ברוך הוא חייב לעשותו כביכול מלבד שנגלה עליהם באל שדי והבטיחם עוד לו שקיים עמהם שבועה וכו', ומעתה צריך לקיים שבועתו והדבר בהכרח להיות, ובזה תחזקנה ידיו של משה כשידע כי דבר זה אין לו מניעה מלהיות כן. והגם שכבר השיבו על מה שטען משה שהיה לו לעכב השליחות עד עת קץ והשיבו ויאמר לו **אני ה'** כי לא יוכל לסבול לכבוש את רחמיו, עדיין יש לחוש שיתעצל משה בגמר שליחות היציאה כשיראה כל חוזק לב פרעה או על הים ירתע לאחוריו, לזה הודיעו אל עליון כי הדברים הם עליו בתוקף השבועה לתת להם את הארץ:
@127 **את ארץ מגוריהם**. צריך לדעת למה לא הספיק במה שהזכיר שמה ארץ כנען וחזר ואמר את ארץ מגוריהם. ואולי שנתכוון לומר כי הגירות כבר התחיל מימי האבות, ונפקא מינה להתחיל המנין מזמן האבות וכמו שכן היה. אלא כי עדיין קשה שהיה לו לומר את ארץ כנען ארץ מגוריהם למה אמר את שנראה שהם ב' ארצות. ואולי שנתכוון להוסיף ארץ פלשתים וכמו שפירשתי בפסוק (בראשית כו ג) גור בארץ הזאת וגו' כי לך ולזרעך אתן וגו' יע ו '' ש:
@128 **וגם אני שמעתי וגו'**. אומרו **וגם** פי' מלבד שהתפללו למדת הרחמים ומלבד אהבת האבות ובריתם יש בחינה ג' שלצד צעקתם לבד מהשעבוד שמע ה' קול צעקתם מכאב לב. והוא אומרו **וגם אני**, ופי' אני הוא שם הרחמים שאמר בתחלה ויאמר אליו אני ה' מצד רחמי לבד שמעתי את נאקתם פי' צעקה מכאב לב כחלל הנואק מבלי צורך תפלתם, והוא שדייק לומר **אשר מצרים מעבידים אותם** פי' בחינת צער השעבוד שמצרים מעבידים אותם הוא ששמעתי. ועיין מה שפירשתי בפסוק (לעיל ב כג) ותעל שועתם אל האלהים מן העבודה. גם יתיישב לפי שאר הדרכים שכתבנו והמשכיל יבין:
@128 **ואזכור את בריתי**. פי' גם כן לגואלם לתת להם את הארץ, והיא הברית הרשומה בסמוך, ואני מקדים בזמן זה לצד הרחמים כמו שכתבנו למעלה. והאומר שהברית היא ליפרע מן הגוי העובד לא הוזכרה ברית זו בסמוך ודוחק להרחיק הדברים:
@129 **לכן אמור לבני ישראל אני ה'**. פי' הודיעם משמי כי מדתי מדת רחמים וריחמתי עליהם, ומלבד הודעה זו תאמר להם סדר הטובות אשר אעשה להם **והוצאתי** וגו'. עוד ירצה באומרו **לכן** לשון שבועה שנשבע ה' לעשות כל האמור בענין, וכן תמצא שאמר יחזקאל סימן כ' ביום ההוא נשאתי ידי להם להוציאם מארץ מצרים, ואומרו **והוצאתי** וגו' נתכוון לסדר סדר הטובות, כי בתחלה יקל עול סבולם, והוא אומרו **והוצאתי אתכם מתחת סבלות מצרים** שהוא תוקף השעבוד, וזה היה תכף ומיד במכת היאור נתפרדה חבילת נוגשים ושוטרים אבל ישראל היו עובדים קצת כי אימת המצריים היתה עליהם ומעצמם. היו עובדים עבודה קלה. וכנגד זה אמר **והצלתי אתכם מעבודתם** שתעקר עבודה מהם כל עיקר, ואחר כך **וגאלתי אתכם** היא יציאתם מארץ מצרים ובכלל פרט זה היא קריעת ים סוף שאם לא כן זו גאולה שאחריה כלייה ב''מ, ולזה לא אמר והוצאתי אתכם מן הארץ אלא וגאלתי לומר הוצאה שיש כה גאולה אם ירדוף אויב ירדוף באף ובחמה שפוכה. ואחר כך **ולקחתי אתכם לי לעם** שהוא מתן תורה כי שם נתייחדנו לו לעם וייחד שמו עלינו והוא אומרו **והייתי לכם לאלהים**.
@129 **או** ירצה על דרך אומרם ז''ל (ברכות ז) בפסוק ונפלינו אני ועמך וגו' כי בקש משה ע''ה מה' שלא ישרה שכינתו על אומות העולם והשיבו אל עליון גם את הדבר וגו' אעשה ע''כ, וכנגד זמן זה אמר **והייתי לכם** וגו' ולא לאומות העולם שלא ישרה שכינתו עליהם.
@129 **עוד** ירצה על דרך אומרם ז''ל (שמו''ר פ''ו) כי ד' גאולות נאמרו בפסוק זה, ואולי כי הם רמוזים בשם הוי''ה שאמר ה' פתח דבריו **אמור לבני ישראל אני ה'** ולצד זה שם הפועל יפעל ד' מיני גאולות. ולפי זה ידוייק אומרו **והייתי לכם לאלהים** על גאולה הבאה בחינת ה''א אחרונה כי תקרא שם אלהים כידוע לאנשי אמת. ואולי כי לזה נתכוון באומרו אחר שסדר ד' לשונות של גאולה וידעתם כי אני שם הוי''ה פי' וזה לך האות ד' גאולות:
@130 ו **ידעתם וגו'**. פי' עכשיו יש לכם לדעת ידיעה ברורה.
@130 **כי אני ה' אלהיכם** הוא **המוציא אתכם מתחת סבלות מצרים** פי' לתת עליכם סבלות אלהותי. עוד ירצה לומר להם שישגיחו להכיר מדות אלהיכם כי אל רחום ה' אלהיכם:
@131 **והבאתי וגו'**. קשה כי דברי אל עליון דברו טהור הוא כי יוצאי מצרים הם הנכנסים לארץ דכתיב והבאתי אתכם אל הארץ ולא מצינו שכן היה אלא ואת בניהם הביא שמה אבל כל דור יוצאי מצרים מבן עשרים שנה נפלו פגריהם במדבר, ותגדל הקושיא למה שאמרנו שנשבע ה' על כל הדברים באומרו לכן ואמרו ז''ל (שמו''ר פ''ו) אין לכן אלא לשון שבועה. ונראה כי מקור החכמה נתחכם על קושיא זו וקודם אומרו **והבאתי אתכם** וגו' אמר **וידעתם כי אני ה' המוציא** וגו' פי' תנאי הוא הדבר ובזה והבאתי וגו' וזולת זה אם תנאצו ה' אין כאן הבטחה זו, ואשר על כן כתב פרט זה של ידיעת ה' וגו' באמצע הבטחות הטובות ולא איחר ולא הקדים לומר עד כאן הוא בשבועה בלא תנאי אבל פרט זה של הבאתם לארץ תנאי הוא הדבר וידעתם וגו' אז הבאתי וזולת זה יהיה מה שיהיה:
@132 **מקצר רוח**. אולי כי לצד שלא היו בני תורה לא שמעו, ולזה יקרא **קוצר רוח** כי התורה מרחבת לבו של אדם:
@132 **ומעבודה קשה**. טעם אומרו **ומעבודה** זה יגיד כי מלבד צער העבודה עוד היה להם קוצר רוח, והטעם בראותם כמה כבדה עליהם המלאכה קצרה נפשם מלבד פרט צער העבודה, וגם מדרך האיש אשר תקצר נפשו לא יוכל עבוד כי יחלש למכאובו ורעים הם השנים אשר על כן אמר **ומעבודה** כי קצרה רוחם וגם כבדה עבודתם.
@132 **עוד** למה שנתבשרו ישראל בשורת הגאולה נתרחב לבבם ותחי נפשם ורוחם וכשחזרו לשעבוד הגם שלא היו משתעבדים אלא שיעור הרגיל ולמטה ממנו אף על פי כן תקצר רוח, והמשכיל בטבעיות הרכבת האנושי ישכיל על דבר. ומודיע עוד הכתוב שגם הכבידו עולם עליהם יותר מהרגיל והוא אומרו **ומעבודה** וגו'.
@133 (י~יא) **לאמר בא דבר וגו'**. אומרו **לאמר** פי' שיאמר אליו כי הוא אמר לו בא דבר, ואומרו **וישלח** בתוספת וא''ו הגם שלא קדם לו דבר, לצד ששליחות משה לדבר לפרעה הוא ענין גדול לדבר הדיוט לפני מלך ועוד לו שידבר אליו דברים הנוקבים לבו להוציא בולעו מפיו.
@133 **עוד** ירצה לומר אליו כי לא מלבד שאם יצאו מעצמן לא יעכב על ידם אלא שצריך הוא בעצמו לשלחם ג''כ ויאמר להם קומו צאו. עוד ירצה שמבטיחו שידבר ובודאי שישלח וגו' לבסוף:
@135 **לפני ה' לאמר הן וגו'**. קשה אומרו **לאמר** כי למי יאמר ה' דברי משה. ואולי שיכוין הכתוב לומר כי לא השיב משה תשובה זו לבל ילך בשליחות זה אלא כמי שמתלונן על עצמו שלא הצליח, והוא אומרו תיבת **לאמר** פי' שאין תכלית הדיבור אלא האמירה לא תכלית זולתה שהיא מניעת השליחות והבן.
@135 **עוד** ירצה כי כוונת דבריו הם לומר אמירה אחרת והיא מובנת מהדיבור מאומרו הן בני וגו' ואני ערל שפתים, ר''ל בזה כי יהיה ה' רופאהו, ועיין בפסוק הן בני וגו':
@135 **הן בני ישראל וגו'**. קל וחומר זה יצדק לפי מה שפירשתי בפסוק מקוצר רוח שהם דברי תורה ישפוט בצדק משה קל וחומר כי לא חשב כי זה גורם. ואם נאמר כי משה גם כן ידע כי טעם שלא שמעו הוא לצד קוצר רוח יהיה הקל וחומר מופרך. ואולי כי ישפוט קל וחומר על זה הדרך שהגם כי בני ישראל הם בקוצר רוח יש בהם גם כן ב' בחינות, הא' שהם בעלי אמונה ומכירים מלכות שמים, והב' שהבשורה היא בשורה טובה ועצומה וב' אלו אינם בפרעה כי הוא כפר בעיקר ואמר מי ה' ח''ו וגם דברים המכהים את עיניו והנוקבים את לבו, ואם כן ק''ו נכון הוא ומה בני ישראל שיש בהם ב' מדות הנזכרים לא הטה ה' לבבם לשמוע ולא שמעו מצד טעם כל שהוא שיש להם קוצר רוח ואיך ישמע פרעה שיש לו ב' סיבות מונעות ממנו השמיעה שאינו מאמין כל עיקר והם דברים שחונקים אותו פשיטא שלא ישמע הגם שאינו קצור רוח, שקוצר רוח של פרעה בדברי משה וגם בדברי המשלח הוא יותר מקצרות רוח של ישראל, ואלו היה כח בדברי משה להכריח לפרעה לשמוע אליו מכל שכן שהיו בני ישראל שומעים אליו הגם היותם בקוצר רוח, והוא אומרו **לאמר הן** וגו' פי' הגם שיש להקשות מה לבני ישראל וכו' הלא יש גם. כן לאמר להכריע הבנייא ההוא כנזכר. ואומרו **ואני ערל** וגו' פי' ועוד בה עצרייה כי הוא ערל שפתים ויאמר פרעה אם אלהי העברים שליט וכל יכול למה לא ריפא את משה, ובערך ענין זה גם כן ישתנה פרעה מישראל להיותו חסר האמונה בכל שהוא ינסה להרחיק האמונה ולהכזיבה ח''ו.
@135 **עוד** ירצה לצד שדקדק ה' בדבריו שאמר לו בפרשת שמות (ד טז) על אהרן ודבר הוא לך אל העם מכאן אתה למד כי אין אהרן לו לפה אלא אל העם ולא לפרעה, וכן תמצא שאמר הכתוב (שם ל') בשליחות ראשונה אל העם וידבר אהרן את כל הדברים אשר דבר ה' אל משה ובדברם לפרעה אמר (ה' א') ויאמרו אל פרעה מוכח כי משה ידבר, וטעם אומרו ויאמרו לשון רבים כן משפט כל שנים שאחד מדבר ואחד מסכים יחשבו כי שניהם דברו, ואם תאמר כלך לדרך זה אהרן דבר ומשה הסכים. ממה שראינו שדקדק הכתוב לומר בדיבור אל העם וידבר אהרן בדיוק גם בדברי ה' מצינו שלא אמר אלא ודבר הוא לך אל העם, זה יגיד כי הדברים יצדיקו לנו, וכפי זה הכרעת צד ק''ו הוא אומרו ואני ערל שפתים, כי בחינה זו אינה אלא בפרעה כי משה ידבר מה שאין כן אל העם כי אהרן הוא המדבר. ואולי כי לזה דקדק לומר בערך ישראל תיבת **אלי** ובערך פרעה אמר **ישמעני** כי ישראל אינם שומעים מפיו ממש אלא מפי אהרן אבל פרעה היה שומע ממשה עצמו. ושמור לך פרט זה להבין אמרי קדוש בסמוך:
@136 **וידבר ה' וגו** '. צריך לדעת מה דבר ה' להם. עוד צריך לדעת כוונת אומרו **ויצוום אל** וגו'.
@136 ורז''ל (שמו''ר פ''ז) דרשו שינהג ישראל בנחת וגם שינהגו כבוד במלכות, וזה דרך דרש. עוד קשה היכן תשובת אל עליון לדברי שלוחו, ומה גם שטען טענה הנשמעת, ולו יהיה שטעה וק''ו אינו ק''ו, היה לו לסתור דבריו, והגם שנוכל לומר כי העדר התשובה היא ההכחשה בק''ו כי איננו נכון, עם כל זה במה שלפנינו אין אנו יכולין לומר כן, בהעיר הערה אחת בכתוב שאחר זה וידבר ה' וגו' אם נאמר שמה שאמר משה הן בני ישראל לא חש להשיבו אל עליון אם כן למה לא רצה ה' לדבר הדברים הנאמרים בפסוק וידבר וגו' גם הצוואה הלז שאמר ויצוום עד אחר דבר משה לפניו הן בני ישראל.
@136 **אכן** הנכון בעיני כי בא להשיבו על טענתו שלא החשיבוהו ישראל לשמוע דבריו ועוד לו כי לצד פרעה כי משה ידבר יש לו גרעון ופחיתות לצד היותו ערל שפתים כמו שפירשתי, ובאה התשובה על זה **וידבר ה' אל משה ואל אהרן** פי' השוה אותם בשליחות ובזה ידבר אהרן גם לפרעה כי שניהם שוים בדבר, ולצד שלא יהיו נחשבים לשמוע להם אמר **ויצום** פי' המליכם על בני ישראל ועל פרעה על דרך (ש''א יג) ויצוהו ה' לנגיד ומעתה הנה מוראם על ישראל ועל פרעה ואמר **להוציא** וגו' פי' לסיבת פרט זה הקנה להם ה' בחינת המלכות על ישראל לבל ימאנו לצאת ועל פרעה לבל יעכב על ידם. ומכאן אתה למד שיש רשות למשה ולאהרן לרדות באיש ישראל הממאן לצאת. ואולי כי לזה נתכוון משה באומרו בני ישראל לא שמעו אלי פי' לא רצו לצאת כי אמרו ינוח לנו בן עמרם במקומנו לזה המליך ה' את האחים למלכים עליהם כנזכר, ומעתה פרחה לה טענת הן בני ישראל וגו' כי מעתה והלאה מורא מלכות עליהם ועל פרעה וידבר משה אליו כדבר אל עבדו וכמו שכן היה, ובזה נתישבו הדברים על נכון:
@137 **אלה ראשי וגו'**. טעם שהעלה מספר בני ישראל עד משה, לפי מה שפירשתי בסמוך שהמליכם על ישראל יחס אותם הכתוב לומר כי אין מעמידין על ישראל אלא המיוחס עד יעקב, ולזה לא יחם אותם הכתוב קודם אלא אחר מאמר משה הן בני ישראל ותשובת ה' אליו ויצום שהמליך אותם ונכון:
@149 **הוא אהרן ומשה**. פי' המיוחסים בפרשה, הם **אשר אמר ה' להם הוציאו** פי' לצד שיש בידם יכולת להוציא שהם מלכי פרעה מלך מצרים ובני ישראל כמו שפי' בפסוק ויצום, לזה **אמר ה' להם הוציאו את בני ישראל מארץ מצרים** וכל הממאן יכוהו בשבט מוסר אשר הכין ה' לגו כסילים.
@150 ואומרו **הם המדברים**, פי' כמלך. הגוזר על עבדו בדבר שפתים לעשות דבר. עוד יכוין להודיע שהגם שתמצא שאמר הכתוב שידבר משה תדע כי גם אהרן דיבר כאשר אבאר בפסוק ויהי ביום דבר ה':
@150 **הוא משה ואהרן**. פי' ששקולים הם, ולזה פעם יקדים משה ופעם יקדים אהרן, ומעתה יכול לומר על שניהם לשון יחיד הוא משה ואהרן. ואולי כי טעם שאמר בסמוך לשון רבים הם המדברים לצד שבדיבור ישתנו:
@151 **ויהי ביום דבר ה' וגו** '. פי' מה שאתה רואה כי שוה אהרן למשה בכל פרטי דבר זה היה לצד **כי ביום אשר דבר** וגו' **בארץ מצרים** פי' לשלול דיבור ראשון שהיה במדבר שאמר לו ה' (לעיל ד' יד) הלא אהרן אחיך וגו', כי שם עדיין לא השוה הכתוב אהרן למשה בשליחות מצוה זו עד שדיבר ה' עם משה בארץ מצרים, והוא אומרו **ביום דבר** וגו' **בארץ מצרים**, וחזר הכתוב לומר אופן הדיבור שדבר ה' עם משה בארץ מצרים, והוא. אומרו **וידבר ה' אל משה לאמר אני ה' דבר אל פרעה** וגו' פי' לאמר שדקדק לומר, לו אני ה', והכוונה בזה שתסתמוך על דברי, ותלך בשליחותי ותדבר אתה בעצמך אל פרעה כל אשר וגו', ותמצא שדיבור זה של אני ה' היה בארץ מצרים דכתיב (ריש משה זו) ויאמר אליו אני ה' זה היה במצרים ואמר לו שילך הוא וידבר אל פרעה לא אהרן, והגם שכבר שתף ה' עמו אהרן הנה ביארתי היטב שם במקומו שאהרן ידבר אל העם אבל, לפרעה עדיין ה' חפץ שידבר משה וריצה אותו באומרו **אני ה'** ולא תחוש לשום דבר ולא רצה משה לעשות כן וחזר וטען **הן אני ערל שפתים ואיך ישמעני פרעה**, הנה דקדק הכתוב לומר שטענת ערל שפתים היתה לצד פרעה לצד שאהרן אינו מדבר עד עתה אלא לעם וכמו שכתבנו, אז אמר ה' למשה **ראה** וגו' **ואהרן אחיך ידבר אל פרעה** פי' גם לפרעה מלבד העם, ומעתה הושוו אהרן ומשה במצוה זו, ולזה תמצא שלא אמר ה' למשה במדבר כששתף עמו אהרן את כל ההכנות האלו האמורים כאן והיה לך לאות כי הם דברים חדשים כנזכר מטעם האמור:
@151 **והנה** הראנו ה' כי הקפיד ה' על הדבר שלא עשאו משה שכל כך השתדל ה' עם משה לעשות הוא הכל. ואולי כי לזה אמר הכתוב **ויהי** לשון צער כי הענין יגיד כי יתרון, גדול היה אם עשה משה הכל, והראיה מהשתדלות ה' עמו, וכפי זה אמר ויהי על חסרון היתרון.
@151 **ואפשר** כי לזה נתכוין מסדר הפרשיות לכתוב פסוק זה **ויהי** ביום בפרשה שקדמה וכפי האמת נקשר הוא עם מה שלמטה כמו שפירשנו, אלא נתכוון לומר כי. הצער הרמוז בתיבת ויהי היא על עשות המצוה בשניהם יחד. ואולי אם היה משה עושה מצוה זו לבדו היה מתחזק כוחו והיה נכנס לארץ ולא היו עוברים הרפתקי על ישראל במדבר, גם אם היה נכנס לארץ היה בונה בית הבחירה והיה עומד כל הימים. או אפשר שבשביל חסרון משה אמר לשון צער.
@151 **עוד** יכוין מהפסיק הסדר לומר כי כל האמור הם אשר אמר ה' וגו' הם המדברים וגו' שהם שוים במצוה שניהם יחד זה היה ביום דבר ה' בארץ מצרים וגו', אבל קודם לכן הגם שאמר ה' הלא אהרן וגו' לא היו שוים במצוה כי משה הוא היה עושה כל השליחות לפרעה מה שאין כן עתה שאהרן לבד הוא ידבר אל פרעה כאומרו **יהיה נביאך** וגו' **ידבר אל פרעה**:
@157 **ולא ישמע**. קשה אחר שאמר ואני אקשה מה מקום לומר ולא ישמע. עוד צריך לדעת מה נתינת יד זו חדשה שאינה בכלל אותות ומופתים האמורים למעלה בהקשאת לבו. עוד יש לדקדק בכתוב.
@157 **אכן** כוונת הכתוב הוא בתחלה אמר **ואני אקשה** וגו' והרביתי ומודיע עוד שאחר שירבה מופתים יוסיף פרעה הרשע על חטאתו פשע ולא ירצה לשמוע השליחות עוד מכם כשאשלח אתכם אליו, וכן היה דכתיב (לקמן י כח) אל תוסף ראות פני וגו', ומודיע ה' למשה כי בעשותו כן אז הוא גבולו כי תכף ומיד יתן ה' ידו פי' מכת בכורות על דרך אומרו (דה''א כא) וחרבו שלופה בידו. ואמר בכינוי אליו **את ידי** לומר כי מכה זו יעשנה ה' בידו ממש כביכול כאומרם ז''ל (מכילתא בא) אני ולא מלאך ולא שרף ולא שליח אלא הקב''ה בכבודו וכו', ובאמצעות מכה זו תיכף ומיד אוציא את צבאותי. ורמז גם כן על מה שעשה באלהיהם שפטים גדולים במכת בכורות כידוע:
@157 **ובזה** נחה דעתי במאמר משה שם כשאמר לו פרעה אל תוסף וגו' השיבו כן דברת לא אוסיף וגו', וקשה על משה רבינו על מי סמך לומר לא אוסיף וגו' ואם יאמר לו אלהינו לך אל פרעה פעם אחרת מה יענה, ולפי מה שפירשנו טעמו לשבח כי ה' אמר אליו כי כשיגיע למדרגת מיאון שמיעת דבריהם זה הוא סוף גזירתו לנטות ה' ידו וגו' ולהוציא לזה כשאמר לו אל תוסף וגו' הרי שלל השמיעה שלא ישמע עוד מהם דבר קטן וגדול ואפי' ראות פניהם אסר על עצמו לזה תכף אמר אליו כן דברת לא אוסיף וגו', אלא עוד תשמענה אזנך דבר עתה וגו', ודבר זה של מכת בכורות כבר הודיעהו ה' וכמו שפירשתי בפרשת שמות בפסוק (ד כב) כה אמר ה' בני בכורי ישראל דרשו משם:
@157 **והוצאתי את צבאותי את עמי וגו** '. צריך לדעת מי הם הצבאות, ואם הם ישראל היה לו לומר את צבאות עמי בני ישראל. ואולי כי יכוין ה' לרשום בתורה הפלגת מעלתינו אצלו כי אין לו צבאות מיוחדים לו כישראל, ולזה אם היה אומר את צבאות עמי וגו' היה מקום לומר כי ה' יש לו הרבה צבאי צבאות וזה אחד מהם, לזה אמר **את צבאותי** סתם לומר הרשומים ואין צורך לומר צבא פלוני כי באומרך צבאות ה' אחד הוא המיוחד, ואחר כך אמר מי הוא זה ואיזה הוא את **עמי בני ישראל**, ויתבאר הכתוב על דרך כלל ופרט אין בכלל צבאותי אלא הפרט שהם בני ישראל, ומעתה לא יקרא בכינוי צבאות ה' אלא ישראל המרוממים והמעולים:
@159 **ויעש משה וגו' כן עשו**. צל''ד למה כפל לומר **כאשר צוה** וגו' כן עשו ולא הספיק הכתוב באחת מהנה. ונראה שיכוין לומר שעשו השליחות כאשר אמר להם ה' בב' הדרגות, האחת שכל מה שהשיגו הבין בדברי ה' כן עשו, והב' שנתכוונו אל אמיתות הדברים בשלימות, וזה הוא שיעור הכתוב ויעש משה וגו' כאשר צוה וגו' ולא שינו דבר, וחוזר הכתוב ומעיד ואומרו **כאשר צוה ה' אותם** פי' מה שנתכוון ה' במצותו להם כן עשו והבן.
@159 **עוד** ירצה לומר כי כל מעשה משה ואהרן לא היתה לסיבת אמצעות שום דבר אלא כאשר צוה אותם ה', והוא על דרך אומרו (דברים ו') וצדקה תהיה לנו וגו' כאשר ציונו, ואומרו **כן עשו** הוא על גוף המעשה שלא היה בשום שינוי:
@159 **עוד** ירצה שעל כל דיבור ודיבור היו מזכירין שם שמים והוא אומרו **עשו** ובשעת מעשה אמרו כאשר וגו'. עוד ירצה לומר שלא היו מתעכבים בדבר אלא תכף ומיד בכלותו לצוות אותם ה' היו נחפזים לעשות דבר ה':
@160 **בדברם אל פרעה**. אולי כי ביום ראשון שדברו היו כן וגו' ולא אחר כן, ושיעור תיבת **בדברם** בהתחלת דברם:
@161 (ח ט) **לאמר כי ידבר אליכם וגו'**. טעם אומרו **לאמר** שנתן להם רשות לומר כי על פי ה' הם עושים האותות, שזולת זה יהיה אסור להם להודיע דבר זה הגם שישאלם, וכאומרם ז''ל (יומא ד:) שהוא בבל תאמר עד שאמר לו לאמר, ודוקא אם ישאל פרעה או אם ירצו הם לומר אליו אבל אין חיוב בדבר עד שיאמר לאמר דבר אחת רשות ואחת לחובה. עוד ירצה על פי דבריהם ז''ל (תו''כ א') כי כל מקום שנאמר למשה ולאהרן אינו אלא למשה שיאמר לאהרן, והוא עצמו שרמז באומרו **לאמר** פי' כי מה שאתה רואה אל משה ואל אהרן לא שהדיבור היה לשניהם אלא לאמר פי' למשה שיאמר לאהרן. וטעם השוואתם בדיבור לצד ששקולים הם במצוה זו כי אהרן ידבר אל פרעה כמו שכתבנו למעלה:
@161 **פרעה לאמר תנו וגו'**. כוונת אומרו **לאמר** לבל יצטרכו עד שיאמר פרעה בפירוש תנו לכם מופת ואז הוא שתעשו האמור בענין אלא כל שיאמר דיבור שהמכוון הוא שצריך הוא לאות ולמופת או שראיתם שהוא מפקפק בדבר ומכחיש לומר מי יאמר כדבריכם הגם שלא אמר תנו וגו' אף על פי כן אמור אל אהרן קח מטך וגו':
@163 **ויעשו כן כאשר צוה וג'**. טעם כפל לומר כן כאשר וגו' ולא הספיק לו באחת מהנה, נתכוין לב' דברים, האחד שעשו הדברים כן, והשני שלא עשו עד אשר שאל מהם פרעה האות כאשר צוה ה':
@163 **עוד** ירצה להיות כי האות יגיד על חיזוק נבואתם כדי שיאמנו העיד הכתוב עליהם כי לא עשו הדבר לצד דבר זה אלא לעשות מצות ה'. והוא אומרו **כאשר צוה ה** כי יותר חביב על הצדיקים עשות מצות ה' מכל רצון בעולם:
@167 **ויאמר ה'** וגו' **כבד וגו'**. צריך לדעת מה מודיע בדבר זה האלהים אחר שהם יודעים אותו. ואולי כי לא היה תשובה בפירוש מפרעה על זה למשה שלא ישלח אלא ראה האות ושתק, והודיע ה' למשה מה זו שתיקה כי כבד לבו ומאן לשלח את העם ולא חש להשיב שלילת הדבר:
@169 **ואמרת אליו ה' וגו' שלחני וגו'**. כל הכתוב מיותר ולא היה לו לומר אלא פסוק שאחריו כה אמר ה' וגו'. ואם לומר כי הוא שלחו זה אינו צריך כי ידוע הוא, ואולי כי להיות שבא אליו והוא הולך לעשות צרכיו בבקר השכם ויאמר פרעה שאין זה מהלכות דרך ארץ שהיה לו להמתין עד עת שיהיה יושב בפלטין שלו ויאמר אליו השליחות, לזה צוה ה' לתת לו טעם בתחילת דבריו ויאמר אליו ה' **שלחני אליך** ודבר מלך עלי לבא בעת זו. גם לצד שהוא אלוה עליון צריך לעשות שליחותו תיכף ומיד:
@169 **עוד** ירצה על דרך אומרם ז''ל (שמו''ר פ''ח) בפסוק (יחזקאל כט) לי יאורי ואני עשיתני שהיה עושה עצמו אלוה והיה מטעה עמו לומר כי הוא מכנים ואינו מוציא והיה יוצא בהשכמה דרך נסתר מכל חי והיה עושה צרכיו ביאור, לזה באה השליחות מה' למקום גנובתו ומסתורו מכל חי ואמר אליו תחילת דבריו ה' **אלהי העברים** הוא **שלחני אליך** פי' הודיעני מקום אתה בו, והרי לך אות כי ה' אלהינו יודע אם יסתר איש במסתרים, גם בזה נבאש כי גילה ה' קלונו לעבדיו כי כבולעו כך פולטו ושקר בימינו והנה הוא כאשר יבער הגלל (מ''א י''ד). ואומרו **והנה לא שמעת עד כה** פי' מודיעו כי ה' יודע מחשבות והגם שעדיין לא השיב פרעה תשובה למשה על הדבר כמו שפירשתי בפסוק כבד לב פרעה אף על פי כן ה' יודע כי לא שמע עד כה.
@169 **עוד** ירצה לצד שקדמה שליחות משה ועשה אות מטה שנהפך לנחש ולא היתה לו מכה כשלא שמע ע''י שליחות זו וכשבא להכות מכה ראשונה של דם אמר אליו כי כבר אמד לו השליחות על מה הוא מביא עליו הרעה, וזה שיעור הכתוב ה' **אלהי העברים** כבר **שלחני אליך** ודברתי לך והנה לא שמעת אשר על כן **כה אמר ה'** וגו' באופן כי אינו צריך לומר לו עוד פעם אחרת כה אמר ה' שלח עמי וגו' שכבר אמר לו הדבר:
@170 **בזאת תדע כי אני ה'**. טעם שציין לו ידיעת ה' באמצעות מכה זו על דרך אומרם ז''ל (שמו''ר פ''ט) כי נילוס היה למצרים לאלוה אשר על כן רשם ה' בהכאת היאור לדם ואמר בזאת תדע כי אני ה' כשאעשה משפט כתוב באלהיכם, ודקדק לומר **אני ה'** כי שם זה מלבד שאמרו ז''ל (זהר ח''ג רצ''ז) שירצה לומר היה הווה ויהיה. עוד ירצה לומר כי במאמרו היה כל הווה. והנה כשיכה עבדו ליאור יראה כי הוא יתברך הוא שעשה היאור הוא מהוהו בכל עת לאשר יחפוץ והנה הוא עושה בו הויה אחרת והפכו לדם:
@170 **עוד** רמז לו כי מזה ידע מדת רחמיו יתברך על הנבראים בראות לפניך היאור נהפך לדם כדי שתשוב ותשלח ולא תמות, ואם לא היה צד הרחמים היה מכה בו ומאבדו מן העולם וק''ו הדברים ומה יאור גדול מהפכו לדם אדם אמגושי כמותו לא כל שכן, והוא אומרו **בזאת תדע כי אני ה'** שאני מתחכם עליך בדברים גדולים כזו של הכאת אלהיך כדי שתאמין ולא תאבד:
@173 **ויעשו כן משה ואהרן כאשר וגו** '. פי' כשעשו משה ואהרן מעשה הכאת היאור, נעשית הפעולה ונתקיים הרצון כאילו היתה מצות ה' מפיו ברוך הוא ליאור שיהפך לדם, ועיין מה שפירשתי עוד בפסוק (ו) ויעש משה וגו' הקודם לזה ועיין בפסוק שאחר זה:
@173 **לעיני פרעה ולעיני עבדיו**. הגם כי תחילת דבריו היה עם פרעה בייחוד בעת הסתרתו לעשות צרכיו לפי דבריהם ז''ל (שמו''ר פ''ט), ומן הסתם הוא לבדו יהיה שם, אף על פי כן מודיעך הכתוב כי נתעכב מהכות עד שהכה בפרסום לעיני עבדיו. והגם כי במצות ה' לא דקדק לומר פרט זה מן הסתם כן דבר ה' אליו, ואולי כי לזה נתכוון הכתוב כאומרו **כן כאשר צוה** פי' כן כדברים הנאמרים בדברי ה' וכנגד פרטים אשר תראה במעשיהם שאין כתובים כן בדבר האלהים מעיד הכתוב עליהם כי הם כאשר צוה ה' ונכון:
@174 **והדגה וגו' מתה**. הכונה בזה לומר כי היה להם סימן במעשה זה כי לא היה מעשה שדים ולא מעשה כשפים כי מעשה שנים אלו יהיו דמיון ולא ממש והדמיון יהיה לעין הרואים לא שיהיה ממש דם שיהרוג כל שותיו ואפי' דגים, לזה אמר **והדגה** וגו' **מתה ויבאש היאור**, וזה יהיה להם לאות עולם כי מעשה אלהים המה פעולה צודקת ולא דמיון. עוד אמר **ויהי הדם בכל ארץ מצרים** וגו' כי אפי' במרחצאות ובאמבטאות. ואולי כי ירצה עוד לומר שהדם ההוא שנעשה מהמים הגם שהיו נוטלים אותו ממקום זה ונותנים אותו במקום אחר וחוזרים וכו' וכל דבר שיהיה ממעשה שדים יבטלהו שינוי מקום ובפרט כשיניחוהו בארץ כידוע (זהר ח''ב קצ''ב) ומה שלפנינו היה הדם בהויתו בכל ארץ מצרים:
@175 **ויעשו כן חרטומי וגו'**. לפי דבריהם ז''ל (שמו''ר פ''ט) שהיו כל מימות מצרים לדם. אם כן מנין מצאו מים להפכו לדם ואולי כי לא נהפכו אלא מים המגולים אבל מים שלא נראו בעולם שהם תחת לארץ לא נהפכו כאומרו ויחפרו מצרים סביבות וגו'. עוד לפי דבריהם ז''ל (שם) כי ישראל נתעשרו ממכת היאור שהיו מוכרים מים למצרים וכו' יעויין שם דבריהם, כפי זה עשו החרטומים מהנמכר להם. וכבר אמרנו שהכתוב רשם שינוי המעשה שנעשה מה' כי ישתנה ממעשי כשפים ושדים, אלא כי לצד קושיות ערפם של המצרים לא בחנו במעשה כשפיהם לדעת כי אינם אלא חזיון ודמיון כוזב:
@176 **ויפן וגו' ולא שת לבו וגו'**. לא שהשיב שאינו חפץ לשלח, וכוונת הרשע כדי שלא יתחייב עונש על המיאון ויביא עליו עוד מכה אחרת. וטעם שלא שת לבו ולא שאל ממשה שיבקש עליו רחמים נבאר בסמוך (לקמן ח' ד') בעז''ה:
@178 **וימלא שבעת ימים**. פי' מלאו שיעור המוגבל למכה, ואחרי ששלמו שבעת ימים אחרי הכות וגו' ויאמר ה'. וכוונת הכתוב בהודעה זו היא כי לא נתרגש פרעה במכה זו לבקש ממשה להתפלל אל ה' ונשארה המכה עד גבולה, והוא אומרו **וימלא** וגו' אחרי שהכה ה' ושלמו ומלאו ימי המכה, וזה לדעת מרבותינו ז''ל (שמו''ר פ''ט) שאמרו כי כ''ד ימים היה מתרה בהם עד שלא באה המכה וז' ימים היתה המכה משמשת בהם, אבל להאומר כי שבעה ימים היה מתרה בהם וכ''ד ימים היתה המכה משמשת בהם, היו שבעת ימים של ההתראה, וממילא הנשאר מהחודש היתה משמשת המכה בהם. אלא שקשה לסברתו ממכת חשך, ואולי זו יצתה מהכלל, ואפשר שגם היאור מכתו יצתה מהכלל, ויודה מאן דאמר עשרים וארבעה ימים היתה משמשת המכה שהיאור לא ארכה מכתו, ויתכוונו שניהם יחד במשמעות הכתוב שאמר שבעת ימים אחרי הכות שלא הוכה אלא שבעת ימים כמשפט מכת חשך שלא היתה יותר משבעה. וסובר אני שהגם שהיה גבול למכה היתה מסתלקת אם היה משה מתפלל קודם הזמן ההוא:
@180 **ואם מאן אתה**. צריך ההתראה סמוך למכה:
@186 **העתירו אל ה'**. צריך לדעת למה לא פנה ובא אל ביתו במכה זו כמו שעשה במכת הדם הלא גם את זאת הראוהו חרטומיו כי עשו גם המה. אכן פיו ענה בו טעם הרגשתו בזו וכל כיוצא בה שהורגש וקרא למשה להתפלל בעדו, כי לא היה מתפעל אלא כשאימות מות נפלו עליו, וזה סדר מכותיו, ראשונה מכת דם לא היה לו בה סכנת מות, ומים לצמאו מצאו לו סביבות היאור או היה קונה מישראל לזה לא נרגש ממנה:
@186 **ב)** מכת צפרדע היו בו שני דברים הא' הרעשת הקול והשני שהיו נכנסים במעיהם דכתיב (לעיל ז' כט) ובכה ובעמך יעלו הצפרדעים, ומכה זו מבהלת הנפש ואין אדם בטוח בחייו, לזה אמר פרעה אל משה וגו' **ויסר הצפרדעים ממני** פי' מתוך בני מעיו וגו';
@186 **ג)** מכת כינים כי הגם שיצטער אבל אין שם סכנת מות כצפרדעים שתנקוב בני מעיו וגו' ותעשנו טרפה, ולזה הגם שידע כי אצבע אלהים היא והעידו החרטומים כי אינם יכולים עשות אף על פי כן ויחזק לב וגו':
@186 **ד)** מכת ערוב אימות שן בהמות ששלח ה' בו בהלוהו וירא עד מאוד ותיכף שלח אחריהם ואמר (פסוק כא) לכו זבחו וגו' אנכי אשלח וגו' העתירו בעדי:
@186 **ה)** מכת דבר לצד שהיתה במקנה לבד הגם כי שלח וראה מקנה ישראל ולא מת א' אף על פי כן לא שת לבו לבקש רחמים:
@186 **ו)** מכת שחין לצד שלא היה בו סכנה גם אפשר שנתכבד במכה זו ממה שלא הזכיר ה' בפי' כי גם בו היה שחין ולא אמר אלא (לקמן ט' יא) כי היה השחין בחרטומים ובכל מצרים לזה לא בקש ממשה להתפלל בעדו:
@186 **ז)** מכת ברד לצד שהרעים ה' משמים ונתן קולות ואש מן השמים נפלה עליהם אימתה ופחד שיעשה להם כמהפכת סדום ועמורה ופחד ורהב (ישעי' ס') לבבו ואמר ה' הצדיק וגו' העתירו אל ה' וגו' (ט' כז):
@186 **ח)** מכת הארבה פיו ענה בו כי מה שנתרגש הוא לצד שירא יראת מות דכתיב (י' יז) ויסר מעלי רק את המות הזה:
@186 **ט)** מכת חושך לא ראינו לו שבקש ממשה להתפלל, ואולי כי בג' ימים ראשונים היה מדליק עששיות ופנסות גדולות ויאר את החושך ובג' ימים שניים שהיה חושך ממושש ולא קמו איש מתחתיו לא היה מציאות לו שילך אדם לקרא למשה כי לא קמו איש מתחתיו, ואחר ששלמו שבעת ימי אפילה (ש''ר יד) תכף ומיד שלח אחר משה ואמר אליו שילכו אלא שיתנו בטחון מהם שיחזרו ולא קבל משה, ולצד שכבר פסקה המכה לא הוצרך לומר לו התפלל:
@187 **התפאר עלי וגו'**. צריך לדעת כוונת אומרו **התפאר עלי** וגו'. ואם לומר כי הגם שיאמר לו להסיר מעליו תכף ומיד זה הוא ההתפארות אם כן כשאמר לו פרעה למחר ולא אמר עתה בשעה זו שיגיד כי לא רצה להתפאר עליו מה מקום לומר לו כדברך למען תדע אין זה התפארות מיום ליום ואדרבה הרחיק לו הזמן:
@187 **עוד** צריך לדקדק דברי משה שאמר **למתי אעתיר** וגו' שלא היה לו לומר אלא מתי יסיר הצפרדעים שהוא המבוקש.
@187 **אכן** כוונת משה להראותו אשר יפליא ה' לחבב ידידיו ומזה ישער ויחליט בדעתו כי מהנמנע שיעזבם ה' בשום אופן, כי הנה מדרך המוסר עבד כי ישאל דבר מרבו ולואי שישיג עשוהו לו לא שיתנה עליו בזמן מסוים ובלבד שלא יקדים ובלבד שלא יאחר אלא ועבד ישאף רבו עת אשר יחפוץ לחוננו רצון, ואמר משה בא וראה ההשגחה הנכונה ושלימות החיבוב שאעתיר לה' ואומר אליו בתפלתי כי יעשה הדבר בעת אשר אקבע לו הזמן, והוא אומרו **למתי אעתיר** פי' לאיזה זמן, תתפאר עלי לומר התפלל לה' עתה כי לזמן פלוני יסיר וגו', והשיבו פרעה למחר וגו', וקשה כי הגם כי נפש רשע אותה רע זה דוקא בדבר שאין הרעות ניכר לאדם אלא במושכל אבל כזו וכזה אין לך אדם שיחפוץ שיתעכב בסכנת מות כמו שכן קראה הוא ויסר מעלי את המות. והיה נראה לומר כי לראותו זריזותו של משה שאמר למתי אעתיר וגו' הטעתו עין שכלו כי אמר כן משה לצד שהכיר כי קרב זמן קץ המכה ואין עוד מאז והלאה שליטה לאלהי העברים והמכה כלתה מאליה והערים ח''ו משה לצד שאמר בדעתו כי חפץ יחפוץ פרעה למהר ולהסיר הנגע לזה אמר התפאר ומן הסתם יאמר בעת ובעונה הזאת לזה סבל צער אותו זמן להכיר הדבר אם מרמה אחז ואמר למחר.
@187 **אלא** שכפי דרכינו אין אנו צריכין לזה, כי רצה לבחון התפארות משה שאמר שיתפלל ויתנה בתפלתו על אלהיו שישמע תפלתו עתה ולא יעשה כי אם למחר, ואין מדה זו אפילו בעובד לכוכב ומזל. ואמר **למחר** פי' שיתפלל עכשיו ויאמר בתפלתו כי למחר יסיר וגו', נתכוון הרשע להגדיל הנסיון שיתפלל להסיר ולא יסיר עד למחר. והשיב משה על זה ואמר כדברך נעשה למען תדע כי אין כה' אלהינו שיקבל תפלתינו בתנאיה על דרך אומרו (דברים ד' ז') כי מי וגו' כה' אלהינו בכל קראנו אליו, ולזה תכף ומיד יצא והתפלל לה'. ואין לחוש ולומר כי במה יאמת פרעה את הדבר שהתפלל אז ולא למחר בעת הצורך, הנה לצד שלא היה מתפלל תוך הכרך היו יודעים זמן תפלתו וכשיצא באותו יום ולא למחר הנה האות צודק, והוא אומרו **ויצא משה** וגו' **מעם פרעה ויצעק משה** וגו' פי' צעק ב' דברים הא' להסירם והב' להסירם למחר ולא קודם, ולזה דקדק לומר על דבר הצפרדעים ולא אמר ויצעק וגו' להסיר הצפרדעים שאז יהיה נשמע שתפלתו היתה על ההסרה לבד בלא תנאי הזמן, ויעש ה' כדבר משה פי' בזמן שאמר לו ויסר וגו':
@190 **אשר שם לפרעה**. מכאן שצריך לפרש תפלתו:
@195 **ותהי הכנם באדם וגו' כל עפר וגו'**. קשה שהיה צריך לומר כל עפר וגו' היה כנים ותהיה הכנם באדם ובבהמה. ויובן על פי מה שנחלקו התוס' במסכת שבת דף י''ב ר''י מאורליינש ור''ת מה היא הנקראת כינה, ומהם הוכיחו מכאן כי כינה היא הקופצת שדרכה להתהוות מעפר הארץ, ומהם אמרו כי זו נקראת פרעוש וכינה היא הלבנה הגדולה בבגדים והוכיחו מאותה שאמרו (ברכות נ''א) מסמרטוטי קלמי. והנה למה שנאמר כי כנים היא כנה, הלבנה בא הכתוב להסיר מקום הטעות כי השכל יכיר דבר זה שמה שמתהווה מהעפר היא כינה הקופצת, לזה אם היה אומר כל עפר הארץ וגו' ותהי הכינם אז תהיה הכוונה בפשיטות שהיא הקופצת, לזה נתחכם לומר **ותהי הכנם באדם** פי' הרגילה להיות באדם ממנו והכנת ההכאה. היא שיתרבה עיפושו ויגדל בגוף האדם כינה הלבנה ובבהמה כינה הרגילה בה.
@195 **או** אפשר כי שניהם היו בענין, הא' רמזה באומרו **ותהי הכינם באדם ובבהמה** פי' המתהוה מהאדם ומהבהמה מלבד כינה הקופצת שכל עפר הארץ היה כנים, וכפי זה ב' מינים אלו נקראים כנים, וכפי זה אין הוכחה מכאן לכינה המוזכר בדברי חכמים מה היא אם היא מין הלבן או מין הקופץ כיון ששניהם נקראים כינה, ומעתה אין הוכחות הר''י מאורליינש הוכחה ובאנו להכרעת ר''ת שהוכיח מהש''ס מה הוא שקורין חז''ל כינה שהיא הלבנה אבל הקופצת יחדו לה חכמים שם פרעוש כדי להכיר מין הכינה שאסרו בשבת וכן הלכה (טור ש''ע או''ח סי' שט''ז):
@199 **ומלאו בתי מצרים את הערוב**. טעם שחזר לומר פעם ב' **את הערוב** ולא סמך על הערוב שהזכיר סמוך לה, נתכוון לומר שהבתים ימלאו מהערוב, ואם לא היה אומר את הערוב יהיה נשמע על זה הדרך ומלאו הערוב את בתי מצרים וכפי זה זה הוא תכלית המכה שימלאו הערוכ בתיהם לבד, ולא כן הוא אלא מתחלה אמר **משליח בך** וגו' פי' לחבול ולהשחית ועוד אמר שימלאו הבתים מהערוב והבן. או יאמר אם לא היה אומר את הערוב והיינו מפרשים ומלאו הערוב את בתי מצרים היה בנשמע כי זה גבול רבויים עד שיהיה בהם גדר זה שימלאו הם את הבתים ולא כן הוא כי רבים הם הערוב ויתמלאו הבתים מהם ולא מכולם, וזה הוא שאמר הכתוב בהבאת המכה ובכל ארץ מצרים וגו':
@201 **ושמתי פדות**. פי' מלבד שלא יכנסו לארץ גושן עוד יעשה פדות אפי' לישראל שהם חוץ מארץ גושן לבל קרוב להם הערוב. ודקדק לומר **בין עמי ובין עמך** פי' כשיהיו עמי ועמך עומדים בשוה יעשה ה' פדות לזה מבין זה ולנכרי ישיך ולאיש ישראל לא ישיך:
@202 **תשחת הארץ**. פי' שהערוב ישחית גם כל נמצא מלבד בני אדם:
@206 **לא תרחיקו ללכת**. פי' כשיעור ג' ימים, כי כלום טעם שאמר משה הוא הן נזבח וגו' ולא יסקלונו אם כן למה יצטרכו להרחיק דרך ג' ימים בהרחקת פרסה או יותר קצת די, וטעם שנתרצה לו משה, כיון שכל עצמינו אין אנו משתדלים אלא לצאת מהעיר מה לי בתנאו יום או יומים, וכי ירדוף תרדפהו רעה וגזירתו עומדת לעומתו, לזה לא רצה משה לדקדק בתנאי הזמן ואמר רק אל יוסף פרעה התל לבלתי שלח באיזה אופן שיהיה, ודקדק לומר רק לשון מיעוט לומר הגם שיהיה השליחות בתנאי פחות מג' ימים:
@211 **בא אל פרעה**. כלל זה בידך כל מקום שיאמר בא אל פרעה יכוין לומר לו שיכנס אל טרקלין שלו בלא השאלת רשות הגם שהיו לו כמשפט המלכים שומרי הבית אף על פי כן יעול ויכנס אצלו מבלי שאלת רשות, וכן היה עושה כאומרם ז''ל (ילקוט קע''ה) כי כמה שומרים היו לפרעה מזוינים ואריות וכלבים והיה נכנס באין מונע. ומצאתי ראיה ברורה לדבריהם ז''ל ממה שאמר פרעה למשה (לקמן י' כח) השמר לך וגו' אל תוסף ראות פני וגו' למה הוצרך פרעה להתרות במשה והיה לו לצוות לעבדיו שומרי הבית כי כן מנהג המלכים להעמיד שומרי המלך ולהם יצו שלא יניחוהו ליכנס, אלא ודאי כי לא עמדו כנגדו ואפי' אריות וזה נם עצום, לזה היה ה' צריך לומר לו בא אל פרעה פי' הכנס ועלה אליו ולא תשים לבך למונע בעולם. ובזמן שהיה פרעה יוצא המימה היה אומר לו לך אל פרעה כי שם אין שומרים לירא מהם להצטרך לומר אליו עלה אליו אלא לצד שאין זמן זה ראוי להליכה כי הוא מוציא בולעו התעוב ואינו מהמוסר לזה אומר לו לך אף על פי כן:
@213 **אשר בשדה**. פי' דוקא, וכולן מתו דכתיב וימת כל מקנה מצרים פי' שהיו בשדה כרשום בדברי ה':
@215 **וישם ה' מועד לאמר**. פי' הודיע אותם זמן המכה כדי שיכניסו המקנה מהשדות וכמו שמצינו לו שעשה במכת הברד, ושם אמר ה' הדברים מפורשים דכתיב (פסוק יט) שלח העז וגו' וכאן אמר הדברים ברמז, והוא מה שנתכוון לומר בתיבת **לאמר** פירוש שיאמרו משה ואהרן שימת מועד זה לפרעה ולמצריים כי הוא תכלית המכוון כמו שפירשנו:
@216 **כל מקנה מצרים**. פי' שלא הכניסום מהשדה, ולזה לא אמר אשר בשדה והבן:
@216 **וממקנה בני ישראל**. שהיו להם מימי יעקב ובניו שבאו מצרימה, גם אולי שקנו מריוח שהרויחו במכת הדם. ועוד ירצה לומר שאם היו מתחכמין מהמצריים למכור לישראל כדי שיהיו נקראים על שם ישראל כדי שיפליא ה' בהם ולא ימותו והיו מערימין גם אלו מתו. אבל מקנה ישראל שהם כפי האמת מקניהם לא מת, ושיעור הכתוב הוא וימת כל מקנה מצרים וחלק א' ממקנה בני ישראל, ופי' מ''ם לא מ''ם מקצת הצאן אלא מ''ם מקצת מן המקנה הנקרא על שם ישראל, כי יש מקנה שנקרא על שמו והוא שלו, ויש שאינו שלו אלא שמו נקרא עליו, ואמר כי בחינה אחת ממקנה ישראל שהערימו המצריים לקרותם על שמם מתו. ומקנה ישראל פי' שהוא כפי האמת של ישראל לא מת מהם אפי' א':
@223 **השכם בבקר וגו'**. ג' מצות נצטווה, א' שילך בהשכמה, ב' שיתיצב לפניו פי' שלא ירכין ראשו ולא ירכין קומתו כדרך העומדים לפני גדולים, אלא כגדול העומד לפני קטן כי כבר עשאו רבון ושליט עליו, והוצרך לצוותו לצד שמטבעו של משה להרכין ראשו מעט כדרך השפלים, לזה אמר כי לפני פרעה לא יתנהג כן, עוד רמז לו כי פרט זה שאומר לו התיצב לא בכל מקום יסיר מעליו ההכנעה הרגיל בה, אלא לפני פרעה, אבל יהיה בלבו עניו ושפל לפני אל עליון ויהיה נצב בגופו ולבו מוכנע מאימת מלא כל הארץ כבודו, ומצוה ג' ואמרת אליו וגו':
@224 **כי בפעם הזאת וגו'**. הודיעו עוצם המכה כדין ההתראה שצריך להתרות עליו במיתה עצמה, שאם התרו בו במיתה קלה ובאים להמיתו בחמורה פטור כידוע:
@224 **כל מגפותי וגו'**. קשה הלא ראינו שהביא עליו עוד שלש מכות אחרות. והיה נראה לומר כי לצד ששקולה זו כנגד כולן, ומה שאמרו ז''ל (רש''י) ששקולה מכת בכורות כנגד כל המכות, אולי שזו שקולה כנגד כל שלפניה שהם שש מכות ומכת בכורות שקולה כנגד כל שלפניה ומכת ברד בכלל, וכשאתה בא למנין תהיה מכת בכורות שקולה כנגד י''ד מכות, ולא הנאני דרך זה. והנכון בעיני שנתכוין לומר אליו כי באמצעות מכה זו יטה לבו להבין להרגיש במגפות שהביא עליו ה', יובן כי בכל מכה ומכה שהביא עד עתה לא היה מחליט פרעה בדעתו כי הם מאלהי היכולת והיה תולה במכשפות ומעשה שדים, וזה לך האות שגם החרטומים עושים כן, והגם שהיתה מכה שאמרו החרטומים אצבע אלהים היא, יש מקום לפרעה לחשוב כי אפשר כי האנשים ההמה לא השיגו השגת משה ואהרן במכשפות ואומרים כן ולעולם ימצא אדם מכשף שיעשה כן, לזה אמר אליו ה' **כי בפעם הזאת** באמצעות המכה אשר אביא עליך אני שולח את כל מגפותי שכבר הבאתי עליך **אל לבך** פי' שתדע כי לא מעשה כישוף ושדים המה אלא מעשה אלהים, והוא אומרו **מגפותי** בכינוי העושה אותם כי בראותך מכה נפלאה אשר אין יכולת לשד וכשוף לעשות אפי' דומה דדומה להוריד אש מן השמים בפלאי פלאות אז לראשונות תתבונן:
@226 **בעבור וגו' ולמען ספר**. ירצה **בעבור הראותך את כחי** אתה שאמרת מי ה', **ולמען ספר שמי** באמצעותך **בכל הארץ** פירושו כל העולם יספרו את גודל אשר עשה לממאן בדבריו. וכן שמענו שאמר מלך אחד גדול כי אם יבא משיח ישראל ויעשה אות או מופת כי לא יעשה כפרעה למאן בדבר ה':
@229 **ועתה שלח העז**. ואם תאמר אם כן מה מכה זו עושה. הרי שלך לפניך מה שהקדים ה' לומר לו שאין תכלית הכוונה במכות להרע אלא בעבור הראותו כחו הגדול וידו החזקה, ולזה הודיעו שיאסוף אדם ובהמה מן השדה, ועל כל פנים תעשה המכה רושם בהשחתה מה שהוא מחובר לארץ שכן כתיב ואת כל עשב השדה הכה הברד ואת כל עץ השדה שבר:
@229 **ונשאר** לנו להשכיל בתיבת **ועתה** מה יכוין בה אלהינו ' עליון, אם לומר כפשטה ממש באותו עת למה יצו האל על זה כיון שאין הברד יורד עד למחר כעת ההוא. ואולי כי צריך שיעור זה לשלוח עד למקום שאדם ובהמה שמה ולשוב ליאסף הביתה.
@229 **עוד** נראה בהקדים לשאול דבר ה' שלח העז לאיזה מקום נוטה אם להירא דבר ה' הוא מעצמו כשישמע כי מחר ימטיר ה' ברד בשדה יירא ויכניס עבדיו ומקנהו אלא ודאי שלא באו הדברים אלא למי שאינו ירא דבר ה', וכפי זה יכוין באומרו **ועתה** על דרך אומרם ז''ל (ב''ר פכ''א) אין ועתה אלא תשובה, כי להיות שהם אינם שמים על לב דכר ה' לזה אמר להם שיחזרו בתשובה וישימו על לב דבר ה' כי עשה יעשה ויכניסו מן השדה וגו'. והודיע הכתוב כי הרשעים לא חזרו בתשובה ולא שמו לבם וגו' ובערה בם אש ה':
@231 **ואשר לא וגו' ויעזוב**. טעם אומרו **ויעזוב** בתום' וא''ו, שיעור הכתוב כן הוא ואשר לא שת לבו בכל הקודם אל דבר ה' הוסיף על חטאתו אפי' בדבר כזה שאין לו שום הפסד בהכנסתם הביתה והוא עומד להפסיד קניניו אף על פי כן **ויעזוב** וגו' להראות כי דבר ה' בזה. והצצתי כי המצריים מכעיסים היו את המקום לא לצד שהיו מחזיקים בישראל לעבודתם הוא שהיו ממאנים לשולחם, והנה לפניך שלא האמינו שיש כח בו חו''ש להוריד הברד ואפי' בתורת ספק לא היו אצלם שלא חששו לשמירת עבדיהם ובהמתם. ואולי כי לצד שלא היו בשש מכות הקודמות דבר פלא כזה לא לקחו מהם שיעור כי יכול לה ונראה בעיניהם שהוא רחוק שיכול עשוהו:
@234 **ויהי ברד ואש וגו'**. אומרו **מתלקחת** פי' כי להיות שהמים והאש הם ב' דברים הפכיים בקצה הקצוות ואין קירוב להם ובהתחברם יחד המתרבה על חבירו נוצח ומאבדו אם מים רבים יוכלו לכבות, ואם אש רבה היא אוכלת את המים, והודיע ה' כי בשליחות ה' כששלחם יחד היתה האש מתלקחת פי' מפעלת הפכיית טבעה אשר הטביע ה' בה שלא להלקח יחד היא עם המים היא היתה מתלקחת בתוך הברד ונסמכת אליו לעשות רצונו יתברך:
@239 **והברד לא יהיה עוד**. פי' לא יהיה מחדש ומה שכבר היה ויצא מן השמים אין עוד על דרך אומרו (פסוק לג) ומטר לא נתך ארצה ועמד באויר עד עת בוא דברו באחרית הימים והוריד אבנים שהיו על גב איש (ברכות נ''ד:):
@239 **למען תדע וגו'**. פי' אין אני מתפלל עליך לצד שאני מאמין בדבריך שתשלח את העם אלא להראותך כי לה' הארץ:
@240 **ואתה ועבדיך וגו'**. הזכיר העבדים להיות שראה כי לא שמו לבם אל דבר ה' והניחו עבדיהם ומקניהם בשדה שתפם יחד, ואם תאמר מי גילה למשה שאחר מכת הברד עודם במרדם ולא נכנעו והלא הצדיקו עליהם את הדין אחר כך ואמרו ה' הצדיק ואני ועמי הרשעים, כבר כתבתי לך שהשם השכילו כי יביא מכת בכורות על המצריים, גם כפי מה שפירשתי בפסוק (לעי. ל ז ד) ולא ישמע אליכם פרעה שיגיע עת שלא ירצה עוד לשמוע אפי' השליחות מהם אם כן מזה ידע משה שהגם שיחדלו המטר וגו' לא ישלחו את העם ואמר להם ידעתי וגו'. עוד יתבאר בסמוך כי ישנו לטעם שממנו אמר טרם תיראון:
@240 **ידעתי כי טרם תיראון**. פי' יודע אני כי קודם שתסתלק המכה אתם יראים את ה' ואומרים ה' הצדיק וגו' אבל אחר כלות המכה ותראו הרווחה תוסיפו למרוד כבתחלה וכבר נהגת כן עמי שתסכים על שלוח העם קודם כלות המכה ואחר כלות תכביד לבך. עוד ירצה להודיעו כי יורע הוא כי דבריהם לא ערמה ותחבולה כדי שיתרצה משה להתפלל בעדם אלא מלבם פחד ורהב לבבם מה' אלהים, ויש בזה הודעה להם כי יודע הוא מחשבות אדם ותחבולותיו, ודבר זה ישיגהו פרעה בעצמו כי צדק בימין משה, גם הודיעו בזה כי יודע הוא כי אין זה אלא טרם כלות המכה לא אחרי כן כשיראה הרוחה ימרוד וגם זה ידעהו לבסוף שהגם שישתדל להכחיש נבואתו ולשלח ישראל לא ימשול ברוחו והבן:
@241 **והפשתה וגו'**. צריך לדעת למה סדר ענין זה קודם גמר ענין תפלתו של משה שהבטיח כצאתי את העיר וגו' היה לו לגמור אומר כי עשה משה כן ויצא מאת פרעה והתפלל וגו' ואחר כך יודיענו את אשר עשה הברד.
@241 **ואולי** שיתכוון להסמיך ענין זה לאומרו טרם תיראון את ה' לרמוז הסיבה אשר סיבבה אותם לחזק לבם ואמר **והפשתה** וגו' ואמרו ז''ל במדרש תנחומא וז''ל כי אפילות פלאי פלאות נעשו להם שלא לקו ע''כ, והנה כראות פרעה כי לא שלטה מכת הברד בחטה וכוסמת שלא כפי הטבע כאומרם פלאי פלאות נעשו להם הוא לא יתלה כי ה' הפליא אלא יתלה כי אין שליטת אלהי ישראל בכל הווה וזה יגיד ח''ו השיתוף ואין שליטה בכל וזה היה לו מקום להכביד לבו, ולזה אמר משה **ידעתי כי טרם תיראוז**, וטעמו **כי הפשתה** וגו' **והחטה** וגו' **לא נכו** ועשה ה' פלא זה לחזק לב פרעה כאשר דבר ואני אחזק וג ו':
@244 **וירא פרעה כי חדל וגו'**. פי' שלא עמד בתשובתו שאמר ה' הצדיק וגו' אפי' זמן מועט אלא תיכף ומיד ויוסף לחטוא פי' הוסיף על הקודם כי אילו לא היה אלא שיעור הראשון לא היה מספיק להחזיק בישראל אחרי ראותו פלא הברד אלא שהוסיף על גדר רשעו שהיה בו והכביד לבו ולב עבדיו:
@244 **חסלת פרשת וארא**
@246 **ויאמר ה' אל משה**. אמר ל' אמירה רכה גם הזכיר שם הרחמים לא לצד המשתלח אליו אלא לצד השליח שהוזכר בסמוך אל משה כי הם דברים שישמח בהם צדיק כי חזה נקם לזה אמר ל' אמירה והזכרת שם הרחמים כי הם דברים הסועדים את לבו:
@246 **עוד** לצד שלא היה ה' שולח המכה תכף ומיד עד שהי' שולח להתרות בו קודם למר שבוע א' (שמו''ר פ''ט) ולמר ג' שבועות, וזה הוא ממדת החסד והרחמים לזה אמר לשון אמירה וזכרון שם הרחמים. עוד ירצה על דרך שפירשתי למעלה בפרשת וארא (ו' ב') כי אפילו מדת הרחמים הסכימה בשמחה לעשות דין ולהנקם מאויב זה:
@246 **כי** אני הכבדתי. פי' מעתה תשכיל לדעת כי אני הוא שהכבדתי את לבו כי מטבע אדם לו יהי' לבו קשה כאבן ירעד ויפחד בראותו מכת הברד וזה האיש עודנו ברשעו אין זה ממדת אדם אלא אלהים גזר עליו להקשותו. ולפי מה שפירשתי בפסוק (לעיל ט' ל''ב) והחטה והכוסמת וגו' כי אפילות וגו' כי ה' עשה פלאי פלאים וזה היה סיבה להכביד לבו ידוייק גם כן על נכון כי אני הכבדתי בעשות פלא זה:
@246 **או** ירצה לדרך זה כי לצד שראה משה המכה הגדולה של הברד ורשע זה אדרבה הוסיף לחטוא ישלול התקוה ממנו ויתחמץ לבבו בשליחותיו אל פרעה לזה אמר לא תחוש לזה **כי אני הכבדתי לבו** וזולת זה כשארף ממנו כובד לב הנה הוא משלחם:
@246 **ואת** לב עבדיו. טעם כובד לב עבדיו הוא לבל יעצוהו לשלח גם שבזה תהיה הבאת המכות לכל מצרים ולא לפרעה לבד כי בזה לא יהי' פרסום המכות אשר יביא ה' על פרעה לבד והגם שלא הזכיר ה' פרט זה בשליחות ראשונה ולא אמר אלא אחזק את לב פרעה אמר העיקר ובכללו הם עבדיו ואולי שנתכוין ה' בדבריו כאן לפרש לו דבריו הראשונים שלא לב פרעה לבד אלא גם לב עבדיו וטעם שלא ביאר מקודם וביאר עתה לצד שאמר משה בפרשה הקודמת ואתה ועבדיך גילה דעתו כי הוא סובר שאין הזכרת עבדיו נכללת בהזכרת פרעה ומעתה יבין בדברי ה' שאמר לו ואני אחזק את לב פרעה כי אין עבדיו בכלל ויחשוב כי חיזוק לב עבדיו לא מה' יצא הדבר לזה אמר **אני הכבדתי את לבו ואת לב עבדיו**:
@246 **למען שיתי אותותי אלה בקרבו**. צריך לדעת למה דקדק לומר **אותותי אלה** שיראה שעיקר הטעם שהכביד לבו הוא לצד אותות אלה לשומם שנראה שיש צורך בשימת אותות אלה ולא זולתם, עוד אומרו **בקרבו** ויתבאר על דעך אומרם ז''ל (שמו''ד פי''ב) כי מעשה מצרים מעיד על האלהות כי הוא השליט והוא האדון, והאדון לצד שחפץ בישראל לקרבם לעבדו ולדבקה בו היה חפץ להשכילם לראות ולהביט בעין הכחשת כל אמונה חוץ ממנו, ועדיין לא הראם כי הוא בורא רוח ועושה מלאכיו רוחות, גם לא הראם כי הוא בורא אור וחושך, ולזה אמר **למען שיתי** וגו' פירוש לצד שאמר אליו כי אני הכבדתי את לבו יש מקום למשה לומר למה יאריך עוד הטורח ויצטרך גם כן לשדד המערכות כי יש בכל מכה שינוי סדר מערכת הבריאה, אם להראותו את כוחו יתברך אשר אמר עליו מי ה' הלא הכה מכת הברד והראהו ה' ידו הנפלאה ומה צורך להפך סדר הבריאה עוד, לזה אמר אליו טעם למען שיתי אותותי אלה פירוש אותות שאני רוצה לעשות בעולמי כדי שיכירו ישראל האלהות עדיין נשארו מהם אלה להשלמת האמונה, כי בכל שבע מכות שעברו אין בהם הכחשה למשתחוה לשמש או לירח, גם לאשר יטעה כי בורא הרוח אינו בורא העפר, והגם ששלט ה' על הארץ במה יודע כי הוא בורא רוח הוא היוצר אדם וצר צורה, והוצרך ה' להראותם במעשה הארבה כי עשה מלאכיו רוחות להביאם גם להחזירם, גם לשאת את המתים לבל יהנו מהם המצריים (שם פי''ג) ובמכת חושך כי הוא יוצר המאורות ושלט בהם, גם יצירת החושך וגזר עליו לשמש עבות למצרים (שם פי''ד), ובמכת בכורות נודע כי הוא היוצר צורה בתוך צורה ומכיר טיפת הבכור (ב''מ ס''א:) גם באמצעות מכה זו צוה ה' מצות (לקמן י''ג ב') קדש לי כל בכור, ויהיה זה לזכרון כי הוא יוצרו מבטן לעבד לו, ולזה כשמצא רשע זה הקשה ה' לבו למען שיתי אותותי אלה שאני צריך לעשות לאות ולמופת לטעם הנזכר יהיו בקרבו שתמצאנה אותו כוסות התרעלה גם כן לצד רשעו וזולת טעם זה לא היה ה' משדד המערכות בשבילו לבד:
@247 **ולמען תספר וגו** '. צריך לדעת לאיזה ענין הוצרך לטעם זה ולא הספיק בטעם הראשון שה' חפץ להשים אותות אלה כמו שפירשתי בסמוך. עוד מה הוא את אשר התעללתי במצרים ומה הוא ואת אותותי שנראה שהם ב' דברים. עוד צריך לדעת כוונת אומרו **וידעתם** וגו':
@247 **אכן** כוונת הכתוב הוא כי בא ה' להודיע כי אין תכלית הכוונה בהבאת האותות בקרבו לעשות נקמה בפרעה אלא לחזק האותו' שבהם עיקר האמונה בלב ישראל כדי שיהיה רשום בל ישכח לנצח כי כשיהי' בקרבו של פרעה יהי' בזכרון בני ישראל לעולם ועד והכוונה ע''ד אומרם ז''ל במם' חולין (עה:) בדין בן פקועה כ''א יהיו בו ב' דברים המופלאים יהי' מוזכר תמיד וכשיראו שאוכלו בלא שחיטה לא יחשדוהו כי מוזכר הוא ביניהם כי תרי תמיהי מדכר דכירי אינשי והנה באמצעות הפלא שיפליא ה' להודיעם כי הוא שולט ברוח ובמים ובעפר ובבעלי חיים ובאש ובאויר וכדומה אין זה מספיק שיזכר הדבר בתמידות לעולם לחקק האמונה אלא באמצעות היות הפלאה ב' כי יפליא ה' להרע את פרעה ועבדיו להשקותם כוסות לענה מה שלא הי' כן לכל גוי וזה לך נעימות אמרי נועם ולמען תספר באזני בנך ענין זה והסיפור מן הנמנע שיהיה הדבר תמיד בזכרונך זולת באמצעות ב' תמיהות, הא' **את אשר התעללתי במצרים** הרי תמיה אחת הגם שהי' ה' עושה להם צרות שאין בהם שדוד המערכות והטבעיות אעפ''כ לצד רוב הצרות והמכות עשר מכות וכל מכה היתה של ארבע וה' מכות לא עשה כן לכל גוי הנה הדבר תמוה ותמיה זו לבד לא דכירי אינשי ולא יספרו מעשה ה' ואמר **ואת אותותי** פי' האותות שעשה ה' תמיה' שנית שגם בלא ענין מצרים האות מעצמו הוא דבר פלא ובאמצעות ב' פלאות תספר באזני בנך ובן בנך וגו' ותכלית המכוון בסיפור הוא וידעתם כי אני ה' ואין עוד ותכזיבו האמונות זולת זה וכן תמצא כשדבר אתנו ה' ב''ה בהר סיני פתח דבריו ית' אמר אנכי ה' אלהיך וזה לך האות אשר הוצאתיך מארץ מצרים והוא שהקדים דבריו כאן ואמר וידעתם כי אני ה' כי יכירו בזה בחוש הראות צדק האמונה מה שלא השיג אדם מהעולם עד העולם ברוך אשר כן עשה לנו:
@251 **ויפן ויצא**. זלזלו בעיניו שאחר שהתוודה ואמר ה' הצדיק וגו' וחזר לסרחונו לזה פנה ויצא כדרך הנהוג עם שאר בני אדם ותמצא כי גם פרעה הרשע שילם לו כן דכתיב ויושב וגו' ויגרש אותם מאת פני פרעה ולזה תמצא שאח''כ כשקרא לו להתפלל על הסרת מכת הארבה אמר אליהם חטאתי לה' ולכם מה שלא היה רגיל לומר קודם שנתכוון להתודות על שנהג בם מנהג פחיתות ויגרש אותם:
@252 **עד מתי יהי' וגו'**. לא שהסכימו לשלח ישראל בהחלט כי הנבואה שאמר ה' למשה הכבדתי וגו' תכחיש זה אלא שרצו שילכו באופן שיחזרו ודאי ולזה תמצא כשאמר משה בנערינו ובזקנינו וגו' וגרש' פרעה לא יספו דבר עוד בדבר הזה גם פיהם ענה בם כי לא האמינו בסדר המעשה כי אלהי העברים הגדול הגבור והנורא נטה ידו בהם לשלוח ישראל אלא שהיו יוקשים בהם ואין לך כפירה באמיתות הענין כזה:
@252 **הטרם תדע**. פי' האם קודם שתשלחם תרצה לדעת שאבדה מצרים לזה שלח אותם קודם שיגיע גדר זה של אבידת מצרים:
@252 **וראיתי** לתת לב במה הסכימה דעתם על אבידת מצרים אחר כך ושתקו והלכו להם ולהבין הענין נשכיל בחקור בענין מה היתה דעתו של פרעה ועבדיו מתחילת הענין האם יש שוטה גמור בעולם שיסבול כל הרעות והצרות ההמה ויכנים עצמו בסכנות נפשות ועוד לו שלקה אלוהו וספו מקניו ואבדו צמחי אדמה וכמעט ספו תמו כאומרו הטרם תדע כי אבדה מצרים ומהן הסתם לא יאמן כי כ''כ טפש היה והגם כי הקשה ה' את רוחו עכ''ז צריך שתהיה לו איזה סברא שבה יתגלה טפשותו ותגדל הקושיא בראות כי לא שאל ה' ממנו אלא דרך שלשת ימים והגם שכתבנו שם (לעיל ג' י''ח) כי ה' לא אמר פדט זה אלא ישראל עם כל זה הרי בכל שליחותיו לא אמר אלא (ה' א') ויחוגו לי במדבר, ויעבדוני (פסוק ג'), זה יגיד כי לא לחלוטין יצו ה'. ואבין דבר כי הוא זה אשר הטעהו לפרעה ולכל עמו אופן השליחות אשר שלח ה' לשלוח ישראל לחוג במדבר שהכוונה הוא לשוב אחר כך הרי הוא גלוי לפרעה ולעמו כי לא בהחלט הוא שואל ומזה נפל הטעות כי יש בדבר שני צדדין הא' כי דבר ה' אמת הוא כי אינו חפץ אלא דרך שלשת ימים והב' כי הדברים באו דרך ערמה ואין דעתו אלא להוציאם לחלוטין ולפי זה הדברים מעידים כי כביכול אין כח בו להוציאם בהחלט ב''מ הא למדת שיש לו מניעה חם ושלום לרצון אשר יחפוץ ולזה פרעה ועבדיו לצד שלילת עיקר האמונה בהם חשבו צד הב' ולזה הקשו ערפם ומאנו לקבל מאמר ה' כי אמרו אין בכוחו ח''ו להכריח הכרח גדול וזה לך האות המופלא שערום יערים ולזה הקשו לבם ואחר כך כשראו עבדיו שעברו עליהם שבע מכות והתרה במכה שמינית של הארבה נתנו לב לצדד צד הא' כי האמת הוא שטעמו של האלוה ב''ה הוא שאינו חפץ להוציאם לחלוטין. והוא אומרם **עד מתי יהיה** וגו' **שלח את האנשים ויעבדו** פי' שאין כוונת ה' אלא על פרט זה והטעם שבו הכרחנו הדבר כי הכרנו כי כל יכול ואם היתה כוונתו שילכו לחלוטין היה אומר כן בפירוש ויאבד כל מסרב וממאן בדבריו ואמרו **הטרם תדע כי אבדה מצרים** במכות אשר הכה הא למדת כי יכול הוא לעשות כל אשר יחפוץ ולפי זה הכריחו שני דברים הא' שישראל לא ילכו בהחלט והצדיקו מפלאי המכות כ''א היה ה' חפץ להוציאם בהחלט אין מידו מציל. ותמצא כי נתחכם פרעה הרשע והשיבם במרמה ויושב את משה וגו' ויאמר להם מי ומי ההולכים והשיבוהו בנערינו ובזקנינו נלך ואמר להם רעה נגד וגו' לכו נא הגברים וגו' כי אותה אתם מבקשים ויגרש אותם וגו' ומאמצעות המעשה נסתרה דעת עבדי פרעה כי לא כמו שחשבו שאין הליכתם אלא לשעה שהרי מהענין מוכח כי ערמה בדבר והליכתם הליכת עולם ולפ''ז חזרו ג''כ למיחוש הראשון כי זה לך האות כי לא כל יכול כנזכר למעלה ובזה לא הוסיפו לדבר עוד כדבריהם הראשונים:
@253 **לכו** עבדו וגו'. אמר סתם הדברים ונתחכם להרחיק שלא יעלה על הדעת שישאלו שילכו כולם ולזה דיבר סתם לכו עבדו ואמר **מי ומי** לא לומר אם כולם אם מהם זה ' ודאי שלא ילכו אלא בני העבודה כמו שגילה לבסוף לכו הגברים כי אותה אתם מבקשים אלא גם בגברים היה חפץ שלא ילכו כולם:
@257 **בארבה**. אולי שיקשור ארבה אחד במטהו או אפשר שיזכיר שם הארבה בנטותו את ידו לסי' כי נטית ידו הוא בשביל ארבה:
@267 **ויט** משה את ידו. צל''ד למה במכת הארבה הסמוכה לה הגם שאמר אליו ה' נטה ידך אמר הכתוב ויט מה את מטהו וגו' וגם בכל המכות לא היתה מכה שהזכיר בה נטית יד אלא מטה ובמכה זו אמר **את ידו**. ואולי שיתכוין ע''פ דבריהם ז''ל (שמו''ר פי''ז) כי חושך של מצרים היה מאותו חושך דכתיב תהלים י''ח ישת חושך סתרו אשר ע''כ לא נהג מנהג מיעוט דרך כבוד לנטות מטהו כלפי מעלה:
@267 **גם** ליש מרבותינו שאמרו (שמו''ר שם) שחושך זה היה מגיהנם אולי כי שניהם נתכוונו אל האמת כי ב' מיני חושך היו אחד ששמש בג' ימים שלא ראו וגו' וא' ששמש בג' ימים אחדים שלא קמו וגו':
@268 **ולכל** בני ישראל היה אור וגו'. דקדק לומר **ולכל** לומר שכל אחד ואחד מישראל שהיה הולך לבית המצרי היה לו אור במושבותם של המצריים. או יכוין לומר אור זה מנין מוצאו ואמר שהוא **אור במושבותם** וחסר תיבת אשר והרבה מקראות יקצרו כן והכוונה ע''ד אוז''ל (שם) כי הרשעים מתכסים בחושך והוא אשר כיסה המצרים הרשעים וכנגד הצדיקים עליהם יזרח ה' ב''ה ואוהביו כצאת השמש בגבורתו ומאור מושבותם ליוה להם ה' ב''ה חלק א' והוא אומרו **אור במושבותם**:
@269 **ויקרא** פרעה וגו'. פי' אחר ששלמו ימי החשך כי קודם לא קמו איש וגו', ולזה דיבר הרשע קשות למשה ואמר לו אל תוסף וגו' ראותך פני תמות, כי אם חושך ישופהו היה מדבר תחנונים:
@269 **גם** טפכם. טעם שלא הסמיך ההולכים יחד ואח''כ המוצגים עז''ה לכו עבדו וגו' גם טפכם גם צאנכם רק צאנכם וגו' אולי שנתחכם הרשע להקדים התנאי קודם למעשה וזה שיעור דבריו **לכו עבדו** כדברי הראשונים שהגברים הם העובדים ולא הטף רק אם תעשו תנאי זה **שצאנכם** וגו' **יוצג** בתנאי זה **גם טפכם ילך** וגו' וזולת התנאי לא ילכו אלא העובדים שהם הגברים ולא הטף ואם היה מקדים המעשה לומר גם טפכם וגו' ואח''כ יאמר רק צאנכם המעשה קיים והתנאי בטל ואולי שגם בין הגוים יקפידו על דיוק זה להיות דברי סברא והם דברים הרגילים במקח וממכר:
@270 **גם** אתה תתן בידנו. קשה איך שאול ישאל עבד ה' זבחי אלהים מאיש בזוי וטמא אשר הרים פיו בקדוש ישראל נוסף על היותו נכרי החפץ לה' בזבח רשעים והגם שאמרה תורה איש איש לרבות (חולין י''ג:) אך ורק לא לשאול ממנו. אכן דברי פי חכם דקדק בלשונו ואמר **ועשינו** שהיל''ל לעשות לה' אלהינו אלא נתכוונו לומר שהוא יתן בידם מקנה הראוי לזבחים ואנחנו נעשה לה' אלהינו לצורך עצמנו אלא שהוא ימציא להם מתנה שיסתפקו ממנה לזבחיהם לה' גם בזה לא קשה אומרו זבחים ועולות לתנא שאמר (מנחות ע''ג:) שאין מקבלין מאו''ה אלא עולה ולא שלמים והרי מקרא מלא דיבר הכתוב כאן זבחים ועולות ולדברינו לא קשה:
@271 **וגם מקנינו וגו'**. צריך לדעת למה הוצרך להזכיר אחר שכבר אמר אליו גם אתה תתן זה יגיד שמלבד שיקחו מקניהם גם אתה וגו'. אם כן הרי הזכיר מקניהם, והיה נראה לומר שחש שיבין פרעה כי אומרו גם אתה לא ירמוז הקודם על מקניהם אלא על הטף כי מלבד שילך הטף גם צריך הוא ליתן וגו', לזה ביאר הדברים שעל המקנה, זה דוחק. עוד צריך לדעת כונת אומרו **כי ממנו נקח** וגו' מה חידוש בזה אם להודיעו שעובדים ה' בזביחת צאן, הלא כבר אמר אליו גם אתה תתן בידינו זבחים וגו' אם כן אין חידוש בהודעה זו. עוד צריך לדעת אומרו לא נדע מה נעבוד כי פשט הדברים יגיד בזה הוא על השיעור שאינם יודעים כמה תכבד העבודה ולזה צריכין למקניהם וגם הוא יתן אם יחפוץ, אם כן היה לו לומד כמה נעבוד. אכן נראה כי נתכוין לשלול טענה אחת לבל יטעון אותה פרעה והוא כי יקחו מין הראוי לזבוח לה' ומין שאינו ראוי יוצג לזה אמר וגם מקנינו ילך עמנו פירוש אפילו אותם שאינם ראוים לזביחה, ולזה גמר אומר **לא תשאר פרסה** פירוש כל רגל בהמה ובכלל זה נכלל סוס ופרד גמל חמור וכו' כי כולם יקרא להם מקנה. ואומרו כי ממנו נקח יתבאר על דרך אומרם במסכתא (ע''ז כ''ד:) וזה לשונם ת''ש וכו' אשר חמל העם על מיטב הצאן וגו' למען זבוח לה' וגו' מאי מיטב דמי מיטב ומ''ש דאקפץ עליהם זבינא ע''כ. הנה שהגם שאמר הכתוב למען זבוח לה' מפרש לה התלמוד למען קנות מדמיהן זבחים וכמו כן יתבאר אומרו כאן **כי ממנו נקח** פירוש הגם שאינם ראוים לזביחה אף על פי כן יצטרך לנו לטעם **כי ממנו** פירוש מדמיו נקח לעבוד ה' פירוש צורכי עבודה, ולזה לא אמר ממנו נזבח לה' אלהינו:
@271 **ואומרו ואנחנו לא נדע מה נעבוד** פירוש ואם תאמר נשער שיעור המספיק לעבודה והשאר יוצג, לזה אמר לא נדע מה נעבוד תיבת מה תסבול ב' עניינים ולב' נתכוון, הא' הוא כמה, והב' מה הוא אופן העבודה שיצו האל אותנו, כי אפשר שיאמר שנבנה בנין לזבוח בו וכלי זהב אין שיעור ואבנים טובות ומרגליות ועבודות אחרים, והגם שאמרו ונזבחה וגו' הרי אמר עוד שלח עמי ויעבדוני והכניס פרטים אחרים בכלל זה מלבד הזביחה באופן שאין דבר זה של הזביחה מסויים שאין זולתה, אשר על כן אנו צריכין לכל מה שיש לנו וגם אתה תתן. ואומרו **עד בואנו שמה** נתחכם להשיב כי יאמר אליו הלא נביא אתה ושאל לך דבר זה מה' ויתברר הענין ויוצג דבר שאין בו צורך, לזה אמר עד בואנו שמה פירוש שאין זה מהמוסר לשאול את אלהינו על הדבר לדעת מה יחפוץ עד בואנו שמה במקום העבודה אז נדע הדבר. ואולי כי לצד שפרעה לא הצדיק תשובה זו וחשד כי משה ערום יערים עליו ודברי עצמו משיב ואין חם ושלום בפיהו נכונה כי מן הסתם יודעים גם יכולים לידע אלא משה מפי עצמו אמר תשובה זו לנגדו לזה נתכעס עליו ואמר אליו אל תוסף ראות פני וגו':
@272 **ויחזק ה' וגו' ולא אבה וגו'**. יעיד הכתוב כי בפעם הזאת החליט בדעתו שלילת שליחות ישראל ולא נשאר בדעתו לחשוב מחשבות אם יחוש למכות או אם יסבול מכות הגדולות אלא חתם הדבר יעבור על דברי ה' הגם שיהרג:
@272 **או** ירצה שנתחכם לעשות אופן שלא יבואו עליו עוד מכות ובזה אין הכרח לשלחם והוא מה שאמר סמוך לאומרו ולא אבה **ויאמר לו פרעה לך מעלי** וגו', הכוונה בזה כי לצד שהשכיל בתשע מכות שבאו עליו שכולן היו על זה האופן ב' בהתראה ואחד בלא התראה למאן דאמר ג' שבועות היה מתרה על כל מכה ומכה ולמאן דאמר שבוע א', אמר מעתה במכה זו הבאה תתחייב להיות ההתראה ואם אין התדאה אין מכה, לזה נתחכם ואמר השמר לך אל תוסף ראות פני וכיון שכן אין התראה וכיון שאין התראה אין מכה. והנה לא הקשה ה' את לבו לעשות כן אלא עד כלות ט' מכות ולא נשארה אלא מכת בכורות, ולזה אמר משה **כן דברת לא אוסיף עוד** וגו', ופירוש דברי משה כבר פירשתי אותם בפרשת וארא בפסוק (ז' ג') ואני אקשה, ולא ישמע אליכם פרעה וגו':
@272 **ובדרך** רמז ירצה באומרו **כן דברת** תשובה למה שאמר לו ביום ראותך פני תמות השיבו כי אינו יכול להמית ואין בידו אלא כח הדיבור, והוא אומרו כן דברת ולא כן תעשה. או ירצה על זה הדרך כבר דברת כן פעם אחרת, והמכוון הוא ראה מה עלתה בידך כאומרם ז''ל (שמות רבה פ''א) בפסוק (ב' ט''ו) ויבקש להרוג את משה ולא עלתה בידו, גם אמרו (ילקוט קע''ה) שהרג כל שועריו שהניחו למשה ליכנם והשיבו כי אין להם שליטה עליו, ואם כן הבזוי איך מחליט לומר ביום וגו' תמות. וכנגד הענין מצד עצמו שאין אתה חפץ לראות פני גם אני אין אני חפץ להסתכל בדמותך לא אוסיף וגו':
@275 **ויאמר ה' וגו' עוד נגע וגו'**. פרשה זו מגדת מה שכבר אמר ה' קודם. ותמצא כי התחלת המכות נבואה ראשונה שהיתה במדין אמר לו (ג' י''ט) לא יתן אתכם מלך מצרים להלוך ולא ביד חזקה ושלחתי את ידי וגו' ונתתי את חן העם וגו' ושאלה וגו'. ונבואה ב' גם כן במדין הודיעו מכת בכורות דכתיב (ד' כ''ב) בני בכורי וגו' ותמאן לשלחו הנה אנכי הורג את בנך בכורך הרי בידו מכת בכורות באחרונה. ונבואה ג' בארץ מצרים אמר אליו (ז' ד') כי סימן סוף המכות הוא כשלא ישמע להם פרעה פירוש שלא ירצה לשמוע דבריהם עוד, אשר על כן כשאמר לו אל תוסף וגו' מזה ידע כי הגיע זמן מכה האחרונה שבה יצאו וידע אותה כי היא זו מכת בכורות ששקולה כנגד כל וכו' הנאמרת אליו בסמיכות מצות ושאלה אשה משכנתה, והוא מה שאמר הכתוב **ויאמר ה' עוד נגע** וגו' פירוש כבר אמר ה' עוד וגו' פירוש שהוא מה שכתב בנבואות הראשונות כמו שרשמתי, ולזה אמר משה תיכף אל פרעה כה אמר ה' כחצות הלילה וגו'. והגם שלא מצינו שאמר לו ה' שם פרט זה של כחצות, ילמד סתום מהמפורש כי כן היו שם הדברים אלא שקצר וממקומו אתה למד כי כן אמר אליו ה'. ומעתה לא נאמרה נבואה זו במצרים, גם לא קשה למה יצו ה' פעמים על שאלת כלים ממצרים:
@278 **כחצות הלילה**. כבר דברו רבותינו ז''ל (כרכות ד'.) בטעם אומרו כחצות בכ''ף. ואולי שיכוין עוד על דרך אומרם ז''ל (בראשית רבה פמ''ג) בפסוק (בראשית י''ד ט''ו) ויחלק עליהם לילה כי ליל ט''ו בניסן היה. עוד אמרו ז''ל (בראשית רבה פמ''ב) כי הריגת ד' מלכים שהרג אברהם אבדה כמה אמונות, גם היתה מלחמה גדולה ועצומה ורשומה במלכי עולם כי היו מלכים תקיפים ושלטו על ה' מלכים גדולים ותקיפים ואדם אחד הוא ועבדי ביתו נצחום, לזה ציין לו הזמן ואמר לו **כחצות הלי**. לה הידוע בעולם שיצאתי לישע אברהם אביהם כמו כן אני יוצא וגו':
@278 **אני יוצא וגו'**. פירוש הגם שיש לי כמה משרתים אף על פי כן אני בעצמי אצא בתוך מצרים, והטעם לב' סיבות, א' לחיבת הבנים שתהיה יציאתם על ידו בכבודו
@278 יבעצמו, ב' כי אין מלאך מבחין ההבחנה הגדולה מי הוא שנוצר מטפה ראשונה של אדם שיקרא גם כן בכור הגם שהוא ב' וג' לבטן זולת הוא היוצר הוא הבורא ברוך הוא מכיר הטיפות שצר מי ומי הבכור:
@279 **ומת כל בכור**. ולא אמר והרגתי כל וגו' להיות כי ה' ברוך הוא פועל הטוב כידו אבל פעולת הרע יצו למשרתיו עושי דברו והם יעשו, לזה לא אמר והרגתי אלא ומת פירוש על ידי שליח, ומעשה ה', המה הזכרת הודעת הבכורות זה הוא וזה גורם כי המשחית ישחיתנו ' ומת, ומזה יתגלה פירוש אומרו והכיתי שהוא על ידי שליח:
@279 **עוד** ירצה על דרך אומרם ז''ל (שבת ל''ד.) יהב ביה עיניה וקטליה, גם אמרו ונעשה גל של עצמות. והנה דברים אלו בהשקפה ראשונה ירחקם השכל כי איך תהיה ראיית צדיק לרעה והלא כתיב (משלי כ''ב) טוב עין הוא יבורך, גם ציין ר' שמעון בן יוחאי ז''ל (זהר ח''ג רי''א) לרע עין המזיק בעינו כי הוא חלק רע. אכן אחר ההשקפה בדקדוק אומרם יהיב עיניה היה לו לומר ראה בו בעיניו, אלא להיות כי כל חלק רע שבעולם בהכרח כי יהיה לו דבר המעמיד כל שהוא מהחיוני שהוא בחינת הטוב כי חלק הרע שם מיתה יש לו ואיך יחיה ויהיה במציאות ואין צריך לומר שיתנועע וילך כבעלי חיים, לזה בהכרח שיהיה בו חלק כל שהוא מבחינה הנקראת חיים וזה חלק טוב. ובזה תשכיל להבין מאמרם ז''ל (סוכה נ''ב.) כי לעתיד לבא יביא הקדוש ברוך הוא לס''מ וישחטנו במעמד הצדיקים וכו' עד כאן. ודברים אלו אין להם משמעות כי לא יוצדק שחיטה למלאך, ולמה שהקדמנו תהיה הכוונה כי יסיר ממנו חלק המחייהו ובהסרת ממנו חלק הטוב זו היא שחיטתו:
@279 **עוד** יש לך לדעת כי כל מקור ישאף למינו וישאבנו, וזה הוא סוד בחינת בירורי ניצוצי הקדושה באמצעות נשמות ישראל ועסק תורתם, והצדיקים העצומים קדמונינו יכירו בהביטם באדם רשע לברר ממנו כח החיוני שהוא בחינת הטוב באמצעות הראיה הדקה אשר יביטו בעין החכמה להוציא חלק הטוב ההוא כי כשיתכוין למול ענף הקדושה תעשה בו נפש הצדיק כמעשה אבן השואבת לברזל הנקראת קאלמיט''ע בלע''ז שתוציאנו ממקום שנקבע שם בראיה, וה' עשה דמיונות בעולם להאמין אדם בתורת חכם. ומעתה נמצא דעת אלהים באומרו ומת כל בכור פירוש כי באמצעות שאני עובר בתוך מצרים בזה ימות מעצמו כל בכור כנתינת עין של חכמים ברשעים ועושים אותם גל של עצמות כי באמצעות כן יצא מהם החיוניות כמו כן הדבר הזה שיפריד מהם באמצעות העברתו שם כל נשמות הבכורות והבן הדברים. ואומרו **כל בכור** פירוש לא שתצא הנפש מהגוף לבד אלא שגם בחינת נפש תמות גוף ונפש של קליפת בכור מצרים. ואולי כי בזה לא נתעצם שום גלות עוד כבחינת גלות ושעבוד מצרים כי אבד כח הקליפה העצום שהוא בחינת בכור:
@279 **וראיתי** לתת טעם למה לא יצאו ישראל אלא באמצעות מכת בכורות. עוד למה ה' הכה אפילו בכור שאינו מצרי דכתיב (לקמן י''ב כ''ט) בכור השבי. ואולי כי הטעם הוא לצד שמצינו שקרא ה' לישראל (לעיל ד' כ''ב) בני בכורי וכבר הודיענו רבותינו ז''ל (זהר ח''ב רס''ג) כי כל מה שברא ה' במדת הטוב גם זה לעומת זה עשה האלהים בבחינת הרע וכל בחינה ובחינה שיש בקדושה יש כנגדה בקליפה והקליפה מתאמצת ומתחזקת לאחוז בה, ולזה כנגד בחינת הבכורה שבקדושה היתה בחינת בכורה שבקליפה אוחזת ותוקפת בה לבל שלח עד אשר הרג ה' כל שם הבכורה שבקליפת מצרים בין של מצרים בין של האומות שהיו שם דכתיב עד בכור השבי ובכור השפחה וכל בכור בהמה, וגם בכור ישראל קדש אותם ה' כאומרו (במדבר ח' י''ז) כל בכור וגו' הקדשתי אותם לי כדי שלא תשאר בכורה זולת של קודש אשר הקדיש ה', ולזה מת אפילו בכור בהמה, וכיון שנעקר שם זה נפל ענף הרע שהיה מחזיק בבכור הקדושה ולזה תכף יצאו בני ישראל והגם שמצינו שיצאו ורדפו אחריהם, חשבו שעדיין יש בהם כח לאחוז בם, וצא ולמד מה עלתה בידם לא נותר בהם עד אחד:
@281 **ולכל בני ישראל וגו'**. צריך לדעת הכוונה בזה, ואם לומר שלא ימות אדם מהם, היה לו לומר בפירוש ולא ימות מבני ישראל וגו'. ואולי שנתכוין בסדר הדיבור על דרך אומרם ז''ל (בבא קמא ס:) כלבים צועקים מלאך המות בעיר, לזה אמר **ולכל בני ישראל** וגו' כדי שתדע שלא ימות מהם אדם שלא יחרץ כלב לשונו שם הא למדת שלא נראה ביניהם מחבל, והוא אומרו **למען תדעון אשר יפלה**:
@281 **עוד** נתכוון לרמוז לו כי דוקא במקום שיהיו כל בני ישראל פירוש כולם יחד יהיו ישראל לא יחרץ כלב וגו' זה לך האות כי אין זר אתם אבל אם לא יהיו כולם בני ישראל ויהיה ביניהם איש מצרי יחרץ כלב לשונו הא למדת כי יראה שם משחית, והכוונה בזה לומר לו כי לא תועיל ערמה לבכורות להמלט שהגם שיתחבאו הבכורות המצרים בין ישראל לא ימלטו באמצעות זה, וכן אמרו רז''ל (שמות רבה פי''ח:) (ח) **וירדו כל עבדיך וגו'**. כאן הבטיח כי עבדיו אלו יחיו ולא ימות מהם אחד במכת בכורות. ואולי שהיו כולם פשוטים ואין בכור ביניהם וידע בידיעת נביא. או הגם שהיו ביניהם בכורות אף על פי כן הוציאם מכלל המכה, והטעם לא לצד צדקותם אלא לצד שביזהו פרעה הרשע בפניהם ודבר אליו כדבר הנבל אל תוסף ראות וגו' כי ביום וגו' לזה צריך גם הוא להתבזות בפניהם כדין המבייש חבירו בפני רבים שצריך לפייסו בפניהם, ותמצא שהקפיד משה על הדבר דכתיב ויצא מעם פרעה בחרי אף. והנה הגם שלא אמר משה אלא וירדו כל עבדיך נתכוון לומר גם עליו כי הוא בעצמו יקום לילה אלא שדבר דרך כבוד:
@281 **והשתחוו לי לאמר**. טעם שלא אמר בפירוש ויאמרו לי, נתכוון לומר כי אמצעות ההשתחויה עצמה יגיד כי כוונתם לאמר צא אתה כיון שהוא אדון עליהם אם כן האדון יעשה חפצו ואין עליו שלטון. עוד ירצה כי להיות כי מנהג המלכים כשיבא אדם לדבר אליהם דבר ישתחוו לפניו ומזה ידע המלך כי הם חפצים לדבר עמו, כי אין מהמוסר לדבר לפני מלך גדול בלא שאלת רשיון גם אין דרך כבוד לשאול רשות לזה ישתחוה ובזה ידע המלך כי חפץ דבר ויאמר אליו דבר, והוא שאמר **והשתחוו לי לאמר** פירוש שההשתחויה היא להגיד שרוצים לאמר והאמירה צא אתה וגו'. והגם שלא הזכיר הכתוב פרט זה באותה הלילה, קצר ואמר גדולה מהאמור כאן שפרעה עצמו קם לילה וגו':
@283 **ויאמר ה' וגו** ' **לא ישמע**. הכוונה בזה אולי שחשב משה כי פרעה בראותו כל המופתים והפלאים אשר עשה משה בזה הגם שיראה כי הלכו ישראל ולא חזרו שמא תפול עליו אימתה ופחד ולא ירדוף אחרי בני ישראל, לזה הודיעו כי לא ישמע פירוש לא יקבל אליכם פירוש למה שאתם חושבים שהחליט דעתו מישראל. ואמר לשון עתיד לומר אפילו אחר מכת בכורות לא אכניע לבו לקצה האחרון לקבל לשלוח בהחלט, והטעם למען רבות מופתי בארץ מצרים כשירדפו אחריהם, ואומרו ארץ כבר אמרו ז''ל (מכילתא י''ד) בפסוק כי ה' נלחם להם במצרים וגו' יעויין שם דבריו:
@283 **עוד** ירצה להיות שאמר משה **והשתחוו לי לאמר צא אתה וכל העם אשר ברגליך** ופירוש ברגליך הוא ברשותך, הרי שהוציאם לעם מרשות פרעה ונתנם ברשות משה רועינו מלכינו ובזה גילה לו כי יציאתן ממצרים היתה בעקירת רשות פרעה מעליהם לזה אמר ה' אליו **לא ישמע אליכם פרעה** פירוש לא יבין דבריכם פרעה, והטעם למען רבות מופתי, ואם יבין הדבר מעת שיאמר לכם בלילה (י''ב ל''א) קומו צאו יחליט הדבר ואין לו מקום לרדוף אחריהם אחר כך ואין מקום למופתים שאני רוצה להרבות מאתים וחמשים מכות יסובבוהו:
@284 **ומשה ואהרן וגו' ויחזק וגו** '. כוונת הכתוב לומר שהגם שעשו את כל המופתים האלה אף על פי כן לא נתרצה לשלחם אפילו שלא בהחלט אלא לצאת מארצו לבד כאומרו (לעיל ה' ג') נלכה נא דרך ג' ימים:
@286 **החדש הזה לכם וגו'**. טעם כפל ראש חדשים ראשון הוא וגו', נתכוון לומר כי חדש זה הוא ראש פירוש מובחר שבחדשים על דרך או' (שמות ל') בשמים ראש. ודקדק לומר **לכם** כי אינו משובח ומעולה שבחדשים אלא לישראל. ותמצא שאמרו רבותינו ז''ל (ראש השנה י''א.) בניסן נגאלו בניסן עתידין ליגאל, כי החודש מסויים לטובת ישראל ועל זה ראשון הוא ראוי להיות לכם שיהיו מונים מניסן לצד מעלתו. עוד ירמוז באומרו **החודש הזה** ולא אמר חדש זה, לרמוז על הידוע שהוא הקדוש ברוך הוא דכתיב (לקמן ט''ו ב') זה אלי כי יהיה זה לכם שיגלה להם כאומרם ז''ל (מכילתא י''ד) ראתה שפחה על הים וכו'. עוד ירמוז **כי החדש הזה לכם ראש** פירוש שיהיה לישראל כינוי בחינת הראש שלא יהיו עוד נבזים ושפלים. עוד רמז בתיבת זה כי יהיה ראש לכל החדשים שהם י''ב כמספר זה:
@287 **דברו וגו' לאמר**. צריך לדעת למה הוצרך לומר דברו ולא סמך על מה שאמר בפסוק ראשון ויאמר ה' וגו' לאמר, ואם לא הספיק לו תיבת לאמר היה לו לומר דברו קודם אומרו החדש הזה כי מצוה זו לישראל לדורותם נתנה ולמה לא אמר קודם לה דברו. עוד קשה אומרו תיבת **לאמר** כי למי יאמרו ישראל. ואולי כי לצד שבמצוה זו של לקיחת השה יש בה ב' בחינות, א' לטובה כי בה נשאו ראש וראו אותם אויביהם עושים באלהיהם שפטים כאומרם ז''ל (שמות רבה פט''ז), והב' לצד המצוה כי מצות המלך היא לעשות כן והעובר עליו ענוש יענש לזה הוצרך לומר **דברו** וגו' **לאמר**, דברו לשון קושי כנגד צורך הדבר וגזירת מלך ולהעניש על כל עובר, ולאמר אמירה רכה כנגד מעלה וכבוד אשר תשיגם בדבר. ולצד שבמצוה שצוה בתחלת הנבואה שהיא לחשוב מניסן אין עונש לעובר על זה כעונש החודל מעשות הפסח ולזה לא אמר כנגדה אלא לאמר אשר על כן הוצרך לחזור ולומר דברו כנגד מצות פסח, ואמר עוד לאמר כי גם בה יש מעלה לישראל כנזכר. ובדרך דרש צום להנהיג את ישראל בהנהגת התורה והמצות להודיעם חוקי ה' ותורותיו ולהנהיגם בדרך ישרה, ולזה אמר דברו ואמר לאמר פירוש כדי שיהיו מעולים, על דרך אומרו (ישעי' ג') אמרו צדיק וגו':
@287 **עוד** ירצה כי מתחלה ידבר אל הזקנים כמו שמצינו לו שכן עשה משה דכתיב (פסוק כ''א) ויקרא משה לכל זקני ישראל, והוא אומרו **דברו אל כל עדת ישראל**; **לאמר** שיאמר להעם, והוא גם כן מה שאמר שם הכתוב ויאמר אליהם:
@287 **ויקחו להם וגו'**. קשה למה אמר ו' בתחלת ענין. ואולי כי רמז לדברים הנאמרים בדברי משה לישראל דכתיב משכו וקחו וגו' ואמרו רבותינו ז''ל (שמות רבה שם) משכו ידיכם מעבודה זרה וגו', ודבר זה לא נאמר בדברי ה' והנה מדברי משה נשמע כי כן נאמר לו בנבואה, והוא אומרו ויקחו בתוס' ו' רמז שקדם דיבור ומה הוא משכו שאמר משה. עוד ירצה להיות שאמר בעשור יכול לקח בעשור ישחט לא לקח בעשור לא יקח בי''א בי''ב בי''ג, תלמוד לומר ויקחו לרבות אחר כך ובמכילתא (כאן) למדו דין זה של לקיחה בי''א בי''ב בי''ג מדין קל וחומר ודבר הבא בקל וחומר אם נמצא לו רמז בכתוב נסכים לומר כי לזה נתכוון. עוד ירמוז בדקדוק עוד תיבת להם. עוד אומרו תיבת **איש** שלא היה צריך לומר אלא ויקחו שה לבית וגו', אכן ירצה על דרך אומרים ז''ל (תנחומא) בפסוק ויקחו לי תרומה וזה לשונו אמר הקב''ה קחו אותי עמכם, והוא אומרו כאן לצד כי זו מצוה ראשונה הודיעם השגת המצוה כי בעשותה ישרה עליו ה' שכינתו בסוד (דברים כ''ח י') וראו כל עמי הארץ כי שם ה' נקרא עליך, גם אמרו כי תיבת מצוה יש בה שם הוי''ה חצי בא''ת ב''ש וחצי בפשוט (תיקוני זוהר תיקון כ''ט) והוא אומרו **ויקחו להם איש** פירוש על דרך אומרם ז''ל (סוטה כ''ט מ''ב:) איש אין איש אלא הקב''ה, כי במצוה זו יקחו להם לקיחה גדולה ועצומה והוא איש שהוא אלהינו מלכנו:
@287 **וראיתי** לתת לב למה לא צוה ה' בפסח מצרים על הטמאים והערלים ובני הנכר שלא יאכלו מפסח, הן אמת כי אזהרת הטמאים לפי מה שכתבנו בפרשה זאת חקת התורה יש טעם נכון בדבר, אבל הערלים ובני הנכר למה לא צוה אותם ה'. והנה לפי דבריהם ז''ל הוזהרו ישראל על שניהם על המילה כאמור בדברי קבלה (יחזקאל ט''ז) ואראך מתבוססת בדמיך, ואמרו רבותינו ז''ל (שמות רבה י''ט) דם פסח ודם מילה, ועל בן נכר דרשו רז''ל (שם ט''ז) בפסוק משכו וגו' משכו ידיכם מע''ז הרי שהזהיר על הדבר כי קודם מצות הפסח יצאו מכלל עובדי עבודה זרה ויכנסו בכלל ישראל, וכל זה אינו מספיק לקושייתינו כי למה לא באו הדברים בדברי ה' בעיקר המצוה:
@287 **והנה** בסוף הפרשה אחר שסדר יציאת ישראל ממצרים נאמרה פרשת זאת חקת הפסח וגו' כל בן נכר וגו' וכל עבד וגו'. וראיתי לר' אברהם בן עזרא ז''ל שכתב כי פרשה זו נאמרה לפסח דורות והוסיף מצות אחרות וכו', ואם נתכוין לומר כי בן נכר וערל הם מצות מוספות בפסח דורות דבריו כאן בטלים הם כפי דברי רבותינו ז''ל, וגם ממה שגמר אומר הכתוב שם בפרשת ערל ובן נכר ואמר (פסוק נ') ויעשו בני ישראל כאשר וגו', ואם לפסח דורות נאמרה פרשה זו לא היה לו לומר ויעשו בני ישראל כאשר צוה וגו' שמשמע שעשו ישראל כל האמור בפרשה, גם מה שאמר שיכוין על פסח שעשו במדבר סיני הם דברים בעלמא ומי ישמע אליו ואין צריך לומר לקבל דבריו בזה, הגם שהרב ז''ל חש לקמחיה ואינו חולק על דברי רבותינו אלא בדבר שאין בו הוראה לעתיד אף על פי כן גם במה שלפנינו חולק בלא עומק המכריח וכיוצא בו:
@287 **וראיתי** לרבותינו ז''ל במכילתא שאמרו וזה לשונם זאת חקת הפסח בפסח מצרים ובפסח דורות הכתוב מדבר דברי רבי יאשיה רבי יונתן אומר בפסח מצרים הכתוב, מדבר אין לי אלא פסח מצרים פסח דורות מנין תלמוד לומר ככל חוקותיו וגו' יעשו אותו על כרחם, הרי דלכל דעת התנאים בפסח מצרים הכתוב מדבר ונעקרו דברי ר' אברהם בן עזרא והיו כלא היו, ולפי זה אפשר שירמוז הכתוב באמרו **ויקחו** פירוש מלבד מצות מילה ומצות משיכתם מעבודה זרה שהוא בחינת בן נכר שצוה ה' הוסיף. עוד לומר ויקחו וגו', ואומרו **להם** כאן רמז שלילת בן נכר וערל שלא יוכלו לאכול בפסח כמו שבא הדבר מבואר בנבואת זאת חקת הפסח:
@288 **ואם ימעט וגו'**. הכתוב יתיישב בין לדעת ר' יהודה ובין לדעת ר' יוסי שנחלקו בתורת כהנים (מכילתא, פסחים צ''ט.) לרבי יהודה שאמר צריך שישאר אחד מבני חבורה ראשונה ידוייק אומרו **ימעט הבית** פירוש שיתמעט. מהחבורה ולא כל החבורה, ולרבי יוסי שאמר שלא יניחו הפסח כמות שהוא ידוייק אומרו **מהיות משה** שמעט שה יתמעט ממנויים ועליו הוא ההקפדה שלא ישאר בלא מנויים, והכתוב שקול הוא:
@288 **עוד** נראה שיכוון לומר שאין דרך שיהיה השה מועט לאוכליו כי כזית בשר ימצא בו לרבים שיהיו בחבורה:
@288 **או** ירצה כי ברכת הקודש מרובה הוא וימצא בו שיעור הצריך למנוייו ולא ימצא המיעוט אלא בבית שהם בני חבורה שלא יספיקו לאוכלו:
@288 **לפי אכלו תכוסו**. יתבאר על דרך אומרם ז''ל (פסחים פ''ח.) שוחט אדם על ידי בנו ובתו הקטנים וגם על ידי אשתו, גם אמרו (שם פ''ז:) אם היא למודה לבא אצל אביה אוכלת משל אביה לצד היותה רגילה לאכול שם, והוא אומרו **איש לפי אכל**. ו פירוש על אותם שהם רגילים לבא אצלו לאכול וסומכים על שלחנו לפי מה שהם ימנה עמו ושם קנו מקומם:
@288 **עוד** יתבאר על דרך אומרם (שם צ':) שאונן שוחטין עליו הגם שבשעת שחיטה אינו ראוי כיון שיכול לאכול בלילה שוחטין עליו, והוא אומרו **לפי אכלו** פירוש הולכין ונמנין בשעת שחיטה על שעת אכילה:
@288 **עוד** ירצה **לפי אכלו** על פי מה ששנינו בפסחים (שם) זב וכו' שוחטים עליו וגם אמרינן התם שוחטין וזורקין על טבול יום ומחוסר כיפורים ועולא אמר אף על טמא שרץ עד כאן, והטעם הוא כל שיכול לאכול את פסחו בעת אכילתו, והוא אומרו **לפי אכלו** פירוש אין הולכים בו אלא לפי אכילתו של פסח וכל שבשעת אכילתו הוא ראוי לאוכלו הגם שבשעת שחיטה לא היה ראוי שוחטין עליו, ולפי זה הוא הדין טמא מת אם היה יום ז' שלו חל ביום י''ד שוחטין עליו ואוכל לערב:
@288 **ומה** שאמרו שם בתורת כהנים והובא בפסחים דף צ' סברת תנא שסובר כי ולא יכלו לעשות הפסח ביום ההוא (במדכר ט' ו') יום ז' שלהם היה ואף על פי כן נדחו לפסח ב', דוקא טומאת מת דחמירא ולזה אמר (שם) לנפש אדם הגם שלערב היו טהורים. ולר' יוסי הגלילי (שם) נוכל לומר שאפילו טמא מת שחל ז' שלו ביום י''ד שוחטים עליו. ומה גם אם טבלו וכדעת התוספות בפסחים דף צ' ולדעת הראב''ד שהשיג על רמב''ם בפ''ו מהלכות קרבן פסח יעויין שם דבריו והוא היותר קרוב לפשטא דסוגיא:
@289 **ומן העזים תקחו**. טעם שהוצרך לומר **תקחו** לומר אפילו יש כבשים יכול ליקח מן העזים, לזה סמך לקיחה לעזים:
@290 **והיה לכם למשמרת**. פירוש צריך שמירה כדין קדשים כיון שקרא עליו שם פסח. עוד ירמוז על דרך אומרם ז''ל (שיד השירים רבה פ' כשושנה בין החוחים) בפסוק גוי מקרב גוי שהיו ישראל במצרים סרוכים קצת בחוקי עבודה זרה מצד היותם בין המצריים, ואמרו עוד (שמות רבה פט''ז) שרמז הכתוב באומרו משכו שימשכו מעבודה זרה. והנה אין כוונתם ז''ל לומר חס ושלום שהיו עובדי עבודה זרה אלא לצד שהיו ביניהם מבלי ידיעתם יעשו חוקים של עובדי עבודה זרה בפרטי המלבושים והמאכלים ודברים הרגילים, ואשר על כן מלבד שצוה שיעקרו מאותם פרטים שידמו להם נתחכם עוד אל עליון לעקור בחינת הרע מהם ולעשות תיקון עון זה ואמר שיקחו הטלה שהיא עבודה זרה של מצרים שבה היה לישראל המכשולות ויעשו בה מצוה האמורה בענין ובזה יהיה להם תיקון לשמירת עון עבודה זרה, והוא אומרו **והיה לכם למשמרת** פירוש במקום מצות שמירת עבודה זרה כשינהגו בו משפט כתוב והבן:
@292 **ואכלו את הבשר**. רבותינו ז''ל (פסחים פ''ג.) אמרו את הבשר ולא גידים ועצמות קרנים וטלפים. ולדבריהם למה אמר את מה בא לרבות. ונראה כי בא לרבות מה שאמרו במשנה (שם פ''ד.) כל הנאכל בשור הגדול נאכל בגדי הרך, ומפרש לה רבא כל הנאכל בשור הגדול בשלקא וכו':
@292 **עוד** ירצה על פי מחלוקת ר' יוחנן ודיש לקיש (שם) בגידין שסופם להתקשות לר' יוחנן נמנין ולריש לקיש אין נמנין. לר' יוחנן יתבאר הכתוב על זה הדרך את הבשר כל שדמו לבשר שעמהם קאמר והרי הם דומין, ולריש לקיש כל שדומין לבשר בבחינת הבשר מצד עצמו וכשם שהבשר אין סופו להתקשות וכו':
@292 **ומצות על מרורים**. לפי פשט הכתוב לפי מה שראינו שאמר ה' שצריך צלי אש ושיהיה שלם כו' זה יגיד שדעת עליון הוא להראות בחינה הגדולה והחירות ואין רשות אחרים עליהם, ולפי זה גם המרורים שיצו ה' הוא לצד כי כן דרך אוכלי צלי לאכול עמו דבר חד כי בזה יערב לחיך האוכל ויאכל בכל אות נפשו. גם בזה יוכר גודל העריבות כשיקדים לפיו מרורים. גם מה שהזכיר המצות הוא פרט אשר יכונן חיך אוכל יטעם לו הצלי. והנה ג' השריגים יטעימו יחד והוא רומז לג' דברים, הא' הוא הגלות שמררו את חייהם, הב' היא היציאה תיכף ומיד שלא הספיק בצקם להחמיץ במצרים, ג' אשר פסח ה' על בתיהם והוא בחינת הגאולה כי עבר ה' בארץ מצרים ונתק חבל מוסרות העבות שהיו תוקפים בהם שהוא בחינת הבכורה וכמו שפירשתי הענין במקומו (לעיל י''א ה'). ושלשת הענינים יחד היו צריכין להיות וזולת א' אין נס בשנים האחרים, שאם לא היה הגלות לא היו משיגים אשר השיגו מהצירוף ומה שבררו, ומה גם לפי מה שכתבנו במקומות אחרים (ויגש מו ג) כי גוי גדול עצמו שהוציא ה' ממצרים הם בחינות ניצוצי הקדושה ששם היתה ושם נמצאת, וסגולת הוצאתה הוא המרור אשר מררו את חייהם, והוא סוד אומרו (קהלת ח') עת אשר שלט האדם באדם לרע לו. ואילו לא היה המהירות שהוציאם ה' היו חוזרים ומשתקעים בוררים ומתבררים, והוא מאמר התנא (הגדה) ואלו לא הוציא וכו' עדיין וכו' והיינו עבדים לפרעה וכו' דכתיב (לקמן יב לט) ולא יכלו להתמהמה, ועיקר הגאולה היא הפסיחה. נמצאת אומר כי שלשתם יחד הם העיקר, ולזה היה הלל מדקדק לכורכם יחד (פסחים קט''ו.):
@297 **ולא יהיה וגו' למשחית**. פירוש לסיבת משחית שיוצא להשחית בזולת אין בו אלא בחינת טבע ההשחתה לכל זולת בראות חותם שמו יתב' שהוא המצוה יפחד וירא מגשת אליו, לזה הוא שצוה ה' להיות הדם לאות. ואם תאמר אם כן מצרי שהיה נחבא אל בית ישראל יהיה ניצול תלמוד לומר בכם ולא במצרים כי לא תאיר אור המצוה להצלה אלא על ישראל דכתיב (ישעי' ס') ועליך יזרח ה' וכבודו עליך יראה:
@298 **חקת עולם תחגוהו**. טעם שלא הספיק לומר לדורותיכם. והגם שאמרו ז''ל (מכילתא) כי דורותיכם לבד הייתי אומר מיעוט רבים שנים תלמוד לומר חקת עולם לגלות על פירוש דורותיכם שהוא תמיד עדיין קשה לא היה לו לומר לדורותיכם אלא חקת עולם. אכן יתבאר על דרך האומר (ברכות י''ב:) למען תזכור את יום צאתך מארץ מצרים כל ימי חייך להביא לימות המשיח, ולמאן דאמר כל ימי חייך הלילות אפשר כי אמר חקת עולם שלא תאמר תינח בימי החירות בימי הגלות שאנו משועבדים מה מקום לזכרון לטובה שפסקה תלמוד לומר חקת עולם אפילו בזמן השעבוד בשאר גליות חקה חקק ה'. ומאמצעות פירושם זה תשכיל גם כן הסרת טענת לדורותיכם שאין כוונתו ב' דורות. ואם לא היה אומר לדורותיכם לא היינו שומעים מה שפירשנו בחקת עולם והיינו אומרים שלא בא אלא להתמדת דורות ולא לב' דורות לבד הנשמע מתיבת לדורותיכם ומהייתור שמענו מה שפירשנו:
@299 **שבעת ימים**. הנה הטעם הוא לצד שלא הספיק בצקם להחמיץ וגאלם הגואל. ואם תאמר והלא היוצאים עדיין לא יצאו לעשות זכרון לדבר. הלא גם הפסח שצוה ה' לקחת שה לבית אבות וגו' עדיין לא פסח אלא שבזכות מצוה זו יפסח ה', גם המצה בזכות מצוה זו ימהר לגואלם, וכן היה:
@299 **ותמצא** שאמרו רבותינו ז''ל (פסחים ק''כ.) מדרשות התורה בא' בי''ג מדות כי כל שבעה אין חיוב במצה אלא לילה הראשונה קבעו הכתוב חובה, והטעם כי גם בחינת המצוה לא היה אלא בליל ט''ו וזה נקבע לחובה בזמן עצמו ומאז והלאה אין כיוון בנס למצוה והבן. וטעם אומרו שבעת ימים מצות אינו אלא רשות. ואולי שדיבר בסדר זה לומר כי מעלה עליו הכתוב כאלו אכל כל ז'. ותמצא כי צוה ה' ב' מקראי קודש ביום הא' וביום הז' יום א' לצד נם יום ט''ו, ויום ז' לצד נם גמר הגאולה של קריעת ים סוף וכו'. עוד טעם אומרו **שבעת** לצד שלא צוה ה' בכל ז' לאו דלא תאכל חמץ והייתי אומר אם לא אכל חמץ אין בידו לא זכות ולא עונש תלמוד לומר שבעת ימים תאכל מצות לומר לך כי כשלא אכל חמץ כאלו אכל מצות והרי בידו ז' מצות עשה. וטעם ז' ולא פחות ולא יותר, נתכוון ה' שיהיו עסוקים במצות עד גמר הגאולה שהוא ביום ז' של פסח אשר הפליא ה' עשות נסים להם וברודפיהם משפטים. גם יש טעם ברוחניות כי יסודי הקדושה שהם שורש נשמות ישראל שבעה עינים (זכרי' ג), ותקרא כנסת ישראל בת שבע לסיבה זו (זהר ח''ג ו':) (יז) **ושמרתם את המצות וגו'**. פי' כשם שאני שמרתי היום ולא אחרתי יום אחד ובעצם היום הזה הוצאתי אתכם לטעם זה אתם גם כן לא תאחרו המצה עד שתחמיץ. ואמר עוד **ושמרתם את היום הזה** יצו כן האל גם כן שיהיה האדם משמר גם היום לבל יטעה בחשבון ולא יקדים ולא יאחר מעשות את היום הזה ולא יום אחר במקומו. וכל פי' זה אומ' **כי בעצם** יאיר ימין ושמאל, יאיר לתת טעם למה שלפניו לשמידת המצות, ויאיר למה שלאחריו לשמירת היום על זה הדרך כי בעצם וגו' פירוש לטעם שבעצם היום וגו' ושמרתם אתם גם כן את היום הזה:
@305 **ויקרא משה לכל זקני ישראל**. והגם כי ה' אמר אליו דברו אל כל עדת ישראל, יהיה פירושו כמאמר (ויקרא ד' י''ג) ואם כל עדת ישראל ישגו שיאמר על הזקנים כמו שמפורש במקומו (בתורת כהנים), ויאמר אליהם יכוין לשאר העם כמשפט כל מצות ה' לישראל שהיו מפי משה (עירובין נד.):
@305 **או** אפשר שלא אמר אלא לזקנים והם ידברו לכל עדת ישראל, וחלוקה מצוה זו משאר מצות התורה כי עדיין לא נכנסו ישראל בברית ולא הוחנכו להכנם לשמור ולעשות ולזה היה מדבר לזקנים והזקנים כל א' ידבר בנחת ובדרך המתקבל לבני משפחתו כדי שיהיו נוחים לעשות:
@308 **ושמרתם את הדבר הזה**. הנה פשט הכתוב יגיד כי גם לדורות יצו דברים האמורים בענין ולא ראינו שעשו כן קדמונינו, גם רבותינו לא צוו לעשות כן. ונראה כי ממה שאמר הכתוב **לחק לך** בפני עצמו וחזר לומר **ולבניך** גילה המכוון שהוא על זה הדרך שאין הדברים שוים בו ובבנו שהיה לו לומר ושמרתם את הדבר הזה לחק עולם, ומאומרו לחק לך ולבניך הרי זה מפרש המכוון שאינם שוים בדבר, לחק לך הוא כל האמור בענין. ולבניך עד עולם פרטים מהענין, וסמך הכתוב על שיבא במקומות אחרים הפרטים שהם נוהגים לדורות ושלל בהם פרטים שאינם לדורות שלא הזכירם בהם, וגם כאן ביאר הדברים באומרו ולא יתן המשחית לבא אל בתיכם לנגוף שינגוף את מצרים ודבר זה אינו מצוי לדורות:
@309 **והיה כי תבואו וגו'**. הנה פשט הכתוב יגיד כי מצוה זו אינה אלא אחר כניסתם לארץ, אם כן למה חזר ה' מדעת זו וצוה את בני ישראל (במדבד ט א) בשנה השנית לעשות הפסח במועדו ככל חקותיו:
@309 **ונראה** כי גילה ה' דעת עליון בזה כי היה בדעתו אם יזכו ישראל לא יעשו פסח ב' אלא בארץ כנען אלא לצד המראתם מעת יצאו ממצרים והם ממרים פי ה' ואפילו בים סוף התחילו למרות דכתיב (תהלים ק''ו) וימרו על ים בים סוף זה היה סיבה שארכו הימים ולא היה להם זכות לעלות תיכף ומיד, ולזה כשראה ה' שגרמו מעשיהם ולא נכנסו לארץ והם עדיין במדבר הוצרך לצוות לעשות הפסח במדבר כי עד עתה לא נצטוו אלא כי תבואו אל הארץ. והגם כי האדון קורא הדורות מראש (ישעי' מ''א), אף על פי כן מחשבותיו הטובים הגיד לעמו כנזכר:
@312 **וילכו וגו' כן עשו**. הוצרך לומר **כז עשו** ולא הספיק במה שקדם לומר ויעשו וגו', לומר הצדיקו במעשיהם במצות ה' ולא הבינו דבר שלא כן הוא במשמעות, וזה לא היה נשמע מאומרו ויעשו וגו' כאשר וגו' כי אפשר שהכתוב אומר מה שחשבו הם והבן:
@314 **ויקם פרעה לילה**. טעם אומרו **לילה** יתבאר על ררך אומרם ז''ל (זהר ח''ב ל''ח.) כי אותו לילה היה כיום יאיר כצחות היום. ורמזתי רמז זה בפסוק (לקמן יג ח) והגדת לבנך ביום ההוא כי יכוין לומר שיגיד לו גם נס הלילה שנעשה יום. ושמא תאמר כי זרח אור בלילה דרך כלל לרעים ולטובים. לזה אמר **ויקם פרעה ליל**. ה כשקם הוא לקרוא למשה ולאהרן מנע ה' מרשע אורה והיה לילה פירוש חשך כאומרו (בראשית א ה) ולחשך קרא לילה:
@315 **ויקרא למשה וגו' לילה**. טעם אומרו פעם ב' **לילה**;. אולי להיות כי חש פרעה בקריאתו למשה שלא יצא לקראתו מחשש גזירתו שאמר לו (לעיל י כח) אל תוסף ראות פני כי ביום ראותך פני תמות ואם כן יחוש לבל יעליל עליו, לזה אמר בקריאתו לילה פירוש אין זה מתנאי הגזירה כי הוא לא אמר אלא ביום ולא בלילה וזמן זה לילה הוא. או לצד שלא יראה פניו הוא אומר כי הוא לילה ואין כאן טענת אל תוסף ראות פני כי הוא במחשך לא יראו איש את וגו':
@315 **או** יכוין הכתוב לומר תשובת משה אל פרעה כשקרא לו כי ענהו ואמר לו לילה ואין אני יכול לצאת לדבר עמך כי צוה ה' (פסוק כב) לא תצאו איש מפתח ביתו עד בוקר, ואמר פרעה **קומו צאו** וגו' פירוש עשאם בני חורין לעצמן, ואולי שרמז בתיבת **קומו** לשון התקוממות ונשיאות ראש על דרך מה שדרשו רבותינו ז''ל (כ''ר פג''ח) בפ' (כראשית כג) ויקם שדה עפרון, וחשב כי בזה תקל המכה מעליו כשיגמור הדבר מצידו לשלחם הגם שיבא העיכוב מהם אין עליו אשמת דבר:
@315 **עוד** ירמוז באומרו **קומו צאו** כי לצד שלא היו רוצים לצאת אליו קראם לקום כי חשב שאינם רוצים לקום ממטתם לבוא אצלו ואמר כי קריאתו להם הוא להנאתם שאומר להם צאו וגו'. ולדרך זה טעם אומרו לילה, הקדים הכתוב לומר טעם שלא יצאו לקראתו תיכף ומיד וה' צוה על כבוד המלכות לזה הקדים סיבה אשר סבבה עכבתם מצאת ואמר לילה וזו סיבה שלא קמו ויצאו אצלו כי ה' צוה לא תצאו איש מפתח ביתו וגו':
@315 **גם אתם וגו'**. צריך לדעת למה אמר גם בתחלת דבר. ועוד וכי משה ואהרן היו אסורים שהוצרך לומר צאו מתוך עמי. ואולי כי מתוך דבריו גילה מחשבתו כי היה חפץ שיוצגו משה ואהרן לזה אמר **גם אתם** מלבד ישראל, ולצד שאין הדבר מובן בתיבת גם שהיא על ישראל כי לפי האמת משה לא היה במאסר וכשאמר גם אין במשמעות הקודם בני ישראל ולא יוצדק לומר גם אתם אלא לפי מחשבת פרעה כנזכר, לזה חזר לבאר **גם בני ישראל**:
@315 **עוד** ירצה כי נתכוון לגרש אותם הגם שיחפצו מרצונם לשבת עמהם, ולפי זה יוצדק לומר **גם אתם** הגם שאתם ברשות עצמכם אף על פי כן אין אני חפץ שתשבו בארצי, וזה חידוש, והוא מה שאמר ה' (י''א א') כשלחו כלה גרש יגרש אתכם. ואומרו **גם בני ישראל** לרבות הטף והנשים, ואומרו **גם צאנכם** וגו' לרכות שאר מקנה או לרבות מה ששאלו לעזר ממנו:
@316 **וברכתם גם אותי**. כאלו אמר וגם תברכו אותי, ושיעור הכתוב וברבתם גם כן אותי מלבד שיסיר המכה הרחקת הנזק והקרבת התועלת:
@319 **עשו כדבר משה**. פירוש לא להנאת הממון אלא למצות נביא. עוד ירצה על פי מה שהעלה רמב''ם בפרק ט' מהלכות יסודי התורה כי אם יבא נביא ויאמר לישראל על פי ה' לעבור על מצוה אחת הוראת שעה כאליהו בהר הכרמל וכדומה שומעין לו חוץ מעבודה זרה, והוא אומרו **ובני ישראל עשו** ולצד כי מעשה זה הוא מעשה בלתי הגון לגנוב דעת גוי, גם לגזול ממונם, ואיך יצדיקו ישראל לאומר להם עבור עבירה לזה אמר על פי משה פירוש אשר הובחן לנביא ובפרט זה יאמנו דבריו כנזכר:
@320 **וישאילום וינצלו וגו'**. פירוש לצד שנתן ה' חן העם בעיני המצרים ובזה היו המצרים משאילים אותם בעל כרחם ומחמת זה הצדיקו הדברים כי אין כוונתם ללכת בהחלט שאם כן היו מבקשים הם לקחת מהם להרויח יותר ובזה וינצלו את מצרים. והנה המשכיל על דבר יראה כי פועל אדם ישולם לו (ברכות ט:) כי לצד שישראל חבבו דבר היציאה ולא חששו להנאת ממון הוא הדבר והוא הסיבה שהפליאו להרויח וזכותם עומדת להם:
@323 **מצות כי לא חמץ**. פירוש הטעם שאפוהו מצות כי לא הותר להם לאכול חמץ לזה מהרו לאפותו מצה. והגם ששהה מעת לישה עד עת אפיה זמן מה. אולי כי היו מתעמלים בו, ולזה אמר הכתוב משארותם צרורות בשמלותם על שכמם, וכי לא היה להם מקום לשאת אותם שהוצרכו לתתם על שכמם, אלא כדי שיתעמלו בהם וכל זמן שמתעמלים בעיסה אינה מחמצת נוסף על שלא נתנו בו שאור לחמץ. ונתן הכתוב טעם **כי לא חמץ כי גורשו ממצרים** וגו':
@325 **ויהי מקץ וגו'**. ולא אמר הכתוב מה היה, ואם נתכוין על היציאה הרי חזר ואמר פעם ב' ויהי בעצם. עוד צריך לדעת מה צער ירמוז בתיבת **ויהי**. ואולי כי יגיד הכתוב הצער של עכובם עד הקץ ולא היה בהם זכות לצאת קודם הקץ. או לרמוז כי הצער שהיה לישראל במספר המוזכר למעלה דכתיב ומושב בני ישראל וגו' לא כל הזמן ההוא אלא מקץ:
@325 **ויהי בעצם**. רמז הצער של יציאת היוצאים עמהם שמהם סבבו רעות. או לרמוז כי לא חדלו המכות והצרות ממצרים גם בעצם היום הזה, וכן הוא אומר (במדבר ל''ג) ומצרים מקברים וגו' ובני ישראל יוצאים ביד רמה (י''ד ח'):
@326 **ליל שמורים וגו'**. יכוין הכתוב לרמוז ה' נסים מופלאים שזמנם לילה זו. א, בימי אברהם כשהכה את ד' מלכים (לר יד טו) ויחלק עליהם לילה. ב, ביציאת מצרים דכתיב (פסוק כט) ויהי בחצי הלילה. ג, בימי חזקיה כשהכה גבריאל מחנה סנחריב דכתיב (מ''ב י''ט) ויהי בלילה ההוא. ד, בימי מרדכי ואסתר (אסתד ו) בלילה ההוא נדדה שנת המלך. ה, גאולה העתידה. כנגד נס אברהם אמר **ליל שמורים הוא לה'** כי באמצעות הנס נתגלית אמתתו יתברך כאומרם ז''ל (בראשית רבה פמ''ב) שיש מהאומות שלא היו מאמינים בנס הצלתו מאור כשדים והאמינו בנם הכאת ד' מלכים. וכנגד מצרים אמר **להוציאם מארץ מצרים**. וכנגד נס חזקיהו אמר **הוא הלילה** הידוע לכם כרשום בדברי נביא (מ''ב י''ט) ויהי בלילה ההוא ויצא מלאך וגו'. וכנגד נס מרדכי אמר **הזה לה'**, וכנגד גאולה העתידה אמר **שמורים לכל בני ישראל לדורותם** פירושו לסוף הדורות בעגלא ובזמן קריב:
@327 **ויאמר ה' וגו' זאת חקת הפסח**. קשה למה לא אמר דבר אל בני ישראל כסדר האמור בכל מצוה ומצוה. ולפי מה שכתבנו (לעיל פסוק ג) כי פרשה זו נאמרה בי''ד בניסן לא הוצרך לומר דבר כי היא סמוכה עם דברו אל כל עדת ישראל שאמר שם. ויש לתת טעם למה לא נכתבה במקומה. כי לצד שמצוה זו בשלימות ישנה כפסח דורות נאמרה אחר יציאת מצרים לומר כי כל זה בשלימות מעכב לדורות:
@327 **וראיתי** מדרש רבותינו (שמות דבה פי''ט) שהוציא ה' רוח''מגן עדן ובשם פסחו של משה ונתקבצו כל ישראל ואמרו לו משה רבינו בבקשה האכילנו מפסח שלך אמר להם אם אין אתם נימולים אין אתם אוכלים דכתיב זאת חקת הפסח וגו' מיד נתנו עצמן ומלו וכו' עד כאן. הנה לפי מדרש זה לא קשה למה לא אמר דבר וגו' או לאמר כי פרשה זו למשה ולאהרן נאמרה וצוה אותם כל בן נכר וגו' ואחר שבאו ישראל לצד אכילת פסחו של משה המבושם מלו עצמם:
@327 **וקשה** לדברי המדרש איך יכול ליתן להם מפסחו והלא אין הפסח נאכל אלא למנוייו. ואולי שאמר להם כן כדי שימולו וכשימולו יהיה כמו כן פסחיהם כפסחו של משה מבושם. וראיתי ראיה לדברי המדרש שלא רצו למול ממה שאמר ביחזקאל (כ') וימרו בי ולא אבו לשמוע אלי וגו' ואומר לשפוך חמתי עליהם בתוך ארץ מצרים, הרי שלא קבלו עשות מצותיו יתברך:
@332 **וכי יגור אתך גר**. כאן הסכים על קבלת גרים מהערב רב כדעת משה. והוא אומרו **אתך**. עוד רמז דעת עליון כי לא הסכימה על הדבר אלא לרצון משה ה' חפץ כאומרם ז''ל (שמות רבה פמ''ב). והוא אומרו **אתך גר** פירוש עמך הוא גר שאין אתה בקי בנסתרות ולא מחשבותי מחשבותיכם, וצא ולמד מה עלתה בידם מהם:
@332 **המול לו כל זכר**. פירוש כשם שמילת עבד מעכבת בישראל שלא יאכל גם הגר מילת עבדיו וגו' מעכבת אותו עד שימול לו כל זכר. ואומרו **ואז יקרב** וגו'. פירוש לא יצטרך שישחטו אחרים עליו אלא הוא בעצמו יקרב לעשותו **והיה כאזרח** וגו':
@335 **ויהי בעצם וגו'**. הודיע הדבר בסמוך לעשית פסח. לומר כי זה גורם גמר היציאה, כי זולת זה לא היה בידם מצוות לצאת כאומרם ז''ל (שם פי''ז) בפ' ואעבור עליך וגו':
@340 **והיה כי יביאך וגו'**. טעם שתלה מצוה זו בביאת הארץ, לטעם עצמו שכתבנו בפסוק (לעיל י''ב כ''ה) והיה כי תבואו אל הארץ, או כדי שלא ישכח באורך הימים שם כשירבו ימיהם על האדמה:
@343 **והגדת לבנך וגו'**. צריך לדעת למה לא אמר ואמרת כי תיבת הגדה מצינו לרבותינו ז''ל שאמרו (שבת פ''ז.) שיתכוין בה דברים קשים כגידים. עוד קשה אומרו **ביום ההוא** ובסמוך גמר אומר בעבור זה ודרשו רבותינו ז''ל (מכילתא ובהגדה) בשעה שמצה ומרור וגו' והוא בלילה ולא ביום ואם כן לא היה לו לומר אלא ובגדת לבנך לאמר בעבור זה ואני יודע זמן ההגדה שהוא בלילה. עוד צריך לדעת אומרו **לאמר** והוא כבר אמר והגדת:
@343 **ונראה** כי יכוין על דרך אומרם ז''ל (פסחים קט''ז:) מתחיל בגנות ומסיים בשבח, יאמר גנות אבותיהם של האבות כי לא היה דבר משובח, והוא אומרו **והגדת** דברים קשים שלב האדם נעקש מהם, ואחר כך מסיים בשבח, והוא אומרו **לאמר** אמירות משובחות משמחים את הלב ומסעדים אותו, ואמר **ביום ההוא** הודיע במתק לשון צדיק כי הלילה ההוא יום יקרא לא לילה והוא אומרו (תהלים קל''ט) ולילה כיום יאיר, ולא חש שתטעה לומר יום ממש ממה שגמר אומר בעבור זה שהוא בשעת מצה כו' כאומרם ז''ל. ואולי כי סמך ביום ההוא עם והגדת כי גם נס זה בכלל מצות ההגדה:
@343 **עוד** ירצה באומרו **לאמר** להיות שאמר והגדת לבנך תינח אם יש לו בן אם אין לו בן יהיה פטור תלמוד לומר לאמר שעל כל פנים צריך להגיד אפילו בינו לבין עמו. ואם תאמר כיון שעל כל פנים הוא צריך להגיד אפילו בינו לבין עצמו אם כן למה אמר לבנך. ואולי שבאמצעות היתור אני מבין כן ולא בלא יתור. ואפשר עוד שירמוז באומרו **והגדת לבנך** שאם יגיד הגדה האמורה בנין יזכהו ה' שיגיד לבנו וכדי שלא תטעה לומר דוקא, לזה אמר לאמר:
@343 **בעבור זה**. אולי שרמז בתיבת זה י''ב מצות הרשומים בחג הפסח, ג' דברים פסח מצה ומרור, והגדה, וז' ימי החג, וקידוש יום א' וב', הרי י''ב כמספר ז''ה, והוא אומרו **בעבור זה עשה** וגו', והגם שז' ימי החג לענין תרי''ג מצות אינם נמנים לז' מצות:
@346 **והיה כי יביאך וגו'**. אמר **והיה כי יביאך** וגו' לומר שלא ישכח מצות ה' כי ירחיב ה' גבולו וישמן ויבעט, ולא חש לומר כי דוקא בארץ, לצד שהיא מצוה התלויה בגוף ואמרינן בקדושין (ל''ו:) שכל מצוה שהיא תלויה בגוף אין חילוק בין בארץ בין בחו''ל:
@349 **והיה כי ישאלך** וגו'. פירוש בשעה שיראה בנך ענין פדיון בכור אם ישאלך אתה חייב לומר לו אבל בלא שאלה אין חיוב אלא בליל פסח. ולזה דקדק לומר **מחר** פירוש אפילו למחר דהיינו כל זמן שיהיה, ואמר **לאמר** פירוש שתהיה כוונתו בשאלה שתאמר אליו אז הוא שתשיבהו בדרך האמור, אבל אם יאמר מה זאת בדרך זלזול לא לכוונת התשובה לא תשיבהו כזה:
@349 **עוד** ירצה שאין צריך שתהיה השאלה בלשון זה מה זאת אלא הגם שתהיה באיזה אופן שתהיה כל שהמכוון של השאלה הוא לאמר מה זאת, נמצינו אומרים כי פסוק זה שלא בליל פסח נאמר אלא במצות קדושת פטר רחם ואין צורך בהגדה זולת על ידי שאלה, ורבותינו ז''ל (מכילתא) אמרו כנגד ד' בנים כו' זה דרך דרוש:
@351 **והיה לאות על ידכה וגו'**. רבותינו ז''ל (מנחות ל''ז) אמרו ידכה יד כהה שהוא יד שמאל, וצריך לדעת מדוע לא בחר ה' ביד ימין לעשות בו המצוה כי הוא המשובח, ורבותינו אמרו (שם) להיותו מכוון כנגד הלב שבצד שמאל, ודבריהם אמת, אלא שנראה לי לתת טוב טעם כי הכתוב עצמו נתן טעם הדבר במה שכתב **כי בחוזק יד**, כי יש לך לדעת כי האדון ברוך הוא יש במדותיו ב' בחינות, הא' תקרא יד הגדולה, והא' תקרא יד החזקה, היד הגדולה היא צד החסד והטוב, והיד החזקה היא הגבורה המשלמת לעושה רעה כרעתו, והנה בהוצאת ישראל ממצרים נטה ה' יד החזקה והכה שונאיו עשר מכות, אשר לזה גמר אומר האדון שתהיה הנחת תפילין בכתיבת זכרון ביד כהה שלנו שהיא דוגמת יד החזקה המוציאה אותנו ממצרים, וזה שאמר הכתוב כאן **כי בחוז** ק **יד** ונכון. והגם שמצינו שאמר בהרבה פעמים יד הגדולה זו הסכמת מדת הרחמים למדת הדין אבל עיקר המשפט יד החזקה יתכנה:
@351 **חסלת פרשת בא**
@352 **ויהי בשלח וגו'**. צריך לדעת למה אמר לשון צער במקום גילה ורנן. עוד למה כינה הענין בפרעה ולא באדון המעשים כי הוא המוציא אותנו מארץ מצרים. אכן הכתוב יגיד הסיבה שגרמה כל הצער שנצטערו ישראל ברדיפת פרעה, כפה אותו עד שנתרצה ושלחם ואמר להם קומו צאו מזה חשב מחשבות לרדוף אחריהם כאשר אבאר בעזרת השם, ובזה גרם צער לישראל, וגם לעצמו גרם איבוד לו ולאומתו. וצא ולמד כי הקב''ה יקפיד על כליון הנבראים כמובא בדבריהם ז''ל (מגילה י':) מעשה ידי טובעים בים ואתם אומרים שירה. וכנגד כל זה אמר הכתוב ויהי לשון צער, ומי גרם כל צער זה בשלח פרעה, שאם היה ה' מוצאים שלא לרצונו הגם שלא היה חפץ לשלחם לא היה לו מקום לרדוף, אלא עינו הטעתו שהיה הדבר תלוי בו ולזה חשב לשוב לקחתם. ואומרו **ולא נחם** בוא''ו בתחלת הודעת ענין, יכוין תוס' על הגדת צער הקודם הרמוז בתיבת ויהי כנזכר:
@352 **עוד** ירצה על דרך אומרם ז''ל (זהר ח''ב מ''ה:) כי כל מקום שיכנה ישראל בשם עם ירמוז על ערב רב, ולזה תמצא בענין זה לפעמים מזכיר שמם העם ולפעמים מזכירם בני ישראל דכתיב וחמושים עלו בני ישראל וגו' הרי זה מראה באצבע כי העם לא מבני ישראל המה. ואמרו ז''ל (שמות רבה פמ''ב) כי השחתת ישראל במדבר זה הוא סיבתו, הם אמרו נתנה ראש וגו', הם אמרו עשה לנו וגו', וזה הוא אומרו **ויהי** צער גדול לשונאיהם של ישראל **בשלח פרעה את העם** פירוש ערב רב ששלחם פרעה לא ה' ברוך הוא הוציאם כי לא בא אלהים לקחת לו אלא גוי גדול נחלתו יתברך אלא פרעה שלחם, וטעמו היה לכוף את ישראל לשוב מצרים, והם מצאו מקום להדבק בישראל וסובב בתכליתם צער לישראל כנזכר. ולדרך זה ידוייק על נכון אומרו ולא נחם אלהים **כי קרוב הוא** פירוש קרוב הוא לרמוז העם מקרוב בא ואין לו חוזק בקדושה. או קרוב הוא להרשיע ויסובב רעה גם לישראל והרעה היא כי אמר וגו' פן ינחם בראותם, וידוייק על נכון אומרו **ולא נחם** בתוס' וא''ו בתחלת ענין לומר כי זה נוסף על כמה צער שגרמו להם הרמוז בתיבת ויהי וגו' ועוד להם ולא נחם:
@352 **עוד** ירצה על דרך אומרם ז''ל (שם פ''כ) כי פרעה עשה לישראל לויה, ולפי זה יגיד הכתוב צער הנמשך להם מזה ואמר **ויהי** לשון צער לסיבת שלח פרעה כי יצטרך הדבר להיות שיטול שכר פסיעותיו. וצא ולמד משכר פסיעות של אותו רשע נבוכדנצר (סנהרין צ''ו.) וכל שכר שיקצוב לו ה' יהיה גורם רעה לשונאיהם של ישראל, אשר על כן נתחכם ה' ובטל מצותו ממנו ונתחכם שלא הוליכם דרך קרוב שמן הסתם לשם יערים פרעה ללותם ובזה בטלה מחשבתו כאילו לא ליוה אותם. נמצא מי גרם שלא הלכו ישראל דרך קרוב לווייתו של פרעה, וטעם אומרו **ולא נחם** בתוס' וא''ו לדרך זה לרמוז כי צער אחר גרם הדבר זולת זה שעל כל פנים הגיעו קצת זכות בלויה וזה סיבה שנכנסו ישראל בסכנה ברדיפתו כאמור בדבריהם ז''ל (שמות רבה פכ''א) בפסוק ולא קרב זה וגו' ובפסוק מה תצעק אלי וגו' וכמה הרפתקי דעדו עלייהו. ואומרו **כי אמר** וגו' הוא טעם אחר וכאלו אמר וכי אמר, ותולדות מיחושו הוא לצד שליחת העם שהם ערב רב כמו שרשמנו בדרך ב':
@353 **וחמושים עלו וגו'**. ואולי כי זולת היותם מזויינים בכלי זיין לא יועיל מה שיסב ה' אותם לבל יחזרו בראותם מלחמה כי על כל פנים ישובו מצרימה כיון שאין בידם כלי זיין לערוך עם אויב מלחמה ויראו עצמן אבודים, לזה אמר **וחמושים עלו** וגו' פירוש מלבד טעם שיסב ה' היו להם גם כן כלי זיין ובהצטרפות שני הטעמים **לא ינחם העם בראותם מלחמה וגו'**:
@354 **פקוד יפקוד וגו'**. טעם הכפל להצדיק אמונת הדבר.
@354 וזה שיעורו פקוד פירוש הפקידה שהבטיח ה' ודאי יפקוד. עוד ירצה לרמוז על ב' דברים על הרחקת הנזק היא הצלתם מעוני מצרים ומעול סובלם, והקרבת התועלת שיצאו ברב טוב לבית ישראל דכתיב (בראשית טו, יד) ואחרי כן יצאו ברכוש גדול, וטעם שרמז להם דבר זה לפי שהוא נוגע לשבועה שלא יהיה להם דבר זה סיבה למניעה לבל יעלו עצמותיו לצד שיהיו טרודים באסיפת הון וטעינת כסף וזהב כי ירבה כאומרם ז''ל (בכורות ה':) שאין לך אדם מישראל שלא טען עשרה חמורים מכסף וזהב של מצרים וזה יהיה סיבה למניעת הדבר, לזה אמר **השבע** וגו' **לאמר פקוד יפקוד** גם פקידת העושר ואף על פי כן תדחקו עצמיכם ותסבלו עצמותי הגם שיהיה להם מאמצעות כן הפסד כשיעור משאו מכסף וזהב. ותמצא שכן עשה משה כאומרם ז''ל (שמות רבה פ''כ) שבמקום שיטעון כסף וזהב טען ארונו של יוסף במקומו ונטל שכרו על הדברו:
@354 **מזה אתכם**. טעם אומרו **מזה** אין לומר כי דוקא משום יעלוהו, אלא נתכוון לחזק השבועה שתהיה חזקה כדין הנשבע על דעת חבירו בשביל טובה שעשה לו, ולזה התנה ואמר **מזה** פירוש על דרך אומרם ז''ל (בראשית רבה פ' פ''ד) בפסוק נסעו מזה נסעו מהאחוה שהוא מנין ז''ה, והוא שרמז להם כאן בשעת השבועה באומרו **מזה אתכם** פירוש כי באמצעות חסד זה שהם נשבעים לו מה שהם הפרידוהו מזה ונסעו מאחוותו ועשו מה שעשו לו עכשיו יתוקן הדבר ויהיו לאחדים, והוא אומרו אתכם יהיו חונים מהנסיעה להיות אתם עמם ונעקר העון ההוא והרי הם יחד באחוה, והכוונה בזה כי מחל להם מה שפשעו בו בעד חסד זה שנשבעין לו, וכפ''ז הנה הם נשבעים על דעתו בשביל טובה שעשה להם:
@356 **וה' הולך** וגו'. אומרו **לנחותם** פירוש להיות להם נח הדרך כי לצד שהיו ימי החום חופף ה' עליהם בעמוד ענן לבל יכם השמש. ולזה לא היה משמש עמוד הענן אלא ביום ולא בלילה, וענן זה הוא לבד מענן הקודם להם לישר המעקשים להשפיל הגבוה ולהגביה הנמוך ולהראותם הדרך. ויש ראיה לזה ממה שאמר הכתוב בפרשת דברים (א' ל''ג) ההולך לפניכם בדרך לתור לכם מקום לחנותכם באש לילה לראותכם בדרך אשר תלכו בה ובענין יומם, והנה הזכיר הכתוב ג'. הא' לתור לכם מקום זה היה משמש תמיד לפניהם פירוש מקדים ללכת קודם להם. הב' עמוד האש לראותכם וגו', הג' ובענן יומם, והם דברינו עצמם שענן זה לא היה אלא חופף מהכותם שמש. ולא כמו שפירש''י להנחותם וחסר ה''א והביא חבר לראותכם כי לפי דברינו גם כאן גם שם אינה חסרה ה''א, ועיין בפסוק שאחר זה:
@356 **ולילה וגו' להאיר וגו'**. קשה לפי דבריהם ז''ל (שבת כ''ב:) שאמרו שכל מ' שנה שהיו במדבר לא הלכו אלא לאורו שהיו רואים אפילו מה שבתוך הטפיח, ואין לומר כי על זמן הלילה הוא אומר שאין זה פשט אומרם לא הלכו אלא לאורו כי מה בא למעט אם לא שנא' אור השמש ביום ואם כן הלילה למה לא יאיר כיום שלא היו צריכין לשמש שהוצרך לעמוד אש להאיר להם. ולהבין הענין יש לדקדק עוד אומרו **ללכת יומם ולילה** למה לא הספיק טעם להאיר להם שהוצרך לומר ללכת וגו':
@356 **אכן** כוונת הדברים היא לעולם שלא זז אורו יתברך ממחנה ישראל תמיד כמאמר חכמינו ז''ל שכתבנו בסמוך אלא שיש לדעת כי האור הקדוש הלזה לא היה מתפשט חוץ ממחנה ישראל אלא דוקא במושבותם. ויש טעם בדבר ומה גם במדבר הרע שהוא מדור של מחנה טומאה כי שם הרגיעה הקליפה כידוע בדברי הקדושים (זהר ח''א קכ''ו.) וכיון שכן לא היו ישראל יכולים ליהנות מהאור העליון אלא במחניהם אבל חוץ למחניהם לילה יחשיך כסדר העולם. והנה אם לא היו ישראל הולכים בלילה כשיחפוץ ה' ללכת לא היו צריכין לאור עמוד האש כי לכל בני ישראל היה אור ה' במושבותם אלא לסיבת הליכתם בלילה הוצרכו לעמוד להאיר למרחוק חוץ למחנה ישראל להכיר מקום שיכלו בו חוץ למחניהם, והוא אומרו **להאיר להם**, וטעם אור זה הוא **ללכת יומם ולילה** פירוש בשוה כשם שביום מלבד אור ה' הנוצץ עליהם היו רואים אור למרחוק באור השמש המאיר לעולם כולו כמו כן היו רואים בלילה באמצעות עמוד האש. ובזה יטעם ביאור מה שאמר הכתוב בפרשת דברים באש לילה לראותכם בדרך אשר תלכו בה פירוש לראותכם כדי לראותכם. כדי שתראו אותם, לא כמו שפירש''י להראותכם וחסר ה''א והביא מהנביאים ומהכתובים חבר לה כין אנו צריכים לזה, וביאר הכ' דבריו כי דברינו יגיד באומרו לראותכם בדרך ולדבריו היה צריך לומר הדרך, אלא הכוונה היא להיות שהיה להם לישראל אור עולם במושבותם ולא בדרך אשר עדיין לא באו שמה לזה אמר כי עמוד [אש] טעמו הוא כדי שיראו בדרך אשר ילכו בה לשון עתיד והבן והם דברינו עצמם. ומעתה אין הבדל בין היום ללילה לבני ישראל ולא היו מכירים זמן יום וזמן לילה אלא על ידי השתנות העננים:
@359 **דבר וגו' וישובו וגו'**. הנה כל רואה יקהה בזה למה יצטרך ה' להערים חם ושלום על הדבר והוא עשה יעשה כל אשר יחפוץ בלב פרעה לרדוף:
@359 **אכן** בהשכיל במה שקדם לנו בידיעת מדת הבורא כי חפץ למען צדק ישראל הלא זה הדבר אשר דבר ה' במצוה זו שנתחכם לבל יכשלו בהכעסה לבורא ויאמרו דברי ניאוץ שאמרו אחר כך (פסוק יא) המבלי אין קברים וגו' הלא וגו' טוב לנו עבוד את מצרים וגו' ונתחכם ה' ועשה דבר מורגש ומוכר להם כי ה' יעץ על פרעה רעה ומתחכם אליו להוציאו ממצרים לרדוף את ישראל להכבד בו. ומעתה אין מקום לישראל לחוש לפרעה ואדרבה יחילו דרכיו לראות נקמתם בו, ולא הספיק לבורא לומר להם הדברים בפה לבד כי הוא יחזק לב פרעה לרדוף אחריהם כי לא יעשו הדברים בהם רושם ובראות אותו ירעשו ויתנו ראש לשוב אליו ממוראו עליהם, לזה צוה ה' שישובו ויחנו ויעשו מעשה המוכן לרדוף פרעה אחריהם ודבר זה ירגישם ויעשה בהם רושם כי הם הם העושים הכנה בהרגשה רעושה שחזרו לאחוריהם ולחנות במקום מיוחד שממנו יטעה פרעה לרדוף אותם ובזה לא יפחד לבם ובבואו יגל יעקב ישמח ישראל כי יחזה נקם באויבו, ותמצא שאף על פי כן לא הועיל בהחלט. וצא ולמד מה שאמרו בראותו ומזה תקיש מה היו עושים זולת החזרה והבן:
@360 **ואמר פרעה וגו'**. פירוש כשישוב המגיד הוא יודיעו כל אשר ראו עיניו:
@362 **ויגד למלך וגו' כי ברח וגו' ויהפך לבב וגו' אל העם**. צריך לדעת אומרו כי ברח ולא אמר כי הלך שיראה שראו בהם סימן בריחה. עוד קשה אומרו **ויהפך** וגו' משמע שנתחרטו על הדבר אשר עשוהו והדברים תמוהים וכי לרצונם עשו והלא הוכו מכות גדולות עד כמעט ספו ותמו ובעל כרחו שלחום ואיך יהפך לבם בדבר שלא לרצונם עשוהו, וקשה עוד אומרם **מה זאת עשינו** וגו' כמתרעמים על עצמם על עשות דבר שלא כהוגן והלא לא עשו אלא בעל כרחם ומה יתאונן אדם על דבר שעשאו בעל כרחם. ואפשר לומר על דרך מאמרם ז''ל (זהר ח''ב מ''ה:) כי העם הוא ערב רב וכמו שכתבנו בתחלת הפרשה ופירוש הכתוב כך הוא ויוגד למלך מצרים כי ברח העם פירוש העם אשר שלח הוא עם ישראל לטעם נכון אצלו להשיב בני ישראל הן עתה ברחו והלכו להם ולאלו יתיחס הבריחה כי זולת הבריחה אין מצילם מיד פרעה כי הם עמו ועבדיו, **ויהפך לבב פרעה** וגו' פירוש שנחמו על אשר שלחום פירוש לעם לא על ישראל, ויאמרו מה זאת עשינו פירוש תמוהים הם על מעשיהם ששלחו העם, וטעם התמיהה הוא כי שלחנו את ישראל מעבדנו פירושו על דרך אומרם ז''ל (ילקוט ר''ח) כי פרעה כתב גט שחרור לישראל ואמר להם הרי אתם לעצמיכם הרי אתם בני חורין, והוא אומרו **שלחנו** בגט שילוחים, **מעבדנו** שאין להם משפט עבד, והגם שאפשר שעלה על דעתם שיחזרו לא יעבוד בהם עוד עבודת עבד, וכיון שכן תחזור העבודה הצריכה למלך על העם, ומעתה כיון שברח העם מי יעבוד. גם בזה רמז למה לא חששו על בריחת העם הנזכר כשירגישו שתכבד העבודה עליהם, ולזה תיכף ומיד הכינו עצמם לרדוף, והנה לפי מה שפירשתי אין הרדיפה אלא על העם ואמר הכתוב כי ה' חזק לבו של פרעה וירדוף גם אחרי בני ישראל ולא לעם בלבד:
@362 **עוד** נראה על פי מה שפירשתי בפרשת בא (י' ז') כי טעם שהקשו ערפם פרעה ועבדיו הוא לחושבם כי דברי ה' בדרך זה הם דרך ערמה וזה יגיד כי לא יוכל עשות כל חפצו חם ושלום, והנה ביום הכות ה' אותם מכת בכורות וימדדם פגרים מתים רעשו ורעדו והצדיקו הדברים כי אלהי ישראל כל יכול להחריב עולם ומכל שכן מצרים ולפי סברא זו יתחייבו לומר כי מה שאמר ה' דרך ג' ימים אין ערמה חס ושלום אלא אמת יהגה והוכחת פרעה ממה שהולכים כלם יחד אינה הוכחה כטעם האמור בדברי משה (שם) כי חג ה' וגו' וזה היה להם למשען שהשאילו ממונם לישראל והונם כי נתחזק בלבם כי שוב ישובו ישראל מצרים, גם לא חששו כי עשה ה' הדבר בדרך זה כדי שישאילום לצד שהכירו שהי' ה' יכול להכריחם גם על זה לתת כל ממונם, ומה גם לדבריהם ז''ל (שמות רבה פי''ד) שגילו מצפוניהם בימי חושך מצרים וידעו מצרים בזה ואם כן מטעם זה היה להם ליטול הכל באין רואה, וכאשר הגיד המגיד לפרעה אמר אליו כי ברח העם פירוש לפי מה שעלה במסקנתם כפי ההוכחות כי מה' לא היה הדבר בהחלט הליכות עולם אם כן מה שלא רצו ישראל לחזור כי רצו לברוח ממצרים וללכת הליכה מוחלטת ולא מן ה' הוא הדבר, לזה **ויהפך לבב פרעה ועבדיו אל העם** פירוש לא לצד המוציא כי המוציא עדיין בחזקת כי לא הוציא אלא לשעה אלא למה שנוגע לעם למה לא חששו להם. שיברחו, והוא אומרם **מה זאת עשינו כי שלחנו את ישראל מעבדנו** פירוש הגם שהיה לנו לשולחם לגזירת אלהיהם אף על פי כן לא היינו שולחים אותם בדרך זה שיוכלו לברוח מעכדנו, כי היו יכולין לשלוח עמהם חיל מצרים ורכבו ופרשיו עד עבוד אלהיהם במדבר וישובו למצרים:
@362 **או** יאמר כי באמצעות המגיד שהגיד שברחו נתהפך לבב פרעה על מה שהכריעו כי אלהי ישראל כל יכול והרי זה לך האות בבירור כי לא יכול על הכל ממה שדבר דרך ערמה אמור מעתה במופת חותך כי לא היה בו חס ושלום כח להוציאם בהחלט והוצרך לגניבת דעת, ודקדק הכתוב לומר.
@362 **לבב** לומר כי ב' לבבות הוכרעו בדבר כי הגם שבתחלה קודם שלח ישראל היה חושב מחשבה זו כי אין כח בידו להוציאם בהחלט ממה ששואל בדרך זה אף על פי כן היה לו לב אחר דוחה סברא זו ואומר אולי כי אינו חפץ בהם אלא לשעה, ומעתה פרחה לה טענה זו והסכימו ב' הלבבות יחד אל העם לבלתי שלחם שהוברר אצלם צד האחר. ואמרו מה פעולה רעה זאת עשינו כי שלחנו וגו' שלמפרע אנו רואים שלא היה יכול להוציאם בהחלט מטעם שכתבנו לזה ויאסר את רכב ו:
@363 **ואת עמו לקח וגו'**. כי לא היה במשא ומתן שכתבנו אלא הוא ועבדיו אבל עמו הוצרך לקחתם בדברים כי הם היו יראים לנפשם:
@365 **ויחזק וגו' ובני ישראל יוצאים וגו'**. פירוש הוצרך ה' לחזק לבו כי היה לו לתת לב לאופן וסדר יציאת בני ישראל שהיתה ביד רמה וזה יגיד כי פסקה יד מושל מעליהם ומזה היה לו להיות נרתע אלא שה' חזק לבו וחשב מחשבות הנזכר למעלה וירדוף וגו':
@367 **ופרעה הקריב וגו' והנה מצרים וגו'**. צריך לדקדק למה הוצרך לומר זה ולא הספיק מה שקדם לומר וישיגו אותם וגו'. ואמר עוד והנה מצרים נוסע וגו' גם למה התחיל הסיבה בפרעה וגמר אומר במצרים דכתיב והנה מצרים שהיה לו לומר והנה פרעה וגו'. עוד צריך לדקדק אמרו **נוסע** לשון יחיד וגו' על מצרים שהם רבים. ולהבין הכתוב יש להעיר הערה גדולה בדברי בני ישראל אל משה המבלי אין קברים וגו' מה זאת עשית לנו וגו' כנשמע שהדבר להם חדש ואין זה אמת כי כבר הודיעם ה' כי יחזק לבו לרדוף להכבד בו והעירם בזה במעשה אשר צוה להם עשות שישובו ויחנו וגו' כדי שיטעה לרדוף אחריהם ויעשו כן הרי הכינו עצמם להטעותו לרדוף אחריהם אם כן מנין נכנס להם הפחד, לו יהיה שראו שבא בכח גדול שש מאות רכב וגו' אשר אפשר כי לא חשבו מקודם שהיו להם כל כך חוזק אף על פי כן כבר הבטיחם ה' כי הוא המחזק לבו להכבד בו והם סייעו בדבר:
@367 **אכן** יתבאר על פי דבריהם ז''ל (שמות דבה פכ''א) שאמרו וזה לשונם ומצרים נוסע אחריהם זה שר של מצרים מצרים שמו עכ''ל, והנה המלאך הלז בא עמהם כי כן הוא הנהוג שהשר יעזור לאומתו ויפול בנפילתה וצא ולמד ממעשה אלכסנדרום מוקדון (יומא ס''ט:) שהיה נדמה לו שרו במלחמות, והנה מן הסתם כי השר יהיה עומד לימין המלך לא לפני העם, והנה מסדר הרגיל במלחמות שהמלך ביניהם שהעם יקדמו קודם למלך והמלך לבסוף מהעם, וכאן הודיע הכתוב הדבר שממנו באה ההרגשה לישראל לירא ולפחד הגם שקדם להם מה שקדם מהידיעה, ואמר **ופרעה הקריב** פירוש לא עשה סדר הרגיל להקדים העם אלא הקריב עצמו קודם לעם, **וישאו בני ישראל את עיניהם והנה מצרים** פירוש שר של מצרים כנזכר פירוש לצד שפרעה הקריב והשר היה לפניו עומד זה היה סיבה לראות ישראל השר ששמו מצרים נוסע וגו' והם לא יוכלו דעת סיבת השר שאינו אלא לעמוד לפני מלך כנהוג כי אין מנהג המלך להקדים למחנה והם ראו השר נוסע אחריהם פירוש קודם המחנה, לזה רעשו כי חשבו כי שרי מעלה באו לערוך עמם מלחמה, והגם שקדם להם מה שקדם לא הספיק להם כשראו מלאכים באו להלחם עמהם כי הוא אות כי ה' חזר ממחשבתו הטובה כי זולת זה לא היה מסכים על מלאכו לבא כנגדם ולזה צעקו וגו'. ואילו לא היה פרעה מקדים או אם היה סדר הרגיל שיקדים המלך הם היו תולים הדבר כי לא למלחמה בא אלא לעמוד לפני המלך כחוק שרי מעלה עם כל מלכים אשר הם ממונים עליהם ולא היו מפחדים, ובזה נתיישב הענין ויישוב הכתובים. וטעם שלא מנע ה' המלאך מבא, לב' טעמים, הא' כדי להורגו לפניהם כאומרו וירא ישראל את מצרים מת על שפת הים ואמרו ז''ל (זהר ח''ב נ''ב:) שיכוין על השר ששמו מצרים, וטעם ב' אלהים חשבה לטובה כדי שיפחדו ויחזרו בתשובה שלימה ויקרבו לבם לשמים כדי שבאמצעות זה יעשה ה' להם הנס העצום של קריעת ים סוף ודבר זה לא הובטחו בו קודם. ותמצא שדרשו ז''ל (שמות רבה פכ''א) בתיבת הקריב ולא אמר קרב ירצה שהקריב לבן של ישראל לאביהם שבשמים, וכן היה דכתיב **ויצעקו בני ישראל אל ה'**:
@370 **התיצבו וראו**. אולי שנתכוון לומר להם שיתיצבו בתפלה כמות שהיו עומדים וצועקים אל ה' כאמור בסמוך ויצעקו וגו' אל ה', וכן הוא אומר (שמואל א' א') אני האשה הנצבת עמכה וגו':
@370 **אשר יעשה לכם היום**. נתכוון באומרו **היום** להסיר מלבם חשש מה שעבר ביציאת מצרים שארך קץ הגאולה מיום שהתחילה הבשורה עד גמר הדבר שנים עשר חדש, לזה אמר להם כי לא יאריך זמן מלחמה זו אלא הן היום יעשה ה' התשועה:
@370 **אשר** ראיתם את מצרים וגו' כוונת מאמר זה אפשר שנתכוון להסיר מהם הפחד על זה הדרך באומרו הלא מה שראיתם את מצרים היום הוא לצד שלא תוסיפו לראותם עוד עד עולם לטעם זה הוא שהביאם ה' והראה ה' אותם לכם כדי שלא ישאר לכם שום מיחוש מהם לעולם, והוא מאמר הקודם שאמר להם (פסוק ד') וחזקתי את לב פרעה וגו', והגם שראו השר, גם אותו יתמדד לפניהם כמו שכן היה:
@371 ה' **ילחם לכם**. פירוש לצד שהפחד שנפל אליהם הוא מהשר וכמו שפירשנו בפסוק ופרעה הקריב לזה אמר להם בשלמא אם היו הם הלוחמים ישערו כי עצום הוא מהם מה שאין כן לצד שה' הוא הלוחם אין לחוש לאלף כיוצא בו:
@371 **עוד** ירצה לומר שאפילו מדת הרחמים תהפך לדין על המצריים להלחם עמהם, ודקדק לומר **לכם** כיון שבערך ישראל יחשב הדבר רחמים. עוד ירצה **ילחם לכם** כי לא לעזרה לבד יהיה להם במלחמה אלא הוא יערוך כל המלחמה. ואומרו **ואתם תחרישון** יתבאר על דרך אומרם ז''ל (פתיחתא דאיכה רבתי ל') ד' צדיקים מה ששאל זה לא שאל זה וחלוקה המעולה שבכולן הוא מה ששאל חזקיה שאמר אני אין בי כח לא להרוג ולא לרדוף ולא להתפלל אלא אני ישן על מטתי ואתה עושה וכן עשה ה' דכתיב (מלכים ב' י''ט) בלילה ההוא ויצא מלאך ה' וגו' והיא המדריגה שאמר משה ואתם תחרישון פירוש אפילו בתפלה אם אין בכם כח כמאמר חזקיה תחרישון והוא ילחם לכם. ולפי מה שפירשנו בפסוק התיצבו שאמר להם יעמדו בתפלה ירצה על זה הדרך **ואתם תחרישון** למדת הדין פירוש תרבו בתפלה להשמיע במרום קולכם להחריש למדת הדין עליכם:
@372 **מה תצעק אלי**. קשה ולמול מי יצעק אם לא לה' אלהיו ובפרט בעת צרה דכתיב (יונה ב') קראת מצרה לי, (תהלים קי''ח) מן המצר קראתי יה, ואם לצד שהרבה להתפלל הלא כל עוד שלא נענה מהעונה בצר לו לא ירף מתפלה. עוד רואני כי נתקבלה תפלתו ואמר לו ה' **הרם את מטך** וגו' אם כן קבלנות זה שאמר **מה תצעק אלי** למה. עוד קשה אומרו **דבר אל בני ישראל ויסעו** להיכן יסעו אם רודף מאחור והים לפניהם, ואם הכוונה אחר שיבקע הים אם כן היה לו לומר הרם את מטך וגו' ואחר כך יאמר דבר אל בני ישראל וגו':
@372 **אכן** יתבאר הענין על פי מאמרם ז''ל (שמות רבה פכ''א) שישראל היו נתונין בדין מה אלו אף אלו, ודבר ידוע הוא כי כח הרחמים הוא מעשים טובים אשר יעשה האדם למטה יוסיפו כח במדת הרחמים ולהיפך ב''מ ימעיטו הכח, והוא אומרו (דברים לב יח) צור ילדך תשי, והנה לצד שראה אל עליון כי ישראל קטרגה עליהם מדת הדין, והן אמת כי חפץ ה' לצדק ישראל אבל אין כח ברחמים לצד מעשיהם כנזכר, אשר על כן אמר למשה תשובה נצחת **מה תצעק אלי** פירוש כי אין הדבר תלוי בידי הגם שאני חפץ עשות נס כיון שהם אינם ראוים מדת הדין מונעת ואין כח ברחמים כנגד מדת הדין המונעת, ואמר אליו **דבר אל בני ישראל** פירוש זאת העצה היעוצה להגביר צד החסד והרחמים דבר אל בני ישראל ויתעצמו באמונה בכל לבם ויסעו אל הים קודם שיחלק על סמך הבטחון כי אני אעשה להם נם ובאמצעות זה תתגבר הרחמים **ואתה הרם את מטך** פירוש באמצעות מעשה הטוב נעשה להם הנם ובקע הים כי גדול הבטחון והאמונה הלז להכריעם לטובה. ותמצא שכן היה וצדיק הראשון הוא נחשון בן עמינדב ונכנס עד גרונו ולא נבקע הים עד שאמר כי באו מים עד נפש כמאמרם ז''ל (סוטה ל''ז.) ובזה נתישבו הכתובים על נכון. ונראה לי לומר כי רשם ה' לומר להם טעם תגבורת הדין עליהם לצד שהם המעיטו בלבם האמונה ואמרו הלא טוב לנו את עבוד מצרים לזה צוה ה' לעשות כנגד עון זה הצדקת האמונה בכל תוקף. גם בזה רמזם לדעת הסובב תגבורת הדין מחדש:
@374 **ואני הנני מחזק וגו'**. בחמלת ה' עליהם נתכוון להודיעם קודם לבל יפחדו בראותם כי הים נשאר חלוק לפני המצריים כסדר שהיה חלוק לפניהם ישובו לחשוב מחשבות ולהמעיט האמונה בלבם ויאמרו הנה המה עולים אחרינו וייראו מאד לזה הודיעם ואמר להם דעו לכם כי ממני היו הדברים להכבד בו ואני פורש רשת לרגליהם:
@376 **ויסע מלאך האלהים וגו'**. יאיר נתיב כתוב זה במה שפירשנו בפסוק (י''ג כ''א) וה' הולך לפניהם וגו' כי ג' עננים היו משמשים לישראל, א' לפניהם לתור להם מקום וגו', והב' להגין עליהם מחום השמש, והג' להאיר להם בלילה, והודיענו הכתוב אשר עשה ה' בלילה ההוא **ויסע מלאך האלהים** שהוא ההולך לפניהם והוא הענן הראשון שמוזכר בפרשה דברים (א' ל''ג) שאמר ההולך לפניכם נסע והלך לאחריהם, ואמר עוד כי הענן המשמש בפניהם שזמנו כל היום שהגיע זמנו לנסוע בלילה והוא המוזכר בפרשה דברים דכתיב (שם) ובענן יומם גם הוא נסע ועמד לאחריהם, נמצאת אומר כי ב' עננים שהיו לפניהם נסעו לאחריהם, וטעם הב' כדי שיחשיך לפניהם בלתי דעת מקום תחנותם של ישראל, והוא אומרו **ויהי הענן והחשך ויאר את הלילה** פירוש כי הוצרך לשניהם להחשיך בפניהם לבל ידעו מחנה ישראל שהיה בו אורה הלילה והאור יגיד להם מקום לזה כיסה חושך פניהם ולא הספיק לו חשך לבד כי יבהיק אור בני ישראל במושבותם לזה עשה ה' ב' הענן והחשך:
@377 **ויבא בין מחנה מצרים וגו'**. אולי כי כל מקום החלל שבין ב' המחנות מילא אותם הענן והחשך, והוא אומרו **ויבא בין** וגו' שאם לא כן למה הוצרך לומר ויבא בין וגו' אחר שכבר אמר וילך מאחריהם ויעמוד מאחריהם:
@378 **ויט משה את ידו וגו'**. הגם שאמר הכתוב ויולך ה' וגו' וישם את הים לחרבה, לא שם לחרבה אלא מים העמוקים כדי שלא יבקעו כל מי הים ויצטרכו ישראל לרדת למעמקים ויאריכו בהליכה וביגיעה ולזה הקדים רוח קדים להקפות עמקי המים, והוא אומרו (לקמן ט''ו ח') קפאו תהומות בלב ים, וחלק שלא נקפא נבקע, ואם לא היה טעם זה לא היה צריך לרוח קדים. ויש לדעת אימתי היתה נטית ידו של משה אם בתחלת הלילה אם בסופו, והנה משטח הכתוב מוכח כי קודם הבוקר היתה, וקשה דאם כן אין היכר לקריעת ים סוף שהיתה על ידי משה, על כן מוכרח לומר שפירוש הכתוב הוא ויט משה וגו' וכבר הוליך ה' וגו' וישם את הים לחרבה ולזה כשנטה ידו בקעו המים, וכפי זה תכף לנטית ידו נבקע הים. וזה מכוון למה שפירשתי בפסוק (ט''ו) מה תצעק אלי שלא נטה ידו אלא אחר נסיעת ישראל ותכף לכניסת ישראל לים נטה ידו ובקעו, וכן הוא ברבות (שמות רבה פכ''א) וז''ל מיד כיון שהרים משה ידו על הים נבקע עד כאן, או ירצה אומרו **וישם את הים לחרבה** פירוש כל מי הים נגלדו ובנטית יד משה נבקעו המים הגלודים כשיעור שלא יצטרכו לירד לעמקי ים ולעולם רוח קדים שם כל מי הים לחרבה וראשון עיקר:
@378 **כל הלילה**. פירוש עד סוף הלילה ואז נקרע הים וירדו ישראל באשמורת הבוקר:
@379 **בתוך הים ביבשה**. פירוש אומרו בתוך הים בפנימיותו, ואומרו **ביבשה** שלא היה קרקעית הים טיט ורפש:
@379 **והמים להם חומה וגו'**. פירוש כי חלק מהמים שנחלק לא נשפך לצדדין. ואומרו מימינם לומר כי לא חומה ממש שהוא בהקף מהצדדין:
@380 **וירדפו מצרים**. הגם שאמר הכתוב ויהי הענן וגו', זה היה בלילה ובאור בוקר לא עבות חזרו המערכות לדאשונות וראו המצריים הליכת ישראל ורדפו אחריהם:
@381 **ויהי באשמורת הבוקר**. צריך לדעת למה עשה ה' המשפט הגדול הזה בבוקר ולא בלילה שהוא זמן תגבורת הדינים. וראיתי שאמרו ז''ל (ילקוט רל''ה) כי גבריאל טען טענה זו לפני ה' והשיבו אל עליון המתן עד אותה שעה שפעל אביהם עמי שנאמר וישכם אברהם בבוקר עד כאן. פירוש תשובת ה' כי הגם שאינו זמן הנקמה אני מהפך הסדר לבני אברהם כשם שהפך אברהם טבעו הרחמן ומה גם על בנו ידידו ואעשה כן גם אני שהפך הזמן לאשר יחפוץ, ויש בזה הנאה לישראל שיעמוד זכות העת. גם יעשה ה' דברו הטוב בכבודו ובעצמו כמו שעשה אברהם וחבש חמורו בעצמו, והוא אומרו **וישקף ה'**:
@383 **נטה את ידך וגו' וישובו וגו'**. צריך לדעת לאיזה ענין הוצרך לנטות ידו על השבת המים הלא הם מעצמם לא יתמידו לעשות כן ובגמר עליית ישראל שהוא גם כן גמר ירידת אחרון של המצריים (שמות רבה פכ''ב) מעצמו ישוב הים. ואולי כי מהטעם עצמו שנשאר חלוק גם במקומות שעברו בו כבר ישראל והיו המצריים באים שמה חשב הים כי מה אלו אף אלו, וה' גזר כן כדי שיכנסו כולן יחד לתוך הים, וטעם זה לא גודע לים ולא הרהר אחר רבו, לזה צוה ה' למשה לרמוז לים כי כלתה שליחותו וילך כמנהגו:
@383 **עוד** יתבאר על דרך אומרם ז''ל במסכת יום טוב (ה'.) כל דבר שבמנין צריך מנין אחר להתירו והוכיחו כן ממה שאמר הכתוב (דברים ה כז) שובו לכם לאהליכם הגם שאין טעם לאסור עוד אף על פי כן הוצרך להתיר:
@383 **עוד** טעם הנטיה לפי שזולת זה הגם שישוב הים ישוב לאט לאט לצד היותו תש כח מההשתנות שעברה עליו ובזה יוכלו להמלט, לזה צוה ה' למשה להעיר לים בנטית ידו לשוב לתוקפו הראשון תיכף ומיד, וכן הוא אומר **וישב** וגו' **לאיתנו**. או אפשר כי לצד שהוכה הים על ידי משה חפץ ה' שעל ידי משה שב ורפא לו על ידי נטית ידו וה' סומכה כאומרו (ישעי' ס''ג) מוליך לימין משה זרוע תפארתו יתברך:
@383 **עוד** ירצה בנטית ידו לרמוז לים שיעשה מלאכתו בהם שלמה לבל ימלט סוס ורוכבו ולא ימנע מהם בשום אופן לבל ימלט מצרי לשוב עלות מהים וכגון אותם שבקצוי הים שבשיטה אחת יפנו מהים, הרשהו לים על כולם לבלתי ימלט מהם עד אחד וכן הוא אומר **וישובו המים ויכסו** וגו':
@384 **לאיתנו**. רז''ל אמרו (שמות רבה פכ''א) לתנאו הראשון. וקשה לי לדבריהם אין זה מקום התנאי אלא בשעת החלוקה שם יזכיר תנאי זה. ואולי כי יודיע הכתוב כי אחר ששב אז ידע שהוא תנאי שהתנה עמו ה' ולא גזירת כליונו או הגעת צביונו להבטל מהעולם, והגם כי התנאי היה ידוע לו, אולי שלראות הפלאת הדבר שנתיבש ונעשו המים יבשה וגם המים העומדים נעשו חומות אבנים יאמרו כי בא עד קיצו גם כן וכשחזר ידע כי אין זה אלא תנאי ראשון לבד. וצריך לדעת אופן התנאי אם היה ליוצאי מצרים אם כן למה נדעש בפעם הזאת כמאמרם ז''ל (שם) שהתריס כנגד משה ואמר לו אין אני נקרע מפניך שאני נבראתי ביום ג' ואתה נבראת ביום ששי וכו' עד שנטה ה' ימינו לימין משה דכתיב (ישעי' ס''ג ז') מוליך לימין משה. ועוד רואני כי ליחידי סגולה היה נקרע בעל כרחו כמעשה הובא בחולין (ז.) ברבי פינחם בן יאיר וכו' ואם לא התנה עמו אלא ליוצאי מצרים לבד מה כוחו של ר''פ בן יאיר עליו השלום להתגבר על מעשה בראשית:
@384 **אכן** תנאי זה הוא בכלל התנאים שהתנה ה' על כל מעשה בראשית להיות כפופים לתורה ועמליה ולעשות כל אשר יגזרו עליהם וממשלתם עליהם כממשלת הבורא ברוך הוא, ולזה תמצא כמו כן בשמים ובארץ ובכוכבים ובשמש וירח שלטו עליהם הצדיקים יחידים ואין צריך לומר מרובים כאשר חקק ה' להם בעת הבריאה, והוא סוד אומרו (ישעי' מ''ג) בוראך יעקב וגו' ואמרו ז''ל (ויקרא רבה פל''ו) שאמר הקדוש ברוך הוא לעולמו מי בראך מי יצרך ישראל והכל בכח התורה. וצא ולמד מ''ש בפסוק בראשית. והנה ביציאת ישראל ממצרים עדיין לא קבלו התורה ואין גזירתו על הנבראים גזירה ולזה לא הסכים הים ליחלק להם וטען למשה אתה נבראת בששי ואני בג' זה רמז כי אינו בן תורה שאם היה בן תורה הנה הוא קודם לו כי התורה קדמה לעולם כולו, ולזה נתחכם ה' והוליך ימינו לימין משה פירוש הראהו כי הוא בן תורה המתיחס לה ימין דכתיב (דברים לג ב) מימינו וגו' וכשראהו תיכף ומיד נקרע כתנאי הראשון, ולזה כל צדיק וצדיק שיעמוד אחר קבלת התורה יביא בידו שטר חוב א' לכופו ליחלק לפניו, ותמצא שכשלא רצה ליחלק לר' פנחס בן יאיר ולהמתלוה עמו רצה לקונסו ופחד הים ממנו:
@384 **ומצרים נסים וגו'**. פירוש שהגם שהיו נסים ממנו כשראוהו ששב לאיתנו אף על פי כן לקראתו פירוש היה הים בא להם למול מקום שנסים שמה ולכל מקום שהיו נסים היו מוצאים עצמן שהולכים לקראתו, על דרך אומרם ז''ל (סנהדרין ק''י, במדבר רבה פי''ח) בבליעת קרח ועדתו שהיה פה הארץ רץ אחריהם למקום שיעמדו שמה כי כל הנבראים עושים רצון קונם בזריזות וזהירות גדולה, ושיעור הכתוב כי נתגבר הים לאיתנו פירוש לתוקפו ונעשה כנזכר:
@384 **וינער ה'**. פירוש לצד שיש בני אדם בקיאין לשוט בים הגם שיהיה הים בכל תוקפו וגבורתו יתחכמו לשום בו דרך, לזה אמר הכתוב כנגד אלו וינער וגו' בטל מהם הכח ההוא. ולדברי רבותינו ז''ל (שמות רבה פכ''א) שאמרו כי מצרים מת הוא שר של מצרים אמר כי הגשימו והשליט עליו גשם המים ונערו בתוך וגו':
@385 **לכל חיל פרעה וגו'**. פירוש הרכב והפרשים שלא היה בהם כח למהר לבא לתוך הים והיו באים אחריהם שבו המים עליהם למקום שהיו שם לא נשאר בהם וגו':
@386 **ובני ישראל הלכו וגו'**. טעם הודעת דבר זה פעם ב'. אולי כי יכוין לומר שידעו המצריים את הדבר הזה כי ישראל עברו ביבשה והמים היו להם חומה וגו' והם ירדו תחתיות ארץ ובזה ידעו ה' כמאמרו יתברך (פסוק י''ח) וידעו מצרים וגו' וזולת זה לא ירגישו בדבר. וצא ולמד (אבן עזרא פ' כ''ז) ממה שטעו מהמשוגעים ואמרו כי משה היה יודע שעות שבו יתמעט הים וכו' והעביר ישראל באותו עת והמצרים לא ידעו ונטבעו, ומופת זה יסיר שגעון דעת זו כי הלכו ביבשה והמים חומה ב' סימנים אלו יעקרו הכחשת הנס, והראם ה' לנטבעים:
@387 **ביום ההוא**. פירוש **ביום ההוא** היתה התשועה ולא קודם הגם שיצאו ממצרים לא היו בוטחים בעצמן מהם:
@387 **וירא וגו' מת על שפת הים**. קשה למה הוצרך להודיענו שראהו מת פשיטא שלא יהיו חיים אחר הטביעה. ורבותינו ז''ל (מכילתא) אמרו כי ראו במיתתן, והודיענו בזה כי שם גמרו מיתתם, והטעם כדי שיכירו בהם ישראל בעודם חיים והם יראו בישראל ותכסם בושה, ולפי זה תהיה כוונת הכתוב על זה הדרך **וירא ישראל את מצרים** שהיתה יוצאה נשמתו **על שפת הים**, ותיבת מת נקשרת עם אומרו על שפת הים ולא עם תיבת וירא:
@388 **וייראו העם את ה'**. פי' יראת הרוממות, אבל יראת העונש מן הסתם היתה להם קודם במצרים. ולפי מה שהוכחנו בפרשת (י''ב מ''ג) זאת חקת הפסח כי לא קבלו עליהם מצות המלך אם כן אפילו יראת העונש לא היתה להם עד שראו היד הגדולה וייראו וגו', ועל כל פנים ביראת הרוממות הכתוב מדבר מאומרו וירא ישראל את היד הגדולה וייראו וגו'. ואומרו **ויאמינו** כי זה תשלום האמונה בהם:
@389 **אז ישיר**. לא היה צריך לומר אז אלא וישר משה וגו' והדבר מובן כי אז שוררו. אכן יכוין הכתוב להודיענו הכנת המושג. כי כשנכנסה בלבם יראת הרוממות והאמונה השלימה אז זכו לומר שירה ברוח הקודש. ואומרו **ישיר** לשון עתיד לצד שאמר אז חש הכתוב שיטעה אדם ויאמר כי אז מיעט שאין שירה זו יכולה ליאמר זולת אז תלמוד לומר ישיר שישנה לשירה זו גם לעתיד וכל הבא לשיר שירה זו לפני ה' יש לאל ידו. או ירמוז למצוה שמצוה לאומרה תמיד וקבעוה בתפלת שחרית בכל יום:
@389 **ויאמרו לאמר אשירה**. פירוש אמרו זה לזה **לאמר** פירוש שיאמרו שירה יחד בלא בחינת השתנות והפרדה עד שיהיו כאיש אחד, הגם היותם רבים, ונתכוונו יחד ועשו כן ואמרו **אשירה** לשון יחיד כאילו הם איש אחד שזולת זה היו אומרים נשירה:
@389 **כי גאה גאה וגו'**. אין לשבח תחלה אלא על מפלתן של רשעים על דרך אומרו (משלי יא) ובאבוד רשעים רנה, ופירוש אומרו **גאה גאה** יכוין על פרעה שנתגאה גאות ששמה גאות כי דרך הגאים יתגאו על כיוצא בהם אדם על אדם כיוצא בו וגאותו של זה אינה חשובה גאות כי הוא מתגאה על השפל אבל פרעה גאה גאה פירוש גאות שנקדאת כפי האמת גאות גאה כי לא החשיב מאמר עליון ואמר מי ה'. או ירצה **גאה גאה** שהיתה גאותו כפולה, סוס ורוכבו של הגאה רמה וגו':
@389 **עוד** ירצה **גאה גאה** על ה' מלך גאות לבש ונתכוונו לומר כי קודם שעשה משפט זה היתה לו בחינת גאוה אחת ובאמצעות יד הגדולה גאה גאה. גם לרמוז בין בעליונים בין בתחתונים באמצעות דבר זה. ולדרך זה חסר הנסמך לרוכבו. ואולי שיעור הכתוב הוא על זה הדרך אשירה לה' כי גאה גאה פירוש ה' ונמשכת עוד תיבת כי גאה גאה למטה על זה הדרך ולאותו שגאה גאה סוס וגו' רמה בים:
@390 **עזי וזמרת וגו'**. הנה סדר העומדים לפני ה' לשורר ולשבח ולהתפלל הוא להתחיל בדברים המושכלים מה' אליו ואחר כך במושכל מה' לאבותיו, וכמו שמצינו שתקנו אנשי כנה''ג באבות אלהינו ואחר כך אלהי אבותינו, ולזה סדרו בהתחלת השיר מה שהגיעם מטובו ואמרו עזי וזמרת יה ויהי לי לישועה, והוא מה שנתחסד ה' עמהם להושיעם מהצרה שהיו בה קודם שיגיע הקץ, וזה היה לצד רחמיו אליהם, וכמו שכתבתי ענין זה באורך בפ' שמות (ג' ז'), ובפ' וארא (ו' ג'), ולזה גמרו אומר **זה אלי** ואחר כך אמרו **אלהי אבי**, והוא כסדר עצמו של כנסת הגדולה שקבעו לומר אלהינו ואלהי אבותינו, וכאן אמרו לשון יחיד כי נעשו כולם כאיש אחד כמו שפירשתי בפסוק ויאמרו לאמר:
@391 **ה' איש מלחמה**. פירוש גם במדת הרחמים עשה מלחמה, ולא שישתנה מפני זה חם ושלום אלא ה' שמו, על דרך (מלאכי ג) אני ה' לא שניתי. או ירצה כי בזמן עצמו שעשה מלחמה עם המצריים בזמן עצמו היה מתנהג במדת הרחמים עם ישראל וכמו שפירשתי במאמרו יתברך (לעיל ו' ב') וידבר אלהים אל משה וגו' אני ה':
@393 **תהומות וגו'**. לפי מה שפירשתי לעיל (י''ד כ''א) כי חצי הים נקפא וחצי נבקע, וכל חלק יקרא תהום לצד הפלגת ריבויו ושניהם יכסיומו, ועיין בפסוק קפאו תהומות באופן אחר:
@393 **ירדו במצולות**. ירמוז אל אותם שהיו משתדלים לעלות מהים בכח מלאכת השיטה שהורידם לעמקי מים וכמו שפירשתי בפסוק (שם כ''ז) וינער וגו':
@394 **ימינך ה' וגו** '. פירוש כשתהיה מדת הרחמים מתחזקת לעשות דבר משפט והוא אומרו **נאדרי בכח** אז ימינך ה' שהיא מדת הרחמים עצמה תרעץ אויב. או ידרוש מסופו לראשו אימתי ימינך ה' נאדרי בכח כשימינך ה' תרעץ אויב אז תפול אימתה ופחד על כל הנבראים מפני שמך האדיר:
@395 **וברוב גאונך**. פירוש לצד שהזכיר כי ירעוץ קמיו הוסיף לומר כי עוד להם שיהרסם ברוב גאונו, והכוונה שלא יהרסם הריסה קלה בלא הרעשה אלא במופתים ובאותות יעשה בהם משפט כתוב. ואומרו **תשלח חרונך יאכלמו כקש** פירוש לא שאתה צריך לרוב גאונך להרום אותם אלא הגם שיכול אתה לשלח חרון אחד שלך ויהיה נאבד כקש:
@396 **נערמו וגו' נצבו וגו' קפאו וגו'**. פירוש כנגד ג' מלאכות שעשה ה' בים. הא' שנבקעו ונתקבצו כולם יחד ולא נשארו מפוזרים במקום הפנוי אלא נעשו כולן ערימה אחת לעשות מדרך רגלי ישראל. ב' המימות שהיו מתקבצים ובאים ושופכים בים מהצדדין היו נצבים במקום שנערמו הראשונים והוא אומרו **נצבו כמו נד נוזלים**. פירוש אותם שנוזלים ובאים נצבו כמו נד. ג' לפי מה שהעלינו (לעיל י''ד כ''א) כי לא נחלק כל הים כדי שלא יצטרכו לרדת לעמקי הים חלק שלא נחלק נקפא ונעשה כיבשה וכנגד זה אמר קפאו וגו'. וכבר כתבתי כי ההקפאה קדמה לביקוע. והוא אומרו **קפאו תהומות בלב ים** קודם שנקרע קפא לבו ונשאר מלבו ומעלה מים שלא קפאו ונבקעו. וטעם אומרו **תהומות** לשון רבים, לדבריהם ז''ל (שמות רבה פכ''ד) שאמרו שהים נקרע לי''ב קרעים וכל מקום ומקום שנקרע קפא שם התהום וכנגד כולם אמר **תהומות**:
@397 **אמר אויב וגו'**. טעם לחזרת דברים אלו והם עצמן שאמרו בתחלת השירה מרכבות פרעה וחילו ירה בים וגו'. נתכוונו לשורר על אופן סדר המעשה שנתחכם ה' עשות במלאכת הים לישראל לנם וצוה ה' שיעמוד הנם כשורתו וכמנהגו לאויב שבזה טעה וחשב לרדוף כי ישיג ויחלק שלל שזולת זה לא היה רודף דרך ים ולא היו מובטחים ממנו:
@397 **אחלק שלל**. הנה הרשע חשב עשות ג' דברים. א' שוה בכולן והוא לשלול כל שללם, והוא אומרו אחלק שלל, ב' שיקח אותם לעבדים כבראשונה, והוא אומרו **תמלאמו נפשי** פי' תתמלא נפשי מהם כשאחזור לכבוש אותם לעבדים. גם רמז שיוסיף לעשות בהם חפצו בעינוי יותר ממה שעבר. ג' להרוג משה ואהרן וזקניהם וגדוליהם, והוא אומרו **אריק חרבי** וגו' ואומרו **תורישמו ידי** ירצה על דרך אומרם ז''ל (שמות דבה פ''א) בפסוק (ב' ט''ו) ויבקש להרוג את משה שבקש להורגו בסייף ולא שלטה בו וכו', והוא שאמר משה (לקמן י''ח ד') ויצילני מחרב פרעה לזה אמר אויב תורישמו ידי כי תשיג ידו מה שלא השיג מקודם:
@398 **נשפת ברוחך וגו'**. ג' פורעניות כנגד ג' מחשבות, כנגד מה שאמר אחלק שלל כסמו ים בזה הגם שימלטנו סום וישוט בים הנה שללו אבד, וכנגד העינוי שחשב על היהודים כרמוז באומרו תמלאמו נפשי גם מה שחשב להריק חרבו אמר **צללו** וגו' פירוש מתו, ולא מתו תכף ומיד אלא צללו כעופרת במים אדירים ואמרו ז''ל (מכילתא) שהיו המים מעלים אותם עד לשמים ומורידים אותם עד התהום והיו מתים באריכות זמן, והוא אומרו **כעופרת במים אדירים** יכוין לב' דברים, הא' הוא השקיעות, והוא אומרו צללו כעופרת, והב' הוא מניעתם מלמות תכף ומיד, והוא אומרו במים אדירים והם יעלום ממעל וימנעום ממות תכף ומיד שיר ושבח לאלהים על נסיו ומופתיו:
@399 **מי כמוכה באלים וגו'**. פירוש כיון שאנו רואים מצרים שהוא השר מצרים שמו מת מי ידמה לה' בבני אלים:
@399 **עוד** נראה על דרך אומרם ז''ל (חגיגה ט''ז) מלך בשר ודם כשנחבא בתוך העם אינו ניכר כי הוא זה מה שאין כן אלהינו אות הוא בצבאו, והוא אומרו **מי כמוכה** אפילו כשאתה באלים בלא שום היכר המלוכה רשום הוא:
@399 **עוד** ירצה על דרך אומרם ז''ל (מכילתא) מלך בשר ודם מוראו על הרחוקים יותר מהקרובים אבל הקב''ה מוראו על הקרובים יותר וכו', והוא אומרו **מי כמוכה באלים** כי שם מכירים יותר אבל בתחתונים אימתי מי כמוכה כשאתה נאדר בקודש כשאתה נותן חוזק ואדר לבחינת הקדושה כמעשה ארץ מצרים אשר השפיל גאון רשע והאדיר הקדושה:
@399 **עוד** ירצה על דרך אומרו נהר דינור נגד ונפיק מן קדמוהי, (דניאל ד' י'), ואמרו ז''ל (חגיגה י''ג:) כי מזיעת החיות שמזיעים בעת שאומרים קדוש יוצא נהר דינור, והוא אומרו **נאדר בקודש** פירוש כשמאדרים אותו בקודש אז לצד המורא שנכנם בחיות כשמהללים אותו עושה הנוראות ההוא שמזיעים נהר דינור:
@399 **נורא תהלות עושה וגו'**. פירוש יש לכל לירא מהגיד תהלותיו לצד שמעשיו כולם פלא ומי הוא שיצטדק בתהלותיו, כי אין אדם ישיג דעת המופלא לשבח בו ואיך יהללו במדרגה קטנה כיון שיש לו בחינה מופלאת ומכוסת גדולה ועצומה:
@400 **נטית ימינך וגו'**. רבותינו ז''ל אמרו בספרא (מכילתא) מלמד שהיה הים זורקן ליבשה והיבשה לים אמרה היבשה לים ומה במקום שלא קבלתי אלא דמו של הבל יחיד נאמר לי ארורה וגו' עתה איך אוכל לקבל כל האוכלוסים עד שנשבע לה הקב''ה שאינו מעמידה בדין דכתיב נטית ימינך וגו' עד כאן. וכן תרגם יונתן בן עוזיאל, מכאן אתה רואה כי לא רצה הים לקבלן והיה פולטן ליבשה, ולא כן מצינו שאמרו בפסחים קי''ח וזה לשונם אמר הקב''ה לשרו של ים פלוט אותם ליבשה אמר לפניו רבונו של עולם יש עבד שנותן לו רבו מתנה וחוזר ונוטלה ממנו אמר לו אתן לך א' ומחצה וכו' אמר לו יש עבד שתובע רבו אמר לו נחל קישון יהיה ערב מיד פלטן ליבשה ובאו ישראל וראו אותם שנאמר וירא ישראל וגו' עד כאן. הדי שאמרו ז''ל בפירוש שלא היה הים חפץ לפולטן אם כן אחר כך כשהחזירתם לו האדמה למה לא שמח לקבלם, גם למה הוצרך ה' לפרוע לו ממחנה סיסרא והרי שלך לפניך יחזירם לו בעצמן ולא היה צריך ערב:
@400 **עוד** קשה הלא עינינו רואות כי אין הים סובל בתוכו אדם ובהמה אלא פולטן ליבשה שזכורני פעמים שטבעו בני ארם בים והשליכן ליבשה מהם ביום ההוא מהם אחר יום או יומים ולדבריהם ז''ל הים חפץ שיהיו עומדים אצלו. וראיתי לרש''י ורשב''ם שפירשו שטענת הים הוא לצד פרנסת דגי הים שימצאו מזון. וצריך לדעת אם כן למה לא קבלם כשזרקתן היבשה והיו למזון הדגים. והיה נראה ליישב כי אז היו סרוחים ואינם ראוים למאכל דגים, וזה דברי דיחוי כי מן הסתם לא יתעכב ה' לומר ליבשה לקוברם מדין לא תלין, וגם אין צורך בדבר לעכב קלונם על פני האדמה אלא עד שימותו ואחר מיתה מה צורך להתעכב בלא קבורה. והגם שאין דרכנו בחיבור זה לפרש מאמרי רבותינו ז''ל, עם כל זה הענין הוא צורך משמעות הכתוב, וכדי שלא נאמר מדרשים חלוקים נראה להתאימם על פי מאמרם ז''ל (מכילתא י''ד ל') וכתבנו אותו בפסוק וירא ישראל וגו' מת על שפת הים כי ראו אותם בגמר מיתה בעודם קצת חיים כדי שיכירו ואז וכו', ולפי דבריהם אלו זרח אור ב' המאמרים, כי מה ששאל הים שלא יפלוט אותם הוא לצד כי ה' אמר אליו לפלוט אותם חיים לסיבת הנזכר לשמח ידידיו שיכירו המצריים ישראל ויראו ותכסם בושה כאמור בדבריהם הפלגת נם זה, והגם שלא רמוז במאמרם זה ענין הפליטה שתהיה בעודם חיים, אף על פי כן רבותינו ז''ל סומכים למה שידוע ביניהם, ולזה טען הים יש עבד שנותן וכו' הכוונה כי חפץ הוא לגמור המצוה במכעיסי אל. ותמצא כי כל שרי מעלה וכל ברואי מעלה ומטה חפצים וחשקים לעשות מצות ה' כי הם אביונים בדבר לצד שאין להם מצות, וכן תמצא שם בפסחים באותה סוגיה כי גבריאל בקש מה' להציל אברהם מכבשן האש ואמרו שם כי ה' לא קפח שכרו ואמר לו תזכה ותציל ג' מבני בניו וגו' עד כאן הרי כי זכות הוא למלאכים לעשות חסד לצדיקים ולאוהבי עליון, וכמו כן היה חפץ הים שתגמור יציאת נפשם בים ולא ביבשה ולזה צעק לבו, והשיבו אל עליון כדרך שעשה לגבריאל כי לעתיד ימציא לו זכות אחר לאבד עם רשע חלק ומחצה והוא מחנה סיסרא שהוא יעשה בהם מצות איבוד רשעים:
@400 **עוד** יש טעם בטענת הים שהיה חפץ שתגמר מיתתם בים לקחת כל כוחות החיוניות שהם כל הנפשות של העם, כי מטבע נפשות העמים לעמוד במקום מיתתן כאומרו (קהלת ג') ורוח הבהמה היורדת היא למטה לארץ, והעובדי כוכבים ומזלות נמשלו לבהמות וכי תצא נפשם בים יזכה השר בהם לבחינת המושגות אצלו מהענין, ולזה כשאמר אליו לפולטן חיים שאז תהיה הארץ זוכה בדבר כי קונים מקומן במקום הנחתם יורדים שמה צעק לבו יש עבד וכו' עד שענהו רבו כי יתן לו בעדם וכו' פירוש בני אדם חיים כמות אלו ופרט לו בדומין לאלו ושאב חיותם מהם שהוא עיקר חשקו לא בגוף, ולזה אחר שפלטם ויצתה נפשם על שפת הים וזרקתם האדמה לים לא רצה לקבלם כי אינו מטבעו והארץ היא המכסת על בניה אשר לוקחו ממנה והכריחה ה' לקבלם כי לה נוגע הדבר. ולא תקשה לדרכינו זה ממה שאמרו שם בפסחים כי כשפרע ה' לים פתחו דגים שבים ואמרו ואמת ה' לעולם ע''כ, אם כן להם נוגע הדבר, ואולי כי בעת אשר יחפוץ הים בקבלתם בתוכו שהוא בזמן שהם חיים היו הדגים נהנים מהם ביני וביני קודם שימותו ואז ישליכם הים ואין להם עוד מהם מזון ועל זמן פרנסתם אמרו שירה. וראיתי מי שנתעצם בטענת הים יש עבד וכו' הלא יד עבד כיד רבו, ואין בזה קיהוי כי הים טענתו נכונה על דרך אומרם (תענית כ''ה,) משמים מיהב יהבי משקל לא שקלי, ועל אדנות אדונו הוא אומר וכי קרה מקרה זה לאיזה עבד מעבדי ה' שנתן לו רבו וחזר וכו', ולזה לא אמר יש אדון שנותן וכו' וחוזר וכו' כי זו אינה טענה יש ויש ואדרבא יד עבד כיד רבו וכאלו לא נתן אלא דבריו הם לרבו כי אינו מתנהג כן עם עבדיו:
@403 **אז נבהלו וגו** '. אומרו אז לומר כי אינו בזמן שדבר בו עד עתה שהוא זמן של הנכנסים לארץ אלא על זמן ביאת גואלנו, ולזה אמר אז נבהלו אלופי אדום, וכן הוא אומר (במדבר כ''ד י''ח) והיה אדום ירשה, וגם אז יחול זמן לזכות במואב ועמון, ולזה אמר **אילי מואב יאחזמו רעד**, וטעם שלא הזכיר עמון, כי גם הוא מאב פירוש עם בתו בא, ואז גם כן נזכה בכל הנשאר מהכנעני, והוא אומרו נמוגו כל יושבי כנען, ואמר **יושבי**, לומר שיטהרו בהם אפילו שאר העמים, וטעם אומרו לשון עבר כי דבר ה' כאילו נתקיים והיה:
@404 **תפול וגו' עד וגו'**. פסוק זה ושלאחריו ידבר כל אחד על ב' הכנסות לארץ אחת בימי משה ואחת בימי המשיח, ולזה אמר העניינים כפולים:
@406 ה' **ימלוך וגו'**. טעם שלא אמרו ה' מלך, אמרו הם עצמם הטעם כי בא וגו' פירוש לצד שלא נעשה המשפט אלא באומה אחת, והוא אומרו **כי בא סוס פרעה** וגו' כי לא יוקח מזה הכחשת כל האלהות אשר אומות אותם יעבדו ולזה אין מלכותו נכרת לעולם, מה שאין כן לעתיד לבא כי יעשה ה' משפט בכל הגוים אז יהיה ה' למלך על כל הארץ והוא אומרו ה' ימלוך:
@406 **או** ירצה טעם אומרו **ימלוך** ולא מלך כי בא סוס פרעה וגו' פירוש כולם היו בטביעה כסוס אחד והכוונה בזה כי לא נמלט מהם עד אחד כשם שיטבע אדם אחד יטבעו כולם, והן אמת אם היה מגיד לעולם הפלגת ועוצם הנם להכיר העולם גדולת תגבורת פאר נצחון והוד יסוד אמונתינו אשר כל שומעיו יתלהבו ויאמרו הבו יקר כי הוא זה אדונינו מלכנו ומעתה יהיה ה' למלך אלא שלא הלכו ביבשה ונמלטו זולת בני ישראל, והוא אומרו ובני ישראל הלכו וגו' ולהם לא ישמעו האומות כי הם נוגעים בדבר להיותו אלהיהם:
@410 **ויסע משה וגו'**. פירוש נסיעה זו על פי משה נסעוה ומכאן ואילך על פי ה':
@411 **ויבואו מרתה וגו'**. צריך לדעת למה לפעמים יקרא לה מרתה ולפעמים מרה, ונראה כי שם המקום היה מרתה והמעיין של מים שבו לא היה לו שם מיוחד, ואמר **ולא יכלו לשתות מים ממרה** פירוש מהמעין שהיה במרתה מטעם כי מרים הם, ואחר כך חזר הכתוב לגלות לך כי שם מרה שאמר הוא שם שנקבע למעין ההוא אחר שמצאו מימיו מרים קראו הכתוב על שם העתיד, ולדרך זה יבא על נכון אומרו **כי מרים הם**, לצד שקריאת שם מרה הוא על העתיד ואז עדיין לא נקרא שמה מרה וכאלו אמר לשתות מים ממרתה, לזה הוצרך לומר **כי מרים הם** והבן:
@412 **וילונו וגו' לאמר**. יספר הכתוב בגנותם כי באו בריב, ואין הכתוב מקפיד אלא על תלונותם, אבל על פרט אומרם מה נשתה לא יקפיד ה' אם היו אומרים כדרך שואל חסרונו:
@414 **אם שמוע וגו'**. פירוש **אם שמוע** לחק ומשפט אשר שם כאמור בסמוך תזכו לשמוע בקול ה' פירוש ממנו יתברך, על דרך אומרו (דברים ד' ל''ג) השמע עם קול אלהים וגו', ומבשרם שיזכו למה שזכו אחר כך, וה' נתן להם שבת ודינים קודם (סנהדרין נ''ו:) לנסותם אם ישמעו למצות אלו יצום התורה כולה, והוא אומרו למעלה **ושם נסהו** פירוש אם יעמוד בקבלת התורה. ותמצא שכאן רמז הכתוב ד' מצות ללמוד וללמד לשמור ולעשות, כנגד ללמוד אמר אם שמוע וגו' בקול ה' זו תלמוד תורה, וכפל השמיעה לטעם הנזכר, גם לרמוז להם שיהיה עסק התורה בחשק גדול שהגם שעודנו לומד יתאוה ללמוד עוד וזה יגיד שאינו שבע וקץ בלימודו. וכנגד ללמד אמר **והישר בעיניו תעשה** על דרך אומרם ז''ל (נדרים ל''ז.) מה אני בחנם אף אתה בחנם, ושיעור הדברים הוא על זה הדרך והישר בעיניו יתברך לעשות הוא עם ברואיו שנתן להם התורה בחנם תעשה גם כן אתה, וכנגד מצות עשה אמר **והאזנת למצותיו**, וכנגד מצות לא תעשה אמר **ושמרת כל חוקיו** לשון שמירה הצודקת על ל''ת:
@414 **אשר שמתי וגו'**. טעם שפרט לומר אשר וגו' נתכוון לבל יאמרו כי אינו מבטיח אלא שלא להביא עליהם מחלה אבל אם באה לזולת בהדי הוצא לקי כרבא ואין כאן הבטחה לזה אמר אשר שמתי במצרים, ולכו וראו מעשה מצרים שהגם שהביא ה' כמה מחלות היה ה' מגביל למכה לבל תגע בהם הא למדת שאפילו בשעת חרון אף יפליא ה' להם חסדו ויצילם ה':
@414 **כי אני ה' רופאך**. פירוש לצד חולאים שאינם בידי שמים כאומרם ז''ל (כתובות ל'.) הכל בידי שמים חוץ מצינים ופחים. לזה אמר **כי אני ה' רופאך** פירוש הגם שיקר לך מקרה מהם אני ארפאך מהם, כי משה הוא שנתחכם להביאם דרך זה לסיבה ידועה:
@418 **ביד ה' בארץ מצרים**. פירוש כי אם היו במצרים והיו ממאנים לצאת מה היה הדבר היו מתים הרוגי ה', לזה אמרו כי הם בוחרים שהיה ה' ממיתם בארץ מצרים על מיאונם ולא יודו לצאת, וימותו ברעב, על דרך אומרו (איכה ד') טובים היו חללי חרב מחללי רעב:
@418 **בשבתנו על סיר וגו'**. מכאן אתה למד כי מדברי לשון הרע זה הם אותם שלא היו עליהם עול סבלות מצרים והם השוטרים, כי המעונים סובלי עול הגלות לחמא עניא אכלו במצרים. ואולי שהם הרשומים ברשע הוא דתן ואבירם:
@418 **בשבתנו על וגו'**. פירוש ובאמצעות הבשר היו אוכלים לחם לשובע כי היה להם הבשר ללפת בו את הפת:
@418 **או** ירצה כי מלבד שכבר אכלו לחם פירוש סעודתם היו מוסיפין לאכול בשר על השובע. ואולי שדקדקו באומרם **על סיר** וגו' ולא אמרו באכלנו בשר וגו' לרמוז כי לא היו אוכלים שנתבשל ושהה כי זה יפגם טעמו אלא שהיו יושבים על הסיר לאוכלו בעת גמר בשולו. ורמזו לו בדבריהם כי הגם שיאמר להם שחטו ממקניכם ואכלו בשר זה לא יספיק בתמידות כאשר היו רגילים לאכול תמיד לחם ובשר. עוד יתבאר הכתוב למה שקדם לומר כל עדת בני ישראל מן הסתם לא תהיה כל העדה בגדר שוה בתלונתם נגד ה' ונגד נביאו, ולזה רשם ה' ב' טענות כנגד ב' כתות שהיו בישראל אחת תובעת בשר ואחת תובעת לחם, והוא אומרו **בשבתנו על סיר הבשר** זו כת הפריצים שבהם והתחיל הכתוב בדברים אלו כי בקלקלה מתחילין מן הצד, ואחר כך אמר באכלנו לחם לשובע כנגד התובעים לחם לאכול כי היו רואים עצמן בארץ לא עבר בה איש ולא היו מושלים ברוחם להמתין עד שיתן להם רבם מנתם:
@419 **ויאמר ה' אל משה הנני וגו'**. לא אמר הכתוב לאמר. גם התחיל לדבר נוכח וסיים נסתר ויצא העם וגו'. יתבאר על דרך אומרם ז''ל (יומא ע''ה.) כי המן היה יורד לצדיקים פתח אהלו של כל אחד ולא היה צריך לצאת אחריו ולשאר העם היה יורד במקום אחר והיו יוצאים ללקוט, והוא אומרו **הנני ממטיר לכם לחם** וגו' פירוש באין צורך לצאת ללקוט, אבל העם יצאו וילקטו. כנגד מה שלא בטחו וקדמו לשאול ישיגוהו בטורח:
@419 **וטעם** שלא אמר בתחלת נבואה זו לאמר, לצד כי עדיין יצוהו פעם ב' כל הדברים בפרשה שאחר זו אלא שהקדים הדברים למשה למצוא בפיו מענה, ותכף ומיד השיבם שהנבואה נאמרה לו כהרף עין ותכף ומיד והנה כבוד ה':
@419 **למען אנסנו וגו'**. כי לחם מן השמים לא יצטרך שום תיקון ובזה יהיו פנוים מכל ואראה הילך וגו':
@419 **עוד** ירצה על זה הדרך טעם **דבר יום ביומו למען אנסנו** כשיהיה צריך לו בכל יום למזונותיו:
@420 **והכינו את אשר יביאו**. פירוש כי ההבאה עצמה בכלל ההכנה וצריכין להכינה מיום ו' כדי שלא יביאו בשבת, והוא מאמר משה לישראל (פסוק כ''ט) אל יצא איש ממקומו וגו':
@421 **ערב וידעתם וגו** '. פירוש לצד שישראל דברו בדרך החלטת המניעה שימצאו בשר במדבר באומרם מי יתן מותינו וגו' ולא שאלו הדבר קודם זה יגיד כי היה להם הדבר בלתי אפשר, לזה אמר להם ערב וידעתם כי ה' וגו', כי עד עתם אינכם יודעים המוציא אתכם מה נורא מעשיו ולא לקחתם ידיעה מהמסות הגדולות כי כל יכול עכשיו מחדש תכירוהו. וכונת דבריו הוא לשבט מוסר כי טח מראות עיניהם וגו' (ישעי' מ''ד). וטעם שלא תלה הידיעה אלא במעשה ערב ולא במעשה בוקר, לצד שהוא המופלג אצלם במניעה. ואמר **וידעתם** בתוספת וא''ו, לומר מלבד שתוסר יראת מות ברעב אלא שיהיה בדרך מופלא כמעשה ה' הנורא המוציא אתכם מארץ מצרים:
@422 **ובוקר וראיתם וגו'**. פירוש בוקר הוא מה שאמר בסמוך ויאמר משה וגו' והנה כבוד ה', וענין זה היה ביום ב'. ולפי זה טעם אומרו **וראיתם** בתוס' ו', פירוש מלבד דברו אשר ידבר לכם על ידי עוד יעשה ה' לכם דבד שיראה לכם את כבודו. או ירצה באומרו **ובקר** כי גם בקר ידעו כי ה' וגו', והיא נמשכת למעלה עם אומרו ערב וידעתם וגו' ובקר, ואומרו וראיתם הוא תחלת ענין, וכפי זה אפשר כי בו ביום ראו כבוד ה':
@423 **ויאמר וגו' בתת וגו'**. להיות שבתחלה אמר הדברים סתומים ערב ובקר ולא אמר מה יהיה ערב ובקר לזה חזר ופירש מה שאמר ערב וידעתם הידיעה היא בתת ה':
@424 **ויאמר משה אל אהרן**. פסוק זה אפשר שהיה ביום ראשון עצמו שדבר אליהם ערב וידעתם. או אפשר שהיה למחרתו, ומה שאמר להם ערב וידעתם אינו חוזר על ערב של אותו יום אלא ערב של זמן שיתן ה' להם כאומרו בתת ה' וגו' ולאפוקי בוקר:
@425 **כדבר וגו'**. פירוש שהיה ה' כיושב ומצפה שיפנו אליו ותכף לדברו נראה כבוד ה' בענן:
@426 (יא~יב) **וידבר וגו' לאמר שמעתי וגו' דבר וגו'**. קשה למה אמר תיבת **לאמר** בפסוק א' ולא הספיק במה שאמר אחר כך דבר אל בני ישראל, ואם נתכוין שגם פרט זה שאמר לו שמעתי את תלונות וגו' יאמרנו לישראל אם כן למה הוצרך לומר עוד אחר כך דבר. ונראה לומר על פי דבריהם ז''ל (יומא ד':) שאמרו שכל האומר דבר לחבירו הרי הוא בבל תאמר עד שיאמר לו לאמר, והנה כשדבר ה' למשה ואמר לו **שמעתי** וגו' הם דברי ה' למשה, וענין זה הוא בבל תאמר לזה אמר לו ה' **לאמר**. והנה אין הכרח בזה שחייב לומר אלא רשות הוא שמרשהו לומר לשלול בל תאמר והדבר בידו להודיע דבר ה' זה אליהם, וכשרצה ה' שידבר אליו דברים שנוגעים לישראל אמר דבר אל בני ישראל כי מכאן ואילך הם דברים שאני מחייבך לדברם, ולזה תמצא ששינה ה' את דברו כי מקודם דיבר דרך נסתר על ישראל כאלו מדבר דברים בינו לבין משה אלא שהרשהו לספר לישראל. וכשיאמר לישראל צריך לדבר להם על זה הדרך כי ה' אמר למשה ששמע תלונות בני ישראל לא שהושלח מה' לומר להם משמו ששמע וגו', ומאמר ב' אמר אליו דבר אל בני ישראל משמי בשליחות בין הערבים תאכלו. וטעם שהוצרך לומר תיבת לאמר נתכוון שיאמר להם משמו יתברך. וזה שיעור הכתוב דבר אל בני ישראל שאני אומר להם בערב תאכלו וגו' והוא אומרו **לאמר**, ומשמשת תיבת לאמר במקום כה אמר ה', גם בזה יוצדק גמר הדברים שאמר **אני ה' אלהיכם**, וזולת לאמר ישמע הדבר שחס ושלום על משה:
@430 **ויאמרו איש וגו' מן וגו** '. צריך לדעת מה כוונת הכתוב בזה. ואולי כי בראותם אותו הזמין ה' לפיהם במקום שיאמרו מה הוא אמרו מן הוא, וזה שמו אשר קבע לו ה' ושם שמו בפי ישראל על דרך אומרם ז''ל (ברכות ז':) אשר שם שמות בארץ שיכוונו לשמות אשר קרא להם הבורא. ואומרו **כי לא ידעו** נתן הכתוב טעם המצאת השם לפיהם הוא לצד שלא ידעו מה הוא ומאמצעות זה נפל אליא בפיהם. ואולי כי מזה נתחכמו בני ישראל וקראו שמו מן דכתיב (פסוק ל''א) ויקראו בית ישראל שמו מן שהשכילו בתיבת מן שאינה מן הרגיל בנדבר ואין זה אלא רוח ה' דיבר ומלתו על לשונם כי זה שמו:
@431 **איש לפי אכלו**. פירוש לפי שיעור בני ביתו אם רבים אם מעטים. ואמר **אכלו** כי אכילת כולן תחשב אכילת האיש התלוי בו, והעד על זה מה שאמר אחר כך וימודו בעומר וגו' איש לפי אכלו וגו', וחזר לומר כמה יקחו לכל אחד עומר לגלגולת, וחזר לומר **מספר** וגו' לומר שלא יעשו הפרש בין קטן לגדול אלא מספר הנפשות כי כולם ישוו באכילת המן. ואומרו **לאשר באהלו** נתכוון לומר כי מי שיש לו באהלו איש או אשה שאין מזונותיהם עליו והם בשכונתו שגם להם יקח האיש. ודרשת רבותינו ז''ל (יומא ע''ה.) תאיר עינים בנפלאות ה':
@434 **ויאמר משה וגו'**. אולי כי מצוה זו משה מעצמו דן אותה, להיות שראה כי ה' נותן להם דבר יום ביומו זה יגיד כי אין יום אחד מכין לחברו והבין דבר מתוך דבר ואסר להם. ולזה אמר הכתוב ולא שמעו אל משה, וקשה לא היה צריך לומר אלא ויותירו וגו' ואני יודע שלא שמע ו:
@434 **עוד** למה לא הספיק לומר ולא שמעו ויותירו ואני יודע כי לא שמעו למשמיע. ולדברינו יבא על נכון פירוש **ולא שמעו** למה שנתחכם ואסר להם מדעתו. ולדרך זה ידויק גם כן אומרו במאמר הקודם לזה זה הדבר אשר צוה ה' מה שלא אמר כן במה שלפנינו. וטעם שהבאיש וירם תולעים, שהסכים ה' על ידו שהצדיק בסברתו סברת חכם עדיף מנביא:
@434 **ואפשר** לומר כי לעולם מפי הגבורה נאמרה לו מצוה זו אלא לצד שכבר אמר זה הדבר אשר צוה ה' סמך שכל ענין פרטי דיני המן נמשך למה שהקדים לומר זה הדבר אשר צוה ה', והם לא השכילו כונתו וחשבו כי הוראתו הוראת חכם לא הודעת נביא:
@435 **וירם תולעים וגו'**. טעם שהקדים וירם וגו' לויבאש, לצד שהרמת התולעים תמצא במין המתוק ולא יבאש כי אין הסרחון רגיל בדברים המתוקים כרגילות הויית התולעים ומן זה טעמו כצפיחת בדבש ולזה אמר **וירם תולעים** ולא די זה אלא **ויבאש**. והעד הנאמן לפרושנו זה אומרו (פסוק כ''ד) ולא הבאיש ורמה לא היתה בו פירוש לא מלבד שלא הבאיש אלא אפילו רמה הרגילה להיות בלא סרחון לא היתה בו, ואם לא ירום תולעים עד שכבר הבאיש אחר שאמר הכתוב ולא הבאיש אין צורך לומר עוד ורימה וגו'. והנה ראיתי לרבותינו ז''ל (מכילתא) שלא פירשו כדברינו, ואולי כי יסברו שעל כל פנים הגדלת התולע יקדים לה קצת מההבאשה שממנו תתהוה הגם שלא יבאש המתוק. ובדרך רמז ירצה כי אין תולע גדל אלא מהנבאש. והנה מצינו שתרגם אונקלוס רע ביש, ובחינת הרע ויסודו הוא עבור פי התורה והמצוה, ואדם כי יחטא ירום תולעים, והוא סוד גדילת תולעים מהפירות ואויר האדמה אחר חטא האדם, והוא אומרו **וירם תולעים** הטעם הוא לצד ויבאש שנעשה בו בחינת הרע שהניחוהו הפך מצות התורה, ולזה כשאמר להם משה הניחו אותו וגו' עד הבקר אמר הכתוב ויניחו אותו עד הבקר כאשר צוה משה ולא הבאיש ורימה לא וגו' פירוש לא נגע בו בחינת הרע ובזה ורימה לא היתה, וכמו כן הצדיקים אשר לא יטעימו נפשם מבחינת הרע לא יתליעו. וצא ולמד מעשה ר' אליעזר בר רבי שמעון בן יוחאי עליו השלום (ב''מ פ''ד:) כי תולע אחד לבד גדל באזנו לצד בחינת הרע אשר נגע שם:
@437 **ויגידו למשה וגו'**. מכאן משמע שלא הודיעם קודם דבר ה', וקשה איך יכבוש חס ושלום נבואתו ולימדונו רבותינו (סנהדרין פ''ט.) דין נביא הכובש נבואתו וכו' חס ושלום, ומה גם בהגדת מצוה לקיים ישראל רצון המלך שיש בזה ב' בחינות כובש נבואה ועקירת המצוה, ואין לומר כי חם ושלום שכח מצות ה' אם כן נחוש לו גם כן ששכח ממה שנצטוה ועדיין שכוח חם ושלום, ומה גם שלא היה לו לעכב זמן מה לישכח ותכף ומיד היה לו להגיד נבואתו, וגם קושיא לאלהינו למה לא הזכירו כשידע בו ששכח באותה שעה עצמה היה לו להזכירו ולא היה מניחו שכוח עד ז' ימים שהוזכר מעצמו:
@437 **אכן** משה רבינו טעמו ונימוקו עמו ובמתק לשונו השיב תשובה כראי מוצק (איוב לז) באומרו **הוא אשר דבר ה' שבתון שבת** וגו' כאן בנועם דבריו השמיט תיבת לאמר רמז כי לא דבר לו ה' לאמר להם, ואשר על כן הדבר בבל תאמר כמאמרם ז''ל (יומא ד':) וכתבנוהו בפסוק (י''א) וידבר וגו' שמעתי וגו', וזה הוא טעמו שלא הודיעם קודם. והעד הנאמן לדברי משה ה' מעידו בנוסח הנבואה כשאמר לו (פסוק ה') והיה ביום הששי וגו' תמצא שלא אמר לו ה' שם דבר אל בני ישראל ולא תיבת לאמר, הרי סתם הדבר בפניו שאין לו שליחות במצוה זו לישראל, והוא שאמר הוא אחר מעשה שלקטו לחם משנה ובאו לפניו גילה להם הדבר ואמר להם שלא היה אצלו אלא בדרך סוד נמסרו לו הדברים ולא לאומרם:
@437 **ויש** לנו לתת לב כפי זה מי התיר לו לאמר להם כל מצות האמורות בדבריו שלא נאמר לו דבר ולא לאמר:
@437 **ונראה** כי נתחכם משה בחקירת חכם למה לא רצה ה' שיאמר הדברים לישראל, והשכיל כי טעמו הוא שחפץ ה' לנטוע בהם נטע אמונת והצדקת מצות שבת שתהיה קבלתה וידיעתה ממנו אל עליון שלא על ידי שליח תחילה אלא כשיצאו ללקוט כמנהגם שיעור הרגיל ליומו וימודו וימצאו פי שנים מהרגיל יום יום יראו ראייה חושיית ושכליית כי ה' מצווה להם לבל יטרחו ביום שבת ומזמין להם מיום ששי צורך יום ז' כדי שבזה תהיה מצוה זו אצלם מקובלת בתום' קבלת הרצון ומורא גדול מעבור עליה לצד שמעלתה גדולה, וכמאמרם ז''ל (שמות דבה פכ''ה) שקול שבת כנגד כל התורה כולה, ולזה לא צוה להם תחלה על השבת משה כדי שלא יכוונו להרבות בלקיטה וילקטו כמשפט יום יום ויעשה להם הנס למצוא בכפלים אין זה אלא מעשה אלהים אשר ישיחם לשמור שבת. ואם תאמר סוף כל סוף יצוה להם משה על השבת ויאמר להם כי לא ילקטו אלא כשיעור זה הרגיל כדי להכיר הדבר, אין זה מהמוסר להבינם כי צריכין נם להצדיק דברי משה, לזה עשה ה' דבר חכמה:
@437 **ועוד** אם היה מקדים המצות על ידי משה עדיין יש מקום לטעות, על דרך מה שאמרו במנחות פרק רבי ישמעאל (ס''ה,) כשנטפל רבן יוחנן בן זכאי לבייתוסין הארורים ואמר להם עצרת אחר השבת מנין לכם ופטפט כנגדו זקן א' מהם ואמר לו משה אוהב ישראל היה ויודע עצרת יום אחד הוא עמד ותקנה אחר השבת כדי שיהיו מתענגין ב' ימים עד כאן. וכתבו התוספ' שם וזה לשונם עמד ותקנה והקב''ה הסכים על ידו עד כאן. הרי כי יש טועים שהגם שתהיה המצוה מפי משה יסכים הקב''ה על ידו, אם כן יש הפרש להקדמת ידיעת המצוה מנסיון אל עליון, לזה לא צוה ה' למשה לאמר לישראל דבר זה, ומעתה אחר שיצתה המחשבה אשר חשב אלהים והכירו ישראל הדבר תחלה אמר להם משה **הוא אשר דבר ה' אלי שבתון שבת קודש**. ואם תאמר למה לא הועיל ההיכר להשיג בו ידיעת שבת והוצרך משה לומר להם הדברים. הנה זולת דברי משה יטעו ויאמרו אולי נגמרה ירידת המן ולזה נתן להם ה' שלא כסדר הרגיל, לזה אמר להם משה **הוא אשר דבר** וגו' ולא לסיבה אחרת, ויוכר הדבר להם בהחלט כשירד המן יום א' אחר השבת. והוכרח משה לומר להם הדברים שהם בבל תאמר שלא יכשלו באותו שבת ויצאו אלא שלא אמר להם האזהרה בפירוש כאשר אבאר בפסוק עד אנה מאנתם:
@440 **אכלהו היום וגו'**. צריך לדעת למה הוצרך לצוותם על אכילתו. ואולי כי להיות שלא אמר להם אלא הניחו אותו למשמרת ולא פירש להם שיהיו מותרים באכילתו, והגם שלא מצינו שאסר בפירוש אכילת הנותר מכאן אתה למד שאסרו להם. או אולי דאסור מדין לא תאכל כל תועבה ואמרו ז''ל (חולין קי''ד:) כל שתעבתי לך הוא בבל תאכל, לזה אמר להם **אכלוהו היום**. ודקדק לומר **היום** לשלול יום אחר אסור הנותר לבקר, וכדי שלא תטעה ותאמר היום דוקא ולא יום אחר כל עיקר ואפילו שבת, לזה גמר אומר **כי שבת** וגו' הא למדת כי מיעוט היום לא בא למעט אלא שאינם שבת:
@440 **עוד** נתכוין באומרו **כי שבת** טעם למה שלאחריה על זה הדרך ולטעם שהיום שבת לא תמצאוהו בשדה, דקדק לומר **בשדה** לרמוז מאמר רבי שמעון בן יוחאי שאמר בזוהר (חלק ב' פח.) כי ביום שבת ירד המזון של כל ששת ימים למעלה ומאותו מזון יורד דבר יום ביומו, והוא אומרו **לא תמצאוהו בשדה** אבל למעלה בו ימצא אדרבה מזון לכל ו' ימים:
@441 **ששת ימים וגו'**. הכוונה בזה להזהירם לבל יצאו ללקוט, ופירוש **לא יהיה בו** לא יהיה בו מעשה זה של הלקיטה, שאם על הויית המן כבר אמר לא תמצאהו בשדה, ולזה כשיצאו מן העם ללקוט אמר ה' להם עד אנה מאנתם לשמור מצותי וגו' הרי שעברו על הלאו והיכן מצינו אזהרה זו שאמר להם כן, ואם כוונתו על דיוק הנשמע מאומרו ששת ימים לבד, לאו זה לא יקרא לאו אלא עשה כדין לאו הבא מכלל עשה (פסחים מא.) ולא יוצדק לומר להם עליו מאנתם לשמור כי לשון שמירה יאמר על הלאו:
@442 **ולא מצאו**. פירוש שאם מצאו היו לוקטין:
@443 **עד אנה מאנתם**. לפי מה שהעליתי בפסוק ויגידו למשה כי משה לא פעל און במה שלא אמר להם קודם ענין זה אם כן מה מקום לכוללו עם הממאנים לשמור מצות ה' ורבותינו ז''ל (בבא קמא צ''ב.) אמרו דבהדי הוצא לקי כרבא, ודבריהם ז''ל יצדיקו כי לא פעל מכשול. ולי נראה כי על כל פנים לא יכללנו הכתוב עם השאר אם לא היה לה' עליו חוט השערה מההקפדה. והצצתי במאמר משה בסמוך לפסוק זה שאמר לישראל ראו וגו' וצריך לדעת נבואה זו אימתי נאמרה למשה, אם נאמרה אחר שאמר לו עד אנה מאנתם קושיא לאלהינו למה לא צוה לו קודם לצוות ישראל אל יצא איש וגו', ואם נאמרה לו קודם איך לא אמרה משה לישראל:
@443 **אכן** זו היא שגיונו של איש האלהים כי ההתחכמות שנתחכם בהשכלתו בדברי ה' בטעם שלא אמר לו דבר וגו' או לאמר היה צריך לאומרה לישראל, והוא לא אמר להם אלא הוא אשר דבר ה' וגו' ולא אמר להם היוצא ממעשה זה אשר עשה ה' לחם משנה שהוא לתת להם השבת בדרך זה ממנו להם על דרך שפירשנו בפסוק (כ''ב) ויבואו כל נשיאי העדה וגו', והנה מזה יצא להם שיצאו ביום שבת קודש מן העם ללקוט כי חשבו כיון שלא אמר להם אזהרה בפירוש אלא דמפרש להם הענין הוא אשר דבר וגו' לא עשו הרגשה ויצאו ללקוט ולא חששו לזה עד אחר כך כשאמר להם אל יצא וגו' אז אמר הכתוב וישבתו העם וגו' הא למדת כי לא כן מקודם, אשר על כן כללו ה' ואמר עד אנה מאנתם. ולזה כשראה משה שהקפיד ה' עליו הבין הדברים ותכף אמר ראו כי ה' וגו', והם הדברים שנאמרו לו בתחילת דבר ה' בענין זה (פסוק ה') והכינו את אשר יביאו וכמו שפירשתי שם. והנה מכאן אתה למד שעל עיכוב מאמר זה לישראל כללו ה' עם הממאנים שהיה לו לומר לישראל כונת ה' כמו שהשיג לדעת הוא וכמו שפירשנו בפסוק ויגידו למשה. וסובר אני כי אין בדבר זה כדי להתיסר בשבט מוסר גדול עליו ליאמר לו עד אנה מאנתם כי הוא לא נצטווה וכחד ולא עבר אפילו על חוט השערה אלא שהיה לו להודיע לישראל מה שהשיג בדעת עליון כדי שלא ישגו לצאת כמו ששגגו ואין בזה עונש, לזה אמרו ז''ל בהדי הוצא לקי כרבא ליקוי שאינו ראוי לו:
@443 **מצותי ותורתי**. כי מצינו להם שעברו על ב' מצות, א' שאמר להם אל יותר ממנו והותירו, וב' שאמר להם תלקטוהו וביום השביעי לא יהיה בו הלקיטה ועברו ויצאו ללקוט לזה אמר עד אנה מאנתם לשמור מצותי, ואומרו **ותורותי** גם כן הם ב' תורות, א' כי ה' אמר להם שילקטו עומר לגלגולת והם לקטו יותר, וכמו שדרשו ז''ל (מכילתא) באומרו ולא העדיף המרבה, ובמעשה שבת גם כן לא הספיק להם מה שנתן להם משנה יום ששי ויצאו ללקוט יותר מעומר לגלגולת, וב' שלא האמינו במאמר ה' כי ביום שבת לא יהיה בו ויצאו וגו' ואין לך עובר על תורה כזה שאינו מאמין בתורת משה עבדו:
@444 **ראו כי ה' וגו'**. פירשתי למעלה שנתכוין משה לומר להם כי מצוה זו אינו צריך לאומרה הוא להם אלא הנה הם רואים אותה כי ה' נותן המצוה ממנו להם בלא שום אמצעי כמו שפירשתי בפסוק (כ''ב) ויגידו וגו' וזה למעלת השבת כי יראו ישראל הדכר בחוש הראות. ואומרו **אל יצא איש** פירוש כי ה' לא הוריד המן לצד שלא יצטרכו לצאת איש ממקומו וגו', ועיין מה שכתבתי בפסוק (כ''ח) עד אנה מאנתם:
@447 **ויאמר משה זה וגו'**. צריך לדעת אומרו **הדבר**. עוד צריך לדעת מצוה זו למי מצוה אותה משה, אם לאהרן הרי הוא אומר אחר כך ויאמר משה וגו'. ועוד כפל הדברים רואני כאן. ונראה כי כונת משה הוא על זה הדרך **זה הדבר אשר צוה** וגו' **מלא העומר** וגו' ולא אמר ה' מי יקחנו וגם לא אמר סדר לקיחתו, גם לא אמר מקום הנחתו אלא זה הוא הדיבור שיצא מפי ה' אלי ולא יותר, ויאמר אל אהרן שפט בצדק דעת חכם, כי פירוש למשמרת סובלת ב' דרכים, ומדרכי התורה כל שהתיבה תסבול ב' דברים שקולים במשמעותה תכוין אל הב' כי איזה מהם תוציא, וב' הדרכים הם, הא' למשמרת מן הטומאה, והב' מן שליחות יד. כנגד שליחות יד אמר מקום המשתמר באוהל מועד, גם שם מקום שצורכי ישראל נתונים שם התורה וכלי שרת וזה גם כן כלי שמשמש הוראת דבר אשר חפץ ה' להראות לדורות, וכמו כן עשה ה' במטה אהרן ובמחתות עדת קרח, ולזה אמר להניחו לפני ה', וכנגד שמירת טומאה אמר צנצנת אחת, ואמרו ז''ל (מכילתא) צנצנת דבר שהוא מציץ מחבירו שהוא כלי חרס שכל שצמיד פתיל עליו טהור, וב' פרטים אלו שמעם מדבר ה' באומרו למשמרת, ומעתה דן כי אהרן הוא הלוקח כי הוא הכהן המשרת במקדש ולזה ויאמר אל אהרן, ולבל יחשבו העם כי ה' אמר אליו לדבר אל אהרן ולקחת צנצנת וגו' לזה אמר הנאמן הגדול זה הדבר אשר צוה ה' ולא יותר, והחכם הבין הכוונה:
@447 **או** ירצה כי מתחילה כשקבל הנבואה סדרה לפני ישראל כסדר שמיעתה מאל עליון והיה חסר הידיעה מי העושה ומקום הנחת המן ומקום הנחת הכלי ולא ידע מה לעשות עד שבאה הנבואה פעם ב' ואמר לו ספקותיו, והוא אומרו בסוף המעשה **כאשר צוה ה' אל משה** פירוש לא תחשוב בדעתך כי פרטים שאינם מפורשים בדבר ה' שהם ג' הנזכרים משה מעצמו עשאן לא כן הוא אלא כאשר צוה ה' אל משה מפי עליון היו הדברים. ולדרך הראשון יתבאר אומרו **כאשר צוה ה'** וגו', יכוין הכתוב לומר כי הצדיקו עיונו של משה כאלו כן צוה ה' אליו כאשר שפט בדברים הסתומים כמו שפירשנו:
@447 **למשמרת לדורותיכם**. אמר לשון רבים, אחת היתה בדורו של ירמיה, ואחת תהיה לעתיד לבא כמאמרם ז''ל (מכילתא, כ''א תנחומא ג') שלשה דברים עתיד אליהו להעמיד לישראל ואחד מהם היא צלוחית של מן:
@450 **את המן אכלו וגו'**. הוצרך לומר פעם ב' את המן ולא סמך על הזכרתו בסמוך, להיות שיש שינוי בין אכילת המן שאכלו עד בואם אל ארץ נושבת למן שאכלו עד בואם לקצה ארץ כנען שהוא קודם העברת הירדן כי אותו שעד ארץ נושבת היה מהמן שבכלים לא שהיה יורד יום יום, לזה כשרצה להזכיר המן שאכלו עד בואם אל ארץ כנען זכר אותו בפני עצמו לומר כי ישתנה זה מזה, והשכל יכיר זה כי כל שיוסיף להתרחק זמן שהיה קרוב למקור שנתהוה ממנו יגשם יותר. עוד אמרו ז''ל (קידושין ל''ח.) וכי מ' שנה אכלו והלא חסרים ל' יום מט''ו בניסן עד ט''ז באייר אלא שהיו טועמים בעוגות טעם כמן. וראיתי לדקדק הכתוב למה שינה לשונו בתחילה כתיב **אכלו את המן** הקדים זכרון האכילה לזכרון המן, וכשהזכיר המן פעם ב' אמר **את המן אכלו** הקדים זכרון המן לזכרון האכילה. הנה הכתוב ידקדק לשונו לומר כי ישתנה חשבון מ' שנה שמנה באכילת המן למה שמודיעך שאכלו המן עד בואם וגו' מלבד ההפרש שכתבנו של ירידתו יום יום או מהשמור, כי המן שנכנס בחשבון מ' שנה אינו אלא בערך מה שהיו טועמים באכילתן, והוא שהקדים זכרון אכילה קודם זכרון המן לומר כי לצד האכילה הוכר היותו מן שהיו טועמים בעוגותיהם מן אבל אין כל המ' שנה מן ממש שהרי ל' יום אכלו מה שהוציאו ממצרים עוגות, וכשרצה להגביל שיעור זמן אכילת המן הקדים זכרונו לומר אין זה נחשב מן לצד שטעמו כן אלא לפי מה שהוא כפי האמת ודו''ק:
@452 **ויחנו ברפידים ואין מים**. לדבריהם ז''ל (בכורות ה:) אין רפידים אלא רפיון ידים מן התורה יכוין הכתוב לומר כשרפו ידיהם מן התורה שנמשלה למים לזה גם ה' מנע מהם המים מדה כנגד מדה:
@453 **וירב העם וגו'**. פירוש והמריבה הוא שאמרו להם בדרך זה תנו לנו מים וכי משה יש לו מים לתת להם אין זה אלא מריבה שאם היתה כוונתם לשאול כי יצעק אל ה' היה להם לומר כדרך שדברו אליו (חקת כא ז) כששלח ה' בהם נחשים שרפים. או אפשר שהיו תובעים המים כמי שתובע חוב מחברו ואומר לו תן לי מה שאתה חייב לי, ואמרו לשון רבים ודבריהם עם משה לבד, כאן כללו לה'. ולזה אמר להם משה **מה תריבון עמדי מה תנסון את ה'**. ואמר בסדר זה כי בערך ה' כבר ידעו כי כל יכול אלא מנסים אם יש בקרבם:
@454 **ויצמא שם וגו'**. הנה הענין יוליד התימה למה יביאם ה' אל הנסיון הגדול הזה למות בצמא, וכפי השכל ישער אדם שדבר זה וכדומה תוליד הכפירה. ועוד תגדל הקושיא על משה שבמקום שיאזור חלציו בתפלה ובתחנונים בא בטענה לפני ה' עוד מעט וגו' שיראה כי לא חשש על צמאונם ועל מות בני ישראל בצמא כי הכתוב מעיד כי צמאו למים:
@454 **ונראה** כי ה' ניסה אותם להדריכם לשאת עיניהם ולהתפלל לפני ה' כי זה עיקר גדול באמונה ובהשלמת הנפש. ותמצא שנתחכם ה' על הדבר ולא נתן להם מן יום לחודש אלא דבר יום ביומו, ואשר על כן מנע מהם הנם עד שיתחננו למול קונם וישמע צעקתם, ומודיע הכתוב כי במקום שיצעקו לה' היו מריבין עם משה וכשתקף עליהם הצמאון וילן העם על משה, לזה סדר הכתוב סדר המעשה ויצמא וגו' וילן וגו', לומר שלא עשו דבר זולת זה הא למדת כי לא צעקו לה'. וכן העיד הכתוב על נסותם וגו' היש ה' בקרבנו אם אין הא למדת כי לא היו מצדיקים בההשגחה. והן האדון ברוך הוא היה מכריחם לצעוק אליו ולהסיר המחשבה הרעה באמצעות תוקף הצמאון, וכל זה השכיל והבין משה ולזה לא התפלל אל ה' והיה מצפה לתקות האדון מהם, וכשראה כי גדול הכאב אמר לפני ה' **מה אעשה לעם הזה** פירוש מה אעשה להם להרחיק תלונתם מעלי ומזה תדע כי הרגיש משה כי אין דבר זה תלוי בתפלה שאם לא כן היה מתפלל כמו שעשה על הים, ולו יהיה שלא נענה היה מוסיף בתפלה עד שיענהו ה', וטען עוד לפני ה' **עוד מעט** וגו' פירוש אם תוסיף לצערם עוד מעט תולדות הדבר שתצא מהם היא וסקלוני, ולו יהיה שאחר תוסיף לצערם עד שיצעקו לפניך בבכיה רבה ותצא כוונת ה' לפועל אבל ביני ביני וילך משה בסקילה, וזו טענה הנשמעת. וראיתי לתת לב איך עם ה' הרואים דברים המופלאים והנוראים במצרים ועל הים ובמדבר יטעו בדבר ולא יצעקו אל ה' והלא הם המכירים תועלת הצעקה כי שמע את נאקתם במצרים. ואולי כי דעתם היה שאין צורך לתפילה על הדבר כל שה' ישנו בתוכם, כי אחר שהביאם למדבר פשיטא שלא הביאם אלא לספק צורכם שאם לא כן הלא המה אבודים ולא יצטרכו לתפלה ואין זה אלא שאין ה' בקרבם, והוא הנסיון שאמרו היש ה' בקרבנו וגו':
@456 **עבור לפני העם וגו'**. אולי שידע ה' כי גדל הצמאון בעם ויהיו מסתכנים אפילו בזמן מועט, לזה אמר כי מדי עוברו יעבור לפני העם פירוש בדרך שידעו שאתה הולך למצוא להם מים כדי שישקוט אש הצמאון מהם ביני וביני ולא תעבור דרך שלא יהיה לפניהם, וגם קח עמך הזקנים כדי שתהיה ההרגשה:
@456 **אשר הכית בו וגו'**. וזה יהיה לנס עצום כי זה אשר הבאיש המים הנמצאים ועשאם דם יפעול בכח עליון פעולה נגדיית שימציא מים לשתות העם. ויש בזה הכחשות מופלאות מנגדות למתחכמים להכחיש כי הם פלאות אלהי ישראל במטה זה תבקע קרקפתו החושבת זרות:
@457 **הנני עומד וגו'**. פירוש לפניך במקום זה ושם על הצור, כי מלא כל הארץ כבודו בתמידות באין השתנות מקום שלא יהיה בו שוכן השוכן אלא יש מקום שתגדל בו השראת שכינתו יתברך, או כפי מעלת הכנת המקום כמקום המקודש, או כפי השרויים בתוכו:
@459 **ויבא עמלק וגו'**. להיות שנתעצלו בתורה שנמשלה למים ולאש דכתיב (ירמי' כ''ג) כה דברי כאש ולא נתעסקו במלחמתה של תורה, לזה הענישם בצמאון כנגד בחינת המים ובאש המלחמה של עמלק:
@460 **ויאמר משה אל יהושע**. נתחכם משה כשהכיר העון שהוא לצד ביטול מלחמת התורה אמר אין ראוי לצאת למלחמה אלא יהושע שנאמר עליו (לקמן ל''ג י''א) לא ימיש מתוך האוהל בעסק התורה, ואמר לו שיבחר כיוצא בו ובזה יתגבר עליו וכן היה:
@465 **ושים באזני וגו'**. צריך לדעת למה נתיחד מאמר זה ליהושע לבד. ואולי כי לצד שראה יהושע עוצם הכעסת עמלק ותוקפו ולא היה בו כח לעשות בו כליון אלא שהחלישם לבד ויש בלבו של צדיק איך לא עשה ה' מה שראוי לעשות ברשע זה, לזה בא ה' להפיג צנתו וצוה למשה לאמר לו באזנו פירוש כי הדבר הוא להשיב למה שבלבו של יהושע ואמר לו כי לא ידאג על הדבר מחה אמחה וגו' ודבר ה' כאילו כבר היה ותהיה זאת נחמתו. וטעם כפל מחה וגו' אולי שרמז לנו זמנים שימחה בהם, א' בימי שאול וכנגדו אמר מחה, ב' בימי מרדכי וכנגדו אמר אמחה, ואחת לעתיד וכנגדו אמר מתחת השמים:
@465 **חסלת פרשת בשלח**
@468 **וישמע וגו'**. צריך לדעת לאיזה ענין יחסו בייחוס כהן מדין שאין זו מעלה אלא ירידה ומן הראוי ראשונות לא תזכרנה. ואולי כי יכוון שבח האיש באומרו **כהן מדין** לומר שהגם שהיו לו ב' בחינות הרמוזות בכהן מדין שהם היותו ראש למדין ואדוק לעבודה זרה אף על פי כן עשה ב' דברים נגדיים והפכיים לב' הפרטים. כנגד היותו גדול אמר **חותן משה** שנתחתן לאדם שלא נודעה לו גדולה עדיין, ודבר זה יקפידו עליו נוהגי שררה ואין צריך לומר א' המיוחד לאומתו שיקפיד לתת בתו לאדם בלא שם, וכנגד היותו אדוק לעבודה זרה כמשמעות המובן מתיבת כהן אמר הכתוב (י''א) מה שאמר בסוף הענין עתה ידעתי כי גדול ה' מכל האלהים ודבר זה אין בו חידוש ומעלה גדולה באמור כן גוי א' לקובעו בתורה אלא באמצעות מה שקדם ליחסו בשם כהן מדין דבר גדול הוא שכהן אומה אחת מהם ובהם יעיד על כי הכל יפצה פיהם:
@468 **עוד** טעם אומרו **כהן מדין** לומר באמצעות כן השיג לדעת כל אשר עשה ה', כי לאנשים הגדולים יתגלה ויודע הכל בצדק בלא תוספת וגרעון מה שאין כן לשאינם רשות הגם שיודע להם החדשות לא ידעו כל הדברים הנעשים:
@468 **את** כל אשר וגו' גם זה יגיד שבח האיש שהשתדל לדעת כל פרטי המעשים, וזה יגיד כי אהב את יעקב, שהלא תראה איש שונא לרעהו יקוץ בהגדת שבחיו וטובו ויחדל מדעת מצבו הטוב, אשר לא כן אהוב לאהובו, ורשם ה' בדתו כי זה האיש אהב את ישראל. עוד ירצה בדקדוק עוד למה הוציא הכתוב פרט זה של הוצאת ישראל ממצרים מכלל כל אשר עשה. ועוד כי הוא עיקר כל אשר עשה ולא היה צריך לפרשה:
@468 **אכן** לצד כי יתרו מן הסתם ידע תוקף שבית מצרים כאמור בדבריהם (מכילתא) כי אסירי מצרים לא פתחו מעולם, ומה גם לדבריהם (סנהדרין קו. שמו''ר פ''א) שאמרו כי יתרו היה מיועצי פרעה ובקי במצרים ואסיריה, ולזה הגם שישמע כי הוציא וגו' לא יצדיק היציאה בלבו, לזה הקדים הכתוב דבר שממנו הצדיק כי הוציא ואמר **וישמע יתרו את כל אשר עשה** פירוש כל הנפלאות והנוראות אשר עשה ה' בהצדקת נביא, והוא אומרו **אשר עשה למשה** והנפלאות שעשה להצלת ישראל בין ברדיית מחזיק בם בין בהפלאתם מהמכות בין בנס הים וכו' ובזה ידע **כי הוציא** וגו', ולזה לא אמר וכי הוציא וזולת שמיעת כל הנעשה מהפלאים לא היה מצדיק הגם שישמע ששלחם כי לא יאמין ואם יאמין לא יבטח כי יאמר שוב ירדפו אחריהם ואם רדפו ולא יכלו יכינו עוד מחנה וירדפו:
@468 **אכן** במה ששמע **כל אשר** וגו' הצדיק כי הוציא. ותמצא כי רבותינו ז''ל נחלקו (זבחים קט''ז.) באיזה מהשמועות נרגש מהם אמרו קריעת ים סוף ומהם אמרו מלחמת עמלק, וזה מתאים לדברינו. ולדברי האומר מלחמת עמלק ממה שסמך לו וישמע, זה יגיד כי לא הספיק לו כל מה ששמע מהנפלאות כי יתלה שהסובב הוא פחזותו של פרעה שהתרים כנגד שלוחו של מקום לא לצורך הצלת ישראל כי לא היה ה' טורח כל כך בשבילם וכפי זה אין בטחון לישראל מעמים אשר יקומו עליהם לזה אמר הכתוב ששמע מלחמת עמלק, וכבר הפליאו רבותינו ז''ל (מכילתא) לומר מה עצמה המלחמה הארורה. ונראה לפרש לדרך זה אומרו כי הוציא פירוש לצד ששמע כל אשר עשה ובכלל זה מלחמת עמלק בזה הצדיק כי כל המופתים לא היו אלא למעלה ולחיבת ישראל להוציאם ובשבילם עשה כל אשר עשה ושמיעת עמלק יגיד:
@468 **עוד** ירצה באומרו **כי הוציא** לסמוך אחריה הגדת קיחת יתרו את צפורה וגו' על דרך אומרם ז''ל (שמו''ר פ''ד) כי אמר יתרו למשה למה אתה מוליך אשתך וכו' אמר לו עתידין ישראל לקבל התורה על הר סיני ולא יהיו בני בכלל אמר לו לך לשלום וכו' עד כאן, ולזה אמר הכתוב **כי הוציא ויקח** וגו' לקיים דברו:
@469 **ויקח יתרו חותן משה**. פירוש לצד שהיה חותן משה מצא עשות ככה שהלך להר האלהים וגו' שהניחוהו מיראתו של משה כי נפלה אימתו על כל העמים, אבל זולת זה היו מונעין אותו מלכת לכפור באמונתם ומה גם שחשוד היה בעיניהם, ותמצא שכל אומה תחייב מיתה לכופר באמונתם, ולצד היות יתרו לחותן משה היא שעמדה לו, ואולי שירמוז עוד כי הגם שהיה ליתרו כינוי של גדולה ליקרות כהן מדין מאם בכינוי זה ולקח לו כינוי חותן משה, והוא אומרו **ויקח יתרו** ומה לקח מהב' יחוסין שיחסו הכתוב בתחלה, **חותן משה** לא כהן מדין:
@469 **אחר שלוחיה** טעם שהוצרך לומר אחר שלוחיה, גם דקדק לומר לשון שלוחין, וזולת דברי רבותינו ז''ל (שמות רבה שם) שכתבתי בפסוק את כל אשר עשה וגו' נראה לומר כי משה גרשה כשראה שהיה עוסק במצות שליחותו יתברך לא ידע שיעור הזמן ושלחה מביתו, והבנים אליעזר קטן היה וצריך לאמו שנולד בדרך במלון, וגרשם מן הסתם קטן היה סמוך לאליעזר מלפניו, או לדבריהם ז''ל שאמרו (מכילתא) שהתנה עם יתרו בן אחד לבת ובן ב' לאב, לטעם זה נמצאו שניהם בידה, וכוונת הודעת ה' הדבר כאן לומר שבח יתרו ומעלת משה בעיניו שהגם ששלחה לקחה וטרח בכבודו ובעצמו להוליכה לו אפילו אחר שלוחיה, אלא לדבריהם ז''ל (שמו''ר) שאמרו שלא שלחה אלא סמך על הבטחת יתרו כי ידיו תביאנה, נראה לומר כי טעם אומרו **אחר שלוחיה** פירוש שלא היה הדבר אלא עד שקדמה ושלחה לו למשה שלוחים וידעה מקום תחנותו והסכים על ידה אז הוא שלקח יתרו וגו' ויבא אל המדבר וגו':
@470 **שם האחד גרשום וגו'**. הוצרך לכתוב טעם השם פעם ב' אחר שכתבו בפרשת שמות (לעיל ב' כ''ב) כדי שתדע כי הוא זה האמור בפרשת שמות ולא אחר שנקרא על שמו:
@470 **עוד** אולי כי חש הכתוב שיאמר האומר כי טעם שקרא לו שם גרשום הוא לצד שגרשו יתרו מעל שלחנו או מביתו, והגם שאמר הטעם גר הייתי וגו', אולי כי לצד שלא ירגיש יתרו אמר כן, לזה חזר הכתוב והצדיק הדברים אפילו בזמן שלא יחוש להרגשת יתרו כי טעם **שם** וגו' **כי אמר** וגו'. ופירוש משמעות כי אמר גר וגו' פירשתיו בפרשת שמות (שם):
@471 **ושם האחד אליעזר וגו'**. טעם אומרו **האחד**, כי לצד טעם קריאת השמות טעמו של זה קדם לטעמו של שם גרשם שבתחלה הצילו מחרב פרעה ואחר בא למדין וגר שם, וטעם שלא הקדים קריאת שם אליעזר הוא כי קרא למאורע שהיה בו אז בארץ נכריה ואחר כך הלך לחפש מאורעות קודמות, או לפי מה שפירשנו בפסוק גר הייתי (שם) שיכוין על גרותו בעולם הזה בחינה זו קדמה להצלתו מחרב פרעה ולזה הקדימו, ולצד בחינת גרות ב' בארץ נכריה קדם לו כוונה הרמוזה בקריאת שם אליעזר וכנגד זה אמר האחד ולזה הוצדך לפרש מה הוא העזר שכנגדו קרא לו שם ואמר **ויצילני** וגו', ובזה יוצדק לומר עליו שם **האחד**, וזולת אומרו ויצילני מחרב פרעה הייתי מפרש שהעזר הוא אחר הגרות והקדימה שהקדים לומר גר הייתי וגו' תחייבני לפרש כן ויסתם בפני ידיעת טעם אומרו האחד:
@472 **אל המדבר וגו'**. פירוש ואם תאמר מנין ידעו מקום תחנותו במדבר הגדול, לזה אמר **אשר הוא חונה שם** וגו' פירוש וכבר הודיעו משה מקום אשר דבר אתו שם האלהים ואמר אליו (לעיל ג' י''ב) תעבדון את האלהים על ההר הזה והודיעו ההר שעליו יקבלו התורה, והוא אומרו אשר הוא חונה שם הר וגו' הידוע אצלו. ותמצא שאמרו ז''ל (שמו''ר פ''ד) שאמר משה ליתרו ענין קבלת התורה וכתבתיו בתחלת הפרשה ותהיה הודעת הר האלהים מכלל מה שהודיעו:
@473 **אני חותנך וגו' ואשתך וגו'**. טעם ששינה הכתוב סדרם כאן מסדר שכתב בפסוק שלפני זה שהקדים הבנים לאשה, יתבאר על פי דבריהם ז''ל (מכילתא, שמו''ר כאן) שאמרו אם אין אתה יוצא בגיני וכו', אם כן ממטה למעלה סדרם הכתוב, לזה הקדים האשה לבנים שאם לא יעשה בשבילה יעשה בשביל הבנים, מה שאין כן כשהודיע הכתוב ביאתם למדבר וסדרם סדר החשוב חשוב קודם הקדים הבנים, והגם שהקדים שם יתרו לבנים וכאן סדרו קודם לאשה שיורה שהוא למטה ממנה, הוא יתרו דבר בענוה ושפלות אבל הכתוב כבדו והקדימו לצד היותו חותנו של משה וצריך לכבדו אפילו משה דכתיב (ש''א כ''ד) ואבי ראה גם ראה:
@473 **ושני** בניה עמה. טעם אומרו **עמה**, נתכוון לומר חלוקה רביעית שאם אין אתה עושה בגינה לבד ולא בגין בניה לבד צרף כבוד שניהם וצא:
@474 **ויצא וגו' לקראת חותנו**. פירוש לצד שאמר לו יתרו אם אין אתה יוצא בגיני וכו' לזה אמר הכתוב **ויצא משה לקראת חותנו** כי כבודו של חותנו הספיק לו לצאת לקראתו. ואולי שעשה היכר לדבר שיצא ביחוד לקראתו ולא פנה ביציאתו למקום אהל האשה וילדיה, או שהיה אומר בפירוש שיציאתו הוא לקראת חותנו, גם לדבריהם ז''ל (מכילתא) שמשה הוא שהשתחוה ליתרו זה לך האות כי לכבודו יצא, ולזה אמרו ז''ל (שם) כבוד גדול נתכבד יתרו וכו', וזולת דברינו מנין לו כבוד מיציאה זו דלמא לכבוד בניו ואשתו יצא משה:
@474 **וישתחו וגו'**. רבותינו ז''ל (שם) אמרו איני יודע מי השתחוה למי כשהוא אומר איש מי הוא שקרוי איש זה משה עד כאן. הנה טעם שלא אמרו כי שניהם השתחוו זה לזה לצד שאמר לשון יחיד וישתחו וישק לו זה יגיד כי אחד לבד השתחוה. ואם תאמר לדבריהם ז''ל והלא מצינו שגם יתרו נקרא איש דכתיב (לעיל ב' כ''א) ויואל משה לשבת את האיש, יש לחלק בין קריאת איש של יתרו לקריאת איש של משה, וקודם אעירה שחר מה מעלה יש בשם זה של איש והלא כל אדם יקרא איש ונקבתו אשה, וגם בבהמות מצינו שאמר הכתוב בפרשת נח (בראשית ז') שבעה איש ואשתו, אלא שישתנה שם איש כשיהיה במקום זכרון האדם ויוסף לו ליווי קריאת איש זה יגיד שהוא לשון מעלה לבמקום שיאמר איש בלא זכרון שמו זה ימצא במקום השם ולא יגיד מעלה, כמו שתאמר (בראשית כד כא) והאיש משתאה לה, וימצאהו איש (בראשית לז טו), וגם זכרון אנשים שאמרו ז''ל (במד''ר פט''ז) שהוא לשון חשיבות דוקא בצירוף זכרון שמם דכתיב (במדבר יג ג) כולם אנשים שאחר שזכר שמם חזר לומר כולם אנשים זה יגיד לשון חשיבות, מה שאין כן כשיהיה במקום הזכרת שמם כנוי זה אין זו מעלה כאומרו (במדבר כ''ב ט') מי האנשים האלה עמך והנה מצינו שאמר הכתוב (לעיל י''א) גם האיש משה, כי זה משה האיש (לקמן ל''ב) הרי הזכיר שמו והוסיף לומר האיש זה יגיד כי למעלה ואדנות יכוין, וזה הוא אומרם מי הוא שקרוי איש זה משה פירוש איש לשון שררות וממשלות, אבל יתרו הגם שמצינו לו שנקרא איש לא מצינו אותו בליווי אלא במקום זכרון שמו אמר האיש והוא שם הצודק על כל נברא זכר, ומעתה כשאמר הכתוב כאן **איש** הדבר שקול אם הוא כנוי הרגיל בבחינת הזכרים או פירושו הוא איש הרשום למעלה וחשיבות, ותיבה זו מונחת בין יתרו ובין משה אם נאמר שפירושו הוא כנוי לזכר יכנם במשמעות גם יתרו ושניהם שקולים במשמעות ואין אני יכול לעשות שניהם שהרי הכתוב לא אמר אלא אחד כמו שדייקנו מאומרו וישתחו, ואחד זה אין אני יודע מי הוא ולא בא הכתוב לסתום אלא לפרש, ובהכרח לומר כי פירוש **איש** האמור כאן הוא לשון חשיבות ובאומרו כן נתחייב לומר כי זה הוא משה האיש שאליו נתייחד חשיבות זה ולא ליתרו ובזה לא סתם הכתוב כוונתו והרי פירש שעל משה הוא אומר:
@475 **ויספר משה**. הגם שאמר הכתוב וישמע וגו' את כל אשר וגו' אולי שהיו פרטים שלא שמעתן אזנו. או אפשר שלא הצדיק הפלאות לצד הגזמת העניינים, או שהגם שקדם לו מהידיעות עדיין היה מסתפק שלא נרתק חבל מצרי שעל צואריהם, וספר לו משה ענין שלא היה יכול לדעת מזולתו והוא הריגת שר מצרים שאמרו רבותינו ז''ל (זהר ח''ב נ''ב:) שראהו ישראל מת ובזה החליט יתרו כי פקע נירם מעליהם, ואולי כי זה הוא שרמז הכתוב באומרו **את כל התלאה אשר מצאתם בדרך ויצילם** וגו' שהודיעו מרדיפת השר כי יתרו כהן מדין היה ומן הסתם הם יבחינו וידעו כי יש שרי מעלה על כל אומה וספר לו כי רדף אותם הוא בעצמו דכתיב (לעיל י''ד י') והנה מצרים נוסע אחריהם ומזה רעשו ופחדו ישראל וכמו שפירשנו שם, וכששמע יתרו כן אמר **ברוך** וגו' **מתחת יד מצרים** שהוא השר שמצרים שמו ונכון:
@476 **ויחד יתרו**. תרגום אונקלום וחדי. וצריך לדעת למה ידבר הכתוב כאן ארמית ולא אמר לשון ברור שהוא לשון הקודש. והגם שאמרו ז''ל (סוטה ל''ב.) בשבעים לשון, אף על פי כן דבר יגיד בשנותו את טעמו. ונראה כי יודיע הכתוב כי מרוב השמחה נתחדד בשרו, כי תמצא כשתהיה לאדם שמחה והוא דבר שלא כפי המשוער במושג הרגיל תולד בו הרגשה בהרכבת מזגו ולפעמים יתעלף ולפעמים יסתכן ממש, ועיין מה שפירשתי בויגש בפסוק (בראשית מ''ה כ''ו) לאמר עוד יוסף חי. והנה יתרו הגם שקדם אצלו ידיעה מבשורות הטובות אף על פי כן כששמע תוכן הנס ומה גם ברדיפת המלאך אותם כמו שפירשתי בפסוק (ח') ויספר משה והצילם ה' נתחדד בשרו, ודבר זה מורגש הוא אצל כל בעל חי מרגיש:
@478 **עתה ידעתי וגו'**. פירוש כי הגם שיש לאומות שרים גדולים ועצומים להלחם בעדם ולהרע לאויביהם וכל מרים יד כנגדם אף על פי כן לא יכוונו להנקם מהאומות הנגדיית בדמיון המרד מה שאין כן אלהי ישראל שיכוין למדוד במדה עצמה של המורד ועושה רשעה שקע שוקעיהם וכו', גם יש לתלות במאורע הרע כי לא מצד שכנגדו הוכה מה שאין כן אלהי ישראל שכל המכות והיסורין אשר יסר פרעה הם מכוונים למה שזדו עליהם. וצא ולמד מה שאמרו ז''ל (תנחומא) בכוון המכות שכל אחת כנגד מדה אחת רעה שזדו המצריים וכו':
@479 **ויקח יתרו וגו' עולה וגו'**. הנה נתחכם יתרו לזבוח שלמים רבים, וזה היה לו לאות כי מזמין הוא גדולי ישראל על שולחנו, ולזה לא אמר הכתוב ויקרא לאהרן ולזקני ישראל לאכל וגו' אלא **ויבא אהרן** וגו' פירוש מעצמן באו כי מעשיו מוכיחים ההזמנה כדי שלא יבואו קדשים לידי נותר וכבדוהו ובאו מעצמן אהרן והזקנים ולא הטריחוהו להזמינם על הזבח:
@482 **כי יבא אלי העם וגו'**. קשה מה תשובה זו עושה והלא ראה יתרו כי בא אליו העם לדרוש וכוונת קושיתו הוא למה יתנהג במנהג זה כי יש טורח לעם. ודבריו ברור מללו אתה יושב לבדך פירוש ואין שופטים אחרים לדון העם, ולו יהיה שלא הבין משה דבריו, היה לו לשאול גזירת הדיבור לא שיאמר לו דברים שעליהם הוא מקשה. ונראה כי משה הבין בדברי יתרו במה שאמר **אשר אתה עושה** וגו' משמע כי משה מכריחם ומחייבם שלא לעמוד לפני דיין זולתו וזה סיבה שסובלים העם הטורח ואם יחפוץ ימנה עליהם דיינים וילכו לדון לפניהם, לזה השיבו כי לא ממנו אלא מהעם כי יבא מעצמו אלי ולא לזולתי חפץ ללכת, ולצד שיקשה לך למה יחפצו בטורח זה, הטעם הוא **כי יהיה להם דבר בא אלי** ואמרו ז''ל (זהר ח''ב ע''ח.) בא אלי הדבר עצמו ויצטדק הדין לאמתו, ודבר זה לא ימצא בזולתי:
@482 **ומעתה** אין מציאות למנות דיינים וילכו העם לפניהם, וגמר אומר **והודעתי** וגו' פירוש גם דבר זה אי אפשר בזולתי. ויתרו נסתפק במשמעות דברי משה שסובל ב' דרכים. הא' כי לצד שבאים אצלו העם הוא חש על המצוה לדון בין איש וגו' לעשותה הוא ולא אחרים, והב' כי העם לא יחפצו לזולתו לצד מה שפירשנו בדבריו, לזה השיבו כנגד המובן מדבריו כי יבחר עשות המצוה בעצמו ולא ימנע עשות טוב אמר **לא טוב הדבר אשר אתה** וגו' כאשר יבאר הטעם. וכנגד מה שמובן מדבריו כי העם לא יתרצו ללכת לזולתו אמר **איעצך** וגו' **היה אתה לעם** וגו' **ואתה תחזה** וגו' **ושפטו את העם בכל עת** פירוש בכל דין שיהיה המשפט רצוי לב' בעלי דינים ומן הסתם כשידונו להם משפט רצוי למה יבחרו בטורח הגדול, **והיה** וגו' פירוש וכשיהיה דבר גדול של התעצמות הדין בין לצד השופטים שלא יוכלו השג בין לצד הנשפטים שלא יתרצו ב' הכתות במשפטם יביאו אליך, ולא לצד פרט זה תתחייב בכל:
@485 **נבל תבל**. כפל לומר **נבול** וגו', להיות כי יש ב' גדרים במשמעות **תבול**, הא' כל שיגרע כל שהוא מכחו הראשון יקרא עליו הלאות לערך הקודם אבל על כל פנים יכול עשות מה שהיה עושה קודם במעט יגיעה. והב' הוא הלאות הנרגש לכל שהוא גדר המונע האדם מעשות חפצו לצד כי לא ישאר בו כח, לזה אמר אליו כי מה שיגיע אליו מהלאות כח לא שיעור מועט אלא שיעור שכפי האמת יקרא לו **תבול**, והוא מה שגמר אומר **לא תוכל עשוהו לבדך**. או אולי שכפל כנגד מה שאמר גם אתה גם וגו':
@485 **גם אתה גם העם הזה**. טעם אומרו **גם** בחלוקה ראשונה ושניה, ירצה לא מבעיא זולתך במצב זה אלא **גם אתה** כי רב חילך, ואומרו **גם העם הזה** פירוש ישראל לצד שצריכין להמתין זה לזה בדין כמעשה האמור בענין ויעמוד וגו' ואומרו תיבת **גם** לצד שטרחם אינו מקובץ ביחיד. ורבותינו ז''ל (מכילתא) אמרו גם זה אהרן העם אלו הע' זקנים, וצריך לדעת טעם רבותינו ז''ל שפירשו כן, ואם לצד גם היה להם לפרש כמו שפירשנו. אכן לצד שראו כי בעצתו אמר שימנה סך גדול מישראל שרי אלפים וגו' שעולה בהם למנין שמונה רבבות גילה דעתו כי לא יספיקו ע' זקנים. ולדבריהם ז''ל יתפרש אומרו **גם** מלבד הזקנים, **וגם** שנית פירוש מלבד משה, ויש רבותא בכל אחד, משה לצד מעלתו, והזקנים לצד היותם רבים, או אפשר שנתכוון באומרו **גם אתה** לרבות העם שיגיע להם הלאות אנשים כשיהיו ממתינים זה לזה בדין, ואומרו גם ב' לרבות הגם שיצטרף הוא עם הזקנים:
@488 **ואתה תחזה**. פירוש לא שהעם ימנו עליהם אלא הוא יחזה. עוד רמז כי לצד זה יחשב כאלו הוא השופט כיון שהם שלוחיו ויטול חלק במצות:
@488 **מכל העם**. פירוש הגם שימצא בני אדם שיראה בעיניו כי הם ראויים לדבר, אף על פי כן לא יהיה מתרצה בהם עד שיבקש כל העם ויקח הגדול שבכולם בכל בחינה מבחינות הטובות המנויות בדבריו:
@488 **אנשי חיל וגו'**. אמר ד' הדרגות כנגד ד' מינוים המוזכרות בדבריו, כנגד שרי אלפים אמר **אנשי חיל**, תיבת חיל תגיד עוצם השלמת האושר והמדות והגבורה וכללות השלימות, כי כן צריך להיות שר האלף, וכנגד שרי המאות אמר **יראי אלהים** כי לצד פרט זה לא יצטרך כל כך אלא כשיהיה ירא אלהים ראוי להתמנות שר למאה, ודקדק לומר **יראי אלהים** שצריכין להיות יראים יראת העונש, כי יש לך לדעת כי הירא בבחינת שם הוי''ה לצד שיהיה בדעתו כי ה' רחום וחנון לפעמים יחטא ויסמוך על רחמיו כי יאריך אפו וכדומה אבל יראת העונש תרעיד המשכיל, וכמו שתמצא שכל גדולי עולם יראים מדקדוקי המשפט הגם כי יודעים שמעשיהם ישרים ונכונים, וצא ולמד ממאמר חכמינו ז''ל (חגיגה ד') שאמרו במעשה בעלת אוב כשעלה שמואל והביא עמו משה רבינו ע''ה יעויין שם דבריהם, ואשר על כן אמר יראי אלהים כי צריכין להיות בגדר יראה מדקדוקי המשפט באין רחמים, ובחינה זו ישנה גם כן בשרי האלפים אלא שנוסף בהם פרטים אחרים שאין צורך להם בשר המאה, וכנגד שרי חמשים אמר **אנשי אמת** שיספיק לגדר זה הגם שלא השיגו לבחינה זו של יראת עוצם הדין אלא שיהיו אנשי אמת שישתדלו על העמדת האמת לבל תהיה נעדרת, וכנגד שרי עשרות אמר **שונאי בצע** די להם גדר זה ובזה יהיו ראוים להיות שרי עשרות, ודקדק לומר **שונאי** פירוש כי יהיה להם הדבר שנאוי לא שיצטרכו להרחיק תאותם כי לאלה יש חשד שינוצחו מהרשע המפתה וכל מדות הג' ישנם באנשי חיל, וכל מדות הב' ישנם ביראי אלהים, ומדת שונאי בצע ישנה באנשי אמת והם זו למעלה מזו, ולזה לא אמר ויראי וגו' ואנשי אמת ושונאי בצע אם כולם יתקבצו יחד באדם א' היה צריך לומר וא''ו בכל אחת או לפחות בחלוקה האחרונה אלא ודאי כמו שכתבתי שאין צורך לזה בכל הפרטים. והנה פשיטא שאם ימצא ממין המשובח שבכולן לכל המנויים מה טוב ומה נעים, ולזה כשבקש משה בישראל מצא ממין המשובח אנשי חיל שיעור שיספיק לכולם כאומרו ויבחר משה אנשי חיל מכל ישראל ולא הוצרך לפרט שאר הפרטים כי ישנם בבחינת אנשי חיל, וזה יצדיק לך גם כן פירושינו בדברי יתרו, שאם כוונתו לומר זאת ועוד אם כן היה לו למשה לבחור גם כן כל הרמוזים בדברי יתרו, ואין לומר חם ושלום כי לא מצא בישראל יראי אלהים אנשי אמת וגו' אלא ודאי כדברינו שלא הזכיר יתרו שאר הפרטים אלא לצד שחש יתרו שלא ימצא שיעור המספיק מבחינה הגדולה והיה מסתפק במדרגה קטנה כנזכר:
@488 **וראיתי** לתת לב איך זכה יתרו שתכתב על ידו פרשה זו, והן אמת כי הוא כבד משה עבד ה' והנה שכרו שכבדו ה', אלא היה ה' יכול עשות לו דרך כבוד אחר לא בדרך זה שיראה חס ושלום כפחות ידיעה בעם ה' עד שבא כהן מדין והשכילם:
@488 **ונראה** כי טעם הדבר הוא להראות ה' את בני ישראל הדור ההוא וכל דור ודור כי יש באומות גדולים בהבנה ובהשכלה, וצא ולמד מהשכלת יתרו בעצתו ואופן סדר בני אדם אשר בחר כי יש באומות מכירים דברים המאושרים, והכונה בזה כי לא באה הבחירה בישראל לצד שיש בהם השכלה והכרה יותר מכל האומות, וזה לך האות השכלת יתרו הא למדת כי לא מרוב חכמת ישראל והשכלתם בחר ה' בהם אלא לחסד עליון ולאהבת האבות. ויותר יערב לחיך טעם זה למאן דאמר (זבחים קט''ז.) יתרו קודם מתן תורה בא כי נתחכם ה' על זה קודם מתן תורה לומר שהגם שיש באומות יותר חכמים מישראל אף על פי כן אותנו הביא ה' אליו ובחר בנו, ועל זה בפרט עלינו לשבח לאשר בחר בנו מצד חסדיו. גם למאן דאמר אחר מתן תורה יש טעם במה שסדר ביאתו קודם להראות הכוונה הנזכרת שזולת זה אין הכונה הנזכרת נגלית והבן:
@489 **בכל עת**. רמז אפילו בזמן שהוא משה עסוק בקבלת חוקי ה' ותורותיו וכדומה אלו הם פנויים ישפוטו בכל עת מה שאין כן יכול עשות משה:
@489 **והקל מעליך ונשאו**. פירוש כי מה שאני אומר לך להקל מעליך לא שלא תשפוט אלא הדבר הגדול אלא **ונשאו אתך** פירוש אתה והם תהיו במלאכה זו:
@490 **אם את הדבר וגו' וצוך וגו'**. צריך לדעת כוונת אומרו **וצוך**, אם להמלך בגבורה הוא אומר כבר אמר לו כן פעם אחת דכתיב (פסוק י''ט) איעצך ויהי אלהים עמך, ומה צורך בכפל הדברים. ואולי שנתכוון לומר לו תשובה על מה שיטעון כי סוף כל סוף הוא מונע מעצמו המצות ואין ממדת הצדיקים להקל מעליהם המצות הגם כי ייעף וכי יגע כי אדם לעמל יולד (איוב ה') בעמלה של מצוה, לזה אמר אליו **וצוך אלהים** וגו' פירוש כי הנה ידוע הוא עוצם הכח אשר יצטרך לאיש נביא, וצא ולמד ממאמרי דניאל (דניאל י') בדבר אליו מלאך ומזה תשכיל לדברות אל, ולזה תמצא שאמרו ז''ל (נדרים ל''ח.) אין נבואה שורה אלא על גבור, והן אמת כי משה זיכך גופו ולא יארע לו התשות כח, אבל על כל פנים לא יכול להתאזר כל כך כשיהיה חלש בטבעו. ולזה אמר אליו כי יותר במצוה זו שיכולה להתקיים על ידי אחרים כדי שיקיים מצות הנבואה שאינה יכולה להתקיים על ידי זולתו, והוא אומרו **אם את** וגו' **וצוך אלהים** פירוש כאשר יצוך אלהים המצות אשר הוא מצוך בהודעת התורה והמצוה תוכל עמוד בהם פירוש יהיה בך כח לעמוד בהם. ואולי כי דקדק לומר לשון עמידה לומר כי יהיה בו כח לקבל הנבואה מעומד כאומרם ז''ל (זהר ח''א קע''א.) כי שאר הנביאים היו נופלים על פניהם מה שאין כן משה דכתיב ונצבת שם וגו' (שמות לד ב) פה עמוד עמדי (דברים ה כח), ולזה אם לא יקל מעליו זה יהיה לו סיבה שיגרע מצדיק עינו חס ושלום ולא יוכל עמוד:
@495 **בחדש השלישי וגו'**. הנה למה שקדם מעוצם חיבתו יתברך בישראל וגודל חשקו לתת להם ארוסתם זאת התורה תקשה למה נתעכב ה' מתת התורה עד חודש השלישי כי מן סימני האהבה היא שלא יתעכב חושק מבא לחשוקתו. ואם לצד הדרך הלא מצינו שאפילו לאליעזר עבד אברהם קפצה לו הארץ (סנהדרין צ''ה.) בלכתו לקחת אשה ליצחק ומכל שכן וקל וחומר לחתונת נשיאת ראש כי תקפוץ הארץ וגם השמים אם יצטרכו לה, אשר על כן בא הקדוש ברוך הוא ונתן אמתלא לדבר כי לא מיעוט החשק הוא הסובב אלא לצד הכשרת החתן כי לא היו ישראל ראוים לצד שהיו בארץ הטמאה והיו לנדה ביניהם והוצרכו לספור ספירת טהרתם שבע שבתות כדרך ז' נקיים אשר צוה ה' לזבה (זהר ח''ג צ''ז:) והוא אומרו **לצאת בני ישראל** פירוש לסיבת יציאתם מארץ מצרים הוא הסובב עכבת הדבר עד החודש הג', והראיה כי כשקרבו ימי הכשרתם בו ביום נסעו בו ביום באו, והוא אומרו **ביום הזה** פירוש שנסעו בו ביום באו, וכן הובא בדבריהם ז''ל (שבת פ''ז:) שביום שנסעו בו באו. והצצתי בענין ואראה עוצם חשקו יתברך בישראל שניכרת מתוך מעשיו בהעיר למה הטריחם ה' בדרך עד החדש הג'. ואם לסיבה שכתבנו עדיין תקשה שהיה לו לקפוץ הארץ ולהגיע למדבר סיני בו ביום ושם יתעכבו עד ספור ז' שבועות ויהיה זמן הכושר כנזכר:
@495 **אכן** זה יגיד עוצם חשק נתינת התורה לישראל, כי לגודל חשקו ברוך הוא בהם לא רצה להביאם ולהתעכב זמן ארוך בלא חתונה בבית חתנות, ולזה היה ממעיט הימים בריחוק מקום, ותקח לך שיעורן של דברים מחשוק וחשוקתו כי לא יצטער בעכבתו מבוא אליה כל זמן שלא הגיעו עת דודים ועדיין לא עלתה כלה לחופתה אשר לא כן בעת כלה בחופתה לא יעצור כח לעכב ביאתו אליה:
@496 **ויסעו מרפידים**. קשה למה איחר המוקדם כי פסוק זה היה לו להקדים קודם פסוק שלפניו שאמר באו מדבר סיני, ואולי שהוא על דרך אומרם (סנהדרין ק''ה:) אהבה מקלקלת השורה להקדים המאוחר, שלהיות כי הוא זה יום המקווה לבורא לתורה לעולם לעליונים ולתחתונים ומיום הבריאה והם יושבים ומצפים מתי יבואו בני ישראל מדבר סיני, לזה כשהגיעו שמה לא עצרו כח לספר סדר הדבר ותכף קדמה ההודעה באומרו **ביום הזה באו** וגו' הגיע חשוק ונחשק לחושק וחשוק ושמחו שמים וארץ כי זה הוא תכלית הבריאה ותקותה ואחר כך חזר הכתוב להודיע פרטן של דברים:
@496 **עוד** ירצה בהעיר עוד אומרו **ויבואו מדבר סיני** והלא כבר אמר בכתוב שלפניו באו מדבר סיני. עוד צריך לדעת למה הוצרך לומר ויחנו במדבר הלא מובן הוא הדבר כי במקום ביאתם חנו:
@496 **אכן** כוונת הכתוב הוא להקדים ג' ענינים הם עקרי ההכנה לקבלת התורה שבאמצעותם נתרצה ה' להנחילם נחלת שדי היא תורתנו הנעימה:
@496 **הא'** הוא התגברות והתעצמות בעסק התורה כי העצלות הוא עשב המפסיד השגתה, ולזה תמצא כי כל מקום שיזכירנה ה' לתורה ידקדק לומר לשון חוזק ואומץ עד גדר שימית עצמו עליה דכתיב (במדבר יט יד) זאת התורה אדם כי ימות וגו' ודרשו ז''ל (שבת פ''ג:) וכו', כמו כן רבותינו ז''ל ידקדקו בהזכרתה לומר עסק התורה השתדלות התורה ורבים כמוהו, ועיין מה שפירשתי בספרי חפץ ה' שחברתי על קצת ממסכתות הש''ס בקטנותי במאמר רבותינו ז''ל (שם פ''ח:) למיימינים בה כו' ותראה כי לא תושג ההשגה אלא בהתעצמות גדול, וכנגד זו אמר הכתוב **ויסעו מרפידים**, לא בא להודיע מקום שממנו נסעו שאם כן היה לו להקדימו קודם תחנותם, אלא נתכוין לומר שנסעו מבחינת רפיון ידים כמו שמצינו שדרשו כן רבותינו ז''ל (סנהדרין ק''ו.) בפסוק (לעיל י''ז ח') וילחם עם ישראל ברפידים ברפיון ידים עד כאן. והן עתה נסעו מבחינה זו והכינו עצמם לעבוד עבודת משא בנועם ה', והוא אומרו **ויבואו מדבר סיני**:
@496 **וענין** ב' הוא השפלות והענוה כי אין דברי תורה מתקיימין אלא במי שמשפיל עצמו ומשים עצמו כמדבר, וכנגד זה אמר **ויחנו במדבר** פירוש לשון שפלות וענוה כמדבר שהכל דורכים עליו:
@496 **וענין** ג' הוא בחינת ייעוד חכמים בהתחברות בלב שלם ותמים לא שיהיו בד בבד שעליהם אמר הכתוב (ידמיה נ) חרב אל הבדים (בדכות ס''ג.), אלא יתועדו יחד ויחדדו זה לזה ויסבירו פנים זה לזה, וכנגד זה אמר **ויחן שם ישראל** לשון יחיד שנעשו כולן יחד כאיש אחד, והן עתה הם ראוים לקבלת התורה:
@497 **ומשה עלה וגו'**. צריך לדעת למה עלה משה קודם שיקרא לו ה'. עוד צריך לדעת לאיזה מקום עלה, אם להר היה לו לומר אל ההר בפירוש. ורבותינו ז''ל אמרו (שמות רבה פכ''ח) זה הוא שאמר הכתוב (תהלים סח) עלית למרום וגו'. ולדבריהם קשה עוד כי מצינו שאחר כך היתה הקריאה אליו מן ההר דכתיב ויקרא וגו' מן ההר ואם הוא כבר עלה לשמים מה מקום לקריאה ממקום נמוך למקום עליון. עוד יש לדקדק למה אמר הכתוב **אל האלהים** ולא אמר אל ה' כמו שגמר אומר ויקרא אליו ה' וגו':
@497 **אכן** כוונת הכתוב היא להיות שקדם ה' ואמר למשה בסנה (לעיל ג' י''ב) בהוציאך את העם תעבדון את האלהים על ההר הזה, הוא מראהו כי שם הוא מקום קבלת התורה, אשר על כן בהגיעו שמה עשה משה משפט עבד נאמן וקדם ועלה אל ההר ולא הוצרך להזכיר ההר כיון שהזכירו בסמוך דכתיב נגד ההר ועליו חוזר אומרו **ומשה עלה**, ואומרו **אל האלהים** הוא טעם עליתו כי מה שייכות בעליה זו לזה אמר אל האלהים שקדם אצלו מהבורא תעבדון את האלהים על ההר הזה לזה אם היה מתעכב עד שיקרא ה' אליו יראה התרשלות ומיעוט חשק בדבר לזה תיכף קדם והכין עצמו ועלה, וזולת מה שקדם לו במאמר ה' תעבדון את האלהים לא היה עולה אל ההר. ובזה נתיישבו כל הדקדוקים שדקדקנו. ואין בפירוש זה סתירה לדברי רבותינו ז''ל שאמרו (שמו''ר שם) עלית למרום כי בעלייתו ההר שהוא מקום שהרכין ה' שמים עליו הנה הוא נמצא עולה לשמים:
@497 **ויקרא אליו ה'**. פירוש כשקדם הוא ועלה תכף קרא לו ה'. ויש לך לדעת כי בחינת הקדושה לא תקדים אלא למזמין אותה ומעיר על הדבר והוא מאמרם ז''ל (זהר ח''ג צ''ב) באתערותא דלתתא אתערותא דלעילא, והוא סוד אומרו (בראשית ב ו) ואד יעלה מן הארץ והשקה מלמעלה את כל פני האדמה, וירמוז באומרו **ויקרא** לשון יקר וגדולה עשה ה' למשה על הכנתו וזריזותו בדבר:
@497 **מן ההר לאמר**. פירוש לצד כי דבר ה' בא מן שמי השמים כי עדיין לא ירד ה' על הר סיני, אשר על כן בא להודיענו הכתוב כי צוה ה' על הקול שיעבור דרך הר ומשם ישמע משה אמריו ולא יפנה לצדדין גם לא ישמע לאוזן משה קודם שיגיע להר אלא להר יבא ומן ההר יהיה נשמע אליו. וזה הוא שיעור הכתוב **ויקרא אליו ה'** ממקום ששמו שם כידוע וקריאה זו **מן ההר לאמר** פירוש מן ההר התחיל האמירה ולא קודם ולא מן הצדדים, ואם לא אמר הכתוב תיבת לאמר היה בנשמע כי התחלת הקריאה היה מן ההר וכבר ירדה שכינה שמה ולא כן הוא:
@497 **כה תאמר וגו' אתם ראיתם וגו'**. צריך לדעת למה כפל **תאמר** וגו' **ותגיד** וגו'. ורבותינו ז''ל אמרו (שמות רבה פכ''ח) בית יעקב הם הנשים ולהם יאמר מענה רך ולבני ישראל דברים קשים כגידים. וקשה הלא לא מצינו שאמר ה' בדבריו ב' מיני שליחות אלא לשון א' לכולם יחד אנשים ונשים אם הם קשים יחד ישמעוהו ואם הם רכים יחד ישמעוהו. ואין לומר שכשידבר משה ישנה מענה לשון מסדר הנדבר חס ושלום כי הלא תמצא כי בסוף דברי ה' אמר אליו (פסוק ו') אלה הדברים אשר תדבר אל בני ישראל ואמרו ז''ל (מכילתא) וזה לשונם לא פחות ולא יותר. ולכשנאמר כי כוונת אומרו **אל בני ישראל** הוא על האנשים, יחסר דרך אשר ידבר בו לנשים, גם אין אני רואה דברים קשים בדברי ה' לאנשים אלא דברים המחיים את הנפש:
@497 **אכן** כוונת דברי ה' הוא על זה הדרך וקודם אקדים המושג אצלינו מכל התורה כי האדון אלהי ישראל מדותיו הם להטיב ויותר מחשק המקבל חשקו להטיב, וזה לגודל הפלגת בחינת טובו, ויותר מהמה לבני ישראל, ומתחכם הוא יתברך להרבות שכרנו וטובתנו כי זה הוא אשר יחפוץ ה'. והנה מצינו לו שגילה דעתו כי שכר המקיים תורת ה' ומצותיו מיראה הוא מחצה מהעושה מאהבה מב' כתובים הבאים בהודעת שכר המצות באחד אמר (דברים ז ט) לאלף דור ובאחד אמר (לקמן כ' ו') לאלפים ודקדק בשר האלף שהוא השומר מיראה ושר האלפים שהוא לעושה מאהבה. והנה יש בבחינת האהבה צד גורם רעה כי לא תספיק לבעליה להשמר בתמידות לבל עבור איזה פעם באקראי כי יאמר שמצד קורבתו לבורא וחביבותו לא יקפיד עליו על זה כמנהג וסדר הרגיל בין הנבראים, ולהשכילך בענין ממשה אתה למד כי לצד רוב קורבתו וחיבתו עם ה' שגג ודבר אליו (לעיל ד' י''ג) שלח נא ביד תשלח, למה הרעתה וגו' (ה' כ''ב), לא הצלת וגו', וזה היה סיבה גודל קריבתו לפני ה' נתקררה היראה כי פשיטא שאדם אחר כשלא יהיה קרב כל כך תפול עליו אימתה ופחד. והנה האדון ה' צבאות לא כן יחשוב כמו שאמר הכתוב (דברים י' י''ז) אשר לא ישא פנים ולא וגו' ויקפיד אדרבה ביותר על אהובו ליסרו בתוספת מרובה על עוברו אפילו פעם אחת ואפילו על הקלה שבקלים כאומרו (תהלים נ') וסביביו נשערה מאוד ואמרו ז''ל (ב''ק נ'.) שמדקדק עם חסידיו כחוט השערה, ואשר על כן בעת נתינת התורה חשב ה' מחשבות טובות להועיל בקבלת התורה ולפניו ב' דרכים, א' לדבר דברי אהבה וחיבה ויש בזה תכלית דבר טוב כשיקבלוה מאהבה שקל הקודש כפול הוא בשכרם, ויש בזה צד אחר כי העושה מאהבה לפעמים לא ידקדק בפרט אחד מהתורה כדרך האב עם בנו המגעגעו והמשעשעו כיון שאין עליו בחינת המורא מה שאין כן כשתהיה קבלת התורה מחמת יראה מדרך הירא לפחד על דקדוק אחד כעבד מרבו ונמצא תמיד עומד לשמור עץ החיים וכן הוא בדבריהם ז''ל. (ירושלמי ברכות). ודרך ב' הוא לדבר דברים קשים כמלך שגוזר על עבדו בזריקת מרה ואימת מלכות, ויש בזה תכלית טוב שלא יזלזלו באחת מכל מצות התורה ואפילו באקראי ועראי אלא שמגיעם מחצית שכר משכר המגיעם בעשותם מאהבה:
@497 **אשר** על כן נתחכם ה' לצוות בב' אופנים בדרך אהבה ודרך שררה והפחדה ואמר גם שניהם במתק לשון צדיק בנושא אחד, והוא מה שהתחיל לומר **כה תאמר** על זה הדרך כה פירוש כסדר זה שאני אומר לך **תאמר לבית יעקב ותגיד** וגו' פירוש יש בו אמירה רכה שהיא דרך אהבה וחיבה **ותגיד** פירוש יש בו גם כן דברים קשים כגידים שהוא דרך הפחדה ויראה. ודקדק לומר **בית יעקב** באמירה **ובני ישראל** בקושי, לומר חלק החסר לכל אחד משניהם על זה הדרך כי בית יעקב הם מדריגה הקטנה שבאומתנו הקדושה אשר לא ישיגו עבוד ה' מאהבה אלא מיראה לזה המצוה להם שצריכין להוסיף עבוד מאהבה הרמוזה באמירה רכה כנזכר, ולבני ישראל שהם מדרגה הנבחרת והמעולה אשר ישיגו בחינת האהבה אמר כנגדם **ותגיד** שלא יספיק להם בחינת האהבה לגבי פרט אחד וצריכין הם ליראה ולאהבה מטעם שכתבנו, נמצאת אומר כי טובים השנים וצורך בהם לקיום התורה וצריך כל איש מישראל לקנות שניהם אהבה ויראה ושניהם יחד אמרם אל עליון בנעימות דבריו באומרו אתם ראיתם אשר עשיתי וגו' כאשר אבאר בסמוך בעזרת השם ודברי רבותינו ז''ל שאמרו (מכילתא) אלו הנשים ואלו האנשים הם דרך דרש:
@498 **אתם ראיתם וגו'**. צריך לדעת כוונת אל עליון במה. שדקדק לומר **אשר עשיתי למצרים** שיותר היה לו לומר אשר הוצאתי אתכם מארץ מצרים שהוא עיקר הדבר להתחייב להשתעבד ולחבק אמריו על כל אשר גמלם ה'. ואם להזכיר נפלאותיו הרי הם רשומים באומרו אשר הוצאתי מארץ מצרים וידוע הוא כי לא הוציאם אלא באמצעות המסות הגדולות:
@498 **והנה** לפי מה שפירשנו כי יכוין ה' לב' דברים שהם בחינת האהבה ובחינת היראה לזה רשם ה' שניהם במאמר. זה, היראה באומרו **אשר עשיתי למצרים** פירוש אשר יסרתי יסורי נקמה לממאן עשות מאמרי כמה מכות רעות באין מספר על אשר מאן עשות מצותי לשלוח אתכם, והיה הדבר הזה לכם לאות לעובר על מצותי כי אתנקם ממנו ביסורי נקמה וצרות רבות כאשר ראיתם וקחו מוסר, ונתכוין ה' לרמוז להם שהם בגדר זה עצמו של המצרים אם ימאנו לשמוע אל התורה ואל המצות וזו בחינת היראה יראת העונש, גם יש בנשמע מאמר **אשר עשיתי** יראת הרוממות בכל הנפלאות והאותות והמופתים אשר עשה למצרים. גם בזה הראה בחינת האהבה והחיבה שכל זה עשה בשבילנו הרעיש כל הבריאה ואבד אומה אחת בשבילנו, ולצד זה יתלהב אדם בחיבת הבורא אשר הפליא חסדו להם, והנה היא בחינת האהבה לה' אלהינו, והם ב' דברים הרמוזים באומרו **תאמר לבית יעקב** שלא תספיק היראה וצריך גם האהבה **ותגיד לבני ישראל** שלא תספיק בחינת האהבה וצריך גם היראה והטעם כמו שכתבנו:
@498 **ואשא אתכם**. הנה האריך האדון בבחינת האהבה כי הוא העיקר במצוה להרויח כפל השכר, וצריך התעצמות גדול להשיגה, לזה אמר ראו חיבתי בכם כרחם אב על בנים חביבין שאפילו מדרך כף רגליכם חסתי עליו ונשאתי אתכם על כנפי נשרים פירוש ענני כבוד היו ממוצעים תחתם, וכן הוא אומר (דברים ח ד) ורגלך לא בצקה, ועוד יש לאלוה מילין לעורר האהבה מה שאין כן היראה שבנקל תכנס בלב האדם לזה הספיק לו ברמיזתו במאמר אשר עשיתי למצרים כמו שפירשתי:
@498 **ואבא אתכם אלי**. ירצה כי לא קדם הקרבתם אל ה' כמשפט כל הקרב הקרב למשכן ה' שיקדים הוא לעורר חבתו כידוע שאין אלהי עולם מקדים לקרב עד שיעורר המתקרב את האהבה, וכן הוא מהמוסר כי ההדיוטות והקלים הם המשתדלים להתקרב לגדולים ונכבדים מהם ומכל שכן עם עבד מושלים, ואף על פי כן אמר ה' כי לא כן עשה אלא הגם שהיו גוי מקרב גוי ערום ועריה בלא שום התעוררות אף על פי כן אני הבאתי אתכם אלי ולא אתם התקרבתם אלי:
@498 **עוד** ירצה לומר שאחר שהוציאם ממצרים היו חוזרים מאחרי השכינה כמו שמצינו להם שהמרו אמרי אל בים סוף במן ובשליו וכדומה אף על פי כן היה ה' מושכם אליו בכל עת שהיו חוזרים לאחוריהם ומביאן ומקרבן אליו יתברך:
@498 **עוד** ירצה על דרך אומרם ז''ל (הגדה) אלו לא הוציא הקדוש ברוך הוא את אבותינו ממצרים מיד כו', והטעם כדי שלא ישתקעו בבחינת הרע בטומאת מצרים ולא תהיה חס ושלום עוד תקומה לשונאיהם של ישראל לזה מיהר להוציאם כדי שיעמדו במקום קדוש, והוא אומרו **ואביא אתכם אלי** דייק תיבת אלי לשלול השתקעות בחלק הרע רחמנא ליצלן והבן:
@498 **עוד** ירצה לשלול טענת הטוען כי הלא מצינו לו (ספרי ברכה) שהלך לשעיר ופארן לישמעאל ועשו והזמינם לקבל תורה ולא קבלו לטעם שאמרו ואם כן מה מעלה זו שמרומם לעם ישראל, לזה אמר **ואבא** וגו' פירוש על דרך אומרם ז''ל (ילקוט הראובני ר''פ בלק) בפסוק (במדבר כג ד) ויקר אלהים אל בלעם וגו' משל למלך שבא אוהבו לדבר עמו וכו' עד כאן, פירוש כי אתם הבאתי אתכם אלי מה שאין כן הם ששלחתי להם למקומם לשעיר ולפארן ואין זה אלא לדחותם לעתיד לבא ולחייבם בדין מה שאין כן אתם כי דעתי ורצוני לקרבכם אלי ואין לדמות מעשה ישראל למעשה אדום וישמעאל:
@499 **ועתה אם וגו'**. אומרו **ועתה**, על דרך אומרם ז''ל (ב''ר פכ''א) אין ועתה אלא תשובה, כי לצד שהיו ישראל מלוכלכים בחרמי העונות אשר קדמו להם וגם החדשים מקרוב באו בהמראתם ככתוב בתורה כמה פרטי חטאים במן בשליו בשבת במים וכאשר רצה אל עליון לתת התורה זכה וברה יסוד הקדושה והטהרה ורוחניות הרוחניות צוה להם שיחזרו בתשובה אפילו מחטא קל, וכבר קדם לנו מאמרם ז''ל (קידושין מ''ט:) בדין המקדש את האשה על מנת שהוא צדיק גמור ונמצא רשע שקידושיו קידושין כי חיישינן שמא עשה תשובה ובאמצעות תשובתו יקרא צדיק. עוד יתבאר בסמוך:
@499 **אם שמוע תשמעו וגו'**. צריך לדקדק טעם כפל **שמוע תשמעו**, ואולי יכוין ה' לצוותם על קבלת ב' תורות אחת אשר ישמיעם באותו מצב, ואחת היא תורה שבעל פה ודקדוקי סופרים וספרים וגדרי חכמים ותקנותם וגזירתם אשר יורו כרמוז במצות (דברים יז יא) לא תסור מכל הדבר אשר יגידו לך ימין ושמאל, ולזה אמר כנגד מה שמשמיעם מהמצות אז אמר **אם שמוע**, וכנגד תורות העתידים מפי חכמי ישראל אמר **תשמעו** לעתיד. ולדרך זה ידוייק על נכון אומרו **ועתה אם שמוע**, כי להיות שמצוה באומרו **תשמעו** על העתיד לזה סמך **ועתה אם שמוע** לומר אם שמוע עתה ותשמעו לעתיד כנזכר. ודקדק לומר בק **ולי**, על דרך אומרם ז''ל (במד''ר פי''ד) שומע מפי חכם וכו' כשומע מפי הגבורה, והוא אומרו כי מצוה זו שאני אומר לכם שתקבלו תקנת חכם צריך שתהיה לכם שוה כאלו אם השמעתיה והגדתיה לכם. ואולי כי בזה יתיישב מאמרם ז''ל (במס' שבת פ''ח.) שדרשו בפסוק (יז) ויתיצבו בתחתית ההר שכפה עליהם ההר כגיגית ואמר להם אם אתם מקבלים וכו' ואם לאו שם תהא קבורתכם, וקשה והלא הם אמרו (לקמן כ''ד ז') כל אשר דבר ה' נעשה ונשמע ומה מקום לכפייה זו, והתוס' תרצו שם שמא היו חוזרים כשיראו האש הגדולה שיצתה נשמתן עד כאן, ואין דבריהם נראים כי אדרבא יוסיפו פחד ופחת ויראו יראת הרוממות. ולפי מה שפירשתי כי ה' אמר להם ב' תורות אחת מפיו אז ואחת לעתיד מפי חכמים כנזכר נוכל לפרש תשובתם שאמרו כל אשר דבר ה' נעשה ונשמע שכוונתם היא על זה האופן כל אשר דבר ה' חלק ממנו שהוא מה שאמר **ועתה אם שמוע** שהוא ענין הנאמר מפי הגבורה אז נעשה אנו מקבלין עלינו לעשות מעתה קודם שנשמעהו, וחלק ממנו שהוא מה שאמר **תשמעו** לעתיד שהוא תורת חכם ונשמע פירוש לא קבלו ולא מאנו אלא תלו הדבר עד שישמעו לדעת מה יעשה ישראל, כי הם דברים שאין להם שיעור ואין גבול לקבלה זו כי בכל דור ודור יחדשו דינים וגדרים וסייגים ותקנות ומי יכלכל תורה שאין לה שיעור כזו, לזה תלו שיהיה הדבר ברשותם עד שישמעו ויבחנו בכל דבר אם יוכלו קבל, ומעתה לא קבלו עליהם אלא תורה שבכתב אבל תורה שבעל פה הדבר תלוי ועומד, ועל זה כפה ה' עליהם ההר כגיגית עד שקבלו עליהם תורת חכם, ובאונס היה עד ימי מרדכי שראו פעולת חכם לחיים אשר עשו להם מרדכי ואסתר חזרו לקבל ברצון לקיים כל דבר אשר יחדשו ויתקנו עליהם חכמיהם אחר אשר ראו מה גדלו מעשה הצדיקים שזולתם לא היה נשאר רושם משונאיהם של ישראל. והגם שרבותינו ז''ל (שם) דרשו אומרם נעשה ונשמע באופן אחר לשבח שדמו למלאכים שקדמו לומר המעשה קודם השמיעה כמלאכים שמקדימין (תהלים קג) עושי דברו קודם לשמוע בקול דברו, זה דרך דרש. וגם לדרכנו הרי אמרו נעשה קודם שישמעו ולא הקדימו השמיעה אלא בתורת חכם. או אפשר שהכתוב נתכוון לב' הפירושים אחד בצדיקים ואחד בשאר העם כי פשיטא שמן הסתם לא ישוו הדרגות ישראל יחד בצדקות:
@499 **עוד** ירמוז בכפל **שמוע תשמעו** מה שהיה אחר האמת בקבלת התורה על פי דבריהם ז''ל (הוריות ח'.) כי ב' דברות שמעום מפי הגבורה וח' מפי המלאך שנברא מדיבורו יתברך לזה אמר **אם שמוע תשמעו** ב' הדרגות השמיעה, ודקדק לומר כנגד שמיעה שישמעו ממש מהגבורה **תשמעו בקולי** ולא אמר לקולי והבן:
@499 **עוד** ירצה לומר כי אם יתחיל לשמוע התורה משם ואילך הוא יתאוה לשמוע עוד, והוא אומרו **אם שמוע** עתה אני מבטיחכם כי תשמעו מעצמכם כשתטעמו טעמה, כאומרו (תהלים לד) טעמו וראו כי טוב ה'. עוד ירצה על דרך אומרם ז''ל (סוטה כ''א:) תורה בין וכו' מגנא ומצלא, והוא אומרו **אם שמוע** פירוש אם תהיה השמיעה זה יהיה לכם לב' תועליות הא' שאתם שומעים קולו יתברך דברי אלהים שיש בהם החיים ותחיו כאומרו (ישעי' נה) שמעו ותחי נפשכם, והב' **ושמרתם את בריתי** פירוש שיגן עליכם מיצר הרע, ולדרך זה הרווחנו גזירת הדבור שמקומו הוא תשמעו וגו' שעיקר המצוה הוא שמיעת התורה וממנה נמשכים כל התועליות, הא' שהם נהנים מקול אלהים חיים, ב' יהיו שומרים המצות ולא ישלוט בהם יצר הרע, ג' והייתם לי סגולה וגו'. ולפי מה שפירשתי למעלה כי אומרו תשמעו הוא לתורה שבעל פה, תהיה גזרת הכתוב **ושמרתם** וגו' כי באמצעות התורה תצילהו מיצר הרע המחטיאו, ואומרו בתוספת וא''ו, לומר מלבד שתהיה לכם ידיעה ממנה להבחין בין טוב לרע עוד לכם שתשיגו השמירה ולא ישלוט בכם השטן:
@499 **עוד** יכוין הכתוב על זה הדרך **ועתה אם שמוע** פירוש תכינו עצמיכם לשמוע אני אשמיעכם את קולי פירוש שלא אדבר עמכם על ידי שליח, גם רמז כי באמצעות שישמעו הדברים ממנו יתברך משמיעה אחת ישמעו עוד שמיעות רבות, על דרך אומרו (תהלים סח) ה' יתן אומר המבשרות צבא רב ותדלה נפשם מים חיים חכמה ותבונה, וזה שיעור הכתוב **אם שמוע** פירוש שמיעה שממנה תשמעו עוד שמיעות רבות היא שמיעה בקולי, והוא אומרו **תשמעו בקולי**, עוד יש לכם תועלת בזה **ושמרתם את בריתי** על דרך אומרם ז''ל (שהש''ר פ''א בפסוק ישקני) כי השומע תורה מפי אדם היא עומדת לישכח ממנו מה שאין כן השומע מפי עליון שמורה לעד ולעולמים, והוא אומרו ושמרתם את בריתי. גם ירצה על דרך אומרם ז''ל (שבת קמ''ו.) ישראל שעמדו על הר סיני פסקה זוהמתן, והכוונה היא כי באמצעות דבור ה' להם בכח בגדי מלכות שנתן להם שהיא נפש אדם ובאמצעות כן תתרצה הנפש למאוס בגעולי גוים המתאוים הרע, והוא אומרו **ושמרתם את בריתי**:
@499 **והייתם לי וגו'**. הכוונה בזה היא כי כשם שהסגולה הוא דבר שאינו כפי הטבע כי הלא תמצא כי יש עשב שטבעו קר וסגולתו לרפאות חולי הקרירות, וכן יש עשב חם וכו', וזה אינו כפי הטבע אלא דבר סגולה, וכמו כן מבטיחם ה' שיהיו סגולה גם שלא כפי המשוער, ויש הרבה ענפים בהבטחה זו, ראשונה על דרך אומרם ז''ל (שבת ס''ג) חשב אדם מישראל לעשות מצוה ונאנס ולא עשאה נותנים לו שכר כאלו עשאה, ולא כן בעבירה, ובאומות אינו כן אלא להיפך, ואין זה מהנשער כפי השכל ממה נפשך אם המחשבה תעשה דבר אם כן תעשה בחושב רע ואם לא תעשה אלא בבחינת הטוב ולא בבחינת הרע אם כן באומות למה בהפך. עוד תמצא (סנהדרין נ''ט.) כותי שעוסק בתורה או ששבת חייב מיתה, ואפילו שאר מצות אין לו לעשות, ולמה אם הפעולה מצד עצמה פעולה טובה כל העושה הרי זה עושה דבר טוב, לזה אמר הכתוב **והייתם לי סגולה מכל העמים** כי אין פעולה טובה יוצאה אלא מידכם שאין סגולת התורה והמצות אלא מכם. ואומרו **כי לי כל הארץ**, פירוש כי יאמר האומר כי הבטחה זו שיהיו סגולה לא תוצדק אלא כשיהיו האומות חפצים ללמוד ולעשות וגו' בזה יוצדק לומר שעשנו סגולה, אבל רואני (ספרי ברכה) כי אדרבה מאנו העמים לקבל תורה ומצות כשדבר ה' לפארן ושעיר ומעתה במה יוכר טוביות הבטחת המעלה, לזה אמר **כי לי כל הארץ**, כאן הודיע ה' כי אין לך אומה ואומה שאין בה מכירי אלהותו יתברך, וכן הוא אומר (מלאכי א') מוקטר מוגש לשמי וגו' הרי כי כל הגוים לו יכרעו ואף על פי כן לא יטלו שכר על הדבר ולא יעשה מעשיהם רושם, וזו היא סגולתם של ישראל:
@499 **עוד** ירצה שיהיו סגולה והסגולה היא שיהיו מיוחדים לו ביחוד לעבוד אלהי עולם מכל העמים כי גם כל העמים לי הם פירוש עבודתם לי הוא כי אינם עובדים אלא למשרתיו הא כיצד עובדים לשמש ולירח ולצבא השמים הלא כולם משמשיו יתברך ונמצאים עובדים לעבדיו כאומרו (דברים ד') אשר חלק ה' וגו' לכל העמים:
@499 **ומה** שמצינו שמרד פרעה וסנחריב וכו' הוא בדרך טעות ושגיון, הא למה הדבר דומה למלך שנחבא ויצא לפני שאינם מכירים אותו הרי הוא כהדיוט ולפעמים עבדיו עצמם יזלזלו בו כפחות הפחותים כמו כן פרעה לא ידע כי הוא זה האדון השליט על מי שחושב שהוא אלוהו, נמצאת אומר כי כל הארץ למשרתי מלכותו ישתחוו ובחר לו לישראל שיעבדוהו לו ביחוד ועשאם סגולה:
@499 **והצצתי** בהשכלת דבר זה שאמרו ז''ל בספרי בפרשת וזאת הברכה וזה לשונם כשנגלה ה' על ישראל לתת התורה הלך אצל בני עשו אמר להם מקבלים אתם התורה אמרו לו מה כתוב בה ואמר להם לא תרצח אמרו לפניו רבונו של עולם כל עצמו של אותו אביהם רוצח היה ועל כך הבטיחו אביו ועל חרבך תחיה הלך אצל עמון ומואב וכו' אמרו לו מה כתוב בה לא תנאף וגו' אמרו לו כל עצמה של ערוה להם היא הלך ומצא בני ישמעאל אמר להם וכו' לא תגנוב וכו' רבונו של עולם כל עצמו של אביהם לסטים היה וכו' עד כאן. הנה מאמר זה תמוה הוא כי מה יצדק אנוש עם אל ומה טענה פחותה זו וכי בשביל שאביהם רשע היא טענה הנשמעת, ועוד מי שאכל שום וריחו וכו', ותגדל הקושיא איך קבל ה' את טענתם כנשמע שיש בה ממש:
@499 **אכן** אשכילך כי כל אשר עיניך תחזינה בתורתינו בין במצות עשה בין במצות לא תעשה טעם הדברים הוא כי ה' בחן במה שברא והכיר בחינת הרע והבדילנו ממנו ובחן בחינת הטוב וקדשנו בו, והוא מאמר הזוהר (תקו''ז תיקון כ''א) בפסוק ועשה לי מטעמים כאשר אהבתי ממצות עשה ולא כאשר שנאתי ממצות לא תעשה, וכן הוא מאמר רבותינו ז''ל בספרא (מכילתא פס' כי אני ה' רופאך) אמר ה' למשה אמור להם לישראל דברי תורה שאני נותן לכם רפואה הם לכם חיים הם לכם עד כאן, כפל לומר רפואה וחיים כנגד מצות לא תעשה ומצות עשה, רפואה לבל תחלו באכלכם או בעשותכם מהמעשים הרעים, וחיים הם בעשותכם מעשים אשר יעשה אותם האדם וחי בהם, ותמצא כי בעת צוות ה' על דברים האסורים יאמר (ויקרא יא מג) אל תשקצו את נפשותיכם, אל תטמאו וגו' (ויקרא יח כד), גם יזכיר העריות בשם תועבה וכדומה לזה, להגיד בא האלהים כי כל מחשבותיו הם לשמור אותנו להיות בבחינת הקדושה וצונו להיות קדושים. ויש לך לדעת כי כל בחינת מעשה הרע יש לה שורש בבחינת רוח הטומאה, וכל בחינת מעשה הטוב היא בחינת שורש הקדושה והטהרה, והנה כל מצוה שצונו ה' עליה לבל עשותה שמה הוא שם בחינת הרע שממנו הוא, כמו שתאמר שיקוץ הניאוף שורש בחינת הרע כך שמו, הגזל כמו כן כך שם שורש בחינת הרע, ובעת עשות האדם מפעל הרע הנה הוא מחזיק שורשו הרע, ובעת שיהיה נזהר מעשותו הנה הוא ביטולו, וכמו שפירשו במאמרם ז''ל (מדרש תהלים פצ''ב) בפסוק הנה אויביך ה' וגו'. ודע כי מעשה האדם יגיד על שורש נפשו אם שורש ראש ולענה שהוא בחינת הרע או אם שורש המתוק והערב שהוא בחינת הקדושה, וכבר כתבתי ענף מזה בפרשת ויחי בפסוק ראובן בכורי וגו'. ובזה מצאנו מאור הברייתא שבאנו עליה. כי טענה נצחת טענו ג' הכתות עשו ישמעאל עמון ומואב כל אחד למה שנגע לו, עשו אמר כי שורש נפשותם הוא מבחינת הרע ההוא ששמו רציחה ממנו הוא כמעשהו ובעת קבלתם הדבר זה הוא שלילת הוייתם, וכמו כן עמון ומואב וישמעאל, וזה הוא שדקדק כל אחד ואמר כל עצמו של אביהם וכו' פירוש כל הווייתו הוא בנוי מבחינת הרע ששמה רוצח, וכמו כן אמרו מואב וכו' עצמה של ערוה פירוש שאתה מצוה עליה להם היא פירוש הם בחינתה ואיך יקבלו ההפכיות אם כן זה הוא ביטולם, וכן ישמעאל אמר כל עצמו של אביהם לסטים היה פירוש בחינת הרע הנקראת לסטים, ומעשיהם היה מגיד על בחינת נפשם מאיזה מקום באה. והנה עמון ומואב הוכיחו בטענתם מעיקר הוויתם שהיתה מבחינת הניאוף, אבל אדום וישמעאל לא הוכר הדבר מעיקר הבנין אלא ישמעאל על פי מלאך שאמר (בראשית טז יב) והוא יהיה פרא אדם ידו בכל הרי כי מגיד לה שורשו כי הוא זה, ועשו על פי יצחק כאומרו (בראשית כז מ) ועל חרבך פירוש שאתה מאותה בחינה. ואשא עיני ואראה חיבת הקודש הוא אדון ישראל אשר התנהג עם העמים בסדר זה להקדים לכל אחד מהם מצוה שיש להם טענה כנגדה, כי אולי שידע שיקבלו כיון שאין להם טענה כנגדה, ונתחכם ברוך הוא כדי שלא יטלו שכר על קבלת מצוה ראשונה שאין להם עליה מענה, ופתח דבריו להם רוממות אל להשמידם מנחלת שדי ובחר לו יה לעמו סגולה. והנה דרך זה אומרו **והייתם לי סגולה** הוא גזרת הפסוק, וכפי זה טעם אומרו בתוס' וא''ו, לתוספת שכר מלבד שאר פרטי המושג מהמעלות עוד לכם שתהיו סגולה כנזכר, ולא הוצרך להזכירם כי מובנים ממשמעות תוס' וא''ו של והייתם וגו'. עוד ירצה בתוס' וא''ו לרמוז ענין אחר, והוא כי לא יטעה לבבם לחשוב כי הוא האדון ברוך הוא חס ושלום צריך להם לשום דבר לא כן הוא אלא סגולה כמלכים שחפצים בדבר סגולה שהוא כלי יקר הגם שאין להם צורך בו, גם אתם תהיו לי אבן יקרה בערך כל העמים ולא שהדבר הוא אצלי לצורך **כי לי כל הארץ** פירוש ומעתה לא יוצדק לומר שיש לי צורך בדבר וכאומרו (איוב לה) אם צדקת מה תתן לו כי הכל שלו יתברך:
@499 **עוד** ירמוז למה שאמרו ז''ל (שבת קמ''ו.) ישראל שעמדו על הר סיני פסקה זוהמתן, וזו היא סגולתן מכל העמים שלא פסקה זוהמתן. עוד ירמוז סתר עליון לפי מה שקדם לנו כי ענפי הקדושה נתפזרו בעולם ואין מציאות להם להתברר זולת באמצעות ישראל וביותר באמצעות עסק התורה שהיא כאבן השואבת ניצוציה במקום שהם, ואותם נצוצי הקדושה גם להם יקרא סגולה, והוא אומרו **והייתם** קרינן ביה והויתם פירוש בה''א מלאפו''ם כי הם יהיו הוית סגולה **מכל העמים** אשר נפוצו שם באמצעות התורה כמאמרם ז''ל וכמו שכתבנו כמה פעמים הדברים במעשה מצרים. ואומרו **כי לי כל הארץ** כאן רמז שיש לו סגולה מפוזרת בכל הארץ, וזה טעם פיזור ישראל בד' רוחות העולם לחזר אחר הסגולה שהיא אבידתם. והנה זולת עונם של ישראל היו יכולים השגת הדבר בלא פיזור בעולם אלא בכח עוצם תורתם היו מולכים בכל העולם ושואבים כל בחינות הקדושות מכל מקום שהם, ובאמצעות החטא תש כוחם וצריכין לרדת שמה לברר הטוב ההוא:
@500 **ואתם תהיו לי וגו'**. צריך לדעת למה הוצרך לומר ואתם כיון שעד עתה להם היה מדבר. ואולי כי על משה ואהרן חוזרים הדברים, ולהיות שעד עתה היה מדבר על כל ישראל ועשאם סגולה אם כן יאמר משה כי אין הפרש עוד בינם לבין ישראל, לזה אמר **ואתם** פירוש אתה ואחיך תהיו לי ממלכת כהנים כנגד אהרן, **וגוי קדוש** כנגד משה ומשפחתו על דרך אומרו הקדשתי אתם [לי ואקח את] הלוים [וגו']:
@500 **או** ירצה לומר להם כי מעתה יהיו הם בבחינת פמליא של מעלה, כי למעלה יש להאדון משרתיו ומשמשים לפניו במרום ולהם יקרא כהנים גם יש לפניו צבא רב הנקרא קדוש דכתיב (דניאל ח') אחד קדוש, ואמר ה' כי אותם יעשה ה' במקום כהנים וקדושים העליונים, וכן היה שצוה לעשות לו בית לשכון בתוכנו ובחר ממנו כהנים וצוה לנו (ויקרא יא מד) והייתם קדושים, וכפי זה אומרו **ואתם** חוזר הדבר לכללות ישראל, והוצרך לומר תיבת **ואתם**, לבל יחשבו כי דבריו להם על העתיד לבא בעלות הנפש אחר הפרדה מהגוף ישיג הרוחניות מעלות הסדורות אבל בחיים חיותו תרחיק הדעת השגה זו, לזה אמר **ואתם** פירוש אתם בעצמיכם בעלי גויה תשיגו מעלה זו. ומצינו שהצדיקים השיגו מעלה זו שנקראים מלאכים וקדושים כי באמצעות התורה תגדל ותעלה מעלת האדם עד אין קץ למעלה מהמלאכים (סנהדרין צ''ג.), וזה לך האות כי ה' בחר ליותר מעלה לקדושת מקום כבודו עם ישראל הא למדת כי הם למעלה מהם כי מעלין בקודש וכו':
@500 **עוד** ירמוז לפי מה שפירשתי בפסוק והייתם לי סגולה שירמוז לבירורי ניצוצות הקדושה אומרו **ואתם** וגו' להגדיל מעלת המברר מהמתברר כי המברר יהיה ממלכת של כהנים ושל גוי קדוש שהם ב' הדרגות הקדושה המתבררים כנזכר, וחלקם לב' חלקים כי יש בנבררים הדרגות עליונים והדרגות קטנים כפי בחינת הקדושה, והכוונה בזה כי בחינת מלכות יש להם על המתבררים, וצא ולמד ממשה כי לצד שהוציא ישראל ממצרים קנה מלכות עליהם:
@500 **אלה הדברים וגו'**. כוונת הכתוב לפי מה שפירשנו בסמוך בפסוק ואתם תהיו לי על ישראל ידוייק הכתוב על זה הדרך שלא תחשוב כי אמירתי ואתם תהיו לי וגו' חוזרת עליכם משה ואהרן לא כן הוא אלא אלה הדברים אשר תדבר אל בני ישראל כי המעלות להם הנה, ולפי מה שפירשתי שחוזר על משה יכוין באומרו **אלה הדברים** וגו' שלא יוסיף עליהם. ואם תאמר פשיטא שלא יוסיף עליהם ואם יש לחושדו חס ושלום למה לא צוה לו בשאר המצות ששלחו עד עתה:
@500 **אכן** הכוונה היא שצוה לו שלא יפרש דברי ה' לישראל אלא יאמר הדברים כמות שהם, וטעם הבורא להיות שדקדק בדבריו ענין היראה וענין האהבה וכמו שפירשנום בפסוק (ג') כה תאמר וחש הבורא למשה שאחר שידבר דברי ה' להם יבא לבאר הדברים להוסיף זירוז מעצמו להכניס מוראו בלב ישראל או להפליג באהבת הבורא, לזה אמר אליו אל תדבר עוד בדבר הזה זולת **אלה הדברים** כי אם יאמר משה דברי יראה יבואו לעשות מצד היראה וה' לא כן יעץ ולא הזכיר היראה אלא כמי שמוסיף תבלין בתבשיל להוסיף בו טעם ערב וכמו שכתבתי שם שהוא לבל יזלזל אדם באיזה זמן באיזה פרט באומרו כי לא יקפיד האוהב אבל כל עיקר העבודה צריכה באהבה ונמצא דברי משה מפסיד חס ושלום הכוונה. עוד נראה כי רצה ה' לנסותם ושיער דברים המספיקים להם מהמוסר ומהאהבה לצורך קבלת התורה ואם לא תרוץ נפשם בשומעם דברים אלו זה יגיד כי רחוקים הם מטוהר לב, לזה אם יוסיף משה לדבר דברים רבים בין בבחינת היראה בין בבחינת האהבה הגם שיאמר בפירוש שהם דברי עצמו הרי הוא מפסיד כוונת הבורא בנסיונו הגם שיקבלו יש מקום לומר כי רצויו של משה הוא הסובב. גם יש בזה פחיתות חיבת התורה ושבח בית אביה האל הגדול, אשר על כן צוה ה' לבל יוסיף לדבר אפילו מפי עצמו דבר והבן:
@501 **ויקרא לזקני העם**. הנה נתחכם משה רבינו עליו השלום בשליחותו לעשותה בהתבוננות, כי ירא ופחד לבבו דלמא תארע תקלה בדבר שהוא תכלית הכל ועיקר העולם, וכבר אחזו חבלים לארץ שמא חם ושלום לא יקבלו ישראל את התורה, ונתחכם עליו השלום ולא דיבר לכללות העם עד שקרא לזקנים והושיבם לפניו וכל ישראל יחד שומעים דברי משה אלא שהקביל הדברים לפני הזקנים, והועיל בזה כדי שלא יתחילו להשיב למשה אלא הזקנים ולא כללות העם כי חש דלמא חם ושלום יענו מהעם תשובה שלא כהוגן מה שאין כן הזקנים מובטח הוא בהם שתשובתם תהיה כהוגן ואחר שישיבו הזקנים כהוגן העם יטו אחריהם, ולו יהיה כי יקהו שיניהם חס ושלום, כל זקן וזקן ידבר לבני משפחתו. ואולי כי בני אל חי נודעה להם התחכמות משה כי חש למיאון חם ושלום והוציאו עצמם מהחשד ולא הניחו לזקנים להשיב תחלה וענו כל העם יחדו כל אשר דבר ה' נעשה מדעתנו השלמה וברצוננו הפשוט ולא קדמה תשובת הזקנים לתשובת כל עם ה', והנה הראו בני ישראל עוצם אחדותם והשואת רצונם באלהינו כי ס' רבוא אמרו בהשואה דיבור אחד כאומרו יחדו ולא נתאחר אחד מהם ולא קדם אחד לחבירו ולא שינה אחד מהם להשיב בנוסח אחר אשרי עולם שאומה זו בתוכו. ובזה ידויק מאמר הנביא (ירמי' ב') כה אמר ה' זכרתי לך חסד נעוריך אהבת כלולותיך פירוש אומרו כלולותיך הוא תשובתם שענו כל העם יחדו שעשו ב' כלליות באהבה, הא' תשובה כהוגן מכולם ואין גם א' שלא נתרצה בדבר. ב' שהושוו יחד בקול התשובה ובלשון התשובה על דרך שכתבנו:
@501 **את כל וגו'**. נתכוון באומרו **את כל** שלא שינה מהודעת כל בלא מגרעת, ואומרו **האלה** שלא הוסיף לדבר דבר כמאמר ה' אליו (פסוק ו') אלא הדברים:
@502 **וישב משה**. פירוש לשון חזרה כי מלבד מה שקדמה הידיעה לבורא מתשובת ישראל כי הוא יודע נסתרות בכליות האדם ומכל שכן הנגלות עוד החזיר הדברים פעם ב', והטעם הוא לשבח התשובה כאשר אבאר בסמוך. או ירצה על דרך אומרם ז''ל (מכילתא) שאמר ה' למשה החזר לי תשובה, לזה אמר **וישב** פירוש כי לצד התשובה שאמר לו ה' השיבני וכו' הוא שעשה, כי זולת זה מי יגיד לפני יודע כל ברוך הוא:
@502 **את דברי העם וגו'**. אין הכוונה שהשיב שקבלו לעשות אלא השיב לה' אופן סדר התשובה שענו כולם יחדיו על דרך שפירשתי, ולא להודעה אלא נתכוין בזה לפאר לרומם עם בני ישראל על כמה בחינות טובות אשר תגיד אופן התשובה, ולזה החזיר משה הדברים לפני ה' על דרך אומרו (ד''ה א' י''ז) ומי כעמך ישראל גוי אחד:
@503 **הנה אנכי בא אליך וגו'**. אולי שיכוין לומר לו כי לצד שהיה ה' רגיל לדבר עמו פנים בפנים לזה אמר אליו שידבר עמו באופן אחר דהיינו **בעב הענן** ולא יהיה הדיבור כל כך רוחני כרגילות הקודם, ונתן הטעם **בעבור ישמע העם** כשידבר עם משה ואם ידבר כסדר הראשון באספקלריא המאירה אין כח בישראל לשמוע הדברים לעוצם רוחניותם, וה' חפץ שישמיע המאמרים לישראל, ואמר לו שמלבד תכלית זה שישמע העם המצוה מפי הבורא ויש בזה חיזוק האמונה בלבם עוד יש תועלת שיאמינו במשה לעולם בשאר מצות כשיצוה אותם על פי ה'. ונתכוין ה' בזה גם כן לרצות משה שלא יקפיד על המעטת כבודו מאופן הדיבור הרגיל:
@503 **יאמינו לעולם**. פירוש לעולם לדורות הבאים יאמינו באמצעותך בכל הנביאים על דרך שכתב רמב''ם בפ''ח מה' יסודי התורה וזה לשונו כל נביא שיעמוד אחר משה רבינו אין אנו מאמינים בו מפני האות וכו' אלא מפני המצוה שצוה משה בתורה ואמר אם נתן אות אליו תשמעון עד כאן. וכתב עוד שם כי אמונת משה לא היתה לצד המופתים וכו' אלא לצד ששמעו בדבר ה' עמו והם עדים באמיתות נבואתו. ועל פי הדברים יכולנו לפרש **וגם בך יאמינו לעולם** טעם אומרו לעולם רמז גם על שאר נביאים הבאים אחריו לעולם כשיבא גם כן נביא להם שלוח ממני יצדיקו נבואתו. כי האותות שיעשו לא יאמתו הנבואה אלא במצות ה' על אמונתם וזולת הבחנה זו גם המצוה במצוה זו יש בו פקפוק כשתהיה אמונתו על פי האותות זולת כשישמע העם בדברו עמו. אלא שיש לתת לב בדברי הרמב''ם איך יצדק לומר שלא האמינו במשה והלא כבר נאמר (לעיל י''ד ל''א) ויאמינו בה' ובמשה וגו' כי מופתיו ואותותיו מופלאים הם ומה גם מעשה קריעת ים סוף הוא דבר מבהיל ובו יצדיקו ויכריחו האמונה, הן אמת כי בשאר נביאים לצד שאין צריכין לעשות אותות חזקים וגדולים כאותות משה לזה צריכין אנו לחזק אמונת נבואתם על פי מאמר ה' אשר צוה לשמוע לו מה שאין כן משה. ומה שכתב רמב''ם שם כי אותות שעשה משה לא היו כדי שיאמינו בו אלא לצורכי ישראל וכו' כאמור שם, סוף כל סוף ישתמע האמת מעצמו כי משה אמת:
@503 **ונראה** לומר כי האמונה שהאמינו ישראל במשה היתה שהוא עבד ה' וה' חפץ בו ועושה תפלתו ורצונו אך לא האמינו שהיה ה' מדבר עמו, כי יש סברא מחכמי אומות שמוכיחים בהרבה הוכחות כפי פילוספיותם כי מן האי אפשריות שידבר ה' עם אדם וחי, ואלה יצדיקו כי ה' ישמע ויענה ויאהב לחביביו ויעשה רצונם, ולצד שיש סברא זו בעולם נוכל לומר כי הגם שהאמינו ישראל במשה עבדו פירוש שהוא עבד ה' וישמע ה' תפלתו ויעשה חפצו ורצונו אבל לא מפני זה יצדיקו כי ידבר ה', וישנה עדיין לחששת פילוסופי האומות, לזה אמר ה' אליו **בעבו** ר **ישמע העם בדברי עמך** ובזה יצדיקו כי ידבר ה' עם האדם וחי, ואומרו **וגם בך יאמינו** פירוש באמצעותך יאמינו בנביא אשר אקים להם תחתיך בכל דור ודור לעולם כי תפקע מהם טענת סברא זו. או ירצה אומרו **בך** באמצעות נבואתך כשיצדיקוה כשתצוה להם שישמעון לנביא על פי אות יאמינו לעולם לכל נביא ונביא אבל זולת הצדקת נבואתך לא יועיל האות להאמין בנביא כמו שכתב הרמב''ם. אחר שכתבתי זה מצאתי ברייתא במכילתא וזה לשונם גם בך גם בנביאים שאחריך עד כאן, והם דברינו עצמם ובמה שפירשתי תבין כוונת דבריהם. והנה בשמוע העם דברי ה' הצדיקו כולם יחד כי ידבר ה' עם האדם וחי וכמו שהגידו בפיהם ואמרו (דברים ה' כ''א) היום הזה ראינו כי ידבר ה' עם האדם וחי והם עדי ה' בדבר ונכזבה דעת הפילוסופים בראיה ברורה, וגם הכירו מעלת הנביא משה במשה שנשאהו ה' בנבואתו דכתיב (פסוק י''ט) משה ידבר והאלהים יעננו בקול וכמו שדרשו ז''ל בכתוב (מכילתא) יעויין שם דבריהם:
@503 **ויגד משה וגו'**. אולי שהגיד שהסכימו לשמוע דברי ה' מפיו כמאמר ה' בעבור ישמע העם וגו', או שאין צריך עוד אות להאמין במשה שכבר האמינו במשה כי הוא נביא. ומכוון ההגדה היא, לימוד זכות על ישראל לבד, ולדבריהם ז''ל (מכילתא) שאמרו שההגדה היא שאמרו ישראל רצוננו לשמוע מפי ה', ולמאן דאמר לראות את מלכנו ידוייק לשון הגדה שהם דברים קשים שיבקש עבד לשמוע קול אלוהו או לראות כבודו יתברך. והגם כי מצינו שאמר ה' בעבור ישמע העם לא אמר שידבר עמהם אעל בדברו עם משה ישמעו הם ובקשתם היתה שידבר ה' עמהם, וטעם ההגדה הגם שלא יכחד ממנו דבר הוא להשיבו על שאלתם. ומצינו לו שהשיב תכף ומיד לך אל העם וקדשתם וגו':
@506 **והגבלת וגו'**. נראה שאין מצות הגבלה זו אלא ליום הג' ואף על פי כן הקדימה מעתה כדי שינהגו בו כבוד מעכשיו, גם ירגילו עצמם להתרחק ממנו בג' ימים, ואין לומר שינהוג חיוב הנגיעה בהר מיום צוותו, זה אינו כי הוא דבר רחוק שיתקדש ההר ויתחייבו עליו קודם רדת שכינתו ית'. וכן משמע ממתניתא בספרי (מכילתא כ''ד) כי לא התחיל החיוב אלא מיום ג':
@511 **ויוצא משה וגו'**. אולי שלצד חרדתם פחדו מן ההר והוציאם משה והעמידם בתחתית ההר לקבל התורה מעומד:
@512 **עשן כולו**. פירוש ששלט האש בגופו של הר ונשרפו אבניו כמשפט הכבשן אשר ישרפו בו האבנים לעשות סיד, ומעתה אבני סיני נעשו סיד, ואומרו **ויחרד כל ההר** כי כן דרך האבנים כששולט בהם אש בכבשן יתזעזעו וישמיעו קול חרדה:
@513 **משה ידבר והאלהים וגו'**. אולי שהיה משה מדבר לפני ה' דברי שיר ושבח כמקבל פני מלך הגדול ברוך הוא, **והאלהים יעננו בקול** פי' בקול האמור בסמוך שהוא קול השופר כמי שמתרצה בדבריו. או יאמר **יעננו** למה שהיה מדבר לו ואומרו **בקול** פי' בקול גדול בעבור ישמע העם בדברו עמו כמו שכתבנו למעלה שבזה יצדיקו נבואתו. ורואני כי יש בזה תוספות הדרגה כי היה ה' עונה לדברי משה וזה יותר מעלה ממה שהיה ה' מדבר תחלה ויענהו משה. ורבותינו ז''ל אמרו (מכילתא) שיכוין על הדברות ששמעו מפי משה שהיה ה' מגביה קולו של משה וכו', וזה דרך דרש וכפטיש וגו':
@514 **וירד ה' על הר סיני**. רבותינו ז''ל אמרו (סוכה ה'.) למעלה מעשרה. וצריך לדעת למה הוצרך לומר **אל ראש ההר** כיון שהגבוה הוא עשרה מההר פשיטא שאפילו לראשו לא הגיע. ואולי כי בא לשלול שלא ירדה שכינה לצדדי ההר ואפילו למעלה מעשרה, הגם שמצינו לו שאפילו במקומות הנמוכים ירדה שכינה כל שיש ממנה לארץ י' טפחים, וצא ולמד מהמשכן בכל מקום אשר יחנו בני ישראל ישכון שם כבוד ה', כאן בהר לא ירד אלא על ראש ההר, ולזה מצא משהעלות אל ראש ההר, וכאומרו בסמוך ויקרא ה' למשה אל ראש ההר. וצריך ליישב עדיין למה לא אמר הכתוב וירד ה' על ראש הר סיני. ואולי שחש לטעות בכוונת דבריו, כי לעולם ירד על כללות הר סיני ראשו וצדדיו ואומרו על ראש לצד שלא השרה שכינתו ממש על ההר בבחינת כל חלק וחלק מההר יקרא מקום שכינת ה' שמה ראש להיותו עליון ממנו והבן, לזה אמר בסדר זה **וירד ה' על הר סיני** למעלה מעשרה ואחר כך חזר להוריע מקום שירד שמה שהוא **אל ראש ההר** והבן:
@514 **עוד** ירצה על פי דבריהם ז''ל שאמרו (מכילתא פ''ט) כתוב א' אומר מן השמים וגו', מלמד שהרכין ה' שמים העליונים וכו' והציען על גבי ההר ודבר עמהם עד כאן. וזה הוא שיעור הכתוב **וירד ה' על** וגו' פירוש לא ירד ממש אלא למעלה כרמוז בתיבת על ושמיו מקום מצבו היו נוגעים אל ראש ההר:
@514 **עוד** ירצה להודיע כי כשירד ה' פירוש כשהתחיל להוריד שכינתו רעש ההר ועלה לקראתו כעבד רץ לפני רבו, וזה הוא שיעור הכתוב **וירד ה'** ועדיין לא גילה הכתוב לאיזה מקום ירד והודיע פעולת ההר הגם היותו דומם שנעשה בעל חי ועלה קודם שיגיע עדיו, ואחר כך הודיע הכתוב לאיזה מקום ירד ואמר **אל ראש ההר**, הא למדת שעלה ההר קודם הגעת שכינת ה' אל ראשו:
@515 **פן יהרסו וגו'**. פירוש לבל יחשבו בדעתם כי יראו ברוך הוא הגם שימותו על דרך אומרו (תהלים ס''ג) טוב חסדך מחיים ומיתתם זו היא חיותם, והוא אומרו **פן יהרסו** פירוש יסכימו על הריסתם **אל ה' לראות** פירוש כאלו אמר לראות אל ה', ואומרו **ונפל ממנו רב** פירוש תהיה נפילתם נפילה רבה מלבד שימותו תהיה להם נפילה אחר נפילה. או ירצה כי לצד שאורו יתברך ממלא המקום כשיבואו לראות יצטרך ה' לסלק האור ההוא לבל יביטו בו, וזה הוא אומרו **פן יהרסו אל ה'** פירוש לאורו לסיבת ראותם, והרי זה מגיד כי לא ישיגו לראות אם יבואו לראות, ולזה לא אמר הכתוב פן יראו כי לא ישיגוהו כנזכר אלא הם יחשבו בדעתם לראות, ושמא תאמר אין כאן לא הקרבת התועלת ולא נזק לזה אמר **ונפל** וגו' פי' מלבד שלא יראו עוד להם הקרבת הנזק. ודקדק לומר **רב** פירוש אפילו יהיה הרב שבהם לא יאמר שלא אקפיד אלא על המון העם אבל גדולי ישראל הראוים להשראת שכינה לא אקפיד תלמוד לומר ונפל ממנו רב:
@516 **וגם הכהנים**. פי' הגם שיש להם מעלת קריבה אל מקום המקודש לעבוד בבית ה' כאשר היה מקובל בידם או הבכורות או מזרע אהרן, **יתקדשו** פי' לא תהיה קדושתם מגעת עד גדר זה וצריכין הם לחשוב עצמם בערך מקום זה כאילו אין להם קדושה כל עיקר. ושיעור תיבת יתקדשו כשיעור תיבת ודשנו (במדבר ד' י''ג.) או ירצה על פי דבריהם ז''ל (מכילתא) כי הגביל ההר עד כאן משה עד כאן גבול אהרן עד כאן גבול הכהנים, כפי זה אומרו **הנגשים אל ה'** פירוש שגבולם בהר נגשים מה שאין כן ישראל, **יתקדשו**, פי' יעמדו בקדושתם ולא יוסיפו לעלות עוד פן וגו':
@517 **ויאמר משה וגו' לא יוכל וגו'**. צריך לדעת תוכן משמעות ענין ההפרש בין משה ובין ה' כי ה' אמר לו רד העד וגו' ולא הספיק מה שכבר צוה קודם ומשה מקשה ואומר כי אינו צריך ודי במה שקדם מהציווי וההתראה. ונראה כי מתחלה צוה ה' על ישראל לבל יעלו ולבל יגעו בהר בדרך כלל וכשחזר ה' לומר למשה שיתקדשו הכהנים ורמז לו שיש להם מקום בהר לעמוד בו וכמו שדייקנו מאומרו הנגשים אל ה' יתקדשו חש שישראל ידונו בדין זה דין דבר שהיה בכלל ויצא מן הכלל שללמד על הכלל יצא והכהנים והעם ואהרן הכל בכלל נגיעת ועליית הר היו וכשיצאו כהנים להתיר חלק בהר ללמד על הכלל יצא ויותרו כל ישראל בחלק שהותרו בו הכהנים ולפחות בחלק שלמטה ממנו בהדרגה, והגם שעדיין לא נתנה תורה לדעת משפט זה אפשר שימצא בתוך ס' ריבוא ישראל חכם שידין בחכמתו כזה. או לו יהיה שלא ידון אדם דין זה מדעתו עם כל זה ה' אוהב משפט צדק ולא יכול לחייבו מיתה לנוגע בהר במקום עמידת הכהנים אחר שכפי משפט התורה פטור הוא כנזכר, לזה חזר ה' לומר לו רד העד בעם ובזה סתר שאין לדון בדין זה דבר שהיה בכלל שהרי גילה הדבר בפירוש לאסור חלק ההר שיעלו בו הכהנים, ומשה לא הבין דברי ה' וכוונתו כמו שפירשנוה כי עדיין לא גילה לו ה' מדות שהתורה נדרשת בהם וסבר כי דוקא אהרן והכהנים שהתירם ה' אבל ישראל באיסורם עומדים ולזה צעק לבו כי אזהרה זו אינה צריכה כי לא יוכל וגו' שכבר העדותה בנו, והשיבו ה' לך רד ועלית אתה וגו' ועל פרטי המקומות שאני מתיר לך ולאהרן ולהכהנים אני מזהירך שתעד בהגבלתם הרי זה מורה באצבע כי לצד מה שגילה בהם ההתר הוא שהוצרך לחזור לאוסרם:
@517 **ולפי** מה שפירשנו באומרו הנגשים וגו' שהכוונה הוא הנגשים לעבודת המשכן גם כן יהיה טעם חזרת האזהרה כמו שפירשנו לצד דבר שהיה בכלל אלא כי עדיין לא גילה ה' היתר עליית אהרן והכהנים שמצדה הוצרך לחזור פעם ב' האזהרה ותיכף קדם משה קודם שיגמור הדבור של היתר עליית הכהנים ואמר **לא** י **וכל** וגו' וחזר ה' והודיעו התבוננות הדברים ואמר לו **לך רד ועלית אתה** וגו' והכהנים הרי התיר חלק מעליית ההר ותיכף סמוך ממש אמר לו **והעם אל יהרסו** פירוש כל עיקר והכהנים לא יהרסו למקום אהרן ואהרן למקום משה ואז השכיל דעת עליון על דרך שפירשתי שהמיחוש הוא לבל ידונו דבר שהיה בכלל וכו', ורמזו אל עליון בסדר הדיבור שהקדים לומר לו **ועלית** וגו' **והכהנים** וגו' ואחר כך **והעם אל יהרסו** וגו'. ובזה מצאנו נחת רוח במאמר ב' שאמר ה' למשה **ועלית אתה** וגו' וקשה ממה נפשך אם הודה לו ה' על תשובתו אם כן למה חזר לומר פעם ב' והעם אל יהרסו, ודבר זה פשוט הוא כי כוונתו היא שיאמר כן לישראל אם כן לא נתקבלה תשובת משה, ואם נאמר גם כן שלא הודה על דברי משה למה לא השיבו תיכף לסתור דבריו עד שהקדים לומר ועלית אתה ואהרן והכהנים כי היה לו לה' לגמור ענין השליחות שהתחיל לצותו עליו שאמר לו העד בעם וגו' ואחר כך יצו האל דבר חדש שהוא ענין עליית אהרן והכהנים שלא הזכירו עד עתה, ובמה שפירשתי יבא על נכון כי לעולם לא באה מצות העד בעם אלא לצד היתר גבולין של אהרן אלא שלא המתין משה עד גמרן של דברים ולזה בדברי ה' אליו הקדים תשלום הדברים שלא הספיק משה לשומעם שהוא טעם האזהרה ואמר לו **ועלית אתה ואהרן והכהנים** הרי התיר גבול מההר לאהרן וגבול לכהנים וגמר אומר **והעם אל יהרסו** לגבולין של אהרן והכהנים אלא כל ההר באיסור:
@517 **עוד** נראה לומר טעם ההתראה פעם ב' להיות כי התראה ראשונה לא נאמר בה זמן מאימתי מתחיל האיסור, והגם שהזכיר שם ג' ימים לא נאמרו בפירוש בענין איסור הגבלת ההר שמתחיל מיום הג' ונמצא שעדיין לא ידעו ישראל זמן התחלתה, לזה כשירד ה' תכף אמר למשה שירד להעד וגו' שהוא משעה זו ואילך, ותשובת משה צריך עיון. ואולי כי משה חשב כי איסור הגבלת ההר היא מעת צוותם כיון שלא נתבאר בפירוש לא תגע בו יד ביום פלוני התחלת המצוה היא מעת האזהרה, ולא כן היה דעת עליון, ולזה היה עליו דבר ה' חזק לחזור לומר כי זה הוא זמן ההגבלה. ולכשנאמר כי כן היתה דעת עליון שאיסור נגיעת ההר יתחיל מעת צוותו טעם שהוצרך האזהרה פעם ב' כי בפעם ראשונה אמר כי סקול יסקל או וגו' הרי זו מיתת בית דין וכאן חידש כי מי שלא הרגוהו ישראל שה' יפרוץ וגו', ודקדק לומר לשון רבים לומר שהגם שיהרסו כולם לראות ידינם בדין שמים ויפרוץ בם ה':
@518 **רד ועלית וגו' עמך**. כפל לומר **לך רד**, אחת לגופה ואחת לומר לו לשון ירידה ואולי שהירידה היא מקודם לא היה למשה מקום מוקבל בהר והיה עולה לראש ההרה וכשסרב אמר לו **רד ועלית** וגו' פי' כשם שאהרן יש לו גבול גם אתה יש לך גבול והוא אומרו עמך הרי השוה האחים בבחינת הגבול:
@520 **וידבר וגו' את כל הדברים וגו'**. טעם זכרון שם אלהים בנתינת תורה, לומר כי התורה נתנה ממדת הדין וממדת הרחמים, מדת הדין **וידבר אלהים**, מדת רחמים **אנכי ה'**, עוד הודיע סוד אומרו (מ''א י''ח) ה' הוא האלהים, כי דבר אלהים אנכי ה', והוא מה שאנו מיחדים פעמים באהבה בפ' שמע ישראל ה' אלהינו ה' אחד:
@520 **עוד** יתבאר על דרך שאמר רב קטינא (מנחות מ''א.) ענשיתו אעשה וכו' עד כאן, הרי שעל עשה לא יעניש הכתוב, לזה אמר ה' כי יביא ה' במשפט עונש על כל הדברים גם לעשין הרשומים בי' הדברות, אמונתו ית' שהוא עיקר הכל הרשומים בתחלת דבר ה' אנכי וגו', שבת, כבוד אב ואם, על אלו הגם שהם עשה יש אלהים שופטים בארץ, והוא. אומרו **וידבר אלהים** שהוא בחינת הדין את כל הדברים בין עשה בין לא תעשה:
@520 **עוד** ירצה באומרו **את כל הדברים** לומר כי אין חפץ במקבל תורה אלא אם יקבל כל התורה, וכל המקבל עליו תורה חוץ ממצוה א' אין לו תורה (בכודות ל:):
@520 **עוד** ירצה על פי ממה שהקדמתי בפ' בראשית כי כשידבר ה' בתגבורת המכונת לשם אלהים ידבר דברים מופלאים אשר אין הפה יכול לדבר והוא שיאמר הדברים שלימים וכן רבים בדבור אחד כאשר עשה בבריאת עולם, כמו כן ביום מתן תורה דיבר בתגבורת את כל הדברים בדבור אחד, ואומרו תיבת **לאמר** יתבאר בהעיר מה שיש להעיר בנוסח עשרת הדברים מדוע שינה הכתוב נוסח דיבור מדיבור כי בתחלה התחיל לדבר בסדר זה **אנכי ה' אלהיך**, **הוצאתיך**, **על פני**, כי ה' הוא המדבר על עצמו יתברך שמו ואחר כך יצא לדבר בדרך אחר **את שם ה' אלהיך**, **לא ינקה ה'**, **שבת לה' אלהיך**, **כי ששת ימים עשה ה'**, שהיה לו לסיים כדרך שהתחיל על זה הדרך לא תשא את שמי, כי לא אנקה, כי ו' ימים עשיתי וגו':
@520 **אכן** יתבאר על דרך אומרם ז''ל (מכות כ''ד.) אנכי ולא יהיה לך מפי הגבורה שמענום פירוש בתגבורת הדיבור יובן כי כאשר דיבר ה' עשרת הדברים בדיבור אחד כמו שכתבנו בסמוך אין האוזן יכולה לשמוע כל הגבורות וכשהשמיעם לישראל השיגו הם שמוע ב' דברות מהם שהם דיבור אנכי וגו' ודיבור לא יהי' לך ויצתה נשמתם כאומרו (שה''ש ה') נפשי יצאה בדברו ולא יכלו הבין עוד ושאר הדברות נחצבו להבות אש מקולו יתברך ועמדו סדורים על הר סיני עד שחזרה נשמת ישראל בטל חיים באו הדברות שהם קולות האדיר ברוך הוא והיו מדברות לכל א' מישראל, ולזה תמצא שאנכי ולא יהיה לך נחקקו בתורה כסדר שאמרם ה' **אנכי ה' אלהיך אשר הוצאתיך** כי האלוה בכבודו מדבר נוכח לישראל בעד עצמו ברוך הוא וכמו כן במצות **לא יהיה לך** גם כן ידבר כסדר זה אבל משם ואילך ידבר קולו יתברך בעד מלאכו כאומרו **שבת לה' אלהיך**, **כי ששת ימים עשה ה'**, **על כן בר** ך ה', וגו' וכן כולם, כי אינו יכול הקול לומר שבת לי וגו', עשיתי את השמים וגו' ונתתי וגו', כי אינו אלא מלאכו ית' והבן ויערב לחכך. והגם שאמרו ז''ל (מכות כ''ג:) כי משה אמרם לישראל, אפשר כי משה היה בו כח ושמע כולם וכשבאו הקולות לדבר לישראל היה קולו של משה גם כן מדבר. ואולי כי לזה רמז הכתוב באומרו (לעיל י''ט י''ט) משה ידבר והאלהים יעננו בקול, ותמצא שאמרו ז''ל (שהש''ר פס' ישקני) שכל דיבור ודיבור היה עומד על כל אחד ואחד מישראל ואומר לו תקבלני עליך והוא אומר לו הן ומחבקו ומנשקו ועולה ומתעטר על ראשו, ולפי זה יתיישב אומרו **לאמר** על זה הדרך **וידבר אלהים את כל** וגו' פירוש בתגבורת האלהים ודיבר כולם בדיבור אחד גם עשה כח בדברות שהם בעצמם יאמרו לישראל כשיצטרכו כמו שכן היה כי כשלא יכלו ישראל לשמוע כולם מהגבורה דברו הם אליהם כמו שכתבנו:
@520 **עוד** יכוין באומרו **לאמר** כי יש בסדר זה שנדברו בו הדברים מעלה ורוממות לישראל על דרך אומרו (דברים כו יח) וה' האמירך וגו' כי הרבה תועליות נמשכו מזה שפסקה זוהמתן וזה יסוד קניית הקדושה בהם לעולם:
@520 **עוד** יתבאר הכתוב על דרך אומרם ז''ל (תנחומא תולדות) שאין הקדוש ברוך הוא מייחד שמו על הנבראים בחיים חיותם משום (איוב טו) הן בקדושיו לא יאמין, ולזה לא יחד שמו על אברהם לומר עליו אלהיך אלא אחר מותו, והוא אומרו **וידבר אלהים את כל הדברים האלה** פירוש בתגבורת הדיבור כמו שפי' דברים שאין האוזן יכולה לשמוע, והטעם הוא **לאמר** להם אנכי ה' אלהיך פירוש ליחד שמו על כל אחד ואחד מהם לומר לו אלהיך אשר על כן השמיעם את קולו ליסרם להפריד מהם הזוהמא ובזה יהיו ראוים לומר להם כן. ולדברי רבותינו ז''ל (שבת פ''ח:) שאמרו שפרחה נשמתם נמצאת אומר כי כשיחד שמו עליהם היה זמן יציאת נשמה אז אמר לכל אחד מהם אלהיך, והגם שהיו בחיים ושמעו גם כן לא יהיה לך וגו', לא יתייחס לה איחור כי הכל אמר ה' בדיבור אחד ולא קדמה אפילו אות לחברתה. עוד אומרו **לאמר** יכוין אומרם ז''ל (זהר ח''ב צ''ג:) שכל התורה כולה רמוזה בעשרת הדברות, והוא אומרו **לאמר** פירוש דברים אלו יש בהם אמרות אחרות כלולות ורמוזות. וראיתי לתת טוב טעם בהשמעת ה' לישראל ב' דברות אנכי ולא יהיה לך כי הם ב' שרשים לב' כללות המצות מצות עשה ומצות לא תעשה, **אנכי** היא עיקר ושורש כל מצות עשה, **לא יהיה לך** וגו' היא עיקר ושורש כל מצות לא תעשה, לזה נטע ה' בהם מפי אל עליון שרשי ב' עיקרי המצות שבזה לא תימוט תורה מזרעינו לעולם ועד:
@521 **אנכי ה' אלהיך וגו'**. טעם כפל אשר הוצאתיך **מארץ** וגו' **מבית עבדים**. פשט הדברים הוא שכוונתו להגדיל עוצם שבייתם שהיו בארץ מצרים מקום שאסיריו לא פתח (ישעי' יד יז) וגו' נוסף על הפלגת טומאתה, ועוד שהיו שם בגדר עבדים והוציאנו ה':
@521 **עוד** יכוין ה' לומר על זה הדרך **אנכי ה' אלהיך** הנה הזכיר בתחלת דברי ה' ב' עניינים האחד היותו ה' ברוך הוא שם הוי''ה זה יגיד האמונה כי ממנו יתברך ובמאמרו היה כל הווה וכל מה שהיה ומה שיהיה, גם יגיד על הוויתו יתברך היה והווה ויהיה, והב' אמר אלהיך פירוש שעליהם לקבל מאמרו וגזרותיו, וכל הממרה את פיו יכנו אלוה, וכנגד ב' בחינות אלו בא האלקים להכריח כל אחת מהם בהוכחה שאין עליה טענה, כנגד אומרו **אנכי ה'** זה לך האות **אשר הוצאתיך מארץ מצרים**, דע כי באמצעות יציאת מצרים הוכחשו כל הדוברים שקר שיש חס ושלום אמונה זולתו כי הוכחשו המאורות כי לא אלהים המה בהחשיך ה' מאורם, הוכחושו הימים כי ה' עשה בהם אותות והפכם לדם, הוכחשה הארץ בהכותה ה' ותשרץ שרצים רעים, הוכחושו בעלי חיים שאין בהם ובמזלם חוזק, הוכחושו כל אלוהות בעשות ה' בהם שפטים, הרי כי ה' הוא אדון כל הווה ושולט על הווה ומכחידו וגוזר על אין ויהיה כאשר עיני כל ישראל רואות. וכנגד מה שאמר **אלהיך** שצריכין לקבלו עליהם לאלוה לקיים כל דבריו אמר טעם הדבר **מבית עבדים** פירוש כי לצד שהיית עבד לזולת ואני הוצאתיך מעבדותם שורת הדין נותנת כי תקבל אלהותי עליך לקיים כל דבר:
@521 **עוד** ירצה בכפל **מארץ מצרים מבית עבדים** להודיע סוד כמוס כידוע ליודעי חן כי נשמות ישראל שיצאו ממצרים הן הנה שהיו טבועים בטומאת מצרים ובאמצעות יעקב אבינו ובניו אשר ירדו מצרים הוציאו אותם כאומרו (בראשית מו ג) כי לגוי גדול אשימך שם. ועיין מה שפירשתי שם, ואמרו יודעי נסתרות לה' כי הוא עצמו שאמר הכתוב עליו (דברים ד' ז') כי מי גוי גדול וגו' שעמדו בהר סיני. וכפי זה יתבאר הכתוב על נכון אומרו **אשר הוצאתיך מארץ מצרים** הוא הוצאות הנשמות משבייתם בטומאת מצרים פי' שבררם באמצעות מועצותיו ית', אבל עודם במצרים בבית עבדות, ואמר **מבית עבדים** כנגד מה שהוציא העם המבורר לבל ישתעבדו בהם שונאיהם:
@521 **עוד** ירצה על דרך אומרם ז''ל (ירושלמי סוכה פ''ה ה''ד) בפירוש יושב תהלות ישראל כי לא נתרצה הקדוש ברוך הוא בתהלת מהלליו כשאמרו אלהי עולם ולא אלהי המלאכים אלא כשאמרו ברוך ה' אלהי ישראל, והוא אומרו **אנכי ה' אלהיך** פירוש שלא נתרציתי בשום כינוי המעלות אלא בקריאתו אלהיך ובזה פרסם מעלות ישראל בעליונים, וכנגד פרסום בתחתונים אמר **אשר הוצאתיך** וגו' פי' מקום שאין מציאות לצאת משם והיתה הוצאתיך פרסום גדול לכבוד ולתפארת, וצא ולמד מדברי יתרו שהוא אחד המיוחד מהאומות. ואומרו **מבית עבדים** פירוש לא הוצאתיך בדרך שישאר עליך שם עבדות, המשל אם היה ה' מוציאם בדרך בריחה וכדומה הגם שהיתה ההצלה נכונה אף על פי כן שם עבדות לא יעקר מהם כי אלה עבדי פרעה, וממה שהוציאם בכמה נוראות עד שאמר פרעה הרי אתם לעצמכם הרי אתם בני חורין כו' (ילקוט ר''ח), ועוד לו כשרדף שעשה ה' הפלא הגדול בהטבעתו בים בזה פקע שם עבדות מהם:
@521 **עוד** ירצה לדבר עם הנפש ועם הגוף, כנגד הנשמה אשר תכיר בחי' הרוחניות אמר **אנכי ה' אלהיך** כי הנשמה תכיר בחינת האלהות, ואולי באותו רגע עצמו היתה יציאת הנפש והכירה אלוה שלה כשאמר לה אנכי, ולזה אמר לשון יחיד **אלהיך** כי בחינת הנשמות הקדושות מתאחדת היא ואין בהם פירוד בעולם הפירוד שהוא עולם הזה, ותמצא שאמר דוד בדברי הימים (א' י''ז) ומי כעמך ישראל גוי אחד בארץ פירוש אפילו בארץ במקום הפירוד הם גוי אחד כי נתקדשו ונעשו בארץ כמלאכים והוא השבח שמשבחם בו דוד עליו השלום, וכנגד בחינת הגוף וחיותו שהוא בחינת הדומה לחיות הבהמי אמר הכרת חסד עולם הזה כי לא תוכל בחון בחשק רוחניות הנאור:
@521 **עוד** ירצה **אנכי ה' אלהיך** פי' קודם ביאתך לעולם הזה כי אתה אור מאור הקדוש חלק ה' כאומרו (דברים לב ט) חלק ה' עמו, ובחינה זו תגידנה תיבת אלהיך כי לא יתיחס דבר זה אלא לבחי' הקדושה שהוא מאורו יתברך כידוע ליודעי חן וכנרמז ברובי מאמרי רז''ל. ואומרו **אשר** וגו' פירוש אשר על כן הוצאתיך מארץ מצרים, ובזה הגיד טעם אשר הרעים והרעיש ה' תבל ויושביה שמים וצבאיה בשביל ישראל להוציאם כי מהנמנע שיציל חלקי הקדושה ולקרבם אליו:
@521 **עוד** ירצה על זה הדרך **אנכי ה'** פירוש בין בזמן שאני מתחסד עמך אהיה לך לרבון בין בזמן שאני מיסרך ומוכיחך אהיה אלהיך:
@521 **עוד** ירצה על דרך אומרו (תהלים קטז) כוס ישועות וגו' ובשם ה' אקרא צרה ויגון וגו' ובשם וגו', ודרשו ז''ל (ברכות ס':) מברכין על הרעה בשמחה כשם וכו', והטעם כי בחינת המוסר מה' אינו אלא לצד הטוב והחסד, והוא אומרו **אנכי ה'** פירוש מדת החסד והרחמים אפילו כזמן אלהיך פירוש שאני מיסרך:
@521 **עוד** ירצה באומרו **מארץ מצרים מבית עבדים** על זה הדרך אני אשר הוצאתיך מארץ מצרים אני עתיד להוציאך מבית עבדים, וזה ירמוז על גלות האחרון אשר שעבדו בישראל כל אומה ולשון כמשפט הרגיל בעבד ורמז ה' כי יוציאנו מבית זה:
@521 **עוד** ירצה על זה הדרך **אשר הוצאתיך מארץ מצרים**, ואם תאמר ולמה הוצאתנו משם ולא הגדלת חסדך עמנו שהיה ה' ממשיל ישראל שם בארץ אויביהם ויעבידו בעובדיהם וישלטו בהם ויקחו את ארצם מידם וישבו בה לעיניהם ויש בזה יותר נחת רוח לישראל והגדת עוצם היכולת כי יש אלהים שופטים בארץ ושולטים בה, לזה אמר ה' כי טעם הדבר הוא לצד שהארץ היא בית עבדים פירוש על דרך אומרו (דברים לב א) בהנחל עליון וגו' יצב גבולות עמים, ואמרו ז''ל (זהר ח''א ק''ח:) כי ה' חלק מקומות העולם לשרי מעלה זולת ארץ כנען אשר בחר לו לשמו כביכול, והוא אומרו **מבית עבדים** פירוש מקום שהוא של עבדים של ה' פירוש שממשלתו ממשלת שר אחד מעבדי ה' ולא רצה ה' שיהיו ישראל תחת ממשלת השרים אלא תחת ממשלתו יתברך בכל והוציאם מארץ מצרים לצד שהיא בית עבדים לתת להם ארץ אשר היא בית אלהים:
@522 **לא יהיה לך וגו'**. פירוש לצד שקדם לצוות על אמונתו יתברך והוא דבר שעיקרו בלב לזה אמר כי כמו כן יצטרך להרחיק מלבו אלהות הזולת הגם שלא יוציאנו בשפתיו, והוא שדקדק לומר בתיבת **לך** פירוש אפילו במחשבתך, וכפי זה מצינו אזהרה למחשבת עבודה זרה שאמרו ז''ל (קידושין ל''ט:) בפסוק (יחזקאל י''ד) למען תפוש וגו' שה' מעניש על מחשבת עבודה זרה ואמרו ז''ל (זכחים קו:) אין עונש בלא אזהרה, הרי לך אזהרתו:
@522 **עוד** ירצה לומר כי כל עבודה זרה שבעולם אין פעולת העובד פועלת הדרגה בנעבד לעשותו אלהים כאשר תעשנה פעולת איש ישראל כי נותן כח גדול בבחינת הרע וכופה חם ושלום בחינה המעולה לפני בחינת הרע רחמנא ליצלן, והוא אומרו **לא יהיה לך אלהים** פי' הויה שלך תעשנו אלהים:
@522 **עוד** ירצה כי באמצעות העובד הוא ממציא הויה אחת שהיא אלהים מה שלא היה כן קודם:
@522 **עוד** ירצה לומר כי אל זר אשר יעשה האדם זולתו יתברך הוא השופט נקמה מעובדהו על דרך אומרו (ירמי' ב') תיסרך רעתך:
@522 **עוד** ירצה כי בעשותו אל זולתו יתברך מהנמנע שיהיה לו אחד והגם שהוא לא ירצה לעבוד אלא לאחד. יתחייב לעשות רבים כי אין אחד, והוא אומרו **לא יהיה** לשון יחיד וגמר אומר אלהים אחרים. או ירצה לומר כי כשיתחיל לעבוד אחד לסוף יעבוד רבים. וצא ולמד מדברי נביאי ישראל (סנהדרין ק''ב:) ריבוי האלוהות שהיו ישראל עובדים בארץ בעונות. ואומרו **על פני** יתבאר על פי מה שכתב רמב''ם בפ''ט מה' יסודי התורה כי יאמן נביא בדבריו אם יאמר לעבור על מצוה אחת ממצות התורה לפי שעה על פי ה', ודוקא בשאר מצות חוץ מעבודה זרה שאפילו לפי שעה הרי זה נביא שקר ובן מות הוא, וזה הוא אומרו.
@522 **על פני** פירוש בכל פרטי הזמנים, כי כבר הקדים הודעתו יתברך בהזכרת שמו כי הוא היה והווה ויהיה באין הפסק, ומעתה הרי זה הכניס בכלל האיסור כל הימים והשעות והרגעים שכולם בכלל איסור לא יהיה:
@522 **עוד ירצה באומרו על פני** רמז לשלול טענת כת הטועים שעושים עבודה זרה לאמצעי לטענת שלילות המצאו חם ושלום, לזה אמר על פני פירוש כל הווה בעולם הוא על פני כי עיני ה' משוטטים בכל הארץ:
@522 **עוד** ירצה לתת טעם לאזהרתו כי כפי שכל אנושי ירחיק הדבר מטעם כי כל עובד אינו עובד אלא לאחד ממשמשיו יתברך ואדרבה מגדולת העבד גדולת האדון נודעת ואם כן העובד לשמש ולירח הרי זה עובד עבדיו ומשמשיו יתברך ולמה יקפיד ה' על הדבר, לזה אמר **על פני** פירוש לסיבה שאני מתכעס על הדבר שמשימים אל ללא אל, ותיבת פני לשון כעס על דרך אומרו (לקמן ל''ג י''ד) פני ילכו וגו', וכמו שאמר לבסוף כי אנכי וגו' אל קנא:
@522 **עוד** ירצה **על פני** על סיבת פני לבל תהיו נמנעים מהביט אל האלהים, כי אין לך עונג בעולם כראות פני ה' בעולם הנשמות כי הוא זה תכלית המקווה, והזהירם ה' לבל יסבבו מניעת עצמם מהשגה זו:
@522 **עוד** ירצה על דרך אומרו (דברים כח י) וראו כל עמי הארץ כי שם ה' נקרא עליך, ומעתה כשעובד אלהים אחרים הנה הוא משרה בחינת הרע על הפנים אשר שם קנתה הקדושה מקומה:
@523 **לא תעשה לך פסל וגו'**. צריך לדעת אחר אומרו לא יהיה לך וגו' ואפילו במחשבה מה צורך עוד לצוות על מעשה הפסילים, ואם לצוות על עשייתם אפי' לזולת אם כן לא היה לו לומר תיבת לך. עוד לא הי' לו לגמור אומר **לא תשתחוה** אם לא באה האזהרה אלא על מעשה אומן. עוד למה קרא לצלמים בשם פסל. עוד צריך לדעת למה הוצרך לומר פעם אחרת ה' **אלהיך** שהיה מספיק לומר כי אנכי אל קנא וחוזרים הדברים להמדבר בתחלה אנכי ה' אלהיך. עוד צריך לדעת למה הוצרך לתת טעם **כי** וגו' אל קנא הלא בלא טעם זה יתחייבו לקבל גזירת מלכו של עולם ברוך הוא:
@523 **ונראה** שיכוין לומר איסור מין עבודה זרה חוץ מהמוזכר בפסוק לא יהיה לך, והוא כי יאמר אדם האמת כי ה' הוא האלהים וכל זולתו אין אבל לצד עוצם גדולתו תתמעט תכונת האדם והשגתו לדבר לפניו ולשאול פרטי שאלותיו כי אינו ממוסר גדר הכבוד שתבא בריה שפלה אפילה כמוני ותשאל שאלות מלפני המלך הגדול והנורא ולפעמים ירבה בפרטי צרכיו דקים ורבים ואיך יהיה לו כל כך עזות פנים להרבות לשאול דקדוקי השאלות, אשר על כן יתיעץ בדעת יצרו שיבחר לדבר דבריו לפני אחד ממשמשי עליון המשמשים לפניו במרום והוא יעזור לו גם יהיה אמצעי לדבר דבריו לפני המלך הגדול בדבר הגדול אם יצטרך ובאמצעות כן כבד יכבד את השמש ההוא ויברכהו וישתחוה לפניו בדרך כל הכבוד והמעלה שבזה יתרצה לשאת משאו עליו לעשות לו צרכיו. ודע כי טעות זה בה טעו רוב העובדים עבודה זרה כי יודעים הם שעובדים ללא אלוה אלא כדי שיהיה להם לאמצעי וכו' כנזכר, ובחינה זו לא יקרא לה שם אלוה אלא פסל כי הוא יודע כי לא אלוה הוא וזה הוא פסלותו שאין בו כח אלהי ופסולת הוא לפני העיקר שהוא הבורא עולם, או קראו **פסל** כי הוא עומד להתפסל כשיעבירנו ה' מממשלתו על ידי סיבה או על ידי סיבת זה המשתחוה לו שיהא גורם להתפסל על דרך אומרם ז''ל (איכה רבתי פ''ב) במעשה דור המבול שאמרו אנו משביעים לשרים הממונים וכו' וה' העביר ממשלת השרים כאומרו (ישעי' מ''ג) ואחלל שרי קודש. וצוה ה' גם על בחינה זו ואמר **לא תעשה לך** פסל פירוש הגם כי לך בעצמך בדעתך שהוא פסל אף על פי כן לא תעשהו לך וחזר ופירש מה הוא המעשה ואמר **לא תשתחוה להם** וגו' ואמר הטעם להאיסור **כי אנכי ה' אל קנא** פירוש מתקנא אני על הדבר הגם שיהיה בדרך זה. ולהבין תוכן הכוונה הנה מצינו לה' שהזכיר פרט זה של הקנאה בפרשת נשא (במדבר י''ד) דכתיב ועבר עליו רוח קנאה וקנא את אשתו וגו' הנה לפעמים יתקנא אדם באשתו על בנו ועל עבדו, וכבר ידעת כי ישראל בבחינת כלה הם כרמוז באורך בספר קודש קדשים שיר השירים, ומעתה כשישראל עושים להם בעלים הגם שלא ימרדו ולא יכחידו בבורא כי הוא אדון האדונים, השכל יחייב כי יתקנא הבעל. והמשל בזה אשת מלך כי תאהוב עבד מלך או בנו להכין דקדוקי פרטים הצריכה להם ותחבקהו ותנשקהו האם לא יתקנא המלך לדוקרה בחרב, כמו כן הדבר הזה, והמבחין אופן דביקות נפש עם בני ישראל עם הבורא בחפיצה בחשיקה בדביקה באהבה רבה ישיג התבוננות המושכל, והוא מה שאמר כי **אנכי ה' אלהיך** דקדק לומר אלהיך לרמוז האמור והוא סוד השראת שכינתו יתברך על ישראל וייחוד שמו והמשכיל יבין. ולזה תמצא כי אמר הכתוב (דברים ד יט) אשר חלק ה' וגו' לכל העמים כי העמים שריהם שרי מעלה והם המושלים בהם לא כן בני ישראל הוא מלכנו הוא שרינו הוא אלהינו ברוך הוא:
@523 **ובדרך** רמז ירמוז אומרו **לא תעשה לך פסל** פירוש שלא יפסול את עצמו, כי בחטא האדם בעון עבודה זרה שהיא כנגד כל התורה כולה מטבעו נפסל ויוסר צלם אלהי דכתיב (תהלים ל''ט) אך בצלם יתהלך איש ולא יראו פניו למעלה ונכנם בגדר איסור לבני אל חי לבל יסתכלו בפניו כמאמר הנביא למלך ישראל (מ''ב ג') לולי פני יהושפט וגו':
@524 **פקד עון אבות וגו'**. פירוש לצד כי אמר שהוא קנאי ברוך הוא וידוע הוא כי הקנאות תפעיל סמוך לדבר המתקנא עליו ורואים אנו הכחשת הדבר חס ושלום כמה וכמה מרדו ופשעו ועשו והצליחו ולא נגעה יד הקנאי, לזה אמר **פוקד** פירוש ואם ראית הפכיות הקנאה דע כי אני פוקד פירוש זו היא מדתי שאין אני נפרע מעושי רשע מיד ומאריך אפי עד דור ב' וג' וד' פירוש לפעמים. ואין אני מאריך אפי אלא עד זמן זה, והטעם כי אם היה ה' מתקנא לאדם תכף אין קיום לנבראים, לזה מתחכם ה' לעושי רשעה ומעלים עין מלאבדם בעולם הזה כדי שיקומו בניהם אולי יטיבו דרכיהם ונמצא עולם קיים בהם, גם יועיל לאבות לזכותם בעולם הבא כאומרם (סנהדרין ק''ד.) ברא מזכה אבא, ואם דור ב' התעיבו כמעשה אבות אז יפקוד עליהם עון אבותם אתם ימקו, ועדיין ישנו לקנאות רשע האב בפרעון הבנים. ולפעמים יוסיף ה' להאריך אפו גם לדור ב' ותולה להם עד דור ג' לטעם עצמו האמור וכשירשיעו יפקוד עליהם וכו', ולפעמים יוסיף גם כן להאריך אפו גם לדור ג', אבל דור רביעי אין עוד תקוה להם כי הושרשו בקליפה לא ינתקו ממנה ובערה בם קנאת ה' עונם ועון אבות אבות אבותם מדור ראשון יחרב, והטעם כי כולם בחינת רע שלשלת אחת. ואשכילך כי בערך האדון ברוך הוא אפילו כשיאריך אפו עד דור רביעי יקרא מיד, כי ג' וד' דורות הם ג' מאות שנה ויומו של הקדוש ברוך הוא אלף שנה וכמו שיאמר תכף ומיד בערך האדם ו' וז' שעות כמו כן יהיה בערך האדון ג' מאות שנה. ובזה תמצא ישוב טעם למה האריך ה' לומר **על ועל** ולא אמר בדרך כלל פוקד עון עד רבעים כאומרו בעושה חסד לאלפים, כי ישתנה זה מזה והבן ועיין בסמוך:
@524 **ודע** כי התבוננות בדבר זה שאין ה' מתקנא בעושי רשע הוא דבר מבהיל ומה גם רשע מאריך ברשעתו ומצליח ברום ההצלחות, והמשכיל בגדר אשר גבל הבורא שהוא לד' דורות יצדיק משפט ישר, והוא שאמר אסף (תהלים ע''ג) אבינה לאחריתם פי' אחרית קצבת הדורות אשר קצב ה'. ודע כי כח בחי' הרע ישנו עד ד' דורות ולא יפרע ה' מדור ה' עון אבות הראשונים שהוא חמישי להם מה שאין כן בחינת הטוב שתגדל עד אלף ואלפים:
@525 **ועושה חסד לאלפים וגו** '. פירוש שגם עושה חסד אין הקדוש ברוך הוא משלם לו כל חסדו תיכף ומיד אלא בוחר לו אופן פרעון הנאות לו לדורות והולך ופורע בכל דור אשר יצטרך אליו ויש בו דבר המעמיד הגנה והצלה עד אלפים, והוא מאמרם ז''ל (שמו''ר פמ''ד) שאם היה הקדוש ברוך הוא פורע לאבות שכרם בעולם הזה במה היו מתפרנסים בניהם בכל דור ודור ובגליות. ואומרו **ולשומרי מצותי** פירושו רבותינו ז''ל (סוטה ל''א.) שאינה נמשכת עם לאלפים כי אלו שהם עובדים מיראה אם יצטרכו הדורות לזכותו לא יאריך אלא עד אלף כמו שמפורש בפסוק אחר דכתיב (דברים ז ט) לאלף דור וגו':
@526 **לא תשא וגו'**. פי' לצד כי השבועה תגיד גדולות ונשיאות לה' יחשוב אדם כי ישבע בשמו יתברך לכבוד ולתפארת כי הוא זה רבונו ושליטו הגם שיהיה לשוא מה בכך אם הנשבע לו לא יכיר בשקרו כי אם ידע שהוא אדונו של זה והוא באופן שלא יתגלה ההפך, לזה אמר **לא תשא** אפילו יש נשיאות לשם שאתה נשבע בו, **כי לא ינקה ה'** הגם שתהיה כונתו לשאת את שמו, כיון שהוא לשוא:
@526 **עוד** ירצה כי באמצעות שבועת שוא הוא נושא מעליו שם ה' הנקרא עליו ומתלבש בבחינת הרע המתיחסת בשם שוא כי שם ה' אמת והמזכירו בשקר פורח ממנו בחינת השם לסיבת בוחרו בשוא, וזה הוא שיעור הכתוב **לא תשא** מעליך **שם ה' אלהיך** לסיבת שוא, ואמר **כי לא ינקה ה'** לעושי כן:
@526 **עוד** ירמוז שלא יהיה נושא עליו שם ה' שהוא אלוהו ואומר לכל שהוא איש יהודי ועובד ה', והוא אומרו **שם ה'** שהוא **אלהיך** ולבבו לא כן יחשוב, והוא אומרו **לשוא**, ואזהרה זו שלא ירמה ברוך הוא לומר כי הוא מעבדיו ולא כן הוא. ובכלל אזהרה זו שלא יראה על עצמו שהוא צדיק יותר ממה שהוא:
@527 **זכור את יום השבת וגו'**. פירוש שיזכרהו מיום א', ולזה הקדים המאוחר כי מן הראוי היה להקדים לומר ששת ימים וגו' ואחר כך יאמר זכור, אלא נתכוין לומר שהזכירה תהיה מיום ראשון על דרך אומרם ז''ל (מכילתא) שכל יום יאמר היום יום א' בשבת וכו' פירוש ובזה יקדשו ולא יטעה בו. גם ירצה **לקדשו** לשון הזמנה על דרך אומרם ז''ל (ביצה ט''ז) מחד בשבא לשבא, גם ירצה על דרך אומרם ז''ל (מדרש תהלים פצ''ב) כי יום ששי שבו נברא אדם הראשון וחטא ויצא חייב בדינו בא יום שבת ונעשה סניגור לאדם לפני ה' ואמר רבון העולם לא נהרג אדם מעולם וכי אני מתחיל וכו' וניצול אדם וכשראה אדם כחה של שבת התחיל לשורר מזמור שיר ליום השבת, לזה אמר ה' **זכור** פירוש שיזכור את יום השבת אשר באמצעותו נתקיים אדם ויוצאי חלציו וראוי להחשיבו כי הוא דבר המעמיד לכל איש ישראל ויקדשו. ותמצא כי מי שנעשה לו נם ביום אחד יהיה היום ההוא מכובד וחשוב בעיניו תמיד מדי שנה בשנה, וזה יותר על בחינה זו שהשבת עצמו הוא המציל, ולזה אמר **זכור** להיות הדבר רחוק מששת ימי בראשית. עוד ירצה על זה הדרך **זכור את יום השבת** פירוש הזכיר שמו של שבת והטעם **לקדשו** כי כשאתה מזכיר שמו של שבת ביום זה בזה אתה מקדשו, וזה הוא שיעור הכתוב **זכור את יום**, ומה יזכור, שבת; וטעם **לקדשו** כי שמו של הקדוש ברוך הוא שבת כמאמר רשב''י (זהר ח''ב פ''ח:), ואח''כ ביאר הכתוב מה יום מימים ואמר **ששת ימים** וגו' **כי ששת ימים** וגו' הא למדת כי על יום ז' של ששת ימי בראשית הוא אומר:
@528 **ששת ימים תעבוד וגו'**. צריך לדעת לאיזה ענין יצו ה' לעבוד בששת ימים. גם מה היא כוונתו באומרו **ועשית** וגו'. ונראה כי יכוין על דרך מאמר הכתוב בפרשת בהר סיני (ויקרא כ''ה כ') וכי תאמרו מה נאכל בשנה השביעית וגו' וצויתי וגו', והם הדברים הנאמרים כאן לפי מה שקדם לומר זכור את יום השבת לקדשו שאין בו דברי חול אם כן העושה ואוכל דבר יום ביומו מה יאכל ביום המקודש, לזה אמר **ששת ימים** לבד **תעבוד** ובהם תעשה **כל מלאכתך** פירוש הצריכה לך לששי ולשביעי על דרך אומרו (שם) ועשת את התבואה לשלש וגו' כי מבטיח ה' לשומרי מצותיו. עוד ירצה לצוות לבל יחשוב במלאכת חול בשבת, והוא אומרו **ששת ימים** וגו' ויהיה בעיניך כאלו עשית כבר כל מלאכתך שיש לך לעשות, והוא על דרך אומרם ז''ל (מכילתא) שבות כאלו מלאכתך עשויה, שזולת זה יחשוב מחשבות לכונן מלאכתו ואשר יחסר מהמלאכה לעשותה בחול, וצא ולמד ממעשה החסיד (שבת ק''נ:) שקנס עצמו על אשר חשב לגדור גדר נפרץ בשבת לבל יבנהו עוד וכו':
@529 **ויום השביעי וגו'**. פירוש כי בעשותו שבת לה' בזה אתה עושה ה' כי הוא אלהיך על דרך אומרם ז''ל (שמו''ר פכ''ה) כי שקול שבת ככל התורה כולה. ואולי כי רמוזה היא כל התורה בתיבת שבת על זה הדרך תרי''א הם מצות שלא שמעום מפי הגבורה אלא מפי נביא וב' מצות אנכי ולא יהיה לך שהם ב' מצות שנצטוו מפי הגבורה מצות אנכי היא מצות עשה ולא יהיה לך היא מצות לא תעשה, וכבר הודיעונו רבותינו ז''ל כי מצות עשה יתכנו לשם הרחמים לפי שהם בבחינת קבלת שכר ומצות לא תעשה יתכנו לשם אדני לפי שהם בבחינת הדין לעובר עליהם, והנה חשבון הוי''ה אדנ''י עולה צ''א ותרי''א הרי שבת:
@529 **עוד** ירצה על דרך אומרם במס' שבת (קי''ח:) כל השומר שבת כהלכתו אפי' עובד עבודה זרה כאנוש מוחלין לו, והוא אומרו **ויום השביעי שבת** לה' בזה נעשה הוא **אלהיך** ולא זולתו הא למדת שנמחל לו מה שקבל לאלוה זולתו יתברך:
@529 **עוד** ירצה באומרו **שבת לה'** כי לא תהיה המנוחה והשביתה למנוחתו ולמרגועו אלא למצות ה' אלהיו:
@529 **עוד** ירצה על זה הדרך **ששת ימים תעבוד** וגו' **ויום השביעי** גם כן יהיה לך מלאכה אחת ומה היא שאתה עושה שבת לה' אלהיך ולא מיעטתי לך יום השביעי אלא ממלאכתך של עצמך:
@530 **וינח ביום השביעי**. כאן נתחכם ה' לאסור מלאכות אשר מנו חכמים מ' מלאכות [ח''א] שיש בהם מלאכה שאין בה שום טורח כלל בעשייתה כמו שתאמר המוציא כלי מרשות היחיד לרשות הרבים או להפך וכדומה לזה רבים וחייבה התורה מיתה עליהם, ויאמר אדם מה טורח יש בדבר זה להתחייב לזה אמר הכתוב **כי ששת ימים** וגו' **וינח** וגו' פירוש ודוק והשכיל בטעם ותדע כי אין הדבר לצד הטורח לבד והרי מי שנאמר בו (ישעי' מ') לא ייעף ולא ייגע ובו לא יוצדק לומר מנוחה אלא הכוונה היא לצד הפעולה היוצאת אנו דנים הגם שלא תהיה בה יגיעה וטורח, ולזה כל ששם מלאכה עליה הגם כי יעשנה אדם בלא הרגשת דבר הרי זה חייב עליה:
@530 **עוד** ירצה על זה הדרך **כי ששת ימים עשה ה'** וגו' פירוש כי לא עשה בתכונת בריאתם שיעמדו אלא ששת ימים, ומעתה יצטרך ה' לחדש הבריאה בכל יום ובאמצעות נפש העולם שהוא השבת שברא ה' נח מהתמדת המלאכה, וכמאמרם ז''ל (ב''ר פ''י) שהיה העולם רופף ורועד ובבא שבת עמד בקיומו, והוא אומרו **וינח ביום הז'** ויום זה מעמיד העולם עוד ששת ימים ובכל יום ששי לערב שכלתה תכונת העולם יבא שבת ויקיים העולם עוד ששת ימים אחרים וכן על זה הדרך, ועיין פרשת בראשית (ב' ב'):
@531 **למען יאריכון**. אמר **יאריכון** שמשמע מעצמם ולא אמר אאריך ימיך. אולי שירצה לומר כי מצוה זו סגולתה היא אריכות ימים מלבד שכרה מה', כי יש מצות שיש בהם סגולות נפלאות מלבד שכר אשר קבע להם ה' וזו גילה אותה ה':
@535 **דבר וגו'**. פירוש ואם לצד כי כשידבר ה' עמנו נקבל גזירותיו, מעתה הרי אנו מקבלין ממך ואם כן אין צורך בדבר ולמה נסתכן והוא אומרו **פן נמות**. עוד ירצה על זה הדרך **דבר אתה עמנו ונשמעה** פירוש יהיה כח בנו לשמוע אבל אם ידבר ה' עמנו פן נמות ולא נשמע:
@536 **אל תיראו**. פירוש שידבר עמכם עוד **כי לבעבור** וגו' וכבר עשה ה' מחשבתו הטובה ועשה אתכם נס שהם מובדלים לטובה כי פסקה זוהמתם באמצעות דבר האלהים, וגם טעם ב' **בעבור תהיה** וגו' פירוש כי בעקירת הזוהמא מהם הנה קנתה היראה שהיא שכינתו יתברך מקום להיות בתמידות על פניהם כי צלם אלהי אשר יצר ה' את האדם בצלמו חזר לקדמותו, והרווחת ב' דברים אלו הוא לבלתי תחטאו כי כל מי שיש לו בושת פנים שהיא יראתו האמורה לא במהרה הוא חוטא. עוד ירצה באומרו **לבעבור נסות אתכם** כדי שלא תהיה לכם טענה למה לא ינבא ה' את כל ישראל, הרי ניסה אותם בנבואה ולא יכלו עמוד:
@539 **לא תעשון אתי וגו'**. צריך לדעת אומרו תיבת **אתי**. ורבותינו ז''ל (מכילתא) דרשו שלא יעשו הכרובים ד', והוא אומרו **אלהי זהב** שמעלה עליהם כאלו עשו אלהי זהב, ולא יעשו הב' של כסף ואם עשו מעלה עליהם וכו', גם שלא יעשו צורה לדמיון ה' להשתחוות לה (ר''ה כ''ד.) וכוונתם לה' ולא צורת שמשים של ה'. ונראה לפרש הכתוב בדקדוק עוד למה חזר לומר פעם ב' **לא תעשו לכם** ולא הספיק במה שקדם לומר לא תעשון אתי וגו'. עוד למה דקדק לומר תיבת **לכם**:
@539 **אכן** יכוין ה' לצוות על ב' מיני עבודות אל אחר, האחד הוא העובד באמונת לבו כי מאמין בה וכוסף לעובדה, וכנגדה אמר **לא תעשו** ן **אתי אלהי כסף** פירוש אלהי בכוסף וזה יורה על העובד מאמונת לבו. ודקדק לומר **אתי** כי העובד עבודה זרה ברצון נפשו הוא ממשיך בשורש נפשו בחינת הרע שבשורש העון ההוא והוא סוד (איכה ר' פ''א) נחש המקנן במגדל, כי כבר הודיענו הכתוב כי נפשות ישראל חלק אלוה ממעל דכתיב (דברים לב ט) חלק ה' עמו ובעובדו לעבודה זרה באמונת נפשו נותן מקום לס''מ ליכנס במקום שורש הנפש ההיא שהוא מקום הקדושה, והוא שאמר שלמה (משלי ל) תחת עבד כי ימלוך, והוא אומרו **לא תעשון אתי**, ואמר **אלהי כסף** פירוש לשון כוסף שהוא עובדו מכוספו בו רחמנא ליצלן. והב' היודע בלבו אמונה שלימה כי הכל הוא צואה בלי מקום אבל עובדה לסיבת הנאה להנאת המועיל כמו שתאמר שיתנו לו ממון על מנת לעובדה, ויאמר האדם בלבו רחמנא לבא בעי ובלבי אני מחרף ומגדף בעבודה זרה זו ואין מעשי אלא לתכלית הריוח, וכנגד זה אמר **ואלהי זהב לא תעשו לכם** פירוש הגם שאין לבו ונפשו מאמינים בה דבר אלא לצד שזה אהב הזהב ובשביל הנאת זהבו הוא משתחוה אף על פי כן לא תעשו, וגילה שחטא זה הוא דוקא בבחינת האדם שהוא פוגם עצמו וממעיט דיוקנו, והוא אומרו **לכם** לצד שלא חטא אלא במעשה והמחשבה מנגדת כגלוי לפני יודע תעלומות, לזה לא יעשה החטא סיבה שתכניע בחינת הרע את בחינת הטוב כמעשה הראשון:
@539 **חסלת פרשת יתרו**
@543 **ואלה המשפטים**. צריך לדעת טעם אומרו **ואלה** והנה נחלקו במכילתא רבי ישמעאל ורבי עקיבא רבי ישמעאל אומר לומר לך מה עליונים מסיני אף תחתונים מסיני רבי עקיבא אומר ואלה יכול שונין ולא יודעים תלמוד לומר ואלה וגו' ערכן לפניהם כשולחן הערוך עד כאן. והנה לרבי ישמעאל שמפרש ואלה שבא לומר שנאמרו בסיני בהכרח לפרש שטעם שהוצרך הכתוב להודיע זה הוא ללמד על פרטי מצוה זו שנאמרו מסיני, שאם על כללותיה הרי אמר רבי ישמעאל בפרק בתרא דזבחים (קט''ו:) שכל המצות נאמרו כללותיהם בסיני ופרטיהם באוהל מועד עד כאן, ואם כן גם אלה המשפטים בכלל ולא היה צריך לומר ואלה ללמד על דבר זה. ולרבי עקיבא שחלק עם ר' ישמעאל שם בבריתא השנויה בזבחים כי כל המצות נאמרו כללותיהם ופרטיהן בסיני אינו יכול לפרש ואלה המשפטים שבא ללמד שנאמרו בסיני כי אינו צריך להשמיענו זה והוצרך לפרש באופן אחר. וצריך עיון לדברי רש''י שפירש כאן כסברת רבי ישמעאל ובפרשת בהר סיני פירש כרבי עקיבא שאמר מה שמיטה נאמרו כללותיה ופרטותיה בסיני אף כל התורה כולה וכו', והם ב' פירושים חלוקים, והיה לו לפרש כאן ואלה המשפטים מוסיף על ענין ראשון מה שצוה בענין שני שצריך לשום לפניהם כשלחן הערוך בין משפטים תחתונים בין משפטים שקדמו להם:
@543 **ומה** שראיתי שכתב הרא''ם שלימוד רבי ישמעאל הוא שנאמרו המשפטים בקולות וברקים, אין דבריו נראים ולא מתקבלים לומר כי דיבר ה' יותר מעשרת הדברות הגם שהיה ר' ישמעאל אומר בפירוש כן היה צריך כח וראיה לדבריו ומכל שכן שלא אמר רבי ישמעאל אלא מה עליונים מסיני ולא אמר מה עליונים בקולות וברקים, ודברים אלו אין לשמוע להם, ואם מחמת הקושיא שהקשינו, כבר ישבנו אותה ישוב נכון שבא הכתוב על הדקדוקים כמו שבא בדין השמיטה שאמר הכתוב בהר סיני, ובהכרח לר' ישמעאל שיודה בשמיטה שנאמרו כללותיה ופרטיה בסיני כמבואר בתורה בפירוש, אלא שלא סבר ללמוד ממנה לכל התורה כולה, ואולי כי טעמו ממה שבאה הזכרת הר סיני בד' מצות לא רצה ללמוד מהם על כל התורה, והעיקר כמו שכתבנו. ויותר נכון להניח הדבר בצריך עיון לדברי רש''י מלפרש בו כי הבין בדברי רבי ישמעאל שאמר ה' אלה המשפטים כדרך שאמר עשרת הדברים, ואם כונת הרב רא''ם לומר שנאמרו בקולות לבד ולא כסדר עשרת הדברות, גם זה אינו כי זה יהיה בנין ג' בסדר הדבור, הא' הוא סדר אשר דיבר ה' בו עשרת הדברות, ב' סדר שהיה רגיל לדבר עמו כל המ' יום כל מצות התורה, ג' סדר דבור אלה המשפטים, ומי יטה אזנו לשמוע דברים אלו לבנות מציאות שלא מצינו לו כיוצא בו בתורה, ועוד יש להקשות אלא שהדברים פשוטים. עוד נראה לומר כי טעם אומרו **ואלה** לרמוז דבריהם ז''ל (סנהדרין פ''ו:) כי צריך לשום דיינים לפני המקדש, לזה אמר **ואלה** מוסיף על ענין ראשון שהזכיר בסמוך מקום שכונת הקודש שכולם במקום אחד:
@543 **אשר תשים לפניהם**. טעם אומרו בלשון זה, הגם שרבותינו ז''ל דרשו דרשות (שם ז') צריך לדעת פשטן של דברים. ואולי כי להיות שיש חלקים בתורה שהם חובת גברא לדעת את אשר יעבודו וזולת זה אינם בני ברית התורה, המשל בזה אם לא ידע שאסור לאכול טריפה הרי הוא אוכלה וכן הדם וחלב, ובמצות עשה פסח מצה ומרור שביתת ימים המקודשים הן אלה יתחייב לדעתם, ויש בחינה אחרת כמו שתאמר דיני טוען ונטען הלכות קידוש החודש הלכות קרבנות וכדומה, האמת כי חובת ידיעת התורה לכל איש ישראל אבל לא יגרע מצדיק עינו אם יחסר ידיעתם כל שיש בישראל גדולים שישפטו ויקדשו ויורו משפטים לישראל, ונתחכם ה' לומר כאן **אשר תשים לפניהם** לומר כי דינים אלו יתחייבו בשמיעתם כל איש ישראל שזולת זה אין הקונה מכיר בשעת הקנין לדעת את אשר יקנה, וגם אין הנקנה יודע כי ה' שחררו אחר שש שנים לתבוע התובע, וגם השופטים לא ידעו כל קונה עבד להודיעו כי חייב לשלחו, ולזה אמר **אשר תשים לפניהם** כי משפט זה הוא מהמשפטים אשר צריכין לשום לפני כולם, ולזה תמצא שדבר הכתוב בדרך נוכח **כי תקנה** וגו' כי יודיע הדבר לכל קונה:
@543 **עוד** ירצה להסביר המצות שתתקבל לכל, ולזה אמר **אשר תשים לפניהם** פירוש הגם כי דבר זה יש בו חסרון הרצון שהקונה עבדו ימהר לשלחו אחר ו' שנים תשים הדברים לפניהם כי מצוה זו לזכות כל אחד מהם היא כשיהיה עבד לא יעבוד בו לעולם ובזה יתרצה בדבר, כי כל אחד יעריך הדבר שהוא לזכותו לצד כי כל עברי הנמכר אינו אלא לצד דוחקו או גנב ומכרוהו בית דין וזה יסובבו העוני ובאותו מצב כולם עשירים היו ואין זה אלא לדבר המתגלגל וכל אחד ישים לפניו שאליו נוגע החסד דלמא יתגלגל עליו הגלגל וזה זכות הוא לו:
@544 **כי תקנה עבד עברי**. אולי שיכוין לומר שאם יהיה לפניו לקנות עבד כנעני ועבד עברי יקדים העברי, וזה שיעור הכתוב כי תרצה לקנות עבד תקדים לקנות עברי ולא תאמר אקנה עבד שאעבוד בו עד עולם ולא אקנה עבד שאחר שש שנים אשלחנו. וטעם שקראו **עברי** כי חש הכתוב ליחס שם עבדות על ישראל, לזה כינה אותו בשם זה. עוד רמז כי שם עבדות על ישראל הוא עובר ואינו קבוע מטעם כי לה' הם עבדים ויצא מתחת ידו בשנה הז'. עוד ירמוז שלא בא לידי מדה זו עד שעבר על התורה ומצות, ומכוון לדבריהם ז''ל (קידושין י''ד:) כי במכרוהו בית דין בגניבתו הכתוב מדבר, וגם במוכר עצמו מחמת דוחקו שמצינו שאמר הכתוב (דברים טו יב) כי ימכר לך אחיך העברי, גם הוא לא בא לידי זו עד שכבר קדמו לו עבירות, וכמאמר ר' אמי (שבת נ''ה.) אין יסורין בלא עון. עוד דקדק לומר **כי תקנה עבד עברי** ולא אמר עברי עבד, לרמוז כי קודם שתקנהו עבד הוא, וכאומרם ז''ל (קידושין שם) כי במוכרים אותו בית דין הכתוב מדבר וכבר נתחייב מהשמים. ובזה לא קשיא למה הוצרך לומר תיבת עבד שמזה יצא לנו לטעות עבד של עברי (מכילתא) עד שהוצרך לפרש פסוק אחר תלמוד לומר כי ימכר לך אחיך העברי:
@544 **עוד** נראה כי טעם שהוצרך לומר עבד לתת טעם למה שצוה שש שנים לזה הקדים לומר כי זה שאתה קונה כבר הוא עבד על דרך שאמר (ויקרא כה נה) כי לי בני ישראל עבדים:
@544 **שש שנים יעבוד**. טעם אומר כן לדרוש שעל כל פנים יעבוד שש ואפילו ברח, ואומרו **יעבוד** ולא פירש יעבדך נתכוון לרבות שיעבוד גם במות הקונה לבנו:
@544 **ובשביעית וגו'**. פירוש ולפעמים יעבוד גם בשביעית כשימכר באמצע שנת עולם לתשלום שנה שנמכר בה כדי שיהיו שש שנים שלמים מיום ליום. עוד ירצה כי יעבוד גם בשביעית פירוש שביעית לשנים אם תפגע בתוך שש שניו. שוב מצאתי דיוק זה בדברי רמב''ם בפירוש המשנה (קידושין פ''א מ''ב):
@545 **אם בגפו יבא וגו'**. רבותינו ז''ל בקידושין (כ'.) אמרו יחידי נכנם יחידי יצא מכאן שאין רבו רשאי למסור לו שפחה כנענית אלא אם הוא נשוי. ונראה כי הוקשה להם יתור הכתוב למה הוצרך לומר כן ממה נפשך אם לומר כי דווקא כשיכנס בגפו הוא שיצא בגפו אבל כשיכנס עם אשתו לא יצא בגפו פשיטא כי מי הכניסה שצריך לומר כן, ותמצא שדקדקו רבותינו ז''ל (קידושין כ''ב.) במאמר ויצאה אשתו כי לא היה צריך לאומרה ופירשוה לחייב מזון אשתו ובניו, ואם על שפחה הנותן לו רבו איגו צריך הרי הוא אומר בסמוך האשה וילדיה תהיה לאדוניה והוא יצא בגפו, אלא ודאי לדרשה בא לומר אם בגפו פירוש בלא אשה ישראלית ממה שגילה בסוף דבריו אם בעל אשה וגו', **בגפו יצא** פירוש יחידי יצא פירוש ישאר בכמות שהוא יחידי עד יציאתו. או על זה הדרך מקיש יציאה להכנסה כשם שכשנכנס נכנס יחידי ממש בלא אשה ובנים בין היוצאים עמו בין הנשארים בבית האדון כמו כן ביציאתו. ואם היתה לו אשה ולא היו לו בנים גם כן אין רבו מוסר לו שפחה שאנו קוראים בו בגפו, ואין צריך לומר היו לו בנים ולא היתה לו אשה:
@545 **וראיתי** להרא''ם שדייק שהיה לו לומר אם בגפו וגו' כן יצא. ואין דבריו נראים כי אדרבה אם היה אומר כן יהיה נשמע יותר שלא יתן לו שפחה וישאר כמות שהוא. והאמת כי טעם שלא אמר כן כי יש לחוש לדרשות אחרים הנשמעים ממנה והמשכיל יבין. ואם תאמר מנין להם לרבותינו ז''ל (שם כ'.) שהוסיפו הבנים, והגם כי דברים אלו הלכה הם, יש לומר כי אם יכנס באשה בלא בנים הרי אני קורא עליו בגפו יצא שלא יתן לו שפחה ויהיו לו בנים ממנה שאז אינו דומה גפו של יציאה לגפו של הכנסה כי אז לא היו לו בנים ועתה יש לו בנים. ואם בשעה שנכנס היתה לו אשה ולא בנים ואחר כך היו לו בנים נכנס בגדר היתר. ואולי כי לזה תלתה התורה הדבר באשה שהיא צריכה להיות בשעת ביאתו לעבדות אבל הבנים הגם שיהיו אחר כך. ואם היתה לו אשה כשקנאו ומתה משמע שמותר כי לא הקפיד הכתוב אלא על שעת ביאה בגפו יבא. וזולת דבריהם ז''ל הייתי אומר כי הכתוב שלל דין זה מאומרו אם בעל אשה הוא צריך שתהיה אשתו עמו עד שעת יציאה ובזה אני מתיר לך אם אדוניו יתן לו אשה:
@545 **אם בעל אשה וגו'**. פירוש על דרך אומרם ז''ל (מכילתא אחריתי דר''ש) שאין האדון חייב במזונות אשתו של עבד אלא אם תהיה אשה הראויה לו לעמוד עמו ולא אשה האסורה לו מאיסורי לאוין, והנה בדין מסירת שפחה כנענית משמע מהש''ס והובא בדברי רמב''ם (הל' עבדים פ''ג ה''ד) שכל שיש לו אשה ובנים ואפילו האשה מאיסורי לאוין יכול ליתן לו וכו', והוא אומרו **אם בעל אשה הוא** פירוש אין צריך שתהיה אשתו הראויה לו לגבי מה שאסרתי לך בסמוך אם בגפו שאין רבו מוסר לו אבל לגבי מזונות **ויצאה אשתו** פירוש הראויה לו הוא שחייב האדון במזונותיה:
@545 **עוד** יתבאר על דרך אומרם ז''ל (מכילתא) וזה לשונם יכול יהיה חייב במזונות ארוסה ושומרת יבם תלמוד לומר אשתו להוציא שומרת יבם, עמו להוציא ארוסתו. והנה עבד שהיתה לו אשה שומרת יבם או ארוסה מותר לתת לו שפחה כנענית, והוא אומרו **אם בעל אשה הוא** פירוש בלא תנאי הגם שתהיה ארוסה או שומרת יבם יצא מכלל בגפו שאסרתי לך נתינת שפחה. ולדברי הש''ס (קידושין כ'.) שדקדקו הבנים גם כן יהיה הדין בהיכא שהיו לו בנים מאשה אחרת ומתה וארם אשה ישנו במסירת שפחה:
@545 **ויצאה**. אומרו בתוספת וא''ו כי לצד שיצו ה' על מזונות האשה יוצדק לומר וא''ו כי מלבד שחייב במזונותיו גם כו':
@546 **אם אדוניו וגו'**. קשה למה התחיל לדבר לנוכח כי תקנה ותוך כדי דבור חזר לדבר דרך נסתר אם אדוניו יתן לו, תהיה לאדוניה, והגישו אדוניו, כל הפרשה בדרך נסתר ומן הראוי היה לו להשלים הדבור כדרך שהתחיל אם תתן לו, תהיה לך וגו', והגשת אותו. והיה נראה לומר כי לא כינה הזווג לקונהו על דרך אומרם ז''ל (ב''ר פס''ח) כי הקב''ה מזווג זיווגים לזה אמר **אם אדוניו** האמיתי כי לו בני ישראל עבדים יתן לו אשה, אלא שלא יצדיק פירוש זה אומרו האשה וילדיה תהיה לאדוניה. עוד צריך לדעת למה הוצרך לומר **והוא יצא בגפו** והלא הדבר מובן שיצא בגפו מאומרו האשה וילדיה תהיה לאדוניה. עוד צריך לדעת למה כפל לומר **אמר יאמר**:
@546 **אכן** כוונת הכתובים הוא לצד כי יצו האל השתנות הדין אם בגפו יבא בגפו יצא פירוש שאין רבו יכול למסור לו שפחה כנענית אלא אם היה נשוי כאומרם בקידושין (כ'.) ויאמר האומר מדוע חקק ה' חוקה זו להשתנות הדין מה לי היה נשוי או לא, לזה בא הכתוב בחכמה לתת טעם ואמר הטעם הוא **אם אדוניו יתן לו אשה** שהיא שפחה כנענית כמובן מהענין המשפט הוא שהאשה וילדיה תהיה לאדוניה והוא העבד יצא בגפו פירוש בלא אשה כל עיקר ולהיות כן אם יתן לו רבו אשה והוא פנוי מעולם לא ירצה לצאת מעבדות לצד ב' סיבות, האחד אהבת אשתו ובניו, והב' שבצאתו נשאר פנוי ושתים רעות יש לו ביציאתו ולצד זה כל עבד איש לא יחפוץ לצאת מאת רבו מה שאין רצונו יתברך כן, אשר על כן גזר אומר שלא יתן לו רבו אשה אלא אם הוא נשוי כי בזה יקל מעליו הפרדת אשתו ובניו כיון שיש לו אשה ישראלית בת חורין יהיה בעיניו קל לצאת, וכפי פסוק אם אדוניו וגו' נתכוון ה' לומר בסדר הדברים לתת טעם במתק לשון למה שינה הדין, ואומרו **ואם אמר יאמר** פירוש מלבד אמירה א' שעשה ה' לו תיקון כנזכר עוד יאמר **אהבתי** וגו' **והגישו** וגו' **ורצע** וגו' כי זה מעיד שאינו חושש לעולו ית' וקונה אדון לעצמו:
@546 **עוד** נראה לפרש הפרשה דרך רמז כי תצוה התורה להאדם לשום לפניו בתמידות כל הדברים האלה בין עיניו והוא אומרו **אשר תשים לפניהם** שתמיד ישים האדם ענין זה לפניו. והוא **כי תקנה עבד עברי** הלא ידעת כי האדם נחלק לשנים חלק אחד רוחני והוא העיקר וחלק אחד גשמי שברא ה' לנשמה לשמשה שבאמצעותו מקיים כמה מצות אשר צוה ה' ולו יקרא שם עבד כי אינו אלא שמש לנפש שבשבילה יקרא אדם כמו שאמר הכתוב (לקמן ל') על בשר אדם לא וגו' שזה יגיד כי לא הבשר יקרא אדם, וכן אמר (יחזקאל ל''ד) אדם אתם אתם קרויים אדם ולא אומות העולם (ב''מ קי''ד.) שאין להם נפש רוחנית, ולזה תצוה התורה להאדם **כי תקנה עבד עברי** פירוש עברי עובר כי אינו קיים לעד כי מי גבר יחיה ולא יראה מות על דרך (תהלים קמד) כצל עובר, וזמן קביעתו הוא עד ס' שנה על דרך אומרו (איוב ה') תבא בכלח אלי קבר, ואמרו בש''ם (מוע''ק כ''ח.) כי בן ס' שנה הוא זמנו של אדם ללכת כחושבן בכלח שאז הוא כעלות גדיש, וזה הוא אומרו **שש שנים** פירוש כל ימיו הם ששים, והגם שאמר שש יש חשבון שיכלול כללות א' וכאן כולל העשירי, **ובשביעית** פירוש בעשר שנים השביעית יצא לחפשי העבד על דרך אומרו (תהלים פ''ח) במתים חפשי, ואומרו תיבת **חנם** לרמוז על יד מי תהיה היציאה על ידי חנם שהוא ס''מ וחילותיו שהם נרמזים בתיבת חנם כאומרם בספר הזוהר הקדוש (ח''ב קכ''ח.) כי במילי דמגנא הוא זינייהו דההיא סטרא ולזה לא שלטי בדבר מצוה שעושה האדם בדמים יקרים, וכן תמצא שכל דבר טומאה בא בחנם מה שאין כן דבר מצוה וקדושה צריך להם טורח גדול ודמים יקרים:
@546 **ואומרו אם בגפו יבא** צריך לדקדק למה אמר לשון זה ולא אמר לשון הרגיל בלשון הקודש אם לבדו כאומרו (וישלח לב כה) ויותר יעקב לבדו:
@546 **אכן** יש לדעת כי אם סיגל מצות ומעשים טובים וקנה לעצמו כח ימצא כח לעלות ביום התחייה על דרך אומרו (תהילים עב) ויציצו מעיר כעשב הארץ (כתובות קי''א.) וזהו שאמר כאן **אם בגפו** פירוש לשון גף על דרך אומרו (משלי ט') על גפי מרומי שרומז אל המצות ומעשים טובים כאומרם ז''ל (שבת מ''ט.) נמשלו ישראל ליונה וכו', ואומרו **יבא** פירוש על דרך אומרו (אונקלוס בראשית כח כא) כי בא השמש עאל שמשא, **בגפו יצא** פירוש באותו כנף יצא מן הארץ בעת התחייה ואחרי נפלו קימה תהיה לו וידיעת ההפכי' שוה היא שאם בעולם הזה לא ישתדל בסגל הטוב אין כח בו לעלות, והוא מאמרם ז''ל (כתובות קי''א:) בפסוק (משלי ג) עץ חיים וגו' שאין גופות עמי הארץ עומדים זולת למחזיקים בה:
@546 **ואומרו אם בעל אשה הוא ויצאה אשתו עמו** כאן רמזה התורה סוד גדול והוא כי יש לך אדם שקנה נשמתו באמצעות חוזק מעשיו הטובים ונעשה הוא בעלה של נשמה הקדושה, וצריך אתה לדעת מה שאמרו בספר הזוהר (ח''ג צ''א,) במה שאמר הכתוב שור או כשב או עז כי יולד וגו' כי הבהמות מעת לידתם קונים שכל שיש לשור מה שאין כן האדם כפי מעשיו זכה נותנים לו נפש זכה יתיר וכו' זכה יתיר וכו' עד כאן, הנה שבאמצעות מעשיו קונה הנשמה הנקראת אשה וכמו כן מצינו שקראוה חכמי אמת (תקו''ז תיקון ו') ולזה אמר **אם בעל אשה** הוא שקנאה כנזכר **ויצאה אשתו** פירוש אפילו אחר יציאת אשתו אף על פי כן עודנה עמו ונשאר חי אפילו אחר מותו, וצא ולמד ממעשה שהובא במסכת שבת (קנ''ב:) של הנהו קפולאי וכו' נחר בהו גברא וכו' שהיה מדבר לאחר מותו, וזה הוא אומרם ז''ל (ברכות י''ח.) צדיקים במיתתן קרויים חיים:
@546 **עוד** יכוין באומרו **אם בעל אשה הוא** לומר אם הוא אדם אשר כל מחשבותיו ויגיעותיו וטרחו בעולם הזה ואפילו מאכלו ומשקהו אינו אלא בשביל הנשמה על דרך אומרו (משלי יג) צדיק אוכל לשובע נפשו להגדיל הרוחניות אדם כזה לו יקרא בעל אשה כבעל הזה שטורח בשביל אשתו לזון ולפרנם ולכלכל ולמלאות רצונה כן זה האיש עושה לנפשו אדם כזה שהחומר נזדכך ונעשה מעין הצורה במציאות זה תוכל נפשו לסבול לדור עמו במחיצתו אפילו אחר יציאתה:
@546 **ואומרו אם אדוניו יתן לו אשה** וגו'. פירוש אם אינו בעל אשה על אופן האמור אבל אשה הקנו לו מן השמים כי תמצא כמה בני אדם שזוכים לנשמה טהורה בסוד הזיווג בשעת יצירה מצד אביו הצדיק, וילדה לו בנים או בנות פירושו על דרך אומרם (ב''ר פ''ל) עיקר תולדותיהם של צדיקים וכו', גם כי על ידי מעשים טובים יהיה נולד מלאך טוב כאומרם ז''ל (אבות פ''ד) העושה מצוה אחת קנה לו פרקליט אחד כו', וכן הוא מפורש באר היטב בספר הזהר הקדוש לזה אמר וילדה לו בנים או בנות בחינת הבנים הם מצות הנעשים בהתעצמות גדול, ובחינת הבנות היא מדרגה למטה מבנים, אדם כזה האשה וילדיה תהיה לאדוניה לשלול מה שזכה האיש אשר קנה האשה באמצעות התעצמותו ונעשה בעל האשה להיות עמו תמיד לא כן הוא זה אלא תהיה לאדוניה כי אדם כזה לא קנאה להיות בעלה שבזה לא תפרד ממנו. גם לפירוש ב' זה לא זיכך גופו כדי שיהיה ראוי שלא תפרד ממנו הנשמה ולזה תהיה לאדוניה, והוא יצא וגו' פירוש ובעת יציאתו מהקבר בעת התחייה יצא בגפו פירוש זכיותיו שיש לו ולא תושלל ממנו התחיה בהעדר הדבר האמור:
@546 **ואומרו** ואם אמר יאמר העבד וגו'. כאן הודיע הכתוב עבודת העבד ישראל המתלהב לעבודת קונו ואף אחר שאפסו כוחותיו מתאוה תאוה לעבוד האדון, וזהו אומרו **אהבתי את אדוני את אשתי ואת בני** שהם הנשמה והמצות שעושה בעולם הזה ואינו רוצה לצאת מהעולם הזה לחפשי כמתים וזה יורה על החשק והתאוה בהאדון, לאיש כזה מבטיח האדון כי לו יקרא עבד ה' וימלא תאותו תאות לבו נתת לו אך לא עתה כי עתה אין לו עוד בעולם אלא **ועבדו לעולם** לעולם הבא יבחר בו ה' מהמלאכים להיות לו לעבד נאמן ומצינו שכן היה למשה שקראו ה' (דברים לד ה) עבד ה' שנתאוה לחיות ליכנס לארץ ישראל לעבוד ה' ולקיים מצותיו (סוטה י''ד.) ומה שאמר הכתוב **ורצע** וגו' **במרצע** תמצא בחשבון מרצע ד' מאות עולמות הכיסוף ככתוב בספר הזוהר (ח''א קכ''ג:) ואומרו **ועבדו לעולם** פירוש יחשוב עליו כאילו חי כל ימי עולם ועבד בה עבודת הקודש מחשבה טובה וכו'. עוד רמז **לעולם** סוד ידוע ליודעי דעת קדוש:
@549 **וכי ימכור**. הלביש הדבר במוכר ולא בקונה, לומר כי זו אין מציאות לקנותה אלא מאביה כי אינה נמכרת על ידי עצמה גם אין בית דין מוכרין אותה (מכילתא), ואומרו בתוס' וא''ו לומר כי מלבד רשות הנתונה לו לזכות בקדושיה שהיא נקנית בהם עוד זוכה הוא בה למכרה לאמה:
@549 **איש את בתו**. אמרו ז''ל (מכילתא סוטה כ''ג.) איש להוציא אשה שלא תמכור בתה. ואומרו תיבת **את** תתפרש על דרך אומרם ז''ל (מכילתא) האיש רשאי למכור עצמו ולא האשה. והוא אומרו **וכי ימכור איש** פירוש את עצמו ועוד בתו, ואם היה אומר כי ימכור איש בתו לא היה נשמע אלא מכר בתו ולא כנזכר:
@549 **לאמה**. יתבאר על דרך אומרם במס' קידושין (ד'.) שאפילו הבת איילונית יש לאביה רשות למוכרה. והוא אומרו **לאמה** פירוש הגם שאינה ראויה להנשא כל שראויה לאמה. או ירצה על דרך אומרם ז''ל (תוספתא דבכורים פ''ד) כי הטומטום והאנדרוגינוס לא ימכרו לא ממכרת עבד עברי ולא אמה העבריה. ולזה אמר **לאמה** פירוש אם היא ברורה אמה ולא טומטום ואנדרוגינוס:
@549 **לא תצא כצאת העבדים**. רבותינו ז''ל (קידושין ט''ז.) פירשו כיציאת עבד כנעני בשן ועין עד כאן. וטעמם כי לא יקרא הכתוב עבד סתם אלא לכנעני כי ישראל אין לו שם עבדות סתם. ופשט הכתוב נראה לי שהכוונה היא **לא תצא כצאת העבדים** שאינם יוצאים עד שיעבדו שש שנים ואם מת האב יעבדו לפני הבן אלא מת האדון הרי זו יוצאה לחרות אפילו לא שהתה שש:
@549 **או** יכוין לומר **לא תצא כצאת העבדים** האמורים בסמוך שבשנה הז' יצא אלא שם קנתה מקומה שישאנה האדון (שם י''ד:) ולא תצא אפילו אחר מאה שנה אלא במיתת האדון או בגט ולזה גמר אומר אם רעה וגו', וקשה עד שיזכיר הכתוב יעודיה ואז יוצדק לומר אם רעה אשר לא יעדה. ולדברינו יבא על נכון כי באומרו **לא תצא** שם רמז היעוד ועל זה אמר **אם רעה** וגו' גם לא חש לטעות ששלל זכיות אשר רשם ה' בעבדים שהם יציאת שנת שביעית ושנת היובל, כי ממה שגמר אומר אם רעה וגו' בזה הראה באצבע כי ליעודי הבעל אמר שקנתה מקומה. והוסיף להסיר הטעות במה שאמר הכתוב (דברים טו יב) אחיך העברי או העבריה הרי השוה האמה העבריה לעבד העברי ליתן את האמור בעברי בעבריה. ואין בפירוש זה הכחשה לדברי רבותינו לענין הלכה זולת בישוב הכתוב רשות נתונה לנו מהם למסבר קראי באופן שיהיה לבד מהכחשת ההלכות כי כולן מסיני באו להם, וכאן באה ההלכה כי דין שן ועין אינו אלא בכנעני ולא בישראל, והטעם נראה כי זכות יש לעבד עברי שלא יצא בשן ועין כי חייב לשלם לו אדונו דמי עינו ושינו ושאר הדברים ויעלה ביותר ומה גם כשיהיה הדבר אחר עבור שנים משש שנים של עבודתו ולפעמים יהיה הדבר בסוף, לזה קבע ה' שיטול עבד עברי דמי עינו מה שאין כן עבד כנעני שגופו קנוי לו עשה בו האדון מנהג הותרנות הידועה לבחינת הקדושה, והדברים עתיקין:
@550 **אשר לא יעדה וגו'**. טעם **לא** באל''ף וקרי בוא''ו, יתבאר על דרך אומרם ז''ל (קידושין י''ט.) שאין יעוד אלא לרצונה ודרשוה בקידושין מתיבת יעדה שצריך לרצונה, ולזה כנגד עיכוב הבא ממנו אמר **אם רעה בעיני אדוניה**, וכנגד עיכוב הבא מצדה אם לא תתרצה בדבר אמר **אשר לא יעדה** כי לא היה הדבר מדעתה, אחת מהנה מעכבת. ואומרו **והפדה** פירוש אז הוא שישנה בפדיון ומגרעת מפדיונה אבל זולת זה אם יעדה אין מציאות לצאת כנזכר:
@550 **לעם נכרי**. פירוש הגם שאמרתי לך כי יכול איש למכור בתו לא לעם נכרי יכול למכרה הגם שכבר עשה הדבר ובגד בה ומכרה אין ממכרו ממכר, והוא אומרו **לא ימשול** וגו' **בבגדו** וגו' ופקע זכות קונה ומקנה. עוד ירצה על דרך אומרם (שם י''ט:) שיש לאב למכור בתו לפסולים אלמנה לכהן גדול כו', והוא אומרו **לעם נכרי** פירוש לעם נכרי הוא שלא ימשול אבל איש נכרי לה והוא מעם שאינו נכרי רשאי:
@551 **ואם לבנו**. פירוש לא יעדה הוא ויחפוץ בה לבנו מודיע הכתוב כי יכול ליעדה, והוא אומר **ייעדנה** פירוש בכסף קנייתה בו יהיה יעודיה או לו או לבנו ואין צריך כסף קדושין, ואומרו **כמשפט הבנות** פירוש בין אם יעדה לו או לבנו צריך לעשות כמשפט הבנות שהוא מה שאמר בסמוך שארה וגו':
@553 **ואם שלש אלה**. הם שארה כסותה ועונתה, ולזה דקדק לומר **אלה** ולא הקודמים להם שהם יעוד וגו'. ואמר **ויצאה חנם** פי' פקע זכותם ממנה שאינם יכולים לכובשה עד זמן שש שנים או שאר סימנים אלא או יקיים ג' דברים או יוציאנה בגט, ולזה גמר אומר **אין כסף** לומר כסף הוא שאין אבל גט צריך כי ארוסתו היא. ורבותינו ז''ל (מכילתא) אמרו ג' אלה יעוד לו ולבנו וגרעון כסף ויצאה חנם בהבאת סימנים, ואלו מן ההלכות שנאמרו בהר סיני וסמכום:
@553 **ונראה** לפרש פרשה זו דרך רמז על פי דבריהם שאמרו (סוטה מ''ב:) אין איש סתם אלא הקדוש ברוך הוא דכתיב (לעיל ט''ו ג') ה' איש מלחמה, ואמרו עוד (שהש''ד פ''ג) לא זז ה' מחבב לכנסת ישראל עד שקראה בתו, ומצינו שכינה הכתוב ענין הגלות בשם מכירה דכתיב (ש''א י''ב) וימכור אותם ביד וגו', והנה לפי מה שקדם וצוה הכתוב על הקונה עבד עברי שלא יעבוד אלא שש שנים לזה קובל הכתוב בעד עם בני ישראל למה נשתנה דינו מדין העבדים היוצאים בשש, והוא אומרו **וכי ימכור איש את בתו לאמה** למה תגרע מדין העבדים אשר צוית שש שנים וגו', והוא אומרו **לא תצא כצאת העבדים** בשביעית. ולמה נמכרה בגלות המר הזה זה לנו אלף ותרע''ב ואנחנו לא נושענו ותן לנו משפט עבד עברי הרשום בכתב. וחזר הכתוב וטען **אם רעה** וגו' פירוש אם עודנה במדרגת רשע שבשבילו נמכרה דכתיב (ישעי' נ') הן בעונותיכם נמכרתם וגו', ואומרו **בעיני אדוניה אשר** וגו' פירוש כי הבת היקרה ישנה גם במדרגת כלה כמאמר ספר קודש הקדשים שיר השירים (ד' ח') והוא אומרו **אדוניה אשר לו יעדה** כי אותה יעד לכלה וכתיב באל''ף אשר לא יעדה פירוש הן עתה לא יעדה לצד מעשיה המכוערים, וטען הכתוב על זה **והפדה** פירוש כי לא יוכר לה בחינת הרע בעודה מכורה ובועליה אדונים זרים כי הם ימנעוה מעשות טוב ויכריחוה לעשות רעה בעיני אדוניה ואין תשובת היותה רעה בגלות תשובה עד שתהיה גאולה אז יוכר בה אם רעה אם לא, ומעתה אינו מן הדין שימכרנה לעם נכרי על אשר תהיה רעה בעיניו כל זמן שהוא בוגד בה פירוש כל זמן מכירתה אלא על אשר עשתה בימי שלותה כשלא היה עליה יד מושל נכרי:
@553 **ואומרו ואם לבנו** טען וחזר וטען כי מצינו שהקדוש ברוך הוא קרא לישראל בנים בהכרזה לעיני העמים כולם וידעו כי ישראל הם אומה המיועדת בשם בן לה' והן עתה אם עדיין אומה זו מיועדת לבחינת בנו מן הראוי היה לפחות שלא תהיה גרועה מהאומות כאשר עינינו רואות רום מעלות האומות וישובן מה שאין כן ישראל ומן הראוי לא תהיה גרועה מהם ודי לה השפלה זו שלא יהיה לישראל מדרגה גדולה מהם, והוא אומרו **כמשפט הבנות** כי גם הם יקראו בנות אלא שלא יתכנו במעלה זו ליקראות בתו של הקדוש ברוך הוא. ואומרו **אם אחרת** דע כי אמרו ז''ל (זהר ח''ב קנ''ב:) כי בזמן החורבן כל כלי השפע משפיעין חוץ למקומן בשאר האומות ולא בישראל כי מתקלקלים הצינורות ומריקים במקום לא קדוש. והוא אומרו **אם אחרת יקח לו** לתת מדת טובו כאשר עיני כל ישראל רואות הפלגת הטוב ביד לא מבני ישראל המה טען הכתוב עוד לו יהיה שכעס עוד עליה שלא תהיה בהדרגת הטוב וההשקט כבנות העולם ונותן ה' מדת טובו לאומה אחרת לפחות שארה כסותה ועונתה לא יגרע, שארה אלו מזונותיה כמאמר ר' יאשיה (מכילתא), כסותה כמשמעו, ועונתה היא שיהיה עונה אותה בצר, וג' דברים אלו הם דברים המוכרחים ואיך יכולה לחיות זולתם. ואמר עוד **ואם שלש אלה** פירוש שארה כסותה ועונתה לא יעשה לה ותהיה גרועה מהם.
@553 **ויצאה חנם** פירוש הגם שלא יהיה בידם לא תורה ולא מצות ואפילו לא יכספו לדבר הגאולה והוא אומרו **איז כסף**, כי יסוריה יספיקו לפדיונה:
@553 **או** תרמוז הפרשה על זה הדרך **וכי ימכור איש** זה הקדוש ברוך הוא **את בתו** אומה הקדושה, **לאמה** פירוש להיות שכבר עברו גליות על ישראל גלות מצרים גלות בבל כו' וכולם לא נשתעבדו ישראל אלא לאומה אחת ואין דבר זה סובב קריאת שם עבדות על ישראל, אבל בגלות החל שאנו בו עתה משתעבדים ישראל לכל ע' אומות בכל מקום אשר שם עברי בזוי הוא ושפל וכל אחד בוזז וחוזר ליקוטי בתר ליקוטי ודבר זה ינסה ויסמן בהם בנסיון גדול וסימן מובהק והוא אומרו **לאמה** כי אומתינו בגלות זה קנתה שם אמה ומעתה גם בבוא גאולתינו ופדיון נפשינו כבר קנתה האומה שם עבדות, לזה אמר הקדוש ברוך הוא הבטחה כי גאולת האומה הלז לא תהיה כדרך אשר הוציאנו ה' ממצרים מבית עבדים אלא בנסים מופלגים בפרסום בכל העולם, והוא אומרו **לא תצא כצאת העבדים** הרמוזים בתורה (לעיל כ' ב') מבית עבדים וגו' שאז לא הפליא ה' פלאיו אלא באומה אחת, ואז בכל העולם והיו מלכים אומניך ושרותיהם וגו' וישתחוו כל מלכי ארץ ככתוב בספר ישעיה (מ''ט.) ואומרו **אם רעה** וגו' יתבאר על פי מאמר הזוהר כי תשתנה גאולת ישראל אם תהיה באמצעות מעשיהם הטובים לאם תהיה לצד השלמת קץ הסתום, כי אם תהיה באמצעות הכנת ישראל יבא הגואל מלאך ה' בעמוד אש מוצב ארצה וראשו בשמימה, ואם לצד הקץ וישראל לא ראוים לו עליו נאמר (זכרי' ט') עני ורוכב על חמור, והוא אומרו כנגד ביאת הגואל לצד הקץ הגם שאין ישראל ראוים לו **אם רעה** וגו' פידוש אפילו אם תהיה רעה בעיני אדוניה כשיגיע הקץ אשר קצב ליעדה **ולא** באל''ף ירצה שאינה ראויה ליעודיו כי היא רעה אף על פי כן **והפדה** פירוש פדיון יושג לה על כל פנים אבל לא יהיה הדבר כדרך אם לא תהיה רעה בעת הגאולה. ואמר **לעם נכרי** וגו' פירוש כי לא לצמיתות יהיה המכר לעם נכרי הגם שיבגוד בה כמאמר הכתוב (איוב כ''ח) קץ שם לחושך. וכנגד ביאת הגאולה לצד מעשיהם הטובים והכשרתם אמר **ואם לבנו ייעדנה** על דרך אומרם (ב''ב י'.) כשישראל עושים רצונו של מקום נקראו בנים, הכוונה אם יעודים אשר ייעדנה ה' בעת הגאולה תהיה לצד היותם במדרגת בנים אז **כמשפט הבנות** דבר זה יגיד הפלגת שעשוע ישראל בבוא הגואל פירוש בנות הם נשמות המשתעשעים בגן עדן הנקראים בנות ירושלים ומשפט שקצב להם צרור המור דודי לי להגלות להם אורו יתברך וזה הוא מחייתם ושעשועם ותכלית מאויים אמר ה' כי כמשפט הזה יעשה להם בביאת הגואל בעודם בעולם הזה יגלה ה' אור שכינתו על כל הצדיקים ויאמרו כולם זה אלי וגו' בתמידות כמשפט הבנות:
@553 **ואומרו אם אחרת וגו'**. בא הכתוב להתנות אימתי חלקתי לך בין זמן שהיא רעה לזמן שהיא במדרגת בנו אלא בזמן שאם אחרת יקח לו על דרך שפירשנוה למעלה **שארה כסותה ועונתה** של הבת הישראלית **לא יגרע** בזה הוא שחלקתי אבל **אם שלש אלה** וגו' **ויצאה חנם** פירוש אפילו אינם צדיקים לכסוף אל יום פדות יצאו אפילו קודם זמן הגלות והרי הם יוצאים בזכות יסורין אשר קבלו במחסור ג' הדברים ושוים הם למדרגת בן:
@554 **מכה איש ומת**. פירוש אין צריך שתהיה המיתה בשעת ההכאה עצמה כמו שתאמר שישחטנו או ישרפנו או יחנקנו שמוציא נשמתו ממנו בידו ממש אלא אפילו מת אחר כך בכח ההכאה חייב אלא אם כן עמד מחוליו דכתיב (פסוק י''ט) אם יקום. וחידוש משמיענו מה שאין הדין כן בהורג בשוגג שאינו חייב לגלות אלא דוקא אם מת בידו כדתניא בפרק מי שאחזו (גטין ע'.) שחט בו שנים או רוב שנים הרי זה אינו גולה משום דחיישינן שמא הרוח בלבלתו או הוא פרכם וקירב מיתתו וכו' עד כאן, וכתבו התוספת כי דוקא בהורג בשוגג אנו דנים דין זה דבהכי תליא דכתיב ויפל עליו וימות (בדמבר לה כג) משמע ליה לאלתר אף על פי שבמזיד חייב אפילו לא מת לאלתר יש חילוק בין מיתה לגלות עד כאן, והם דברינו שדייקנו באומרו במזיד **מכה איש ומת** ולא אמר הורג איש וגו' לומר אפילו הרגו עתה ומת אחר כמה ימים ובשוגג דקדק לומר **אנה לידו** פירוש שהרגו בידו ממש, וכן משמע מדברי רמב''ם בפ''ה מהלכות רוצח, ולא כן דעת הראב''ד שאינו מחלק יעוין שם דבריהם, ואין דבריו נראים בשום אופן בעולם, ואין כאן מקום פלפול הפוסקים:
@554 **מות יומת**. טעם הכפל בדין זה ובדין מכה ומקלל יולדיו ובגניבת איש ובהכאת עבדו וכדומה. דע כי משפטי ה' הוא השופט כל העולם להמית לעושי רשעה אלא שבחר לתת קצת מהם לשופטי ארץ להמית הרשומים בתורת ה' לטעמים רבים מהם נגלו לנו מהתבוננות התורה וכהנה וכהנה ישפוט הוא האדון למעלה כבועל נדה ומחלל יום כפור וכאוכל חלב וכדומה הוא ישלח מלאכו לפגוע בו, ולזה אמר הכתוב **מות יומת** פירוש אותו שהוא בן מות יומת על ידכם כי בן מות הוא הגם שלא יומת מכם. ולזה אמרו ז''ל (כתובות ל'.) הגם שיבטלו הדיינים, דינם לא בטל וישפטהו השופט לעולם, ולזה בדין שור שנגח אדם והועד בבעליו אמר וגם בעליו יומת כי שם אין מיתה אלא בידי שמים ולא מסרו לבית דין כאומרם ז''ל (מכילתא) יומת בידי שמים. ורבותינו ז''ל (ב''מ ל''א:) אמרו עוד בזה דבר:
@555 **ואשר לא צדה והאלהים וגו'**. צריך לדעת למה כפל לא צדה והאלהים וגו'. ועוד קשה למה יאנה ה' לאדם און זה. ורבותינו ז''ל אמרו במכילתא ובהגולין (מכות י':) זה הוא שאמר הכתוב מרשעים יצא רשע וגו' הא כיצד היה יורד בסולם ונפל עליו והרגו וכו' הרי זה גולה היה עולה בסולם ונפל עליו והרגו הרי זה אינו גולה וכו' בא מזיד ונפל ביד שוגג עד כאן. וקשה הן אמת כי מזיד זה נטל שכרו מושלם כי בן מות הוא והרי הוא נהרג אלא שוגג זה שגולה גלות זה הוא על מה ששגג עתה בפעם הזאת ועל שגגתו אשר שגג בראשון אין לו פרעון עליה, ואם אשר הזמין לידו ה' לא יתחייב עליה כי ה' הזמינה לידו אם כן מוכרח לומר כי בפעם הזאת לא אנה ה' לידו והנהרג על ידו לא היה מחוייב מיתה שאם מחוייב הרי זה יכנס גם כן בגדר כי ה' אנה לידו, וזה דוחק, כי הכתוב יגיד ענין שגגת הריגת נפש בלא צדיה ולא חלק בקצת מהם. והנכון כי גם נהרג ראשון נתחייב מיתה והרגו זה במאמרו יתברך אשר אנה ליד זה ההורג בשוגג, והנה זה שנהרג נלכד בפשעו ונהרג על אשר הרג במזיד אבל היה ה' יכול להפיל עליו מפולת בלא אמצעות הורג בשוגג, אלא לצד שקדם אליו עון מזיד [שוגג] שאין עליו חיוב אלא גלות ואנה ה' לידו דבר זה, והנה אדם זה אינו גולה על ההריגה אלא על מה שקדם לה שסבב הריגה וכפי זה אפילו הרג עשרה אינו חייב אלא גלות אחת כי סבת הגלות אחת היא ואחר שישלם עונו לא יזמין ה' לידו רציחה אחרת. ותמצא שלא הגביל ה' שיעור הגלות לכל הרצחנים שיעור אחד. אלא כל אחד כפי שיעור חטא הקדום לו. וכפי זה טעם שאמר הש''ס שעון זה ההורג בשוגג הוא על אשר הרג בשוגג וכפי דברינו הוא חטא נעלם קדום להריגת הראשון, אולי שנקטו המצאה שוה בעונש שניהם שהוא על ההריגה, והמשכיל על דבר לבבו יבין יסודן של דברים:
@555 **או** אפשר כי לצד שרמזוהו מן השמים דהמתגלגל על ידו שהרג הנפש והיה לו להכנע ולקבל עליו הגלות מעצמו הרי זה הוסיף על חטאתו פשע, ולזה הזמין לו עוד שוגג אחר מלבד הראשון וצריך לגלות פי שנים כשיעור הצריך למספר רשעיותיו. ולזה תמצא שנתחכם ה' ולא גבל שיעור גלות הרוצח אלא עד מות הכהן הגדול ודבר זה הנה הוא מסור לאדון כל הארץ והוא ישפוט בצדק כמה שיעור הצריך לו אם לאחת אם לשתים. ולפי דרך זה יתיישב כוונת אומרו הענין אבל עדיין אין כדי ליישב אומרו **והאלהים** בתוספת ו':
@555 **ונראה** כי יכוין הכתוב לדקדק דין הגולה אופן שנתחייב בו על פי מה שכתב רמב''ם בפ''ו מהלכות רוצח שאין גולה אלא שוגג שאינו אונם פירוש שהמעשה הוא דבר הרגיל, גם שלא היה לו צד הזדה כל עיקר, אבל אם היה השוגג דבר שאינו מצוי, או שהיה בו צד הזדה כגון שונא שחזקתו למזיד וכדומה לו אינו גולה. וכנגד שניהם דקדק הכתוב לומר ב' דברים **ואשר** וגו' **והאלהים** וגו', כנגד שוגג בדבר שאינו מצוי אמר **לא צדה** פירוש לא צדה להורגו גם לא צדד שלא להורגו, כי כל שוגג צד חיובא הוא שהיה לו להעלות על דעתו לבל תבא תקלה על ידו, אבל במקום שהגם שיצדד הוא דבר שאינו רגיל אנום הוא ופטור, וכנגד בחינת מזיד של השונא אמר **והאלהים** וגו' פירוש למעט בא שלא בא הדבר אלא מה' ולא ממנו כי לא חפץ הוא המיתו כי לא שונא לו אלא מה' יצא הדבר, אבל אם גם יש צד שנאה ממנו שהיה שונא אינו גולה:
@556 **וכי יזיד וגו'**. בספרי (מכילתא כאן) וזה לשונם למות ולא לדון ולא ללקות ולא לגלות. וזה הוא טעמו של יואב שברח אל המזבח ויחזק וגו', הגם שלא הרגו שלמה אלא בדין וכמו שכתבו התוספת בסוף פרק נגמר הדין דף מ''ט. שהיה מורד במלכות, הוא ברח קודם הדין. ואמרו בהגולין (מכות י''ב.) כי טעותו היה שלא היה מזבח עולמים וגם שתפם בקרנותיו ואינו קולט אלא גגו:
@556 **וראיתי** לרמב''ם שכתב בפ''ה מהלכות רוצח ושמירת נפש שהמזבח קולט רוצח בשוגג לענין מיתה מגואל הדם אבל לא מגלות עד כאן, והוא ודאי שלא ראה הברייתא שמדייק למות ולא לגלות ולא וכו', והגם שיש לדחוק ביישוב אומרם ולא לגלות שהכונה היא למי שנתחייב גלות שלא יהרגנו גואל הדם, פירוש זה דחוק הוא, וגם תכחישנו מה שלפניו ולא לדון ולא ללקות והבן. ומה מאוד גדלה לי הקושיא לדעת הרב בעל משנה למלך שכתב ותמה על רמב''ם שחלק בין שוגג למזיד אפילו לענין מיתה מגואל הדם ואמר כי אין לחלק כלל בין שוגג למזיד עד כאן, ואין דבריו מחוורין אפילו בלא מתניתא כי אין לנו לומר שאין מזבח קולט אלא במה שמיעט הכתוב בפירוש:
@560 **וכי יריבון אנשים וגו' ולא ימות**. צריך לדעת למה הוצרך לומר **ולא ימות** ולא סמך להבין כי בלא ימות מדבר הכתוב בין ממה שקדם במשפט אם ימות ב. ן ממה שגמר אומר אם יקום והתהלך וגו':
@560 **אכן** הכונה היא לומר שאין חיוב לתת שבת ורפוי אלא אם לא ימות אבל אם ימות לא יתן שבת ורפוי, ולזה לא אמר הכתוב שבתו יתן וגו' אלא אחר שעמד מחליו והתהלך. ומסתפק אני אם אמדוהו למיתה ולא מת אם נאמר מעשה נסים נעשו לו שלא מת כמו שאמרו ז''ל (חולין מ''ב.) בטריפה שאינה חיה ואם חיתה מעשה נסים נעשו לה (שם מ''ג.) כמו כן במה שלפני כאן אם לא מת נס הוא זה וחיוב שבת ורפוי כיון שפקע פקע או דלמא הרי לא מת וחייב בשבת, ומדברי רמב''ם בפ''ד משמע כי כל שלא מת הגם שאמדוהו למיתה חייב בשבת וריפוי. שוב מצאתי שאמרו במכילתא וזה לשונם ולא ימות ונפל למשכב הא אם הכהו המכה מכה שיש בה כדי להמית פטור מהשבת והרפוי עד כאן. משמע אפילו לא מת ממה שתולה הטעם במכה ולא אמר הא אם ימות:
@560 **ונראה** שכוונת התנא לומר שצריך ליפטר מן השבת דוקא אם מת על ידי מכה שיש בה כדי להמית אבל אם מת במכה שאין בה כדי להמית שאז פטור המכה ממיתה יתחייב לתת שבת וריפוי אם לא נתן לו בחיים חיותו לצד איזו סיבה יתחייב לתת ליורשיו כל מה שנוגע לאביהם אם חי:
@561 **רק שבתו יתן ורפא** י **רפא**. פירוש אפילו אחר שקם והתהלך בחוץ אם הוא עדיין בטל ממלאכתו ואינו יכול לעשותה או שעדיין הוא צריך לרופא לשיורי החולי מחמת המכה הרי זה חייב לתת. ואומרו רק יתבאר על פי מה שכתב רמב''ם (פ''ב חובל ומזיק) משערין את הריפוי וכו' וכן השבת אומדין וכו' ואם וכו' וארך החולי יותר על מה שאמדוהו אינו מוסיף לו כלום וכו' במה דברים אמורים כשרצה המזיק שזו תקנה היא לו וכו' עד כאן, ולזה אמר רק וגו' פירוש למעט בא שיש זמן שלא יתן שבתו ורפואתו והוא אם קדם וקצב וכו' אבל בלא קצבה יתן עד שיתרפא לח לוטין:
@561 **ורפא ירפא**. יתבאר על דרך מה שכתב רמב''ם (הל, חובל ומזיק פ''ב הי''ד) אמר לו הניזק פסוק וכו' ואני ארפא את עצמי אין שומעין לו, והוא או' **ורפא ירפא** ולא אמר יתן כאומרו בשבתו הסמוכה שהיה לו לומר שבתו ורפואתו יתן, והרבה דרשות נאמרו בכפל זה:
@562 **בשבט**. כתב רמב''ם בפ''ב מהלכות רוצח וז''ל יראה לי דוקא בשבט אבל בסייף וסכין או אבן ואגרוף וכיוצא ואמדוהו למיתה אפילו מת לאחר שנה הרי זה נהרג עליו עד כאן. וקשה לי אם לא הרגו בדבר שאמדוהו להריגה למה אם לא יעמוד יום יתחייב הרי אפילו לאדם אחר שאינו עבדו פטור הוא אפילו לא יעמוד יום. ואולי שעל שאר אומדנות הוא אומר שהגם שאמדוהו שימות במקום המכה ושאר אומדנות. ולי נראה שאומרו **בשבט** לומר שאם מעשיו מוכיחים כי ליסרו בשבט מוסר הוא שנתן ה' זכות יום אחד וכו', אבל אם מעשיו מוכיחים שמתכוין להורגו כגון שתוחב לו סכין בבטנו ובסימניו שזה מגיד שאינו מיסרו אלא ממיתו ומת אפילו אחר שנה חייב עליו:
@563 **לא יוקם כי כספו**. ואם הרגו שוגג יגלה על ידו, ובדין זה אין בו חילוק בינו לבין רוצח לאדם שאינו עבדו כי אינו חייב גלות אלא אם הרגו ומת תחת ידו ממש וכמו שכתבנו בפסוק (י''ב) מכה איש וגו', ולא הוצרך לכתוב אלא דין שהוא משונה מדין רוצח לשאינו עבדו:
@564 **וכי ינצו אנשים**. פירוש וכל אחד מתכוין להרוג את חבירו ובאה המכה באשה בזה הוא שאמר כל צדדי הדינים האמורים בענין:
@564 **ונגפו וגו'**. אמר לשון רבים לומר שאם שניהם נפלו עליה ונגפוה משלשין ביניהם וכמו שכתב רמב''ם בפ''א מהלכות חובל ומזיק:
@564 **אשה הרה**. פירוש המצויה שם בידיעתם, אבל אם באה ועמדה בגבולם ונגפוה בלא ידיעה פטורים מכלום מדין שכתב בירושלמי ופסקו רמב''ם בפ''א מהלכות חובל ומזיק וזה לשונו אם היה אחד ישן ובא אחד ושכב בצדו הרי זה פטור הישן גם מהנזק כי זה אונס מיקרי:
@564 **כאשר ישית עליו בעל האשה** פירוש לצד כי הוא הנוטל דמי ולדות הוא יהיה בעל דינו בעונש זה לקחת ממנו הראוי לו:
@565 **ונתתה נפש וגו'**. נחלקו רבותינו ז''ל במכילתא יש אומרים מיתה הגם שנתכוין להרוג את זה והרג את זה ויש אומרים ממון. ולדבריו ידוייק אומרו **ונתתה** על נכון שהוא דבר הניתן מיד ליד. ולמאן דאמר נפש ממש אמר **ונתתה** לומר כי במקום נתינה האמורה בסמוך כשלא יהיה אסון תהיה זו ואין כאן נתינה אחרת כי פטור מדמי ולדות זולת אם היה אסון והוא בדרך שאינו חייב כגון שאמדו המכה שאינה כדי להמית הרי זה חייב וכמו שכתבתי בפסוק (י''ח) וכי יריבון:
@568 **וכי יכה וגו'**. בקידושין (כ''ד:) פליגי רבן שמעון בן גמליאל ורבנן רבן שמעון בן גמליאל סובר צריך לכוין לשחתה ורבנן סוברים הגם שלא נתכוון לשחתה אלא שצריך לכוין לעין עצמה. וקשה לרבנן היה לו לומר וכי ישחית איש את עין עבדו. ואולי כי הייתי אומר כי השחתה שאמר הכתוב היא לגופה ולא היינו יודעים שיכוין הכתוב לומר תנאי הוא הדבר שצריך שיכוין לה:
@568 **עוד** נראה שנתכוון לומר שהגם שלא שחתה בשעת הכאה עצמה אלא אחר זמן יהיה הדין כן ואינו דומה לשוגג שכתבנו למעלה שצריך שימות בשעה עצמה. ודרשת רבנן שצריך שיכוין לעין נשמעת מכינוי ושחתה:
@569 **ואם שן עבדו**. טעם שלא כלל הכתוב שן ועין וחלקם בב' מצות, יתבאר על דרך אומרם ז''ל בקדושין (כ''ד:) אמר ר' ששת היתה עינו סמויה וחטטה יוצא לחירות, ולפי זה יש בעין ב' דינים של שחרור. האחד אם כיהה עינו הגם שלא חטטה כמובן שם בקדושין שהגם שלא נחטטה כל שחסר מאורה ואינו יכול להשתמש בה יצא לחירות, והב' שהגם שהיתה כהויה אם חטטה יצא לחרות, ואם היה הכתוב כולל אותם בדין אחד היינו לומדין בעין כדין השן מה שן ביטולה הוא נפילתה גם עין ביטולה הוא נפילתה אבל כיהוי שאינו מחסר כלל מהעין לא יצא לחירות:
@570 **וכי יגח וגו' את איש**. טעם אומרו **את**. יתבאר על דרך אומרם בגמ' (סנהדרין ע''ט.) נתכוין להרוג שמעון והרג ראובן חייב שהרי נתכוין להרוג מי שחייב עליו, והוא אומרו **את איש** לרבות כל שנתכוין לאיש הגם שהרג אחר שלא נתכוין לו. ודוקא נתכוין לאיש אבל נתכוין לבהמה והרג האיש פטור כדאמרינן שם (ע''ח:):
@570 **ומת** פירוש אפילו מת אחר זמן כל שמת מחמת נגיחה, וכן משמע מדברי רש''י (ב''ק מ''א.) בפירוש סוגיית סכן ג' בני אדם ולא מתו יעויין שם:
@570 **ולא יאכל את בשר** ו. ואם אכלו לוקה, אבל שאר הנאות הנשמעות מאומרו ובעל השור נקי הגם שאסור אינו לוקה, ולזה לא כלל הכל בכללות אחד:
@570 כט) **והועד בבעליו**. אמר לשון רבים, נתכוון לומר שאם היו לו ב' בעלים חייבים שניהם מיתה, ולא יהיו כב, שהרגו אדם כאחת שפטורין למאן דאמר (ב''ק כ''ו:), כי התם פטורין ממיתה בידי אדם וחייבים בידי שמים וכאן פטורין ממיתה בידי אדם וחייבים בידי שמים. ובכופר להיותו ממון חייבין אפילו בידי אדם:
@572 **פדיון נפשו**. נחלקו בפרק ארבעה וחמשה (ב''ק מ') בשל מי שמין אם בשל מזיק אם בשל ניזק. והיה נראה כי להאומר בשל מזיק אם המית שור של ב' בני אדם חייבין לשלם דמי כל אחד מהם כי כולן נתחייבו לשמים. ולהאומר של ניזק אינם חייבין אלא דמי הניזק. וקשה אם כן מאי בעי שם ר' נחמן לר' אחא בר יעקב אם חייבין לתת כופר כל אחד שלם הלא דבר זה מחלוקת התנאים, אלא ודאי דהן אמת להאומר בשל מזיק ודאי שצריך לשלם ב' כופרים מידי דהוה שהמית שור אדם גדול ששוה מאתים לאדם ששוה חמשים שחייב לשלם ולא יגרע אם יחלקו לב' גופים וחייבים לתת דמי כופר שנים, ובעיא דר' נחמן היא אליבא דחכמים שסוברין שמין בשל ניזק, וכן משמע מדברי רמב''ם שפסק פי''א מהלכות נזקי ממון בדין דמי כופר ששמין דמי הנהרג ובשור ב' שותפין פסק (שם פ''י) שחייבין ליתן כופר שלם לכל אחד והבן. וטעם שפסק רמב''ם לחומרא משום דהויא ספק כופר נפש:
@572 **ואם** קדם גואל הדם והרג את זה קודם שיתן פדיון נפשו נראה לי שנהרג עליו שלא פטר הכתוב אלא הריגת הורג ביד בשוגג מדין יחם לבבו אבל אם שורו הרג אין כאן יחם לבבו כהורג ביד:
@575 **וכי יפתח וגו'**. פירוש אפילו בשעת פתיחת וכריית הבור אם נפל עליו שור או חמור חייב בעל הבור, ואפילו נהרג בתוך בורו יורשיו ישלמו וכדאיתא בפרק קמא דערכין (ז'):
@577 **שור איש את שור רעהו**. אומרו **את**, ירצה ששניהם שוים בחייהם כשנערכו אותם יהיו שוים, והוא אומרו **שור איש את שור** פירוש הנערך אתו, אבל אם היה גדול הנוגף אין לניזק אלא חצי נזקו, וכן מבואר בדברי רבותינו ז''ל (ב''ק ל''ד.) ואם אין שיעור המזיק כניזק אין לומר שיטול יותר מחציו של חי שאם כן לא היה הכתוב תולה במכירת השור החי אלא היה לו לומר יתן לו חצי נזקו של מת ויחצון המת, וממה שתלה בחצי שור החי שמע מינה שאין לו אלא חצי החי הגם שיעלה לפחות מחצי נזק, ולא חש עלי לטעות שאפילו יותר ממה ששוה. ואם תאמר כלך לדרך זה מה שתלה הדבר בחצי החי הוא אפילו יהיה בחציו יותר מחצי נזק ואמר ההשואה בשוודים להיכא שלא היה שוה שיטול יותר מחצי, זה אינו דלכשתאמר כי ניגף יטול חצי מזיק הרי לא חלקת אם כן לפעמים יגח שור שוה מאתים לשור שוה חמשים ולכשתדון כסברא זו הרי הוא נוטל כפלים מהזיקו ונראה למי דומה דין זה שנסכים עליו:
@578 **ולא ישמרנו**. יתבאר על דרך אומרם בפרק ד' וה' (ב''ק מ''ה:) ר' אליעזר אומר אין לו שמירה אלא סכין אמר רבה מאי טעמא דאמר קרא ולא ישמרנו שוב אין לו שמירה לזה אמר ליה אביי אלא מעתה ולא יכסנו נמי שוב אין לו וכו' עד כאן. ונראה כי דיוקא דרבה קאי וקאי, כי יש הפרש בין ולא יכסנו שהכתוב לא שינה שיעור הדבור שהתחיל לומר כי יפתח לשון עתיד כי יכרה וגו' ולא יכסנו לשון עתיד מה שאין כן ולא ישמרנו שהתחיל הכתוב לומר לשון עבר או נודע וגו' וגמר אומר לשון עתיד ולא ישמרנו שהיה לו לומר ולא שמרו ונכון. והתם לא חש רבה להשיב לאביי, ולסברת ר' יהודה שפוטרו בשמירה אפילו פחותה אמר הכתוב כסדר זה ולא ישמרנו לדרוש לזה ולא לאחר, ועיין שם בסוף הפרק:
@578 **ישלם שור**. אולי שהגם שאמרו (ב''ק ה'.) מועד ישלם מעידית שבנכסיו אם היה לבעל המזיק עידית יותר בנכסיו יכול לסלקו בשוה כשורו ולא אמרו עידית אלא לאפוקי פחות מזה:
@579 **וטבחו וגו'**. פירוש לשור ושה, אבל טלה וגדי וגדלו ברשותו ונשתנו בידו אינו חייב שקנאו בשינוי ושלו מכר או טבח וכן מוכח מדבריהם (ב''ק ס''ה):
@579 **השור**. במשנה (שם ס''ב:) אמרו אין חייב בד' וה' אלא דוקא שור ושה ולא חיה ועוף, וטעמם שהיה לו לומר כי יגנוב איש שור וטבחו או מכרו חמשה בקר ישלם וארבע צאן תחת השה, ודורש אחת מהם למעט כל חוץ מהם וביתור של אחד היה נשמע המכוון שישתנה הדין בין השור לשה:
@582 **אם המצא תמצא**. טעם הכפל לומר אחת לגופה שבאו עדים שגנבה, וב' לומר שמצאוה בעין אצלו, אבל זולת זה יתחייב בד' וה' שכל שאינה בידו בחזקת מכורה או שחוטה, ולא אמר הכתוב שנים לבד אלא בנמצאת. ותדע שלאו דוקא מכר או טבח אלא הוא הדין נתן או אבד כל שיצתה מרשותו, וכן מוכח בש''ס (ב''ק ע''ט:) להדיא, והוא הדין הקדיש. וראיתי לדייק מכאן שאם גנב מעובד כוכבים ומזלות אין בו דין ואם אין לו ונמכר בגניבתו שאמר בסמוך ממה שאמר סמוך לונמכר בגניבתו אם המצא תמצא וגו' שנים ישלם ואמר הכתוב בדין תשלומי ב' לרעהו ולא לעובד כוכבים ומזלות כמו שדרשו ז''ל (מכילתא) הא למדת כי דין ונמכר בגניבתו האמור בענין אין הכתוב מדבר אלא בגנב מישראל ולא מעובד כוכבים ומזלות ולא מהקדש, והם דברי רמב''ם בפ''ג מהלכות גניבה ולא מצאו לו שם טעם והנה הוא:
@583 **כ יבער איש וגו**. יתבאר על דרך מה שאמרו בהכונם (ב''ק נ''ו:) אמר רב המעמיד בהמת חבירו על קמת חבירו וכו' חייב, ואמרו שם אפילו קם לה באפה ואפילו הכישה חייב, והוא אומרו **כי יבער איש** פירוש. אפילו אם [אין] הבעיר שלו. ואומרו **ושילח את בעירו** פירוש ואפילו לא העמיד ולא קם לה באפה ולא הכישה אלא ששלחה לנפשה ולא שמרה מלכת והיא מעצמה ביערה בשדה הזולת אם הבהמה שלו כאומרו בעירה בכינוי חייב מיטב וגו':
@584 **כי תצא אש וגו'**. פירוש הגם שהדליק בתוך שלו כשיהיה באש הנדלקת שיעור לצאת למקום שאינו שלו. ושיעור תיבת **תצא** הוא שתהיה ראויה לצאת, אבל הדליק בתוך שלו ולא היה שיעור לצאת לחוץ ויצאתה פטור שזו מכה בידי שמים וכדאיתא בגמרא (ב''ק ס''א:) ואומרו **ומצאה קוצים** פירוש והגם שזולת הקוצים לא היתה משגת מקום קמה וגדיש להבעירם ובאמצעות הקוצים נאכל גדיש וגו' **שלם ישלם** פירוש שלם הגדיש או הקמה ישלם דמי העצים הגם שהם אדרבה היו סיבה לקלקול. ודוקא שמצאתם אבל בא אדם והניחם אחר שהבעיר, השני חייב לשלם.
@584 **המבעיר** וכפל לומר **הבערה** לרמוז גם אל העצים שהם הם המבעירים את הגדיש והקמה:
@584 **עוד** נתכוין באומרו **ומצאה** הגם שלא ידע המבעיר שהיו שם קוצים או אפילו לא היו שם בשעת ההבערה ובא אדם והניחם במחוז שלו ולא ידע כי יש הבערה הרי המבעיר חייב:
@584 **ובדרך** רמז תרמוז התורה את אשר יסובבו הרשעים ברשעם כדי שיתעורר האדם מתרדמת שינת שכלו בהביטו הפלגת הרעות אשר יביאו לעולם כי לא לבדם יריעו אלא יסובבו רע לכל העולם, והוא אומרו **כי תצא אש** הלא ידעת כי צרת העם תתכנה בשם אש. וצא ולמד משליח גבריאל (יומא ע''ז.) אשר שאל אש מבין הבדים (הכרובים) והוא בחינת תגבורת הדינים, ואמר **ומצאה קוצים** הם הרשעים שאינם אלא קוצים מכאיבים, ואומרו לשון **מצאה** על דרך אומרו (דברים לא כא) והיה כי תמצאן אותו וגו', והטעם משום שהרשע אין לו בעלים כי האדון ברוך הוא הנה הוא פקר בו והסיר אדנותו מעליו וה' הסתיר פניו ממנו ומעתה הרי הוא כמציאה וכל הפוגע בו יעשה בו רצונו, והודיע הכתוב עוד כי אחר שניתן רשות לאש הדינים להבעיר לא לקוצים לבד הם מבעירים אלא **ונאכל גדיש** כאן רמז אל תינוקות של בית רבן שעדיין אין להם קומה אלא גדושים שבולת עם חברתה כי בעונות הם הנתפסים בצרת עולם. גם אמרו ז''ל (שהש''ר פס' משכני) בפסוק (תהלים ח) מפי עוללים ויונקים יסדת עוז כי היו ערבים בשעת קבלת התורה וכשירשיעו בני אדם הנה הרשות נתונה לאש לבער בהם, ואומרו **או הקמה** כאן מודיע כי לפעמים חרב עד צואר הגיעה מופתי הדור יסודי עולם נלקחים בעונם כדי להציל על כללות הדור כאומרו (שה''ש א') אשכול הכופר וגו', ולהם יקרא קמה על דרך אומרו (שם ה') זאת קומתך דמתה לתמר שהם הצדיקים הנמשלים לתמר כאומרו (תהלים צ''ב) צדיק כתמר וגו', ולפעמים יגדל החטא ולא יצילו הצדיקים לבד וחימה שפוכה על כל שונאי ישראל, והוא אומרו **או השדה** שזה ירמוז אל כללות ישראל ולא יספיקו לא תינוקות ולא צדיקים להציל. והודיע הכתוב כי יש יום לאל איום לבא במשפט עם הסובבים את הדבר למיתת הצדיקים וגאוני עולם להשתלם מהם, והוא אומרו **שלם ישלם המבעיר** הם הרשעים הקוצים את כל אשר הרגו, ואמרו ז''ל (סנהדרין ק':) כי ה' יתן כח ברשעים לסבול שיעור המגיע להם בחטאם אוי לרשע רע לשמים ולבריות כמה יסבול בעד קלקולו, ותמצא (ב''ר פס''ג) שהצדיקים כשהיו בניהם מגיעים לכלל שנים שאינם נלכדים בעון אביהם היו שמחים ואומרים ברוך המקום שפטרם מעונש זה, הרי כי יעניש ה' לגורם עונש בשבילו לזולת, ובאמת כי יחרד אנוש ויכבה שלהבת יצרו המחטיא אותו באש המשפט בהעלותו על לבבו נהרות העונשים אשר יגיעוהו על כמה נפשות קטנים וגדולים אין קץ שכולם הוא הרצחן הגדול להם באמצעות תאותו הסרוחה, והנה אמרו ז''ל (קידושין מ':) לעולם יראה אדם כאלו כל העולם כולו חציו זכאי וכו' עשה עבירה אחת אוי לו שהכריע את כל העולם לחובה ודם כל העולם ודם זרעיותיהם על צוארו ועל נפשו עמוסים ויסבול מר המות בעד כל נפש אחת מהם ובכל צרתם לו צר כאשר עשה, והוא אומרו **שלם ישלם** וגו' טעם כפל שלם וגו' המבעיר וגו' כאן רמז הכתוב כי לא לאיש הרשע לבד יעשה ה' משפט התשלומין אלא גם להמחטיאו והוא יצר הרע בחינה המחטיאתו כי גם לו משפט חרוץ ביום ההוא יגדל המספד עליו בעשות בו ה' דין כמאמרם ז''ל (סוכה נ''ב.) שמביאו ה' ושוחטו ולא ימלט בבורחו לבצרה ואפילו לבצר (מכות י''ב.) כי מזיד הוא ומלך המשפט ישפוט בצדק להשתלם ממנו ונשגב ה' לבדו ובקמא (ב''ק ס'.) רמזו באופן אחר:
@585 **כי יתן איש**. פרשה זו העמידוה רבותינו ז''ל (ב''מ צ''ד:) בשומר חנם כי הוא לבדו פטור מגניבה ואבידה, ואמרו שעל כל פנים חייב בפשיעה, ולא נודע מנין להם כיון שהכתוב לא חייבו אלא לישבע שלא שלח ידו כל חוץ מזה פטור, ורש''י ז''ל בהשואל דף צ''ה כתב בדיבור המתחיל אשומר חנם וז''ל דכתיב ביה פשיעה דכתיב על כל דבר פשע. ונשאר לדעת על מי סמך הכתוב לדעת כי ידבר בשומר חנם. ואולי כי לצד שהלביש הנתינה בכסף או כלים שהם דברים שמן הסתם שאינם צריכין שכר לשומרם ובשומר שכר אמר דברים שמן הסתם צריכין שכר לשומרם שהם חמור או שור או שה וכל בהמה שכל מין זה יש בו טיפול ומן הסתם רגילות לשמור בשכר:
@585 **אל רעהו**. רבותינו ז''ל אמרו (שם נ''ז:) ולא של הקדש, ונראה לי לתת טעם הדבר שהוא לטעם עצמו שצוה ה' לפטור בבעלים ושפיר יקרא האדון בעליו של הקדש עמו של כל נפקד שאין לך שעה ורגע שאין ה' עושה פעולה עם האדם בין בבחינת גופו בין בבחינת צרכיו:
@585 **כסף או כלים**. לא היה צריך לומר אלא כי יתן איש אל רעהו והרי הוא אומר בסמוך על כל דבר פשע על שור על וגו' ודרשו ז''ל כל פרטים שיתחייב עליהם אם לא שמר ופשע. ואם לרשום הכתוב כי בשומר חנם הוא מדבר היה מספיק לומר כי יתן כסף, [כלים] למה לי. ובמכילתא אמרו כסף או כלים מה כסף שדרכו לימנות אף כלים שדרכם לימנות מכאן אמרו כל טענה שאינה במדה במשקל ובמנין אינה טענה עד כאן. ואין סתירה לדברינו מדכריהם. עוד נראה לי טעם אומרו **כלים** לומר שהגם שירצה השומר לשלם אינו נפטר, וכמו שכתב רמב''ם בפ''ו מהלכות שאלה ופקדון שאם הפקדון הוא כלי מתוקן משביעין אותו, והגם שהרמב''ם אמר משום תקנת חכמים אפשר שירמוז הכתוב לזה, וידוייק גם כן מה שגמר אומר הכתוב **אם לא שלח ידו במלאכת רעהו** דקדק לומר מלאכת לומר הגם שאין טענה אלא טענת מלאכה שבכלים ומשלם שויו:
@585 **לשמור**. במכילתא רבי ישמעאל אומר עד שיפקיד אצלו ויאמר לו שמור לי אבל אם אמר לו עיניך בו הרי זה פטור. ובהחובל (ב''ק צ''ג.) דרשו לשמור ולא לאבד ולקרוע לשמור ולא לחלק לעניים. ומדברי התוספת שם משמע שלא פטר התנא כל שלא אמר לו שמור לי אלא מפשיעה אבל אם אבדו בידים אינו פטור עד שיאמר לו בפירוש לאבד ולקרוע, וקשה לי מנין מצאו לדרוש ב' מיעוטים בב' הדרגות הא' אם לא אמר לו שמור פטור מפשיעה והב' אם אמר לו לאבד פטור אם אבד. ונראה כי דרשת מכילתא דרשה גמורה היא ודרשת החובל ולא לאבד סברא היא אלא שאסמכוה אקרא. ותדע כי אמרו עוד ולא לחלק לעניים וטעם מיעוט העניים מוכח משם שהוא מטעם שהוא ממון שאין לו תובעים, וכמו שאמר שם בההיא מעשה שהקדיש ההוא גברא ארנקי לצדקה אפקדיה רב יוסף בההוא גברא אתו גנבי גנבוהו וחייביה רב יוסף אמר ליה אביי והתניא לשמור ולא לחלק לעניים אמר ליה עניי פומבדיתא מיקץ קץ להו ופרש''י והוה להו ממון שיש לו תובעים, הרי שטעמו הוא זה, ולטעם זה לא היה צריך מיעוט דזה כיון דאקדשיה לממון זה לעניים פקע זכותו ממנו ונשאר הממון אין לו תובעים, ונראה כי הוא הדין אם אמר לו לשמור לחלקם לעניים שהוא פטור מטעם שהוא ממון שאין לו תובעים, והראיה ממה שמקשה אביי לרב יוסף מברייתא לשמור ולא לחלק ומאי קושיא דלמא הוא אמר לו בפירוש לשמור מה תאמר שלא אמר לו לשמור אם כן הוה ליה להקשותו מברייתא דלשמור עד שאמר לו שמור וזולת זה יהיה פטור אפילו בממון שאינו לחלק, עוד אמרו שם במכילתא אחר דברי ר' ישמעאל ר' נתן אומר לשמור להביא כל הדומה לכסף וכלים:
@587 **על כל דבר פשע וגו'**. אמרו ז''ל (ב''מ נ''ז:) על כל וגו' כלל על שור וגו' פרט על כל וגו' חזר וכלל מה הפרט דבר המטלטל וגופו ממון וכו' יצאו קרקעות שאין מטלטלין ועבדים שהוקשו לקרקעות יצאו שטרות שאין גופן ממון עד כאן. ופסק כן רמב''ם פ''ב מהלכות גניבה. הנה פשטן של דברים יגידו כי הגם שפשע שומר חנם וכו' פטור כי זולת הפשיעה אפילו בכסף וכלים פטור הוא. וראיתי לרמב''ם שכתב בפ''ב מהלכות שכירות וזה לשונו יראה לי שאם פשע השומר בעבדים וכיוצא בהם חייב לשלם שאינו פטור בעבדים וקרקעות ושטרות אלא מדין גניבה ואבידה שאם היה שומר חנם ונגנבו או אבדו וכו' פטור משבועה כו' אבל אם פשע בה חייב לשלם שכל הפושע מזיק הוא ואין הפרש בין דין מזיק קרקע לדין מזיק מטלטלין ודין אמת הוא זה למבינים וכו' עד כאן. וחלקו עליו רבוואתא ז''ל בטענה הנשמעת והיא שאם היה פושע מזיק ממש לא היה פטור אם בעליו עמו שאמר הכתוב לא ישלם ואפילו אם פשע וכמו שכתב רמב''ם עצמו בפ''א מהלכות שכירות וזה לשונו ואפילו פשע כו' ואבד מחמת הפשיעה פטור עד כאן. ופשוט שדין פושע אינו כדין מזיק כי הפושע אינו לא שומר ולא מזיק אלא שבהסתלקות שמירתו ההיזק בא מעצמו אבל המזיק הוא גורם לו ההיזק. ועוד הקשו אם כן יתחייב על כל פנים שומר חנם שבועה שלא פשע כיון שאם פשע חייב:
@587 **ונראה** לומר כי מה שהקשו משמירה בבעלים שאני ושאני כי בבעלים גילה הכתוב בפירוש כי פטור הוא הגם שהזיק כמובן מהכתובים וכמו שדרשו בהשואל, אבל מה שמיעט הכתוב קרקעות ושטרות בדין שומר חנם לא מצינו שמיעטם בפירוש אפילו פשע כי לא הוזכרה פשיעה כלל אלא שליחות יד דכתיב אם לא שלח, ומה שאנו מחייבין שומר חנם על הפשיעה אינו אלא לצד דין מזיק ואיך נפרש המיעוט על דבר שלא הוזכר כלל, ואם אומרו דבר פשע, כבר פירשוהו שיכוין על פשעו בו שגנבו הוא ואומר נגנב אבל הפשיעה לא הוזכרה. והן אמת כי אם הפשיעה לא היה בה משפט מזיק היינו אומרים כי מיעט לכל משפטי שומר חנם הגם שלא הוזכרו אכן למה שאנו רואים כי מה שחייבו חכמינו ז''ל פושע הוא מדין מזיק אם כן מנין לנו להקל בדבר, ולזה כתב הרמב''ם שאין לפוטרו. ואם תאמר כיון שפושע דין מזיק יש לו אם כן בעל הבית שהדליק גדישו של שכיר או כסותו יהיה פטור שהרי פושע מזיק ופטר רחמנא. ואולי כי לא הקל הכתוב אלא בשומר. עוד נראה כי גם הרמב''ם יודה שאין לו דין מזיק ממש, ואם שרף כסותו המופקדת אצלו מהבעלים חייב עליה, ופושע כמזיק ולא מזיק ממש. ותמצא שכתב רמב''ם פכ''א מהלכות אישות האשה ששברה כלים בעת מלאכתה פטורה מתקנת חכמים עד כאן. הרי ששבירה בידים אינה פטורה אלא מתקנה, ומה שהקשו עליו אם כן יתחייב שבועה על הפשיעה, כתב רמב''ם פ''ד מהלכות שאלה ופקדון המפקיד אצל חבירו חנם ונגנב וכו' הרי זה נשבע וכו' אם לא שלח ידו וגו' ומגלגלין עליו שלא פשע עד כאן. משמע מדברי הרב כי עיקר שבועה דאורייתא אינה אלא שנגנבה ואינו ברשותו אבל שבועת שלא פשע מדין גלגול אנו באים עליה, ומעתה שבועת שלא פשע האמורה בשומר חנם תקנת חכמים הוא שלא אמרה תורה אלא שלא שלח, ולזה כל שישנה לשבועה של תורה גלגלו בה חכמים שבועת לא פשע וכל שאינה שבועת התורה שפטרתו פקע גלגול:
@587 **נמצינו** אומרים שלא בא המיעוט של ההקדשות הקרקעות וכו' אלא על שבועת שומר חנם שלא שלח ידו דוקא ואם יטענו שפשע בה יתחייב שבועת היסת כתקנת רב נחמן (ב''מ ה'.) ולפי זה מה שאמרו בסוף פרק החובל (ב''ק צ''ג.) בההוא ארנקי של צדקה שהפקידו רב יוסף אצל ההוא גברא נגנב וחייבו רב יוסף והקשה אביי לשמור ולא לחלק אם כן שסובר שממעט הכתוב אפילו מדין פושע כי התם שפושע היה ממה שחייבו לשלם והוא שומר חנם, לפי מה שכתבתי בפסוק לשמור כי דין זה דלחלק מסברא פטור הוא בלא מיעוטא דלשמור אלא דאסמכוה אקרא או שבא הכתוב לבל תטעה מדבריו לחייב אפילו לחלק, לזה שמר לך הסברא הנשמעת לך כי כל ממון שאין לו תובעים פטור הוא כי לכל אחד יאמר וגו' מה שאין כן דין פושע בממון שיש לו תובעים שהשכל נותן כי פושע מזיק הוא אם לא תהיה ראיה ברורה לפוטרו, כמבואר, כשלא בבעלים, בדינו עומד:
@589 **בין שניהם**. ירצה כי יש עונש לנשבע ולמשביע אם ידע שהוא רוצה לישבע לשקר ומסכים על הדבר:
@593 **אם בעליו עמו וגו'**. יש לנו לדון במשפט זה האם נשפטה בדין זה לעולם הבא כשיבוא בעל הפקדון הוא אדון העולם אשר הפקיד הנפש ביד האדם לשמור דכתיב (דבדים ד ט) ושמור נפשך מאד כשיבא לתבוע פקדונו מכל א' ונמצא נגנב או נשבר או נשבה או מת כי כל בחינת אלו ישנם מצויות בעוברי עבירה יש מי שנפשו נגנבת ממנו במקרה לא טהור ויש שהוא מזיד בעבירה ואבר מאברי הנשמה המיוחד כנגד המצוה שעבר עליה הוא נפגם ולפעמים בעשות עון מהכריתות ומיתות בית דין גורם מיתה לנפש כאומדו (בראשית יז יד) ונכדתה הנפש ולפעמים יגרום לה שביה על דרך אומרם (זהר ח''ב צ''ה:) הנפשות העשוקות וגו' ובעמוד בעל הפקדון ויטעון טענה הנשמעת תן לי הנפש כמו שנתתיה לך כאומרו (קהלת י''ב) והרוח תשוב אל האלהים אשד נתנה ודרשו ז''ל (שבת קנ''ב:) תנה לו כמו שנתנה לך האם יכולין הנפקדים ליפטר בטענת בעליו עמו, כי אמרו ז''ל (ב''מ צ''ז.) אפילו אמר לו השקיני מים ושאל ממנו חפצו הרי זה שאלה בבעלים והוא הדין כל השומרים, והן האדון קדם לזון ולכלכל מיום היות האדם והוא הנופח באף האדם נשמת חיים ומתעסק בצורכי אדם מלבד אשר יעשה לכללות העולם מחדש בכל יום מעשה בראשית לזה יקרא בעליו עמו מתחלה ועד סוף והרי שומרי הנפשות פטורים הגם שלא ישיבו הנפש כמו שנתנה:
@593 **ואומר** לנפש אדם אל תבטחי בעושק משפט זה כי לב' סיבות לא יפטר בטענה זו, האחד כי כאן פירש בפירוש שיתחייבו השומרים וכל תנאי שבשמירה קיים וכאומרם בהשוכר את הפועלים (ב''מ צ''ד.) מתנה בעל הפקדון על שומר חנם להיות חייב כשואל והטעם כי כל תנאי שבממון קיים והוא הדין שיכול להתנות המפקיד על השומר שיתחייב הגם שהוא בבעלים ואין זה מתנה על מה שכתוב בתורה בדרך זה כמובן מההיא דאמר שמואל במס' מכות (ג':) ע''מ שלא תשמטנו שביעית אין שביעית משמטתו, ואמרו ז''ל שהטעם הוא שכל תנאי שבממון קיים ובמציאות שלפנינו כאלו התנה בפירוש על הדבר ממה שקבע עונשין לכל העובר על הפקודים ועוד לו שהוסיף להשביעה על הדבר, ב' יש לך לדעת כי שופטי ארץ לא ישפטו כל החיובים אלא מעט מהרבה וכל המשפטים השופט כל הארץ ישפוט בצדק ומי יאמר כי הפושע בנכסי רעהו והוא בבעלים שלא ישפטהו השופט כמו שהוא שופט כמה וכמה שפטורין בדיני אדם וחייבים בדיני שמים וכו' וכמו שפירשתי למעלה בפסוק (כ''א י''ב) מות יומת כי לא לכל מחוייבי מיתה יצו ה' לשופטי ארץ להרוג וכו'. ותמצא כיוצא בזה שצוה ה' כי שומר חנם ושומד שכר ושואל פטורין בהקדשות ואפילו פשעו ואפילו לרמב''ם שחלק לחייב בפשיעה בקרקעות ועבדים נראה מדבריו כי יודה בהקדשות שפטור גם בפשיעה מטעם כי בא המיעוט בכל השומרים, וממנה אתה למד כי לא פטור ומותר הוא ואדרבה עונשו גדול הוא שזלזל נכסי שמים אלא שלא קבע ה' משפטו לדייני ארץ וסלק דינו לפניו. ויש עוד לאלוה מילין כפי פנימיות התורה ואין כאן מקומן:
@599 **וגר לא תונה וגו' כי גרים וגו'**. רש''י ז''ל פירש אף הוא יכול להונותך כי גרים וגו', ור''א פי' זכור כי הייתם כמותו, ורמב''ן דחה ב' הדרכים ופי' כי תדעו שאשמע צעקת דלים כאשר שמע צעקתך וגו':
@599 **ונראה** לו' על פי הקדמה הידועה כי נשמות בני ישראל הם שורש הקדושה בני אברהם יצחק ויעקב חבל נחלתו יתברך וכל זולתם הם חלק רע, ולזה לא יקפידו בזלזול אדם שאינו מהם ובאונאתו לצד שיחשבוהו שפחות הוא מהדרגות הקדושה ומזה יולד ענפי האונאה, לזה כאשר צוה עליהם לבל יונום ולא ילחצום אמר הטעם שאני מצוך לבל תונהו שאין לך לומר שהוא בחינת שורש הרע או כיון שהוא מוטבע בבחינת הקליפה הרי נגרע מערכך **כי אתם גרים הייתם במצרים** פירוש על דרך מה שפירשתי (ויגש מו ג) כי לגוי גדול אשימך שם ובפסוק (כ' ב') אשר הוצאתיך מארץ מצרים בפרשת יתרו שנשמות ישראל עצמם היו טבועות בקליפה ואם כן יהיה גר זה כאחד מכם באין הבדל ולזה לא תונהו ולא תלחצנו:
@601 **אם ענה תענה אותו**. צריך לדעת למה הוצרך לומר תיבת אותו ולא הספיק באומרו אם תענה וגו' והדבר ידוע שחוזר אל הסמוך. ונראה על פי מה שאמרו במכילתא בפסוק לא תענון אין לי אלא יתום ואלמנה שאר כל אדם מנין תלמוד לומר לא תענון עד כאן. וכפי זה יש אזהרה גם לשאר כל אדם מלא תענון לזה אמר הכתוב **אותו** פירוש אותו שמוזכר בפירוש הוא שעונשו נשיהם אלמנות ובניהם יתומים אבל המענה כל אדם אין עונשו כל כך:
@603 **אם כסף**. במכילתא רבי ישמעאל אומר כל אם שבמקרא רשות חוץ מזו וכו'. וצריך לדעת למה ידבר ה' בדרך ספק במקום ודאי. ואולי כי בא הכתוב להודיע ולהשיב גם כן לאשר ישאל השואל בראותו כי ירבה כבוד אדם בזהב לרוב ואוצרותיו מלאים הון עתק ללא צורך בו ויאמר אדם מה הנה אוצרות זהב לאדם ללא דבר למה לא הספיק ה' לתת לו מזונותיו הצריכין ולא יהיה זה גדול מיעקב אבינו אשר שאל (ברשית כח כ) לחם לאכול ובגד ללבוש, הן אמת כי מה שיחסר לאדם מכדי צורכו יש טעם בדבר ליסרו על עונו מה שאין כן אוצרות הון למה לאיש אין לו צורך בהם, לזה הודיע הכתוב כי הסובב דבר הוא אותם שאינם ראוים לקבל חקם לצד מעשיהם כי ה' בחסדו נותן שפע הצריך בריוח לכל איש ואיש די מחסורו והיה כי יחטא אדם ואינו ראוי לקבל פרנסתו בכבוד מאל הכבוד החלק המגיעו לא יטלנו עליון אלא הרי הוא מתקבץ אל מקום אחר ותהיה פרנסת הלז עם אדם אחר הבא לו דרך שם פרנסתו ויתפרנם בפחיתות ובביזוי כאשר גזר הגוזר בצדק. ויעשה ה' בדרך זה לב' מדות טובות הא' להשתלם אדם בעולם הזה פעלו הרע, והב' כדי שיזכה הנותן באמצעות נתינת צדקה וחסד לרעהו. וזה הוא אומרו **אם כסף תלוה את עמי** פירוש אם ראית שהיה לך כסף יתר על מה שאתה צריך לעצמך שאתה מלוה לעמי תדע לך שאין זה חלק המגיעך אלא חלק אחרים שהוא העני עמך, ובזה רמז כי צריך לפתוח לו משלו. ואולי כי רמז לו גם כן שלא יתנשא ויתגדל על העני בראותו כי הוא הנותן לו, והוא אומרו **לא תהיה לו כנושה** לשון נשיאות ומעלה כי משלו הוא נותן לו. וחזר לומר כנגד ההלואה **לא תשימון עליו** וגו':
@604 **אם חבול תחבול**. נראה כי ירמוז להעיר אדם הנרדם אשר בידו שלמת מי שאמר עליו הכתוב (משלי כ''ז) רעך ורעה אביך וגו' והנפש תתיחס לשלמה על דרך אומרם במסכת שבת (קנ''ב:) משל למלך שחלק בגדי מלכות וכו', וכבר פירשנו בו כי לצד שנפש אדם היא מאורו יתברך, שנאמר בו (תהלים קד) עוטה אור כשלמה, ויצו ה' אם משכנה בחובו שהם חטאיו יש לו זמן להשיבו עד בא השמש על דרך אומרו (תהלים צ) תשב אנוש עד דכא, ואמרו ז''ל (קהלת רבה פ''ב) עד דכדוכה של מות כי יש לו זמן תשובה עד ביאת שמשו. וטעם כפל **חבול תחבול**, דע כי כל אדם מישראל יש לו ג' בחינות נפש רוח נשמה וכאן רמז הכתוב על שלשתן, כנגד הנשמה אמר **אם חבול**, וכנגד הרוח אמר **תחבול**, וכנגד הנפש אמר **שלמת רעך**, וכנגדם אמר ג' חלוקות, א' כי היא **כסותה לבדה** היא הנשמה, ב' **היא שמלתו לעורו** והיא הרוח, ג' **במה ישכב** והיא הנפש אשר עמו בקבר וכאומרו (איוב י''ד) ונפשו עליו תאבל. ואומרו **והיה כי יצעק** פירוש חוזר לענין ראשון תשיבנו לו שהיא התשובה כי לא יצטרך לצער להשיבו אלא כי יצעק ישמע ה' וגו' ויעבור חטאתיו:
@611 **לא תהיה אחרי רבים וגו'**. רבותינו ז''ל הרבו לדרוש בפסוק זה אבל אין המקרא מתיישב לפי פשוטו. ונראה לפרש הכתוב לפי מה שאמרה התורה ושפטו העדה והצילו וגו', ואמרו ז''ל (סנהדרין ב'.) עדה שופטת ועדה מצלת אבל אם פתחו כולם לחובה פטור (שם י''ז.) ובא הכתוב כאן להסיר ב' מכשולין אשר יכשל בהם חכם מאמצעות דין זה, הא' בהגיע משפט כזה ויראה חכם אחד מהשופטים שכל חבריו פתחו לחובה והוא חושב בדעתו כי הוא זכאי ויתחכם לומר אם נאמר זכאי הנה הוא יצא חייב כי יש שם עדה שופטת ועדה מצלת ונמצאו דברי עושים הפך דעתי לזה אתחכם ואומר חייב שבזה תהיה סברתי מתקיימת שיצא זכאי מטעם פתחו כולם וכו', וגם אהיה מקיים המוסר לבטל דעתי לפני דעת המרובין שאומרים חייב ונאמר חייב עמהם, לזה בא הכתוב וצוה על זה בדיוק לבל עשותו ואמר **לא תהיה אחרי רבים לרעות** פירוש כשתהיה סובר סברא אחת שבאומרך דעתך יצא זה הנידון חייב בדינו וכגון שכולם אמרו חייב ואתה חושב זכאי לא תתחכם להיות אחרי רבים שאומרים חייב והוא אומרו **לרעות** ותאמר אתה כדעתם חייב הפך מה שנראה לך כדי שיצא זכאי כדעתך אלא אמור דעתך כפי מה שידעת במשפטי התורה ואין לך להתחכם על המשפט כי ה' הוא האלהים והוא שאמר פתחו כולם לחובה זכאי לא אמר ה' שיזכה זה אלא אם לך יראה חייב ולא שיראה לך זכאי שאז חייב הוא כמשפט האלהים:
@611 **עוד** יש מכשול ב' במשפט זה באופן אחר והוא אם יראה בעיני חכם שהוא חייב ככל הדיינים שאמרו חייב ורואה שאם יאמר חייב הנה הוא יוצא זכאי הפך דבריו שאומר חייב לזה יתחכם לומר זכאי כדי שיוטה המשפט אחרי רבים שאומרים חייב ויצא חייב כפי סברתו, ויש בזה גם כן כפיית ראש בגמר המשפט לנטות אחרי רבים, לזה אמר **ולא תענה על ריב** וגו' פירוש לא תענה מענה על ריב לנטות **אחרי רבים** פירוש שתהיה כוונתך במענך כדי שיהיה כמשפט יחיד ורבים וזה יגיד שאם יגלה דעתו כמות שהוא אין כאן הטייה אחרי רבים אלא כולם בדעת אחת. וביאר הכתוב טעם הקפדתו על הדבר ואמר **להטות** פירוש כשתהיה כוונתך להטות ממה שבדעתך בעיון משפט התורה שהוא חייב ואתה מטה לומר זכאי כדי שיצא חייב לנטות אחרי רבים ויצא חייב אלא אמור דעתך הגם שיצא זכאי הפך דעתך ה' זכהו. וטעם משפט זה לצד כי ה' יושב במסיבת הדיינים והוא ישפוט בפיהם וכשיראה משפט מרומה ואין בו מציאות לזכות הזכאי יתחכם לפתוח כולן לחובה וצוה שיצא זכאי בזה:
@612 **ודל לא תהדר בריבו**. ירמוז בתיבת **בריבו** על דרך אומרם ז''ל (ויק''ר פל''ד) כי העני עושה מריבה עם קונו למה זן לכל והוא ברעב ובעירום וכל הנותן פרוטה לעני ומפרנסו הרי זה משבית ריב עני מעל השמים ובזמן שאין חונן דלים טענת עני היא טענה הנשמעת ומהודרת, ולזה יצו ה' שלא יסובבו הידור לריב העני עם קונו אלא יחוננוהו כמשפט חונן דלים:
@615 **לא תטה משפט אביונך**. אולי שיצו ה' על משפט העניים על דרך אומרם ז''ל (ב''מ ע''א.) ענייך ועניי עירך וכו' עניי עירך ועניי עיר אחרת עניי עירך קודמין, ולזה בא המצוה כאן בלאו לבל יטה משפט הקדום לאחרו, והוא אומרו אביונך:
@616 **כי לא אצדיק רשע**. לדבריהם ז''ל (סנהדרין ל''ג:) שפירשו נקי זה מי שיש עליו מגיד זכות וצדיק זה מי שיצא צדיק בדינו ויש עליו מגיד חובה, יכוין הכתוב לומר טעם הדברים שלא תאמר איך אחר שנגמר דינו לחובה יחזור הדין לזכות, לזה אמר **כי לא אצדיק רשע** פירוש ממה נפשך אם מה שיצא חייב הוא כפי האמת והצדק לא אצדיק רשע ולא יועיל המלמד זכות, ואם מה שיצא חייב היה שלא כפי הדין למה יבולע נקי חנם. וכנגד חלוקת מי שיצא צדיק בדינו אמר גם כן **כי לא אצדיק רשע** פירוש כיון שיצא צדיק לא הצדקתיהו והוא רשע כי אלהים נצב בעדת אל ובקרב אלהים ישפוט והוא שופט בצדק ומן הנמנע שיחתום ה' על דבר שקר ח''ו. וצא ולמד אומרם ז''ל (כתובות כ''א:) דאסור למחתם על מלתא דמתחזי כשקרא. ואם תאמר ולמה אין אנו אומרים כן ביצא חייב, יש לך לדעת כי ה' ינחם על הרעה ולא ינחם על הטובה ומי שיצא חייב חזר בו ה' לזכותו אבל מי שיצא זכאי לא ינחם ה' מהטובה, ולפעמים יספיק לאדם זה עינוי זה שיצא משפטו חייב ואימות מות יגיעוהו בראותו כי נגמר דינו למות, ולזה אחר כך בקרב אלהים ישפוט לזכותו:
@618 **ואתם ידעתם את נפש וגו** '. עיין מה שכתבתי בפסוק (כ''ב כ') וגר לא תונה ופסוק זה יצדיק לך כל מה שכתבתי לך:
@619 **ושש שנים וגו'**. סמך מצוה זו למה שלפניה לומר כדי שלא תטעמו טעם גרות עוד על דרך אומרו (ויקרא כו לד) אז תרצה הארץ את שבתותיה וגו':
@621 **תעשה מעשיך**. ולא כל מעשיך כמו שאמר בעשרת הדברות כי בששת ימים של שנת השמיטה שעליה חוזר צווי שבת כאן אינו יכול לעשות כל מלאכתו כי מלאכת אדמה אסורה לו כאמור בסמוך:
@622 **ובכל אשר אמרתי וגו'**. טעם אומרו **ובכל** וגו' **תשמרו** ולא אמר וכל אשר וגו' תשמרו, יכוין לומר על דרך אומרם ז''ל (מכות כ''ג:) כי מנין מצות עשה הם רמ''ח כנגד רמ''ח אברים של אדם ושס''ה לא תעשה הם כנגד שס''ה גידיו (זהר ח''א ק''ע:) והוא מה שרמז שלא יאמר אדם אקיים כך וכך מצות ויספיקו לשמירתי, לזה אמר **ובכל אשר** וגו' פירוש בכל המצות תהיו נשמרים ובחסרון אחד מהם תחסר השמירה לאותו אבר המכוון לה:
@622 **ושם אלהים וגו'**. בא לומר כשם ששמירת כל המצות תועיל לכל אדם למנין אבריו ושס''ה גידיו כמו כן יש שמירה לכללות האדם בכפירת עבודה זרה שכל הכופר בעבודה זרה כמודה בכל התורה ויחזק בשומר ועושה כל אשר תמצא ידו עשות ויהיו נשמרים באמצעות כפירת עבודה זרה כל איבריו וגידיו הגם שלא עשה המצוה ההיא ולא באה לידו העבירה ונשמר ממנה ודוקא מן הסתם אבל אם מבטל להדיא קצת מהמצות לא יהיה נשמר באותו אבר המכוון לאותה מצוה שמבטל לצד כפירתו בעבודה זרה:
@624 **כאשר צויתיך**. לפי שיש הרבה פרטי מצות שלא נתפרשו כאן, הא' שצריך להיות מצה מדבר הבא לידי חימוץ (פסחים ל''ה:), ב' שלא יצא ידי חובתו במעשה קדרה, ג' שלא יהיה חמץ מיום טוב ראשון וכל זה מפורש בפרשת בא כמבואר במכילתא לזה אמר **כאשר צויתיך** לרמוז לתנאי המצוה הנזכרים:
@625 **בכורי מעשיך**. פירוש למעט דעייל ביד גוי שאינו מעשיו וכמו שמיעט באומרו קצירכם כמו שדרשו בר''ה (י''ג.) שכל שהביאה שליש ביד גוי לא יביא ממנה בכורים:
@628 **ראשית בכורי וגו'**. אולי שירמוז שלא ישחית זרעו ושתהיה טיפה ראשונה שתצא ממנו מובאת בית ה' על דרך אומרם (יומא ב'.) ביתו זו אשתו, ודייק לומר **בית ה'** לשלול בית אשה זונה, והוא מצוה שקיים יעקב אבינו עליו השלום דכתיב (בראשית מט) כחי וראשית אוני, וגמר אומרו **לא תבשל גדי בחלב אמו** לרמוז סוד גדול כי המשחיתים זרעם סובבים מיתת הקטנים מבין שדי אמם, וכמו שפירש הדבר באומרו בפסוק (מיכה ו') האתן בכורי פשעי פרי בטני חטאת נפשי כי כשאדם משחית זרעו נברא ממנו משחית רע והוא שולט אחר כך בבן היולד, והם נפשות העשוקות כאמור בספר הזוה''ק (ח''א רי''ט.), ומי גרם זה שלא הביא בכוריו בית ה', וכפי דרך הפשט טעם סמך **לא תבשל** וגו' עם הביכורים, להאומר (חולין קי''ד:) בשר בחלב אסור בהנאה שהוא עיקר ההלכה נתכוין לסומכו עם הביכורים להיות שהם אסורים בהנאה, (רמב''ם פ''ב) ועיין בספרי פרי תואר:
@629 **הנה אנכי וגו'**. פירוש מלאך זה הוא המלאך הגואל את האבות לא משרת ממשרתיו אלא מלאך גדול כידוע למשכילים כי אין אנו מכידים מלאך אמצעי אלא הוא יתברך ושכינת עוזו המתיחדת עמו בסוד (זכרי' יא) ה' אחד ושמו אחד:
@630 **השמר מפניו וגו'**. כאן צוה על מצות עשה ומצות לא תעשה, כנגד מצות לא תעשה אמר **השמר** וגו' כי כל השמר וגו' לא תעשה, וכנגד מצות עשה אמר **ושמע בקולו**:
@630 **אל תמר בו**. כאן רמז לפעולת האדם אשר תסובב תמורת טוב ברע ועבד מולך ושפחה יורשת גבירתה, ועל ידי זה יתנקם נקם מהעושה תמורה ולא ישא לפשעכם, גם מלאך זה ידוע הוא כי הוא בחינת המשפט ולא ישא עון כאומרו **לא ישא** וגו', ואומרו **כי שמי בקרבו** השכילו בדבר הזה כי באמצעות חטא האדם יסובב פרידת אלוף מקרבו. ואשכילך כי מטט''רון הקדוש אמרו ז''ל (סנהדרין ל''ח:) שמו כשם רבו והוא שדי כי עולה מספר עצמו של השם ובחטא האדם יסתלק שם שדי ממנו, והוא סוד אומרו (ישעי' י''ט) ונהר יחרב וגו' והשכיל לב משכיל בדברים באומרו **כי אם שמוע תשמע בקולו** כמדבר על זולת וגמר אומרו **ועשית את אשר אדבר** ולא אמר אשר ידבר לומר כי שמי בקרבו והבן:
@631 **ואיבתי וגו'**. אולי שירמוז כי באמצעות עסק התורה והמצוה הנה האדון יעקר שורש הקליפה וענפיה שהם המסיתים והמדיחים והמבקשים להשפיל דגל התורה, ועיין מה שפירשתי בפרשת בראשית במעשה קין בהתווכחות האדון עמו:
@632 **והביאך וגו' והכחדתיו**. יכוין כי באמצעות הכנסת ישראל יהיו נכחדים האומות ההם, ועיין מה שפירשתי בפסוק (במדבר יד ט) סר צלם וגו' וה' אתנו וגו' כי הקדושה תשאוב חלק המחיה ותשאר כפגר מובס, והוא סוד אומרם ז''ל (שבת ל''ד.) יהיב עיניה ביה ונעשה גל של עצמות כי יברר וישאוב חלק המחיה ממקום תחנותו:
@633 **לא תשתחוה וגו'**. צריך לדעת למה הוצרך לצוות לזה אחר שהזהיר כמה אזהרות על כיעור זה ועל הדומה לו ומה גם שבסמוך למעלה הזהיר אפילו על בל ישא את שמותם על שפתיו ולא לגרום שיזכרו שמם הזולת דכתיב (פסוק י''ג) ולא ישמע על פיך אם כן מה מקום להזהיר עוד על העבודה. ורמב''ן יישב כי להיותה חמורה ירבה בה האזהרות, ומן התימה הוא שאחר שהשווה אותה לכל התורה כולה כאמור למעלה בין לענין עונש בין לעגין שכר הנה העובדה עובר על תרי''ג אזהרות ומה גם שיש מצות שיש בהם ב' לאוין ויותר ומצוה זו שקולה כנגד הכל:
@633 **ונראה** לומר כי טעם הכתוב הוא לג' סבות, האחד להיות שרצה להזהיר שלא ידמה להאומות במעשיהם לזה אם לא היה מקדים לומר לא תשתחוה ולא תעבדם לא יעלה על דעת אנוש לומר שיכוין הכתוב לומר על מעשה חול שאין בו עבודה זרה שאסור ובהכרח לומר שאינו אומר אלא על מעשה איסור שהוא עבודה זרה אך אחר שאמר **לא תשתחוה ולא תעבדם** בזה גילה דעתו כי מה שאמר **לא תעשה כמעשיהם** הוא אפילו דבר שאינו ניכר שיש בו עבודה זרה והוא שלא ידמה להם לא במלבושיהם ולא בתגלחתם כלל, וכאן נכלל כל שהוא מיוחד למעשה הגוים כאמור בדבריהם ז''ל (שבת ס''ז.), והב' להודיענו בא כי כל מעשיהם יש בו עבודה זרה כי ה' יודע מחשבות בני אדם ויסוד כל דבר ואם כן כל העושה מעשה גוים הרי זה טועם מעון עבודה זרה, והג' להיות שרצה לצוות על הריסתם ושברונם לזה קדם לומר **לא תשתחוה** וגו' לומר שאם לא הרס ולא שיבר הנה הוא כעובד עבודה זרה כי ה' תופס על המחשבה בעבודה זרה וצריכין היכר לשלילת מחשבת עבודה זרה מלבם ואין היכר אלא בשבר מצבותיהם ואם לא יעשו כן הרי הם כעובדי עבודה זרה וזה לך האות, ולזה הוצרך לומר **לא תשתחוה ולא תעבדם** וגו' כי הרס לומר שבהעדר הרס הנה הוא עובר על לא תעבדם. ותמצא שהקפיד ה' על ישראל שלא עשו כן בכניסתם לארץ (שופטים ב'):
@634 **ועבדתם את ה'**. אולי שהוא נמשך עם מה שלמעלה כי כשישבר כח העבודה זרה ויהרוס מבצריה בזה עובד את ה' וישפיע לו טובה ויברך לחמו. ואומרו **ואת מימיך** פירוש להיות שמהמים יולד הכחישות ותולדות החולאים וליחות הרעות לזה הבטיח שיברך מימיו שיצמחו צמח האדם בתכלית הבריאות כידוע למשכילים בהבחנת המימות כי אחרי מים חיים ישוטט האדם לשכון שם והבטחה גדולה הבטיח הבורא ברוך הוא בזה, ולזה סמך לברכת המים ולא תהיה משכלה וגו', וצא ולמד מה שדרשו ז''ל (ברכות נ''ט:) במי פרת:
@634 **והסירותי וגו'**. רשם ה' הבחנת הברכה בשלשה דברים, הא' שיהיה האדם בריא להתעדן בטוב ה'. והוא אומרו **והסירותי** וגו' שזולת זה כל אוכל תתעב נפשם, ב' ירבה לו בנים, והוא אומרו **לא תהיה משכלה** וגו', ג' שישלים ימיו אורך ימים ושנות חיים, והוא אומרו **את מספר ימיך** וגו'. גם בזה הראה ה' הפלגת הברכה כי זולת ג' דברים אלו אין היכר לברכה. שאם היו האוכלים מועטים ומשוללי הבריאות ושנים מועטות כל שהוא שיתן ה' יספיק לספוק צרכם ונמצא בירך לחמו ומימיו ואין בהבטחה זו דבר גדול אלא באמצעות ג' דברים אלו:
@636 **את אימתי וגו'**. הגם שאמר למעלה (פסוק כ''ג) והכחדתיו כאן גילה כי בתחלה לא לכל יכחיד אלא עד שיפרה יוסיף ה' להום את העם הצריך ישראל לארצו וכן על זה הדרך יהיו כובשים והולכים וכמו שגילה לבסוף באומרו **לא אגרשנו** וגו' עד אשר תפרה ותנחל הכל:
@641 **לא תכרות וגו**. קשה אם כבר צוה שיהרסו וישברו אותם מה מקום לצוות על כריתת ברית עמהם, ועוד איך יוצדק לכרות ברית לאלהיהן, ואם על עבודת עבודה זרה הוא אומר מאי איריא בכריתת ברית:
@641 **אכן** כוונת הכתוב הוא לומר שאין אוסר כריתת ברית עם האומות אלא כל עוד שהם ואלהיהן עמהם אבל אם כפרו באלהיהן אין איסור לזה אמר **לא תכרות להם ולאלהיהם** פירוש כשיהיו להם אלהיהן ברית. ונתכוון גם לומר כי הכורת ברית לעובד עבודה זרה כאלו כרת ברית לעבודה זרה עצמה מב' טעמים. האחד כי סופו ליכשל כמאמר הסמוך פן יחטיאו וגו' כי תעבוד. והב' כי בחינת העבודה זרה תתלבש בעובדיה ובזה נמצא שכורת ברית גם לאלהיהן רחמנא ליצלן, ואין לומר כי לזה לבד נתכוין שאם כן היה לו לומר לא תכרות להם ברית ולאלהיהן ואז היינו אומרים שהכוונה היא אם כרת להם ברית מעלה עליו הכתוב כאלו וכו', אכן מאומרו הזכרת הברית אחר הזכרת אלהיהן יגיד גם מה שפירשנו שלא אסר אלא בזמן שלא קבל שלא לעבוד עבודה זרה אבל אם אין לו אלוה מותר לכרות לו ברית כמו שכרתו ברית לגבעונים. וטעם שהקפידו ישראל אחר כך, לצד שאמרו ז''ל (ירושלמי שביעית פ''ו) שמתחלה היו מהמורדים בישראל בשליחות אגרת יהושע ונתחייבו כליה כמצות המלך לא תחיה כל נשמה:
@642 **פן יחטיאו אותך לי**. כאן גילה האדון כי החסרון נוגע לבורא. והשכלת הדברים היא כי ישראל להיותם בחינת הקדושה בעת אשר יעבדו עבודה זרה הנה הם גורעים מערך קודש ונחסרים משורשם ונמצא החסרון נוגע לשורש הקדושה:
@642 **כי** יהיה לך למוקש וגו'. פירוש נתן טעם מנין יעלה על הדעת שיחשדו ישראל על זה להמיר כבודם בלא יועיל, לזה הודיע כי העבודה זרה מטעה את עובדיה לינקש אחריה, כאומרם ז''ל (ע''ז נ''ה.) שיש עבודה זרה שמגלה מצפונות ומטמונות ומגדת עתידות ולזה חש ה' על בניו לבל ינקשו:
@643 **ואל משה וגו'**. משמעות הכתובים יגיד כי פרשה זו במקומה נאמרה אחר מתן תורה ואין להאריך בכיתי הוכחות המעידים על הדבר, וכן ראיתי לראב''ע ורשב''ם ורמב''ן שיחדיו היו תמים בדעת זו:
@643 **אלא** שראיתי במכילתא סברא באין חולק עליה כי ביום ה' בחודש שהיתה הפסקה בנה משה מזבח האמור בפרשת המשפטים וכרת עמהם הברית על כמה מהמצות אשר כבר קבלום עליהם למר על ז' מצות ולמר על מה שנצטוו במרה, ויש מרבותינו שאמרו שם שעל מצות הנאמרות בפרשת בהר סיני עד סוף אם בחקותי, ומשמע מדבריו כי אלו קדמו קודם מתן תורה ועליהם כרת ברית האמור לפי שלא כרתו ברית עד עתה על שום קבלת מצוה ובחן אותם משה אם מעצמן יקיימו עליהם הברית על מה שעבר הגם שלא חייבם ה' עליו. ואולי כי דבר משה כן לצד שרמזו ה' באומרו (לעיל י''ט ג') ותגיד לבני ישראל ודרשו ז''ל (שבת פ''ז.) שנתכוון לומר לו משוך אותם בדברי אגדה וגם זה מכלל המשכת הלב שמעצמם ישבעו על הראשונות. גם מסוגיית הגמ' (שם פ''ח.) שאמרו שהקדימו ישראל נעשה לנשמע כשבא משה אליהם וירדו ס' ריבוא מלאכים וקשרו להם ב' כתרים וכו' זה יגיד שקודם מתן תורה היתה פרשה זו:
@653 **ואל אצילי וגו'**. צריך לדעת למה הוצרך לומר ואל אצילי ולא הספיק לומר ולא שלח בהם ידו והדבר מובן שעל הזקנים וגו' המוזכרים בסמוך הוא אומר. ואולי כי טעם הוא נותן למה לא שלח ידו לצד שהיו אצילי פירוש גדולי ישראל ואילו עשו כן זולתם היה שולח ידו. או על דרך אומרם ז''ל (במד''ר פט''ו) שלא רצה לערבב השמחה כי כל ישראל יתאבלו עליהם לצד היותם גדוליהם ואציליהם לזה לא שלח ידו:
@653 **לא שלח וגו' ויאכלו וגו'**. קשה למה חזר לו' פעם ב' **ויחזו** וגו' ולא הספיק מה שקדם באומרו ויראו את וגו' והנה רבותינו ז''ל (ויק''ר פ''כ) אמרו כי נתכוין לו' כי על ידי מחזה שדי נהנו והרגישו הבריאות והשובע כאיש אכל ושתה. ועדיין קשה למה הפסיק הכתוב באמצע הענין במאמר לא שלח ידו כי מן הראוי היה לו להקדים לו' מעשיהם בשלימות ואחר כך אריכות אפים שהאריך ה' להם ולא הרגם מיד על זה הדרך ויראו את אלהי ישראל וגו' ויחזו את האלהים ויאכלו וגו' ואל אצילו בני ישראל. וגם לא היה צריך לכתוב פעם ב' ויחזו וגו' והיה מספיק במה שהתחיל לומר ויראו את אלהי ישראל וגו' לטוהר ויאכלו וגו' ודרשת חכמינו ז''ל לא זזה ממקומה:
@653 **ואולי** שכוונת הכתוב על דרך אומרו (לקמן ל''ג כ''ג) והסירותי את כפי וראית וגו' הרי כי ה' יעשה הבדלה בידו לנבראים מהביט אל האלהים ואפילו למשה כשנגלה אליו בגלוי שכינה שם כפו עליו פירוש בחינה המפסקת לבל יסתכל, וכאן הודיע הכתוב כי לאצילי ישראל לא שלח ידו למנוע מהם המחזה לצד היותם חשובים בעיניו והניחם לזון עיניהם מאורו יתברך. וזה הוא שיעור הכתוב **ויראו את אלהי ישראל** פירוש ראו אור גדול של אלהי ישראל אבל לא נסתכלו אלא תחת רגליו ואחר כך לצד שלא שלח ה' ידו פירוש כחו ורשיונו למנוע מהם ובזה היה להם כח לחזות בנועם ה' ונהנו זו אכילה זו שתיה ושבעה בטוב נפשם, ולא יקשה למה למשה שם כפו עליו ומנעו מהביט ולאצילי ישראל לא שלח ידו כי מה שהוצרך ה' לשום כפו על משה לא לשלול ממנו השגה שהשיגו אצילי ישראל כי השגה זו היתה למשה בתמידות אלא להביט בהשגה מופלאת אשרי כל מחזה עליון יחזה. ויש עוד לאלוה מילין בפירושן של דברים ושומר אני עצמי מהעלות על ספר דברים היושבים בסתר עליון לבל יהנו מהם מי שאינו ראוי לאור באור החיים:
@653 **חסלת פרשת משפטים**
@662 **דבר אל בני ישראל**. צריך לדעת למה לא הספיק במה שקדם לומר **לאמר** והדבר מובן שלבני ישראל יאמר. או לא היה צריך לומר לאמר ויספיק באומרו דבר אל בני ישראל. ונראה לי על דרך מה שאמרו ז''ל (יומא ד':) מנין שהאומר דבר לחבירו שהוא בבל תאמר שנאמר וידבר ה' אל משה לאמר. ועל פי הדברים האלה יצטרך לומר דבר אל בני ישראל שאם לא כן יחשוב משה כי לא בא אלא לתת רשות שאין זה בבל תאמר חובה מנין תלמוד לומר דבר וגו'. ולדרך זה תמצא מרגוע לנפשך בכל התורה כולה שאמר הכתוב לאמר וחזר לומר דבר, כי בכל מצוה צריך לומר לו לאמר ודבר ובאחת מהנה לא יהיה נשמע שחובה עליו הם הדברים לאומרם להם אלא רשות, ורבותינו ז''ל (ילקוט הראובני) דרשו דבר אל בני ישראל שלא ימנה עליהם מערב רב ודורשים לשון דברות ושררה. עוד יתבאר בסמוך באופן אחר:
@662 **ויקחו לי**. צריך לדעת למה כתב וא''ו בתחלת ענין. ואולי שירצה על דרך אומרם ז''ל (שקלים פ''א מ''ג) ממשכנין על השקלים, ואמרו ז''ל (תנחומא) כי ג' תרומות שנו כאן ב' מהם שקלים בקע לגלגולת אחת לאדנים ואחת לקרבנות צבור והג' נדבת המשכן עד כאן. וכפי זה נתכוון באומרו **ויקחו** כנגד נדבת השקלים הרמוזה בתרומה הסמוכה לה לומר שישנו בכפייה לשקול, וסמך תיבת **ויקחו אל** בני ישראל לרמוז שבשקלים מדבר הכתוב שאינם שוקלים אלא בני ישראל ולא בנות ישראל דכתיב (לקמן ל' י''ג) כל העובר וגו'. ולפי זה אומרו **מאת כל איש** פירוש שהלקיחה תהיה בהשואה מאת כל איש ואפילו את אשר ידבנו לבו תהיה לקיחה שוה מכולם ולא ירבה הנדיב ולא ימעיט הכילי. ועוד ירצה בתוספת וא''ו לרמוז שכבר קדם דבר אחר והוא נדבת לב כרמוז בסוף דבריו שאמר **אשר ידבנו לבו**, ולדרך זה ידבר הכתוב גם בתרומת המשכן ויחפוץ ה' שכל נדבה תהיה מלב ולא תהיה הנתינה עד שתקדם הנדבה בלב:
@662 **עוד** נראה לפרש הכתוב על פי מה שאמרו במסכת בבא בתרא (ח':) קופה נגבית בב' ומתחלקת בג' נגבית בב' לפי שאין עושין שררות על הציבור פחות מב' ואמרו שם מנא הני מילי אמר קרא (לקמן כ''ח ה') והם יקחו ומאי שררות שממשכנים על הצדקה אם אמוד הוא עד כאן. והעלו שם התוספת והר''ן כי ב' שאמרו דוקא בדבר הקצוב אבל שאינו קצוב צריך ג'. ודע כי לענין דין אפילו יחיד אם הוא מומחה יכוף אדם בעל כרחו לדון אותו יחידי כדתניא (סנהדרין ה') אם היה יחיד מומחה לרבים כו' הרי זה דן יחידי, וכתבו התוספת שם ויכול לכוף את האדם בעל כרחו דאי בדקבליה וכו'. ומכאן אני למד שהוא הדין וכל שכן הוא שיכול להנהיג שררות יחידי ואינו צריך ב', ומה משפט הצריך ג' דן וכייף שררות שמספיק בב' לא כל שכן. ובזה נשכיל ביאור הכתוב אומרו **דבר אל בני ישראל** אין פירוש לשון דבור אלא לשון שררות ודברות לומר כי הוא לבדו יכול לעשות ב' משפטים שישנם בענין הא' היא ההערכה, והב' היא השררות, שהגם שההערכה צריך ג' והשררה צריכה ב' כנזכר אתה לבדך תהיה דבר על הדבר לצד שאתה יחיד מומחה תספיק במקום ג' ואין צריך למור במקום ב' לענין השררות, ודוקא אתה אבל הזולת **ויקחו** לשון רבים. ותמצא שכן היה דכתיב (לקמן ל''ו ג') ויקחו מלפני משה הרי כי משה לבדו קבל הנדבה בין דבר שיש בו קצבה בין דבר שאין בו קצבה. והגם שבתלמוד דרשו מפסוק (לקמן כ''ח ה') והם יקחו, אולי כי שם חדש לענין השררות שצריכה ב' וכאן לענין פרט לקיחת דבר שאין בו קצבה שלא נתן רשות לעשות הדבר ביחיד אלא למשה אבל הזולת צריך רבים. ולדרך זה יתיישב אומרו **ויקחו** בתוספת וא''ו לצד שקדם ואמר דברותו של משה לזה יוצדק לומר אחר כך ויקחו:
@662 **מאת כל איש וגו'**. אולי שיכוין לומר כי באיש שיודעים בו שהוא נדיב לב לא יכניסוהו במשפט ההערכה לדעת מה יקבלו ממנו כיון שהוא מוחזק כי לבו נדיב יקחו ממנו את אשר יביא כי ודאי שיודע הוא עצמו שזה הוא יכלתו ואת זו אצדיק שהוא תרומתי הצריך לתת כאומרו **את תרומתי**. עוד ירצה לומר שאינה חשובה ליקראות תרומתי אלא המובא מנדבת לב האדם, והוא אומרו **מאת אשר** וגו' **תקחו את תרומתי**, אבל המעושה לא קראה תרומתי אלא תרומה דכתיב ויקחו לי תרומה. עוד נראה בדקדוק אומרו ג' ריבויים אלו **מאת כל איש** שלא היה לו לומר אלא מאשר ידבנו וגו', ואולי שנתכוין הכתוב לרבות ג' פרטים שישנם בהדרגה משונה בדין הצדקות מכל ישראל והם היתומים והנשים והשוע, היתומים כמו שאמרו במסכת בבא בתרא (ח'.) אין פוסקים צדקה על היתומים ואם לעשות להם שם מותר, הנשים כמו שאמרו בסוף מסכת בבא (קי''ט) שאין לוקחים מהנשים אלא דבר מועט, ואמרו עוד שם כי מועט ומרובה הוא לפי ערך מה שהם הנשים וכמעשה רבינא שלקח שרשרות זהב מהם ואמר כי בערך בני מחוזא דבר מועט הוא, שוע כמו שאמרו בבבא בתרא (שם) שאסור לגבאי צדקה לתובעו ולגבות ממנו וכו' וכמעשה הובא שם (תענית כ''ד.) עוד שהיו נשמטים הגבאים מהתראות לפניו לבל יהיה מצר לעצמו ויתן מה שאין בו כח ליתן. והנה בנדבת המשכן אמר ה' למשה שיקח מהג' הנזכרים, והוא מה שריבה בג' הריבויים יתומים נשים שוע, **את** לרבות הנשים, **כל** לרבות היתומים, **איש אשר ידבנו לבו** זה שוע כמשמעו שמשלשתם יקח אפילו דבר גדול:
@662 **ויש** טעם בדבר על פי דבריהם ז''ל (תנחומא) שאמרו כי המשכן הוא כפרה על מעשה העגל, עוד אמרו (שמו''ר פל''ג) וזה לשונם אמר משה לפני ה' וכי ישראל יכולין לבנות משכן אמר לו מהקטן שבהם כו' כי המן היה מוריד לישראל אבנים טובות ומרגליות עד כאן. וגם אמרו (תנחומא) כי מביזת מצרים נטלו קטן שבכולם משא מ' חמורים כסף וזהב ואבנים טובות וכו'. ואמרו (שהש''ר פס' תורי זהב) עוד שביזת הים גדולה מביזת מצרים, הרי שהיה לישראל עושר מופלג, ולפי זה יש טעם נכון לשלשתם כי לא אמרו אין לוקחים מהיתומים אלא במקום שאין בו שם ולא כפרה אבל במקום שיש אחד מהם כמשכן לוקחים מהם, והנשים גם כן במקום כפרה לוקחים מהם, ועוד שהגם שיתנו דבר גדול בערך עושרם המופלג דבר קטן יחשב, והשוע גם כן לצד רוב העושר לא יעשה בו רושם כל מה שיתן לנדבת המשכן אפילו יתן כל הצריך למשכן, ודקדק לומר **תקחו את תרומתי** לומר שלא התיר לקחת מהדרגות הנזכרים מאת כל איש וגו' אלא את תרומתי שהיא תרומת המשכן לטעמים שפירשנו. ובדרך רמז ירצה שיכוין כל אחד לדבק בה' בחינת נפשו הנקראת תרומה באמצעות המעשה, והוא אומרו **ויקחו לי תרומה** כי הנפש של ישראל תקרא תרומה דכתיב (ירמי' ב') קדש ישראל לה' ראשית תבואתו ותרומה נקראת ראשית ובאמצעות לקיחת מאת כל איש וגו' ישיגו שתשרה עליהם השכינה, והוא אומרו **תקחו את תרומתי** כי השכינה תקרא תרומת ה' והמשכיל יבין:
@663 **וזאת התרומה וגו'**. טעם אומרו **וזאת** וגו', אולי שיכוין לומר שלא יביאו ישראל נדבה ממין א' או מג' אלא צריכין להביא מכל המינים ואינם יוצאים ידי חובת תרומת המשכן אלא בהבאתם מכל המינים, והוא אומרו וזאת לומר מלבד חיוב ההבאה עוד אני מצוה שתהיה התרומה ממינים אלו כולם, והטעם כי אין הכנת המשכן מושלמת בחסרון אחד מהמינים, ואין הכונה כי כל איש ואיש מישראל יביא מכלן אלא שבכללות תרומת כל ישראל יהיו כל המינים. או ירצה לומר שיקבלו מהמביאים כל הי''ג מינים ולא יזלזל במביא פשתן ועורות וכו':
@667 **אבני שהם וגו'**. צריך לדעת למה כתב **אבני שוהם ואבני מלואים** בסדר אחר כל הי''א מינים ומן הראוי היה לו לסדרם קודם זהב וכסף כי הם מעולים מהם. ואולי כי לצד שמצינו שהנשיאים הביאו אותם באחרונה כשראו שהביאו ישראל כל הצורך למשכן, ותמצא שאמרו ז''ל (במד''ר פי''ב) שהקפיד ה' על זה וחסר אות אחת מהם והנשאם כתיב, לזה סדרם ה' באחרונה לומר כי הם למטה מכולם, ומהטעם עצמו שהם באחרונה והבן:
@667 **עוד** נראה לומר על פי מה שאמרו ביומא פרק בא לו (ס''ט.) שבגדי כהונה מותרים ליהנות מהם ומשמע שאין מועלין בהם. ושוב ראיתי לרמב''ם שכתב כן בפ''ה מהלכות מעילה, ולפי זה בגדי כהונה אינם בהשואה עם כלי המשכן ועבודתו שכולן קדושתן למעלה מבגדי כהונה ומועלין בהם ומעתה בדין הוא לסדר באחרונה אבני שהם ואבני מלואים אחר כל הי''א דברים לצד שכל י''א הדברים כולם הם צורכי המשכן ועבודתו מה שאין כן האבנים שאינם אלא לבגדי כהונה, והגם שבהי''א דברים יש גם כן בקצת מהם שהם לצורכי בגדי כהונה אף על פי כן אין לך מין ומין מהי''א שאין בו צורכי משכן ועבודתו מה שאין כן האבנים שאינם אלא לבגדי כהונה. עוד נראה על פי דבריהם ז''ל שאמרו ביומא (ע''ה.) שהעננים היו מביאים את אבני השוהם וכו' אם כן משלחן גבוה היו מביאים בלא טורח ויגיעה ולא חסרון כיס אשר על כרחו סדר נדבתם אחר כל הנדבות שמביאין מכיסם ועל ידי טודח:
@668 **ועשו לי מקדש וגו'**. צריך לדעת למה קראו **מקדש** ותיכף חזר בו וקראו משכן דכתיב **את תבנית המשכן**. ונראה כי אומרו **ועשו לי מקדש** היא מצות עשה כוללת כל הזמנים בין במדבר בין בכניסתן לארץ בכל זמן שיהיו ישראל שם לדורות, וצריכין היו ישראל לעשות כן אפילו בגליות אלא שמצינו שאסר ה' כל המקומות מעת שנבנה בית המקדש כאומרו (דברים י''ב ט') כי לא באתם עד עתה אל המנוחה ואל הנחלה, ולזה לא אמר ועשו משכן שיהיה נשמע שעל אותו זמן לבד נאמרה מצוה זו. ואחר שצוה דרך כלל אמר פרט הנעשה במדבר שאינו מקום לבנות בו בנין אבנים שיעשה משכן כסדר האמור. ותמצא שכתב רמב''ם בפ''א מהלכות בית הבחירה מצות עשה לעשות בית לה' דכתיב ועשו לי מקדש עד כאן, וטעמו הוא משינוי הלשון כמו שכתבנו. עוד ירצה באומרו **ועשו לי מקדש** כי מעת שעושים אותו לשמו יתברך כאומרו לי הגם שעדיין לא שרתה בו שכינה הרי הוא מקדש ודין קודש יש לו:
@668 **ושכנתי בתוכם**. ולא אמר בתוכו לומר שהמקום אשר יקדישו לשכנו יהיה בתוך בני ישראל שיקיפו המשכן בד' דגלים. ואולי כי דברים אלו הם תשובה למה שחשקו ישראל (במד''ר פ''ב) בראותם בהר סיני שהיה ברוך הוא מוקף בדגלי המלאכים והוא אות בתוכם וחשקו אהב להיות כן בתוכם, ולזה באה התשובה מבוחן לבות ואמר **ועשו לי מקדש ושכנתי** כמו כן **בתוכם**:
@669 **ככל אשר וגו'**. בפסיקתא (רבתי ט''ז) אמרו כשאמר ה' למשה ועשו לי וגו' נבהל משה ואמר לפניו הלא השמים ושמי השמים לא יכלכלוהו וגו' עד שאמר לו הקדוש ברוך הוא לא כמו שאתה סובר אלא כ' קרשים וכו' עד כאן. וצריך לדעת מי עמד בסוד ה' ומשה עבדו לדעת כל הדברים שעברו ביניהם, והגם שכל דבריהם דברי קבלה הם עם כל זה לא יבצר דבר מהכתובים. ונראה לומר לדבריהם ז''ל שהוקשה להם שאין משמעות לכתוב ממה נפשך אם הוא נמשך למטה על זה הדרך ככל אשר וגו' תעשו לא היה לו לומר וכן בתוספת וא''ו אלא כן תעשו שהיא גזרת תחלת מה שאמר ככל אשר וגו', ואם אומרו ככל חוזר לאומרו ועשו לי מקדש לא היה לו להפסיק באומרו ושכנתי בתוכם אלא היה לו לומר ועשו לי מקדש ככל אשר וגו' ואחר כך יאמר ושכנתי וגו', וממה שהקדים לומר ושכנתי גילה ה' כי גמר מאמר כללות המצוה ולא הוצרך לומר בה ככל וגו' וסמך על מה שיודיענו כל פרטי המעשה שיעור הקרשים וכל הכלים כמו שאמר אחר כך, וממה שאנו רואים שנמלך אחר כך לומר ככל וגו' המשכיל יבין שזה היה לצד דברים שנולדו באמצע שזולת זה מתחילה מאי סבר שלא אמר ככל ולבסוף מאי סבר. ונשכיל לדעת מה הם הדברים שיכולין להיות באמצע, מהתשובה אתה יודע השאלה, והתשובה היא **ככל אשר אני** וגו' הא למדת שחשב יותר והסברא תצדיק ותאמת זה ויותר זה אין לו שיעור לבבך יבין כי ישנה לתמיה, והוא אומרם שאמר הלא שמי השמים וגו' ועל זה הוצרך להשיבו ואמר לו **ככל אשר** וגו' והראהו תבנית המשכן באותו מצב, והכתוב מעיד על זה מאומרו **מראה** ולא אמר אראה לעתיד, ואז ראה כי היה עשרים קרשים וגו'. וטעם הראיה ולא הספיק בדיבור, אבאר בעזרת השם בסמוך:
@669 **ודרך** זה נעלה להבין דבריהם ז''ל (ברכות נ''ה.) שאמרו בפסוק (לקמן ל''ח כ''ב) ובצלאל וגו' עשה את כל אשר צוה אפילו דברים שלא אמר לו רבו הסכימה דעתו וכו' משה צוה לבצלאל לעשות כלים תחילה ואחר כך משכן אמר לו בצלאל מנהג העולם לעשות תחילה בית וכו' אמר לו כך שמעתי מפי הקדוש ברוך הוא בצל אל היית כי בודאי כך צוה לי הקדוש ברוך הוא וכו' עד כאן. וקשה איך ישכח משה מצות ה' חם ושלום שיאמן עליו דבר כזה. ולהבין הענין יש להעיר עוד כי כפי סדר הכתוב רואני כי ה' הקדים מצות הכלים תחילה את הארון וכפורת וכרוביו ואחר כך השולחן ואחר כך המנורה ואחר כך המשכן ומשה אמת ודבריו אמת ולמה חזר מדבריו הראשונים. אכן לפי מה שפירשנו כי כשאמר ככל אשר אני מראה אותך את תבנית המשכן אז באותו מצב הראהו המשכן בתחלה וכשפרט לו פרטי המעשה הקדים הכלים, ויש בזה ב' דרכים בדברי ה'. האחד שיקדים המשכן כמובן מפסוק א' דכתיב **את תבנית המשכן** ומה שהקדים ה' בסדר המעשה את הכלים לא להתחיל בהם אלא שהתחיל ממה שגמר שהוא תבנית הכלים, והב' שכוונת ה' הוא להקדים הכלים כסדר שאמר ה' בפרטי המעשה, וטעם שהקדים ה' בפסוק א' לומר **את המשכן** קודם הכלים הוא לצד שהתמיהה שהיתה למשה שמים ושמי שמים וגו' כמו שכתבתי למעלה לא היתה אלא על המשכן לזה באה התשובה בהוראת המשכן כי קטן הוא ובאגב הודיע הכתוב כי גם הראהו עם תבנית המשכן תבנית הכלים שהיו בו. ואולי כי נתכוין גם כן לומר כי אין צורך שיהיו גדולים בהפלגה, וכשבא לסדר סדר פרטי המעשה הקדים הכלים, ומשה עליו השלום מתחילה הכריע בפירוש דברי ה' כדרך ב' וכשדן לפניו בצלאל הכריע בסברא כדרך הראשון, ולזה תמצא שאמר המדרש שאמר משה ודאי כך אמר לי הקדוש ברוך וצריך לדעת למה אמר ודאי אלא לצד שהיו לפניו ב' דרכים הנזכרים ומתחלה ברר אחד מהם ועתה חזר בו ואמר בודאי כי האמת הוא כדבר בצלאל. והנה לצד שלא אמר לו ה' בפירוש את מי יקדים לא יאמר על זה חס ושלום ששכח דברי ה', ואל יקשה בעיניך לפי דברינו לשון המאמר שאמר משה כך שמעתי מפי הקדוש ברוך הוא. אין הכוונה לומר שאמר בפירוש הקדים המשכן אלא פירוש לפי סדר הדברים כן נשמע. ונשאר לתת טוב טעם למה הוצרך ה' להראותו את תבנית המשכן, ואולי כי לצד שלא באו הדברים אלא תשובה לדברי משה שאמר שמים ושמי וגו' לזה אם היה משיב ה' כ' קרשים וכו' היה שומע משה כי לא בא השיעור אלא לומר כי יקבל ויתרצה ה' בבית קטן כזה מבלי להטריח ואין בדיוק שיעור זה מצוה, ולו יהיה שיאמר ה' אליו בצו לצו שלא יוסיף עם כל זה עדיין ישנו שהוא לטעם הסתפקות במועט, אשר על כן הראהו ה' תבנית המשכן דמות שהוא למעלה ובזה יצדיק כי זו מצותו לא למעלה ולא למטה:
@669 **ובדרך** רמז ירמוז הכתוב באומרו בסדר זה שהקדים **ושכנתי בתוכם** קודם אומרו **ככל** לומר לו ענין גדול כי בחינת הקדושה והדרגותיה לא בגדר המספר כי גבוה מעל גבוה וגבוהים, הלא תמצא אומרם ז''ל (אבות פ''ג) אחד שיושב ועוסק בתורה שכינה עמו שנאמר (לעיל כ' כ''א) בכל המקום אשר אזכיר את שמי ואמרו על ב' וג' וה' ועשרה וכל אחד כפי הדרגתו, ואמרו עוד (ב''ד פע''ד) שאין השכינה שורה על פחות מם' ריבוא כי מטעם זה לא נתנה תורה להאבות עד שהיו הבנים במספר ס' ריבוא, מכאן תקיש ותדין כי הדרגות הקדושה הם מא' עד ס' ריבוא, וזה בבחינת המספר ובבחינת האיכות כמה הדרגות מאחד לאחד עד אין קץ. וכיון שכן כאשר אמר ה' למשה שישכון בתוכנו לא ידע משה הדרגות של בחינת השוכן כמה שיעורה לזה נתחכם ה' ודבר אליו כדברים האלה **ושכנתי בתוכם ככל אשר אני מראה אותך** סמך **ככל אשר** וגו' **לושכנתי** לומר כי אותה בחינה המדברת עמו כשיעור אותה המרכבה אשר היה מראהו ישכון בתוכם, וכפי זה תהיה נקשרת תיבת **ככל** וגו' עם **ושכנתי** וגו':
@669 **וכן תעשו**. הנה לפי מה שפי' שהראהו תבנית המשכן לומר כזה תעשו לא פחות ולא יותר אל יקשה לך אם כן לא היה צריך לומר לומר וכן תעשו, כי תמצא שאמרו בשבועות דף י''ד וזה לשונם אחד הנכנם לעזרה וכו' שאין מוסיפין על העיר והעזרות אלא במלך ונביא ואורים ותומים וע''א סנהדרין מנא הני מילי אמר רב שימי אמר קרא ככל אשר אני מראה וגו' ואת תבנית כל כליו וכן תעשו לדורות. הנה כי באה וכן תעשו לצוות שיעשו כסדר הזה לדורות, ודע שדרשת לדורות דורש לה התלמוד מתיבת וכן תעשו לא מתוספת וא''ו לבד, כי לכשנאמר שאינו דורש אלא יתור תיבת וא''ו אין כאן יתור כי אם היה אומר הכתוב כן תעשו לא היה נשמע כוונת ההודעה שבא הכתוב להודיענו שעברו הדברים בין משה ובין ה' ויהיה קשה לי לשמוע דברי ה' למה לא אמר ככל וגו' קודם אומרו ושכנתי, אלא ודאי שכל תיבת וכן תעשו מיותרת, וכן פירש רש''י שם בשבועות וזה לשונו וכן תעשו קרא יתירה למדרש לדורות עד כא. וטעמו של רש''י ז''ל לא מטעמינו אלא לצד שפירש ככל אשר אני וגו' שהוא מחובר למעלה ועשו לי מקדש וגו' ככל וגו' אם כן הרי בא הדבר לעיכוב שלא יחשוב להתנדב לעשות גדול אם כן וכן תעשו למה לי לדורות, ולדרכנו שהלכנו לשיטת דברי רבותינו ז''ל כי אומרו **ככל** וגו' בא להשיב למשה עיכוב השיעור ממה שהראה לו כיוצא בו בשמים מזה ירגיש שלא ישנו:
@669 **וראיתי** להרב אבן עזרא שפירש וכן תעשו על הכלים לפי שלא הוזכר בתחלה אלא ועשו לי מקדש. ולא נתן לב הרב לומר טעם שהוצרך לומר וכן תעשו על הכלים ולא הספיק במה שמצוה בסמוך על פרטות כל הכלים, בשלמא מה שאמר ועשו לי מקדש היא כללות המצוה וטעמה שיעשה מקדש לשכון ה' בתוכו ואחר כך אמר אופני הבנין מה שאין טעם זה צודק במאמר וכן תעשו על עשיית הכלים אם לא שתאמר כדברי רבותינו ז''ל שדרשו לדורות, ולא ידעתי למה מעלים עיניו מאור החיים אשר האירו רבותינו ז''ל. גם בעיני יפלא דברי רמב''ן ז''ל שהשיג על דברי רש''י שאמר וכן תעשו לדורות ואמר ולא ידעתי אם יהיה זה אמת שיתחייב שלמה לעשות כלי בית עולמים כתבנית אלו ומזבח הנחושת עשה כ' אמה אורך ועשרים רוחב (דה''ב ד) עד כאן. מדבריו נראה כי נעלמה מלפני זכרונו סוגיית מס' שבועות שדברי רש''י הם דברי הגמרא ומה מקום לחלוק על התלמוד. והיה נראה לומר שסובר רמב''ן כי מה שאמרו בש''ם וכן תעשו לדורות אין הכוונה על שיעור הכלים אלא על דברים האמורים שם שצריך מלך ונביא וכו' וע''א סנהדרין, ואין דבריו נראים כי מי מפיס. ועוד לדבריו מה מקשה שם בגמרא ממשיחת כלים שמקדשת כלים שעשה משה ולא בשאר כלים שעשו זולת משה והוצרך הש''ס להביא להם ראיה מהפסוק והיה יכול לומר כי לא לכל הפרטים אמר הכתוב וכן תעשו לדורות אלא לדברים שמנו שם במשנה:
@669 **אלא** שצריך ליישב קושיית רמב''ן ממזבח הנחושת שעשה שלמה. וראיתי להרא''ם שרצה ליישב ואמר כי אין כוונת וכן תעשו על השיעור ממש אלא על דוגמת תכונת הבנין הרוחב בערך האורך וגובה לפי ערך ארכו ורחבו אבל לענין הגודל אין קפידא, ולזה כשם שמזבח שעשה משה היה ה' על ה' כמו כן עשו לדורות מרובע עשרים על עשרים, ונסתייע הרב מדברי התוספת כפרק הזורק שבת (צ''ח:) שהקשו למה שנשמע מדברי הש''ס כי רוחב המשכן היה עשר אמות מנין להם זה ודלמא רחבו אחד עשר אמות כו' ותירץ ר' יהודה דמבית עולמים ילפינן לה שהיה אורכו ששים אמה ורחבו עשרים הכי נמי במשכן רחבו שליש אורכו וכתיב וכן תעשו עד כאן. והקשה הרב על זה אם כן למה לא עשה הגובה של המזבח כתכונת מזבח משה שעשה ג' גובה לה' אורך ורוחב ולפי שיעור זה יעלה למזבח שלמה שהיו בו כ' על כ' שנים עשר גובה ותירץ כי כך באה ההלכה שלא אמר וכן תעשו אלא על אורך ורוחב לבד ולא על הגובה עד כאן:
@669 **ולפי** דעתי אין דברי הרב נראים כי מה שכתב כי וכן תעשו לדורות לא באה אלא על תכונת הבנין ולא על שיעורו לא יקובלו הדברים מפיו בלא הוכחה מהש''ם, ואם מחמת הקושיא, יותר יש להניח הדבר בצריך עיון מלבדות מדעתינו דברים שאין להם על מה שיסמוכו, ומה שהוכיח מתירוץ ר''י, וגם עליו אני דן, ועוד אינו הוכחה כי ר''י לא סמך תירוצו על דרשת וכן תעשו, ומה שכתב הרב בהעתק דברי ר''י וכתיב וכן תעשו אינם מדברי ר''י אלא הרב להצדיק דבריו אמר כן, ופירוש דברי ר''י הוא כי גילוי מלתא הוא אומר כי ממה שראינו שהיה בבית עולמים עשרים על ששים וכאן במשכן יש ספק אם היה עשרים אורך ועשרה רוחב או אחד עשר יתגלה הספק מבית עולמים, או אפשר שהיה להם איזו ראיה ללמוד סדר זה מבית עולמים ולא מדרשת וכן תעשו, וזה לך האות כי לא הזכיר ר''י דרשת וכן תעשו לחזק תירוצו, ועוד מה שהוסיף להקשות מהגובה ואמר כי באה ההלכה מהר סיני שלא נאמר וכן תעשו אלא על תכונת הריבוע ולא על תכונת הגובה לשיעור הריבוע:
@669 **דע** כי נחלקו רבותינו ז''ל (זבחים נ''ט:) רבי יהודה ורבי יוסי ר' יוסי סובר כי כל מזבחות הנחושת בין מה שעשה משה בין מה שעשה שלמה בין מה שעשו בני גולה ושעתיד להעשות כולן עשר אמות גובה של כל אחד מהם וג' אמות שכתוב בתורה מקום המערכה לבד עד כאן. וסברא זו הלכה היא (רמב''ם הל' ב''ה פ''ב) וסוגיית פרק שתי הלחם (מנחות צ''ז) כדעת זו מגדת ולסברא זו אין קושיית הרא''ם קושיא כל עיקר, ור' יהודה חולק וסובר דברים ככתבן ג' אמות קומתו. והנה קושיית הרא''ם אינה צודקת אלא לסברת ר' יהודה ומן הראוי לא היה מדבר דבריו בדרך פשיטות שנראה כי הם דברים מוסכמים אשר לא כן הוא. ומה שתי' הרב ז''ל כי כך באה ההלכה וכו', מסוגיית שבועות לא משמע כן ממה שאמר הש''ס אמתניתין דאין מוסיפין על העזרות וכו' מנא הני מילי ומתרץ רב שימי דאמר קרא וכן תעשו לדורות עד כאן. הנה ממה ששואל הש''ם מנא הני מילי והוצרך רב שימי לתרץ שמע מינה כי השואל לא היה יודע דרשת וכן תעשו לדורות וממוצא דבר אתה יודע כי לא היה יודע גם כן ההלכה שאמר הרב שבאה על הגובה שאינה לדורות שאם היה יודע ההלכה בהכרח שהיה יודע דרשת וכן תעשו לדורות שעל משמעותה באה ההלכה וכיון שכן למה לא הקשה השואל עצמו מגובה המזבח שלא עשאו שלמה כשל משה שהיא קושית הרא''ם עצמה שהרי אין לה תירוץ אלא בהלכה שבאה על זה והלכה זו לא ידעה השואל כנזכר, ויש עוד להוכיח מעומק הסוגיא כי לא היתה הלכה בזה ודברי הרב שלא בדקדוק:
@669 **ואני** אומר כי אין קושית רמב''ן מהמזבח שהיה עשרים על עשרים ולא קושית רא''ם מהגובה קושיא, והרי לפניך ברייתא ערוכה בפרק קדשי קדשים (זבחים ס''ב.) וזה לשונם תנו רבנן קרן וכבש ויסוד וריבוע מעכבין מדת ארכו ומדת רחבו ומדת קומתו אינם מעכבין וקאמר בש''ם מנא הני מילי דאמר קרא המזבח לעכב עד כאן. הרי כי מזבח עצמו שעשה משה יכול היה לעשותו מעשרים על עשרים והגובה גם כן יכול היה לעשותו יותר מג' אמות ואם כן מה מקום לקושית הרב ממזבח שעשה שלמה כי הקדוש ברוך הוא גילה כי אין מעכב גובה ורוחב ואורך, וגם הרא''ם ז''ל נעלם מעיניו דברי הברייתא וחשב כי לא היה משה יכול לעשות המזבח ביותר משיעור זה וגם הגובה צריך שיהיה ה' על ג' גובה ולא על יותר והוצרך לתרץ ב' התירוצים הכחושים. והנה שתלתי לך עץ שתול על מים ותחזק בו בל תמוט כי אומרו וכן תעשו הוא על דברים המעכבין במזבח מדבר שהם קרן וכבש ויסוד וריבוע כדקתני בברייתא וגם שלא יפחות מחמש אמות רוחב וה' אמות אורך כמו שאמרו שם בפרק קדשי קדשים ובלבד שלא יפחיתנו ממזבח שעשה משה:
@669 **אלא** שנשאר לנו לדעת שאר הפרטים שבמשכן היו לעיכובא ובבית עולמים לא היו מעכבין ואדרבה כתב רמב''ם בפ''א מהלכות בית הבחירה שאין בונים אלא באבנים או בלבנים. והנה הבינותי בכל מה שכתב רמב''ם במשפטי בית אלהינו ואראה כי בג' כלים כתב שצריך שיהיו כמות כלים שעשה משה במדבר ממש והם השלחן והמנורה ומזבח הזהב וכן מפורש בפרק שתי הלחם אבל שאר כלים וצורת הבית אין לקחת שיעור לדורות ממעשה משה במדבר, ולפי זה היה נראה לומר כי לא באה מצות וכן תעשו לדורות אלא בכלים ואין זה אמת כי בגמרא דרשוהו לענין קידוש העזרה וזה יגיד שגם על הבית באה המצוה לדורות, ועוד גם בכלים רואני שעשה שלמה כרובים שניים ומשונים הרבה מכרובים שעשה משה (מ''א ו') וכמה שנוים היו בשאר הכלים:
@669 **והנה** בהשכלה מועטת בענין אין שום קושיא כלל, כי יש לדעת כי כל בנין הבית והכלים לא עשאם שלמה כפי אשר נראה בעין שכלו לפאר אלא על פי נביא וגם הנביא הגיד כי לא דברי נבואתו הגיד אלא דברי קבלתו דכתיב בדברי הימים (א' כ''ח) ויתן דוד לשלמה בנו תבנית האולם וגו' ותבנית כל אשר היה ברוח עמו וגו' הכל בכתב מיד ה' עלי השכיל כל מלאכת התבנית וגו', וכתיב עוד (רש''י שם) אשר היה ברוח עמו כאשר הראהו שמואל הרואה, ואמרו ז''ל באגדת שמואל (מדרש שמואל פט''ו) רבי ירמיה בשם ר''ש כו' בית המקדש מסרה הקדוש ברוך הוא בעמידה למשה ומשה מסדה ליהושע בעמידה וכו' יהושע מסרה לזקנים בעמידה דכתיב ויאסוף יהושע וגו' ויתיצבו וגו' זקנים מסרוה לנביאים בעמידה נביאים מסרוה לדוד בעמידה וכו' דוד לשלמה וכו' ואומר הכל בכתב וגו' מלמד שנתנה לידרש מיד ה' מלמד שנתנה במסורת עלי השכיל מלמד שנתנה ברוח הקודש עד כאן. הראת לדעת כי כל מה שעשה שלמה בבית היה הלכה למשה מסיני והכל כתוב בספר גלוי לדורשי תורה ברוח הקודש, וכן תמצא שכתב רש''י בפירוש דברי הימים (פסוק י''ט) וזה לשונו והכל דרש שמואל מן התורה ברוח הקודש כמו ששנינו הר הבית היה ה' מאות אמה על ה' מאות אמה דרש אורך החצר מאה באמה ורוחב חמשים בחמשים וגו' יהיו חמש מאות על חמש מאות עד כאן. ומן הסתם יהיה כל המעשה נרמז בתורה למבינים ברוח הקודש, ולפי זה מה שאמר הכתוב וכן תעשו לדורות הם על דברים שלא בא עליהם ההפכיות בתורה כמושכל למביני מדע ברוח הקודש בזה יתנהגו על פי מעשה האמור במשכן מדבר אבל דברים שנאמרו בתורה במשפט מקדש עולמים לא תהיה להם סתירה מפסוק וכן תעשו כיון שיש לו מקום לעמוד בו בשאר הפרטים שלא באה עליהם ההלכה והבן:
@669 **ולדרך** זה גם כן נרתק חבל קושית רמב''ן מעל רש''י וגם נתרפא כאבו של רא''ם בענין שיעור גובה מזבח לו יהיה שהיה גובה מזבח מדבר מעכב:
@669 **ולהיות** שאמרו רבותינו ז''ל שנתנה לידרש בנינה של בית עולמים מן התורה אמרתי ליטול חלק בדרשה זו בב' וג' פרטים, וזה יצא ראשונה תחילת דבר ה' אמר **ועשו לי מקדש** וגמר אומר **תבנית המשכן** והיה צריך לומר ועשו לי משכן הא למדת כי על ב' מקדשות צוה וכמו שרמזנו בתחילת הענין ורמז מעשהו באומרו חמשים בחמשים כמו שפירש שמואל הנביא עליו השלום ואם אינו ענין למשכן מדבר תנהו ענין למקדש עולם הרמוז באומרו **ועשו לי מקדש**, ומעתה מאמר **וכן תעשו** לדורות אינו נוהג בפרט זה של שיעור תבנית הבית ועודנו במקומו לשאר דברים שדרשו ז''ל בשבועות לענין נביא וסנהדרין וכו':
@669 **עוד** מצינו (מ''א ו') שעשה שלמה ב' כרובים שניים נוספים על מה שעשה משה ונמצאו ד' כרובים אשר לא צוה ה' גם משונים שינוי גדול מכרובי משה:
@669 **ונראה** כי הכתוב רמזם במה שאמר (פסוק י''ח) ועשית שנים כרובים וגו' משני קצות הכפורת ועשה כרוב אחד וגו' וכרוב אחד וגו' וקשה למה הוצרך לומר ב' פעמים המעשה ועשית ועשה. עוד קשה שכל הכתוב מיותר כי מאומדו מב' קצות הכפורת מובן הוא שכרוב אחד מקצה וגו'. עוד קשה למה אמר עוד על שני קצותיו. אכן רמז ה' למעשה ב' כרובים שיעשו בבית עולמים מלבד כרובים שיעשה משה, כנגד מה שיעשה לפי שעה אמר **ועשית** לנוכח כי הוא יעשה במשכן, וכנגד כרובי בית עולמים שרמז בתחלת דבריו אמר **ועשה** לא דבר אליו לנוכח אלא כמצוה על עשיה אחרת לזמן אחר שמלבד ב' כרובים הנזכרים שהם מקצות הכפורת עוד יעשו מעשה אחר כרוב אחד מקצה מזה ואלו הם בפני עצמן כמו שכן עשאם שלמה שהיו רגליהם נוגעים בארץ ולא בקצה הכפורת, ופירוש **מקצה** במקום שכלה קצתו, ואולי שנתכוון בתיבת **מזה** לומר מלבד זה וחוזר אל הכרוב שהזכיר. ואחר כך חזר להתנות הכתוב ואמר כנגד כרובים שיעשה משה אמר **מן הכפורת** פירוש מגופו של כפורת **תעשו את הכרובים** שזכרתי בתחילת דברי שנים כרובים, וכדי שלא תטעה שחוזר אל הכרובים השניים לזה הזכיר פעם ב' **תעשו** שלא היה צריך לומר שכבר אמר ועשה אלא לומר כי אינו מדבר במעשה של כרובי המקדש אלא במעשה משה הוא מדבר ולזה אמר לנוכח **תעשו**, ועוד העיר ה' להבינך כן במה שאמר **את הכרובים** שלא היה צריך להזכירם כיון שבהם הוא עוסק ולא היה לו לומר אלא תעשם או תעשה אותם ומאומרו **תעשו את הכרובים** גילה שאינו מדבר במה שלפניו אלא במה שלפני פניו כמו שפירשנו. ואומרו **על שני קצותיו** פירוש צריך שיעמדו על קצה הכפורת שלא תאמר הן אמת שיהיו מגופו של כפורת אבל אפשר שירדד להם רגליהם ויעמידם בארץ ולא על כפורת הארון, לזה אמר **על שני קצותיו** פירוש שיהיה העמדתם על קצות הכפורת ממש מה שלא התנה כן בב' של בית עולמים:
@669 **והגם** שתמצא שבמעשה שעשה בצלאל אמר הכתוב כסדר כל האמור שנראה שכל האמור בכתוב ישנו במעשה המשכן של מדבר וישבו רבותינו ז''ל טעם הכפל שלא תאמר שתעשה ב' לכל קצה וכו' יעויין שם בדברי רש''י (פסוק י''ט), והנה אם לא היה לטעם שרצה לרמוז על כרובים השניים שיעשה לעתיד לא היה לו לכתוב תחילה סתם ועשית ב' כרובים ולחזור להסיר הטעות שלא תחשוב ב' מכל צד ויאמר כרוב אחד וגו' ומתחילה היה לו לכתוב ועשית כרוב אחד מקצה הכפורת וכרוב אחד וגו' (מקצה) תעשה אותם, אלא ודאי שנתכוון לרמוז כמו שפירשתי, ופשט הכתובים במקומו מונח כי הלא תמצא מה שפירש שמואל הרואה בפסוק (כ''ז י''ח) חמשים בחמשים אין זה פשט הכתוב אלא דרשה ולא נעקר הפשט גם לדרכינו הגם שישנו לפשט הכתוב ישנה לדרשה מכח הקושיא שהקשינו בסמוך. ועוד תמצא כי כאן במצות ה' דקדק לומר תיבת **ועשה** לדייק מה שפירשנו בה מה שאין כן במעשה בצלאל לא אמר ויעש יספיק בהערה:
@669 **ומזבח** הזהב מצינו (מ''א ז') שעשה שלמה אחר וגנז לשל משה כמפורש בדברי רבותינו ז''ל (מנחות צ''ט) שהשלחן והמנורה שעשה משה יש בו מחלוקת אם לא היו מסדרין ומדליקין (אלא) בו או גם בשאר שולחנות והמנורות שעשה שלמה היו מסדרים ומדליקין לפעמים בזה ולפעמים בזה אבל מזבח הזהב דבר מוסכם שנגנז ולא שמשו אלא בשל שלמה, וצריך לדעת למה גנז של משה:
@669 **ונראה** כי התורה רמזה הדבר במה שעקרה סדר מצות מזבח הזהב ממקום שהיה ראוי לצוות עליו, כי תמצא כי מתחילה התחיל בארון שהוא פנימי פנימיים ואחר כך הכפורת ואחר כך השולחן ואחר כך המנורה ואחריהם המשכן יריעיו קרשיו עמודיו אדניו ואחריו מזבח החיצון ואחריו חצר המשכן ואחריו השמן ובגדי שרת לאהרן וקרבנות החינוך והתמידין ואחר כל זה צוה מזבח הזהב, ויש בזה הרגשה גדולה בשינוי גדול כזה, ורמז בזה שדינו משונה מכל המשכן וכליו כי המשכן וכליו הראוי לבית עולמים ישמש לבית עולמים כגון השלחן והמנורה כמו שכתבנו למעלה שהיו משמשים בבית עולמים ומי שאינו ראוי לבית עולמים כגון משכן וכלים שלא שמשו במקדש, גם מזבח החיצון שלא היה בו הקפדה אלא בריבוע ובמקדש היו צריכין לעשותו גדול לצד הצורך אבל מזבח הזהב הגם שלא תשתנה עבודתו שהוא הקטורת חצי מנה בבוקר וחצי מנה בערב אף על פי כן לא ישמש בבית עולמים ועשה אחר וגנזו לחלוטין מה שלא עשה כן בשולחן ומנורה שעשה משה שהגם שעשה עשרה של משה עולה על כולן, וענין רמיזות מעשה בית עולמים אינו אלא רמז בעלמא:
@670 **ועשו ארון**. טעם שבארון שינה ה' את דברו הטוב מכל הכלים שבכולם אמר ועשית שולחן ועשית מנורת וגו' ואת המשכן תעשה ועשית את המזבח עצי וגו', וגם בפרטי הארון עצמו גמר אומר בנוכח דכתיב וצפית אותו ויצקת לו ועשית בדי וגו', אולי שרמז שאין גופה של תורה יכול להתקיים אלא בכללות כל ישראל ואין מציאות בעולם יכול עשות כל עקרי התורה וזה לך האות אם הוא כהן הרי זה אינו מקיים נתינת כ''ד מתנות כהונה ופדיון בכור וכו' ואם הוא ישראל הרי אינו יכול לקיים מצות עשה שבהקרבת הקרבנות ודיניהם אשר רבו מצות עשה שבהם וכן לוי ובכללות כל ישראל יקיימו כללות עקרי התורה, לזה אמר **ועשו** לשון רבים, ובשאר פרטי תיקוני הארון אמר לשון יחיד כי לתקן כלי התורה שהם לומדיה ועמליה והכנותיה יכולין להתקיים מאדם אחד:
@670 **עוד** אולי שקדם לדבר לו בלשון זה לגלות לו על כל המעשה שהגם שמדבר עמו לנוכח לא אליו בא המצוה אלא לזולת שהם חכמי לב כמו שבאר אחר כך ומכנה הדבר אליו לפי שהוא המצוה לישראל. עוד לפי מה שאמרו ז''ל (רש''י פ' עקב) כי ארון עץ עשה משה ושם שם הלוחות תיכף בירידתו מן ההר עד שעשה בצלאל הארון שהונחו שם לעולם, וכן אמר בפרשת עקב (דברים י' א') ועשית לך ארון עץ דקדק לומר לך פירוש אין פירוש ועשית כשאר ועשית אשר צויתיך במעשה משכן ועשית שולחן ועשית מנורת ועשית מזבח וכולן לא עשאן אלא בצלאל, דבר זה לך אני מצוה לעשות, וכן עשה דכתיב (שם ג') ואעש ארון עצי שטים וכתיב (שם ה') ואשים את הלוחות בארון אשר עשיתי, אשר על כן אמר כאן **ועשו** פירוש מלבד מה שתעשה אתה שהוא לפי שעה עוד יעשו העושים, ומנכסי נדבת המשכן, ואם היה אומר ועשית היה סובר משה לדון ממה שגילה לו בארון שלפי שעה שיהיה משלו גם את זה יהיה הדבר כן, או יחשוב שיהיה אותו ארון עצמו שכבר עשה, לזה אמר לא כן הוא **ועשו** וגו', ובשאר מעשים שלא היה מעשה זולת האמור דבר הכתוב כדרכו ועשית (לו) לומר שהזכות מכונה למשה הגם שאחרים עושים:
@675 **לא יסורו ממנו**. טעם שהוצרך לומר **ממנו** ולא הספיק לומר לא יסורו והענין מובן שממנו הוא, אפשר שנתכוון לומר שאין צריך שיהיו מהודקין ממש שלא יזוזו מתחילתם לסופם בטבעות עצמם אלא שלא יסורו מהארון היא ההקפדה, אלא שביומא (ע''ב.) אמרו וזה לשונם רבי יוסי בר חנינא רמי כתיב בטבעות הארון יהיו הבדים לא יסורו ממנו וכתיב והובא את בדיו הא כיצד מתפרקין ואין נשמטין עד כאן. מדברי הגמ' מוכח כי לא יסורו לבד משמע ליה שלא יזוזו ואולי כי תיבת **ממנו** יש בה משמעות אחר כי בא לרבות שלא יזוזו אנה ואנה לזה אמר הכתוב (י''ד) **והבאת**:
@675 **עוד** נראה כי אם לא אמר והבאת הייתי אומר כי מה שאמר הכתוב ממנו בא לומר שאין חיוב מלקות אלא על הסרתם בהחלט ולעולם יש איסור אפילו בהזזתם תלמוד לומר **והבאת** פירוש לשון הבאה שאם כונת הכתוב שיהיו קבועים ולא זזים היה לו לומר וקבעת או וחברת ולא והבאת שיהיה נשמע שיהיו נכנסים ויוצאים:
@675 **וראיתי** להתום' שהקשו למה הביא רבי יוסי בר חנינא פסוק והובא, והק' עוד מפסוק ושמו את בדיו בשעת סילוק מסעות שנראה שהיו נותנים אותם בכל מסע הא למדת שהיו מסירים אותם והתורה אמרה לא יסורו ממנו וא' כי היו שמונה טבעות בארון וד' בדים ודייק הכתוב שאמר ויצקת לו ד' טבעות וגו' וכתיב ושתי טבעות וגו' הא למדת שהם שמונה יעיין שם דבריהם, ואין אני מצדיק דברים אלו כי רבו הקושיות על האותיות, והדבר פשוט כי טעות נפל בספרים וצריך לומר במקום והובא והבאת את הבדים בטבעות וקושית ושמו בדיו נראה לי לומר כי להיות שהבדים היו לשאת את הארון בהם לזה כשצוה ה' לכסות את הארון בפרוכת המסך צוה שישימו הכהנים הכנת הבדים שיוציאו ראשי הבדים, ופירוש ושמו קונפוני''ר בלע''ז כדי שיהיה בסדר ואופן שישאו אותם הלוים על כתפיהם שלא יצטרכו הלוים להוציא ראשי הבדים ויזונו עיניהם מן הקודש. והר''י מאורליינש פירש שישימו הבדים על כתפי הלוים וכבר דחו התום' דבריו יעיין שם דבריהם. ועוד יש להקשות על דבריו ז''ל כהנה וכהנה ויותר יש לבחור בדברינו. וטעם אומרו ושתי טבעות לא ידעתי מה יפרשו בפסוק (לקמן כח ג) ועשו את בגדי אהרן וגו' ואלה הבגדים ובהכרח לומר שאין יותר מח' וכאלה רבות ותהיה זאת כאח' מהם בוא''ו נוסף שבא לאיזה דרשה, ואולי כי צוה ה' לעשות ב' טבעות שיהיו קבועים בגוף הארון ואינם נעים ונדים ואחר כך יעשה ב' טבעות ויכניסם בטבעות הקבועים בארון ואלו הם נעים ונדים וזה מיופי הנעשה בהתכונות הנושאים לכבוד ולתפארת ולעולם לא היו אלא ב' בדים אשר בהם היו נושאים הארון:
@681 **ונתת את הכפורת וגו' ואל הארון תתן וגו'**. קשה למה הוצרך לומר פעם ב' **ואל הארון תתן** אחר שכבר אמר למעלה ונתת את העדות וגו'. ורש''י ז''ל יישב שירצה לומר שיתן תחלה העדות ואחר כך יתן הכפורת עליו עד כאן. משמע מדבריו שהיה מקום לטעות שיתן העדות על הארון, ואין דעתי נוחה לומר שיש מקום לטעות בזה ומה גם שאין מקום שם כי הוא מקום הכרובים, ועוד היה לו לומר בפסוק ראשון במקום תיבת אל תוך ולא היה צריך לכתוב פעם ב' ואל הארון. ויש עוד להקשות בזה. ורא''ם ז''ל כתב בזה דברים שאינם לפי רום חכמתו. וראיתיו שרצה להסתייע לדברי רש''י מדברי ראב''ע, ובמחילה מכבודו דברי ראב''ע הם שבא לתקן המשמעות שלא יקשה לך בפסוק שהקדים נתינת הכפורת קודם נתינת העדות ומן הראוי להקדים נתינת העדות לזה אמר וכבר וכו' לא לפרש שכל הכתוב בא לומר שלא יתן העדות למעלה מהכפורת שזה אדרבה מובן מפסוק ראשון והטעות אדרבה מפסוק שני. והנכון בעיני לומר כי כונת הכתוב היא לרבות בו נתינה לומר שאחר שיתן הכפורת על הארון לא יצאו ממנו עוד לדורות עולם כמשפט ספר תורה אשר צוה לשום מצד וכו' ואמרו ז''ל (דב''ר פ''ט) שמשפטו שאם יהיה הפרש בין שבט לשבט בספריהם שכתבו כל שבט ספר תורה אחד יבררו הספר מספר המונח בית ה', ואמר כי העדות שם יהיו לבל יצאו עוד. ולזה ריבה בו נתינה אחר נתינה, ולטעם זה גם כן אנו מרויחים למה הקדים נתינת הכפורת לנתינת העדות, כי לא בא אלא לומר שאחר שנתנום בארון וכיסה בכפורת נתונים נתונים יהיו שמה עד עולם והבן. עוד ירצה כי לא יניח העדות בארון עד שיהיה הארון שלם בכפורת הלום ולא קודם, וזה אומרו **ונתת את הכפורת** וגו' אז **אל הארון תתן את העדות** עוד אפשר לומר על פי דבריהם ז''ל (ב''ב י''ד:) שהלוחות ושברי לוחות מונחים בארון, לזה אמר פעם ב' אחד כנגד הלוחות השלימים והב' כנגד השבורים, ובדרך רמז נראה כי בא לרמוז לו שהגם שהכפורת למעלה מן העדות שהם בתוך הארון למטה מהכפורת הם בבחינה למעלה ממנה ולזה סדר נתינת העדות אחר הכפורת לומר זו למעלה מזו מה שלא היה נשמע כן אם היה מקדים לומר ונתת את העדות וגו' ונתת את הכפורת על הארון מלמעלה משמע שהכפורת הוא למעלה מהארון:
@683 **אמתים ארכו וגו'**. הנה כשתרבע כל אמות השולחן אמה על אמה ברום אמה יהיו בין אורך ורוחב וגובה ג' אמות מרובעות באורך ורוחב וגובה, והוא סוד השפעת שולחן העליון מג' הדרגות בנצח הוד יסוד העולם:
@687 **לבתים לבדים**. לפי מה שפירשתי בטבעות הארון שצריך לצקת ד' טבעות ולקובעם בארון ובתוך הטבעות יכניס ב' טבעות ובתוך הטבעות יתן הבדים, כאן אמר כי אינו צריך לעשות ככה אלא הטבעות עצמן הקבועות הם יהיו בתים לבדים והבן:
@691 **תיעשה המנורה**. צריך לדעת למה הוצרך לומר תיעשה המנורה, ובמנחות פרק הקומץ רבה (כ''ח.) דרשו תיעשה לרבות שאר המתכות. ולפי זה דקדק לומר תיעשה ולא תעשה כי בימי משה לא היה צורך לזה כי של זהב עשו ובמדבר לא הוצרכו לעשות אחרת:
@696 **כפתוריהם וקנותם ממנה יהיו**. בהקומץ רבה (שם) תנן שבעה קני מנורה מעכבין זה את זה שבעה נרותיה מעכבין זה את זה מאי טעמא הויה כתיב בהו עד כאן. וקשה והלא לא נאמר הויה אלא בקנים ולא בנרות כי ב' הויות נאמרו במנורה אחת בפסוק זה ואחת בפסוק ראשון ועשית מנורת וגו' ירכה וקנה גביעיה כפתוריה ופרחיה ממנה יהיו משמע שאינו מעכב אלא ז' קנים וגביעיה כפתוריה ופרחיה, והגם שבמשנה לא הזכיר אלא הקנים והנרות כתבו התוספת שהוא הדין ולא הזכירם התנא לצד שאינם במנורות של מתכות, וכן כתב רמב''ם פ''ג מהלכות בית הבחירה יעויין שם. אבל הנרות לא הזכיר בהם ההויה, והנה יש מחלוקת בין רבותינו ז''ל (מנחות פ''ח:) אם הנרות קבועים או לא, ולא מבעיא להאומר שלא היו קבועים שהם כלים בפני עצמן ולא מצינו בהם הויה, אלא אפילו למאן דאמר קבועים הרי מודה הוא שאינם מקשה עמה שלא נחלקו רבותינו ז''ל בפרק ב' מדות (מנחות פ''ח:) אלא אם היתה מהככר או לבד מהככר אבל שאינם מקשה ממנה אליבא דכולי עלמא לא, וכן דקדק הכתוב באומרו מקשה ירכה וקנה גביעיה כפתוריה ופרחיה ואילו נרותיה לא אמר, ואחר שאמר משפטי פרטי המנורה באורך אמר שיעשו את נרותיה הרי זה מראה באצבע שחלוקים הם מהמנורה, ועוד דקדק הכתוב לומר **ממנה יהיו** לומר אותם שהם ממנה עליהם אני מתנה הויה. ואולי כי כיון שנתגלה טעם ז' קנים שהם לשום בהם נרות אם כן כשאין נר הרי הקנה בטל וכאילו אינו והוא מעכב. ואולי כי לא אמר הש''ם בהקומץ רבה מאי טעמא אלא על הקנים אבל הנרות אינו צריך כי זה תלוי בזה:
@698 **ומלקחיה וגו' זהב טהור**. הוצרך לומר **זהב טהור** לפי שאליבא דכולי עלמא אינם באים מהככר ולזה צריך להודיע ממה יעשו אותם:
@699 **ככר זהב וגו'**. בפרק ב' מדות (מנחות שם) תניא ככר זהב טהור וגו' למדנו למנורה שבאה מן הככר מנין לרבות נרותיה תלמוד לומר את כל הכלים יכול שאני מרבה אף מלקחיה תלמוד לומר אותה. ולעמוד על אמיתתן של דברים נשכיל לדעת מה היה חסר לי בידיעת מצות המנורה שעליו הוצרך לומר פסוק זה, ואראה כי בלא פסוק זה לא הייתי יודע שיעור זהב המנורה אם ככר אם חציו, לזה בא והודיע הכתוב השיעור דככר זהב טהור תעשה, ואחר שהודיע שיעור המנורה אז נכנסנו בספק אם הנרות בכלל השיעור או לא, וטעם שלא נכנס אלא בספק הנרות ולא בספק המלקחיים והמחתות מפני שהמלקחיים והמחתות ביאר הכתוב ואמר זהב טהור ואם הם משיעור הרשום במנורה לא היה צריך לומר בהם זהב טהור מה שאין כן הנרות שלא הזכיר בהם זהב נשארו בספק אם הם מהככר. ואין לומר כי ממה שלא אמר זהב טהור שמע מינה שהם מהככר משום שיש לומר כי לא הקפיד ה' עליהם שיהיו או מן הזהב או מן שאר המתכות לצד שעומדים לתשמיש ולעולם אינם מהככר, לזה אמר הכתוב **ואת כל כליה** הרי בירר ספקן שהיינו מסתפקין בנרות ואמר שהם מהככר, אבל מלקחים ומחתות אין לי ספק בהם ממה שהוצרך לומר בהם זהב טהור ודאי שאינם מהככר. ומעתה לא חש עלי הכתוב לטעות במאמר את כל כליה שנכנס גם מלקחיים ומחתות, אם כן קשה למה אמר הכתוב תיבת אותה למעט אם למעט מלקחיים ומחתות הרי אין צריך מיעוט, ונראה לומר בהעיר עוד בכתוב אחר האמת שאין בכלל הככר המלקחיים והמחתות למה סדר מצות ככר זהב טהור אחר שהזכיר מלקחיים ומחתות שמזה יחויב השכל לומר שגם עליהם חוזר הדיבור שאם לא כן היה לו להקדים לומר ככר זהב טהור וגו' ואת כל כליה ואחר כך יצו ה' מלקחיה ומחתותיה ואז על כל פנים לא היה צריך לומר תיבת אותה למעט מלקחיה ומחתותיה כי ממועטים הם כיון שלא הוזכרו אלא אחר אומרו ככר זהב וגו':
@699 **אכן** הנה האדון ברוך הוא נותן התורה בחר לומר פסוק **ומלקחיה** וגו' קודם אומרו **ככר זהב** וגו' לב' סיבות. האחד לצד שהוא אומר **וראה ועשה בתבניתם אשר אתה מראה בהר** לזה סמך פסוק זה למאמר המנורה וכליה שהם נרותיה, ואם היה מסדר פסוק זה ככר זהב וגו' קודם ומלקחיה היה נשמע שחוזרים הדברים גם עליהם ולא כן הוא כי אפשר שלא הראהו ה' תבנית המלקחיים והמחתות בהר. וסיבה ב' לסמוך מלקחים לנרות לומר כשם שהמלקחיים נעשו בפני עצמם גם הנרות דומות להם בפרט זה שמעשיהם בפני עצמן הגם שהם מהככר לא מפני זה תתחייב לומר שהיו מקשה ככפתורי' וגביעים וגו', והגם שפירשתי למעלה כי ממה שלא הזכיר הנרות עם שאר הפרטים שהזכיר במקשה שמע מינה כי אינם בכלל ואם כן לא היה צריך לרמז הנזכר, עם כל זה כיון שאמר הכתוב ככר זהב טהור וגו' את כל הכלים הרי השוה אותם למנורה ותבא הסברא לומר כי גם לזה נתכוין הכתוב לכוללם שיהיו במקשה כי לא מצינו פרט מפרטי המנורה שהוא מהככר ואינו מהמקשה לזה בא הכתוב והסמיך ענין המלקחיים והמחתות לנרות לומר כנזכר:
@699 **והנה** אחר שהיה צורך בדבר לכתוב פסוק ככר זהב וגו' אחר פסוק ומלקחיה וגו' לטעמים הנזכרים חש הכתוב שלא ישכיל משכיל על דבר כי זאת היא כוונתו יתברך ויאמר הא ודאי שלא דיבר כסדר זה אלא להכניס המלקחים והמחתות בשיעור הככר וידחוק לומר טעם אומרו זהב טהור לאיזו דרשה כמו שתאמר לעכב בהם הגם שהמנורה אמר בה הכתוב ריבוי תיעשה המנורה מכל מקום אפילו משאר מתכות באלו צריכין להיות זהב טהור, אשר על כרחו נתחכם ה' ואמר תיבת **אותה** למעט מלקחיה ומחתותיה שאינם מהככר והודעת הנרות שהם מהככר מאומרו **את כל הכלים** במקומה עומדת. ומעתה נחזק לומר שטעם שסדר פסוק **ומלקחיה** וגו' קודם פסוק **ככר זהב** וגו' שהוא לסיבות שכתבנו, ולזה דרש התנא תיבת אותה למעט מלקחיה ומחתותיה ואת כל הכלים לרבות הנרות, ואמר **כל** לומר שאפילו נר אחד אין לעשותו אלא מהככר ולדרך זה הרוחתי אומרו **את כל הכלים** ולא אמר ואת לומר אותה את וגו' את כל וגו' ואותה והבן:
@701 **ואת המשכן תעשה עשר יריעות**. רמז בזה כנגד עשרה מאמרות שבהם נברא העולם לומר ששקול המשכן ככל העולם כלו שנברא בי' מאמרות, גם זכות לישראל בו כאילו קיימו הי' מאמרות שבהם נברא העולם. עוד נתכוין בסדר מצוה זו של יריעות שש ושל יריעות עזים שבשל שש צוה עשרה ושל עזים צוה עשתי עשר עוד צוה שיחבר ה' יריעות לבד וה' יריעות לבד וכן בשל עזים צוה לחבר שש לבד, טעם הדבר הוא כי רשם ה' שמו הנכבד ביריעות וצוה כי כולן יהיו רחבן ד' בין של שש בין של עזים כנגד ד' אותיות של שם הוי''ה, וכן תמצא שרמזו ראשונים במאמרם הזך (שבת ו'.) רשות היחיד רחבו ארבעה וגובהו עשרה שהוא על שם הוי''ה רחבו ד' וגובהו פירוש במילוי עשרה על זה הדרך יו''ד ה''י וא''ו ה''י, וקדש הפנימי להיותו קרוב למקום המקודש וצוה לעשות עשרה יריעות כנגד אות יו''ד של שמו הגדול וצוה שיחבר ה' לבד לרמוז בזה אות ה''א ראשונה של שמו יתברך, ורמז בזה כי אות ה''א ראשונה היא מוכללת תמיד באות היו''ד, וזה הוא סוד קריאתה כי כשאתה קורא יו''ד אתה מחבר וא''ו ודל''ת שהם תכונת הה''א על זה הדרך ה ואין אתה קורא אלא אות אחת כמו כן הדבר הזה והבן. ובחינה זו היא סוד החכמה והנה לך רשומה ניכר ביריעות אלו חכמה, הב' אותיות ראשונים הם שמונה ועשרים כנגדם צוה אורך היריעה שמונה ועשרים באמה, אות שלישית מ' ארבעים כנגדם צוה ה' רוחב ד' באמה שעולה למנין עשר יריעות ארבעים, ואות רביעית היא אות ה' שרשם במאמר ה' לבד, וגם הוא סוד ה' חסדים הנמשכים מהחכמה, ואחר כך צוה ה' כנגד תשלום השם שהוא ו''ה לעשות יריעות עזים אחד עשר ורשם שיחבר שש לבד שהוא כנגד וא''ו וחמש לבד כנגד ה''א הרי תשלום שמו ית', וגם רשם בחשבון רוחב עשתי עשרה מ''ד לסוד הוא''ו תפארת ישראל שהוא סוד יו''ד ה''א וא''ו ה''א שעולה בו מ''ה, וכבר הודיענו ה' (בראשית מ''ח ה') כי לא יעכב אחד למספר כי ישלימנו הכללות, ורשם בחשבון האורך שלשים באמה כנגד הדרגות ה''א אחרונה שבשם שמאירה משלש הכוללות עשיריות והם שלשים ועוד יש לאלוה מילין עילאין קדישין והשומע ישמע ולבבו יבין:
@715 **ועשית הקרשים למשכן**. פירוש כי המשכן יקרא האהל שעל הקרשים ואין הקרשים נקראים משכן אלא קרשי המשכן:
@715 **עצי שטים עומדים**. רבותינו ז''ל ביומא (ע''ב.) אמרו שעומדין דרך גדילתן. ונראה שדייקו לה ממה שלא אמר על זה הדרך ועשית את הקרשים למשכן עומדים עצי שטים או ועשית את הקרשים עצי שטים למשכן עומדים שאז יהיה נשמע שההעמדה היא במצות המשכן שלא יהיו שוכבים ומאומרו **עצי שטים עומדים** רמז כי חוזרת תיבת עומדים גם לתכונת העצים מעצמם שיהיו כסדר העמדתם בשעת גדילתם:
@715 **רמז** המשכן **קרשים** אין קרשים אלא קשרים שבאמצעותו יתקשרו ויתיחדו כל בחינות הקדושה עליונים ותחתונים וכולן רמוזים בו עשר אמות אורך הקרש אין לך בחינה מבחינת הקדושה שאין בה כללות עשרה, ואומרו **ואמה וחצי** כאן רמז יחוד מצה שלימה ומצה פרוסה, והוא סוד ה''א ודל''ת. או ירצה סוד היסוד חי העולמים הוא רמז האמה ועטרת היסוד הוא בחינת חצי האמה, נמצאת אומר כי כל קרש יש בו רמז עשרה שישנם בכל ספירה ויש בהם רמז צדיק וצדק מיוחדים ברוחב, מנין הקרשים מ''ח, והוא סוד (ישעי' נ''ד) ושמתי כ''ד כ''ד שמשותיך, האדנים שמם יגיד ומעשיהם יצדיק בחינתם כי הם בחינת השכינה אשר תתכנה בשם אדנ''י ואשר תקבל היסוד בתוכה ומספרם מאה והוא סוד הקטן למאה גם היא העשירי למדריגות וכוללת כל העשיריות הרי מאה:
@730 **והקמות את המשכז**. פירש ראב''ע שיאמר כן לחכמי לב וכו', הרב השכיל בכללות מצות ה' וחשב כי כשם שנאמרו כל מעשיה של המשכן לנוכח ואחר האמת לא הוא עשה אלא חכמי לב כמו כן תהיה מצוה זו, ולא כן הוא לעולם כי כל מה שיצוה ה' בנוכח למשה הוא יעשה ואין זולתו זולת במקום שיחזור ה' ויאמר בפירוש כי אחרים הם העושים אז נאמר כי טעם שדבר אליו לנוכח הוא לומר לו כי כיון שהוא המצוה כאילו הוא העושה וכמעשה כל המשכן וכליו שהגם שכינה הדבר אליו חזר וציוהו בפרשת כי תשא קראתי בשם בצלאל וגו' ואתו אהליאב וגו' ובלב כל חכם וגו' ועשו את כל אשר צויתיך חזר וגילה הדבר כי לא יעשה משה דבר במלאכה, אבל הקמת המשכן שלא מצינו שחזר ה' ופירש לו מי המקים הרי זה יגיד כי הדברים ככתבן כי הוא יקים, והוא הקים דכתיב (לקמן י''ח) ויקם משה את המשכן וגו' הוא לבדו ואין איש אתו, והוא דברי חכמינו ז''ל (שמו''ר פנ''ב) ועיקר, וזולתו עיקר נעקר:
@733 **ונתתה את הפרוכת וגו' והבאת שמה**. מכאן משמע כי יקדים לתלות הפרוכת במקומו ואחר כך יביא הארון לפנים מהפרוכת, ובפרשת פקודי (לקמן מ' ג') אמד ה' אליו ושמת שם את ארון העדות וסכות על הארון את הפרוכת משמע כי יקדים הארון וכן עשה משה שהקדים הארון תחילה כמבואר שם. (פסוק כ') ונראה כי מה שהקדים נתינת הפרוכת להבאת הארון אינו אלא שרצה לגמור מעשה הפרוכת אבל סדר את מי יקדים הנה הובא בפרשת פקודי, או לצד כי סדר ההקמה אין זה מקומו אלא בפרשת פקודי ולא הוזכר כאן הבאת הארון אלא לומר מה משמש הפרוכת ומה מעשיו שהוא להבדיל בין הקודש ובין קודש הקדשים שהוא מקומו של הארון, לזה לא דקדק לומר מי קודם ותדרשנו במקומו:
@738 **ועשית את המזבח**. אמר **המזבח** ולא אמר מזבח. אולי שחוזר אל המוזכר במצות הכללות דכתיב (לעיל כ''ה ט') את תבנית המשכן ואת תבנית כל כליו ושם הראהו המזבח, ולזה אמר **ועשית את המזבח** שהראיתיך תבניתו צריך שיהיה מבפנים עצי שטים:
@755 **חמש אמות וגו'**. עיין מה שפירשתי בפסוק (שם) וכן תעשו:
@757 **ואתה תצוה**. צריך לדעת למה הוצרך לומר ואתה אחר שעמו היה מדבר, עוד למה אמר תצוה ולא צו, עוד למה אמר לשון ציווי. ורבותינו ז''ל אמרו בזה דרשות מהם אמרו (תו''כ ס''פ אמוד) אין צו אלא זירוז לצד שיש חסרון כים, ואולי כי לצד שהדבר אינו מן המוסר לצוות ה' שידליקו נרות בבית ה' אשר ממנו תצא אורה, אשר על כן אמר למשה כי מצוה זו לא יאמרנה לישראל על פי ה' אלא הוא יצוה פירוש מפי עצמו שינהגו כבוד זה להביא שמן להדליק, ולזה אמר **ואתה**, פירוש מלבד מה שצויתיך הוסף אתה לצוותם על זה. ודקדק לומר **תצוה** ולא תדבר להצדיק דברינו אלה שיזרזם הוא על הדבר שאם אמר תדבר יהיה הנשמע כי ידבר דברי ה' כסדר הרגיל לדבר מבלי צורך הזירוז, ולזה לא אמר צו שאז יהיה נשמע שיאמר כי ה' אמר אליו לצוות אלא **תצוה** פירוש מעצמך. ולא יראה בעיניך כי מצוה זו קלה היא כיון שאינה אלא מפי משה לא כן הוא שאין זה אלא משום דרך כבוד לאל עליון אבל המצוה הרי אנו רואים כי ה' אמר אליו שיצוה. ואולי כי לזה אמר **ויקחו אליך** פירוש למה שאתה בדעתך תצוה. עוד ירצה לצד שצוה ה' כל מעשה המשכן וענייניו לנוכח שיראה שמצוה לו שיעשה הוא כל הנדבר אליו ויביא כל הנדבה אל המשכן לצד התלהבותו בעבודת ה' גם יעשה מלאכת המשכן ועבודתו, לזה אמר אליו **ואתה תצוה** פירוש מה שיש לך מהיתרון על כל ישראל אינו אלא מה שתצוה אותם לבד, ולזה אמר תיבת **ואתה** ותוספת הוא''ו לצד שיש עושים לבד משה, וידוייק גם כן אומרו **תצוה** ולא אמר צו:
@757 **עוד** ירמוז לצד כי הגיע זמן תת הכהונה לאהרן ברר ה' למשה המלכות והמליכו על ישראל, והוא אומרו **תצוה את בני ישראל**, על דרך אומרו (ש''א י''ג) ויצוהו ה' לנגיד וגו'. והגם שבארץ מצרים אמר הכתוב (לעיל ו' י''ג) ויצום אל בני ישראל ופירשנו שם שעשאם מושלים בעם כאן יחד משה למלכות ישראל ואהרן כהן. ואולי כי לזה נתכוון מה שאמר הכתוב (לעיל י''ט ו') ואתם תהיו לי ממלכת כהנים וגוי קדוש, ממלכת חוזר אל משה, כהנים אהרן ובניו, וגוי קדוש אלו הלוים. ואולי שירמוז באומרו **תצוה** על דרך אומרם ז''ל (זהר ח''א פ''ג) כי כל תלמיד חכם יש לו ניצוץ מנשמת משה, ולזה רבותינו ז''ל (סוכה ל''ט.) היו קוראים זה לזה משה כי הוא זה המדבר בבחינת נפש הלומדת תורה, והוא אומרו **ואתה תצוה** על דרך אומרו (תהלים צ''א) כי מלאכיו יצוה לך שהוא לשון צוותא ליווי לאיש ישראל הנכבדים, וכבר ידעת כי אין חשיבות אלא באמצעות עסק התורה. ובחר ה' לרמוז רמז זה במצוות שמן כי הוא בחינת התורה שהוא אור העולם. ועיין בפסוק שאחר זה:
@757 **ויקחו אליך**. טעם אומרו **אליך** יתבאר על דרך מה שאמרו במסכת שבת דף כ''ב וזה לשונם מחוץ לפרוכת העדות עדות היא לכל באי עולם שהשכינה שורה בישראל מאי עדות אמר רב זה נר המערבי כו' עד כאן. והנה אמרו ז''ל (שמו''ד פנ''ב) ליצני הדור היו מתלוצצים על משה לומר אפשר שהשכינה שורה על מעשה של משה וכו' עד כאן. הרי כי לא היו מצדיקים אפילו מישראל שתשרה שכינה במשכן וכפי זה הגם ששרתה שכינה ביום א' בניסן עם כל זה אין זה סימן לתמידות שתקבע השכינה מקומה במשכן אבל בנם נר המערבי הוא עדות לכל באי עולם שהשכינה שורה בישראל, והוא מאמר ה' **ויקחו אליך** פירוש אליך נוגע הדבר כי בזה תתחזק נבואתך שיכירו ויצדיקו נבואתך שהשכינה תשרה בתוכם כשיראו נם שיעשה בשמן המנורה. ואולי כי לזה נתכוון באומרו **ואתה תצוה** לומר שלא יחוש שלא יאמנו דבריו להיות הדבר תמוה שידור אל עליון בתחתונים וכמו שכן היה ואם תאמר מנין יצדיקו **ויקחו אליך** פירוש בדבר זה יש לך חיזוק והצדקת הדברים כנזכר:
@757 **ובדרך** רמז יתבאר הכתוב על דרך מאמר הובא בספר זוהר חדש (בראשית ח') כי ד' גליות של ישראל כל אחד מהם נגאלו ממנו בזכות אחד, גלות הראשון נגאלו בזכות אברהם אבינו עליו השלום, ב' נגאלו בזכות יצחק, ג' בזכות יעקב, והד' תלוי בזכות משה ולזה נתארך הגלות כי כל עוד שאין עוסקים בתורה ובמצות אין משה חפץ לגאול עם בטלנים מן התורה. וזה הוא שרמז הכתוב כאן באומרו **ואתה תצוה את בני ישראל** על דרך (תהלים צ''א) כי מלאכיו יצוה, או על דרך אומרם ז''ל אין צו אלא מלכות כי הוא ימלוך עלינו לעתיד ותנאי הוא הדבר שיעסקו ישראל בתורה. וזה הוא אומרו **ויקחו אליך שמן זית** זך ירמוז אל התורה שנמשלה לשמן מה השמן מאיר לעולם כך התורה והם דברי הזוהר שכתבנו בסמוך, ודקדק לומר **זך** שצריכין לעסוק בתורה לשמה בלי שמרים שהם לקנתר ח''ו או להתגדל וכדומה אלה הם שמריה. ואמר עוד **כתית** פירוש שצריכין לעסוק בתורה ולכתת גופם וכחם על דרך אומרו (במדבר יט יד) זאת התורה אדם כי ימות (ברכות ס''ג:) וכבר כתבתי ענין זה בחפצי (חפץ ה') בענין המיימינים בה יעויין שם. ואומרו **למאור** תתפרש גם כן כפי דרכנו כי בזמן הגלות נחשך מאור הלבנה שנקראת המאור הקטן ונפרד אלוף ממנה ושפחה תירש גבירתה, ולזה יצו כי יכוין בשמן זית להאיר למאור וליחדו במכון גם יכוין אל המאור הגדול, כי כבר ידעת מאמרם ז''ל (מגילה כ''ט.) בפסוק (דברים ל ג) ושב ה' ממה שלא אמר והשיב, גם מאמרם ז''ל (תענית ה'.) בפסוק לא אבא בעיר והבן. ואומרו **להעלות** וגו' עולה תמיד ותמיד זה אין לו שיעור ולא תשוב לדאבה עוד והיה לה ה' לאור עולם. ואולי שכיוון עוד לומר **למאור להעלות נר תמיד** כי המאור הגדול הוא יעלה הנר תמיד על דרך אומרו (ישעי' ס''ב) נשבע ה' וגו' אם אתן את דגנך והיית רק למעלה:
@758 **מאת בני ישראל**. יתבאר על דרך מה שאמרו בתוספתא דשקלים (פ''ב) כל קרבנות הציבור שנתנדבו מעצמן כשרים ובלבד שימסרום לציבור עד כאן לשונם, והוא מה שאמר הכתוב **מאת בני ישראל** פירוש כי שמן זה קרבן ציבור ולזה לו יהיה שיתנדבו יחיד צריך שימסרם לציבור ותהיה הבאתו למשכן מאת בני ישראל:
@759 **ואתה הקרב אליך**. טעם אומרו **ואתה**, גם אמר לשון הקרבה, גם אמר תיבת **אליך**, יתבאר על דרך אומרם ז''ל (שמו''ר פ''ג) כי הכהונה למשה היתה למנה אלא לצד שמאן ללכת בדבר ה' אחר כמה פעמים חרה ה' בו והסירו מגבירת הכהונה באומרו (לעיל ד' י''ד) הלא אהרן אחיך הלוי פירוש שהיה לוי ועכשיו נעשה כהן עד כאן. לזה אמר לו בשעת מעשה **ואתה** פירוש לא לצד שאני מצוך לבד אלא גם אתה מצד עצמך **הקרב** את אהרן במקומך ותעשה הדבר כאלו אתה חפץ בו כי זה לך במקום קרבן לכפרה על אשר העזת פניך לפני ה', ואומרו **אליך** לכפרתך בהקריב את אהרן ויתן לו גדולתו אין לך קרבן גדול מזה:
@759 **עוד** ירמוז באומרו **הקרב אליך** כי על ידי חטא האדם מתרחק בחינת עינף נשמתו שכנגד אותו ענף שבו חטא משורשו הגדול כפי גדלו והקטן כו', והנה באמצעות ההפצרות שהפציר בשליחות ה' גרם להתרחקות ענף אחד מענפי נשמתו משורשה, והגם כי ה' הענישו אף על פי כן כל עוד שלא קיבל העונש הפגם עומד במקומו והרחוק עודנו מרוחק, לזה בשעת תכלית הדבר הודיעו כי בזה יהיה מתקרב הרחוק, והוא אומרו **ואתה הקרב אליך** פירוש הקרב לעצמך פירוש לבחינתך שרחוקה באמצעות החטא ההוא, ונתכוון ה' להודיעו כי זה תיקונו, ומזה אני משכיל על דבר שאמרו ז''ל בסוף ברכות (נ''ד.) חייב אדם לברך על הרעה כשם שהוא מברך על הטובה וכו' ומפרש בגמרא (שם ס':) לקבל הרעה בשמחה כשם ששמח בטובה עד כאן. והיה הדבר קצת בעיני רחוק, ועל פי הדברים האמורים בענין הנה היסורין הם מקריבין ענפי הנשמה שהיו רחוקים משורשם, שאין לך רע ומר כעוזבו את ה' אלהיו, ובאמצעות היסורין יתקרב הרחוק ועל זה ישמח לב המשכיל, ואמר **ועשית בגדי קודש** וגו' **לכבוד ולתפארת** שהם הם סימני השמחה שיראה שחפץ ודבר לפארו, אשר זה הוא שנאוי לעושה הדבר לצד ההכרח, והגם שהבגדים הם חובת גברא העומד לשרת, עם כל זה רצה ה' לזכות לגלגל זכות זה על ידו שיעשה אותם לחיבה ולשמחה באחיו, ודבר זה הוא בחינת נשמה לנשמה בעיקר מעשה זה, ואולי שנתכוון ה' לומר לו שיעשה הבגדים משלו, והגם ששנינו (יומא פ''ג מ''ז) בגדי הכהנים באים משל ציבור, הרי אמרו שיחיד יכול להתנדבם ולמוסרם לציבור וכמו כן צוה ה' לעשות:
@760 **ועשית וגו' לכבוד ולתפארת**. צריך לדעת מה היא כוונת ה' באומרו **לכבוד** וגו' אחר שמודיע מעשיהם ואופניהם, ואם להודיעו שבגדים אלו יש בהם לאהרן כבוד ותפארת מה יצא לנו מזה. ואולי שיתבאר על פי מה שאמרו בפרק אין מעמידין (ע''ז ל''ד.) וזה לשונם שאלו את רבי עקיבא במה שמש משה שבעת ימי המילואים לא הוה בידיה אתא ושאל בי מדרשא אמר ליה בחלוק לבן שאין בו אמרא עד כאן. הנה ממה ששמש משה בשבעת ימי המילואים בחלוק זה יגיד שאין הבגדים מעכבין אלא לאהרן ולבניו אבל זולת הכהנים תתרצה עבודת הקרבנות בלא בגדים, והוא מה שמודיעו באומרו **כבוד** וגו' לומר לא תחשוב כי הבגדים לצורכי עבודה לבד ויתחייב הדבר ללובשם משה בעבודת ימי המילואים ולא כן הוא אינם אלא לכבוד וגו' למשרת קבוע לעבודתו אבל לצד העבודה לבד כשתהיה בזולת אהרן ובניו יעבדו בחלוק לבן וכמו שכן שמש משה כנזכר:
@760 **או** יאמר כי בא ה' לתת טעם למה צוה ח' בגדים ד' לבן וד' זהב ואמר הטעם הוא **לכבוד ולתפארת** פירוש על פי דבריהם ז''ל (הקדמת תיקונים) כי הח' בגדים ד' של בגדי לבן ירמזו אל ד' אותיות של שם הוי''ה ברוך הוא וד' בגדי זהב ירמזו אל ד' אותיות של שם אדנ''י, ודע כי שם הוי''ה ברוך הוא יתיחם אליו כינוי התפארת כידוע ושם אדנ''י יתיחס אליו כינוי הכבוד, והוא אומרו **ועשית בגדי קודש** וגו' **לכבוד** כנגד בגדי זהב **ולתפארת** כנגד בגדי לבן, וסדר הכתוב סדר הדרגות הקדושה זו למעלה מזו והקדים **לכבוד** והבן. וצוה ה' עשות ח' בגדים שבאמצעותם יתכפר פגמים אשר יסבבו בני האדם אשר יגיע למקום עליון ובזה יכופר העון ההוא. ולדרך זה יש לתת טוב טעם למה הקפיד ה' על הבגדים באהרן ולא במשה על דרך אומרם ז''ל (ערכין ט''ז.) כי ח' בגדי כהונה מכפדים על ח' מיני עבירות שיהיה בבני ישראל אשר על כן לא צוה ה' הדבר אלא להכהן העומד לשרת הוא ובניו כל הימים לכפר על בני ישראל מה שאין כן משה שכל מה ששמש בז' ימי המילואים לא היה אלא לכפרת אהרן ובניו למלא את ידם לעבוד לפני ה' לא היה צורך למה שיכפרו הבגדים כנזכר לזה שמש בחלוק וגו':
@761 **ואתה תדבר**. טעם אומרו **ואתה**, שצריך הוא בעצמו להתטפל בדבר לדבר לחכמי לב, והגם שאמר ועשית בגדי וגו' חזר ה' ופירש דבריו כי לא הוא יעשה אלא על פיו יהיו נעשים וכדי שלא יבין שהעיקר הוא שיהיו נעשים על פי משה ואין צורך בדבר שידבר משה מפיו אל חכמי לב לזה באה המצוה ואמר **ואתה** בפיך **תדבר אל כל** וגו', ודקדק לומר **אל כל** כי זה הוא אחד מסימנים המובהקים שהדבר הוא מהשלמת הדעת ומרצון הלב שידבר הדברים לכולם יחד שאם היה הדבר בא בדאבון נפש ישתדל לומר הדברים שלא בפני רבים וכל עוד שיכול לדבר דבריו לפני אחד לא ידבר בפני שנים כי הדבר הוא פחיתות למשה שלא יהיה הוא ראוי לשרת לפני המלך, אשר על כן צוה ה' לעשות סימן לדבר אל כל חכמי לב ובזה יוודע לעיני הכל כי נפש חפצה ולב שלם:
@761 **עוד** נראה כי טעם שאמר ה' בה' פסוקים אלו ג' פעמים **ואתה** כי בא לתת לו מעלה בג' דברים והם נדבת המשכן בכללותיה א', ומלאכת המשכן וכליו ובגדי כהונה א', ועבודת בית המקדש א'. ואמר ה' אליו כי הוא נוטל שכר כאילו הוא עשה הכל, כנגד הבאת נדבת המשכן אמר **ואתה תצוה** וגו' ואליך הם מביאין והוא מה שגמר. אומר **ויקחו אליך** פירוש אני לך מצוה להביא והם יביאו אליך לעשות, וכנגד מלאכת המשכן אמר **ואתה תדבר אל כל חכמי לב** ובזה אינם אלא שלוחיך. ודקדק לומר **אל כל** כדי שכל המעשים שיהיו נעשים במשכן יהיו נעשים בשליחותך וכאילו הוא עשאם, וכנגד עבודת בית ה' אמר **ואתה הקרב אליך את אהרן** וגו' שיבא ויעבוד בשליחותך, ולזה דקדק לומר **אליך**, ולטעם זה מצוה ה' אל משה כל מעשה המשכן ומלאכתו ועבודתו לנוכח כי אחר האמת עליו הוא המצוה אלא שצוה לו שהוא יצוה אחרים במקומו:
@762 **ואלה הבגדים וגו'**. קשה למה לא מנה הכתוב אלא ששה בגדים והשמיט ציץ הקודש ומכנסיים. ואולי שרמזם הכתוב שניהם, הציץ רמזו בפסוק שלפני זה **ועשו את בגדי אהרן לקדשו** שלא היה נצרך לומר אלא ואלה הבגדים וגו' אלא נתכוין אל הציץ שלא הזכיר בפסוק ואלה הבגדים. ולזה אמר לאהרן ולא הזכיר לבניו כי לא נתכוין אלא על הציץ, ואומרו לשון רבים לצד שהוא לבדו לא יועיל כי ח' בגדים מעכבין זה את זה לכן אמר עליו לשון רבים, ובזה ידוייק גם כן אומרו **ואלה** שנראה כמוסיף על בגדים אחרים, לצד שכבר קדם וצוה על קצת ולא הוצרך לבאר כי סמך על מה שעתיד הוא לפרטם אחד אחד ובפרטן תמצא מבואר הרמוז, וכנגד המכנסיים אחר שהזכיר אלה הבגדים וגו' אמר **ועשו בגדי קודש**.
@762 **לאהרן אחיך ולבניו** ופסוק זה מיותר הוא לומר על המכנסיים, ולזה הזכיר **אהרן ובניו** כי המכנסיים צריכין בין לכהן גדול בין לכהן הדיוט. ונשאר לדעת למה לא סדרם הכתוב יחד עם הששה ולא היה צריך לכל זה, ואולי ב' דברים אלו אינם בגדר אחד עם הששה, הציץ לצד מעלתו יותר מג' בגדי כהן גדול ולזה הקדימו בפני עצמו, והמכנסיים לצד היותם בהדרגה פחותה מג' בגדי כהן הדיוט, ולזה איחרו בפני עצמו, והששה הם הדרגה שוה. עוד נראה טעם עשותו ככה שנתכוון לומר שצריך לעשות בגדי כהונה לשמן, לזה פרט בפסוק **ועשו בגדי קודש** שפירשנוהו במכנסיים ואמר **לאהרן אחיך ולבניו לכהנו לי** פירוש שצריך לעשותם לשם אהרן לשרת לפני ה' ומזה תלמוד לשאר בגדים. ובפסוק ראשון שפירשנו בציץ אמר.
@762 **לקדשו** וגו' כי מלבד שיעשהו לשם כהונה עוד יוסיף לכתוב בו קודש לה':
@767 **ולקחת את שתי וגו'**. צריך לדעת למה אמר **את** וגו'. ואולי שיכוין אל אבני שוהם שכבר הזכיר בתחלת המצוה בפרשת תרומה. וזה הוא שיעור הכתוב **ולקחת את שתי אבני שוהם** אשר צויתיך להביא. ובזה נתכוין במתק דבריו יתברך לתת לו טעם למה פרט אבני שוהם מכלל כל האבנים, כי אבני שוהם יש בהם מצוה אחת פרטית מלבד אבני המילואים, ולזה אמר אליו **ולקחת אותם אבני שוהם** שפרטתי לך:
@768 **ששה משמותם וגו'**. צריך לדעת למה אמר **משמותם** ולא אמר ששה שמות וגו' וששה שמות על וגו' כתולדותם. גם לא היה צריך לומר הנותרים כי רואה אני שנותרים הם. ובהכרח לפרש **נותרים** הפחותים על דרך אומרו על אלעזר וגו' הנותרים ודרשו ז''ל (יומא פ''ז זהר ח''ג נ''ו:) הפחותים כו' וכמו שדרשו גם כן (ב''ר פע''ג) בפסוק צאן לבן הנותרות יעויין שם, וזה יבהיל כי מאומרו **כתולדותם** משמע כסדר שנולדו ליעקב ואם כן למה הנולדים באחרונה פחותים מהדאשונים ומה גם שיש באחרונים בני הגבירות יוסף ובנימין זבולון ויששכר בן תורה ויש בראשונים מבני השפחות ואיך יקרא הכתוב לבני הגבירה נותרים בערך בני השפחות. ולהבין הענין אל זה אביט למה שאמרו בסוטה (ל''ו.) וזה לשונם ת''ר שתי אבנים היו לכהן גדול על כתפו וגו' ושמות בני ישראל כתוב עליהן ששה על אבן זו וששה על אבן זו שנאמר ששה וגו' שניה כתולדותם ולא ראשונה כתולדותם מפני שיהודה מוקדם ונ' אותיות כ''ה על אבן זו וכ''ה על אבן זו ר' חנינא בן גמליאל אומר לא כדרך שחלוקים בחומש הפקודים, אלא כדרך שחלוקים בחומש ב', כיצד בני לאה כסדרן בני רחל אחד מכאן ואחד מכאן ובני השפחות באמצע ואלא מה אני מקיים כתולדותם כשמותם שקרא להם יעקב ולא כשמות שקרא להם משה ראובני שמעוני וגו' עד כאן, פשטן של דברים הוא כי לתנא קמא כתולדותם חוזר על שמות ב' האבנים אלא שיקדימו יהודה לראובן על זה הדרך יהודה ראובן שמעון לוי דן נפתלי באבן אחת ובאבן השנית גד אשר יששכר זבולן יוסף ובנימין כסדר לידתן, וכשתחשוב האותיות תמצא כ''ה באחת וכ''ד באחת, ואמרו בש''ס (שם) ר' יצחק אמר הוסיף לו יהוס''ף, רב נחמן אמר בנימין מלא, וחשבון זה לא נרמז בפסוק אלא שכך באה להם הקבלה כ''ה באחת וכ''ה באחת. והקדמת יהודה לראובן אני אומר כי מהכתוב דורש לה ממה שכתב כתולדותם באחרונה ולא כתב על זה הדרך ופתחת עליהם שמות בני ישראל כתולדותם ואז יהיה נשמע שבאה מצות כתולדותם על סדר ב' האבנים. ואין להקשות מי גילה כי מה שאבן ראשונה אינה כתולדותם הוא לצד הקדמת יהודה ודלמא לומר שאין בהם סדר כל עיקר, זה אינו כי בהכרח כשתבוא לומר באבן ראשונה סדר אחר שאינו כתולדותם תבחר באחד מהסדרים שישנם בכתוב או סדר שכתוב בחומש הפקודים או בחומש שני ולכל אחד מהם כשתבוא לסדר אבן ראשונה שלא כתולדותם תצא בהכרח אבן השנית שלא כתולדותם ואם כן הרי בטלת כתולדותם בב' האבנים אשר על כרחך תתחייב לומר שהשינוי שמבטל כתולדותם באבן ראשונה הוא באופן שאינו מבטל גם בשניה והיכי דמי בהכרח בכהאי גוונא שיקדים יהודה ודבר זה סברא הוא כי הוא מלך ולו ראוי להקדים וגם מצינו לו שקדם בהקרבת חנוכת המזבח, והגם שגם יששכר קדם, אם באנו להקדימו כאן הרי בטלנו כתולדותם של אבן שניה, ולדרך זה מה שדקדקנו בפ' במקומו מונח. ואפשר לומר כי נתכוין לומר שאין הסדר מפסיל באבני האפוד שאם הקדים שמעון לראובן אינו מעכב, לזה אמר **ששה משמותם** וגו', **ואת שמות** וגו' **הנותרים** פירוש אין לכתוב אלא הנותר בידך שלא כתבת אותו על הראשונה. ויש להוכיח כן ממה שלא תנא בתוספתא דמנחות (פ''ה) סדר כתיבת השמות מעכבין זה את זה כדתני בגדי כהנים מעכבין זה את זה אבני שהם ואבני מילואים מעכבין זה את זה כתב שעל גביהן מעכבין זה את זה היה לו לומר גם כן סדר השמות מעכבין זה את זה אפשר שסובר שאין מעכב:
@768 **ור'** חנינא בן גמליאל סובר באבן ראשון בני לאה כולן כסדרן פירוש ואין להקדים בני זלפה הגם שקדמו בלידה ובשניה בנימין בראש האבן קודם בני השפחות שכן כתוב בחומש ב' ואחריו בני השפחות כסדר לידתן ויוסף בסוף האבן והוא אומרו אחד מכאן, ולפי סדר זה נמצא חשבון האותיות אינם חלוקים כ''ה על אבן זו וכ''ה על אבן זו כי אבן ראשונה שבה בני לאה כסדרן יש בה כ''ח אותיות ובאבן שניה כ''א ולכשתוסיף האות או ה''א ביוסף או יו''ד בבנימין יהיו כ''ב ולסברא זו יתבאר מה שדקדקנו בכתוב על זה הדרך **ששה משמותם** פירוש שלא כסדרן מהם שנולדו תחילה ומהם שנולדו אחר הששה הנותרים והם יששכר וזבולן שנולדו אחר כל בני השפחות, ואומרו **הנותרים** פירוש שנעשו נותר מסדר החשבון כשתבוא לסדר סדר הנולדים תחילה תמצא שהב' קדמו לב' בני לאה והותירם ה' אחריהם ולזה קרא להם נותרים, והגם שעמהם יוסף ובנימין אמר הנותרים לצד הארבעה שבהם:
@768 **ואבוא** אל העין מה שכתב הרמב''ם בפ' ט' מהלכות כלי המקדש וזה לשונו ששה על אבן זו וששה על אבן זו וכותבין שם יהוסף ונמצא כ''ה אותיות באבן זו וכ''ה אותיות אותיות באבן זו וכך היו כותבין. עד כאן. ודבריו ז''ל אינם לא כתנא קמא ולא כר' חנינא בן גמליאל אין זה אלא בנין חדש ולא כסברת רב כהנא שהביא הש''ס ודחאה שהוא אמר באבן ראשונה ראור.... ן גד אשר זבולון דן נפתלי ובאבן הב' שמעון לוי יהודה יששכר יוסף בנימין וגו', ומהרי''ק (בכ''מ) דחק ופירש כי פסק רמב''ם כר' חנינא בן גמליאל ומפרש דברי ר' חנינא בן גמליאל על זה האופן בני לאה כסדרן פירוש אחד כאן ואחד כאן בני רחל אחד מכאן ואחד מכאן בשני קצוות האבנים מלמטה ובני השפחות באמצע פירוש באמצע ב' האבנים עד כאן:
@768 **ולי** נראה שאין דברים אלו מתקבלים בלב כל חכם לב מד' טעמים, א' איך יניח תנא קמא ויפסוק כר' חנינא, ומה שאמר הרב שטעמו של ר' חנינא בן גמליאל מסתבר אדרבה טעמו דר' חנינא בן גמליאל לא מסתבר כלל דמפיק הכתוב ממשמעותו שפירש כתולדותם כשמות שקרא להם אביהם ולא כשמות שקרא להם משה כי מנין יעלה על דעת אנוש שיכתוב ראובני וגדי שיוצרך למעטם, ועוד כתולדותם לא משמע שפיר שרצונו לומר על שמותם בלידתם ואין הכרח להוציא התיבה מפשטה שהוא כסדר לידתם כסברת תנא קמא ויותר מסתבר טעמיה דתנא קמא. וקושיא זו קלה ממה שלאחריה, ב' לסברת הרב שאמר שבני לאה אחד מכאן כבני רחל למה אמר ר' חנינא בן גמליאל בני לאה כסדרן בני רחל אחד מכאן ואחד מכאן שמורה באצבע שבני לאה אינם אחד מכאן ואחד מכאן שאם פירוש כסדרן הוא אחד מכאן ואחד מכאן גם בני רחל כסדרן של בני לאה הם ולא היה לו לומר אלא בני רחל לבסוף, ועוד משמעות אחד מכאן ואחד מכאן לא יגיד כדבריו כי היה לו לומר אחד באבן זו ואחד באבן זו כי אחד מכאן וכו' יגיד כדברי רש''י שהוא אחד בראש האבן ואחד בסופה, וקושיא זו קלה משלאחריה, ג' כפי פירוש דברי הרב אין סדר זה בחומש שני כי בחומש ב' בני לאה בזה אחר זה ובנימין אחריהם ובני השפחות אחר בנימין ויוסף לבסוף ולר' חנינא בן גמליאל לדברי רמב''ם יוסף אחר ב' בני השפחות באבן הראשונה ובנימין מאוחר אחר שני בני השפחות האחרונים באבן השנית ואיך קאמר ר' חנינא בן גמליאל כדרך שחלוקים בחומש שני והלא בחומש שני בנימין קודם כל בני השפחו':
@768 **ועוד** למה הקדים יוסף לבנימין והלא בחומש ב' בנימין קודם, ואין לדחות שהפכם כדי לדייק חשבון כ''ה בכל אבן שהרי חשבונם שוה הוא ה' בכל אחד. ובאמת אם יעמוד ר' חנינא בן גמליאל ויאמר כי לכך נתכוון לא יוצדקו דבריו כיון שתלה הדבר ואמר כדרך שחלוקים בחומש ב', וגם אין דבריו מתקבלין כי הכתוב הקדים בנימין לבני השפחות ולדבריו הוא באחרונה שבאחרונות, הד' מנין מצא רמב''ם לסדר בני לאה חצים באבן זו וחצים באבן זו הלא פשטן של דברים שאמר ר' חנינא בן גמליאל בני לאה כסדרן לא משמע כן ומנין נתהוה לרמב''ם סברא זו בדברי ר' חנינא בן גמליאל. ואחרון הכביד מה שכתב הכסף משנה בטעם רמב''ם שכתב להשלים החמשים אותיות בתוספות ה''א ביוסף והקשה על זה מהש''ם דקאמר התם וזה לשונם הני חמשים חמשים נכי חדא הויין אמר רבי יצחק יוסף הוסיפו לו אות אחת שנאמר עדות ביהוסף מתקיף לה רב נחמן כתולדותם בעינן אלא בכל התורה בנימן והכא בנימ. ן שלם דכתיב ואביו קרא לו בנימין עד כאן הרי שדחה הש''ס תירוץ יהוסף דלא מתוקמא יהוסף והעלה אלא בנימין כתוב בב' יודין. ותירץ הרב כי קושית הש''ס מתולדותם לא הוי אלא לסברת תנא קמא אבל לדעתיה דר' חנינא בן גמליאל לא מקשה כי הוא לא אמר ששלל כתולדותם אלא שלא יכתוב ראובני שמעוני וכיון שכן אוקימתא ראשונה דיהוסף במקומה עומדת ורבינו פסק כר' חנינא בן גמליאל כנזכר עד כאן:
@768 **ודבריו** תמוהים בעיני עד למאוד הלא לדעת תנא קמא לא דקדק בשמות כלל ומפרש תיבת כתולדותם על סדר לידתם ראשון ראשון ומה מקום להקשות הש''ס לדעת תנא קמא מכתולדותם, אלא ודאי שלא הקשה מעיקרא אלא לדעת ר' חנינא בן גמליאל שמפרש כתולדותם כשמות שקרא להם אביהם ותירץ רב נחמן בנימין מלא. ולכשנניח הנחה סוברת כי תהיה הקושיא לדעת תנא קמא כל שכן וקל וחומר שתהיה לסברת ר' חנינא בן גמליאל שמדייק כתולדותם על השמות. ועוד מדברי רמב''ם מוכח שמפרש כתולדותם על הסדר ולא על השמות שכתב וזה לשונו ששה על אבן זו וששה על אבן זו כתולדותם עד כאן, ואם היתה כונת רמב''ם לפסוק כר' חנינא בן גמליאל לא היה סותם לומר כתולדותם שמצינו ראינו כי הש''ס הקשה אותה והוצרך לפרשה אלא ודאי שלא פסק כר' חנינא בן גמליאל אשר ע''כ יותר היה נכון להניח הדבר בצריך עיון מלומר כזה:
@768 **ואפשר** לומר כי רמב''ם לא גרס במילתיה דתנא קמא מפני שיהודה ראשון אלא על זה הדרך שניה **כתולדותם** פירוש בהצטרפות שניה הוא שיהיו נמצאים סדורים כתולדותם על זה הדרך ראובן באחת שמעון בשניה לוי באחת יהודה בשניה וכן על זה הדרך, נמצאת כשאתה בא לקרותם בסדר ב' שורות יהיו כתולדותם והוא אומרו שניה כתולדותם אבל ראשונה אינה כתולדותם כי הם סדורים בה על זה הדרך ראובן לוי יששכר ואין זה כתולדותם בשום אופן, ופירוש **כתולדותם** לפנינו ב' דרכים, הא' הוא סדר חומש הפקודים שהוא על זה הדרך בני לאה יחד בני רחל אחריהם בני השפחות אחריהן, והב' האמור בחומש ב' בני לאה ראשונים בני השפחות באחרונה בני רחל יוסף לבסוף ובנימין בין בני לאה ובין בני השפחות, ותנא קמא לא ביאר במה בחר, והגם שאמר כתולדותם אין הוכחה לסברתו כי יכול ליאמר כתולדותם הגם שיקדים כל בני לאה לצד שלא יפסיק בין בני אם אחת והגם שהמיעוט מהם נולדו אחר בני בלהה יכול ליאמר כתולדותם בסדר האמהות לאה ילדה ראשונה וכל הבנים יחשבו כבן א' להקדים כולם יחד, או גם כן לצד שרוב הבנים הם קדמו, וגם לצד שלא מצינו שנסדרו בכל התורה כולה כסדר לידתן על זה האופן, ודייק רמב''ם דברי ר' חנינא בן גמליאל שאמר לא כסדר שחלוקים בחומש הפקודים חלוקים וכו' זה יגיד כי דבר זה יכול ליכנס בדברי תנא קמא שבא לשלול אותו וזה לך האות כי כוונת תנא קמא באומרו כתולדותם שהוא באחד מב' הדרכים או כסדר חומש הפקודים או סדר חומש ב' ובא ר' חנינא בן גמליאל ושלל חומש הפקודים ובחר בחומש ב', וסבר רמב''ם שאין הכרח בדברי תנא קמא ואפשר שכך היא דעת תנא קמא לפרש בו כסדר חומש הפקודים, והגם שמדברי ר' חנינא בן גמליאל נראה כי תנא קמא סובר כן, להיות שדבריו שקולים הם לזה הוצרך לבאר אבל אנו אין לנו לפרש בדברי תנא קמא אלא כדעת ר' חנינא בן גמליאל כל שלא נמצא בפירוש שחלק עליו. ומחלוקת ר' חנינא בן גמליאל ותנא קמא היא במשמעות כתולדותם תנא קמא סובר שני' כתולדותם ע''ד שפירשנו אבל ר' חנינא בן גמליאל אמר בני לאה כסדרן פירוש באבן אחת בני (יוסף) [רחל] א' בראש האבן וא' בסוף ובני השפחות באמצע האבן אם כן אינם כתולדותם והוצרך לפרש כשמות וגו'. ופסק הרב כתנא קמא וסדר בני לאה א' באבן זו וא' באבן זו כדי שתבוא השניה כתולדותם ובני השפחות אחריהם כסדר הנזכר, וטעם שהקדימם כי הם נסדרו בחומש ב' קודם יוסף וגם בזה יצדק אומרו כתולדותם שאם יקדים יוסף ובנימין אז אפילו השניה אינם כתולדותם שהרי קדמו בני רחל לבני השפחות. וטעם שהקדים נפתלי לדן להשלים כ''ה אותיות כמו שאמר תנא קמא כי לא ר' חנינא בן גמליאל אמר דבר זה, והגם שיש מקום לומר כי מן הסתם אינו חולק מאמצעות הדברים תתחייב לומר שחולק כיון שחלק אותם בסדר שיהיו כ''ח באחת וכ''ב באחת. ואחר כך סדר יוסף ובנימין והשלים המנין באות ביהוסף כי לא דחה התלמוד סברא זו אלא לר' חנינא בן גמליאל אבל לא לתנא קמא כי אינו מפרש כתולדותם על השמות. ולא כתב יהודה בתחלה כי לא גרם לה בש''ם כמו שכתבנו, זה הוא מה שנראה לדחוק ליישב הברייתא לסברת רמב''ם. ואולי שנזדמנה לו איזה ברייתא ופסק אותה. ויהי מה לדרך זו של רמב''ם יתיישבו הדקדוקים שדקדקנו בכתוב על נכון. אומרו **ששה משמותם** ולא אמר ו' שמות שאז תבין שהם כסדרן כתולדותם בכל אבן ואבן אלא **משמותם** פירוש מכל ב' וב' מהם תקח אחד ותכתבנו על האבן הא' ויהיה נותר א' וכן לזוג הב' והג' וכו' ואחר כך תקח אותם הו' שנותרו מכל זוג וזוג ויהיה על האבן הב', ועל זה דקדק לומר **ואת שמות הששה הנותרים** פירוש שנותרו בידך כאמור, וכפי זה אומרו **כתולדותם** הוא על סדרן בב' האבנים ולזה איחר לומר **כתולדותם** אחר שהזכיר ב' האבנים והבן:
@793 **ובצאתו ולא ימות**. נראה שאם לא היו לו הפעמונים שמשמיעים את הקול חייב מיתה לשמים שאם לא כן ולא היתה כוונתו אלא למחוסר בגדים היה אומר ולא ימות אחר תשלום הבגדים או לפחות אחר תשלום ד' בגדי כהן גדול ולא באמצע אלא ללמד על הפרט בא שחייב אפילו על הפעמונים, ובפסוק האמור בסוף מעשה הבגדים דכתיב והיו על אהרן וגו' ולא ישאו עון ומתו שם חייב על העובד מחוסר בגדים:
@794 **קדש לה'**. משמע שכל מציאות שיכתוב קדש לה' כשר, ומה שאמרו בגמרא (שבת ס''ג:) שהיה כתוב שני שיטין יו''ד ה''א למעלה קדש לה' למטה לא לעכובא. ולזה תמצא שם שאמר ר' אליעזר בר' יוסי אני ראיתיו ברומי כתוב עליו קודש לה' בשיטה אחת וגו' הרי שאין הדבר מעכב ואפילו לתנא קמא אינו מעכב, ובזה לא יקשה בעיניך פסק רמב''ם פרק ט' מהל' כלי בית המקדש יע''ש:
@796 **לרצון להם לפני ה'**. צריך לדעת מה ענין יגידו ב' תיבות אלו שבהם יהיה לרצון לפני ה', ואולי שיכוון באומרו **קדש** על ישראל כאומרו (ירמי' כ') קדש ישראל, ותיבת **לה'** ירצה כי כללות ישראל הנקראים קדש הם לה' חשוקים דבוקים משועבדים ולזה יהיה **לרצון לפני ה'** שיש לו רצון בישראל באמצעות הכתב, והוא סוד (שה''ש ו) אני לדודי ובזה יתרצה דודי לי:
@798 **לכבוד ולתפארת**. טעם שאמר כן פעם ב' לרמוז מה שאמרו בזבחים (י''ח:) וזה לשונם היו מטושטשין או מקורעין ועבד עבודתו פסולה. ותניא עוד שם בד שיהיו חדשים. ואמרו בש''ם חדשים אין שחקים לא והתניא משוחקים כשרים וכו' אלא למצוה וכו', והוא או' **לכבוד** כנגד קרועים וזה לעכובא, **ולתפארת** כנגד חדשים וזה למצוה, ולזה הוצרך הכתוב לומר שניהם וזולת זה היה לו לומר לתפארת שהוא יותר מאומר לכבוד:
@799 **והלבשת אותם וגו' ומשחת וגו'**. פירוש אחר שילבישם בעוד הבגדים עליהם ימשחם ולא קודם ובזה הגיעתם הכהונה לידם, והוא אומרו **ומלאת את ידם**, ואולי כי יכוין באומרו **את ידם** בזה לומר כי באמצעות המעשה הם נשפעים בבחינת החסד המתיחסת ליד הגדולה והבן:
@799 **וקדשת**. פירוש במעשה הקרבנות כאומרו וזה אשר תעשה להם לקדש אותם. וטעם שהזכיר הדבר כאן לומר שלא יקדש אותם עד שיקדים לעשות הלבישה והמשיחה והבן:
@800 **ועשה להם מכנסי בד**. קשה למה איחר מצות המכנסים, ויש לומר לצד שאמר והלבשת אותם את אהרן לזה איחר המכנסים לומר שאינו חוזר עליו מצות והלבשת וגו'. ואין לומר שיכוין לומר שתהיה לבישתם באחרונה שהרי אמר הכתוב במקום אחר (ויקרא טז ד) ומכנסי בד יהיו על בשרו ודרשו ביומא (כ''ג:) שלא יהיה דבר קודם למכנסים אלא ודאי לטעם שכתבנו. עוד נראה שנתכוון לכותבו באחרונה ולהסמיך לו מצות והיו על אהרן וגו' ולא ישאו עון ומתו, ואם היה כוללו עם שאר בגדים ואומר והיו על אהרן וגו' תבא הסברא לומר כי לא באה האזהרה אלא על שאר בגדים אבל המכנסים אינם באים אלא כדי שלא תגלה ערוה ואין בהם צורך קדושת עבודה, לזה אמרם לבסוף וסמך להם האזהרה והעונש לומר כי מעכב הוא לקדושת הכהונה כשאר בגדים:
@802 **וזה הדבר אשר תעשה וגו'**. הכוונה להיות שקדם אליו מניעת המעשה כמו שפירשתי למעלה (כ''ז כ') שאין עליו אלא מצות הדבור לעושים, לזה **וזה הדבר** זה יצא מהכלל המושלל ויש לו לעשותו להקריב קרבנותיו ז' ימים, ואומרו **וזה** לצד שקדם וצוה שילבישנו לאהרן ולבניו וגמר אומר **וזה** גם כן תעשה, ואם לא אמר **אשר תעשה** אלא לקח פר וגו' יש מקום לומר כי יצוה לאהרן או לבניו לעשות, לזה אמר אשר תעשה כי הוא העושה. ולהיות שיש מקום לומר שלא הוכשר להקריב אלא קרבן שעה שהם קרבנות ימי המילואים של אהרן ובניו אבל קרבן שהוא קבוע לדורות שהם התמידים של כבש אחד בבקר וכבש אחד בין הערבים לא, לזה חזר ואמר **וזה אשר תעשה** וגו' **כבשים בני שנה שנים ליום תמיד**, ושלא יבין כי הותר במעשה הקרבנות תמיד, לזה אמר וזה לומר אין לו להקריב אלא ז' ימים האמורים בענין, ואומרו **הדבר** תתבאר למאן דאמר ביומא (ד':) מלואים כל הכתוב בהן מעכב, לזה אמר **וזה הדבר** כל הדבר האמור כאן לעיכוב, ולמאן דאמר דבר שאין מעכב לדורות אין מעכב במילואים אומרו **הדבר** לומר ולא כל דבר מעכב:
@802 **לקח פר וגו'**. אולי כי רשות נתונה להביא או משל אהרן ובניו או משל משה ואין עכבה בדבר:
@808 **ויצקת על ראשו ומשחת**. פירוש צריך יציקה על ראשו וצריך משיחה בפני עצמו וכמו כן לבניו כי הכתוב השוה אותם יחד דכתיב ומשחת אותם, וכמו כן בפרשת פקודי (לקמן מ' ט''ו) כתוב ומשחת אותם כאשר משחת את אביהם, וכן הוא מפורש בתורת כהנים (פ' צו):
@810 **ומלאת יד אהרן ויד בניו**. פירוש שימשח אהרן ובניו כמו שאמר למעלה ומשחת אותם ומלאת את ידם וכאן לא הזכיר המשיחה ורמזה באומרו ומלאת את ידם:
@811 **וסמך וגו'**. ולא אמר וסמכו שאהרן יסמוך בפני עצמו ואחר כך יסמכו בניו. שוב בא בידי תוספתא בפ''י דמנחות וזה לשונם ה' שהביאו זבח אחד כולן סומכין עליו לא כולן כאחד אלא כל אחד סומך ומסתלק עד כאן, ופסקו רמב''ם בפ''ג מהלכות מעשה הקרבנות, וכפ''ז אמר הכתוב **וסמך** לומר שיסמכו אחד אחד ולא יחד. אלא שצריך לדעת למה אמר ב' פעמים ולא הספיק בא' כמו שכתוב במעשה בפרשת צו (ויקרא ח' י''ח). ואולי כי מאחד הייתי אומר כי לצד שבו תלוי החטא שעליו בא הקרבן כי הוא עשה העגל ולא בניו לזה פרטו להקדימו לרמוז על הדבר ואין למדין ממנו לכל זבח, לזה כפל ואמר ב' פעמים **וסמך** לשון יחיד, ומעתה יש טעם נכון למה בפרשת צו בהודעת המעשה לא אמר לשון יחיד אלא בא', כי יספיק ללימוד שאנו צריכין לו, כי לא הוכפל במצוה אלא להסיר הטעות והבן:
@828 **מאשר לאהרן ומאשר וגו'**. צריך לדעת למה הוצרך לומר, ואולי שיכוין לומר שלא יאכל מכל חזה ושוק הניתנים לאהרן ולבניו זולת אלו:
@834 **ואכלו אותם אשר כופר**. פירוש לצד שהם בעליו ולא לצד שהם כהנים, והוא אומרו **אשר כופר בהם** כי אכילת שלמים לבעלים תפעיל הכפרה, ואפילו למשה אסורים הגם שאוכל החזה שאסור לאהרן:
@835 **כי קודש הוא**. פירוש ולזה ישרף:
@840 **את הכבש האחד וגו'**. אמר **את הכבש** כדי שלא תסתפק שהוא זולת ב' כבשים האמורים בסמוך, לזה אמר **את הכבש** פירוש אחד מהמוזכרים, ואומרו **האחד** נתכוון לומר שהגם שלא היה להם אלא כבש אחד בנמצא יקרבוהו בבוקר ואין כבש שני של בין הערבים מעכב, והנה אומרו **האחד** פירוש הגם שיש אחד ואין לו שני, ואפילו בחינוך שמעכב ראשון לב' כאומרם בפרק התכלת (מנחות פ''ד מ''ד), אין ב' מעכב לראשון:
@844 **ונועדתי שמה לבני ישראל ונקדש וגו'**. צריך לדעת כוונת הכתוב מה בא ללמדנו באומרו **ונועדתי שמה לבני ישראל**, ויראה כי בא לתת טעם למה שאומר בגמר דבריו **ונקדש בכבודי** ואמרו ז''ל (זבחים קט''ו:) שכאן נאמר למשה בקרובי אקדש, לזה הקדים לומר **ונועדתי שמה לבני ישראל** פירוש לצד שאני מזמן שכינתי לבני ישראל חוששני להם מפרצת גדר ומיעוט כבוד מהם לזה צריך לקדשו בקרובי כדי שייראו ממקדשי, ורמז לו שלא הוצרך עשות דבר אלא לצד ישראל אבל לצדו אינו צריך לאיום זה:
@847 **אני ה' אלהיהם**. טעם שכפל לומר כן פעם ב', אולי שנתכוון לרבות אפילו בזמן שאין שכינתו בתוכנו הוא ה' אלהינו ולו אנחנו. או ירצה על זה הדרך בידיעתם ובהכרתם הדבד כאומרו בתחלה וידעו וגו' בזה יהיו ראוים לקרוא שמי עליהם לומר ה' אלהיהם אבל זולת זה יפרקו עול ויהיו לאלהים אחרים ב''מ:
@848 **ועשית מזבח וגו'**. טעם שסידר כלי זה של פנים מאוחר מכל המשכן ועבודתו, כבר פירשתי בפרשת תרומה בפסוק (לעיל כ''ה ט') וכן תעשו, ואומרו **תעשה** למעט מעשה שעשה שלמה שלא היה עצי שטים שהיו כולו זהב:
@848 **חסלת פרשת תצוה**
@859 **כי תשא את ראש וגו'**. צריך לדעת טעם אומרו **תשא** ולא אמר תפקוד כאומרו במטה לוי (במדבר ג' ט''ו) ב' אומרו **את ראש** ולא הספיק לומר כי תשא את בני ישראל, שאין לומר שלא יצו ה' למנות אלא לראשים כי הענין יכחיש זה, ג' צריך לדעת כוונת אומרו **לפקודיהם**, ויתבאר הכתוב על פי דבריהם ז''ל כי החוטא גורם בחטאו כפיפת ראשו כי בחינת הרע מהותה היא אל ארץ תביט כי שפלה היא ובחינת הקדושה היא נשיאת ראש והרמת המהות והאיכות, ותמצא שאמר הכתוב (בראשית כ''ג י''ז) ויקם שדה עפרון, ודרשו ז''ל (ב''ר פנ''ח) קימה היתה לו, והנה להיות שמצוה זו באה אחר מעשה העגל וכמו שדייק הכתוב באומרו **ונתת אותו על עבודת אוהל מועד** ואמרו זכרונם לברכה (רש''י) מכאן שנצטווה למנותם אחר מעשה העגל, והוא מה שאמר **כי תשא** לשון נשיאות ראש על דרך אומרו (בראשית מ' י''ג) ישא פרעה את ראשך שהוא לשון מעלה, שתשא ראש בני ישראל שראשם נמוך לצד חסרונם במעשה העגל, והוא אומרו **לפק ודיהם** על דרך אומרו (במדכר ל''א מ''ט) ולא נפקד ממנו איש ואמרו ז''ל (שבת ס''ד.) שלא נמצא בהם אדם שחטא, **ונתנו איש כופר נפשו לה'** אשר חטא על הנפש, **בפקוד אותם** פירוש כמשמעו, וטעם אומרו **ונתנו** בתוספת וא''ו לצד שצריך קודם הכרת החטא כי לא טוב עשה וחטא בנפש ואחר כך יתן כופר נפשו לה':
@859 **עוד** ירצה באומרו **לפקודיהם** וגו' שאין לך רשות למנותם אלא לסיבת פקודיהם פירוש לצד חסרונם אם נחסרו מהם ותרצה לעמוד על הנשארים או שגכנסו בגדר הכנת החוסר כאומרו (במדבר שם) עבדיך נשאו את ראש וגו' לצד שירדו למלחמה או לסיבת צורך המספר לערוך מלחמה עם אויב וכדומה, ובא לשלול שאין למנותם בלא סיבה כלל, ואומרו **ונתנו** בתום' וא''ו להיות הדבר תנאי נוסף על תנאי ראשון שצריך לפקודיהם עוד צריך לתת איש כופר וגו', ודבר זה אינו נוהג אלא לאותו זמן שהיו ישראל חייבים על העגל אבל לדורות אין צורך בנתינה, ועיין בפסוק שאחר זה:
@859 **ולא יהיה בהם נגף בפקוד אותם**. צריך לדעת למה כפל לומר פעם ב' **בפקוד אותם**, ונראה כי לצד שבאה המצוה על זמן שהיו חייבים לשמים לסיבת עון העגל יאמר האומר שבזמן אחר כשירצה למנות אין קפידא בדבר ויכול למנותם אחד אחד לזה אמר **ולא יהיה בהם נגף בפקוד אותם** ריבה מנין אחר זולת הראשון שגם עליו באה האזהרה שאם יפקוד יהיה בהם נגף. עוד ירצה על זה הדרך כי מלבד שבנתינה הם מכפרים על נפשם עוד ולא יהיה בהם נגף בסיבת פקוד אותם, וממוצא דבר אתה יודע כי המנין מצד עצמו יסובב הנגף:
@859 **עוד** ירצה כי יצו ה' ב' דברים, הא' שיהיה המספר על ידי נתינת דבר כאומרו **ונתנו** וגו', וכמו שביאר באומרו **זה יתנו** והוא לטעם כפרת נפשם, והב' שלא ימנו אותם אחד אחד אלא על ידי דבר אחר, והוא אומרו **ולא יהיה בהם נגף בפקוד אותם** אחד אחד אלא על ידי דבר אחר ודרך מספר זה אין בו הקרבת התועלת אלא הרחקת הנזק הנמשך מהמספר, והוא מה שמצינו לשאול דכתיב (ש''א י''א) ויפקדם בבזק פירוש בחרסית וזולת פירושינו זה תקשה מי התיר לשאול לפקוד ישראל בחרסית והתורה אמרה זה יתנו כל העובר על הפקודים מחצית השקל ולדברינו תמצא נחת רוח בענין, ונתתי לבי להשכיל במעשה דוד (ש''ב כ''ד), כי לפי הנשמע מהכתובים כי מנה ישראל אחד אחד בלא אמצעי נוסף על שמנאם ללא דבר, והם דברים תמוהים שיעשה דוד המלך עליו השלום דבר זר כזה, ומצינו שרז''ל (ברכות ס''ב:) אמרו כי מן השמים הכשילוהו בדבר שאפילו תינוקות של בית רבן וכו' לטעם אומרו (ש''א כ''ו) אם ה' הסיתך בי יעש''ד, פירוש דבריהם כי לצד שקרא לה' ח''ו מסית נביא מלאך רע לפי מה שקדם מדבריהם (אבות פ''ד) העובר עבירה אחת קונה לו קטיגור אחד והוא מין העון ממש כמעשהו, ולזה נברא מלאך רע מסית שמו והסיתו והטעהו לעשות כן בסוד אומרם (שם) עבירה גוררת עבירה, ותמצא כי העון עשה דוגמתו שכשם שדברי דוד שאמר הסיתך כשגגה היתה ממנו וח''ו שנתכוון לדבר מילין לצד עילאה חלילה ומי עבד ירא מאלהיו כדוד אלא שגגה היא כמו כן לא הוסת מהמסית לעשות דבר בלתי הגון כמזיד, ועדיין קשה תינח לגבי דוד אמרינן שטעה מה נענה ביואב ממה נפשך תקשה, אם דברי דוד באו אליו סתם פקוד בני ישראל מי אמר לו שאין כוונת דוד לומר לו שיפקדם על פי התורה ומן הסתם לא יוצרך לומר אליו דבר שתינוקות יודעים אותו ואם נאמר כי דוד צוה אליו בפירוש שימנה אותם אחד אחד ולא על ידי מחצית השקל קשה איך קבל דבריו כשאמר לו כן שהיה לו למאן כי דברי הרב ודברי התלמיד דברי מי שומעין ואפילו במצות מלך וזה הלכה רווחת (רמב''ם הל' מלכים פ''ג), ולו יהיה שיואב נעלמה ממנו ומקרה אחד קרה לדוד ויואב, מה נענה בסנהדרין מה נענה בכל איש כשראו שבאו למנותם היה להם לחרוד חרדה גדולה ואימת מות יפלו עליהם ויצעקו על הדבר לפני יואב ולפני המלך גם כן יכולין לבא בטענה הנשמעת ולא יהיה בהם נגף בפקוד אותם, ואם חסו על מחצית השקל יותר מגופן היה להם לטעון שימנו בחרסית כמעשה שאול המלך ואיך לא חסו על נפשם כל בני אל חי:
@859 **והנכון** בעיני כי דוד אמר דבריו סתם ליואב והדבר פשוט כי יואב יודע ספר היה ולא מנאם אלא על ידי דבר אחר בבזק וכדומה לו ותמצא שדייק התלמוד בלשונו (ברכות ס''ב:) לא שקל מינייהו כופר משמע כופר הוא דלא שקל אבל המנין היה על ידי דבר אחר, והנה דייקנו שלא לכל מספר יתחייב הנתינה והטעות שטעה היתה שהיה המספר ללא דבר וכבר פירשנו מדקדוק הכתוב כי לא יפקדו אותם אלא לסיבת דבר כמו שכתבנו למעלה אבל ללא דבר לא, והיא טענה שתמצא שטען יואב לדוד שאין צורך בדבר למנות ישראל, ואולי שאם היה מונה אותם על ידי מחצית השקל לו יהיה שיתחייבו ישראל ב''מ מיתה הנה הוא כופר נפש של כל אחד, והוא אומרם ז''ל שאם היה דוד מונה אותם על ידי השקלים לא היה בהם נגף, ותמצא שאמר הכתוב (ש''ב כ''ד) ויוסף ה' לחרות בישראל ויסת את דוד בהם הראת לדעת כי ישראל היו חייבין על הקודם, ולזה כשבא המספר בהם ללא צורך באין רשיון מאדון הכל שלט בהם הדין ונפרע מהם עונם:
@859 **עוד** אפשר לומר כי כיון שהוזכר בתנאי המנין שצריך לסיבת דבר כל שחסר תנאי א' הרי הם נכללים בגדר הנגף ב''מ, וזו היתה טעותו של דוד שטעה, ולזה תמצא בתשובת יואב אליו ואדוני המלך למה חפץ בדבר הזה פירוש מנין ללא צורך אבל אם היה צורך בדבר יסכים גם הוא ואם המנין היה אחד אחד הגם שיהיה צורך במנין לא יפקדם בדרך זה והיה צריך לומר לו איך יכול לעשות דבר זה, ולפי שאין ענין זה מפורש בכתוב אלא מדיוק הכתוב לא מצא יואב לחלוק עם דוד. או אפשר שחשב כשראה דבר מלך חזק עליו אמר אולי שיש לו טעם נכמס וחש על עצמו ממרוד במלכות ולעולם לא מנאם אחד אחד, ובזה אין קושיא גם כן על כל איש ישראל שלא פקחו על נפשם כי הם לא נמנו אחד אחד ודבר זה שצריך למנותם על ידי סיבה אין עליהם מוטל לדעת אם יש סיבה למלך ולא בדקו אחריו לחזקת כשרותו, נמצינו אומרים כללו של דבר מספר בני ישראל נחלק לג' דינים, האחד הוא מספר שהיה אחר העגל זה היה לצורך גם הוצרך לתת מחצית השקל לצד שהיו חייבים כנזכר, ב' כל שיש צורך במספרם אין צריך למנותם על ידי שקלים אלא אפילו בחרסית אדמה וזה מעשה שאול, ג' כל שאין צורך למנותם אין למנותם אפילו על ידי חרסית וזו היתה טעותו של דוד שהטעהו ה' על שגיונו ועל ידי נתינת מחצית השקל מותר כי זה מונע הנגף הבאה מהמספר. ואם תאמר למה הוצרך דוד למספר ולא הספיק לו מנין שקלי בני ישראל המביאים מדי שנה בשנה, יש לומר שאין הוכחה מהשקלים כי יואב לא הביא אלא מספר האנשים שולפי חרב והשקלים מביאים הכל ואפילו הקטנים כאומרם (שקלים פ''א מ''ג) אדם שוקל על ידי בנו ובתו הקטנים ועל ידי אשתו וכו', ולזה רצה לדעת מספר אנשי המלחמה ודבר זה לא ידענו ממחצית השקל המובא בית ה':
@860 **זה יתנו וגו'**. רז''ל אמרו (תנחומא) לקח כמין מטבע של אש מתחת כסא הכבוד והראהו למשה, וקשה והלא יותר תהיה נשגת הידיעה באמירה כשיאמר לו המשקל בפ רוש ממה ש כ ר בתבנ ת אש כי השערת שיעור הדטות לא תחקק בציור לשער אליה אלא בסמיכות, ונראה בהעיר למה נתרצה ה' במחצית השקל לבד ולפחות היה לו לומר שקל שלם, גם למה יצו ה' לבל יוסיף העשיר ולבל יגרע העני ממחצית השקל, ולתת טעם לב' הערות נתכוין ה' ואמר לו **זה יתנו** דע כי אין עיקר הענין הוא הנגלה אלא הנסתר שזה בא בדמיונו, וכבר כתבנו בכמה מקומות כי שכינתו יתברך שהיא בחינת כסא כבודו יתברך על ידי מעשה בני ישראל יסובבו הפרדה, והוא אומרו (ישעי' נ') ובפשעיכם שולחה אמכם, גם אומרו (משלי ט''ז) ונרגן מפריד אלוף, ועל ידי מעשה העגל שהוא כנגד כל התורה כולה יסובבו הפרדת השכינה בשורשי בחינת כל נשמות ישראל, לזה צוה ה' שיתנו מחצית השקל שהוא סימן למה שהפרידו הם במעשיהם לשוב ליחדם יחד, ולהכרת הדבר הראהו כמין מטבע של אש מתחת כסא כבודו כי שם בחינת שורשי נשמות בני ישראל ואמר לו **זה יתנו** פירוש יחזור לתת סוד מחצית השקל שהפריד והוא זה יסוד וסוד הדבר ולזה יכוין כל נותן ורחמנא לבא בעי לכוין אל המכוון ליחד הנפרד והנחלק, ולזה גמר אומר **את תרומת ה'** והוא מה שרמזנו במחצית השקל כי מתכנית בחינה זו בשם תרומת ה', ומעתה אם ירבה העשיר הנה הוא מפסיד הכוונה שהיא העיקר לזה צוה ואמר **העשיר לא ירבה והדל לא ימעיט** והטעם **לתת את תרומת ה'** כנזכר שאם ירבה או ימעיט אין רישום תרומת ה' ניכר, ולטעם זה הקדים הכתוב זכרון השיעור ואחר כך זכרון הנתינה שהיה לו להקדים זכרון הנתינה ואח''כ שיעורה אלא נתכוין לתת טעם הקצבה למה קצב מחצית השקל ואמר **לתת** וגו' כמו שפירשנו, ואולי כי רמז גם כן שאין הקצבה שוה אלא בבחינת הקצבה אבל בבחינת הכוונה מן הנמנע כי ישוו כל ישראל בכוונת הלב שכל אחד כפי בחינת חיבתו בקונו יעשה הדבר בחשק גדול והבן, ולזה סמך מצות ההשואה לא ירבה העשיר ולא ימעיט העני ממחצית השקל, אבל בבחינת הכוונה אין מציאות להשוות הלבבות:
@860 **ובדרך** רמז תתבאר על זה הדרך כי בא הכתוב לגלות נסתרות לה' אשר יעשה בעולמו דבר שכל רואה יתמה בהלקח איש צדיק ישר קודם זמנו יחצו ימיו כמשפט המתחייב לאנשי דמים ומרמה ויבהלו רעיוני האדם לחשוב אחד מב' דרכים או יכחיש ב''מ אושר הצדיקים כי אין טוב בעמל האלהיי או יחשוב כי זה האיש מצפונו אינו כנגלה ממנו והורעה חזקתו לטוב, אשר על כן אמר ה' **כי תשא את ראש בני ישראל** פירוש אם תראה שיסתלק ראש בני ישראל בלא עת ולא יעלה בכלח כעלות גדיש בעתו הטעם הוא **לפקודיהם** על דרך אומרם ז''ל (שהש''ר פ''א) בפ' אשכול הכופר דודי לי ואמרו ז''ל איש שהכל בו הוא כופר נפשם של ישראל, והוא אומרו **לפקודיהם** לשון חסרון על דרך אומרו (במדבר ל''א מ''ט) ולא נפקד ממנו איש כי לצד חסרון ישראל שנתחייבו לזה אני נוטל את ראשם בעדם לכופר נפשם שלא ימותו כל ישראל, ויתבאר גם כן **לפקודיהם** על דרך אומרם בזוהר (ז''ח) בפסוק כל העובר על הפקודים כל העובר על המצות לומר כי טעם החסרון הוא לצד עוברם על מצות ה', ומעתה לא יחשוב אדם רע לא על המסלק למה ולא על המסתלק כי נסתרו בלתי הגון:
@860 **ואמר** ה' כי לצד שהדור הוא הגורם לילקח הצדיק לזה צריך לתת כל איש ישראל כופר נפש הצדיק שמת בעדו, והוא אומרו **ונתנו איש כופר נפשו** של המסתלק או גם כן של הנשארים שירגישו בפטירת הצדיק שנלכד בשחיתותם וכל אחד ישכיל כי חייב מיתה לשמים ויתקן מעשיו, והוא מה שמפורש בדברי קבלה (ישעי' נ''ז) מפני הרעה נאסף הצדיק פירוש אם הסובבים דבר הרגישו החסרונו ותקנו מעשיהם שלא תבא, ואם לא הרגישו כדי שלא יהיה בתוך הרעה שתבא אחריו, ולזה צוה ה' כאן **ונתנו איש** וגו', ואומרו **בפקוד אותם** פירוש לא יאחרו נתינת הכופר אלא תכף ומיד בפקוד אותם במעשה זה שנטל ראשם כל אחד יתקן מעוותו, ואומרו **ולא יהיה בהם** וגו' הא למדת שאם לא יעשו כנזכר יהיה בהם וגו', ואמר **בפקוד אותם** רמז כי לא יאוחר העונש אלא תכף לפקידה, וכן תמצא שבכל עת שיסתלק הצדיק רעה הבאה אחריו היא סמוכה לפטירתו כמאמרם ז''ל (סנהדרין קי''ג:) וכמו שראינו בעינינו בדורות הללו, ואומרו **זה יתנו** כאן פירש הכתוב מה הוא כופר נפש שצוה לתת ואמר **זה יתנו** יכוין אל ספר התורה דכתיב (יהושע א') לא ימוש ספר התורה הזה מפיך, גם אמרו ז''ל כי הקב''ה לפניו כל היום מונח ס''ת כמשפטו אשר צוה למלך ישראל (דבריסי''ז י''ט) והיתה עמו וגו', והוא מה שהראהו באצבע זה יתנו וסתמו כפירושו שעל המונח לפניו תמיד צוה ה' ובאמצעות מה שילמדו בתורה היא מגינה ומכפרת עון ומרבה זכיות כאומרם (מנחות ק''י) ותלמוד תורה כנגד הכל ואפילו היו ביד האדם עבירות רבות זאת התורה לעולה למנחה ולחטאת ולאשם כאילו הקריב כל הקרבנות המכפרים, והוא אומרו **כל העובר על הפקודים** שהם המצות זה יהיו לו לתיקון כל דבר, ונמשך גם כן אומרו **כל העובר** עם שלמטה לומר תיקון למי שאינו בן תורה במה יתן כופר נפשו כי הוא בור ריק אין בו מים, לזה אמר **כל העובר** וגו' **יתז מחצית השקל** כיששכר וזבולון ושמעון אחי עזריה (סוטה כ''א.) ורבים כהם אשר יחצון כספם לעמלי תורה, ואומרו **בשקל הקדש** פירוש בעד שקל הקודש שהוא התורה, או ירצה שבזה ישוה הוא לנותן אמרי ספר כאומרו (קהלת ז') בצל החכמה בצל הכסף, עוד ירצה על דרך אומרם ז''ל (בכורות ה'.) שקל הקודש כפול היה, ובא להודיע כי מה שיטול מהקודש בעד מחצית כספו לא שיתנכה מחלק הלומד ונמצא כל אחד אין בידו אלא מחצית שכר לא כן הוא כי שקל הקודש כפול היה ונמצא כל אחד בידו שקל שלם והבן, ואומרו **עשרים גרה** וגו' רמז לב' עשיריות שבשכינה, כסא ה', והמלך היושב על הכסא והבן, והנה באמצעות הלומד והעושה יתכוין הדבר ליחוד הבחינות, ורשם באומרו **מחצית השקל תרומה לה'** כי היא זאת שכינת אל חי והיא הנפגמת במעשה ישראל ומתיחדת בתורה ומעשים, ומעתה הגם כי שנים עשו הדבר כל אחד יטול כנגד השנים כידוע הטעם, ואומרו **העשיר לא ירבה** פירוש כי הנותן מחצית שקלו בעולם הזה לא יראה בעיניו שהוא דבר מרובה וירע בעיניו לחלק מחציתו, ואמר **והדל לא ימעיט** פירוש לצד היותו דל ונכסיו מצומצמים לא ימעיט, וטעם ב' אמר **לתת את תרומת ה' לכפר על נפשותיכם** ובערך המוצג יוקטן כל הניתן בעדו, וכאן יש ב' השגות יקרות, א' שבזה יתן תרומת ה' ויחוד קוב''ה ואין ערך לדבר הלז, ועוד לכפר בעד הנפש אשר בעדה יתן אדם עור בעד עור וגו' (איוב ב'):
@860 **ואומרו כל העובר** וגו' מבן עשרים שנה כאן הודיע סוד מה שלא חייבה התורה לאדם אלא עד שהוא בן עשרים שהוא לטעם עד שיגיע לגדר זה שתהיה נפשו שלימה מהשגת המושכל מההדרגות הרוחניים האלהיים אשר נפש ישראל משם הוא ולזמן הנזכר תשיג, והוא סוד אומרו (תהלים ב') ה' אמר אלי בני אתה אני היום ילדתיך, ועיין בדברי הזוהר (משפטים צ''ח.) ויש טעם נכבד למה לא יענש אדם עד גבול זה כי הוא לצד שעדיין לא שלימה דעתו בהכרת המושכל ובהשכלת הידיעה ובתגבורת המספיק להערכת מלחמה לשבור כח המסית ולנצח תאות הטבעיות ולהשכיל ברצון הנפש ולהבחין את אשר ידבר בלבו אם לאושר ובהיותו כן כ' הנה הוא שלם בדעתו להחזיק מגן וצנה בתגבורת השכל וההבחנה והבחירה בדרך החיים והבן:
@865 **ונתת שמה מים**. נראה שאין חיוב לעשות הדבר על ידי משה אלא הוא הדין זה יכול לתת מים בכיור וכשם שאמר בתחלת הפסוק ועשית כיור וגו' שאין הכוונה שיעשה הוא:
@866 **את ידיהם ואת רגליהם**. לא היה צריך לומר אלא ידיהם ורגליהם, אלא נתכוון לומר שאין רחיצה לידים בלא רגלים ולא לרגלים בלא ידים, לזה אמר **את** פירוש עם ידיהם רגליהם ועם רגליהם ידיהם והם דברי רז''ל בזבחים (י''ט:) שצריך לקדש ידים ורגלים כאחד:
@868 **חק עולם**. אפילו עלה מבית הטבילה שנטהר מטומאה חמורה חוקה חקק ה', ולזה הוצרך לומר פעם ב'.
@868 **ולא ימותו** הא אם לא רחצו הגם שעלו מטבילה הרי הם במיתה ולא תועיל טבילה:
@870 **ואתה קח לך**. פשט הכתוב הוא שיקח הוא משלו שמן המשחה, לזה אמר **ואתה** פירוש כי מצוה זו אתה תעשנה ואינו כשאר מצות שאני מצוך לנוכח וכוונתי שהזולת יעשה, והגם שכלל הכתוב השמן והסממנים בנדבת רבים דכתיב (לעיל כ''ה ג') וזאת התרומה וגו' בשמים לשמן המשחה וגו', כאן גילה לו ה' כי יחפוץ בשל משה בפרטים אלו:
@870 **עוד** יתבאר ע''פ מה דתניא בכריתות (כריתות ה'.) שמן שעשה משה בו שלקו וכו' בו נמשחו כהנים ז' ימים וכו' וכולו קיים לעתיד ע''כ, הא למדת שלא נעשה שמן המשחה זולתו, וכן כתב רמב''ם בפ''א מהלכות כלי המקדש שמעולם לא נעשה שמן אחר זולת מה שעשה משה, והוא אומרו **ואתה קח לך** אתה תעשה ולא זולתך ורמז באומרו **קח לך** על פי דבריהם שאמרו (ילקוט תשס''ד) שעתיד משה לעמוד לשרת לעתיד לבא, והגם שבפרשת הקטורת נאמר (פסוק ל''ד) קח לך שם לא נאמר ואתה:
@870 **וקנמון בשם מחציתו**. רז''ל אמרו (כריתות ה'.) מחצית הבאתו נמצאת אומר שצריך להביא ת''ק, והקשו בגמרא ודלמא קנמן בשם ר''ן כקנה בשם, ומתרץ אם כן לכתוב קרא קנמן בשם וקנה בשם מחצה ומחצה ר''ן ע''כ, ואפשר לנו לתרץ עוד שאם כן לא היה צריך לומר מחיצתו כי אני יודע שר''ן הם מחצית הת''ק אבל אי אמרינן מחציתו של קנמן בא לומר ששוקלים אותו ב' פעמים, ומה שראיתי לראב''ע שכתב שאין מנהג הישמעאלי להוסיף אפילו כגרגיר חרדל במשקל, אין זה אמת, שעל כל פנים צריך הכרת ההכרעה ואף במשקלי הזהב הגם שמתחכמין לשקול בעיון כף כנגד חברתה בלא הכרעה אף על פי כן כשיצטרף ב' משקלים יוכר ההכרע ביותר, וטעם שהש''ס לא בחר לתרץ כדברינו, כי יש לומר לעולם ר''ן לבד הוא אומר ואומרו **מחציתו** שיביא קכ''ה לבד וקכ''ה לבד:
@879 **קודש הוא**. פירוש תכונתו, ואפילו יעשהו מחולין, והעושה במתכונתו כמעלה עולה וחטאת לעצמו, ואם עשאו להתלמד בו או על מנת ליתנו לציבור מותר כן אמרו בכריתות (ה'.), עוד נראה אומרו **קדש הוא קודש יהיה** על זה הדרך קודש הוא זה שמן שעשה משה שקדושתו יתירה שהסך ממנו חייב כרת וכמו שאמר בסמוך ואשר יתן ממנו ואמרו בכריתות ממנו פירוש משמן שעשה משה ולא משמן המשחה זולתו, ואומרו **קדש יהיה לכם** זה שמן דורות שאינו שוה לקדושתו של שמן משה ואין חייב אלא הרוקח כמוהו, ותיבת ממנו לכד לא תספיק שזולתה הייתי אומר עד שימשחנו כולו, ורז''ל (שם ו'.) דרשו מפסוק זה שצריך לעשותה במקום קודש, ולדבריהם היה לו לומר כן במצותו לא באזהרת לא תעשו כמוהו, ודבריהם ז''ל אינם אלא אסמכתא להלכות שבידם ודברינו הם פשט הכתוב:
@882 **ממולח טהור**. נראה כי פירוש טהור הוא שלא יראה בו ערבוב גוונים כי לצד שיש בו אחד עשר סממנים יתרבו הגוונים והגם שיערבם יחד לצד ריבוי הסממנים וריבוי הכמות שלש מאות וס''ח מנים תשאר איזה פינה בו שאין הגוון שוה בה והגם שיהיה שוה אף על פי כן כשידקדק בחוש דקות הראות ישכיל כי איננו גוון אחד ואינו קרוי מציאות זה טהור, לזה אמרו **ממולח טהור** פירוש זך שיראה גוון אחד ממש באמצעות התערובת מעשה אומן ובאמצעות היותה דקה ביותר:
@884 **והקטרת אשר תעשה**. יתבאר על פי דבריהם ז''ל (שם ו'.) שאמרו חכמים כל יום מתקן במתכונתה והיה מכנים, והוא אומרו **והקטורת אשר תעשה** פירוש כל מה שישנו בהכשר מעשה בית ה' במתכונתה לא תעשו הא למדת המפטם חצי מנה חייב כרת:
@884 **לא תעשו**. פירוש אפילו שלא להריח אסור בלאו אבל בכרת דוקא להריח, ולזה לא רשם תנאי להריח בפסוק זה אלא בפסוק שהזכיר בו עונש כרת:
@887 **ראה קראתי בשם**. אולי שיכוין לומר שיראו רמז הענין בשמו ושם אבותיו, **בצלאל** שעשה צל לאל, **בן אורי** שעשה מקום לאשר אור לו, **בן חור** שעשה ישראל בני חורין מעון העגל כאומרם ז''ל (שמו''ר פנ''א) בפסוק משכן העדות עדות לכל שנמחל להם עון העגל הרי שנרשם בו הדבר בשמו ושם אבותיו. ובזה יבא על נכון אומרו **ואמלא** בתום' וא''ו לומר מלבד זו עוד אני מוסיף בו מלאי מהחכמה, ואומרו **בחכמה** ולא אמר חכמה, ואולי שיכוין על פי דבריהם ז''ל (ברכות נ''ה.) בפסוק (דניאל ב') יהב חכמתא לחכימין שאין הקב''ה נותן חכמה אלא למי שיש בו חכמה וכו', והוא אומרו **ואמלא** וגו' בחכמה שיש בו אוסיף למלאותו יותר וכן בתבונה וגו':
@896 **לקדש**. פירוש לפי שכל המעשים הרשומים בפרשה לא נאסר מעשיהם להדיוט זולת ב' דברים אלו שהם שמן המשחה וקטורת הסמים לזה דקדק לומר בהם **לקודש** לומר אותם שתכונת מעשיהם מיוחדים לקודש והקדושה חלה על מתכונת הדבר לצד תכונתו לבד מה שאין כן בכל המעשים שבעולם שכל שלא קרא עליו קודש אינו קודש:
@897 **ויאמר ה' וגו'**. צריך לדעת למה שינה לומר כאן **ויאמר**, וראיתי במכילתא שאמרו ויאמר ה' למשה לאמר לא על ידי מלאך ולא על ידי שליח, וצריך לדעת מה נשתנה פסוק זה לדרוש בו כן ויותר היה נכון לומר הדברים בוידבר האמור ראשון בתורה, ואולי שהרגישו מקושיתנו ואמרו כי ויאמר לשון מעלה על דרך אומרו (ישעי' ג') אמרו צדיק כי טוב ומה היא המעלה שאמר ה' אליו בלא אמצעי, ובסמוך יתבאר הטעם באופן אחר:
@898 **ואתה דבר וגו'**. צריך לדעת אומרו **ואתה** מה שאינו רגיל לומר בשאר מצות, גם תוספת וא''ו, עוד למה כפל לומר **דבר אל בני ישראל לאמר**, והגם שפירשתי בתחלת פרשת תרומה כי צריך לומר דבר ולא תספיק לאמר לבד, כאן הוסיף לומר תיבת לאמר פ''ב מלבד לאמר ראשונה, עוד צריך לדעת אומרו **אך**, ואומרו **שבתותי** לשון רבים, ורבותינו ז''ל דרשו בפרק כלל גדול (ס''ט.) שבא ליתן שמירה אחת לשבתות הרבה יע''ש, ובמקום אחר (מכ. לתא) דרשו שבתותי להביא דברים שהם משום שבות, ונראה לפרש הכתוב וקודם נעמוד על כוונת תיבת אך את שבתותי ונעלה דרך שם להשכיל אומרו ואתה ותוספת לאמר, ויתבאר על פי מה שאמרו רבותינו ז''ל (שבת קכ''ט.) שמחללים את השבת לצורכי חולה שיש בו סכנה ולכל פקוח נפש וכדומה, והוא מה שרמז באומרו **אך את שבתותי** פירוש יש מציאות שאין לך לשמור שבת, ודקדק באומרו **את שבתותי** לכלול כל הנקרא שבת בין שבת בראשית בין יום הכיפורים בין שאר מועדות למלאכות האסורות בהם, גם לרבות אפילו שבת אחר שבת אם עדיין הוא מסוכן לא יאמר אדם כבר חללתי עליו שבת אחת אלא הרי הוא בהיתר עד שיצא מהסכנה. עוד נתכוון לרמוז ענין אחד שהעלו רבותינו ז''ל (יומא פ''ד:) (האחרונים) והוא שאם אמדוהו לחולה שיש בו סכנה שצריך לעשות לו רפואה ידועה שיש בה מלאכת שבת ח' ימים אין אומרים שלא לחלל אלא שבת אחד אלא יעשה מיד אף על פי שמחללין ב' שבתות ע''כ, והוא אומרו **אך את שבתותי**:
@898 **עוד** ירמוז באומרו **את שבתותי** לתת טעם למיעוט למה אני אומר לך שתחלל שבת על החולה אין זה קרוי חילול אדרבה זה קרוי שמירת שבת חלל עליו שבת אחד כדי שישמור שבתות הרבה, ושיעור הכתוב כפי זה הוא על זה הדרך שמרו שבתות הרבה על ידי שתעשה מיעוט שמירה בהם ומציאות הדבר הוא לחלל שבת על החולה שבזה אתה מחלל שבת אחד לשמור שבתות הרבה, ואין אומרים בזה אין אומרים לאדם חטא בשביל שיזכה חברך, כי דוקא בעובר עבירה ומחלל שבת בידו כאותה שאמרו (שבת ד'.) הדביק פת בתנור שחלל שבת וחייב מיתה על זה אין אומרים לו חטא כו' אבל חולה אמרה תורה חלל אפילו דוד מלך ישראל אם יזדמן הדבר לידו יחלל והנמנע מהדבר אין זה אלא מזלזל במצות האל ח''ו, וגמר אומר **כי אות היא ביני וביניכם** פירוש ואם כן אם אין שומר אין שבת, ואומרו **לדעת** כאן נתחכם ה' להודיע שקדושת נפש ישראל גדולה מקדושת שבת שזה נדחה מפני זה ודבר פשוט הוא שהקטן הוא הנדחה מפני הגדול, והוא אומרו **לדעת** פירוש בזה אתה יודע כי אני ה' מקדשכם יתגדל ויתקדש שמו יתברך:
@898 **ורש'** 'י ז''ל פירש אך למעט מלאכת המשכן שלא תהיה בשבת, ודבריו אמת אלא שמשמעות המיעוט הוא בשבת לא חוץ ממנו, גם מנין יעלה על הדעת שיעשו מלאכת המשכן בשבת שהוצרך למעט, ואין כוונתינו בפירוש זה להקשות ולהשיג על הפירושים ובפרט דברי רש''י המקודשים ואלו ואלו דברי אלהים חיים. ולדרכנו נשכיל לדעת כוונת ה' באומרו **ואתה דבר** וגו' שהכוונה היא לצד שרמז ה' מיעוט אחד בשמירת שבת ומיעוט זה לא נודע מעשהו מה יגיד ואל משה אמר בעל פה תבונתו ולא בכתב מפרש כי תורתינו שתתעלה דבריה מזוקקים ואותיותיה ספורות וכל אות ואות מגדת הלכות ונפלאות כאשר יסד בה האדון בחכמה רבה בשבעים פנים וארבעה אופנים ול''א נתיבות וכל נתיב בכמה שבילין, וצא ולמד מאמרם ז''ל (במד''ר פי''ט) בפסוק שלשת אלפים וגו' והכל במקרא מועט, אלא שיש לך לדעת שיש דרשות ודקדוקים בתורה שהם חובת כל אדם נברא להכירם והם דברים שיש בהם הלכות ויש שאין בהם חובת כל אדם, ואל יקחך לבך לדבר לפני האלהים למה יעשה כה לעבדיו להעלים מהם תעלומות חכמה ולא הודיע כל דבר בכתב מפרש, הנה תשובתך לנוכח עיניך כי הם דברים שלא יכילם ספר, וצא ולמד מאמר קדמונינו (אבדר''נ פכ''ה) שהיו אומרים אם יהיו הרקיעים גוילים כו' אינו מספיק לכתוב מה שלמד מרבו ולא חסר ממנו טפה מהים וכן תלמידו אמר עליו, והכל רמוז יושר במקרא גדול אדונינו ורב תבונות אשר כתב מקרא מועט ובו השמיע מה שאין כח בנבראים לכתוב מיום ברוא אלהים אדם על הארץ עד סוף כל הדורות והכל נמסר למשה בסיני, ולזה לצד שאמר בכתב מיעוט בשמירת שבת ובעל פה נאמר למשה כוונת המיעוט והיא תורה שבעל פה לזה צוה ה' למשה לומר לישראל כוונת הדברים אשר הודיעו להשמיעם לכל עם ישראל כי דבר זה הוא חובה להשמיע לכל, והוא אומרו **ואתה** פירוש מלבד המכתב תוסיף אתה לדבר להם בעל פה כוונת המאמר הסתום שהוא מה שממעיט בשמירת השבתות:
@898 **וזה** הוא אומרו **דבר אל בני ישראל לאמר** פירוש דבר להם כוונת המאמר מה שפירשתי לך בו כי המאמר עצמו כבר אמר לאמר ולא בא אלא על אמירת הפירוש הנאמר לו בעל פה כנזכר כי הוא זה מהדברים שהם חובת אדם לשמוע, ועל פי דרך זה יש לנו להתהלך באורחות חיים בכל התורה אשר יאמר הכתוב **לאמר** וחזר לומר **דבר אל בני ישראל** אחת לדברים שבכתב ואחת לדברים שבעל פה הצריכין להלכות אשר יעשה אותם האדם והגם שפירשנו באופן אחר אלו ואלו דברי אלהים חיים:
@898 **עוד** נראה לפרש אומרו **ואתה** וגו' על דרך מה שאמרו במסכת שבת (י':) בפסוק לדעת כי אני ה' וגו' שאמר הקב''ה למשה מתנה טובה יש לי בבית גנזי כו' מכאן שהנותן מתנה לחבירו צריך להודיעו, והטעם כדי להחזיק לו טובה וחינות והקשו מקירון פני משה ואמרו כי של משה עבידא לאגלויי כו' ע''כ, והוא אומרו **ואתה דבר** פירוש לא תקח שיעור מעצמך כשיתגלה לך מתנת קרנות הוד ולא הודעתיך תאמר כן הדברים במתנת שבת שאני נותן לישראל ולא תגלה לא כן הוא אלא דבר וגו' ולא תקח המשפט ממך, והטעם הוא שאתה עתיד לדעת אבל ישראל לא עבידא לאגלויי שידעו שיש להם, ואומרו **אות היא** פירוש ואל תאמר והלא גם שבת עבידא לאגלויי וידעו מעצמן שיש להם בו מנוחה ועונג גם התכוננות לגוף לבל יחלה מיגיעות הטרדה וכמה פרטי הטובות, לזה אמר **כי אות היא** פירוש כל המנוחה והעונג הנרגש לישראל ביום השבת אינו אלא אות היא ביני וגו' פירוש סימן לטובה הגנוזה והיא בחינת עולם שכולו שבת והוא מושלל ההשגה זולת על ידי מצות שבת והיא נשמה יתירה הבאה ממנו והבן כי הוא סוד עתיק, ואם כן לא עבידא לאגלויי לזה **דבר** וגו' **לדעת** וגו' כי צריך להודיע מעלת המתנה לאחזוקי עליה טובה ולברך לנותן ברוך הוא אשר מקדשם בקדושת שבת להשיג האושר המופלג והמופלא:
@899 **ושמרתם את השבת**. צריך לדעת למה חזר לצוות על שמירת שבת ולתת טעם חדש כי קודש, ונראה כי לפי שקדם להתיר חילול שבת לחולה כמו שפירשנו בפסוק שלפני זה וחש שיטעה הטועה כי לגבי חולה זה נעשה שבת חול ויש לחללו אפילו לפרטי הרפואה שאין בהם פיקוח נפש תלמוד לומר **ושמרתם את השבת כי קודש הוא** פירוש בקדושתה עומדת לכל שאר הפרטים שאין בהם פיקוח נפש. עוד יתבאר על פי מה שאמרו ז''ל (מנחות ס''ד.) אמדוהו לב' גרוגרות וכו' והיו ב' עוקצים א' יש בו ב' גרוגרות ואחד יש בו ג' לא יכרתו אלא עוקץ שיש כו ב' ולא שיש בו ג' ע''כ, והנה בבחינת המעשה אשר יעשה האדם אחד הוא בין אם יכרות בעל ב' או בעל ג' אבל בערך מעשה הנעשה בשבת ישתנה היות כריתת ב' לכריתת ג', והוא אומרו **ושמרתם את השבת** פירוש שלא יהיה נעשה בה דבר מלאכה שאין צורך בו לאותו חולה **כי קודש היא** תלה הדבר בשבת ואם כן כשיכרתו עוקץ שיש בו ג' ואינו צריך אלא לב' נמצאת שבת מחוללת בערך הג' וזה היא חילול קדושתה כי גם בערך חולה זה שיש בו סכנה עומדת שבת בקדושתה:
@899 **מחלליה מות יומת**. אמר **מחלליה** לשון רבים וגמר אומר בלשון יחיד, יתבאר על פי מה שפירשנו כי יש מחלל באופן הנזכר שהותר לכרות עוקץ של ב' תאנים לחולה וכרת בעל ג', ויש שכרת ללא צורך ושניהם נקראים מחללים אבל אינו חייב מיתה אלא אחד מהם אבל הכורת לרפואת מסוכן שכרת במקום של שנים של שלש והואיל ועיקר המלאכה ברשות נעשית אינו בן מות, ולפי פשט הכתוב ירצה **מחלליה** בין עושה בפני עדים ואחר ההתראה בין עושה בינו לבין עצמו א' מהם שהוא העושה בפני עדים והותרה הוא שימות אבל הב' לא יומת אלא **ונכרתה** וגו' במשפט אל עליון:
@899 **עוד** ירצה ע''פ דבריהם ז''ל (שבת ק''ו:) ישב האחד על הפתח ולא מלאהו וישב הב' ומלאהו השני חייב, והוא אומרו **מחלליה** פירוש לצד שלא היתה מלאכה זו נעשית אלא באמצעות שנים אלו שהרי זולת הראשון לא היה ניצוד ונמצאו ב' חללוה, והוא אומרו **מחלליה מות יומת** א' מהם לבד הוא שחייב. עוד יתבאר על פי מה שאמרו ז''ל (ביצה ל''ד.) וזה לשונם אחד מהם מביא את האור ואחד מביא את העצים ואחד שופת את הקדירה ואחד מביא את המים מסיק בגמרא שאם מביא האור היה לבסוף הוא חייב וכולן פטורים, והוא אומרו **מחלליה** אחד מהם הוא שחייב מיתה וכולן פט ורים:
@899 **מות יומת**. כבר פירשתי בפרשת משפטים (כ''א י''ב) טעם הכפל, כי זה האיש בן מות הוא לשמים ומרשה ה' התחתונים להמית בן מות זה, ולשלול בן מות אחר שלא יהיה דינו מסור לבריות אלא לשמים, והוא מה שהזכיר בסמוך **כל העושה בה מלאכה ונכרתה** וגו':
@899 **כי כל העושה**. פירוש טעם שזכרתי לך לשון יחיד במחלליה לא יחשוב החושב שהמחלל האחר שאינו בעדים וגו' אין לו עונש מיתה כל עיקר אלא הוא כעובר על לאו ועשה של קדושת שבת לא כן הוא אלא כל העושה בה מלאכה ונכרתה הנפש ואפילו בלא עדים והתראה, ומעתה מה שמיעט הכתוב באומרו לשון יחיד אינו אלא לענין עשות משפט בבית דין של מטה, ולפי מה שפירשתי בפסוק **מחלליה** כי מה שמיעט הכתוב באומרו לשון יחיד הוא מי שכרת עוקץ שיש בו ג' לחולה שאינו צריך אלא ב' שאפילו היה בהתראה ועדים פטור, הוצרך לומר כי **כל העושה** וגו' שלא תחשוב במשמעות המיעוט שבא על העושה במזיד בלא עדים כנז' ואין בו עונש תלמוד לומר **כי** וגו':
@900 **ששת ימים וגו'**. צריך לדעת למה הוצרך לצוות עוד לזה, עוד למה אמר **יעשה** ולא אמר תעשה כסדר שדבר בו פעמים רבות, עוד למה שינה כאן להזכירו בשם **יום השביעי** ועד עתה לא הזכירו אלא בשם שבת, ועוד רואני שגמר אומר להזכירו בשינוי השם **כל העושה מלאכה ביום השבת**, גם לא היה צריך לומר אלא כי כל העושה בו, ואולי שרמז הכתוב כאן מה שאמרו במסכת שבת דף ס''ט תנו רבנן היה מהלך בדרך או במדבר ואינו יודע אימתי שבת מונה ששה ימים ומשמר יום אחד, והעמידוה בש''ס שבכל יום עושה פרנסת אותו יום ואפילו בשבת, והקשו אם כן במה מנכר ותרצו בקדושא ואבדלתא, וכתבו התוס' שלא יהלך ביום שבת וטעם שלא אמר בש''ס מנכר בהליכה משום שאין זה היכר בשבת אי נמי שאפילו ביום שמשמר הולך, והנה לדרך הראשון יתבאר הכתוב על זה הדרך **ששת ימים** וגו' הכתוב מדבר במי שהיה במדבר או בים ואינו יודע מה יום מימים ואמר **ששת ימים יעשה** וגו' פירוש יעשה בהם התר מלאכה לעשות דבר המוכרח שהוא פרנסת אותו יום, ולזה לא אמר תעשה אלא **יעשה** פירוש יכול הוא לעשות לחיות נפש, **וביום השביעי** פירוש לחשבונו, **שבת שבתון** פירוש אינו כפי האמת שבת אלא לענין שבתון כאמור במצות השמיטה דכתיב (ויקרא כ''ה ד') שבת שבתון יהיה לארץ שלא יעשה מלאכה בארץ גם ביום השביעי לחשבונו יעשה בו שביתה שלא תהיה בו הליכה, ואומרו **קודש לה'** שצריך לקדשו בקידוש והבדלה כאילו הוא יום שבת, ולדרך שפירשו שאין הפרש בין יום השביעי לשאר ששת ימים אלא לענין קידוש והבדלה יתבאר על זה הדרך **שבת שבתון** לענין קודש לה' פירוש לקדשו וגו', ואומרו **כל העושה מלאכה ביום השבת מות יומת** דקדק לומר ביום השבת לשלול יום השביעי שבו מדבר הכתוב שהוא שביעי לחשבון יום זכרונו שאם עבר על מה שצריך להזהר בו אינו חייב, הגם שיעשה בו מלאכה שאינה צריכה הרי זה פטור הגם שמקדשו בחזקת יום שבת:
@901 **ושמרו בני ישראל וגו**. צריך לדעת למה הוסיף עוד שמירה אחרת, עוד צריך לדעת כוונת. אומרו **לעשות את השבת**, ורבותינו ז''ל דרשו מה שדרשו, ואולי כי בא לצוות שישמרו לבל יבואו לידי מכשול טעות היום כדי לעשות את יום השבת לאמיתו, והוא אומרו **ושמרו בני ישראל את השבת** כדי **לעשות את השבת** הידוע שלא יבא לידי טעות, והגם שיקדש יום שביעי כנז' בסמוך זה אינו יום השבת כפי האמת. או ירמוז לפי מה שפירשנו בפסוק שלפני זה שיצו ה' למי שאבדה לו ידיעת היום שימנה ו' ימים ומשמר הז' לזה בא לתת טעם ואמר **ושמרו בני ישראל את השבת** שהוא יום שמקדש. למנינו, והטעם הוא **לעשות את השבת** האמיתי כדי שלא יפקע מזכרונו מצות יום המקודש, וטעם שהזכיר יום ז' בשם שבת לא חש עליך לטעות ממה שגמר אומר לעשות את השבת הרי זה מראה באצבע כי שבת ראשון הוא שבת אשר עושה לחשבונו:
@901 **עוד** ירצה על דרך אומרו (בראשית ל''ז י''א) ואביו שמר את הדבר פירוש ממתין ומצפה מתי יבא, והכונה בזה לצוות שלא יהיה השבת כדבר טורח לצד מניעת מלאכת הרצון ומצוא החפץ אלא צריכין לשמוח בו בשלימות הרצון וחפץ בדבר ותמיד יהיה ממתין ומצפה מתי יבא, ואומרו **לעשות את השבת** לשלול הכוונה כחפץ מצות השבת למרגוע הגוף ולעונג אשר יתענג אלא לצד עשית מצות השבת ולא לתכלית המורגשות:
@901 **עוד** ירצה על דרך אומרם ז''ל (יומא פ''א) שצריך להוסיף מחול על הקודש ולא לימנע ממלאכה אחר שיגיע ויתנוצץ יום השבת אלא צריך להכין עצמו בקדושת שבת ויצא כחתן לקראת כלה ויהיה יושב ומשמר עד שיגיע השבת לעשותו פירוש לקיים מעשים הצריכין בו. עוד ירצה באומרו **לעשות את השבת** כי מה שמוסיף מחול על הקדש יסכים ה' לקרותו שבת ונמצא זה האיש עושה שבת ממש כי שעות מיום ו' וגם שעות מיום א' שהם חול בני ישראל עושים אותם שבת:
@901 **עוד** ירצה על דרך אומרם ז''ל (ב''ר פי''א) אמרה שבת לפני הקב''ה לכלם נתת בן זוג ולי לא נתת בן זוג אמר לה הרי ישראל וכו' ע''כ, הנה כי השבת חסר פרט א' מפרטי השלימות ותיקונו הוא על ידי שישמרוהו ישראל, והוא אומרו **ושמרו בני ישראל את השבת**, מה טעם **לעשות את השבת** לשון תיקון שבזה יתוקן מעשהו של שבת ונמצא לו בן זוג:
@901 **עוד** ירצה שצריך לשמור את השבת לבל יהיה בו דבר חול בין ממנו בין מהזולת ולא יאמר אדם די לי במה שנשמור עצמו מחללו ואם יתחלל מהזולת מה בכך אלא צריך שיהיה שומר אותו לבל יתחלל כמו ששומר גנו ופרדסו ובכלל גדר זה שישתדל לשמור לבל יבא לידו דבר שוגג שיתחלל בו שבת על דרך אומרם ז''ל (שבת י''א.) לא יקרא לאור הנר וכל הסייגים והשמירות לבל יתחלל שבת אפילו במציאות שהוא פטור עליהם:
@901 **עוד** ירצה לומר כי משונית שמירה זו מכל שאר שמירות המצוה כי שמירה זו נחשבת בגדר עשיה, והוא אומרו **ושמרו** וגו' **לעשות** הרי שלך לפניך שקורא לשמירה עשיה, ואולי כי הטעם הוא על פי דבריהם ז''ל שאמרו (קידושין ל''ט:) ישב אדם ולא עבר עבירה נותנין לו שכר כעושה מצוה והעמידוה בגמרא בבאה עבירה לידו ולא עבר ע''כ, וכמו כן ביום המקודש אין לך באה עבירה לידו של מלאכות כזה כי בכל עת מזדמנים לפניו מלאכות הרבה מהארבעים ותולדותיהם בפרטי המחובר ובפרטי הבישול ובפרטי מקח וממכר שהאדם רגיל בהם כל היום ומזדמנים באין מספר והוא נשמר מהם לזה יחשב להם כעושה מצוה:
@901 **עוד** ירצה להיות שקדם וצוה על שמירת השבת תבא הסברא לומר שכל השומר שבת הנה הוא נוטל שכר שבת, לזה צוה ה' ואמר **ושמרו בני ישראל** פירוש דוקא בני ישראל הם שישנם בשמירת שבת ולא שום אומה ולשון, ולזה לא אמר ושמרתם שאז יהיה נשמע שבא לצוות על השמירה והוא בא לשלול חוץ מבני ישראל שלא ישמרו שבת, והוא מאמרם ז''ל (סנהדרין נ''ח:) גוי ששבת חייב מיתה שהרי מיעטם הכתוב ואזהרתם זו היא מיתתם:
@901 **עוד** ירצה על זה הדרך **ושמרו בני ישראל את השבת** פירוש כשישמרו אפילו שבת אחת ולאו דוקא אם ישמרו אלא גם אם יסכימו בדעתם לעשות מצות השבת, והוא אומרו **לעשות את השבת** מעלה עליהם הכתוב כאילו עשו לדורותם, וכפי זה איש ישראל ששמר אפילו שבת אחת ומת אין מנכין לו משכר העולה לו אם היה שומר לדורות עולם (מכילתא):
@901 **עוד** ירצה לפי מה שהקדמנו בפסוק אך את שבתותי כי צוה ה' לחלל שבת בשביל פיקוח נפש כאן ביאר הכתוב כי לא נתמעט שבת בשמירה אלא בערך בני ישראל אבל בערך זולתם להחיות עכו''ם הגם שיהיה גר תושב ששומר שבע מצות ונסתכן סכנת מות לא יחלל ישראל שבת בשבילו (רמב''ם הל' שבת פ''ב), והוא אומרו **ושמרו בני ישראל** לבל ימות מהם **את השבת** פירוש לצד אזהרת שבת אלא יחללוהו או על זה הדרך שבת וישראל לפניך זה לחלל וזה למות תשמור ישראל ויתחלל השבת אבל עממין לא והטעם.
@901 **לעשות את השבת** פירוש כלום מה טעם אני מתיר לך לחלל שבת עליו הוא **לעשות את השבת לדורותם** חלל עליו שבת אחת כדי שישמור שבתות הרבה אבל עכו''ם שאינם בני שבת לא:
@901 **או** ירצה על זה הדרך אימתי אמרתי לך לשמור איש ישראל אפילו בערך כבוד שבת דוקא **לעשות** פירוש באדם שישנו בגדר עמוד לעשות אבל מי שודאי לא יקום ולא יגיע לשבת לשומרו הגם שרפואות אלו יועילו לשעות או לימים לא יחלל עליו שבת:
@901 **עוד** ירצה על פי דבריהם ז''ל (ר''ה ל''א.) שעולם הבא נקרא עולם שכולו שבת, ואמרו עוד (שמו''ר פכ''ה) שקול שבת כנגד כל התורה כולה, לזה אמר **ושמרו בני ישראל את השבת** והטעם **לעשות להם את השבת** פירוש העולם המתכנה בשם שבת שיהיו בו לדורי דורות, והוא אומרו **לדורותם** לשלול עולם הזה שאין האדם קיים בה לדורות, **ברית עולם** פירוש ברית כרותה לשומר שבת שינחל עולם עליון:
@901 **עוד** יתבאר על פי דבריהם ז''ל (ביצה ט''ז.) שאמרו שביום שבת באה נשמה יתירה לישראל כרמוז באומרו **שבת וינפש**, והוא סוד הנעלם שלא גלהו ה' לאומות כאומרם ז''ל (שם) נשמה יתירה לא אודעינהו, והעירותי בצפונו של דבר במה שהקשו בגמרא על הודעת שבת לאומות שאם לא אודעינהו לא לענשו עלה ואמרו שבת אודעינהו נשמה יתירה לא אודעינהו ע''כ, וקשה ולמה לא יבואו כטענה גם כן ויאמרו אם היה מודיעם נשמה יתירה היו מקבלין שבת ולא לענשו עליה, ונראה כי לזה נתחכמו רבותינו ז''ל ואמרו (שכת י':) מתנה טובה וכו' פירוש כי אין דבר זה אלא בגדר מתנה אשר נתרצה ה' לתת לעמו ואינה שכר שיבואו בטענה האומות כנזכר כי אין דרך לומר למה לא נתת לנו מתנה גם אנחנו, עוד תמצא כי כבר קבלו ישראל עליהם שמירת שבת קודם נתינת נשמה יתירה, ומעתה ענוש יענשו כל האומות על השבת ועינינו רואות, וענין נשמה זו היתירה רמזו מקומה רבותינו באומרם מתנה טובה בבית גנזי וידוע הוא מקום הנקרא גנזי המלך שהוא בחינת עולם עליון ונשמה זו מחצבה שם היא ולזה תקרא שבת כאומרם ושבת שמה כשם העולם שממנו היא שנקרא עולם שכולו שבת (ר''ה ל''א.) ועולם זה אין בו עצבון ועליו לא בא כדבריהם בו אלא עונג ושמחה, ולזה צוה ה' להרחיק ביום שבת כל אותם בחינות החול המלאכה והעינוי כי באחת מהנה תגעל הנשמה משבת בקרב איש, ולזה תמצא שעיקר איסור אזהרת מלאכות שבת ביאר ה' שהם במחשבה כאומרם (ביצה י''ג.) מלאכת מחשבת אסרה תורה, ואפילו דבור של חול אסור (שבת קי''ג:) דכתיב (ישעי' נ''ח) ממצוא חפצך ודבר דבר, והכל לצד תוספת נשמה העליונה לעשות לפניה כסדר עולם שבאה ממנו, והוא מה שצוה ה' באומרו **ושמרו בני ישראל את השבת** פירוש נשמה הנקראת שבת ותכלית שמירה זו היא השגת עולם ששמו שבת, והוא אומרו **לעשות את השבת**, ותדע כי מן הנמנע החלטי שישיג אדם עלות לעולם עליון זולת באמצעות השגת ענף ממנו בהיותו בעולם הזה, ולזה אם לא ישיגו ישראל בחינת נשמה זו אין בהם יכולת לעמוד בגדר עליון. והוא אומרו **לעשות את השבת** פירוש שבאמצעותו תעשו לכם את השבת שתוכלו השג עמוד שם ולהתענג נפשם בגנזי עליון, ואומרו **לדורותם** כי שם יתקבצו כל דורות בני ישראל שהיא בחינת עולם הבא:
@901 **עוד** ירצה לשון דירה ולזה כתובה חסרה בלא וא''ו והם דברינו שירמוז אל מקום דירת הנשמות והוא עולם המקווה שכרת ה' ברית לתתו לנו, והוא אומרו **ברית עולם**, ואולי שירמוז באומרו ברית עולם לתרי''ג מצות שחשבון ברית עולה תרי''ב וכולם תלויים בשבת הרי תרי''ג, ולזה סמך תיבת **ברית לעולם** לומר כי על ידי שמירת שבת הוא מקיים כל תרי''ג מצות שהוא שקול כנגדם והנה עולמו:
@901 **ואומרו ביני ובין בני ישראל** פירוש אין זר אתנו בעולם הלז, ואולי שגם המלאכים לא ישבו במסיבתינו בעולם זה כי הוא למעלה מעולם המלאכים, ועל דרך אומרו (במדבר כ''ג כ''ג) כעת יאמר ליעקב ולישראל מה פעל אל, ואז''ל (במד''ר פ''כ) שהמלאכים ישאלו לישראל הקרובים לאל מה פעל אל. עוד ירצה **ביני ובין בני ישראל** יהיה סוד הדברים האמורים ולא ידעם אדם בעולם, והוא מאמרם ז''ל (ביצה ט''ז.) שאמרו נשמה יתירה לא אודעינהו כי אין חפץ לה' שידעו האומות סתרי אל חי, והוא אומרו (תהלים קמ''ז) חקיו ומשפטיו לישראל לא עשה כן לכל גוי ואז''ל (חגיגה י''ג:) וכו'. ואומרו **אות היא לעולם** פירוש כיון שכל זה יהיה סוד לישראל ולא יגלו הדבר אם כן הבא לישאל על מצות היום מה היום מימים מה אות נעשה בו לעשות בו כל השינויים מה תהיה תשובתינו אליו, לזה אמר **אות היא לעולם** פירוש שיהיה נגלה לבאי עולם כי ששת ימים וגו' **וביום השביעי שבת** וגו' טעם זה יהיה נגלה לזולתינו ועם בני ישראל טעמם כמום עמם חתום באוצרות החיים:
@903 **ויתן וגו' ככלתו**. צריך לדעת למה הפסיק בין זכרון הנתינה לזכרון דבר הניתן בהודעת הזמן שהיה לו לומר ויתן אל משה שני לוחות ככלותו או היה לו להקדים ככלותו קודם זכרון הנתינה, עוד יש להעיר למה איחר ה' נתינת הלוחות עד זמן זה כיון שלא היה בהם אלא עשרת הדברים ביום מתן תורה או למחרתו היה לו לתת הלוחות, אכן יתברר הענין על פי דבריהם ז''ל (זוהר ח''ב צ''ג:) שאמרו שכל המצות הלא המה בתוך תוכם של עשרת הדברים, והוא אומרו **ויתן אל משה ככלתו לדבר אתו בהר סיני** ומה דבר אתו ב' **לוחות העדות** פירוש כי הדברים בלוחות שם לו אל עליון ואינו מן הראוי לתת לו הלוחות עד שיגמור הרשום בהם, ולזה גמר הדברים הנרמזים בה בלוחות העדות ונתנם לו ולא קודם, ובזה נתיישבו ב' הדקדוקים כאחת על נכון, וכפי זה מאמר שני לוחות נמשך עם ככלותו לדבר אתו וגו' ונמשך עם ויתן האמור בתחלת הכתוב:
@903 **כתובים באצבע אלהים**. הכונה בזה על דרך אומרם ז''ל (תנחומא פ' עקב) כי הלוחות נחצבו מתחת כסא כבודו יתברך, ואולי כי זה הוא שרמז באומרו מעשה אלהים פירוש מעשה (אלהים) הוא הכסא והבן, וכבר נתפרש כי יש בחינות רבות אורות הקדושה בסוד (קהלת ה') כי גבוה מעל גבוה וגו' וגבוהים וצא ולמד ממעשה הנפלא שהובא כספר הזוהר הקדוש (ח''ב ג''ב.) כשעלה משה למרום ופגע במלאך סנד''ל וכו' ואחר כך במלאך מט''ט והיה ירא מלאך מאשו של מה שלמעלה ממנו פן ישרפהו וכן וכו', והנה אמר הכתוב (דברים ד') כי ה' אלהיך אש אוכלה הוא, כי אשו הקדושה היא אוכלת כל אש זולתה, והודיע הכתוב אופן כתיבת הלוחות במה נכתבו ואמר **כתובים באצבע אלהים** פירוש כי היה ה' מצייר צורת האות באצבעו כביכול פירוש בחינת אור אחד מאורו יתברך בדמות אצבע כנגד הלוח כשיעור שטח אברי האותיות כדי שלא יהיה חרות אלא את אשר יצייר כנגדו ולצד עוצם תוקף אורו יתברך לא היה אור של הלוחות יכול עמוד בכל המקום אשר יכוין כנגדו אצבע אלהים והיה נאכל או מתצמצם לצדדין והיה נשאר כל אשר יצטייר כנגדו חלול ולזה נכתבו משני עבריהם, והוא אומרו (לקמן ל''ב ט''ז) חרות על הלוחות ולא אמר חרות בלוחות שיהיה נשמע שעשה החרות בלוחות אלא על, פירוש שהיה מניח אצבעו ב''ה על הלוחות בדמיון צורת האות ובזה נחרתו האותיות של עשרת הדברים:
@904 **וירא העם וגו'**. פירוש בעיני השכל, או על דרך אומרם ז''ל (שבת פ''ט.) שבא שטן והראה להם דמות חשך ואפלה וכו' ודמות מטתו של משה שמת, לזה אמר **וירא העם** עניינים הנזכרים והצדיקו הענין מטעם כי בא שש שהוא זמן שהגביל להם, וזולת זה לא היו עושים חשבון מדברי השטן הרמאי:
@904 **ויקהל העם על אהרן**. צריך לדעת טעם אומרו **על אהרן**, ואם לדבר אליו היה לו לומר ויקהל העם ויאמרו אל אהרן, אולי יכוין לומר כי נקהלו עליו להורגו **ויאמרו קום** וגו' ואם לאו וגו', ורז''ל אמרו (סנהדרין ז'.) שהרגו לחור וזה לך האות לדברינו, וטעם שלא נרמז בתורה הריגת חור כדי שלא ישאר רישומו ניכר בתורה לדורות עולם וה' חס על כבוד עם בני ישראל ולא נכתב מעשה העגל אלא לטעם שאם חטא צבור אומרים להם כלך אצל צבור שנתקבלה תשובתם על חטאם כאמור שם (ע''ז ה'.) ואולי כי רמזה התורה הריגת חור ממה שאמר הכתוב (לעיל כ''ד י''ד) והנה אהרן וחור עמכם ולא הזכירו בפסוק זה עם אהרן הרי זה מגיד כי טרוף טורף, ומפורש הדבר בדברי קבלה דכתיב (ירמי' ב') גם בכנפיך נמצאו דם נפשות וגו' כאמור בויקרא רבה (פ''י), ונראה לתת טעם למה שהרגוהו, ואולי כי כשלא רצה לעשות מעשיו מוכיחות כי חפץ להיות הוא אמצעי כמשה, ועיין בפסוק שאחר זה, לכן הרגוהו שלא רצו שיהיה אמצעי אדם לפי שיש בו בחינת הרצון הטבעי וכוחותיו נמשכים בארציות והבן:
@904 **אשר ילכו לפנינו**. דקדק לומר **לפנינו** פירוש לצד כי ה' המוציא אותם מארץ מצרים הוא נעלם וגבוה מאד ויקר להם מקרה רע באין משגיח עליהם לזה יעשו כח מכוחות צבא השמים שיהיה למטה לפניהם ולעולם לא מרדו בסיבה ראשונה אלא שרצו באמצעי, ואולי שחשבו שלא צוה ה' על איסור האמצעי אלא כל עוד שיהיה משה, ולזה אמרו **כי זה משה האיש** וגו', ואפשר כי טענות טעות טרופה בפיהם באומרם כי זה משה האיש אשר העלנו וגו' פירוש הרי לך ראיה כי צריך אמצעי שלא הוציאנו ה' בלא אמצעות שליח אמור מעתה כי יש צורך באמצעי, ומה שקראוהו **אלהים** על דרך אומרו (לעיל ז') ראה נתתיך אלהים לפרעה, ודברים אלו טעות גדולה הם, ועיין מה שפירשתי בפרשת יתרו (כ' ד'):
@905 **ויאמר**. פירוש אליהם הוא שאמר כן ולבבו לא כן יחשוב:
@905 **פרקו**. פירוש אתם ולא הם:
@905 **נזמי הזהב**. ולא זהב אחר.
@905 **אשר באזני**. אם ישנם ולא מונחים בארגז ולא שילבשו מחדש ואם לא דבר זה מעכב, גם אמר **נשיכם בניכם ובנותיכם** שלא להניח זהב על כלם ובאמצעות כל זה יתעכבו זמן מה, גם אמר **והביאו** פירוש ולא תשלחו על ידי שליח, **אלי** ולא לזולתי ולא על ידכם, וטעמו שדבר הנעשה על ידי רבים אין בו עיכוב ועל ידי יחיד יתעכב קצת והם לא נתעכבו ועשו כל התנאים זולת הנזמים אז''ל (תנחומא) שלא רצו הנשים והביאו את שלהם כדי שלא להתעכב:
@907 **ויעשהו עגל**. פירוש בעבור שנעשה על ידו לא שעשאו הוא דכתיב (פסוק כ''ד) ויצא העגל הזה. או לצד שלקח הזהב מידם לידו ולא נתחכם שיניחו הזהב בארץ לבטל כשפיהם (זוהר ח''ב קצ''ב.) העלה עליו הכתוב המעשה:
@907 **ויאמרו אלה אלהיך ישראל אשר וגו'**. קשה איך יאמן הטפשות והבערות לדור דעה רבים ונכבדים לומר לדומם אלה אלהיך וגו', ולו יהיה שדיבר העגל באמצעות מעשה כישוף כמאמרם ז''ל (תנחומא) אף על פי כן זה יועיל לחשוב בו דבר אבל להעיד עדות שקר שזה הוא המוציא לא, אכן הנכון הוא כי אדרבה בדבריהם אלו גילו דעתם שאינם משתחוים ועושים אלוה אלא להמוציאם מארץ מצרים ונתכוונו בדיבור זה להכין בו בחינת האלהות שהוא המוציא ותהיה העבודה לחלק מהכל והרי הם כעובדים לכל והחלק היה הולך לפניהם והוא יענה להניקח ממנו, ולא היה בעיניהם לזרות כי הלא יש באדם חלק אלוה ממעל אלא כי לצד שהרכבתו אינה ממין המתקיים הרוח תשוב אל האלהים, ונתחכמו לעשות הדבר להמשיך כח עליון בדבר המתקיים ויהיה מצוי תמיד לפניהם ולעולם לא עקרו אנכי ה' וגו' אשר הוצאתיך מארץ מצרים אלא אמרו **אלה**, ואולי כי לזה אמר **העלוך** לשון רבים לרמוז לכח תחתון כעליון ח''ו, ובאמצעות זה פגמו פגמים רבים ועשה ה' בהם שפטים, ועיין בפירוש פסוק (ח) סרו מהר מן הדרך וגו'. ונראה בעיני כי לא כל ישראל הסכימו על הטעות אלא חלק מהם וחלק לא מיחו ושקולים היו בדבר וחלק לא היה בהם כח למחות, והנה מדקדוק אומרם **אלהיך** ולא אמרו ח''ו אלהינו וגו' הוציאנו זה יגיד כי קצת מהם אמרו זה לכולם ויש שהצדיק ויש שלא הצדיק, ורבותינו ז''ל אמרו (שמו''ר פמ''ב) שערב רב שעלו עם ישראל הם העושים, ובהכרח לומר כי ישראל לא הסכימו בשעת מעשה שאם הסכימו הרי גם המה עשו שהמחשבה פועלת בעבודה זרה וגם לא מיחו ועל זה נענשו כללות ישראל זולת מעטי היכולת שבחן ה' לבם שלא נטה אחר הרע והמפורסמים בדבר הם בני לוי, והנה אחר שנעשה העגל בהכרח לומר שחלק מישראל טעו אחריו דכתיב (פסוק כ''ח) ויפול מן העם כשלשת אלפי איש ובהכרח שמישראל נפלו כמובן מאומרו (פסוק כ''ז) הרגו איש את אחיו וגו' את קרובו אם כן בהכרח לומר שחלק מישראל עבדו עבודה זרה בעדים והתראה:
@908 **וירא אהרן**. פירוש ראה דבר פלא כי לא עשה דבר אלא השליכו באש ויצא העגל מעצמו:
@908 **ויבן מזבח לפניו**. ולא אמר ויבן לפניו מזבח שאז יהיה נשמע שלכבודו עשה והוא לא עשה המזבח לעגל אלא לפניו עשאו וכונתו למקום, ולדברי הזוהר (ח''ב קצ''ג.) יכוון גם כן על נכון כי עשה לבל יפליא חוץ והיה לו. המזבח למאסר ככל מחוייבי מיתה, ואמר **חג לה' מחר** נתכוון לדחות השעה וכונתו ומחשבתו בדבריו היתה לאלהי ישראל אמת כי שם זה הוא שם המיוחד, וישראל גם כן למה שפירשתי כי לא נעקרה מחשבתם ואמונתם מה' אמת ואליו יכוונו אלא שרצו לקחת חלק ממנו שיהיה לפניהם אין דבר נגדיות לדעתם בדברי אהרן:
@909 **וישכימו ממחרת וגו'**. קשה למה לא עשה ה' כ''ה הרגשה בשעת מעשה העגל תכף ומיד לומר למשה רד כי שחת עמך עד אחר שעבר יום המעשה ולמחרת אחר שהעלו עולות ושלמים, ועוד שאם היה מקפיד על הדבר תכף ומיד לומר למשה רד וגו' לא היו באים לידי זביחה לאלהים אחרים, ואין לומר שקודם אמר אליו אלא שמשה נתעכב להשיב חרון אף, שהרי בדברי ה' נאמר וישתחוו לו ויזבחו לו הא למדת שדבריו היו אחר שזבחו למחרת המעשה, והגם שאמרו ז''ל (ע''ז ד':) לא היו ישראל ראוים לאותו מעשה וכו' אלא שאם חטא ציבור וכו' אף על פי כן ישנו ללימוד זה גם אם לא היו זובחים שבדיבור ראשון שאמרו אלה אלהיך הרי קבלוה עליהם לאלוה, והגם שאמרנו קצת מהם אמרו כן ולא כולם ולהאומרים ערב רב הם אמרו, על כל פנים שמעו ושתקו כולם, ובהכרח לומר שהמועטים הוא שלא הסכימו שאם היו המרובים היו עומדים עליהם והורגים את האומרים כן ואם כן הרי המרובים מתחייבים מדין ערב:
@909 **ונראה** לומר כי לצד שקדם ואמר ה' למשה כי שם ישב ארבעים יום ואחר הארבעים יתן לו הלוחות כמאמרם ז''ל (שבת פ''ט.) בפסוק כי בשש משה שבאו שש שעות ביום הגבול של מ' הא למדת כי נאמר לו מה' ששם ישב מ' אשר על כן לא אמר לו ה' למשה לרדת מן ההר קודם המ' יום עד סופם ואז אמר אליו לך מן ההר, ואומרו רד אפרשנו במקומו, וכפי זה הגם שהרגיש ה' במעשה ישראל הרע מעת הקהלם על אהרן עם כל זה דבר אלהינו שאמר מ' יום יקום לעולם, ואם תאמר למה לא חשב ה' מחשבות לבל יכשלו, זו חקירה כללית בהנהגות הבורא עם ברואיו, וכבר כתבנו בפרשת בראשית (ו' ה') קצת מהטעמים המושגים אצלנו, ובמה שלפנינו אין אנו צריכין לטעמים כי טעמו בצדו כי בהכרח שיהיה שם משה מ' יום לקבלת הלוחות ויש טעמים נסתרות לה' והנגלות לנו כנגד יצירת הולד, גם להודיע הדרגות של התורה מכל העולם שכל העולם נברא בששה ימים והלוחות בריאתם למ' יום וכמאמר רבי יוחנן לר' חייא (שמו''ר פ' מ''ז) על מה שזבן שדות וכרמים וזיתים כי מכר דבר הניתן לששה וקנה דבר הניתן למ', עוד יראה לי טעם אחר כי לצד שהתורה יש בה ד' דרכים כלליים והן מנין פרד''ס, ויש לך לדעת שהם מארבעה הדרגות אורות עליונים המתכנים בשם אצילות בריאה יצירה עשיה, הפשט אורו מאיר בעולם העשיה, רמז בעולם היצירה, דרש בעולם הבריאה, סוד בעולם האצילות, וכבר הקדמנו פעמים רבות שאין לך הדרגה בקדושה שאין גובהה עשרה והרי לפניך מ' ולזה היה שם מ' יום שלימים ואם היה חסר יום אחד היתה תורה חסרה אותה בחינה וישרים דרכי ה', ועוד יש טעמים רבים, ובזה אין קושיא לאלהינו, ועיין בפסוק לך רד שאחר זה באופן אחר:
@910 **לך רד כי וגו'**. כפל לומר **לך רד** אחת לגופו שילך ואחת לומר לו שירד מגדולתו, ואם היה אומר רד לבד היינו אומרים כי להיותו בהר אמר לשון ירידה, וכן הוא אומר (לעיל י''ט י''ד) וירד משה מן ההר, וצריך לדעת אופן ירידה זו מה היא, ואולי שהודיעו כי כל מעלתו היתה בשביל ישראל ומעתה שחטאו לא ישיג הנבואה כמחזה הראשון, או אפשר כי שם במקום עמידתו לא היה בו כח לעמוד שם כיון שכשל עוזר, והוא מה שאמר לו **רד** פירוש לא תעמוד במקום הראשון והטעם **כי שחת עמך** שמכחם באתה, וקשה אם כן היה לו לומר כן מעת שאמרו ישראל אלה אלהיך אם לצד שישראל עבדו עבודה זרה תתחייב ירידת משה מגדר שהיה בו, ויש לומר בהעיר עוד למה הוצרך ה' להאריך הודעת עון ישראל, ומה גם לדברי רבותינו ז''ל (סנהדרין מ''ג:) שאמרו במעשה עכן ששאל יהושע דבר מאת ה' להודיע מי המועל בחרם והיתה תשובת ה' אליו דלטור אני לך, אם כן כאן במה שלפנינו לא היה לו לומר למשה הדברים הרעים שעשו ישראל, והן אמת כי שם היה דבר שאינו עומד להתגלות ויש בזה דלטורות מה שאין כן במציאות זה שהיה דבר שעומד להתגלות ברדת משה מן ההר, עם כל זה בערך מקור החסידות וטהרת הלשון כסף נבחר לשון צדיק לא יגיד כדברים האלה:
@910 **אכן** טעם דברי ה' הוא כי ח''ו לא לדלטר על עושה עול בא האלהים אלא לצדק דינו הצדק, והוא כי לצד שאמר למשה **רד** מגדולתך הוצרך לומר על מה הוכה בית מאהבו מה פשעו כי יורידנו אלוה, ולזה אמר **כי שחת עמך** וחל עליו להודיעו אופן ההשחתה שעליה נתחייב משה הירידה וסדר ג' דברים, א' עשו להם וגו', ב' **וישתחוו לו ויזבחו** וגו', ג' **ויאמרו אלה** וגו', והם כנגד דיבור מחשבה ומעשה, והתחיל במחשבה ואמר **עשו להם** הרי. מחשבה מעת שעשאוהו חשבו בעבודה זרה, והוא מה שדייק באומרו **להם**, ועיין מה שכתבתי בפסוק (לעיל כ' ג') לא יהיה לך אלהים אחרים וגו', כנגד המעשה אמר **וישתחוו לו ויזבחו לו** אין לך מעשה גדול מזה, כנגד הדיבור אמר **ויאמרו אלה אלהיך** וגו' ולצד זה תשש כח משה בג' בחינות שהם נפש רוח נשמה ולא יוכל עמוד במדרגה ראשונה, וממוצא דבר אתה יודע כי קודם שעברו ישראל על ג' פרטים עדיין היה משה יכול עמוד באמצעות בחינה הנשארת בלא פגם, שאם לא כן ובאחת או בב' מהאמור יש טעם למשפט הירידה לא היה ה' מגלה למשה כל המעשים משום פגם דלטורות כמו שכתבנו, ומעתה אין מקום לקושייתנו למה לא ירד מעת אומרם אלה אלהיך או מעת שאמרו לאהרן עשה לנו אלהים:
@911 **סרו מהר מן הדרך**. יתבאר על פי דכריהם (חולין ה'.) שאמרו המודה בעבודת גילולים ככופר בכל התורה כולה, והוא אומרו **סרו מן הדרך אשר צויתים** הרי כל מה שצוה בכלל.
@911 **עוד** ירצה לפי מה שפירשנו כי ישראל עודם באמונת ה' השלימה אלא חשבו להיות לפניהם כח אחד מאל עליון, לזה אמר **סרו מן הדרך אשר צויתים** פירוש לבל עשות אמצעיים ועשו דרך אמצעיים, ולזה לא אמר מרדו בי או כפרו בי כי עודם באמונתם:
@911 **עשו להם וגו'**. פירוש אחרים עשו להם העגל כי הם נתנו הזהב ויצא העגל מעצמו, והודיע ה' כי לא מעצמו יצא כמאמר אהרן (פסוק כ''ד) ויצא העגל הזה אלא על ידי מעשה והוא מאמר רבותינו ז''ל (תנחומא) כי יונוס וימברום עשו וגו':
@911 **ויאמרו אלה וגו'**. קשה למה [היפך] סדר העשוי שהיה לו להקדים אמירת אלה אלהיך קודם הזביחה שכן מצינו שביום ראשון אמרו אלה וגו' וממחרת זבחו וגו', והנה לפי דבריהם ז''ל (שמו''ר פמ''ב) שערב רב הם העושים כל מעשה העגל ולא ישראל יסדר הכתוב הדרגות העון בערך ישראל לא בערך ערב רב, ואמר הדרגה אחד **עשו להם**, פירוש ערב רב עשו עגל מסכה לעצמן ולא מיחו ישראל, עוד השתחוו וזבחו ערב רב ולא מיחו ישראל וזהו הדרגה גדולה יותר מהראשונה, ועוד אמרו בפירוש אלה אלהיך ישראל ושתקו ישראל וזו קשה מכולם, ולפי פשט הכתוב טעם שאיחר אומרו אלה אלהיך הגם שהוא בחינת פגם הדיבור והוא מדרגה ממוצעת בין המחשבה למעשה לצד שיש בו בבחינת דיבור זה הדרגה גדולה שקבלוהו לאלוה לעולם באומרם אשר העלוך, וטעם זה יגיד ההתמדה לבני בנים והוא פגם מופלא, לזה סדרו באחרונה כדרך לא זו אף זו.
@911 **עוד** נראה כי טעמו הוא לפי מה שמגיד משמעות אלהיך לנכח כי לא ישראל הם המדברים אם כן הדברים שקולים הם, אם השומעים מאמר אלה אלהיך הסכימו לזה או לא, לזה לא אמר בתחלה אלא עשו להם עגל, ואחר שהשתחוו וזבחו לו נתגלה למפרע כי שמעו והסכימו על הדבר, ולזה אחר שהזכיר ה' וישתחוו ויזבחו לו, אמר **ויאמרו אלה** וגו', לומר כי הצדקת הדבר שהם הסכימו הוא ממה שהשתחוו וגו':
@912 **ויאמר ה' אל משה וגו'**. טעם שייחד אמירה אחרת באמצע ענין, להצדיק מה שפירשתי, כי מאמר ראשון שאמר **סרו** וגו' **עשו** וגו' לא בא אלא לתת טעם לירידת משה ממדרגתו ועכשיו בא לדבר מה שנוגע לישראל על חטאתם לזה אמר **ויאמר** וגו', וזולתה היה נשמע שעל זה באה הודעת סרו מהר והבן:
@913 **ועתה הניחה לי**. אומרו **ועתה** ירצה לצד שהוא מרצהו באומרו **ואעשה אותך** וגו', ובזה יניחהו לכלותם ויאמר משה בלבו ומה הבטחה הוא זאת וגם לבניו יארע כמו כן והיו כלא היה, לזה אמר שלא יבקש ממנו להניחו אלא עתה, אבל גוי שיעשה ממשה לא יאמר ה' עוד אליו הניחה לי, או לצד שיהיו מטיבים דרכם או שמבטיחו שלא יאמר לו עוד הניחה ותמיד יבטל משה גזירה מעליהם. ובדרך רמז רמז שלא צוה עליו **הניחה** אלא באותו עת ולא תמיד, וממוצא דבר אתה יודע שיעמוד תכף ומיד בתפלה, כי יאמר ועתה אפילו על שיעור רגע, והנה עבר במשך אומרו **ועתה**, ולזה תכף ומיד עמד בתפלה ולא הניחו לחרות אפו.
@913 **עוד** ירצה לפי דבריהם ז''ל (ב''ר פכ''א) שאמרו, אין ועתה אלא תשובה, רמז לו שיעשה תשובה על הסובב ממנו כי הטעות יצא מדבריו שאמר להם לסוף מ' אני בא, ולא פירש להם שהוא לבד מאותו יום שמזה טעו.
@913 **עוד** ירצה על פי דבריהם ז''ל (שמו''ר פ''ב) שאמרו שקבלת ערב רב היתה מצד משה ולא הסכים ה' עליהם ונתרצה לעשות רצון משה, ולזה אמר לו **שחת עמך** אלו ערב רב, והוא מה שרמז באומרו **ועתה** שעליו לעשות תשובה וחרטה על מעשה בלתי הגון, ואולי כי הוא מתקן הדבר לעתיד לבא שאמרו ז''ל (יבמות כ''ד:) אין מקבלין גרים לימות המשיח ומשה הוא שיהיה גואל ויתקן הדבר:
@913 **הניחה לי ויחר אפי**. קשה וכי משה היה מונעו ואדרבה לא עמד בתפלה אלא אחר כך, עוד קשה כי מאומרו ויחר אפי משמע כי עדיין לא חרה אפו והוא רוצה בחרות אף, והלא אין זו מדתו יתברך שהוא מבקש תמיד לכבוש כעסו, וצא ולמד ממעשה שהובא בתלמוד (ברכות ז.) שאמר רבי ישמעאל כהן גדול שנתרצה ה' בברכתו אשר ברך ה' ברוך הוא שיכבשו רחמיו את כעסו, ואולי כי זו הוא טענת משה רבינו עליו השלום באומרו **למה ה' יחרה אפך** וגו' לשון עתיד פירוש כיון שלא חרה עדיין ועל כל פנים קושיא לאלהינו. ויתבאר הענין בהשכיל על דבר והוא כי דבר ידוע הוא כי שורש האף יהיה מהעלבון הנרגש בלב כפי המעליבין והעלבון ואחר שיגיע ההרגש לבחינת המרגיש יסובב העצבון והיגון ותהיה תרופתו באחד מב' דרכים, האחד בנקום נקם מהסובב, הב' בדברי רצוי לשיעור המספיק להרגש הקפדת העלבון, והנה בעשות ישראל מעשה המכוער אין לך עלבון לאל עליון גדול מזה, והוא אומרו סרו מהר עדיין כלה בחופתה והנה הרה לזנונים, והנה הרגיש אלהינו יתעלה שמו הרגש גדול עד שמחמת עוצם ההקפדה חשב כי לא יועיל הריצוי שהוא אחד מהב' המרחיקין דאבון העלבון זולת דרך הנקמה כמו שכתבנו, והנה גם זה הוא מושלל ממנו יתברך על פי דבריהם ז''ל (שמו''ר פ''ב) כי אין הקב''ה סובל לראות צער צדיקו וידידו, ומימי עולם שמענוהו שאמרו ז''ל (ב''ר פל''ב) שלא הביא מבול עד אחר פטירת מתושלח ולא מתושלח לבד אלא כל צדיקי הדור כרמוז בפסוק (בראשית ז' כ''ב) כל אשר נשמת רוח חיים באפיו כבר מתו קודם הבאת המבול כמאמרם ז''ל (זוהר ח''א ר''ו.) וכן הוא אומר (ישעי' נ''ז) מפני הרעה נאסף הצדיק, והנה גלוי וידוע לפני מי שאמר והיה העולם את אשר יצטער נאמן ביתו באבדן מולדתו ית' יותר בנוגע לו ולא יותר בדבר הנוגע לידידיו, ובראותו יתברך כי אין מקום להניח דאגתו בקש ממשה דבר שיניח לו, והוא לבל יצטער על הדבר ואז יהיה מציאות לחרות אפו ויהיה לו נחת רוח וכביכול ריצהו למשה על הדבר, ואמר לו **ואעשה אותך לגוי גדול**, דקדק לומר לגוי גדול ולא אמר ואעשה אותך גוי גדול לומר הגם שאינך הן עתה בבחינת נשמתך גוי גדול אני אכונן אותך ואשפיע בך מדה טובה מרובה הפלגת נשמות קדושות, ולזה לא אמר ויהיה ממך גוי גדול כי צריך מעשה בנין חדש בשורש נשמתו.
@913 **עוד** רמז לסתור טענת ואיה הבטחתך שנשבעת לאבות, לזה אמר **ואעשה אותך לגוי גדול**, פירוש לקיום הבטחת גוי גדול שהבטחתי לאבות, ובאה התשובה של משה כי מן הנמנע שיניח לו והראהו צערו על הדבר באומרו **ויחל משה** ואמרו ז''ל (ברכות ל''ב.) אחזתו אחילו וכמה עניינים של מרירות נפש עשה לפני קונו זה כנגד הניחה לי, וכנגד אומרו **ויחר אפי** שהיא טענה שעליה בא כי זולת זה אין להם נחת רוח מעצבון העלבון, לזה אמר **למה ה' יחרה אפך** פירוש למה לא מצאת תיקון לדבר אלא חרון אף כלך לדרך זו והוא בחינת הריצוי שכתבנו, טענה ראשונה שיש לך לחוש על קניינך, והוא אומרו **בעמך** ואין אבידה אלא לבעליה, ב' אשר **הוצאת** ועל ידיהם נתפרסמה אלהותך, ג' **למה יאמרו מצרים**, ד' **זכור לאברהם** וגו', ובזה יש לך דברים וטעמים נכונים המספיקים לבחינת הרצוי, ועלתה ביד משה הטענה **וינחם ה'** וגו', וירמוז תיבת **וינחם** לשון נחמה ולשון נחת כי נח תוקף הרוגז שהיה לו ומאמצעות זה ניחם על וגו', ועיין בפסוק שאחר זה:
@914 **למה ה' יחרה וגו'**. על פי דבריהם ז''ל (שמו''ר פמ''ב) שאמרו שערב רב לבד עשו את העגל, והוא אומר (פסוק ז') שחת עמך, ולדבריהם ז''ל בהכרח לומר שהיתה ההקפדה על כל ישראל שלא מיחו, וכפי זה יהיה כוונת משה באומרו **למה** טענה הנשמעת כי כיון שערב רב הם המשחיתים אין ראוי שיחרה אפו בעמו שהם ישראל, והגם שיש להם דין ומשפט עם כל זה לא לחרות אפו בהם, וממוצא דבר אתה יודע כי הסכים על השמדת ערב רב. ואולי כי זה דייק באומרו **אשר הוצאת מארץ מצרים** ולא ערב רב שמעצמם יצאו. ונראה כי כל ערב רב שהיו אז מתו שאפילו פטרון שקבלם הסכים על כלייתם וגם אין לו פנים לבקש רחמים עליהם אם על קבלתם נענש כמו שכתבנו למעלה, גם אין להם זכות אבות וטענות שהזכיר משה בטענתו, ולפי פשט הכתוב שישראל עשו העגל והשתחוו לו טען משה כנגד חלק שלא עשו כי הלא תמצא שמתו כל עושי רשעה והם ג', יש שעבדו בעדים והתראה, ויש בעדים לבד, ויש בהתראה לבד, וכל אלו מתו ולא נשארו אלא מי שלא היו בו א' מג', וה' אמר למשה ואכלם ואעשה אותך לגוי גדול זה יורה שביקש לעקור את הכל לזה צעק לבו אל ה' **למה ה' יחרה אפך בעמך**, פירוש באותם שלא עבדו כל עשו את העגל, והוא אומרו (פסוק ז') שחת עמך, יעקר מהם זכרון עמך:
@914 **אשר הוצאת וגו'**. בטענה בא לסתור מה שאמר **ואעשה אותך לגוי** וגו' כי לא יתכן שימצא הכנת אושר הצדקות כאשר ימצא בעם זה כי הם הוציאם ממצרים, מה שאין כן בני משה אשר יקום ה' אינם בגדר זה, והלא תמצא כי תחלת דבר ה' בעשרת הדברות (לעיל כ' ב') אמר אשר הוצאתיך וגו' זה יורה כי יציאת מצרים הוא דבר המעמיד השתעבדותם לבורא, ולך נא ראה מה שכתבתי בפירוש פסוק זה, ועוד בכל המצות תמצא רמז יציאת מצרים ואם אלו לא יעמדו בעבודת הקדש מכל שכן הבאים ממשה אשר לא ידעו ואינם בגדר יציאת מצרים, ומעתה הפסד זה אין לו תיקון בבני משה, ואומרו **בכח גדול** פירוש ויש לחוש למה שבא בכח גדול לבל יפסידנו.
@914 **עוד** ירצה באומרו **אשר** וגו' פירוש לצד כי ה' אמר אליו **שחת עמך** שלא רצה לכנותם אליו אם כן איך ישוב משה להזכירם לפניו בשם עמך שהוא דבר ששללו ה' אשר על כן דקדק בלשונו ואמר **הוצאת** וגו' פירוש לא לצד שהם עמך עדיין אני קורא אותם עמך אלא לבחינה זו אשר וגו':
@915 **למה יאמרו וגו'**. פירוש יש בזה חילול ה' כי יאמרו מצרים אתמול אמר (לעיל ד' כ''ב) בני בכורי ישראל שלח וגו' ויעבדני והן עתה גילה סופו על תחילתו כי לא לטובה יכוין וח''ו נראה כשקר, עוד נתכוין בזה כי דבר ידוע שישראל יעבדו ה' וכל האומות יעבדו עבודות אחרים וממה שיראו שהוציאם ה' לרעה מה שלא עשה לעובדי זולתו אם כן ח''ו פגם גדול מופלא לעובדי ה' ותחזקנה ידי עובדי אלילים חזקה שיש. עמה טענה, ואומרו תיבת **לאמר** כי אין הכרח שיאמרו הדברים כמות שהן כסדרן, אלא יאמרו דברים שזה כוונתם, או ירצה לומר שאין הדברים אמתיים ח''ו אלא בבחינת האמירה, עוד ירצה כי לא מצרים לבד יאמרו אלא יאמרו הם וישמיעו הדברים לכל שבזה יתרבה ח''ו חילול ה':
@916 **זכור לאברהם וגו'**. אין הכוונה על השבועה שזה כבר השיבו ה' שיקיים שבועתו בזרעו של משה ויהיה לגוי גדול והוא זרעם של אבות גם כן, אלא בא לומר כי יתעצבו האנשים מאוד על המאורע, גם בא בטענה שצריך לזכור זכותם מטעם שאמר בעשרת הדברות (לעיל כ' ו') ועושה חסד לאלפים לאוהבי והוא אומרו **עבדיך**, ואומרו **אשר נשבעת** וגו' כל זה להגדיל המושג לאבות לצד האהבה:
@916 **וכל הארץ הזאת וגו'**. רבו בזה הדרכים ויש מפרשים שהם דברי משה שאמר לפני ה' מה שאמרתי להם וגו', ואפשר לומר כי הוא דברי ה' ופירוש **אמרתי** לשון מעלה על דרך אומרו (ישעי' ג') אמרו צדיק, וזהו פירוש **כל הארץ** וגו' אשר רוממתי על כל הארצות **אתן** וגו', וכן מצינו שאמר הכתוב (דברים י''א י''ב) ארץ אשר וגו' עיני ה' אלהיך וגו', והכוונה בזה להזכיר מעלתם לפניו:
@917 **וינחם ה'**. פירוש לב' טעמים ניחם הא' לצד היות הדבר רע הב' להיות הרע לעמו.
@917 **עוד** ירצה על זה הדרך **וינחם על הרעה אשר דיבר** דוקא לצד הדיבור אבל אם נשבע לא.
@917 **עוד** ירצה שלא ניחם אלא על הרעה אשר דבר דהיינו לכלותם, אבל יש עדיין רעה אחרת שלא ניחם עליה והם הדברים הרעים אשר סבבם העגל כידוע.
@917 **עוד** ירצה שלא ניחם אלא על הרעה אשר דבר לעשות לאותם שלא חטאו שמתיחסים בשם עמו, אבל אותם שעבדו עבודה זרה בעדים או בלא עדים אלא בלב האמינו בה רעתם עמדה לעומתם מהם נגף ה' וכו' ומהם השקם משה ומהם הכום בני לוי:
@918 **ויפן וירד**. צריך לדעת אומרו **ויפן** שאינו מהלכות דרך ארץ שיפן משה, ואולי כי לזה דקדק לומר **מן ההר** שלא לומר שח''ו נהג מנהג מיעוט דרך ארץ שפנה עורף מפני השכינה אלא מן ההר הוא שפנה, וקשה אם כן היה לו לומר ויפן מן ההר, ועוד קשה שלא היה צריך לומר ויפן כל עיקר, ואולי שיכוין לומר שתשש כחו והיה מתירא מהמלאכים והיה מפנה עצמו לצדדי ההר כאדם הנחבא ללכת.
@918 **עוד** ירצה על דרך אומרם (דב''ר פ''א) כי למה דומה דרכו של משה כשהיה מדבר עם הקב''ה היה אומר למה ה' יחרה וגו' וכשהלך אצל ישראל הפך הסדר ואמר אתם חטאתם וגו' ע''כ, והוא אומרו **ויפן** פירוש שלא נשאר כסדר פנים הראשונים שהיה מראה כשהיה עומד לפני המקום:
@918 **לוחות העדות**. אולי שרמז גם כן באומרו **העדות** שהם מעידים כי הם כתובים כתב אלהים לצד היות כתבם מופלא מזה ומזה בהשואה מה שאין מכתב זה יכול להיות על ידי מעשה אדם, כי האות תשתנה צורתה מעבר האחר, גם מאמרם ז''ל (מגילה ג.) שאמרו מ''ם וסמ''ך שבלוחות בנס היו עומדים, ואולי שהאות הזה יצטרף עם אות מעשה הלוחות והיו ב' האותות לעדות שאין עדות פחות מב', והוא אומרו **והלוחות מעשה אלהים** הרי עד א' **והמכתב מכתב אלהים** עד ב':
@920 **וישמע יהושע וגו' ברעה וגו'**. צריך לדעת מה הוא כוונת אומרו **ברעה**, ומה קול זה ששמע, גם תשובת משה צריכה נביא להגיד משמעות הדברים, ויתבארו הכתובים ע''פ מאמרם ז''ל (ירושלמי תענית פ''ד ה''ה) כי הצדיקים יבחינו בקול אם לצדק אם להופכו, והשגה זה הוא השגה אלהיית אשר הנחיל ה' לגדולי עולם, והוא מה שהריח יהושע שאמר הכתוב **וישמע יהושע את קול העם** פירוש הברת קול שהיתה נשמעת מן המחנה של ישראל שמע בו בחינת הרע והוא אומרו **ברעה**, **ויאמר אל משה קול מלחמה במחנה** אמר לו כי קול זה ששומע הוא קול מלחמה, ובחינה זה הוא בחינת הרע שהכיר בקול, או רמז באומרו **קול מלחמה** על מלחמת הצר שהוא ס''מ המצוי. תמיד במערכת המלחמה עם האדם, והשיב משה **אין** ק **ול ענות גבורה**, פירוש שלא נתגברו על יצרם, **ואין קול ענות חלושה**, פירוש לא בחינת חולשה לבד, **אלא קול ענות** כי שבר מטה עוז תפארה, והכוונה שלא הרעו מעשיהם בפרט אחד מפרטי התורה שיחליש אדם ולא יגוע, אלא עקרו הכל ששקולה עבודה זרה כנגד כל התורה כולה (חולין ה'.). ואולי שרמז באומרו סמוך **לענות** תיבת **אנכי** על השכינה בסוד (דברים ל''ב י''ח) צור ילדך תשי, וזה הוא שיעורה קול ענות של אנכי שומע, ותיבת **שומע** חוזרת על יהושע שאמר קול מלחמה **במחנה** אמר לומר כי קול זה ששומע הוא קול שיגיד שברון השכינה בסוד (משלי י') ובן כסיל תוגת אמו, אחר שכתבתי זה מצאתי מאמר הזוהר (ח''ב קצ''ה.) וזה לשונו מהו ברעה וגו' דההוא קלא דסטרא אחרא הוא ויהושע אסתכל בההוא קלא דהוא סטרא דרעה, מיד ויאמר אל משה עד כאן, והוא ככל הכתוב לחיים:
@922 **ויהי**. אמרו ז''ל (מגילה י':) לשון צער יכוין על מאורע רע שאירע בלוחות שפרחו מהם האותיות כמאמרם ז''ל (שמו''ר פמ''ו), וזה גרם לנו כל מה שטעמו אבותינו גם אנחנו מכוסות המרים המיתה עצמה ומר ממות, כי אם היו הלוחות הראשונים פסקה צרה מן העולם וחירות אפילו ממלאך המות (שם פמ''א), והן עתה פסקה טובה, ולזה יאות קרות **ויהי**, ויכוין גם כן על צערו של אותו צדיק משה רבינו עליו השלום שנצטער הרבה על מה שראה, ויכוין גם כן על ישראל שנמצאו כבושת גנב כי ימצא בבושה גדולה כאשר קרב משה אל המחנה, ויכוין גם כן על בחינת הקליפה שקרב לה הוי להומה ולאבדה דומם ורוחניות רע שבה שאליו נאמר אלה אלהיך סר אליו מר המות, כן יאבדו אויבי ה':
@922 **כאשר קרב וגו'**. אולי שישמיענו הכתוב שנזדמן ראות העגל לפני משה קודם שיכנס למחנה, והטעם כדי שלא יכנסו הלוחות כתובים למחנה שיש בו עבודה זרה, וזה הוא שיעור הכתוב **ויהי כאשר קרב** וגו' תכף ומיד **וירא את העגל** מזומן לפניו:
@922 **וירא את העגל ומחולות**. אולי כי באמצעות הזדמנות משה פרחה לה בחינת הטומאה שהיתה מדברת בו ואומרת אלה אלהיך ישראל, גם רוח הטומאה שפעלה צורתו מבלי צורף ואומן תכף יצא בולעו של עגל מיראת משה, כי הקליפה תכיר אדונה ותפחד ותרתע, ולזה אמר **וירא את העגל ומחולות**, מקיש עגל למחולות מה מחולות דומם גם עגל דומם, כי עברה ממנו רוח המטעה.
@922 **או** יאמר בדקדוק אומרו **את העגל** שלא היה צריך לומר אלא וירא העגל, אלא נתכוין לומר שראה העגל ורוח הטומאה שבו כי הצדיקים יכירו בחינת הרע ומכל שכן אדם כמשה ע''ה שעלה ודרך על במתי כל הרוחות בעלותו אל האלהים, ורבותינו ז''ל אמרו (תיקונים קמ''ב) ששאל משה לעגל מי עשאו, והשיב כי ערב רב עשאוהו יעש''ד, והדבר פשוט כי לא ידבר הדומם, ותמצא שבמחולות לא אמר את כי לא היה בהם רוח הטומאה המצפצפת כמו שהיה בעגל כמאמר רבותינו ז''ל הנזכר.
@922 **או** ירצה להודיע כי בעת שקרב משה אל המחנה לא נזדמן לפניו אדם מפני הבושה ולא ראה זולת העגל ומחולות, אבל מסיבתו ותופשי מחול פינו מקום, ולזה אמר **וירא את העגל ומחולות** לומר כי הוא זה לבד מה שראה:
@922 **ויחר אף משה וישלך**. צריך לדעת טעם של משה בשבירת הלוחות ולא חש להפסד מופלג ופשיטא שלא יעשה דבר קלקול אם לא באומד גדול ובצדדי המועיל אשר צדד ע''ה, ורבותינו ז''ל אמרו (אדר''נ פ''ב) לא שבר עד שנאמר לו מפי הגבורה, וכן אמר ר' מאיר ויהיו שם כאשר ציוני (דברים י' ה') שנצטוה ושבר הלוחות ע''כ, וצריך לתת טעם לאל עליון למה מנע הטוב. ונראה כי קודם שעבדו עבודה זרה פסקה זוהמתן כמאמרם ז''ל (שבת קמו.), ולזה עשה ה' להם משפט כתוב חרות על הלוחות חירות ממלאך המות (שמו''ר פמ''א) כי כלום מיתה זו למה לצד הפרדת הזוהמא אלו כבר פסקה זוהמתן, ולזה כשעשו את העגל הרי זוהמת החטא דבקה בהם ומעתה צריכים למלאך המות, הגם שלא חזרה הזוהמא ממש על ידי העגל לכמות שהיתה קודם קבלת התורה אף על פי כן שברם כי אין דין זה להם עוד שיהיו בני חורין ממלאך המות ומשעבוד מלכיות, ולטעם זה לו יהיה שנאמר כי משה מדעת עצמו עשה מתחילה אין כאן קושיא:
@923 **ויקח את העגל אשר עשו**. לא היה צריך לומר אשר עשו, ואולי כי לצד שהעגל היו בו ב' בחינות לצד ראשו היה דומה לעגל ולצד זנבו היה דומה לחמור כאמור בדבריהם ז''ל (זוהר ח''ב קצ''ב), לזה לא יספיק לומר ויקח העגל לבד שאז יטעה הטועה כי לא שרף אלא צד העגל שבו ולא צד החמור, לזה אמר **אשר עשו** לרבות כל המעשה אפילו חלק החמור:
@923 **עוד** ירצה על דרך אומרו (ירמי' כ') תיסרך רעתך, ותמוגנו וגו', (ישעי' ס''ד) כי החטא בעצמו הוא יפרע מעושהו, כי אחיזת הרע היא עצמו תאבד אוהביה ושונאי הקדושה, והוא אומרו **אשר עשו** וגו' וישק את בני ישראל, ודבר זה יהיה לבן דעת לפקוח עינים עורות לשנוא בחינת הרע ולאהוב מדרגת הקדושה אהבת הטוב במה שהוא טוב.
@923 **עוד** אולי שיכוין לרמוז אל בחינת הרע שעשו ב' המכשפים שבאמצעותו יצא העגל והיה מדבר ואמר אלה אלהיך, שגם אותה לקח, כי לצד בחינת שליטת הקדושה בקליפה יוצדק לומר לשון לקיחה שישלוט עליו לבל יפנה מלפניו עד עשות בו כטוב בעיניו, והנה לפניך מעשה אנשי כנסת הגדולה (יומא ס''ט:) אשר לקחו יצרא דעבודה זרה וגם דעבירה ורצו לאבדו, ומזה תשכיל כי כמו כן ישלוט משה בכיוצא בזה ללקחו ולבערו באש אוכלתו, והוא אומרו **וישרוף באש** שיותר יוצדק לומר לשון שריפה בבחינת רוח רעה שבתוך העגל מלומר כפשט הכתוב שהוא על גוף העגל שהוא הזהב כי לא ישרף הזהב באש אם לא שתאמר מעשה נסים או על ידי אמצעי אבל בחינת רוח הרעה שבו יותר יוצדק שריפה, והוא סוד (ישעי' י''א) וברוח שפתיו ימית רשע:
@924 **מה עשה לך וגו'**. פירוש לצד שאיסור מעשה עבודה זרה לאחרים אינו אלא בלאו (רמב''ם הל' ע''ז פ''ג) ומלקות לבד הוא שחייב, ואין זה מדברים שנאמר בהם יהרג ואל יעבור וכל שאנסוהו הרי זה פטור, אבל צריך הכרת אונס שאנסוהו ואם לאו הרי זה חייב מלקות ואפילו לא התרו בו כי חבר אינו צריך התראה (מכות ו':), ולזה אמר אליו **מה עשה לך העם הזה** מהאונס **כי הבאת עליו** וגו' במה שעשית להם ע''ז, וענהו אהרן **אתה ידעת את העם כי ברע הוא** פירוש ואזורם (וסורם) מוכיח כי יריעו וישחיתו, ועוד וכי סובר אתה שעשיתי בידי העגל לא כן הוא אלא השלכתי הזהב ויצא מעצמו על ידי מעשה שהיה כמאמרם ז''ל (תנחומא) שעשו יונוס וימברוס, ומעתה לו יהיה שלא היה אונס בענין הרי לא עבר על הלאו כי לא עשה בידו לא צורה ולא דמות:
@924 **עוד** ירצה אומרו **מה עשה** וגו' פירוש לו יהיה שאנסוך באונס המספיק לעבור על הלאו אף על פי כן היה לך לשער החטאה הגדולה שתשיגם והיה לך לסבול הצער לבל תאבד עם רב, וענהו כי לא עשה דבר כנזכר:
@928 **כי פרוע הוא**. פירוש סר צלם מעליהם כי נועם ה' היה עליהם מיום שקבלו התורה והוסר מסוכתם:
@928 **כי פרעה אהרן**. אולי שיכוין לומר שעל ידי תשובת אהרן נשאר כל חוב העון עליהם, כי אהרן לא עשה דבר שיש בו ממש בענין העגל והכל נעשה על ידי נותני זהב נתנו הזהב ועשו בו מכשפות לצאת העגל שיצא ולא עשה אהרן אלא לקיחת הזהב ונתינתו באש ואף זה באונס כאומרו כי ברע הוא ומעתה מתיחס כל העון עליהם ואין להם מכסה השגיון והוא אומרו **כי פרעה אהרן** פירוש בטענתו:
@928 **לשמצה בקמיהם**. כל שיעור קטן מבחינת התיעוב יקרא שמץ ואז''ל (סנהדרין ק''ב.) אין לך צרה שעוברת על ישראל שאין בו מעון חטא זה, גם ירצה כי האומות הקמים עלינו תמיד מענה בפיהם כבר התעבתם עצמכם ונזנחתם:
@930 **איש את אחיו ואיש את קרובו**. צריך לדעת למה הוצרך לומר **ואיש את קרובו** אחר שאמר את אחיו שהוא קרוב שבקרובים, אכן יכוין לומר שיש כמה אחים שדעתם מרוחקת זה מזה ועם אנשים אחרים לא קרובים המה להם יאהבו אהבת נפש וזה ימשך משורש הנשמות כי יש נשמות שקרובים בשורשם ונמשכים בריחוק מולידים, ויש נשמות שהם מרוחקים בשורשם ובאים בקירוב מוליד ויותר יאהבו הקרובים בקורבת השורש מהקרובים בבחינת מוליד, ולקרובים בבחינת מוליד יתיחס שם אחוה ולקרובים בשורשם יתיחס שם קרוב, וכפי זה ידבר הכתוב בב' הבחינות וזו למעלה מזו:
@931 **בני לוי**. ולא אמר כל כי לא כולם בני חיל לעשות האמור בענין, וצריך לדעת למה הוצרך להזכירם ולא סמך על מה שבא זכרונם בסמוך, ואולי שבא למעט שלא עשה עמהם הדבר זולתם, ומפסוק ראשון שאמר ויאספו אליו כל בני לוי אין לשמוע שמיעט איש ישראל אלא בא לומר שכל בני לוי באו ויש מקום לומר שבאו קצת מישראל לזה אמר **ויעשו בני לוי** לומר ולא איש ישראל:
@931 **כדבר משה**. פירוש כי דברי משה לבד יספיק למה שעשאוהו, או ירצה שלא נשתהו אלא ככלותו לדבר סמוך לגמר דבריו עשו:
@932 **מלאו**. לא נודע מילואים אלו מה יגידו, ואם על הריגת הקרובים הלא כבר עשו מה שעשו, והמפרשים אמרו כי פסוק זה מדבר מה שאמר קודם המעשה, וקשה למה לא כתבו במקומו, ונראה כי פסוק זה במקומו מונח, והכוונה היא לצד שעשו בני לוי מעשה האמור בסמוך שהרגו כשלשת אלפי איש והוא מעשה אשר אינו נעשה כיוצא בו על ידי בחינת הצדיקים כידוע, וצא ולמד מאמרם ז''ל (מכות ז'.) שאמרו בית דין שהיו הורגים אחד לז' שנים ויש אומרים לע' שנים היתה נקראת בית דין קטלנית, ובני לוי הרגו ביום אחד כג' אלפי איש ויש לחוש בזה לחסרון האושר וסימן הגריעות שיחסרו אורות נשמת העושה כזה לו יהיו שיהרוג כפי הדין סוף כל סוף זה יגיד האכזריות שהיא בחינת הרע, לזה בא איש האלהים ואמר להם **מלאו ידכם** אין פירושה לשון ציווי אלא פירושו הודעה כי הן היום יהיו מלואכם ידכם פירוש כחכם לה' ואין במעשה זה הכרת חוסר האושר אלא אדרבא מילוי אורות הנפש, והטעם הוא **כי איש בבנו** וגו' וזה הוא מעשה המצויין לאברהם אבינו שבו היה לו השלימות דכתיב (בראשית כ''ב) וישלח אברהם את ידו וגו' וכתיב עתה ידעתי וגו' כי ברך אברכך, והוא אומרו **ולתת עליכם היום ברכה** מלבד שבזה השגתם שלימות יד הקודש עוד **לתת עליכם ברכה**.
@932 **עוד** נתכוין לומר בדקדוק תיבת **עליכם** ולא אמר לכם שיכוין לומר גם כן שהחסרון שנחסר על ידם אינו קרוי חסרון אלא אדרבה ברכה גרמו במעשיהם, והרי זה דומה לאילן שזומרין אותו להצלחתו בהסרת ענפים הרעים כמו כן באמצעות הריגת עושי רשע מבני ישראל שנמשלו לגפן (תהלים פ') והוא אומרו **ולתת עליכם** פירוש על סיבתכם **היום ברכה** פירוש לישראל שבהם היה החסרון שזולת זה היה בית מיחוש לכל ישראל, וכפי זה טעם שאמרו בית דין ההורגת א' לע' שנה וכו' הוא במציאות שאינו דומה מציאות שלפנינו מב' טעמים, הא' כי כאן הרגו חביביהם וזה יגיד בחינת הפלגת אהבתם בבורא, ועוד שהיה מציאות שזולת זה תדבק הרעה לכל ישראל ובאמצעות זה שב ה' מחרון אפו:
@934 **חטא העם וגו'**. אולי שיכוין לומר על דרך אומרם ז''ל (סוטה ג'.) אין אדם עובר עבירה אלא אם כן נכנסה בו רוח שטות, וזה הוא חסרון הנפש, והוא אומרו **חטא** פירוש נחסר מהארת נפשו, ובזה עשו להם וגו', וזה הוא א' מטענות שבהם יזכה האדם ליום הדין, כי בעשותו החטא לא היה דעתו שלם, והגם שיענש על אשר גרם לעצמו החסרון במחשבות הכיעור אף על פי כן לא ידמה לאם יהיה נדון על מעשה הרע בדעתו השלימה:
@934 **עוד** ירצה על פי מה שקדם לנו (קידושין מ'.) כי בע''ז יענש האדם גם על המחשבה לבד, והוא אומרו כנגד המחשבה **חטא העם** הזה וכנגד המעשה אמר **ויעשו להם** וגו':
@935 **ועתה וגו'**. יתבאר על דרך אומרם (ב''ר פכ''א) אין ועתה אלא תשובה, והוא מה שטען משה לפני ה' כי עשו ישראל תשובה על הדבר הרע:
@935 **אם תשא חטאתם**. פירוש מוטב, וצריך לדעת למה לא השלים דבריו, ואולי ששיעור דבריו הם על זה הדרך, **ועתה** פירוש הנה ישראל חזרו בתשובה, וזה כנגד מה שמהם אבל כנגד מה שממנו יתברך אין ידוע אם ה' יקבל תשובתם על חטא הגדול אם לא, לזה גמר אומר **אם תשא חטאתם** כי התשובה צריכה שב ומקבל:
@935 **ואם אין מחני וגו'**. פירוש לצד שבאמצעות כל מה שעבר בין ישראל ובין ה' ב''ה יזכה הסרסור הנאמן בזכות המגיע לו בכל מצוה, ובפרט במתן תורה כמה זכות יעלה למשה ביגיעתו עם ישראל והכל כתוב בספר זכרון לפניו, ומעתה אם לא ישא לחטאתם צריך למחות מספר כל זכיותיו של משה שנכתבו באמצעות זכותם של ישראל, והשיבו ה' כי אין דבריו אמת בזה, כי דוקא החוטא עצמו הוא אשר ימחנו ה' מספרו אחר שנכתב בספר, אבל מי שזכה באמצעותו לא יפקע זכותו אשר זכה בו לצד שחזר בו הלה והרשיע.
@935 **עוד** ירצה ע''פ דבריהם ז''ל (זוהר ח''ג רע''ג.) שאמרו כי כל נשמות דור המדבר היו ענפי נשמת משה, ומעתה כשלא ישא חטאתם הנה החסרון נוגע למשה, לזה אמר **מחני** וגו', והשיב ה' כי לא ירעו הענפים אלא לעצמן ולא לבחינת שורש הנשמה, והוא אומרו **מי אשר חטא לי** דוקא הוא **שאמחנו מספרי**, אבל בחינת נשמת משה לא.
@935 **עוד** ירצה כי אם לא ישא חטאתם הנה גם הוא חטא הרבה פעמים לפניו כמו שמצינו לו שאמר (לעיל ה' כ''ב) למה הרעותה וכיוצא בזה, ואם כן גם חטאו לא ישא וצריך למחות וגו' ח''ו, והשיב הבורא **מי אשר חטא לי** פירוש כי ישתנה חטאו מחטא ע''ז שכפרו באלהי ישדאל וחסרו האלהות כפי מה שנצטוו כי מעשה האמצעי יהיה בערך ישראל בגדר עקירת הכל, והוא מה שדקדק לומר **חטא לי** מה שאין כן שאר חטאים שימחול על ידי תשובה בלא עונש, והנה כל התווכחות משה עם ה' אינה אלא למחול מיד ויהיו נכתבים בספר צדיקים אבל לא לענין שיש להם תקוה אחר תוכחות על עון כי זה פשיטא שיתכפר, והוא מה שדקדק לומר **מספרך אשר כתבת** פירוש כי ג' ספרים כתובים למעלה אחד של צדיקים וכו', ואחד של רשעים, וא' של בינונים, והם הנפתחים בראש השנה, ספר שהוא של צדיקים הקדוש ברוך הוא כותבו ומניחו לפניו, והוא מה שאמר **מספרך** פירוש אותו שכתבת אתה לא אותם שנכתבים על ידי הזולת, והוצרך לפרש **אשר כתבת** כי מכינוי מספרך אינו מובן שחוזר על ספר הצדיקים כי הכל הוא של הקב''ה שהוא אדון הכל, ובמסכת ר''ה (ט''ז:) דרשו הכתוב על זה הדרך מספרך זה ספרן של צדיקים אשר כתבת זה ספרן של בינונים ע''כ, ולדבריהם ז''ל יתבאר על פי אומרם ז''ל (קידושין מ':) לעולם יראה אדם עצמו כאלו חציו זכאי וחציו חייב, וכן אמרו במקום אחר (בדכות ס''א:) שאין להעריך אדם עצמו אלא בבינוני, ומעתה יתבארו דברי משה על זה הדרך כי משה היה מעריך עצמו בבינוני כמשפט כל איש ישראל, ולזה אמר כי אם לא ישא לפשע ישראל הנה נגרע מערך זכיותיו ולא מבעיא מערך צדיק אלא אפילו מבינוני כאומרו אשר כתבת:
@935 **או** ירצה כי באמצעות ישראל אם יצדיקו יעמוד חי במדרגת צדיק כי רבים זכיותיו ואם לא ישא לפשעם לא מלבד שלא ירויח תוספת זכיות להכריע זכיותיו כדי שיקרא צדיק, אלא אדרבה יחשב לו זכות הראשון לגריעות כשיענשו כי טוב היה אם לא היה מה שקדם מהטוב והבן:
@935 **עוד** יכוין רועה נאמן לומר כנגד מה שקדם אליו במאמר ה' ואעשה אותך לגוי גדול, ואמר לפניו שאם לא ירצה ה' לישא חטאתם בוחר הוא שימחהו מספרו אשר כתב פירוש כי בעת אשר אמר אליו ואעשה אותך לגוי גדול הלא היא כתובה בספר הישר מאת שיצאת מפי אל עליון ובהכרח להתקיים שאפילו בקללה אמרו ז''ל (מכות י''א.) קללת חכם אפילו על תנאי ומכל שכן דבר טוב שיצא מפי עליון הרי הוא כתוב לעד ולאות, ולזה מתפלל שאם לא ימחול לישראל שימחהו וממילא אין מקום לקיים שבועת האבות, והשיב ה' כי לא תקום ולא תהיה שימחה אלא וגו' אבל מה שדבר טוב על משה יקום לעולם, וכן היה דכתיב (דה''א כ''ג) ובני רחביה רבו למעלה ואמרו ז''ל (ברכות ז'.) למעלה מם' ריבוא:
@938 **אשר עשה אהרן**. צריך לדעת לאיזה ענין אמר זה, ואולי שהקפיד ה' על שגרמו לאהרן קדוש ה' לחטוא כי חטא אדם גדול לו יהיה כחוט השערה יקפיד ה' עליו למאוד.
@938 **או** ירצה להוציא הלעז מעל אהרן כי ישראל הם שעשו העגל אשר עשה אהרן כי מעשה אהרן עליהם יחשב, או לצד שאנסוהו או לצד שהם עשו עיקר המעשה שהוא הכישוף שבו יצא מדבר:
@939 **לך עלה מזה**. הזכיר לשון עליה, אולי שירמוז למה שאמרו ז''ל (שבת פ''ח.) שהעדי שהתנצלו ישראל נטל משה, והוא העליה שרמז לו באומרו **עלה מזה** פירוש מזה שעבר, ולזה דקדק לומר גם כן תיבת **אתה** שלא היה צריך לומר כיון שעמו היה מדבר אלא לומר אתה תעלה ולא זולתך שאדרבה ירידה היתה להם, ואומרו **והעם** פירוש ילך עמך:
@939 **לאמר**. טעם אומרו **לאמר**, כי לשון זה האמור בדברי ה'. לא היה שוה לכולם יש מהם שאמר לו בלשון זה ויש מהאבות שאמר לו בלשון אחר כמבואר מן הכתובים, לזה אמר **לאמר** פירוש שכוונת האמירה לכולם הוא לזרעך וגו':
@940 **ושלחתי לפניך מלאך**. מכאן מוכח כי עד עתה הנה דעת קדוש מסכמת לכניסת משה לארץ ולהנחילה לישראל, והגם שאמר (לעיל ו' א') עתה תראה, שהרי הוא אומר עלה וגו' **ושלחתי לפניך מלאך** לגרש הז' אומות, ואולי כי בשביל שנתן נפשו על ישראל במעשה העגל נתבטל גזירת עתה תראה וגו':
@941 **פן אכלך וגו'**. שאינו דומה המכעיס את רבו בפניו לשלא בפניו, ואומרו **בדרך** כאן רמז שלא לכל הזמנים הוא אומר כן אלא לזמן היותם בדרך אבל בעיר עז לנו יעלה בקדבנו.
@941 **או** ירצה ע''פ מאמר אנשי אמת כי המדבר היה מקום מושבו של ס''מ הרשע, ולזה היה כמה פעמים מתגבר והורג מהם לסיבה המזדמנת להם מהחטא ועיין בדברי הזוהר (ח''ב קנ''ז.) בפירוש פסוק המדבר הגדול והנורא, ולזה אמר **פן אכלך בדרך** פירוש באמצעות המזדמן בדרך והבן:
@949 **ודבר ה' וגו' פנים אל פנים**. הכוונה בזה הוא כפי שיעור ההכנה שהיה עושה משה להקבלת פני שכינה לאותו שיעור תהיה ההשגה מפנים העליונים כי כפי אשר יכין אדם עצמו להשפעת הקדושה ישיג, ואומרו **כאשר ידבר איש אל רעהו**, יתבאר לדרכנו על דרך אומרו (משלי כ''ז) כמים הפנים לפנים כן לב האדם לאדם פירוש כי הלבבות ישכילו בנעלם אם לאהוב אם לשנוא כי כפי אשר יכין האדם לבו לאהוב חבירו כמו כן יתבונן לב חברו לאהוב אותו, והוא אומרו **כאשר ידבר איש אל רעהו** שלא יאהבהו אם לא יכין לבו להיות גם הוא רעהו כמו כן דבר ה' פנים אל פנים, ומעתה יבחין אדם מה הוא עם קונו אם לבבו יתאוה ויחשוק בה' ובעבודתו הנה זה סימן כי ה' אהבו:
@950 **ראה אתה אומר וגו'**. כוונת הענין הוא כי לצד שעשאו שליח להעלות ישראל אל הארץ והוא אומרו **אתה אומר אלי העל** וגו' ושתף עמו עוד שליח א' מהעליונים דכתיב ושלחתי לפניך מלאך ומן הראוי היה להודיעו לדעת את מי ילך, לזה אמר **ואתה לא הודעתני** מי הוא המלאך אשר ילך עמי לדעת אם אסכים על הדבר או לא כי אין אדם משתתף בדבר עם מי שאינו מכירו, ואם תאמר שבעל כרחך אסכים ללכת עם המלאך שתתן לי בין אם יהיה נוח לי או לא הלא **אתה אמרת ידעתיך בשם** פירוש אמרת לי שאותי גדלת מכל אשר אהבת מאומרו (לעיל ו' ג') וארא אל אברהם וגו' ושמי ה' לא נודעתי להם, הא למדת שאלי נודע בשמו יתברך המיוחד, והוא מה שאמר כאן **ידעתיך בשם**, ושיעור תיבת **ידעתיך** תאיר למולך כשיעור נודעתי במקומה והבן.
@950 **ואמר** עוד **וגם מצאת חן בעיני**, תתבאר על פי דבריהם ז''ל (ילקוט קע''ג) שאמרו כשעלה משה למרום מצא רבי עקיבא שהיה דורש וכו' אמר משה לפני המקום שלח שליחות זה ביד ר' עקיבא שהוא יותר ממני והשיבו ה' כי אינו חפץ אלא במשה, והנה הענין יגיד שאין זה אלא מציאות חן ולא לצד ההשגה במושכלות שהרי הכיר משה בעיני שכלו כי ר' עקיבא עצום הוא ממנו ואף על פי כן לא רצה ה' אלא במשה וזה סימן לחן, ומעתה איך תתנהג עמי במדה זו אין זה אלא שעדיין לא נודע לי מדותיך, לזה שאל להודיעו מדותיו:
@951 **ואדעך למען אמצא חן**. פירוש לצד שאין מהמוסר לומר עבד לאדונו שרוצה לדעת אותו, לזה גמר אומר **למען** וגו' פירוש כדי שנעשה הנהגה ישרה בתמידות לפניך והוא מציאות חן המושג בעיני ה':
@951 **וראה כי עמך הגוי הזה**. כאן דבר משה בנעלם מעיני אדם והודע אליו והוא טענה הנשמעת לפני הבורא מכל הטענות שאמר, והוא כי נשמות ישראל הם חלק ה' כמו שפירשתי בשירת האזינו בפסוק (ל''ב ט') כי חלק ה' עמו, והוא גם כן מה שרמז ה' באומרו (לעיל כ' ב') אנכי ה' אלהיך וכמו שפירשתי שם והוא מה שטען באומרו **וראה** פירוש ראה בפרט זה **כי עמך הגוי הזה** פירוש סמוכים ודבוקים עמך ואיך תמאס חלק עליון והבן:
@952 **ויאמר פני ילכו וגו'**. הרבה פירושים נאמרו בפסוקים אלו, ונראה לפרש הכתוב על פי דבריהם ז''ל (תיקונים י''ח) כי שכינתו יתברך תקרא פני ה' לצד שהיא הנראית לצבא השמים, ואליה רומז אומרו (לעיל כ''ג ט''ו) ולא יראו פני ריקם, וכאן השיב ה' למשה על טענותיו והודיעו כי ההולך עמו הוא **פני** ה' שהוא השכינה, ועל חששת שמא לא יהיה נוח למשה מציאות זה אמר **והניחותי לך**:
@952 **ונתכוין** עוד לומר לו שינוח אור עליון עליו ולא יפסק ממנו מה שנח עליו עד עתה מן הרוח, אלא שלבחינת ישראל תהיה השכינה הולכת לפניהם, ובחינה זו בחינת דין הוא והשם יגיד עליה אדני, ועל זה השיב משה ואמר **אם אין** וגו':
@953 **אם אין פניך וגו'**. לא נתרצה במאמר ה' ואמר וכי על דבר זה אני מתפלל **אם אין פניך הולכים** מעתה אבודים הם ואין צורך בעלייתם, **ובמה יודע איפוא כי מצאתי חן** וגו' **הלא בלכתך עמנו** פירוש בחינה העליונה שהיא סוד המאור הגדול המתכנה בשם הוי''ה ב''ה לא פניך לבד שהוא בחינת הכסא, ומה שהבטחתני שבחינה זו תהיה לי לבדי כאומרו **והניחותי לך** אני שואל שתהיה גם מנהגת כולנו יחד אני ועמך, והוא אומרו **ונפלינו אני ועמך** במדת הרחמים ומעלה עליונה שאין למעלה ממנה, ונתרצה אל עליון ואמר אליו **גם את הדבר הזה** אשר דברת אעשה להנהיגם בבחינת שם שלם המיוחד ב''ה **כי מצאת** וגו' פירוש לא לזכות ישראל אלא למציאת חינו:
@955 **כי מצאת חן וגו** '. ומשה הקדים לומר **ידעתיך בשם** ואחר כך אמר **וגם מצאת חן**, כאן הודיעו הכתוב כי מעלת הודעה בשם הוא עליונה מבחינת השגת החן כי הלא נח מצא חן בעיני ה' ולא ידעו בשם, לזה אמר בתחילה **מצאת חן בעיני** ולא זו בלבד אלא **ואדעך בשם**.
@955 **עוד** נתכוון לומר לו כי מה שהודיעו בשם גם כן היה לצד מה שמצא חן בעיניו, לזה הקדים לומר **מצאת חן בעיני** ואחר כך **ואדעך בשם** לומר שזה יצא מזה מה שאין כן נשמע מדברי משה שהקדים ידעתיך בשם קודם מציאות חן שזה יגיד שהשיג הדבר לצד מה שזכה:
@956 **הראני נא את כבודך**. והגם שאמרו ז''ל (מכילתא פסוק זה אלי) שראוהו ישראל על שפת הים וכתיב (לעיל פסוק י''א) ודבר ה' אל משה פנים אל פנים, אין זה אלא ראות אש אוכלה, והגם שאמר ה' לאהרן ומרים (במדבר י''ב ז') לא כן עבדי משה וגו' ומראה וגו' ותמונת ה' יביט, אין זה אלא תמונת אור עליון ומשה רצה שתהיה לו הכרה בו יתברך ידיעה פרטית כדי שיוכל שכלו ישכיל בחינת האלהות כי ראה שעת הכושר והרחיב פיו לשאול:
@957 **אני אעביר כל טובי על פניך**. פירוש כל מדות טובות שאני מטיב בהם לבריותי, ואומרו **על פניך**, פירוש טעם השגתך דבר זה ממני הוא על פניך, פירוש פנים אשר אתה מראה בעוצם הפלגת אהבתך וחשקך בי כמו שפירשתי בפסוק פנים אל פנים:
@957 **וקראתי וגו'**. פירוש אעביר מדותי ואקראם כל אחת בשמה לפניך, ואולי כי כל מדה תקרא בשמה וכולם יקראו בשם הוי''ה ב''ה, ואין לך הודעה גדולה מזו שהכיר בשמיעת האוזן כל מדותיו יתברך כל אחת תקרא באזניו, ואומרו **וחנותי** וגו' הודיעו כי אותו שעה היא שעת רחמים וחנינה לשאול מאוויו:
@958 **ויאמר לא תוכל וגו'**. פירוש לא שאני מונע הדבר ממך, אלא לצד שאין בך יכולת המשיג כי לא יראני האדם, ואומרו **וחי** פירוש וישאר חי ואני חושש לחייך על דרך אומרו (תהלים פ''ד) כי טוב יום בחצרך מאלף, או יאמר על זה הדרך **כי לא יראני האדם** פירוש בשום אופן ואפילו **חי** פירוש אפילו יהיה צדיק שיקרא עליו חי על דרך אומרו (ש''ב כ''ג) בן איש חי, ואות וא''ו תשמש וא''ו המוסיף, עוד ירצה על זה הדרך **כי לא יראני האדם** אפילו אחר מיתה ואתה מבקש לראות, ועוד **וחי** פירוש בחיים חייתך, כאן רמז שאחר מיתה ישיג מה שלא השיג אדם בעולם שהרי לא שלל אלא לצד היותו חי, והגם שהצדיקים מסתכלים באורו יתברך אחר מותם לא ישיגו מה ששאל משה מלפני ה' אשרי ילוד אשה:
@961 **וראית את אחורי וגו'**. הנה באל עליון לא יתיחס אליו פנים ואחור, אלא כוונתו יתברך הוא לצד כי חיות העולמות עומד בחשק הסתכלות אורו יתברך וקיומו הוא האדון חי העולמים, ודבר זה הוא מן הנמנע שיכול שום נברא להביט אל אורו יתברך, לזה הכין ה' ועשה מסוה אשר דרך שם יביט והוא שקרא אחוריים כמו שעשה בחכמתו את האדם הגוף אחוריים והנפש פנים לו והרוח פנים לנפש והנשמה פנים לרוח, כמו כן הכין אור ממנו יתברך אשר דרך שם ישקיפו ויחזו את האלהים ולו קרא אחוריים ואור עליון שהוא מושלל מהשגת נפש כל חי יקרא פנים, והוא אומרו **וראית את אחורי ופני לא יראו**, ואפשר שרמז לו באומרו סמוך **לאחורי** תיבת **ופני** לומר כי גם שם הם פנים אלא שהכין ה' אחוריים כדי שיהיו במושג לנביאים כמו שכתבנו, ואולי שדקדק באומרו **אחורי** לומר שאין הרבה פרגודים ומסכים מפסיקים כאשר הם בערך הנביאים אשר נוכח ה' יביטו אלא אחד דוקא, והוא אומר **אחורי** ולא אחורי אחורי, והמשכיל על דבר אמת יקוד וישתחוה לאל הגדול וימעיט בעיניו כל עבודתו אשר יעבוד כפי שיעור המושג המקווה לנפש חיה למינה:
@967 **ה' ה' אל רחום**. רבותינו ז''ל אמרו (ר''ה י''ז:) כי ב' מדות אלו של רחמים אחת קודם שיחטא אדם ואחת אחר שיחטא, והרא''ש ז''ל הקשה קודם שיחטא למה צריך רחמים, ותירץ כי צריך רחמים לצד כי ה' יודע שעתיד לחטוא, או מדבר הכתוב בחושב בעבודה זרה ואליו יקרא קודם שיחטא פירוש קודם שיעבור, ואין דבריו ראשונים ואחרונים מובנים לי, כי אם יבא ה' להעניש על מה שעתיד נאמר לפניו גם כן למה בראת אותו כיון שאתה יודע שיחטא וידין אותו על העתיד כי קודם לידתו וקודם חטאו ישוה בהם המשפט ואפילו סמוך למעשה החטא והבן, ומה שכתב בחושב בעבודה זרה ועדיין לא עשה קשה כי זה יקרא אחר מעשה כי הגם שלא עבד חטא המחשבה נתפס עליו, ואני אומר שיצטרך לרחמים אפילו קודם שיחטא אם אין לו זכות שהוא קיום מצות עשה ליהנות מהם הוא האדון יחון אותו ברחמים, והנה לפניך מקרא (דברים י''א י''ג) והיה אם שמוע תשמעו וגו' ונתתי מטר וגו' הרי שבשכר מעשה הטוב יבא הטוב ואם היה אדם אנום ולא למד וכו' אין לו לא שכר ולא עונש ובמה ירוחם, לזה אמר ה' קודם שיחטא והוא חידוש, ועוד אפילו התעיב מעשיו ועבר על מצות לא תעשה יתנהג עמו ברחמים.
@967 **עוד** ירצה להודיע כי כשיטיב ה' ברחמיו לאיש הגם שיחטא לא יפחות מטובו דבר ותהיה המדה שהיה בה קודם מתנהגת גם אחר שחטא, לזה אמר רחמים שקודם שיחטא להשוות להם רחמים שיהיו אחר שיחטא, ובזה נחה דעתי בראות כי לא ישתנה טוב הרשעים ולא כלום כי כן היא המדה:
@970 **ילך וגו' כי עם וגו'**. קשה כי בדברי ה' (ל''ג ג') נאמר לו לא אעלה בקרבך כי עם קשה עורף אם כן כי טעם עם קשה עורף הוא ימנע עלות ה' בקרבם ואיך נותן משה הטעם עצמו כדי שיעלה, עוד קשה למה הוצדך לשאול דבר שכבר נתרצה לו ה' כששאל ממנו ללכת עמהם והשיבו (ל''ג י''ז) גם את הדבר הזה וגו' אעשה. אכן יתבאר הענין בדקרוק עוד למה אמר משה כאן שם אדנות, ותגדל הקושיא למה שפרשתי למעלה כי לא חפץ משה אלא בבחינת הרחמים, ואולי כי כשגילה ה' למשה מדותיו יתברך וראה הפלגתם השכיל כי אם יתנהג ה' עם ישראל במדות אלו בלא דין כל עיקר כמו ששאל קודם העברת הטוב לפניו לא יוכלו עמוד בדרך ישר לפני ה' כי עם קשה עורף הוא לזה חזר בו ושאל שאלה שהוא לצד כבוד המלך לבל יסובב טובו לזלזל במצותיו יתברך כי בהסתלק מהרשעים בחינת הדין כל עיקר יהיו פוקרים, לזה אמר **ילך נא אדני** שהיא בחינת הדין, ושאל מדה שהיה צריך לה כאומרו **וסלחת לעוננו** ומדה זו אינה בבחינת אדנות וכן הוא אומר (לעיל כ''ג כ''א) כי לא ישא לפשעכם אלא במדת הרחמים, נמצאת אומר כי יחפוץ משה ברחמים ודין כי טובים השנים מן האחד:
@970 **ונחלתנו**. פירוש שלא יחליפם באומה אחרת אלא יהיו לו נחלת עולם:
@972 **שמר לך**. צריך לדעת מה ישמור בזה, ואם ישמור הדברים כדברי ראב''ע לא היה צריך להזהירו על מצוה בפרטות מכל מצות התורה ופשיטא שלא יכבוש הנאמר לו בנבואה, ואולי כי לצד שעבדו ישראל את ע''ז לזה מתחכם ה' לרפא שברם במה שיצוררו את עובדי ע''ז ויקוו לאבדם ולהרחיקם בל קרוב אליהם על ידי זה יתכפר עונם ותתרצה תשובתם, והגם שעדיין לא הגיעו לארץ יועיל החפץ והרצון בזה לכפרה על הדבר, והוא אומרו **שמר לך** פירוש על דרך אומרו (בראשית ל''ז י''א) ואביו שמר את הדבר, שיהיו משמרים מתי יבא עת לעשות כל הכתוב להתעיב אותו דבר שבו נכשלו.
@972 **או** יאמר כי מקודם שעשו את העגל לא צוה ה' כל ההרחקה מהאומות והתעבתם, ולצד שקדם מעשה הרע הוסיף ה' להם מצוה זו כדין הרחקת הנכשל בעבירה שצריך להגדיר עצמו בגדר חדש, והוא אומרו **שמר לך** פירוש מצוה זו למה שאליך באה לצד מה שעשית את העגל.
@972 **או** אפשר כי קודם מעשה העגל לא היה ה' מצוה על הדבר האמור בענין כי תכף היה ה' גורש מפניהם כל יושבי הארץ ואין מקום למצוה ולא היה בית מיחוש לחית הארץ, או לצד אימתם של ישראל שהיה נפסק מהם יצר הרע וחית השדה תעבדם, או לצד כי ירבו עד מאד ומלאו הארץ, ואחר העגל בטל הענין והוצרכו לצוות לזה והוא אומרו **שמר לך**.
@972 **ובדרך** רמז אפשר שתיבת **לך** חוזרת אל משה ורמז לו כי מה שאומר לו **הנני גורש מפניך** וגו' אינו לזמן המזדמן אלא לזמן רחוק, והוא מאמרם ז''ל (במ''ר פי''ט) משה שגאל אותנו הוא יגאל אותנו לעתיד לבא, ועל אותו זמן הוא אומר **שמר לך**, ותדע כי לא נתקיימו דברי ה' שאמר כאן למשה הנני גורש מפניך וגו', לזה אמר **שמר לך** לאחרית הימים את אשר אנכי מצוך היום:
@976 **פן תכרות וגו'**. פירוש הגם שבשעה כריתת ברית יקבלו עליהם ז' מצות אף על פי כן לא תכרות, והטעם כי **וזנו** פירוש יושבי הארץ אחרי אלהיהם כי אין אמונה בהם כגלוי ליודע נסתרות, **וזבחו לאלהיהם** וקרא לך וגו' ואמרו במס' ע''ז (ח'.) כי משעת קריאה מעלה עליו הכתוב כאילו אכל, ואומרו **מזבחו** כתב רמב''ם בהלכות שחיטה (פ''ד) שבא לאסור שחיטת גוי ממה שהזכירם באיסורי גוים הא למדת שבחינת הזביחה לבד יתעב ה' הגם שאין בה א' מפסולי שחיטה:
@979 **את חג המצות תשמור**. טעם מצוה זו כאן לציון כי הן אלה תיקוני החטא שקודם כאומרם ז''ל (זוהר ח''ב מ'.) כי החמץ הוא בחינת אל אחר, ולזה צוה ה' ביתר שאת לשמור את הדבר, וצוה כאן על כללות המועדים, אולי כי לצד שנאמר בעגל (לעיל ל''ב ד') אלה אלהיך אשר העלוך וגו' וכל המועדים תלוים ביציאת מצרים, לזה חזר ה' על הדברים כדי שיקבלו עליהם הפרטים שיש נגדיות להם במשמעות מאמר הכפירה, וזה אחד מפרטי התשובה הצריכין, והזכיר שמירת שבת לפי שהם עבדו ע''ז שהיא שקולה כנגד כל התורה כולה לזה אמר ה' מצות שבת שהיא גם כן שקול כנגד כל התורה שבזה יתוקן המעוות, ועיין מה שכתבתי בתחילת פרשת ויקהל:
@985 **אוריש גוים מפניך**. דקדק לומר **מפניך**, פירוש לבל תצטער בראייתם על דרך מאמרם ז''ל (גיטין נ''ו:) במעשה רבי יוחנן בן זכאי עם אספסינוס, הבטיח ה' כי לא יראו לפנינו כל עיקר:
@985 **והרחבתי וגו'**. על דרך אומרו (ירמי' ג') ארץ צבי, ואמרו ז''ל (גיטין נ''ז.) כעור של צבי זה וכו':
@989 **לחם לא אכל וגו'**. הוצרך לפרט **לחם ומים** ולא הספיק לומר לא אכל ולא שתה, לדייק בדבריו בא כי דווקא לחם ומים הוא שלא אכל ושתה אבל אכילה אחרת ושתיה אחרת אכל ושתה כאומרו (תהלים מ') ותורתך בתוך מעי, גם נמשלה למים (תענית ז'.), ואם היה אומר לא אכל ולא שתה יש במשמע כל מין אכילה ושתיה:
@990 **ויהי ברדת וגו'**. אמר **ויהי** לשון צער, לרמוז מה שנכוו כל הצדיקים שבמחנה ישראל ממעלת משה אשר ענתה בפניו דכתיב וירא אהרן וכל בני ישראל את משה והנה קרן וגו':
@990 **ברדת משה מהר וגו'**. לא נודע גזרת הכתוב איה מקומה, עוד צריך לדעת למה כפל לומר **ברדתו מן ההר** ולא הספיק במה שאמר בסמוך ברדת משה וגו'. עוד צריך לדעת לאיזה ענין הודיע הכתוב שלילת ידיעת משה בדבר קודם שיודיענו תחילה ענין קירון פנים שישנו. עוד צריך לדעת מי הודיעו למשה כיון שלא ידע מעצמו ואם הודיעוהו למה לא הודיע הכתוב סדר ההודעה.
@990 **אכן** יתבאר הענין לפי מה שהודיע הכתוב אחר זה כי נתן משה מסוה על פניו בתמידות זולת בעת לימודו אם כן יאמר האומר למה לא נתן משה מסוה על פניו ברדתו מן ההר בזמן שלא היה מלמד את ישראל תורה, לזה אמר הכתוב **ומשה לא ידע** זה היה סיבה שלא נתן על פניו מסוה קודם וראהו אהרן וישראל והנה קרן עור פניו, ועדיין יקשה על זה איך יהיה הדבר שלא ירגיש בעל חי בדבר נוסף בפניו ובפרט קירון פנים, לזה הקדים הכתוב לומר הסיבה שמנעה ממנה הידיעה ואמר **ברדת משה מהר** פירוש כי בהיותו בהר לו יהיה שירגיש בהוד פניו יתלה הדבר כי יבהיקו פניו מאור פני אל המדבר עמו וברדתו מן ההר נסתלק תלית הרגשת אור פניו, ועדיין תקשה למה לא הרגיש במשך ירידתו, לזה אמר **ושני לוחות העדות ביד משה ברדתו מן ההר** פירוש בכל משך רדתו מן ההר, ולזה היה תולה כי מה שהיה מרגיש בפניו היה מאור הלחות אל מול פניו יאירו ולא ידע כי קירון פנים היה קבוע בו בעור פניו, והוא אומרו **לא ידע כי קרן עור פניו** פירוש ידע בקירון פנים אבל לא חשב שהיה אור קבוע בעור פניו והיה תולה בלוחות שבידו וזה היה סיבה שלא עשה מסוה וראהו אהרן, וכפי זה גזרת הכתוב היא **וירא אהרן** וגו' כי זולת כל הכתוב לא היו רואים אהרן וישראל קירון פנים קודם שיקראם שהיה שם מסוה כאשר עשה אחר כך כשהניח מידו הלוחות ולא נשאר במה לתלות מעצמו הרגיש מתת אלהים כי קרן עור פניו ונתן המסוה תכף בסוד (משלי כ''ה) כבוד אלהים הסתר דבר:
@990 **ובמדרש** (שמו''ר פמ''ז) ר' יהודה בר נחמן אמר כשכתב משה התורה נשתייר בקולמוס קמעא והעבירו על ראשו ומשם נעשה קרני הוד ע''כ, ודבריהם ז''ל סתומים וחתומים, ואולי שיכוונו לומר כי מצינו שמדת הענוה למעלה מכל כאומרם ז''ל (שהש''ר פ''א) מה שעשתה חכמה עטרה לראשה שהוא היראה דכתיב (תהלים קי''א) ראשית חכמה יראת ה' עשתה ענוה עקב לסנדל' דכתיב (משלי כ''ב) עקב ענוה יראת ה', ומצינו שהעידה התורה על משה (במדבר י''ב ג') שעניו מאוד מכל האדם, וכשאמר ה' לכתוב הדברים מצינו לו שלא כתב עניו אלא ענו חסרה יו''ד ואף זה מן הענוה, ובשכר זה זכה לקרני הוד כי הפליא ברצונו יתברך גם ה' הפליא חסדו לו בשנותו מכל האדם, והוא מה שרמז רבי יהודה באומרו נשתייר בקולמום קמעא והוא אות יו''ד שהיה צריך לכתוב ולא כתב לרוב ענותו וממנה זכה כנזכר:
@996 **וראו בני ישראל וגו'**. צריך לדעת לאיזה ענין חזר הכתוב להודיע זה, ואולי כי ישמיענו שהוצרכו ישראל לראות הדבר פעמים אחרים להצדיק כי קרן עור פניו לצד שהיה מיחוש שהאור הלז היה לצד עכבתו את ה' נוצצו אורות בפניו ובהאריך הזמן יחזור הדבר לכמות שהיה, לזה היו מסתכלים בפניו בכל עת להצדיק כי קרן וגו', ואולי כי חזרה עטרה ליושנה בבחינת פניו על דרך אומרם ז''ל (ב''ר פ''ב) בספרו של רבי מאיר כתוב כתנות אור, כמו כן משה נעשה עור פניו אור.
@996 **עוד** ירצה כי הגם שעשה משה המסוה לא דנו מפני זה לאסור לראות פניו בזמן שאין מסוה אלא **וראו בני ישראל את פני משה** והדבר מובן כי לא בדרך איסור היו רואים ממה שלא הקפיד עליהם וחפץ ה' לראות באור החיים:
@996 **חסלת פרשת כי תשא**
@997 **ויקהל משה וגו'**. צריך לדעת טעם שהוצרך לומר **ויקהל** אחר שהוא דבר הרגיל בכל עת אשר יצוה דבר ה', ונראה כי לצד שראו כי קרן עור פניו וייראו מגשת אליו, לזה הוצרך להקהיל את כולן לבל ימנעו קצת מהמורא, וזה שדקדק לומר **את כל עדת**.
@997 **עוד** ירצה באומרו **את כל** על פי מה שפירשתי בפרשת תרומה בפסוק מאת כל איש אשר וגו' שבא לרבות יתומים קטנים ונשים יע''ש, והוא אומרו **את כל** ב' ריבויים, וטעם שלא הזכיר הג' שהוא שוע זה אינו צריך לקרא לו כי מעצמו בא יבא ברנה בכלל כל ישראל, ובספר הזהר (ח''ג קצ''ו:) אמרו שהקהיל האנשים להפרידם מהנקבות לצד שהיה השטן מצוי בינם לבל יזיקם ח''ו ע''כ, ומן הסתם לא יכחיש שלא נזדמנו הנשים לשמוע דבר ה' ובפרט להביא נדבת המשכן, וכן הוא אומר (פסוק כ''ב) ויבואו האנשים על הנשים, אלא יכוין לומר כי הקהיל האנשים בפני עצמן והנשים בפני עצמן ולא באו יחד ולא עמדו במסיבה אחת, והכתוב רמז הדברים בייתור תיבת **בני** שלא היה צריך לומר אלא את כל עדת ישראל:
@997 **אלה הדברים וגו'**. צריך לדעת אומרו **אלה הדברים**, ובמסכת שבת (צ''ז:) דרש מכאן רבי ט''ל מלאכות כמנין אלה ל''ו דברים ב' הדברים ג' הרי ט''ל, וזה דרך דרש, עוד צריך לדעת למה הוצרך לומר **לעשות אותם** ולא הספיק באומרו אשר צוה ה', ועוד כיון שלא אמר במצוה זו אלא ענין שבת איך יוצדק ליאמר עליו תעשו. אכן יתבאר ע''פ דבריהם ז''ל (הוריות ח'.) שאמרו בפסוק (במדבר ט''ו כ''ב) כי תשגו וגו' שכל המודה בעבודה זרה ככופר בכל התורה, ומעתה הנה צריכין כל ישראל לתקן כל תרי''ג מצות אשר פגמו בכולן ודבר זה הוא רחוק מגדר ההשגה, אשר על כן באה מצות ה' להם שיזהרו במצות שבת, ואמרו ז''ל (שמו''ר פכ''ה) שקול שבת כנגד כל התורה, ובזה יתקנו פגם שפגמו בכל התורה, והוא מאמר משה כאן **אלה הדברים אשר צוה ה' לעשות אותם** פירוש לשון תיקון בזה יתוקנו פגמיהם של בני ישראל ומה הם הדברים **ששת ימים** וגו' **וביום השביעי** וגו', ובזה יתיישב מה שקשה עוד למה חזר עוד לצוות על השבת אחר שכבר צוה כמה פעמים, ועוד למה צוה עליו סמוך למצות מעשה המשכן, ולדברינו יבא על נכון כי יצו ה' על תיקון העבר כדי שיהיו מוכשרים לשכון בתוכם ובמצות שבת ששקולה ככל התורה היא תקנת עבודה זרה כאומרו (ישעי' נ''ו) אשרי אנוש יעשה זאת ודרשו ז''ל (שבת קי''ח:) כל השומר שבת כהלכתו אפילו עובד עבודה זרה כדור אנוש מוחלין לו:
@997 **עוד** יתבאר ע''פ דבריהם ז''ל (מכילתא פ' תשא) רבי אלעזר בר פרטא אומר מנין שכל המשמר שבת מעלין עליו כאלו עשאו דכתיב ושמרו וגו' לעשות את השבת ע''כ, והנה בפ' כי תשא פירשתי דרכים רבים באומרו לעשות את השבת, ודרשה זו זה מקומה, והוא אומרו **אלה הדברים אשר צוה ה' לעשות אותם** פירוש הדברים עצמן שהם שבתות אתם עושים אותם והבן.
@997 **עוד** ירצה לומר כי הגם כי מצות שבת היא שמירה מהמלאכות ושביתה ואין כאן מעשה ליטול עליה שכר **אלה הדברים אשר צוה ה'** שיהיו בגדר מעשה ליטול עליהם שכר, ועיין מה שכתבתי בפרשת כי תשא (ל''א ט''ז) טעם לזה, ודקדק לומר **אלה** לשלול הדוגמא שישנו בבחינת שמירה לבד אינו כבחינת המעשה ליטול עליו שכר.
@997 **ועל** פי המדרש (ילקוט) שאמרו כי אמר הקב''ה למשה הקהל קהילות ודרוש ברבים כדי שילמדו לדורות הבאים להקהל בכל שבת וכו', יתבאר הכתוב על נכון **ויקהל משה** וגו' **ויאמר אליהם אלה הדברים** פירוש הקהלת העדה ודרשת התורה **צוה ה' לעשות אותם**, או ירמוז באומרו **לעשות אותם** על בני ישראל כי באמצעות הדברים מתכפרים כל עונותם כמאמר ר' ישמעאל שם:
@998 **ששת ימים תעשה**. טעם זכרון עשיית מלאכה בימי החול, אולי שיכוין לומר שאם יהיה יום ז' קודש תעשה המלאכה הצריכה לך בששת ימים.
@998 **או** ירצה הכתוב לאסור מלאכת שבת בין על ידי עצמו בין על ידי גוי, והוא אומרו **ששת ימים תעשה** בציר''י תחת התי''ו פירוש תהיה נעשית אבל ביום השביעי אפילו על ידי אחרים אין לך לעשות, וזה כהאומר אמירה לגוי אסורה דבר תורה (מכילתא פ' בא), וטעם אומרו **ששת** ולא בששת כדי שלא תטעה כי יש מצוה בעשיית מלאכה בהם.
@998 **עוד** ירמוז כי לא יקומו ששת ימים במלאכתם אשר הכינם ה' לעשות אלא אם יום השביעי יהיה לכם קדש אבל אם לא ישמרו שבת לא יהיו הששת ימים כי שבת הוא נפש קיום העולם, וכמו שהקדמנו בפרשת בראשית בפירוש פסוק (ב' ב') ויכל וגו' ביום השביעי יע''ש:
@1000 **אל כל עדת וגו' לאמר וגו'**. צריך לדעת למי יאמרו בני ישראל, ואולי כי לצד שלא ידבר משה עם הנשים והקטנים הגם שיהיו שם וצוה לאמר להם הדברים, ואומרו **זה הדבר** וגו' **לאמר** יתבאר ע''פ מה שאמרו בספרי (פ' תצא) ר' מאיר אומר טוב אשר לא תדור טוב מזה ומזה שלא תדור כל עיקר ר' יהודה אומר טוב מזה ומזה נודד ומשלם ע''כ, ואמרו בפ''א דנדרים (ט'.) ב' אוקימתות א' שחולקים בנדר אבל בנדבה מודה ר' מאיר שיהא נודב ומשלם וכגון שהיה באופן שאינו בא לידי תקלה וכמעשה הלל שהיה מביא קרבנו כשהיא חולין לעזרה ושם היה מקדישה, והב' שחולקים בנדבה ולא אמר ר' יהודה אלא נודב אבל נודר לא, ונודב עצמו דוקא באופן שאינו בא לידי תקלה כנזכר יע''ש, לפי זה יכוין הכתוב לומר על זה הדרך כי לצד שקדם לומר קחו מאתכם תרומה כל נדיב לבו אם כן בנדבה מדבר הכתוב, לזה אמר **זה הדבר** פירוש הנדבה צוה ה' **לאמר** אותה פירוש דוקא במציאות זה שהוא שצוה ה' שתאמרו נודב ומשלם והוא בסדר שאינו בא לידי תקלה, לאוקימתא ראשונה יעלה דרכנו כר' מאיר ולאוקימתא ב' כר' יהודה:
@1001 **יביאה את תרומת ה'**. פסוק זה מראה באצבע כי לבד המורגש יש המושכל והוא מאמרם ז''ל (תיקונים תיקון כ''א) כי מעשה התרומה מושכל היא בחינת השכינה כי לה יקרא תרומת ה' ועל ידי מעשה התרומה יפעיל בה דבר טוב ויחבר אוהל בל ימוט, ועיקר הרצון במעשה הוא המושכל, והוא אומרו **יביאה** פירוש יביא לבחינה הנעלמת עם תרומת ה', וביאר הכתוב מי הוא אשר יביאה ואמר **כל נדיב לבו** פירוש העושה דבר מנשיאות הלב אשר ידבנו לצד התנועעות הרוחנית השוכן בלב בחשק הדבר יפעיל במושכל נעלם אבל אם יביא התרומה בלא נדיבות לב אין זה פועל במושכל:
@1001 **זהב וכסף וגו'**. ראיתי לתת לב בכל הפרשה בסדר התחברות השמות ופרטי הדברים כי לא השוה מדותיו בהם לפעמים יאמר וא''ו בכל פרט הנוסף כמעשהו בסדר י''ג דברים הבאים בנדבת המשכן שאמר וא''ו בכל נוסף ולפעמים יאמר וא''ו בהתחברות הג' כאומרו את המשכן את אהלו ואת מכסהו ותכף חזר בו בכתוב עצמו ולקח סדר התחברות אחר ואמר את קרסיו ואת קרשיו וכן על זה הדרך עד סוף סדר פרטי המשכן כמה שינויים בפרט זה.
@1001 **ונראה** ליישב בהקדים דבריהם ז''ל (ב''ר פ''ל) כי הוי''ו יגיד התקשרות הנוסף עם הראשון, וחסרון הוא''ו יגיד כי הוא גבול בפני עצמו, ומזה נשכיל על כל דבר ודבר ונלך לישב כל פרט ופרט במקומו, וזה יצא ראשונה בנדבת המשכן אמר ו' בראש כל פרט כדי להסמיך ולהשוות כל הי''ג דברים לומר שכולם שוים ליקראות תרומת ה' וזכותן שוה מביא הנחושת כמביא זהב כמו שמצינו שאמר הכתוב בעולת הבהמה ריח ניחוח ובעולת העוף ריח ניחוח ואמרו ז''ל (מנחות ק''י.) לומר לך אחד המרבה ואחד הממעיט כו', ועיין מה שפירשתי בענין בפרשת ויקרא (א' י''ז) גם נתכוין לומר שכל הי''ג דברים חובה הם לצורכי המשכן דבר קטן כדבר גדול מעכבין אשר על כן חברם במחברת הווין, כל זה בערך דבר הניתן אבל בערך הנעשה ממנו יש בהם הדרגות הקדושה כמה קדושות הם זו למעלה מזו ולא תדמה שום קדושה למה שלמעלה ממנה:
@1007 **את המשכן וגו'**. הנה הדרגת המשכן שהם יריעות התחתונות להיות שמסככין על הקודש הם בהדרגה מעולה מאהלו ומכסהו העשויים מהעורות שאינם רואים פני הקודש לזה לא אמר ואת אהלו להשוות אליו אבל כל מה שעל יריעות התחתונות השוה אותם הכתוב במדרגה אחת ואמר **ואת מכסהו** להשוותו בגדר אחד עם אהלו, ולו יהיה שתהיה גדולה קצת הדרגת האוהל מהמכסה יודיע הכתוב כי אין הפרש כל כך ובהדרגה אחת תחשב, ואומרו **את קרסיו** ולא אמר ואת לומר כי הדרגה זו של הקרסים אינה בגדר השואה עם אוהל ומכסהו, ואמר **ואת קרשיו** כי שוים הם בגדר עם הקרסים, ואמר **את בריחיו** כי אינם בגדר קדושת הקרשים, ואמר **את עמודיו** שאינם בגדר הבריחים ואמר **ואת אדניו** כי שוים בהדרגה עמודים לאדנים והמשכיל על דבר יראה כי השכל יכיר ההדרגות שהם כמו שכתבתי:
@1008 **את הארון**. התחיל הכתוב במעולה שבכלים כמו שהתחיל במשכן ביריעות של שש שהם גדר הקדושה המעולה שבבית, ואומרו **ואת בדיו** יודיע הכתוב כי שוים הבדים לגופו של ארון בקדושה, ולזה תמצא שצוה הכתוב (לעיל כ''ה ט''ו) לא יסורו ממנו, ואומרו **את הכפורת** כי לא שוה לקדושת הארון, וכן תמצא שלא היה קבוע בארון וגם אין אזהרה שלא להסירו, ואומרו **ואת פרוכת המסך** השוה הכתוב קדושתו לקדושת הכפורת שהם בגדר אחד:
@1009 **את השלחן**. אין קדושת השלחן שוה לקדושת הקודם לו, לזה אמר **את**, ואמר בכל פרטיו **ואת** כי מדרגת כולם שוה בקדושה, **ואת מנו רת המאור** בתום' וא''ו לומר כי זו קדושתה וקדושת כליה שוים לקדושת שלחן וכליו, ואמר **ואת מזבח** הזהב כמו כן בגדר שוה למנורה ולשלחן הוא וכליו ושמן המשחה וגו' עד מסך הפתח בכל פרט אמר הכתוב **ואת** לומר שכולן בגדר אחד הם, ואמר **את מזבח העולה** בלא וא''ו לומר שאינו בגדר קדושת הקודם ומקומו מוכיח עליו, ואמר **ואת מכבר** שהוא בגדר עמו, ואמר **את בדיו** שאינו בגדר עמו, **ואת כל כליו** בגדר א' עם בדיו, **את הכיו** ר אינו בגדר מזבח הנחשת, **ואת כנו** בגדר א' עם הכיור, **את קלעי החצר** אינם בגדר מזבח העולה וכליו, **את עמודיו** גדר למטה מהקלעים, **ואת אדניה ואת מסך** בגדר א' עם עמודיה, **את יתדות** גדר בפני עצמו, **ואת יתדות החצר ואת מיתריהם** כולן שוים בגדר אחד, **את בגדי השרד** הם דברים שמכסים הקודש בפרק הנסיעה ומדרגתם למטה ממדרגת יתדות וגו', **את בגדי הקדש** הם מדרגה בפני עצמן, ועיין מה שכתבתי בפרשת תרומה (כ''ה ז') כי אין מועלים בבגדי כהונה ומועלין בכל כלי הקודש, **ואת בגדי בניו** שוים הם לקדושת בגדי אהרן אביהם לזה חברם בוא''ו המחברת:
@1016 **ויצאו כל עדת בני ישראל**. פירוש שיצאו כולם כאחד בזריזות להביא ולא היה בהם אחד שנתעכב מחבירו:
@1016 **מלפני משה**. פירוש מלפניו קודם שיתן להם רשות לעמוד מלפניו, והגם דאמרינן ביומא (נ''ג.) שאין רשות לתלמיד לעמוד מלפני רבו אלא עד שיתן לו רשות, דנו ישראל כי כשאמר להם קחו מאתכם תרומה וגו' וגמר דבריו כאילו אמר להם עמדו, או אפשר כי אהבת הדבר קלקלה השורה, עוד נראה שנתכוונו להקדים לבל ילך משה ויקדים להביא כל הצורך משלו כי עשיר גדול היה וחשק גדול הוא בעשות מצות ה' לזה יצאו מלפניו פירוש על דרך אומרו (רות ד') וזאת לפנים קודם לו:
@1017 **ויבאו כל איש אשר נשאו וגו'**. פירוש אומרו **נשאו לבו ונדבה** וגו', דע כי יש שתי הדרגות במתנדבים, הא' הוא המתנדב ברצון נפשו כפי יכולתו וערך ממונו, ולזה יקרא נדבה רוחו לשלול שאינו עושה הדבר כמו צער בנפשו, והב' הוא המתנדב יותר מיכולתו מגודל טוביות לבו, ולזה יקרא נשאו לבו פירוש שהלב מנשאהו ומעריכו בערך עשיר יותר ממה שהוא לתת דבר יקר, ולזה אמר כי בישראל נמצאו ב' סוגים הנזכרים, ופתח במעולה שבשניהם ואמר כל איש אשר נשאו לבו, ודקדק לומר תיבת **איש** לשון חשיבות, וכנגד הב' אמר **וכל אשר נדבה רוחו** ולא אמר איש כי אינו חשוב בערך הראשון, וממוצא דבר אתה יודע כי לא היו בכל המתנדבים אלא ב' הדרגות וב' לשבח שנדבו בלבם ולא עשו הדבר בחסרון רצון הלב אלא שאחד גדול מחברו, ולזה דקדק לומר **הביאו את תרומת ה'** לרמוז לבחינת הנעלמת שרמז באומרו (פסוק ה') יביאה את תרומת ה' וכמו שפירשנו שם שיכוין אל המושכל ודבר זה עקרו בנדבת הלב והנה הוא:
@1017 **ולכל עבודתו וגו'**. יודיע הכתוב כי כל צרכי המשכן פירוש כל הי''ג דברים שצריכין למשכן וכו' באו בעצמן בנדבה ולא הוצרכו לקנות דבר מהם בכסף וזהב המובא בתרומה והבן:
@1018 **ויבואו האנשים על הנשים וגו'**. צריך לדעת כוונת. אומרו **על הנשים**, עוד למה כפל לומר פעם אחרת **כל נדיב ל**. ב, ואולי כי יודיע הכתוב אופן נדבת לב אשר עשו אנשי החיל, כי דבר ידוע הוא שיש הדרגות באהבת הנכסים והם ד', הא' שבראשונות הם כלי תכשיטי בני ביתו של אדם וכלי הבית דברים אלו יגדל ערכם בעיני האדם מכל קנין כספו והדבר פשוט הוא, ב' הזהב כי מכל קנינים שישנם בעולם יאהב הזהב יותר מכולם, ג' דברים שאינם בנמצא זולת אצלו יגדל מעלתם בעיניו יותר משיעור שוים, ד' הם שאר קנייני האדם כסף ושוה כסף, וסידר הכתוב הדרגות המתנדבים בעם וראשון בקודש התחיל בו ואמר **ויבואו האנשים על הנשים** פירוש מה שעל הנשים כל נדיב לב הביאו אותם וסידר הכתוב התכשיטים שהביאו להראות חיבת המתנדבים שלא רצו להביא אלא דבר היותר מעולה וחביב אצלם הגם שעומדים לשבירה ולקלקל אף על פי כן אהבה נפשם חיבת הקודש מכל יקר ראתה עינם והביאו כל תכשיטי נשיהם חח ונזם וטבעת וגו', ודקדק לומר **נדיב לב** דע כי יש הפרש בין ידבנו לבו לנדיב לב כי ידבנו לבו יאמר על כל אשר יתנדב מלבו ויש שידבנו הרבה ויש שידבנו מועט אבל נדיב לב יאמר על לב נדיב, והוא הרמוז באומרו **אשר נשאו לבו** כי מי שלבו נדיב יתנדב יותר מהיכולת ולא יקפיד על החסרון אשר ימצאנו כי שמח בנתינה יותר מהקנין אצלו, ואומרו **כל כלי זהב** פירוש לא תאמר כי לצד שהיו להם התכשיטין הוא שהביאו לה' הכפל, לזה אמר **כל כלי זהב** שלא הניחו להם כלי זהב ואומרו **חח ונזם** שם המין, או ירצה **כל כלי זהב** לומר שלא הניחו בביתם כל מין כלי זהב שבהם ישתעשע אדם לקיים אומרו (שה''ש א') נגילה ונשמחה בך, ואולי כי רמז באומרו **על הנשים** שהביאום עליהם ובבואה לפני משה הורידו עדים מעליהם ונתנום לתרומת ה' חיבה יתירה נודעת להם בזה לאדונינו ב''ה, הדרגה ב' היא הזהב שאינו עשוי תכשיט כנגד המביא מבחינה זו אמר **וכל איש אשר הניף תנופת זהב לה'**. ג' דברים שאינם בנמצא כי היו במדבר ואין שם בנמצא תכלת וארגמן וכו' וכנגד המביא מהם אמר **וכל איש אשר** וגו' **תכלת וארגמן** וגו'. ד' והוא מדרגה שלמטה מכולן בבחינת הקנינים כסף ושוה כסף אמר **כל מרים תרומת כסף ונחושת** וגו', ואומרו **וכל אשר נמצא אתו עצי שיטים** אלו אין להם כינוי נדבה, והטעם על דרך אומרם ז''ל (תנחומא פ' תרומה) כי צפה יעקב אבינו וכו' יצוה ונטעום לצרכי המשכן, ולזה לא אמר אלא **וכל אשר נמצא אתו עצי שטים** וגו' **הביאו**, ודקדק לומר **לכל מלאכת העבודה** לצדק דברינו כי מציאת עצי שטים בידם היה לצורכי מלאכת המשכן שאם לא כן לא היה צריך לומר כן, ועוד היה לו להקדים לומר **הביאו** ואחר כך יאמר **לכל מלאכת המשכן** אלא לומר כי מציאותם בידם הוא למלאכת וגו' והם לא עשו אלא ההבאה והוי כדבר שאין בו חסרון כיס להם והבן, ולפי מה שהצענו יש טעם נכון למה אמר בכל פרט ופרט הביאו ולא הספיק באחת כי אין הדרגת ההבאה שוה:
@1023 **והנשאם וגו'**. לצד שבאו באחרונה נכתבו אחר מטוה העזים בחכמת נשים:
@1025 **הביאו בני ישראל נדבה לה'**. התורה מעידה על כללות ישראל שהביאו נדבת ה' פירוש דבר הראוי ליקרא נדבה:
@1030 **ולהורות נתן וגו'**. פירוש לצד שיש חכמים רבים שתהיה חכמתם בלבם לבד שלא ידעו ללמדה, לזה אמר **ולהורות נתן בלבו** השכיל חכמת הלימוד, עוד בא לשלול מה שכתוב בפ''ג דיומא (ל''ח) של בית גרמו לא רצו ללמד על מעשה לחם הפנים של בית אבטינם לא רצו וכו', והודיענו הכתוב כי על אלו יאמר (משלי י') זכר צדיק לברכה כי היו מורים ומלמדים כל הרוצה:
@1032 **ועשה בצלאל וגו' את כל מלאכת וגו'**. קשה והלא אפילו לקיחת הנדבה עדיין לא לקח לעשות ואיך יוצדק לומר **ועשה** וגו', אכן הכוונה היא שהכין כלי אומנות הצריכין לעשות בהם כל פרטי המלאכה אשר צוה ה' לעשות כי צריכין כמה פרטי כלי אומנות, וזה שיעור הכתוב **ועשה בצלאל** וגו' **את כל מלאכת** פירוש כלים שהם מלאכת מעשה **עבודת הקדש לכל אשר צוה ה'** כי יש עבודת המתכות ועבודת כלי עץ ועבודת האבנים והאריגה, וצא ולמד מה שאמרו ז''ל (שבת מ''ט:) כי המ' מלאכות כולן היו במקדש, ומהנשמע מהכתובים מובן כי ביום אחד הכינו כל כלי אומנות:
@1034 **והם הביאו אליו עוד וגו'**. פירוש מדברים הנעשת בהם מלאכה כמו שתאמר מטוה של תכלת וגו' ושל עזים וכל הפרטים אשר תעשנה בידים וזה סיבת עכבתם שלא הביאו עד אחר יום או יומים כי עסוקים היו ומביאים מלאכתם יום יום, אבל נדבת ממון הצריכה כבר הביאו ביום ראשון בפעם אחת:
@1036 **מרבים העם להביא**. קשה וכי רע הדבר שיהיה בית אלהינו באוצרות זהב לכבוד ולתפארת, אכן לא באו לקבול על המובא בית ה' מהזהב וכסף וגו' אלא על המובא עשוי מלאכה שהוא דבר שאין צורך בו גם עומד להתקלקל כל שיש די מחסור, והוא אומרו **מרבים** וגו' **מדי העבודה למלאכה** פירוש מרבים להביא יותר משיעור העבודה הצריכה למלאכה אשר צוה ה' הא למדת שעל פרטי העבודה הקפידו, והעד לדברינו מאמר הכרוז **אל יעשו עוד מלאכה לתר ומת הקודש**, ואומרו **ויכלא העם מהביא** ולא אמר מעשות כי יאמר הכתוב דבר שהוכר לחכמים העושים במלאכה והיא ההבאה:
@1038 **דים וגו' והותר**. הם ב' דברים הפכיים אם דים אינו הותר ואם הותר אינו דים, וכאן אין מקום לומר לא זו אף זו לצד ששניהם סוג אחד ובחינה אחת ואין דרך לעשות סוג א' ב' סוגים כי יש בנשמע הכחשה, ועוד לא היה צריך לומר דים אלא והמלאכה היתה הותר לכל המלאכה, ועוד כל הכתוב מיותר שהרי אמר למעלה מרבים העם להביא מדי העבודה למלאכה ופשיטא שלא אמרו כן עד ששערו ומה צורך עוד לומר והמלאכה וגו'. ואולי שישמיענו הכתוב חיבת בני ישראל בעיני המקום כי לצד שהביאו ישראל יותר משיעור הצריך חש ה' לכבוד כל איש שטרחו והביאו ונכנם כל המובא בית ה' במלאכת המשכן, וזה שיעור הכתוב **והמלאכה** אשר צוה ה' לעשות במשכן הספיקה להכנס בתוכה כל המלאכה שעשו בני ישראל הגם שהותר פירוש שהיה יותר מהצריך הספיק המקבל לקבל יותר משיעורו על ידי נס. או על זה הדרך **והמלאכה** שהביאו **היתה דים** לא חסר ולא יותר הגם שהיתה יותר כפי האמת והוא אומרו **והותר** כי נעשה נס ולא הותיר:
@1039 **ויעשו כל חכם לב**. פירוש הגם שהעושים רבים הם אף על פי כן היתה המלאכה נעשית כאילו עשאה אדם אחד, והכוונה בזה כי כשיעשו המלאכה רבים על כל פנים ישתנה תואר מלאכת זה מזה ולא תדמה למלאכה שיעשנה כולה אומן אחד, והשמיענו הכתוב כי מלאכת המשכן שלימה היתה גם בבחינה זו כי הנותן חכמה בהמה השוה אותם בהתבוננות החכמה שוה ודומים כולם לאיש אחד, ולדרך זה יתיישב טעם אומרו בכל פרטי המעשים לשון יחיד ולא פירש מי הוא ופשיטא שאינו חוזר על בצלאל כי לא הוא עשה הכל והעד הנאמן (לקמן ל''ז א') ויעש בצלאל את הארון, אלא יכוין אל עושי המלאכה והזכירם בלשון יחיד לטעם שכתבתי:
@1039 **חכם לב בעושי וגו'**. אולי שירמוז שבאמצעות עשייתם המלאכה ובסיבתה נעשו חכם לב:
@1042 **ויעשו וגו'**. טעם אשר החזיר הכתוב כל הפרטים ולא הספיק לומר ויעש כאשר צוה ה' את משה, על דרך אומרם ז''ל (ב''ר פ''ס) בכפל פרשת אליעזר עבד אברהם כי מתוך שחביבה עליו כתבה ב' פעמים, וכמו כן גילה הכתוב בענין מעשה המשכן כי חביב עליו ולזה נכתב ב' פעמים:
@1074 **על צלעות הארון**. ג' פעמים נזכר **הארון** בפרשה זו כנגד ג' ארונות שעשה בצלאל כאומרם ז''ל (יומא ע''ב:):
@1077 **משני קצותיו**. אולי שיכוין לומר שלא עשה הכפורת שוה והיה מכה בקורנס בכל רוחב הכפורת וכו' אלא בשעת ההתכה התיך במקום רחב כשיעור הכפורת ובב' קצותיו הרבה זהב שיעור שיספיק לכרובים ובזה ידוייק אומרו **משני קצותיו**:
@1086 **ויעש את המנורה וגו'**. תמצא בכל המעשה שידייק לשון המעשה כלשון המצוה וצריך לדעת למה שינה במנורה שבמצוה אמר **מנורת זהב** וכאן אמר **את המנורה**. ואולי כי לפי מה שאמרו ז''ל בהקומץ רבה (מנחות כ''ח:) כי המנורה באה גם מהמתכות דכתיב תעשה לרבות, לזה אמר ה' **מנורת זהב** לומר כי מה שהתיר בריבוי **תעשה** אינו אלא לדורות אבל במשכן מעכב להיות זהב, ולזה הסמיך **מנורת זהב** בלא הפסקה לומר שאין מעשיך במנורה אלא של זהב. או על זה הדרך מנורת זהב ולא מנורת שאר מתכות הגם שהכשרתים לך, ודקדוק זה אין שייכות להודיע במעשה אלא הודיע שקיים מצות ה' ועשאה זהב והבן:
@1094 **ויעש את מזבח הקטורת**. זה הוא מקום זכרונו כי פנימי מהאמור אחריו, ומה שצוה ה' עליו מאוחר מהכל כתבתי בפ' תרומה בפסוק וכן תעשו (כ''ה ט'):
@1094 **חסלת פרשת ויקהל**
@1119 **אלה פקודי וגו'**. אומרו **אלה** לפסול כל מנינים שבעולם כי כל מה שימנה אדם מקנינים המדומים אין מניינו מנין ושמו מורה עליו מה אתה מונה, אבל מנין זה עומד לעולם, והטעם להיות מנין המשכן המופלא אשר שכן שם אלהי עולם ה':
@1119 **עוד** ירצה על דרך אומרם ז''ל (ב''מ מ''ב.) אין ברכה שורה לא בדבר הספור ולא בדבר המנוי, וכאן אמר **אלה פקודי** פירוש לאלה יש מנין ואין הקפדה כי מנין זה אדרבא מניינו תביא הברכה כי כל פרט שירבה במספר תגדיל הזכות ותסובב הברכה למרבה, והטעם להיותו של המשכן:
@1119 **עוד** ירמוז באומרו **אלה** על דרך אומרם ז''ל (ויק''ר פכ''א) אם עשית חבילות וכו' עשה כנגדן חבילות של מצות, כי צריך האדם לתקן החטא בדוגמא, והנה ישראל חטאו ואמרו (לעיל ל''ב ד') אלה אלהיך לזה באה **אלה** זאת בבחינת הזכות לכפרת עון זה, ותמצא כי אמרו (רבה) העדות שעדות הוא להם שנתכפר עון העגל, וכשתדקדק תמצא כי כל פרטי עון העגל בא כנגדן במשכן, הם התאוו תאוה (ל''ב א') אלהים אשר ילכו לפניהם הנה הנם הכינו מקום לה' אלהים אמת להיות לפניהם, הם בנו מזבח והעלו עולות (שם ו') הנה הנם הכינו מזבח להעלות עולות ושלמים לה', הם נתנו זהבם הנה הנם נתנו זהבם וכספם וכל כלי חמדתם לה', הם פרקו נזמיהם הנה הנם הביאו האנשים על הנשים לא נזם לבד אלא כל עדים מעליהם וכל כלי חמדה, וכמו שפירשנו בפרשת ויקהל (ל''ה כ''ב) הם עשו ממונים עליו לעשותו הנה הנם פקדו בצלאל לעשות וכו', אמרו אלה אלהיך הנה **אלה פקודי** לכפרה:
@1119 **עוד** ירצה על זה הדרך להיות שמשה עשה המספר לישראל המובא בית ה', לזה באה התורה והצדיקתו ואמרה **אלה פקודי** וגו', פירוש על דרך אומרו (ויקרא כ''ג ב') אלה הם מועדי, מה הוא המספר שה' מצדיק אשר פוקד על פי משה דקדק לומר **על פי משה** ולא אמר אשר פקד משה, הטעם כי לא היה הזולת עמו להצטדק אלא מפיו אנו חיין שכן כתיב (ל''ו ג') ויקחו מלפני משה שהוא לבדו לקח הכל, וטעמו של משה שהביא עצמו לידי חשד, אולי שלא עלה בדעתו חשד זה להשמר ממנו כי איך יחשדו אותו וה' מדבר עמו בכל עת אם ח''ו ימצא בו עול ימאסנו אלוה היודע נסתרות, ואין צריך לומר שלא ידבר אתו עוד אלהים, או דקדק מאמר ה' שאמר לו (ריש פ' תרומה) דבר אל בני ישראל ויקחו לי וגו' כמו שפירשנוה במקומה כי צוה לו להיות הוא גזבר לבדו, וישרים דרכי ה' וצדיקים ילכו בם אף על פי שפושעים יכשלו בם:
@1119 **עוד** ירצה על זה הדרך **אלה פקודי המשכן** ומי יצדיק שכן הוא ולא יותר, לזה אמר משכן העדות פירוש המשכן הוא יעיד על הדבר על דרך אומרם ז''ל (שמו''ר פנ''ב) בפסוק ויקם משה את המשכן שלא היה אחד מישראל יכול להעמידו, וזה לשונם כמה חכמים היו שם ולא היו יכולין להקים את המשכן וכו' ולא היו יודעים לישב אותו כל אחד נטל מלאכתו והלך אצל משה וכו' ושרתה רוח הקודש על משה והקים את המשכן ע''כ, זה הוא עדותו היותו נקי כפים שאין חמס בכפיו שאין הקב''ה עושה נס לעושי עול ובפרט במקום עצמו שנעשה בו העול ח''ו, ואם תאמר ומה עדות הוא זו יש לתלות כי לצד כי משה היה גבור חיל גבורתו עמדה לו שהעמידו מה שלא היה כח כמו כן בזולתו, לזה גמר אומר **עבודת הלוים ביד איתמר** וגו', פירוש הלא תמצא שעבודת הלוים שהיא ביד איתמר היא קרשי המשכן ובריחיו ועמודיו ואדניו והם המורידים אותו בנסעם ומקימין אותו בחנותם דכתיב בפרשת במדבר (א' נ''א) ובחנות המשכן יקימו אותו הלוים הרי שהלוים היו מפרקין ומקימין אותו אם כן לא מניעת הכח היא הסיבה; וכפי זה הרווחנו כוונת אומרו **עבודת הלוים** וגו' **ביד איתמר** שאין ידוע מה בא ללמד ומה שייכות למאמר זה כאן ולמה לא אמר אלא איתמר ולא אלעזר הגדול, ולדרכינו יבא על נכון, ועדיין יש לתלות לצד החכמה כי משה חכם וחריף היה וידע להקימו ולעולם לא נעשו מעשה נסים, לזה אמר **ובצלאל בן אורי** וגו' **עשה את כל אשר צוה ה'** ואמרו ז''ל שאפילו דברים שלא אמר לו משה הסכימה דעתו, **ואתו אהליאב** וגו' **חרש** וגו' ואף על פי כן לא עמדה לו חכמתו וכאומרם במדרש (שמו''ר פנ''ב) שגם אומנות האומנים לא הועילה, וכפי זה הרווחנו כוונת הכתוב בהודעת מעשה בצלאל אחר שכבר ידענו זה פעמים ושלש בפרשת ויקהל אלא בא לחזק עדות נס המשכן לומר הא למדת שאין זה אלא נס וזו הוא עדות המשכן על פקודיו, ולדרך זה אומרו **אשר פוקד על פי משה** לומר שעל זה באה העדות להסיר החשד ממנו:
@1119 **עוד** ירצה על דרך אומרם ז''ל (שם פנ''א) שהמשכן היה כפרה על מעשה העגל, עוד אמרו בחולין (ה'.) כי שקולה עבודה זרה ככל התורה כולה, והוא אומרו אלה פקודי פירוש על דרך שתרגם אונקלוס (ויקרא כ''ז ל''ד) אלה המצות אלין פקודיא, המצות שתלוים במשכן **משכן העדות אשר פוקד** וגו' פירוש כל המצות שבתורה שנצטווה משה כולם ישנם במצות המשכן, ובזה יכפר המשכן על העגל ששקול כנגד כל התורה, ואולי שנתכוון לרמוז הענין בחשבון פקודי המשכן שעולה תרי''ה והם תרי''ג מצות וב' הלוחות, ומעתה אלה תשכחנה כי נתקן בפקודי המשכן, ואומרו **עבודת הלוים** בא לשמור את הדבר לבל תאמר כיון שנתכפר עון העגל אשר הוא יסובב הסרת עבודה מהבכורות כמאמרם ז''ל (במ''ר פי''ב) אם כן תחזור העטרה ליושנה ויעבדו הבכורות עבודת המשכן, לזה אמר סמוך לדבר **עבודת הלוים** פירוש עבודה זו אינה אלא ללוים, כאן כלל כל שבט לוי בין הכהנים בין הלוים כי גם הכהנים יקראו לוים דכתיב (דברים כ''ז ט') והכהנים הלוים, ואומרו **ביד איתמר** וגו' פירוש לא מבעיא עבודות המעולות של הכהנים ולא מבעיא עבודות הלוים המעולות של בני קהת ובני גרשון אלא אפילו עבודה הקלה של הלוים **ביד איתמר** שהם הקרשים והאדנים הדבר במקומו עומד, ומזה אתה למד כי לא נמחק עון העגל מחק שאין רשומו ניכר והעד הנאמן (לעיל ל''ב ל''ד) וביום פקדי וגו':
@1119 **עוד** ירמוז באומרו **פקודי המשכן** לשון מינוי על דרך אומרו (במדבר ד' ט''ז) ופקודת אלעזר שהוא לשון מינוי על הדבר, והודיע הכתוב כל מינויי המשכן מהם ממונים על המשכן עצמו להתקיים או להתבטל ח''ו, ומהם על עבודתו, ומהם על עובדיו, ומהם על מלאכתו, והתחיל במינוי קיום המשכן ואמר **משכן העדות** פירוש פקודת המשכן הוא העדות שהיא התורה כי כל זמן שישראל עוסקים בתורה ומקיימין מצותיה יתקיים המשכן וזולת זה אין משכן, והוא אומרם ז''ל (במד''ר ל''ב) בפסוק (תהלים ע''ח) אוהל שכן באדם וכי באדם שכן אהלו אלא באמצעות אדם אם יכינו לבם ללמוד תורה ולקיים מצותיה, ולאו דוקא עדות הכתובה בלוחות ובספר כתובה אלא **אשר פוקד על פי משה** פירוש תורה שבעל פה שנמסרה למשה לפה ולא לכותבה, ב' יכוין על פקודת משה שפקיד הוא בדבר זה לצוות משפטיו ודיניו של משכן, מינוי ג' הם העובדים במשכן עבודת הלוים פירוש הם ממונים על עבודת המשכן, מינוי ד' הם אהרן ובניו ושלשתם רמזם הכתוב **איתמר ואהרן** הרי נאמרו בפירוש ואלעזר רמזו באומרו **בן אהרן** כי אני יודע כי איתמר בנו של אהרן הוא אלא לרמוז על אלעזר, ואולי שלא הזכירה התורה אהרן כל עיקר במינוי המשכן אלא בניו ואומרו **בן אהרן הכהן** יכוין אל אלעזר ולא הזכיר אהרן לצד שעדיין חסר תיקון מעשה העגל שעשה כי אחרי כן מתו ב' בניו והביא כפרתו ביום ח' למילואים אשר על כן לא הזכיר פקודתו אלא הזכיר שמו עם בנו, מינוי ה' הוא העושה מלאכת המשכן והוא שאמר **ובצלאל** וגו' **עשה** וגו' **ואתו אהליאב** וגו' נמצאת אומר שהממונים בפרט זה של המשכן הם ה', א' התורה היא מושלת על קיומו אם יתקיים אם לאו, ב' משה ממונה על מצותו באיזה אופן יעשה ויתנהג, ג' הלוים לעבוד לפרוק ולטעון וכו', ד' הכהנים לעבוד העבודות ולהתמנות על הלוים בעבודתם, ה' ובצלאל ואהליאב על המלאכה ועל אלה אמר **אלה פקודי המשכן**:
@1122 **כל הזהב העשוי וגו'**. צריך לדעת גזירת הכתוב איה מקומה, ואם אומרו תשע ועשרים ככר אם כן למה חזר לומר **ויהי זהב** וגו', ואולי כי גזירת הכתוב הוא **בכל מלאכת הקודש** וכוונת הכתוב היא לומר שכל הזהב העשוי למלאכה לא נחסר ולא נפשע ולא נגנב ממנו דבר אלא הכל נכנם בכל מלאכת הקודש, ובזה הוציא האומנים העושים במלאכה מהחשד.
@1122 **עוד** ירצה להודיע נסים שנעשו בזהב המשכן כי דבר ידוע הוא כי בעשות האדם כלי מזהב או משאר המתכות על כל פנים יתמעט משיעור משקל הזהב שנעשה ממנו הכלי ולא יעמוד הכלי במשקל הראשון לצד ההתחלקות ופעולות המלאכותיו ומה גם כשיהיה במלאכה ריבוי התחלקות וחלקים דקים פשיטא שיתמעט באמצעות כן, ועוד בהכין האדם מעשה המלאכה כמו שתאמר שתי וערב לארוג בגד פתילי זהב לעשות מהם המלאכה מן הנמנע שידקדק במוכן לא פחות ולא יותר וכאן הודיע הכתוב שנעשה נס שכל הזהב העשוי למלאכה היה **בכל מלאכת הקודש**, מאומרו **כל** הודיעך. שלא נתמעט מאמצעות המלאכה כנזכר, ומאומרו **העשוי** רשם גם כן שכל המוכן למלאכה לא נותר ממנו דבר לבטלה והכל נכנס בכל מלאכת הקודש, ודקדק לומר **בכל** ולא אמר במלאכת הקודש נתכוין לומר גם כן שהספיק העשוי לכל, וזה הוא עיקר הנס שזולת זה אין נם במה שלא הותיר כי אפשר ששיער שיעור שודאי לא יותיר ולא הוכר הנם אלא באמצעות שלא הותיר ולא החסיר:
@1126 **ואת האלף ושבע וגו** '. פירוש הנשארים, ורבותינו ז''ל אמרו (שמו''ר פנ''א) ששכחם וכשזכר אותם אמר ואת האלף וגו' הם ממה שעשה ווים וגו', והנה להסוברים מהחכמים (ראב''ע) כי לא היה כסף בנדבת המשכן זולת מחצית השקל יתבאר אומרו **ואת האלף** על זה הדרך לפי שמצינו שצוה ה' בתרומת הכסף מחצית השקל ובכל מלאכת המשכן לא מצינו שצוה ה' מעשה כסף זולת האדנים והווין וחשוקיהם וביאר באדנים שצריך ככר לאדן והווין לא הודיע ה' שיעורן ושיעור חשוקיהן, לזה נתחכם בצלאל וחלק הנשאר מהאדנים ועשאן ווין שהגם שלא צוה ה' שיעורן ממה שנתן שיעור לאדנים השכילו כי הווין וחשוקיהם יהיו מהנשאר, ולזה אמר **ואת האלף** וגו' **עשה ווין** פירוש שחלק הסך לווין, ואין הכי נמי אם היה נשאר יותר או פחות היה מחלק הנשאר, ואם היה אומר הכתוב ויעש ווין וגו' יהיה נשמע כי נאמר מפי אל עליון שיעור זה ולא כן הוא אלא מכללן של דברים הבין כנזכר, ודעתי אינה כסברא זו כי ודאי כי כסף אחר היה בתרומת המשכן מלבד הבקע לגלגולת כי מקרא מלא דבר הכתוב בויקהל (ל''ה כ''ד) כל מרים תרומת כסף ונחושת ובפסוק זה לא יצדיקו דברי ראב''ע שיישב בפסוק (כ''ה ג') וזאת התרומה והמשכיל יבין, ויתבאר אומרו **ואת האלף** על דרך מה שפירשנו בפסוק (כ''ד) כל הזהב וגו' פירוש שלא נחסר באמצעות ההתכה ופרטי המלאכה שהגם שעשה כמה פרטי מלאכה במעשה כמה ווין וחשוקיהן אף על פי כן המספר עצמו בשלימות היה בווין ולא נחסר ממנו כלום והוא אומרו **ואת האלף** וגו' **עשה ווין** והבן:
@1130 **כאשר צוה ה' את משה**. טעם אומרו כן בכל פרט ופרט, על פי מה שכתבנו בפרשת תצוה (כ''ז כ') כי חלק ה' למשה חלק בכל מלאכות ועבודות הנעשות במשכן כי חלקו במעשה הוא המצוה אשר יצוה ה' הדבר על ידו לזה מזכירו בכל פרט ופרט שהגם שאינו עושה הרי הוא מצוה לעשות.
@1130 **עוד** ירצה שהיו אומרים בשעת המלאכה הרי אנו עושים דבר זה **כאשר צוה ה' את משה**.
@1130 **עוד** נראה לפי מה שקדם לנו כי אין לך מצוה שאין בה פרטי ההשכלה ולא נכתב בתורה אלא מיעוט כמאמר ר' יוחנן בהניזקין (גיטין ס':) ומלבד זה יש בכל מעשה ממעשה המשכן מושכל, והוא פנימיות הדברים ואלה יעשו בכוונת הלב ובשכליות הנעלם ויעשו דבר במינו כידוע ליודעי דעת והבנין, והוא מה שרמזה התורה בכל פרט ופרט **כאשר צוה ה' את משה** פירוש בעל פה ואינו מפורש בתורה לצד יקרת הדבר, ואשכילך כי המכתב הוא מבחינת המופעל והמושכל מושלל מהתקבל מקצתו בבחינת ההפעל ומקצתו גם מבחינת הנדבר כי רחוק הוא בב' הדרגות, וקצת רמז ה' בנפעל נראה ואינו נראה בסוד צורת האותיות וטעמיהם ועטרות שעל ראשיהם התגין ומעשיהם בחינת מחשבה יקראו ונגלה למשה בסיני פלאי פלאות, וצא ולמד מדרשת ר' עקיבא (סנהדרין ק''ו) ג' מאות הלכות בעליונו של למ''ד, המה ראו מעשה ה', והודיע הכתוב בכל פרטי המשכן כי עשאוהו **כאשר צוה ה' את משה** ככל נפלאות אשר יכוין עליהם:
@1153 **על שולי וגו'**. מכאן אני מדייק שהאמת הוא כהסוברים שהפעמונים הם בשורה עם הרמונים ולא בתוכם ממש שהרי הקדים הכתוב נתינת הרמונים על שולי המעיל ואחר כך אמר מעשה הפעמונים בפני עצמן ויתנו אותם תוך הרמונים ומעתה אם הפעמון תוך הרימון ממש למה הוצרך הכתוב לומר על שולי אחר שכבר קדם ואמר שהרמונים הם על שולי המעיל זה בזה תלוי, ותמה אני על רמב''ן שפנה מדרך זה, ומה שיישב שלא נתן הרימון במעיל עד שנתן בתוכו הפעמון הכתוב יגיד הפך זה, וממה שאמר כי לזה כפל לומר בתוך הרמונים פעמים, קשה למה הקדים הכתוב לצוות שיתן הרמונים על שולי המעיל קודם שיעשה הפעמונים ויצטרך לחזור לומר פעמים בתוך הרמונים לרבות שיתנם קודם, ופשוט הוא שהרב לא דק יפה כמנהג זכות עיונו הקדוש:
@1154 **בתו** ך **הרמונים**. טעם שכפל לומר כן, לומר שיהיו מכוונים הפעמונים כנגד הרמונים שלא יהיה הפעמון משוך לצד מטה או לצד מעלה אלא גופו של פעמון לפני הרימון ועומד בשורה לא למעלה ולא למטה, ודבר זה אינו מתחייב מאומרו פעם ראשונה הפעמונים בתוך הרימונים כי זה בא לשלול שלא יהיו הרימונים בתוך הפעמונים על זה האופן תתחיל השורה בפעמון ולפניו רימון כפי זה יהיו הרמונים בתוך הפעמונים כי המעיל לא היה מחובר מלמטה סביב לומר שתמיד יהיו אלו תוך אלו כל שיהיו שוים במספר אלא מחולק היה לב', ולזה תמצא שלא עשה בברייתא מספר הרימונים כפעמונים כי הם יותר מהם:
@1155 **פעמון ורימון**. הוצרך לכתוב זה שלא תבין שיכול לעשות ב' או ג' פעמונים בתוך ב' או ג' רימונים וקורא אני בהם בתוך הרימונים, לזה אמר **פעמון ורימוז**, פירוש שלא יעשה ב' פעמונים ורימון, וחזר לומר **פעמון ורימון** בא לשלול שלא יעשה ב' רימונים לכל פעמון ויהיה כל פעמון בב' רימונים ולא תעלה רימון שבימינו של פעמון זה לשמאלו של פעמון הבא אחריו, לזה אמר פעם ב' **פעמון ורימון** פירוש סמוך לרימון של פעמון ראשון יהיה פעמון ב' והבן:
@1161 **ותכל כל עבודת וגו'**. פירוש לא הם כילו שאם היה ה' מצוה עוד בעבודתו יתברך יעשו בני ישראל בכל אות נפשם אלא שכלתה המלאכה אשר צוה ה':
@1161 **עוד** ירצה באומרו **ותכל** לצד שהיה בה מלאכות שנעשו מעצמן שהיא מנורה שאמרו ז''ל (במד''ר פט''ו) שנעשית מעצמה לזה לא כינה הכל עליהם כי יש חלק במלאכה שהוא לא נעשה אלא הכאה בקורנם והיא מעצמה כלתה.
@1161 **עוד** ירמוז על דרך אומרו (תהלים פ''ד) נכספה וגם כלתה נפשי לחצרות ה', כי עשו כל העבודה חשוקה וכלילת יופי:
@1161 **ויעשו בני ישראל וגו'**. והגם שלא עשה אלא בצלאל וחכמי לב, שלוחו של אדם כמותו וכאילו כל ישראל עשו, והגם שלא מצינו שעשה בצלאל אלא במאמר ה' ולא הם שלחוהו, אף על פי כן הרי הסכימו עליו:
@1161 **עוד** נראה כי כאן עשה הכתוב מחברת הכללות בקיום התורה והראה כי בני ישראל יזכו זה לזה והתורה נתנה להתקיים בכללות ישראל כל אחד יעשה היכולת שבידו ויזכו זה לזה. ואולי כי לזה רמז באומרו (ויקרא י''ט י''ח) ואהבת לרעך כמוך, פירוש לצד שהוא כמותך כי בשלומו ייטיב לך ובאמצעותו אתה משלים שלימותך ואם כן אינו אחר אלא אתה עצמך וכאחד מחלקיך, ובזה מצאנו נחת רוח כי ה' צוה תרי''ג מצות ומן הנמנע שימצא אדם אחד שישנו בקיום כולם וזה לך האות כהן ולוי וישראל ונשים, יש מצות עשה בכהנים שאין מציאות לישראל לעשותם, ויש מצות לישראל שאינם בכהנים, וכן בלוים, וכן בנשים, ומה מציאות יש ליחיד לקיימם להשלים תיקון לרמ''ח איבריו ושס''ה גידיו אשר יכוונו להם, אלא ודאי שתתקיים התורה במחברת הכללות ויזכו זה מזה, והוא מה שאמר הכתוב כאן **ויעשו בני ישראל ככל אשר צוה ה'** כינה לכולם יחד מעשה כולם הגם שמהם הביאו הנדבה מהם עשו מלאכה יאמר על כללותם שעשו הכל, וסמך מאמר זה למלאכת הבגדים אשר עשאום יחידים מישראל, להעירך כי על פרט זה יאמר שעשאוהו בני ישראל באין הבדל, ומעתה כל אחד מישראל הביא כל הי''ג מינים שבנדבה ועשה כל המלאכות האמורות:
@1161 **ככל אשר וגו'**. נתכוין בזה להסיר החשד מהם כי יראה הרואה שצוה ה' על המשכן ונעשה וקפלוהו ג' חדשים (שמו''ר פנ''ב) יאמר כי היתה סיבה מצד המעשה שהיה בו דבר בלתי הגון או שישראל עכבו דבר מכל האמור במצותו, לזה אמר **ותכל** וגו' **ויעשו בני ישראל ככל** ומה טעם המתין הקב''ה עד חדש הראשון שהוא חדש המשובח שנקרא ראשון, והוא אומרו בגמר המלאכה (לקמן מ' ב') ביום החדש הראשון תקים וגו' ורבותינו ז''ל אמרו (שם) לצד שנתבשר אברהם ביצחק:
@1161 **אשר צוה וגו** ' **כן עשו**. טעם אומרו **עשו** ולא הספיק במאמר ויעשו, אולי כי העלה עליהם הכתוב שקיימו כל מה שצוה ה' את משה בתורה, וזה שיעור הכתוב **ויעשו בני ישראל ככל** וגו' האמור בענין ובזה העריכם הכתוב כאילו ככל אשר צוה ה' את משה ככל התורה כן עשו, ובזה נשרף ונפזר אפרו של חטא העגל:
@1162 **ויביאו את המשכן**. פירוש הזמינוהו לפניו:
@1171 **ככל אשר צוה ה'**. וחזר לומר פעם ב' דבר זה וגם בסמוך פעם ג', אולי כי לצד שחטאו בעגל במחשבה ובדיבור ובמעשה וכמו שפירשתי שם ובבחינת כל אחת כפרו בכל התורה כולה, אשר על כן בתיקון היו שלשתם יחד, הנדבה הוא המעשה, המחשבה היא בחינת החכמה שבמלאכה, הדיבור הוא שהיו אומרים בשעת מעשה לשם מצות ה' כמו שפירשתי בקודם, וכנגד שלשתם אמר הכתוב שעשו **כאשר צוה ה' את משה** כי תקנו שלש הדרגות הרע:
@1172 **והנה עשו וגו' כן עשו**. טעם שחזר לומר פעם ב' **כן עשו**, כי אומרו והנה עשו נמשכת למעלה וירא וגו' והנה היא עשויה פירוש גוף המעשה, והכוונה בזה שלא היה שיעור בזמן וראה שהנה עשאוהו בזמן מועט.
@1172 **עוד** ירצה באומרו **עשו אותה** לשון תיקון שתקנו אותה כמצטרך, ועוד מודיע שהשכיל בה שעשאוה כאשר צוה ה' בפרטי המשפט, והוא אומרו **כאשר** וגו' **כן עשו**.
@1172 **עוד** ירצה על פי דבריהם ז''ל (זבחים ס''ב.) כי יש פרטי המצות שאינם לעיכוב אלא למצוה ומנו חכמים דברים המעכבים זה את זה, והודיע הכתוב בכפל המעשה לומר שעשו כל אשר צוה אפילו דברים שאינם אלא למצוה מן המובחר:
@1172 **ויברך אותם משה**. טעם שהוצרך לומר **משה** ולא סמך על זכרונו בסמוך, לומר לא תהיה ברכה זו קלה בעיניך כי משה איש האלהים ברכם ודבר גדול הודיע הכתוב בדבר זה, ולטעם זה הוא שהודיע הכתוב ואמר **ויברך אותם** וזולת היות משה אין התורה מגדת אם יברך אדם לחבירו:
@1174 **ביום החדש וגו'**. הקמה זו היתה אחר ז' ימי מילואים לדבריהם ז''ל (במד''ר פי''ג), וכן מוכיחים הכתובים כי ז' ימי המילואים לא נעשה בהם אלא מלואי ידי אהרן, ולזה צוה ה' מעשה ז' ימי מילואים קודם מצות הקמת המשכן והערכתו, וגם בפרשת צו כשמשח אהרן ובניו יום א' של מילואים שם הזכיר משיחת המשכן וכליו, ולא הזכיר שם הקמת המשכן וסדרו הא למדת כי המילואים היו קודם הקמת המשכן והערכת כליו, ויום ר''ח ניסן הוא שנתקדש המשכן וסדר משה מערכת המשכן והקריב בו את האמור בענין הא למדת שלא שמש משה במשכן בסדר כל האמור בפרשה זו אלא ביום אחד שהוא יום השמיני של מילואים, ואפילו להסוברים שכל ז' ימי המלואים היה משה בונה משכן וסותרו, בהכרח לומר כי משכן הוא שהיה בונה וסותר אבל סדר הכנתו לא היתה אלא ביום ר''ח ניסן כאמור בענין באחד לחדש וגו' ושמת שם וגו' והבאת את השלחן וגו' הרי כי מחדש הוא מודיעו ההערכה ומקום כל דבר וסדר הנחתו ואם זה לו ז' ימים והוא מעריך מה מקום להודיע מחדש, אלא ודאי זה היום תחלת סדר מעשה המשכן ותיקונו והקריב משה בו ביום כל האמור בענין במצות ה' אליו כאמור לפנינו:
@1191 **כאשר צוה ה' את משה**. הוצרך לומר **את משה** ולא הספיק לומר כאשר צוה ה' והדבר ידוע כי אותו צוה ה', כוונת הכתוב הוא להודיע שהתורה מעידה על המעשה שלא היה בו שינוי מהמצוה, ושיעור אומרו כאשר הוא על גופו של מעשה, ואם היה אומר כאשר צוהו ה' היה בנשמע שחוזר על העושה שעשה כאשר צוהו והבן, וטעם כפל הדבר בכל פרט ופרט להראות שכל פרט הוא חשוב מצוה בפני עצמו וראוי ליאמר עליו לבדו צוה ה' את משה:
@1207 **ולא יכול משה וגו'**. והגם שאמר הכתוב בפרשת משפטים (כ''ד י''ח) ויבא משה בתוך הענן, שם היה אחר שקרא אליו ה' נתן בו כח. או יאמר על זה הדרך **ולא יכול משה** וגו', והטעם **כי שכן עליו הענן** ואין מציאות זה כמציאות האמור בפרשת משפטים כי כאן.
@1207 **כבוד ה' מלא את המשכן** מה שאין כן הענן שבא בו בהר סיני שם נאמר ומראה כבוד ה' כאש אוכלת בראש ההר וסמוך ליה ויבא משה בתוך הענן ויעל אל ההר פירוש מקום שאין שם שוכן כבוד ה' מה שאין כן במה שלפנינו שהיה כבוד ה' מלא המשכן ולא יכול ליכנם במקום מלא כבודו יתברך:
@1207 **חסלת פרשת פקודי סליק ספר שמות**
